INSERT INTO `msds_disposal` VALUES (2865, 3021, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '集中收集后交由有资质的危险废物处置单位进行高温焚烧或化学处理。焚烧时需确保完全燃烧，尾气需经碱洗和活性炭吸附处理。也可采用化学降解方法，在强碱条件下水解。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (2866, 3022, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '用控制焚烧法处置。焚烧炉排出的氮氧化物、氧化硫和氰化物通过洗涤器除去。也可采用化学处理法，在碱性条件下水解后，按危险废物进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (2867, 3023, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '集中收集后交由有资质的危险废物处置单位进行高温焚烧或化学处理。焚烧时需确保完全燃烧（>1100℃），尾气需经碱洗和活性炭吸附处理。也可采用化学降解方法，在强碱或金属催化剂条件下脱氯。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (2868, 3024, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '集中收集后交由有资质的危险废物处置单位进行高温焚烧或化学处理。焚烧时需确保完全燃烧（>1100℃），尾气需经碱洗和活性炭吸附处理。也可采用化学降解方法，在强碱或金属催化剂条件下脱氯。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (2869, 3025, '处置前应参阅国家和地方有关法规。本品为剧毒物质，应按危险废物进行处置。', '集中收集后交由有资质的危险废物处置单位进行高温焚烧或化学处理。焚烧时需确保完全燃烧，尾气需经碱洗和活性炭吸附处理。空容器仍可能存在残留物危害，应远离热和火源，如有可能返还给供应商循环使用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (2870, 3026, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '集中收集后交由有资质的危险废物处置单位进行高温焚烧或化学处理。焚烧时需确保完全燃烧（>1100℃），尾气需经碱洗和活性炭吸附处理。也可采用化学降解方法，在强碱条件下水解后，按危险废物进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (2871, 3027, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '集中收集后交由有资质的危险废物处置单位进行高温焚烧或化学处理。焚烧时需确保完全燃烧（>1100℃），尾气需经碱洗和活性炭吸附处理，特别注意去除氰化物。也可采用化学降解方法，在强碱条件下水解后，按危险废物进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (2872, 3028, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '集中收集后交由有资质的危险废物处置单位进行高温焚烧或化学处理。焚烧时需确保完全燃烧（>1100℃），尾气需经碱洗和活性炭吸附处理。也可采用化学降解方法，在强碱条件下水解后，按危险废物进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (2873, 3029, '危险废物（HW06有机溶剂废物），废物代码900-401-06（含有机过氧化物的废有机溶剂）。具有易燃性、反应性和毒性。', '集中收集后交由有资质的危险废物处置单位进行安全处置。有机过氧化物应小心处理，避免受热、摩擦、震动。可采用化学还原法或稀释后焚烧法处置。处置前应参阅国家和地方有关法规。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (2874, 3030, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '集中收集后交由有资质的危险废物处置单位进行安全处置。有机过氧化物应小心处理，避免受热、摩擦、震动。可采用化学还原法或稀释后焚烧法处置。处置前应参阅国家和地方有关法规。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (2875, 3031, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '优先回收再利用。无法回收时，可在专用焚烧炉中燃烧分解，并对尾气进行洗涤以吸收氟化氢。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (2876, 3032, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '集中收集后交由有资质的危险废物处置单位进行高温焚烧或化学处理。焚烧时需确保完全燃烧（>1100℃），尾气需经碱洗和活性炭吸附处理。也可采用化学降解方法，在强碱或金属催化剂条件下脱氯。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (2877, 3033, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '可采用焚烧法或回收再利用。焚烧时尾气需经吸收净化。也可采用生物处理法，在好氧条件下进行生物降解。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (2878, 3034, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。PFOS是持久性有机污染物，需特别谨慎处理。', 'PFOS是持久性有机污染物，应由专业机构进行无害化处置。建议采用高温焚烧法（>1100℃），焚烧炉需配备高效尾气处理系统，以去除氟化氢、氧化硫等有毒产物。也可采用化学降解方法，但需确保完全降解。处置前应参阅国家和地方有关法规。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (2879, 3035, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '集中收集后交由有资质的危险废物处置单位进行安全处置。应采用高温焚烧法处置，焚烧温度需≥1100℃，停留时间≥2秒，确保完全燃烧。尾气需经碱洗、活性炭吸附等处理以去除氯化氢，确保达标排放。也可采用化学处理法，在碱性条件下处理后，按危险废物进行处置。禁止将未经处理的废物直接排入环境。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (2880, 3036, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '尽量回收再利用。无法回收时，集中收集后交由有资质的危险废物处置单位进行安全处置。应在专用焚烧炉中焚烧，焚烧温度需≥1100℃，停留时间≥2秒，确保完全燃烧。尾气需经碱洗、活性炭吸附等处理以去除HF和HCl，确保达标排放。禁止将未经处理的废物直接排入环境。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (2881, 3037, '处置前应参阅国家和地方有关法规。建议用高温焚烧法处置。', '集中收集后交由有资质的危险废物处置单位进行安全处置。可采用焚烧法处置，焚烧时需确保完全燃烧（>1100℃），尾气需经碱洗和活性炭吸附处理。处置前应参阅国家和地方有关法规。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
