INSERT INTO `msds_disposal` VALUES (3295, 3455, '危险化学品废弃物，具有剧毒性和环境危害性。', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。废液经过中和、铁碳微电解、催化氧化、过滤、最后经过生化处理以及深度电芬顿处理达标排放。废固送废固焚烧场焚烧处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
