INSERT INTO `msds_disposal` VALUES (3381, 3541, '该物质为第6.1类毒害品，属于有毒有害化学品。废弃物具有毒性，对环境和人体健康有潜在危害。', '建议用焚烧法处置。在能利用的地方重复使用容器或在规定场所掩埋。焚烧时应配备尾气处理装置，确保燃烧完全，防止产生二噁英等二次污染物。废弃物处置应委托有资质的危险废物处理单位进行。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3382, 3542, '危险废物，具有毒性和腐蚀性。', '建议用焚烧法处置。焚烧炉须配备除尘和尾气处理设施，以防止溴化氢等有毒气体排放。也可采用化学还原脱卤法、高级氧化法等处理技术。处置前应参阅国家和地方有关法规。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
