INSERT INTO `msds_disposal` VALUES (3386, 3546, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。焚烧炉应配备尾气处理装置，以去除燃烧产生的溴化氢等有害气体。也可在专业危险化学品处理中心进行化学中和处理。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
