INSERT INTO `msds_disposal` VALUES (3403, 3563, '危险废物', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。在能利用的地方重复使用容器或在规定场所掩埋。废弃物处置应遵守国家和地方有关法规。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3404, 3564, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3405, 3565, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3406, 3566, '该物质为危险废物，属于自反应物质B型。具有爆炸性、毒性和环境危害性。', '处置前应参阅国家和地方有关法规。建议用焚烧法处置，需在有资质的危险废物处理单位进行，并配备适当的防爆和废气处理设施。禁止随意倾倒或排放到下水道、土壤或水体中。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3407, 3567, '危险化学品废物，具有毒性和刺激性。', '建议焚烧处理。在具备许可证的危险废物处理设施中，采用高温焚烧方法进行处置。焚烧过程中应配备尾气处理系统，确保符合环保要求。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3408, 3568, '危险化学品废弃物，具有毒性和自反应性', '建议使用焚烧法处理。必须交由有资质的危险废物处理单位进行处置。严禁随意丢弃或排入下水道、水体或土壤。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3409, 3569, '危险废物，毒性废物。', '建议使用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。应交由有资质的危险废物处理单位进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3410, 3570, '属于危险废物。具有毒性，需按危险废物管理。', '建议用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。与当地环保部门或废物处理机构联系，按照国家和地方有关法规进行处置。禁止随意倾倒或排放到环境中。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3411, 3571, '属于危险废物，废物类别为HW04农药废物，具有毒性，需按照危险废物进行管理。', '建议用焚烧法处置，焚烧温度应不低于1100℃，并配备二次燃烧室。焚烧炉排出的气体要通过洗涤器除去酸性气体和有害物质。也可采用化学分解法处理。处置前应与相关环保部门联系，获得许可后交由有资质的危险废物处理单位进行处置。必须按照《国家危险废物名录》和《危险废物经营许可证管理办法》的要求进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3412, 3572, '危险废物。具有毒性，对环境和人体健康有潜在危害。', '建议使用焚烧法处置。焚烧炉应配备烟气净化系统，确保完全燃烧。必须交由有资质的危险废物处理单位进行处置。禁止随意丢弃或排入下水道、水体或土壤中。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3413, 3573, '危险废物，有机过氧化物', '建议使用控制焚烧法处理。处置前应充分稳定化处理。处置应遵守国家和地方有关法规。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3414, 3574, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。（来源：GB 18597-2023、中国化学品安全网）', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。根据《危险废物焚烧污染控制标准》（GB 18484-2020）进行焚烧处置。焚烧温度应≥850℃，烟气停留时间≥2秒。（来源：GB 18597-2023、GB 18484-2020）', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3415, 3575, '危险废物', '处置前应参阅国家和地方有关法规。建议用焚烧法处置。中和、稀释后，排入废水系统。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3416, 3576, '危险废物', '建议用控制焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3417, 3577, '有机过氧化物危险废物', '建议采用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去。废弃物处置应委托有资质的危险废物处理单位进行，并遵守当地相关法律法规（如GB18484-2001危险废物焚烧污染控制标准）。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3418, 3578, '危险废物，易燃液体', '建议用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。废弃物必须按照当地、国家和国际法规进行处置。不得随意倾倒或排放到下水道、河流或土壤中。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3419, 3579, '危险废物', '建议用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3420, 3580, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用控制焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3421, 3581, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3422, 3582, '危险废物，属于毒害品类危险废物，具有毒性、腐蚀性和刺激性。', '处置前应参阅国家和地方有关法规。建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去。中和、稀释后，排入废水系统。废弃物应交由有资质的危险废物处理单位进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3423, 3583, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3424, 3584, '危险废物，属于易燃液体类危险废物', '处置前应参阅国家和地方有关法规。建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去。中和、稀释后，排入废水系统。废弃物应交由有资质的危险废物处理单位进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3425, 3585, '危险废物', '处置前应参阅国家和地方有关法规。建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去。中和、稀释后，排入废水系统。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3426, 3586, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。废弃物应交由有资质的危险废物处理单位进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3427, 3587, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '集中收集后交由有资质的危险废物处置单位进行安全处置。应采用高温焚烧法处置，焚烧温度需≥1100℃，停留时间≥2秒，确保完全燃烧。尾气需经碱洗、活性炭吸附等处理以去除氧化氮和氯化氢，确保达标排放。也可采用化学处理法，在碱性条件下处理后，按危险废物进行处置。禁止将未经处理的废物直接排入环境。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3428, 3588, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3429, 3589, '有毒有害化学品', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。与易燃溶剂混合后焚烧。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3430, 3590, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3431, 3591, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3432, 3592, '危险废物', '建议用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3433, 3593, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '集中收集后交由有资质的危险废物处置单位进行安全处置。应采用高温焚烧法处置，焚烧温度需≥1100℃，停留时间≥2秒，确保完全燃烧。尾气需经碱洗、活性炭吸附等处理。也可采用化学处理法，在碱性条件下处理后，按危险废物进行处置。禁止将未经处理的废物直接排入环境。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3434, 3594, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3435, 3595, '属于危险废物，废物类别：HW49其他废物，废物代码：900-041-49。', '建议用焚烧法处置。焚烧时应配备尾气处理设施，确保充分燃烧以去除氮氧化物等有害气体。也可委托有资质的危险废物处理单位进行处置。在处置前应进行分类收集，不得随意倾倒或排放。剩余物和容器应按照危险废物管理规定处理。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3436, 3596, '酸性腐蚀性危险化学品废弃物', '建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去。废弃物应交由有资质的危险废物处理单位进行处置。在处置前应先进行中和处理。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3437, 3597, '危险化学品废物', '建议用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。与当地环保部门联系，按照国家危险废物管理法规进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3438, 3598, '属于危险废物，废物类别：HW08废矿物油与含矿物油废物，废物代码：900-199-08。', '建议用焚烧法处置。焚烧时应配备尾气处理设施，确保充分燃烧。也可委托有资质的危险废物处理单位进行处置。在处置前应进行分类收集，不得随意倾倒或排放。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3439, 3599, '危险废物，具有毒性', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。根据当地法规，交由有危险废物处理资质的单位进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3440, 3600, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。废弃物性质：有毒固体废弃物。', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。建议与生产厂家或回收公司联系，确定最佳的处置方法。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3441, 3601, '危险废物，具有腐蚀性和毒性。', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。废弃物应交由有资质的危险废物处理单位进行处置。处置前应与当地环保部门联系，遵守相关法律法规。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3442, 3602, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '在焚烧炉中焚烧。焚烧炉排出的氮氧化物通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3443, 3603, '有机过氧化物废物，具有氧化性和易燃易爆性。', '建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去。须在具备有机过氧化物处理资质的危险废物处置单位进行处置。处置前应与当地环境保护部门和相关法规要求保持一致。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3444, 3604, '属于危险废物，具有毒性。', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。处置前应参阅国家和地方有关法规。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3445, 3605, '危险废物，属于有毒化学品，具有抗凝血作用，对环境有害。', '建议采用焚烧法处置，将可燃性固体废弃物置于高温炉中，用氧化剂将有害物质分解成无害的气体和液体。焚烧过程中应配备尾气处理设施，防止二次污染。也可采用固化/稳定化技术处理后进行安全填埋。所有处置工作必须交由有资质的危险废物处理单位进行。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3446, 3606, '危险废物', '建议用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。在符合当地法律法规的前提下，委托有资质的危险废物处理单位进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3447, 3607, '危险废物。具有极高毒性，对环境和人体健康有严重危害。', '建议使用焚烧法处置。焚烧炉应配备烟气净化系统，确保完全燃烧。必须交由有资质的危险废物处理单位进行处置。禁止随意丢弃或排入下水道、水体或土壤中。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3448, 3608, '危险废物，有毒，对环境有害。', '建议用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。与易燃溶剂混合后，再焚烧。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3449, 3609, '有毒固体废弃物。', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。必须委托有资质的危险废物处理单位进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3450, 3610, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '焚烧法。焚烧炉排出的氮氧化物通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3451, 3611, '有毒固体废弃物，含砷化合物。', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。与燃料混合后，再焚烧。焚烧炉排出的气体通过酸洗器或碱洗器除去。必须委托有资质的危险废物处理单位进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3452, 3612, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '焚烧法处置。焚烧炉排出的气体通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3453, 3613, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '焚烧法处置。焚烧炉排出的气体通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3454, 3614, '危险废物', '用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3455, 3615, '属于危险废物，具有毒性和易燃性。', '建议用焚烧法处置。焚烧炉排出的碘化氢和其他有害气体通过洗涤器或其他适宜装置进行处理。处置前应参阅国家和地方有关法规，交由有资质的危险废物处理单位进行处理。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3456, 3616, '危险废物，对环境有害。', '建议用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。与易燃溶剂混合后，再焚烧。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3457, 3617, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3458, 3618, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。焚烧炉排出的氮氧化物、氰化氢通过洗涤器除去。废弃物应交由有资质的危险废物处理单位进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3459, 3619, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去。也可以交由有资质的危险废物处理单位进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3460, 3620, '危险废物', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3461, 3621, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3462, 3622, '危险废物', '建议用焚烧法处置。在能保证充分燃烧的条件下，焚烧炉排气中氮氧化物通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3463, 3623, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '本品及内装物、容器依据国家和地方法规处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
