INSERT INTO `msds_disposal` VALUES (3465, 3625, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用控制焚烧法处置。焚烧炉排出的气体通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3466, 3626, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。废弃危险化学品应委托具备资质的单位进行处置，处置过程应采取隔离、封闭、惰性气体保护等有效措施，确保处置过程安全。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3467, 3627, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。（来源：检索补充）', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3468, 3628, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '集中收集后交由有资质的危险废物处置单位进行安全处置。应采用高温焚烧法处置，焚烧温度需≥1100℃，停留时间≥2秒，确保完全燃烧。尾气需经碱洗、活性炭吸附等处理，确保达标排放。也可采用化学处理法，在碱性条件下处理后，按危险废物进行处置。禁止将未经处理的废物直接排入环境。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
