INSERT INTO `msds_disposal` VALUES (3496, 3656, '有毒固体废弃物。', '建议用焚烧法处置。焚烧炉排出的氯化氢通过洗涤器除去。必须委托有资质的危险废物处理单位进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3497, 3657, '危险废物', '建议用焚烧法处置。焚烧炉排出的卤化氢通过酸洗涤器除去。按照地方/区域/国家/国际规章处置内装物/容器（来源：道客巴巴）。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
