INSERT INTO `msds_disposal` VALUES (3523, 3683, '属于危险废物，具有毒性和环境危害性。', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器或其他适宜装置进行处理。处置前应参阅国家和地方有关法规，交由有资质的危险废物处理单位进行处理。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
