INSERT INTO `msds_disposal` VALUES (3543, 3703, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。焚烧炉排出的卤化氢通过酸洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3544, 3704, '危险废物，具有腐蚀性', '建议用焚烧法处置。焚烧炉排出的卤化氢气体通过酸洗器除去。废弃物必须交由有资质的危险废物处理单位进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3545, 3705, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3546, 3706, '危险废物，属于易燃液体。', '建议用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。与易燃物、氧化剂等分开存放。按照当地法规和危险废物管理规定进行处理和处置。建议联系有资质的危险废物处理单位进行处理。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3547, 3707, '属于危险废物，具有易燃性。', '建议用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。必须委托有危险废物经营许可证的单位进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3548, 3708, '本化学品属于危险废物。根据《国家危险废物名录》，该物质属于HW06废有机溶剂与含有机溶剂废物，废物代码为900-401-06（其他有机卤化物的生产、配制过程中产生的废卤化有机溶剂）。具有易燃性、毒性等危险特性。废弃物必须按照危险废物进行管理和处置。', '1. 焚烧法：在有资质的危险废物处置单位进行高温焚烧，焚烧温度应达到1100℃以上，停留时间大于2秒，确保彻底分解。焚烧炉必须配备完善的尾气处理设施，包括急冷塔、洗涤器、除尘器等，确保烟气达标排放。2. 回收利用：对于未被污染的废弃物，可考虑回收再利用。3. 物理化学处理：对于少量废弃物，可采用物理化学方法进行处理，如活性炭吸附、化学氧化等。4. 禁止随意倾倒、填埋或排放到下水道、水体中。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3549, 3709, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '本品及内装物、容器依据国家和地方法规处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3550, 3710, '有毒农药废弃物', '建议用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3551, 3711, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3552, 3712, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3553, 3713, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3554, 3714, '有害固体废物', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。根据国家和地方有关法规的规定处置。或与制造商或供应商联系，以确定最佳处置方法。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3555, 3715, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3556, 3716, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3557, 3717, '有机过氧化物废弃物，属于危险废物', '废弃物应从作业场所清除并销毁，其方法主要取决于该过氧化物的物化性质，根据其特性选择合适的方法处理，以免发生意外事故。处理方法包括分解、烧毁、填埋等，必须匹配其物化性质。不同有机过氧化物的稳定性、反应性差异极大，需根据具体特性选择处理方法。绝对禁止将泄漏物冲入下水道或随意丢弃，以免造成二次污染或引发不可预知的化学反应。处理过程需遵循\"减量化、资源化、无害化\"原则，严格依据国家及地方相关法规执行。建议交由具备相应资质的专业机构进行最终安全处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3558, 3718, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '集中收集后交由有资质的危险废物处置单位进行安全处置。应采用高温焚烧法处置，焚烧温度需≥1100℃，停留时间≥2秒，确保完全燃烧。尾气需经碱洗、活性炭吸附等处理以去除氮氧化物。也可采用化学处理法，在碱性条件下还原后，按危险废物进行处置。禁止将未经处理的废物直接排入环境。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3559, 3719, '爆炸性废物', '建议用控制焚烧法处置。焚烧炉排出的气体要通过洗涤器除去。必须由有资质的危险废物处理单位进行处理。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3560, 3720, '处置前应参阅国家和地方有关法规。废物性质：危险废物，爆炸性废物。', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。在处理过程中，必须保持含水不低于15%以确保安全。处置应在具备相应资质的危险废物处理单位进行。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3561, 3721, '有害化学品废物', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。与制造商或供应商联系，获取有关废弃处置的建议。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
