INSERT INTO `msds_disposal` VALUES (3657, 3817, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。在能保证充分燃烧的条件下，将废弃物送入焚烧炉中焚烧。焚烧炉应配备尾气处理装置，以除去燃烧产生的有毒气体。少量废弃物也可用化学中和法处理。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3658, 3818, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
