INSERT INTO `msds_disposal` VALUES (3660, 3820, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3661, 3821, '危险废物', '建议用焚烧法处置，焚烧温度需≥1100℃。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3662, 3822, '有害化学品废弃物', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3663, 3823, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。', '焚烧法处置', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3664, 3824, '危险化学品废弃物，具有毒性和易燃性', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。废弃物处置应遵守国家和地方有关环境保护法规。处置前应参阅国家和地方有关法规。废弃物处置应交由有资质的危险废物处理单位处理。禁止随意倾倒或排放。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3665, 3825, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。焚烧设施应符合GB 18484-2020《危险废物焚烧污染控制标准》的要求。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3666, 3826, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3667, 3827, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。焚烧设施应符合GB 18484-2020《危险废物焚烧污染控制标准》的要求。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3668, 3828, '危险废物', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3669, 3829, '危险废物，剧毒化学品。', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。与易燃溶剂混合后焚烧。必须按照当地相关法律法规和危险废物管理规定进行处置。交由有资质的危险废物处理单位处理。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3670, 3830, '属于危险废物，具有毒性。', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。在处置前应尽可能回收利用。处置必须符合国家及地方有关危险废物管理的法律法规。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3671, 3831, '危险废物，具有毒性和致癌性。', '应交由有资质的危险废物处置机构进行焚烧或化学处理。禁止随意丢弃或排入环境。少量废弃物应收集在专用容器中，交由专业机构处理。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3672, 3832, '危险废物，具有腐蚀性。', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。根据国家和地方有关法规的要求处置。或与制造商或供应商联系，了解最佳的处置方法。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3673, 3833, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。在专业废物处理机构进行处置，不得随意倾倒或排放到环境中。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3674, 3834, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3675, 3835, '该物质属于危险废物，具有易燃性和毒性。废弃物应按照危险废物进行管理和处置。', '建议使用焚烧法处置。焚烧应在符合《危险废物焚烧污染控制标准》（GB 18484）的设施中进行，确保充分燃烧，温度不低于850℃，停留时间不少于2秒。焚烧产生的废气应经过净化处理，达标后排放。也可委托有资质的危险废物处置单位进行集中处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3676, 3836, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '集中收集后交由有资质的危险废物处置单位进行安全处置。应采用高温焚烧法处置，焚烧温度需≥1100℃，停留时间≥2秒，确保完全燃烧。尾气需经碱洗、活性炭吸附等处理，确保达标排放。也可采用化学处理法，在碱性条件下处理后，按危险废物进行处置。禁止将未经处理的废物直接排入环境。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3677, 3837, '危险废物', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3678, 3838, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '集中收集后交由有资质的危险废物处置单位进行安全处置。应采用高温焚烧法处置，焚烧温度需≥1100℃，停留时间≥2秒，确保完全燃烧。尾气需经碱洗、活性炭吸附等处理以去除氧化氮和氯化氢，确保达标排放。也可采用化学处理法，在酸性条件下处理后，按危险废物进行处置。禁止将未经处理的废物直接排入环境。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3679, 3839, '危险废物', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3680, 3840, '爆炸性废物，属于危险废物', '建议使用焚烧法处置。在具备危险废物经营许可证的专业设施中进行高温焚烧处理，确保废物彻底分解。也可采用水泥窑协同处置技术，通过高温焚烧及水泥熟料矿物化高温烧结过程实现废物毒性分解、降解、消除、惰性化、稳定化等目的。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3681, 3841, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3682, 3842, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '集中收集后交由有资质的危险废物处置单位进行安全处置。应采用高温焚烧法处置，焚烧温度需≥1100℃，停留时间≥2秒，确保完全燃烧。尾气需经碱洗、活性炭吸附等处理以去除氮氧化物。也可采用化学处理法，在碱性条件下还原后，按危险废物进行处置。禁止将未经处理的废物直接排入环境。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3683, 3843, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '在专用焚烧炉中焚烧，焚烧炉应配备除尘和尾气处理装置。废弃物应与易燃物、还原剂、酸类等分开处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
