INSERT INTO `msds_disposal` VALUES (3731, 3892, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3732, 3893, '该化学品属于危险废物，具有毒性、环境危害性。废弃物应按照国家危险废物管理规定进行分类、包装、标识和处置。', '建议交由有资质的危险废物处理单位进行处置。可采用物理、化学或生物处理方法进行无害化处理，最终采用安全填埋或焚烧方式处置。处理过程应符合《中华人民共和国固体废物污染环境防治法》和《危险废物经营许可证管理办法》等相关法律法规要求。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3733, 3894, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3734, 3895, '属于第8类腐蚀性物质，具有腐蚀性、可燃性和毒性。废弃的N-氨基乙基哌嗪及其容器属于危险废物，需按照危险废物管理要求进行处置。', '1. 废弃的N-氨基乙基哌嗪严禁向下水口倾倒或随普通垃圾丢弃。2. 建议交由有资质的危险废物处理单位进行处置。3. 处置方法包括高温焚烧（1000℃以上）分解有害物质、中和处理等。4. 尽可能将废弃物转化为无害或低毒物质，减少对环境的危害。5. 处置前应进行分类收集，并做好标识。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3735, 3896, '该物质为第6.1类毒害品，具有毒性和刺激性。', '建议用焚烧法处置。焚烧炉需配备烟气净化装置，确保充分燃烧，控制焚烧温度和烟气排放。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3736, 3897, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3737, 3898, '危险化学品废物，对环境有害。', '建议用焚烧法处置。焚烧炉排出的卤化氢通过酸洗涤器除去。废弃物应交由有资质的危险废物处理单位进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3738, 3899, '有害化学废弃物', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。与当地环保部门联系，按照相关法律法规和危险废物管理规定进行处置。必须交由有资质的危险废物处理单位进行处理。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3739, 3900, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
