INSERT INTO `msds_disposal` VALUES (3741, 3902, '危险废物。', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3742, 3903, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3743, 3904, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。在具备相关资质的危险废物焚烧设施中进行焚烧处理，确保完全燃烧。焚烧过程中应配备尾气处理设施，防止二次污染。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3744, 3905, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。在具备相关资质的危险废物焚烧设施中进行焚烧处理，确保完全燃烧。焚烧过程中应配备尾气处理设施，防止氮氧化物等有害气体排放。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
