INSERT INTO `msds_disposal` VALUES (3851, 4014, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3852, 4015, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '焚烧法处置。在焚烧炉中燃烧，并配备洗涤装置以去除燃烧产物中的有害物质。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3853, 4016, '危险化学品废物', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。与易燃物混合后焚烧。在处理前，应咨询当地环保部门和相关法规要求。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3854, 4017, '危险化学品废物', '建议用焚烧法处置。在能利用的地方重复使用容器或在规定场所掩埋。用控制焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。废弃物处置前应参阅国家和地方有关法规。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3855, 4018, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '将内装物/容器送到批准的废物处理厂处理。按照地方/区域/国家/国际规章处置内装物/容器。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3856, 4019, '危险废物，遇水分解产生氨和氢氧化钠。', '处置前应参阅国家和地方有关法规。建议用焚烧法处置。处置逸出物料时须戴防毒面具与手套，用干燥沙土混合并送至空旷地方，与大量水反应后放入废水系统。对污染的地面也应用水冲洗。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3857, 4020, '酸性腐蚀性废物', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3858, 4021, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3859, 4022, '危险废物', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。在能利用的地方重复使用容器或在规定场所掩埋。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3860, 4023, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3861, 4024, '碱性腐蚀性废物', '处置前应参阅国家和地方有关法规。建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。也可以用大量水稀释后排入废水系统，经处理达到排放标准后排放。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3862, 4025, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '焚烧法处置。在焚烧炉中燃烧，并配备洗涤装置以去除燃烧产物中的有害物质。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3863, 4026, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。废弃物应交由有资质的危险废物处理单位进行无害化处理。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3864, 4027, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3865, 4028, '危险废物', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
