INSERT INTO `msds_disposal` VALUES (3867, 4030, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3868, 4031, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。焚烧炉排出的氯化氢通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3869, 4032, '危险废物，属于持久性有机污染物', '建议使用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。必须按照当地法律法规和危险废物管理规定进行处置。交由有资质的危险废物处理单位处理。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (3870, 4033, '危险废物，剧毒废物（HW02）', '用控制焚烧法处置。焚烧温度需≥1100℃，并配备尾气处理装置。处置前应参阅国家和地方有关法规。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
