INSERT INTO `msds_disposal` VALUES (4014, 4178, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4015, 4179, '爆炸性固体废物。具有毒性和爆炸性。', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。必须在有资质的危险废物处理单位进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4016, 4180, '处置前应参阅国家和地方有关法规。属于危险废物，具有毒性和爆炸性', '建议用焚烧法处置。焚烧炉应配备尾气处理装置，确保充分燃烧。也可在专业机构进行化学处理或水解处理。处理过程中应采取防爆措施，避免撞击、摩擦和受热。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4017, 4181, '爆炸性废物，属于危险废物。', '处置前应参阅国家和地方有关法规。建议用焚烧法处置，但必须在具备爆炸品处置资质的专业机构进行，并确保含水或乙醇≥20%以保持稳定。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4018, 4182, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4019, 4183, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4020, 4184, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '集中收集后交由有资质的危险废物处置单位进行安全处置。应采用高温焚烧法处置，焚烧温度需≥1100℃，停留时间≥2秒，确保完全燃烧。尾气需经碱洗、活性炭吸附等处理以去除氮氧化物和氰化物，确保达标排放。也可采用化学处理法，在碱性条件下处理后，按危险废物进行处置。禁止将未经处理的废物直接排入环境。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
