INSERT INTO `msds_disposal` VALUES (4261, 4429, '危险废物', '建议用焚烧法处置，焚烧温度需≥1100℃', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4262, 4430, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4263, 4431, '危险废物', '建议用焚烧法处置。必须由专业人员进行操作。焚烧炉排出的氟化氢通过酸洗涤器除去。汞化合物应按照危险废物处理，交由有资质的危险废物处理单位处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4264, 4432, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。与燃料混合后，再焚烧。焚烧炉排出的气体要通过洗涤器除去。', '建议用控制焚烧法处置。在焚烧炉中与燃料混合后焚烧。必须使用配有洗涤器的焚烧设备，以除去燃烧产生的氟化氢等有毒气体。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
