INSERT INTO `msds_disposal` VALUES (4299, 4467, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4300, 4468, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '用焚烧法处置，或在符合环保要求的设施中处理。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4301, 4469, '爆炸性废物，需按照危险废物管理。', '在符合环保要求的设施中处理，建议由专业机构处理。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4302, 4470, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '用控制焚烧法处置。也可采用还原法处理，用还原剂将高碘酸还原后，按危险废物进行处置。处置前应参阅国家和地方有关法规。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4303, 4471, '高碘酸钡为强氧化剂和高毒物质，具有重金属钡离子和高碘酸盐的双重危害性。废弃前必须进行无害化处理，避免对环境和人体造成危害。', '建议采用控制焚烧法处理，在专业危险废物处理设施中进行。也可采用化学还原法，使用还原剂将高碘酸盐还原为低毒性化合物，再进行后续处理。处理过程中必须严格控制钡离子的释放。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4304, 4472, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '用控制焚烧法处置。也可采用还原法处理，用还原剂将高碘酸钠还原后，按危险废物进行处置。处置前应参阅国家和地方有关法规。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4305, 4473, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '用控制焚烧法处置。也可采用还原法处理，用还原剂将高氯酸钙还原后，按危险废物进行处置。处置前应参阅国家和地方有关法规。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4306, 4474, '高氯酸锂为强氧化剂，具有强氧化性，与有机物、还原剂接触可能发生爆炸反应。', '采用化学还原法处理，使用还原剂(如亚硫酸盐、硫代硫酸盐)将高氯酸根还原为氯离子。处理后的废液经中和、检测达标后方可排放。固体废物应作为危险废物委托有资质单位处理。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4307, 4475, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '用控制焚烧法处置。也可采用还原法处理，用还原剂将高氯酸镁还原后，按危险废物进行处置。处置前应参阅国家和地方有关法规。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4308, 4476, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4309, 4477, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '用控制焚烧法处置。也可采用还原法处理，用还原剂将高氯酸铅还原为硫酸铅后，按危险废物进行处置。处置前应参阅国家和地方有关法规。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4310, 4478, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4311, 4479, '危险废物', '用控制焚烧法处置。也可采用还原法处理，用亚硫酸氢钠、硫酸亚铁等还原剂将高锰酸钡还原为二氧化锰和硫酸钡后，按危险废物进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
