INSERT INTO `msds_disposal` VALUES (4324, 4495, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '根据国家和地方有关法规，建议用焚烧法处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4325, 4496, '危险废物', '建议用焚烧法处置。焚烧炉排出的氮氧化物、氯化氢、氰化氢通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4326, 4497, '危险废物，易燃', '建议用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。在能利用的地方，回收或再利用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4327, 4498, '危险废物', '建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去。在处理过程中，必须避免与水接触。处置前应参阅国家和地方有关法规。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4328, 4499, '处置前应参阅国家和地方有关法规。废弃物属于危险废物。', '建议在专业设施中进行焚烧处理，焚烧炉需配备尾气处理装置。也可采用化学稳定化/固化处理后填埋。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4329, 4500, '危险废物，遇湿易燃物品（HW43）', '建议用焚烧法处置。焚烧温度需≥1100℃，并配备尾气处理装置。处置前应参阅国家和地方有关法规。禁止用水处理。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4330, 4501, '危险废物，遇湿易燃', '建议在专业设施中进行焚烧处理，焚烧炉需配备尾气处理装置。也可采用化学稳定化/固化处理后填埋。处理前必须进行干燥处理。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4331, 4502, '危险废物', '建议用焚烧法处置。在能保证充分燃烧的条件下，焚烧炉排气中氮氧化物含量不得超过排放标准。焚烧炉排出的炉灰按危险废物处理。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4332, 4503, '危险废物', '建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去。在处理过程中，必须避免与水接触。处置前应参阅国家和地方有关法规。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4333, 4504, '危险废物', '建议用焚烧法处置。焚烧温度需≥1100℃。处置前应参阅国家和地方有关法规，禁止随意倾倒。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4334, 4505, '危险废物', '建议用焚烧法处置，焚烧炉排出的气体要通过洗涤器除去。废弃物应交由有资质的危险废物处理单位处理。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4335, 4506, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。废弃物属于危险废物，应按照危险废物管理要求进行处置。', '建议用焚烧法处置。在焚烧过程中应配备尾气处理设施，确保排放符合环保要求。也可交由有资质的危险废物处理单位进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4336, 4507, '危险废物', '建议用焚烧法处置，焚烧炉排出的气体要通过洗涤器除去。废弃物应交由有资质的危险废物处理单位处理。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4337, 4508, '危险废物', '建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去。在处理过程中，必须避免与水接触。处置前应参阅国家和地方有关法规。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4338, 4509, '危险废物', '建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去。在处理过程中，必须避免与水接触。处置前应参阅国家和地方有关法规。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4339, 4510, '危险废物，腐蚀性废物（HW34）', '建议交由有资质的危险废物处理单位处理。可用碱性物质（如碳酸钠、氢氧化钙）中和后，按照当地法规进行处置。不得直接排入下水道或水体。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
