INSERT INTO `msds_disposal` VALUES (4577, 4750, '危险废物，毒性物质，对环境和人体健康有潜在危害。', '建议采用高温焚烧法处置，焚烧温度应不低于850℃，并配备尾气处理系统，确保燃烧完全。也可委托有资质的危险废物处理单位进行专业处置。少量废弃物可在实验室条件下使用化学分解法处理，但需确保反应完全。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
