INSERT INTO `msds_disposal` VALUES (4627, 4800, '危险废物（毒性物质）', '建议用焚烧法处置。废弃物应交由有资质的危险废物处理单位处理。根据当地法规处置废弃物。汞化合物废弃物需按照特殊危险废物处理要求进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4628, 4801, '处置前应参阅国家和地方有关法规。建议用固化法处置。', '建议用固化法处置。将废弃物与固化剂混合后，再进行填埋或焚烧处理。在处理过程中，应配备硫氧化物和钒氧化物净化装置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4629, 4802, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。焚烧炉排出的氯化氢、氟化氢通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4630, 4803, '危险废物，属于第2.3类有毒气体', '建议用焚烧法处置。焚烧炉排出的氟化氢通过洗涤器除去。废弃物应交由有资质的危险废物处理单位处理。禁止随意排放或倾倒。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4631, 4804, '危险废物，具有毒性和刺激性。', '建议用焚烧法处置。在配备有尾气处理系统的焚烧炉中高温焚烧。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4632, 4805, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4633, 4806, '处置前应参阅国家和地方有关法规。', '建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4634, 4807, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4635, 4808, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。废弃物属于危险废物，必须按照危险废物管理规定进行处置。', '建议用焚烧法处置。焚烧过程中应配备尾气处理设施，防止氟化物等有毒气体排放。也可以与水泥窑协同处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4636, 4809, '本品及内装物、容器依据国家和地方法规处置。具有腐蚀性和毒性，属于危险废物。', '建议用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。废物处置应交由有资质的废物处理单位进行。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4637, 4810, '有害化学品废弃物。具有易燃性和毒性。属于危险废物，废物类别为HW06废有机溶剂与含有机溶剂废物。', '建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去，特别是要去除氟化氢等有毒气体。处置前应参阅国家和地方有关法规。也可采用化学中和、吸附等方法进行预处理后再焚烧。禁止直接排放到下水道或环境中。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4638, 4811, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4639, 4812, '危险废物。属于受控温室气体，需按照危险废物和温室气体管理规定进行处置。', '建议采用回收利用或焚烧法处置。在配备尾气处理系统的焚烧炉中高温焚烧，确保完全分解。也可采用化学分解法处理。处置前应参阅国家和地方有关法规。建议与有关环保部门联系，寻求专业处理。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4640, 4813, '有毒有害化学品废弃物。属于危险废物，需按照危险废物进行管理。', '建议用焚烧法处置。在配备尾气处理系统的焚烧炉中高温焚烧。也可采用化学中和法处理。处置前应参阅国家和地方有关法规。建议与有关环保部门联系，寻求专业处理。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4641, 4814, '六氟化铀是放射性废物，具有放射性和化学毒性双重危害。六氟化铀属于低水平放射性废物（LLW），但也可能属于中水平放射性废物（ILW），具体取决于放射性活度。六氟化铀遇水分解产生氟化氢和铀酰化合物，氟化氢具有强腐蚀性，铀酰化合物具有放射性和化学毒性。六氟化铀废物包括：1）泄漏物、受污染的吸收剂、清洗剂、防护用品等；2）废弃的六氟化铀容器；3）受污染的设备、工具等；4）受污染的土壤、水、建筑材料等。六氟化铀废物不能焚烧，因为焚烧会产生剧毒的氟化氢气体和放射性气溶胶。六氟化铀废物不能排入下水道或普通垃圾，必须按放射性废物处理。', '六氟化铀废物的处置方法：1）固化：将六氟化铀废物转化为稳定、不溶性的固体形式，如水泥固化、玻璃固化、陶瓷固化等。水泥固化是最常用的方法，将废物与水泥、添加剂混合，形成稳定的水泥固化体。玻璃固化适用于高放射性废物，将废物与玻璃原料混合，在高温下熔融，形成稳定的玻璃固化体。陶瓷固化适用于高放射性废物，将废物与陶瓷原料混合，在高温下烧结，形成稳定的陶瓷固化体。2）包装：将固化后的废物放入密封容器中，容器应符合放射性废物包装标准。包装材料应具有足够的强度、耐腐蚀性、耐辐射性。包装容器应贴上放射性废物标签，注明废物类型、放射性活度、处置日期等。3）储存：将包装好的废物储存在专用的放射性废物储存设施中，储存设施应符合国家相关规定。储存设施应具备防火、防水、防盗、防辐射等功能。储存设施应配备辐射监测设备，定期监测辐射水平。4）运输：将包装好的废物运输到放射性废物处置场，运输应符合放射性废物运输规定。运输车辆应具备防火、防水、防盗、防辐射等功能。运输人员应经过专门培训，取得放射性废物运输资质。5）处置：将废物处置在专用的放射性废物处置场中，处置方法包括浅地层处置、深地质处置等。浅地层处置适用于低水平放射性废物，将废物埋在地下数米到数十米深的处置设施中。深地质处置适用于高水平放射性废物，将废物埋在地下数百米深的处置设施中。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4642, 4815, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。废物应交由有资质的危险废物处理单位进行处理。', '建议用焚烧法处置，在高温下分解为无害物质。也可以采用物理回收方法，将气体收集后重新利用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4643, 4816, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '焚烧法处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4644, 4817, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4645, 4818, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。', '建议用控制焚烧法处置。在焚烧炉中燃烧，并配备洗涤器以除去燃烧产生的氮氧化物。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4646, 4819, '危险废物，具有毒性、持久性和生物富集性。属于持久性有机污染物（POPs）候选物质。', '建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去。废弃物应交由有资质的危险废物处理单位进行处置。处理前应进行分类、包装和标识，确保运输和处理过程中的安全。禁止随意倾倒或排放到环境中。根据《国家危险废物名录》，六氯-1,3-丁二烯废物属于HW06废有机溶剂与含有机溶剂废物或HW12染料、涂料废物，废物代码为900-404-06或900-299-12。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4647, 4820, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4648, 4821, '有害废弃物，具有毒性和腐蚀性。', '建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
