INSERT INTO `msds_disposal` VALUES (4652, 4825, '本品及内装物、容器依据国家和地方法规处置。具有剧毒性和腐蚀性，属于危险废物。', '建议用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。废物处置应交由有资质的危险废物处理单位进行。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
