INSERT INTO `msds_disposal` VALUES (4655, 4828, '爆炸性废物', '建议用控制焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。必须由具有相应资质的专业机构进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4656, 4829, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4657, 4830, '属于危险废物，含有持久性有机污染物（POPs）。', '建议用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。必须委托有危险废物处理资质的单位进行处置。处置前应咨询当地环保部门和相关法规要求。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4658, 4831, '危险废物，属于持久性有机污染物（POPs）。', '建议焚烧处理。使用配备有尾气净化系统的焚烧炉进行高温焚烧。焚烧前应与易燃物混合。处理前应与当地环保部门联系，获取许可和指导。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4659, 4832, '废弃物性质：属于危险废物，具有毒性、持久性和生物富集性。被列入《国家危险废物名录》HW49其他废物（900-041-49）。属于持久性有机污染物（POPs），需要特殊处置。', '废弃处置方法：建议采用高温焚烧法处置，焚烧温度应达到1200℃以上，停留时间应超过2秒，以确保彻底破坏有机溴化合物。焚烧炉必须配备完善的尾气处理系统，包括洗涤器、除尘器和活性炭吸附装置，以去除溴化氢、二噁英等有毒物质。禁止随意倾倒、填埋或排放到环境中。必须委托有资质的危险废物处置单位进行处理。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4660, 4833, '危险废物', '建议用焚烧法处置。在能保证充分燃烧的条件下,将废弃物与大量空气混合焚烧。焚烧炉排出的气体要通过洗涤器除去。根据国家和地方有关法规的要求处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4661, 4834, '危险废物', '建议用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4662, 4835, '危险废物', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4663, 4836, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4664, 4837, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4665, 4838, '有毒、强氧化性、强腐蚀性气体。', '建议用控制焚烧法处置。在专业设施中，用碱液（如氢氧化钠溶液）吸收后进行无害化处理。必须由有资质的危险废物处理单位进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4666, 4839, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。焚烧炉排出的卤化氢通过酸洗涤器除去。', '用控制焚烧法处置。废弃物与燃料混合后焚烧，焚烧炉要装有净化装置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4667, 4840, '处置前应参阅国家和地方有关法规。本品及内装物、容器依据国家和地方法规处置。', '建议用焚烧法处置。在能利用的地方重复使用容器或在规定场所掩埋。用水泥、沥青或适当的热塑性材料固化处理再废弃。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4668, 4841, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。在能保证充分燃烧的条件下，焚烧炉排出的气体通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
