INSERT INTO `msds_disposal` VALUES (4688, 4862, '无资料', '根据国家和地方有关法规的要求处置。或与厂商或制造商联系，确定处置方法。废物储存参见\"储存注意事项\"。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
