INSERT INTO `msds_disposal` VALUES (4692, 4867, '属于危险废物，具有毒性和腐蚀性', '建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去。或与水反应后，用碱性物质中和，然后按照当地法规进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
