INSERT INTO `msds_disposal` VALUES (4694, 4870, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4695, 4871, '危险废物，具有爆炸性、毒性和环境危害。属于易制爆危险化学品。', '建议用焚烧法处置，焚烧炉排出的氮氧化物、氯化氢等有毒气体通过洗涤器除去。或根据当地法规委托有资质的危险废物处理单位进行处置。处置前应进行稳定化处理以降低爆炸风险。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4696, 4872, '该物质属于危险废物，具有爆炸性、毒性和刺激性。废弃的重氮盐需按照规定的危险废物处理程序进行处理，避免对环境造成污染。', '建议使用焚烧法处置，焚烧炉应配备尾气净化装置，确保完全燃烧并处理产生的有毒气体。也可委托有资质的危险废物处理单位进行处置。处置过程应符合《危险废物焚烧污染控制标准》（GB 18484）和《危险废物贮存污染控制标准》（GB 18597）的要求。禁止随意倾倒或排入下水道。反应结束后剩余的重氮盐需经碱性中和降解处理后再进行最终处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4697, 4873, '该物质属于危险化学品废弃物，具有毒性、易燃性等危险特性。', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。废弃物应交由有资质的危险废物处理单位进行处置。处理前应咨询当地环保部门和相关法规要求。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4698, 4874, '危险废物，具有毒性和反应性', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。或按照地方、区域、国家、国际法规处置废弃化学品和容器。必须交由有危险废物处理资质的单位进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4699, 4875, '危险废物，具有毒性和易燃性。', '建议使用焚烧法处置。焚烧必须在具备相应资质的危险废物处置设施中进行，并确保完全燃烧。焚烧过程中产生的废气必须经过净化处理，达到排放标准后方可排放。也可采用化学稳定化/固化后填埋的方法处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4700, 4876, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
