INSERT INTO `msds_disposal` VALUES (4787, 4965, '危险废物', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。与易燃物、还原剂等分开处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4788, 4966, '危险废物，具有毒性', '建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去。与易燃物混合后焚烧。采用安全掩埋法处置。必须按照当地法律法规和相关标准进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4789, 4967, '危险废物，氧化性固体', '建议用控制焚烧法处理。焚烧炉排出的气体要通过洗涤器除去。与当地环保部门联系，按照相关法规处理。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4790, 4968, '危险废物', '建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4791, 4969, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去。', '建议用控制焚烧法处置。也可以用中和法处理，将废弃物缓慢加入大量水中，用碱性物质（如石灰、氢氧化钠）中和至pH值7-8，然后排入废水系统。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4792, 4970, '危险废物，含砷化合物', '建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去。与当地环保部门联系，按照危险废物管理法规进行处理。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4793, 4971, '危险废物，属于含砷废物。', '建议用焚烧法处置，焚烧温度需≥1100℃，焚烧炉排出的气体通过洗涤器除去砷氧化物。废弃物应交由有资质的危险废物处理单位进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4794, 4972, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
