INSERT INTO `msds_disposal` VALUES (4796, 4974, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4797, 4975, '危险废物。根据《国家危险废物名录》属于HW49类（其他废物），废物代码900-041-49。具有持久性、生物累积性和毒性（PBT）特性。可能对生态环境造成长期危害。属于持久性有机污染物（POPs）范畴', '1. 高温焚烧：在温度≥1100°C、停留时间≥2秒的条件下进行焚烧，确保完全分解。应配备完善的烟气净化系统，去除酸性气体（HCl、SO2）和颗粒物。2. 水泥窑协同处置：在水泥熟料生产过程中作为替代燃料使用，利用高温环境彻底分解。3. 专业危废处理：交由具有危险废物经营许可证的专业机构处理。4. 化学处理：采用脱溴技术进行预处理，降低毒性。5. 禁止采用填埋方式处置', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
