INSERT INTO `msds_disposal` VALUES (4825, 5003, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4826, 5004, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。在能保证充分燃烧的条件下，焚烧炉排出的气体通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4827, 5005, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '根据国家和地方有关法规，建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去氰化氢。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4828, 5006, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '根据国家和地方有关法规，建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去氰化氢和汞蒸气。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4829, 5007, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4830, 5008, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。在处理氰化物废物时，必须严格遵守国家有关危险废物处置的规定。应委托有资质的危险废物处理单位进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4831, 5009, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '根据国家和地方有关法规，建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4832, 5010, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '根据国家和地方有关法规，建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去氰化氢和镉化合物。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4833, 5011, '危险废物，属于HW29含氰废物和HW49其他废物。含有剧毒的氰化物和汞，对环境和人体健康有严重危害。', '建议用焚烧法处置，焚烧温度需达到1100℃以上，停留时间应超过2秒，焚烧炉必须配备完善的尾气处理系统，以去除氰化氢和汞蒸气。也可以委托有资质的危险废物处置单位进行处理。处理前应先用碱性溶液（如氢氧化钠）处理，使氰化物转化为无毒的氰酸盐，再进行汞的回收处理。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4834, 5012, '危险废物。具有剧毒，含氰化物和汞，对环境和人体健康有严重危害。', '建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去。废弃化学品应交由有资质的危险废物处理单位处理。处理前应先进行氧化处理，使氰化物转化为无毒物质，再进行汞的回收处理。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4835, 5013, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4836, 5014, '危险废物，含氰化物', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。与易燃物混合后焚烧。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4837, 5015, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '根据国家和地方有关法规，建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4838, 5016, '危险废物，含氰化物', '作为危险废物处置。建议使用焚烧法处理，需配备尾气处理装置以去除氰化氢。在处理前，可用次氯酸钠等氧化剂进行氧化处理。必须委托有资质的危险废物处理单位进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4839, 5017, '氰化物类危险废物。', '建议使用控制焚烧法处理。处理前应进行氰化物解毒处理。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4840, 5018, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4841, 5019, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '根据国家和地方有关法规，建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去氰化氢和镍化合物。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4842, 5020, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '根据国家和地方有关法规，建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去氰化氢和镍化合物。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4843, 5021, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '根据国家和地方有关法规，建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去氰化氢和铅化合物。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4844, 5022, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '根据国家和地方有关法规，建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去氰化氢和铜化合物。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4845, 5023, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '根据国家和地方有关法规，建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去氰化氢和锌化合物。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4846, 5024, '剧毒化学品，对环境和人体健康有严重危害。', '建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去。与易燃物混合后焚烧。在专业危险化学品废物处理中心处置。处置前应咨询当地环保部门，遵守相关法律法规。禁止随意倾倒或排放到下水道、河流、湖泊等环境中。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4847, 5025, '氰化亚金钾属于剧毒危险化学品，含有氰化物和重金属金，具有极高的毒性和环境危害性。废弃物必须按照危险废物管理，严禁随意排放或倾倒。', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。根据国家和地方有关法规，处置前应咨询环保部门或专业废弃物处理机构。氰化物废弃物也可采用化学氧化法（如次氯酸钠、过氧化氢）进行解毒处理，将氰化物转化为毒性较低的氰酸盐或二氧化碳和氮气。含金废液应回收金金属后再进行氰化物解毒处理。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4848, 5026, '处置前应参阅国家和地方有关法规。', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。根据国家和地方有关法规，处置前应咨询环保部门或专业废弃物处理机构。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4849, 5027, '氰化物属于危险废物，具有剧毒性。处置前应参阅国家和地方有关法规。', '建议用焚烧法处置。焚烧炉应配备尾气处理装置，确保氰化氢等有毒气体得到有效处理。也可在专业机构进行化学氧化处理，将氰化物转化为无毒物质。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4850, 5028, '氰化物属于危险废物，具有剧毒特性。废弃前应进行无害化处理，将氰化物氧化为无毒或低毒物质。', '建议用焚烧法处置。焚烧炉需配备尾气处理系统，确保氰化氢等有毒气体完全分解。也可使用化学氧化法，如使用次氯酸钠、过氧化氢等氧化剂将氰化物氧化为氰酸盐，最终转化为二氧化碳和氮气。处置前应参阅国家和地方有关法规，委托有资质的危险废物处理单位进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4851, 5029, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '根据国家和地方有关法规，建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去氰化氢和银化合物。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4852, 5030, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '根据国家和地方有关法规，建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去氰化氢、氰化物和银化合物。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4853, 5031, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '根据国家和地方有关法规，建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去氰化氢。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4854, 5032, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '根据国家和地方有关法规，建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去氰化氢。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4855, 5033, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '根据国家和地方有关法规，建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去氰化氢。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4856, 5034, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '根据国家和地方有关法规，建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去氯化氢。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4857, 5035, '氰乙酸丁酯属于危险化学品废弃物，具有毒性和易燃性。处置前应参阅国家和地方有关法规。建议用焚烧法处置，在能保证充分燃烧的条件下，焚烧炉排出的气体通过洗涤器除去有害物质。', '建议用焚烧法处置。在能保证充分燃烧的条件下，焚烧炉排出的气体通过洗涤器除去。焚烧温度应达到1200℃以上，以确保氰基化合物完全分解。也可以委托有资质的危险废物处理单位进行处置。严禁将废弃物直接排入下水道、土壤或水体中。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4858, 5036, '属于危险废物，具有毒性和持久性。', '建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去。与当地环保部门联系，按照国家和地方有关危险废物处置的法律法规进行处理。处置前应参阅国家和地方有关法规。废物处置应交由有资质的危险废物处理单位进行。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4859, 5037, '危险废物，具有毒性和持久性。属于持久性有机污染物（POPs），具有PBT（持久性、生物富集性、毒性）特性。', '建议采用高温焚烧法处置（温度≥1000℃），确保完全分解。焚烧炉排出的气体必须通过洗涤器等净化装置处理。必须委托具有危险废物经营许可证的单位进行处置。严格按照《危险废物经营许可证管理办法》和《国家危险废物名录》的规定执行。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4860, 5038, '有害废弃物，属于危险废物。', '建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去。与易燃物、还原剂、酸类、活性金属粉末等分开存放。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4861, 5039, '属于危险废物，含有持久性有机污染物', '建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去。根据当地法规，委托有资质的危险废物处理单位进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4862, 5040, '属于危险废物，具有持久性有机污染物特性。', '建议使用高温焚烧技术进行处置。焚烧装置应配备尾气处理系统，确保有毒有害物质完全分解。处置前应咨询当地环保部门，按照《危险废物经营许可证管理办法》等相关法规要求，委托有资质的危险废物处置单位进行处理。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4863, 5041, '属于危险废物，具有持久性、生物累积性和毒性。', '建议用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。作为持久性有机污染物，应按照《关于持久性有机污染物的斯德哥尔摩公约》和相关法规要求进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4864, 5042, '属于危险废物，具有毒性和持久性。', '建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去。与当地环保部门联系，按照国家和地方有关危险废物处置的法律法规进行处理。处置前应参阅国家和地方有关法规。废物处置应交由有资质的危险废物处理单位进行。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4865, 5043, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去。', '建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
