INSERT INTO `msds_disposal` VALUES (4907, 5085, '毒害性废物', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。废弃物应交由有资质的危险废物处理单位进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4908, 5086, '危险废物，具有易燃性和毒性。', '建议用焚烧法处置。与燃料混合后，再焚烧。焚烧炉排出的卤化氢通过酸洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4909, 5087, '危险废物，属于含氟无机废物。', '建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去氟化氢。也可采用化学稳定化处理后填埋的方法。处置前应与供应商或专业废物处理机构联系。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4910, 5088, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。废弃物与燃料混合后，在装有洗涤器的焚烧炉中焚烧。焚烧炉排出的氮氧化物通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4911, 5089, '危险废物', '建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
