INSERT INTO `msds_disposal` VALUES (4913, 5091, '该物质属于危险废物，具有强氧化性和强腐蚀性。', '建议用焚烧法处置。焚烧处置应委托有资质的危险废物处置单位进行，并符合GB 18484-2020危险废物焚烧污染控制标准的要求。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
