INSERT INTO `msds_disposal` VALUES (4945, 5123, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4946, 5124, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用控制性水解法处理。在控制条件下缓慢加入水中，生成盐酸和硅酸，然后中和处理。或交由有资质的化学废物处理机构处理。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4947, 5125, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4948, 5126, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4949, 5127, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '集中收集后交由有资质的危险废物处置单位进行安全处置。应采用高温焚烧法处置，焚烧温度需≥1100℃，停留时间≥2秒，确保完全燃烧。尾气需经碱洗、活性炭吸附等处理以去除氯化氢、氧化磷、磷烷，确保达标排放。也可采用化学处理法，在碱性条件下水解后，按危险废物进行处置。禁止将未经处理的废物直接排入环境。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4950, 5128, '危险废物，具有腐蚀性。', '建议用焚烧法处置。焚烧炉排出的氯化氢通过酸洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4951, 5129, '危险废物，毒性物质。', '建议用焚烧法处置。焚烧炉排出的氯化氢通过酸洗器除去。或与燃料混合后焚烧。废弃物处置必须符合国家有关危险废物管理的规定。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4952, 5130, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
