INSERT INTO `msds_disposal` VALUES (4954, 5132, '危险废物', '用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。建议用控制性焚烧。与易燃物分开处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
