INSERT INTO `msds_disposal` VALUES (4958, 5136, '危险废物，腐蚀性物质。', '建议用焚烧法处置。焚烧炉排出的氯化氢通过酸洗器除去。或与燃料混合后焚烧。废弃物处置必须符合国家有关危险废物管理的规定。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4959, 5137, '危险废物，具有腐蚀性和毒性。', '建议使用有资质的危险废物处理单位进行处置。可采用高温焚烧方式处理，确保完全燃烧。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (4960, 5138, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '集中收集后交由有资质的危险废物处置单位进行安全处置。应采用高温焚烧法处置，焚烧温度需≥1100℃，停留时间≥2秒，确保完全燃烧。尾气需经碱洗、活性炭吸附等处理以去除氯化氢和光气，确保达标排放。也可采用化学处理法，在碱性条件下处理后，按危险废物进行处置。禁止将未经处理的废物直接排入环境。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
