INSERT INTO `msds_disposal` VALUES (4988, 5166, '有害废物，属于危险废物类别中的有机卤素化合物废物', '建议用控制性焚烧法处置。焚烧炉排出的溴化氢和氮氧化物通过洗涤器除去。焚烧温度应控制在850°C以上，停留时间不少于2秒，确保完全分解。焚烧设施应配备废气净化系统，处理燃烧产生的溴化氢和可能产生的二噁英等副产物。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
