INSERT INTO `msds_disposal` VALUES (5040, 5218, '有机废物，易燃液体', '建议用焚烧法处置。在符合环保要求的焚烧炉中进行，确保充分燃烧。处置前应参阅国家和地方有关法规。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5041, 5219, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。焚烧炉排出的硫氧化物通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5042, 5220, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。焚烧炉排出的硫氧化物通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
