INSERT INTO `msds_disposal` VALUES (5046, 5224, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5047, 5225, '危险废物', '建议用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5048, 5226, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。在焚烧炉中焚烧时，应配备尾气处理设施，确保完全燃烧，防止有害气体排放。废弃物应交由有资质的危险废物处理单位进行集中处理。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5049, 5227, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。在焚烧炉中焚烧时，应配备尾气处理设施，确保完全燃烧，防止氯化氢等有害气体排放。废弃物应交由有资质的危险废物处理单位进行集中处理。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5050, 5228, '危险废物', '建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去。在处理和处置过程中，必须遵守国家和地方的有关危险废物管理规定。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5051, 5229, '危险废物', '建议用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
