INSERT INTO `msds_disposal` VALUES (5053, 5231, '危险废物', '建议用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5054, 5232, '危险废物', '建议用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5055, 5233, '危险废物', '建议用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5056, 5234, '危险废物', '建议用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5057, 5235, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5058, 5236, '废物性质：叔丁基苯属于第3.3类高闪点易燃液体。具有易燃性、刺激性。对水生生物具有毒性。对环境可能造成危害。属于危险废物，需要按照危险废物进行管理和处置。', '处置方法：建议用焚烧法处置。焚烧应在有资质的危险废物焚烧设施中进行，焚烧温度应不低于850℃，停留时间应不少于2秒。焚烧设施应配备完善的烟气处理系统，确保烟气排放符合国家和地方环保标准。也可采用化学氧化、生物降解等方法进行处理，但需确保处理效果达到环保要求。处置前应参阅国家和地方有关法规。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5059, 5237, '有机过氧化物废物，具有易燃性和氧化性。', '建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去。处置前应与有资质的废物处理机构联系，按照当地法规进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5060, 5238, '危险废物，属于有机过氧化物类危险废物', '建议用焚烧法处置，焚烧温度应达到1100℃以上，停留时间应超过2秒，焚烧炉必须配备完善的尾气处理系统。也可以委托有资质的危险废物处置单位进行处理。处置前应查阅国家和地方有关法规。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5061, 5239, '有机过氧化物废弃物，具有易燃性和氧化性。', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。根据国家和地方有关法规的要求处置。或与有资质的危险废物处理单位联系，按照相关法规进行处置。废弃化学品和包装容器应按照危险废物管理规定进行处理。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5062, 5240, '有机过氧化物废物', '建议用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。废弃物应交由有资质的危险废物处理单位进行处理。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5063, 5241, '有机过氧化物废物', '建议在具备资质的危险废物处理设施中进行处置。根据当地相关法律法规进行处理。不得随意倾倒或排放到环境中。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5064, 5242, '危险废物，HW49其他废物（900-041-49）', '建议用焚烧法处置。焚烧温度应达到1100℃以上，停留时间应超过2秒。焚烧炉必须配备完善的尾气处理系统。也可以委托有资质的危险废物处置单位进行处理。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5065, 5243, '1. 属于危险废物，废物类别：HW06（废有机溶剂与含有机溶剂废物）或HW49（其他废物）2. 具有易燃性、毒性、刺激性3. 废弃物必须按照《危险废物管理条例》等相关法律法规进行管理4. 废弃物处置前应进行分类、标识、包装', '1. 建议采用焚烧法处置，焚烧温度应≥1100℃，停留时间≥2秒2. 焚烧炉应配备完善的废气处理系统，包括洗涤器、除尘器等3. 焚烧炉排出的气体要通过洗涤器除去硫化物、氮氧化物等污染物4. 废弃物应交由有资质的危险废物处理单位进行处置5. 禁止随意倾倒、排放或填埋6. 废弃物包装应符合危险废物包装标准，确保运输安全', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5066, 5244, '危险废物，具有腐蚀性和易燃性。', '建议用焚烧法处置。焚烧前必须进行中和处理，使用碱性物质（如氢氧化钠、氢氧化钙、碳酸钠等）将废液中和至pH值6-9。处理过程中产生的废水需要进一步处理，确保达到排放标准后方可排放。废弃物处置必须委托有资质的危险废物处理单位进行。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5067, 5245, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5068, 5246, '危险废物，有机过氧化物', '委托有资质的单位进行焚烧处置。小量可采用控制焚烧法处置。禁止与可燃物混合焚烧。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5069, 5247, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
