INSERT INTO `msds_disposal` VALUES (5092, 5270, '有害固体废物，具有毒性。', '建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去。根据国家和地方有关法规，交由有资质的危险废物处理单位处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5093, 5271, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '用焚烧法处置。与燃料混合后，再焚烧。焚烧炉排出的卤化氢通过酸洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5094, 5272, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5095, 5273, '危险化学品废物', '建议用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。与当地环保部门联系，按照危险废物管理要求进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5096, 5274, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去。', '建议用焚烧法处置。与易燃物混合后焚烧。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5097, 5275, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5098, 5276, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。废弃物属于危险废物，必须委托有资质的危险废物处理单位进行处置。不得随意排放或倾倒。', '建议用焚烧法处置。焚烧时必须配备完善的尾气处理设施，确保充分燃烧，防止产生二次污染。焚烧温度应足够高，以完全分解有机物。焚烧后的残渣应按照危险废物进行处置。也可以委托有资质的危险废物处理单位进行回收或安全处置。处理过程中应避免与水接触，防止产生氟化氢。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5099, 5277, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5100, 5278, '属于危险废物，具有毒性、腐蚀性。遇水反应产生氟化氢，具有强腐蚀性。含铅废物具有持久性和生物累积性。', '必须委托有资质的危险废物处理单位进行处置。采用化学稳定化/固化处理，将废物转化为稳定的、不溶性的形态。在专业设施中进行高温焚烧处理，确保完全分解。处理过程中应采取有效的尾气处理措施，防止二次污染。禁止随意倾倒或自行处理。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5101, 5279, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5102, 5280, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5103, 5281, '属于危险废物，具有爆炸性、毒性、腐蚀性。重氮化合物具有热不稳定性，遇热、撞击、摩擦可能引起爆炸。氟化物具有腐蚀性。', '必须委托有资质的危险废物处理单位进行处置。采用化学稳定化/固化处理，将废物转化为稳定的、不溶性的形态。在专业设施中进行受控分解处理，确保完全分解。处理过程中应采取有效的尾气处理措施，防止二次污染。禁止随意倾倒或自行处理。处置时应遵守《危险废物经营许可证管理办法》等相关法规。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5104, 5282, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。废弃物属于危险废物，必须委托有资质的危险废物处理单位进行处置。不得随意排放或倾倒。', '建议用焚烧法处置。焚烧时必须配备完善的尾气处理设施，确保充分燃烧，防止产生二次污染。焚烧温度应足够高，以完全分解有机物。焚烧后的残渣应按照危险废物进行处置。也可以委托有资质的危险废物处理单位进行回收或安全处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5105, 5283, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用焚烧法处置。焚烧炉排出的气体要通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5106, 5284, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用控制焚烧法处置。焚烧炉排出的气体通过洗涤器除去。必须委托有资质的危险废物处理单位进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
