INSERT INTO `msds_disposal` VALUES (5110, 5288, '本品属于危险废物，具有腐蚀性和毒性。遇水产生有毒的氯化氢气体。', '建议用焚烧法处置。在高温条件下使有害物质氧化分解，达到减量化和无害化的目的。需控制焚烧温度、停留时间等参数。处置前应向环保部门进行危险废物申报登记，委托具有法定资质的单位进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
