INSERT INTO `msds_disposal` VALUES (5413, 5593, '危险废物', '建议用焚烧法处置。焚烧炉配备除尘和焚烧尾气处理装置。处置前应参阅国家和地方有关法规。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5414, 5594, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5415, 5595, '危险废物，具有致癌性和毒性。属于危险废物名录HW02医药废物或HW49其他废物', '建议用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。在能利用的地方，回收或再利用。处置前应参阅国家和地方有关法规，禁止随意倾倒。操作人员必须佩戴适当的防护装备。焚烧温度需≥1100℃，确保完全分解。应委托有危险废物处理资质的单位进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5416, 5596, '危险废物，具有致癌性和毒性。属于危险废物名录HW02医药废物或HW49其他废物', '建议用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。在能利用的地方，回收或再利用。处置前应参阅国家和地方有关法规，禁止随意倾倒。操作人员必须佩戴适当的防护装备。焚烧温度需≥1100℃，确保完全分解。应委托有危险废物处理资质的单位进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5417, 5597, '危险废物。处置前应参阅国家和地方有关法规。', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
