INSERT INTO `msds_disposal` VALUES (5447, 5627, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '建议用控制焚烧法处置。焚烧炉排出的氯化氢和氧化铬气体通过洗涤器除去。处置前应参阅国家和地方有关法规。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5448, 5628, '危险废物', '建议用控制焚烧法处置。焚烧炉排出的氯化氢和氧化硫气体通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5449, 5629, '危险废物', '建议用控制焚烧法处置。焚烧炉排出的氯化氢和氧化硒气体通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5450, 5630, '危险废物', '建议用控制焚烧法处置。焚烧炉排出的氮氧化物、汞和氰化氢气体通过洗涤器除去。处置前应参阅国家和地方有关法规。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5451, 5631, '处置前应参阅国家和地方有关法规。建议用焚烧法处置。', '在专用焚烧炉中焚烧，配备洗涤器或过滤器以去除酸性气体。或与碱性物质中和后，按照当地环保部门的要求进行安全处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5452, 5632, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
