INSERT INTO `msds_disposal` VALUES (5516, 5697, '废弃物性质：危险废物。', '建议用焚烧法处置。焚烧炉排出的气体通过洗涤器除去。也可用控制性焚烧。与燃料混合后焚烧。焚烧炉要配备除尘器和洗涤器。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
