INSERT INTO `msds_disposal` VALUES (5518, 5699, '危险废物，具有毒性和环境危害性。', '建议委托有资质的危险废物处理单位进行处置。根据当地法律法规，按照危险废物管理要求进行收集、储存、运输和处置。可采用焚烧法处理，焚烧过程中应配备废气处理设施。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
