INSERT INTO `msds_disposal` VALUES (5668, 5849, '危险废物，有机胺类', '建议用控制焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器或高温装置除去。与燃料混合后，再焚烧。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
