INSERT INTO `msds_disposal` VALUES (5670, 5851, '氧化性固体废物', '建议用焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5671, 5852, '危险废物', '建议用控制焚烧法处置。在能保证充分燃烧的焚烧炉中焚烧，并配备洗涤器以除去酸性气体。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
