INSERT INTO `msds_disposal` VALUES (5677, 5858, '危险废物', '建议用控制焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。处理前应中和还原，交由有资质的单位处理。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5678, 5859, '危险废物', '建议用控制焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。焚烧后的残渣按危险废物处理。也可采用化学还原法，将六价铬还原为三价铬后，再进行固化处理。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5679, 5860, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5680, 5861, '危险废物', '建议用控制焚烧法处置。焚烧炉排出的氮氧化物通过洗涤器除去。废物应交由有资质的危险废物处理单位处理', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5681, 5862, '危险废物', '建议用还原剂（如亚硫酸钠、硫酸亚铁等）将六价铬还原为三价铬，然后用碱性物质沉淀，沉淀物按危险废物处理。或交由有资质的危险废物处理单位进行处置。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_disposal` VALUES (5682, 5863, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
