INSERT INTO `msds_ecological` VALUES (2867, 3021, '对水生生物和陆生生物具有高毒性，对鱼类、鸟类和哺乳动物有害。LC50（96小时，鱼类）：0.002-0.01 mg/L。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:27', '', NULL);
INSERT INTO `msds_ecological` VALUES (2868, 3022, '本品为有机硫氰酸酯类农药，对水生生物可能具有毒性。应避免进入水体、土壤和地下水。对鱼类和其他水生生物可能有害。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:27', '', NULL);
