INSERT INTO `msds_ecological` VALUES (2873, 3027, '对水生生物具有高毒性，对鱼类和水生无脊椎动物尤其敏感。应避免进入水体、土壤和地下水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:29', '', NULL);
INSERT INTO `msds_ecological` VALUES (2874, 3028, '0,0-二乙基硫代磷酰氯对水生生物有毒性。对鱼类LC50（96h）：1-10mg/L；对甲壳类LC50（48h）：0.1-1mg/L；对藻类EC50（72h）：1-10mg/L。对鸟类、哺乳动物等陆生生物也有毒性作用。对水生生物可能有害，应避免进入水体、土壤和地下水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:30', '', NULL);
