INSERT INTO `msds_ecological` VALUES (2876, 3030, '1-(2-叔丁基过氧异丙基)-3-异丙烯基苯对水生生物有毒性。对鱼类LC50（96h）：1-10mg/L；对甲壳类LC50（48h）：0.1-1mg/L；对藻类EC50（72h）：1-10mg/L。对鸟类、哺乳动物等陆生生物也有毒性作用。对水生生物可能有害，应避免进入水体、土壤和地下水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:30', '', NULL);
INSERT INTO `msds_ecological` VALUES (2877, 3031, '属于温室气体，对大气和臭氧层具有潜在影响，泄漏会在封闭空间造成窒息风险。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:30', '', NULL);
INSERT INTO `msds_ecological` VALUES (2878, 3032, '对水生生物和陆生生物具有高毒性，对鸟类、鱼类、哺乳动物有害。LC50（96小时，鱼类）：0.01-0.1 mg/L。对鸟类影响尤其严重，可导致蛋壳变薄、繁殖失败。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:31', '', NULL);
INSERT INTO `msds_ecological` VALUES (2879, 3033, '对水生生物可能有害，应避免进入水体、土壤和地下水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:31', '', NULL);
INSERT INTO `msds_ecological` VALUES (2880, 3034, 'PFOS对水生生物具有高毒性（急性毒性类别2，慢性毒性类别1），对鱼类和水生无脊椎动物尤其敏感。在环境中极难降解，具有极高的生物富集性，可通过食物链传递，对生态系统造成长期严重危害。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:32', '', NULL);
INSERT INTO `msds_ecological` VALUES (2881, 3035, '1,1,2,2-四氯乙烷对水生生物有毒性。对鱼类LC50（96h）：1-10mg/L；对甲壳类LC50（48h）：0.1-1mg/L；对藻类EC50（72h）：1-10mg/L。对鸟类、哺乳动物等陆生生物也有毒性作用。对水生生物有毒，应避免进入水体、土壤和地下水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:32', '', NULL);
INSERT INTO `msds_ecological` VALUES (2882, 3036, '属消耗臭氧层物质，对大气环境有长期影响。对水生生物毒性较低但应避免进入水体和土壤。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:32', '', NULL);
