INSERT INTO `msds_ecological` VALUES (2888, 3042, '1,1-二(2-甲氧基乙氧基)乙烷对水生生物有毒性。对鱼类LC50（96h）：10-100mg/L；对甲壳类LC50（48h）：1-10mg/L；对藻类EC50（72h）：10-100mg/L。对水生生物可能有害，应避免大量排放。应避免进入水体、土壤和地下水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:34', '', NULL);
INSERT INTO `msds_ecological` VALUES (2889, 3043, '1,1-二-(叔丁基过氧)-3,3,5-三甲基环己烷对水生生物有毒性。对鱼类LC50（96h）：1-10mg/L；对甲壳类LC50（48h）：0.1-1mg/L；对藻类EC50（72h）：1-10mg/L。对鸟类、哺乳动物等陆生生物也有毒性作用。对水生生物可能有害，应避免进入水体、土壤和地下水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:34', '', NULL);
INSERT INTO `msds_ecological` VALUES (2890, 3044, '对水生生物可能有害，应避免进入水体、土壤和地下水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:36', '', NULL);
INSERT INTO `msds_ecological` VALUES (2891, 3045, '对水生生物可能有害。慢性水生毒性（过氧化(2-乙基己酸)叔丁酯）：甲壳纲动物，NOEC：0.62mg/L；藻类/水生植物，NOEC：0.017mg/L。应避免进入水体、土壤和地下水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:37', '', NULL);
INSERT INTO `msds_ecological` VALUES (2892, 3046, '对大气可造成污染。在大气中可被能量更大的紫外线分解。对水生生物可能有害。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:37', '', NULL);
INSERT INTO `msds_ecological` VALUES (2893, 3047, '1,1-二甲基环己烷对水生生物有毒性。对鱼类LC50（96h）：1-10mg/L；对甲壳类LC50（48h）：0.1-1mg/L；对藻类EC50（72h）：1-10mg/L。对鸟类、哺乳动物等陆生生物也有毒性作用。对水生生物可能有害，应避免进入水体、土壤和地下水。该物质对环境有危害，应特别注意对地表水、土壤、大气和饮用水的污染。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:37', '', NULL);
INSERT INTO `msds_ecological` VALUES (2894, 3048, '1,1-二甲基环戊烷对水生生物有毒性。对鱼类LC50（96h）：1-10mg/L；对甲壳类LC50（48h）：0.1-1mg/L；对藻类EC50（72h）：1-10mg/L。对鸟类、哺乳动物等陆生生物也有毒性作用。对水生生物可能有害，应避免进入水体、土壤和地下水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:38', '', NULL);
