INSERT INTO `msds_ecological` VALUES (2897, 3051, '1,1-二氯-1-硝基乙烷对水生生物有毒性。对鱼类LC50（96h）：1-10mg/L；对甲壳类LC50（48h）：0.1-1mg/L；对藻类EC50（72h）：1-10mg/L。对鸟类、哺乳动物等陆生生物也有毒性作用。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:39', '', NULL);
INSERT INTO `msds_ecological` VALUES (2898, 3052, '对水生生物可能有害，应避免进入水体、土壤和地下水。本品为有机氯农药，在环境中难以降解，具有持久性。在水生生物中可能发生生物蓄积。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:39', '', NULL);
INSERT INTO `msds_ecological` VALUES (2899, 3053, '1,1-二氯丙酮对水生生物有毒性。对鱼类LC50（96h）：1-10mg/L；对甲壳类LC50（48h）：0.1-1mg/L；对藻类EC50（72h）：1-10mg/L。对鸟类、哺乳动物等陆生生物也有毒性作用。1,1-二氯丙酮对水生生物有毒，应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。挥发后可参与形成光化学烟雾。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:39', '', NULL);
INSERT INTO `msds_ecological` VALUES (2900, 3054, '对鱼类LC50（96h）：1-10mg/L\n        对甲壳类LC50（48h）：0.1-1mg/L\n        对藻类EC50（72h）：1-10mg/L', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:39', '', NULL);
