INSERT INTO `msds_ecological` VALUES (2903, 3057, '六氯环己烷对水生生物有极高毒性。对鱼类LC50（96h）：0.01-0.1mg/L；对甲壳类LC50（48h）：0.001-0.01mg/L；对藻类EC50（72h）：0.01-0.1mg/L。对鸟类LD50：50-200mg/kg。对哺乳动物也有毒性作用。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:40', '', NULL);
