INSERT INTO `msds_ecological` VALUES (3049, 3207, '1-萘胺对水生生物有剧毒。对鱼类LC50（96h）：0.1-1mg/L；对甲壳类LC50（48h）：0.01-0.1mg/L；对藻类EC50（72h）：0.1-1mg/L。对鸟类、哺乳动物等陆生生物也有毒性作用。应避免进入水体、土壤和地下水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:28', '', NULL);
INSERT INTO `msds_ecological` VALUES (3050, 3208, '1-萘甲腈对水生生物有毒性。对鱼类LC50（96h）：1-10mg/L；对甲壳类LC50（48h）：0.1-1mg/L；对藻类EC50（72h）：1-10mg/L。含氰基，在环境中可能分解产生氰化物，对水生生物有极高毒性。对鸟类、哺乳动物等陆生生物也有毒性作用。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:28', '', NULL);
INSERT INTO `msds_ecological` VALUES (3051, 3209, '1-萘氧基二氯化膦对水生生物有毒性。对鱼类LC50（96h）：1-10mg/L；对甲壳类LC50（48h）：0.1-1mg/L；对藻类EC50（72h）：1-10mg/L。对鸟类、哺乳动物等陆生生物也有毒性作用。与水或水蒸气反应释出有毒的腐蚀性气体，对大气环境有污染。对水生生物可能有害，应避免进入水体、土壤和地下水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:28', '', NULL);
