INSERT INTO `msds_ecological` VALUES (3353, 3519, '对水生生物有毒性。对鱼类、水生无脊椎动物和藻类具有毒性作用（参考同类硝基苯酚化合物数据）。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:41', '', NULL);
