INSERT INTO `msds_ecological` VALUES (3355, 3521, '该物质对水生生物有毒性。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:41', '', NULL);
INSERT INTO `msds_ecological` VALUES (3356, 3522, '对水生生物有毒作用。基于硝基苯类化合物毒性推断，对鱼类、水生无脊椎动物和水生植物具有毒性。可能对水生生态系统造成长期影响。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:42', '', NULL);
INSERT INTO `msds_ecological` VALUES (3357, 3523, '对水生生物有毒性。硝基芳香族化合物通常对鱼类、水生无脊椎动物和藻类具有毒性作用。具体毒性数据暂无，建议避免向水体环境中排放。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:43', '', NULL);
INSERT INTO `msds_ecological` VALUES (3358, 3524, '对水生生物有剧毒。砷化合物在环境中具有持久性，对水生生态系统可能造成长期危害。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:43', '', NULL);
INSERT INTO `msds_ecological` VALUES (3359, 3525, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:43', '', NULL);
INSERT INTO `msds_ecological` VALUES (3360, 3526, '2-硝基丙烷对水生生物有毒性。对鱼类LC50（96h）：10-100mg/L；对甲壳类LC50（48h）：1-10mg/L；对藻类EC50（72h）：10-100mg/L。对鸟类、哺乳动物等陆生生物也有毒性作用。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:43', '', NULL);
INSERT INTO `msds_ecological` VALUES (3361, 3527, '硝基苯进入水体后，会对水生生物产生毒性作用，破坏水生生态系统的平衡。由于硝基苯难溶于水且密度比水大，它会在水体底部积累，长期影响水体的质量，导致水中的溶解氧降低（参考硝基苯类化合物数据）。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:43', '', NULL);
INSERT INTO `msds_ecological` VALUES (3362, 3528, '对水生生物有毒', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:45', '', NULL);
INSERT INTO `msds_ecological` VALUES (3363, 3529, '对水生生物有毒性', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:45', '', NULL);
INSERT INTO `msds_ecological` VALUES (3364, 3530, '2-硝基甲苯对水生生物有毒性。对鱼类LC50（96h）：1-10mg/L；对甲壳类LC50（48h）：0.1-1mg/L；对藻类EC50（72h）：1-10mg/L。对鸟类、哺乳动物等陆生生物也有毒性作用。对水生生物可能有害，应避免进入水体、土壤和地下水。应特别注意对水体的污染。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:45', '', NULL);
