INSERT INTO `msds_ecological` VALUES (3403, 3569, '对水生生物有毒性。鱼类LC50：0.5～5mg/L(96h)；水蚤EC50：0.2～2mg/L(48h)；藻类EC50：1～10mg/L(72h)。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:03', '', NULL);
INSERT INTO `msds_ecological` VALUES (3404, 3570, '对水生生物有极高毒性。鱼类LC50：0.5-2mg/L(96h)；水蚤EC50：0.1-0.5mg/L(48h)；藻类EC50：0.2-1mg/L(72h)。对鸟类和哺乳动物有毒性。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:03', '', NULL);
INSERT INTO `msds_ecological` VALUES (3405, 3571, '对水生生物有毒。鱼类LC50（96小时）：约0.1-10mg/L（因具体品种而异）；水蚤EC50（48小时）：约0.5-5mg/L；藻类EC50（72小时）：约1-20mg/L。对蜜蜂高毒，应避免在蜜蜂活动期使用。对鸟类低毒至中等毒性。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:03', '', NULL);
