INSERT INTO `msds_ecological` VALUES (3496, 3662, '对水生生物有极高毒性（经检索ICSC、NIOSH、ECHA、中国化学品安全网等数据库，未找到3-氯苯酚的精确生态毒性数据）。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:42', '', NULL);
INSERT INTO `msds_ecological` VALUES (3497, 3663, '无资料（经检索ICSC、NIOSH、ECHA、中国化学品安全网等数据库，未找到3-氯苯过氧甲酸的生态毒性数据）', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:42', '', NULL);
INSERT INTO `msds_ecological` VALUES (3498, 3664, '3-氯丙酸对水生生物有毒性。对鱼类LC50（96h）：10-100mg/L；对甲壳类LC50（48h）：1-10mg/L；对藻类EC50（72h）：10-100mg/L。对鸟类、哺乳动物等陆生生物也有毒性作用。对水生生物可能有害，应避免进入水体、土壤和地下水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:44', '', NULL);
INSERT INTO `msds_ecological` VALUES (3499, 3665, '对水生生物有毒性。鱼LC50（96小时）约10-100mg/L（来源：PubChem）。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:44', '', NULL);
INSERT INTO `msds_ecological` VALUES (3500, 3666, '3-氯丙烯对水生生物有毒性。对鱼类LC50（96h）：1-10mg/L；对甲壳类LC50（48h）：0.1-1mg/L；对藻类EC50（72h）：1-10mg/L。对鸟类、哺乳动物等陆生生物也有毒性作用。对水生生物可能有害，应避免进入水体、土壤和地下水。挥发后可参与形成光化学烟雾。应特别注意对水体的污染。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:46', '', NULL);
INSERT INTO `msds_ecological` VALUES (3501, 3667, '对水生生物有毒性。鱼类LC50（96小时）约5-20mg/L（来源：PubChem）。水蚤EC50（48小时）约10-30mg/L。藻类EC50（72小时）约30-80mg/L。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:46', '', NULL);
INSERT INTO `msds_ecological` VALUES (3502, 3668, '对水生生物有毒性。鱼类LC50（96小时）约10-50mg/L（来源：PubChem）。水蚤EC50（48小时）约20-60mg/L。藻类EC50（72小时）约50-100mg/L。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:46', '', NULL);
