INSERT INTO `msds_ecological` VALUES (3504, 3670, '对水生生物有毒并具有长期持续影响。危害水生环境-急性危害，类别2；危害水生环境-长期危害，类别2。LC50：鱼类约10mg/L；水蚤约5mg/L；藻类约2mg/L。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:46', '', NULL);
