INSERT INTO `msds_ecological` VALUES (3510, 3676, '该物质对水生生物可能具有毒性。由于缺乏具体的LC50和EC50数据,建议避免直接排放到水体中。该物质易挥发,可从水中快速挥发,从而减少对水生生物的长期暴露风险。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:50', '', NULL);
