INSERT INTO `msds_ecological` VALUES (3540, 3706, '鱼类LC50：4mg/L（24h）（参考己烷数据）。水蚤EC50：>50mg/L（24h）（参考己烷数据）。藻类IC50：10mg/L（72h）（参考己烷数据）。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:02', '', NULL);
INSERT INTO `msds_ecological` VALUES (3541, 3707, '对水生生物有毒性。LC50（鱼类，96h）>10mg/L；EC50（水蚤，48h）>10mg/L。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:02', '', NULL);
INSERT INTO `msds_ecological` VALUES (3542, 3708, '该物质对水生生物可能具有毒性。由于该物质易溶于水，可能对水生环境造成危害。对鱼类、藻类和水生无脊椎动物的毒性数据有限，建议避免直接排放到水体中。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:03', '', NULL);
