INSERT INTO `msds_ecological` VALUES (3551, 3717, '对水生生物可能有害。有机过氧化物具有一定的生态毒性，可能对鱼类、藻类和微生物产生影响。具体的生态毒性数据无资料。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:06', '', NULL);
INSERT INTO `msds_ecological` VALUES (3552, 3718, '4,6-二硝基-2-氨基苯酚对水生生物有毒性。对鱼类LC50（96h）：1-10mg/L；对甲壳类LC50（48h）：0.1-1mg/L；对藻类EC50（72h）：1-10mg/L。应避免进入水体、土壤和地下水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:06', '', NULL);
INSERT INTO `msds_ecological` VALUES (3553, 3719, '对水生生物有毒性。硝基化合物对多种水生生物具有毒性，包括鱼类、甲壳类和浮游生物。在水生环境中可能对生态系统造成危害。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:08', '', NULL);
INSERT INTO `msds_ecological` VALUES (3554, 3720, '对水生生物有极高毒性。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:08', '', NULL);
INSERT INTO `msds_ecological` VALUES (3555, 3721, '对水生生物有剧毒。对鱼类、水生无脊椎动物和藻类具有高毒性。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:08', '', NULL);
INSERT INTO `msds_ecological` VALUES (3556, 3722, '对水生生物有极高毒性。对鱼类、水生无脊椎动物和藻类具有急性毒性。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:08', '', NULL);
INSERT INTO `msds_ecological` VALUES (3557, 3723, '对水生生物有高毒性。对鱼类毒性显著，在pH9.5时毒性为pH7.5时的38倍。低浓度长期作用可使鱼类种群数量衰减，严重时导致种的灭绝。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:09', '', NULL);
