INSERT INTO `msds_ecological` VALUES (3667, 3833, '对水生生物有极高毒性。对鱼类、水蚤和藻类具有高毒性。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:51', '', NULL);
INSERT INTO `msds_ecological` VALUES (3668, 3834, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:51', '', NULL);
INSERT INTO `msds_ecological` VALUES (3669, 3835, '对水生生物有毒性。鱼类LC50（96小时）约50-100mg/L（估算值）；水蚤EC50（48小时）约30-60mg/L（估算值）；藻类EC50（72小时）约20-50mg/L（估算值）。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:52', '', NULL);
INSERT INTO `msds_ecological` VALUES (3670, 3836, '5-甲基-2-己酮对水生生物有毒性。对鱼类LC50（96h）：100-1000mg/L；对甲壳类LC50（48h）：10-100mg/L；对藻类EC50（72h）：100-1000mg/L。对鸟类、哺乳动物等陆生生物也有毒性作用。对水生生物可能有害，应避免进入水体、土壤和地下水。对水体应给予特别注意。挥发后可参与形成光化学烟雾。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:53', '', NULL);
INSERT INTO `msds_ecological` VALUES (3671, 3837, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:53', '', NULL);
INSERT INTO `msds_ecological` VALUES (3672, 3838, '5-氯-2-甲基苯胺对水生生物有毒性。对鱼类LC50（96h）：1-10mg/L；对甲壳类LC50（48h）：0.1-1mg/L；对藻类EC50（72h）：1-10mg/L。对鸟类、哺乳动物等陆生生物也有毒性作用。对水生生物可能有害，应避免进入水体、土壤和地下水。建议不要让其进入环境。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:53', '', NULL);
INSERT INTO `msds_ecological` VALUES (3673, 3839, '该物质对水生生物可能具有毒性。由于缺乏具体的生态毒性数据，建议避免该物质进入水体。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:53', '', NULL);
INSERT INTO `msds_ecological` VALUES (3674, 3840, '对水生物有剧毒，对水生环境可能会引起长期有害作用。作为典型持久性有机污染物，对水生生态系统具有潜在的生态风险。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:54', '', NULL);
