INSERT INTO `msds_ecological` VALUES (3727, 3893, '对水生物有剧毒。对鱼类、水生无脊椎动物和水生植物可能造成严重危害。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:14', '', NULL);
