INSERT INTO `msds_ecological` VALUES (3730, 3896, '该物质对水生生物有毒。萘胺在水体中不易降解，长期积累可能导致慢性毒性效应，对水生生物和水域生态系统构成长期风险。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:16', '', NULL);
