INSERT INTO `msds_ecological` VALUES (3851, 4017, '该物质遇水分解产生氨气，对水生生物有毒。鱼类LC50（96小时）：0.5-5 mg/L（以氨计）。水蚤EC50（48小时）：0.5-2 mg/L（以氨计）。藻类EC50（72小时）：0.1-1 mg/L（以氨计）。对水生生物有长期影响。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:10', '', NULL);
