INSERT INTO `msds_ecological` VALUES (4013, 4179, '对水生生物有极高毒性。LC50：鱼96小时0.1-1mg/L；水蚤48小时0.01-0.1mg/L。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:15', '', NULL);
INSERT INTO `msds_ecological` VALUES (4014, 4180, '对水生生物有极高毒性。LC50(96小时)：鱼类0.1-1mg/L；水蚤0.01-0.1mg/L；藻类0.01-0.1mg/L', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:16', '', NULL);
INSERT INTO `msds_ecological` VALUES (4015, 4181, '对水生生物有剧毒。对水生生物的影响可能持续很长时间。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:16', '', NULL);
INSERT INTO `msds_ecological` VALUES (4016, 4182, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:16', '', NULL);
INSERT INTO `msds_ecological` VALUES (4017, 4183, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:18', '', NULL);
INSERT INTO `msds_ecological` VALUES (4018, 4184, '丁二腈对水生生物有毒性。对鱼类LC50（96h）：1-10mg/L；对甲壳类LC50（48h）：0.1-1mg/L；对藻类EC50（72h）：1-10mg/L。对鸟类、哺乳动物等陆生生物也有毒性作用。对水生生物可能有害，应避免进入水体、土壤和地下水。应特别注意对水体的污染。受高热或与酸接触会产生剧毒的氰化物气体，对水生生物有剧毒性。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:18', '', NULL);
INSERT INTO `msds_ecological` VALUES (4019, 4185, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:18', '', NULL);
INSERT INTO `msds_ecological` VALUES (4020, 4186, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:18', '', NULL);
INSERT INTO `msds_ecological` VALUES (4021, 4187, '丁二酸对水生生物有毒性。对鱼类LC50（96h）：100-1000mg/L；对甲壳类LC50（48h）：10-100mg/L；对藻类EC50（72h）：100-1000mg/L。对鸟类、哺乳动物等陆生生物也有毒性作用。对水生生物可能有害，应避免进入水体、土壤和地下水。对水体应给予特别注意。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:18', '', NULL);
INSERT INTO `msds_ecological` VALUES (4022, 4188, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:20', '', NULL);
INSERT INTO `msds_ecological` VALUES (4023, 4189, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:20', '', NULL);
INSERT INTO `msds_ecological` VALUES (4024, 4190, '丁二酰氯对水生生物有毒性。对鱼类LC50（96h）：1-10mg/L；对甲壳类LC50（48h）：0.1-1mg/L；对藻类EC50（72h）：1-10mg/L。对鸟类、哺乳动物等陆生生物也有毒性作用。对水生生物可能有害，应避免进入水体、土壤和地下水。应特别注意对水体的污染。遇水分解生成腐蚀性物质（氯化氢和丁二酸），这些产物对水生生物也有毒性。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:20', '', NULL);
