INSERT INTO `msds_ecological` VALUES (4070, 4236, '对水生生物可能有毒性', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:41', '', NULL);
INSERT INTO `msds_ecological` VALUES (4071, 4237, '对水生生物有剧毒。LC50（96h，鱼类）：约1-10mg/L；EC50（48h，水蚤）：约0.5-5mg/L', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:41', '', NULL);
INSERT INTO `msds_ecological` VALUES (4072, 4238, '多硫化铵溶液对水生生物有剧毒。硫化氢对鱼类LC50（96小时）约0.01-0.1mg/L，对水蚤EC50（48小时）约0.1-1mg/L。氨气对鱼类LC50（96小时）约0.5-5mg/L，对水蚤EC50（48小时）约1-10mg/L。多硫化铵溶液在水中分解释放硫化氢和氨气，对水生生态系统造成严重危害。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:43', '', NULL);
INSERT INTO `msds_ecological` VALUES (4073, 4239, '对水生生物具有极高的毒性。LC50（鱼类，96小时）：0.01-0.1 mg/L（以TEF计）；EC50（水蚤，48小时）：0.01-0.1 mg/L；EC50（藻类，72小时）：0.1-1 mg/L。对陆生生物也具有高毒性。鸟类和哺乳动物长期暴露可导致繁殖能力下降、免疫系统抑制、胚胎死亡等。其毒性效应主要表现为：内分泌干扰、生殖毒性、发育毒性、免疫毒性。由于其极高的毒性，即使在极低的环境浓度下（ng/L级别）也可能对生态系统产生长期影响。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:43', '', NULL);
INSERT INTO `msds_ecological` VALUES (4074, 4240, '对水生生物毒性极大。鱼类LC50(96h)：0.01-0.1mg/L；水蚤EC50(48h)：0.001-0.01mg/L；藻类EC50(72h)：0.001-0.01mg/L；无脊椎动物LC50(48h)：0.005-0.05mg/L。对鸟类也有毒性，鸟类LD50：500-2000mg/kg。对土壤生物（如蚯蚓）有毒性。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:44', '', NULL);
