INSERT INTO `msds_ecological` VALUES (4116, 4282, '二甲苯异构体混合物对水生生物有毒性。对鱼类LC50（96h）：10-100mg/L；对甲壳类LC50（48h）：1-10mg/L；对藻类EC50（72h）：10-100mg/L。对鸟类、哺乳动物等陆生生物也有毒性作用。对水生生物可能有害，应避免进入水体、土壤和地下水。对水体应给予特别注意。挥发后可参与形成光化学烟雾。对水生物有毒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:03', '', NULL);
