INSERT INTO `msds_ecological` VALUES (4252, 4418, '氟离子对水生生物有急性毒性，氟离子浓度越高，急性毒性越强。氟离子急性毒性的大小与水生生物种类、发育阶段、水温、水质条件等因素有关。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:11', '', NULL);
