INSERT INTO `msds_ecological` VALUES (4302, 4468, '对水生生物有毒性。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:31', '', NULL);
INSERT INTO `msds_ecological` VALUES (4303, 4469, '对水生生物有毒性。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:31', '', NULL);
INSERT INTO `msds_ecological` VALUES (4304, 4470, '高碘酸为强氧化剂，对水生生物可能有害。应避免进入水体、土壤和地下水。高碘酸在水中可能释放碘离子，对水生生态系统造成影响。对鱼类和其他水生生物可能有害。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:31', '', NULL);
INSERT INTO `msds_ecological` VALUES (4305, 4471, '高碘酸钡为强氧化剂和高毒物质，对水生生物具有高毒性。应避免进入水体、土壤和地下水。钡离子对水生生态系统有严重危害，可能导致鱼类和其他水生生物死亡。对土壤和地下水可能造成长期污染。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:31', '', NULL);
INSERT INTO `msds_ecological` VALUES (4306, 4472, '高碘酸钠为强氧化剂，对水生生物可能有害。应避免进入水体、土壤和地下水。高碘酸钠在水中可能释放碘离子，对水生生态系统造成影响。对鱼类和其他水生生物可能有害。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:32', '', NULL);
INSERT INTO `msds_ecological` VALUES (4307, 4473, '高氯酸钙为强氧化剂，对水生生物可能有害。应避免进入水体、土壤和地下水。高氯酸钙在水中可能释放氯离子，对水生生态系统造成影响。对鱼类和其他水生生物可能有害。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:34', '', NULL);
INSERT INTO `msds_ecological` VALUES (4308, 4474, '高氯酸锂为强氧化剂，对水生生物可能有害。应避免进入水体、土壤和地下水。高氯酸锂在水中可能释放氯离子和锂离子，对水生生态系统造成影响。对鱼类和其他水生生物可能有害。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:34', '', NULL);
INSERT INTO `msds_ecological` VALUES (4309, 4475, '高氯酸镁为强氧化剂，对水生生物可能有害。应避免进入水体、土壤和地下水。高氯酸镁在水中可能释放氯离子和镁离子，对水生生态系统造成影响。对鱼类和其他水生生物可能有害。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:34', '', NULL);
INSERT INTO `msds_ecological` VALUES (4310, 4476, '高氯酸钠为强氧化剂，对水生生物可能有害。应避免进入水体、土壤和地下水。高氯酸钠在水中可能释放氯离子，对水生生态系统造成影响。对鱼类和其他水生生物可能有害。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:34', '', NULL);
INSERT INTO `msds_ecological` VALUES (4311, 4477, '高氯酸铅为强氧化剂和高毒物质，对水生生物具有高毒性。应避免进入水体、土壤和地下水。铅离子对水生生态系统有严重危害，可能导致鱼类和其他水生生物死亡。对土壤和地下水可能造成长期污染。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:36', '', NULL);
INSERT INTO `msds_ecological` VALUES (4312, 4478, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:36', '', NULL);
INSERT INTO `msds_ecological` VALUES (4313, 4479, '高锰酸钡为强氧化剂和剧毒物质，对水生生物具有高毒性。应避免进入水体、土壤和地下水。钡离子对水生生态系统有严重危害，可能导致鱼类和其他水生生物死亡。对土壤和地下水可能造成长期污染。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:36', '', NULL);
INSERT INTO `msds_ecological` VALUES (4314, 4480, '对水生生物有害。LC50(96h)范围：10-50mg/L（基于高锰酸钾数据估算）。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:37', '', NULL);
INSERT INTO `msds_ecological` VALUES (4315, 4481, '高锰酸钾为强氧化剂，对水生生物可能有害。应避免进入水体、土壤和地下水。高锰酸钾在水中会分解产生二氧化锰沉淀，可能对水生生态系统造成影响。对鱼类和其他水生生物可能有害。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:37', '', NULL);
