INSERT INTO `msds_ecological` VALUES (4635, 4803, '对水生生物有毒性。对鱼类和水生生物具有急性毒性。可能对水生生态系统造成长期不良影响。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:02', '', NULL);
INSERT INTO `msds_ecological` VALUES (4636, 4804, '对水生生物有毒性。鱼类LC50（96小时）：约10-50 mg/L；水蚤EC50（48小时）：约5-20 mg/L；藻类EC50（72小时）：约20-100 mg/L。对水生环境有长期不利影响。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:04', '', NULL);
INSERT INTO `msds_ecological` VALUES (4637, 4805, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:04', '', NULL);
