INSERT INTO `msds_ecological` VALUES (4639, 4807, '对水生生物有毒性。钡离子对水生生物有害。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:05', '', NULL);
INSERT INTO `msds_ecological` VALUES (4640, 4808, '对水生生物有剧毒。该物质对环境有危害，应特别注意对水体的污染。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:05', '', NULL);
INSERT INTO `msds_ecological` VALUES (4641, 4809, '对环境有害。对水生生物有毒性。氟离子和磷酸根离子对水生生态系统有潜在危害。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:06', '', NULL);
INSERT INTO `msds_ecological` VALUES (4642, 4810, '对水生生物有毒性。可能对水生环境造成长期不良影响。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:06', '', NULL);
INSERT INTO `msds_ecological` VALUES (4643, 4811, '对水生生物有极高毒性。鱼类LC50（96h）：0.1-1mg/L；水蚤EC50（48h）：0.5mg/L。对陆生生物也有毒性。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:06', '', NULL);
INSERT INTO `msds_ecological` VALUES (4644, 4812, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:06', '', NULL);
INSERT INTO `msds_ecological` VALUES (4645, 4813, '对水生生物有极高毒性。鱼类LC50（96h）：0.1-1mg/L；水蚤EC50（48h）：0.5mg/L。对陆生生物也有毒性。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:07', '', NULL);
INSERT INTO `msds_ecological` VALUES (4646, 4814, '六氟化铀对生态系统具有严重的毒性和放射性危害。急性生态毒性：鱼类LC50（96小时）：0.01-0.1 mg/L；水生无脊椎动物EC50（48小时）：0.005-0.05 mg/L；藻类EC50（72小时）：0.001-0.01 mg/L；鸟类LD50（经口）：10-50 mg/kg；哺乳动物LD50（经口）：未测定（因遇水分解）。慢性生态毒性：长期低浓度暴露可导致水生生物生长迟缓、繁殖能力下降、免疫功能下降、畸形率增加。陆生生物长期接触可导致慢性中毒、癌症、生殖系统损害。六氟化铀遇水分解产生的氟化氢对水生生物具有剧毒性，可导致水生生物大量死亡。铀化合物可在生物体内蓄积，导致长期毒性效应。放射性危害：α辐射可损伤水生生物和陆生生物的DNA，导致基因突变、染色体畸变、癌症。β辐射和γ辐射可穿透生物体，损伤深层组织。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:07', '', NULL);
INSERT INTO `msds_ecological` VALUES (4647, 4815, '对水生生物的毒性较低。目前缺乏详细的生态毒性数据。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:07', '', NULL);
INSERT INTO `msds_ecological` VALUES (4648, 4816, '对水生生物有毒作用。鱼类LC50（96小时）：约1-10mg/L；水蚤EC50（48小时）：约0.5-5mg/L；藻类EC50（72小时）：约1-10mg/L。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:07', '', NULL);
