INSERT INTO `msds_ecological` VALUES (4762, 4930, 'LC50：440mg/L，96小时(蓝鳃太阳鱼)；LC50：560mg/L，96小时(黑头呆鱼)；LC50：210mg/L，48小时(水蚤)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:53', '', NULL);
