INSERT INTO `msds_ecological` VALUES (4764, 4932, '马来酸二丁酯对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。对鱼类和其他水生生物可能有害。急性毒性：对鱼类LC50约为10-100mg/L，对水蚤EC50约为10-100mg/L。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:55', '', NULL);
INSERT INTO `msds_ecological` VALUES (4765, 4933, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:55', '', NULL);
INSERT INTO `msds_ecological` VALUES (4766, 4934, 'LC50(96h): 约150 mg/L（基于结构相似化合物马来酸二乙酯数据估算）\n        EC50(48h): 约80 mg/L（基于结构相似化合物马来酸二乙酯数据估算）\n        EC50(72h): 约120 mg/L（基于结构相似化合物马来酸二乙酯数据估算）\n        对水生生物有害，应避免进入水体环境', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:55', '', NULL);
