INSERT INTO `msds_ecological` VALUES (4800, 4969, '该物质对环境有危害，应特别注意对水体的污染。偏磷酸遇水会迅速水解生成磷酸，降低水体pH值，对水生生物产生酸性危害。高浓度可导致水生生物死亡。对水生生物的急性毒性数据有限，但根据其强酸性和腐蚀性，推测对鱼类、水生无脊椎动物和藻类具有毒性。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:11', '', NULL);
INSERT INTO `msds_ecological` VALUES (4801, 4970, '对水生生物有剧毒。对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:11', '', NULL);
INSERT INTO `msds_ecological` VALUES (4802, 4971, '对水生生物有剧毒。LC50：0.46mg/L（96小时，蓝鳃太阳鱼）；0.33mg/L（48小时，水蚤）；0.1mg/L（72小时，藻类）。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:11', '', NULL);
