INSERT INTO `msds_ecological` VALUES (4836, 5005, '对水生生物有极高毒性。可能对水生环境造成长期不良影响。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:26', '', NULL);
INSERT INTO `msds_ecological` VALUES (4837, 5006, '对水生生物有极高毒性。可能对水生环境造成长期不良影响。汞及其化合物在环境中具有持久性和生物富集性。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:26', '', NULL);
INSERT INTO `msds_ecological` VALUES (4838, 5007, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:27', '', NULL);
INSERT INTO `msds_ecological` VALUES (4839, 5008, '该物质对水生生物有极高毒性。氰化物对水生生物具有剧毒作用，可能导致鱼类和水生生物大量死亡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:28', '', NULL);
INSERT INTO `msds_ecological` VALUES (4840, 5009, '对水生生物有极高毒性。可能对水生环境造成长期不良影响。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:28', '', NULL);
INSERT INTO `msds_ecological` VALUES (4841, 5010, '对水生生物有极高毒性。可能对水生环境造成长期不良影响。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:28', '', NULL);
INSERT INTO `msds_ecological` VALUES (4842, 5011, '对水生生物有极高毒性。氰化汞同时具有氰化物和汞的双重毒性，对水生生态系统造成严重危害。LC50：鱼类0.01-0.1mg/L，96小时；水蚤0.05mg/L，48小时；藻类0.02mg/L，96小时。汞离子在水中可转化为甲基汞，具有更强的生物毒性和生物富集性。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:28', '', NULL);
INSERT INTO `msds_ecological` VALUES (4843, 5012, '对水生生物有极高毒性。氰化汞钾同时具有氰化物和汞的双重毒性，对水生生态系统有严重危害。鱼类LC50(96h)极低，对水生生物有急性毒性。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:28', '', NULL);
INSERT INTO `msds_ecological` VALUES (4844, 5013, '对水生生物有剧毒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:30', '', NULL);
