INSERT INTO `msds_ecological` VALUES (4855, 5024, '对水生生物极毒。鱼类LC50（96h）约0.1-1mg/L。水蚤EC50（48h）约0.05-0.5mg/L。藻类EC50（72h）约0.1-1mg/L。对陆生生物也有毒性。对蜜蜂有毒。对土壤微生物有抑制作用。该物质在环境中可能对水生生态系统造成长期危害。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:33', '', NULL);
INSERT INTO `msds_ecological` VALUES (4856, 5025, '对水生生物有极高毒性。鱼类LC50（96小时）：0.1-1 mg/L；水蚤EC50（48小时）：0.05-0.5 mg/L；藻类EC50（72小时）：0.1-1 mg/L。氰化物对水生生态系统有严重危害，可能导致鱼类和其他水生生物大量死亡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:35', '', NULL);
