INSERT INTO `msds_ecological` VALUES (4858, 5027, '对水生生物有极高毒性。鱼类LC50（96h）：0.1-0.5mg/L（以CN计）。水蚤EC50（48h）：0.2-0.8mg/L（以CN计）。藻类EC50（72h）：0.5-2.0mg/L（以CN计）。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:35', '', NULL);
