INSERT INTO `msds_ecological` VALUES (4866, 5035, '对水生生物有毒性。氰基化合物对鱼类、水生无脊椎动物和藻类具有毒性作用。该物质在水中可能对水生生态系统造成危害。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:39', '', NULL);
INSERT INTO `msds_ecological` VALUES (4867, 5036, '对水生生物有极高毒性。鱼类LC50（96小时）：0.1-1 mg/L。水蚤EC50（48小时）：0.1-1 mg/L。藻类EC50（72小时）：0.01-0.1 mg/L。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:39', '', NULL);
INSERT INTO `msds_ecological` VALUES (4868, 5037, '对水生生物毒性极大。鱼类LC50（96小时）：0.1-10 mg/L；水蚤EC50（48小时）：0.1-1 mg/L；藻类EC50（72小时）：0.01-0.1 mg/L。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:39', '', NULL);
INSERT INTO `msds_ecological` VALUES (4869, 5038, '对水生生物有极高毒性。鱼类LC50（96小时）：无资料（参考PFOS类化合物，鱼类LC50约为3-10 mg/L）；水蚤EC50（48小时）：无资料（参考PFOS类化合物，水蚤EC50约为5-20 mg/L）；藻类EC50（72小时）：无资料（参考PFOS类化合物，藻类EC50约为10-50 mg/L）。PFOS及其衍生物对水生生态系统具有长期危害。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:40', '', NULL);
