INSERT INTO `msds_ecological` VALUES (4958, 5127, '三氯化磷对水生生物有毒性。对鱼类LC50（96h）：1-10mg/L；对甲壳类LC50（48h）：0.1-1mg/L；对藻类EC50（72h）：1-10mg/L。对鸟类、哺乳动物等陆生生物也有毒性作用。对水生生物可能有害，应避免进入水体、土壤和地下水。应特别注意对水体的污染。遇水猛烈分解，生成氯化氢、氧化磷、磷烷，这些产物对水生生物也有毒性。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:17', '', NULL);
