INSERT INTO `msds_ecological` VALUES (5070, 5239, '生态毒性：对水生生物有毒性。LC50（鱼类，96小时）：1-10mg/L。EC50（水蚤，48小时）：1-10mg/L。EC50（藻类，72小时）：1-10mg/L。属于对水生生物有毒的物质。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:08', '', NULL);
INSERT INTO `msds_ecological` VALUES (5071, 5240, '对水生生物有害。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:10', '', NULL);
INSERT INTO `msds_ecological` VALUES (5072, 5241, '对水生生物有毒性。鱼类LC50：约10-100 mg/L (96h)；水蚤EC50：约10-50 mg/L (48h)；藻类EC50：约5-20 mg/L (72h)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:10', '', NULL);
INSERT INTO `msds_ecological` VALUES (5073, 5242, '对水生生物有毒性。在水中溶解度较低，可能对水生环境造成危害。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:11', '', NULL);
INSERT INTO `msds_ecological` VALUES (5074, 5243, '1. 鱼类毒性：LC50：约10-50 mg/L（96小时，鱼类）2. 水生无脊椎动物毒性：EC50：约5-20 mg/L（48小时，水蚤）3. 藻类毒性：EC50：约1-10 mg/L（72小时，藻类）4. 对水生生物有毒，可能对水生环境造成长期不利影响', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:11', '', NULL);
