INSERT INTO `msds_ecological` VALUES (5107, 5276, '对水生生物有极高毒性。LC50(96h)鱼类：约1-10mg/L。对水蚤、藻类等水生生物也有高毒性。氟化物可导致水体酸化，影响水生生态系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:24', '', NULL);
INSERT INTO `msds_ecological` VALUES (5108, 5277, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:24', '', NULL);
INSERT INTO `msds_ecological` VALUES (5109, 5278, '对水生生物毒性极高。对鱼类LC50（96小时）约为0.1-1mg/L。对水生无脊椎动物LC50（48小时）约为0.05-0.5mg/L。对藻类EC50（72小时）约为0.01-0.1mg/L。对陆生生物也有毒性，可导致土壤污染，影响植物生长和土壤微生物群落。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:25', '', NULL);
INSERT INTO `msds_ecological` VALUES (5110, 5279, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:26', '', NULL);
