INSERT INTO `msds_ecological` VALUES (5112, 5281, '对水生生物毒性极高。重氮化合物和氟化物对鱼类、水生无脊椎动物和藻类具有高毒性。具体数据：对鱼类LC50（96小时）可能小于1mg/L。对水生无脊椎动物LC50（48小时）可能小于0.5mg/L。对藻类EC50（72小时）可能小于0.1mg/L。对陆生生物也有毒性，可导致土壤污染，影响植物生长和土壤微生物群落。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:26', '', NULL);
INSERT INTO `msds_ecological` VALUES (5113, 5282, '对水生生物有毒性。鱼类LC50：无充分数据。水蚤EC50：无充分数据。藻类EC50：无充分数据。对陆生生物的毒性数据有限。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:26', '', NULL);
