INSERT INTO `msds_ecological` VALUES (5693, 5865, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:34', '', NULL);
INSERT INTO `msds_ecological` VALUES (5694, 5866, '对水生生物可能有毒性', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:34', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (2864, 3021, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，应该佩戴防毒面具。紧急事态抢救或逃生时，建议佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿相应的防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:29:27', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (2865, 3022, NULL, '无资料（建议参考类似农药标准：5mg/m³）', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。', '生产操作或农业使用时，佩戴防毒口罩。空气中浓度超标时，建议佩戴防毒面具。', '高浓度环境中，戴化学安全防护眼镜。', '穿工作服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:29:27', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (2866, 3023, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '生产操作或农业使用时，建议佩戴自吸过滤式防毒面具（全面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '呼吸系统防护中已作防护。', '穿聚乙烯防毒服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:29:28', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (2867, 3024, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风或全面排风。', '作业工人建议佩戴防毒面具。紧急事态抢救或逃生时，佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿相应的防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:29:28', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (2868, 3025, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，必须佩戴自吸过滤式防毒面具（全面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:29:28', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (2869, 3026, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。', '生产操作或农业使用时，建议佩戴防毒口罩。紧急事态抢救或撤离时，佩带自给式呼吸器。', '一般不需特殊防护，但建议特殊情况下，戴化学安全防护眼镜。', '穿聚乙烯薄膜防毒服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:29:28', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (2870, 3027, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '生产操作或农业使用时，应该佩戴防毒口罩。紧急事态抢救或逃生时，佩戴自给式呼吸器。', '戴安全防护眼镜。', '穿相应的防护服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:29:29', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (2871, 3028, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。尽可能机械化、自动化。', '可能接触其蒸气时，必须佩带防毒面具。紧急事态抢救或逃生时，建议佩带自给式呼吸器。', '戴化学安全防护眼镜。', '穿工作服(防腐材料制作)。', '戴橡皮手套。', NULL, NULL, NULL, '2026-03-06 14:29:30', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (2872, 3029, NULL, '无资料（建议参考《工作场所有害因素职业接触限值》GBZ 2.1-2019，有机过氧化物混合物）', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。提供安全淋浴和洗眼设备。使用防爆型通风系统和设备。', '空气中浓度超标时，佩戴自吸过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:29:30', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (2873, 3030, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。提供安全淋浴和洗眼设备。使用防爆型通风系统和设备。', '空气中浓度超标时，佩戴自吸过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:29:30', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (2874, 3031, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。', '一般条件下无需特殊防护；当浓度超标或在抢险救援时，佩戴自吸过滤式防毒面具（全面罩）或自给式空气呼吸器。', '必要时，戴化学安全防护眼镜。', '穿防静电工作服。', '戴一般作业防护手套。', NULL, NULL, NULL, '2026-03-06 14:29:30', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (2875, 3032, NULL, '0.3', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。', '生产操作或农业使用时，必须佩戴防毒口罩。紧急事态抢救或逃生时，应该佩戴自给式呼', '戴化学安全防护眼镜。', '穿相应的防护服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:29:31', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (2876, 3033, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。', '空气中浓度较高时，佩带防毒面具。', '必要时戴化学安全防护眼镜。', '穿工作服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:29:31', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (2877, 3034, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，必须佩戴自吸过滤式防毒面具（全面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN374、美国USF739或相当标准认证的手套。', NULL, NULL, NULL, '2026-03-06 14:29:32', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (2878, 3035, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风和全面通风。', '空气中浓度超标时，佩戴直接式防毒面具（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '戴安全防护眼镜。', '穿防毒物渗透工作服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:29:32', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (2879, 3036, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。', '空气中浓度超标时佩戴自吸过滤式防毒面具（全面罩），紧急抢险或浓度未知时佩戴自给式呼吸器。', '戴安全防护眼镜。', '穿相应的防护服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:29:32', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (2880, 3037, NULL, '未制定标准（基于结构相似硫醇类化合物类比，建议时间加权平均浓度≤2 mg/m³）', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。提供安全淋浴和洗眼设备。使用防爆型通风系统和设备。', '正压全面罩呼吸器辅之以辅助自携式正压呼吸器。逃生：装有机蒸气滤毒盒的空气净化式呼吸器。空气中浓度超标时，佩戴自吸过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿防静电工作服。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:29:32', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (2881, 3038, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。提供安全淋浴和洗眼设备。使用防爆型通风系统和设备。', '空气中浓度超标时，佩戴自吸过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟 EN 166 或美国 NIOSH 标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:29:33', '', NULL);
