INSERT INTO `msds_exposure_control` VALUES (2883, 3040, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '可能接触其蒸气时佩戴防毒口罩或过滤式全面罩；紧急抢险或浓度未知时佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿相应的防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:29:34', '', NULL);
