INSERT INTO `msds_exposure_control` VALUES (2922, 3080, NULL, '100mg/m3', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供局部排风与整体通风，设置防爆通风系统。', '空气中浓度超标时佩戴自吸过滤式防毒面具，在抢险或高浓度时佩戴自给式呼吸器。', '佩戴化学安全防护眼镜。', '穿防静电、防溶剂工作服。', '戴耐油耐溶剂手套。', NULL, NULL, NULL, '2026-03-06 14:29:47', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (2923, 3081, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。', '作业工人应戴口罩。高浓度接触时，应该佩戴防毒面具。', '戴安全防护眼镜。', '穿防静电工作服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:29:47', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (2924, 3082, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '提供良好的自然通风条件。', '一般不需要特殊防护，高浓度接触时可佩戴自吸过滤式防毒面具（半面罩）。', '必要时，戴化学安全防护眼镜。', '穿防静电工作服，避免皮肤直接接触。工作场所应配备紧急洗眼器和安全淋浴装置。', '戴橡胶耐油手套，建议使用丁腈橡胶或氯丁橡胶材质的手套。手套应定期检查，发现破损应及时更换。', NULL, NULL, NULL, '2026-03-06 14:29:47', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (2925, 3083, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。提供安全淋浴和洗眼设备。', '高浓度蒸气接触可佩戴过滤式防毒面具（半面罩）。', '一般不需要特殊防护，高浓度接触时可戴化学安全防护眼镜。', '穿防静电工作服。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:29:48', '', NULL);
