INSERT INTO `msds_exposure_control` VALUES (3032, 3198, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '可能接触其蒸气时，佩戴防毒口罩。紧急事态抢救或逃生时，佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿防静电工作服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:30:25', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3033, 3199, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。', '高浓度环境中，佩戴防毒面具。', '戴安全防护眼镜。', '穿工作服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:30:25', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3034, 3200, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '可能接触其蒸气时，应该佩戴防毒口罩。紧急事态抢救或逃生时，佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿相应的防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:30:25', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3035, 3201, NULL, '时间加权平均容许浓度(TWA): 50 ppm', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，全面通风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，佩戴过滤式防毒面具(半面罩)。紧急事态抢救或撤离时，应该佩戴自给式呼吸器。', '戴化学安全防护眼镜', '穿防静电工作服', '戴橡胶耐油手套', NULL, NULL, NULL, '2026-03-06 14:30:25', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3036, 3202, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '空气中浓度超过参考限值(10 ppm)时，佩戴过滤式防毒面具（半面罩，配有机蒸气滤毒盒）。紧急事态抢救或撤离时，应该佩戴自给式呼吸器或正压式空气呼吸器。', '戴化学安全防护眼镜或面罩，防止液体溅入眼睛。', '穿防静电工作服，避免皮肤接触。建议使用防渗透防护服，如丁基橡胶或氯丁橡胶材质。', '戴防渗透手套，推荐材质：丁基橡胶、氯丁橡胶或氟橡胶。手套厚度应≥0.5mm，使用前检查无破损。', NULL, NULL, NULL, '2026-03-06 14:30:26', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3037, 3203, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，应该佩戴自吸过滤式防毒面具（半面罩）。', '戴化学安全防护眼镜。', '穿防静电工作服。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:30:26', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3038, 3204, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，应该佩戴自吸过滤式防毒面具（半面罩）。', '一般不需要特殊防护，高浓度接触时可戴化学安全防护眼镜。', '穿防静电工作服。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:30:26', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3039, 3205, NULL, '1[皮]', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。', '空气中浓度超标时，应该佩带防毒面具。紧急事态抢救或逃生时，佩带自给式呼吸器。', '戴安全防护眼镜。', '穿相应的防护服。', '必要时戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:30:26', '', NULL);
