INSERT INTO `msds_exposure_control` VALUES (3053, 3219, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '可能接触其粉尘时，应该佩戴自吸过滤式防尘口罩。必要时，佩戴自给式呼吸器。', '戴安全防护眼镜。', '穿防毒物渗透工作服。', '戴一般作业防护手套。', NULL, NULL, NULL, '2026-03-06 14:30:33', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3054, 3220, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，应该佩戴自吸过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '必要时，戴化学安全防护眼镜。', '穿防静电工作服。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:30:33', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3055, 3221, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，应该佩戴自吸过滤式防毒面具（半面罩）。', '戴化学安全防护眼镜。', '穿防静电工作服。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:30:34', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3056, 3222, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。控制工作场所空气中粉尘浓度低于容许限值。设置应急淋浴和洗眼设备。使用防爆型通风系统和设备。提供安全淋浴和洗眼设备。', '空气中粉尘浓度超标时，佩戴自吸过滤式防毒面具（全面罩）。紧急事态抢救或撤离时，建议佩戴正压自给式空气呼吸器。', '戴化学安全防护眼镜或面罩，防止眼睛接触粉尘。', '穿防毒物渗透工作服，戴橡胶耐油手套。建议穿着防静电服和防静电鞋。', '戴橡胶耐油手套，建议使用丁腈橡胶手套或氯丁橡胶手套。手套厚度应不小于0.5mm。使用前检查手套完整性，使用后及时更换。', NULL, NULL, NULL, '2026-03-06 14:30:34', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3057, 3223, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭化，全面通风。提供安全淋浴和洗眼设备。设置局部排风装置和全面通风系统。使用防爆电气设备和防静电设施。设置泄漏报警装置和应急处理系统。', '空气中浓度超标时，佩戴过滤式防毒面具(半面罩)。紧急事态抢救或撤离时，建议佩戴自给式呼吸器(SCBA)。长期接触且浓度可能超标时，应使用全面罩呼吸防护器。', '戴化学安全防护眼镜，必要时佩戴面罩。提供安全淋浴和洗眼设备。', '穿防静电工作服，戴防化学品手套和防护鞋。避免皮肤直接接触。提供安全淋浴和洗眼设备。', '戴橡胶耐油手套，建议使用丁腈橡胶或氯丁橡胶材质的手套。手套应定期检查，确保无破损。接触后应彻底清洗双手。', NULL, NULL, NULL, '2026-03-06 14:30:34', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3058, 3224, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。', '紧急事态抢救或逃生时，佩戴防毒面具。', '高浓度环境中，戴化学安全防护眼镜。', '穿防静电工作服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:30:36', '', NULL);
