INSERT INTO `msds_exposure_control` VALUES (3167, 3339, NULL, '1mg/m³[皮]', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，必须佩戴自吸过滤式防尘口罩或防毒面具（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '戴安全防护眼镜。', '穿防毒物渗透工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:31:25', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3168, 3340, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风，尽可能机械化、自动化。', '可能接触其蒸气时，佩带防毒面具。紧急事态抢救或撤离时，应该佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿紧袖工作服，长筒胶鞋。', '戴橡皮胶手套。', NULL, NULL, NULL, '2026-03-06 14:31:25', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3169, 3341, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，注意通风。', NULL, '戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:31:25', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3170, 3342, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', NULL, NULL, NULL, NULL, '2026-03-06 14:31:25', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3171, 3343, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '作业工人佩戴防毒口罩。紧急事态抢救或逃生时，应该佩戴防毒面具。', '戴化学安全防护眼镜。', '穿相应的防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:31:27', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3172, 3344, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风和全面排风。', '作业工人应该佩戴防毒口罩。', '必要时戴安全防护眼镜。', '穿防静电工作服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:31:27', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3173, 3345, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。', '可能接触其蒸气时，佩戴防毒口罩。紧急事态抢救或逃生时，应该佩戴自给式呼吸器。', '空气中浓度较高时，戴化学安全防护眼镜。', '穿防静电工作服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:31:27', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3174, 3346, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '可能接触其蒸气时，应该佩带防毒面具。高浓度环境中，佩带自给式呼吸器。', '一般不需特殊防护，高浓度接触时可戴化学安全防护眼镜。', '穿相应的防护服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:31:27', '', NULL);
