INSERT INTO `msds_exposure_control` VALUES (3179, 3351, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '提供良好的自然通风条件。', '高浓度环境中，应该佩戴供气式头盔。', '必要时戴化学安全防护眼镜。', '穿防静电工作服。', '一般不需要特殊防护，高浓度接触时可戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:31:29', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3180, 3352, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', NULL, NULL, NULL, NULL, '2026-03-06 14:31:30', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3181, 3353, NULL, '0.5 mg/m³（有机过氧化物参考值）', NULL, NULL, NULL, NULL, NULL, NULL, '使用局部排风装置，控制空气中浓度低于职业接触限值。设置应急冲洗设备。', '当空气中浓度超过职业接触限值时，佩戴防毒面具（带有机蒸气滤盒）。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '佩戴防渗透的化学防护手套（如丁腈橡胶手套）。', NULL, NULL, NULL, '2026-03-06 14:31:30', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3182, 3354, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', NULL, NULL, NULL, NULL, '2026-03-06 14:31:30', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3183, 3355, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN374、美国USF739或', NULL, NULL, NULL, '2026-03-06 14:31:31', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3184, 3356, NULL, '0.5 mg/m³', NULL, NULL, NULL, NULL, NULL, NULL, '使用局部排风装置，控制蒸气浓度在安全范围内。设置应急冲洗设备和洗眼器。', '正压全面罩呼吸器辅之以辅助自携式正压呼吸器。逃生：装有机蒸气滤毒盒的空气净化式呼吸器。', '佩戴化学安全护目镜或面罩', '穿戴防静电工作服和防护围裙', '佩戴丁腈橡胶手套，建议厚度0.5mm以上', NULL, NULL, NULL, '2026-03-06 14:31:31', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3185, 3357, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', NULL, NULL, NULL, NULL, '2026-03-06 14:31:31', '', NULL);
