INSERT INTO `msds_exposure_control` VALUES (3210, 3384, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。提供安全淋浴和洗眼设备。', '空气中粉尘浓度超标时，必须佩戴自吸过滤式防尘口罩（全面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:31:44', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3211, 3386, NULL, '1[皮]', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。', '空气中浓度超标时，佩带防毒面具。紧急事态抢救或逃生时，应该佩带自给式呼吸器。', '戴安全防护眼镜。', '穿紧袖工作服，长统胶鞋。', '戴橡皮手套。', NULL, NULL, NULL, '2026-03-06 14:31:44', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3212, 3387, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '佩戴防尘口罩。紧急事态抢救或逃生时，建议佩戴防毒面具。', '必要时可采用安全面罩。', '穿防静电工作服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:31:45', '', NULL);
