INSERT INTO `msds_exposure_control` VALUES (3220, 3395, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，应该佩戴防毒口罩。紧急事态抢救或逃生时，建议佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿一般作业防护服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:31:47', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3221, 3396, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。', '空气中浓度较高时，佩带防毒面具。紧急事态抢救或逃生时，应该佩带自给式呼吸器。', '戴安全防护眼镜。', '穿紧袖工作服，长统胶鞋。', '戴橡皮手套。', NULL, NULL, NULL, '2026-03-06 14:31:47', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3222, 3397, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，注意通风。', '可能接触其蒸气时，佩带防毒面具。紧急事态抢救或逃生时，建议佩带自给式呼吸器。', '戴化学安全防护眼镜。', '穿工作服(防腐材料制作)。', '戴橡皮手套。', NULL, NULL, NULL, '2026-03-06 14:31:49', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3223, 3398, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，注意通风。提供安全淋浴和洗眼设备，设置局部排风装置，控制工作场所空气中浓度低于容许限值', '空气中浓度超过容许限值时，佩戴过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，佩戴自给式呼吸器', '戴化学安全防护眼镜，必要时佩戴面罩', '穿防腐工作服，戴防化学品手套和防护靴', '戴耐化学品手套（如丁腈橡胶手套），定期更换', NULL, NULL, NULL, '2026-03-06 14:31:49', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3224, 3399, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程应密闭操作，全面通风。设置必要的事故通风系统和紧急洗眼设备。使用防爆型通风系统和设备。工作场所严禁吸烟。储存区域应设置泄漏检测报警装置。操作人员必须经过专门培训，严格遵守操作规程。', '空气中浓度超标时，佩戴过滤式防毒面具（有机蒸气滤盒）。紧急事态抢救或撤离时，建议佩戴自给式呼吸器（SCBA）。呼吸防护器的选择应根据工作场所空气中2-苯基丙烯的浓度和暴露时间确定，确保防护因子足够。', '戴化学安全防护眼镜。', '穿防静电工作服。', '戴防化学品手套。也可使用皮肤防护膜。', NULL, NULL, NULL, '2026-03-06 14:31:49', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3225, 3400, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，佩戴自吸过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:31:49', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3226, 3401, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '高浓度环境中，应该佩带防毒面具。紧急事态抢救或逃生时，佩带自给式呼吸器。', '戴化学安全防护眼镜。', '穿相应的防护服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:31:49', '', NULL);
