INSERT INTO `msds_exposure_control` VALUES (3247, 3422, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。', '可能接触其蒸气时，应该佩带防毒面具。紧急事态抢救或逃生时，佩带自给式呼吸器。', '高浓度蒸气接触可戴化学安全防护眼镜。', '穿相应的防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:32:00', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3248, 3423, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。', '可能接触其蒸气时，应该佩带防毒面具。紧急事态抢救或逃生时，佩带自给式呼吸器。', '戴安全防护眼镜。', '穿相应的防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:32:00', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3249, 3424, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，佩戴自吸过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:32:00', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3250, 3425, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，佩戴自吸过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器或氧气呼吸器。', '戴化学安全防护眼镜。', '穿防静电工作服。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:32:02', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3251, 3426, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。', '空气中浓度较高时，佩带防毒面具。紧急事态抢救或撤离时，应该佩戴供气式呼吸器。', '一般不需要特殊防护，高浓度接触时可戴化学安全防护眼镜。', '穿防静电工作服。', '必要时戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:32:02', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3252, 3427, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。', '空气中浓度较高时，佩带防毒面具。紧急事态抢救或撤离时，应该佩戴供气式呼吸器。', '一般不需要特殊防护，高浓度接触时可戴化学安全防护眼镜。', '穿防静电工作服。', '必要时戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:32:02', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3253, 3428, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，全面通风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，必须佩戴过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴防化学品手套（丁基橡胶、聚氯乙烯或氟橡胶材质）。', NULL, NULL, NULL, '2026-03-06 14:32:02', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3254, 3429, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，注意通风。', '可能接触其蒸气时，建议佩戴防毒口罩。高浓度环境中，应该佩戴自给式呼吸器。', '可能接触其蒸气时，戴化学安全防护眼镜。', '穿工作服。', '高浓度接触时，戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:32:03', '', NULL);
