INSERT INTO `msds_exposure_control` VALUES (3325, 3501, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风和全面通风。尽可能采取隔离操作。', '可能接触其蒸气时，应该佩戴自吸过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:32:34', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3326, 3502, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。提供安全淋浴和洗眼设备。', '高浓度环境中，应该佩戴自吸过滤式防毒面具（半面罩）。', '戴化学安全防护眼镜。', '穿防静电工作服。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:32:34', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3327, 3503, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。提供安全淋浴和洗眼设备。', '高浓度环境中，应该佩戴自吸过滤式防毒面具（半面罩）。', '戴化学安全防护眼镜。', '穿防静电工作服。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:32:35', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3328, 3504, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，注意通风。', '空气中浓度超标时，戴面具式呼吸器。紧急事态抢救或撤离时，佩带供气式呼吸器。', '戴化学安全防护眼镜。', '穿防静电工作服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:32:35', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3329, 3505, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，佩戴自吸过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴橡胶耐酸碱手套。', NULL, NULL, NULL, '2026-03-06 14:32:36', '', NULL);
