INSERT INTO `msds_exposure_control` VALUES (3384, 3560, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', NULL, NULL, NULL, NULL, '2026-03-06 14:32:59', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3385, 3561, NULL, '未制订标准前', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风和全面排风。', '可能接触其蒸气时，应该佩戴防毒面具。紧急事态抢救或撤离时，建议佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿防静电工作服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:32:59', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3386, 3562, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', NULL, NULL, NULL, NULL, '2026-03-06 14:32:59', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3387, 3563, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。', '生产操作或农业使用时，应该佩戴防毒口罩。紧急事态抢救或逃生时，佩戴防毒面具。', '戴安全防护眼镜。', '穿相应的防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:33:01', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3388, 3564, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。尽可能采用隔离式操作。', '空气中浓度超标时，必须佩戴防毒面具。紧急事态抢救或撤离时，建议佩戴正压自给式呼吸器。', '戴化学安全防护眼镜。', '穿防腐工作服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:33:01', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3389, 3565, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN374、美国USF739或AS/NZS', NULL, NULL, NULL, '2026-03-06 14:33:01', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3390, 3566, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭化，加强局部排风和全面通风。提供安全淋浴和洗眼设备。设置紧急切断装置和泄漏报警装置。采用防爆型电气设备和照明设施。工作场所应保持良好的通风条件，确保空气流通。', '空气中浓度超标时，佩戴过滤式防毒半面罩（全面罩）或自给式呼吸器。紧急事态抢救或撤离时，必须佩戴正压式空气呼吸器。呼吸器应符合NIOSH或同等标准要求。根据作业环境和暴露浓度选择合适的防护等级。', '佩戴化学安全防护眼镜（符合欧盟EN 166或美国NIOSH标准）。必要时佩戴面罩或全面罩，防止化学品溅入眼睛。', '穿阻燃防静电防护服（符合GB 8965.1标准）和抗静电的防护靴。避免皮肤直接接触。工作服应定期清洗和更换。', '戴防化学品手套（如丁基橡胶手套、氯丁橡胶手套或聚乙烯醇手套）。手套应定期检查和更换，发现破损立即更换。手套使用前应检查气密性。', NULL, NULL, NULL, '2026-03-06 14:33:01', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3391, 3567, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风和全面通风。尽可能将操作场所隔离。', '空气中浓度超标时，佩戴过滤式防毒面具（半面罩）或自给式呼吸器。', '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴防化手套（如丁基橡胶手套、氯丁橡胶手套）。', NULL, NULL, NULL, '2026-03-06 14:33:01', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3392, 3568, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '采用密闭操作，提供充分的局部排风。提供安全淋浴和洗眼设备', '佩戴防毒口罩（符合GB 2626-2006标准）或自吸过滤式防毒面具', '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴耐化学品的防护手套（如丁基橡胶手套、聚氯乙烯手套）', NULL, NULL, NULL, '2026-03-06 14:33:03', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3393, 3569, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风和全面通风。尽可能机械化、自动化。提供安全淋浴和洗眼设备。', '空气中粉尘浓度超标时，必须佩戴自吸过滤式防尘口罩（半面罩）或全面罩。紧急事态抢救或逃生时，建议佩戴空气呼吸器。', '戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:33:03', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3394, 3570, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。尽可能机械化、自动化。提供安全淋浴和洗眼设备。', '空气中粉尘浓度超标时，佩戴自吸过滤式防尘口罩（全面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:33:03', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3395, 3571, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。提供安全淋浴和洗眼设备。', '如果蒸气浓度超过职业接触限值或发生刺激等症状时，请使用全面罩式多功能防毒面具', '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴防化学品手套（推荐使用丁基橡胶或聚乙烯醇手套）。', NULL, NULL, NULL, '2026-03-06 14:33:03', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3396, 3572, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '采用密闭操作，局部排风。提供安全淋浴和洗眼设备。确保工作场所有充分的通风。', '当空气中浓度超标时，佩戴过滤式防毒面具（半面罩）或自给式呼吸器。紧急事态抢救或撤离时，佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴防化学品手套（推荐使用丁基橡胶或氯丁橡胶手套）。', NULL, NULL, NULL, '2026-03-06 14:33:05', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3397, 3573, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风和全面通风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，必须佩戴过滤式防毒面具（全面罩）。紧急事态抢救或撤离时，建议佩戴自给式呼吸器。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴防化学品手套（丁腈橡胶或氯丁橡胶材质）。', NULL, NULL, NULL, '2026-03-06 14:33:05', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3398, 3574, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。', '可能接触其蒸气时，应该佩戴防毒口罩。紧急事态抢救或逃生时，佩戴自给式呼吸器。', '戴安全防护眼镜。', '穿相应的防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:33:06', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3399, 3575, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。', '空气中浓度超标时，必须佩戴自吸过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器或氧气呼吸器。', '戴化学安全防护眼镜。', '穿防腐工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:33:06', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3400, 3576, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，必须佩戴自吸过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:33:06', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3401, 3577, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，佩戴过滤式防毒面具（半面罩）或自给式呼吸器。紧急事态抢救或撤离时，建议佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴防化学品手套（如丁基橡胶手套、聚乙烯醇手套）。', NULL, NULL, NULL, '2026-03-06 14:33:08', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3402, 3578, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，全面通风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，佩戴过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴防化学品手套（丁基橡胶、聚乙烯醇或丁腈橡胶材质）。', NULL, NULL, NULL, '2026-03-06 14:33:08', '', NULL);
