INSERT INTO `msds_exposure_control` VALUES (3435, 3611, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风和全面通风。尽可能将操作场所隔离。', '空气中粉尘浓度超标时，佩戴过滤式防尘呼吸器（半面罩）。紧急事态抢救或撤离时，佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴防化学品手套（丁基橡胶或丁腈橡胶手套）。', NULL, NULL, NULL, '2026-03-06 14:33:22', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3436, 3612, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '佩戴防尘口罩。高浓度环境中，应该佩戴防毒面具。', '高浓度环境中，戴安全防护眼镜。', '穿工作服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:33:22', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3437, 3613, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，佩戴过滤式防毒面具（半面罩）或自给式呼吸器。紧急事态抢救或撤离时，佩戴空气呼吸器。', '戴化学安全防护眼镜。', '穿防静电工作服。尽可能减少直接接触。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:33:22', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3438, 3614, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '空气中浓度较高时，佩戴防毒口罩。', '戴安全防护眼镜。', '穿紧袖工作服，长筒胶鞋。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:33:22', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3439, 3615, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。', '可能接触毒物时，必须佩戴防毒面具。紧急事态抢救或撤离时，建议佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿防静电工作服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:33:22', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3440, 3616, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风和全面排风。', '可能接触其蒸气时，必须佩戴防毒面具。高浓度环境中，应该佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿聚乙烯薄膜防毒服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:33:24', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3441, 3617, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。', '可能接触其蒸气时，佩戴自吸过滤式防毒面具（全面罩）。', '呼吸系统防护中已作防护。', '穿聚乙烯防毒服。', '戴橡胶耐油手套或丁基橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:33:25', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3442, 3618, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风和全面排风。尽可能机械化、自动化。', '可能接触毒物时，佩带供气式防毒面具。紧急事态抢救或逃生时，应该佩带正压自给式呼吸器。', '戴化学安全防护眼镜。', '穿相应的防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:33:25', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3443, 3619, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '生产操作或农业使用时，佩戴防尘口罩。', '空气中浓度较高时，戴化学安全防护眼镜。', '穿工作服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:33:26', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3444, 3620, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风和全面通风。尽可能机械化、自动化。提供安全淋浴和洗眼设备。', '可能接触其粉尘时，必须佩戴自吸过滤式防尘口罩（全面罩）或空气呼吸器。紧急情况下，戴压气式呼吸器、自吸式呼吸器、全面罩自携式呼吸器或自吸式送风呼吸器。', '戴化学安全防护眼镜', '穿防毒物渗透工作服', '戴橡胶手套', NULL, NULL, NULL, '2026-03-06 14:33:27', '', NULL);
