INSERT INTO `msds_exposure_control` VALUES (3472, 3648, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，注意通风。', '空气中浓度较高时，应该佩戴防毒面具。紧急事态抢救或撤离时，建议佩戴供气式呼吸器。', '戴化学安全防护目眼镜。', '穿防静电工作服。', '必要时戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:33:36', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3473, 3649, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '高浓度环境中，应该佩带防毒口罩。紧急事态抢救或逃生时，建议佩带自给式呼吸器。', '戴化学安全防护眼镜。', '穿相应的防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:33:38', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3474, 3650, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，全面排风。尽可能机械化、自动化。', '可能接触其蒸气时，应该佩戴防毒口罩。必要时建议佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:33:38', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3475, 3651, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，佩戴自吸过滤式防毒面具（半面罩）。', '一般不需要特殊防护，高浓度接触时可戴化学安全防护眼镜。', '穿防静电工作服。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:33:38', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3476, 3652, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。提供安全淋浴和洗眼设备。尽可能将工作场所与生活区分开。在可能产生蒸气或粉尘的区域设置局部排风系统。确保工作场所空气流通良好。', '空气中浓度超标时，佩戴自吸过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，建议佩戴空气呼吸器。存在过量接触风险时，可佩戴经MSHA/NIOSH批准的自给式呼吸器。', '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴橡胶耐油手套。推荐使用丁腈橡胶手套，因其耐有机溶剂和酸碱性能较好。手套应定期检查和更换，确保防护效果。', NULL, NULL, NULL, '2026-03-06 14:33:38', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3477, 3653, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。', '可能接触其蒸气时，佩戴自吸过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，佩戴氧气呼吸器或空气呼吸器。', '戴安全防护眼镜。', '穿紧袖工作服，长统胶鞋。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:33:38', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3478, 3654, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，全面排风。', '可能接触其蒸气时，应该佩戴防毒口罩。必要时建议佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿防静电工作服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:33:40', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3479, 3655, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。', '空气中浓度较高时，戴面具式呼吸器。紧急事态抢救或撤离时，佩带供气式呼吸器。', '戴化学安全防护眼镜。', '穿工作服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:33:40', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3480, 3656, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。尽可能机械化、自动化。', '可能接触其蒸气时，应该佩戴防毒口罩。紧急事态抢救或逃生时，佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿相应的防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:33:40', '', NULL);
