INSERT INTO `msds_exposure_control` VALUES (3524, 3701, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风和全面排风。尽可能采用隔离式操作。', '可能接触其蒸气时，必须佩戴防毒面具。紧急事态抢救或撤离时，建议佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿聚乙烯薄膜防毒服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:34:00', '', NULL);
