INSERT INTO `msds_exposure_control` VALUES (3528, 3705, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。', '高浓度环境中，应该佩戴防毒面具。', '戴安全防护眼镜。', '穿防静电工作服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:34:02', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3529, 3706, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '使用密闭系统，提供充分的局部排风或全面通风。确保工作场所的通风系统正常运行。在可能产生蒸气的地方安装局部排气装置。', '当空气中浓度超过职业接触限值时，或作业环境中存在高浓度蒸气时，应佩戴自吸过滤式防毒面具（半面罩）或全面罩。紧急救援或撤离时，应佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。如需要，佩戴面罩。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN374、美国USF739或AS/NZS 2161.2标准认证的手套。手套在使用前应检查是否有泄漏。使用后，按照当地法规处理。', NULL, NULL, NULL, '2026-03-06 14:34:02', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3530, 3707, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风和全面通风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，佩戴过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴防化学品手套（丁基橡胶手套或聚乙烯醇手套）。', NULL, NULL, NULL, '2026-03-06 14:34:02', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3531, 3708, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，注意通风。', '可能接触其蒸气时，建议佩戴防毒口罩。高浓度环境中，应该佩戴自给式呼吸器。', '可能接触其蒸气时，戴化学安全防护眼镜。', '穿防静电工作服。', '高浓度接触时，戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:34:03', '', NULL);
