INSERT INTO `msds_exposure_control` VALUES (3545, 3722, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。提供安全淋浴和洗眼设备。', '空气中粉尘浓度超标时，佩戴过滤式防尘呼吸器（半面罩）或自吸过滤式防尘口罩。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '佩戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:34:08', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3546, 3723, NULL, '0.5mg/m³(皮)', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。尽可能机械化、自动化。', '空气中浓度超标时，佩戴自吸过滤式防毒面具（半面罩）。紧急情况下，戴压气式呼吸器、自吸式呼吸器、全面罩自携式呼吸器或自吸式送风呼吸器。', '戴化学安全防护眼镜', '穿防毒物渗透工作服', '戴橡胶手套', NULL, NULL, NULL, '2026-03-06 14:34:09', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3547, 3724, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。尽可能实现机械化、自动化。提供安全淋浴和洗眼设备。', '空气中浓度超标时，佩戴过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，佩戴空气呼吸器或长管面具。', '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴防化学品手套（丁基橡胶、聚乙烯醇等材质）。', NULL, NULL, NULL, '2026-03-06 14:34:09', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3548, 3725, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。', '高浓度环境中，佩带防毒面具。紧急事态抢救或逃生时，应该佩带自给式呼吸器。', '戴化学安全防护眼镜。', '穿紧袖工作服，长统胶鞋。', '戴橡皮手套。', NULL, NULL, NULL, '2026-03-06 14:34:09', '', NULL);
