INSERT INTO `msds_exposure_control` VALUES (3630, 3807, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。', '空气中粉尘浓度超标时，佩戴自吸过滤式防尘口罩。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:34:42', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3631, 3808, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。', '空气中浓度较高时，佩带防毒面具。紧急事态抢救或逃生时，应该佩带自给式呼吸器。', '戴化学安全防护眼镜。', '穿紧袖工作服，长统胶鞋。', '戴橡皮手套。', NULL, NULL, NULL, '2026-03-06 14:34:42', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3632, 3809, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。提供安全淋浴和洗眼设备。', '空气中粉尘浓度超标时，佩戴自吸过滤式防尘口罩（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:34:43', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3633, 3810, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。提供安全淋浴和洗眼设备。', '空气中粉尘浓度超标时，必须佩戴头罩型电动送风过滤式防尘呼吸器。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '呼吸系统防护中已作防护。', '穿防毒物渗透工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:34:43', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3634, 3811, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，必须佩戴自吸过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器或氧气呼吸器。', '戴化学安全防护眼镜。', '穿防静电工作服。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:34:44', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3635, 3812, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。', '空气中浓度超标时，必须佩戴自吸过滤式防毒面具（全面罩）或隔离式呼吸器。', '呼吸系统防护中已作防护。', '穿胶布防毒衣。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:34:45', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3636, 3813, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '空气中浓度较高时，应该佩戴防毒面具。', '戴化学安全防护眼镜。', '穿防腐工作服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:34:45', '', NULL);
