INSERT INTO `msds_exposure_control` VALUES (3648, 3825, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '可能接触其蒸气时，应该佩戴防毒口罩。紧急事态抢救或逃生时，建议佩戴防毒面具。', '戴安全防护眼镜。', '穿防静电工作服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:34:48', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3649, 3826, NULL, '未制订标准前', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。', '空气中浓度较高时，佩带防毒面具。紧急事态抢救或撤离时，应该佩戴供气式呼吸器。', '一般不需要特殊防护，高浓度接触时可戴化学安全防护眼镜。', '穿防静电工作服。', '必要时戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:34:49', '', NULL);
