INSERT INTO `msds_exposure_control` VALUES (3651, 3828, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '可能接触其蒸气时，佩戴防毒口罩。紧急事态抢救或逃生时，建议佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿相应的防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:34:50', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3652, 3829, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，注意通风。', '一般不需要特殊防护，高浓度接触时可佩戴自吸过滤式防毒面具（半面罩）。', '空气中浓度较高时，佩戴化学安全防护眼镜。', '穿防静电工作服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:34:50', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3653, 3830, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。尽可能实现机械化、自动化。提供安全淋浴和洗眼设备。', '空气中浓度超标时，佩戴过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴丁基橡胶手套或防化学品渗透手套。使用前检查手套完整性，定期更换。', NULL, NULL, NULL, '2026-03-06 14:34:50', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3654, 3831, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。尽可能实现机械化、自动化操作。提供安全淋浴和洗眼设备。工作场所应设置应急通风系统。', '当空气中浓度超标时，佩戴过滤式防毒面具（半面罩）或全面罩呼吸器。紧急事态抢救或撤离时，佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN374、美国USF739或AS/NZS', NULL, NULL, NULL, '2026-03-06 14:34:51', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3655, 3832, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '无资料', '正压全面罩呼吸器辅助自携式正压呼吸器。逃生：装有机蒸气滤毒盒的空气净化式全面罩', '空气中浓度较高时，佩戴化学安全防护眼镜。', '穿防静电工作服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:34:51', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3656, 3833, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风或全面排风。尽可能机械化、自动化。', '生产操作或农业使用时，必须佩戴防毒口罩。空气中浓度较高时，应该佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿相应的防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:34:51', '', NULL);
