INSERT INTO `msds_exposure_control` VALUES (3662, 3839, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '佩戴防尘口罩。空气中浓度较高时，应该佩戴自给式呼吸器。', '可采用安全面罩。', '穿相应的防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:34:53', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3663, 3840, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭化，加强局部排风和全面通风。设置安全警示标识，配备应急处理设施。采用防爆型电气设备和通风系统。', '空气中粉尘浓度超标时，必须佩戴过滤式防尘呼吸器（半面罩）或自给式呼吸器。紧急事态抢救或撤离时，建议佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴防化学品手套（推荐使用丁基橡胶手套或聚乙烯醇手套）。', NULL, NULL, NULL, '2026-03-06 14:34:54', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3664, 3841, NULL, '5[皮]', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。提供安全淋浴和洗眼设备。', '空气中粉尘浓度超标时，佩戴过滤式防尘呼吸器（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '戴化学安全防护眼镜。', '穿胶布防毒衣。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:34:54', '', NULL);
