INSERT INTO `msds_exposure_control` VALUES (3682, 3859, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。', '空气中浓度超标时，佩戴自吸过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:35:02', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3683, 3860, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '作业工人应该佩戴防毒口罩。紧急事态抢救或逃生时，佩戴防毒面具。', '必要时戴安全防护眼镜。', '穿工作服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:35:02', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3684, 3861, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。尽可能机械化、自动化。提供安全淋浴和洗眼设备。', '佩戴自吸过滤式防毒面具（半面罩）', '戴化学安全防护眼镜。', '穿连衣式胶布防毒衣。', '戴氯丁橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:35:02', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3685, 3862, NULL, '无资料（建议向相关机构查询最新标准）', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。提供安全淋浴和洗眼设备。设置局部排风装置，控制空气中浓度低于职业接触限值。', '空气中浓度超标时，佩戴过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器或氧气呼吸器。选择符合GB/T 18664标准的呼吸防护设备。', '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN374、美国USF739或AS/NZS', NULL, NULL, NULL, '2026-03-06 14:35:02', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3686, 3863, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', NULL, NULL, NULL, NULL, '2026-03-06 14:35:04', '', NULL);
