INSERT INTO `msds_exposure_control` VALUES (3713, 3890, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。', '佩戴防毒口罩。紧急事态抢救或逃生时，佩戴自给式呼吸器。', '戴安全防护眼镜。', '穿防腐工作服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:35:14', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3714, 3891, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，注意通风。', '空气中浓度超标时，佩带防毒面具。紧急事态抢救或撤离时，建议佩戴供气式头盔。', '戴化学安全防护眼镜。', '穿防腐工作服。', '戴橡皮手套。', NULL, NULL, NULL, '2026-03-06 14:35:14', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3715, 3892, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', NULL, NULL, NULL, NULL, '2026-03-06 14:35:14', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3716, 3893, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。提供安全淋浴和洗眼设备。工作场所应设置通风设施，确保空气流通。操作区域应设置明显的警示标志。', '空气中粉尘浓度超标时，必须佩戴自吸过滤式防尘口罩（半面罩）或全面罩。紧急事态抢救或撤离时，应该佩戴空气呼吸器。建议使用符合GB2626-2019标准的防尘口罩。', '佩戴化学安全防护眼镜或护目镜（符合欧盟EN 166或美国NIOSH标准）。防止粉尘和化学品飞溅入眼。', '穿防毒物渗透工作服或防化学品防护服。佩戴防护手套，穿防化学品防护靴。避免皮肤直接接触。', '戴橡胶手套、丁腈手套或其他防化学品手套。手套应定期更换，破损时立即更换。建议使用符合GB 24540-2009标准的防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:35:14', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3717, 3894, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN374、美国USF739或AS/NZS', NULL, NULL, NULL, '2026-03-06 14:35:15', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3718, 3895, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '无资料', '式正压全面罩呼吸器辅之以辅助自携式正压呼吸器。逃生：装有机蒸气滤毒盒的空气净化', '无资料', '无资料', '无资料', NULL, NULL, NULL, '2026-03-06 14:35:15', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3719, 3896, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。提供安全淋浴和洗眼设备。', '空气中粉尘浓度超标时，应该佩戴自吸过滤式防尘口罩。紧急事态抢救或撤离时，建议佩戴空气呼吸器。', '戴安全防护眼镜。', '穿一般作业防护服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:35:16', '', NULL);
