INSERT INTO `msds_exposure_control` VALUES (3721, 3898, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。设置局部排风系统。', '可能接触其蒸气或粉尘时，必须佩戴防毒面具（半面罩）或防尘口罩。紧急事态抢救或撤离时，建议佩戴自给式呼吸器。', '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161标准认证的手套。', NULL, NULL, NULL, '2026-03-06 14:35:17', '', NULL);
