INSERT INTO `msds_exposure_control` VALUES (3739, 3916, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作、局部排风。', '空气中浓度超标时，应该佩带防毒口罩。紧急事态抢救或逃生时，佩带自给式呼吸器。', '戴化学安全防护眼镜。', '穿相应的防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:35:25', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3740, 3917, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。提供安全淋浴和洗眼设备。', NULL, '戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:35:25', '', NULL);
