INSERT INTO `msds_exposure_control` VALUES (3742, 3919, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', NULL, NULL, NULL, NULL, '2026-03-06 14:35:27', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3743, 3920, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '佩戴防尘口罩。高浓度环境中，应该佩戴防毒面具。', '可采用安全面罩。', '穿相应的防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:35:27', '', NULL);
