INSERT INTO `msds_exposure_control` VALUES (3747, 3924, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。尽可能机械化、自动化。', '生产操作或农业使用时，必须佩戴防毒口罩。必要时佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿相应的防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:35:29', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3748, 3925, NULL, '1', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。提供安全淋浴和洗眼设备。', '生产操作或农业使用时，建议佩戴头罩型电动送风过滤式防尘呼吸器。', '呼吸系统防护中已作防护。', '穿防毒物渗透工作服。', '戴氯丁橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:35:29', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3749, 3926, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风和全面通风。', NULL, '呼吸系统防护中已作防护。', '穿聚乙烯防毒服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:35:29', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3750, 3927, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '生产操作或农业使用时，建议佩戴防毒口罩。紧急事态抢救或撤离时，佩带自给式呼吸器。', '一般不需特殊防护，但建议特殊情况下，戴化学安全防护眼镜。', '穿聚乙烯薄膜防毒服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:35:30', '', NULL);
