INSERT INTO `msds_exposure_control` VALUES (3783, 3960, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。尽可能机械化、自动化。', '可能接触其蒸气时，应该佩带防毒面具。紧急事态抢救或逃生时，建议佩带自给式呼吸器。', '戴化学安全防护眼镜。', '穿相应的防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:35:45', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3784, 3961, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。尽可能机械化、自动化。', NULL, '戴化学安全防护眼镜。', '穿相应的防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:35:46', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3785, 3962, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '生产操作或农业使用时，建议佩戴防毒口罩。紧急事态抢救或撤离时，佩带自给式呼吸器。', '一般不需特殊防护，但建议特殊情况下，戴化学安全防护眼镜。', '穿聚乙烯薄膜防毒服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:35:46', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3786, 3963, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', NULL, NULL, NULL, NULL, '2026-03-06 14:35:47', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3787, 3964, NULL, '0.01[皮]', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。尽可能机械化、自动化。提供安全淋浴和洗眼设备。', NULL, '呼吸系统防护中已作防护。', '穿连衣式胶布防毒衣。', '戴氯丁橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:35:48', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3788, 3965, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风或全面排风。尽可能机械化、自动化。', '生产操作或农业使用时，佩戴防毒口罩。紧急事态抢救或逃生时，应该佩戴自给式呼吸器。', '可采用安全面罩。', '穿相应的防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:35:48', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3789, 3966, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', NULL, NULL, NULL, NULL, '2026-03-06 14:35:48', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3790, 3967, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。尽可能机械化、自动化。', NULL, '戴化学安全防护眼镜。', '穿相应的防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:35:48', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3791, 3968, NULL, '美国：0．18μg／1测定：选用适用测定水中农药中氮—磷含量的气相色谱仪分析', NULL, NULL, NULL, NULL, NULL, NULL, '无资料', '紧急情况下，戴压气式、自吸式、全面罩自携式呼吸器或自吸式送风呼吸器', '无资料', '穿全遮式防化服', '无资料', NULL, NULL, NULL, '2026-03-06 14:35:48', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3792, 3969, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭化，加强通风。提供安全淋浴和洗眼设备。设置局部排风装置，控制蒸气扩散。', '空气中浓度超标时，佩戴过滤式防毒面具（半面罩）或自给式呼吸器。紧急事态抢救或撤离时，建议佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS 2161标准认证的手套。', NULL, NULL, NULL, '2026-03-06 14:35:50', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3793, 3970, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。提供安全淋浴和洗眼设备。设置局部排风装置，控制蒸气扩散。安装报警装置，及时发现泄漏。', '空气中浓度超标时，佩戴过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，佩戴空气呼吸器或长管面具。', '戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:35:50', '', NULL);
