INSERT INTO `msds_exposure_control` VALUES (3960, 4137, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。提供安全淋浴和洗眼设备。', '可能接触其粉尘时，建议佩戴头罩型电动送风过滤式防尘呼吸器。', '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:36:55', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3961, 4138, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。提供安全淋浴和洗眼设备。', '高浓度环境中，应该佩戴直接式防毒面具（半面罩）。', '戴化学安全防护眼镜。', '穿防腐工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:36:55', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3962, 4139, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', NULL, NULL, NULL, NULL, '2026-03-06 14:36:57', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3963, 4140, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。', '空气中浓度超标时，应该佩戴防毒口罩。', '戴安全防护眼镜。', '穿工作服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:36:57', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3964, 4141, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风和全面通风。采用防爆型通风系统和设备。', '空气中浓度超标时，佩戴过滤式防毒面具（半面罩）或自给式呼吸器。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:36:58', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3965, 4142, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作。提供良好的自然通风条件。', '一般不需要特殊防护。当作业场所空气中氧气浓度低于18%时，必须佩戴空气呼吸器或长管面具。', '一般不需特殊防护。', '穿一般作业工作服。', '戴一般作业防护手套。', NULL, NULL, NULL, '2026-03-06 14:36:58', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3966, 4143, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。提供安全淋浴和洗眼设备。', '空气中粉尘浓度超标时，佩戴防尘口罩。紧急事态抢救或撤离时，建议佩戴空气呼吸器。', '戴化学安全防护眼镜。', '穿防静电工作服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:36:59', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3967, 4144, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。提供安全淋浴和洗眼设备。', '空气中粉尘浓度超标时，必须佩戴自吸过滤式防尘口罩（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '佩戴化学安全防护眼镜。', '穿防静电工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:37:00', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3968, 4145, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供良好的自然通风条件', '一般不需要特殊防护。当作业场所空气中氧气浓度低于18%时，必须佩戴空气呼吸器或长管面具', '一般不需特殊防护', '穿一般作业工作服', '戴一般作业防护手套', NULL, NULL, NULL, '2026-03-06 14:37:01', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3969, 4146, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '无资料', '紧急情况，应穿戴压气式、自吸式、全面罩自携式呼吸器或自吸式送风呼吸器', '无资料', '穿严实的防化服', '无资料', NULL, NULL, NULL, '2026-03-06 14:37:01', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3970, 4147, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '生产操作或农业使用时，建议佩戴防尘口罩。紧急事态抢救或逃生时，佩戴防毒面具。', '高浓度环境中，戴化学安全防护眼镜。', '穿紧袖工作服，长筒胶鞋。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:37:01', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3971, 4148, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。尽可能机械化、自动化。', '空气中粉尘浓度超标时，佩戴过滤式防尘呼吸器。紧急事态抢救或撤离时，佩戴空气呼吸器。', '戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:37:03', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3972, 4149, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。', '生产操作或农业使用时，佩戴防尘口罩。必要时佩戴防毒面具。', '必要时可采用安全面罩。', '穿紧袖工作服，长筒胶鞋。', '必要时戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:37:03', '', NULL);
