INSERT INTO `msds_exposure_control` VALUES (3997, 4174, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。提供安全淋浴和洗眼设备。', '可能接触其粉尘时，应该佩戴自吸过滤式防尘口罩。', '戴化学安全防护眼镜。', '穿胶布防毒衣。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:37:13', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3998, 4175, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。提供安全淋浴和洗眼设备。', '可能接触其粉尘时，必须佩戴头罩型电动送风过滤式防尘呼吸器。紧急事态抢救或撤离时，必', '呼吸系统防护中已作防护。', '穿防酸碱工作服。', '戴橡胶耐酸碱手套。', NULL, NULL, NULL, '2026-03-06 14:37:13', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (3999, 4176, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。', '可能接触其蒸气时，佩戴防毒口罩。紧急事态抢救或逃生时，应该佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿相应的防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:37:14', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4000, 4177, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。', NULL, '呼吸系统防护中已作防护。', '穿胶布防毒衣。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:37:14', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4001, 4178, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '作业工人应该佩戴防尘口罩。', '可采用安全面罩。', '穿防静电工作服。', '必要时戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:37:14', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4002, 4179, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。尽可能机械化、自动化。提供安全淋浴和洗眼设备。', '空气中粉尘浓度超标时，佩戴防尘面具（全面罩）。紧急事态抢救或逃生时，佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿胶布防毒衣。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:37:15', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4003, 4180, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。尽可能机械化、自动化。提供安全淋浴和洗眼设备。', '空气中浓度超标时，应该佩带防毒口罩。紧急事态抢救或逃生时，佩带自给式呼吸器。', '戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:37:15', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4004, 4181, NULL, '0.05mg/m³（尘），0.03mg/m³（烟）（按Pb计）', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。尽可能机械化、自动化。提供安全淋浴和洗眼设备。', '空气中粉尘浓度超标时，佩戴过滤式防尘呼吸器（半面罩）或自给式呼吸器。紧急事态抢救或撤离时，建议佩戴空气呼吸器。', '戴化学安全防护眼镜。', '穿防毒物渗透工作服，穿防静电工作服。', '戴防化学品手套（推荐材料：丁基橡胶、聚乙烯醇）。', NULL, NULL, NULL, '2026-03-06 14:37:16', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4005, 4182, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。', '高浓度接触时，应该佩戴防毒面具。', '戴化学安全防护眼镜。', '穿工作服。', '必要时戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:37:16', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4006, 4183, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。', '高浓度接触时，应该佩戴防毒面具。', '戴化学安全防护眼镜。', '穿工作服。', '必要时戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:37:18', '', NULL);
