INSERT INTO `msds_exposure_control` VALUES (4036, 4213, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。', '紧急情况，应穿戴压气式；自吸式、全面罩自携式呼吸器或自吸式送风呼吸器。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:37:29', '', NULL);
