INSERT INTO `msds_exposure_control` VALUES (4057, 4234, NULL, '5mg/m3[皮]', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，佩戴过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，建议佩戴自给式呼吸器。', '戴安全防护眼镜（符合欧盟EN 166或美国NIOSH标准）。', '穿防毒物渗透工作服。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:37:39', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4058, 4235, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '空气中粉尘浓度较高时，应该佩戴自吸过滤式防尘口罩。紧急事态抢救或撤离时，佩戴自', '戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:37:40', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4059, 4236, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。尽可能采用隔离式操作。提供安全淋浴和洗眼设备。', '可能接触毒物时，应该佩戴防毒面具。紧急事态抢救或撤离时，建议佩戴自给式呼吸器。', '戴化学安全防护眼镜（符合欧盟EN 166或美国NIOSH标准）。', '穿防腐工作服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:37:41', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4060, 4237, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。尽可能以机械化、自动化代替手工操作，减少直接接触。', '空气中浓度超标时，必须佩戴自吸过滤式防尘口罩（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器或氧气呼吸器。', '佩戴化学安全防护眼镜（符合欧盟EN 166或美国NIOSH标准）。', '穿防毒物渗透工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:37:41', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4061, 4238, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风和全面通风。尽可能将生产过程密闭化、自动化，减少操作人员直接接触。设置有效的通风系统，确保工作场所空气中多硫化铵溶液蒸汽和分解产物浓度低于职业接触限值。', '空气中浓度超标时，佩戴自吸过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，佩戴空气呼吸器或正压自给式呼吸器（SCBA）。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴橡胶耐油手套。建议使用丁基橡胶或丁腈橡胶手套，定期更换。', NULL, NULL, NULL, '2026-03-06 14:37:43', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4062, 4239, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭化，加强通风排气。提供安全淋浴和洗眼设备。设置局部排风装置和全面通风系统，确保工作场所空气中多氯联苯的浓度低于安全限值。采用负压操作，防止污染物扩散到其他区域。', '佩戴正压自给式呼吸器（SCBA）或符合NIOSH标准的防毒面具，配P100级滤毒盒。在紧急救援或高浓度暴露情况下，必须使用正压自给式呼吸器。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）或全面罩防毒面具。', '穿防毒物渗透工作服（符合GB 24539-2009标准）或防化服，穿抗静电的防护靴。', '戴防化学品手套（如丁基橡胶手套、氟化橡胶手套），建议双层佩戴。手套使用前应检查是否完好，使用后应妥善处理，不得重复使用。', NULL, NULL, NULL, '2026-03-06 14:37:43', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4063, 4240, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '使用密闭系统操作，确保生产设备密闭性良好。安装局部排风装置和全面通风系统，保持工作场所空气流通。设置应急通风系统，在泄漏时能够快速排除有害气体。工作场所应设置安全淋浴和洗眼设备。', '在通风不良或空气中浓度超过安全限值时，佩戴符合NIOSH标准的有机蒸气防毒面具或自给式呼吸器（SCBA）。在紧急情况或高浓度暴露环境下，必须使用正压式空气呼吸器。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '佩戴耐化学品的防护手套（如丁腈橡胶手套、聚氯乙烯手套或丁基橡胶手套）。手套应定期检查和更换，避免破损。建议佩戴双层手套以提供额外保护。', NULL, NULL, NULL, '2026-03-06 14:37:44', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4064, 4241, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '空气中粉尘浓度超标时，应该佩戴自吸过滤式防尘口罩。', '戴安全防护眼镜。', '穿防毒物渗透工作服。', '戴一般作业防护手套。', NULL, NULL, NULL, '2026-03-06 14:37:44', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4065, 4242, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', NULL, NULL, NULL, NULL, '2026-03-06 14:37:46', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4066, 4243, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', NULL, NULL, NULL, NULL, '2026-03-06 14:37:46', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4067, 4244, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '可能接触毒物时，佩戴防毒面具。紧急事态抢救或逃生时，应该佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿相应的防护服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:37:46', '', NULL);
