INSERT INTO `msds_exposure_control` VALUES (4163, 4340, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，注意通风。', '空气中浓度较高时，佩带防毒面具。紧急事态抢救或撤离时，建议佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿工作服。', '戴防化学品手套。也可使用皮肤防护膜。', NULL, NULL, NULL, '2026-03-06 14:38:31', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4164, 4341, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', NULL, NULL, NULL, NULL, '2026-03-06 14:38:32', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4165, 4342, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，注意通风。', '空气中浓度超标时，佩带防毒面具。紧急事态抢救或撤离时，建议佩戴供气式头盔。', '戴化学安全防护眼镜。', '穿防腐工作服。', '戴橡皮手套。', NULL, NULL, NULL, '2026-03-06 14:38:32', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4166, 4343, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风和全面排风。尽可能采用隔离式操作。', '可能接触其蒸气时，必须佩戴防毒面具。紧急事态抢救或撤离时，建议佩戴正压自给式呼吸器。', '戴化学安全防护眼镜。', '穿聚乙烯薄膜防毒服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:38:33', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4167, 4344, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。', '可能接触其蒸气时，必须佩戴防毒面具。紧急事态抢救或撤离时，建议佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿防腐工作服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:38:33', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4168, 4345, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。', '可能接触其蒸气时，佩带防毒口罩。高浓度环境中，佩带自给式呼吸器。', '必要时戴化学安全防护眼镜。', '穿相应的防护服。', '一般不需特殊防护，高浓度接触时可戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:38:33', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4169, 4346, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', NULL, NULL, NULL, NULL, '2026-03-06 14:38:33', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4170, 4347, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。提供安全淋浴和洗眼设备。', '空气中粉尘浓度超标时，佩戴自吸过滤式防尘口罩。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:38:36', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4171, 4348, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。', NULL, '戴化学安全防护眼镜。', '穿紧袖工作服，长筒胶鞋。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:38:39', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4172, 4349, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '可能接触其蒸气时，应该佩戴防毒口罩。紧急事态抢救或逃生时，建议佩戴防毒面具。', '空气中浓度较高时，戴化学安全防护眼镜。', '穿防静电工作服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:38:39', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4173, 4350, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风或全面排风。', '可能接触其蒸气时，佩戴防毒口罩。空气中浓度较高时，应该佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿相应的防护服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:38:41', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4174, 4351, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。提供安全淋浴和洗眼设备。', '空气中粉尘浓度超标时，佩戴过滤式防尘口罩（半面罩）或自吸过滤式防尘口罩。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:38:41', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4175, 4352, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', NULL, NULL, NULL, NULL, '2026-03-06 14:38:41', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4176, 4353, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风和全面通风。', '可能接触其粉尘时，必须佩戴自吸过滤式防尘口罩。', '戴化学安全防护眼镜。', '穿紧袖工作服，长筒胶鞋。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:38:41', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4177, 4354, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。', '高浓度环境中，应该佩带防毒面具。紧急事态抢救或逃生时，佩带自给式呼吸器。', '戴安全防护眼镜。', '穿相应的防护服。', '必要时戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:38:41', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4178, 4355, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。', '空气中浓度超标时，应选择佩戴自吸过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，', '戴安全防护眼镜。', '穿透气型防毒服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:38:43', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4179, 4356, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。', '可能接触其蒸气时，应该佩戴防毒面具。', '戴化学安全防护眼镜。', '穿化学防护服。', '必要时戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:38:43', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4180, 4357, NULL, '无资料（建议参考OSHA或ACGIH标准）', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风和全面通风。提供安全淋浴和洗眼设备。使用防爆型通风系统和设备。避免蒸气积聚到爆炸极限浓度。', '可能接触其蒸气时，应该佩戴自吸过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，建议佩戴空气呼吸器。防护面具应符合NIOSH或EN标准。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴橡胶耐油手套（如丁腈橡胶手套）。手套应定期检查，如有破损立即更换。防护手套应符合EN374或ASTM F739标准。', NULL, NULL, NULL, '2026-03-06 14:38:43', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4181, 4358, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。', '可能接触其粉尘时，建议佩戴自吸过滤式防尘口罩。', '戴化学安全防护眼镜。', '穿紧袖工作服，长筒胶鞋。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:38:43', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4182, 4359, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，注意通风。', NULL, '戴化学安全防护眼镜。', '穿工作服(防腐材料制作)。', '戴橡皮手套。', NULL, NULL, NULL, '2026-03-06 14:38:44', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4183, 4360, NULL, '5[NO2]', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风和全面通风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，佩戴自吸过滤式防毒面具（全面罩）。紧急事态抢救或撤离时，建议佩', '呼吸系统防护中已作防护。', '穿胶布防毒衣。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:38:45', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4184, 4361, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '可能接触其蒸气时，戴面具式呼吸器。紧急事态抢救或撤离时，建议佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿紧袖工作服，长筒胶鞋。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:38:45', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4185, 4362, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作。', '高浓度接触时，应该佩戴防毒口罩。', '戴安全防护眼镜。', '穿工作服。', '必要时戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:38:45', '', NULL);
