INSERT INTO `msds_exposure_control` VALUES (4187, 4364, NULL, '15', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风和全面通风。提供安全淋浴和洗眼设备。', NULL, '呼吸系统防护中已作防护。', '穿聚乙烯防毒服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:38:45', '', NULL);
