INSERT INTO `msds_exposure_control` VALUES (4247, 4425, NULL, '1mg(F)／m3', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。提供安全淋浴和洗眼设备。', '作业工人应该佩戴防尘口罩。空气中浓度较高时，建议佩戴防毒面具。', '戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:39:13', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4248, 4426, NULL, '1mg(F)／m3', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '可能接触其蒸气时，佩戴防毒口罩。必要时佩戴防毒面具。', '戴化学安全防护眼镜。', '穿相应的防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:39:13', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4249, 4427, NULL, 'lmg(F)／m3', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '可能接触毒物时，佩戴防毒口罩。高浓度环境中，建议佩戴防毒面具。', '戴化学安全防护眼镜。', '穿相应的防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:39:13', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4250, 4428, NULL, '1mg(F)／m3', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '佩戴防尘口罩。', '一般不需特殊防护。必要时可采用安全面罩。', '穿工作服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:39:15', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4251, 4429, NULL, '1mg(F)／m3', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。', '佩戴防毒口罩。紧急事态抢救或逃生时，佩戴自给式呼吸器。', '戴安全防护眼镜。', '穿相应的防护服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:39:15', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4252, 4430, NULL, '1[F]', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。', '空气中粉尘浓度超标时，建议佩戴自吸过滤式防尘口罩。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '戴安全防护眼镜。', '穿防腐工作服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:39:15', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4253, 4431, NULL, '0.01mg(Hg)/m3', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。', '作业工人应佩戴防尘口罩。必要时佩戴自给式呼吸器。', '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:39:15', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4254, 4432, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '可能接触其粉尘时，应该佩戴防尘口罩。紧急事态抢救或逃生时，建议佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿相应的防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:39:16', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4255, 4433, NULL, '1[F]', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。提供安全淋浴和洗眼设备。', '可能接触其粉尘时，应该佩戴头罩型电动送风过滤式防尘呼吸器。紧急事态抢救或撤离时，', '呼吸系统防护中已作防护。', '穿胶布防毒衣。', '戴乳胶手套。', NULL, NULL, NULL, '2026-03-06 14:39:17', '', NULL);
