INSERT INTO `msds_exposure_control` VALUES (4270, 4448, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，注意通风。尽可能机械化、自动化。提供安全淋浴和洗眼设备。', '空气中浓度超标时，必须佩戴自吸过滤式防毒面具（全面罩）或供气式呼吸器。紧急事态抢救或撤离时，应该佩戴空气呼吸器或氧气呼吸器。', '戴化学安全防护眼镜。', '穿橡胶耐酸碱服。', '戴橡胶耐酸碱手套。', NULL, NULL, NULL, '2026-03-06 14:39:23', '', NULL);
