INSERT INTO `msds_exposure_control` VALUES (4284, 4462, NULL, '1mg(F)／m3', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。提供安全淋浴和洗眼设备。', '可能接触毒物时，应该佩戴防毒面具。紧急事态抢救或撤离时，建议佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿连衣式胶布防毒衣。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:39:28', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4285, 4463, NULL, '1mg(F)／m3', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。尽可能机械化、自动化。', '空气中浓度较高时，佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿相应的防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:39:28', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4286, 4464, NULL, '1mg(F)／m3', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。尽可能机械化、自动化。', '可能接触其蒸气时，佩戴防毒面具。紧急事态抢救或逃生时，佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿防静电工作服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:39:28', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4287, 4465, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。', '空气中浓度较高时，应该佩戴防毒面具。紧急事态抢救或撤离时，建议佩戴供气式呼吸器。', '一般不需特殊防护。', '穿防静电工作服。', '一般不需特殊防护。', NULL, NULL, NULL, '2026-03-06 14:39:28', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4288, 4466, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。', '空气中浓度较高时，应该佩戴防毒面具。紧急事态抢救或撤离时，建议佩戴供气式呼吸器。', '一般不需特殊防护。', '穿防静电工作服。', '一般不需特殊防护。', NULL, NULL, NULL, '2026-03-06 14:39:30', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4289, 4467, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '可能接触其粉尘时，佩戴头罩型电动送风过滤式防尘呼吸器。', '呼吸系统防护中已作防护。', '穿胶布防毒衣。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:39:30', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4290, 4468, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '提供良好的自然通风条件。', '一般不需要特殊防护，高浓度接触时可佩戴自吸过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器或氧气呼吸器。', '戴化学安全防护眼镜。', '穿防静电工作服。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:39:31', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4291, 4469, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '提供良好的自然通风条件。', '一般不需要特殊防护，高浓度接触时可佩戴自吸过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器或氧气呼吸器。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:39:31', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4292, 4470, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。提供安全淋浴和洗眼设备。', '可能接触其粉尘时，建议佩戴头罩型电动送风过滤式防尘呼吸器。', '呼吸系统防护中已作防护。', '穿聚乙烯防毒服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:39:31', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4293, 4471, NULL, '无资料（建议参考钡化合物标准：Ba 1 mg/m³）', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。防止粉尘释放到车间空气中。提供安全淋浴和洗眼设备。工作场所应配备应急冲洗设备。', '空气中浓度超标时，必须佩戴过滤式防毒面具（全面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴橡胶耐油手套（符合EN 374标准）。', NULL, NULL, NULL, '2026-03-06 14:39:31', '', NULL);
