INSERT INTO `msds_exposure_control` VALUES (4313, 4491, NULL, '美国TWA：0．1mg／m3，ACGIH中国MAC：0．05mg／l(以Cr+6计)', NULL, NULL, NULL, NULL, NULL, NULL, '无资料', '选用适当呼吸器，对皮肤、眼睛、肺、呼吸系统及中枢神经系统进行定期检查', '无资料', '穿防护服，戴防护眼镜；配备应急淋浴设施和眼药水；每日下班前洗澡', '无资料', NULL, NULL, NULL, '2026-03-06 14:39:42', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4314, 4492, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风和全面排风。', '可能接触其蒸气时，必须佩戴防毒面具。紧急事态抢救或撤离时，建议佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿聚乙烯薄膜防毒服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:39:43', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4315, 4493, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风和全面排风。尽可能机械化、自动化。', '可能接触其蒸气时，必须佩戴防毒面具。紧急事态抢救或撤离时，建议佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:39:43', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4316, 4494, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '可能接触其蒸气时，佩戴防毒口罩。紧急事态抢救或逃生时，佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿防酸碱工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:39:45', '', NULL);
