INSERT INTO `msds_exposure_control` VALUES (4319, 4497, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。提供安全淋浴和洗眼设备。', '空气中粉尘浓度超标时，必须佩戴过滤式防尘呼吸器（半面罩）或自吸过滤式防尘口罩。紧急事态抢救或撤离时，建议佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴防化学品手套（如橡胶手套）。', NULL, NULL, NULL, '2026-03-06 14:39:45', '', NULL);
