INSERT INTO `msds_exposure_control` VALUES (4401, 4579, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '空气中浓度较高时，戴面具式呼吸器。紧急事态抢救或撤离时，建议佩戴自给式呼吸器。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN 374、美国US F739或AS/NZS标准认证的手套。', NULL, NULL, NULL, '2026-03-06 14:40:28', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4402, 4580, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作。提供良好的自然通风条件。', '一般不需要特殊防护。高浓度接触时佩戴空气呼吸器。', '一般不需特殊防护。', '穿一般作业工作服。', '戴一般作业防护手套。', NULL, NULL, NULL, '2026-03-06 14:40:28', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4403, 4581, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。尽可能机械化、自动化。提供安全淋浴和洗眼设备。', '空气中粉尘浓度超标时，佩戴自吸过滤式防毒面具（半面罩）或自给式呼吸器。紧急事态抢救或撤离时，建议佩戴空气呼吸器。', '佩戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:40:28', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4404, 4582, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '可能接触其粉尘时，应该佩戴自吸过滤式防尘口罩。', '戴化学安全防护眼镜。', '戴一般作业防护手套。', '戴一般作业防护手套。', NULL, NULL, NULL, '2026-03-06 14:40:29', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4405, 4583, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，注意通风。', '空气中浓度较高时，建议佩戴防毒面具。紧急事态抢救或撤离时，佩带供气式呼吸器。', '戴化学安全防护眼镜。', '穿工作服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:40:29', '', NULL);
