INSERT INTO `msds_exposure_control` VALUES (4454, 4632, NULL, '30', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。', '可能接触其蒸气时，应该佩戴自吸过滤式防毒面具（半面罩）。', '戴化学安全防护眼镜。', '穿防静电工作服。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:40:52', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4455, 4633, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '空气中浓度超标时，佩戴防毒面具。紧急事态抢救或撤离时，应该佩戴自给式呼吸器。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:40:53', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4456, 4634, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，注意通风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，佩戴过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。佩戴自给式正压全面罩呼吸器辅之以辅助自携式正压呼吸器。', '戴化学安全防护眼镜。', '穿防静电工作服。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:40:53', '', NULL);
