INSERT INTO `msds_exposure_control` VALUES (4459, 4637, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，注意通风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，佩戴过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '戴化学安全防护眼镜。', '穿防静电工作服。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:40:53', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4460, 4638, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '空气中浓度较高时，戴面具式呼吸器。紧急事态抢救或撤离时，建议佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿防静电工作服。', '戴橡皮胶手套。', NULL, NULL, NULL, '2026-03-06 14:40:55', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4461, 4639, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。', '空气中浓度超标时，必须佩戴自吸过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器或氧气呼吸器。', '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:40:55', '', NULL);
