INSERT INTO `msds_exposure_control` VALUES (4636, 4815, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。提供安全淋浴和洗眼设备。设置气体泄漏报警装置。', '空气中浓度较高时，应该佩戴防毒面具。紧急事态抢救或撤离时，建议佩戴自给式呼吸器。一般不需要特殊防护，但在密闭空间或高浓度环境下应佩戴空气呼吸器。', '一般不需特殊防护，但建议佩戴化学安全防护眼镜。', '穿防静电工作服。', '一般不需特殊防护，建议戴一般作业防护手套。', NULL, NULL, NULL, '2026-03-06 14:42:07', '', NULL);
