INSERT INTO `msds_exposure_control` VALUES (4643, 4822, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '可能接触其蒸气时，应该佩戴防毒口罩。紧急事态抢救或撤离时，建议佩戴自给式呼吸器。', '必要时戴化学安全防护眼镜。', '穿工作服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:42:11', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4644, 4823, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。', '空气中粉尘浓度超标时，建议佩戴自吸过滤式防尘口罩；可能接触其蒸气时，佩戴自吸过滤式防毒面具（半面罩）。', '戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:42:11', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4645, 4824, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。提供安全淋浴和洗眼设备。', '可能接触其粉尘时，应该佩戴自吸过滤式防尘口罩。紧急事态抢救或撤离时，建议佩戴自给式呼吸器。', '一般不需要特殊防护，高浓度接触时可戴安全防护眼镜。', '穿透气型防毒服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:42:11', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4646, 4825, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。提供安全淋浴和洗眼设备。', '空气中粉尘浓度超标时，佩戴自吸过滤式防尘口罩。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:42:11', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4647, 4826, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。', '空气中粉尘浓度超标时，必须佩戴自吸过滤式防尘口罩。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '佩戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:42:11', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4648, 4827, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。提供安全淋浴和洗眼设备。', '空气中粉尘浓度较高时，建议佩戴自吸过滤式防尘口罩。', '戴化学安全防护眼镜。', '穿紧袖工作服，长筒胶鞋。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:42:13', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4649, 4828, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。尽可能机械化、自动化。', '空气中浓度超标时，佩戴过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:42:13', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4650, 4829, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风或全面排风。', '作业工人应该佩戴防尘口罩。', '可采用安全面罩。', '穿防静电工作服。', '必要时戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:42:13', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4651, 4830, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风和全面通风。尽可能机械化、自动化。提供安全淋浴和洗眼设备。', '可能接触其粉尘时，应该佩戴自吸过滤式防尘口罩。紧急事态抢救或撤离时，建议佩戴自给式呼吸器。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴防化学品手套（如丁基橡胶手套、聚乙烯醇手套）。', NULL, NULL, NULL, '2026-03-06 14:42:13', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4652, 4831, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风和全面通风。', '空气中粉尘浓度超标时，佩戴自吸过滤式防尘口罩（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '佩戴防化手套（如丁基橡胶手套、丁腈橡胶手套）。', NULL, NULL, NULL, '2026-03-06 14:42:13', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4653, 4832, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。提供安全淋浴和洗眼设备。', '空气中粉尘浓度超标时，必须佩戴自吸过滤式防尘口罩（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:42:15', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4654, 4833, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风和全面排风。尽可能采用隔离式操作。', '可能接触其蒸气时，必须佩戴防毒面具。紧急事态抢救或撤离时，建议佩戴正压自给式呼吸器。', '戴化学安全防护眼镜。', '穿聚乙烯薄膜防毒服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:42:15', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4655, 4834, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '粉尘浓度较高的环境中，佩戴自吸过滤式防尘口罩。必要时，建议佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴一般作业防护手套。', NULL, NULL, NULL, '2026-03-06 14:42:15', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4656, 4835, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，注意通风。', '空气中浓度超标时，佩戴自吸过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器或氧气呼吸器。', '呼吸系统防护中已作防护。', '穿带面罩式胶布防毒衣。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:42:15', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4657, 4836, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。最好采用湿式操作。', '空气中粉尘浓度超标时，应该佩戴自吸过滤式防尘口罩。必要时，建议佩戴空气呼吸器。', '戴化学安全防护眼镜。', '穿防静电工作服。', '戴一般作业防护手套。', NULL, NULL, NULL, '2026-03-06 14:42:16', '', NULL);
