INSERT INTO `msds_exposure_control` VALUES (4680, 4859, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作。加强局部排风。', '空气中浓度较高时，应该佩戴防毒口罩。紧急事态抢救或撤离时，建议佩戴供气式头盔。', '戴安全防护眼镜。', '穿防静电工作服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:42:25', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4681, 4860, NULL, '0.005[皮]', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风和全面排风。', '作业工人应该佩戴碘化活性碳口罩。紧急事态抢救或撤离时，佩带自给式呼吸器。', '必要时戴安全防护眼镜。', '穿聚乙烯薄膜防毒服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:42:25', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4682, 4861, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', NULL, NULL, NULL, NULL, '2026-03-06 14:42:25', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4683, 4862, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '作业工人应该佩戴防尘口罩。紧急事态抢救或逃生时，应该佩戴自给式呼吸器。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:42:25', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4684, 4863, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。尽可能采取隔离操作。', '空气中粉尘浓度超标时，佩戴自吸过滤式防尘口罩（半面罩）或全面罩。紧急事态抢救或撤离时，建议佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴耐化学品手套（丁腈橡胶或氯丁橡胶材质）。', NULL, NULL, NULL, '2026-03-06 14:42:27', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4685, 4864, NULL, '0.001', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风或全面排风。尽可能机械化、自动化。', '作业工人佩戴防毒口罩。高浓度环境中，应该佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿相应的防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:42:27', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4686, 4865, NULL, '15', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风和全面通风。', NULL, '必要时，戴化学安全防护眼镜。', '穿化学防护服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:42:27', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4687, 4866, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风和全面通风。采用隔离式操作。提供安全淋浴和洗眼设备。', NULL, '呼吸系统防护中已作防护。', '穿带面罩式胶布防毒衣。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:42:27', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4688, 4867, NULL, '1mg/m³（以Cu计）', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。提供安全淋浴和洗眼设备。', '空气中粉尘浓度超标时，佩戴自吸过滤式防尘口罩（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN374、美国USF739或中国GB/T 29512标准认证的防护手套。', NULL, NULL, NULL, '2026-03-06 14:42:27', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4689, 4868, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。尽可能机械化、自动化。提供安全淋浴和洗眼设备。', '可能接触其蒸气时，建议佩戴自吸过滤式防毒面具（全面罩）。紧急事态抢救或撤离时，建议', '呼吸系统防护中已作防护。', '穿连衣式胶布防毒衣。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:42:29', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4690, 4869, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '可能接触其粉尘时，应该佩带防毒面具。必要时佩带自给式呼吸器。', '戴化学安全防护眼镜。', '穿工作服(防腐材料制作)。', '戴橡皮手套。', NULL, NULL, NULL, '2026-03-06 14:42:29', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4691, 4870, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '无资料', '无资料', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '无资料', NULL, NULL, NULL, '2026-03-06 14:42:30', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4692, 4871, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。提供安全淋浴和洗眼设备。设置局部排风装置，控制粉尘飞扬。', '空气中粉尘浓度超标时，佩戴自吸过滤式防尘半面罩。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '佩戴化学安全防护眼镜（符合欧盟EN166或美国NIOSH标准）。', '穿防毒物渗透工作服和抗静电的防护靴。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:42:30', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4693, 4872, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。操作场所应安装防爆通风系统，确保空气流通。设置紧急洗眼器和淋浴设备。可能接触该化学品的生产设备应密闭化、管道化，减少操作人员直接接触的机会。设置泄漏报警装置和应急通风系统。', '空气中浓度超标时，佩戴过滤式防毒面具（半面罩）或全面罩。紧急事态抢救或撤离时，佩戴空气呼吸器。建议使用符合GB 2626标准的KN95级别或更高级别的防护口罩。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴防化学品手套（如丁基橡胶手套、丁腈橡胶手套或聚氯乙烯手套）。手套应符合GB 24540-2009标准。手套使用前应检查是否有破损，使用后应正确处置。建议在操作过程中定期更换手套。', NULL, NULL, NULL, '2026-03-06 14:42:30', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4694, 4873, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风和全面通风。尽可能机械化、自动化。提供安全淋浴和洗眼设备。', '空气中粉尘浓度超标时，佩戴自吸过滤式防尘口罩（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:42:30', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4695, 4874, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。尽可能机械化、自动化。提供安全淋浴和洗眼设备。', '空气中浓度超标时，佩戴过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:42:31', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4696, 4875, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '采取密闭操作，提供充分的局部排风和全面通风。尽可能将操作过程自动化，减少人员直接接触。', '当空气中浓度超过职业接触限值时，佩戴自吸过滤式防毒面具（半面罩）或全面罩。紧急事态抢救或撤离时，佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴防化学品手套（如丁基橡胶手套、氟化橡胶手套）。建议使用符合EN374标准的防护手套。', NULL, NULL, NULL, '2026-03-06 14:42:31', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4697, 4876, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风和全面通风。', NULL, '呼吸系统防护中已作防护。', '穿带面罩式胶布防毒衣。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:42:31', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4698, 4877, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '空气中浓度超标时，必须佩戴自吸过滤式防毒面具（全面罩）或隔离式呼吸器。紧急事态抢救', '呼吸系统防护中已作防护。', '穿橡胶耐酸碱服。', '戴橡胶耐酸碱手套。', NULL, NULL, NULL, '2026-03-06 14:42:32', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4699, 4878, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '作业工人应该佩戴防尘口罩。必要时佩带防毒面具。', '戴化学安全防护眼镜。', '穿工作服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:42:33', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4700, 4879, NULL, '0.01mg(T1)／m3(皮)', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风或全面排风。尽可能机械化、自动化。', '作业工人应该佩戴防毒面具。紧急事态抢救或逃生时，佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿化学防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:42:33', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4701, 4880, NULL, '0.005[皮]', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '作业工人应该佩戴自吸过滤式防尘口罩。必要时，建议佩戴空气呼吸器、氧气呼吸器或长管面', '戴化学安全防护眼镜。', '穿聚乙烯防毒服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:42:33', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4702, 4881, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，注意通风。尽可能机械化、自动化。提供安全淋浴和洗眼设备。', '可能接触其烟雾时，佩戴过滤式防毒面具（半面罩）或空气呼吸器。紧急事态抢救或撤离时，建议佩戴空气呼吸器。', '戴化学安全防护眼镜。', '穿橡胶耐酸碱服。', '戴橡胶耐酸碱手套。', NULL, NULL, NULL, '2026-03-06 14:42:33', '', NULL);
