INSERT INTO `msds_exposure_control` VALUES (4709, 4888, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。提供安全淋浴和洗眼设备。设置局部排风系统，确保工作场所空气中氯甲酸甲酯浓度低于容许浓度。', '可能接触其蒸气时，佩戴自吸过滤式防毒面具（全面罩）。高浓度环境中，必须佩戴空气呼吸器或长管面具。', '戴化学安全防护眼镜或面罩。', '穿防毒物渗透工作服，必要时穿防化服。', '戴橡胶耐油手套，推荐使用丁基橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:42:36', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4710, 4889, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风和全面排风。', '空气中浓度超标时，必须佩戴自吸过滤式防毒面具（半面罩）或空气呼吸器。', '戴化学安全防护眼镜。', '穿防腐工作服。', '戴橡皮胶手套。', NULL, NULL, NULL, '2026-03-06 14:42:36', '', NULL);
