INSERT INTO `msds_exposure_control` VALUES (4719, 4898, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。尽可能机械化、自动化。提供安全淋浴和洗眼设备。', '可能接触其蒸气时，应该佩戴自吸过滤式防毒面具（半面罩）。紧急事态抢救或逃生时，佩戴自给正压式呼吸器。', '戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:42:41', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4720, 4899, NULL, '40mg/m3', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风和全面通风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，佩戴过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，建议佩戴空气呼吸器。', '戴化学安全防护眼镜。', '穿透气型防毒服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:42:41', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4721, 4900, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风和全面通风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，佩戴自吸过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，建议佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴防化学品手套（如丁基橡胶手套）。', NULL, NULL, NULL, '2026-03-06 14:42:42', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4722, 4901, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，必须佩戴自吸过滤式防毒面具（半面罩）或供气式呼吸器。紧急事态抢救或撤离时，建议佩戴空气呼吸器。', '戴化学安全防护眼镜。', '穿防静电工作服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:42:42', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4723, 4902, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。提供安全淋浴和洗眼设备。', '空气中粉尘浓度超标时，佩戴自吸过滤式防尘口罩（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '戴化学安全防护眼镜。', '穿一般作业防护服。', '戴一般作业防护手套。', NULL, NULL, NULL, '2026-03-06 14:42:42', '', NULL);
