INSERT INTO `msds_exposure_control` VALUES (4791, 4970, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风和全面通风。尽可能机械化、自动化。提供安全淋浴和洗眼设备。', '空气中粉尘浓度超标时，必须佩戴过滤式防尘呼吸器（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴防化学品手套（丁基橡胶或聚氯乙烯材质）。', NULL, NULL, NULL, '2026-03-06 14:43:11', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4792, 4971, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。尽可能机械化、自动化。提供安全淋浴和洗眼设备。', '空气中粉尘浓度超标时，必须佩戴过滤式防尘呼吸器（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿连衣式胶布防毒衣。', '戴防化学品手套（丁基橡胶或聚氯乙烯材质）。', NULL, NULL, NULL, '2026-03-06 14:43:11', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4793, 4972, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', NULL, NULL, NULL, NULL, '2026-03-06 14:43:13', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4794, 4973, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '可能接触其蒸气时，必须佩戴防毒口罩。高浓度环境中，建议佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿防腐工作服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:43:13', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4795, 4974, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '作业工人应该佩戴防尘口罩。空气中浓度较高时，建议佩戴防毒面具。', '戴化学安全防护眼镜。', '穿防腐工作服。', '戴橡皮手套。', NULL, NULL, NULL, '2026-03-06 14:43:13', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4796, 4975, NULL, '无资料（中国尚未制定七溴二苯醚特定职业接触限值）', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。尽可能机械化、自动化操作。提供充分的局部通风和全面通风。使用密闭系统和设备，防止粉尘释放到车间空气中。工作场所应配备紧急洗眼器和冲淋设备', '空气中粉尘浓度超标时，必须佩戴过滤式防尘口罩（符合GB/T 32610标准，过滤效率≥95%）；紧急事态抢救或撤离时，应佩戴自给式呼吸器或正压式空气呼吸器（符合GB/T 16556标准）', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。如存在粉尘暴露风险，应佩戴防尘眼镜或面罩。工作现场应提供紧急洗眼设备', '穿阻燃防静电防护服和抗静电的防护靴。工作服应定期清洗，受污染的工作服应单独存放并专业清洗。避免工作服带出工作场所', '佩戴防化学品手套（推荐材质：丁腈橡胶或氯丁橡胶，符合EN 374标准）。手套应定期检查，如发现破损应立即更换。操作后应彻底清洗双手', NULL, NULL, NULL, '2026-03-06 14:43:13', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4797, 4976, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', NULL, NULL, NULL, NULL, '2026-03-06 14:43:14', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4798, 4977, NULL, '美国IDLH：5mg／m3，ACGIH', NULL, NULL, NULL, NULL, NULL, NULL, '无资料', '紧急情况下，戴压气式呼吸器、自吸式呼吸器、全面罩自携式呼吸器或自吸式送风呼吸器', '无资料', '穿全遮式防化服', '无资料', NULL, NULL, NULL, '2026-03-06 14:43:14', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4799, 4978, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '作业工人应该佩戴防毒口罩。高浓度环境中，佩戴防毒面具。', '戴化学安全防护眼镜。', '穿工作服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:43:14', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4800, 4979, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', NULL, NULL, NULL, NULL, '2026-03-06 14:43:16', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4801, 4980, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。提供安全淋浴和洗眼设备。', '一般不需要特殊防护，高浓度接触时可佩戴自吸过滤式防毒面具（半面罩）或空气呼吸器。', '一般不需要特殊防护，高浓度接触时可戴化学安全防护眼镜。', '穿防静电工作服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:43:16', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4802, 4981, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。提供安全淋浴和洗眼设备。', '佩戴防尘口罩或自吸过滤式防毒面具。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:43:17', '', NULL);
