INSERT INTO `msds_exposure_control` VALUES (4859, 5038, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。尽可能机械化、自动化。提供安全淋浴和洗眼设备。', '空气中浓度超标时，必须佩戴过滤式防毒面具（半面罩）或自给式呼吸器。紧急事态抢救或撤离时，建议佩戴空气呼吸器。', '佩戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:43:40', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4860, 5039, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。尽可能机械化、自动化。', '空气中粉尘浓度超标时，佩戴自吸过滤式防尘口罩。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴橡胶手套或丁腈橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:43:40', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4861, 5040, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风和全面通风。工作场所应设置独立的通风系统，确保空气中有害物质浓度低于职业接触限值。提供安全淋浴和洗眼设备。可能接触粉尘的场所应设置除尘装置。操作人员必须经过专门培训，严格遵守操作规程。', '空气中粉尘浓度超标时，佩戴符合GB 2626标准的KN95或N95防尘口罩（半面罩）。可能接触蒸气时，佩戴过滤式防毒半面罩或全面罩，配适合的滤毒盒。紧急事态抢救或撤离时，应该佩戴空气呼吸器或长管面具。', '佩戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '佩戴防化学品手套（丁腈橡胶、氯丁橡胶或聚乙烯醇手套）。手套应定期更换，破损时立即更换。建议使用符合GB 24541标准的化学品防护手套。', NULL, NULL, NULL, '2026-03-06 14:43:40', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4862, 5041, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。尽可能以机械化、自动化替代手工操作，减少人员直接接触。设置应急通风系统和洗眼器。操作区域应配备适当的通风设备，确保空气流通。', '空气中浓度超标时，佩戴过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '佩戴防化学品手套（丁基橡胶或氟橡胶材质），手套应符合相关标准（如GB 24540-2009）。手套在使用前应检查气密性，破损后及时更换。', NULL, NULL, NULL, '2026-03-06 14:43:40', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4863, 5042, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭化，加强通风。提供安全淋浴和洗眼设备。设置局部排风装置和全面通风系统。在可能接触的场所设置警示标识和应急处理设施。', '空气中浓度超标时，佩戴过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，佩戴空气呼吸器或长管面具。', '佩戴化学安全防护眼镜。如可能接触液体，应佩戴面罩。', '穿防毒物渗透工作服。建议穿防静电工作服。', '戴橡胶耐油手套。建议使用丁基橡胶手套或氟化橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:43:42', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4864, 5043, NULL, '未制订标准前', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，注意通风。尽可能机械化、自动化。', '可能接触其蒸气时，应该佩戴防毒面具。紧急事态抢救或撤离时，建议佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿防腐工作服。', '戴橡皮胶手套。', NULL, NULL, NULL, '2026-03-06 14:43:42', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4865, 5044, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '高浓度环境中，应该佩戴防毒面具。紧急事态抢救或逃生时，佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿相应的防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:43:42', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4866, 5045, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，注意通风。', '空气中浓度超标时，佩带防毒面具。紧急事态抢救或撤离时，建议佩戴供气式头盔。', '戴化学安全防护眼镜。', '穿工作服。', '必要时戴橡皮手套。', NULL, NULL, NULL, '2026-03-06 14:43:42', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4867, 5046, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '空气中浓度较高时，戴面具式呼吸器。', '戴化学安全防护眼镜。', '穿防酸碱工作服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:43:42', '', NULL);
