INSERT INTO `msds_exposure_control` VALUES (4869, 5048, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作。', '高浓度环境中，应该佩戴供气式呼吸器。', '可采用安全面罩。', '穿工作服。', '一般不需特殊防护。', NULL, NULL, NULL, '2026-03-06 14:43:44', '', NULL);
