INSERT INTO `msds_exposure_control` VALUES (4881, 5060, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '可能接触其蒸气时，应该佩戴防毒口罩。', '戴化学安全防护眼镜。', '穿相应的防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:43:49', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4882, 5061, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '可能接触其蒸气时，建议佩戴防毒口罩。紧急事态抢救或逃生时，应该佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿相应的防护服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:43:49', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4883, 5062, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '生产操作或农业使用时，应该佩戴防尘口罩。', '戴安全防护眼镜。', '穿相应的防护服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:43:49', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4884, 5063, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '作业工人应该佩戴防尘口罩。', '可采用安全面罩。', '穿工作服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:43:49', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4885, 5064, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。提供安全淋浴和洗眼设备。', '空气中粉尘浓度超标时，佩戴自吸过滤式防尘口罩。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:43:51', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4886, 5065, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。使用防爆型通风系统和设备。工作场所应设置应急洗眼器和淋浴设备。操作区域应保持负压状态，换气次数不少于12次/小时。设置局部排风罩，控制风速不低于0.5m/s。配备氯化氢气体检测报警装置，报警阈值设定为5ppm。', '可能接触其烟雾时，必须佩戴防毒面具。紧急事态抢救或撤离时，建议佩戴自给式呼吸器。推荐使用带有机蒸气滤盒的呼吸防护器，滤盒类型为A型(有机蒸气)。在浓度超过10倍TLV(如已设定)或未知浓度环境中，应使用全面罩正压式空气呼吸器(SCBA)。', '戴化学安全防护眼镜或面罩，防止溅入眼睛。推荐使用间接通风式化学护目镜，符合ANSI Z87.1标准。当存在飞溅风险时，应佩戴全面罩或化学防护面屏。', '穿防腐工作服，建议使用耐酸碱材质的防护服。推荐使用PVC、氯丁橡胶或丁基橡胶材质的防护服，符合ASTM F1001标准。防护服应完全覆盖身体，袖口和裤脚应收紧。在高风险操作中应考虑使用化学防护围裙和靴套。', '戴耐化学腐蚀手套，推荐使用丁腈橡胶或氯丁橡胶材质手套。手套厚度应不少于0.5mm，符合EN 374标准。建议使用双层手套系统，内层为丁腈手套，外层为氯丁橡胶手套。手套使用前应进行气密性检查，使用后应正确脱除并妥善处理。', NULL, NULL, NULL, '2026-03-06 14:43:51', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4887, 5066, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。', '可能接触毒物时，应该佩戴防毒口罩。空气中浓度较高时，佩戴自给式呼吸器。', '可采用安全面罩。', '穿相应的防护服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:43:51', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4888, 5067, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。', '高浓度接触时，应该佩戴防毒面具。', '戴化学安全防护眼镜。', '穿工作服。', '必要时戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:43:51', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4889, 5068, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '可能接触其蒸气时，佩戴防毒面具。紧急事态抢救或逃生时，应该佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿防静电工作服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:43:53', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4890, 5069, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '生产操作或农业使用时，应戴口罩。紧急事态抢救或逃生时，应该佩戴防毒面具。', '必要时戴安全防护眼镜。', '穿紧袖工作服，长筒胶鞋。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:43:53', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4891, 5070, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。尽可能机械化、自动化。提供安全淋浴和洗眼设备。', NULL, '呼吸系统防护中已作防护。', '穿连衣式胶布防毒衣。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:43:53', '', NULL);
