INSERT INTO `msds_exposure_control` VALUES (4905, 5084, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', NULL, NULL, NULL, NULL, '2026-03-06 14:43:59', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4906, 5085, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，佩戴过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:43:59', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4907, 5086, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。', '可能接触其蒸气时，佩戴防毒口罩。紧急事态抢救或逃生时，建议佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿防静电工作服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:43:59', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4908, 5087, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风和全面通风。提供安全淋浴和洗眼设备。', '空气中粉尘浓度超标时，佩戴自吸过滤式防尘口罩。紧急事态抢救或撤离时，建议佩戴空气呼吸器。', '戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:44:00', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4909, 5088, NULL, '1', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风和全面通风。', '空气中浓度较高时，应该佩戴自吸过滤式防毒面具（半面罩）。', '戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:44:01', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4910, 5089, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风和全面通风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，佩戴自吸过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，建议佩戴空气呼吸器或氧气呼吸器。', '戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:44:01', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4911, 5090, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风和全面排风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，佩戴过滤式防毒面具（半面罩）或自给式呼吸器。紧急事态抢救或逃生时，佩戴正压自给式呼吸器。', '戴化学安全防护眼镜，或面罩。', '穿防毒物渗透工作服，或防化学品防护服。', '戴防化学品手套（如丁基橡胶手套、聚乙烯醇手套等）。', NULL, NULL, NULL, '2026-03-06 14:44:01', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4912, 5091, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风和全面通风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，佩戴自吸过滤式防毒面具（半面罩）或导管式防毒面具。紧急事态抢救或撤离时，建议佩戴空气呼吸器。', '呼吸系统防护中已作防护。', '穿带面罩式胶布防毒衣。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:44:01', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4913, 5092, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，佩戴自吸过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，建议佩戴空气呼吸器。', '戴化学安全防护眼镜。', '穿防酸碱工作服。', '戴橡胶耐酸碱手套。', NULL, NULL, NULL, '2026-03-06 14:44:03', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4914, 5093, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风或全面排风。', '可能接触毒物时，佩戴防毒口罩。空气中浓度较高时，建议佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿防腐工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:44:03', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4915, 5094, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风和全面通风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，必须佩戴自吸过滤式防毒面具（半面罩）或自给式呼吸器。紧急事态抢救或撤离时，建议佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。操作时佩戴面罩。', '穿阻燃防静电防护服和抗静电的防护靴。穿防化学品渗透的工作服。', '戴橡胶耐油手套或防化学品手套（符合欧盟EN374或美国NIOSH标准）。', NULL, NULL, NULL, '2026-03-06 14:44:03', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4916, 5095, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '可能接触毒物时，应该佩戴防毒口罩。紧急事态抢救或撤离时，建议佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿防腐工作服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:44:03', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4917, 5096, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，必须佩戴自吸过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '戴化学安全防护眼镜。', '穿防酸碱工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:44:03', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4918, 5097, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。尽可能机械化、自动化。提供安全淋浴和洗眼设备。', '空气中浓度超标时，必须佩戴自吸过滤式防毒面具（全面罩）或隔离式呼吸器。紧急事态抢救或撤离时，建议佩戴空气呼吸器。', '戴化学安全防护眼镜。', '穿连衣式胶布防毒衣。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:44:05', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4919, 5098, NULL, '1mg/m3[以锑计]', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风和全面通风。提供安全淋浴和洗眼设备。', '空气中粉尘浓度超标时，佩戴自吸过滤式防尘口罩。紧急事态抢救或撤离时，建议佩戴空气呼吸器。', '戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:44:05', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4920, 5099, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，佩戴自吸过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，建议佩戴正压自给式呼吸器。', '戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:44:05', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4921, 5100, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。', '空气中浓度较高时，建议佩戴自吸过滤式防毒面具（半面罩）。', '一般不需特殊防护。', '穿一般作业工作服。', '戴一般作业防护手套。', NULL, NULL, NULL, '2026-03-06 14:44:05', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4922, 5101, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。', '空气中浓度超标时，应该佩带防毒面具。紧急事态抢救或逃生时，佩带自给式呼吸器。', '一般不需特殊防护。', '穿工作服。', '一般不需特殊防护。', NULL, NULL, NULL, '2026-03-06 14:44:06', '', NULL);
