INSERT INTO `msds_exposure_control` VALUES (4975, 5154, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。', '作业工人应该佩戴防尘口罩。', '戴化学安全防护眼镜。', '穿防静电工作服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:44:30', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4976, 5155, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', NULL, NULL, NULL, NULL, '2026-03-06 14:44:30', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4977, 5156, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '空气中粉尘浓度较高时，建议佩戴自吸过滤式防尘口罩。', '必要时，戴化学安全防护眼镜。', '穿紧袖工作服，长筒胶鞋。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:44:30', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4978, 5157, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。', '空气中浓度较高时，应该佩戴防毒面具。紧急事态抢救或撤离时，建议佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿防酸碱工作服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:44:31', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4979, 5158, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，注意通风。尽可能机械化、自动化。提供安全淋浴和洗眼设备。', '可能接触其蒸气时，必须佩戴自吸过滤式防毒面具（全面罩）或自给式呼吸器。紧急事态抢救或撤离时，建议佩戴空气呼吸器。', '呼吸系统防护中已作防护。', '穿橡胶耐酸碱服。', '戴橡胶耐酸碱手套。', NULL, NULL, NULL, '2026-03-06 14:44:31', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4980, 5159, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。提供安全淋浴和洗眼设备。', '空气中粉尘浓度超标时，应该佩戴一级或二级自吸过滤式防尘口罩。', '戴化学安全防护眼镜。', '穿橡胶耐酸碱服。', '戴橡胶耐酸碱手套。', NULL, NULL, NULL, '2026-03-06 14:44:31', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4981, 5160, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，注意通风。尽可能机械化、自动化。提供安全淋浴和洗眼设备。', '可能接触其蒸气时，必须佩戴导管式防毒面具或氧气呼吸器。紧急事态抢救或撤离时，建议佩戴空气呼吸器。', '呼吸系统防护中已作防护。', '穿橡胶耐酸碱服。', '戴橡胶耐酸碱手套。', NULL, NULL, NULL, '2026-03-06 14:44:31', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4982, 5161, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风或全面排风。', '作业工人应戴口罩。紧急事态抢救或逃生时，建议佩戴防毒面具。', '高浓度蒸汽接触可戴化学安全防护眼镜。', '穿防静电工作服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:44:33', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (4983, 5162, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风或全面排风。', '作业工人应该佩戴防毒口罩。空气中浓度较高时，应该佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿相应的防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:44:33', '', NULL);
