INSERT INTO `msds_exposure_control` VALUES (5036, 5215, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '提供良好的自然通风条件。', '高浓度环境中，应该佩戴供气式头盔。', '必要时戴化学安全防护眼镜。', '穿工作服。', '一般不需要特殊防护，高浓度接触时可戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:44:55', '', NULL);
