INSERT INTO `msds_exposure_control` VALUES (5048, 5227, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '可能接触其蒸气时，应该佩戴防毒口罩。紧急事态抢救或逃生时，建议佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿防腐工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:45:00', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5049, 5228, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。提供安全淋浴和洗眼设备。', '空气中粉尘浓度超标时，佩戴自吸过滤式防尘口罩。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '戴护目镜、防毒面具', '穿全身防护衣、足靴，戴不透水手套；衣物污染后随时清洗；每年进行一次体检', '戴防化学品手套', NULL, NULL, NULL, '2026-03-06 14:45:00', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5050, 5229, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，注意通风。', '一般不需特殊防护。', '可采用安全面罩。', '穿工作服。', '必要时戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:45:00', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5051, 5230, NULL, '2', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。最好采用湿式作业。', '应该佩戴防尘口罩（全面罩）。', '可采用安全面罩。', '穿工作服。', '一般不需特殊防护。', NULL, NULL, NULL, '2026-03-06 14:45:02', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5052, 5231, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，佩戴过滤式防毒面具（半面罩）。', '戴安全防护眼镜。', '穿防静电工作服。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:45:02', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5053, 5232, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，佩戴过滤式防毒面具（半面罩）。', '戴化学安全防护眼镜。', '穿防静电工作服。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:45:02', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5054, 5233, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。尽可能机械化、自动化。', '可能接触蒸气时，应该佩戴自吸过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器或氧气呼吸器。', '戴化学安全防护眼镜。', '穿防静电工作服。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:45:04', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5055, 5234, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。尽可能机械化、自动化。', '可能接触蒸气时，应该佩戴自吸过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器或氧气呼吸器。', '戴化学安全防护眼镜。', '穿防静电工作服。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:45:04', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5056, 5235, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。提供安全淋浴和洗眼设备。', '佩戴导管式防毒面具（全面罩）。', '呼吸系统防护中已作防护。', '穿防毒物渗透工作服。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:45:05', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5057, 5236, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。', '高浓度环境中，佩带防毒面具。紧急事态抢救或逃生时，建议佩带自给式呼吸器。', '戴化学安全防护眼镜。', '穿相应的防护服。', '戴防化学品手套。也可使用皮肤防护膜。', NULL, NULL, NULL, '2026-03-06 14:45:05', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5058, 5237, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，佩戴过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，佩戴空气呼吸器。', '佩戴化学安全防护眼镜。', '穿防静电工作服。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:45:05', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5059, 5238, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭化，加强通风排气。提供安全淋浴和洗眼设备。设置局部排风装置，将有害物质排出工作场所。', '空气中浓度超标时，佩戴过滤式防毒面具（半面罩）或自给式呼吸器。紧急事态抢救或撤离时，佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴耐化学品的橡胶手套或丁腈橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:45:07', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5060, 5239, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，佩戴自吸过滤式防毒面具（半面罩）或自吸过滤式防毒面具（全面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器或氧气呼吸器。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:45:08', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5061, 5240, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，必须佩戴自吸过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器或氧气呼吸器。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:45:10', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5062, 5241, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '使用局部排风或全面通风。确保工作区域有良好的通风系统。', '当空气中化学品浓度超过职业接触限值时，佩戴防毒面具（符合欧盟EN140或美国NIOSH标准）。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '佩戴防化学品手套（符合欧盟EN374或美国NIOSH标准）。', NULL, NULL, NULL, '2026-03-06 14:45:10', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5063, 5242, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。', '应戴口罩。高浓度环境中，佩戴防毒面具。', '一般不需要特殊防护，高浓度接触时可戴安全防护眼镜。', '穿防静电工作服。', '必要时戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:45:11', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5064, 5244, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，注意通风。尽可能机械化、自动化。', '可能接触其蒸气或烟雾时，必须佩带防毒面具或供气式头盔。紧急事态抢救或逃生时，建', '戴化学安全防护眼镜。', '穿工作服(防腐材料制作)。', '戴橡皮手套。', NULL, NULL, NULL, '2026-03-06 14:45:11', '', NULL);
