INSERT INTO `msds_exposure_control` VALUES (5074, 5254, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。尽可能机械化、自动化。提供安全淋浴和洗眼设备。', '空气中粉尘浓度超标时，佩戴自吸过滤式防尘口罩（全面罩）。紧急事态抢救或撤离时，建议佩戴空气呼吸器。', '佩戴化学安全防护眼镜。', '穿防静电工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:45:14', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5075, 5255, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。尽可能机械化、自动化。', '可能接触其蒸气时，应该佩带防毒面具。紧急事态抢救或逃生时，佩带自给式呼吸器。', '戴化学安全防护眼镜。', '穿相应的防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:45:16', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5076, 5256, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。尽可能机械化、自动化。', '可能接触其蒸气时，佩戴防毒面具。紧急事态抢救或逃生时，应该佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿相应的防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:45:16', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5077, 5257, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。', '空气中浓度超标时，应该佩戴防毒面具。', '必要时戴化学安全防护眼镜。', '穿工作服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:45:16', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5078, 5258, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。', '生产操作或农业使用时，建议佩戴防毒口罩。紧急事态抢救或撤离时，佩带自给式呼吸器。', '一般不需特殊防护，但建议特殊情况下，戴化学安全防护眼镜。', '穿聚乙烯薄膜防毒服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:45:16', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5079, 5259, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风和全面通风。尽可能机械化、自动化。提供安全淋浴和洗眼设备。', '空气中浓度超标时，佩戴过滤式防毒面具（半面罩）或自给式呼吸器。紧急事态抢救或撤离时，建议佩戴空气呼吸器。', '佩戴化学安全防护眼镜。', '穿防静电工作服。', '戴防化学品手套（丁基橡胶手套）。', NULL, NULL, NULL, '2026-03-06 14:45:17', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5080, 5260, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风和全面通风。提供安全淋浴和洗眼设备。尽可能机械化、自动化操作，减少人员直接接触。', '空气中浓度超标时，佩戴过滤式防毒面具（半面罩）或自吸过滤式防尘半面罩。紧急事态抢救或撤离时，佩戴空气呼吸器。', '佩戴化学安全防护眼镜或面罩。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴防化学品手套（推荐材料：丁基橡胶、氟化橡胶、聚乙烯醇）。', NULL, NULL, NULL, '2026-03-06 14:45:18', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5081, 5261, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。提供安全淋浴和洗眼设备。', '可能接触其蒸气时，应该佩戴过滤式防毒面具（半面罩）。', '戴化学安全防护眼镜。', '穿化学防护服。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:45:18', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5082, 5262, NULL, '0.13mg/m3[皮]', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。提供安全淋浴和洗眼设备。', '可能接触其蒸气时，必须佩戴自吸过滤式防毒面具（全面罩）。紧急事态抢救或撤离时，建议佩戴空气呼吸器。', '呼吸系统防护中已作防护。', '穿橡胶耐酸碱服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:45:18', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5083, 5263, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。尽可能机械化、自动化。提供安全淋浴和洗眼设备。', '建议操作人员佩戴自吸过滤式防毒面具（半面罩），戴化学安全防护眼镜。', '戴化学安全防护眼镜。', '穿透气型防毒服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:45:18', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5084, 5264, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '空气中浓度较高时，戴面具式呼吸器。紧急事态抢救或撤离时，建议佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿防酸碱工作服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:45:20', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5085, 5265, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '空气中浓度较高时，戴面具式呼吸器。紧急事态抢救或撤离时，建议佩戴自给式呼吸器。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:45:20', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5086, 5266, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '空气中浓度较高时，戴面具式呼吸器。紧急事态抢救或撤离时，建议佩戴自给式呼吸器。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:45:20', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5087, 5267, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作。提供良好的自然通风条件。', '空气中浓度较高时，戴面具式呼吸器。紧急事态抢救或撤离时，佩戴供气式呼吸器。', '必要时戴安全防护眼镜。', '穿工作服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:45:20', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5088, 5268, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '空气中浓度较高时，戴面具式呼吸器。紧急事态抢救或撤离时，建议佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿一般工作服。', '戴橡皮胶手套。', NULL, NULL, NULL, '2026-03-06 14:45:21', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5089, 5269, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '选用适当呼吸器', '戴防尘镜，保护眼睛', '穿戴清洁完好的防护用具(防护服、手套、足靴、头盔)，以保护皮肤', '无资料', NULL, NULL, NULL, '2026-03-06 14:45:22', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5090, 5270, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '佩戴防毒口罩。空气中浓度较高时，应该佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿相应的防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:45:22', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5091, 5271, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风和全面通风。', '空气中粉尘浓度超标时，应该佩戴自吸过滤式防尘口罩。紧急事态抢救或撤离时，应该佩戴空气呼吸器或长管面具。', '戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:45:22', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5092, 5272, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '可能接触其蒸气时，应该佩戴防毒口罩。紧急事态抢救或逃生时，佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿防腐工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:45:22', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5093, 5273, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风和全面通风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，必须佩戴自吸过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:45:22', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5094, 5274, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '可能接触其蒸气时，佩戴防毒口罩。紧急事态抢救或逃生时，应该佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿相应的防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:45:24', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5095, 5275, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风和全面排风。', '可能接触毒物时，必须佩戴防毒面具。紧急事态抢救或撤离时，建议佩戴正压自给式呼吸', '戴化学安全防护眼镜。', '穿胶布防毒服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:45:24', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5096, 5276, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风和全面通风。', '空气中浓度超标时，必须佩戴自吸过滤式防毒面具（全面罩）或隔离式呼吸器。紧急事态抢救或撤离时，建议佩戴正压自给式呼吸器。', '呼吸系统防护中已作防护。', '穿密闭型防毒服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:45:24', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5097, 5277, NULL, '1mg(F)／m3', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风和全面排风。', '空气中浓度较高时，应该佩戴防毒面具。紧急事态抢救或撤离时，佩带自给式呼吸器。', '必要时戴安全防护眼镜。', '穿胶布防毒服。', '必要时戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:45:24', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5098, 5278, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '采用密闭化生产，减少粉尘飞扬。设置局部排风装置，在产生粉尘的作业点安装有效的通风除尘设施。确保工作场所通风良好，定期检查通风系统运行状况。操作区域应与其他工作区域隔离。设置应急通风系统，以应对泄漏事故。', '空气中铅尘浓度超标时，佩戴自吸过滤式防尘半面罩（符合GB 2626-2006 KN95或KN100标准）。氟化物浓度超标时，佩戴自吸过滤式防毒半面罩（全面罩或半面罩），配相应滤毒盒。紧急救援或泄漏处理时，佩戴正压自给式空气呼吸器(SCBA)。', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴橡胶手套、丁基橡胶手套或防化学品手套（符合EN 374标准）。手套应定期更换，破损后立即更换。', NULL, NULL, NULL, '2026-03-06 14:45:25', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5099, 5279, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，注意通风。', '作业工人应该佩戴防尘口罩。', '戴防辐射面罩。', '穿抗辐射防护服。', '戴抗辐射手套。', NULL, NULL, NULL, '2026-03-06 14:45:25', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5100, 5280, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。', '一般不需要特殊防护，高浓度接触时可佩戴自吸过滤式防毒面具（半面罩）。', '一般不需特殊防护。', '穿一般作业工作服。', '戴一般作业防护手套。', NULL, NULL, NULL, '2026-03-06 14:45:26', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5101, 5281, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN374、美国USF739或', NULL, NULL, NULL, '2026-03-06 14:45:26', '', NULL);
