INSERT INTO `msds_exposure_control` VALUES (5116, 5296, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。提供安全淋浴和洗眼设备。', '可能接触其蒸气时，必须佩戴自吸过滤式防毒面具（全面罩）或隔离式呼吸器。紧急事态抢救或撤离时，建议佩戴空气呼吸器。', '呼吸系统防护中已作防护。', '穿橡胶耐酸碱服。', '戴橡胶耐酸碱手套。', NULL, NULL, NULL, '2026-03-06 14:45:31', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5117, 5297, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。提供安全淋浴和洗眼设备。', '可能接触其粉尘时，应该佩戴自吸过滤式防尘口罩。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '戴化学安全防护眼镜。', '穿防酸碱工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:45:31', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5118, 5298, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。提供安全淋浴和洗眼设备。', '可能接触其蒸气时，应该佩戴自吸过滤式防毒面具（半面罩）。必要时，佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿橡胶耐酸碱服。', '戴乳胶耐酸碱手套。', NULL, NULL, NULL, '2026-03-06 14:45:32', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5119, 5299, NULL, '无资料（建议查询中国职业卫生标准GBZ 2.1-2019，或向供应商索取具体限值数据）', NULL, NULL, NULL, NULL, NULL, NULL, '无资料（建议采用密闭操作、局部排风和全面通风相结合的控制措施，确保工作场所空气中浓度低于职业接触限值）', '无资料（建议佩戴防毒面具，滤毒盒类型根据实际检测结果选择，或佩戴正压式空气呼吸器）', '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '无资料（建议佩戴防化学品手套，材质可选择丁腈橡胶、氯丁橡胶或氟橡胶，手套厚度≥0.5mm）', NULL, NULL, NULL, '2026-03-06 14:45:32', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5120, 5300, NULL, '无资料（建议基于重氮化合物和锌盐特性制定职业接触限值，或参考相似化合物数据）', NULL, NULL, NULL, NULL, NULL, NULL, '无资料（建议采用密闭操作系统，局部排风和全面通风相结合，防爆型通风设备）', '无资料（建议佩戴防毒面具，选择适合有机蒸气和颗粒物的滤毒盒，或正压式空气呼吸器）', '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN374、美国USF739或AS/NZS', NULL, NULL, NULL, '2026-03-06 14:45:32', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5121, 5301, NULL, '200', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。', NULL, '戴化学安全防护眼镜。', '穿透气型防毒服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:45:32', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5122, 5302, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '可能接触其蒸气时，必须佩带防毒口罩。紧急事态抢救或逃生时，建议佩带自给式呼吸器。', '戴化学安全防护眼镜。', '穿相应的防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:45:32', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5123, 5303, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。', '可能接触其蒸气时，佩戴防毒口罩。紧急事态抢救或逃生时，应该佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿防静电工作服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:45:33', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5124, 5304, NULL, '300', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。提供安全淋浴和洗眼设备。', '可能接触其蒸气时，应该佩戴过滤式防毒面具（半面罩）。必要时，建议佩戴自给式呼吸', '一般不需要特殊防护，高浓度接触时可戴安全防护眼镜。', '穿防静电工作服。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:45:34', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5125, 5305, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，注意通风。', '可能接触其蒸气时，应该佩戴防毒面具。', '戴化学安全防护眼镜。', '穿工作服。', '戴橡皮手套。', NULL, NULL, NULL, '2026-03-06 14:45:34', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5126, 5306, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', NULL, NULL, NULL, NULL, '2026-03-06 14:45:34', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5127, 5307, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。提供安全淋浴和洗眼设备。', '空气中浓度较高时，建议佩戴自吸过滤式防毒面具（半面罩）。', '戴安全防护眼镜。', '穿防毒物渗透工作服。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:45:34', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5128, 5308, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。尽可能机械化、自动化。', '作业工人佩戴防毒口罩。紧急事态抢救或逃生时，应该佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿相应的防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:45:35', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5129, 5309, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，佩戴自吸过滤式防毒面具（半面罩）或空气呼吸器。紧急事态抢救或撤离时，佩戴空气呼吸器。', '呼吸系统防护中已作防护。', '穿聚乙烯防毒服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:45:35', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5130, 5310, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风或全面排风。尽可能机械化、自动化。', '高浓度环境中，佩戴防毒面具。', '戴化学安全防护眼镜。', '穿防静电工作服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:45:35', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5131, 5311, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。提供安全淋浴和洗眼设备。', '空气中粉尘浓度超标时，必须佩戴自吸过滤式防尘口罩（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:45:35', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5132, 5312, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。提供安全淋浴和洗眼设备。工作场所应配备急救设备和药品。', '可能接触毒物时，应选择佩戴自吸过滤式防尘口罩。紧急事态抢救或撤离时，建议佩戴空气呼吸器。', '戴化学安全防护眼镜。必要时，戴面罩或呼吸防护器。', '穿透气型防毒服。工作现场禁止吸烟、进食和饮水。', '戴防化学品手套。戴防护手套，防止皮肤接触。', NULL, NULL, NULL, '2026-03-06 14:45:36', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5133, 5313, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风和全面通风。', '空气中粉尘浓度超标时，应该佩戴头罩型电动送风过滤式防尘呼吸器。；可能接触其蒸气时，', '呼吸系统防护中已作防护。', '穿防酸碱塑料工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:45:37', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5134, 5314, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。提供安全淋浴和洗眼设备。设置局部排风装置和全面通风系统。工作场所禁止吸烟、进食和饮水。', '可能接触其蒸气时，应该佩戴自吸过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，佩戴空气呼吸器或氧气呼吸器。', '戴化学安全防护眼镜或面罩。', '穿防毒物渗透工作服或防酸碱工作服。', '戴橡胶耐酸碱手套或丁基橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:45:37', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5135, 5315, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '作业工人应该佩带防尘口罩。必要时佩带防毒面具。', '戴化学安全防护眼镜。', '穿相应的防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:45:37', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5136, 5316, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', NULL, NULL, NULL, NULL, '2026-03-06 14:45:38', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5137, 5317, NULL, '0.03[烟]，0.05[尘]', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。提供安全淋浴和洗眼设备。', NULL, '一般不需特殊防护。必要时，戴安全防护眼镜。', '穿透气型防毒服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:45:38', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5138, 5318, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。尽可能机械化、自动化。', '可能接触其蒸气时，应该佩戴防毒面具。紧急事态抢救或逃生时，佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿化学防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:45:38', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5139, 5319, NULL, '0.005[皮]', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。尽可能机械化、自动化。提供安全淋浴和洗眼设备。', NULL, '呼吸系统防护中已作防护。', '穿防毒物渗透工作服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:45:38', '', NULL);
