INSERT INTO `msds_exposure_control` VALUES (5164, 5344, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风和全面排风。', '吸器。', '戴化学安全防护眼镜。', '穿胶布防毒服。', '必要时戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:45:46', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5165, 5345, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。', '空气中浓度较高时，必须佩戴防毒面具。紧急事态抢救或撤离时，佩带自给式呼吸器。', '必要时戴安全防护眼镜。', '穿工作服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:45:46', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5166, 5346, NULL, '0.001', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。', NULL, '戴化学安全防护眼镜。', '穿相应的防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:45:47', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5167, 5347, NULL, '1', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。提供安全淋浴和洗眼设备。', '空气中粉尘浓度超标时，必须佩戴自吸过滤式防尘口罩（半面罩）或空气呼吸器。紧急事态抢救或撤离时，建议佩戴空气呼吸器。', '戴化学安全防护眼镜。', '穿透气型防毒服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:45:47', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5168, 5348, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风和全面通风。', '空气中浓度超标时，佩戴过滤式防毒面具(半面罩)或导管式防毒面具。紧急事态抢救或撤离时，建议佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿胶布防毒衣。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:45:47', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5169, 5349, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。提供安全淋浴和洗眼设备。', '空气中粉尘浓度超标时，必须佩戴自吸过滤式防尘口罩（半面罩）或全面罩。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:45:47', '', NULL);
