INSERT INTO `msds_exposure_control` VALUES (5199, 5379, NULL, '1[皮]', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。', '空气中浓度超标时，佩带防毒面具。紧急事态抢救或逃生时，应该佩带自给式呼吸器。', '戴化学安全防护眼镜。', '穿紧袖工作服，长统胶鞋。', '戴橡皮手套。', NULL, NULL, NULL, '2026-03-06 14:45:58', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5200, 5380, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风和全面通风。', NULL, '戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:45:58', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5201, 5381, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟EN374、美国USF739或AS/NZS', NULL, NULL, NULL, '2026-03-06 14:45:58', '', NULL);
