INSERT INTO `msds_exposure_control` VALUES (5236, 5416, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风和全面通风。', '空气中粉尘浓度超标时，必须佩戴自吸过滤式防尘口罩（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '佩戴化学安全防护眼镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:46:11', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5237, 5417, NULL, '1mg/m³[皮]', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。尽可能机械化、自动化。提供安全淋浴和洗眼设备。', '空气中浓度超标时，必须佩戴自吸过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '佩戴化学安全防护眼镜（符合欧盟EN 166或美国NIOSH标准）。', '穿防静电工作服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:46:12', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5238, 5418, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '佩戴化学护目镜（符合欧盟EN166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', NULL, NULL, NULL, NULL, '2026-03-06 14:46:12', '', NULL);
