INSERT INTO `msds_exposure_control` VALUES (5308, 5488, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风和全面排风。', '可能接触其蒸气时，必须佩戴防毒面具。', '戴化学安全防护眼镜。', '穿聚乙烯薄膜防毒服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:46:42', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5309, 5489, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。', '可能接触其蒸气时，应戴口罩。', '一般不需要特殊防护，高浓度接触时可戴安全防护眼镜。', '穿防静电工作服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:46:43', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5310, 5490, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。', '可能接触其粉尘时，佩戴防尘口罩。空气中浓度较高时，应该佩戴防毒面具。', '戴化学安全防护眼镜。', '穿防腐工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:46:43', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5311, 5491, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。', '可能接触其蒸气或烟雾时，应戴口罩。紧急事态抢救或逃生时，应该佩戴防毒面具。', '戴化学安全防护眼镜。', '穿防腐工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:46:45', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5312, 5492, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，全面排风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，佩戴自吸过滤式防毒面具（半面罩）。', '戴安全防护眼镜。', '穿防静电工作服。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:46:45', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5313, 5493, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。', '应该佩戴防毒口罩。紧急事态抢救或逃生时，佩戴防毒面具。', '戴化学安全防护眼镜。', '穿工作服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:46:45', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5314, 5494, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '可能接触其蒸气时，佩戴防毒口罩。紧急事态抢救或逃生时，应该佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿相应的防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:46:45', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5315, 5495, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。提供安全淋浴和洗眼设备。', '空气中粉尘浓度超标时，必须佩戴自吸过滤式防尘口罩（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟 EN 166 或美国 NIOSH 标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴化学防护手套（例如丁基橡胶手套）。建议选择经过欧盟 EN374、美国 USF739 或 AS/NZS 2161标准认证的产品。', NULL, NULL, NULL, '2026-03-06 14:46:45', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5316, 5496, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，注意通风。尽可能机械化、自动化。提供安全淋浴和洗眼设备。', '空气中浓度超标时，必须佩戴自吸过滤式防毒面具（全面罩）或隔离式呼吸器。紧急事态抢救或撤离时，建议佩戴空气呼吸器。', '呼吸系统防护中已作防护。', '穿橡胶耐酸碱服。', '戴橡胶耐酸碱手套。', NULL, NULL, NULL, '2026-03-06 14:46:47', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5317, 5497, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，佩戴自吸过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，建议佩戴空气呼吸器或氧气呼吸器。', '戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:46:47', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5318, 5498, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，必须佩戴自吸过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '佩戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:46:48', '', NULL);
