INSERT INTO `msds_exposure_control` VALUES (5322, 5502, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '空气中浓度较高时，应该佩带防毒面具。紧急事态抢救或逃生时，建议佩带自给式呼吸器。', '戴化学安全防护眼镜。', '穿工作服（防腐材料制作）。', '戴橡皮手套。', NULL, NULL, NULL, '2026-03-06 14:46:48', '', NULL);
