INSERT INTO `msds_exposure_control` VALUES (5326, 5506, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '作业工人应该佩戴导管式防毒面具。必要时，佩戴空气呼吸器、氧气呼吸器或长管面具。', '呼吸系统防护中已作防护。', '穿聚乙烯防毒服。', '戴氯丁橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:46:52', '', NULL);
