INSERT INTO `msds_exposure_control` VALUES (5343, 5523, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风和全面通风。', '空气中浓度超标时，应该佩戴自吸过滤式防毒面具（半面罩）或隔离式呼吸器。紧急事态抢救或逃生时，建议佩戴空气呼吸器。', '戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:46:58', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5344, 5524, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。尽可能机械化、自动化。提供安全淋浴和洗眼设备。', '空气中浓度超标时，应该佩戴自吸过滤式防毒面具（全面罩）或隔离式呼吸器。紧急事态抢救或逃生时，建议佩戴空气呼吸器。', '戴化学安全防护眼镜。', '穿连衣式胶布防毒衣。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:46:59', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5345, 5525, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '可能接触其蒸气时，佩戴防毒口罩。紧急事态抢救或逃生时，应该佩戴自给式呼吸器。', '戴安全防护眼镜。', '穿紧袖工作服，长筒胶鞋。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:46:59', '', NULL);
