INSERT INTO `msds_exposure_control` VALUES (5348, 5528, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，应该佩戴自吸过滤式防毒面具（半面罩）或隔离式呼吸器。紧急事态抢救或撤离时，建议佩戴空气呼吸器。', '一般不需要特殊防护，高浓度接触时可戴安全防护眼镜。', '穿防毒物渗透工作服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:47:01', '', NULL);
