INSERT INTO `msds_exposure_control` VALUES (5514, 5694, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', NULL, NULL, NULL, NULL, '2026-03-06 14:48:11', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5515, 5695, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。尽可能机械化、自动化。', '空气中浓度较高时，应该佩戴防毒口罩。必要时建议佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿相应的防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:48:11', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5516, 5696, NULL, '0.05', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '作业工人应该佩带防尘口罩。必要时佩带防毒面具。', '必要时戴安全防护眼镜。', '穿相应的防护服。', '戴防护手套。', NULL, NULL, NULL, '2026-03-06 14:48:11', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5517, 5697, NULL, '未制订标准.', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。', '空气中浓度超标时，必须佩戴自吸过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器或氧气呼吸器。', '戴化学安全防护眼镜。', '穿防静电工作服。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:48:13', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5518, 5698, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。尽可能机械化、自动化。提供安全淋浴和洗眼设备。', '空气中浓度超标时，必须佩戴过滤式防毒面具（半面罩）或自给式呼吸器。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴防化学品手套（丁基橡胶、聚乙烯醇等材质）。', NULL, NULL, NULL, '2026-03-06 14:48:13', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5519, 5699, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。尽可能机械化、自动化。提供安全淋浴和洗眼设备。', '空气中浓度超标时，佩戴过滤式防毒面具（半面罩）或自给式呼吸器。紧急事态抢救或撤离时，建议佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴耐化学品的橡胶手套或丁腈手套。', NULL, NULL, NULL, '2026-03-06 14:48:13', '', NULL);
