INSERT INTO `msds_exposure_control` VALUES (5663, 5844, NULL, '未制订标准', NULL, NULL, NULL, NULL, NULL, NULL, '提供良好的自然通风条件。', '一般不需要特殊防护，高浓度接触时可佩带防毒面具。', '防护要求不高。', '穿工作服。', '防护要求不高。', NULL, NULL, NULL, '2026-03-06 14:49:24', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5664, 5845, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '空气中浓度超标时，必须佩戴防毒面具。紧急事态抢救或撤离时，建议佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿工作服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:49:25', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5665, 5846, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。', '可能接触其蒸气时，应该佩带防毒面具。紧急事态抢救或逃生时，建议佩带自给式呼吸器。', '戴化学安全防护眼镜。', '穿相应的防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:49:26', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5666, 5847, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，全面通风。提供安全淋浴和洗眼设备。', '一般不需要特殊防护，高浓度接触时可佩戴自吸过滤式防毒面具（半面罩）。', '必要时，戴安全防护眼镜。', '穿防静电工作服。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:49:27', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5667, 5848, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风。尽可能机械化、自动化。提供安全淋浴和洗眼设备。', '可能接触其蒸气时，应该佩戴自吸过滤式防毒面具（全面罩）。紧急事态抢救或逃生时，建议佩戴自给式呼吸器。', '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:49:27', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5668, 5849, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。提供安全淋浴和洗眼设备。', '空气中浓度超标时，佩戴自吸过滤式防毒面具（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '呼吸系统防护中已作防护。', '穿胶布防毒衣。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:49:27', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5669, 5850, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。', '空气中浓度超标时，必须佩戴过滤式防毒面具(半面罩)。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴橡胶耐油手套。', NULL, NULL, NULL, '2026-03-06 14:49:28', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5670, 5851, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风。提供安全淋浴和洗眼设备。', '空气中粉尘浓度超标时，必须佩戴过滤式防尘呼吸器。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴防化学品手套（如丁基橡胶手套）。', NULL, NULL, NULL, '2026-03-06 14:49:28', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5671, 5852, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风和全面通风。', '空气中粉尘浓度超标时，佩戴自吸过滤式防尘口罩（半面罩）。紧急事态抢救或撤离时，应该佩戴空气呼吸器。', '佩戴化学安全防护眼镜。', '穿防毒物渗透工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:49:28', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5672, 5853, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，提供充分的局部排风和全面通风。使用防爆型通风系统和设备。提供安全淋浴和洗眼设备。', '空气中浓度超标时，佩戴过滤式防毒面具（半面罩）或自给式呼吸器。紧急事态抢救或撤离时，建议佩戴空气呼吸器。', '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', '戴防化学品手套（丁基橡胶或聚乙烯醇材质）。', NULL, NULL, NULL, '2026-03-06 14:49:28', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5673, 5854, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '可能接触毒物时，应该佩戴防毒口罩。', '戴化学安全防护眼镜。', '穿防静电工作服。', '必要时戴橡皮手套。', NULL, NULL, NULL, '2026-03-06 14:49:30', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5674, 5855, NULL, '未制定标准', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风和全面通风。提供安全淋浴和洗眼设备。', '建议操作人员佩戴自吸过滤式防毒面具（全面罩）', '呼吸系统防护中已作防护。', '穿防静电工作服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:49:30', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5675, 5856, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '严加密闭，提供充分的局部排风和全面排风。尽可能机械化、自动化。', '可能接触其蒸气时，应该佩戴防毒面具。紧急事态抢救或撤离时，建议佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿防静电工作服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:49:30', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5676, 5857, NULL, '0.05[CrO3]', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。提供安全淋浴和洗眼设备。', NULL, '呼吸系统防护中已作防护。', '穿聚乙烯防毒服。', '戴橡胶手套。', NULL, NULL, NULL, '2026-03-06 14:49:31', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5677, 5858, NULL, '0.05mg(Cr2O3)／m3', NULL, NULL, NULL, NULL, NULL, NULL, '密闭操作，局部排风。', '作业工人必须佩戴防毒口罩。紧急事态抢救或逃生时，佩戴自给式呼吸器。', '戴安全防护眼镜。', '穿化学防护服。', '戴防化学品手套。', NULL, NULL, NULL, '2026-03-06 14:49:31', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5678, 5859, NULL, '0.05[CrO3]', NULL, NULL, NULL, NULL, NULL, NULL, '生产过程密闭，加强通风。提供安全淋浴和洗眼设备。', '可能接触其粉尘时，必须佩戴头罩型电动送风过滤式防尘呼吸器。紧急事态抢救或撤离时，建议佩戴自给式呼吸器。', '戴化学安全防护眼镜。', '穿聚乙烯防毒服。', '戴橡胶耐酸碱手套。', NULL, NULL, NULL, '2026-03-06 14:49:32', '', NULL);
INSERT INTO `msds_exposure_control` VALUES (5679, 5860, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '佩戴化学护目镜（符合欧盟EN 166或美国NIOSH标准）。', '穿阻燃防静电防护服和抗静电的防护靴。', NULL, NULL, NULL, NULL, '2026-03-06 14:49:32', '', NULL);
