INSERT INTO `msds_fire_fighting` VALUES (2887, 3021, '不易燃烧。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氯化氢、氧化硫。', '泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2888, 3022, '遇明火、高热可燃。与氧化剂能发生强烈反应。受热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、氧化硫、氰化物。', '泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2889, 3023, '遇明火、高热可燃。', '一氧化碳、二氧化碳、氯化氢。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：干粉、泡沫、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2890, 3024, '不易燃烧。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氯化氢。', '泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2891, 3025, '安全阀泄漏出内容物。受热或接触火焰可能会产生膨胀或爆炸性分解。', '氯化氢、氮氧化物、一氧化碳、二氧化碳等有毒气体。', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2892, 3026, '遇明火、高热可燃。受热分解，放出氮、磷的氧化物等毒性气体。', '一氧化碳、二氧化碳、氧化氮、氧化磷。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2893, 3027, '遇明火、高热可燃。受高熟分解，放出高毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、氯化氢、氰化物。', '泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2894, 3028, '遇明火、高热可燃。与强氧化剂、水、强碱接触可发生反应。受热分解产生一氧化碳、氧化硫、氯化氢、氧化磷等有毒的腐蚀性气体。有腐蚀性。', '一氧化碳、氧化硫、氯化氢、氧化磷。', '泡沫、二氧化碳、砂土、干粉。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2895, 3029, '本品为有机过氧化物D型，具有高度不稳定性。受热、接触火焰、摩擦、震动或撞击时可能发生爆炸性分解。在封闭空间内分解可能导致压力骤增和爆炸。与还原剂、促进剂、强酸、强碱、金属粉末等接触可能发生剧烈反应。燃烧时可能产生大量热量和有毒气体。', '一氧化碳、二氧化碳、醛类、酮类、有机酸、过氧化物分解产物等有毒有害气体。燃烧可能产生刺激性烟雾和有毒蒸气。', '合适的灭火介质：大量水喷雾、泡沫、干粉（ABC型）、二氧化碳。不合适的灭火介质：避免使用直流水冲击，以免造成火势蔓延。禁止使用强酸、强碱类灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2896, 3030, '有机过氧化物（D型），受热、接触火焰或受到摩擦、震动、撞击时可能发生爆炸性分解。与还原剂、促进剂、强酸、强碱等接触可能发生剧烈反应。燃烧时可能产生爆炸性分解，释放大量热量和有毒气体。容器受热可能发生爆炸。', '一氧化碳、二氧化碳、有机过氧化物分解产物、有毒烟雾', '使用大量水冷却容器，避免直接喷射到泄漏物上。可使用干粉、二氧化碳、泡沫灭火剂。禁止使用强水流直接冲击泄漏物，可能导致扩散', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2897, 3031, '受热或火灾条件下容器内压急剧升高并有爆裂危险。气体比空气重，可在低洼处积聚并沿地面扩散，遇火源会回燃。分解产生剧毒的氟化物气体。', '一氧化碳、二氧化碳、氟化氢。 切断气源。若不能切断气源，则不允许熄灭泄漏处的火焰。喷水冷却容器，可能的话将容器从', '火场移至空旷处。灭火剂：雾状水、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2898, 3032, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氯化氢。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷 处。灭火剂：抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2899, 3033, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。粉体与空气可形成爆炸性混合物，当达到 一定的浓度时，遇火星会发生爆炸。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2900, 3034, '接触火焰可能会产生膨胀或爆炸性分解。', '无资料 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:32', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2901, 3035, '稳定，但在光照下可能缓慢分解。受高热分解产生有毒的腐蚀性烟气。', '一氧化碳、二氧化碳、氯化氢。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:32', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2902, 3036, '稳定，但在高温或与活性金属接触时可发生反应，引起分解。', '一氧化碳、二氧化碳、氯化氢、氟化氢。', '不燃。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:32', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2903, 3037, '有毒的具有腐蚀性的易燃蒸气。易燃性(红色)：2反应活性(黄色)：0', '一氧化碳、二氧化碳、硫氧化物等有害燃烧产物。蒸气最初比空气重，易在低处聚集。封闭区域内的蒸气遇火能爆炸。如果该物质或被污染的流体进入水路，通知有潜在水体污染的下游用户，通知地方卫生、消防官员和污染控制部门。', '使用干粉、抗醇泡沫、二氧化碳灭火。在安全防爆距离以外，使用雾状水冷却暴露的容器。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:32', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2904, 3038, '接触火焰可能会产生膨胀 或爆炸性分解。', '无资料', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2905, 3039, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '无资料', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2906, 3040, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氯化氢。', '抗溶性泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2907, 3041, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。若遇高热，容器内压增大，有开裂和爆炸 的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2908, 3042, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。其蒸气比空气重，能在较低处扩散到相当 远的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2909, 3043, '接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、有机过氧化物分解产物等。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2910, 3044, '接触火焰可能会产生膨胀或爆炸性分解。', '燃烧时产生一氧化碳、二氧化碳、有机过氧化物分解产物等有害气体。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:36', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2911, 3045, '受热、摩擦、震动、撞击时可能发生爆炸性分解反应。遇明火、高热、氧化剂有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:36', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2912, 3046, '聚合反应，放出大量热量而引起容器破裂和爆炸事故。气体比空气重，能在较低处扩散到相当远 的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳、氟化氢。 切断气源。若不能切断气源，则不允许熄灭泄漏处的火焰。喷水冷却容器，可能的话将容器', '从火场移至空旷处。灭火剂：雾状水、普通泡沫、干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:37', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2913, 3047, '烈反应, 引起燃烧或爆炸。在火场中，受热的容器有爆炸危险。其蒸气比空气重，能在较 低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。处在火场中的容器若已变色或从安全', '泄压装置中产生声音，必须马上撤离。灭火剂：泡沫、二氧化碳、干粉、砂土。用水灭火 无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:37', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2914, 3048, '其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂接触发生剧烈反应。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。在火场中，受热的容器有爆炸危险。', '无资料 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2915, 3049, '其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂及铝反应剧烈。受热分解产生一氧化碳、二氧化碳、氧化氮等有毒的气体。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。在火场中，受热的容器有爆炸危险。', '一氧化碳、二氧化碳、氮氧化物(NOx)。', '灭火剂：抗溶性泡沫、二氧化碳、干粉、砂土。禁止用水直接喷射。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2916, 3050, '接触空气或在光照条件下可生成具有潜在爆炸危险性的过氧化物。其蒸气比空气重，能在较低 处扩散到相当远的地方，遇火源引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '抗溶性泡沫、泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2917, 3051, '遇明火、高热可燃。与强氧化剂可发生反应。受高热分解产生有毒的腐蚀性气体。', '一氧化碳、氧化氮、氯化氢。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2918, 3052, '遇明火、高热可燃。受高热分解产生有毒的腐蚀性烟气。', '一氧化碳、二氧化碳、氯化氢。', '雾状水、泡沫、干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:39', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2919, 3053, '可与空气形成爆炸性混合物。暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从 而增加火势和/或蒸气的浓度。蒸气可能会移动到着火源并回闪。液体和蒸气易燃。燃烧时 可能会释放毒性烟雾。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性 分解。', '一氧化碳、二氧化碳、氯化氢、光气等有毒气体', '水雾或抗溶泡沫灭火剂。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使 火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:39', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2920, 3054, '稳定，但在高温下可能分解。与氧化剂能发生强烈反应。受热分解产生一氧化碳、二氧化碳、氯化氢、光气等有毒的腐蚀性烟气。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳、氯化氢、光气。', '灭火剂：泡沫、干粉、二氧化碳、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:39', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2921, 3055, '遇明火、高热极度易燃。与氧化剂接触发生剧烈反应。受热分解产生一氧化碳、二氧化碳、氯化氢、光气等有毒的腐蚀性烟气。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。本品能发生聚合反应，需添加阻聚剂防止聚合。', '一氧化碳、二氧化碳、氯化氢、光气。 尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的', '容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：雾状水、泡沫、干 粉、二氧化碳、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:39', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2922, 3056, '蔓延(即使部分用水润湿)。可能会剧烈燃烧。任何点火源，即摩擦、受热、火花或火焰都可 能引起火灾和爆炸。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳、耐醇泡沫或水喷雾。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2923, 3057, '不易燃烧。受高热分解，放出腐蚀性、刺激性的烟雾。', '氯化氢、一氧化碳、二氧化碳。', '砂土、泡沫、雾状水、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2924, 3058, '遇明火、高热可燃。', '一氧化碳、二氧化碳、氯化氢。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2925, 3059, '建规火险分级：', '喷水或使用干粉、二氧化碳、泡沫灭火剂；用水冷却火中容器，以防爆炸；穿戴防护服；', '转移容器', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2926, 3060, '遇明火、高热可燃。与强氧化剂接触可发生化学反应。受高热分解产生有毒的腐蚀性烟气。', '一氧化碳、二氧化碳、氯化氢、光气。', '采用泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2927, 3061, '遇明火、高热可燃。受高热分解产生有毒的腐蚀性气体。', '一氧化碳、二氧化碳、氯化氢。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2928, 3062, '遇明火能燃烧。受高热分解产生有毒的腐蚀性烟气。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、氯化氢。', '采用泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2929, 3063, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。若遇高热，容器内压增大，有开裂和 爆炸的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2930, 3064, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：泡沫、二氧化碳、干粉、砂', '土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2931, 3065, '稳定，但在高温或光照下可能缓慢分解。气能水解生成微量的氯化氢，光照亦能促进水解而对金属的腐蚀性增强。遇明火、高热可燃。', '一氧化碳、二氧化碳、氯化氢。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:43', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2932, 3066, '遇明火、高热可燃。与强氧化剂可发生反应。受高热分解产生有毒的腐蚀性气体。', '一氧化碳、二氧化碳、氯化氧。', '雾状水、泡沫、二氧化碳、砂土、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:43', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2933, 3067, '体。', '一氧化碳、二氧化碳、氯化氢。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:43', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2934, 3068, '当达到一定的浓度时，遇火星会发生爆炸。', '一氧化碳、二氧化碳。', '雾状水、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:43', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2935, 3069, '可燃。遇明火能燃烧。受高热分解产生有毒的氯化物气体。与强氧化剂接触可发生化学应。', '一氧化碳、二氧化碳、氯化氢。', '采用泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:44', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2936, 3070, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。与氧化剂能发生强烈反应。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：泡沫、二氧化碳、干粉、砂', '土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:44', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2937, 3071, '遇明火能燃烧。在空气中受热分解释出剧毒的光气和氯化氢气体。与氧化剂接触猛烈反应。', '一氧化碳、二氧化碳、氯化氢。', '采用雾状水、泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:44', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2938, 3072, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2939, 3073, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氯化氢。', '雾状水、抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2940, 3074, '遇明火、高热可燃。受热分解放出有毒的氧化氮烟气。', '一氧化碳、二氧化碳、氧化氮。', '采用雾状水、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2941, 3075, '遇明火、高热可燃。受高热分解放出有毒的气体。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳。', '采用雾状水、抗溶性泡沫、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2942, 3076, '气。能腐蚀铜及其合金。', '一氧化碳、二氧化碳、氧化氮。 用水喷射逸出液体，使其稀释成不燃性混合物，并用雾状水保护消防人员。灭火剂：水、抗溶', '性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:46', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2943, 3077, '遇明火、高热可燃。受热分解放出有毒的氧化氮烟气。与强氧化剂接触可发生化学反应。粉末与空气可形成爆炸性混合物，当达到一定浓度时，遇火星会发生爆炸。', '一氧化碳、二氧化碳、氧化氮。', '采用雾状水、泡沫、二氧化碳、干粉、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:46', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2944, 3078, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳。', '水、抗溶性泡沫、干粉、雾状水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:46', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2945, 3079, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与强氧化剂发生反应，可引起燃烧。受高热分解放出有毒的氟化氢气体。', '一氧化碳、二氧化碳、氟化氢。 喷水冷却容器，可能的话将容器从火场移至空旷处。处在火场中的容器若已变色或从安全', '泄压装置中产生声音，必须马上撤离。灭火剂：泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2946, 3080, '发生强烈反应。流速过快，容易产生和积聚静电。其蒸气比空气重，能在较低处扩散到 相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '喷水冷却容器，将容器从火场移至空旷处。灭火剂：泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2947, 3081, '会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、1211灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2948, 3082, '易燃，其蒸气与空气可形成爆炸性混合物，遇热源和明火有燃烧爆炸的危险。在火场中，受 热的容器有爆炸危险。与氧化剂能发生强烈反应, 引起燃烧或爆炸。其蒸气比空气重，能在 较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '喷水冷却容器，可能的话将容器从火场移至空旷处。处在火场中的容器若已变色或从安全泄压装 置中产生声音，必须马上撤离。灭火剂：泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2949, 3083, '下可生成具有潜在爆炸危险性的过氧化物。其蒸气比空气重，能在较低处扩散到相当远的 地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的', '容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：抗溶性泡沫、干粉、 二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:48', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2950, 3084, '其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与强氧化剂、铝接触可发生反应，放出热和近似白色烟雾状有刺激性和腐蚀性的氯化氢气体。受高热分解放出有毒的气体（氯化氢、一氧化碳、二氧化碳等）。在火场中，受热的容器有爆炸危险。', '一氧化碳、二氧化碳、氯化氢。', '采用雾状水、泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:48', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2951, 3085, '稳定，但在高温或光照下可能缓慢分解。与氧化剂接触发生反应，受高热分解产生有毒的腐蚀性气体。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氯化氢、光气。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:48', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2952, 3086, '分解释出剧毒的光气和氯化氢气体。与氧化剂能发生强烈反应。与铜及其合金有可能生成 具有爆炸性的氯乙炔。', '一氧化碳、二氧化碳、氯化氢。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：泡沫、二氧化碳、干粉、砂', '土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2953, 3087, '可能会释放毒性烟雾。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性 分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2954, 3088, '具有爆炸性的氯乙炔。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火 回燃。', '一氧化碳、二氧化碳、氯化氢、光气。 尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的', '容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：雾状水、泡沫、干 粉、二氧化碳、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2955, 3089, '遇明火、高热易燃。与强氧化剂、强还原剂、强碱接触可发生剧烈反应或爆炸。受高热分解产生有毒的氧化氮气体。', '一氧化碳、二氧化碳、氧化氮。 消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：水、泡沫、二氧化碳、', '砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2956, 3090, '遇明火、高热可燃。受高热分解产生有毒的溴化物气体。', '一氧化碳、二氧化碳、溴化氢。', '雾状水、二氧化碳、泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:50', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2957, 3091, '遇明火、高热可燃。与强氧化剂发生反应，可引起燃烧。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、溴化氢。', '雾状水、抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:50', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2958, 3092, '受高热分解产生有毒的溴化物气体。', '一氧化碳、二氧化碳、溴化氢。 消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：泡沫、干粉、二氧化', '碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2959, 3093, '受高热分解产生有毒的溴化物气体。与强氧化剂接触可发生化学反应。', '溴化氢。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2960, 3094, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：泡沫、二氧化碳、干粉、砂', '土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2961, 3095, '建规火险分级：', '灭火方法： 喷水或使用干粉、二氧化碳、抗醇泡沫灭火剂；用水冷却火中容器，以免爆炸', '喷水或使用干粉、二氧化碳、抗醇泡沫灭火剂；用水冷却火中容器，以免爆炸', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2962, 3096, '铝的过氧化物以及碱金属氢氧化物等催化剂的活性表面接触能聚合放热，使容器爆破。遇 氨水、氯磺酸、盐酸、氟化氢、硝酸、硫酸、发烟硫酸猛烈反应，有爆炸危险。', '一氧化碳、二氧化碳。 尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的', '容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：抗溶性泡沫、二氧 化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2963, 3097, '爆炸的危险。与氧化剂能发生强烈反应。在空气中久置后能生成有爆炸性的过氧化物。 其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 尽可能将容器从火场移至空旷处。处在火场中的容器若已变色或从安全泄压装置中产生声', '音，必须马上撤离。灭火剂：抗溶性泡沫、1211灭火剂、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:52', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2964, 3098, '遇明火、高热可燃。受热分解，放出氮、硫的氧化物等毒性气体。', '一氧化碳、二氧化碳、氮氧化物、硫化物。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：抗溶性泡沫、干粉、 砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:52', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2965, 3099, '遇明火、高热可燃。受热分解，放出氮、硫的氧化物等毒性气体。', '一氧化碳、二氧化碳、氮氧化物、硫化物、氧化钠。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：抗溶性泡沫、干粉、 砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:52', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2966, 3100, '易燃，与强氧化剂、强酸、酰基氯、酸酐等剧烈反应。能腐蚀铜及其合金。', '一氧化碳、二氧化碳、氧化氮。', '用水喷射逸出液体，使其稀释成不燃性混合物，并用雾状水保护消防人员。灭火剂：水、抗溶性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2967, 3101, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：泡沫、干粉、二氧化碳、砂', '土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2968, 3102, '不易燃烧。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氯化氢。', '泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2969, 3103, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。处在火场中的容器若已变色或从安全', '泄压装置中产生声音，必须马上撤离。灭火剂：泡沫、干粉、二氧化碳、砂土。用水灭火 无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2970, 3104, '应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。遇高热能发 生聚合反应，出现大量放热现象，引起容器破裂或爆炸事故。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2971, 3105, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。若遇高热，容器内压增大，有开裂和爆炸 的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:54', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2972, 3106, '遇明火能燃烧。在空气中受热分解释出剧毒的光气和氯化氢气体。与氧化剂接触猛烈反应。', '一氧化碳、二氧化碳、氯化氢。', '采用雾状水、泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:54', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2973, 3107, '遇明火、高热可燃。受热分解放出有毒的氧化氮烟气。', '一氧化碳、二氧化碳、氧化氮。', '采用雾状水、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:54', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2974, 3108, '遇明火、高热可燃。受高热分解放出有毒的气体。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳。', '采用雾状水、抗溶性泡沫、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:54', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2975, 3109, '建规火险分级：', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2976, 3110, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2977, 3111, '可发生聚合反应，放出大量热量而引起容器破裂和爆炸事故。气体比空气重，能在较低处扩散到 相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 切断气源。若不能切断气源，则不允许熄灭泄漏处的火焰。喷水冷却容器，可能的话将容器从火', '场移至空旷处。灭火剂：雾状水、泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2978, 3112, '燃烧时可能会释放毒性烟雾。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或 爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:56', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2979, 3113, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与强氧化剂发生反应，可引起燃烧。受高热分解放出有毒的氟化氢气体。', '一氧化碳、二氧化碳、氟化氢。 喷水冷却容器，可能的话将容器从火场移至空旷处。处在火场中的容器若已变色或从安全', '泄压装置中产生声音，必须马上撤离。灭火剂：泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:56', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2980, 3114, '爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:56', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2981, 3115, '遇明火、高温能引起分解爆炸和燃烧。遇酸和碱，有分解的危险。', '一氧化碳、二氧化碳、氮氧化物。', '二氧化碳、泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:56', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2982, 3116, '易燃液体，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂能发生强烈反应。流速过快，容易产生和积聚静电。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2983, 3117, '能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳、氮氧化物。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：抗溶性泡沫、二氧化碳、干', '粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2984, 3118, '氧化剂可发生反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。 若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、1211灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:58', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2985, 3119, '可与空气形成爆炸性混合物。暴露于火中的容器可能会通过压力安全阀泄漏出内容物，从 而增加火势和/或蒸气的浓度。蒸气可能会移动到着火源并回闪。液体和蒸气易燃。加热时， 容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:58', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2986, 3120, '其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压 增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:59', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2987, 3121, '高热，容器内压增大；有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氯化氢、光气。', '雾状水、泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:59', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2988, 3122, '若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氯化氢。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2989, 3123, '遇明火能燃烧。受高热分解放出有毒的气体。遇氧化剂及铝反应剧烈。', '一氧化碳、二氧化碳、氯化氢。', '采用雾状水、泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:01', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2990, 3124, '遇明火能燃烧。受热易分解，燃烧时产生有毒的氯化物气体。与氧化剂接触猛烈反应。', '一氧化碳、二氧化碳、氯化物。 消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：抗溶性泡沫、二氧化', '碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2991, 3125, '稳定，但在高温下可能分解。遇明火、高热易燃。受热分解能放出剧毒的光气。与氧化剂能发生强烈反应。受热分解产生一氧化碳、二氧化碳、氯化氢、光气等有毒的腐蚀性气体。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氯化氢、光气', '泡沫、二氧化碳、干粉、砂土。喷水冷却容器，可能的话将容器从火场移至空旷处。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2992, 3126, '遇明火、高热易燃。与氧化剂接触发生反应。受热分解产生有毒的腐蚀性气体。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳、氯化氢、光气。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：泡沫、二氧化碳、干粉、砂土。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2993, 3127, '遇明火、高热易燃。与强氧化剂、强还原剂、强碱接触可发生剧烈反应或爆炸。受高热分解产生有毒的氧化氮气体。', '一氧化碳、二氧化碳、氧化氮。 消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：水、泡沫、二氧化碳、', '砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2994, 3128, '胺类及三氯化铝、六甲基苯等均能引起燃烧爆炸。燃烧分解时,放出有毒的氮氧化物气体。', '一氧化碳、二氧化碳、氧化氮。 尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火剂：雾状', '水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2995, 3129, '生强烈反应。接触空气或在光照条件下可生成具有潜在爆炸危险性的过氧化物。其蒸气比 空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 尽可能将容器从火场移至空旷处。处在火场中的容器若已变色或从安全泄压装置中产生声', '音，必须马上撤离。灭火剂：抗溶性泡沫、1211灭火剂、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2996, 3130, '易燃，遇明火、高热能引起燃烧爆炸。与强氧化剂发生反应,可引起燃烧。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：泡沫、二氧化碳、干粉、砂', '土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2997, 3131, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳、氮氧化物、氧化硫。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2998, 3132, '生强烈反应。高速冲击、流动、激荡后可因产生静电火花放电引起燃烧爆炸。其蒸气比空 气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。处在火场中的容器若已变色或从安全', '泄压装置中产生声音，必须马上撤离。灭火剂：泡沫、干粉、二氧化碳、砂土。用水灭火 无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (2999, 3133, '产生静电火花放电引起燃烧爆炸。其蒸气比空气重，能在较低处扩散到相当远的地方，遇 火源会着火回燃。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。处在火场中的容器若已变色或从安全', '泄压装置中产生声音，必须马上撤离。灭火剂：泡沫、干粉、二氧化碳、砂土。用水灭火 无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3000, 3134, '容器可能爆炸。暴露于火中的容器可能会通过压力安全阀泄漏出内容物。受热或接触火焰 可能会产生膨胀或爆炸性分解。', '无资料 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3001, 3135, '其蒸气与空气形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。 其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。遇高热能发生聚 合反应，出现大量放热现象，引起容器破裂或爆炸事故。', '一氧化碳、二氧化碳。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷 处。灭火剂：抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3002, 3136, '可发生聚合反应，放出大量热量而引起容器破裂和爆炸事故。气体比空气重，能在较低处扩散到 相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 切断气源。若不能切断气源，则不允许熄灭泄漏处的火焰。喷水冷却容器，可能的话将容器从火', '场移至空旷处。灭火剂：雾状水、泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3003, 3137, '遇明火、高热可燃。与强氧化剂可发生反应。受高热分解产生有毒的腐蚀性气体。', '一氧化碳、二氧化碳，氯化氢。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3004, 3138, '遇明火、高热可燃。与强氧化剂可发生反应。受热分解放出有毒的氧化氮烟气。', '一氧化碳、二氧化碳、氧化氮。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3005, 3139, '遇明火、高热可燃。与强氧化剂接触可发生化学反应。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳。', '采用雾状水、抗溶性泡沫、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3006, 3140, '遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。具有腐蚀性。', '一氧化碳、二氧化碳、氧化氮。', '采用抗溶性泡沫、二氧化碳、干粉、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3007, 3141, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与强氧化剂发生反应，可引起燃烧。受高热分解放出有毒的氟化氢气体。', '一氧化碳、二氧化碳、氟化氢。喷水冷却容器，可能的话将容器从火场移至空旷处。处在火场中的容器若已变色或从安全泄压装置中产生声音，必须马上撤离。', '灭火剂：泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3008, 3142, '生强烈反应。流速过快，容易产生和积聚静电。其蒸气比空气重，能在较低处扩散到相当 远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：泡沫、二氧化碳、干粉、砂', '土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:07', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3009, 3143, '氧化剂能发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回 燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、1211灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:07', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3010, 3144, '有开裂和爆炸的危险。有腐蚀性。', '一氧化碳、二氧化碳、氮氧化物。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:07', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3011, 3145, '受高热分解产生有毒的腐蚀性气体。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氯化氢。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:07', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3012, 3146, '其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与强氧化剂、铝接触可发生反应，引起分解。受高热分解产生有毒的腐蚀性烟气。在火场中，受热的容器有爆炸危险。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳、氯化氢、光气等有毒气体。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:08', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3013, 3147, '稳定，但在高温下可能分解。遇明火、高热易燃。受热分解能放出剧毒的光气。与氧化剂能发生强烈反应。受热分解产生一氧化碳、二氧化碳、氯化氢、光气等有毒的腐蚀性气体。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氯化氢、光气。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:08', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3014, 3148, '强酸、碱土金属、氢氧化物及卤化物等污染后，有可能发生爆炸。', '一氧化碳、二氧化碳。', '采用水、抗溶性泡沫、二氧化碳、干粉、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:08', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3015, 3149, '或爆炸。', '一氧化碳、二氧化碳、氧化氮。 消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：水、泡沫、二氧化碳、', '砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3016, 3150, '易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆 炸的危险。与氧化剂能发生强烈反应。接触空气或在光照条件下可生成具有潜在爆炸危险 性的过氧化物。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳', '抗溶性泡沫、1211灭火剂、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3017, 3151, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：泡沫、二氧化碳、干粉、砂', '土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3018, 3152, '产生静电火花放电引起燃烧爆炸。其蒸气比空气重，能在较低处扩散到相当远的地方，遇 火源会着火回燃。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。处在火场中的容器若已变色或从安全', '泄压装置中产生声音，必须马上撤离。灭火剂：泡沫、干粉、二氧化碳、砂土。用水灭火 无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3019, 3153, '应, 引起燃烧或爆炸。若遇高热，可发生聚合反应，放出大量热量而引起容器破裂和爆炸 事故。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的', '容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：泡沫、二氧化碳、 干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:10', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3020, 3154, '其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。受热可能发生剧烈的聚合反 应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 切断气源。若不能切断气源，则不允许熄灭泄漏处的火焰。喷水冷却容器，可能的话将容器从火', '场移至空旷处。灭火剂：雾状水、泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:10', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3021, 3155, '稳定，但在高温下可能分解。遇明火、高热易燃。受热分解能放出剧毒的光气。与氧化剂能发生强烈反应。受热分解产生一氧化碳、二氧化碳、氯化氢、光气等有毒的腐蚀性气体。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氯化氢。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：泡沫、二氧化碳、干粉、砂', '土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:10', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3022, 3156, '都可能引起火灾和爆炸。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸 性分解。', '合适的灭火介质:干粉、二氧化碳、水喷雾或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:10', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3023, 3157, '遇明火、高热能引起燃烧爆炸。与氧化剂混合能形成有爆炸性的混合物。', '一氧化碳、二氧化碳、氧化氮。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:10', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3024, 3158, '易燃液体，其蒸气与空气混合，能形成爆炸性混合物。暴露于火中的容器可能会通过压力安全阀泄漏出内容物。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳', '干粉、二氧化碳或耐醇泡沫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3025, 3159, '本品极度易燃，蒸气与空气可形成爆炸性混合物，遇明火、高热极易引起燃烧或爆炸。若遇高热，可发生聚合反应，放出大量热量而引起容器破裂和爆炸事故。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3026, 3160, '遇明火、高热易燃。受热分解放出有毒的氧化氮烟气。与氧化剂能发生强烈反应。', '一氧化碳、二氧化碳、氧化氮。', '采用抗溶性泡沫、二氧化碳、干粉、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3027, 3161, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳', '雾状水、泡沫、二氧化碳、干粉、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3028, 3162, '接触火焰可能会产生膨胀或爆炸性分解。', '无资料 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。不合适的灭火介质:避免用太强烈的水汽灭火， 因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当', '的)）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表 和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3029, 3163, '可燃。遇明火、高热可燃。加热分解产生易燃的有毒气体。具有腐蚀性。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳、氧化氮', '采用抗溶性泡沫、干粉、二氧化碳、砂土灭火', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3030, 3164, '遇明火、高热能引起燃烧爆炸。与氧化剂混合能形成有爆炸性的混合物。受热分解产生有毒的氧化氮气体。蒸气比空气重，易在低处聚集，遇火源会着火回燃。', '一氧化碳、二氧化碳、氧化氮', '雾状水、泡沫、二氧化碳、干粉、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3031, 3165, '其蒸气与空气可形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。与氧化剂能发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。容器受热内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳', '砂土、泡沫、干粉、二氧化碳', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3032, 3166, '遇明火、高热可燃。与氧化剂混合能形成有爆炸性的混合物。粉体与空气可形成爆炸性混合物，当达到一定的浓度时，遇火星会发生爆炸。在潮湿空气中缓慢分解。受热分解释放出有毒气体。', '一氧化碳、二氧化碳', '雾状水、二氧化碳、干粉、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3033, 3167, '极度易燃，蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。具有腐蚀性，与氧化剂接触发生剧烈反应。受热分解放出有毒的氮氧化物气体。流动搅拌会产生静电积聚，有燃烧爆炸的危险。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氮氧化物、氨气', '抗溶性泡沫、二氧化碳、干粉、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3034, 3168, '遇明火、高热可燃。受高热分解，放出有毒的烟气。粉体与空气可形成爆炸性混合物，当达到一定浓度时，遇火星会发生爆炸。加热分解产生有毒气体。', '一氧化碳、二氧化碳、氮氧化物、氰化氢。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3035, 3169, '可燃液体，遇明火、高热有燃烧危险。受热分解放出有毒的氮氧化物气体。与强氧化剂接触可发生剧烈反应。若遇高热，容器内压增大，有开裂和爆炸的危险。流动搅拌会产生静电积聚，有燃烧爆炸的危险。', '一氧化碳、二氧化碳、氮氧化物、氨气', '干粉、二氧化碳、耐醇泡沫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3036, 3170, '易燃液体，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触发生剧烈反应。在火场中，受热的容器有爆炸危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。流速过快容易产生和积聚静电。', '一氧化碳、二氧化碳。', '抗溶性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:15', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3037, 3171, '反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳、碘化氢。 尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的', '容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：雾状水、泡沫、干 粉、二氧化碳、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3038, 3172, '其蒸气与空气可形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。与氧化剂能发生强烈反应。受高热分解产生有毒的碘化物气体。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、碘化氢。 尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的', '容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：雾状水、泡沫、干 粉、二氧化碳、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3039, 3173, '其蒸气与空气可形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。与氧化剂能发生强烈反应。受高热分解产生有毒的碘化物气体。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、碘化氢。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：泡沫、二氧化碳、干粉、砂', '土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3040, 3174, '其蒸气与空气可形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。与氧化剂（如高锰酸钾等）能发生强烈反应，引起燃烧或爆炸。受高热分解产生有毒的碘化物气体。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、碘化氢。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：泡沫、二氧化碳、干粉、砂', '土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:17', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3041, 3175, '经过稳定化处理才允许储运。气体比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。在密闭空间内，蒸气与空气可形成爆炸性混合物，遇热源和明火有燃烧爆炸的危险。与强氧化剂接触发生剧烈反应。受热分解产生有毒气体。蒸气比空气重，易在低处聚集，形成爆炸性混合物。', '一氧化碳、二氧化碳、氮氧化物、未完全燃烧的碳氢化合物等有毒有害气体。', '灭火剂：雾状水、泡沫、二氧化碳、干粉。切断气源。若不能切断气源，则不允许熄灭泄漏处的火焰。喷水冷却容器，可能的话将容器从火场移至空旷处。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:17', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3042, 3176, '易燃液体，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。加热时容器有爆炸危险。可能会释放毒性烟雾。', '燃烧产生一氧化碳、二氧化碳等有毒气体。不完全燃烧可能产生醛类、酮类等刺激性物质。', '小火：干式化学灭火剂、二氧化碳、抗溶泡沫灭火剂；大火：水雾或抗溶泡沫灭火剂。禁止使用强水流直接喷射，可能导致火势蔓延。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:17', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3043, 3177, '极易燃气体，与空气混合能形成爆炸性混合物，遇热源和明火有燃烧爆炸的危险。与氧化剂接触发生剧烈反应，放出大量热量而引起容器破裂和爆炸事故。气体比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，可发生聚合反应，放出大量热量而引起容器破裂和爆炸事故。', '一氧化碳、二氧化碳。受热分解可能产生其他有毒气体。', '雾状水、泡沫、二氧化碳、干粉。切断气源。若不能切断气源，则不允许熄灭泄漏处的火焰。喷水冷却容器，可能的话将容器从火场移至空旷处。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:17', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3044, 3178, '易燃液体，遇明火、高热可燃。与强氧化剂可发生剧烈反应。具有腐蚀性，对皮肤、眼睛和呼吸道有强烈刺激性。受高热分解，放出有毒的氮氧化物烟气。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。在密闭空间内，蒸气与空气可形成爆炸性混合物。流动和搅动可能产生静电积聚，有静电火灾风险。', '一氧化碳、二氧化碳、氮氧化物、胺类化合物等有毒气体。燃烧时可能产生氰化氢等剧毒物质。', '抗溶性泡沫、干粉、二氧化碳、砂土。小面积火灾可使用二氧化碳或干粉灭火器。大面积火灾应使用抗溶性泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3045, 3179, '遇明火、高热可燃。受热分解放出有毒的氮氧化物和氟化物烟气。与氧化剂可发生反应。燃烧时产生有毒刺激性气体。容器受热可能发生爆炸，危险性极高。', '一氧化碳、二氧化碳、氮氧化物（NOx）、氟化氢（HF）、氰化物等有毒气体。', '泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3046, 3180, '1-庚炔为易燃液体，闪点-10℃，高度易燃。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。受冲击、流动、激荡后可因产生静电火花放电引起燃烧爆炸。受热、光照或接触催化剂时可能发生危险的聚合反应，导致容器破裂和爆炸。与强氧化剂接触会发生剧烈反应。', '一氧化碳、二氧化碳', '泡沫、干粉、二氧化碳、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3047, 3181, '生聚合反应，放出大量热量而引起容器破裂和爆炸事故。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：泡沫、二氧化碳、干粉、砂', '土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3048, 3182, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。在火场中，受热的容器有 爆炸危险。', '一氧化碳、二氧化碳。 尽可能将容器从火场移至空旷处。灭火剂：泡沫、二氧化碳、干粉、砂土。用水灭火无效，', '但须用水保持火场容器冷却。用雾状水保护消防人员，用砂土堵逸出液体。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3049, 3183, '易燃液体，蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。受冲击、流动、激荡后可因产生静电火花放电引起燃烧爆炸。能发生聚合反应，随温度升高聚合速度加快，可能导致容器破裂。', '一氧化碳、二氧化碳。受热分解可能产生其他有毒气体。', '泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:20', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3050, 3184, '极度易燃液体，蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，可发生聚合反应，放出大量热量而引起容器破裂和爆炸事故。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。受热分解可能产生其他有毒气体。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:20', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3051, 3185, '其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器 内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '抗溶性泡沫、二氧化碳、干粉、用水冷却火场容器。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:20', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3052, 3186, '从而增加火势和/或蒸气的浓度。蒸气可能会移动到着火源并回闪。 液体和蒸气易燃。 加 热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:20', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3053, 3187, '易燃液体，其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。蒸气可能会移动到着火源并回闪。液体和蒸气易燃。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '燃烧产生一氧化碳、二氧化碳等有毒气体', '干粉、二氧化碳、耐醇泡沫、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:20', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3054, 3188, '酸钾等接触，能发生强烈反应，引起燃烧或爆炸。', '一氧化碳、二氧化碳。', '采用二氧化碳、雾状水、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3055, 3189, '遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。若遇高热，容器内压增大，有开裂 和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:22', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3056, 3190, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:22', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3057, 3191, '其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，可能发生 聚合反应，出现大量放热现象，引起容器破裂和爆炸事故。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:22', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3058, 3192, '易燃气体。与氧化剂接触猛烈反应。气体比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。受热分解产生有毒的氟化氢和氯化氢气体。', '一氧化碳、二氧化碳、氟化氢、氯化氢。', '雾状水、泡沫、干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:23', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3059, 3193, '1-氯-1-硝基丙烷为易燃液体，遇明火、高热、氧化剂能燃烧，并散发出有毒气体。急剧加热时可发生爆炸。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。受热分解释放出有毒的氮氧化物和氯化氢气体。', '一氧化碳、二氧化碳、氮氧化物、氯化氢、光气', '泡沫、二氧化碳、干粉、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:23', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3060, 3194, '1-氯-2,2,2-三氟乙烷为不燃气体，但在火场中受热会导致容器内压增大，有开裂和爆炸的危险。蒸气比空气重，能在较低处扩散到相当远的地方。受热分解释放出有毒的氟化氢和氯化氢气体。对大气臭氧层有极强破坏力，属于消耗臭氧层物质（ODS）。', '氟化氢、氯化氢、光气', '雾状水、二氧化碳、泡沫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:23', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3061, 3195, '易燃液体，蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。受热分解产生有毒的氯化氢、一氧化碳等气体。能发生聚合反应，放出大量热量，可能引起爆炸。', '一氧化碳、二氧化碳、氯化氢、光气等有毒气体。', '抗溶性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:23', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3062, 3196, '可燃固体，遇明火、高热可燃。受高热分解放出有毒的气体。已知在150℃下受强烈震动能引起爆炸。与氧化剂可发生反应。粉体与空气可形成爆炸性混合物，当达到一定浓度时，遇火星会发生爆炸。', '一氧化碳、二氧化碳、氮氧化物、氯化氢等有毒气体。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:23', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3063, 3197, '易燃液体，蒸气与空气可形成爆炸性混合物，遇明火、高热有引起燃烧爆炸的危险。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。受热分解产生有毒的腐蚀性气体。与氧化剂接触会发生剧烈反应。', '一氧化碳、二氧化碳、氯化氢等有毒气体。', '干粉、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:24', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3064, 3198, '易燃液体，蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。受热分解产生有毒的腐蚀性烟气。能发生聚合反应，放出大量热量，可能引起爆炸。', '一氧化碳、二氧化碳、氯化氢等有毒气体。', '抗溶性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3065, 3199, '可燃液体，蒸气与空气可形成爆炸性混合物，遇明火、高热有引起燃烧的危险。受热分解产生有毒的腐蚀性烟气，包括氯化氢和溴化氢。若遇高热，容器内压增大，有开裂和爆炸的危险。与强氧化剂接触会发生剧烈反应。', '一氧化碳、二氧化碳、氯化氢、溴化氢等有毒气体。', '雾状水、泡沫、二氧化碳、砂土、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3066, 3200, '可燃液体，蒸气与空气可形成爆炸性混合物，遇明火、高热有引起燃烧的危险。受热分解产生有毒的腐蚀性烟气，包括氯化氢和溴化氢。若遇高热，容器内压增大，有开裂和爆炸的危险。与强氧化剂、强碱接触会发生剧烈反应。', '一氧化碳、二氧化碳、氯化氢、溴化氢等有毒气体。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3067, 3201, '易燃液体，蒸气与空气可形成爆炸性混合物，遇明火、高热有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。受热分解产生有毒的腐蚀性烟气，包括氯化氢。若遇高热，容器内压增大，有开裂和爆炸的危险。与强氧化剂接触会发生剧烈反应。', '一氧化碳、二氧化碳、氯化氢等有毒气体。', '泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3068, 3202, '可燃液体，蒸气与空气可形成爆炸性混合物，遇明火、高热有引起燃烧的危险。受热分解产生有毒的腐蚀性烟气，包括氯化氢和溴化氢。若遇高热，容器内压增大，有开裂和爆炸的危险。与强氧化剂、强碱接触会发生剧烈反应。', '一氧化碳、二氧化碳、氯化氢、溴化氢等有毒气体。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3069, 3203, '1-氯丙烷为极度易燃液体，其蒸气与空气可形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。与氧化剂能发生强烈反应。受高热分解产生有毒的氯化物气体。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氯化氢等有毒气体', '泡沫、二氧化碳、干粉、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3070, 3204, '1-氯丁烷为易燃液体，其蒸气与空气可形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。与氧化剂能发生强烈反应。受高热分解产生有毒的氯化物气体。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氯化氢等有毒气体', '泡沫、干粉、二氧化碳、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3071, 3205, '遇明火、高热可燃。与强氧化剂可发生反应。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、氯化氢。', '雾状水、泡沫、二氧化碳、砂土、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3072, 3206, '易燃液体，其蒸气与空气可形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。受热分解产生有毒的氯化物气体。', '一氧化碳、二氧化碳、氯化氢、光气等有毒气体。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3073, 3207, '可燃。受高热分解放出有毒的气体。与氧化剂可发生反应。', '一氧化碳、二氧化碳、氧化氮。', '采用雾状水、泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3074, 3208, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、抗溶性泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3075, 3209, '遇明火、高热可燃。遇水或水蒸气反应发热放出有毒的腐蚀性气体。有腐蚀性。', '一氧化碳、二氧化碳、氯化氢、氧化磷。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3076, 3210, '或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3077, 3211, '易燃液体，遇明火、高热可燃。与强氧化剂可发生剧烈反应。若遇高热，可发生聚合反应，放出大量热量而引起容器破裂和爆炸事故。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。在密闭空间内，蒸气与空气可形成爆炸性混合物。流动和搅动可能产生静电积聚，有静电火灾风险。能发生聚合反应，需添加阻聚剂。', '一氧化碳、二氧化碳、未完全燃烧的碳氢化合物、聚合物分解产物等有毒气体。燃烧时可能产生刺激性烟雾。', '抗溶性泡沫、干粉、二氧化碳、砂土。小面积火灾可使用二氧化碳或干粉灭火器。大面积火灾应使用抗溶性泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3078, 3212, '易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂接触发生强烈反应。在火场中，受热的容器有爆炸危险。受高热分解放出有毒的腐蚀性烟雾。', '一氧化碳、二氧化碳。', '抗溶性泡沫、干粉、二氧化碳、1211灭火剂、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3079, 3213, '极度易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂可发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、硫化氢、氧化硫。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3080, 3214, '易燃液体，蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。受热分解放出有毒气体，放出大量热量而引起容器破裂和爆炸事故。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，可发生聚合反应，放出大量热量而引起容器破裂和爆炸事故。流动搅拌产生静电，有燃烧爆炸的危险。', '一氧化碳、二氧化碳、醛类等有毒气体。', '抗溶性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3081, 3215, '极度易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。若遇高热，可发生聚合反应，放出大量热量而引起容器破裂和爆炸事故。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。与氧化剂接触发生强烈反应，甚至引起燃烧。流速过快，容易产生和积聚静电。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3082, 3216, '极度易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。由于流动、搅拌等，可能产生静电。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。与氧化剂接触发生强烈反应，甚至引起燃烧。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3083, 3217, '易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。若遇高热，可发生聚合反应，出现大量放热现象，引起容器破裂或爆炸事故。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。与氧化剂接触发生强烈反应，甚至引起燃烧。', '一氧化碳、二氧化碳。', '干粉、二氧化碳或耐醇泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3084, 3218, '胺类及三氯化铝、六甲基苯等均能引起燃烧爆炸。燃烧分解时,放出有毒的氮氧化物气体。', '一氧化碳、二氧化碳、氧化氮。 尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火剂：雾状', '水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:32', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3085, 3219, '当达到一定浓度时，遇火星会发生爆炸。受热分解产生有毒气体。', '一氧化碳、二氧化碳、氧化氮。', '灭火剂：雾状水、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3086, 3220, '速冲击、流动、激荡后可因产生静电火花放电引起燃烧爆炸。其蒸气比空气重，能在较低 处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。处在火场中的容器若已变色或从安全', '泄压装置中产生声音，必须马上撤离。灭火剂：泡沫、干粉、二氧化碳、砂土。用水灭火 无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3087, 3221, '冲击、流动、激荡后可因产生静电火花放电引起燃烧爆炸。其蒸气比空气重，能在较低处 扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。处在火场中的容器若已变色或从安全', '泄压装置中产生声音，必须马上撤离。灭火剂：泡沫、干粉、二氧化碳、砂土。用水灭火 无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3088, 3222, '本品为可燃固体，遇高热、明火或与氧化剂接触，有引起燃烧的危险。受热分解放出有毒的溴化氢、一氧化碳、二氧化碳、氮氧化物等气体。在火场中，受热的容器有爆炸危险。燃烧时产生有毒、刺激性烟雾。粉尘与空气形成爆炸性混合物，遇明火、高热或氧化剂有引起燃烧爆炸的危险。', '一氧化碳、二氧化碳、溴化氢、氮氧化物、光气等有毒气体。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3089, 3223, '高度易燃液体，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。与氧化剂接触发生剧烈反应。流速过快，容易产生和积聚静电。受高热分解产生有毒的腐蚀性烟气。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3090, 3224, '内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、溴化氢。', '泡沫、二氧化碳、干粉、水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3091, 3225, '其蒸气与空气可形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。与氧化剂能发生强烈反应。受高热分解产生有毒的溴化物气体。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、溴化氢。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：泡沫、二氧化碳、干粉、砂', '土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:36', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3092, 3226, '易燃，遇明火、高热易引起燃烧，并放出有毒气体。受高热分解产生有毒的溴化物气体。', '一氧化碳、二氧化碳、溴化氢。 尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的', '容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：雾状水、泡沫、干 粉、二氧化碳、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:36', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3093, 3227, '易燃液体，其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。若遇高热，容器内压增大，有开裂和爆炸的危险。流速过快容易产生和积聚静电。', '一氧化碳、二氧化碳。', '干粉、二氧化碳或耐醇泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:36', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3094, 3228, '受热或接触火焰可能会产生膨胀或爆炸性分解。燃烧时可能产生有毒气体。高温下容器可能发生爆炸。与强氧化剂接触可能发生剧烈反应。为氨基甲酸酯类杀虫剂，具有毒性，燃烧时可能释放氮氧化物等有毒气体。', '一氧化碳、二氧化碳、氮氧化物、氰化氢等有毒气体。', '干粉、二氧化碳、耐醇泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:36', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3095, 3229, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氯化氢。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3096, 3230, '遇明火、高热可燃。遇潮时对大多数金属有腐蚀性。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氯化氢。', '雾状水、抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3097, 3231, '遇明火、高热可燃。与氧化剂可发生反应。有腐蚀性。', '一氧化碳、二氧化碳、氮氧化物。', '抗溶性泡沫、二氧化碳、干粉、水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3098, 3232, '遇高热、明火或氧化剂，有引起燃烧的危险。', '一氧化碳、二氧化碳。', '泡沫、干粉、砂土、二氧化碳、水。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3099, 3233, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。', '一氧化碳、二氧化碳、氟化氢。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：抗溶性泡沫、二氧化碳、干', '粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3100, 3234, '遇明火、高热、氧化剂极易燃烧。', '一氧化碳、二氧化碳。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3101, 3235, '若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '抗溶性泡沫、二氧化碳、干粉、1211灭火剂、用水冷却火场容器。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3102, 3236, '易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂可发生强烈反应。在火场中，受热的容器有爆炸危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '喷水冷却容器，可能的话将容器从火场移至空旷处。处在火场中的容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3103, 3237, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3104, 3238, '从而增加火势和/或蒸气的浓度。蒸气可能会移动到着火源并回闪。液体和蒸气易燃。加 热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3105, 3239, '烧爆炸。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。处在火场中的容器若已变色或从安全', '泄压装置中产生声音，必须马上撤离。灭火剂：泡沫、二氧化碳、干粉、砂土。用水灭火 无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3106, 3240, '在火场中，受热的容器有爆炸危险。其蒸气比空气重，能在较低处扩散到相当远的地方， 遇火源会着火回燃。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。处在火场中的容器若已变色或从安全', '泄压装置中产生声音，必须马上撤离。灭火剂：泡沫、二氧化碳、干粉、砂土。用水灭火 无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3107, 3241, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳、水喷雾或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3108, 3242, '接触火焰可能会产生膨胀或爆炸性分解。', '无资料', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:43', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3109, 3243, '接触火焰可能会产生膨胀或爆炸性分解。', '无资料', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:44', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3110, 3244, '接触火焰可能会产生膨胀或爆炸性分解。', '无资料', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:44', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3111, 3245, '接触火焰可能会产生膨胀或爆炸性分解。', '无资料 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。不合适的灭火介质:避免用太强烈的水汽灭火， 因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当', '的)）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表 和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:44', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3112, 3246, '热，可能发生聚合反应，出现大量放热现象，引起容器破裂和爆炸事故。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3113, 3247, '其蒸气与空气形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。 其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压 增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:46', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3114, 3248, '引起燃烧或爆炸。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 切断气源。若不能切断气源，则不允许熄灭泄漏处的火焰。喷水冷却容器，可能的话将容器从火', '场移至空旷处。灭火剂：雾状水、泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:46', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3115, 3249, '发生化学反应或引起燃烧。在火场中，受热的容器有爆炸危险。其蒸气比空气重，能在较 低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的', '容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：1211灭火剂、泡沫、 干粉、二氧化碳、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:46', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3116, 3250, '而增加火势和/或蒸气的浓度。蒸气可能会移动到着火源并回闪。液体和蒸气易燃。 加热 时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3117, 3251, '烈反应。在火场中，受热的容器有爆炸危险。其蒸气比空气重，能在较低处扩散到相当远 的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。处在火场中的容器若已变色或从安全', '泄压装置中产生声音，必须马上撤离。灭火剂：泡沫、二氧化碳、干粉、砂土。用水灭火 无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3118, 3252, '化学反应或引起燃烧。在火场中，受热的容器有爆炸危险。其蒸气比空气重，能在较低处 扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。处在火场中的容器若已变色或从安全', '泄压装置中产生声音，必须马上撤离。灭火剂：泡沫、二氧化碳、干粉、砂土。用水灭火 无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3119, 3253, '生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 尽可能将容器从火场移至空旷处。处在火场中的容器若已变色或从安全泄压装置中产生声', '音，必须马上撤离。灭火剂：泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:48', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3120, 3254, '遇明火、高热易燃。受热或遇水分解放热, 放出有毒的腐蚀性烟气。燃烧分解时, 放出有 毒的刺激性氯化物烟气。与氧化剂接触猛烈反应。', '一氧化碳、二氧化碳、氯化物。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：二氧化碳、干粉、砂 土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:48', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3121, 3255, '蚀铜及铜的化合物。', '一氧化碳、二氧化碳、氧化氮。', '喷水保持火场容器冷却，直至灭火结束。灭火剂：水、干粉、二氧化碳、抗溶性泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3122, 3256, '都可能引起火灾和爆炸。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸 性分解。', '一氧化碳、二氧化碳。', '干粉、二氧化碳、水喷雾或耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:50', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3123, 3257, '接触火焰可能会产生膨胀或爆炸性分解。', '无资料', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:50', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3124, 3258, '火焰都可能引起火灾和爆炸。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或 爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:50', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3125, 3259, '火焰都可能引起火灾和爆炸。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或 爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:50', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3126, 3260, '火焰都可能引起火灾和爆炸。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或 爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫或水喷雾。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:52', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3127, 3261, '火焰都可能引起火灾和爆炸。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或 爆炸性分解。', '合适的灭火介质:干粉、二氧化碳、耐醇泡沫或水喷雾。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:52', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3128, 3262, '气体。受热时性质不稳定，40℃逐渐分解，至103～104℃时激烈分解，放出氮气及数种 有机氰化合物，对人体有害，并散发出较大热量，能引起爆炸。', '一氧化碳、二氧化碳、氰化物、氮氧化物、氮气。 尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火剂：水、', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:52', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3129, 3263, '炸。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:52', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3130, 3264, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氯化氢。', '干粉、二氧化碳或耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3131, 3265, '不易燃烧。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氯化氢。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:54', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3132, 3266, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:54', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3133, 3267, '爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3134, 3268, '烧爆炸。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。处在火场中的容器若已变色或从安全', '泄压装置中产生声音，必须马上撤离。灭火剂：泡沫、二氧化碳、干粉、砂土。用水灭火 无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3135, 3269, '或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3136, 3270, '建规火险分级：', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3137, 3271, '遇高热、明火或氧化剂，有引起燃烧的危险。有腐蚀性。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3138, 3272, '生聚合反应，出现大量放热现象，引起容器破裂或爆炸事故。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土、1211灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:56', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3139, 3273, '其蒸气与空气形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反 应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。遇高热能发 生聚合反应，出现大量放热现象，引起容器破裂或爆炸事故。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土、1211灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3140, 3274, '遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。受热分解放出有毒的氧化氮烟气。', '一氧化碳、二氧化碳、氧化氮。', '采用泡沫、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3141, 3275, '应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热， 容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。 抗溶性泡沫、二氧化碳、干粉、1211灭火剂。用水保持火场容器冷却，并用水喷淋保护堵', '漏人员。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3142, 3276, '而增加火势和/或蒸气的浓度。蒸气可能会移动到着火源并回闪。液体和蒸气易燃。 加热 时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3143, 3277, '烈反应。在火场中，受热的容器有爆炸危险。其蒸气比空气重，能在较低处扩散到相当远 的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。处在火场中的容器若已变色或从安全', '泄压装置中产生声音，必须马上撤离。灭火剂：泡沫、二氧化碳、干粉、砂土。用水灭火 无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:59', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3144, 3278, '器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:59', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3145, 3279, '化学反应或引起燃烧。在火场中，受热的容器有爆炸危险。其蒸气比空气重，能在较低处 扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。处在火场中的容器若已变色或从安全', '泄压装置中产生声音，必须马上撤离。灭火剂：泡沫、二氧化碳、干粉、砂土。用水灭火 无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:59', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3146, 3280, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氯化氢。', '泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:59', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3147, 3281, '发生化学反应。', '一氧化碳、二氧化碳、氧化氮、氯化氢。', '采用雾状水、泡沫、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3148, 3282, '遇明火、高热可燃。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、氯化氢。', '泡沫、二氧化碳、砂土、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:01', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3149, 3283, '不稳定，在光照、空气中可能分解。遇明火、高热易燃。与氧化剂接触发生反应。受热分解产生有毒的腐蚀性气体。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。本品能发生聚合反应。', '一氧化碳、二氧化碳、氯化氢。 泡沫、二氧化碳、干粉。用水灭火无效。用水保持火场容器冷却，并用水喷淋保护堵漏人', '员。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:01', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3150, 3284, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:01', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3151, 3285, '遇明火、高热可燃。受热分解放出有毒的氧化氮烟气。', '一氧化碳、二氧化碳、氧化氮。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:01', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3152, 3286, '心等症状。对眼睛、皮肤、呼吸道有刺激作用。', '无资料', '用干粉、抗溶性泡沫、二氧化碳灭火，小面积可用雾状水扑救。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3153, 3287, '遇明火、高热可燃。受高热分解，产生有毒的氮氧化物和氯化物气体。', '一氧化碳、二氧化碳、氮氧化物、氯化物。', '水、泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3154, 3288, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。受高热发生剧烈分解，甚至发生爆炸。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3155, 3289, '若遇高热可发生剧烈分解，引起容器破裂或爆炸事故。', '一氧化碳、二氧化碳。', '雾状水、泡沫、三氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3156, 3290, '从而增加火势和/或蒸气的浓度。蒸气可能会移动到着火源并回闪。液体和蒸气易燃。加 热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3157, 3291, '从而增加火势和/或蒸气的浓度。蒸气可能会移动到着火源并回闪。液体和蒸气易燃。加 热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3158, 3292, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '灭火方法： 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3159, 3293, '发生化学反应。', '一氧化碳、二氧化碳、氧化氮、氯化氢。', '采用雾状水、泡沫、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3160, 3294, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氯化氢。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3161, 3295, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氯化氢。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:07', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3162, 3296, '发生化学反应。', '一氧化碳、二氧化碳、氧化氮。', '采用雾状水、泡沫、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:07', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3163, 3297, '遇明火、高热可燃。有腐蚀性。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氯化氢。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:07', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3164, 3298, '遇明火、高温、震动、撞击、摩擦，有引起燃烧爆炸的危险。', '一氧化碳、二氧化碳、氧化氮。 消防人员须在有防爆掩蔽处操作。用大量水灭火。遇大火须远离以防炸伤。在物料附近失火，', '须用水保持容器冷却。禁止用砂土压盖。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:07', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3165, 3299, '与重金属粉末能起化学反应生成金属盐, 增加敏感度。', '一氧化碳、二氧化碳、氮氧化物。 消防人员须在有防爆掩蔽处操作。用大量水灭火。遇大火须远离以防炸伤。在物料附近失火，', '须用水保持容器冷却。禁止用砂土压盖。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:07', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3166, 3300, '受热、接触明火、或受到摩擦、震动、撞击时可发生爆炸。在干燥状态下，对摩擦、撞击特别 敏感。分解时放出有毒的氮氧化物气体。干燥的苦味酸铵与金属不发生作用，潮湿情况下，与 铜、铝等作用，生成苦味酸盐，增加敏感度。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、氧化氮。 消防人员须在有防爆掩蔽处操作。用大量水灭火。遇大火须远离以防炸伤。在物料附近失火，', '须用水保持容器冷却。禁止用砂土压盖。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:08', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3167, 3301, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '灭火方法： 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3168, 3302, '建规火险分级：', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3169, 3303, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '灭火方法： 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:10', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3170, 3304, '遇明火、高热、摩擦、震动、撞击，有引起燃烧爆炸的危险。', '一氧化碳、二氧化碳、氮氧化物。', '水、雾状水。禁止用砂土压盖。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:10', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3171, 3305, '受热、接触明火、或受到摩擦、震动、撞击时可发生爆炸。着火后会转为爆轰。', '一氧化碳、二氧化碳、氮氧化物。 消防人员须在有防爆掩蔽处操作。用大量水灭火。遇大火切勿轻易接近。在物料附近失火，须', '用水保持容器冷却。禁止用砂土压盖。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3172, 3306, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '灭火方法： 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:12', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3173, 3307, '烧可不起爆。大量堆积或在密闭容器中燃烧，有可能由燃烧转变为爆轰。遇碱生成不安定的爆 炸物。该物质不导电，在粉碎时易产生静电积累。', '一氧化碳、二氧化碳、氧化氮。 消防人员须在有防爆掩蔽处操作。用大量水灭火。遇大火切勿轻易接近。在物料附近失火，须', '用水保持容器冷却。禁止用砂土压盖。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:12', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3174, 3308, '遇明火、高热、摩擦、震动、撞击，有引起燃烧爆炸的危险。', '一氧化碳、二氧化碳、氮氧化物。', '水、雾状水。禁止用砂土压盖。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3175, 3309, '干燥时，即使数量很少，在接触火焰或火花或受到震动、摩擦和静电时，能引起爆炸。', '一氧化碳、二氧化碳、氧化氮、氧化铅。', '雾状水、泡沫、二氧化碳。禁止用砂土压盖。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3176, 3310, '受热、接触明火、或受到摩擦、震动、撞击时可发生爆炸。', '一氧化碳、二氧化碳、氧化氮。 消防人员须在有防爆掩蔽处操作。用大量水灭火。遇大火切勿轻易接近。在物料附近失火，须', '用水保持容器冷却。禁止用砂土压盖。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3177, 3311, '遇明火、高热可燃。与强氧化剂可发生反应。受高热分解产生有毒的溴化物气体。', '一氧化碳、二氧化碳、溴化氢、氧化氮。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3178, 3312, '遇高热、明火可燃。受热分解产生有毒溴化物气体。', '一氧化碳、二氧化碳、溴化氢。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3179, 3313, '遇明火、高热可燃。其粉末与空气可形成爆炸性混合物。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3180, 3314, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氯化氢。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷 处。灭火剂：泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3181, 3315, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氯化氢。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷 处。灭火剂：泡沫、干粉、砂土、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3182, 3316, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氯化氢、氧化钠。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷 处。灭火剂：泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:17', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3183, 3317, '遇明火、高热可燃。受热分解放出有毒的氧化氮烟气。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、氧化氮。', '采用雾状水、抗溶性泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:17', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3184, 3318, '遇高热、明火或氧化剂，有引起燃烧的危险。有腐蚀性。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3185, 3319, '其蒸气与空气形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与强氧化剂可发生反应。 其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器 内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3186, 3320, '遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。受热分解放出有毒的氧化氮烟气。', '一氧化碳、二氧化碳、氧化氮。', '采用泡沫、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3187, 3321, '氮烟气。', '一氧化碳、二氧化碳、氮氧化物。 尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火剂：抗溶', '性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3188, 3322, '而增加火势和/或蒸气的浓度。蒸气可能会移动到着火源并回闪。液体和蒸气易燃。 加热 时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3189, 3323, '烈反应。在火场中，受热的容器有爆炸危险。其蒸气比空气重，能在较低处扩散到相当远 的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。处在火场中的容器若已变色或从安全', '泄压装置中产生声音，必须马上撤离。灭火剂：泡沫、二氧化碳、干粉、砂土。用水灭火 无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3190, 3324, '化学反应或引起燃烧。在火场中，受热的容器有爆炸危险。其蒸气比空气重，能在较低处 扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。处在火场中的容器若已变色或从安全', '泄压装置中产生声音，必须马上撤离。灭火剂：泡沫、二氧化碳、干粉、砂土。用水灭火 无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3191, 3325, '发生化学反应。', '一氧化碳、二氧化碳、氧化氮、氯化氢。', '采用雾状水、泡沫、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3192, 3326, '遇明火、高热可燃。与强氧化剂可发生反应。受高热分解产生有毒的腐蚀性气体。', '一氧化碳、二氧化碳、氯化氢。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3193, 3327, '性。', '氯化氢、光气。', '雾状水、泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:20', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3194, 3328, '遇明火、高热可燃。受高热分解，放出刺激性的氯化氢气体。', '一氧化碳、二氧化碳、氯化物。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3195, 3329, '遇明火、高热可燃。受高热分解产生有毒的腐蚀性烟气。', '一氧化碳、二氧化碳、氯化氢。', '采用雾状水、泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3196, 3330, '爆炸性分解。', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3197, 3331, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:22', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3198, 3332, '炸性，但只有在强起爆药引爆下才能起爆。', '一氧化碳、二氧化碳、氧化氮。', '采用雾状水、泡沫、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:22', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3199, 3333, '应生成金属盐, 增加敏感度。粉尘在流动和搅拌时，会有静电积累。', '一氧化碳、二氧化碳、氧化氮。 遇大火，消防人员须在有防护掩蔽处操作。灭火剂：雾状水、泡沫、二氧化碳。禁止用砂土压', '盖。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:22', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3200, 3334, '爆炸性分解。', '灭火方法： 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:22', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3201, 3335, '遇明火、高热可燃。与强氧化剂可发生反应。受热或遇水分解放热，放出有毒的腐蚀性烟气。', '一氧化碳、氯化氢、氧化硫、氧化氮。', '二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:24', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3202, 3336, '易燃，遇明火、高热、摩擦、撞击有引起燃烧的危险。燃烧时放出有毒的刺激性烟雾。与 氧化剂混合能形成爆炸性混合物。', '一氧化碳、二氧化碳、氧化氮。 尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火剂：二氧', '化碳、泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:24', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3203, 3337, '与氧化剂混合能形成爆炸性混合物。', '一氧化碳、二氧化碳、氮氧化物。 尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火剂：二氧', '化碳、泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:24', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3204, 3338, '反应。', '一氧化碳、二氧化碳、氧化氮。', '采用雾状水、泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:24', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3205, 3339, '遇明火、高热可燃。受热分解产生有毒气体。燃烧时产生大量烟雾。', '一氧化碳、二氧化碳、氧化氮。', '雾状水、二氧化碳、泡沫、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3206, 3340, '遇高热、明火或与氧化剂混合，经摩擦、撞击有引起燃烧爆炸的危险。', '一氧化碳、二氧化碳、氯化氢、氮氧化物。', '泡沫、于粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3207, 3341, '氧化氮烟气。', '一氧化碳、二氧化碳、氮氧化物。', '采用雾状水、泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3208, 3342, '都可能引起火灾和爆炸。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸 性分解。', '合适的灭火介质: 干粉、二氧化碳、水喷雾或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3209, 3343, '遇明火、高热可燃。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、氮氧化物、溴化氢。', '雾状水、抗溶性泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3210, 3344, '受热，接触明火、高热或受到强烈震动，接触氧化剂和易燃物有发生燃烧爆炸的危险。', '一氧化碳、二氧化碳、氧化氮。', '雾状水、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3211, 3345, '反应，出现大量放热现象，引起容器破裂或爆炸事故。', '一氧化碳、二氧化碳。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷 处。灭火剂：抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3212, 3346, '遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。若遇高热，容器内压增大，有开裂和 爆炸的危险。', '一氧化碳、二氧化碳', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3213, 3347, '遇明火、高热可燃。受热分解放出有毒的氧化氮烟气。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、氧化氮。', '采用雾状水、抗溶性泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3214, 3348, '遇高热、明火或氧化剂，有引起燃烧的危险。有腐蚀性。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3215, 3349, '而增加火势和/或蒸气的浓度。蒸气可能会移动到着火源并回闪。液体和蒸气易燃。加热时， 容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3216, 3350, '而增加火势和/或蒸气的浓度。蒸气可能会移动到着火源并回闪。液体和蒸气易燃。加热时， 容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3217, 3351, '其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容 器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3218, 3352, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '灭火方法： 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3219, 3353, '接触火焰可能会产生膨胀或爆炸性分解。', '燃烧产生一氧化碳、二氧化碳、有机酸和醛类等有毒有害气体。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3220, 3354, '接触火焰可能会产生膨胀或爆炸性分解。', '无资料', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3221, 3355, '接触火焰可能会产生膨胀或爆炸性分解。', '无资料', '雾状水、泡沫、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3222, 3356, '化物。受热、摩擦、接触还原剂、硫氰酸盐、有机物、可燃物或受到污染，可引起爆炸发 生。能腐蚀塑料、橡胶和涂料。防止容器受到震动、受热及摩擦。', '无资料 能助长火势；能快速燃烧，有闪燃的效果。蒸气比空气重，易在低处聚集。封闭区域内的 蒸气遇火能爆炸。储存容器及其部件可能向四面八方飞射很远。如果该物质或被污染的流', '体进入水路，通知有潜在水体污染的下游用户。流体能产生火灾或爆炸危害，通知地方卫 生、消防官员和污染控制部门。使用干粉、泡沫、二氧化碳灭火。使用雾状水冷却容器。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3223, 3357, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '灭火方法： 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3224, 3358, '遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。受热分解放出有毒的氧化氮烟气。', '一氧化碳、二氧化碳、氧化氮。', '采用泡沫、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:32', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3225, 3359, '遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氧化氮。', '二氧化碳、泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:32', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3226, 3360, '其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。', '一氧化碳、二氧化碳。', '砂土、泡沫、干粉、二氧化碳。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3227, 3361, '其蒸气与空气形成爆炸性混合物，遇明火、高热能引起燃烧爆炸；与氧化剂能发生强烈反 应。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、1211灭火剂、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3228, 3362, '烈反应。在火场中，受热的容器有爆炸危险。其蒸气比空气重，能在较低处扩散到相当远 的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。处在火场中的容器若已变色或从安全', '泄压装置中产生声音，必须马上撤离。灭火剂：泡沫、二氧化碳、干粉、砂土。用水灭火 无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3229, 3363, '发生化学反应。', '一氧化碳、二氧化碳、氧化氮、氯化氢。', '采用雾状水、泡沫、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:36', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3230, 3364, '遇明火、高热可燃。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、氯化氢。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷 处。灭火剂：干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:36', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3231, 3365, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。受高热分解产生有毒的腐蚀性气体。', '一氧化碳、二氧化碳、氯化氢。', '雾状水、泡沫、二氧化碳、砂土、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:36', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3232, 3367, '遇明火、高热可燃。与氧化剂能发生强烈反应。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、氯化氢。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:37', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3233, 3368, '遇明火、高热可燃。受高热分解，放出刺激性烟气。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3234, 3369, '或撞击可引起燃烧或爆炸。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。 合适的灭火介质: 干粉、二氧化碳、水喷雾或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3235, 3370, '安全阀泄漏出内容物。受热或接触火焰可能会产生膨胀或爆炸性分解。', '无资料', '二氧化碳、水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3236, 3371, '爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3237, 3372, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:39', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3238, 3373, '遇高热、明火或氧化剂，有引起燃烧的危险。有腐蚀性。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:39', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3239, 3374, '其蒸气与空气形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。 其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压 增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:39', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3240, 3375, '遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。受热分解放出有毒的氧化氮烟气。', '一氧化碳、二氧化碳、氧化氮。', '采用泡沫、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:39', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3241, 3376, '猛烈反应。', '一氧化碳、二氧化碳、氮氧化物。 尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火剂：抗溶', '性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3242, 3377, '的危险。', '一氧化碳、二氧化碳、氧化氮。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3243, 3378, '受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氯化氢。', '抗溶性泡沫、二氧化碳、干粉。不宜用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3244, 3379, '发生化学反应。', '一氧化碳、二氧化碳、氧化氮、氯化氢。', '采用雾状水、泡沫、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3245, 3380, '遇明火、高热可燃。与强氧化剂可发生反应。受高热分解产生有毒的腐蚀性气体。', '一氧化碳、二氧化碳、氯化氢。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3246, 3381, '遇明火、高热可燃。受高热分解产生有毒的腐蚀性烟气。', '一氧化碳、二氧化碳、氯化氢。', '采用雾状水、泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3247, 3382, '爆炸性分解。', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3248, 3383, '遇明火、高热、氧化剂能燃烧，并散发出有毒气体。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:43', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3249, 3384, '遇明火、高热可燃。与强氧化剂可发生反应。急剧加热时可发生爆炸。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、氧化氮。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。切勿将水流直接射至熔融物，以免引起严重的流淌火灾或剧烈的沸溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:44', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3250, 3385, '高度易燃，其粉体与空气混合，能形成爆炸性混合物。受热或接触火焰可能会产生膨胀或爆炸性分解。燃烧时可能会释放毒性烟雾。加热时，容器可能爆炸。', NULL, '使用大量的水冲刷灭火。如果没有水，使用干式化学灭火剂或沙土等。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:44', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3251, 3386, '震动或撞击可引起燃烧或爆炸。', '一氧化碳、二氧化碳、氧化氮。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:44', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3252, 3387, '出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、抗溶性泡沫、干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3253, 3388, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氯化氢。', '泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3254, 3389, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3255, 3390, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3256, 3391, '遇明火、高热可燃。受热分解放出有毒的氧化氮烟气。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、氧化氮。', '采用雾状水、抗溶性泡沫、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3257, 3392, '遇明火、高热可燃。受高热或接触酸或酸雾放出剧毒的砷氧化物烟雾。', '一氧化碳、二氧化碳、氮氧化物、氧化砷、砷化氢。', '雾状水、抗溶性泡沫、二氧化碳、干粉、砂土。禁止使用酸碱灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:46', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3258, 3393, '遇明火、高热可燃。与强氧化剂可发生反应。受热分解放出有毒的氧化氮烟气。', '一氧化碳、二氧化碳、氧化氮。', '干粉、砂土。禁止用水和泡沫灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3259, 3394, '器内压增大，有开裂和爆炸的危险。有腐蚀性。', '一氧化碳、二氧化碳、氧化氮。', '泡沫、二氧化碳、于粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3260, 3395, '遇明火、高热可燃。受高热分解，放出有毒的烟气。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、氮氧化物。', '采用雾状水、抗溶性泡沫、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3261, 3396, '遇明火、高热可燃。与强氧化剂可发生反应。受热分解放出有毒的氧化氮烟气。', '一氧化碳、二氧化碳、氧化氮。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3262, 3397, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。与硫酸、硝酸、盐酸等强酸发生剧烈反应。', '一氧化碳、二氧化碳、氧化氮。', '雾状水、泡沫、二氧化碳、砂土、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3263, 3398, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。受高热分解放出有毒的气体。与强氧化剂、强碱接触可发生反应。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3264, 3399, '其蒸气与空气可形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。与氧化剂能发生强烈反应。若遇高热，可能发生聚合反应，出现大量放热现象，引起容器破裂和爆炸事故。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3265, 3400, '能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '有害燃烧产物：一氧化碳、二氧化碳、氮氧化物等有毒气体', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3266, 3401, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。受热分解放出有毒的氧化氮烟气。', '一氧化碳、二氧化碳、氧化氮。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:49', '', NULL);
