INSERT INTO `msds_fire_fighting` VALUES (3268, 3403, '其蒸气与空气形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。 其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源引着回燃。若遇高热，容器内压增 大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3269, 3404, '其蒸气与空气形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反 应。若遇高热，可能发生聚合反应，出现大量放热现象，引起容器破裂和爆炸事故。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:52', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3270, 3405, '其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。在使用和贮存过程中， 易发生自聚反应，酿成事故。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3271, 3406, '容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、硫化氢、氧化硫。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷 处。灭火剂：干粉、二氧化碳、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3272, 3407, '与氧化剂、强酸、强碱、胺类、溴反应剧烈。在火场高温下，能发生聚合放热，使容器破 裂。', '一氧化碳、二氧化碳、氧化氮、氰化氢。', '抗溶性泡沫、二氧化碳、干粉、砂土。用水灭火无效，但须用水保持火场容器冷却。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:54', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3273, 3408, '受热或接触火焰可能会产生膨胀或爆炸性分解。蒸气可能会移动到着火源并回闪。液体和蒸气易燃。加热时，容器可能爆炸。', '一氧化碳、二氧化碳', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:54', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3274, 3409, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:54', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3275, 3410, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。受热分解产生有毒的碘化氢烟气。', '一氧化碳、二氧化碳、碘化氢。', '灭火剂：雾状水、泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3276, 3411, '的地方，遇明火会引着回燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、碘化氢。', '雾状水、抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3277, 3412, '内压增大，有开裂和爆炸的危险。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、碘化氢。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3278, 3413, '有毒气体。与氧化剂能发生强烈反应。在火场中，受热的容器有爆炸危险。', '一氧化碳、二氧化碳。', '用水喷射逸出液体，使其稀释成不燃性混合物，并用雾状水保护消防人员。灭火剂：抗溶性泡沫、干粉、二氧化碳、雾状水、1211灭火剂、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:56', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3279, 3414, '其蒸气与空气形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。 其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压 增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氧化硫。', '砂土、干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:56', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3280, 3415, '能发生强烈反应,引起燃烧或爆炸。若遇高热，可发生聚合反应，放出大量热量而引起容器 破裂和爆炸事故。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的', '容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：泡沫、二氧化碳、 干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:56', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3281, 3416, '易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:56', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3282, 3417, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '氮氧化物、一氧化碳、二氧化碳', '合适的灭火介质: 干粉、二氧化碳、水喷雾或耐醇泡沫。不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:58', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3283, 3418, '聚合反应。与氧化剂接触猛烈反应。气体比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '切断气源。若不能切断气源，则不允许熄灭泄漏处的火焰。喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:58', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3284, 3419, '其蒸气与空气形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。 若遇高热，容器内压增大，有开裂和爆炸危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、1211灭火剂、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:58', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3285, 3420, '在火场高温下，能发生聚合放热，使容器破裂。其蒸气比空气重，能在较低处扩散到相当 远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的', '容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：抗溶性泡沫、干粉、 二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:59', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3286, 3421, '可能会通过压力安全阀泄漏出内容物。受热或接触火焰可能会产生膨胀或爆炸性分解。', '无资料', '干粉、二氧化碳或耐醇泡沫。不合适的灭火介质:避免用太强烈的水汽灭火， 因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3287, 3422, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。接触空气或在光照条件下可生成具有潜在 爆炸危险性的过氧化物。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '干粉、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3288, 3423, '其蒸气与空气形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。 遇无机酸和某些有机酸可能引起爆炸。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3289, 3424, '遇高热、明火或氧化剂，有引起燃烧的危险。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、氟化氢。', '雾状水、抗溶性泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3290, 3425, '其蒸气与空气形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氟化氢。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3291, 3426, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、干粉、二氧化碳、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3292, 3427, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、干粉、二氧化碳、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3293, 3428, '易燃液体，其蒸气与空气混合可形成爆炸性混合物。遇明火、高热极易燃烧爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。蒸气可能会移动到着火源并回闪。加热时，容器可能爆炸。', '一氧化碳、二氧化碳', '干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3294, 3429, '其蒸气与空气可形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。与氧化剂能发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '雾状水、二氧化碳、泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3295, 3430, '其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。', '一氧化碳、二氧化碳。', '砂土、泡沫、干粉、二氧化碳。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3296, 3431, '遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到 相当远的地方，遇火源引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3297, 3432, '甚至引起燃烧。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源引着回燃。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3298, 3433, '遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。', '一氧化碳、二氧化碳、氮氧化物。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3299, 3434, '遇明火、高热可燃。与氧化剂能发生强烈反应。受高热分解产生有毒的硫化物烟气。', '一氧化碳、二氧化碳、氧化硫。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3300, 3435, '遇明火、高热可燃。具有腐蚀性。受高热分解放出有毒的气体。与强氧化剂、碱类接触可发生反应。', '一氧化碳、二氧化碳。 消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：雾状水、泡沫、干粉、', '二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3301, 3436, '其蒸气与空气可形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。与氧化剂能发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。能发生聚合反应。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3302, 3437, '其蒸气与空气可形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。与氧化剂能发生强烈反应。在火场中，受热的容器有爆炸危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳', '抗溶性泡沫、干粉、二氧化碳、雾状水、1211灭火剂、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3303, 3438, '易燃液体。其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂接触发生反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。会引起静电积聚，点燃其蒸气。', '一氧化碳、二氧化碳、硫化氢、氧化硫。', '使用干粉、泡沫、二氧化碳灭火。在安全防爆距离以外，使用雾状水冷却暴露的容器。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3304, 3439, '易燃液体。其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂接触发生反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。会引起静电积聚，点燃其蒸气。', '一氧化碳、二氧化碳。', '使用干粉、泡沫、二氧化碳灭火。在安全防爆距离以外，使用雾状水冷却暴露的容器。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:07', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3305, 3440, '易燃液体和蒸气。蒸气比空气重，可能沿地面扩散，遇火源会回燃。受热分解产生有毒的硫化物气体。', '一氧化碳、二氧化碳、硫化物', '干粉、二氧化碳、泡沫。禁止使用直流水灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:08', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3306, 3441, '起容器破裂和爆炸事故。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着 火回燃。', '一氧化碳、二氧化碳。 尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:08', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3307, 3442, '较低处扩散到相当远的地方，遇明火会引着回燃。与氧化剂能发生强烈反应。若遇高热， 容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '抗溶性泡沫、二氧化碳、干粉、1211灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3308, 3443, '其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触猛烈反应。流速过快，容易产生和积聚静电。容易自聚，聚合反应随着温度的上升而急骤加剧。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3309, 3444, '其蒸气与空气可形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。与氧化剂能发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '灭火剂：抗溶性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:10', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3310, 3445, '遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '抗溶性泡沫、二氧化碳、干粉、1211灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3311, 3446, '其蒸气与空气形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。 其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压 增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、硫化氢。', '砂土、干粉、二氧化碳、泡沫、雾状水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3312, 3447, '火场中，受热的容器有爆炸危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇 火源会着火回燃。', '一氧化碳、二氧化碳。 尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的', '容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：泡沫、二氧化碳、 干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3313, 3448, '遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '抗溶性泡沫、二氧化碳、干粉、1211灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3314, 3449, '其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3315, 3450, '远的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:12', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3316, 3451, '其蒸气与空气形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。 若遇高热，可能发生聚合反应，出现大量放热规象，引起容器破裂和爆炸事故。', '一氧化碳、二氧化碳。', '砂土、泡沫、干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3317, 3452, '易燃液体，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触发生强烈反应，甚至引起燃烧。在火场中，受热的容器有爆炸危险。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '抗溶性泡沫、二氧化碳、干粉、1211灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3318, 3453, '相当远的地方，遇明火会引着回燃。若遇高热，可能发生聚合反应，出现大量放热现象，引起 容器破裂和爆炸事故。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3319, 3454, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3320, 3455, '受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、抗溶性泡沫、干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3321, 3456, '受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3322, 3457, '遇明火、高热可燃。受高热分解放出有毒的气体。与硝酸反应强烈。与强氧化剂、酸类接触可发生反应。', '一氧化碳、二氧化碳、氧化氮。', '采用雾状水、泡沫、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3323, 3458, '氮烟气。', '一氧化碳、二氧化碳、氧化氮。 尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火剂：抗溶', '性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3324, 3459, '其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源引着回燃。若遇高热，可能发生聚 合反应，出现大量放热现象，引起容器破裂和爆炸事故。', '一氧化碳、二氧化碳、氧化氮。', '泡沫、二氧化碳、1211灭火剂、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3325, 3460, '其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3326, 3461, '在空气中或阳光照射下可生成具有潜在爆炸危险性的过氧化物。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '二氧化碳、干粉、用水冷却火场容器。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3327, 3462, '容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3328, 3463, '后可因产生静电火花放电引起燃烧爆炸。其蒸气比空气重，能在较低处扩散到相当远的地 方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。处在火场中的容器若已变色或从安全', '泄压装置中产生声音，必须马上撤离。灭火剂：泡沫、二氧化碳、干粉、砂土。用水灭火 无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3329, 3464, '遇明火、高热可燃。与强氧化剂可发生反应。受热分解产生有毒的氮氧化物气体。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3330, 3465, '锰酸钾等接触，能发生强烈反应，引起燃烧或爆炸。粉体与空气可形成爆炸性混合物,当 达到一定浓度时,遇火星会发生爆炸。', '一氧化碳、二氧化碳。 采用雾状水、二氧化碳、砂土灭火。切勿将水流直接射至熔融物，以免引起严重的流淌火', '灾或引起剧烈的沸溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3331, 3466, '易燃，遇高热、明火及强氧化剂易引起燃烧。受热分解放出有毒的氧化氮烟气。', '一氧化碳、二氧化碳、氧化氮。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3332, 3467, '其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压 增大，有开裂和爆炸的危险。接触空气或在光照条件下可生成具有潜在爆炸危险性的过氧化物。', '一氧化碳、二氧化碳。', '砂土、泡沫、干粉、二氧化碳。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3333, 3468, '容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '雾状水、抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:20', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3334, 3469, '其蒸气与空气可形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。与氧化剂能发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:20', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3335, 3470, '易燃，遇明火、高热有燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:20', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3336, 3471, '遇明火、高热可燃。与强氧化剂可发生反应。受热分解放出有毒的氧化氮烟气。', '一氧化碳、二氧化碳、氧化氮。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:20', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3337, 3472, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。', '一氧化碳、二氧化碳。 尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的', '容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：抗溶性泡沫、干粉、 二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:20', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3338, 3473, '达到一定的浓度时，遇火星会发生爆炸。', '一氧化碳、二氧化碳。', '雾状水、二氧化碳、干粉、泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:22', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3339, 3474, '蒸气挥发,高温下能迅速挥发。', '一氧化碳、二氧化碳。', '尽可能将容器从火场移至空旷处。灭火剂：雾状水、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:22', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3340, 3475, '遇明火、高热、氧化剂能燃烧，并散发出有毒气体。', '一氧化碳、二氧化碳、硫化氢、氧化硫。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:22', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3341, 3476, '易燃，受热分解产生有毒气体。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氯化氢。', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:22', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3342, 3477, '遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。受高热分解产生有毒的腐蚀性气体。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氯化氢。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:22', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3343, 3478, '遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。受高热分解产生有毒的腐蚀性气体。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氯化氢、溴化氢。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:23', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3344, 3479, '易燃液体。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触猛烈反应。受热分解产生有毒的氯化氢等气体。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳、氯化氢。', '雾状水、抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:24', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3345, 3480, '受热分解产生有毒的氯化物、氮氧化物和一氧化碳气体。', '氯化氢、氮氧化物、一氧化碳、二氧化碳', '干粉、二氧化碳、耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:24', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3346, 3481, '受热分解产生有毒的氯化物、氮氧化物和一氧化碳气体。', '氯化氢、氮氧化物、一氧化碳、二氧化碳', '喷水、喷雾或使用干粉、二氧化碳、泡沫灭火剂', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:24', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3347, 3482, '遇明火、高热可燃。与强氧化剂可发生反应。受高热分解，产生有毒的氮氧化物和氯化物气体。', '一氧化碳、二氧化碳、氯化物、氧化氮。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:24', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3348, 3483, '遇明火、高热可燃。受高热分解，产生有毒的氮氧化物和氯化物气体。', '一氧化碳、二氧化碳、氧化氮。', '采用雾状水、泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3349, 3484, '会产生膨胀或爆炸性分解。遇明火、高热可燃。与强氧化剂可发生反应。受高热分解产生有毒的腐蚀性气体。', '一氧化碳、二氧化碳、氯化氢', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3350, 3485, '遇明火、高热可燃。与强氧化剂可发生反应。受高热分解产生有毒的腐蚀性气体。', '一氧化碳、二氧化碳。', '干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3351, 3486, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳、氧化氮、氯化氢。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3352, 3487, '遇明火、高热可燃。与强氧化剂、强碱接触可发生反应。受热分解产生一氧化碳、二氧化碳、氯化氢等有毒的腐蚀性气体。有腐蚀性。', '一氧化碳、二氧化碳、氯化氢。', '采用雾状水、抗溶性泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3353, 3488, '其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。受高热分解，放出有毒的烟气。有腐蚀性。若遇高热，容器内压增大，有开裂和爆炸的危险。', '-氧化碳、二氧化碳、氯化氢。', '抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3354, 3489, '遇明火、高热易燃。与氧化剂能发生强烈反应。受高热分解产生有毒的腐蚀性气体。若遇 高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氯化氢。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷 处。灭火剂：二氧化碳、泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3355, 3490, '容器可能爆炸。暴露于火中的容器可能会通过压力安全阀泄漏出内容物。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、氯化氢', '干粉、二氧化碳或耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3356, 3491, '容器可能爆炸。暴露于火中的容器可能会通过压力安全阀泄漏出内容物。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、氯化氢', '干粉、二氧化碳或耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3357, 3492, '其蒸气与空气可形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。与氧化剂能发生强烈反应。受高热分解产生有毒的氯化物气体。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氯化氢。 尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的', '容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：泡沫、二氧化碳、 干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3358, 3493, '生聚合放热，使容器破裂。遇酸性催化剂如路易斯催化剂、齐格勒催化剂、硫酸、氯化铁、氯 化铝等都能产生猛烈聚合，放出大量热量。其蒸气比空气重，能在较低处扩散到相当远的地方， 遇火源会着火回燃。对很多金属尤其是潮湿空气存在下有腐蚀性。', '一氧化碳、二氧化碳、氯化氢。 尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的容器', '若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：泡沫、二氧化碳、干粉、砂 土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3359, 3494, '生有毒的腐蚀性烟气。与氧化剂能发生强烈反应。其蒸气比空气重，能在较低处扩散到相 当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳、氯化氢。 喷水冷却容器，可能的话将容器从火场移至空旷处。处在火场中的容器若已变色或从安全', '泄压装置中产生声音，必须马上撤离。灭火剂：泡沫、干粉、二氧化碳、砂土。用水灭火 无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3360, 3495, '遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。若遇高热，容器内压增大，有开 裂和爆炸的危险。', '一氧化碳、二氧化碳、氯化氢。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷 处。灭火剂：雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:32', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3361, 3496, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3362, 3497, '遇明火、高热、氧化剂能燃烧，并散发出有毒气体。', '一氧化碳、二氧化碳、氯化氢、氟化氢。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3363, 3498, '其蒸气与空气可形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。与氧化剂能发生强烈反应。受高热分解产生有毒的腐蚀性烟气（光气、氯化氢）。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳、光气、氯化氢。', '泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3364, 3499, '遇明火、高热可燃。其粉体与空气可形成爆炸性混合物，当达到一定浓度时，遇火星会发生爆炸。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、氮氧化物、氯化氢', '尽可能将容器从火场移至空旷处。灭火剂：雾状水、泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3365, 3500, '可燃。受高热分解放出有毒的气体。与氧化剂可发生反应。', '一氧化碳、二氧化碳、氧化氮。', '采用雾状水、泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3366, 3501, '遇明火、高热可燃。受高热分解放出有毒的氰化氢气体。与强氧化剂、强还原剂、强酸、强碱接触可发生反应。', '一氧化碳、二氧化碳、氧化氮、氰化氢。', '灭火剂：水、雾状水、抗溶性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3367, 3502, '易燃，遇明火、高热能引起燃烧爆炸。与强氧化剂发生反应，可引起燃烧。', '一氧化碳、二氧化碳。', '抗溶性泡沫、雾状水、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3368, 3503, '其蒸气与空气可形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。与强氧化剂发生反应，可引起燃烧。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '抗溶性泡沫、雾状水、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3369, 3504, '爆炸的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3370, 3505, '遇明火、高热可燃。受热分解产生有毒的硫氧化物气体。', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:36', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3371, 3506, '遇高热、明火或氧化剂，有引起燃烧的危险。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氧化硫。', '抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:36', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3372, 3507, '可引起燃烧。其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若 遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '抗溶性泡沫、二氧化碳、干粉、用水冷却火场容器。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:36', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3373, 3508, '遇明火、高热可燃。受热分解产生有毒气体。', '一氧化碳、二氧化碳、氮氧化物、氟化氢', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:36', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3374, 3509, '遇高热、明火或氧化剂，有引起燃烧的危险。有腐蚀性。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3375, 3510, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3376, 3511, '遇高热、明火或氧化剂，有引起燃烧的危险。', '一氧化碳、二氧化碳。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3377, 3512, '生强烈反应。在火场中，受热的容器有爆炸危险。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：抗溶性泡沫、干粉、二氧化', '碳、1211灭火剂、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3378, 3513, '易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂能发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：抗溶性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3379, 3514, '器有爆炸危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的', '容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：泡沫、二氧化碳、 干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:39', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3380, 3515, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。不合适的灭火介质:避免用太强烈的水汽灭火， 因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当', '的)）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表 和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3381, 3516, '遇明火、高热可燃。与强氧化剂可发生反应。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、氧化氮。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷 处。灭火剂：雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3382, 3517, '可燃，遇明火、高热可燃。受热分解产生有毒气体。', '一氧化碳、二氧化碳、氮氧化物', '干粉、二氧化碳或耐醇泡沫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3383, 3518, '遇明火、高热可燃。受热分解放出有毒的氧化氮烟气。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、氧化氮。', '采用水、泡沫、干粉、二氧化碳灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3384, 3519, '遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。受热分解放出有毒的氧化氮烟气。', '一氧化碳、二氧化碳、氧化氮。', '采用雾状水、泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3385, 3520, '受热分解产生有毒的腐蚀性烟气。', '一氧化碳、二氧化碳、氮氧化物、氯化氢、氧化硫。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3386, 3521, '遇明火能燃烧。受高热分解放出有毒的气体。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、氧化氮。', '采用雾状水、泡沫、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3387, 3522, '遇水反应，放出具有刺激性和腐蚀性的氯化氢气体。蒸馏残留物可能发生爆炸。受高热 分解，放出有毒的烟气。', '-氧化碳、二氧化碳、氮氧化物、氯化氢。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3388, 3523, '遇明火、高热可燃。受热分解产生有毒的氮氧化物气体。与氧化剂接触有燃烧爆炸的危险。', '一氧化碳、二氧化碳、氧化氮。', '采用雾状水、泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3389, 3524, '可燃，受热可能发生爆炸性分解。遇明火、高热可燃。', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:43', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3390, 3525, '遇明火能燃烧。受高热分解放出有毒的气体。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、氧化氮。', '采用雾状水、泡沫、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:43', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3391, 3526, '易燃液体，蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。受热分解产生有毒的氮氧化物气体。与氧化剂接触猛烈反应。胺类及三氯化铝、六甲基苯等均能引起燃烧爆炸。', '一氧化碳、二氧化碳、氮氧化物。', '水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:43', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3392, 3527, '遇明火能燃烧。受高热分解放出有毒的气体。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、氮氧化物、碘化氢。', '采用雾状水、泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:43', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3393, 3528, '从而增加火势和/或蒸气的浓度。蒸气可能会移动到着火源并回闪。液体和蒸气易燃。加 热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、氧化氮', '干粉、二氧化碳、耐醇泡沫。避免使用直流水灭火，以免火势蔓延。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3394, 3529, '遇明火、高热可燃。受热分解产生有毒的氮氧化物气体。与氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、氧化氮。', '泡沫、雾状水、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3395, 3530, '遇明火、高热可燃。受高热分解放出有毒的气体。与强氧化剂、强还原剂、强碱接触可发生反应。', '一氧化碳、二氧化碳、氧化氮', '泡沫、干粉、二氧化碳、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3396, 3531, '遇明火、高热易燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3397, 3532, '遇明火、高热可燃。与强氧化剂可发生反应。受高热分解，产生有毒的氮氧化物和氯化物气体。有腐蚀性。', '一氧化碳、二氧化碳、氧化氮、氯化氢。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3398, 3533, '遇明火、高热可燃。与强氧化剂可发生反应。受高热分解，产生有毒的氮氧化物和氯化物 气体。', '一氧化碳、二氧化碳、氯化氢、氧化氮。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3399, 3534, '本品与空气可形成爆炸性混合物，当达到一定浓度时，遇火星会发生爆炸。受热分解放出有毒的氧化氮烟气。', '一氧化碳、二氧化碳、氧化氮。', '雾状水、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3400, 3535, '遇明火能燃烧。受高热分解放出有毒的气体。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、氧化氮、溴化氢。', '采用雾状水、泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3401, 3536, '易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈 反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。处在火场中的容器若已变色或从安全泄压', '装置中产生声音，必须马上撤离。灭火剂：泡沫、干粉、二氧化碳、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3402, 3537, '的危险。', '一氧化碳、二氧化碳。', '泡沫、抗溶性泡沫、干粉、砂土、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3403, 3538, '烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '喷水冷却容器，可能的话将容器从火场移至空旷处。处在火场中的容器若已变色或从安全泄压装 置中产生声音，必须马上撤离。灭火剂：泡沫、干粉、二氧化碳、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3404, 3539, '遇明火、高热、氧化剂能燃烧，并散发出有毒气体。', '一氧化碳、二氧化碳、溴化氢。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:50', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3405, 3540, '从而增加火势和/或蒸气的浓度。蒸气可能会移动到着火源并回闪。液体和蒸气易燃。加 热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3406, 3541, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、溴化氢。', '泡沫、二氧化碳、水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3407, 3542, '遇明火、高热易燃。受高热分解产生有毒的溴化物气体。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、溴化氢。', '采用雾状水、抗溶性泡沫、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3408, 3543, '体。有腐蚀性。受高热分解，放出高毒的烟气。', '一氧化碳、二氧化碳、氯化氢、溴化氢、光气。', '抗溶性泡沫、二氧化碳、干粉。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:52', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3409, 3544, '遇明火、高热可燃。受高热分解产生有毒的溴化物气体。', '一氧化碳、二氧化碳、溴化氢。', '雾状水、抗溶性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3410, 3545, '其蒸气与空气可形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。与氧化剂能发生强烈反应。受高热分解产生有毒的溴化物气体。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳、溴化氢。', '尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：雾状水、泡沫、干粉、二氧化碳、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3411, 3546, '遇明火、高热可燃。遇水反应发热放出有毒的腐蚀性气体。', '一氧化碳、二氧化碳、溴化氢。', '砂土、二氧化碳、干粉。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3412, 3547, '从而增加火势和/或蒸气的浓度。蒸气可能会移动到着火源并回闪。液体和蒸气易燃。加 热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3413, 3548, '遇明火、高热可燃。受热分解产生有毒气体。', '一氧化碳、二氧化碳、溴化氢。', '采用泡沫、干粉、砂土灭火。用水可引起沸溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3414, 3549, '其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内 压增大，有开裂和爆炸的危险。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、溴化氢。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3415, 3550, '遇明火易燃。受高热燃烧并分解产生有毒气体。', '一氧化碳、二氧化碳、溴化氢。', '水、抗溶性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3416, 3551, '其蒸气与空气形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反 应。接触空气或在光照条件下可生成具有潜在爆炸危险性的过氧化物。其蒸气比空气重， 能在较低处扩散到相当远的地方，遇火源引着回燃。若遇高热，容器内压增大，有开裂和 爆炸的危险。', '一氧化碳、二氧化碳、溴化氢。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。不合适的灭火介质:避免用太强烈的水汽灭火， 因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当', '的)）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表 和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3417, 3552, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3418, 3553, '遇明火、高热能引起燃烧爆炸。与强氧化剂发生反应，可引起燃烧。若遇高热，容器内压增大， 有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '二氧化碳、泡沫、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:56', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3419, 3554, '其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。遇高热能发生聚合反应，出现大量放热现象，引起容器破裂或爆炸事故。', '一氧化碳、二氧化碳。', '干粉、二氧化碳或耐醇泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3420, 3555, '遇明火、高热易燃。受热分解放出有毒的氧化氮烟气。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、氧化氮。', '采用泡沫、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3421, 3556, '扩散到相当远的地方，遇明火会引着回燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3422, 3557, '热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氮氧化物。', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3423, 3558, '其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。', '一氧化碳、二氧化碳。', '抗溶性泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:59', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3424, 3559, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。', '一氧化碳、二氧化碳、氧化氮。 用水喷射逸出液体，使其稀释成不燃性混合物，并用雾状水保护消防人员。灭火剂：水、干粉、', '二氧化碳、抗溶性泡沫、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:59', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3425, 3560, '或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:59', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3426, 3561, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。受热分解释放出有毒气体。', '氮氧化物、一氧化碳、二氧化碳。', '泡沫、砂土、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:59', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3427, 3562, '爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:59', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3428, 3563, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3429, 3564, '遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。燃烧分解时，放出有毒的氮氧化物。', '一氧化碳、二氧化碳、氮氧化物。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:01', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3430, 3565, '火焰都可能引起火灾和爆炸。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、氮氧化物等有毒气体', '干粉、二氧化碳或耐醇泡沫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:01', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3431, 3566, '该物质为自反应物质B型，遇热、摩擦、撞击或接触火焰可能发生爆炸性分解。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。与还原剂、强酸、强碱、金属粉末、有机物等接触可能发生剧烈反应。在封闭空间内可能发生爆炸。', '一氧化碳、二氧化碳、氮氧化物、氯化氢、硫氧化物、氯化氢气体', '干粉、二氧化碳、耐醇泡沫。大量水雾可用于冷却容器。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:01', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3432, 3567, '遇明火、高热可燃。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '受热分解产生氮氧化物、硫氧化物、一氧化碳、二氧化碳等有毒气体。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:01', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3433, 3568, '遇明火、高热可燃。受热分解产生有毒气体。火焰都可能引起火灾和爆炸。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '受热分解产生氮氧化物、硫氧化物、氯化氢等有毒气体。', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3434, 3569, '遇明火、高热可燃。受高热分解，放出有毒的烟气。与强氧化剂可发生反应。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3435, 3570, '不易燃烧。受高热分解，放出高毒的烟气。与强氧化剂可发生反应。', '一氧化碳、二氧化碳、氮氧化物、氧化硫。', '泡沫、抗溶性泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3436, 3571, '遇明火、高热可燃。受热分解产生有毒的氮氧化物、一氧化碳、二氧化碳等气体。', '一氧化碳、二氧化碳、氮氧化物。', '泡沫、抗溶性泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3437, 3572, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、氮氧化物等有毒烟雾。', '合适的灭火介质：干粉、二氧化碳、耐醇泡沫或水喷雾。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3438, 3573, '接触火焰可能会产生膨胀或爆炸性分解。受热可能分解产生有毒气体。', '一氧化碳、二氧化碳、醛类、酮类等有毒气体', '合适的灭火介质：使用大量水、雾状水、抗溶性泡沫、干粉、二氧化碳。不合适的灭火介质：避免使用直流水冲击，可能导致火势蔓延。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3439, 3574, '遇明火、高热可燃。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、氮氧化物、氯化氢。', '泡沫、二氧化碳、干粉、水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3440, 3575, '遇高热、明火或氧化剂，有引起燃烧的危险。有腐蚀性。', '一氧化碳、二氧化碳、氮氧化物。', '抗溶性泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3441, 3576, '易燃，受热、摩擦、撞击或与杂质接触可能发生爆炸。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、醛类、酮类等有毒气体。', '尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3442, 3577, '接触火焰可能会产生膨胀或爆炸性分解。受热分解产生有毒气体。遇明火、高热极易燃烧爆炸。', '一氧化碳、二氧化碳', '合适的灭火介质：大量水、干粉灭火剂。不合适的灭火介质：禁止使用泡沫、二氧化碳、蒸汽等惰性气体灭火，因为有机过氧化物会放出氧而加剧火势。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:08', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3443, 3578, '高度易燃，其蒸气与空气混合，能形成爆炸性混合物。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳', '干粉、二氧化碳或耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:08', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3444, 3579, '蒸气可能会移动到着火源并回闪。液体和蒸气易燃。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳。', '干粉、二氧化碳或耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:08', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3445, 3580, '易燃，其蒸气与空气混合，能形成爆炸性混合物。遇明火、高热极易燃烧爆炸。与氧化剂能发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3446, 3581, '其蒸气与空气形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。 接触空气或在光照条件下可生成具有潜在爆炸危险性的过氧化物。其蒸气比空气重，能在较低 处扩散到相当远的地方，遇火源引着回燃。若遇高热，可能发生聚合反应，出现大量放热现象， 引起容器破裂和爆炸事故。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3447, 3582, '遇高热、明火或氧化剂，有引起燃烧的危险。有腐蚀性。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3448, 3583, '危险。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。', '抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:10', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3449, 3584, '其蒸气与空气混合，能形成爆炸性混合物。遇明火、高热极易燃烧爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳', '干粉、二氧化碳或耐醇泡沫。灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3450, 3585, '高度易燃液体。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。受热分解产生有毒烟雾。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3451, 3586, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳、氧化氮、氰化氢。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3452, 3587, '发生化学反应。', '一氧化碳、二氧化碳、氧化氮、氯化氢。', '采用雾状水、泡沫、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3453, 3588, '遇明火、高热可燃。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、氯化氢。', '泡沫、二氧化碳、砂土、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3454, 3589, '受热或接触火焰可能会产生膨胀或爆炸性分解。', '受热分解产生有毒的氮氧化物、氯化物、硫氧化物气体。', '干粉、二氧化碳或耐醇泡沫。不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3455, 3590, '遇明火、高热可燃。受高热分解产生有毒的腐蚀性烟气。', '一氧化碳、二氧化碳、氯化氢。', '抗溶性泡沫、二氧化碳、干粉。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3456, 3591, '遇明火能燃烧。受高热分解产生有毒的腐蚀性烟气。', '一氧化碳、二氧化碳、氯化氢。', '采用雾状水、泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3457, 3592, '遇明火、高热可燃。与强氧化剂可发生反应。受高热分解，产生有毒的氮氧化物和氯化物气体。', '一氧化碳、二氧化碳、氧化氮、氯化氢。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3458, 3593, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:15', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3459, 3594, '遇高热、明火或氧化剂，有引起燃烧的危险。有腐蚀性。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:15', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3460, 3595, '遇明火、高热可燃。与氧化剂可发生反应。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:15', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3461, 3596, '遇明火、高热可燃。受热分解产生有毒的氯化氢气体。', '氯化氢、一氧化碳、二氧化碳。', '干粉、二氧化碳或耐醇泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3462, 3597, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。受热分解产生有毒的氮氧化物烟气。', '一氧化碳、二氧化碳、氧化氮。', '尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火剂：抗溶性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3463, 3598, '其蒸气与空气形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土、1211灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3464, 3599, '遇明火、高热可燃。受热分解产生有毒的氯化氢和氮氧化物烟雾。', '氯化氢、氮氧化物、一氧化碳', '干粉、二氧化碳、泡沫。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3465, 3600, '遇明火、高热可燃。受热分解产生有毒的氮氧化物气体。与氧化剂可发生反应。', '一氧化碳、二氧化碳、氧化氮。', '采用雾状水、泡沫、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3466, 3601, '遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。', '一氧化碳、二氧化碳、氮氧化物、氯化氢。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:17', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3467, 3602, '遇明火、高热可燃。受高热分解，放出有毒的氮、溴化物烟气。', '一氧化碳、二氧化碳、氧化氮、溴化氢。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3468, 3603, '受热、撞击、摩擦可能引起爆炸。接触火焰可能会产生膨胀或爆炸性分解。与还原剂、有机物、易燃物等接触可能发生剧烈反应。具有强氧化性，遇可燃物易着火并助长火势。', '一氧化碳、二氧化碳、醛类、酮类等有毒烟雾。', '合适的灭火介质：大量水、水雾、泡沫、二氧化碳、干粉。不合适的灭火介质：禁止使用直流水冲击，以免引起飞溅或爆炸。灭火注意事项：消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。切勿将水流直接射入熔融液体，以免引起严重的流淌火灾或剧烈沸腾。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3469, 3604, '遇明火、高热可燃。与强氧化剂可发生反应。受高热分解放出有毒的氰化物和氮氧化物气体。', '一氧化碳、二氧化碳、氰化氢、氧化氮。', '雾状水、泡沫、二氧化碳、干粉、砂土。禁止使用酸碱灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3470, 3605, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、氮氧化物等有毒烟雾。', '合适的灭火介质：干粉、二氧化碳、耐醇泡沫或水喷雾。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3471, 3606, '遇明火、高热可燃。受热分解产生有毒烟雾。与氧化剂接触可能发生剧烈反应。', '受热分解产生氮氧化物（NOx）、一氧化碳（CO）、二氧化碳（CO2）等有害气体。', '合适的灭火介质：干粉、二氧化碳、耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:20', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3472, 3607, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、溴化氢。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:20', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3473, 3608, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、溴化氢。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:20', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3474, 3609, '遇明火、高热可燃。受热分解放出有毒的氧化氮烟气。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、抗溶性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:20', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3475, 3610, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、氰化氢。', '雾状水、抗溶性泡沫、二氧化碳、干粉。禁止使用酸碱灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:20', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3476, 3611, '遇明火、高热可燃。受热分解放出有毒的砷和氧化氮烟雾。受高热或接触酸或酸雾放出剧毒的烟雾。', '砷的氧化物、氮氧化物、一氧化碳、二氧化碳。', '干粉、二氧化碳、耐醇泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3477, 3612, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:22', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3478, 3613, '危险。燃烧时，放出剧毒的氰化氢气体。在火场高温下，能发生聚合放热，使容器破裂。 在酸性催化剂存在下能猛烈聚合爆炸。具有腐蚀性。', '一氧化碳、二氧化碳、氧化氮、氰化氢。', '灭火剂：抗溶性泡沫、二氧化碳、干粉、砂土。喷水冷却容器，可能的话将容器从火场移至空旷处。处在火场中的容器若已变色或从安全泄压装置中产生声音，必须马上撤离。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:22', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3479, 3614, '遇明火、高热可燃。受热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:22', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3480, 3615, '遇明火、高热、氧化剂能燃烧，并散发出有毒气体。', '一氧化碳、二氧化碳、碘化氢。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:22', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3481, 3616, '蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压增 大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:24', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3482, 3617, '蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的容器若 已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：抗溶性泡沫、干粉、二氧化碳、 砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3483, 3618, '遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到 相当远的地方，遇火源引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氧化氮、氰化氢。', '泡沫、二氧化碳、砂土。禁止使用酸碱灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3484, 3619, '受热分解，放出有毒的烟气。与氧化剂可发生反应。', '一氧化碳、二氧化碳、氮氧化物、溴化氢。', '根据周围环境选择合适的灭火剂。小火：干粉、二氧化碳。大火：抗溶性泡沫、雾状水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3485, 3620, '无资料', '无资料 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。', '不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3486, 3621, '遇明火、高热可燃。受热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、氟化氢。', '雾状水、抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3487, 3622, '其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源引着回燃。若遇高热，容器内压增 大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氟化氢。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3488, 3623, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。', '一氧化碳、二氧化碳。', '喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3489, 3624, '易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触猛烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '泡沫、干粉、二氧化碳、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3490, 3625, '生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '喷水冷却容器，可能的话将容器从火场移至空旷处。处在火场中的容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：泡沫、干粉、二氧化碳、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3491, 3626, '易燃，遇高热、明火有引起燃烧的危险。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳。', '喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3492, 3627, '遇明火、高热、或与氧化剂接触能燃烧, 并散发出有毒气体。', '一氧化碳、二氧化碳、硫化氢、氧化硫。', '采用抗溶性泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3493, 3628, '遇明火、高热可燃。具有腐蚀性。受高热分解放出有毒的气体。与强氧化剂、碱类接触可发生反应。', '一氧化碳、二氧化碳。 消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：雾状水、泡沫、干粉、', '二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3494, 3629, '生强烈反应。在火场中，受热的容器有爆炸危险。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：抗溶性泡沫、干粉、二氧化', '碳、1211灭火剂、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3495, 3630, '硫氧化物气体。与强氧化剂发生反应,可引起燃烧。', '一氧化碳、二氧化碳、硫化氢、氧化硫。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：泡沫、二氧化碳、干粉、砂', '土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3496, 3631, '合反应，出现大量放热现象，引起容器破裂和爆炸事故。高速冲击、流动、激荡后可因产生静 电火花放电引起燃烧爆炸。', '一氧化碳、二氧化碳。', '泡沫、干粉、二氧化碳、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3497, 3632, '若遇高热，可能发生聚合反应，出现大量放热现象，引起容器破裂和爆炸事故。', '一氧化碳、二氧化碳。', '砂土、泡沫、干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3498, 3633, '发生聚合反应，出现大量放热现象，引起容器破裂或爆炸事故。', '一氧化碳、二氧化碳。', '抗溶性泡沫、二氧化碳、干粉、用水冷却火场容器。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3499, 3634, '若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。 消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷', '处。喷水保持火场容器冷却，直至灭火结束。处在火场中的容器若已变色或从安全泄压装 置中产生声音，必须马上撤离。灭火剂：雾状水、泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3500, 3635, '生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的', '尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：抗溶性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3501, 3636, '易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂能发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。（来源：检索补充）', '一氧化碳、二氧化碳。（来源：检索补充）', '消防人员须穿全身消防服，佩戴防毒面具，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火剂：泡沫、二氧化碳、干粉、砂土。用水灭火无效。（来源：检索补充）', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3502, 3637, '其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压 增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3503, 3638, '量放热现象，引起容器破裂或爆炸事故。具有强腐蚀性。', '一氧化碳、二氧化碳。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3504, 3639, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '抗溶性泡沫、二氧化碳、干粉、1211灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3505, 3640, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3506, 3641, '遇明火、高热可燃。受高热分解放出有毒的气体。与强氧化剂、酸类接触可发生反应。', '一氧化碳、二氧化碳、氧化氮。', '采用雾状水、泡沫、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3507, 3642, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、氮氧化物、氰化氢', '合适的灭火介质:干粉、二氧化碳、水喷雾或耐醇泡沫。不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3508, 3643, '氮烟气。', '一氧化碳、二氧化碳、氧化氮。 尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火剂：抗溶', '性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3509, 3644, '易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂能发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '抗溶性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:36', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3510, 3645, '与空气混合能形成爆炸性混合物，遇明火、高热极易燃烧爆炸。是非常活泼的物质，容易产生 聚合。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:36', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3511, 3646, '从而增加火势和/或蒸气的浓度。蒸气可能会移动到着火源并回闪。液体和蒸气易燃。 加 热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:36', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3512, 3647, '其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压 增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '砂土、泡沫、干粉、二氧化碳。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:36', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3513, 3648, '的危险。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:36', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3514, 3649, '远的地方，遇火源引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、硫化氢、氧化硫。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:37', '', NULL);
