INSERT INTO `msds_fire_fighting` VALUES (3519, 3654, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、雾状水、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3520, 3655, '遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3521, 3656, '遇明火、高热易燃。受高热分解，放出有毒的烟气。', '-氧化碳、二氧化碳、氯化氢。', '雾状水、抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3522, 3657, '遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。受高热分解产生有毒的腐蚀性 气体。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氯化氢。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷 处。灭火剂：泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3523, 3658, '其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂能发生强烈反应。若遇高热，可能发生聚合反应，出现大量放热现象，引起容器破裂和爆炸事故。', '一氧化碳、二氧化碳、氯化氢。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3524, 3659, '可能发生聚合反应，出现大量放热现象，引起容器破裂和爆炸事故。', '一氧化碳、二氧化碳、氯化氢。', '砂土、泡沫、干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3525, 3660, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、氯化氢。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3526, 3661, '遇明火、高热可燃。受高热分解，产生有毒的氮氧化物和氯化物气体。', '一氧化碳、二氧化碳、氧化氮、氯化氢。', '采用雾状水、泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3527, 3662, '遇明火、高热可燃。受高热分解产生有毒的腐蚀性烟气。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、氯化氢。', '采用雾状水、泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3528, 3663, '接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、氯化氢等', '合适的灭火介质：使用适合火灾类型的合适的灭火剂（如干粉、二氧化碳、泡沫）。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3529, 3664, '遇明火、高热、或与氧化剂接触能燃烧, 并散发出有毒气体。具有腐蚀性。', '一氧化碳、二氧化碳、氯化氢。', '采用雾状水、抗溶性泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:44', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3530, 3665, '遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。具有腐蚀性。', '一氧化碳、二氧化碳、氯化氢。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:44', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3531, 3666, '其蒸气与空气可形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。与氧化剂能发生强烈反应。遇酸性催化剂如路易斯催化剂、齐格勒催化剂、硫酸、氯化铁、氯化铝等都能产生猛烈聚合，放出大量热量，使容器破裂。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳、氯化氢。', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3532, 3667, '遇明火、高热易燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氯化氢、氟化氢。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:46', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3533, 3668, '遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。若遇高热，容器内压增大，有开 裂和爆炸的危险。', '一氧化碳、二氧化碳、氯化氢。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷 处。灭火剂：雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:46', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3534, 3669, '遇高热、明火或氧化剂，有引起燃烧的危险。遇水或高热能放出大量有毒的气体。', '一氧化碳、二氧化碳、氯化氢、氟化氢。', '雾状水、抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:46', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3535, 3670, '遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氧化氮、氯化氢。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。灭火剂：雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:46', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3536, 3671, '接触火焰可能会产生膨胀或爆炸性分解。遇明火、高热有引起燃烧爆炸的危险。受热分解产生有毒气体。', '一氧化碳、二氧化碳、有机过氧化物分解产物', '合适的灭火介质：泡沫、二氧化碳、干粉、砂土。不合适的灭火介质：禁止用水直接灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:48', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3537, 3672, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:48', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3538, 3673, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。若遇高热，容器内压增大，有开裂和 爆炸的危险。', '一氧化碳、二氧化碳。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷 处。灭火剂：雾状水、泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:48', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3539, 3674, '可引起燃烧。其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若 遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '抗溶性泡沫、二氧化碳、干粉、用水冷却火场容器。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3540, 3675, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、氟化氢。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷 处。灭火剂：雾状水、抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:50', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3541, 3676, '易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂能发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：抗溶性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:50', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3542, 3677, '遇明火、高热可燃。受高热分解放出有毒的气体。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、氧化氮。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：泡沫、雾状水、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:50', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3543, 3678, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。不合适的灭火介质:避免用太强烈的水汽灭火， 因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当', '的)）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表 和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:50', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3544, 3679, '爆炸性分解。', '一氧化碳、二氧化碳、氮氧化物、氯化氢、氟化氢。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:52', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3545, 3680, '或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:52', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3546, 3681, '遇明火、高热可燃。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:52', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3547, 3682, '遇明火、高热可燃。受热分解放出有毒的氧化氮烟气。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、氧化氮。', '采用水、泡沫、干粉、二氧化碳灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:52', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3548, 3683, '遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。受热分解放出有毒的氧化氮烟气。', '一氧化碳、二氧化碳、氧化氮。', '采用雾状水、泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:52', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3549, 3684, '遇明火、高热可燃。遇潮时对大多数金属有腐蚀性。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、氮氧化物、氯化氢、氧化硫', '干粉、二氧化碳或耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3550, 3685, '遇明火能燃烧。受高热分解放出有毒的气体。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、氧化氮。', '采用雾状水、泡沫、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:54', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3551, 3686, '氢气体。遇潮时对大多数金属有腐蚀性。受高热分解，放出高毒的烟', '一氧化碳、二氧化碳、氯化氢、光气。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。不合适的灭火介质:避免用太强烈的水汽灭火， 因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当', '的)）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表 和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:54', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3552, 3687, '遇明火、高热可燃。受热分解释放出有毒的氮氧化物。与氧化剂混合能形成爆炸性混合物。经摩擦、震动或撞击可引起燃烧或爆炸。', '一氧化碳、二氧化碳、氧化氮。', '采用雾状水、泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:54', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3553, 3688, '爆炸性分解。受热分解产生有毒的砷氧化物和氮氧化物气体。', '砷氧化物、氮氧化物。', '干粉、二氧化碳、耐醇泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:54', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3554, 3689, '火焰都可能引起火灾和爆炸。燃烧时可能会释放毒性烟雾。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、氮氧化物等（来源：检索补充）', '合适的灭火介质：使用大量的水冲刷灭火。如果没有水，使用干式化学灭火剂或沙土等。不合适的灭火介质：二氧化碳，因为它对此类火灾基本无效。（来源：检索补充）', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:56', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3555, 3690, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、碘化氢。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫不合适的灭火介质:避免用太强烈的水汽灭火， 因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当', '的)）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表 和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:56', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3556, 3691, '易燃，遇明火、高热可燃。受热分解放出有毒的气体。', '一氧化碳、二氧化碳、氧化氮', '泡沫、干粉、二氧化碳、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:56', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3557, 3692, '遇明火、高热可燃。与强氧化剂可发生反应。受高热分解，产生有毒的氮氧化物和氯化物 气体。', '一氧化碳、二氧化碳、氯化氢、氧化氮。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷 处。灭火剂：泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:56', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3558, 3693, '遇明火、高热可燃。与强氧化剂可发生反应。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、溴化氢、氧化氮。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:56', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3559, 3694, '遇明火、高热易燃。受高热分解产生有毒的烟雾。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水冷却容器，可能的话将容器从火场移至空旷处。处在火场中的容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：泡沫、干粉、二氧化碳、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3560, 3695, '易燃液体和蒸气。遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳', '使用泡沫、干粉、二氧化碳或砂土灭火。用水灭火无效。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水冷却容器，使温度低于物质的闪点。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:58', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3561, 3696, '遇明火、高热、氧化剂能燃烧，并散发出有毒气体。', '一氧化碳、二氧化碳、溴化氢。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:58', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3562, 3697, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。受高热分解产生有毒的溴 化物气体。在酸、碱、水分等催化剂存在下，能发生聚合放热反应。', '一氧化碳、二氧化碳、溴化氢。', '采用抗溶性泡沫、二氧化碳、干粉、砂土灭火。消防人员须在有防爆掩蔽处操作。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:58', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3563, 3698, '易燃液体。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳、溴化氢。', '尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：雾状水、泡沫、干粉、二氧化碳、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:58', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3564, 3699, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、溴化氢。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷 处。灭火剂：雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3565, 3700, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、溴化氢。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷 处。灭火剂：抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3566, 3701, '遇明火、高热、氧化剂能燃烧，并散发出有毒气体。', '一氧化碳、二氧化碳、氮氧化物、溴化氢。', '干粉、二氧化碳、耐醇泡沫。（来源：检索补充）', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3567, 3702, '若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、溴化氢。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3568, 3703, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。受高热分解产生有毒的溴化物气体。', '一氧化碳、二氧化碳、溴化氢。', '雾状水、泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3569, 3704, '遇明火、高热可燃。受热分解产生有毒的溴化氢气体。与水反应剧烈，产生腐蚀性烟雾。与氧化剂可发生反应。', '溴化氢、一氧化碳、二氧化碳', '用干粉、二氧化碳、砂土灭火。禁止用水灭火。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:01', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3570, 3705, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、溴化氢。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3571, 3706, '易燃，其蒸气与空气混合，能形成爆炸性混合物。蒸气可能会移动到着火源并回闪。液体和蒸气易燃。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳。', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3572, 3707, '易燃，其蒸气与空气混合，能形成爆炸性混合物。蒸气可能会移动到着火源并回闪。液体和蒸气易燃。加热时，容器可能爆炸。暴露于火中的容器可能会通过压力安全阀泄漏出内容物。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳。', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3573, 3708, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3574, 3709, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3575, 3710, '遇明火、高热可燃。受热分解产生有毒的氮氧化物和一氧化碳气体。', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '消防人员须穿全身消防服，佩戴空气呼吸器，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3576, 3711, '遇明火、高热可燃。受热分解产生有毒的氯化氢和氧化氮气体。', '氯化氢、氧化氮', '干粉、二氧化碳、耐醇泡沫。禁止使用直流水灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3577, 3712, '气。', '一氧化碳、二氧化碳、氯化物。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3578, 3713, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3579, 3714, '遇明火、高热可燃。与强氧化剂可发生反应。受热分解放出有毒的氧化氮烟气。', '一氧化碳、二氧化碳、氧化氮。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3580, 3715, '其蒸气与空气形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反 应。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '二氧化碳、干粉、泡沫、1211灭火剂、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3581, 3716, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3582, 3717, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳', '合适的灭火介质：泡沫、干粉、二氧化碳、砂土。不合适的灭火介质：禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3583, 3718, '混合物。干燥状态下，受摩擦、震动、撞击可引起爆炸。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。', '泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3584, 3719, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。遇明火、高热、摩擦、震动有引起燃烧爆炸的危险。', '一氧化碳、二氧化碳、氮氧化物', '使用水、泡沫、二氧化碳、干粉灭火剂。禁止使用直流水冲击泄漏物。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:07', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3585, 3720, '易燃。受撞击、摩擦，遇明火或其他点火源有爆炸危险。受热分解产生有毒的氮氧化物气体。', '一氧化碳、二氧化碳、氮氧化物、氧化钠。', '雾状水、泡沫、二氧化碳、砂土。禁止使用直流水冲击。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:08', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3586, 3721, '遇明火、高热可燃。受热分解产生有毒的氮氧化物和一氧化碳等气体。', '氮氧化物、一氧化碳、二氧化碳', '泡沫、干粉、二氧化碳、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:08', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3587, 3722, '遇明火、高热可燃。受热分解产生有毒气体。', '一氧化碳、二氧化碳、氮氧化物、氰化氢', '干粉、二氧化碳、耐醇泡沫、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:08', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3588, 3723, '遇明火、高热可燃。受热分解产生有毒的氮氧化物、一氧化碳等气体。', '一氧化碳、二氧化碳、氮氧化物', '干粉、二氧化碳、耐醇泡沫。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3589, 3724, '遇明火、高热可燃。受热分解产生有毒的氮氧化物和一氧化碳气体。', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3590, 3725, '遇明火、高热可燃。与强氧化剂可发生反应。受热分解放出有毒的氧化氮烟气。', '一氧化碳、二氧化碳、氧化氮。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3591, 3726, '遇明火、高热可燃。受热分解放出有毒的氧化氮烟气。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、氧化氮。', '采用雾状水、抗溶性泡沫、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3592, 3727, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳、氧化氮。', '雾状水、泡沫、二氧化碳、于粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:10', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3593, 3728, '遇明火、高热可燃。受热分解放出有毒的砷和氧化氮烟雾。受高热或接触酸或酸雾放出剧 毒的烟雾。', '一氧化碳、二氧化碳、氮氧化物、氧化砷。', '采用雾状水、泡沫、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3594, 3729, '不易燃烧。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、砷。', '雾状水、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3595, 3730, '遇明火、高热可燃。受热分解放出有毒的氧化氮烟气。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、氧化氮。', '采用泡沫、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3596, 3731, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、抗溶性泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3597, 3732, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:12', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3598, 3733, '遇明火、高热可燃。受热分解放出有毒的氧化氮烟气。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、氧化氮。', '采用水、抗溶性泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:12', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3599, 3734, '易燃液体和蒸气。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。受热分解产生有毒的烟雾。与氧化剂接触猛烈反应。流速过快容易产生和积聚静电。加热时，容器可能爆炸。', '一氧化碳、二氧化碳', '干粉、二氧化碳、泡沫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:12', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3600, 3735, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:12', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3601, 3736, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、碘化氢。', '雾状水、抗溶性泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:12', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3602, 3737, '爆炸性分解。', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3603, 3738, '都可能引起火灾和爆炸。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸 性分解。', '一氧化碳、二氧化碳、氮氧化物、氯化氢', '泡沫、二氧化碳、干粉、砂土。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3604, 3739, '遇明火、高热可燃。受高热分解放出有毒的气体。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、氧化氮、氟化氢。', '灭火剂：雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3605, 3740, '遇明火、高热可燃。受热分解放出有毒的氟化物气体。', '一氧化碳、二氧化碳、氟化氢。', '灭火剂：水、雾状水、抗溶性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3606, 3741, '其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂能发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳、氟化氢。', '喷水冷却容器，可能的话将容器从火场移至空旷处。处在火场中的容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3607, 3742, '流速过快，容易产生和积聚静电。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：雾状水、泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3608, 3743, '爆炸性分解。', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3609, 3744, '遇明火、高热可燃。受高热分解放出有毒的气体。与氧化剂可发生反应。', '一氧化碳、二氧化碳、氧化硫。', '采用抗溶性泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3610, 3745, '遇明火、高热可燃。具有腐蚀性。受高热分解放出有毒的气体。与强氧化剂、碱类接触可发生反应。', '一氧化碳、二氧化碳。 消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：雾状水、泡沫、干粉、', '二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3611, 3746, '其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器 内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '抗溶性泡沫、二氧化碳、干粉、用水冷却火场容器。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3612, 3747, '其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。在使用和贮存过程中， 易发生自聚反应，酿成事故。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:17', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3613, 3748, '其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '抗溶性泡沫、砂土、泡沫、干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3614, 3749, '易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂能发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的容器若已变色或从安全泄压装置中发出声音，必须马上撤离。灭火剂：抗溶性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3615, 3750, '其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压 增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3616, 3751, '其蒸气与空气形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。 其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压 增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '抗溶性泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3617, 3752, '遇明火、高热可燃。受高热分解放出有毒的气体。与强氧化剂、酸类接触可发生反应。', '一氧化碳、二氧化碳、氧化氮。', '采用雾状水、泡沫、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3618, 3753, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、氰化物。', '泡沫、二氧化碳、干粉、砂土。禁止使用酸碱灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3619, 3754, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。若遇高热，可发生聚合反应，放出大量热量而引起容器破裂和爆炸事故。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3620, 3755, '从而增加火势和/或蒸气的浓度。蒸气可能会移动到着火源并回闪。液体和蒸气易燃。加 热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3621, 3756, '容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3622, 3757, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:20', '', NULL);
