INSERT INTO `msds_fire_fighting` VALUES (3627, 3762, '其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂可发生反应。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:23', '', NULL);
