INSERT INTO `msds_fire_fighting` VALUES (3632, 3767, '放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、氯化氢。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3633, 3768, '遇明火、高热可燃。与强氧化剂可发生反应。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、氧化氮、氯化氢。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3634, 3769, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '氮氧化物、氯化物、一氧化碳、二氧化碳', '合适的灭火介质：干粉、二氧化碳、水喷雾或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3635, 3770, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '-氧化碳、二氧化碳、氯化氢、氮氧化物。', '雾状水、抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3636, 3771, '遇明火、高热可燃。受高热分解，产生有毒的氮氧化物和氯化物气体。', '一氧化碳、二氧化碳、氧化氮、氯化氢。', '采用雾状水、泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3637, 3772, '遇明火、高热可燃。与强氧化剂可发生反应。受高热分解产生有毒的腐蚀性气体。', '一氧化碳、二氧化碳、氯化氢。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3638, 3773, '烟雾。受高热分解产生有毒的腐蚀性烟气。', '一氧化碳、二氧化碳、氯化氢、光气。', '二氧化碳、干粉。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3639, 3774, '热放出有毒的腐蚀性气体。', '一氧化碳、二氧化碳、氯化氢。', '二氧化碳、砂土、干粉。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3640, 3775, '易燃。遇明火、高热极易燃烧。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、氯化氢、氟化氢。', '雾状水、抗溶性泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3641, 3776, '遇明火、高热可燃。受热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氯化氢、氧化汞、汞。', '雾状水、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3642, 3777, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3643, 3778, '易燃，遇明火有引起燃烧的危险。与氧化剂接触猛烈反应。', '一氧化碳、二氧化碳、氯化氢。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、泡沫、干粉、二氧', '化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3644, 3779, '遇明火、高热可燃。受高热分解，放出高毒的烟气。', '一氧化碳、二氧化碳、氯化物、光气。', '雾状水、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3645, 3780, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、氯化氢。', '泡沫、二氧化碳、水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3646, 3781, '的地方，遇明火会引着回燃。遇水或高热能放出大量有毒的气体。', '一氧化碳、二氧化碳、氯化氢、氟化氢。', '泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3647, 3782, '遇明火、高热可燃。与强氧化剂可发生反应。受高热分解，产生有毒的氮氧化物和氯化物 气体。有腐蚀性。', '一氧化碳、二氧化碳、氧化氮、氯化氢。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷 处。灭火剂：雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:32', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3648, 3783, '受热易分解，燃烧时产生有毒的氯化物气体。', '一氧化碳、二氧化碳、氯化氢。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：抗溶性泡沫、干粉、二氧化', '碳、砂土。不宜用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:32', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3649, 3784, '引起燃烧或爆炸。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:32', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3650, 3785, '遇明火、高热可燃。与强氧化剂可发生反应。受高热分解放出有毒的氰化氢和氮氧化物气体。', '一氧化碳、二氧化碳、氧化氮、氰化氢', '干粉、二氧化碳、泡沫、砂土。禁止使用酸碱灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:32', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3651, 3786, '容易自聚，聚合反应随着温度的上升而急骤加剧。流速过快，容易产生和积聚静电。若遇 高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。 消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷 处。喷水保持火场容器冷却，直至灭火结束。处在火场中的容器若已变色或从安全泄压装', '置中产生声音，必须马上撤离。灭火剂：雾状水、泡沫、干粉、二氧化碳、砂土。不宜用 水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:32', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3652, 3787, '遇明火、高热可燃。受高热分解, 放出刺激性烟气。与氧化剂能发生强烈反应。暴露于火中的容器可能会通过压力安全阀泄漏出内容物。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳', '采用泡沫、干粉、二氧化碳、砂土灭火。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3653, 3788, '遇明火、高热可燃。与氧化剂接触可发生化学反应。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、氧化氮。', '泡沫、雾状水、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3654, 3789, '遇明火、高热可燃。受高热分解放出有毒的气体。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、氧化氮。', '泡沫、雾状水、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3655, 3790, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、抗溶性泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3656, 3791, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。', '干粉、二氧化碳、耐醇泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3657, 3792, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。', '干粉、二氧化碳、耐醇泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:36', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3658, 3793, '遇明火、高热可燃。受热分解产生有毒的氮氧化物烟雾。', '一氧化碳、二氧化碳、氮氧化物。', '干粉、二氧化碳、耐醇泡沫或水喷雾。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:36', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3659, 3794, '遇明火、高热可燃。受热分解产生有毒的氮氧化物气体。', '一氧化碳、二氧化碳、氮氧化物', '干粉、二氧化碳、泡沫、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:36', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3660, 3795, '遇明火、高热可燃。受热分解放出有毒的氧化氮烟气。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、氧化氮。', '采用水、泡沫、干粉、二氧化碳灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:36', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3661, 3796, '遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。受热分解放出有毒的氧化氮烟气。', '一氧化碳、二氧化碳、氧化氮。', '采用雾状水、泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:36', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3662, 3797, '遇明火、高热可燃。遇潮时对大多数金属有腐蚀性。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、氮氧化物、氯化氢、氧化硫。', '干粉、砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:37', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3663, 3798, '遇明火能燃烧。受高热分解放出有毒的气体。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、氧化氮。', '采用雾状水、泡沫、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3664, 3799, '遇明火、高热可燃。受热分解放出有毒的氧化氮烟气。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、氧化氮。', '采用泡沫、二氧化碳、干粉、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3665, 3800, '遇明火、高热可燃。与强氧化剂可发生反应。受高热分解，产生有毒的氮氧化物和氯化物 气体。遇水反应发热放出有毒的腐蚀性气体。', '一氧化碳、二氧化碳、氧化氮、光气。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷 处。灭火剂：泡沫、二氧化碳、干粉、砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3666, 3801, '或爆炸。', '一氧化碳、二氧化碳、氧化氮。', '采用雾状水、泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3667, 3802, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、氧化砷。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3668, 3803, '遇明火、高热可燃。与强氧化剂可发生反应。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、氧化氮、氰化氢。', '雾状水、泡沫、二氧化碳、砂土。禁止使用酸碱灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3669, 3804, '遇明火能燃烧。受高热分解放出有毒的气体。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、氧化氮。', '采用雾状水、泡沫、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3670, 3805, '遇明火、高热可燃。受热分解，放出有毒的烟气。与强氧化剂、强碱接触可发生反应。', '一氧化碳、二氧化碳、氮氧化物、碘化氢。', '泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3671, 3806, '遇明火、高热可燃。受高热分解放出有毒的气体。与强氧化剂、强还原剂、强碱接触可发生反应。', '一氧化碳、二氧化碳、氧化氮', '泡沫、干粉、二氧化碳、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3672, 3807, '遇高热、明火或与氧化剂混合，经摩擦、撞击有引起燃烧爆炸的危险。受热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。', '使用抗溶性泡沫、二氧化碳、干粉、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3673, 3808, '遇明火、高热可燃。与强氧化剂可发生反应。受高热分解，产生有毒的氮氧化物和氯化物气体。', '一氧化碳、二氧化碳、氧化氮、氯化氢。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3674, 3809, '遇明火能燃烧。受高热分解放出有毒的气体。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、溴化氢、氧化氮。', '采用雾状水、泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:43', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3675, 3810, '遇明火能燃烧。受热分解产生有毒的烟气。与强氧化剂接触可发生化学反应。具有腐蚀性。', '一氧化碳、二氧化碳、氧化氮、溴化氢。', '采用雾状水、泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:43', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3676, 3811, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。受热分解产生有毒气体。容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '使用干粉、二氧化碳、泡沫灭火剂。切勿将水流直接射入熔融液体，以免引起严重的流淌火灾或剧烈的沸溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:44', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3677, 3812, '遇明火能燃烧。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、溴化氢。', '消防人员必须佩戴过滤式防毒面具（全面罩）或隔离式呼吸器、穿全身防火防毒服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：雾状水、泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3678, 3813, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。受热分解产生有毒的溴化氢和氮氧化物。', '一氧化碳、二氧化碳、溴化氢、氮氧化物。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3679, 3814, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、氯化氢、氟化氢、溴化氢', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3680, 3815, '遇明火、高热可燃。受热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氧化氮、溴化氢。', '雾状水、抗溶性泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3681, 3816, '遇明火能燃烧。受高热燃烧并分解产生有毒气体。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、溴化氢。', '采用雾状水、抗溶性泡沫、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3682, 3817, '遇明火、高热可燃。受热分解产生有毒的溴化物和氯化物烟雾。', '一氧化碳、溴化氢、氧化硫、氯化氢。', '干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:46', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3683, 3818, '遇明火能燃烧。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、溴化氢。', '采用雾状水、泡沫、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3684, 3819, '遇明火、高热可燃。与强氧化剂可发生反应。有腐蚀性。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氯化氢、溴化氢、光气。', '二氧化碳、干粉、砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3685, 3820, '遇明火能燃烧。受高热分解产生有毒的溴化物气体。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、溴化氢。', '采用泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3686, 3821, '遇高热、明火或氧化剂，有引起燃烧的危险。燃烧时放出有毒的刺激性烟雾。', '一氧化碳、二氧化碳、溴化氢。 合适的灭火介质:干粉、二氧化碳、耐醇泡沫或水喷雾。不合适的灭火介质:避免用太强烈的 水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要', '求的或相当的)）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防 水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3687, 3822, '遇明火、高热可燃。受热分解产生有毒的氮氧化物气体。暴露于火中的容器可能会通过压力安全阀泄漏出内容物。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、氮氧化物', '干粉、干砂、二氧化碳或耐醇泡沫。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:48', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3688, 3823, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:48', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3689, 3824, '遇明火、高热可燃。受热分解产生有毒的氮氧化物气体。暴露于火中的容器可能会通过压力安全阀泄漏出内容物。受热或接触火焰可能会产生膨胀或爆炸性分解。与酸、碱接触能引起燃烧爆炸。', '一氧化碳、二氧化碳、氮氧化物', '干粉、干砂、二氧化碳或耐醇泡沫。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:48', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3690, 3825, '扩散到相当远的地方，遇明火会引着回燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:48', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3691, 3826, '其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压 增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:48', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3692, 3827, '其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3693, 3828, '遇明火、高热可燃。受高热分解放出有毒的气体。', '氮氧化物、一氧化碳、二氧化碳。', '干粉、二氧化碳或耐醇泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:50', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3694, 3829, '遇明火、高热可燃。受热分解产生有毒的氮氧化物气体。', '氮氧化物、一氧化碳、二氧化碳。', '干粉、二氧化碳、耐醇泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:50', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3695, 3830, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、氮氧化物', '干粉、二氧化碳、耐醇泡沫或水。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:50', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3696, 3831, '遇明火、高热可燃。受热分解产生有毒气体。', '氮氧化物、氯化氢', '干粉、二氧化碳、耐醇泡沫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3697, 3832, '在潮湿环境且有二氧化碳存在下，能腐蚀铝和钢。蒸气比空气重，易在低处聚集。封闭区 域内的蒸气遇火能爆炸。', '无资料', '使用干粉、抗醇泡沫、二氧化碳灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3698, 3833, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、氧化磷。', '泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3699, 3834, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。燃烧分解时，放出有毒的氮氧化物。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3700, 3835, '遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩 散到相当远的地方，遇火源引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷 处。灭火剂：泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3701, 3836, '其蒸气与空气可形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。与强氧化剂、强还原剂、强碱接触可发生反应。', '一氧化碳、二氧化碳。', '干粉、二氧化碳、泡沫、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3702, 3837, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3703, 3838, '遇明火、高热可燃。受高热分解放出有毒的气体（一氧化碳、二氧化碳、氧化氮、氯化氢）。与强氧化剂、酸类接触可发生反应。', '一氧化碳、二氧化碳、氧化氮、氯化氢。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3704, 3839, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化韧、氯化氢。', '雾状水；泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3705, 3840, '火焰都可能引起火灾和爆炸。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、氮氧化物', '干粉、二氧化碳、耐醇泡沫或水喷雾。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:54', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3706, 3841, '遇明火、高热可燃。受高热分解放出有毒的气体。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、氧化氮。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：泡沫、雾状水、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:54', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3707, 3842, '遇明火、高热可燃。受热分解产生有毒的氮氧化物气体。与氧化剂可发生反应。', '一氧化碳、二氧化碳、氮氧化物。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。灭火剂：雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:54', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3708, 3843, '遇明火、高热、摩擦、震动、撞击，有引起燃烧爆炸的危险。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。灭火剂：雾状水、抗溶性泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:54', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3709, 3844, '遇明火、高热可燃。受热分解产生有毒的氮氧化物气体。与氧化剂可发生反应。粉体与空气可形成爆炸性混合物，当达到一定浓度时，遇火星会发生爆炸。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、抗溶性泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:54', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3710, 3845, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、氮氧化物、硫氧化物', '干粉、二氧化碳或耐醇泡沫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3711, 3846, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:56', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3712, 3847, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质: 干粉、二氧化碳、水喷雾或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:56', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3713, 3848, '遇明火、高热可燃。受高热分解，放出高毒的烟气。与强氧化剂、强碱、酸酐、酰基氯接触可发生反应。', '一氧化碳、二氧化碳、氯化氢、光气。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:56', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3714, 3849, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:56', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3715, 3850, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质: 干粉、二氧化碳、水喷雾或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:58', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3716, 3851, '遇明火、高热可燃。爆炸性分解。', '一氧化碳、二氧化碳、氮氧化物', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:58', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3717, 3852, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:59', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3718, 3853, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳、水喷雾或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:34:59', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3719, 3854, '遇明火、高热可燃。受热分解产生有毒气体。与氧化剂接触有发生燃烧和爆炸的危险。暴露于火中的容器可能会通过压力安全阀泄漏出内容物。受热或接触火焰可能会产生膨胀或爆炸性分解。', '磷氧化物、一氧化碳、二氧化碳', '干粉、干砂、二氧化碳或耐醇泡沫。切勿使用直流水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3720, 3855, '一定的浓度时，遇火星会发生爆炸。', '一氧化碳、二氧化碳、氧化氮。', '二氧化碳、雾状水、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3721, 3856, '从而增加火势和/或蒸气的浓度。蒸气可能会移动到着火源并回闪。液体和蒸气易燃。加 热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:01', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3722, 3857, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、氯化氢。', '泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:01', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3723, 3858, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、氟化氢、氧化硫、氮氧化物', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。灭火剂：干粉、二氧化碳或耐醇泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3724, 3859, NULL, '一氧化碳、二氧化碳、氯化氢、氮氧化物', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3725, 3860, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氯化氢、氮氧化物。', '泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3726, 3861, '遇明火、高热可燃。受高热分解，产生有毒的氮氧化物和氯化物气体。', '一氧化碳、二氧化碳、氯化氢、氧化氮。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：抗溶性泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3727, 3862, '可燃。遇高热可能分解产生有毒气体。燃烧时可能产生一氧化碳、二氧化碳、氮氧化物、氯化氢等有毒气体。', '一氧化碳、二氧化碳、氮氧化物、氯化氢、光气等有毒气体', '干粉、二氧化碳、耐醇泡沫、雾状水', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3728, 3863, '接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3729, 3864, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳、氧化氮。', '抗溶性泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3730, 3865, '一定的浓度时，遇火星会发生爆炸。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、二氧化碳、泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3731, 3866, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质: 干粉、二氧化碳、水喷雾或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3732, 3867, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。具有腐蚀性。', '一氧化碳、二氧化碳、氮氧化物。', '尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火剂：雾状水、抗溶性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3733, 3868, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。若遇高热，容器内压增大，有开裂和爆炸 的危险。', '一氧化碳、二氧化碳、氮氧化物、氰化氢。', '雾状水、干粉、抗溶性泡沫、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3734, 3869, '易燃，遇明火、高热有燃烧爆炸的危险。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳、氮氧化物', '抗溶性泡沫、干粉、二氧化碳、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3735, 3870, '产生刺激性、毒性或腐蚀性的气体。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、氮氧化物。', '合适的灭火介质：小火：干式化学灭火剂、二氧化碳、水或抗溶泡沫灭火剂；大火：水、水雾或抗溶泡沫灭火剂。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:07', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3736, 3871, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。', '一氧化碳、二氧化碳、氧化氮。', '雾状水、抗溶性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:07', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3737, 3872, '高热，可能发生聚合反应，出现大量放热现象，引起容器破裂和爆炸事故。', '一氧化碳、二氧化碳、氧化氮。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:07', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3738, 3873, '易燃，遇明火、高热有燃烧爆炸危险。受热分解放出有毒的氧化氮烟气。与强氧化剂接触反应剧烈。', '一氧化碳、二氧化碳、氧化氮。', '水、抗溶性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:07', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3739, 3874, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。与强氧化剂（如过氧化物、硝酸盐等）发生剧烈反应,甚至发生爆炸。与卤化物（如四氯化碳）能发生强烈反应。', '一氧化碳、二氧化碳、氧化氮。', '尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火剂：雾状水、抗溶性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:07', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3740, 3875, '遇明火、高热可燃。', '一氧化碳、二氧化碳、氮氧化物、氧化硒。', '二氧化碳、泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3741, 3876, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。', '一氧化碳、二氧化碳、氮氧化物。', '水、抗溶性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3742, 3877, '烈反应。', '一氧化碳、二氧化碳、氮氧化物。 尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火剂：雾状', '水、抗溶性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3743, 3878, '遇明火、高热可燃。受热分解产生有毒气体。与氧化剂接触有发生火灾和爆炸的危险。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '氮氧化物、一氧化碳、二氧化碳', '干粉、二氧化碳、水喷雾或耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3744, 3879, '化剂混合能形成爆炸性混合物。经摩擦、震动或撞击可引起燃烧或爆炸。', '一氧化碳、二氧化碳、氮氧化物。', '采用水、砂土灭火。禁止使用酸碱灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:10', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3745, 3880, '遇明火、高热易燃。与氧化剂可发生反应。有腐蚀性。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、氮氧化物。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:10', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3746, 3881, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3747, 3882, '遇明火、高热易燃。与氧化剂接触猛烈反应。', '一氧化碳、二氧化碳、氮氧化物。', '采用泡沫、二氧化碳、干粉、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3748, 3883, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳、氮氧化物。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3749, 3884, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、氯化氢、氧化硫。', '泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3750, 3885, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。燃烧分解时，放出有毒的氮氧化物。', '一氧化碳、二氧化碳、氧化氮。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:12', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3751, 3886, '加热时，容器可能爆炸。暴露于火中的容器可能会通过压力安全阀泄漏出内容物。受热或 接触火焰可能会产生膨胀或爆炸性分解。', '无资料 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。不合适的灭火介质:避免用太强烈的水汽灭 火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或', '相当的)）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染 地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:12', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3752, 3887, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:12', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3753, 3888, '易燃，遇高热、明火有引起燃烧的危险。与氧化剂接触猛烈反应。能腐蚀轻金属和铜。', '一氧化碳、二氧化碳、氧化氮。 尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火剂：雾状', '水、抗溶性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:12', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3754, 3889, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氮氧化物。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:12', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3755, 3890, '遇明火、高热可燃。与氧化剂可发生反应。有腐蚀性。', '一氧化碳、二氧化碳、氮氧化物。', '抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3756, 3891, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳、氮氧化物。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3757, 3892, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3758, 3893, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、氮氧化物、硫化氢、氯化氢、氟化氢等有毒烟雾。', '用干粉、泡沫和砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3759, 3894, '或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:15', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3760, 3895, '遇明火、高热可燃。与锌或电镀钢接触能引起剧烈反应。受热分解放出有毒的氮氧化物烟气。与氧化剂混合能形成爆炸性混合物。', '一氧化碳、二氧化碳、氮氧化物（NOx）', '干粉、二氧化碳、耐醇泡沫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:15', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3761, 3896, '遇明火、高热可燃。受热分解放出有毒的氧化氮烟气。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、氧化氮。', '采用雾状水、泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3762, 3897, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。燃烧分解时，放出有毒的氮氧化物。', '一氧化碳、二氧化碳、氮氧化物。', '水、二氧化碳、泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3763, 3898, '加热时，容器可能爆炸；受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:17', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3764, 3899, '遇明火、高热可燃。受热分解产生有毒的氮氧化物烟气。与氧化剂可发生反应。', '氮氧化物、一氧化碳、二氧化碳', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3765, 3900, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、氯化氢。', '泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3766, 3901, '遇明火、高热可燃。受热分解产生有毒的氮氧化物烟雾。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '氮氧化物', '雾状水、砂土。切勿将水流直接射至熔融物，以免引起严重的流淌火灾。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3767, 3902, '遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。受热分解放出有毒的氧化氮烟气。', '一氧化碳、二氧化碳、氧化氮', '采用雾状水、泡沫、二氧化碳、干粉、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3768, 3903, '易燃液体，其蒸汽比空气重，可能产生爆炸。遇明火、高热可燃。受热分解产生有毒的氮氧化物烟气。', '一氧化碳、二氧化碳、氧化氮。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3769, 3904, '易燃，遇高热、明火、氧化剂有引起燃烧的危险。受热分解放出有毒的氧化氮烟气。', '一氧化碳、二氧化碳、氧化氮。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：泡沫、二氧化碳、干粉、砂', '土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3770, 3905, '其蒸气与空气形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反 应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、砂土、泡沫、干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3771, 3906, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '氟化物、氮氧化物、硫氧化物', '干粉、二氧化碳或耐醇泡沫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3772, 3907, '易燃液体，其蒸汽比空气重，可能产生爆炸。遇明火、高热可燃。受热分解产生有毒的氮氧化物烟气。', '一氧化碳、二氧化碳、氮氧化物。', '抗溶性泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3773, 3908, '建规火险分级：', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:22', '', NULL);
