INSERT INTO `msds_fire_fighting` VALUES (3787, 3922, '遇明火、高热可燃。与氧化剂能发生强烈反应。受热分解，放出高毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、苯胺', '干粉、二氧化碳或耐醇泡沫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3788, 3923, '爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3789, 3924, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、氧化硫。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3790, 3925, '遇明火、高热可燃。受热分解，放出氧化磷和氯化物的毒性气体。与强氧化剂接触可发生 化学反应。', '一氧化碳、二氧化碳、氯化氢、氧化磷。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：抗溶性泡沫、干粉、 砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3791, 3926, '受热分解，放出磷、硫的氧化物等毒性气体。', '一氧化碳、二氧化碳、氧化磷、氧化硫。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：干粉、泡沫、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3792, 3927, '遇明火、高热可燃。受热分解，放出磷、硫的氧化物等毒性气体。', '一氧化碳、二氧化碳、硫化物、氧化硫、氧化磷。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3793, 3928, '器破裂或爆炸事故。有腐蚀性。', '一氧化碳、氯化氢、氧化硫、磷烷。', '干粉、泡沫、二氧化碳、砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3794, 3929, '遇明火、高热可燃。受高热分解放出有毒的气体。', '氯化氢、溴化氢、氧化磷。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3795, 3930, '遇明火、高热可燃。与强氧化剂可发生反应。受热分解，放出氧化磷和氯化物的毒性气体。', '一氧化碳、二氧化碳、氯化氢、氧化磷。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷 处。灭火剂：雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3796, 3931, '遇明火、高热可燃。受热分解，放出磷、硫的氧化物等毒性气体。', '一氧化碳、二氧化碳、硫化氢、氧化硫、氧化磷。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3797, 3932, '遇明火、高热可燃。受热分解，，放出氮、磷的氧化物等毒性气体。在碱液中能迅速分解。', '一氧化碳、氧化磷、氯化氢、氧化氮。', '泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:32', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3798, 3933, '遇明火、高热可燃。与强氧化剂可发生反应。受热分解，放出氮、磷的氧化物等毒性气体。', '一氧化碳、二氧化碳、氧化磷、氧化氮。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:32', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3799, 3934, '无资料', '无资料 合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:32', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3800, 3935, '爆炸性分解。', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:32', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3801, 3936, '遇明火、高热可燃。受高热分解产生有毒的腐蚀性烟气。', '一氧化碳、二氧化碳、氧化硫、氧化磷。', '雾状水、泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3802, 3937, '遇明火、高热可燃。受高热分解，放出有毒的氮、磷和硫的氧化物烟气。', '一氧化碳、二氧化碳、氧化氮、硫化氢、氧化硫、氧化磷。', '泡沫、砂土、干粉。禁止使用酸碱灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3803, 3938, '安全阀泄漏出内容物。受热或接触火焰可能会产生膨胀或爆炸性分解。', '无资料 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。不合适的灭火介质:避免用太强烈的水汽灭 火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或', '相当的)）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染 地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:34', '', NULL);
