INSERT INTO `msds_fire_fighting` VALUES (3817, 3952, '遇明火、高热可燃。受高热分解，放出高毒的烟气。', '一氧化碳、二氧化碳、氯化氢、溴化氢、氧化硫、氧化磷。', '泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3818, 3953, '遇明火、高热可燃。受热分解，放出氧化磷和氯化物的毒性气体。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、氯化氢、氧化磷', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火剂：抗溶性泡沫、干粉、砂土。禁止用水柱直接喷射，防止火势蔓延。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:40', '', NULL);
