INSERT INTO `msds_fire_fighting` VALUES (3858, 3993, '遇明火、高热可燃。有腐蚀性。受高热分解产生有毒的腐蚀性烟气。', '一氧化碳、二氧化碳、氯化氢。', '抗溶性泡沫、干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:58', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3859, 3994, '遇明火、高热可燃。与氧化剂可发生反应。', '一氧化碳、二氧化碳。', '泡沫、抗溶性泡沫、二氧化碳、干粉、砂土、1211灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:35:59', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3860, 3995, '其蒸气与空气形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。 其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源引着回燃。若遇高热，可能发生聚 合反应，出现大量放热现象，引起容器破裂和爆炸事故。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3861, 3996, '爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3862, 3997, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '-氧化碳、二氧化碳、氮氧化物、氯化氢。', '二氧化碳、砂土、水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3863, 3998, '遇明火、高热可燃。受热分解产生有毒的烟气。', '一氧化碳、二氧化碳。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：雾状水、泡沫、干粉、二 氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3864, 3999, '遇明火、高热可燃。与强氧化剂可发生反应。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3865, 4000, '反应。与硝酸发生剧烈反应或立即燃烧。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：泡沫、干粉、二氧化碳、砂', '土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3866, 4001, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳、水喷雾或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3867, 4002, '遇明火、高热可燃。与氧化剂能发生强烈反应。受高热分解，放出高毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、氰化氢、氰化物。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3868, 4003, '遇明火、高热可燃。受高热分解，放出高毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、氰化氢。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3869, 4004, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3870, 4005, '遇明火、高热可燃。与氧化剂可发生反应。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、抗溶性泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3871, 4006, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳、氧化氮、氰化氢。', '雾状水、泡沫、二氧化碳、于粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3872, 4007, '爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3873, 4008, '反应。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：泡沫、干粉、二氧化碳、砂', '土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3874, 4009, '遇明火、高热可燃。受热分解产生有毒的烟气。', '一氧化碳、二氧化碳。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：雾状水、泡沫、干粉、二 氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:08', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3875, 4010, '安全阀泄漏出内容物。受热或接触火焰可能会产生膨胀或爆炸性分解。', '无资料 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:08', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3876, 4011, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:08', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3877, 4012, '禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。', '无资料', '合适的灭火介质:干粉、二氧化碳、水喷雾或耐醇泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:08', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3878, 4013, '不易燃烧。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氯化氢。', '雾状水、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3879, 4014, '化学反应。若遇高热，容器内压增大，有开裂和爆炸的危险。', '氧化氮、氨。', '雾状水、抗溶性泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3880, 4015, '遇高热、明火或氧化剂，有引起燃烧的危险。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、氧化硫。', '泡沫、二氧化碳、干粉、砂土、抗溶性泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:10', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3881, 4016, '固体，易燃，其粉体与空气混合，能形成爆炸性混合物。受热分解产生有毒气体。', '碳氧化物、氮氧化物', '合适的灭火介质：干粉、二氧化碳、水喷雾或耐醇泡沫。消防人员须穿全身消防服，佩戴正压自给式呼吸器，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:10', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3882, 4017, '遇水放出易燃气体，遇明火、高热有燃烧爆炸危险', '氨气、氮氧化物', '合适的灭火介质: 干粉，干砂或石灰。不合适的灭火介质: 水、二氧化碳和泡沫。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:10', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3883, 4018, '遇明火、高热可燃。接触酸或酸气以及氧化性物质，能发生强烈的化学反应而产生高热。遇水或水蒸气反应放出有毒的或易燃的气体。加热至熔融状态时能在空气中自燃。', '氨、氮氧化物。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。灭火剂：干粉、砂土。禁止用水和泡沫灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3884, 4019, '受高热、接触明火或与氧化剂混合，可发生爆炸。遇水反应发热放出有毒的腐蚀性气体。', '氨、氧化钠。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷 处。灭火剂：干粉、砂土。禁止用水和泡沫灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3885, 4020, '受热分解，放出氮、硫的氧化物等毒性气体。', '氧化氮、硫化物。', '采用雾状水、泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3886, 4021, '遇明火、高热可燃。受热分解产生有毒的氮氧化物和氨气。', '氮氧化物、氨气', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3887, 4022, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3888, 4023, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:12', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3889, 4024, '易分解放出氨气, 温度越高, 分解速度越快, 可形成爆炸性气氛。', '氨。', '采用水、雾状水、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3890, 4025, '受高热分解产生有毒的腐蚀性烟气。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、二氧化碳、泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3891, 4026, '若遇高热，容器内压增大，有开裂和爆炸的危险。', '氟化氢。', '切断气源，喷水冷却容器，可能的话将容器从火场移至空旷处。雾状水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3892, 4027, '若遇高热，容器内压增大，有开裂和爆炸的危险。', '氟化氢。', '切断气源。喷水冷却容器，可能的话将容器从火场移至空旷处。雾状水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3893, 4028, '若遇高热，容器内压增大，有开裂和爆炸的危险。', '氟化氢。', '切断气源。喷水冷却容器，可能的话将容器从火场移至空旷处。雾状水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:15', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3894, 4029, '不燃的剧毒气体。在贮存、运输和操作处置过程中，受热可聚合，产生意外的危害。受热分解产生氟化氢、四氟化碳等有毒气体。容器受热内压增大，有爆炸危险。', '氟化氢、四氟化碳、一氧化碳、二氧化碳等有毒气体。', '本品不燃。根据周围环境选择适当灭火剂。切断气源。喷水冷却容器，可能的话将容器从火场移至空旷处。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:15', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3895, 4030, '遇明火、高热可燃。受热分解，放出氮、磷的氧化物等毒性气体。', '一氧化碳、二氧化碳、氧化氮、氧化磷。', '雾状水、泡沫、二氧化碳、砂土。禁止使用酸碱灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:15', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3896, 4031, '遇明火、高热可燃。', '一氧化碳、二氧化碳、氯化氢。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:15', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3897, 4032, '受热分解产生有毒烟雾', '一氧化碳、二氧化碳、溴化氢等有毒烟雾', '合适的灭火介质:干粉、二氧化碳、水喷雾或耐醇泡沫。不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3898, 4033, '接触空气易自燃。与氯酸盐等氧化剂混合发生爆炸。其碎片和碎屑接触皮肤干燥后即着火，可引起严重的皮肤灼伤。', '氧化磷。消防人员必须穿橡胶防护服、胶鞋，并佩戴过滤式防毒面具（全面罩）或自给式呼吸器灭火。', '灭火剂：雾状水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:17', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3899, 4034, '火焰或化学反应能引起燃烧和爆炸。与水或酸接触剧烈反应，并释出氢气引起燃烧。与氟、 氯等接触会发生剧烈的化学反应。遇酸或稀酸会引起燃烧爆炸。', '氧化磷。 不可用水、泡沫、二氧化碳、卤代烃（如1211灭火剂）等灭火。须用干燥石墨粉或其它干', '粉灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:17', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3900, 4035, '易燃液体，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂能发生强烈反应。易产生和聚集静电，有燃烧爆炸危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:17', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3901, 4036, '遇明火、高热可燃。与酸类、卤素、醇类、胺类发生强烈反应，会引起燃烧。', '一氧化碳、二氧化碳、氧化氮。 消防人员须戴好防毒面具，在安全距离以外，在上风向灭火。灭火剂：水、泡沫、二氧化', '碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3902, 4037, '遇高热、明火或氧化剂，有引起燃烧的危险。', '一氧化碳、二氧化碳。', '雾状水、抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3903, 4038, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳。', '雾状水、抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3904, 4039, '遇高热、明火或氧化剂，有引起燃烧的危险。其蒸气比空气重，能在较低处扩散到相当远 的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷 处。灭火剂：雾状水、抗溶性泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3905, 4040, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3906, 4041, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、氧化硫。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷 处。灭火剂：抗溶性泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3907, 4042, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷 处。灭火剂：雾状水、抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:20', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3908, 4043, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:20', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3909, 4044, '遇明火、高热可燃。', '一氧化碳、二氧化碳。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：水、抗溶性泡沫、干 粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:20', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3910, 4045, '酸、氨、脂肪胺、链烷醇胺、异氰酸酯、烯基氧化物、环氧氯丙烷不能配伍。', '无资料 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3911, 4046, '气体。', '一氧化碳、二氧化碳、氧化钠。 消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：雾状水、抗溶性泡沫、干', '粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3912, 4047, '容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氟化氢。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3913, 4048, '受高热分解产生有毒的硫化物烟气。', '一氧化碳、二氧化碳、硫化物。', '消防人员必须穿全身防火防毒服，在上风向灭火。灭火时尽可能将容器从火场移至空旷处。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3914, 4049, '受高热分解产生有毒的硫化物烟气。', '一氧化碳、二氧化碳、氧化硫。', '尽可能将容器从火场移至空旷处。灭火剂：雾状水、泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:22', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3915, 4050, '危险。燃烧时，放出有毒气体。', '一氧化碳、二氧化碳、氧化氮、氧化硫。', '采用雾状水、二氧化碳、泡沫、干粉、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:23', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3916, 4051, '性。', '一氧化碳、二氧化碳、氧化氮、氯化氢。', '灭火剂：干粉、二氧化碳。禁止用水和泡沫灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:23', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3917, 4052, '产生刺激性、毒性或腐蚀性的气体。加热时，容器可能爆炸。暴露于火中的容器可能会通 过压力安全阀泄漏出内容物。受热或接触火焰可能会产生膨胀或爆炸性分解。', '无资料 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。不合适的灭火介质:避免用太强烈的水汽灭火， 因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当', '的)）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表 和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:23', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3918, 4053, '遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。受高热分解产生有毒的硫化物烟 气。', '一氧化碳、二氧化碳、硫化氢、氧化硫。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：雾状水、泡沫、二氧 化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:23', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3919, 4054, '爆炸性分解。', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3920, 4055, '化学反应。对很多金属尤其是潮湿空气存在下有腐蚀性。', '一氧化碳、二氧化碳、氯化氢、氧化硅。', '灭火剂：抗溶性泡沫、干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3921, 4056, '中的容器可能会通过压力安全阀泄漏出内容物。受热或接触火焰可能会产生膨胀或爆炸性分 解。', '无资料 合适的灭火介质:干粉，干砂或石灰。不合适的灭火介质:水、二氧化碳和泡沫。灭火时，应', '佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安全距离处、有 充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3922, 4057, '遇明火、高热可燃，遇水或水蒸气反应发热放出有毒的腐蚀性气体。', '一氧化碳、二氧化碳、氯化氢、氧化磷。', '泡沫、二氧化碳、干粉、砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3923, 4058, '遇明火能燃烧。受高热分解放出有毒的气体。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、氧化氮。', '采用抗溶性泡沫、干粉、二氧化碳、砂土灭火。禁止使用酸碱灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3924, 4059, '易燃，遇高热、明火及强氧化剂易引起燃烧。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：泡沫、二氧化碳、干粉、砂', '土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3925, 4060, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '无资料', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷 处。灭火剂：雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3926, 4061, '遇明火、高热能引起燃烧爆炸。与氧化剂接触猛烈反应。', '一氧化碳、二氧化碳。', '采用泡沫、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3927, 4062, '空气存在下有腐蚀性。', '一氧化碳、二氧化碳、氯化氢、光气。', '灭火剂：抗溶性泡沫、干粉、二氧化碳。禁止用水和泡沫灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3928, 4063, '可燃。遇明火、高热可燃。受热分解放出有毒的氧化氮烟气。与强氧化剂接触可发生化学 反应。', '一氧化碳、二氧化碳、氧化氮。', '采用雾状水、泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3929, 4064, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳、氧化氮、氯化氢。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3930, 4065, '遇明火、高热可燃。受高热升华产生有毒气体。加热分解产生毒性气体。', '一氧化碳、二氧化碳。', '采用水、泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3931, 4066, '能会通过压力安全阀泄漏出内容物。受热或接触火焰可能会产生膨胀或爆炸性分解。', '无资料 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。不合适的灭火介质:避免用太强烈的水汽灭火， 因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当', '的)）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表 和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3932, 4067, '遇水或水蒸气反应发热放出有毒的腐蚀性气体。受热分解，放出高毒的烟气。', '一氧化碳、二氧化碳、砷、氧化砷。', '雾状水、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3933, 4068, '受高热分解，放出高毒的烟气。', '一氧化碳、二氧化碳、砷、氧化砷。', '雾状水、抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3934, 4069, '安全阀泄漏出内容物。受热或接触火焰可能会产生膨胀或爆炸性分解。', '无资料 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3935, 4070, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3936, 4071, '遇明火、高热可燃。受热分解产生有毒的烟气。', '一氧化碳、二氧化碳。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：雾状水、泡沫、干粉、二 氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3937, 4072, '遇明火、高热可燃。与氧化剂可发生反应。受高热分解，放出剧毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、氰化氢。 合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽 灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的', '或相当的)）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污 染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3938, 4073, '遇明火能燃烧。受高热分解放出有毒的气体。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、氧化氮、氰化氢。', '采用抗溶性泡沫、干粉、二氧化碳、砂土灭火。禁止使用酸碱灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3939, 4074, '易燃液体，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。放出大量热量而引起容器破裂和爆炸事故。', '一氧化碳、二氧化碳', '抗溶性泡沫、干粉、二氧化碳、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3940, 4075, '猛烈聚合，放出大量热量。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会 着火回燃。', '一氧化碳、二氧化碳。 尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火剂：泡沫、', '干粉、二氧化碳、砂土。用水灭火无效。遇大火，消防人员须在有防护掩蔽处操作。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3941, 4076, '大多数金属有腐蚀性。', '一氧化碳、二氧化碳、氯化氢、光气。 消防人员须戴好防毒面具，在安全距离以外，在上风向灭火。灭火剂：干粉、二氧化碳、砂土。', '禁止用水和泡沫灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3942, 4077, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。', '抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3943, 4078, '其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氧化氮。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3944, 4079, '遇明火、高热易燃。与氧化剂能发生强烈反应。受热分解放出有毒的氧化氮烟气。若遇高热， 容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氧化氮。', '雾状水、二氧化碳、泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3945, 4080, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。受热分解放出有毒的氧化氮烟气。', '一氧化碳、二氧化碳、氧化氮。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3946, 4081, '遇明火、高热易燃。受高热分解产生有毒的硫化物烟气。', '一氧化碳、二氧化碳、硫化氢、硫化物。', '采用雾状水、泡沫、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3947, 4082, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质: 干粉、二氧化碳、水喷雾或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3948, 4083, '爆炸危险性的过氧化物。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3949, 4084, '加热至 120℃，与碱性物质接触，立即猛烈聚合。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、氮氧化物。', '采用抗溶性泡沫、干粉、二氧化碳、砂土灭火。禁止使用酸碱灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3950, 4085, '受高热分解，放出刺激性烟气。粉体与空气可形成爆炸性混合物，当达到一定的浓度时，遇火 星会发生爆炸。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3951, 4086, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氧化铊。', '泡沫、砂土、水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3952, 4087, '易燃，与空气混合能形成爆炸性混合物。遇热源和明火有燃烧爆炸的危险。是非常活泼的物质, 容 易产生聚合。在200kPa大气压下可发生爆炸性分解。气体比空气重，能在较低处扩散到相当远的 地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '灭火剂：雾状水、泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3953, 4088, '气体。', '一氧化碳、二氧化碳、氯化氢、光气。', '二氧化碳、干粉。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:36', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3954, 4089, '分解产生有毒的腐蚀性烟气。', '一氧化碳、二氧化碳、氯化氢、氧化硅。', '抗溶性泡沫、干粉、二氧化碳、1211灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:36', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3955, 4090, '遇明火、高热可燃。受热分解产生有毒的砷氧化物烟雾。', '砷氧化物', '泡沫、干粉、二氧化碳、砂土。不宜用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:36', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3956, 4091, '生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。在 火场中，受热的容器有爆炸危险。', '一氧化碳、二氧化碳、氧化氮。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：抗溶性泡沫、干粉、二氧化', '碳、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:36', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3957, 4092, '烈反应。若遇高热，可发生聚合反应，放出大量热量而引起容器破裂和爆炸事故。其蒸气 比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的', '容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：抗溶性泡沫、干粉、 二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3958, 4093, '扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 切断气源。若不能切断气源，则不允许熄灭泄漏处的火焰。喷水冷却容器，可能的话将容器从火', '场移至空旷处。灭火剂：雾状水、泡沫、干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3959, 4094, '物。腐蚀某些塑料、橡胶和涂料。能积聚静电而引燃气蒸气。易燃性（红色）：4；反应活 性（黄色）：2', '无资料 设法关闭泄漏容器，以免爆炸；使用二氧化碳、干粉灭火剂。消防器具包括（SCBA）不能 提供足够有效得防护。若不小心接触，立即撤离现场，隔离器具，对人员彻底清污。蒸气 比空气重，易在低处聚集。封闭区域内的蒸气遇火能爆炸。蒸气能扩散到远处，遇点火源', '着火，并引起回燃。储存容器及其部件可能向四面八方飞射很远。如果该物质或被污染控 制部门。受过特殊培训的人员可以利用喷雾水流冷却周围暴露物，让或自行烧尽。在安全 防爆距离以外，使用雾状水冷却暴露的容器。若冷却水流不起作用（排放音量，音调升高， 罐体变色或有任何变形的迹象），立即撤离到安全区域。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3960, 4095, '遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3961, 4096, '强烈反应。', '一氧化碳、二氧化碳。 用水喷射逸出液体，使其稀释成不燃性混合物，并用雾状水保护消防人员。灭火剂：雾状', '水、抗溶性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3962, 4097, '受高热、明火会产生剧毒的蒸气。', '一氧化碳、二氧化碳、氧化汞。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3963, 4098, '其蒸气与空气可形成爆炸性混合物，遇明火、高热易引起燃烧爆炸。与强氧化剂接触可发生化 学反应。具有腐蚀性。', '一氧化碳、二氧化碳。', '消防人员须戴好防毒面具，在安全距离以外，在上风向灭火。用水喷射逸出液体，使其稀释成 不燃性混合物，并用雾状水保护消防人员。灭火剂：抗溶性泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3964, 4099, '炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '喷水保持火场容器冷却，直至灭火结束。灭火剂：抗溶性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3965, 4100, '容器可能爆炸。暴露于火中的容器可能会通过压力安全阀泄漏出内容物。受热或接触火焰 可能会产生膨胀或爆炸性分解。', '无资料 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。不合适的灭火介质:避免用太强烈的水汽灭火， 因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当', '的)）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表 和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3966, 4101, '若遇高热，可能发生聚合反应，出现大量放热现象，引起容器破裂和爆炸事故。其蒸气比空气 重，能在较低处扩散到相当远的地方，遇明火会引着回燃。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3967, 4102, '生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '采用泡沫、二氧化碳、干粉、砂土灭火。用水灭火无效，但可用水保持火场中容器冷却。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:43', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3968, 4103, '容器可能爆炸。暴露于火中的容器可能会通过压力安全阀泄漏出内容物。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳', '干粉、二氧化碳或耐醇泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:43', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3969, 4104, '易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂能发 生强烈反应。', '一氧化碳、二氧化碳。', '采用泡沫、二氧化碳、干粉、砂土灭火。用水灭火无效，但可用水保持火场中容器冷却。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:43', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3970, 4105, '易燃，遇明火、高热能引起燃烧爆炸。与氧化剂可发生反应。', '一氧化碳、二氧化碳。', '泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:43', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3971, 4106, '易燃，遇明火、高热能引起燃烧爆炸。与氧化剂可发生反应。', '二氧化碳、一氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：泡沫、干粉、二氧化碳、砂', '土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:43', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3972, 4107, '易燃，遇明火、高热能引起燃烧爆炸。与氧化剂可发生反应。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：泡沫、干粉、二氧化碳、砂', '土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:44', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3973, 4108, '而增加火势和/或蒸气的浓度。蒸气可能会移动到着火源并回闪。液体和蒸气易燃。加热时， 容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3974, 4109, '易燃液体，其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3975, 4110, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。若遇高热，容器内压增大，有开裂和爆炸 的危险。', '一氧化碳、二氧化碳。', '二氧化碳、干粉、雾状水、抗溶性泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3976, 4111, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。受热分解放出剧毒的氰化物气体。', '一氧化碳、二氧化碳、氧化氮、氰化氢。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3977, 4112, '易燃气体。与空气混合能形成爆炸性混合物，遇热源和明火有燃烧爆炸的危险。与氧化剂接触猛 烈反应。气体比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 切断气源。若不能切断气源，则不允许熄灭泄漏处的火焰。喷水冷却容器，可能的话将容器从火', '场移至空旷处。灭火剂：雾状水、泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:46', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3978, 4113, '二氮、氧化二氮等激烈化合，与其它氧化剂接触剧烈反应。气体比空气重，能在较低处扩散到相 当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 切断气源。若不能切断气源，则不允许熄灭泄漏处的火焰。喷水冷却容器，可能的话将容器从火', '场移至空旷处。灭火剂：雾状水、泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:46', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3979, 4114, '气。在空气中久置后能生成有爆炸性的过氧化物。与酸类、碱类、氨、胺类、二氧化硫、 硫脲、金属盐类、氧化剂等猛烈反应。在火场高温下，能发生聚合放热，使容器破裂。', '一氧化碳、二氧化碳。 消防人员须戴好防毒面具，在安全距离以外，在上风向灭火。灭火剂：抗溶性泡沫、二氧', '化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:46', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3980, 4115, '水分、过氧化物及铁质易自聚而引起爆炸。', '一氧化碳、二氧化碳。', '消防人员须戴好防毒面具，在安全距离以外，在上风向灭火。用水喷射逸出液体，使其稀释成 不燃性混合物，并用雾状水保护消防人员。灭火剂：雾状水、抗溶性泡沫、干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:46', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3981, 4116, '易燃液体，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触猛烈反应。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:46', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3982, 4117, '而增加火势和/或蒸气的浓度。蒸气可能会移动到着火源并回闪。液体和蒸气易燃。加热时， 容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3983, 4118, '生强烈反应。容易自聚，聚合反应随着温度的上升而急骤加剧。其蒸气比空气重，能在较 低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 消防人员必须穿全身防火防毒服，在上风向灭火。遇大火，消防人员须在有防护掩蔽处操', '作。灭火剂：抗溶性泡沫、二氧化碳、干粉、砂土。用水灭火无效，但可用水保持火场中 容器冷却。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:48', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3984, 4119, '能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:48', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3985, 4120, '生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。容 易自聚，聚合反应随着温度的上升而急骤加剧。温度超过20℃，能聚合积热，引起爆炸。', '一氧化碳、二氧化碳。 消防人员必须穿全身防火防毒服，在上风向灭火。遇大火，消防人员须在有防护掩蔽处操', '作。灭火剂：抗溶性泡沫、二氧化碳、干粉、砂土。用水灭火无效，但可用水保持火场中 容器冷却。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:48', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3986, 4121, '度的上升而急骤加剧。', '一氧化碳、二氧化碳。 消防人员必须穿全身防火防毒服，在上风向灭火。遇大火，消防人员须在有防护掩蔽处', '操作。灭火剂：泡沫、干粉、二氧化碳、砂土。用水灭火无效，但可用水保持火场中容 器冷却。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:48', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3987, 4122, '温度的上升而急骤加剧。', '一氧化碳、二氧化碳。 消防人员必须穿全身防火防毒服，在上风向灭火。遇大火，消防人员须在有防护掩蔽处操', '作。灭火剂：泡沫、干粉、二氧化碳、砂土。用水灭火无效，但可用水保持火场中容器冷 却。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:50', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3988, 4123, '遇明火、高热可燃。若遇高热，可发生聚合反应，放出大量热量而引起容器破裂和爆炸事 故。受高热分解产生有毒的腐蚀性烟气。', '一氧化碳、二氧化碳。', '采用雾状水、抗溶性泡沫、二氧化碳、干粉、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:50', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3989, 4124, '易燃液体，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触猛烈反应。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氯化氢、光气。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:50', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3990, 4125, '其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压 增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氮氧化物。', '水雾、二氧化碳、干粉、泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:50', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3991, 4126, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。燃烧分解时，放出有毒的氮氧化物。', '一氧化碳、二氧化碳、氧化氮。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:50', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3992, 4127, '遇明火，高热易燃。与氧化剂能发生强烈反应。遇水反应发热放出有毒的腐蚀性气体，若遇高 热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氯化氢、光气。', '干粉、1211灭火剂、二氧化碳、砂土，禁止用水', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3993, 4128, '遇明火、高热可燃。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、氯化氢、氮氧化物、氧化硫。', '泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:52', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3994, 4129, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。加热分解产生毒性气体。', '一氧化碳、二氧化碳。', '干粉、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:52', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3995, 4130, '爆炸性分解。', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:52', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3996, 4131, '爆炸性分解。', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3997, 4132, '强并让火焰自身维持。灭火行动对已发生的火灾可能无效。加热时，容器可能爆炸。受热 或接触火焰可能会产生膨胀或爆炸性分解。', '灭火剂：用水雾、干粉、泡沫或二氧化碳灭火剂灭火。避免使用直流水灭火，直流水可能', '导致可燃性液体的飞溅，使火势扩散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3998, 4133, '强并让火焰自身维持。灭火行动对已发生的火灾可能无效。加热时，容器可能爆炸。受热 或接触火焰可能会产生膨胀或爆炸性分解。', '灭火剂：用水雾、干粉、泡沫或二氧化碳灭火剂灭火。避免使用直流水灭火，直流水可能', '导致可燃性液体的飞溅，使火势扩散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (3999, 4134, '跟可燃物质接触可能会引起火灾。受热或接触火焰可能会产生膨胀或爆炸性分解。燃烧时可能会释放毒性烟雾。', '氯化物、氧化钡。', '选择合适的灭火剂，勿用水。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:54', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4000, 4135, '引起燃烧的危险。受热、遇酸或日光照射会分解放出剧毒的氯气。', '氯化物、氧化钙。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：直流水、雾状水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4001, 4136, '能会通过压力安全阀泄漏出内容物。受热或接触火焰可能会产生膨胀或爆炸性分解。', '氯化物、氧化钾。', '干粉、二氧化碳或耐醇泡沫。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4002, 4137, '跟可燃物质接触可能会引起火灾。受热或接触火焰可能会产生膨胀或爆炸性分解。加热时，容器可能爆炸。', '氯化物、氧化锂。', '使用适合火灾类型的合适的灭火剂。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4003, 4138, '受高热分解产生有毒的腐蚀性烟气。具有腐蚀性。', '氯化物。', '采用雾状水、二氧化碳、砂土灭火。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4004, 4139, '爆炸性分解。', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4005, 4140, '在空气中发热并自燃。受热分解，放出氮、硫的氧化物等毒性气体。', '一氧化碳、二氧化碳、氮氧化物、硫化物、氧化锰。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4006, 4141, '接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、有机过氧化物分解产物', '泡沫、干粉、二氧化碳、砂土。禁止用水直接灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4007, 4142, '若遇高热，容器内压增大，有开裂和爆炸的危险。', '氮气。', '本品不燃。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:58', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4008, 4143, '遇水或潮湿空气剧烈反应，产生高度易燃的氨气。与氧化剂能发生强烈反应。受高热分解，放出有毒的烟气。', '氮氧化物、氧化锂、氨气。', '干粉、砂土。禁止用水、泡沫、二氧化碳、卤代烃灭火剂。消防人员必须佩戴空气呼吸器、穿全身消防服。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:59', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4009, 4144, '遇水或潮气产生有刺激性、腐蚀性的氨毒气。粉体与空气混合，能形成爆炸性混合物。受热或接触火焰可能会产生膨胀或爆炸性分解。', '氮氧化物、氧化镁', '干粉、砂土。禁止用水、泡沫、二氧化碳、卤代烃灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4010, 4145, '易燃气体，与空气混合能形成爆炸性混合物。遇明火、高热极易燃烧爆炸。与氟、氯、溴等卤素会剧烈反应。受热容器内压增大，有开裂和爆炸的危险。', '燃烧时生成蓝色火焰，主要产物为水蒸气。', '切断气源。若不能切断气源，则不允许熄灭泄漏处的火焰。喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:01', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4011, 4146, '受热分解产生有毒烟雾。', '一氧化碳、二氧化碳、氮氧化物', '干粉、二氧化碳、耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:01', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4012, 4147, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、氯化氢。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷 处。灭火剂：泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:01', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4013, 4148, '不易燃烧。受高热分解，放出有毒的烟气。加热时，容器可能爆炸。', '一氧化碳、二氧化碳、氮氧化物、溴化氢', '泡沫、干粉、砂土。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4014, 4149, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、氯化氢', '泡沫、干粉、砂土、水。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4015, 4150, '不易燃烧。受高热分解，放出有毒的烟气。加热时，容器可能爆炸。', '一氧化碳、二氧化碳、氮氧化物、氯化氢', '泡沫、干粉、砂土。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4016, 4151, '遇明火、高热可燃。受热分解，放出氮、硫的氧化物等毒性气体。', '一氧化碳、二氧化碳、氮氧化物、硫化物、氧化钠', '水、泡沫、二氧化碳、干粉、砂土。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4017, 4152, '粉体在受热、遇明火或接触氧化剂时会引起燃烧爆炸。', '无资料', '采用水、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4018, 4153, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4019, 4154, '受高热分解，放出高毒的烟气。', '氧化钾、汞、碘化氢。 合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。', '不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4020, 4155, '器可能爆炸。暴露于火中的容器可能会通过压力安全阀泄漏出内容物。受热或接触火焰可 能会产生膨胀或爆炸性分解。', '无资料 合适的灭火介质:干粉、二氧化碳。不合适的灭火介质:避免用太强烈的水汽灭火，因为它可 能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿', '上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系 统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4021, 4156, '爆炸性分解。', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。', '不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4022, 4157, '受热分解放出有毒的碘化物烟气。', '碘化氢。', '消防人员必须穿全身防火防毒服，在上风向灭火。灭火剂：二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4023, 4158, '遇明火、高热、氧化剂能燃烧，并散发出有毒气体。遇水或水蒸气反应发热放出有毒的腐蚀性 气体。', '一氧化碳、二氧化碳、碘化氢。', '泡沫、二氧化碳、干粉、砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4024, 4159, '受热分解放出有毒的碘化物烟气。', '一氧化碳、二氧化碳、碘化氢。 消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：雾状水、泡沫、二氧化', '碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4025, 4160, '强氧化剂。与易燃物硫、磷、有机物、还原剂接触,能发生化学反应,甚至燃烧。', '碘化氢。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、砂土。在火场中与', '可燃物混合会爆炸，消防人员须在有防爆掩蔽处操作。切勿将水流直接射至熔融物，以免 引起严重的流淌火灾或引起剧烈的沸溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4026, 4161, '强并让火焰自身维持。灭火行动对已发生的火灾可能无效。加热时，容器可能爆炸。暴露 于火中的容器可能会通过压力安全阀泄漏出内容物。受热或接触火焰可能会产生膨胀或爆 炸性分解。', '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4027, 4162, '解放出有毒的碘化物烟气。', '碘化氢、氧化钡。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、砂土。在火场中', '与可燃物混合会爆炸，消防人员须在有防爆掩蔽处操作。切勿将水流直接射至熔融物， 以免引起严重的流淌火灾或引起剧烈的沸溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:08', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4028, 4163, '磷、硒、硫剧烈反应。受热分解放出有毒的碘化物烟气。', '碘化氢、氧化钙。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、砂土。在火场中', '与可燃物混合会爆炸，消防人员须在有防爆掩蔽处操作。切勿将水流直接射至熔融物， 以免引起严重的流淌火灾或引起剧烈的沸溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:08', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4029, 4164, '受热分解放出有毒的碘化物烟气。', '碘化氢、氧化镉。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、砂土。在火场中', '与可燃物混合会爆炸，消防人员须在有防爆掩蔽处操作。切勿将水流直接射至熔融物， 以免引起严重的流淌火灾或引起剧烈的沸溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:08', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4030, 4165, '与可燃物形成爆炸性混合物。', '碘化氢。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、砂土。在火场中', '与可燃物混合会爆炸，消防人员须在有防爆掩蔽处操作。切勿将水流直接射至熔融物， 以免引起严重的流淌火灾或引起剧烈的沸溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:08', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4031, 4166, '与有机物、还原剂、硫、磷等混合，能形成爆炸性混合物。具有较强的腐蚀性。', '碘化氢、氧化钾。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、砂土。在火场中', '与可燃物混合会爆炸，消防人员须在有防爆掩蔽处操作。切勿将水流直接射至熔融物， 以免引起严重的流淌火灾或引起剧烈的沸溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4032, 4167, '无机氧化剂。与还原剂能发生强烈反应，引起燃烧爆炸。受热分解放出有毒的碘化物烟气。', '碘化氢、氧化锂。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、砂土。在火场中', '与可燃物混合会爆炸，消防人员须在有防爆掩蔽处操作。切勿将水流直接射至熔融物， 以免引起严重的流淌火灾或引起剧烈的沸溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:10', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4033, 4168, '强并让火焰自身维持。灭火行动对已发生的火灾可能无效。加热时，容器可能爆炸。受热 或接触火焰可能会产生膨胀或爆炸性分解。', '灭火方法： 合适的灭火介质:使用适合火灾类型的合适的灭火剂。 不合适的灭火介质: 无特别说明。', '合适的灭火介质:使用适合火灾类型的合适的灭火剂。 不合适的灭火介质: 无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:10', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4034, 4169, '蚀性。', '碘化氢。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、砂土。在火场中', '与可燃物混合会爆炸，消防人员须在有防爆掩蔽处操作。切勿将水流直接射至熔融物， 以免引起严重的流淌火灾或引起剧烈的沸溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:10', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4035, 4170, '受热分解放出有毒的碘化物烟气。', '碘化氢、氧化铅。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、砂土。在火场中与', '可燃物混合会爆炸，消防人员须在有防爆掩蔽处操作。切勿将水流直接射至熔融物，以免 引起严重的流淌火灾或引起剧烈的沸溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:10', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4036, 4171, '受热分解放出有毒的碘化物烟气。', '碘化氢、氧化锶。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、砂土。在火场中', '与可燃物混合会爆炸，消防人员须在有防爆掩蔽处操作。切勿将水流直接射至熔融物， 以免引起严重的流淌火灾或引起剧烈的沸溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:12', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4037, 4172, '受热分解放出有毒的碘化物烟气。', '碘化氢。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、砂土。在火场中', '与可燃物混合会爆炸，消防人员须在有防爆掩蔽处操作。切勿将水流直接射至熔融物， 以免引起严重的流淌火灾或引起剧烈的沸溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:12', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4038, 4173, '受热分解放出有毒的碘化物烟气。', '碘化氢、氧化锌。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、砂土。在火场中', '与可燃物混合会爆炸，消防人员须在有防爆掩蔽处操作。切勿将水流直接射至熔融物， 以免引起严重的流淌火灾或引起剧烈的沸溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:12', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4039, 4174, '受热分解放出有毒的碘化物烟气。', '碘化氢。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、砂土。在火场中', '与可燃物混合会爆炸，消防人员须在有防爆掩蔽处操作。切勿将水流直接射至熔融物， 以免引起严重的流淌火灾或引起剧烈的沸溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:12', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4040, 4175, '遇明火、高热可燃。受热分解放出有毒的碘化物烟气。遇潮时对大多数金属有腐蚀性。', '碘化氢、一氧化碳。', '采用雾状水、泡沫、二氧化碳灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4041, 4176, '放出有毒气体。', '一氧化碳、二氧化碳、碘化氢。', '抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4042, 4177, '生有毒的腐蚀性气体。与氧化剂接触猛烈反应。', '一氧化碳、二氧化碳、碘化氢。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4043, 4178, '受热、震动、撞击、摩擦，相当敏感，极易分解发生爆炸。', '氮氧化物、氧化银。', '雾状水。禁止用砂土压盖。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4044, 4179, NULL, '氮氧化物、钡化合物', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:15', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4045, 4180, '受热，接触明火、高热或受到摩擦震动、撞击时可发生爆炸。', '氧化氮。', '雾状水、二氧化碳、泡沫。禁止用砂土压盖。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:15', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4046, 4181, '干燥时，接触明火、高热或受到摩擦震动、撞击时可发生爆炸。与铜生成极敏感的叠氮化铜。能与浓硫酸、发烟硝酸猛烈反应，甚至发生爆炸。遇二氧化碳分解放出叠氮酸。含水或乙醇≥20%时相对稳定，但仍为爆炸品。', '氮氧化物、铅化合物、氧化铅。', '雾状水、泡沫。禁止用砂土压盖，防止产生摩擦火花。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4047, 4182, '易燃。其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂接触发生剧烈反应。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4048, 4183, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4049, 4184, '遇明火能燃烧。与氧化剂可发生反应。受高热或与酸接触会产生剧毒的氰化物气体。', '一氧化碳、二氧化碳、氮氧化物。', '采用抗溶性泡沫、干粉、二氧化碳、砂土灭火。禁止使用酸碱灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4050, 4185, '放热现象，引起容器破裂和爆炸事故。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4051, 4186, '是非常活泼的物质，容易产生聚合。与空气混合能形成爆炸性混合物，遇明火、高热极易燃烧 爆炸。在2～20kPa大气压下可发生爆炸性分解。', '一氧化碳、二氧化碳。 切断气源。若不能立即切断气源，则不允许熄灭正在燃烧的气体，喷水冷却容器，可能的话将', '容器从火场移至空旷处。泡沫、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4052, 4187, '遇明火、高热可燃。受高热分解，放出刺激性烟气。粉体与空气可形成爆炸性混合物，当达到 一定的浓度时，遇火星会发生爆炸。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4053, 4188, '遇明火、高热可燃。受热分解产生有毒气体。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:20', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4054, 4189, '遇明火、高热可燃。受热分解产生有毒气体。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:20', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4055, 4190, '遇明火、高热可燃。受热或遇水分解放热, 放出有毒的腐蚀性烟气。具有较强的腐蚀性。', '一氧化碳、二氧化碳、光气。', '灭火剂：干粉、二氧化碳、砂土。禁止用水和泡沫灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:20', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4056, 4191, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、二氧化碳、泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:20', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4057, 4192, '的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4058, 4193, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。若遇高热，容器内压增大，有开裂和爆炸 的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4059, 4194, '强烈反应。', '一氧化碳、二氧化碳、氧化锂。 消防人员必须穿全身防火防毒服，在上风向灭火。灭火剂：干粉、干砂。禁止使用水、泡', '沫或卤化物灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:22', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4060, 4195, '遇明火、高热可燃。有腐蚀性。受热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氧化磷。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:22', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4061, 4196, '遇明火、高热可燃。受热分解产生有毒的氯化物烟雾。与氧化剂可发生反应。遇水或水蒸气反应放热并产生有毒的腐蚀性气体。具有强腐蚀性。', '氯化氢、氧化硅、一氧化碳、二氧化碳。', '干粉、二氧化碳、砂土。禁止用水、泡沫、酸碱灭火器。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:22', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4062, 4197, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。若遇高热，容器内压增大，有开裂和爆炸 的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:23', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4063, 4198, '遇明火、高热易引起燃烧爆炸。与氧化剂接触会猛烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氮氧化物。', '抗溶性泡沫、干粉、砂土、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:23', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4064, 4199, '遇明火、高热可燃。具有腐蚀性。', '一氧化碳、二氧化碳。 用水喷射逸出液体，使其稀释成不燃性混合物，并用雾状水保护消防人员。灭火剂：雾状水、', '抗溶性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:23', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4065, 4200, '遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。若遇高热，可能发生聚合反应，出现 大量放热现象，引起容器破裂和爆炸事故。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:23', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4066, 4201, '易燃，遇明火、高热能引起燃烧爆炸。与氧化剂可发生反应。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：泡沫、干粉、二氧化碳、砂', '土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:23', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4067, 4202, '性和腐蚀性的氯化氢气体。有腐蚀性。受热分解，放出高毒的烟气。', '一氧化碳、二氧化碳、氯化氢、光气。', '二氧化碳、干粉、砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:24', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4068, 4203, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4069, 4204, '其蒸气与空气形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反 应。 其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源引着回燃。若遇高热，容器内压增 大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4070, 4205, '器破裂或爆炸事故。', '一氧化碳、二氧化碳。', '抗溶性泡沫、二氧化碳、干粉、用水冷却火场容器。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4071, 4206, '的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4072, 4207, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。燃烧分解时，放出有毒的氮氧化物。', '一氧化碳、二氧化碳、氧化氮。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4073, 4208, '遇明火、高热可燃。受热分解产生有毒气体。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4074, 4209, '受热或接触火焰可能会产生膨胀或爆炸性分解。遇明火、高热有引起燃烧爆炸的危险。', '一氧化碳、二氧化碳、氮氧化物', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4075, 4210, '受热或接触火焰可能会产生爆炸性分解', '一氧化碳、二氧化碳', '干粉、二氧化碳或耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4076, 4211, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、氯化氢。', '雾状水、抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4077, 4212, '受热分解产生有毒的烟气。遇明火、高热可燃。', '一氧化碳、二氧化碳等有毒气体', '干粉、二氧化碳、砂土。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4078, 4213, '遇明火、高热可燃。受热分解产生有毒的氯化氢烟雾。', '一氧化碳、二氧化碳、氯化氢。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4079, 4214, '受热分解，放出氮、硫的氧化物等毒性气体。', '一氧化碳、二氧化碳、硫化物、氧化氮。', '雾状水、泡沫、二氧化碳、干粉、砂土。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4080, 4215, '遇明火、高热可燃。', '一氧化碳、二氧化碳。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：雾状水、泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4081, 4216, '遇水发生剧烈化学反应。具有腐蚀性。遇水产生刺激性气体。', '一氧化碳、二氧化碳、光气、氯化氢。', '灭火剂：干粉、二氧化碳、砂土。禁止用水和泡沫灭火。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4082, 4217, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。其蒸气与空气可形成爆炸性混合物。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4083, 4218, '遇明火、高热可燃。受高热分解产生有毒的硫化物烟气。其蒸气与空气可形成爆炸性混合物。', '一氧化碳、二氧化碳、硫化物。', '泡沫、二氧化碳、干粉、砂土。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4084, 4219, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。受高热分解，放出腐蚀性、刺激性的烟雾。其蒸气与空气可形成爆炸性混合物。', '一氧化碳、二氧化碳、氧化氮。', '雾状水、泡沫、二氧化碳、干粉、砂土。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4085, 4220, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。其蒸气与空气可形成爆炸性混合物。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4086, 4221, '受高热分解产生有毒的硫化物烟气。', '一氧化碳、二氧化碳、硫化物。', '雾状水、二氧化碳、泡沫、干粉、砂土。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:32', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4087, 4222, '受高热分解产生有毒的硫化物烟气。遇明火、高热可燃。', '一氧化碳、二氧化碳、氧化硫。', '雾状水、泡沫、二氧化碳、干粉、砂土。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4088, 4223, '遇明火、高热易燃。受高热分解放出有毒的气体。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、氧化硫、氯化氢。', '采用干粉、二氧化碳、砂土灭火。禁止用水。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4089, 4224, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4090, 4225, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4091, 4226, '遇明火能燃烧。接触酸和酸雾产生剧毒气体。', '一氧化碳、二氧化碳、氮氧化物、氰化氢。', '采用泡沫、干粉、二氧化碳、砂土灭火。禁止使用酸碱灭火剂。用水灭火无效，但可用水保持火场中容器冷却。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4092, 4227, '遇明火、高热可燃。受热分解，放出有毒的硫氧化物、氯化物气体。', '一氧化碳、二氧化碳、硫化物、氯化物。', '雾状水、泡沫、二氧化碳、干粉、砂土。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4093, 4228, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。遇热有火灾危险。', '一氧化碳、二氧化碳等有害气体。', '使用适合火灾类型的合适的灭火剂。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。禁止用直流水灭火，以免引起爆炸。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4094, 4229, '能会通过压力安全阀泄漏出内容物。受热或接触火焰可能会产生膨胀或爆炸性分解。遇明火、高热可燃。', '一氧化碳、二氧化碳。', '干粉、二氧化碳或耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:36', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4095, 4230, '受热或接触火焰可能会产生膨胀或爆炸性分解。受热分解产生有毒的氧化氮烟气。', '一氧化碳、二氧化碳、氧化氮。', '合适的灭火介质：干粉、二氧化碳、水喷雾或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:37', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4096, 4231, '受热或接触火焰可能会产生膨胀或爆炸性分解。受热分解产生有毒的氧化氮烟气。', '一氧化碳、二氧化碳、氧化氮。', '合适的灭火介质：干粉、二氧化碳、水喷雾或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:37', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4097, 4232, '受热或接触火焰可能会产生膨胀或爆炸性分解。受热分解产生有毒的氧化氮烟气。', '一氧化碳、二氧化碳、氧化氮。', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:37', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4098, 4233, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、氧化氮。', '合适的灭火介质：干粉、二氧化碳、水喷雾或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:37', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4099, 4234, '遇明火、高热可燃。受高热分解产生有毒的腐蚀性烟气。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、氧化氮。', '采用泡沫、雾状水、干粉、二氧化碳、砂土灭火。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:39', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4100, 4235, '遇明火、高热可燃。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、氮氧化物、溴化氢。', '采用雾状水、泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4101, 4236, '遇明火、高热、氧化剂能燃烧，并散发出有毒气体。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4102, 4237, '遇明火、高热可燃。受热分解产生有毒气体。', '一氧化碳、二氧化碳、氮氧化物、钒氧化物等有毒气体', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4103, 4238, '多硫化铵溶液可燃，受热或接触火焰可能会产生膨胀或爆炸性分解。受热分解产生硫化氢、氨气、二氧化硫等有毒气体。与氧化剂接触可能发生剧烈反应或爆炸。', '受热分解产生硫化氢（H2S）、氨气（NH3）、二氧化硫（SO2）、氧化硫（SO3）等有毒有害气体。', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:43', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4104, 4239, '多氯联苯可燃，遇明火、高热可燃。受热分解温度约为500-700℃，分解产生的烟雾和气体具有极强的毒性和腐蚀性。在火灾情况下，多氯联苯可能通过挥发、烟雾传播等方式扩散到周围环境中，造成严重的环境污染和人员中毒。火灾现场的温度和压力可能加速多氯联苯的分解和扩散，增加其危害性。此外，多氯联苯在高温下可能与其他物质发生反应，生成新的有毒物质。', '氯化氢（HCl）、一氧化碳（CO）、二氧化碳（CO2）、多氯二苯并二噁英（PCDDs）、多氯二苯并呋喃（PCDFs）、氯气（Cl2）等有毒有害气体。燃烧产物具有强腐蚀性和毒性，可对人员健康和环境造成严重危害。氯化氢具有强烈的刺激性和腐蚀性，可引起呼吸道灼伤、肺水肿等严重后果。一氧化碳可导致缺氧、中毒甚至死亡。多氯二苯并二噁英和多氯二苯并呋喃也是持久性有机污染物，具有极高的毒性和持久性。', '干粉灭火器、二氧化碳灭火器、耐醇泡沫灭火器。不合适的灭火介质：避免使用直流水枪灭火，因为水流可能使火苗蔓延分散，并可能导致污染物的扩散。灭火时，消防人员必须佩戴正压自给式呼吸器（SCBA），并穿着全身防护服（包括防化服、防化手套、防化靴等）。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统，应采取措施收集和处理消防废水。如有可能，应将容器从火场移至空旷处。火场周围应设置警戒线，禁止无关人员进入。灭火后，应对现场进行全面清理和检测，确保没有残留的多氯联苯污染。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:43', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4105, 4240, '接触火焰可能会产生膨胀或爆炸性分解。遇明火、高热可燃。受热分解产生有毒的氯化氢气体和光气。燃烧时产生大量浓烟。', '氯化氢、光气、一氧化碳、二氧化碳', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:44', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4106, 4241, '遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。受热分解产生有毒的烟气。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、泡沫、二氧化碳、', '干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:44', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4107, 4242, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '灭火方法： 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4108, 4243, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '灭火方法： 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:46', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4109, 4244, '遇高热、明火或氧化剂，有引起燃烧的危险。', '一氧化碳、二氧化碳。', '雾状水、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:46', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4110, 4245, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '灭火方法： 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4111, 4246, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氯化氢。', '雾状水、抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4112, 4247, '接触火焰可能会产生膨胀 或爆炸性分解。', '无资料', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4113, 4248, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '灭火方法： 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4114, 4249, '接触火焰可能会产生膨胀或爆炸性分解。', '无资料 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4115, 4250, '都可能引起火灾和爆炸。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸 性分解。', '合适的灭火介质: 干粉、二氧化碳、水喷雾或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:50', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4116, 4251, '易燃，遇明火、高热能引起燃烧爆炸。遇水或受热分解，放出有毒的腐蚀性烟气。', '一氧化碳、二氧化碳、氯化氢。 消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：水、二氧化碳、干粉、', '砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:50', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4117, 4252, '能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:50', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4118, 4253, '接触火焰可能会产生膨胀或爆炸性分解。', '无资料', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:50', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4119, 4254, '焰被扑灭后可能复燃。注意有自燃的危险。加热时，容器可能爆炸。受热或接触火焰可能 会产生膨胀或爆炸性分解。', '合适的灭火介质: 干粉、干砂、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:52', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4120, 4255, '遇明火、高热可燃。粉体与空气可形成爆炸性混合物，当达到一定的浓度时，遇火星会发生爆 炸。', '一氧化碳、二氧化碳、氮氧化物。', '二氧化碳、泡沫、干粉、砂土。用水可引起沸溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:52', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4121, 4256, '爆炸性分解。', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4122, 4257, '遇明火、高热可燃。与强氧化剂可发生反应。受热或遇水分解放热，放出有毒的腐蚀性烟气。 有腐蚀性。', '一氧化碳、二氧化碳、氯化氢、氧化硅。', '泡沫、二氧化碳、砂土、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4123, 4258, '遇明火、高热可燃。', '一氧化碳、二氧化碳、氧化硒。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4124, 4259, '遇明火、高热可燃。与氧化剂可发生反应。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、氧化汞。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4125, 4260, '遇明火、高热可燃。受热或遇水、酸分解放热，放出有毒烟气。', '一氧化碳、二氧化碳、氮氧化物。', '二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4126, 4261, '接触火焰可能会产生膨胀或爆炸性分解。', '无资料 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:54', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4127, 4262, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氯化氢、氧化砷。 合适的灭火介质:泡沫、二氧化碳、干粉、砂土。灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH 要求的或相当的)）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消', '防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4128, 4263, '空气，湿气或水可能燃烧。使用时可能产生易燃或易爆的蒸气-空气混合物。加热时，容器 可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质：干粉，干砂或石灰。不合适的灭火介质：水、二氧化碳和泡沫。灭火时，', '应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安全距离处、 有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4129, 4264, '遇明火、高热可燃。有腐蚀性。', '一氧化碳、二氧化碳、溴化氢。 合适的灭火介质:二氧化碳、干粉。灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或 相当的)）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染', '地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4130, 4265, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。若遇高热，容器内压增大，有开裂和爆炸 的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4131, 4266, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。若遇高热，容器内压增大，有开裂和爆炸 的危险。', '一氧化碳、二氧化碳。', '水、泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4132, 4267, '会产生膨胀或爆炸性分解。', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4133, 4268, '遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4134, 4269, '接触可发生化学反应。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：泡沫、二氧化碳、干粉、砂', '土。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4135, 4270, '爆炸性分解。', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4136, 4271, '受热分解放出有毒的碘化物烟气。与三氟化氯、金属钾、金属钠剧烈反应。', '碘化氢、氧化汞。', '本品不燃。消防人员必须穿全身防火防毒服，在上风向灭火。灭火剂：雾状水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:58', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4137, 4272, '受热分解放出有毒的碘化物烟气。与锂、钾钠合金接触剧烈反应。', '一氧化碳、二氧化碳、碘化氢。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：雾状水、泡沫、二氧 化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:59', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4138, 4273, '遇明火、高热可燃。与氧化剂可发生反应。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氧化锡。 合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽 灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的', '或相当的)）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污 染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:59', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4139, 4274, '气体。', '一氧化碳、二氧化碳、氧化锡、氯化氢。', '泡沫、二氧化碳、干粉、水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:59', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4140, 4275, '遇明火、高热可燃。与氧化剂可发生反应。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氧化锡、锡。', '雾状水、抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:59', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4141, 4276, '压力安全阀泄漏出内容物。受热或接触火焰可能会产生膨胀或爆炸性分解。', '无资料 消防人员必须穿全身防火防毒服，在上风向灭火。切断气源。喷水冷却容器，可能的话将容器', '从火场移至空旷处。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:01', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4142, 4277, '会通过压力安全阀泄漏出内容物，从而增加火势和/或蒸气的浓度。蒸气可能会移动到着火 源并回闪。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质: 干粉、二氧化碳或水喷雾。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:01', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4143, 4278, '有腐蚀性。受高热分解产生有毒的腐蚀性烟气。', '氟化氢、氧化磷。', '不燃。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:01', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4144, 4279, '其蒸气与空气形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。 其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，可能发 生聚合反应，出现大量放热现象，引起容器破裂和爆炸事故。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:01', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4145, 4280, '可燃。遇明火、高热可燃。', '一氧化碳、二氧化碳、氧化氮。', '采用干粉、二氧化碳、抗溶性泡沫、砂土灭火。用水灭火无效，但可用水保持火场中容器冷却。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4146, 4281, '易燃，与空气混合能形成爆炸性混合物。遇热源和明火有燃烧爆炸的危险。与氧化剂接触猛烈反 应。气体比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳、氧化氮。 切断气源。若不能切断气源，则不允许熄灭泄漏处的火焰。喷水冷却容器，可能的话将容器从火', '场移至空旷处。灭火剂：雾状水、抗溶性泡沫、干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4147, 4282, '易燃液体，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。蒸气可能会移动到着火源并回闪。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4148, 4283, '爆炸性分解。', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4149, 4284, '遇明火、高热可燃。受热或遇水分解放热，放出有毒的腐蚀性烟气。有腐蚀性。', '一氧化碳、二氧化碳、氧化氮、氯化氢。', '砂土、二氧化碳、干粉、泡沫。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4150, 4285, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。受热或遇水分解，放出剧毒的氮氧化物和 氰化物烟气。', '一氧化碳、二氧化碳、氧化氮、氰化氢。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4151, 4286, '易燃。受热分解产生有毒的氮氧化物烟气。与强氧化剂接触可发生剧烈反应。', '一氧化碳、二氧化碳、氮氧化物。', '合适的灭火介质：干粉、二氧化碳、泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4152, 4287, '产生刺激性、毒性或腐蚀性的气体。加热时，容器可能爆炸。受热或接触火焰可能会产生 膨胀或爆炸性分解。', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4153, 4288, '有毒的腐蚀性烟气。具有腐蚀性。', '一氧化碳、二氧化碳、氧化硅、氯化氢。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：二氧化碳、干粉、干砂。禁', '止用水和泡沫灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4154, 4289, '的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳、氧化硅。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：二氧化碳、干粉、干砂。禁', '止用水和泡沫灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4155, 4290, '遇明火、高热易燃。受热分解产生有毒气体。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4156, 4291, '放出易燃气体。遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。', '一氧化碳、二氧化碳、氧化镁。', '干粉、砂土。禁止用水、雾状水、泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4157, 4292, '不易燃烧。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氧化砷、氧化钠。', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4158, 4293, '暴露在空气中能自燃。接触水、酸类、氧化剂发生剧烈反应，有燃烧爆炸危险。', '一氧化碳、二氧化碳、氧化锌。', '干粉、砂土。禁止用水、泡沫、卤代烃灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:08', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4159, 4294, '其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源引着回燃。若遇高热，容器内压增 大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:08', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4160, 4295, '易燃气体。与空气混合能形成爆炸性混合物。接触热、火星、火焰或氧化剂易燃烧爆炸。接触空 气或在光照条件下可生成具有潜在爆炸危险性的过氧化物。气体比空气重，能在较低处扩散到相 当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。 切断气源。若不能切断气源，则不允许熄灭泄漏处的火焰。喷水冷却容器，可能的话将容器从火', '场移至空旷处。灭火剂：雾状水、抗溶性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:08', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4161, 4296, '受高热分解，放出高毒的烟气。', '一氧化碳、二氧化碳、氧化砷。', '雾状水、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:08', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4162, 4297, '遇明火、高热可燃。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、氧化氮。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4163, 4298, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳、氧化硒。', '泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4164, 4299, '遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。能与酰氯、三氯硅烷、三氯化磷等卤 化物发生剧烈的化学反应。', '一氧化碳、二氧化碳、氧化硫。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:10', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4165, 4300, '猛烈反应。接触空气或在光照条件下可生成具有潜在爆炸危险性的过氧化物。', '一氧化碳、二氧化碳。 尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的', '容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：抗溶性泡沫、二氧 化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:10', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4166, 4301, '爆炸性分解。', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:10', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4167, 4302, '其蒸气与空气形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。 其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。遇高热能发生聚 合反应，出现大量放热现象，引起容器破裂或爆炸事故。', '一氧化碳、二氧化碳。', '雾状水、抗溶性泡沫、干粉、二氧化碳、砂土、用水冷却火场容器。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:10', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4168, 4303, '遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。', '一氧化碳、二氧化碳。', '砂土、泡沫、干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:12', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4169, 4304, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、氧化硫。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4170, 4305, '其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压 增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、硫化氢。', '砂土、泡沫、干粉、二氧化碳、雾状水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4171, 4306, '火焰被扑灭后可能复燃。注意有自燃的危险。加热时，容器可能爆炸。受热或接触火焰可 能会产生膨胀或爆炸性分解。', '合适的灭火介质: 干粉、干砂、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4172, 4307, '其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂能发生强烈反应。高速冲击、流动、激荡后可因产生静电火花放电引起燃烧爆炸。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳、氧化硫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4173, 4308, '和氧化银发生剧烈反应。受高热分解，放出有毒的烟气。', '氧化硫、硒、氧化硒。', '不燃。火场周围可用的灭火介质。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4174, 4309, '爆炸性分解。', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4175, 4310, '烟气。有腐蚀性。', '一氧化碳、二氧化碳、氯化氢、氧化硅。', '抗溶性泡沫、二氧化碳、干粉。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4176, 4311, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。燃烧分解时，放出有毒的氮氧化物。', '一氧化碳、二氧化碳、氯化氢。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4177, 4312, '不燃。受高热分解，放出有毒的氟化物和氯化物气体。', '一氧化碳、二氧化碳、氟化氢、氯化氢。', '本品不燃。切断气源。喷水冷却容器，可能的话将容器从火场移至空旷处。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4178, 4313, '在空气中不发生燃烧爆炸。若遇高热，容器内压增大。有开裂和爆炸的危险。', '氯化氢、氟化氢。', '不燃。水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4179, 4314, '及其它氧化剂剧烈反应。遇水或水蒸气剧烈反应，生成盐酸烟雾。', '氯化氢、氧化硅。 切断气源。若不能切断气源，则不允许熄灭泄漏处的火焰。喷水冷却容器，可能的话将容器从火', '场移至空旷处。灭火剂：雾状水、泡沫、干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4180, 4315, '遇明火、高热可燃。有腐蚀性。受高热分解，放出剧毒的烟气。', '一氧化碳、二氧化碳、氯化氢、氧化磷、磷化氢。', '二氧化碳、砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4181, 4316, '故。对很多金属尤其是潮湿空气存在下有腐蚀性。', '氯化氢、氧化硫。', '消防人员必须穿全身耐酸碱消防服。灭火剂：二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4182, 4317, '受热分解，放出有毒的烟气。', '氯化氢、一氧化碳、二氧化碳。', '二氧化碳、砂土。禁止用水、泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:20', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4183, 4318, '易燃液体，其蒸气与空气可形成爆炸性混合物，遇明火、高热可燃。受高热分解产生有毒的腐蚀性烟气。与碱金属、铝接触可发生反应。光照亦能促进水解而对金属的腐蚀性增强。', '一氧化碳、二氧化碳、氯化氢、光气。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:20', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4184, 4319, '与酸反应，放出有毒的腐蚀性烟气。受高热分解，放出有毒的烟气。若遇高热，容器内压 增大，有开裂和爆炸的危险。', '氯化氢、氧化硫、一氧化碳、二氧化碳。', '二氧化碳、砂土、干粉。不宜用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:20', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4185, 4320, '遇明火、高热可燃。受高热分解，放出腐蚀性、刺激性的烟雾。具有腐蚀性。', '一氧化碳、二氧化碳、氯化氢。', '采用抗溶性泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:20', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4186, 4321, '受高热分解，放出有毒的氟化物和氯化物气体。若遇高热，容器内压增大，有开裂和爆炸的危险。', '氯化氢、氟化氢。', '本品不燃。切断气源。喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:22', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4187, 4322, '气。', '一氧化碳、二氧化碳、氯化物。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:22', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4188, 4323, '不燃。遇火或赤热表面会分解出剧毒的氯化氢、氟化氢，还可能有光气。若遇高热，容器内压增 大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氟化氢、氯化氢。', '本品不燃。切断气源。喷水冷却容器，可能的话将容器从火场移至空旷处。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:22', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4189, 4324, '遇明火、高热可燃。与强氧化剂可发生反应。受热分解放出剧毒的氰化物气体。若遇高热，容 器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氯化氢、氮氧化物。', '干粉、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:22', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4190, 4325, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。受高热分解产生有毒的腐蚀性气体。', '一氧化碳、二氧化碳、氯化氢。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:23', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4191, 4326, '受热或接触酸或酸雾，产生氯化物烟气。', '一氧化碳、二氧化碳、氯化铝。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:23', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4192, 4327, '大多数金属有腐蚀性。', '一氧化碳、二氧化碳、氯化氢。', '采用雾状水、泡沫、二氧化碳灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:24', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4193, 4328, '遇明火、高热易燃。受热分解能放出剧毒的光气。遇水或水蒸气反应放热并产生有毒的腐 蚀性气体。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、氯化氢、光气。', '喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：抗溶性泡沫、干粉、二氧化 碳、砂土。不宜用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:24', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4194, 4329, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质: 干粉、二氧化碳、水喷雾或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:24', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4195, 4330, '遇明火、高热、氧化剂能燃烧，并散发出有毒气体。受热或遇水、酸分解放热，放出有毒烟气。', '一氧化碳、二氧化碳、氯化氢、光气。', '泡沫、二氧化碳、干粉、砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:24', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4196, 4331, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。受高热分解产生有毒的腐蚀性气体。', '一氧化碳、二氧化碳、氯化氢。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4197, 4332, '反应生成易爆炸的三氯化氮。受热或遇潮易分解释出剧毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、氯化物。', '不燃。火场周围可用的灭火介质。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4198, 4333, '遇明火、高热可燃。受高热分解，放出有毒的氮、磷和硫的氧化物烟气。', '一氧化碳、二氧化碳、氧化氮、硫化氢、氧化硫。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4199, 4334, '受高热分解，产生氰化物和氮氧化物剧毒烟气。', '氰化氢、氧化氮。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4200, 4335, '接触火焰可能会产生膨胀或爆炸性分解。', '无资料', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4201, 4336, '其蒸气与空气形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与还原剂及硫、磷混合， 能形成爆炸性混合物。', '一氧化碳、二氧化碳。', '抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4202, 4337, '接触火焰可能会产生膨胀或爆炸性分解。', '无资料', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4203, 4338, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '灭火方法： 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4204, 4339, '会产生膨胀或爆炸性分解。', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4205, 4340, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4206, 4341, '会产生膨胀或爆炸性分解。', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4207, 4342, '相当远的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氮氧化物。', '砂土、泡沫、干粉、二氧化碳。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:32', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4208, 4343, '遇明火、高热可燃。受高热或与酸接触会产生剧毒的氰化物气体。', '一氧化碳、二氧化碳、氰化物、氮氧化物。', '水、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:32', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4209, 4344, '物毒气。', '一氧化碳、二氧化碳、硫化物。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4210, 4345, '生成具有潜在爆炸危险性的过氧化物。与氧化剂能发生强烈反应。其蒸气比空气重，能在较低 处扩散到相当远的地方，遇火源引着回燃。若遇高热，可能发生聚合反应，出现大量放热现象， 引起容器破裂和爆炸事故。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4211, 4346, '爆炸性分解。', '灭火方法： 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4212, 4347, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。遇明火、高热极易引起燃烧爆炸。与氧化剂能发生强烈反应。', '一氧化碳、二氧化碳、氮氧化物', '使用大量水灭火。禁止用沙土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:36', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4213, 4348, '属盐, 增加敏感度。与氧化剂混合能形成爆炸性混合物。', '一氧化碳、二氧化碳、氮氧化物。 遇大火，消防人员须在有防护掩蔽处操作。灭火剂：雾状水、泡沫、二氧化碳。禁止用砂土压', '盖。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4214, 4349, '遇明火、高热易燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。 合适的灭火介质: 干粉、二氧化碳、水喷雾或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:39', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4215, 4350, '敏感性极强的爆炸性物质。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、氮氧化物、氨。', '雾状水、泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4216, 4351, '遇明火、高热可燃。受热分解产生有毒的氮氧化物和氧化钾烟雾。', '一氧化碳、二氧化碳、氮氧化物、氧化钾', '干粉、二氧化碳、泡沫、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4217, 4352, '接触火焰可能会产生膨胀或爆炸性分解。', '无资料 用水雾、干粉、泡沫或二氧化碳灭火剂灭火。避免使用直流水灭火，直流水可能导致可燃', '性液体的飞溅，使火势扩散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4218, 4353, '撞击感度和摩擦感度低于雷汞、叠氮化铅。火焰感度较敏感，与雷汞近似。含水40％以上 时安定性较好。该物质具有腐蚀性。', '一氧化碳、二氧化碳、氮氧化物。', '遇大火，消防人员须在有防护掩蔽处操作。灭火剂：水。禁止用砂土压盖。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4219, 4354, '反应，引起分解。', '溴化氢、氟化氢。', '不燃。火场周围可用的灭火介质。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4220, 4355, '受高热分解产生有毒的溴化物气体。', '一氧化碳、二氧化碳、溴化氢。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：泡沫、干粉、二氧化 碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:43', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4221, 4356, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '氯化氢、溴化氢。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:43', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4222, 4357, '容器可能爆炸。暴露于火中的容器可能会通过压力安全阀泄漏出内容物。受热或接触火焰 可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、溴化氢、溴气等有毒气体。燃烧时可能产生有毒的溴化氢气体，对呼吸道有强烈刺激作用。', '相当的)）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染 地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:43', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4223, 4358, '遇明火、高温能引起分解爆炸和燃烧。燃烧分解时, 放出有毒的氮氧化物气体。', '一氧化碳、二氧化碳、氮氧化物。', '必须在安全距离以外施救。遇大火须远离以防炸伤。灭火剂：雾状水、泡沫、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:43', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4224, 4359, '险。', '氧化氮、一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、砂土、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:44', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4225, 4360, '一般燃料或火箭燃料以及氯代烃等猛烈反应引起爆炸。遇水有腐蚀性，腐蚀作用随水分含量增 加而加剧。', '氮氧化物。 本品不燃。消防人员必须佩戴过滤式防毒面具(全面罩)或隔离式呼吸器、穿全身防火防毒服，', '在上风向灭火。切断气源。喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：干 粉、二氧化碳。禁止用水、卤代烃灭火剂灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4226, 4361, '或爆炸事故。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4227, 4362, '或爆炸事故。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4228, 4363, '或爆炸事故。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4229, 4364, '不燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '氧化硫。 本品不燃。消防人员必须佩戴过滤式防毒面具(全面罩)或隔离式呼吸器、穿全身防火防毒服，在', '上风向灭火。切断气源。喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、 泡沫、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4230, 4365, '易分解发生爆炸。', '氯化氢。', '切断气源。喷水冷却容器，可能的话将容器从火场移至空旷处。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4231, 4366, '热分解放出有毒的气体。', '氧化铅。', '雾状水、砂土、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4232, 4367, '若遇高热，容器内压增大，有开裂和爆炸的危险。', '无资料', '本品不燃。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4233, 4368, '本身不能燃烧。若遇高热，升华产生剧毒的气体。', '氧化硒。', '砂土、火场周围可用的灭火介质。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4234, 4369, '或爆炸事故。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4235, 4370, '放射性物品。在炽热空气中能自燃并猛烈燃烧。', '无资料', '二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4236, 4371, '重，能在较低处扩散到相当远的地方，遇火源会着火回燃。有腐蚀性，能腐蚀玻璃。', '一氧化碳、二氧化碳、氮氧化物。 喷水冷却容器，可能的话将容器从火场移至空旷处。处在火场中的容器若已变色或从安全', '泄压装置中产生声音，必须马上撤离。灭火剂：抗溶性泡沫、二氧化碳、干粉、砂土。用 水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4237, 4372, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。接触空气有生成过氧物的危险。', '一氧化碳、二氧化碳。', '雾状水，泡沫，二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4238, 4373, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。接触空气有生成过氧化物的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4239, 4374, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4240, 4375, '烈反应。', '一氧化碳、二氧化碳、氮氧化物。', '水、二氧化碳。禁止用砂土压盖。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4241, 4376, '潜在爆炸危险性的过氧化物。若遇高热，可发生聚合反应，放出大量热量而引起容器破裂和爆 炸事故。', '一氧化碳、二氧化碳。 尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的容器', '若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：雾状水、泡沫、干粉、二氧 化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4242, 4377, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。接触空气有生成过化物的危险。', '一氧化碳、二氧化碳。', '雾状冰、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4243, 4378, '遇明火、高热可燃。受高热或接触酸或酸雾放出剧毒的烟雾。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、二氧化碳、干粉、砂土。禁止使用酸碱灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:52', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4244, 4379, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4245, 4380, '遇高热、明火或氧化剂，有引起燃烧的危险。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、氮氧化物、氧化硫。', '泡沫、二氧化碳、水、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4246, 4381, '产生大量的腐蚀性烟雾。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氯化氢、氧化硅。', '抗溶性泡沫、干粉、二氧化碳。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4247, 4382, '遇明火、高热可燃。与氧化剂可发生反应。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、氧化汞。', '雾状水、泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4248, 4383, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '氮氧化物。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4249, 4384, '出易燃气体。遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。', '一氧化碳、二氧化碳、氧化镁。', '干粉、砂土。禁止用水、泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4250, 4385, '可能会释放毒性烟雾。加热时，容器可能爆炸。暴露于火中的容器可能会通过压力安全阀 泄漏出内容物。受热或接触火焰可能会产生膨胀或爆炸性分解。', '无资料 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。不合适的灭火介质:避免用太强烈的水汽灭 火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或', '相当的)）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染 地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4251, 4386, '二氧化硫发生爆炸性反应。能和溴、水、硝基化合物发生剧烈反应。接触空气、臭氧、甲 醇或胂能着火。和非金属卤化物剧烈反应生成可自燃的产物。', '一氧化碳、二氧化碳、氧化锌。', '干粉、砂土。禁止用水、泡沫、卤代烃灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4252, 4387, '水及水蒸气均能生成有毒和易燃的气体。', '一氧化碳、二氧化碳、硫化氢、氧化硫。', '喷水冷却容器，可能的话将容器从火场移至空旷处。泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4253, 4388, '其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂能发生强烈反应。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:56', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4254, 4389, '程中,易发生自聚反应,酿成事故。其蒸气比空气重，能在较低处扩散到相当远的地方，遇 火源会着火回燃。', '一氧化碳、二氧化碳。 尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的', '容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：抗溶性泡沫、二氧 化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4255, 4390, '远的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4256, 4391, '接触空气或在光照条件下可生成具有潜在爆炸危险性的过氧化物。其蒸气比空气重，能在较低 处扩散到相当远的地方，遇火源引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4257, 4392, '生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。具 有腐蚀性。', '一氧化碳、二氧化碳、氧化氮。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：抗溶性泡沫、二氧化碳、干', '粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4258, 4393, '遇明火、高热可燃。与强氧化剂接触可发生化学反应。具有腐蚀性。', '一氧化碳、二氧化碳、氧化氮。', '喷水保持火场容器冷却，直至灭火结束。灭火剂：水、干粉、二氧化碳、抗溶性泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:59', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4259, 4394, '氮烟气。具有腐蚀性。', '一氧化碳、二氧化碳、氧化氮。 尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火剂：雾状', '水、泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:59', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4260, 4395, '遇明火、高热能引起燃烧爆炸。与强氧化剂发生反应，可引起燃烧。若遇高热，容器内压增大， 有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '二氧化碳、泡沫、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:59', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4261, 4396, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。燃烧分解时，放出有毒的氮氧化物。', '一氧化碳、二氧化碳、氮氧化物。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:38:59', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4262, 4397, '险性的过氧化物。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：二氧化碳、泡沫、干粉、砂', '土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4263, 4398, '遇明火、高热可燃。受高热分解，放出有毒的烟气。有腐蚀性。', '一氧化碳、二氧化碳、氧化磷。', '泡沫、抗溶性泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:01', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4264, 4399, '比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。具有腐蚀性。', '一氧化碳、二氧化碳、氧化氮。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：抗溶性泡沫、二氧化碳、干', '粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:01', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4265, 4400, '接触火焰可能会产生膨胀或爆炸性分解。', '无资料', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:01', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4266, 4401, '遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。', '一氧化碳、二氧化碳、氧化氮。 用水喷射逸出液体，使其稀释成不燃性混合物，并用雾状水保护消防人员。灭火剂：水、抗溶', '性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4267, 4402, '接触火焰可能会产生膨胀或爆炸性分解。', '无资料', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4268, 4403, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4269, 4404, '遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。燃烧分解时, 放出有毒的氮氧化 物 气体。', '一氧化碳、二氧化碳、氮氧化物。', '采用泡沫、二氧化碳、干粉、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4270, 4405, '容器可能爆炸。暴露于火中的容器可能会通过压力安全阀泄漏出内容物。受热或接触火焰 可能会产生膨胀或爆炸性分解。', '无资料 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。不合适的灭火介质:避免用太强烈的水汽灭火， 因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当', '的)）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表 和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4271, 4406, '强氧化剂，与可燃物、还原剂、有机物等接触有燃烧爆炸危险。本身不燃烧，但能助燃。受热分解产生有毒的氮氧化物。', '氮氧化物', '合适的灭火介质：雾状水、泡沫、二氧化碳、干粉。不合适的灭火介质：禁止使用直流水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4272, 4407, '炸性分解。', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4273, 4408, '炸性分解。', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4274, 4409, '受热或接触火焰可能会产生膨胀或爆炸性分解。在火场中，受热的容器有爆炸危险。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氮氧化物等有毒气体', '干粉、二氧化碳、耐醇泡沫。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4275, 4410, '受热或接触火焰可能会产生膨胀或爆炸性分解。在火场中，受热的容器有爆炸危险。', '一氧化碳、二氧化碳、氮氧化物、硫化物等有害燃烧产物', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4276, 4411, '星会发生爆炸。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4277, 4412, '的危险。', '一氧化碳、二氧化碳。', '抗溶性泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4278, 4413, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。受高热分解，放出刺激性烟气。', '一氧化碳、二氧化碳。', '抗溶性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:08', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4279, 4414, '物,当达到一定浓度时,遇火星会发生爆炸。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、泡沫、二氧化碳、', '干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:08', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4280, 4415, '易燃液体，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂能发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '抗溶性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4281, 4416, '其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4282, 4417, '遇明火、高热可燃。受热或遇水分解放热，放出有毒的腐蚀性烟气。有腐蚀性。', '一氧化碳、二氧化碳、氯化氢。', '二氧化碳、泡沫、砂土、干粉。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4283, 4418, '与水或杂质接触时，可发生激烈反应而燃烧，使容器破裂。氟对许多金属有腐蚀性，并能形成一层保护性金属氟化物。', '氟化氢。', '本品不燃。消防人员必须穿特殊防护服，在掩蔽处操作。切断气源。须有无人操纵的定点水塔或雾状水保持火场中容器冷却，切不可将水直接喷到漏气的地方，否则会助长火势。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4284, 4419, '遇明火、高热易燃。蒸气可能会移动到着火源并回闪。', '一氧化碳、二氧化碳、氟化氢。', '泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4285, 4420, '蒸气可能会移动到着火源并回闪。液体和蒸气易燃。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、氟化氢。', '干粉、二氧化碳或耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4286, 4421, '受高热分解，放出有毒的烟气。', '受热分解产生氟化氢、氧化钾等有毒气体。', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4287, 4422, '受热分解放出有毒的氟化物气体。具有较强的腐蚀性。', '氟化氢。', '消防人员必须穿全身耐酸碱消防服。灭火剂：泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4288, 4423, '与酸反应，放出有毒的腐蚀性烟气。受高热分解，放出有毒的烟气。', '氮氧化物、氧化硅、氟化氢、氨。', '雾状水、抗溶性泡沫、二氧化碳、干粉。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:12', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4289, 4424, '与酸反应，放出有毒的腐蚀性烟气。受高热分解，放出有毒的烟气。', '氟化钾、四氟化硅、氧化钾。', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4290, 4425, '受高热或接触酸或酸雾放出剧毒的烟雾。', '氟化氢、氧化硅、氧化钠。', '水、砂土、干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4291, 4426, '受热分解产生腐蚀性烟气。', '氟化氢、氨、氮氧化物。', '泡沫、二氧化碳、水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4292, 4427, '受高热分解，放出有毒的烟气。', '氧化钡、氟化氢。', '干粉、二氧化碳或耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4293, 4428, '受高热分解，放出有毒的烟气。', '氟化氢、氧化锆', '干粉、二氧化碳或耐醇泡沫。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:15', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4294, 4429, '与钾发生剧烈反应。受高热分解，放出高毒的烟气。', '氟化氢、镉', '干粉、二氧化碳或耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:15', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4295, 4430, '受高热分解, 放出刺激性烟气。', '氟化氢。', '采用水、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:15', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4296, 4431, '爆炸性分解。受高热分解，放出有毒的烟气。', '受热分解产生氟化氢、汞蒸气等有毒有害气体。', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:15', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4297, 4432, '本品不燃，但遇水或潮气反应产生氢氟酸，遇高温分解产生有毒的氟化物气体。放出有毒的烟气。', '氟化氢、氧化钴等有毒气体。', '不燃。火场周围可用的灭火介质：干粉、二氧化碳、砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4298, 4433, '与酸类反应放出有腐蚀性、刺激性更强的氢氟酸，能腐蚀玻璃。', '氟化氢。', '用大量水灭火。用雾状水驱散烟雾与刺激性气体。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4299, 4434, '遇明火、高热可燃。受热分解产生有毒氟化物烟雾。', '氟化氢、氧化镧', '干粉、二氧化碳、砂土。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:17', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4300, 4435, '受高热分解，放出有毒的烟气。', '氟化氢、氧化锂', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:17', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4301, 4436, '与碱金属能发生剧烈反应。', '氟化氢、氧化铝。', '用大量水灭火。用雾状水驱散烟雾与刺激性气体。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:17', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4302, 4437, '与酸类反应放出有腐蚀性、刺激性更强的氢氟酸，能腐蚀玻璃。', '氟化氢。', '用大量水灭火。用雾状水驱散烟雾与刺激性气体。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:17', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4303, 4438, '能与碳化钙、氟剧烈反应。与硫酸反应可产生氟化氢。', '氟化氢、氧化铅。', '用大量水灭火。用雾状水驱散烟雾与刺激性气体。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4304, 4439, '氟化氢为反应性极强的物质，能与各种物质发生反应。腐蚀性极强。', '氟化氢。', '不燃。火场周围可用的灭火介质。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4305, 4440, '受热分解，放出有毒的氮氧化物和氟化物烟气。', '氧化氮、氟化氢、氨气。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4306, 4441, '吸潮或遇水会产生大量的腐蚀性烟雾。其水溶液有腐蚀性和强烈的刺激性。受高热分解产生有毒的腐蚀性烟气。', '氟化氢、氧化钾。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4307, 4442, '受热分解产生高毒的氟化物烟气。', '氟化氢、氧化钠。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4308, 4443, '未有特殊的燃烧爆炸特性。', '氟化氢。', '用大量水灭火。用雾状水驱散烟雾与刺激性气体。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:20', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4309, 4444, '未有特殊的燃烧爆炸特性。', '氟化氢。', '用大量水灭火。用雾状水驱散烟雾与刺激性气体。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4310, 4445, '遇酸分解，放出腐蚀性的氟化氢气体。受高热分解，放出高毒的烟气。', '氟化氢。', '不燃。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4311, 4446, '能与钾猛烈反应。', '氟化氢。', '用大量水灭火。用雾状水驱散烟雾与刺激性气体。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4312, 4447, '受高热分解，放出有毒的烟气。', '氧化钴、氟化氢。', '不燃。火场周围可用的灭火介质。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4313, 4448, '露置空气中冒烟, 加热更甚, 有强烈的刺激性和腐蚀性。遇水发生剧烈反应，散发出白色有强 刺激性和腐蚀性的氟化氢烟雾。遇潮时对玻璃、其它硅质材料及大多数金属有强腐蚀性。', '氟化氢、氧化硫。', '消防人员必须穿全身耐酸碱消防服。灭火剂：二氧化碳、砂土。禁止用水和泡沫灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:23', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4314, 4449, '气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氟化氢。', '切断气源；若不能立即切断气源，则不允许熄灭正在燃烧的气体，喷水冷却容器，尽可能将容器从火场移至空旷处。雾状水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:23', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4315, 4450, '会产生膨胀或爆炸性分解。', '氟化氢、氧化磷。', '本品不燃。根据周围环境选择合适的灭火剂。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:24', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4316, 4451, '遇发泡剂立即燃烧。受热分解放出有毒的氟化物气体。能腐蚀大多数金属及有机组织。', '氟化氢、氧化硼。', '消防人员必须穿全身耐酸碱消防服。灭火剂：二氧化碳、砂土。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:24', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4317, 4452, '都可能引起火灾和爆炸。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、氮氧化物、氟化氢。', '合适的灭火介质：干粉、二氧化碳、水喷雾或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:24', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4318, 4453, '受高热分解，放出高毒的烟气。', '镉、氟化氢、氧化硼、氧化镉。', '本品不燃。根据周围环境选择合适的灭火剂。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:24', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4319, 4454, '受高热分解，放出高毒的烟气。', '铅、氟化氢、氧化硼。', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4320, 4455, '不燃。受热分解产生有毒气体。', '锌、氟化氢、氧化硼。', '本品不燃。根据周围环境选择合适的灭火剂。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4321, 4456, '不燃。受热分解产生有毒气体。', '银、氟化氢、氧化硼。', '本品不燃。根据周围环境选择合适的灭火剂。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4322, 4457, '会产生膨胀或爆炸性分解。', '受热分解产生氟化氢、氧化铍、氨等有毒气体。', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4323, 4458, '会产生膨胀或爆炸性分解。', '受热分解产生氟化氢、氧化铍等有毒气体。', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4324, 4459, '受高热分解，放出有毒的烟气。', '氧化钾、氟化物。', '不燃。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4325, 4460, '会产生膨胀或爆炸性分解。遇明火、高热可燃。', '一氧化碳、二氧化碳、氟化氢、氮氧化物', '干粉、二氧化碳或耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4326, 4461, '可能会释放毒性烟雾。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、氟化氢。', '干粉、二氧化碳或耐醇泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4327, 4462, '遇明火、高热可燃。受高热分解，放出高毒的烟气。', '一氧化碳、二氧化碳、氟化氢、氧化钾。', '泡沫、砂土、水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4328, 4463, '遇明火、高热可燃。受高热分解，放出高毒的烟气。', '一氧化碳、二氧化碳、氟化氢、氧化钠。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4329, 4464, '易燃。受高热分解，放出高毒的烟气。', '一氧化碳、二氧化碳、氟化氢。', '泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4330, 4465, '其蒸气与空气形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氟化氢。', '切断气源。若不能立即切断气源，则不允许熄灭正在燃烧的气体，喷水冷却容器，可能的话将容器从火场移至空旷处。雾状水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4331, 4466, '比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，可能发生聚合反应，出现大量放热现象，引起容器破裂和爆炸事故。', '一氧化碳、二氧化碳、氟化氢。', '切断气源。若不能立即切断气源，则不允许熄灭正在燃烧的气体，喷水冷却容器，可能的话将容器从火场移至空旷处。雾状水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4332, 4467, '燃烧时放出有毒的刺激性烟雾。遇水或酸发生反应放出氢气及热量,能引起燃烧。粉尘与 湿气接触能灼伤眼睛和皮肤。', '氧化钙。 严禁用水、卤代烃灭火剂施救，也不宜用二氧化碳灭火。在灭火时，如灭火剂选用不当，', '也可发生猛烈反应，引起爆炸，必须特别注意消防施救安全。灭火剂：干燥石墨粉、苏 打灰、氯化钠粉末。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4333, 4468, '遇明火、高热可燃。燃烧产生有毒烟雾。', '一氧化碳、二氧化碳。', '尽可能将容器从火场移至空旷处。灭火剂：雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4334, 4469, '接触火焰可能会产生膨胀或爆炸性分解。遇明火、高热、撞击、摩擦有引起爆炸的危险。', '氮氧化物、一氧化碳、二氧化碳。', '尽可能将容器从火场移至空旷处。灭火剂：雾状水、泡沫、二氧化碳。禁止使用砂土、干粉、直流水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4335, 4470, '无机氧化剂。遇易燃物、有机物会引起爆炸。受热分解，放出氧气。', '碘化氢、碘蒸气。', '采用雾状水、砂土灭火。在火场中与可燃物混合会爆炸，消防人员须在有防爆掩蔽处操作。切勿将水流直接射至熔融物，以免引起严重的流淌火灾或引起剧烈的沸溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4336, 4471, '并让火焰自身维持。灭火行动对已发生的火灾可能无效。加热时，容器可能爆炸。受热或接 触火焰可能会产生膨胀或爆炸性分解。', '碘化氢、碘蒸气、氧化钡。', '采用雾状水、砂土灭火。避免使用大量水，防止火势蔓延。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4337, 4472, '急剧加热时可发生爆炸。', '碘化氢、碘蒸气。', '采用雾状水、砂土灭火。在火场中与可燃物混合会爆炸，消防人员须在有防爆掩蔽处操作。切勿将水流直接射至熔融物，以免引起严重的流淌火灾或引起剧烈的沸溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:32', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4338, 4473, '急剧加热时可发生爆炸。', '氮氧化物、氧气。', '采用雾状水、水灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4339, 4474, '受热分解，放出氧气。', '氯化物、氧化锂。', '采用雾状水、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4340, 4475, '受热分解，放出氧气。', '氯化氢、氧化镁。', '采用雾状水、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4341, 4476, '急剧加热时可发生爆炸。', '氯化物。', '采用雾状水、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4342, 4477, '会剧烈反应引起爆炸。', '氯化氢、氧化铅。', '采用雾状水、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4343, 4478, '与还原剂、有机物、易燃物或金属粉末接触可形成爆炸性混合物。受热分解，放出氧气。', '氯化物。', '采用雾状水、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:36', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4344, 4479, '铵盐形成爆炸性混合物。受热或受热或经摩擦、震动或撞击可引起燃烧或爆炸。', '氧化钡、氧化锰。', '水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:36', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4345, 4480, '遇硫酸、铵盐或过氧化氢能发生爆炸。遇甘油、乙醇能引起自燃。', '氧化钙、氧化锰。', '采用雾状水、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:37', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4346, 4481, '还原剂、易燃物如硫、磷等接触或混合时有引起燃烧爆炸的危险。', '氧化钾、氧化锰。', '采用水、雾状水、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:37', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4347, 4482, '还原剂、易燃物如硫、磷等接触或混合时有引起燃烧爆炸的危险。', '氧化锰。', '采用雾状水、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:37', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4348, 4483, '并让火焰自身维持。灭火行动对已发生的火灾可能无效。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '氧化银、氧化锰。', '采用雾状水、砂土灭火。避免使用大量水，防止火势蔓延。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:37', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4349, 4484, '其粉体遇高热、明火能燃烧甚至爆炸。', '氧化镉。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4350, 4485, '产生膨胀或爆炸性分解。', '灭火方法： 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:39', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4351, 4486, '强氧化剂。接触有机物有引起燃烧危险。受高热分解，放出有毒的烟气。', '氧化钾、氧化铬。', '不燃。火场周围可用的灭火介质。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:39', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4352, 4487, '强氧化剂。接触有机物有引起燃烧危险。受高热分解，放出有毒的烟气。', '氧化钠、氧化铬。', '不燃。火场周围可用的灭火介质。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:39', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4353, 4488, '炸性分解。', '灭火方法： 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:39', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4354, 4489, '受高热分解，放出有毒的蒸气。', '氧化铅、氧化铬。', '不燃。火场周围可用的灭火介质。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4355, 4490, '有腐蚀性。强氧化剂。接触有机物有引起燃烧危险。', '氧化铬。', '水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4356, 4491, '接触火焰可能会产生膨胀或爆炸性分解。', '无资料 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4357, 4492, '遇明火、高热、氧化剂能燃烧，并散发出有毒气体。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:43', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4358, 4493, '可能会释放毒性烟雾。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性 分解。', '合适的灭火介质：小火：干式化学灭火剂、二氧化碳、水或抗溶泡沫灭火剂；大火：水、', '水雾或抗溶泡沫灭火剂。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使 火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:43', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4359, 4494, '遇明火、高热可燃。有腐蚀性。', '一氧化碳、二氧化碳。', '雾状水、抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:44', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4360, 4495, '常温下有蒸气挥发，高温下能迅速挥发。与氯酸盐、硝酸盐、热硫酸等混合可发生爆炸。', '氧化汞。', '不燃。根据着火原因选择适当灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4361, 4496, '遇明火、高热可燃。受热分解，放出有毒烟气。加热时，容器可能爆炸。', '一氧化碳、二氧化碳、氮氧化物、氯化氢、氰化氢', '干粉、二氧化碳、耐醇泡沫。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4362, 4497, '遇明火、高热可燃。粉体与空气可形成爆炸性混合物，遇明火、高热有燃烧爆炸危险。', '氧化硅。', '干粉、砂土。禁止用水。禁止用二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4363, 4498, '遇水放出易燃气体。受热或接触火焰可能会产生膨胀或爆炸性分解。', '硅化氢、氧化硅', '合适的灭火介质: 干粉，干砂或石灰。不合适的灭火介质: 水、二氧化碳和泡沫。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4364, 4499, '遇水或潮湿空气会释放易燃气体，可引起火灾或爆炸。粉体与空气可形成爆炸性混合物，遇明火、高热有燃烧爆炸危险。', '氧化硅、氧化钙、氢气、硅烷等', '干粉、砂土、二氧化碳。禁止用水、泡沫、酸碱灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4365, 4500, '遇水或潮湿空气会释放易燃气体，可引起火灾或爆炸。粉体与空气可形成爆炸性混合物，遇明火、高热有燃烧爆炸危险。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '氧化镁、氧化硅、氢气、硅烷等', '干粉、干砂或石灰。禁止用水、二氧化碳和泡沫。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4366, 4501, '遇水或潮湿空气会释放易燃气体，可引起火灾或爆炸。粉体与空气可形成爆炸性混合物，遇明火、高热有燃烧爆炸危险。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '氧化镁、氧化硅、氢气、硅烷等', '干粉、干砂或石灰。禁止用水、二氧化碳和泡沫。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4367, 4502, '遇水放出易燃气体。受热分解放出有毒蒸气。', '硅化氢、氧化锂、氧化硅', '干粉、干砂或石灰。禁止用水、二氧化碳和泡沫灭火。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4368, 4503, '遇水放出易燃气体。受热或接触火焰可能会产生膨胀或爆炸性分解。', '硅化氢、氧化硅', '干粉、干砂或石灰', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:48', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4369, 4504, '遇水放出易燃气体。受热或接触火焰可能会产生膨胀或爆炸性分解。', '硅化氢、氧化锰、氧化钙、氧化硅', '干粉、干砂或石灰。禁止用水、二氧化碳和泡沫灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4370, 4505, '不燃。受高热分解，放出有毒的氧化铅和氧化硅烟雾。', '氧化铅、氧化硅、一氧化碳、二氧化碳。', '根据周围环境选择合适的灭火剂。火场周围可用的灭火介质：水、泡沫、干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4371, 4506, '受高热分解，放出有毒的蒸气。', '氧化铅、氧化硅。', '不燃。火场周围可用的灭火介质。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4372, 4507, '易燃，遇高热、明火有引起燃烧的危险。遇水能逐渐水解放出刺激性气体。', '一氧化碳、二氧化碳、氧化硅。', '灭火剂：二氧化碳、干粉、砂土。禁止用水和泡沫灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:50', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4373, 4508, '遇水放出易燃气体。受热或接触火焰可能会产生膨胀或爆炸性分解。', '硅化氢、氧化硅', '合适的灭火介质: 干粉，干砂或石灰。不合适的灭火介质: 水、二氧化碳和泡沫。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4374, 4509, '遇水放出易燃气体。受热或接触火焰可能会产生膨胀或爆炸性分解。', '硅化氢、氧化硅', '合适的灭火介质: 干粉，干砂或石灰。不合适的灭火介质: 水、二氧化碳和泡沫。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4375, 4510, '遇明火、高热、氧化剂能燃烧，并散发出有毒气体。', '一氧化碳、二氧化碳；氯化氢、光气。', '泡沫、二氧化碳、干粉、砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4376, 4511, '混合可形成爆炸性混合物。', '氧化氮、氧化硫。', '采用雾状水、泡沫、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4377, 4512, '急剧加热时可发生爆炸。', '氧化硫、氧气。', '采用雾状水、泡沫、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:52', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4378, 4513, '在室温下迅速分解，其蒸气接触空气能自燃。受热或震动撞击时可发生爆炸。与还原剂、 促进剂、有机物、可燃物等接触发生剧烈反应，有燃烧爆炸危险。', '一氧化碳、二氧化碳。', '抗溶性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4379, 4514, '接触火焰可能会产生膨胀或爆炸性分解。', '无资料', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:54', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4380, 4515, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '灭火方法： 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:54', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4381, 4516, '强并让火焰自身维持。灭火行动对已发生的火灾可能无效。加热时，容器可能爆炸。受热 或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质: 水。 不合适的灭火介质: 干粉、二氧化碳或泡沫。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:54', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4382, 4517, '触时就会爆炸。对摩擦、撞击和热敏感，易起爆。有强腐蚀性。', '一氧化碳、二氧化碳。 消防人员须在有防爆掩蔽处操作。灭火剂：雾状水、二氧化碳、砂土。遇大火切勿轻易接', '近。在物料附近失火，须用水保持容器冷却。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4383, 4518, '急剧加热时可发生爆炸。', '氧化硫。', '采用雾状水、泡沫、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:56', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4384, 4519, '强氧化剂。与可燃气体或蒸气、氰化钾、硫氰化钾、氧化氮等发生爆炸性反应。与含氮碱 类(如异丙胺、苯胺、苯肼等)反应生成爆炸性产物。受热分解，放出有毒的烟气。', '氯化氢、氟化氢。', '切断气源。用水冷却火场容器。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:56', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4385, 4520, '弱氧化剂。加热时可能发生爆炸。遇潮气逐渐分解。与易燃物、有机物接触易着火燃烧。', '氧气、氧化硼。', '雾状水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:56', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4386, 4521, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '灭火方法： 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4387, 4522, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '灭火方法： 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4388, 4523, '接触火焰可能会产生膨胀或爆炸性分解。', '无资料', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4389, 4524, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '灭火方法： 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:59', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4390, 4525, '过氧化物，受热、光照、猛烈撞击或遇明火、硫酸，均有引起燃烧爆炸的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、三氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4391, 4526, '接触火焰可能会产生膨胀或爆炸性分解。', '无资料', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:01', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4392, 4527, '遇低级醇和水起化学反应而分解。急剧加热时可发生爆炸。', '氧化钡。', '采用干粉、砂土灭火。严禁用水、泡沫、二氧化碳扑救。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:01', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4393, 4528, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '灭火方法： 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4394, 4529, '接触火焰可能会产生膨胀或爆炸性分解。', '无资料', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4395, 4530, '接触火焰可能会产生膨胀或爆炸性分解。', '无资料', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4396, 4531, '与还原剂、促进剂、有机物、可燃物等接触会发生剧烈反应，有燃烧爆炸的危险。', '一氧化碳、二氧化碳、氯化氢。 消防人员须在有防爆掩蔽处操作。灭火剂：雾状水、砂土。遇大火切勿轻易接近。在物料', '附近失火，须用水保持容器冷却。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4397, 4532, '接触火焰可能会产生膨胀或爆炸性分解。', '无资料', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4398, 4533, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '灭火方法： 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4399, 4534, '可燃物等接触会发生剧烈反应，有燃烧爆炸的危险。', '一氧化碳、二氧化碳。 消防人员须在有防爆掩蔽处操作。灭火剂：雾状水、二氧化碳、砂土。遇大火切勿轻易接', '近。在物料附近失火，须用水保持容器冷却。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:07', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4400, 4535, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '灭火方法： 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:07', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4401, 4536, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '灭火方法： 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:08', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4402, 4537, '强氧化剂。常温下能分解，引起燃烧爆炸。与还原剂、促进剂、有机物、可燃物等接触发 生剧烈反应，有燃烧爆炸危险。', '一氧化碳、二氧化碳。', '抗溶性泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:08', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4403, 4538, '对温度、震动、撞击及接触酸、碱等化学品特别敏感，极易分解而引起爆炸。', '一氧化碳、二氧化碳。', '雾状水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:08', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4404, 4539, '蒸气比空气重，易在低处聚集。封闭区域内的蒸气遇火能爆炸。蒸气能扩散到远处，遇点 火源着火，并引起回燃。储存容器及其部件可能向四面八方飞射很远。', '无资料 消除点火源。如果该物质或被污染的流体进入水路，通知有潜在水体污染的下游用户，通 知地方卫生、消防官员和污染控制部门。使用于粉、泡沫、二氧化碳灭火。在安全防爆距', '离以外，使用雾状水冷却暴露的容器。若冷却水流不起作用(排放音量、音调升高，罐体变 色或有任何变形的迹象)，立即撤离到安全区域。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4405, 4540, '强氧化剂。遇热、明火、摩擦、撞击或与还原剂接触可能发生剧烈分解或爆炸。受热分解产生易燃和有毒气体。', '一氧化碳、二氧化碳、苯酚、有机酸等有毒有害燃烧产物。', '雾状水、砂土、二氧化碳、干粉。禁止使用直流水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:10', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4406, 4541, '加热时，容器可能爆炸。暴露于火中的容器可能会通过压力安全阀泄漏出内容物。受热或 接触火焰可能会产生膨胀或爆炸性分解。', '无资料', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:10', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4407, 4542, '接触火焰可能会产生膨胀或爆炸性分解。', '无资料', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4408, 4543, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '灭火方法： 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4409, 4544, '遇潮气逐渐分解。具有较强的腐蚀性。', '氧化钙。', '采用干粉、砂土灭火。严禁用水、泡沫、二氧化碳扑救。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:12', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4410, 4545, '温下即可着火。对撞击、摩擦敏感，易发生爆炸。', '一氧化碳、二氧化碳。 消防人员须在有防爆掩蔽处操作。灭火剂：雾状水、二氧化碳、砂土。遇大火切勿轻易接', '近。在物料附近失火，须用水保持容器冷却。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:12', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4411, 4546, '接触火焰可能会产生膨胀或爆炸性分解。', '无资料', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4412, 4547, '接触火焰可能会产生膨胀或爆炸性分解。', '无资料', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4413, 4548, '接触火焰可能会产生膨胀或爆炸性分解。', '无资料', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4414, 4549, '接触火焰可能会产生膨胀或爆炸性分解。', '无资料', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4415, 4550, '可导致燃烧或爆炸。与硫磺、酸性腐蚀液体接触时，能发生燃烧或爆炸。遇潮气、酸类会 分解并放出氧气而助燃。急剧加热时可发生爆炸。具有较强的腐蚀性。', '氧化钾。', '采用干粉、砂土灭火。严禁用水、泡沫、二氧化碳扑救。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4416, 4551, '与还原剂能发生强烈反应。', '氧化锂。', '干粉。禁止用水、泡沫、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4417, 4552, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。遇明火、高热有燃烧爆炸危险。与还原剂、酸类、金属粉末等反应剧烈。', '一氧化碳、二氧化碳、其他有毒烟雾', '合适的灭火介质：使用大量水、泡沫、干粉灭火剂。不合适的灭火介质：避免使用直流水冲击，防止过氧化物飞溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4418, 4553, '撞击可引起燃烧或爆炸。', '氧化镁。', '干粉、砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4419, 4554, '可导致燃烧或爆炸。与硫磺、酸性腐蚀液体接触时，能发生燃烧或爆炸。遇潮气、酸类会 分解并放出氧气而助燃。急剧加热时可发生爆炸。具有较强的腐蚀性。', '氧气、氧化钠。', '采用干粉、砂土灭火。严禁用水、泡沫、二氧化碳扑救。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4420, 4555, '能引起燃烧或爆炸。', '一氧化碳、二氧化碳。', '雾状水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4421, 4556, '热或受污染会发生爆炸，与有机物接触会发生剧烈反应。', '使用干粉、泡沫、二氧化碳灭火。大火时，考虑撤离至少250m；罐车或卡车四周至少隔离', '800m。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4422, 4557, '接触火焰可能会产生膨胀或爆炸性分解。', '无资料', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:17', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4423, 4558, '无资料', '氧气、水。 消防人员必须穿全身防火防毒服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水', '保持火场容器冷却，直至灭火结束。处在火场中的容器若已变色或从安全泄压装置中产生 声音，必须马上撤离。灭火剂：水、雾状水、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4424, 4559, '接触火焰可能会产生膨胀或爆炸性分解。', '无资料', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4425, 4560, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '灭火方法： 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4426, 4561, '过氧化物，受热、光照、猛烈撞击或遇明火、硫酸，均有引起燃烧爆炸的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4427, 4562, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '灭火方法： 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:20', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4428, 4563, '接触火焰可能会产生膨胀或爆炸性分解。', '无资料', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:20', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4429, 4564, '水溶液为碱性腐蚀液体。', '氧化锶、氧气。', '采用干粉、砂土灭火。严禁用水、泡沫、二氧化碳扑救。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4430, 4565, '强并让火焰自身维持。灭火行动对已发生的火灾可能无效。加热时，容器可能爆炸。受热或 接触火焰可能会产生膨胀或爆炸性分解。', '灭火方法： 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4431, 4566, '级醇和水起化学反应而分解。急剧加热时可发生爆炸。水溶液为碱性腐蚀液体。', '氧化锌。', '采用干粉、砂土灭火。严禁用水、泡沫、二氧化碳扑救。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4432, 4567, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '灭火方法： 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4433, 4568, '遇水或水蒸气反应并放热。', '一氧化碳、二氧化碳。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:23', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4434, 4569, '接触火焰可能会产生膨胀或爆炸性分解。', '无资料', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:23', '', NULL);
