INSERT INTO `msds_fire_fighting` VALUES (4441, 4576, '险。', '一氧化碳、二氧化碳。', '抗溶性泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4442, 4577, '可燃物等接触会发生剧烈反应，有燃烧爆炸的危险。有强腐蚀性。', '一氧化碳、二氧化碳。 消防人员须在有防爆掩蔽处操作。灭火剂：雾状水、二氧化碳、砂土。遇大火切勿轻易接', '近。在物料附近失火，须用水保持容器冷却。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4443, 4578, '接触火焰可能会产生膨胀或爆炸性分解。', '无资料', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4444, 4579, '爆炸性分解。受热分解或爆炸性分解。', '一氧化碳、二氧化碳等有毒气体。合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4445, 4580, '若遇高热，容器内压增大，有开裂和爆炸的危险。', '无资料', '本品不燃。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4446, 4581, '受热分解产生有毒的汞蒸气。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '汞蒸气、一氧化碳、二氧化碳。', '干粉、二氧化碳或耐醇泡沫。禁止使用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4447, 4582, '氯酸盐、硝酸盐、高氯酸盐或高锰酸盐等组成爆炸性能十分敏感的化合物。燃烧时放出有 毒的刺激性烟雾。', '氧化磷、磷烷。 小火可用干燥砂土闷熄。大火用水灭火。待火熄灭后，须用湿沙土覆盖，以防复燃。清理', '时须注意防范，以免灼伤。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4448, 4583, '的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4449, 4584, '易燃液体，遇明火、高热可燃。', '一氧化碳、二氧化碳。', '尽可能将容器从火场移至空旷处。灭火剂：二氧化碳、泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4450, 4585, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4451, 4586, '易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂可发生反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳', '抗溶性泡沫、干粉、二氧化碳、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4452, 4587, '易燃气体，与空气混合能形成爆炸性混合物，遇热源和明火有燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳', '切断气源。若不能切断气源，则不允许熄灭泄漏处的火焰。喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4453, 4588, '易燃气体，与空气混合能形成爆炸性混合物。遇明火、高热极易燃烧爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。加热时，容器可能爆炸。暴露于火中的容器可能会通过压力安全阀泄漏出内容物。', '一氧化碳、二氧化碳。', '合适的灭火介质：干粉、二氧化碳。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4454, 4589, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4455, 4590, '发生强烈反应,引起燃烧或爆炸。在火场中，受热的容器有爆炸危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '喷水冷却容器，可能的话将容器从火场移至空旷处。处在火场中的容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：泡沫、干粉、二氧化碳、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4456, 4591, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。可发生聚合反应，放出大量热量而引起容器破裂和爆炸事故。', '一氧化碳、二氧化碳。', '喷水冷却容器，可能的话将容器从火场移至空旷处。处在火场中的容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：泡沫、干粉、二氧化碳、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4457, 4592, '其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。遇明火、高热易引起燃烧爆炸。与氧化剂能发生强烈反应。', '一氧化碳、二氧化碳、氧化氮', '抗溶性泡沫、干粉、二氧化碳、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4458, 4593, '遇高热、明火或氧化剂，有引起燃烧的危险。受高热分解放出有毒的气体。有腐蚀性。', '一氧化碳、二氧化碳、氮氧化物。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷 处。灭火剂：泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4459, 4594, '易燃，遇高热、明火有引起燃烧的危险。', '一氧化碳、二氧化碳、硫化氢。', '泡沫、二氧化碳、干粉、砂土。喷水冷却容器，可能的话将容器从火场移至空旷处。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4460, 4595, '容器可能爆炸。暴露于火中的容器可能会通过压力安全阀泄漏出内容物。受热或接触火焰 可能会产生膨胀或爆炸性分解。', '燃烧可能产生一氧化碳、二氧化碳等有害气体', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4461, 4596, '易燃，遇高热、明火有引起燃烧的危险。与氧化剂接触猛烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4462, 4597, '易燃液体，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与强氧化剂发生强烈反应，甚至引起燃烧。在火场中，受热的容器有爆炸危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳', '抗溶性泡沫、干粉、二氧化碳、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4463, 4598, '强烈反应,引起燃烧或爆炸。长期储存,可生成具有潜在爆炸危险性的过氧化物。其蒸气比 空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '泡沫、干粉、二氧化碳、砂土。喷水冷却容器，可能的话将容器从火场移至空旷处。处在火场中的容器若已变色或从安全泄压装置中产生声音，必须马上撤离。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4464, 4599, '蚀性气体。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氯化氢、氧化硅。', '二氧化碳、干粉、抗溶性泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4465, 4600, '受热，接触明火、高热或受到摩擦震动、撞击时可发生爆炸。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水。禁止用砂土压盖。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4466, 4601, '接触火焰可能会产生膨胀或爆炸性分解。受热，接触明火、高热或受到摩擦震动、撞击时可发生爆炸。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水。禁止用砂土压盖。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:37', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4467, 4602, '遇明火、高热易燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氧化钴。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4468, 4603, '遇明火、高热易燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氧化锌。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4469, 4604, '容器可能爆炸。暴露于火中的容器可能会通过压力安全阀泄漏出内容物。受热或接触火焰可能会产生膨胀或爆炸性分解。', '燃烧时产生氮氧化物、一氧化碳、二氧化碳等有毒烟雾。', '干粉、二氧化碳、耐醇泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4470, 4605, '爆炸危险。', '一氧化碳、二氧化碳。', '喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：抗溶性泡沫、干粉、二氧化碳、1211灭火剂、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:39', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4471, 4606, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:39', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4472, 4607, '发生强烈反应，甚至引起燃烧。在火场中，受热的容器有爆炸危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:39', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4473, 4608, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:39', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4474, 4609, '易燃液体，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触猛烈反应。在火场中，受热的容器有爆炸危险。', '一氧化碳、二氧化碳。', '尽可能将容器从火场移至空旷处。灭火剂：泡沫、二氧化碳、干粉、砂土。用水灭火无效，但须用水保持火场容器冷却。用雾状水保护消防人员，用砂土堵逸出液体。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:39', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4475, 4610, '易燃，受高热分解放出大量热量而引起容器破裂和爆炸事故。', '一氧化碳、二氧化碳。', '泡沫、干粉、二氧化碳、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4476, 4611, '易燃，遇明火、高热能燃烧。受高热分解放出有毒的气体。粉体与空气可形成爆炸性混合物，当达到一定浓度时，遇火星会发生爆炸。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4477, 4612, '无水氯化物及铁和铝的氧化物可大量放热，并可能引起爆炸。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '切断气源。若不能切断气源，则不允许熄灭泄漏处的火焰。喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、抗溶性泡沫、干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4478, 4613, '会产生膨胀或爆炸性分解。', '合适的灭火介质: 干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质: 避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4479, 4614, '遇明火、高热可燃。', '一氧化碳、二氧化碳', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的容器若已变色或从安全泄压装置中产生声音，必须马上撤离。用水喷射逸出液体，使其稀释成不燃性混合物，并用雾状水保护消防人员。灭火剂：水、雾状水、抗溶性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4480, 4615, '遇明火能燃烧。遇高热分解释出剧毒的气体。与氧化剂可发生反应。', '一氧化碳、二氧化碳、氧化氮。', '采用雾状水、泡沫、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:43', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4481, 4616, '易燃，遇明火、高热可燃。受热分解放出有毒气体。蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。', '一氧化碳、二氧化碳', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:43', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4482, 4617, '遇明火、高热可燃。与氧化剂可发生反应。遇潮时对大多数金属有腐蚀性。遇水或水蒸气 反应发热放出有毒的腐蚀性气体。受高热分解，放出高毒的烟气。', '一氧化碳、二氧化碳、氯化氢、光气。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷 处。灭火剂：二氧化碳、干粉、砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:43', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4483, 4618, '遇水反应，放出有毒的、有腐蚀性的氯和氯化氢气体。遇明火、高热可燃。受高热分解产生有毒的腐蚀性烟气。遇潮时对大多数金属有腐蚀性。', '一氧化碳、二氧化碳、氯化氢、氧化硅、氯化物', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。禁止用水。灭火剂：泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:43', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4484, 4619, '遇明火能燃烧。', '一氧化碳、二氧化碳、氮氧化物。', '喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：泡沫、干粉、二氧化碳、砂 土。禁止使用酸碱灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4485, 4620, '易燃，遇明火、高热可燃。接触酸或酸气能产生有毒气体。受高热分解放出有毒的气体。有腐蚀性。其蒸气与空气形成爆炸性混合物，遇明火、高热极易燃烧爆炸。', '一氧化碳、二氧化碳、氧化硫、硫化氢', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：抗溶性泡沫、二氧化碳、干粉、砂土。用水冷却火场容器。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4486, 4621, '与空气可形成爆炸性混合物，当达到一定的浓度时，遇火星会发生爆炸。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4487, 4622, '其蒸气与空气形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。 其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压 增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4488, 4623, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4489, 4624, '遇明火、高热易燃。与强氧化剂可发生反应。有腐蚀性。', '一氧化碳、二氧化碳、光气。', '砂土、二氧化碳、泡沫、干粉。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:46', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4490, 4625, '接触火焰可能会产生膨胀或爆炸性分解。遇明火、高热、撞击、摩擦极易发生爆炸。受热分解产生有毒的氮氧化物气体。', '一氧化碳、二氧化碳、氮氧化物等有毒气体', '使用适合火灾类型的合适的灭火剂。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。禁止用直流水灭火，以免引起爆炸。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4491, 4626, '会产生膨胀或爆炸性分解。', '合适的灭火介质：金属粉尘引起的火灾需要用沙子、惰性干粉灭火剂灭火。不合适的灭', '火介质：禁止用水、二氧化碳(CO2)或泡沫灭火剂灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4492, 4627, '易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触发生剧烈反应。流速过快，容易产生和积聚静电。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '抗溶性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:48', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4493, 4628, '易燃，遇水、潮湿空气、酸类、氧化剂、高热及明火能引起燃烧。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触猛烈反应。会产生膨胀或爆炸性分解。', '燃烧产物包括一氧化碳、二氧化碳、氧化钾。', '使用干粉、二氧化碳、砂土灭火。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4494, 4629, '易燃，遇水、潮湿空气、酸类、氧化剂、高热及明火能引起燃烧。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触猛烈反应。', '燃烧产物包括一氧化碳、二氧化碳、氧化钠。', '使用干粉、二氧化碳、砂土灭火。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4495, 4630, '易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触发生剧烈反应。流速过快，容易产生和积聚静电。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。暴露于火中的容器可能会通过压力安全阀泄漏出内容物。受热或接触火焰可能会产生膨胀或爆炸性分解。', '燃烧产物包括一氧化碳、二氧化碳。', '使用抗溶性泡沫、干粉、二氧化碳、砂土灭火。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4496, 4631, '若遇高热，可发生聚合反应，放出大量热量而引起容器破裂和爆炸事故。遇明火、高热可燃。', '一氧化碳、二氧化碳。', '雾状水、抗溶性泡沫、干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:52', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4497, 4632, '蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。在紫外线的作用下易发生聚合，粘度逐渐增加，严重时整个容器的单体可全部发生不规则爆发性聚合。', '一氧化碳、二氧化碳。', '抗溶性泡沫、二氧化碳、干粉、砂土。用水灭火无效，但可用水保持火场中容器冷却。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:52', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4498, 4633, '接触火焰可能会产生膨胀或爆炸性分解。通过打击、摩擦、火灾或其他着火源有极大爆炸危险。', '一氧化碳、二氧化碳、氮氧化物。', '使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4499, 4634, '易燃，遇明火、高热有引起燃烧爆炸的危险。受热分解产生有毒气体。若遇高热，可能发生聚合反应，出现大量放热现象，引起容器破裂和爆炸事故。遇氧化剂会引起着火和爆炸。暴露于空气中能形成危险的过氧化物。', '一氧化碳、二氧化碳。', '消防人员必须穿全身防火防毒服，在上风向灭火。遇大火，消防人员须在有防护掩蔽处操作。灭火剂：泡沫、干粉、二氧化碳、砂土。用水灭火无效，但可用水保持火场中容器冷却。在安全防爆距离以外，使用雾状水冷却暴露的容器。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4500, 4635, '紫外线的作用下易发生聚合，粘度逐渐增加，严重时整个容器的单体可全部发生不规则爆发性聚合。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '抗溶性泡沫、二氧化碳、干粉、砂土。用水灭火无效，但可用水保持火场中容器冷却。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4501, 4636, '可全部发生不规则爆发性聚合。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '泡沫、干粉、二氧化碳、砂土。用水灭火无效，但可用水保持火场中容器冷却。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4502, 4637, '易燃，遇明火、高热有引起燃烧爆炸的危险。受热分解产生有毒气体。若遇高热，可能发生聚合反应，出现大量放热现象，引起容器破裂和爆炸事故。', '一氧化碳、二氧化碳。', '消防人员必须穿全身防火防毒服，在上风向灭火。遇大火，消防人员须在有防护掩蔽处操作。灭火剂：泡沫、干粉、二氧化碳、砂土。用水灭火无效，但可用水保持火场中容器冷却。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4503, 4638, '高热，可能发生聚合反应，出现大量放热现象，引起容器破裂和爆炸事故。遇明火、高热可燃。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:54', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4504, 4639, '遇明火、高热可燃。受热分解产生有毒气体。', '一氧化碳、二氧化碳、氮氧化物等有毒气体。', '干粉、二氧化碳或耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4505, 4640, '遇水或潮湿空气会剧烈反应并放出易燃气体和腐蚀性烟雾。与氧化剂接触猛烈反应。放出的热量可导致其自燃，并放出有毒和腐蚀性的烟雾。', '一氧化碳、二氧化碳、氯化氢、氧化硅。', '消防人员必须穿全身防火防毒服，在上风向灭火。灭火剂：二氧化碳、干粉、砂土。禁止用水和泡沫灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4506, 4641, '受高热、明火会产生剧毒的汞蒸气。遇明火、高热可燃。', '一氧化碳、二氧化碳、氧化汞。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4507, 4642, '易燃液体和蒸气。蒸气可能会移动到着火源并回闪。液体和蒸气易燃。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳。', '干粉、二氧化碳或耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4508, 4643, '易燃液体和蒸气。蒸气可能会移动到着火源并回闪。液体和蒸气易燃。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳。', '干粉、二氧化碳或耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4509, 4644, '因产生静电火花放电引起燃烧爆炸。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4510, 4645, '蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，可能发生聚合反应，出现大量放热现象，引起容器破裂和爆炸事故。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4511, 4646, '因产生静电火花放电引起燃烧爆炸。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4512, 4647, '易燃，其蒸气与空气可形成爆炸性混合物。遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。遇水或水蒸气反应放热并产生有毒的腐蚀性气体。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氯化氢、硅氧化物。', '干粉、二氧化碳、砂土。禁用水柱和泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:58', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4513, 4648, '遇明火、高热易燃。受热分解产生有毒的腐蚀性烟气。具有腐蚀性。', '一氧化碳、氧化硅、氯化氢、光气。', '喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：二氧化碳、干粉、干砂。禁止用水和泡沫灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:40:59', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4514, 4649, '遇明火、高热易燃。', '一氧化碳、二氧化碳、氧化硅。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4515, 4650, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。', '一氧化碳、二氧化碳。', '喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4516, 4651, '蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。与氧化剂接触猛烈反应。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '抗溶性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4517, 4652, '蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳。', '干粉、二氧化碳、耐醇泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4518, 4653, '遇水或潮湿空气会分解放热并产生易燃的乙醚蒸气，有燃烧爆炸的危险。遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、溴化氢、氧化镁。', '二氧化碳、干粉、砂土。禁止用水、泡沫、酸碱灭火器。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:01', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4519, 4654, '与空气混合能形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '切断气源。若不能立即切断气源，则不允许熄灭正在燃烧的气体。喷水冷却容器，可能的话将容器从火场移至空旷处。雾状水、泡沫、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4520, 4655, '遇明火、高热可燃。受热分解，放出有毒烟气。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4521, 4656, '蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4522, 4657, '蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，可能发生聚合反应，出现大量放热现象，引起容器破裂和爆炸事故。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4523, 4658, '蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，可能发生聚合反应，出现大量放热现象，引起容器破裂和爆炸事故。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4524, 4659, '其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。与氧化剂能发生强烈反应。接触空气或在光照条件下可生成具有潜在爆炸危险性的过氧化物。', '一氧化碳、二氧化碳。', '抗溶性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4525, 4660, '易燃液体，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂能发生强烈反应。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4526, 4661, '易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触发生剧烈反应。流速过快，容易产生和积聚静电。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '抗溶性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4527, 4662, '易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触发生剧烈反应。流速过快，容易产生和积聚静电。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '抗溶性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4528, 4663, '其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:07', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4529, 4664, '其蒸气与空气形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。若遇高热，可能发生聚合反应，出现大量放热现象，引起容器破裂和爆炸事故。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:07', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4530, 4665, '热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '抗溶性泡沫、二氧化碳、雾状水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:07', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4531, 4666, '猛烈反应。在火场中，受热的容器有爆炸危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '抗溶性泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:08', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4532, 4667, '其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。受热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4533, 4668, '易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触发生剧烈反应。流速过快，容易产生和积聚静电。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '使用抗溶性泡沫、干粉、二氧化碳、砂土灭火。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4534, 4669, '易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触发生剧烈反应。流速过快，容易产生和积聚静电。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '抗溶性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4535, 4670, '易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触发生剧烈反应。流速过快，容易产生和积聚静电。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '燃烧产物包括一氧化碳、二氧化碳。', '使用抗溶性泡沫、干粉、二氧化碳、砂土灭火。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4536, 4671, '易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触发生剧烈反应。流速过快，容易产生和积聚静电。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '燃烧产物包括一氧化碳、二氧化碳。', '使用抗溶性泡沫、干粉、二氧化碳、砂土灭火。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4537, 4672, '爆炸危险性的过氧化物。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '切断气源。若不能切断气源，则不允许熄灭泄漏处的火焰。喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、抗溶性泡沫、干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4538, 4673, '起燃烧或爆炸。暴露在空气或氧气中能自行燃烧并爆炸使熔融物飞溅。遇水、二氧化碳都 能猛烈反应。与卤素、磷、许多氧化物、氧化剂和酸类剧烈反应。燃烧时发出紫色火焰。', '氧化钾。 不可用水、卤代烃（如1211灭火剂），碳酸氢钠、碳酸氢钾作为灭火剂。即使石墨干粉对', '钾亦不适用。而应使用干燥氯化钠粉末、碳酸钠干粉、碳酸钙干粉、干砂等灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:12', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4539, 4674, '能燃烧。使用时可能产生易燃或易爆的蒸气-空气混合物。加热时，容器可能爆炸。受热 或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉，干砂或石灰。 不合适的灭火介质:水、二氧化碳和泡沫。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4540, 4675, '能燃烧。使用时可能产生易燃或易爆的蒸气-空气混合物。加热时，容器可能爆炸。受热 或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉，干砂或石灰。 不合适的灭火介质:水、二氧化碳和泡沫。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4541, 4676, '明火、高热可燃。与强氧化剂可发生反应。有腐蚀性。受高热分解，放出高毒的烟气。', '一氧化碳、二氧化碳、氯化氢、光气。', '二氧化碳、干粉。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4542, 4677, '遇明火、高热可燃。受高热分解放出有毒的气体。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳。', '采用雾状水、抗溶性泡沫、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4543, 4678, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳。', '雾状水，泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4544, 4679, '遇明火、高热可燃。与强氧化剂可发生反应。遇水反应发热放出有毒的腐蚀性气体。', '一氧化碳、二氧化碳、氯化氢。', '泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:15', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4545, 4680, '遇明火、高热可燃。受高热分解，放出腐蚀性、刺激性的烟雾。', '一氧化碳、二氧化碳、氯化氢。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：雾状水、泡沫、干粉、二 氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:15', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4546, 4681, '遇明火、高热可燃。加热 200℃以上发生急剧分解。放出有毒的烟气。遇硫酸+SO3，加热 至150℃以上可发生爆炸。', '一氧化碳、二氧化碳、氮氧化物、氧化硫。', '二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:15', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4547, 4682, '遇明火、高热、氧化剂能燃烧，并散发出有毒气体。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:15', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4548, 4683, '的危险。', '一氧化碳、二氧化碳。', '抗溶性泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4549, 4684, '受高热分解，放出有毒的烟气。不燃。', '氧化磷、氧化钠、一氧化碳、二氧化碳。', '不燃。火场周围可用的灭火介质：水、泡沫、干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4550, 4685, '受热分解产生有毒气体。遇明火、高热有燃烧爆炸的危险。', '汞蒸气、硫氧化物、一氧化碳、二氧化碳等。', '灭火剂：干粉、二氧化碳、泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4551, 4686, '受热分解产生有毒气体。遇明火、高热有燃烧爆炸的危险。', '砷氧化物、一氧化碳、二氧化碳等。', '灭火剂：干粉、二氧化碳、泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:17', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4552, 4687, '可燃，受热发出有毒气体，有腐蚀性。接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、硫化物等。', '灭火剂：干粉、二氧化碳、泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4553, 4688, '遇明火、高热可燃。与强氧化剂可发生反应。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、氧化硫、氯化氢。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4554, 4689, '都可能引起火灾和爆炸。加热时，容器可能爆炸。暴露于火中的容器可能会通过压力安全 阀泄漏出内容物。受热或接触火焰可能会产生膨胀或爆炸性分解。', '无资料', '采用干粉、砂土灭火。严禁用水、泡沫、二氧化碳扑救。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4555, 4690, '触，有引起燃烧爆炸的危险。与氟、氯等能发生剧烈的化学反应。', '无资料', '干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4556, 4691, '被扑灭后可能复燃。接触水可能发生强烈或爆炸性反应。物质接触空气，湿气或水可能燃 烧。使用时可能产生易燃或易爆的蒸气-空气混合物。加热时，容器可能爆炸。受热或接 触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质：金属粉尘引起的火灾需要用沙子、惰性干粉灭火剂灭火。不合适的灭', '火介质：禁止用水、二氧化碳(CO2)或泡沫灭火剂灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4557, 4692, '合物。遇水或酸能发生化学反应，放出易燃气体。与氟、氯等能发生剧烈的化学反应。', '氧化锰。', '干粉、砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4558, 4693, '化学反应活性很高，暴露在空气中可发生氧化反应。与氟、氯等能发生剧烈的化学反应。 也可与氮气发生反应。如浸入煤油中，则参照煤油的危险性，遇高热明火有燃烧的危险。', '无资料', '二氧化碳、干粉、1211灭火剂、砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4559, 4694, '氧气反应则生成超氧化物，如混有有机物等，发生爆炸性反应。遇水或潮气猛烈反应放 出氢气，大量放热，引起燃烧或爆炸。与卤素、硫、磷等发生剧烈的化学反应,引起燃烧。', '无资料 不可用水、卤代烃（如1211灭火剂），碳酸氢钠、碳酸氢钾作为灭火剂。即使石墨干粉及', '干砂亦不适用。须用干燥氯化钠粉末、碳酸钠干粉、碳酸钙干粉灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:20', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4560, 4695, '有机物等，发生爆炸性反应。与水和酸强烈反应,发热冒烟,甚至发生燃烧爆炸。与卤素及 其它氧化剂剧烈反应。', '无资料 不可用水、卤代烃（如1211灭火剂），碳酸氢钠、碳酸氢钾作为灭火剂。即使石墨干粉及', '干砂亦不适用。有效的灭火剂为：干燥氯化钠粉末、碳酸钠干粉、碳酸钙干粉灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4561, 4696, '于火中的容器可能会通过压力安全阀泄漏出内容物。受热 或接触火焰可能会产生膨胀或爆 炸性分解。', '无资料', '合适的灭火介质: 干粉，干砂或石灰。 不合适的灭火介质: 水、二氧化碳和泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4562, 4697, '发生反应放出氢气及热量,能引起燃烧。与卤素、硫、磷等发生剧烈的化学反应,引起燃烧。 燃烧时发出深红色火焰。', '无资料 不可用水、泡沫、二氧化碳、卤代烃（如1211灭火剂）等灭火。须用干燥石墨粉或其它干', '粉灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4563, 4698, '在空气中能自燃。金属钛不仅能在空气中燃烧,也能在二氧化碳或氮气中燃烧。高温时易 与卤素、氧、硫、氮化合。', '氧化钛。 采用干粉、干砂灭火。严禁用水、泡沫、二氧化碳扑救。高热或剧烈燃烧时，用水扑救可', '能会引起爆炸。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4564, 4699, '遇明火、高热可燃。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳。', '消防人员必须穿全身防火防毒服，在上风向灭火。灭火剂：干粉、二氧化碳、砂土。用水可引 起沸溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:22', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4565, 4700, '受热或接触火焰可能会产生膨胀或爆炸性分解。遇明火、高热有燃烧爆炸的危险。', '氮氧化物、氨', '干粉、二氧化碳、耐醇泡沫、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:22', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4566, 4701, '燃烧时可能会释放毒性烟雾。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀 或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:22', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4567, 4702, '性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:23', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4568, 4703, '加热时，容器可能爆炸。暴露于火中的容器可能会通过压力安全阀泄漏出内容物。受热或 接触火焰可能会产生膨胀或爆炸性分解。', '无资料 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:24', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4569, 4704, '火焰都可能引起火灾和爆炸。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀 或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳、水喷雾或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:24', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4570, 4705, '能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:24', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4571, 4706, '遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。燃烧时产生大量烟雾。', '一氧化碳、二氧化碳。', '尽可能将容器从火场移至空旷处。灭火剂：雾状水、二氧化碳、干粉、泡沫、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4572, 4707, '爆炸的危险。', '一氧化碳、二氧化碳、氮氧化物。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4573, 4708, '易燃，遇明火有引起燃烧的危险。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳。 采用雾状水、泡沫、干粉、二氧化碳、砂土灭火。用水灭火无效，但可用水保持火场中容', '器冷却。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4574, 4709, '遇明火、高热可燃。受热分解，放出有毒烟气。', '一氧化碳、二氧化碳、氮氧化物', '泡沫、干粉、二氧化碳、砂土。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4575, 4710, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳、氧化氮。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4576, 4711, '时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '灭火方法： 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4577, 4712, '受热、接触明火、或受到摩擦、震动、撞击时可发生爆炸。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、氧化氮。 消防人员须在有防爆掩蔽处操作。用大量水灭火。遇大火须远离以防炸伤。在物料附近失火，', '须用水保持容器冷却。禁止用砂土压盖。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4578, 4713, '遇明火、高热可燃。受热分解放出有毒的氧化氮烟气。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、氧化氮。', '采用雾状水、泡沫、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4579, 4714, '遇明火、高热可燃。受热分解，放出磷、硫的氧化物等毒性气体。与强氧化剂接触可发生 化学反应。', '一氧化碳、氧化硫、氧化氮、氧化磷。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：抗溶性泡沫、干粉、 砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4580, 4715, '受热、摩擦、撞击或震动极易爆炸；与金属粉末、还原剂、有机物等接触可能发生爆炸', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4581, 4716, '场全部荫蔽。金属锂能在空气、氧气、氮气或二氧化碳中燃烧，特别是有氧化锂或氮化锂 存在下极易燃烧。锂在高温下能与混凝土或其它含湿的材料猛烈反应，反应放出的氢气与 空气能形成爆炸性混合物。与卤素、硫、磷等发生剧烈的化学反应,引起燃烧。', '氧化锂。 禁止使用水、泡沫或卤化物灭火剂。用二氧化碳与干粉也无效。最好的灭火方法是用干燥', '石墨粉和干砂闷熄火苗，隔绝空气。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4582, 4717, '火焰被扑灭后可能复燃。注意有自燃的危险。加热时，容器可能爆炸。受热或接触火焰 可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、干砂、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4583, 4718, '火焰被扑灭后可能复燃。注意有自燃的危险。加热时，容器可能爆炸。受热或接触火焰 可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、干砂、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4584, 4719, '酸类或与有机物、氧化剂接触，都可放出大量热而引起剧烈燃烧，并放出有毒和易燃的二 氧化硫。', '硫化物。', '尽可能将容器从火场移至空旷处。灭火剂：干粉、二氧化碳、砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4585, 4720, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4586, 4721, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳、成分未知的黑色烟雾。', '泡沫、二氧化碳、1211灭火剂、干粉、砂土。用水可引起沸溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4587, 4722, '遇明火、高热可燃。与氧化剂可发生反应。', '一氧化碳、二氧化碳、成分未知的黑色烟雾。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：雾状水、泡沫、干粉、二 氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4588, 4723, '加热时，容器可能爆炸。暴露于火中的容器可能会通过压力安全阀泄漏出内容物。受热或 接触火焰可能会产生膨胀或爆炸性分解。', '无资料', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4589, 4724, '或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4590, 4725, '遇明火、高热可燃。与氧化剂可发生反应。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、氧化硫。', '雾状水、泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4591, 4726, '或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4592, 4727, '遇明火、高热可燃。', '一氧化碳、二氧化碳。 尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的', '容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：雾状水、泡沫、干 粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4593, 4728, '遇明火、高热可燃。', '一氧化碳、二氧化碳。', '切勿将水流直接射至熔融物，以免引起严重的流淌火灾或引起剧烈的沸溅。灭火剂：抗溶性泡 沫、干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4594, 4729, '遇明火、高热可燃。与强氧化剂可发生反应。受高热分解产生有毒的腐蚀性气体。有腐蚀性。', '一氧化碳、二氧化碳、光气、氯化氢。', '泡沫、二氧化碳、砂土、干粉。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4595, 4730, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:32', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4596, 4731, '能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4597, 4732, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4598, 4733, '有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '二氧化碳、泡沫、干粉、1211灭火剂、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4599, 4734, '遇高热、明火或与氧化剂接触，有弓[起燃烧的危险。受高热分解，放出腐蚀性、刺激性的 烟雾。', '一氧化碳、二氧化碳、氯化氢。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4600, 4735, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳、水喷雾或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4601, 4736, '能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4602, 4737, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。受高热分解，产生有毒的氮氧化物。', '一氧化碳、二氧化碳、氧化氮。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4603, 4738, '遇明火、高热可燃。受高热分解产生有毒的腐蚀性烟气。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、氧化氮。', '采用泡沫、雾状水、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4604, 4739, '遇明火、高热、氧化剂能燃烧，并散发出有毒气体。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4605, 4740, '遇湿放出磷化氢', '灭火方法： 用干粉，苏打粉或石灰灭火剂；勿用水或泡沫灭火剂', '用干粉，苏打粉或石灰灭火剂；勿用水或泡沫灭火剂', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:36', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4606, 4741, '发生强烈反应。受高热分解，放出高毒的烟气。', '氧化磷、磷化氢、氧化钾。', '干粉、砂土。禁止使用酸碱灭火剂、水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:37', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4607, 4742, '会立即在空气中自燃。与氧化剂能发生强烈反应，引起燃烧或爆炸。', '磷烷。', '干粉、砂土。禁止用水。禁止使用酸碱灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:37', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4608, 4743, '与卤素发生剧烈反应。受高热分解，放出高毒的烟气。', '氧化磷、磷化氢、氧化镁。', '干粉、砂土。禁止使用酸碱灭火剂、水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:37', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4609, 4744, '发生强烈反应。受高热分解，放出高毒的烟气。', '磷化氢、氧化磷、氧化钠。', '干粉、砂土。禁止使用酸碱灭火剂、水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4610, 4745, '炸，与卤素接触激烈反应。与氧化剂能发生强烈反应。', '氧化磷。 消防人员必须佩戴过滤式防毒面具(全面罩)或隔离式呼吸器、穿全身防火防毒服，在上风向灭火。', '切断气源。若不能切断气源，则不允许熄灭泄漏处的火焰。喷水冷却容器，可能的话将容器从火 场移至空旷处。灭火剂：雾状水、泡沫、干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4611, 4746, '发生强烈反应。与卤素发生剧烈反应。受高热分解，放出有毒的烟气。', '氧化磷、氧化锶、磷化氢。', '干粉、砂土。禁止使用酸碱灭火剂、水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4612, 4747, '发生强烈反应。受高热分解，放出高毒的烟气。', '氧化磷、磷化氢、氧化锡。', '干粉、砂土。禁止使用酸碱灭火剂、水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4613, 4748, '发生强烈反应。遇浓硝酸和王水发生爆炸。受高热分解，放出高毒的烟气。', '氧化硒、磷化氢、氧化锌。', '干粉、砂土。禁止使用酸碱灭火剂、水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:39', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4614, 4749, '遇明火能燃烧。燃烧时放出极毒气体。', '氧化磷、氧化汞。 消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：水、干粉、泡沫、二', '氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:39', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4615, 4750, '可燃。受热分解产生剧毒的氧化磷烟气。与氧化剂能发生强烈反应。', '一氧化碳、二氧化碳、氧化磷、磷烷。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：干粉、二氧化碳、砂 土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4616, 4751, '爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4617, 4752, '会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4618, 4753, '遇明火、高热可燃。遇酸类放出易燃、有毒的硫化氢气体。受高热分解，放出有毒的烟气。', '氧化硫、硫化氢、钡化合物', '水、泡沫、砂土、二氧化碳', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4619, 4754, '高度易燃，其蒸气与空气混合，能形成爆炸性混合物。遇明火、高热极易引起燃烧爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、氧化硫、氮氧化物。', '干粉、二氧化碳、耐醇泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4620, 4755, '其蒸气与空气形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。有腐蚀性。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氯化氢、氧化硫。', '雾状水、抗溶性泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4621, 4756, '化物烟气。具有腐蚀性。', '一氧化碳、二氧化碳、硫化氢、氧化硫。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、泡沫、二氧化碳、', '砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4622, 4757, '易燃液体，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。受热分解产生有毒的氰化氢、氮氧化物、硫化物等气体。具有强刺激性和毒性。', '一氧化碳、二氧化碳、氮氧化物、氰化氢、硫化物', '二氧化碳、泡沫、干粉、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4623, 4758, '易燃液体，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。受热分解产生硫化氢、氨气等有毒气体。', '一氧化碳、二氧化碳、硫化氢、氨气、氧化硫', '干粉、二氧化碳、耐醇泡沫、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:43', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4624, 4759, '在潮湿空气中或酸雾中能发生强烈的化学反应，可能引起燃烧。具有腐蚀性。', '硫化氢、硫化物、氧化钡', '采用二氧化碳、干粉、砂土灭火', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:44', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4625, 4760, '受高热分解产生有毒的硫化物烟气。', '氧化硫、硫化氢。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:44', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4626, 4761, '受高热分解产生有毒的汞蒸气和硫化物。', '汞蒸气、硫化物、氧化硫', '干粉、二氧化碳、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:44', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4627, 4762, '无水物为自燃物品，其粉尘易在空气中自燃。遇酸分解，放出剧毒的易燃气体。其水溶液有腐蚀性和强烈的刺激性。100℃时开始蒸发，蒸气可侵蚀玻璃。', '硫化氢、二氧化硫', '采用水、雾状水、砂土灭火。禁止使用酸碱灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:44', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4628, 4763, '与过氧化氢发生剧烈反应。与硝酸钠的混合物是一种炸药。受高热分解，放出有毒的烟气。', '硫化氢、氧化硫、钼', '不燃。根据周围环境选择合适的灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:46', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4629, 4764, '无水物为自燃物品，其粉尘易在空气中自燃。遇酸分解，放出剧毒的易燃气体。粉尘与空气可形成爆炸性混合物。其水溶液有腐蚀性和强烈的刺激性。', '硫化氢、氧化硫', '采用水、雾状水、砂土灭火', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:46', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4630, 4765, '易燃气体，与空气混合能形成爆炸性混合物，遇明火、高热极易引起燃烧爆炸。与浓硝酸、发烟硫酸或其它强氧化剂剧烈反应，发生爆炸。气体比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '氧化硫', '雾状水、抗溶性泡沫、干粉、二氧化碳', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:46', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4631, 4766, '接触酸或酸气能产生有毒气体。受高热分解，放出有毒的烟气。', '硫化氢、氧化硫', '灭火剂：雾状水、泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:46', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4632, 4767, '粉尘或蒸气与空气或氧化剂混合形成爆炸性混合物。遇明火、高热有引起燃烧爆炸的危险。', '氧化硫、二氧化硫。', '遇小火用砂土闷熄。遇大火可用雾状水灭火。切勿将水流直接射至熔融物，以免引起严重的流淌火灾或引起剧烈的沸溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:46', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4633, 4768, '受热分解产生硫化氢等有毒气体。遇酸分解，放出剧毒的易燃气体。', '硫化氢、氧化硫', '不燃。根据周围环境选择合适的灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4634, 4769, '遇明火、高热可燃。暴露在空气中会发生氧化反应，甚至自燃。受热分解产生硫化氢等有毒气体。', '硫化氢、氧化硫', '雾状水、泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:48', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4635, 4770, '接触酸或酸气能产生有毒气体。受高热分解，放出高毒的烟气。', '氮氧化物、汞、氧化硫、氰化物、氧化汞。', '干粉、二氧化碳或耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:48', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4636, 4771, '遇高热、明火或氧化剂，有引起燃烧的危险。受高热分解，放出高毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、氧化硫、氰化物', '雾状水、二氧化碳、干粉、砂土。禁止使用酸碱灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4637, 4772, '受高热分解放出有毒的气体。', '硫化物、氰化氢、氧化硫', '雾状水、干粉、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4638, 4773, '受热分解产生硫化氢、氰化氢等有毒气体。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、硫化氢、氰化氢、氧化硫、氧化氮', '干粉、二氧化碳、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4639, 4774, '爆炸性分解。受热分解产生硫化氢、氰化氢等有毒气体。', '硫化氢、氰化氢、氧化汞、氧化硫、氮氧化物。', '干粉、二氧化碳或耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4640, 4775, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。受高热分解释出剧毒的氮 氧化物和氧化硫气体。', '一氧化碳、二氧化碳、氧化氮、氧化硫。', '采用雾状水、干粉、泡沫、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:50', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4641, 4776, '遇明火易燃。受高热燃烧并分解产生有毒气体。', '一氧化碳、二氧化碳、硫化物、氰化氢。', '采用泡沫、干粉、二氧化碳、砂土灭火。禁止使用酸碱灭火剂。用水灭火无效，但可用水保持火场中容器冷却。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4642, 4777, '遇水大量放热，可发生沸溅。与易燃物（如苯、糖和纤维素等）接触会发生剧烈反应，甚至引起燃烧。遇电石、高氯酸盐、雷酸盐、硝酸盐、苦味酸盐、金属粉末等猛烈反应，发生爆炸或燃烧。有强烈的腐蚀性和吸水性。', '氧化硫', '干粉、二氧化碳、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4643, 4778, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、氧化硫', '雾状水、抗溶性泡沫、二氧化碳、干粉、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4644, 4779, '遇热有火灾危险。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '氮氧化物、硫氧化物', '干粉、二氧化碳、水喷雾、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:52', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4645, 4780, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。受高热分解，放出有毒的烟气。', '氮氧化物、硫氧化物、一氧化碳、二氧化碳。', '干粉、二氧化碳或耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:52', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4646, 4781, '受热分解产生有毒的氮氧化物和硫氧化物。与氧化剂能发生强烈反应。', '氮氧化物、硫氧化物、一氧化碳、二氧化碳', '干粉、二氧化碳、泡沫、雾状水', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:52', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4647, 4782, '遇明火、高热可燃。受热分解产生有毒的氮氧化物和硫氧化物。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '氮氧化物、硫氧化物', '干粉、二氧化碳、耐醇泡沫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:52', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4648, 4783, '遇明火、高热可燃。受热分解产生有毒的氮氧化物和硫氧化物。具有爆炸性分解的危险。', '氮氧化物、硫氧化物', '干粉、二氧化碳、耐醇泡沫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4649, 4784, '受热分解产生有毒的氮氧化物和硫氧化物。与氧化剂能发生强烈反应。', '氮氧化物、硫氧化物、一氧化碳、二氧化碳', '干粉、二氧化碳、泡沫、雾状水', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4650, 4785, '遇明火、高热可燃。受热分解产生有毒的氧化硫气体。与氢氧化铵反应强烈。', '一氧化碳、二氧化碳、氧化硫', '雾状水、二氧化碳、泡沫、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:54', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4651, 4786, '遇明火、高热可燃。受热分解产生有毒的氧化硫气体。与氧化剂可发生反应。', '一氧化碳、二氧化碳、氧化硫', '采用抗溶性泡沫、干粉、二氧化碳、砂土灭火', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:54', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4652, 4787, '受高热分解产生有毒的硫化物烟气。', '硫化物', '不燃。火场周围可用的灭火介质', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:54', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4653, 4788, '受热分解产生有毒的汞蒸气和硫氧化物。', '汞蒸气、硫氧化物', '根据周围火灾情况选择合适的灭火剂。周围火灾时，使用水、干粉、二氧化碳或耐醇泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:54', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4654, 4789, '受热分解产生有毒的硫氧化物。', '硫氧化物', '根据周围火灾情况选择合适的灭火剂。周围火灾时，使用水、干粉、二氧化碳或耐醇泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:56', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4655, 4790, '遇明火、高热可燃。受热分解产生有毒的氮氧化物和硫氧化物气体。', '氮氧化物、硫氧化物、一氧化碳、二氧化碳', '干粉、二氧化碳、耐醇泡沫、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:56', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4656, 4791, '遇明火、高热可燃。受热分解产生有毒的氮氧化物和硫氧化物气体。', '氮氧化物、硫氧化物、一氧化碳、二氧化碳', '干粉、二氧化碳、耐醇泡沫、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:56', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4657, 4792, '受热分解产生有毒的硫氧化物。', '硫氧化物', '根据周围火灾情况选择合适的灭火剂。周围火灾时，使用水、干粉、二氧化碳或耐醇泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:56', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4658, 4793, '受高热分解，放出高毒的烟气。', '氧化硫、氧化铍', '不燃。火场周围可用的灭火介质', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4659, 4794, '受热分解产生有毒的硫氧化物和铍化合物。', '硫氧化物、铍化合物', '根据周围火灾情况选择合适的灭火剂。周围火灾时，使用水、干粉、二氧化碳或耐醇泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:58', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4660, 4795, '受高热分解产生有毒的硫化物烟气。', '氧化铅、氧化硫', '不燃。火场周围可用的灭火介质', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:58', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4661, 4796, '受热分解产生有毒的硫氧化物和氮氧化物。', '硫氧化物、氮氧化物', '根据周围火灾情况选择合适的灭火剂。周围火灾时，使用水、干粉、二氧化碳或耐醇泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:58', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4662, 4797, '有腐蚀性。受高热分解，放出有毒的烟气。', '氧化硫、氧化钾', '干粉、二氧化碳或耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4663, 4798, '有腐蚀性。受高热分解，放出有毒的烟气。', '氧化硫、氧化钠', '干粉、二氧化碳、水喷雾或耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4664, 4799, '遇明火、高热可燃。加热分解产生毒性气体。', '一氧化碳、二氧化碳、硫化物、氧化锡', '水、泡沫、二氧化碳、干粉、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4665, 4800, '受热分解产生有毒的氧化硫和汞蒸气。与氧化剂可发生反应。', '一氧化碳、二氧化碳、氧化硫、汞蒸气', '干粉、二氧化碳或耐醇泡沫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:01', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4666, 4801, '受热分解产生有毒的硫氧化物。与氧化剂接触可能发生剧烈反应。', '硫氧化物、钒氧化物', '根据周围火灾情况选择合适的灭火剂。周围火灾时，使用水、干粉、二氧化碳或耐醇泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4667, 4802, '受高热分解，放出有毒的氟化物和氯化物气体。', '氯化氢、氟化氢。', '水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4668, 4803, '若遇高热，容器内压增大，有开裂和爆炸的危险。遇水反应生成水合六氟丙酮，并放出热量。遇醇类、胺类等活性氢化合物发生剧烈反应。遇强氧化剂有发生火灾爆炸的危险。', '分解产生氟化氢、一氧化碳、二氧化碳等有毒气体。氟化氢具有强腐蚀性和毒性。', '本品不燃，但周围火灾可使用干粉、二氧化碳、泡沫灭火器。切断气源。喷水冷却容器，可能的话将容器从火场移至空旷处。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4669, 4804, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '氟化氢、一氧化碳、二氧化碳等有毒气体。', '干粉、二氧化碳、水喷雾或耐醇泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4670, 4805, '若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氟化氢。', '本品不燃。切断气源。喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4671, 4806, '与酸反应，放出有毒的腐蚀性烟气。受高热分解，放出有毒的烟气。', '氟化氢、氧化镁、氧化硅', '本品不燃。根据周围环境选择合适的灭火剂。灭火剂：干粉、二氧化碳、砂土。禁止用水、泡沫、酸碱灭火器。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4672, 4807, '受高热或接触酸或酸雾放出剧毒的烟雾。', '氟化氢。', '砂土、二氧化碳、干粉、水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4673, 4808, '与酸反应，放出有毒的腐蚀性烟气。受高热分解，放出有毒的烟气。', '氧化锌、氟化氢、氧化硅。', '干粉、二氧化碳或耐醇泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4674, 4809, '放出有毒的腐蚀性气体。受热分解，放出高毒的烟气。', '氟化氢、氧化磷、磷化氢。', '二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4675, 4810, '热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氟化氢。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4676, 4811, '有腐蚀性。在水中分解放出剧毒的腐蚀性气体。', '氟化氢。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4677, 4812, '若遇高热，容器内压增大，有开裂和爆炸的危险。', '氧化硫、氟化氢。', '本品不燃。切断气源。喷水冷却容器，可能的话将容器从火场移至空旷处。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4678, 4813, '不燃的剧毒气体。若遇高热，容器内压增大，有开裂和爆炸的危险。', '氟化氢、硒化合物等有毒气体。', '本品不燃，根据周围着火原因选择适当灭火剂。切断气源。喷水冷却容器，可能的话将容器从火场移至空旷处。雾状水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:07', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4679, 4814, '六氟化铀本身不燃，但受高热、明火会产生剧毒的氟化氢（HF）蒸气、铀酰化合物气溶胶和放射性物质。火灾时产生的烟雾具有剧毒、腐蚀性和放射性，对消防人员和周围环境造成严重危害。具有强腐蚀性，遇水分解产生剧毒的氟化氢气体。', '氟化氢（HF）、铀酰化合物（UO2F2）、放射性气溶胶、铀氧化物。', '六氟化铀本身不燃，不需要常规灭火剂。如容器受热可能发生爆炸，应使用水雾冷却容器。禁止使用直流水直接冲击泄漏的六氟化铀，因为水会与六氟化铀反应产生剧毒的氟化氢气体。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:07', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4680, 4815, '本品不燃。若遇高热，容器内压增大，有开裂和爆炸的危险。受热分解可能产生有毒气体。', '氟化氢、一氧化碳、二氧化碳等有毒气体。', '本品不燃，根据周围着火原因选择适当灭火剂。切断气源。喷水冷却容器，可能的话将容器从火场移至空旷处。雾状水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:07', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4681, 4816, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:07', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4682, 4817, '遇高热、明火及强氧化剂易引起燃烧。', '一氧化碳、二氧化碳、氧化硅。', '二氧化碳、干粉、干砂。禁止用水和泡沫灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:07', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4683, 4818, '遇明火、高热、氧化剂极易燃烧。其蒸气比空气重，能在较低处扩散到相当远的地方，遇 明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。受热分解放出易燃气 体能与空气形成爆炸性混合物。', '一氧化碳、二氧化碳、氧化硅。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4684, 4819, '遇明火、高热可燃。与氧化剂能发生强烈反应。受高热分解，放出剧毒的光气和有腐蚀性的氯化氢烟气。', '一氧化碳、二氧化碳、氯化氢、光气。', '抗溶性泡沫、二氧化碳、干粉、雾状水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4685, 4820, '受高热分解产生有毒的腐蚀性烟气。', '一氧化碳、二氧化碳、氯化氢。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：雾状水、泡沫、干粉、二 氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4686, 4821, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氯化氢。', '雾状水、抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4687, 4822, '不易燃烧。受高热分解，放出腐蚀性、刺激性的烟雾。', '氯化氢、一氧化碳、二氧化碳。', '砂土、泡沫、雾状水、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4688, 4823, '遇明火、高热可燃。燃烧分解时, 放出有毒的刺激性氯化物烟气。', '一氧化碳、二氧化碳、氯化氢。', '雾状水、泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4689, 4824, '高热时能分解出剧毒的光气。与氧化剂能发生强烈反应。', '氯化氢、光气。', '本品不燃。根据周围环境选择合适的灭火剂。灭火剂：雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4690, 4825, '遇明火、高热可燃。受热分解产生有毒气体。', '一氧化碳、二氧化碳、氮氧化物等有毒气体。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4691, 4826, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '氮氧化物、一氧化碳、二氧化碳', '使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4692, 4827, '受热、接触明火、或受到摩擦、震动、撞击时可发生爆炸。', '一氧化碳、二氧化碳、氧化氮。 消防人员须在有防爆掩蔽处操作。用大量水灭火。遇大火须远离以防炸伤。在物料附近失火，', '须用水保持容器冷却。禁止用砂土压盖。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:12', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4693, 4828, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、氮氧化物', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4694, 4829, '干燥状态下，受摩擦、震动可引起燃烧爆炸。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氧化硫、氮氧化物。', '二氧化碳、水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4695, 4830, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '受热分解产生有毒的溴化氢、一氧化碳和二氧化碳等气体。', '合适的灭火介质：干粉、二氧化碳、水喷雾或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4696, 4831, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '溴化氢、溴化物、一氧化碳、二氧化碳', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4697, 4832, '危险特性：本身不易燃烧，但受高热分解会产生有毒的溴化氢气体和溴化物。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '有害燃烧产物：一氧化碳、二氧化碳、溴化氢、溴化物等有毒气体。', '灭火方法：使用水、泡沫、二氧化碳、干粉灭火剂。切勿将水流直接射入熔融物质，以免引起严重的流淌火灾或剧烈的沸溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:15', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4698, 4833, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。燃烧分解时，放出有毒的氮氧化物。', '一氧化碳、二氧化碳、氮氧化物。', '二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:15', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4699, 4834, '遇明火、高热易燃。与氧化剂能发生强烈反应。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氧化氮。', '喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：泡沫、二氧化碳、雾状水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:15', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4700, 4835, '易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂能发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳、氧化氮。', '抗溶性泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:15', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4701, 4836, '发生剧烈的化学反应。与酸类或与强碱接触也能产生氢气，引起燃烧爆炸。粉体与空气可 形成爆炸性混合物,当达到一定浓度时,遇火星会发生爆炸。', '氧化铝。', '严禁用水、泡沫、二氧化碳扑救。可用适当的干砂、石粉将火闷熄。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:15', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4702, 4837, '能会通过压力安全阀泄漏出内容物。受热或接触火焰可能会产生膨胀或爆炸性分解。', '无资料 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:17', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4703, 4838, '形成爆炸性混合物。氯气能与许多化学品如乙炔、松节油、乙醚、氨、燃料气、烃类、氢气、金属粉末等猛烈反应发生爆炸或生成爆炸性物质。它几乎对金属和非金属都有腐蚀作用。', '氯化氢', '本品不燃。消防人员必须佩戴过滤式防毒面具(全面罩)或隔离式呼吸器、穿全身防火防毒服，在上风向灭火。切断气源。喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、泡沫、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:17', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4704, 4839, '易燃，遇明火、高热有燃烧爆炸危险。与氧化剂能发生强烈反应。', '一氧化碳、二氧化碳、氯化物。', '喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4705, 4840, '金属有腐蚀性。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氯化氢、氧化硅。', '二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4706, 4841, '有腐蚀性。与三氟化硼发生剧烈反应。受高热分解，放出有毒的烟气。', '氯化氢。', '干粉、二氧化碳或耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4707, 4842, '建规火险分级：', '喷水、喷雾或使用干粉、二氧化碳、泡沫灭火剂；尽可能转移火中容器；用水冷却火中容', '器，以免爆炸', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4708, 4843, '其蒸气与空气形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反 应。受高热分解产生有毒的腐蚀性气体。其蒸气比空气重，能在较低处扩散到相当远的地 方，遇火源引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氯化氢。', '泡沫、干粉、二氧化碳、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4709, 4844, '受高热分解产生有毒的腐蚀性气体。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火 源引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氯化氢。', '泡沫、干粉、二氧化碳、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4710, 4845, '遇明火、高热易燃。受热分解能放出剧毒的光气。与氧化剂能发生强烈反应。', '一氧化碳、二氧化碳、氯化氢。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：泡沫、二氧化碳、干粉、砂', '土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:20', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4711, 4846, '受高热、明火会产生剧毒的蒸气。', '氮氧化物、氯化物。', '水、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:20', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4712, 4847, '内压增大，有开裂和爆炸的危险。', '氟化氢、氯化氢、溴化氢。', '切断气源。喷水冷却容器，可能的话将容器从火场移至空旷处。雾状水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:20', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4713, 4848, '与卤素发生剧烈反应。受高热分解，放出高毒的烟气。', '氮氧化物、氯化氢、汞。', '水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4714, 4849, '未有特殊的燃烧爆炸特性。', '氯化氢、氧化钡。', '不燃。火场周围可用的灭火介质。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4715, 4850, '一氧化碳、二氧化碳、氯化氢、汞、氧化汞。', '一氧化碳、二氧化碳、氯化氢、汞、氧化汞。', '泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4716, 4851, '遇明火、高热可燃。受高热分解产生有毒的腐蚀性烟气。与铜、铝、镁、锌及锡等接触放出热 量及氯化氢气体。', '一氧化碳、二氧化碳、氯化氢。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：雾状水、泡沫、干粉、二 氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4717, 4852, '具有强腐蚀性。在潮湿条件下能腐蚀某些金属。遇水发生剧烈反应，散发出具有刺激性和 腐蚀性的氯化氢气体。与磷发生猛烈反应。', '氯化氢、氧化硫。', '干粉、砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4718, 4853, '炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:22', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4719, 4854, '暴露在空气或二氧化碳中会自燃，遇酸类、碱、氧化剂和水接触可发生剧烈的化学反应。', '一氧化碳、二氧化碳、氯化物、氧化铝。', '干粉、砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:23', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4720, 4855, '受高热分解产生有毒的腐蚀性烟气。', '氯化氢。', '消防人员必须穿全身防火防毒服，在上风向灭火。灭火剂：水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:23', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4721, 4856, '与碱金属能发生剧烈反应。', '氯化物、氧化汞。', '本品不燃。消防人员必须穿全身防火防毒服，在上风向灭火。灭火剂：水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:23', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4722, 4857, '与钠、钾的混合物对震动敏感。受高热分解，放出腐蚀性、刺激性的烟雾。', '氯化氢、氧化钴。', '不燃。火场周围可用的灭火介质。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:23', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4723, 4858, '炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4724, 4859, '应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热， 容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氯化氢。', '砂土、泡沫、干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4725, 4860, '遇明火、高热可燃。受高热分解产生有毒的腐蚀性烟气。', '一氧化碳、二氧化碳、氯化氢、氧化汞。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4726, 4861, '爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4727, 4862, '爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '氯化氢、氧化汞。', '干粉、二氧化碳或耐醇泡沫。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4728, 4863, '本品不燃，有毒，具刺激性。受高热分解产生有毒的腐蚀性烟气。', '氯化氢、氧化镍、氮氧化物（如含氮杂质）', '消防人员必须穿全身防火防毒服，在上风向灭火。灭火剂：水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4729, 4864, '遇水反应，放出具有刺激性和腐蚀性的氯化氢气体。受高热分解，放出有毒的烟气。', '氯化氢、氧化铍。', '不燃。火场周围可用的灭火介质。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4730, 4865, '化物能产生剧毒的氰化氢气体。', '氯化氢。 本品不燃。但与其它物品接触引起火灾时，消防人员须穿戴全身防护服，关闭火场中钢瓶的阀门，', '减弱火势，并用水喷淋保护去关闭阀门的人员。喷水冷却容器，可能的话将容器从火场移至空旷 处。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4731, 4866, '释出剧毒和腐蚀性的烟雾。', '氯化氢、氰化氢、氮氧化物。 本品不燃。消防人员必须穿全身防火防毒服，在上风向灭火。切断气源。喷水冷却容器，可能的', '话将容器从火场移至空旷处。灭火剂：干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4732, 4867, '受热分解产生有毒的氯化氢气体。', '氯化氢', '干粉、二氧化碳、泡沫、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4733, 4868, '能与磷、钾、过氧化钾、过氧化钠剧烈反应。遇水分解成亚硒酸、硒和盐酸，有腐蚀性。', '氯化氢、氧化硒。', '消防人员必须穿全身防火防毒服，在上风向灭火。灭火剂：二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4734, 4869, '受高热分解产生有毒的腐蚀性气体。遇水迅速分解，放出白色烟雾。', '氯化氢、氧化锌等有毒腐蚀性气体。', '雾状水、火场周围可用的灭火介质。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4735, 4870, '都可能引起火灾和爆炸。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸 性分解。', '一氧化碳、二氧化碳、氮氧化物、氯化氢', '干粉、二氧化碳、水喷雾或耐醇泡沫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4736, 4871, '遇热、摩擦、撞击或接触火焰可能发生爆炸或分解。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。具有自反应性，可能发生放热反应。', '一氧化碳、二氧化碳、氮氧化物、氯化氢、氧化锌等有毒烟雾。', '干粉、二氧化碳、水喷雾或耐醇泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4737, 4872, '遇热、摩擦、撞击或接触火焰可能发生爆炸或分解。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。具有自反应性，可能发生放热反应。', '合适的灭火介质：干粉、二氧化碳、水喷雾或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。消防人员须佩戴自给式呼吸器，穿全身消防防毒服。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4738, 4873, '都可能引起火灾和爆炸。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '受热分解产生氮氧化物、氯化氢、氧化锌等有毒有害气体。', '合适的灭火介质：干粉、二氧化碳、水喷雾或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4739, 4874, '都可能引起火灾和爆炸。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质：干粉、二氧化碳、水喷雾或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4740, 4875, '遇明火、高热可燃。受热分解产生有毒气体。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、氮氧化物、氯化氢等有毒气体。', '合适的灭火介质：干粉、二氧化碳、水喷雾或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4741, 4876, '具有强氧化性。与易燃物、可燃物接触能引起剧烈燃烧。具有较强的腐蚀性。室温下迅速分解, 放 出剧毒的氯和溴的烟雾。吸潮或遇水会产生大量的腐蚀性烟雾。', '氯气、溴气。 消防人员必须穿全身防火防毒服，在上风向灭火。切断气源。喷水冷却容器，可能的话将容器从', '火场移至空旷处。灭火剂：干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4742, 4877, '本品不燃, 遇水或潮气会分解放出二氧化硫、氯化氢等刺激性的有毒烟气。受热分解也能产生 有毒物质。对很多金属尤其是潮湿空气存在下有腐蚀性。', '硫化氢、氯化氢、氯气。', '消防人员必须穿全身耐酸碱消防服。灭火剂：二氧化碳、砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:32', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4743, 4878, '受高热分解，放出腐蚀性、刺激性的烟雾。', '氯化氢、氧化汞。', '不燃。火场周围可用的灭火介质。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4744, 4879, '能与氟或钾发生剧烈反应。受高热分解，放出高毒的烟气。', '氯化氢、铊、氧化铊。', '不燃。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4745, 4880, '遇高热或光分解，放出有毒气体。', '一氧化碳、二氧化碳、氯化物、氧化汞。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：水、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4746, 4881, '蚀金属并放出氢气，容易燃烧爆炸。与易燃物（如苯）和可燃物（如糖、纤维素等）接触会发 生剧烈反应，甚至引起燃烧。具有强腐蚀性。', '氯化氢、氧化硫。', '消防人员必须穿全身耐酸碱消防服。灭火剂：二氧化碳、砂土。禁止用水和泡沫灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4747, 4882, '易燃，遇明火、高热有引起燃烧爆炸的危险。受热分解产生有毒的甲醛和氯化氢气体。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳、氯化氢、甲醛。', '尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：抗溶性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4748, 4883, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。受热分解产生有毒的氯化氢和氧化硅烟气。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。与水反应产生氯化氢气体。', '一氧化碳、二氧化碳、氯化氢、氧化硅', '用干粉、二氧化碳、砂土灭火。禁止用水、泡沫、酸碱灭火器。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4749, 4884, '易燃，遇明火、高热有引起燃烧爆炸的危险。受热分解产生有毒的甲醛和氯化氢气体。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳、氯化氢、甲醛。', '尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：抗溶性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4750, 4885, '遇明火、高热可燃。受热分解产生有毒的腐蚀性烟气。与氧化剂可发生反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氯化氢、光气。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4751, 4886, '有腐蚀性。若遇高热，容器内压增大，有开裂和爆炸的危险。受高热分解，放出有毒的烟 气。', '一氧化碳、二氧化碳、氯化氢、光气。', '二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:36', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4752, 4887, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。受热分解产生有毒气体。', '一氧化碳、二氧化碳、氯化氢、光气。', '泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:36', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4753, 4888, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。受热分解产生有毒的氯化氢和光气等气体。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氯化氢、光气。', '泡沫、干粉、二氧化碳、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:36', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4754, 4889, '遇明火有引起燃烧的危险。遇水或受热会反应放出具有刺激性和腐蚀性的白色氯化氢烟雾。', '一氧化碳、二氧化碳、氯化氢、光气。', '干粉、二氧化碳、砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:36', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4755, 4890, '受热分解能放出剧毒的光气。遇水反应发热放出有毒的腐蚀性气体。与氧化剂可发生反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '氯化氢、光气。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4756, 4891, '遇明火、高热易燃。受热发生分解释出有刺激性和腐蚀性的气体。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氯化氢。', '抗溶性泡沫、干粉、二氧化碳、砂土。不宜用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4757, 4892, '蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压增 大，有开裂和爆炸的危险。遇潮时对大多数金属有腐蚀性。受高热分解，放出高毒的烟气。', '一氧化碳、二氧化碳、氯化氢、光气。', '抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4758, 4893, '易燃液体。受热分解能放出剧毒的光气。遇明火、高热易引起燃烧爆炸。', '一氧化碳、二氧化碳、氯化氢、光气。', '消防人员必须佩戴过滤式防毒面具(全面罩)或隔离式呼吸器、穿全身防火防毒服，在上风向灭火。灭火剂：二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4759, 4894, '易燃，受热分解能放出剧毒的光气。遇水或水蒸气反应放热并产生有毒的腐蚀性气体。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳、氯化氢、光气。', '消防人员必须佩戴过滤式防毒面具(全面罩)或隔离式呼吸器、穿全身防火防毒服，在上风向灭火。灭火剂：二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:39', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4760, 4895, '遇明火、高热易燃。遇水或受热分解，放出有毒的腐蚀性烟气。其蒸气比空气重，能在较低处 扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氯化氢。', '采用干粉、抗溶性泡沫、二氧化碳、砂土灭火。不宜用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4761, 4896, '遇明火有引起燃烧的危险。遇水或受热会反应放出具有刺激性和腐蚀性的白色氯化氢烟雾。', '一氧化碳、二氧化碳、氯化氢、光气。', '干粉、二氧化碳、砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4762, 4897, '扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氯化氢', '抗溶性泡沫、干粉、二氧化碳、砂土。不宜用水。喷水冷却容器，可能的话将容器从火场移至空旷处。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4763, 4898, '易燃液体。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂可发生反应。受热或接触火焰可能会产生膨胀或爆炸性分解。遇水反应发热放出有毒的腐蚀性气体。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4764, 4899, '易燃气体。与空气混合能形成爆炸性混合物。遇热源和明火有燃烧爆炸的危险。受热分解产生有毒的氯化物气体。与氧化剂接触猛烈反应。', '一氧化碳、二氧化碳、氯化氢、光气。', '切断气源。若不能切断气源，则不允许熄灭泄漏处的火焰。喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、泡沫、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4765, 4900, '高压压缩气体，遇热有爆炸危险。容器受热可能爆炸。暴露于火中的容器可能会通过压力安全阀泄漏出内容物。受热或接触火焰可能会产生膨胀或爆炸性分解。', '燃烧或分解时可能产生氟化氢、氯化氢等有毒气体。', '合适的灭火介质：干粉、二氧化碳。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4766, 4901, '不燃。受热分解产生有毒的腐蚀性烟气。容器受热有爆炸危险。', '氯化氢、氟化氢、一氧化碳、二氧化碳。', '消防人员必须佩戴空气呼吸器，穿全身防毒服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火剂：雾状水、泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4767, 4902, '受热或接触火焰可能会产生膨胀或爆炸性分解。加热时，容器可能爆炸。', '氮氧化物、氯化物、氨。', '使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4768, 4903, '与硫酸接触容易发生爆炸。急剧加热时可发生爆炸。', '氯化物、氧化钡。', '用大量水扑救，同时用干粉灭火剂闷熄。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4769, 4904, '为强氧化剂。能与可燃物、有机物、金属粉末或其他易氧化物形成爆炸性混合物。', '氯化物、氧化钙', '本品不燃。根据周围环境选择合适的灭火剂。如果该物质或被污染的流体进入水路，通知有潜在水体污染的下游用户，通知地方卫生、消防官员和污染控制部门。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:43', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4770, 4905, '磷或金属粉末等混合可形成爆炸性混合物。急剧加热时可发生爆炸。', '氯化物、氧化钾。', '用大量水扑救，同时用干粉灭火剂闷熄。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:44', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4771, 4906, '强氧化剂。与可燃物、还原剂、有机物等混合可形成爆炸性混合物。急剧加热时可发生爆炸。', '氯化物、氧化钾', '用大量水扑救，同时用干粉灭火剂闷熄。切勿将水流直接射入熔融物质，以免引起严重的流淌火灾或剧烈的沸溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:44', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4772, 4907, '无机氧化剂。与还原剂、有机物、易燃物如硫、磷或金属粉末等混合可形成爆炸性混合物。', '氯化物。', '用大量水扑救，同时用干粉灭火剂闷熄。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:44', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4773, 4908, '强氧化剂。与可燃物、还原剂、有机物等混合可形成爆炸性混合物。急剧加热时可发生爆炸。遇火源可引起燃烧或爆炸。', '氧气、氯化物、氧化钠。', '用大量水扑救，同时用干粉灭火剂闷熄。切勿将水流直接射入熔融物质，以免引起严重的流淌火灾或剧烈的沸溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4774, 4909, '加强并让火焰自身维持。灭火行动对已发生的火灾可能无效。加热时，容器可能爆炸。暴露于火中的容器可能会通过压力安全阀泄漏出内容物。受热或接触火焰可能会产生膨胀或爆炸性分解。', '氧气、氯化物、氧化钠。', '用大量水扑救，同时用干粉灭火剂闷熄。切勿将水流直接射入熔融物质，以免引起严重的流淌火灾或剧烈的沸溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4775, 4910, '本身不燃，但能助燃。与有机物、还原剂、易燃物等接触可发生剧烈反应，甚至爆炸。大于40%的溶液不稳定，其水溶液在蒸发时能发生爆炸性分解。', '氯化氢、氧气', '本品不燃。根据周围环境选择合适的灭火剂。如果该物质或被污染的流体进入水路，通知有潜在水体污染的下游用户，通知地方卫生、消防官员和污染控制部门。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4776, 4911, '强氧化剂。与可燃物、有机物或还原剂混合能形成爆炸性混合物。受热分解产生氧气，加剧燃烧。', '氯化氢、氧化铯', '雾状水、泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4777, 4912, '击可引起燃烧或爆炸。与硫酸接触容易发生爆炸。受高热分解，放出有毒的烟气。', '氯化氢。', '雾状水、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4778, 4913, '摩擦、撞击可引起燃烧或爆炸。与硫酸接触容易发生爆炸。受高热分解，放出有毒的烟气。', '氯化氢、铊。', '雾状水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4779, 4914, '击可引起燃烧或爆炸。与硫酸接触容易发生爆炸。受高热分解，放出有毒的烟气。', '氯化氢、氧化铜。', '雾状水、泡沫、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4780, 4915, '高热分解，放出有毒的烟气。', '氯化氢、氧化锌。', '雾状水、泡沫、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4781, 4916, '强氧化剂。与还原剂、有机物、易燃物如硫、磷或金属粉末等混合可形成爆炸性混合物。与硫酸接触容易发生爆炸。受高热分解，放出有毒的烟气。', '氧化银、氯化氢。', '雾状水、泡沫、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4782, 4917, '遇明火、高热可燃。受热分解产生有毒的氮氧化物和氯化物气体。', '一氧化碳、二氧化碳、氮氧化物、氯化氢', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火剂：雾状水、泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4783, 4918, '受高热分解放出有毒的气体。与碱金属能发生剧烈反应。', '氯化氢、溴化氢、光气。', '消防人员必须佩戴空气呼吸器、穿全身防毒服。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火剂：雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4784, 4919, '酸或酸气产生有毒的可燃性气体。', '一氧化碳、二氧化碳、氮氧化物、氯化氢。', '干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4785, 4920, '遇明火、高热可燃。受高热分解产生有毒的腐蚀性烟气。与强氧化剂接触可发生化学反应。 遇潮时对大多数金属有强腐蚀性。', '一氧化碳、二氧化碳、氯化氢、光气。', '采用雾状水、泡沫、二氧化碳灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4786, 4921, '燃烧时可能会释放毒性烟雾。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆 炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:50', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4787, 4922, '遇明火、高热可燃。受高热分解产生有毒的腐蚀性烟气。与强氧化剂接触可发生化学反应。遇 潮时对大多数金属有强腐蚀性。', '一氧化碳、二氧化碳、氯化氢、光气。', '采用雾状水、泡沫、二氧化碳灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:50', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4788, 4923, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。受热、接触酸或酸雾会放出剧 毒的烟雾。', '一氧化碳、二氧化碳、氯化氢。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。喷水冷却容器，可能的话将容器从 火场移至空旷处。灭火剂：雾状水、抗溶性泡沫、干粉、二氧化碳、砂土。用雾状水驱散蒸气。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4789, 4924, '不易燃烧。受高热分解产生有毒的腐蚀性烟气。', '一氧化碳、二氧化跋；氯化氢、氧化钠。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4790, 4925, '燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氯化氢。', '雾状水、抗溶性泡沫、二氧化碳、于粉、砂', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4791, 4926, '增加火势和/或蒸气的浓度。蒸气可能会移动到着火源并回闪。液体和蒸气易燃。燃烧时可 能会释放毒性烟雾。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽', '灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4792, 4927, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。受高热分解产生有毒的腐蚀性 烟气。', '一氧化碳、二氧化碳、氯化氢。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：雾状水、抗溶性泡沫、干 粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4793, 4928, '增加火势和/或蒸气的浓度。蒸气可能会移动到着火源并回闪。液体和蒸气易燃。燃烧时可 能会释放毒性烟雾。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4794, 4929, '易燃气体。与空气混合能形成爆炸性混合物。遇热源和明火有燃烧爆炸的危险。与氧化剂接触猛烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳、氯化氢、光气。', '切断气源。若不能切断气源，则不允许熄灭泄漏处的火焰。喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、泡沫、干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4795, 4930, '可发生剧烈聚合。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳、氯化氢。', '切断气源。若不能切断气源，则不允许熄灭泄漏处的火焰。喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、泡沫、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4796, 4931, '不燃。能与很多物质发生剧烈反应导致燃烧爆炸。受热或遇水分解放热, 放出有毒的腐蚀性烟 气。具有较强的腐蚀性。', '一氧化碳、二氧化碳、氯化氢。', '灭火剂：干粉、二氧化碳、砂土。禁止用水和泡沫灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4797, 4932, '遇明火、高热可燃。受热分解，放出有毒烟气。其蒸气与空气可形成爆炸性混合物，当达到一定的浓度时，遇火星会发生爆炸。', '一氧化碳、二氧化碳。', '雾状水、二氧化碳、泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4798, 4933, '放热现象，引起容器破裂和爆炸事故。', '一氧化碳、二氧化碳。', '雾状水、二氧化碳、泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4799, 4934, '易燃液体，其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '使用抗溶性泡沫、干粉、二氧化碳或砂土灭火', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4800, 4935, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。有腐蚀性。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4801, 4936, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。受热分解产生有毒的氮氧化物烟气。', '一氧化碳、二氧化碳、氧化氮。', '抗溶性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:56', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4802, 4937, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。遇明火、高热易燃。与强氧化剂发生反应，可引起燃烧。有腐蚀性。', '一氧化碳、二氧化碳、多环芳烃。', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:56', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4803, 4938, '遇明火、高热易燃。与强氧化剂发生反应，可引起燃烧。有腐蚀性。', '一氧化碳、二氧化碳。', '雾状水、二氧化碳、泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:56', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4804, 4939, '容器可能爆炸。暴露于火中的容器可能会通过压力安全阀泄漏出内容物。受热或接触火焰可能会产生膨胀或爆炸性分解。遇明火、高热易燃。与强氧化剂发生反应，可引起燃烧。有腐蚀性。', '一氧化碳、二氧化碳、多环芳烃。', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:56', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4805, 4940, '易燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4806, 4941, '引起燃烧或爆炸。遇氯、溴、碘、硫、磷、砷、和氧化剂剧烈反应，有燃烧、爆炸危险。粉体与空气可形成爆炸性混合物，当达到一定浓度时，遇火星会发生爆炸。', '氧化镁', '严禁用水、泡沫、二氧化碳扑救。最好的灭火方法是用干燥石墨粉和干砂闷熄火苗，隔绝空气。施救时对眼睛和皮肤须加保护，以免飞来炽粒烧伤身体、镁光灼伤视力。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:58', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4807, 4942, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。若遇高热，容器内压增大，有开裂和爆炸 的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:59', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4808, 4943, '加热时，容器可能爆炸。暴露于火中的容器可能会通过压力安全阀泄漏出内容物。受热或 接触火焰可能会产生膨胀或爆炸性分解。', '无资料', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:59', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4809, 4944, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳等', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:59', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4810, 4945, '可燃，受热、同硝酸等强氧化剂有引起燃烧的危险。产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳', '干粉、泡沫、沙土、二氧化碳、雾状水。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4811, 4946, '与卤素、磷、许多氧化物、氧化剂和酸类剧烈反应。燃烧时呈黄色火焰。100℃时开始蒸发， 蒸气可侵蚀玻璃。', '氧化钠。 不可用水、卤代烃（如1211灭火剂），碳酸氢钠、碳酸氢钾作为灭火剂。而应使用干燥氯', '化钠粉末、干燥石墨粉、碳酸钠干粉、碳酸钙干粉、干砂等灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:01', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4812, 4947, '能会通过压力安全阀泄漏出内容物。受热或接触火焰可能会产生膨胀或爆炸性分解。', '无资料 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:01', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4813, 4948, '若遇高热，容器内压增大，有开裂和爆炸的危险。', '无资料', '本品不燃。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:01', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4814, 4949, '酸钾等接触，能发生强烈反应，引起燃烧或爆炸。粉体与空气可形成爆炸性混合物,当达 到一定浓度时,遇火星会发生爆炸。', '一氧化碳、二氧化碳。 采用二氧化碳、雾状水、砂土灭火。切勿将水流直接射至熔融物，以免引起严重的流淌火', '灾或引起剧烈的沸溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:01', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4815, 4950, '遇明火、高热可燃。受高热分解，放出高毒的烟气。', '一氧化碳、二氧化碳、氧化硫、汞。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4816, 4951, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4817, 4952, '粉尘可燃，能与空气形成爆炸性混合物。', '氧化镍', '消防人员必须佩戴过滤式防毒面具(全面罩)或隔离式呼吸器、穿全身防火防毒服，在上风向灭火。灭火剂：干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4818, 4953, '遇明火、高热易燃。受热分解，放出有毒的烟气。若遇高热可发生剧烈分解，引起容器破 裂或爆炸事故。', '一氧化碳、二氧化碳、氮氧化物、氮气。', '雾状水、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4819, 4954, '遇明火、高热易燃。与氧化剂能发生强烈反应。', '一氧化碳、二氧化碳、氧化氮。', '喷水冷却容器，可能的话将容器从火场移至空旷处。泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4820, 4955, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳、氧化氮。', '雾状水、泡沫、二氧化碳、砂土、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4821, 4956, '遇水、潮湿空气、酸类、氧化剂，高热及明火能引起燃烧。遇水或酸类分解放出氢气，有燃烧爆炸危险。', '氧化硼、氢气', '干粉、干砂、石灰', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4822, 4957, '遇水、潮湿空气、酸类、氧化剂、高热及明火能引起燃烧。', '氧化硼、氢气。 合适的灭火介质:干粉，干砂或石灰。不合适的灭火介质:水、二氧化碳和泡沫。灭火时， 应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安全距离处、', '有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4823, 4958, '水或水蒸气、酸或酸气产生有毒的可燃性气体。与氧化剂能发生强烈反应。', '氧化铝、氧化硼。 合适的灭火介质:干粉，干砂或石灰。 不合适的灭火介质:水、二氧化碳和泡沫。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4824, 4959, '遇水、潮湿空气、酸类、氧化剂，高热及明火能引起燃烧。遇水或酸类分解放出氢气，有燃烧爆炸危险。', '氧化硼、氢气', '干粉、干砂、石灰', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:07', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4825, 4960, '受高热分解放出有毒的气体', '氧化硼', '不燃。火场周围可用的灭火介质：水、泡沫、干粉、二氧化碳', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:07', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4826, 4961, '易燃，其蒸气与空气可形成爆炸性混合物。遇明火、高热极易燃烧爆炸。与氧化剂接触猛烈反应。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氧化硼', '干粉、二氧化碳、耐醇泡沫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:07', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4827, 4962, '体。', '一氧化碳、二氧化碳、氧化硼。', '二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:07', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4828, 4963, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。若遇高热，容器内压增大，有开裂和 爆炸的危险。', '一氧化碳、二氧化碳、一氧化硼。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:08', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4829, 4964, '气时易自燃。', '可能产生有害的毒性烟雾。 消防人员必须佩戴过滤式防毒面具(全面罩)或隔离式呼吸器、穿全身防火防毒服，在上风向灭', '火。灭火剂：二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:08', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4830, 4965, '有氧化性。接触有机物有引起燃烧危险。', '受热分解可能产生氮氧化物、氨、钒氧化物等有毒烟雾', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4831, 4966, '爆炸性分解。', '受热分解可能产生钒氧化物、钾氧化物等有毒烟雾', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4832, 4967, '强氧化剂，与可燃物、还原剂等接触可能发生剧烈反应，甚至引起燃烧或爆炸。在火场中与可燃物混合会爆炸。加热时，容器可能爆炸。暴露于火中的容器可能会通过压力安全阀泄漏出内容物。受热或接触火焰可能会产生膨胀或爆炸性分解。', '分解产生碘蒸气、氧化碘等有毒气体。', '合适的灭火介质：雾状水、砂土。不合适的灭火介质：无特别说明。灭火方法：喷水冷却容器，可能的话将容器从火场移至空旷处。在火场中与可燃物混合会爆炸，消防人员须在有防爆掩蔽处操作。切勿将水流直接射至熔融物，以免引起严重的流淌火灾或引起剧烈的沸溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4833, 4968, '本身不燃，遇水或水蒸气反应放热，产生有毒和腐蚀性烟雾。与酸类物质反应剧烈。', '氧化硅、氧化钠', '根据周围环境选择合适的灭火剂。本品不燃，使用适合周围火源的灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4834, 4969, '有腐蚀性。受热分解产生剧毒的氧化磷烟气。', '氧化磷、磷烷。', '泡沫、二氧化碳、砂土、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4835, 4970, '受热分解产生有毒气体，与还原剂、有机物、易燃物等接触有燃烧爆炸危险。', '砷的氧化物、砷化氢等有毒气体', '干粉、二氧化碳或耐醇泡沫。不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4836, 4971, '不燃。受高热分解放出有毒的气体。', '氧化砷、氧化钠。', '消防人员必须穿全身防火防毒服，在上风向灭火。灭火剂：干粉、水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4837, 4972, '或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4838, 4973, '有腐蚀性。遇水或水蒸气反应发热放出有毒的腐蚀性气体。受热分解，放出高毒的烟气。', '一氧化碳、二氧化碳、氟化氢。', '不燃。火场周围可用的灭火介质。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4839, 4974, '受热或摩擦极易燃烧。与强氧化剂如铬酸酐、氯酸盐和高锰酸钾等接触，能发生强烈的反应， 引起燃烧或爆炸。遇水或水蒸气反应放出有毒的或易燃的气体。', '氧化硫、氧化磷、磷烷。', '二氧化碳、干粉、砂土。禁止用水。禁止用泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4840, 4975, '不易燃固体，但在高温下可能分解产生有毒气体。加热至分解温度（>300°C）时可能释放溴化氢、一氧化碳、二氧化碳及其他溴代有机化合物。粉尘与空气混合可能形成爆炸性混合物，但爆炸风险较低', '分解产物包括：溴化氢（HBr）、一氧化碳（CO）、二氧化碳（CO₂）、溴代二苯并二噁英（PBDDs）、溴代二苯并呋喃（PBDFs）等有毒有害气体。这些产物具有刺激性和潜在致癌性', '适用灭火剂：水雾、干粉灭火剂（ABC类）、二氧化碳、泡沫灭火剂。禁止使用直流水直接冲击粉尘，防止粉尘飞扬。灭火时应从上风向进行，保持安全距离', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4841, 4976, '或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4842, 4977, '建规火险分级：', '使用泡沫、二氧化碳或干粉灭火剂；喷水冷却火中容器，以免爆炸；灭火时穿戴自携式呼', '吸器、防护手套、足靴及护目镜', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4843, 4978, '遇高热、明火或氧化剂，有引起燃烧的危险。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、氧化硫、硫化氢。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4844, 4979, '或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:15', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4845, 4980, '与氟、氯、溴等卤素会剧烈反应。其蒸气与空气混合能形成爆炸性混合物，遇明火、高热极易燃烧爆炸。', '燃烧时生成水蒸气。', '灭火剂：雾状水、泡沫、二氧化碳、干粉。由于氢有复燃危险，在氢气源未切断前，可扑灭气源周围火势，防止扩大。但不得灭掉气源渗漏处的火。用水冷却容器，以防受热爆裂，并用水保护进行关阀或堵漏的人员。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4846, 4981, '受热可能发生爆炸性分解。', '二氧化碳、水蒸气。', '使用适合火灾类型的合适的灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:17', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4847, 4982, '遇水或潮湿空气产生氢气，遇火源会引起燃烧或爆炸。与氧化剂能发生强烈反应，引起燃烧或爆炸。', '氧化钡、氢气、水。', '合适的灭火介质：干粉、干砂或石灰。不合适的灭火介质：水、二氧化碳和泡沫。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:17', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4848, 4983, '遇水或潮湿空气产生氢气，遇火源会引起燃烧或爆炸。与氧化物剧烈反应。遇湿气和水分生成氢氧化物，腐蚀性很强。', '氧化钙、水。', '不可用水、泡沫、二氧化碳、卤代烃（如1211灭火剂）等灭火。只能用金属盖或干燥石墨粉、干燥白云石粉末将火焖熄。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:17', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4849, 4984, '具有强还原性。与氧化剂能发生强烈反应。受热或遇潮气、酸类放出氢气和热量，可引起燃烧或爆炸。', '水、氢气、氧化锆。', '合适的灭火介质：干粉、二氧化碳、耐醇泡沫和水喷雾。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:17', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4850, 4985, '遇水或潮湿空气产生氢气，遇火源会引起燃烧或爆炸。加热分解，放出剧毒的氧化钾烟雾。粉体在受热、遇明火或接触氧化剂时会引起燃烧爆炸。遇湿气和水分生成氢氧化物，腐蚀性很强。', '氧化钾、水。', '不可用水、泡沫、二氧化碳、卤代烃（如1211灭火剂）等灭火。只能用金属盖或干燥石墨粉、干燥白云石粉末将火焖熄。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4851, 4986, '遇湿气和水分生成氢氧化物，腐蚀性很强。与氧化剂能发生强烈反应，引起燃烧或爆炸。', '氧化锂、水。', '不可用水、泡沫、二氧化碳、卤代烃（如1211灭火剂）等灭火。只能用金属盖或干燥石墨粉、干燥白云石粉末将火焖熄。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4852, 4987, '暴露在空气中能自燃。遇水或酸发生反应放出氢气及热量，能引起燃烧。与氧化剂能发生强烈反应。', '氢气、氧化铝、水。', '合适的灭火介质：干粉、干砂或石灰。不合适的灭火介质：水、二氧化碳和泡沫。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4853, 4988, '与空气、水、醇、酸类接触，即发生放热反应并放出氢气而燃烧或爆炸。与强氧化剂接触猛烈反应而爆炸。', '氧化铝、氢气。', '不可用水、泡沫、二氧化碳、卤代烃（如1211灭火剂）等灭火。只能用金属盖或干燥石墨粉、干燥白云石粉末将火焖熄。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4854, 4989, '遇氧化剂、酸或水有引起燃烧爆炸危险。', '氢气、氧化铝、水。', '合适的灭火介质：干粉、干砂或石灰。不合适的灭火介质：水、二氧化碳和泡沫。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4855, 4990, '遇水或受热放出氢气，能引起燃烧或爆炸。与氧化剂能发生强烈反应。', '氧化镁、水。', '合适的灭火介质：干粉、干砂或石灰。不合适的灭火介质：水、二氧化碳和泡沫。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4856, 4991, '引起燃烧和爆炸。与氧化剂能发生强烈反应，引起燃烧或爆炸。遇湿气和水分生成氢氧化物，腐蚀性很强。', '氧化钠、水。', '不可用水、泡沫、二氧化碳、卤代烃（如1211灭火剂）等灭火。只能用金属盖或干燥石墨粉、干燥白云石粉末将火焖熄。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4857, 4992, '遇潮气、酸类放出氢气和热量，可引起燃烧或爆炸。', '氧化钛、氢气、钛、水。', '合适的灭火介质：干粉、二氧化碳、水喷雾或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4858, 4993, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4859, 4994, '易燃，受热分解产生有毒气体，可能引起燃烧和爆炸事故。', '氮氧化物、一氧化碳、二氧化碳。', '灭火剂：抗溶性泡沫、雾状水、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:22', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4860, 4995, '对大多数金属有强腐蚀性。能与普通金属发生反应，放出氢气而与空气形成爆炸性混合物。遇发泡剂立即燃烧。遇氰化物能产生剧毒的氰化氢气体。', '溴化氢。', '用碱性物质如碳酸氢钠、碳酸钠、消石灰等中和。小火可用干燥砂土闷熄。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:23', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4861, 4996, '未有特殊的燃烧爆炸特性。', '氧化钡。', '本品不燃。灭火剂：水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:23', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4862, 4997, '腐蚀性。', '可能产生有害的毒性烟雾。', '用水、砂土扑救，但须防止物品遇水产生飞溅，造成灼伤。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:23', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4863, 4998, '腐蚀性极强。与酸发生中和反应并放热。在水中形成腐蚀性溶液。', '可能产生有害的毒性烟雾。', '不燃。火场周围可用的灭火介质。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:24', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4864, 4999, '燃烧，遇水和水蒸气大量放热，形成腐蚀性溶液。具有强腐蚀性。', '可能产生有害的毒性烟雾。', '用水、砂土扑救，但须防止物品遇水产生飞溅，造成灼伤。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:24', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4865, 5000, '不燃。受高热分解放出有毒的气体。', '可能产生有害的毒性烟雾。', '消防人员必须佩戴过滤式防毒面具（全面罩）或隔离式呼吸器、穿全身防火防毒服，在上风向灭火。灭火剂：水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:24', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4866, 5001, '遇水发热，能引起有机物燃烧。与酸类发生剧烈反应。具有强腐蚀性。', '氧化铷。', '灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4867, 5002, '遇水发热，能引起有机物燃烧。与酸类发生剧烈反应。具有强腐蚀性。', '可能产生有害的毒性烟雾。', '灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4868, 5003, '安全阀泄漏出内容物。受热或接触火焰可能会产生膨胀或爆炸性分解。', '可能产生有害的毒性烟雾。', '灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4869, 5004, '较低处扩散到相当远的地方，遇火源引着回燃。遇水或水蒸气、酸或酸气产生剧毒的烟气。若遇高热，容器内压增大，有开裂和爆炸的危险。', '氰化氢、氧化氮。', '切断气源。若不能立即切断气源，则不允许熄灭正在燃烧的气体。喷水冷却容器，可能的话将容器从火场移至空旷处。二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4870, 5005, '本身不燃烧，但遇水或潮气、酸类产生易燃气体并放热，有发生燃烧爆炸的危险。', '一氧化碳、二氧化碳、氮氧化物、氰化氢。', '干粉、干砂或石灰。禁止使用水、二氧化碳和泡沫。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4871, 5006, '本身不燃烧，但受热分解产生剧毒的氰化氢、汞蒸气和氮氧化物气体。', '氰化氢、汞蒸气、氮氧化物、一氧化碳。', '干粉、二氧化碳或耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4872, 5007, '无资料', '氰化氢、氧化氮', '本品不燃。发生火灾时应尽量抢救商品，防止包装破损，引起环境污染。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：干粉、砂土。禁止用二氧化碳和酸碱灭火剂灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4873, 5008, '受高热分解，放出腐蚀性、刺激性的烟雾。', '氧化氮、氰化氢、碘化氢。', '不燃。火场周围可用的灭火介质。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4874, 5009, '有发生爆炸的危险。遇酸或露置空气中能吸收水分和二氧化碳分解出剧毒的氰化氢气体。', '氰化氢、氧化氮。', '本品不燃。发生火灾时应尽量抢救商品，防止包装破损，引起环境污染。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：干粉、砂土。禁止用二氧化碳和酸碱灭火剂灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4875, 5010, '遇酸或露置空气中能吸收水分和二氧化碳分解出剧毒的氰化氢气体。受热可能发生爆炸性分解。', '氰化氢、氧化氮、镉化合物。', '本品不燃。发生火灾时应尽量抢救商品，防止包装破损，引起环境污染。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：干粉、砂土。禁止用二氧化碳和酸碱灭火剂灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4876, 5011, '有发生爆炸的危险。遇酸或露置空气中能吸收水分和二氧化碳分解出剧毒的氰化氢气体。', '氰化氢、氧化氮。', '本品不燃。发生火灾时应尽量抢救商品，防止包装破损，引起环境污染。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：干粉、砂土。禁止用二氧化碳和酸碱灭火剂灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4877, 5012, '受热分解产生有毒的氰化氢和汞蒸气。', '氧化钾、汞、氰化物、氰化氢。', '不燃。根据周围环境选择合适的灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4878, 5013, '无资料', '氰化氢、氧化氮', '本品不燃。发生火灾时应尽量抢救商品，防止包装破损，引起环境污染。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：干粉、砂土。禁止用二氧化碳和酸碱灭火剂灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4879, 5014, '遇明火、高热可燃。受热分解产生有毒气体。或爆炸性分解。', '一氧化碳、二氧化碳、氮氧化物、氰化氢', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4880, 5015, '发生爆炸的危险。遇酸或露置空气中能吸收水分和二氧化碳分解出剧毒的氰化氢气体。水溶液为碱性腐蚀液体。', '氰化氢、氧化氮。', '本品不燃。发生火灾时应尽量抢救商品，防止包装破损，引起环境污染。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：干粉、砂土。禁止用二氧化碳和酸碱灭火剂灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4881, 5016, '遇明火、高热可燃。受热分解产生有毒的氰化氢和氮氧化物气体。与酸接触会释放剧毒的氰化氢气体。', '氰化氢、氮氧化物', '干粉、二氧化碳、耐醇泡沫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4882, 5017, '遇明火、高热可燃。受热分解产生剧毒的氰化氢气体。与氧化剂可发生反应。', '氰化氢、氮氧化物', '干粉、二氧化碳、耐醇泡沫。禁止用水、泡沫、酸碱灭火器。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4883, 5018, '受热或接触酸类会放出剧毒的氰化氢气体。在潮湿空气或二氧化碳中即缓慢发出微量氰化氢气体。', '氰化氢、氧化氮。', '本品不燃。发生火灾时应尽量抢救商品，防止包装破损，引起环境污染。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：干粉、砂土。禁止用二氧化碳和酸碱灭火剂灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4884, 5019, '遇酸或露置空气中能吸收水分和二氧化碳分解出剧毒的氰化氢气体。受高热分解，放出高毒的烟气。', '氮氧化物、氰化氢、镍化合物。', '本品不燃。发生火灾时应尽量抢救商品，防止包装破损，引起环境污染。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：干粉、砂土。禁止用二氧化碳和酸碱灭火剂灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:32', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4885, 5020, '遇酸或露置空气中能吸收水分和二氧化碳分解出剧毒的氰化氢气体。受高热可能发生爆炸性分解。', '氰化氢、氮氧化物、镍化合物。', '本品不燃。发生火灾时应尽量抢救商品，防止包装破损，引起环境污染。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：干粉、砂土。禁止用二氧化碳和酸碱灭火剂灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:32', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4886, 5021, '遇酸或露置空气中能吸收水分和二氧化碳分解出剧毒的氰化氢气体。受高热分解，放出高毒的烟气。', '氮氧化物、氰化氢、铅。', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:32', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4887, 5022, '遇酸或露置空气中能吸收水分和二氧化碳分解出剧毒的氰化氢气体。受高热分解，放出高毒的烟气。', '氮氧化物、氰化氢、铜化合物。', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4888, 5023, '遇酸或露置空气中能吸收水分和二氧化碳分解出剧毒的氰化氢气体。', '氰化氢、氧化氮、锌化合物。', '本品不燃。发生火灾时应尽量抢救商品，防止包装破损，引起环境污染。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：干粉、砂土。禁止用二氧化碳和酸碱灭火剂灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4889, 5024, '受热分解产生剧毒的氰化氢和溴化氢气体。', '氰化氢、溴化氢、氮氧化物、溴化物。', '消防人员必须佩戴过滤式防毒面具（全面罩）或隔离式呼吸器、穿全身防火防毒服，在上风向灭火。尽可能将容器从火场移至空旷处。灭火剂：二氧化碳、干粉、砂土。禁止用水、泡沫、酸碱灭火器。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4890, 5025, '遇明火、高热可燃。受高热分解放出有毒的氰化氢气体。', '氰化氢、氧化氮。', '干粉、二氧化碳、砂土。禁止用水、泡沫和酸碱灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4891, 5026, '有发生爆炸的危险。遇酸或露置空气中能吸收水分和二氧化碳分解出剧毒的氰化氢气体。', '氰化氢、氧化氮。', '本品不燃。发生火灾时应尽量抢救商品，防止包装破损，引起环境污染。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：干粉、砂土。禁止用二氧化碳和酸碱灭火剂灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4892, 5027, '受高热或接触酸或酸雾放出剧毒的氰化氢烟雾。氰化物遇酸会产生剧毒的氰化氢气体，吸入可致命。', '氰化氢、氧化氮、一氧化碳等有毒气体。', '本品不燃，但周围环境着火时，使用适合周围火源的灭火剂：干粉、二氧化碳、泡沫。禁止使用酸碱灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4893, 5028, '受高热或接触酸或酸雾放出剧毒的氰化氢烟雾。氰化物遇酸会产生剧毒的氰化氢气体，吸入可致命。', '氰化氢、氧化氮、一氧化碳等有毒气体。', '本品不燃，但周围环境着火时，使用适合周围火源的灭火剂：干粉、二氧化碳、泡沫。禁止使用酸碱灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4894, 5029, '遇酸或露置空气中能吸收水分和二氧化碳分解出剧毒的氰化氢气体。', '氰化氢、氮氧化物、银化合物。', '本品不燃。发生火灾时应尽量抢救商品，防止包装破损，引起环境污染。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：干粉、砂土。禁止用二氧化碳和酸碱灭火剂灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4895, 5030, '遇酸或露置空气中能吸收水分和二氧化碳分解出剧毒的氰化氢气体。', '氰化氢、氰化物、氧化钾、氧化银、氮氧化物。', '本品不燃。发生火灾时应尽量抢救商品，防止包装破损，引起环境污染。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：干粉、砂土。禁止用二氧化碳和酸碱灭火剂灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:37', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4896, 5031, '遇明火能燃烧。受潮或受高热分解释出剧毒的乙氰蒸气。具有腐蚀性。', '一氧化碳、二氧化碳、氧化氮、氰化氢。', '消防人员须佩戴氧气呼吸器。灭火剂：干粉、二氧化碳、泡沫。禁止使用酸碱灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:37', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4897, 5032, '遇明火、高热可燃。与强氧化剂可发生反应。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、氧化氮、氰化氢。', '干粉、泡沫、二氧化碳、砂土。禁止使用酸碱灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:37', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4898, 5033, '受热分解放出剧毒的氰化物气体。遇明火、高热可燃。', '一氧化碳、氮氧化物、氰化氢。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:37', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4899, 5034, '有毒的腐蚀性气体。遇明火、高热可燃。受热分解产生有毒的氯化氢气体。', '氧化氮、氯化物、氯化氢。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4900, 5035, '遇明火、高热可燃。与强氧化剂可发生反应。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、氧化氮。', '干粉、泡沫、二氧化碳、砂土。禁止使用酸碱灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4901, 5036, '遇明火、高热易燃。受热分解，放出有毒的烟气。若遇高热可发生剧烈分解，引起容器破裂或爆炸事故。', '氟化氢、二氧化硫、一氧化碳、二氧化碳等有毒气体。', '干粉、二氧化碳、耐醇泡沫。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:39', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4902, 5037, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、氟化氢、硫氧化物等', '干粉、二氧化碳、泡沫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:39', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4903, 5038, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。遇明火、高热可燃。', '一氧化碳、二氧化碳、氟化氢、硫氧化物、氮氧化物等有毒烟雾。', '干粉、二氧化碳、泡沫、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4904, 5039, '遇明火、高热可燃。受热分解产生有毒的氟化氢、氮氧化物、二氧化硫等气体。与氧化剂接触有发生燃烧爆炸的危险。', '氟化氢、氮氧化物、二氧化硫、一氧化碳、二氧化碳', '干粉、二氧化碳、泡沫。禁止使用直流水灭火，以免引起飞溅或扩散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4905, 5040, '遇明火、高热可燃。受热分解产生有毒的氟化氢和硫氧化物烟雾。与氧化剂接触可能发生剧烈反应。', '氟化氢、硫氧化物、一氧化碳、二氧化碳', '干粉、二氧化碳、泡沫。切勿将水流直接射入熔融物质，以免引起严重的流淌火灾或飞溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4906, 5041, '不燃，但受热分解产生有毒气体。', '受热分解产生氟化氢、硫氧化物等有毒气体。', '根据周围环境选择合适的灭火剂。建议使用干粉、二氧化碳、泡沫。灭火时佩戴自给式呼吸器，穿全身防护服。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4907, 5042, '遇明火、高热易燃。受热分解，放出有毒的烟气。若遇高热可发生剧烈分解，引起容器破裂或爆炸事故。', '氟化氢、二氧化硫、一氧化碳、二氧化碳等有毒气体。', '干粉、二氧化碳、耐醇泡沫。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4908, 5043, '受高热分解，放出腐蚀性、刺激性的烟雾。', '氯化氢、硫化物。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4909, 5044, '不易燃烧。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氯化氢。', '泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4910, 5045, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。燃烧分解时，放出有毒的氮氧化物。', '一氧化碳、二氧化碳、氮氧化物。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4911, 5046, '遇明火、高热可燃。粉尘与空气可形成爆炸性混合物。', '一氧化碳、二氧化碳', '雾状水、泡沫、二氧化碳、干粉、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4912, 5047, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳。', '抗溶性泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:44', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4913, 5048, '的危险。', '一氧化碳、二氧化碳。', '抗溶性泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:44', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4914, 5049, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:44', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4915, 5050, '能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳', '干粉、二氧化碳或耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4916, 5051, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4917, 5052, '遇潮时对大多数金属有腐蚀性。受热分解，放出有毒的氯化氢气体和氧化硅烟雾。遇水或水蒸气反应剧烈，放出氯化氢气体。', '一氧化碳、二氧化碳、氯化氢、氧化硅。', '抗溶性泡沫、干粉、二氧化碳。不宜用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4918, 5053, '的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:46', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4919, 5054, '与氧化剂发生强烈反应。在火场中，受热的容器有爆炸危险。', '一氧化碳、二氧化碳。', '尽可能将容器从火场移至空旷处。灭火剂：泡沫、二氧化碳、干粉、砂土。用水灭火无效，但须用水保持火场容器冷却。用雾状水保护消防人员，用砂土堵逸出液体。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:46', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4920, 5055, '或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4921, 5056, '或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4922, 5057, '遇高热、明火或氧化剂，有引起燃烧的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、砂土、1211灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4923, 5058, '器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、硫化氢、氧化硫。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4924, 5059, '或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4925, 5060, '遇明火、高热可燃。受高热分解，放出高毒的烟气。', '一氧化碳、二氧化碳、溴化氢、氧化磷。', '抗溶性泡沫、干粉、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4926, 5061, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '氮氧化物、氧化磷、一氧化碳、二氧化碳。', '干粉、二氧化碳或耐醇泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4927, 5062, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、氧化锡。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4928, 5063, '遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4929, 5064, '遇明火、高热可燃。受热分解产生剧毒的氧化磷烟气。与氧化剂可发生反应。', '一氧化碳、二氧化碳、氧化磷、磷烷。', '采用雾状水、泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4930, 5065, '遇明火、高热可燃。遇水或水蒸气分解放出有毒的气体。', '一氧化碳、二氧化碳，氧化硅、氯化氢。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4931, 5066, '遇明火、高热可燃。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、氧化锡。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4932, 5067, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4933, 5068, '卤代烃、醇发生剧烈反应。加热产生易燃气体。', '一氧化碳、二氧化碳、氧化铝。 合适的灭火介质:干粉，干砂或石灰。 不合适的灭火介质:水、二氧化碳和泡沫。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:52', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4934, 5069, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '氯化氢、一氧化碳、二氧化碳。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。不合适的灭火介质:避免用太强烈的水汽灭火， 因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当', '的)）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表 和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4935, 5070, '若遇高热，升华产生剧毒的气体。与金属钾和钠能形成对撞击敏感的物质。', '碘化氢、氧化砷。', '消防人员必须穿全身防火防毒服，在上风向灭火。灭火剂：干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4936, 5071, '或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4937, 5072, '本身不燃烧，但遇高热能放出有毒的烟气。遇氰化物能产生剧毒的氰化氢气体。遇Ｈ发泡剂立 即燃烧。遇钾、钠剧烈反应。具有腐蚀性。', '氧化锑、碘化氢。', '灭火剂：干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4938, 5073, '不燃。与锂、钾钠合金接触剧烈反应。本品较不稳定，在空气与阳光照射下容易分解出游 离碘能刺激眼睛和呼吸道，并灼伤皮肤。', '一氧化碳、二氧化碳、碘化氢。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：雾状水、泡沫、二氧 化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4939, 5074, '不易燃烧。受高热分解产生有毒的腐蚀性烟气。有腐蚀性。', '一氧化碳、二氧化碳、碘化氢。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4940, 5075, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氧化锡。', '泡沫、二氧化碳、水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4941, 5076, '具有强还原性。遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳、氧化磷。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4942, 5077, '接触空气，湿气或水可能燃烧。使用时可能产生易燃或易爆的蒸气-空气混合物。加热时， 容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '灭火方法： 合适的灭火介质：干粉，干砂或石灰。不合适的灭火介质：水、二氧化碳和泡沫。', '合适的灭火介质：干粉，干砂或石灰。不合适的灭火介质：水、二氧化碳和泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4943, 5078, '或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:56', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4944, 5079, '火焰被扑灭后可能复燃。注意有自燃的危险。加热时，容器可能爆炸。受热或接触火焰 可能会产生膨胀或爆炸性分解。', '灭火方法： 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4945, 5080, '烧时可能会释放毒性烟雾。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或 爆炸性分解。', '合适的灭火介质：小火：干式化学灭火剂、二氧化碳、水或抗溶泡沫灭火剂；大火：水、', '水雾或抗溶泡沫灭火剂。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会 使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4946, 5081, '或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4947, 5082, '或爆炸性分解。', '灭火方法： 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4948, 5083, '或爆炸性分解。', '灭火方法： 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:59', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4949, 5084, '或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:59', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4950, 5085, '遇明火、高热可燃。受热分解产生有毒气体。', '一氧化碳、二氧化碳、氧化锡等有毒气体。', '灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。灭火剂：干粉、二氧化碳或耐醇泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:59', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4951, 5086, '地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氟化氢。', '雾状水、抗溶性泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:59', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4952, 5087, '不燃。受热分解产生有毒的氟化氢烟雾。遇水分解产生氟化氢，具有强腐蚀性。', '氟化氢、铋的氧化物。', '本品不燃。根据着火原因选择适当灭火剂。灭火剂：干粉、二氧化碳、砂土。禁止用水直接灭火，因为遇水会产生氟化氢。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:59', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4953, 5088, '强氧化剂。受热或与火焰、电火化、有机物等接触能燃烧，甚至爆炸。与易燃物（如苯）和可燃物（如糖、纤维素等）接触会发生剧烈反应，甚至引起燃烧。与还原剂能发生强烈反应，引起燃烧爆炸。', '氟化氢、氮氧化物', '消防人员必须穿全身防火防毒服，在上风向灭火。切断气源。喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4954, 5089, '接触F202发生爆炸。和硼烷、氟、氧等发生剧烈反应。遇水或高热能放出大量有毒的气体。', '氟化氢、氧化磷、磷化氢。', '本品不燃。根据着火原因选择适当灭火剂。切断气源。若不能切断气源，则不允许熄灭泄漏处的火焰。喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:01', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4955, 5090, '若遇高热，容器内压增大，有开裂和爆炸的危险。', '氟化氢、氯化氢。', '不燃。切断气源。喷水冷却容器，可能的话将容器从火场移至空旷处。雾状水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:01', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4956, 5091, '化学反应活性很高，遇水发生爆炸性分解。与铜及其合金有可能生成具有爆炸性的氯乙炔。暴露在空气中遇潮气时迅速水解成氟硼酸与硼酸，产生白色烟雾。腐蚀性很强，冷时也能腐蚀玻璃。', '氟化氢、氧化硼。', '本品不燃。消防人员必须穿全身防火防毒服，在上风向灭火。切断气源。喷水冷却容器，尽可能将容器从火场移至空旷处。灭火剂：泡沫、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:01', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4957, 5092, '极端易燃，有爆炸危险。会跟水激烈反应，生成高度易燃的气体。受高热分解产生有毒的腐蚀性烟气。', '氟化氢、一氧化碳、二氧化碳、硼化合物', '干粉、二氧化碳、砂土。禁止用水、泡沫、酸碱灭火器。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4958, 5093, '有腐蚀性。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、氟化氢、氧化硼。', '抗溶性泡沫、二氧化碳、干粉。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4959, 5094, '火会产生刺激性、毒性或腐蚀性的气体。加热时，容器可能爆炸。受热或接触火焰可能 会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、氟化氢、硼化物', '干粉、二氧化碳、抗溶性泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4960, 5095, '遇明火、高热可燃。有腐蚀性。', '一氧化碳、二氧化碳、氟化氢、氧化硼。', '泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4961, 5096, '遇明火、高热可燃。受热分解产生有毒的氟化氢、氧化硼等气体。具有强腐蚀性。', '一氧化碳、二氧化碳、氟化氢、氧化硼。', '二氧化碳、干粉、砂土。禁止用水直接灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4962, 5097, '不燃。受热分解产生有毒的氟化氢和氧化砷烟雾。', '氟化氢、氧化砷。', '消防人员必须穿全身防火防毒服，在上风向灭火。灭火剂：干燥砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4963, 5098, '不燃。受热分解产生有毒的氟化氢烟雾。遇水或潮湿空气分解产生氟化氢。', '氟化氢、氧化锑。', '本品不燃。根据着火原因选择适当灭火剂。灭火剂：干粉、二氧化碳、砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4964, 5099, '接触易着火燃烧。遇水发生剧烈反应，产生剧毒的腐蚀性的氟化氢气体。受高热或接触 酸或酸雾放出剧毒的烟雾。具有强腐蚀性。', '氟化物、溴化物、溴化氢、氟化氢。', '二氧化碳、干粉。禁止用水、泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4965, 5100, '不燃。受热分解释出剧毒的烟雾。', '氟化氢。', '本品不燃。切断气源。喷水冷却容器，可能的话将容器从火场移至空旷处。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4966, 5101, '有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氟化氢、氯化氢。', '切断气源。若不能立即切断气源，则不允许熄灭正在燃烧的气体。喷水冷却容器，可能的话将容器从火场移至空旷处。雾状水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4967, 5102, '不燃。受热分解或与酸类接触放出有毒气体。具有强腐蚀性。', '一氧化碳、二氧化碳、氟化氢。', '灭火剂：干粉、砂土。禁止用水和泡沫灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4968, 5103, '遇低级醇和水起化学反应而分解。对很多金属尤其是潮湿空气存在下有腐蚀性。', '一氧化碳、二氧化碳、氟化氢。', '灭火剂：干粉、砂土。禁止用水和泡沫灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4969, 5104, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、氟化氢、氧化铬', '干粉、二氧化碳或耐醇泡沫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:07', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4970, 5105, '其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂可发生反应。流速过快，容易产生和积聚静电。其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。有腐蚀性。', '一氧化碳、二氧化碳、氟化氢。', '抗溶性泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:08', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4971, 5106, '遇明火、高热可燃。受热分解产生有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、氟化物。', '采用泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:08', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4972, 5107, '遇水反应，放出具有刺激性和腐蚀性的氯化氢气体。受高热分解放出有毒的气体。遇潮时对大多数金属有腐蚀性。', '一氧化碳、氯化氢、氟化物。', '切断气源。喷水冷却容器，可能的话将容器从火场移至空旷处。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:08', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4973, 5108, '遇明火、高热可燃。受热分解产生有毒气体，可能发生爆炸性分解。', '氧化硫、氧化锡烟雾、一氧化碳、二氧化碳', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:08', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4974, 5109, '烟气。与氧化剂接触猛烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着 火回燃。', '一氧化碳、二氧化碳、氧化氮。 切断气源。若不能切断气源，则不允许熄灭泄漏处的火焰。喷水冷却容器，可能的话将容器从火', '场移至空旷处。灭火剂：雾状水、抗溶性泡沫、干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:10', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4975, 5110, '遇明火、高热可燃。受热分解产生有毒的氮氧化物烟气。', '一氧化碳、二氧化碳、氮氧化物。', '喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：干粉、二氧化碳、耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:10', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4976, 5111, '接触空气、湿气或水可能燃烧。使用时可能产生易燃或易爆的蒸气-空气混合物。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '氧化铝、一氧化碳、二氧化碳', '合适的灭火介质：干粉、干砂或石灰。不合适的灭火介质：水、二氧化碳和泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:10', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4977, 5112, '遇明火、高热极易燃烧燃烧。受热分解产生有毒的腐蚀性烟气。具有腐蚀性。', '一氧化碳、二氧化碳、氧化硅、氯化氢。', '喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：二氧化碳、干粉、干砂。禁止用水和泡沫灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4978, 5113, '遇明火、氧化剂或暴露于空气中有引起燃烧的危险。', '一氧化碳、二氧化碳、氧化硼。', '二氧化碳、干粉、砂土。禁止用水。禁止用泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:12', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4979, 5114, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。遇潮时对大多数金属有腐蚀性。', '一氧化碳、二氧化碳、氯化氢。', '二氧化碳、干粉。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:12', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4980, 5115, '从而增加火势和/或蒸气的浓度。蒸气可能会移动到着火源并回闪。液体和蒸气易燃。加 热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:12', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4981, 5116, '一定的浓度时，遇火星会发生爆炸。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4982, 5117, '受热分解放出剧毒的氰化物气体。', '一氧化碳、二氧化碳、氮氧化物、氰化氢。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4983, 5118, '出现大量放热现象，引起容器破裂或爆炸事故。', '一氧化碳、二氧化碳、氮氧化物、氰化物。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4984, 5119, '容器可能爆炸。暴露于火中的容器可能会通过压力安全阀泄漏出内容物。受热或接触火焰 可能会产生膨胀或爆炸性分解。', '无资料', '采用抗溶性泡沫、二氧化碳、干粉、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4985, 5120, '从而增加火势和/或蒸气的浓度。蒸气可能会移动到着火源并回闪。液体和蒸气易燃。加 热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4986, 5121, '受热或摩擦极易燃烧。与强氧化剂如铬酸酐、氯酸盐和高锰酸钾等接触，能发生强烈的反应， 引起燃烧或爆炸。遇水或水蒸气反应放出有毒的或易燃的气体。', '氧化硫、氧化磷、磷烷。', '二氧化碳、干粉、砂土。禁止用水。禁止用泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4987, 5122, '时，遇火星会发生爆炸。', '氧化硫、硫化氢、氧化锑。', '水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:15', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4988, 5123, '受热或摩擦极易燃烧。与强氧化剂如铬酸酐、氯酸盐和高锰酸钾等接触，能发生强烈的反应， 引起燃烧或爆炸。遇水或水蒸气反应放出有毒的或易燃的气体。', '氧化硫、氧化磷、磷烷。', '干粉、砂土。禁止用水。禁止用泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:15', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4989, 5124, '极易挥发，在空气中发烟，遇水或水蒸气能产生热和有毒的腐蚀性烟雾。', '氯化氢、氧化硅。 消防人员必须佩戴过滤式防毒面具(全面罩)或隔离式呼吸器、穿全身防火防毒服，在上风', '向灭火。灭火剂：干粉、干砂。切忌使用水、泡沫、二氧化碳、酸碱灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:15', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4990, 5125, '受高热分解，放出腐蚀性、刺激性的烟雾。吸潮或遇水会产生大量的腐蚀性烟雾。具有强腐蚀 性。', '氯化物、氯气、碘化氢。', '消防人员必须穿全身耐酸碱消防服。灭火剂：二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:15', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4991, 5126, '基碘化镁和其它格利雅试剂发生剧烈反应。受高热分解，放出有毒的烟气。', '氯化氢、氧化钒。', '不燃。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:17', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4992, 5127, '遇水猛烈分解, 产生大量的热和浓烟, 甚至爆炸。对很多金属尤其是潮湿空气存在下有腐蚀性。', '氯化氢、氧化磷、磷烷。', '消防人员必须穿全身耐酸碱消防服。灭火剂：干粉、二氧化碳、干燥砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:17', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4993, 5128, '遇水或水蒸气反应放热并产生有毒的腐蚀性气体。对很多金属尤其是潮湿空气存在下有腐蚀性。', '氯化氢、氧化铝。', '消防人员必须穿全身耐酸碱消防服。灭火剂：干燥砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:17', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4994, 5129, '遇明火、高热可燃。受热分解产生有毒、腐蚀性烟气。与氧化剂发生剧烈反应。', '氯化氢、钼氧化物等有毒、腐蚀性气体。', '干粉、二氧化碳、砂土。禁止用水、泡沫灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:17', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4995, 5130, '遇水剧烈反应，产生氯化氢和硼酸，对大多数金属有强腐蚀性，也能腐蚀玻璃等。在潮湿空气中可形成白色的腐蚀性浓厚烟雾。', '氯化氢、氧化硼。', '本品不燃。切断气源。喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：砂土。禁止用水和泡沫灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4996, 5131, '受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氯化氢、氧化铝。', '干粉、砂土。禁止用水、泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4997, 5132, '接触空气，湿气或水可能燃烧。使用时可能产生易燃或易爆的蒸气-空气混合物。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '氯化氢、氧化铝。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：干粉、干砂或石灰。禁止用水、二氧化碳和泡沫灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4998, 5133, '受热分解产生有毒的砷和氯化物烟雾。与水或水蒸气反应产生有毒和腐蚀性的氯化氢烟雾。与碱类、氧化剂、金属粉末等发生剧烈反应。撞击后能猛烈爆炸。具有较强的腐蚀性。', '氯化氢、氧化砷。', '消防人员必须穿全身防火防毒服，在上风向灭火。灭火剂：干燥砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (4999, 5134, '潮湿空气存在下，放出热和近似白色烟雾状有刺激性和腐蚀性的氯化氢气体。', '氯化氢、氧化钛。', '灭火剂：二氧化碳、干粉、砂土。禁止用水和泡沫灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5000, 5135, '在潮湿空气中发烟，具有强腐蚀性。', '氯化氢、氧化锑', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。用雾状水保持火场中容器冷却。灭火剂：二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5001, 5136, '受高热分解产生有毒的腐蚀性烟气。', '氯化物。', '采用水、泡沫、二氧化碳灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5002, 5137, '遇明火、高热可燃。与氧化剂可发生反应。受高热分解产生有毒的腐蚀性烟气。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5003, 5138, '对金属有强烈的腐蚀性。', '氯化氢、光气。 消防人员必须佩戴过滤式防毒面具(全面罩)或隔离式呼吸器、穿全身防火防毒服，在上风向灭', '火。灭火剂：雾状水、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:22', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5004, 5139, '在高温下可燃烧。', '一氧化碳、二氧化碳、氯化氢、氟化物。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:22', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5005, 5140, '其蒸气沿地面扩散，有毒。遇发烟硫酸可分解产生光气。', '氯化氢、氧化氮、一氧化碳、二氧化碳。 消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：雾状水、泡沫、二氧化碳、', '砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:22', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5006, 5141, '与钠、钾发生剧烈反应。遇潮时对大多数金属有腐蚀性。受高热分解，放出有毒的烟气。', '氯化氢、氧化钒。', '二氧化碳、干粉、砂土。禁止用水、泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:22', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5007, 5142, '若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氟化氢、氯化氢。', '本品不燃。切断气源。喷水冷却容器，可能的话将容器从火场移至空旷处。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:24', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5008, 5143, '强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、氧化氮、氯化氢。 消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：干粉、二氧化碳、砂土。', '禁止用水、泡沫和酸碱灭火剂灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:24', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5009, 5144, '受热分解放出有催泪性及腐蚀性的气体。', '一氧化碳、二氧化碳、氯化氢。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：雾状水、抗溶性泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:24', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5010, 5145, '受高热分解产生有毒的腐蚀性烟气。具有较强的腐蚀性。', '一氧化碳、二氧化碳、氯化氢。', '采用雾状水、泡沫、二氧化碳灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:24', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5011, 5146, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氯化氢。', '抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5012, 5147, '热时分解产生有毒的光气和腐蚀性的盐酸烟雾。', '一氧化碳、二氧化碳、氯化氢、光气。 消防人员须佩戴氧气呼吸器。喷水保持火场容器冷却，直至灭火结束。灭火剂：雾状水、泡沫、', '干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5013, 5148, '热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氯化氢、光气。', '不燃。火场周围可用的灭火介质。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5014, 5149, '遇水或潮湿空气会分解产生氯气，遇热会分解产生有毒气体。具有强氧化性，与可燃物、还原剂接触能引起燃烧爆炸。', '一氧化碳、二氧化碳、氮氧化物、氯化氢、氯气。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火剂：雾状水、泡沫、干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5015, 5150, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳、氮氧化物。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5016, 5151, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '灭火方法： 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5017, 5152, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '灭火方法： 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5018, 5153, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '灭火方法： 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5019, 5154, '遇明火、高热、摩擦、震动、撞击，有引起燃烧爆炸的危险。与氧化剂能发生强烈反应。 受热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、水。禁止用砂土压盖。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5020, 5155, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '灭火方法： 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5021, 5156, '达到一定浓度时, 遇火星会发生爆炸。', '一氧化碳、二氧化碳、氮氧化物。 消防人员须戴好防毒面具，在安全距离以外，在上风向灭火。遇大火切勿轻易接近。灭火剂：', '水、泡沫、二氧化碳、干粉。禁止用砂土压盖。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5022, 5157, '受高热发生剧烈分解，甚至发生爆炸。与还原剂能发生强烈反应。具有强腐蚀性。', '溴化氢、碘化氢。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5023, 5158, '遇水发热、冒烟甚至燃烧爆炸。具有腐蚀性。', '溴化氢、氧化磷、磷烷。', '灭火剂：二氧化碳、砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5024, 5159, '受高热分解产生有毒的溴化物气体。与水强烈反应产生高热, 可发生爆炸。与金属钾和钠能 形成对撞击敏感的物质。具有腐蚀性。', '溴化氢、氧化铝。', '消防人员必须穿全身耐酸碱消防服。灭火剂：二氧化碳、干燥砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5025, 5160, '受热或遇水分解，放出有毒的腐蚀性气体，有时会发生爆炸。具有腐蚀性。', '溴化氢、氧化硼。', '消防人员必须穿全身耐酸碱消防服。灭火剂：干粉、二氧化碳、干燥砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5026, 5161, '受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、溴化氢、氧化铝。 合适的灭火介质:干粉，干砂或石灰。 不合适的灭火介质:水、二氧化碳和泡沫。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5027, 5162, '遇水或高热能放出大量有毒的气体。', '溴化氢、砷。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5028, 5163, '受热或遇水分解放热, 放出有毒的腐蚀性烟气。具有腐蚀性。', '溴化氢。', '消防人员必须穿全身耐酸碱消防服。灭火剂：干粉、二氧化碳、干燥砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5029, 5164, '不燃。受高热分解产生有毒的溴化物气体。与锂、钾钠合金接触剧烈反应。', '一氧化碳、二氧化碳、溴化氢。', '泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5030, 5165, '有腐蚀性。受热分解放出有催泪性、腐蚀性的烟气。', '一氧化碳、二氧化碳、溴化氢。', '雾状水、抗溶性泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5031, 5166, '遇明火能燃烧。受高热分解产生有毒的溴化物气体。', '溴化氢。', '在物料附近失火，须用水保持容器冷却。灭火剂：雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5032, 5167, '遇明火、高热可燃。燃烧时，放出有毒气体。能腐蚀铜及其合金。', '一氧化碳、二氧化碳、氧化氮。', '用水喷射逸出液体，使其稀释成不燃性混合物，并用雾状水保护消防人员。灭火剂：水、抗溶 性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5033, 5168, '受热分解产生有毒的氮氧化物烟雾。与易燃物、可燃物、还原剂等发生剧烈反应，有燃烧爆炸的危险。', '氮氧化物。', '消防人员必须穿全身防火防毒服，在上风向灭火。切断气源。若不能切断气源，则不允许熄灭泄漏处的火焰。喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5034, 5169, '在空气中加热时能着火。受高热分解，放出有毒的烟气。', '有害的毒性烟气。', '不燃。火场周围可用的灭火介质。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5035, 5170, '遇水或水蒸气反应放出并产生剧毒的自燃的磷化氢气体。熔化物在空气中易燃。遇氧气、 空气、卤素、硫酸、水、氨等发生剧烈反应。受高热分解，放出有毒的烟气。', '有害的毒性烟气。', '不燃。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:36', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5036, 5171, '受高热分解，放出有毒的蒸气。', '氧化铅。', '不燃。火场周围可用的灭火介质。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:37', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5037, 5172, '若遇高热，升华产生剧毒的气体。', '氧化砷。', '消防人员必须穿全身防火防毒服，在上风向灭火。灭火剂：干粉、水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:37', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5038, 5173, '起燃烧。与还原性物质如镁粉、铝粉、硫、磷等混合后,经摩擦或撞击,能引起燃烧或爆炸。 具有较强的腐蚀性。', '可能产生有害的毒性烟雾。', '采用雾状水、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:37', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5039, 5174, '与水能发生强烈反应。', '氧化硫', '砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:37', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5040, 5175, '受高热分解，放出有毒的蒸气。', '氧化硒。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:39', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5041, 5176, '生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。具 有腐蚀性。', '一氧化碳、二氧化碳、氧化氮。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：抗溶性泡沫、二氧化碳、干', '粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:39', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5042, 5177, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳、氮氧化物。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:39', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5043, 5178, '遇明火、高热可燃。', '一氧化碳、二氧化碳。 尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的容器 若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：雾状水、泡沫、干粉、二氧', '化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:39', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5044, 5179, '爆炸。与酸、卤素、醇、胺类接触发生剧烈反应。遇水强烈分解,放出易燃的烷烃气体。', '一氧化碳、二氧化碳、氧化铝。', '采用干粉、干砂灭火。禁止用水和泡沫灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5045, 5180, '遇明火、高热可燃。燃烧分解时，放出有毒的刺激性氯化物烟气。', '一氧化碳、二氧化碳、氯化氢、氧化锡。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5046, 5181, '气体。', '一氧化碳、二氧化碳、氧化硼。 合适的灭火介质:干粉、干砂、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5047, 5182, '或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5048, 5183, '烧爆炸的危险。具有腐蚀性。', '一氧化碳、二氧化碳、氧化锑。', '采用干粉、干砂灭火。禁止用水和泡沫灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5049, 5184, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳、氧化磷、磷烷。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5050, 5185, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳、氮氧化物。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:43', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5051, 5186, '爆炸。与氧化剂能发生强烈反应。遇水强烈分解,放出易燃的烷烃气体。遇高温剧烈分解。', '一氧化碳、二氧化碳、氧化铝。', '采用干粉、干砂灭火。禁止用水和泡沫灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:43', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5052, 5187, '其蒸气与空气可形成爆炸性混合物，遇明火、高热易引起燃烧爆炸。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、氧化氮。', '采用干粉、二氧化碳、抗溶性泡沫、砂土灭火。用水灭火无效，但可用水保持火场中容器冷却。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:43', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5053, 5188, '本品易燃，其蒸气与空气混合，能形成爆炸性混合物。遇明火、高热易引起燃烧爆炸。受热分解放出有毒的氧化氮烟气。与氧化剂能发生强烈反应。', '一氧化碳、二氧化碳、氧化氮。', '采用干粉、二氧化碳、抗溶性泡沫、砂土灭火。用水灭火无效，但可用水保持火场中容器冷却。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:43', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5054, 5189, '遇明火、高热可燃。受热分解，放出氮、磷的氧化物等毒性气体。在火场中，容器内压增大有开裂或爆炸的危险。', '一氧化碳、二氧化碳、氮氧化物、氧化磷。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5055, 5190, '可燃。含有机溶剂的液体制剂可能易燃。受热分解产生有毒的烟气。', '一氧化碳、二氧化碳、氧化磷、氧化氮等有毒气体', '抗溶性泡沫、干粉、砂土。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5056, 5191, '燃烧时产生白色的氧化砷烟雾。', '氧化砷。', '干粉、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5057, 5192, '受热分解产生有毒气体。', '砷化合物、汞化合物等有毒气体。', '干粉、二氧化碳或耐醇泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5058, 5193, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '砷化合物等有毒气体。', '干粉、二氧化碳、耐醇泡沫或水喷雾。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:46', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5059, 5194, '强还原剂。与空气混合能形成爆炸性混合物。遇明火、高热能引起燃烧爆炸。', '氧化砷。', '雾状水、泡沫、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5060, 5195, '受热分解产生有毒气体。', '砷化合物等有毒气体。', '干粉、二氧化碳或耐醇泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5061, 5196, '遇高热、明火会产生剧毒的蒸气。与金属接触会散发出剧毒的砷化氢。', '氧化砷。', '干粉、水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5062, 5197, '受热分解产生有毒的砷氧化物和氨气。受热或接触火焰可能会产生膨胀或爆炸性分解。本品不燃。', '砷氧化物、氨气等有毒烟雾', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5063, 5198, '受高热分解，放出高毒的烟气。遇明火、高热可燃。可能发生爆炸性分解。', '砷氧化物、氧化钡等有毒烟雾', '干粉、二氧化碳、泡沫。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:48', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5064, 5199, '受热分解产生有毒的砷氧化物烟雾。遇明火、高热可燃。与还原剂、金属粉末等可发生反应。', '砷氧化物、氧化钾、氮氧化物等有毒烟雾', '干粉、二氧化碳、泡沫。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5065, 5200, '受热分解产生有毒的砷氧化物烟雾。遇明火、高热可燃。与还原剂、金属粉末等可发生反应。', '砷氧化物、氧化钠、氮氧化物等有毒烟雾', '干粉、二氧化碳、泡沫。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5066, 5201, '受高热分解，放出高毒的烟气。遇明火、高热可燃。', '氧化砷、氧化钙等有毒烟雾', '干粉、二氧化碳、泡沫。消防人员必须穿全身防火防毒服，在上风向灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5067, 5202, '受高热分解，放出高毒的烟气。遇明火、高热可燃。', '汞、砷、氧化汞、氧化砷等有毒烟雾', '干粉、二氧化碳、泡沫。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5068, 5203, '受高热分解，放出高毒的砷氧化物和氧化镁烟气。本品不燃。', '砷氧化物、氧化镁等有毒烟雾', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5069, 5204, '受高热分解，放出高毒的烟气。遇明火、高热可燃。可能发生爆炸性分解。', '砷氧化物、氧化钠等有毒烟雾', '干粉、二氧化碳、泡沫。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5070, 5205, '不燃。受高热分解放出有毒的气体。', '氧化砷、氧化铅等有毒烟雾', '消防人员必须穿全身防火防毒服，在上风向灭火。灭火剂：干粉、水、砂土。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5071, 5206, '受高热分解，放出高毒的烟气。遇明火、高热可燃。', '氮氧化物、氧化砷、砷、氨等有毒烟雾', '干粉、二氧化碳、泡沫。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:51', '', NULL);
