INSERT INTO `msds_fire_fighting` VALUES (5076, 5211, '受高热分解，放出高毒的砷氧化物和氧化锌烟气。本品不燃。', '砷氧化物、氧化锌等有毒烟雾', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5077, 5212, '受热分解产生有毒的砷氧化物烟雾。遇明火、高热可燃。与还原剂、金属粉末等可发生反应。', '砷氧化物、氧化铁、氮氧化物等有毒烟雾', '干粉、二氧化碳、泡沫。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5078, 5213, '受热分解产生有毒的砷氧化物烟雾。本品不燃。', '砷氧化物等有毒烟雾', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5079, 5214, '比熟松香易燃，遇火种、高温、氧化剂有引起燃烧危险。', '一氧化碳、二氧化碳。', '灭火剂：干粉、二氧化碳、耐醇泡沫或水喷雾。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5080, 5215, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5081, 5216, '氢气体。遇潮时对大多数金属有腐蚀性。受高热分解产生有毒的腐蚀性烟气。', '一氧化碳、二氧化碳、氯化氢、氧化硅。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5082, 5217, '遇明火、高热可燃。与强氧化剂可发生反应。受高热分解产生有毒的腐蚀性气体。', '一氧化碳、二氧化碳、氯化氢。', '泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5083, 5218, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5084, 5219, '遇明火、高热可燃。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、硫化物、氧化钠。', '雾状水、二氧化碳、泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5085, 5220, '遇明火、高热易燃。受高热分解产生有毒的硫化物烟气。', '一氧化碳、二氧化碳、硫化氢、硫化物。', '采用干粉、泡沫、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5086, 5221, '遇明火、高热可燃。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、硫化物、氧化钠。', '雾状水、二氧化碳、泡沫、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:58', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5087, 5222, '遇明火、高热可燃。受高热分解产生有毒的腐蚀性烟气。对大多数金属有腐蚀性。', '一氧化碳、二氧化碳、氯化氢、氧化硅。', '干粉、二氧化碳或耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:58', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5088, 5223, '遇明火、高热可燃。与强氧化剂可发生反应。受高热分解产生有毒的腐蚀性气体。', '一氧化碳、二氧化碳、氯化氢。', '泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:58', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5089, 5224, '金属有腐蚀性。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氯化氢、氧化硅。', '抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:59', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5090, 5225, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳、耐醇泡沫或水喷雾。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:59', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5091, 5226, '下可生成具有潜在爆炸危险性的过氧化物。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、泡沫、干粉、二氧', '化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5092, 5227, '蚀性气体。受热分解，放出高毒的烟气。', '一氧化碳、二氧化碳、氯化氢、光气。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5093, 5228, '建规火险分级：丙类。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '溴化氢、一氧化碳、二氧化碳、含溴有机物', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5094, 5229, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、1211灭火剂、砂土。用水可引起沸溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5095, 5230, '未有特殊的燃烧爆炸特性。', '无资料', '不燃。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5096, 5231, '其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。用水灭火无效，但可用水保持火场中容器冷却。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5097, 5232, '极度易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂能发生强烈反应。高速冲击、流动、激荡后可因产生静电火花放电引起燃烧爆炸。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5098, 5233, '高浓度时有麻醉作用。如果吸入含有丁烷5%-6%的空气达30分钟，即稍现意志消沉、抑郁。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。', '一氧化碳、二氧化碳等有毒烟雾。', '消防人员必须佩戴隔绝式面具；如有可能应迅速将钢瓶转移至安全地带。灭火剂：雾状水、泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5099, 5234, '遇高热、明火有燃烧危险。能与氧化剂反应。遇热分解释出有毒的烟雾。吸入大量蒸气能引起神经症状。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。', '一氧化碳、二氧化碳、硫化物等有毒烟雾。', '用泡沫、二氧化碳、干粉、砂土灭火，小面积可用雾状水扑救。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5100, 5235, '其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。具有腐蚀性。', '一氧化碳、二氧化碳、氧化氮', '抗溶性泡沫、二氧化碳、干粉、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5101, 5236, '遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。若遇高热，容器内压增大，有 开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '二氧化碳、泡沫、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5102, 5237, '遇明火、高热可燃。受热分解产生有毒气体。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、苯甲酸、叔丁醇等', '使用干粉、二氧化碳、泡沫灭火器。切勿直接用水灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5103, 5238, '接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、醛类、酮类等有机物分解产物', '合适的灭火介质：泡沫、干粉、二氧化碳、砂土。不合适的灭火介质：避免直接用水流灭火，可能导致过氧化物加速分解。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5104, 5239, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、有机过氧化物分解产物', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:08', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5105, 5240, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、其他有害燃烧产物。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:10', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5106, 5241, '遇明火、高热可燃。受热分解产生有毒气体。与还原剂、酸类、碱类、易燃物、有机物等发生剧烈反应，有燃烧爆炸危险。摩擦、撞击或震动有爆炸危险。有机过氧化物本身不稳定，容易发生自加速分解，导致火灾或爆炸。在包装件中可发生热爆炸。接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、其他有毒烟雾。', '合适的灭火介质：泡沫、干粉、二氧化碳、砂土。禁止使用直流水。禁止使用酸碱灭火剂。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。切勿将水流直接射入熔融液体，以免引起严重的流淌火灾或剧烈的沸溅。容器突然发出异常声音或出现异常现象，应立即撤离。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:10', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5107, 5242, '地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5108, 5243, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5109, 5244, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。遇水反应发热放出有毒的腐蚀性气体。', '一氧化碳、二氧化碳、氯化氢、氧化硅。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5110, 5245, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:12', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5111, 5246, '接触火焰可能会产生膨胀或爆炸性分解。加热可能起火或爆炸。', '一氧化碳、二氧化碳及其他有毒气体', '合适的灭火介质：水雾、干粉、二氧化碳、泡沫。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:12', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5112, 5247, '接触火焰可能会产生膨胀或爆炸性分解。', '无资料', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:12', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5113, 5248, '接触火焰可能会产生膨胀或爆炸性分解。', '无资料', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:12', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5114, 5249, '爆炸的危险。', '一氧化碳，二氧化碳、氮氧化物。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:12', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5115, 5250, '遇明火、高热易燃。与氧化剂可发生反应。', '一氧化碳、二氧化碳、氧化钙', '干粉、二氧化碳、耐醇泡沫或水喷雾。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5116, 5251, '遇高热、明火或氧化剂，有引起燃烧的危险。暴露在空气中能自燃。沾染植物纤维（如棉花）会自燃。', '一氧化碳、二氧化碳、氧化钴等有毒气体', '采用泡沫、二氧化碳、干粉、砂土灭火。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5117, 5252, '遇高热、明火或氧化剂，有引起燃烧的危险。其粉体与空气混合，能形成爆炸性混合物。加热时，容器可能爆炸。', '一氧化碳、二氧化碳、氧化铝等', '采用泡沫、二氧化碳、干粉、砂土灭火。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5118, 5253, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。其粉体与空气混合，能形成爆炸性混合物。', '一氧化碳、二氧化碳、氧化锰。', '干粉、二氧化碳、耐醇泡沫或水喷雾。禁止使用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5119, 5254, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。其粉体与空气混合，能形成爆炸性混合物。', '一氧化碳、二氧化碳、氧化锌。', '干粉、二氧化碳、耐醇泡沫或水喷雾。禁止使用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5120, 5255, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。受高热分解放出有毒的气体。', '一氧化碳、氟化氢、氧化磷、磷烷。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5121, 5256, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、氯化氢。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5122, 5257, '受热分解，放出氮、硫的氧化物等毒性气体。', '一氧化碳、二氧化碳、硫化物、氧化氮。', '雾状水、二氧化碳、泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5123, 5258, '遇明火、高热可燃。受高热分解，放出有毒的氮、磷氧化物和氟化物气体。', '一氧化碳、二氧化碳、氧化氮、氧化磷、氟化氢。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5124, 5259, '接触火焰可能会产生膨胀或爆炸性分解。遇明火、高热可燃。受热分解产生有毒气体。', '一氧化碳、二氧化碳、氮氧化物', '合适的灭火介质：水、泡沫、二氧化碳、干粉。不合适的灭火介质：禁止使用直流水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:17', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5125, 5260, '接触火焰可能会产生膨胀或爆炸性分解。受热分解产生有毒气体。强氧化剂，遇可燃物、还原剂、有机物等有燃烧爆炸危险。', '一氧化碳、二氧化碳、氧化硫、氧化氮、硫化物等有毒有害气体。', '合适的灭火介质：使用大量水灭火。也可使用干粉、二氧化碳灭火剂。不合适的灭火介质：禁止使用直流水冲击，禁止使用泡沫灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5126, 5261, '放出大量热量而引起容器破裂和爆炸事故。', '一氧化碳、二氧化碳。', '喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：泡沫、干粉、二氧化碳、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5127, 5262, '遇明火、高热可燃。具有强还原性。与氧化剂能发生强烈反应，引起燃烧或爆炸。遇氧化汞、金属钠、氯化亚锡、2,4-二硝基氯化苯剧烈反应。', '氮氧化物、氨气。', '遇大火，消防人员须在有防护掩蔽处操作。用水喷射逸出液体，使其稀释成不燃性混合物，并用雾状水保护消防人员。灭火剂：雾状水、抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5128, 5263, '遇高热、明火及强氧化剂易引起燃烧并放出有毒气体。', '一氧化碳、二氧化碳。', '采用雾状水、泡沫、二氧化碳、干粉、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5129, 5264, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:20', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5130, 5265, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。受热分解或爆炸性分解。', '一氧化碳、二氧化碳、氮氧化物、汞蒸气等有毒气体。合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:20', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5131, 5266, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。受热分解或爆炸性分解。', '一氧化碳、二氧化碳、氮氧化物等有毒气体。合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:20', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5132, 5267, '遇高热，明火或与氧化剂接触，有引起燃烧的危险。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '雾状水、二氧化碳、泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:20', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5133, 5268, '遇高热、明火或与氧化剂接触，有引起燃烧的危险，燃烧分解时，放出有毒的氮氧化物。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5134, 5269, '建规火险分级：', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5135, 5270, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、锡、氧化锡。', '雾状水、抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:22', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5136, 5271, '本身不燃烧，但遇高热能放出有毒的烟气。遇氰化物能产生剧毒的氰化氢气体。遇Ｈ发泡剂 立即燃烧。具有腐蚀性。', '碘化氢、氧化锡。', '灭火剂：干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:22', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5137, 5272, '与酸类发生剧烈反应。具有强腐蚀性。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、氨。', '不燃。火场周围可用的灭火介质。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:22', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5138, 5273, '遇酸反应产生热和烟雾。受热分解产生有毒气体。', '磷氧化物、一氧化碳、二氧化碳', '干粉、二氧化碳或耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:22', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5139, 5274, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氧化锡、锡。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:24', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5140, 5275, '对热、光、空气十分敏感的不稳定爆炸性气体，在容器中受压可发生爆炸。与碳氢化合物、 氢气、有机物、还原剂、氧气能发生爆炸性的反应。', '氮氧化物、氟化氢。', '切断气源。若不能立即切断气源，则不允许熄灭正在燃烧的气体，喷水冷却容器，可能的 话将容器从火场移至空旷处。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:24', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5141, 5276, '在潮湿空气中产生白色有腐蚀性和刺激性的氟化氢烟雾。遇水剧烈反应，生成硅酸及氟化氢。', '氟化氢。', '消防人员必须穿全身防火防毒服，在上风向灭火。切断气源。喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:24', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5142, 5277, '遇水或水蒸气、酸或酸气产生剧毒的烟气。腐蚀性很强，可腐蚀玻璃和大多数金属。', '氟化氢、氧化硫。', '切断气源。喷水冷却容器，可能的话将容器从火场移至空旷处。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:24', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5143, 5278, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '氟化氢、氧化铅', '用大量水灭火。用雾状水驱散烟雾与刺激性气体。或使用二氧化碳、沙粒、灭火粉末灭火。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5144, 5279, '受高热、明火会产生剧毒的蒸气。具有强腐蚀性。', '氟化氢、氧化铀。', '二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5145, 5280, '不燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '氟化氢。', '本品不燃。切断气源。喷水冷却容器，可能的话将容器从火场移至空旷处。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5146, 5281, '火焰都可能引起火灾和爆炸。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀 或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5147, 5282, '气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。受热可发生聚合反应，放出大量热量，有爆炸危险。容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氟化氢。 切断气源。若不能切断气源，则不允许熄灭泄漏处的火焰。喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、普通泡沫、干粉、二氧化碳。', '灭火剂：雾状水、普通泡沫、干粉、二氧化碳。尽可能将容器从火场移至空旷处。喷水冷却容器，直至火灾结束。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5148, 5283, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、氧化铅。', '水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5149, 5284, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。其蒸气比空气重，能在较低处扩散到 相当远的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氧化锡。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5150, 5285, '易燃液体和蒸气。蒸气可能会移动到着火源并回闪。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳', '干粉、二氧化碳或耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5151, 5286, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氧化磷。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5152, 5287, '受高热分解产生有毒的腐蚀性烟气。', '一氧化碳、二氧化碳、氯化氢、光气。 消防人员须佩戴氧气呼吸器。喷水保持火场容器冷却，直至灭火结束。灭火剂：雾状水、泡沫、', '干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5153, 5288, '遇水或水蒸气反应发热放出有毒的腐蚀性气体。受高热分解，放出高毒的烟气。', '氯化氢、碲。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5154, 5289, '建规火险分级：', '灭火方法： 使用干粉、二氧化碳灭火剂；用水冷却暴露在火中的容器，严禁容器进水', '使用干粉、二氧化碳灭火剂；用水冷却暴露在火中的容器，严禁容器进水', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5155, 5290, '受热或遇水分解放热, 放出有毒的腐蚀性烟气。对金属有强腐蚀性。', '氯化氢。', '消防人员必须穿全身耐酸碱消防服。灭火剂：干燥砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5156, 5291, '受热或遇水分解放热, 放出有毒的腐蚀性烟气。对很多金属尤其是潮湿空气存在下有腐蚀性。', '氯化氢、氧化硅。', '消防人员必须穿全身耐酸碱消防服。灭火剂：干燥砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5157, 5292, '遇水或水蒸气反应发热放出有毒的腐蚀性气体。遇潮时对大多数金属有腐蚀性。受高热分 解，放出有毒的烟气。', '氯化氢、氧化硫。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5158, 5293, '受高热发生剧烈分解，甚至发生爆炸。遇水反应发热放出有毒的腐蚀性气体。', '氯化物、氧化铅。', '砂土、干粉、二氧化碳、泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5159, 5294, '受热或遇水分解放热, 放出有毒的腐蚀性烟气。具有较强的腐蚀性。', '氯化物、氧化钛。', '消防人员必须穿全身耐酸碱消防服。灭火剂：干燥砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5160, 5295, '遇水或潮湿空气分解产生氯化氢和硒化合物，释放出有毒烟雾。受热分解产生有毒的硒氧化物和氯化物烟雾。遇水反应剧烈，可能产生爆炸性分解。', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用水直接灭火，因为它可能会使火苗蔓延分散并产生有毒烟雾。', '灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5161, 5296, '近似白色烟雾状有刺激性和腐蚀性的氯化氢气体。具有腐蚀性。', '氯化物。', '灭火剂：干粉、二氧化碳。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5162, 5297, '建规火险分级：无意义（本身不燃）', '氯化氢、氧化锡', '干粉、二氧化碳或耐醇泡沫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5163, 5298, '受热分解产生有毒的氯化物气体。具有强腐蚀性，与水反应产生盐酸和氧化锗沉淀。', '氯化物。', '灭火剂：干燥砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:32', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5164, 5299, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:32', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5165, 5300, '火焰都可能引起火灾和爆炸。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀 或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳、耐醇泡沫或水喷雾。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:32', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5166, 5301, '一般不会燃烧, 但长时间暴露在明火及高温下仍能燃烧。受高热分解产生有毒的腐蚀性烟气。', '氯化氢、光气。 消防人员须佩戴氧气呼吸器。喷水保持火场容器冷却，直至灭火结束。灭火剂：雾状水、泡', '沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:32', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5167, 5302, '遇明火、高热易燃。与强氧化剂如铬酸酐、氯酸钾和高锰酸钾等接触，能发生强烈的反应，引 起燃烧或爆炸。受热分解放出有毒的氧化氮烟气。', '一氧化碳、二氧化碳、氧化氮。', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:32', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5168, 5303, '其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器 内压增大，有开裂和爆炸的危险。接触空气或在光照条件下可生成具有潜在爆炸危险性的 过氧化物。与酸类物质能发生剧烈反应。', '一氧化碳、二氧化碳。', '抗溶性泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5169, 5304, '极易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂能发生强烈反应。在火场中，受热的容器有爆炸危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳', '尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的容器若已变色或从安全泄压装置中产生声音，必须马上撤离。用抗溶性泡沫、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5170, 5305, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。若遇高热，容器内压增大，有开裂和 爆炸的危险。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、二氧化碳、干粉、抗溶性泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5171, 5306, '会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5172, 5307, '遇高热、明火及强氧化剂易引起燃烧。', '一氧化碳、二氧化碳、硫化氢、氧化硫。', '喷水冷却容器，可能的话将容器从火场移至空旷处。泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5173, 5308, '的烟气。', '一氧化碳、二氧化碳、氰化物、氮氧化物。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5174, 5309, '能增加爆炸敏感性。能与可燃物、有机物或易氧化物质形成爆炸性混合物，经摩擦和与少 量水接触可导致燃烧或爆炸。', '一氧化碳、二氧化碳、氧化氮。', '雾状水、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5175, 5310, '分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、泡沫。禁止用砂土压盖。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5176, 5311, '遇明火、高热可燃。受热分解产生有毒的溴化氢气体。', '溴化氢、一氧化碳、二氧化碳、溴化物。', '干粉、二氧化碳、耐醇泡沫、水喷雾。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5177, 5312, '受高热分解产生有毒的溴化物气体。本品不燃，但遇高热会分解产生有毒气体。', '溴化氢、一氧化碳、二氧化碳等有毒气体。', '雾状水、泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:36', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5178, 5313, '吸潮或遇水会产生大量的腐蚀性烟雾。在空气中强烈发烟。', '溴化氢、氧化硒。', '消防人员必须穿全身耐酸碱消防服。灭火剂：干粉、二氧化碳、干燥砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:37', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5179, 5314, '遇明火、高热可燃。受热分解产生有毒的氮氧化物烟雾。与氧化剂可发生反应。具有腐蚀性，遇水或水蒸气反应产生有毒和腐蚀性烟雾。', '一氧化碳、二氧化碳、氮氧化物、氨等有毒气体。', '泡沫、干粉、二氧化碳、砂土。禁止用水、酸碱灭火器。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:37', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5180, 5315, '具有强氧化性。与易燃物、有机物接触易着火燃烧。受热分解产生有毒的烟气。', '可能产生有害的毒性烟雾。', '不燃，火场周围可用的灭火介质。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:37', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5181, 5316, '压力安全阀泄漏出内容物。受热或接触火焰可能会产生膨胀或爆炸性分解。', '无资料', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5182, 5317, '受高热分解放出有毒的气体。', '氧化铅。', '采用水、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5183, 5318, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氧化磷、磷化氢。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5184, 5319, '遇高热、明火有引起燃烧的危险。加热分解产生毒性气体。与氧化剂接触猛烈反应。', '一氧化碳、二氧化碳、氧化铅。 消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：雾状水、泡沫、二氧化碳、', '砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5185, 5320, '与酸类发生剧烈反应。具有强腐蚀性。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、氨。', '不燃。火场周围可用的灭火介质。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5186, 5321, '受热时可能会释放毒性烟雾。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '干粉、二氧化碳或耐醇泡沫', '避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:39', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5187, 5322, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。通过打击、摩擦、火灾或其他着火源有爆炸危险。', '一氧化碳、二氧化碳、氮氧化物', '干粉、二氧化碳或耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5188, 5323, '易燃，其蒸气与空气混合，能形成爆炸性混合物。受热分解产生有毒的烟气。加热时，容器可能爆炸。', '一氧化碳、二氧化碳等有毒气体', '干粉、二氧化碳、砂土。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5189, 5324, '易燃，其蒸气与空气混合，能形成爆炸性混合物。受热分解产生有毒的烟气。遇明火、高热可燃。与硝酸发生剧烈反应或立即燃烧。', '一氧化碳、二氧化碳。', '采用泡沫、二氧化碳、干粉、砂土灭火。用水灭火无效，但可用水保持火场中容器冷却。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5190, 5325, '易燃，其蒸气与空气混合，能形成爆炸性混合物。受热分解产生有毒的烟气。遇明火、高热可燃。蒸气可能会移动到着火源并回闪。液体和蒸气易燃。加热时，容器可能爆炸。', '一氧化碳、二氧化碳等有毒气体', '采用泡沫、二氧化碳、干粉、砂土灭火。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5191, 5326, '易燃，其蒸气与空气混合，能形成爆炸性混合物。受热分解产生有毒的烟气。遇明火、高热可燃。', '一氧化碳、二氧化碳等有毒气体', '干粉、二氧化碳、砂土。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5192, 5327, '易燃，其蒸气与空气混合，能形成爆炸性混合物。受热分解产生有毒的烟气。', '一氧化碳、二氧化碳等有毒气体', '干粉、二氧化碳、砂土。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5193, 5328, '爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5194, 5329, '微细粉末遇热源和明火有燃烧爆炸的危险。与氧剧烈反应。暴露在空气中会被氧化而变质。', '可能产生有害的毒性烟雾。', '消防人员必须穿全身防火防毒服，在上风向灭火。灭火剂：二氧化碳、干燥砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5195, 5330, '毒和易燃的气体。在火场中，受热的容器有爆炸危险。', '一氧化碳、二氧化碳、氧化钛。', '采用二氧化碳、干粉、砂土灭火。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5196, 5331, '毒和易燃的气体。在火场中，受热的容器有爆炸危险。', '一氧化碳、二氧化碳、氧化钛。', '采用二氧化碳、干粉、砂土灭火。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5197, 5332, '爆炸危险。', '一氧化碳、二氧化碳、氧化钛。', '采用干粉、二氧化碳、砂土灭火。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:43', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5198, 5333, '可发生爆炸性灾害。与酸类物质能发生剧烈反应。', '乙炔、一氧化碳、二氧化碳。', '禁止用水和泡沫灭火。二氧化碳也无效。须用干燥石墨粉或其它干粉灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:43', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5199, 5334, '生剧烈反应。', '一氧化碳、二氧化碳、氧化铝。', '禁止用水和泡沫灭火。灭火剂：干粉、干燥砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:43', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5200, 5335, '未有特殊的燃烧爆炸特性。', '一氧化碳、二氧化碳、氧化钡。', '本品不燃。灭火剂：水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:43', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5201, 5336, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:44', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5202, 5337, '方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：泡沫、干粉、二氧化碳、砂 土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:44', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5203, 5338, '易燃，遇明火、高热易燃。在火场中，受热的容器有爆炸危险。', '一氧化碳、二氧化碳。', '砂土。泡沫、干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:44', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5204, 5339, '方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：泡沫、干粉、二氧化碳、砂 土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:44', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5205, 5340, '受高热分解，放出高毒的烟气。', '一氧化碳、二氧化碳、氧化铍。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:44', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5206, 5341, '受高热分解，放出高毒的烟气。', '一氧化碳、二氧化碳。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5207, 5342, '而增加火势和/或蒸气的浓度。蒸气可能会移动到着火源并回闪。液体和蒸气易燃。加热 时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:46', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5208, 5343, '不燃。化学反应活性较高，遇水后有强烈腐蚀性。', '氯化氢。 本品不燃。消防人员必须佩戴过滤式防毒面具(全面罩)或隔离式呼吸器、穿全身防火防毒服，在 上风向灭火。切断气源。喷水冷却容器，可能的话将容器从火场移至空旷处。万一有', '光气漏逸，微量时可用水蒸气冲散，较大时，可用液氨喷雾冲洗。灭火剂：雾状水、干粉、二氧 化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:46', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5209, 5344, '在水中分解放出剧毒的腐蚀性气体。具有强腐蚀性。', '一氧化碳、氟化氢。', '切断气源。喷水冷却容器，可能的话将容器从火场移至空旷处。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:46', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5210, 5345, '应。遇水或水蒸气反应放出有毒的或易燃的气体。', '一氧化碳、硫化氢、氧化硫。 切断气源。若不能立即切断气源，则不允许熄灭正在燃烧的气体，喷水冷却容器，可能的', '话将容器从火场移至空旷处。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:46', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5211, 5346, '引起燃烧爆炸。', '一氧化碳。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5212, 5347, '遇明火、高热可燃。粉体与空气可形成爆炸性混合物，当达到一定浓度时，遇火星会发生爆炸。', '氧化锑。', '采用干粉、干砂灭火。禁止用二氧化碳和酸碱灭火剂灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5213, 5348, '氢气和金属锑。与氧化剂、氯气、硝酸、臭氧、氨剧烈反应。', '氧化锑。 消防人员必须佩戴过滤式防毒面具(全面罩)或隔离式呼吸器、穿全身防火防毒服，在上风向灭火。', '切断气源。若不能切断气源，则不允许熄灭泄漏处的火焰。喷水冷却容器，可能的话将容器从火 场移至空旷处。灭火剂：雾状水、泡沫、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5214, 5349, '遇明火、高热可燃。受热分解产生有毒的氯化氢、二氧化硫等气体。', '一氧化碳、二氧化碳、氯化氢、二氧化硫等有毒气体。', '雾状水、泡沫、二氧化碳、干粉、砂土。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5215, 5350, '极端易燃气体，遇明火、高热极易燃烧爆炸。高压压缩气体，遇热有爆炸危险。加热时，容器可能爆炸。暴露于火中的容器可能会通过压力安全阀泄漏出内容物。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、氮氧化物等有毒气体。', '合适的灭火介质：切断气源。若不能切断气源，则允许将火熄灭。雾状水、泡沫、二氧化碳、干粉、砂土。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5216, 5351, '爆炸的危险。', '一氧化碳、二氧化碳。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:48', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5217, 5352, '而增加火势和/或蒸气的浓度。蒸气可能会移动到着火源并回闪。液体和蒸气易燃。加热 时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5218, 5353, '都可能引起火灾和爆炸。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸 性分解。', '合适的灭火介质:干粉、二氧化碳、耐醇泡沫或水喷雾。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5219, 5354, '能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5220, 5355, '爆炸性分解。遇明火、高热可燃。受热分解产生有毒的烟雾。', '一氧化碳、二氧化碳、其他有毒烟雾', '干粉、二氧化碳或耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:50', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5221, 5356, '其粉体遇高温、明火能燃烧。与卤素、硫、磷等发生剧烈的化学反应，引起燃烧。', '无资料', '干粉、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:50', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5222, 5357, '遇明火、高热可燃。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:50', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5223, 5358, '爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5224, 5359, '以上能和液体石蜡发生剧烈反应。受高热分解，放出高毒的氟化物烟气。', '氟化氢。', '不燃。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5225, 5360, '烟雾。接触酸或酸气能产生有毒气体。', '氟化氢、碘化氢。', '不燃。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:52', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5226, 5361, '体。遇碱分解。', '氧化磷、磷烷、氟化氢。 消防人员必须穿全身防火防毒服，在上风向灭火。切断气源。喷水冷却容器，可能的话将容器从', '火场移至空旷处。灭火剂：干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:52', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5227, 5362, '受高热分解，放出高毒的烟气。遇潮时对大多数金属有腐蚀性。', '氯化氢、氟化氢、氯化物、氟化物。', '小火可用干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:52', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5228, 5363, '受热或遇水分解放热，放出有毒的腐蚀性烟气。有腐蚀性。', '氟化氢、氧化锑。', '砂土、干粉。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:52', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5229, 5364, '甲烷、石蜡、氯甲烷等)接触发生爆炸或燃烧。与酸、卤素、非金属、金属卤化物、金 属、氧、水发生强烈反应，并引起燃烧。具有强腐蚀性。受高热分解，放出高毒的烟 气。', '溴化氢、氟化氢。', '二氧化碳、干粉。不宜用水。用水冷却火场容器。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:52', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5230, 5365, '而增加火势和/或蒸气的浓度。蒸气可能会移动到着火源并回闪。液体和蒸气易燃。加热 时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5231, 5366, '氯酸盐、硝酸盐、高氯酸盐或高猛酸盐等组成敏感度极高的爆炸性混合物。遇水或潮湿空 气分解成有腐蚀和刺激作用的磷酸及硫化氢气体。', '氧化磷、磷烷、硫化氢、氧化硫。', '消防人员必须穿全身防火防毒服，在上风向灭火。灭火剂：二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:54', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5232, 5367, '可形成爆炸性混合物，当达到一定的浓度时，遇火星会发生爆炸。', '氧化硫、硫化氢、氧化锑。', '水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:54', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5233, 5368, '都可能引起火灾和爆炸。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸 性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:54', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5234, 5369, '一般不会燃烧，但长时间暴露在明火及高温下仍能燃烧。受高热分解产生有毒的腐蚀性气体。', '一氧化碳、二氧化碳、氯化氢。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:54', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5235, 5370, '爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5236, 5371, '受高热分解产生有毒的腐蚀性烟气。', '一氧化碳、二氧化碳、氯化氢、光气。', '泡沫、二氧化碳、1211灭火剂、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5237, 5372, '受高热分解，放出腐蚀性、刺激性的烟雾。', '氧化钠、氯化氢', '泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5238, 5373, '遇水发热、冒烟甚至燃烧爆炸。与易燃物（如苯）和可燃物（如糖、纤维素等）接触会发生剧 烈反应，甚至引起燃烧。具有较强的腐蚀性。', '氯化氢、氧化磷、磷烷。', '消防人员必须穿全身耐酸碱消防服。灭火剂：干粉、二氧化碳、干燥砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5239, 5374, '与水发生剧烈反应，放出近似白色烟雾状有毒和腐蚀性的氯化氢气体。潮湿时会腐蚀金属。', '氯化氢。', '消防人员必须穿全身耐酸碱消防服。灭火剂：二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:56', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5240, 5375, '吸潮或遇水会产生大量的腐蚀性烟雾。具有强腐蚀性。', '氯化氢。', '不燃。火场周围可用的灭火介质。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5241, 5376, '本身不燃烧，但遇高热能放出有毒的烟气。', '氯化氢。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5242, 5377, '受热或遇水分解放热, 放出有毒的腐蚀性烟气。对很多金属尤其是潮湿空气存在下有腐蚀性。', '氯化物、氧化锑。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。用雾状水保持火场中容器冷却。灭 火剂：干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5243, 5378, '遇明火、高热可燃。受高热分解产生有毒的腐蚀性烟气。', '一氧化碳、二氧化碳、氯化氢。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5244, 5379, '遇明火、高热可燃。与强氧化剂可发生反应。受高热分解，产生有毒的氮氧化物和氯化物气体。', '一氧化碳、二氧化碳、氧化氮、氯化氢。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:58', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5245, 5380, '水蒸气能产生热和有毒的腐蚀性烟雾。', '一氧化碳、二氧化碳、氯化氢。 消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。喷水保持火场容器冷却，直至灭火', '结束。灭火剂：雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:58', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5246, 5381, '爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:58', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5247, 5382, '气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。与锌及过渡族金属 卤化物一起发生剧烈反应。', '一氧化碳、二氧化碳、氧化铁。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:58', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5248, 5383, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:58', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5249, 5384, '受热或遇水分解放热, 放出有毒的腐蚀性烟气。对很多金属尤其是潮湿空气存在下有腐蚀性。', '溴化氢、氧化磷。', '消防人员必须穿全身耐酸碱消防服。灭火剂：干粉、砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:59', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5250, 5385, '发生爆炸的危险。', '氧化氮。', '雾状水、泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5251, 5386, '加强并让火焰自身维持。灭火行动对已发生的火灾可能无效。遇火会产生刺激性、毒性或 腐蚀性的气体。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '灭火方法： 合适的灭火介质：水。不合适的灭火介质：干粉、二氧化碳或泡沫。', '合适的灭火介质：水。不合适的灭火介质：干粉、二氧化碳或泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5252, 5387, '未有特殊的燃烧爆炸特性。', '可能产生有害的毒性烟雾。', '不燃。火场周围可用的灭火介质。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5253, 5388, '接触有机物有引起燃烧的危险。受热或遇水分解放热, 放出有毒的腐蚀性烟气。具有强腐蚀性。', '氧化磷。', '消防人员必须穿全身耐酸碱消防服。灭火剂：干粉、砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5254, 5389, '遇高热、明火会产生剧毒的蒸气。', '氧化砷。', '消防人员必须穿全身防火防毒服，在上风向灭火。灭火剂：干粉、水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5255, 5390, '弱氧化剂。与还原剂能发生反应。', '氧化锑。', '采用水、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5256, 5391, '遇明火能燃烧。受高热或与酸接触会产生剧毒的氰化物气体。', '一氧化碳、二氧化碳、氮氧化物、氰化氢', '采用抗溶性泡沫、干粉、二氧化碳、砂土灭火。禁止使用酸碱灭火剂。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5257, 5392, '遇明火、高热可燃。受热分解产生有毒气体。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳', '雾状水、抗溶性泡沫、二氧化碳、干粉、水。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5258, 5393, '一定的浓度时，遇火星会发生爆炸。', '一氧化碳、二氧化碳', '雾状水、泡沫、二氧化碳、干粉、砂土。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5259, 5394, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。吸潮或遇水会产生大量的腐蚀性烟雾。', '一氧化碳、二氧化碳、氯化氢、氧化硅', '泡沫、二氧化碳、干粉、砂土。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5260, 5395, '遇明火、高热易燃。其蒸气与空气混合，能形成爆炸性混合物。受热分解产生有毒的氰化物气体。', '一氧化碳、二氧化碳、氮氧化物、氰化物', '泡沫、干粉、二氧化碳、砂土。禁止使用酸碱灭火剂。喷水冷却容器，可能的话将容器从火场移至空旷处。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5261, 5396, '剧烈分解，引起容器破裂或爆炸事故。与强氧化剂如铬酸酐、氯酸盐和高锰酸钾等接触，能发生强烈反应，引起燃烧或爆炸。与水和水蒸气反应，放出易爆炸着火的氢气。', '氧化硼、硼的氧化物', '采用干粉、二氧化碳、干砂灭火。禁止用水和泡沫灭火。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5262, 5397, '遇明火、高热易燃。其蒸气与空气可形成爆炸性混合物。受热分解，放出烟气。', '一氧化碳、二氧化碳', '泡沫、干粉、二氧化碳、砂土。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5263, 5398, '遇明火、高热易燃。其蒸气与空气可形成爆炸性混合物。受热分解，放出烟气。', '一氧化碳、二氧化碳', '泡沫、干粉、二氧化碳、砂土。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5264, 5399, '遇明火、高热易燃。受热分解，放出高毒的氯化氢、光气等烟气。其蒸气与空气可形成爆炸性混合物。', '一氧化碳、二氧化碳、氯化氢、光气', '二氧化碳、干粉、砂土。禁止用水、泡沫。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5265, 5400, '遇明火、高热可燃。与强氧化剂可发生反应。受热分解放出有毒的氧化氮烟气。', '一氧化碳、二氧化碳、氧化氮。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5266, 5401, '在高温下可燃烧。受热分解产生有毒气体。', '氧化硒、二氧化硒等有毒气体。', '雾状水、干粉、砂土。禁止使用强水流冲击。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5267, 5402, '受热或遇酸能产生剧毒的硒化氢气体。', '硒、氧化硒、氧化镉等有毒烟雾', '消防人员必须穿全身防火防毒服，在上风向灭火。灭火剂：二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5268, 5403, '遇明火、高热可燃。受热分解产生有毒的铅化合物和硒化物烟雾。', '氧化铅、硒化物等有毒烟雾。', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5269, 5404, '与空气混合能形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。', '氧化硒、二氧化硒等有毒气体。', '切断气源。若不能立即切断气源，则不允许熄灭正在燃烧的气体。喷水冷却容器，尽可能将容器从火场移至空旷处。雾状水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:07', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5270, 5405, '遇明火、高热可燃。受热分解产生有毒的硒化物和氧化硒烟雾。', '氧化硒、硒化物等有毒烟雾。', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:07', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5271, 5406, '遇稀硝酸分解放出剧毒的硒化氢气体。', '硒、氧化硒、氧化锌等有毒烟雾。', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:07', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5272, 5407, '受热分解产生有毒烟雾。', '氧化硒、氮氧化物等有毒烟雾。', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:07', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5273, 5408, '具有强氧化性。其水溶液有腐蚀性和强烈的刺激性。与有机物、还原剂、易燃物如硫、磷等接触有燃烧爆炸危险。', '氧化硒、二氧化硒等有毒烟雾。', '消防人员必须穿全身耐酸碱消防服。灭火剂：雾状水、砂土。禁止使用直流水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5274, 5409, '不燃，受高热分解时会释放有毒烟气。燃烧（分解）产物包括氧化硒、二氧化硒、氧化钡等有毒烟雾。', '氧化硒、二氧化硒、氧化钡等有毒烟雾。', '根据周围环境选择合适的灭火剂。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5275, 5410, '受高热分解，放出有毒的烟气。', '硒、氧化钾。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5276, 5411, '不燃，受高热分解时会释放有毒烟气。燃烧（分解）产物包括氧化硒、二氧化硒等有毒烟雾。', '氧化硒、二氧化硒等有毒烟雾。', '根据周围环境选择合适的灭火剂。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5277, 5412, '不燃，受高热分解时会释放有毒烟气。燃烧（分解）产物包括氧化硒、二氧化硒、氧化铜等有毒烟雾。', '氧化硒、二氧化硒、氧化铜等有毒烟雾。', '根据周围环境选择合适的灭火剂。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:10', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5278, 5413, '易燃。遇明火、高热有燃烧爆炸的危险。受热分解产生有毒的氯化物烟雾。遇水或水蒸气反应产生氯化氢气体，具有强腐蚀性。', '一氧化碳、二氧化碳、氯化氢、氯气。', '灭火剂：干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:10', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5279, 5414, '易燃。遇明火、高热有燃烧爆炸的危险。受热分解产生有毒气体。若遇高热，容器内压增大，有开裂和爆炸的危险。可能形成爆炸性的过氧化物。', '一氧化碳、二氧化碳。', '灭火剂：干粉、二氧化碳、耐醇泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5280, 5415, '若遇高热，容器内压增大，有开裂和爆炸的危险。', '无资料', '本品不燃。切断气源。喷水冷却容器，可能的话将容器从火场移至空旷处。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5281, 5416, '接触火焰可能会产生膨胀或爆炸性分解。遇明火、高热有引起燃烧爆炸的危险。加热时，容器可能爆炸。', '一氧化碳、二氧化碳、氮氧化物等有毒气体。', '干粉、二氧化碳、耐醇泡沫或水喷雾', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5282, 5417, '撞击、摩擦，遇明火、高热时，均有引起爆炸的危险。与强酸接触能发生强烈反应，引起燃烧或爆炸。加热时，容器可能爆炸。', '氧化氮、二氧化碳、一氧化碳等有毒气体。', '雾状水、泡沫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:12', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5283, 5418, '能产生膨胀或爆炸性分解。遇有机物、还原剂等易燃物可发生剧烈反应，甚至爆炸。', '氮氧化物、硫氧化物等有毒气体', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:12', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5284, 5419, '强烈反应，引起燃烧或爆炸。通常加乙醇、丙酮或水作润湿剂，润湿剂干燥后，容易发生 火灾。', '一氧化碳、二氧化碳、氮氧化物。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷 处。灭火剂：雾状水、二氧化碳、泡沫。禁用砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:12', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5285, 5420, '遇明火、高热极易燃烧。燃速很快。与氧化剂接触发生强烈反应，甚至引起燃烧。久储会逐渐发热，若积热不散会引起自燃。其粉体化学活性很高，在空气中能自燃。', '一氧化碳、二氧化碳、氮氧化物等有毒气体。', '使用雾状水、二氧化碳、泡沫、干粉、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5286, 5421, '遇明火、高热可燃。与硝酸反应强烈。', '一氧化碳、二氧化碳、氧化氮。', '合适的灭火介质：雾状水、抗溶性泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:15', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5287, 5422, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。震动撞击时可发生爆炸。受热分解产生有毒的氮氧化物。', '一氧化碳、二氧化碳、氮氧化物。', '灭火剂：干粉、砂土、雾状水、泡沫、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:15', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5288, 5423, '受热、接触明火、或受到摩擦、震动、撞击时可发生爆炸。受高热分解，产生有毒的氮氧化物。', '氮氧化物。', '必须在安全距离以外施救。灭火剂：雾状水、泡沫。禁止用砂土压盖。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:15', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5289, 5424, '胺类及三氯化铝、六甲基苯等均能引起燃烧爆炸。燃烧分解时，放出有毒的氮氧化物气体。', '一氧化碳、二氧化碳、氮氧化物。', '使用雾状水、泡沫、二氧化碳、干粉、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:15', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5290, 5425, '受热可能发生爆炸性分解。遇明火、高热可燃。', '受热分解产生一氧化碳、二氧化碳、氮氧化物等有毒气体。', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5291, 5426, '通过打击、摩擦、火灾或其他着火源有极大爆炸危险。受热分解产生有毒的氮氧化物。', '氮氧化物。', '灭火剂：雾状水、泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5292, 5427, '安全阀泄漏出内容物。受热或接触火焰可能会产生膨胀或爆炸性分解。遇明火、高热可燃。受热分解产生有毒气体。', '一氧化碳、二氧化碳、氟化氢、氮氧化物等有毒气体。', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5293, 5428, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。遇明火、高热有引起燃烧爆炸的危险。', '一氧化碳、二氧化碳、氮氧化物等有毒气体。', '合适的灭火介质：干粉、二氧化碳、耐醇泡沫或水喷雾。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5294, 5429, '受热分解产生有毒气体。遇金属反应可能产生易燃气体。', '一氧化碳、二氧化碳、氮氧化物等有毒气体。', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:16', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5295, 5430, '胺类及三氯化铝、六甲基苯等均能引起燃烧爆炸。燃烧分解时，放出有毒的氮氧化物气体。遇明火、高热可燃。受热分解产生有毒气体。', '一氧化碳、二氧化碳、氧化氮。', '合适的灭火介质：雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:17', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5296, 5431, '与还原剂、可燃物如糖、纤维素、木屑、棉花、稻草或废纱头等接触，引起燃烧并散发出剧毒的棕色烟雾。具有强腐蚀性。', '氧化氮。', '消防人员必须穿全身耐酸碱消防服。灭火剂：雾状水、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5297, 5432, '强氧化剂。受强烈震动也会起爆。急剧加热时可发生爆炸。与还原剂、有机物、易燃物如硫、磷或金属粉末等混合可形成爆炸性混合物。', '氮氧化物', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。切勿将水流直接射至熔融物，以免引起严重的流淌火灾或引起剧烈的沸溅。遇大火，消防人员须在有防护掩蔽处操作。灭火剂：水、雾状水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5298, 5433, '高温时分解，释出剧毒的氮氧化物气体。', '氮氧化物。', '雾状水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5299, 5434, '与可燃物、还原剂等混合可形成爆炸性混合物。燃烧分解时，放出有毒的氮氧化物气体。', '氮氧化物。', '雾状水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5300, 5435, '遇明火、高热可燃。受热分解，放出有毒的氮氧化物气体。有燃烧爆炸的危险。', '一氧化碳、二氧化碳、氮氧化物。', '干粉、二氧化碳或耐醇泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5301, 5436, '遇明火、高热可燃。受高热分解，放出高毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、汞。', '干粉、二氧化碳或耐醇泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:20', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5302, 5437, '无机氧化剂。与还原剂、有机物、易燃物如硫、磷或金属粉末等混合可形成爆炸性混合物。', '氮氧化物。', '雾状水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5303, 5438, '遇明火、高热可燃。受热分解产生有毒气体。与可燃物接触可能引起火灾。与有机物、还原剂及易燃物硫、磷等混和后，摩擦、撞击，有引起燃烧爆炸的危险。加热时，容器可能爆炸。有腐蚀性。与可燃物、还原剂、活性金属粉末、硫、磷等混合可形成爆炸性混合物。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '氮氧化物、镝氧化物', '雾状水、砂土。切勿将水流直接射至熔融物，以免引起严重的流淌火灾或引起剧烈的沸溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5304, 5439, '遇明火、高热可燃。受热分解产生有毒气体。与可燃物接触可能引起火灾。与有机物、还原剂及易燃物硫、磷等混和后，摩擦、撞击，有引起燃烧爆炸的危险。加热时，容器可能爆炸。', '氮氧化物、铒氧化物', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5305, 5440, '与可燃物、还原剂接触可形成爆炸性混合物。燃烧分解时，放出有毒的氮氧化物气体。受高热分解，产生有毒的氮氧化物。', '氮氧化物。', '雾状水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5306, 5441, '强氧化剂。与可燃物、还原剂、有机物等混合能形成爆炸性混合物，遇明火、高热有燃烧爆炸危险。受热分解产生有毒的氮氧化物。', '氮氧化物。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。切勿将水流直接射至熔融物，以免引起严重的流淌火灾或引起剧烈的沸溅。灭火剂：雾状水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:23', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5307, 5442, '遇明火、高热可燃。受热分解产生有毒气体。与可燃物接触可能引起火灾。与有机物、还原剂及易燃物硫、磷等混和后，摩擦、撞击，有引起燃烧爆炸的危险。加热时，容器可能爆炸。有腐蚀性。与可燃物、还原剂、活性金属粉末、硫、磷等混合可形成爆炸性混合物。高温时分解，释出剧毒的氮氧化物气体。', '氮氧化物、镉氧化物', '雾状水、砂土。切勿将水流直接射至熔融物，以免引起严重的流淌火灾或引起剧烈的沸溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:23', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5308, 5443, '遇明火、高热可燃。受热分解产生有毒气体。与可燃物接触可能引起火灾。与有机物、还原剂及易燃物硫、磷等混和后，摩擦、撞击，有引起燃烧爆炸的危险。加热时，容器可能爆炸。有腐蚀性。', '氮氧化物、铬氧化物', '雾状水、泡沫、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:23', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5309, 5444, '受热分解放出有毒的汞蒸气和氮氧化物。', '氧化氮、氧化汞。', '合适的灭火介质：雾状水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:23', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5310, 5445, '金属粉末等混合可形成爆炸性混合物。在74℃开始分解，放出有毒的氮氧化物。', '氮氧化物。', '雾状水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:24', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5311, 5446, '与硝基化合物和氯酸盐组成的混合物对震动和摩擦敏感并可能爆炸。受高热分解，产生有毒的氮氧化物。', '氮氧化物。', '采用水、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:24', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5312, 5447, '受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、氮氧化物。', '灭火剂：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5313, 5448, '混合时有引起燃烧爆炸的危险。燃烧分解时，放出有毒的氮氧化物气体。受热分解，放出氧气。', '氮氧化物。', '雾状水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5314, 5449, '遇明火、高热可燃。受热分解产生有毒气体。与可燃物接触可能引起火灾。与有机物、还原剂及易燃物硫、磷等混和后，摩擦、撞击，有引起燃烧爆炸的危险。加热时，容器可能爆炸。有腐蚀性。与可燃物、还原剂、活性金属粉末、硫、磷等混合可形成爆炸性混合物。高温时分解，释出剧毒的氮氧化物气体。', '氮氧化物、镧氧化物', '雾状水、砂土。切勿将水流直接射至熔融物，以免引起严重的流淌火灾或引起剧烈的沸溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5315, 5450, '遇明火、高热可燃。受热分解产生有毒气体。与可燃物接触可能引起火灾。加热时，容器可能爆炸。', '氮氧化物、铑氧化物', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5316, 5451, '强氧化剂。与可燃物、还原剂、有机物等混合能形成爆炸性混合物，遇明火、高热有燃烧爆炸危险。受热分解产生有毒的氮氧化物。', '氮氧化物、氧化锂。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。切勿将水流直接射至熔融物，以免引起严重的流淌火灾或引起剧烈的沸溅。灭火剂：雾状水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5317, 5452, '受热或接触火焰可能会产生膨胀或爆炸性分解。强氧化剂，与可燃物、还原剂、有机物等接触可能引起燃烧或爆炸。加热时，容器可能爆炸。', '氮氧化物、镥氧化物', '灭火剂：雾状水、砂土、泡沫、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5318, 5453, '遇明火、高热可燃。受热分解产生有毒气体。与可燃物接触可能引起火灾。与有机物、还原剂及易燃物硫、磷等混和后，摩擦、撞击，有引起燃烧爆炸的危险。加热时，容器可能爆炸。有腐蚀性。', '氮氧化物、氧化铝', '雾状水、砂土。切勿将水流直接射至熔融物，以免引起严重的流淌火灾或引起剧烈的沸溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5319, 5454, '遇明火、高热可燃。受热分解产生有毒气体。与可燃物接触可能引起火灾。与有机物、还原剂及易燃物硫、磷等混和后，摩擦、撞击，有引起燃烧爆炸的危险。加热时，容器可能爆炸。有腐蚀性。与可燃物、还原剂、活性金属粉末、硫、磷等混合可形成爆炸性混合物。', '氮氧化物、镁氧化物', '雾状水、砂土。切勿将水流直接射至熔融物，以免引起严重的流淌火灾或引起剧烈的沸溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5320, 5455, '强氧化剂。与可燃物、还原剂、有机物等混合能形成爆炸性混合物，遇明火、高热有燃烧爆炸危险。受热分解产生有毒的氮氧化物。', '氮氧化物。', '消防人员必须佩戴过滤式防毒面具（全面罩）或隔离式呼吸器、穿全身防火防毒服，在上风向灭火。灭火剂：雾状水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5321, 5456, '强酸接触能引起燃烧或爆炸。燃烧分解时，放出有毒的氮氧化物气体。受高热分解，产生有毒的氮氧化物。', '氮氧化物。', '雾状水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5322, 5457, '受热、撞击、摩擦或与氧化剂接触有燃烧爆炸的危险。', '氮氧化物。', '必须在安全距离以外施救。灭火剂：雾状水、泡沫、二氧化碳。禁止用砂土压盖。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5323, 5458, '遇明火、高热可燃。受热分解产生有毒气体。与可燃物接触可能引起火灾。与有机物、还原剂及易燃物硫、磷等混和后，摩擦、撞击，有引起燃烧爆炸的危险。加热时，容器可能爆炸。有腐蚀性。与可燃物、还原剂、活性金属粉末、硫、磷等混合可形成爆炸性混合物。粉末等混合可形成爆炸性混合物。高温时分解，释出剧毒的氮氧化物气体。急剧加热时可发生爆炸。', '氮氧化物、镍氧化物', '雾状水、砂土。切勿将水流直接射至熔融物，以免引起严重的流淌火灾或引起剧烈的沸溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5324, 5459, '受热或接触火焰可能会产生膨胀或爆炸性分解。强氧化剂，与可燃物、还原剂、有机物等接触可能引起燃烧或爆炸。', '一氧化碳、二氧化碳、氮氧化物。', '灭火剂：雾状水、砂土、泡沫、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5325, 5460, '遇明火、高热可燃。受热分解，放出有毒的烟气。灭火行动对已发生的火灾可能无效。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '氮氧化物。', '使用适合火灾类型的合适的灭火剂。禁止用砂土压盖。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5326, 5461, '强酸接触能引起燃烧或爆炸。受高热分解，产生有毒的氮氧化物。', '氮氧化物。', '雾状水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5327, 5462, '遇明火、高热可燃。受热分解产生有毒气体。与可燃物接触可能引起火灾。与有机物、还原剂及易燃物硫、磷等混和后，摩擦、撞击，有引起燃烧爆炸的危险。加热时，容器可能爆炸。有腐蚀性。与可燃物、还原剂、活性金属粉末、硫、磷等混合可形成爆炸性混合物。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '氮氧化物、镨氧化物', '雾状水、砂土。切勿将水流直接射至熔融物，以免引起严重的流淌火灾或引起剧烈的沸溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5328, 5463, '与还原剂、有机物、易燃物或金属粉末等混合可形成爆炸性混合物。受高热分解，产生有毒的氮氧化物。', '氮氧化物。', '雾状水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5329, 5464, '受高热发生剧烈分解，甚至发生爆炸。', '氮氧化物。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5330, 5465, '遇明火、高热可燃。受热分解产生有毒气体。与可燃物接触可能引起火灾。与有机物、还原剂及易燃物硫、磷等混和后，摩擦、撞击，有引起燃烧爆炸的危险。加热时，容器可能爆炸。有腐蚀性。与可燃物、还原剂、活性金属粉末、硫、磷等混合可形成爆炸性混合物。', '氮氧化物、铯氧化物', '雾状水、砂土。切勿将水流直接射至熔融物，以免引起严重的流淌火灾或引起剧烈的沸溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5331, 5466, '遇明火、高热可燃。受热分解，放出有毒的烟气。灭火行动对已发生的火灾可能无效。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '氮氧化物。', '使用适合火灾类型的合适的灭火剂。禁止用砂土压盖。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5332, 5467, '与还原剂、有机物、易燃物或金属粉末等混合可形成爆炸性混合物。高温时分解，释出剧毒的氮氧化物气体。', '氮氧化物。', '雾状水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5333, 5468, '分解，放出有毒的烟气。', '氮氧化物。', '雾状水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5334, 5469, '遇明火、高热可燃。受热分解产生有毒气体。与可燃物接触可能引起火灾。与有机物、还原剂及易燃物硫、磷等混和后，摩擦、撞击，有引起燃烧爆炸的危险。加热时，容器可能爆炸。有腐蚀性。与可燃物、还原剂、活性金属粉末、硫、磷等混合可形成爆炸性混合物。', '氮氧化物、锶氧化物', '雾状水、砂土。切勿将水流直接射至熔融物，以免引起严重的流淌火灾或引起剧烈的沸溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5335, 5470, '受热分解产生有毒气体。与还原剂、有机物、易燃物或金属粉末等混合可形成爆炸性混合物。', '氮氧化物。', '雾状水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5336, 5471, '与还原剂、有机物、易燃物、硫、磷等接触或混合时有引起燃烧爆炸的危险。高温时分解，释出剧毒的氮氧化物气体。', '氮氧化物。', '雾状水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5337, 5472, '遇明火、高热可燃。受热分解产生有毒气体。与可燃物接触可能引起火灾。与有机物、还原剂及易燃物硫、磷等混和后，摩擦、撞击，有引起燃烧爆炸的危险。加热时，容器可能爆炸。有腐蚀性。', '氮氧化物、铜氧化物', '雾状水、泡沫、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5338, 5473, '强氧化剂。与可燃物、还原剂、有机物等混合能形成爆炸性混合物，遇明火、高热有燃烧爆炸危险。受热分解产生有毒的氮氧化物。', '氮氧化物、氧化锌。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。雾状水、砂土。切勿将水流直接射至熔融物，以免引起严重的流淌火灾或引起剧烈的沸溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5339, 5474, '受热分解产生有毒的汞蒸气和氮氧化物。', '氧化汞、氮氧化物。', '灭火剂：雾状水、泡沫、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5340, 5475, '跟可燃物质接触可能会引起火灾。受热或接触火焰可能会产生膨胀或爆炸性分解。', '氮氧化物。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5341, 5476, '遇明火、高热极易燃烧爆炸。与还原剂能发生强烈反应。受热分解放出有毒的氧化氮烟气。', '一氧化碳、二氧化碳、氮氧化物。', '合适的灭火介质：泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5342, 5477, '遇明火、高热可燃。受热分解，放出有毒的烟气。', '氮氧化物。', '水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:37', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5343, 5478, '易燃，具有强氧化性。遇明火、高热会引起燃烧爆炸。', '一氧化碳、二氧化碳、氧化氮。', '灭火剂：泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:37', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5344, 5479, '易燃液体，蒸气与空气混合能形成爆炸性混合物。受热或接触火焰可能会产生膨胀或爆炸性分解。蒸气可能会移动到着火源并回闪。加热时，容器可能爆炸。', '受热分解产生一氧化碳、二氧化碳、氮氧化物等有毒气体。', '灭火剂：干粉、二氧化碳、耐醇泡沫、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:37', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5345, 5480, '遇明火、高热可燃。受热分解产生有毒气体。与可燃物接触可能引起火灾。与有机物、还原剂及易燃物硫、磷等混和后，摩擦、撞击，有引起燃烧爆炸的危险。加热时，容器可能爆炸。有腐蚀性。与可燃物、还原剂、活性金属粉末、硫、磷等混合可形成爆炸性混合物。', '氮氧化物、镱氧化物', '雾状水、砂土。切勿将水流直接射至熔融物，以免引起严重的流淌火灾或引起剧烈的沸溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:37', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5346, 5481, '遇明火、高热可燃。受热分解产生有毒气体。与可燃物接触可能引起火灾。与有机物、还原剂及易燃物硫、磷等混和后，摩擦、撞击，有引起燃烧爆炸的危险。加热时，容器可能爆炸。', '氮氧化物、镱氧化物', '雾状水、砂土。切勿将水流直接射至熔融物，以免引起严重的流淌火灾或引起剧烈的沸溅。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5347, 5482, '遇明火、高热可燃。受热分解产生有毒气体。与可燃物接触可能引起火灾。与有机物、还原剂及易燃物硫、磷等混和后，摩擦、撞击，有引起燃烧爆炸的危险。加热时，容器可能爆炸。有腐蚀性。', '氮氧化物、铟氧化物', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:39', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5348, 5483, '无机氧化剂。遇可燃物着火时，能助长火势。受高热分解，产生有毒的氮氧化物。', '氮氧化物。', '采用水、雾状水、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:39', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5349, 5484, '易燃，具有强氧化性。遇明火、高热会引起燃烧爆炸。', '一氧化碳、二氧化碳、氧化氮。', '灭火剂：泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:39', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5350, 5485, '易燃液体，蒸气与空气混合能形成爆炸性混合物。遇高热、明火或氧化剂，有引起燃烧的危险。与路易氏酸（如三氟化硼、氯化铝等）发生爆炸性反应。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物', '灭火剂：干粉、二氧化碳、耐醇泡沫、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:39', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5351, 5486, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。受热分解放出有毒的氧化氮烟气。', '一氧化碳、二氧化碳、氮氧化物。', '灭火剂：泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5352, 5487, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。受热、撞击、摩擦或与氧化剂接触有燃烧爆炸的危险。', '一氧化碳、二氧化碳、氮氧化物。', '使用适合火灾类型的合适的灭火剂。禁止用砂土压盖。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5353, 5488, '遇明火、高热、氧化剂能燃烧，并散发出有毒气体。', '一氧化碳、二氧化碳、氮氧化物。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5354, 5489, '其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。遇高热能发生聚 合 反应，出现人黾放热现象，引起容器破裂或爆炸事故。', '-氧化碳、二氧化碳。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:43', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5355, 5490, '遇明火、高热可燃。与强氧化剂可发生反应。受热分解，放出有毒的烟气。有腐蚀性。', '一氧化碳、二氧化碳。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:43', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5356, 5491, '有腐蚀性。', '一氧化碳、二氧化碳、氧化硅、氯化氢。', '二氧化碳、干粉、砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5357, 5492, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：泡沫、干粉、二氧化碳、砂', '土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5358, 5493, '遇明火、高热可燃。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、锡、氧化锡。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5359, 5494, '蚀性气体。受热分解，放出高毒的烟气。', '-氧化碳、二氧化碳、氯化氢、光气。', '二氧化碳、干粉。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5360, 5495, '燃的危险。接触水可能发生强烈或爆炸性反应。物质接触空气，湿气或水可能燃烧。使用时可能产生易燃或易爆的蒸气-空气混合物。加热时，容器可能爆炸。暴露于火中的容器可能会通过压力安全阀泄漏出内容物。受热或接触火焰可能会产生膨胀或爆炸性分解。', '氧化锌', '采用干粉、干砂灭火。禁止用水和泡沫灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5361, 5496, '和氢、甲烷、硫磺、锑、砷、磷、钠、钾及其它金属粉末剧烈反应，甚至引起燃烧爆炸。与还原剂能发生强烈反应。能腐蚀大多数金属及有机组织。', '溴化氢。喷水保持火场容器冷却，直至灭火结束。用雾状水赶走泄漏的液体。用氨水从远处喷射，驱散蒸气，并使之中和。但对泄漏出来的溴液不可用氨水喷射，以免引起强烈反应，放热而产生大量剧毒的溴蒸气。', '喷水保持火场容器冷却，直至灭火结束。用雾状水赶走泄漏的液体。用氨水从远处喷射，驱散蒸气，并使之中和。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5362, 5497, '易燃，遇高热、明火及强氧化剂易引起燃烧。', '一氧化碳、二氧化碳、溴化氢。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、泡沫、干粉、二氧', '化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5363, 5498, '遇明火、高热可燃。受热分解产生有毒气体。', '一氧化碳、二氧化碳、氮氧化物、溴化氢', '干粉、二氧化碳、耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5364, 5499, '遇明火易燃。受高热燃烧并分解产生有毒气体。', '一氧化碳、二氧化碳、溴化氢。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：抗溶性泡沫、二氧化碳、砂土。', '抗溶性泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:48', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5365, 5500, '遇明火、高热可燃。受热分解产生有毒的溴化物气体。', '一氧化碳、二氧化碳、溴化氢。喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：泡沫、二氧化碳、干粉、砂土。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:48', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5366, 5501, '遇明火、高热可燃。受高热分解产生有毒的溴化物气体。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、溴化氢。', '雾状水、泡沫、干粉、二氧化碳。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:48', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5367, 5502, '遇明火、高热易燃。受热或遇水分解放热，放出有毒的腐蚀性烟气。有腐蚀性。', '一氧化碳、二氧化碳、溴化氢。', '干粉、砂土、二氧化碳。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:48', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5368, 5503, '受高热分解，放出高毒的烟气。', '氧化汞、溴化氢、汞。', '干粉、二氧化碳或耐醇泡沫。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:50', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5369, 5504, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。受高热分解产生有毒的溴化物气体。', '一氧化碳、二氧化碳、溴化氢。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:50', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5370, 5505, '遇明火、高热可燃。受热分解产生有毒的硒化物和溴化物气体。', '硒化物、溴化氢等有毒气体。', '干粉、二氧化碳或耐醇泡沫。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:50', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5371, 5506, '受高热升华产生有毒气体。', '溴化氢、氧化汞。', '采用水、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5372, 5507, '受高热分解产生有毒的溴化物气体。', '溴化氢。', '消防人员必须穿全身防火防毒服，在上风向灭火。灭火剂：二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:52', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5373, 5508, '遇明火、高热易燃。受热或遇水分解放热，放出有毒的腐蚀性烟气。有腐蚀性。', '一氧化碳、二氧化碳、溴化氢。', '干粉、砂土、二氧化碳。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:52', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5374, 5509, '与活性金属粉末（如镁、铝等）能发生反应，引起分解。与碱金属接触受冲击时会着火燃烧。', '一氧化碳、二氧化碳、溴化氢', '切断气源。若不能切断气源，则不允许熄灭泄漏处的火焰。喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、泡沫、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:52', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5375, 5510, '若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氟化氢、溴化氢。', '不燃。切断气源。喷水冷却容器，可能的话将容器从火场移至空旷处。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5376, 5511, '强氧化剂，与易燃物和有机物质接触会引起剧烈反应，甚至爆炸。受热分解产生有毒气体。', '一氧化碳、二氧化碳、溴化氢', '干粉、二氧化碳、砂土。禁止用水、泡沫、酸碱灭火器。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5377, 5512, '强氧化剂，高毒，具刺激性。摩擦或受热易引起燃烧或爆炸。与硫酸接触容易发生爆炸。能与铝、砷、铜、碳、金属硫化物、有机物、磷、硒、硫剧烈反应。', '溴化氢、氧化钡', '喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5378, 5513, '强氧化剂。与铵盐、金属粉末、可燃物、有机物或其它易氧化物形成爆炸性混合物，经摩擦或受热易引起燃烧或爆炸。与硫酸接触容易发生爆炸。能与铝、砷、铜、碳、金属硫化物、有机物、磷、硒、硫剧烈反应。', '溴化氢、氧化镉。', '喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5379, 5514, '强氧化剂。与铵盐、金属粉末、可燃物、有机物或其他易氧化物形成爆炸性混合物，经摩擦或受热易引起燃烧或爆炸。与硫酸接触易于着火或爆炸。能与铝、砷、铜、碳、金属硫化物、有机物、磷、硒、硫剧烈反应。', '溴化氢、氧化钾。', '喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5380, 5515, '强氧化剂。与铵盐、金属粉末、可燃物、有机物或其它易氧化物形成爆炸性混合物，经摩擦或受热易引起燃烧或爆炸。与硫酸接触容易发生爆炸。能与铝、砷、铜、碳、金属硫化物、有机物、磷、硒、硫剧烈反应。', '溴化氢、氧化镁。', '喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5381, 5516, '强氧化剂，与易燃物、还原剂、有机物接触会引起剧烈反应，甚至爆炸。摩擦或受热易引起燃烧或爆炸。与硫酸接触容易发生爆炸。能与铝、砷、铜、碳、金属硫化物、有机物、磷、硒、硫剧烈反应。', '溴化氢、氧化钠', '喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5382, 5517, '强氧化剂。能与可燃物、有机物或易氧化物质形成爆炸性混合物，经摩擦和与少量水接触可导致燃烧或爆炸。', '溴化氢、氧化铅。', '喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5383, 5518, '强氧化剂。与铵盐、金属粉末、可燃物、有机物或其它易氧化物形成爆炸性混合物，经摩擦或受热易引起燃烧或爆炸。与硫酸接触容易发生爆炸。能与铝、砷、铜、碳、金属硫化物、有机物、磷、硒、硫剧烈反应。具刺激性。', '溴化氢、氧化锶。', '喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5384, 5519, '强氧化剂。与铵盐、金属粉末、可燃物、有机物或其它易氧化物形成爆炸性混合物，经摩擦或受热易引起燃烧或爆炸。与硫酸接触容易发生爆炸。能与铝、砷、铜、碳、金属硫化物、有机物、磷、硒、硫剧烈反应。', '溴化氢、氧化锌。', '喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5385, 5520, '强氧化剂。与铵盐、金属粉末、可燃物、有机物或其它易氧化物形成爆炸性混合物，经摩擦或受热易引起燃烧或爆炸。与硫酸接触容易发生爆炸。能与铝、砷、铜、碳、金属硫化物、有机物、磷、硒、硫剧烈反应。具刺激性。', '溴化氢、氧化银。', '喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5386, 5521, '遇明火、高热可燃。受高热分解产生有毒的溴化物气体。与强氧化剂接触可发生化学反应。遇潮时对大多数金属有腐蚀性。', '一氧化碳、二氧化碳、溴化氢。', '采用雾状水、泡沫、二氧化碳灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5387, 5522, '遇明火、高热可燃。受高热分解产生有毒的烟气。', '一氧化碳、二氧化碳、溴化氢。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：抗溶性泡沫、干粉、砂土。', '抗溶性泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:57', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5388, 5523, '遇明火易燃。受高热燃烧并分解产生有毒气体。', '一氧化碳、二氧化碳、溴化氢', '雾状水、抗溶性泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:58', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5389, 5524, '其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。受高热分解产生有毒的溴化物气体。', '一氧化碳、二氧化碳、溴化氢。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：抗溶性泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:59', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5390, 5525, '遇明火、高热可燃。有腐蚀性。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、溴化氢。合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '干粉、二氧化碳或耐醇泡沫。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:59', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5391, 5526, '遇明火能燃烧。受高热分解产生有毒的溴化物气体。', '一氧化碳、二氧化碳、溴化氢。喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、抗溶性泡沫、干粉、砂土。', '雾状水、抗溶性泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:59', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5392, 5527, '遇明火能燃烧。受高热分解产生有毒的溴化物气体。', '一氧化碳、二氧化碳、溴化氢。喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、抗溶性泡沫、干粉、砂土。', '雾状水、抗溶性泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:46:59', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5393, 5528, '其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。受高热分解产生有毒的溴化物气体。受光照或火焰下易分解生成溴化氢和碳酰溴。与强氧化剂接触可发生化学反应。', '一氧化碳、二氧化碳、溴化氢。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：泡沫、干粉、二氧化碳、砂土。', '泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:01', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5394, 5529, '燃烧或无抑制剂时可发生剧烈聚合。', '一氧化碳、二氧化碳、溴化氢。切断气源。喷水冷却容器，可能的话将容器从火场移至空旷处。若不能切断气源，则不允许熄灭泄漏处的火焰。灭火剂：雾状水、泡沫、干粉、二氧化碳。', '雾状水、泡沫、干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:01', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5395, 5530, '遇明火、高热可燃。受高热放出大量催泪性毒气。', '一氧化碳、二氧化碳、溴化氢、溴气。合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '干粉、二氧化碳或耐醇泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:01', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5396, 5531, '与乙醇发生剧烈反应，释出具有刺激性、腐蚀性的溴化氢烟气。遇潮时对大多数金属有腐蚀性。受高热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、溴化氢。合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '干粉、二氧化碳或耐醇泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:01', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5397, 5532, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。受热分解放出有毒的氧化氮烟气。', '一氧化碳、二氧化碳、氧化氮。', '雾状水、二氧化碳、泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:01', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5398, 5533, '遇明火、高热可燃。受热分解产生有毒的氧化氮、氯化物、含汞气体。', '一氧化碳、二氧化碳、氮氧化物、氯化氢、汞蒸气', '干粉、二氧化碳、泡沫。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5399, 5534, '受高热分解，放出有毒的烟气。', '碲、氧化钠。', '雾状水、泡沫、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5400, 5535, '具有腐蚀性。受热分解产生剧毒的氧化磷烟气。', '磷烷、氧化磷。', '用雾状水保持火场中容器冷却。用大量水灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5401, 5536, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。受热分解产生剧毒的氧化磷烟气。', '一氧化碳、二氧化碳、氧化磷。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5402, 5537, '遇到火星或受热时，易于燃烧。甚至在缺氧时也能引起持续燃烧。', '氧化磷、磷烷、氧化铅。', '水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5403, 5538, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。遇潮气逐渐分解。', '一氧化碳、二氧化碳、氧化磷、磷烷。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:05', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5404, 5539, '热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氧化磷、磷烷。', '二氧化碳、泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5405, 5540, '磷烟气。', '一氧化碳、二氧化碳、氧化磷、磷烷。', '雾状水、二氧化碳、泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:07', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5406, 5541, '暴露在空气中可发生氧化反应。受高热分解产生有毒的硫化物烟气。具有腐蚀性。', '氧化硫。', '灭火剂：雾状水、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:07', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5407, 5542, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳、耐醇泡沫或水喷雾。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:08', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5408, 5543, '具有还原性。有腐蚀性。接触酸或酸气能产生有毒气体。受高热分解，放出有毒的烟气。', '氧化硫。 合适的灭火介质:干粉、二氧化碳、耐醇泡沫或水喷雾。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5409, 5544, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳、耐醇泡沫或水喷雾。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5410, 5545, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳、耐醇泡沫或水喷雾。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5411, 5546, '具有强还原性。有腐蚀性。接触酸或酸气能产生有毒气体。受高热分解，放出有毒的烟气。', '氧化硫、氧化钠。 合适的灭火介质:干粉、二氧化碳、耐醇泡沫或水喷雾。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5412, 5547, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳、耐醇泡沫或水喷雾。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5413, 5548, '气体。在潮湿条件下，与硫或磷接触引起着火和爆炸。接触硫代氰酸钾能引发燃烧。', '不燃，但能助长火势。如果该物质或被污染的流体进入水路，通知有潜在水体污染的下游', '用户，通知地方卫生、消防官员和污染控制部门。使用适合于火场的任何一种灭火剂灭火。 在安全防爆距离以外，使用雾状水冷却暴露的容器。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5414, 5549, '势加强并让火焰自身维持。灭火行动对已发生的火灾可能无效加热时，容器可能爆炸。 受热或接触火焰可能会产生膨胀或爆炸性分解。', '灭火方法： 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5415, 5550, '或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5416, 5551, '不燃。遇高热、明火会产生剧毒的蒸气。遇酸产生剧毒的三氧化二砷。', '氧化砷、氧化钙。', '消防人员必须穿全身防火防毒服，在上风向灭火。灭火剂：干粉、水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:12', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5417, 5552, '氧化碳逐渐分解。', '氧化砷、氧化钾。', '消防人员必须穿全身防火防毒服，在上风向灭火。灭火剂：干粉、水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5418, 5553, '遇酸产生剧毒的三氧化二砷。', '氧化砷、氧化钠。', '消防人员必须穿全身防火防毒服，在上风向灭火。灭火剂：干粉、水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5419, 5554, '受高热分解，放出高毒的烟气。', '氧化砷、氧化铅、砷。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5420, 5555, '受高热分解，放出高毒的烟气。', '砷、氧化锶。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:15', '', NULL);
