INSERT INTO `msds_fire_fighting` VALUES (5435, 5570, '受高热分解，放出高毒的烟气。', '氧化硒、硒。', '不燃。火场周围可用的灭火介质。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:20', '', NULL);
