INSERT INTO `msds_fire_fighting` VALUES (5437, 5572, '能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:20', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5438, 5573, '有引起燃烧爆炸的危险。受热分解，放出高毒的烟气。', '氮氧化物、氨。', '雾状水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:20', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5439, 5574, '分解，放出有毒的烟气。', '氮氧化物、氧化钡。', '雾状水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:22', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5440, 5575, '高温时分解，释出剧毒的氮氧化物气体。', '氧化氮。', '消防人员须戴好防毒面具，在安全距离以外，在上风向灭火。灭火剂：雾状水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:23', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5441, 5576, '分解时有爆炸危险。与联氨、卤化铵、铵盐、硫氰酸盐、铁氰化物、可燃物和氧化剂接触受热 爆炸。', '一氧化碳、二氧化碳、氮氧化物。', '切断气源。灭火剂：泡沫、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:24', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5442, 5577, '体。与铵盐、可燃物粉末或氰化物的混合物会爆炸。加热或遇酸能产生剧毒的氮氧化物气 体。', '氮氧化物。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：雾状水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:24', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5443, 5578, '气体。与铵盐、可燃物粉末或氰化物的混合物会爆炸。加热或遇酸能产生剧毒的氮氧化 物气体。', '氮氧化物。', '消防人员须戴好防毒面具，在安全距离以外，在上风向灭火。灭火剂：雾状水、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:24', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5444, 5579, '热分解，放出有毒的烟气。', '氮氧化物。', '雾状水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5445, 5580, '势加强并让火焰自身维持。灭火行动对已发生的火灾可能无效。加热时，容器可能爆炸。 受热或接触火焰可能会产生膨胀或爆炸性分解。', '灭火方法： 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5446, 5581, '分解时有爆炸危险。', '一氧化碳、二氧化碳、氮氧化物。 尽可能将容器从火场移至空旷处。处在火场中的容器若已变色或从安全泄压装置中产生声', '音，必须马上撤离。灭火剂：1211灭火剂、干粉、砂土。禁止用水和泡沫灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5447, 5582, '接触铵盐、氰化物可引起强烈分解。', '一氧化碳、二氧化碳、氮氧化物。 消防人员必须佩戴过滤式防毒面具(全面罩)或隔离式呼吸器、穿全身防火防毒服，在上风', '向灭火。喷水保持火场容器冷却，直至灭火结束。灭火剂：泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5448, 5583, '遇明火、高热易引起燃烧，并放出有毒气体。受热分解放出有毒的氧化氮烟气。', '一氧化碳、二氧化碳、氮氧化物。 消防人员必须佩戴过滤式防毒面具(全面罩)或隔离式呼吸器、穿全身防火防毒服，在上风', '向灭火。喷水保持火场容器冷却，直至灭火结束。灭火剂：泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5449, 5584, '遇高热、明火及强氧化剂易引起燃烧并放出有毒气体。', '一氧化碳、二氧化碳、氮氧化物。 消防人员必须佩戴过滤式防毒面具(全面罩)或隔离式呼吸器、穿全身防火防毒服，在上风', '向灭火。喷水保持火场容器冷却，直至灭火结束。灭火剂：泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5450, 5585, '易燃，遇明火、高热易引起燃烧，并放出有毒气体。', '一氧化碳、二氧化碳、氧化氮。 喷水保持火场容器冷却，直至灭火结束。消防人员必须佩戴过滤式防毒面具(全面罩)或隔', '离式呼吸器、穿全身防火防毒服，在上风向灭火。灭火剂：泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5451, 5586, '遇明火、高热易引起燃烧，并放出有毒气体。受热分解放出有毒的氧化氮烟气。', '一氧化碳、二氧化碳、氧化氮。 消防人员必须佩戴过滤式防毒面具(全面罩)或隔离式呼吸器、穿全身防火防毒服，在上风', '向灭火。喷水保持火场容器冷却，直至灭火结束。灭火剂：泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5452, 5587, '热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氧化氮。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5453, 5588, '强氧化剂。本品不会燃烧, 但可助燃。与丙酮、铝接触剧烈反应。与易燃物、有机物接触易着火 燃烧。遇水或潮气分解。对钢铁有腐蚀性。', '氮氧化物、氯化氢。 消防人员必须穿特殊防护服，在掩蔽处操作。切断气源。喷水冷却容器，可能的话将容器从火场', '移至空旷处。灭火剂：雾状水、泡沫、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5454, 5589, '遇明火、高热可燃。', '一氧化碳、二氧化碳。 消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。 喷水保持火场容器冷却，直至灭火结束。处在火场中的容器若已变色或从安全泄压装置中产生', '声音，必须马上撤离。灭火剂：雾状水、泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5455, 5590, '若遇高热，容器内压增大，有开裂和爆炸的危险。', '无资料', '本品不燃。切断气源。喷水冷却容器，可能的话将容器从火场移至空旷处。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5456, 5591, '遇明火、高热可燃。受热分解产生有毒气体。', '一氧化碳、二氧化碳、氯化氢、氮氧化物。', '灭火剂：干粉、二氧化碳、泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:29', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5457, 5592, '遇明火、高热可燃。其粉体与空气可形成爆炸性混合物，当达到一定浓度时，遇火星会发生爆炸。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、氮氧化物、氯化氢', '合适的灭火介质：雾状水、泡沫、干粉、二氧化碳、砂土。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。切勿将水流直接射至熔融物，以免引起严重的流淌火灾或引起剧烈的沸溅。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5458, 5593, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '氮氧化物、氯化氢、一氧化碳、二氧化碳', '合适的灭火介质：干粉、二氧化碳、耐醇泡沫或水喷雾。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5459, 5594, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、氮氧化物、氯化氢', '合适的灭火介质：干粉、二氧化碳、耐醇泡沫或水喷雾。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5460, 5595, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、氮氧化物、氯化氢', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5461, 5596, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '燃烧产物包括一氧化碳、二氧化碳、氮氧化物、氯化氢。', '使用干粉、二氧化碳、耐醇泡沫灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5462, 5597, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、氮氧化物、氯化氢', '使用干粉、二氧化碳、耐醇泡沫灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5463, 5598, '遇高热、明火或氧化剂，有引起燃烧的危险。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、氮氧化物、氯化氢。', '使用干粉、二氧化碳、耐醇泡沫灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:32', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5464, 5599, '一般不会燃烧，但长时间暴露在明火及高温下仍能燃烧。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、氮氧化物、氯化氢', '使用干粉、二氧化碳、耐醇泡沫灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:32', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5465, 5600, '受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、氮氧化物、氯化氢', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:32', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5466, 5601, '受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、氮氧化物、氯化氢', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5467, 5602, '遇高热、明火或氧化剂，有引起燃烧的危险。受高热分解，放出有毒的烟气。', '氮氧化物、氯化氢、一氧化碳、二氧化碳。', '泡沫、水、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5468, 5603, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、氮氧化物、氯化氢', '干粉、二氧化碳、耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:33', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5469, 5604, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、氮氧化物、氯化氢', '干粉、二氧化碳、耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5470, 5605, '遇明火、高热可燃。与强氧化剂可发生反应。受高热分解产生有毒的腐蚀性气体。', '一氧化碳、二氧化碳、氧化氮、氯化氢。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5471, 5606, '受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、氮氧化物、氯化氢', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5472, 5607, '遇明火、高热可燃。受热分解产生有毒的氮氧化物和氯化氢烟雾。', '一氧化碳、二氧化碳、氮氧化物、氯化氢', '干粉、二氧化碳、耐醇泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5473, 5608, '遇明火、高热可燃。受热分解产生有毒的氮氧化物和氯化氢烟雾。', '一氧化碳、二氧化碳、氧化氮、氯化氢。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5474, 5609, '遇明火、高热可燃。受热分解产生有毒的氮氧化物和氯化氢烟雾。', '一氧化碳、二氧化碳、氧化氮、氯化氢。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5475, 5610, '遇明火、高热可燃。受热分解产生有毒的氮氧化物和氯化氢烟雾。', '一氧化碳、二氧化碳、氧化氮、氯化氢。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5476, 5611, '遇明火、高热可燃。受热分解产生有毒的氮氧化物和氯化氢烟雾。', '一氧化碳、二氧化碳、氮氧化物、氯化氢', '喷水、喷雾或使用干粉、二氧化碳、泡沫灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:37', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5477, 5612, '与易燃物、可燃物（如氢气、甲烷等）形成有爆炸性的混合物。', '无资料', '用水保持容器冷却，以防受热爆炸，急剧助长火势。迅速切断气源，用水喷淋保护切断气源的人员，然后根据着火原因选择适当灭火剂灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:37', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5478, 5613, '未有特殊的燃烧爆炸特性。', '氧化钡。', '不燃。火场周围可用的灭火介质。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:37', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5479, 5614, '与氧化剂可发生反应。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '雾状水、抗溶性泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:37', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5480, 5615, '受高热分解，放出有毒的蒸气。', '氧化碲蒸气。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:37', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5481, 5616, '与酸类物质能发生剧烈反应。具有较强的腐蚀性。', '氧化钙。', '采用干粉、二氧化碳、干砂灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5482, 5617, '不燃。与镁的混合物加热时可能发生爆炸。受高热分解，放出有毒的烟气。', '受高热分解，放出有毒的镉化合物烟气。', '不燃。火场周围可用的灭火介质：水、泡沫、干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:39', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5483, 5618, '接触有机物有引起燃烧危险。受高热会放出剧毒汞蒸气。', '氧化汞、汞蒸气。', '不燃。火场周围可用的灭火介质：干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:39', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5484, 5619, '其蒸气与空气形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。 其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内 压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:39', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5485, 5620, '能会产生膨胀或爆炸性分解。', '与水反应生成氢氧化钾，放出热量。遇酸类反应剧烈。', '干粉、二氧化碳或耐醇泡沫。禁止用水灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:39', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5486, 5621, '不燃，具有强腐蚀性，与水反应产生氢氧化钠并放出大量热量。', '与水反应生成氢氧化钠', '本品不燃。根据周围环境选择合适的灭火剂。灭火时，应佩戴呼吸面具并穿上全身防护服。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5487, 5622, '受高热分解，放出高毒的烟气。', '受高热分解，放出高毒的铍化合物烟气。', '不燃。火场周围可用的灭火介质。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5488, 5623, '和硫、三硫化锑的混合物在研磨时可能发生爆炸。受高热分解，放出有毒的烟气。', '铊。', '不燃。火场周围可用的灭火介质。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5489, 5624, '受高热会放出剧毒的烟气。', '汞、氧化汞。', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5490, 5625, '受高热、明火会产生剧毒的蒸气。', '氧化铊。', '二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5491, 5626, '不燃。跟可燃物质接触可能会引起火灾。', '受热分解可能产生银氧化物和有毒烟雾。', '不燃。火场周围可用的灭火介质：水、泡沫、干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5492, 5627, '本品助燃，具强腐蚀性、强刺激性，可致人体灼伤。遇水反应剧烈，放出腐蚀性烟雾。', '氯化氢、氧化铬', '干粉、二氧化碳、干燥砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5493, 5628, '遇水剧烈反应，放出氯化氢和氧化硫，具有强腐蚀性。', '氯化氢、氧化硫、硫化氢。', '不燃。火场周围可用的灭火介质：干粉、干燥砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5494, 5629, '不燃。具有强氧化性。遇水发生剧烈反应，散发出具有刺激性和腐蚀性的氯化氢气体。与磷、钾能发生猛烈的化学反应。对很多金属尤其是潮湿空气存在下有腐蚀性。', '氯化氢、氧化硒。', '不燃。火场周围可用的灭火介质：干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5495, 5630, '气体。受高热分解，放出高毒的烟气。', '氮氧化物、汞、氰化氢', '干粉、二氧化碳或耐醇泡沫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5496, 5631, '多数金属有腐蚀性。受高热分解，放出有毒的烟气。', '溴化氢、氧化磷。', '干粉、砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:44', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5497, 5632, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:44', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5498, 5633, '爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:44', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5499, 5634, '空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳、氧化氮。 切断气源。若不能切断气源，则不允许熄灭泄漏处的火焰。喷水冷却容器，可能的话将容器', '从火场移至空旷处。灭火剂：雾状水、抗溶性泡沫、干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:44', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5500, 5635, '其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂接触发生反应。受热分解产生一氧化碳、二氧化碳、氯化氢、光气等有毒的腐蚀性烟雾。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氯化氢、光气。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:46', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5501, 5636, '若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氟化氢。', '本品不燃。切断气源。喷水冷却容器，可能的话将容器从火场移至空旷处。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:46', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5502, 5637, '遇明火、高热可燃。受热分解产生有毒气体。', '一氧化碳、二氧化碳、氯化氢。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5503, 5638, '具有强氧化性。接触有机物有引起燃烧危险。遇潮时对大多数金属有腐蚀性。遇水或水蒸 气反应发热放出有毒的腐蚀性气体。与钠、钾发生剧烈反应。受高热分解，放出高毒的烟 气。', '氯化氢、碘化氢。', '二氧化碳、干粉。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:47', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5504, 5639, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。受热或遇水分解放热，放出有毒的腐蚀性 烟气。', '氯化氢、氧化硫、硫化氢。', '砂土、二氧化碳。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5505, 5640, '受高热分解，放出有毒的氟化物和氯化物气体。', '一氧化碳、二氧化碳、氯化氢、氟化氢。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5506, 5641, '在空气中不发生燃烧爆炸。受高热分解，放出有毒的氟化物和氯化物气体。若遇高热，容器内压 增大，有开裂和爆炸的危险。', '氯化物、氟化物。', '本品不燃。切断气源。喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5507, 5642, '易燃，遇明火、高热可燃。', '一氧化碳、二氧化碳、氯化氢。', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。灭火剂：雾状水、抗溶性泡沫、二 氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5508, 5643, '受热或遇水分解放热，放出有毒的腐蚀性烟气。', '溴化氢、碘化氢。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:50', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5509, 5644, '在空气中不发生燃烧爆炸。若遇高热，容器内压增大，有开裂和爆炸的危险。', '氟化氢、溴化氢。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5510, 5645, '发出棕色有氧化性的烟雾。一氧化氮较不活泼，但在空气中易被氧化成二氧化氮，而后者 有强烈毒性。', '氧化氮。 消防人员必须穿全身防火防毒服，在上风向灭火。切断气源。喷水冷却容器，可能的话将', '容器从火场移至空旷处。灭火剂：雾状水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5511, 5646, '遇乙醚、乙烯等易燃气体能起助燃作用，可加剧火焰的燃烧。', '氧化氮。 本品不燃。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。用雾状水保持火', '场中容器冷却。迅速切断气源，用水喷淋保护切断气源的人员，然后根据着火原因选择 适当灭火剂灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5512, 5647, '未有特殊的燃烧爆炸特性。', '氧化铅。', '采用水、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:52', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5513, 5648, '反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳、氧化氮。 切断气源。若不能切断气源，则不允许熄灭泄漏处的火焰。喷水冷却容器，可能的话将容', '器从火场移至空旷处。灭火剂：雾状水、抗溶性泡沫、干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:52', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5514, 5649, '炸的危险。与氧化剂接触猛烈反应。流速过快，容易产生和积聚静电。其蒸气比空气重， 能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。处在火场中的容器若已变色或从安全', '泄压装置中产生声音，必须马上撤离。灭火剂：泡沫、干粉、二氧化碳、砂土。用水灭火 无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:52', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5515, 5650, '易燃液体，其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂接触发生剧烈反应，甚至引起燃烧。在火场中，受热的容器有爆炸危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳', '抗溶性泡沫、干粉、二氧化碳、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5516, 5651, '而增加火势和/或蒸气的浓度。蒸气可能会移动到着火源并回闪。液体和蒸气易燃。加热 时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质：干式化学灭火剂、纯碱、石灰或干砂。不合适的灭火介质：不要使用', '水、二氧化碳或泡沫灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:53', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5517, 5652, '燃烧时放出有毒的刺激性烟雾。', '氧化钠、一氧化碳、二氧化碳。', '二氧化碳、干粉。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:54', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5518, 5653, '可生成具有潜在爆炸危险性的过氧化物。', '一氧化碳、二氧化碳。 尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的', '容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：抗溶性泡沫、干粉、 二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:54', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5519, 5654, '易燃，遇明火、高热能引起燃烧爆炸。受热分解产生有毒气体。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:54', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5520, 5655, '可生成具有潜在爆炸危险性的过氧化物。', '一氧化碳、二氧化碳。 尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的', '容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：抗溶性泡沫、干粉、 二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5521, 5656, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳。', '水、泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:56', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5522, 5657, '遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。接触空气或在光照条件下可生成具有 潜在爆炸危险性的过氧化物。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、1211灭火剂、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:56', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5523, 5658, '遇明火、高热可燃。加热分解产生易燃的有毒气体。与氧化剂可发生反应。', '一氧化碳、二氧化碳。', '采用抗溶性泡沫、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:56', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5524, 5659, '遇明火、高热可燃。加热分解产生毒性气体。', '一氧化碳、二氧化碳。', '采用抗溶性泡沫、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:56', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5525, 5660, '遇明火、高热可燃。加热分解产生易燃的有毒气体。', '一氧化碳、二氧化碳。', '采用抗溶性泡沫、干粉、二氧化碳、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:58', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5526, 5661, '受热或遇水分解放热，放出有毒的腐蚀性烟气。若遇高热可发生剧烈分解，引起容器破裂或爆 炸事故。具有较强的腐蚀性。', '一氧化碳、二氧化碳、光气。', '砂土、干粉、二氧化碳、泡沫。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:58', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5527, 5662, '或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:58', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5528, 5663, '会通过压力安全阀泄漏出内容物。受热或接触火焰可能会产生膨胀或爆炸性分解。', '无资料 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安全 距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:58', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5529, 5664, '触空气或在光照条件下可生成具有潜在爆炸危险性的过氧化物。其蒸气比空气重，能在较低处 扩散到相当远的地方，遇火源引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:47:58', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5530, 5665, '剂接触猛烈反应。', '一氧化碳、二氧化碳、氯化氢、氧化硅。 消防人员必须穿全身防火防毒服，在上风向灭火。灭火剂：干粉、二氧化碳、砂土。禁止', '用水和泡沫灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5531, 5666, '受高热分解，放出高毒的烟气。', '氯化物、氰化氢、二氧化碳、氧化砷。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5532, 5667, '相当远的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '砂土、泡沫、干粉、二氧化碳。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5533, 5668, '其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压 增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '砂土、泡沫、干粉、二氧化碳。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5534, 5669, '其蒸气与空气形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。 若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5535, 5670, '散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险 。', '一氧化碳、二氧化碳。', '抗溶性泡沫、二氧化碳、干粉、砂土、雾状水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5536, 5671, '有毒的腐蚀性烟气。具有腐蚀性。', '一氧化碳、二氧化碳、氯化氢、氧化硅。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：二氧化碳、干粉、干砂。禁', '止用水和泡沫灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5537, 5672, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳、氧化硅。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5538, 5673, '触空气或在光照条件下可生成具有潜在爆炸危险性的过氧化物。其蒸气比空气重，能在较低处扩 散到相当远的地方，遇火源引着回燃。若遇高热，可能发生聚合反应，出现大量放热现象，引起 容器破裂和爆炸事故。', '一氧化碳、二氧化碳。', '泡沫、抗溶性泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5539, 5674, '容器可能爆炸。暴露于火中的容器可能会通过压力 安全阀泄漏出内容物。受热或接触火焰 可能会产生膨胀或爆炸性分解。', '无资料 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安全 距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5540, 5675, '极易燃液体，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂能发生强烈反应。燃烧时有发光火焰。与硫酸、发烟硫酸、氯磺酸、过氯酸盐等反应剧烈。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳、氧化氮、氰化氢', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5541, 5676, '次氯酸钙、氢氧化钙发生剧烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火 源引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氧化硫。', '泡沫、二氧化碳、干粉、砂土、1211灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5542, 5677, '应。在空气中久置后能生成有爆炸性的过氧化物。在火场中，受热的容器有爆炸危险。其 蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的', '容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：抗溶性泡沫、二氧 化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5543, 5678, '潮湿空气能自燃。与氟、氯、溴等卤素会剧烈反应并能与氟氯烷灭火剂猛烈反应。', '氧化硼。 切断气源。若不能切断气源，则不允许熄灭泄漏处的火焰。喷水冷却容器，可能的话将容', '器从火场移至空旷处。灭火剂：二氧化碳。禁止用水和泡沫灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5544, 5679, '中久置后能生成有爆炸性的过氧化物。受热可能发生剧烈的聚合反应。其蒸气比空气重， 能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 遇到大火，消防人员须在有防爆掩蔽处操作。抗溶性泡沫、二氧化碳、干粉、砂土。用水', '灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5545, 5680, '炸。', '一氧化碳、二氧化碳、氧化氮。', '雾状水、二氧化碳、泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5546, 5681, '易燃，与空气混合能形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氟、氯等接触会发生剧烈的化学反应。与铜、银、汞等的化合物生成爆炸性物质。', '一氧化碳、二氧化碳', '切断气源。若不能切断气源，则不允许熄灭泄漏处的火焰。喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5547, 5682, '受热、震动、撞击、摩擦，相当敏感，极易分解发生爆炸。', '一氧化碳、二氧化碳；氧化银。', '水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5548, 5683, '易燃液体，其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与铬酸、过氧化钠、硝酸或其它氧化剂接触，有爆炸危险。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。具有腐蚀性。', '一氧化碳、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:07', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5549, 5684, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。若遇高热，容器内压增大，有开裂和爆炸 的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:07', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5550, 5685, '遇明火、高热、氧化剂能燃烧，并散发出有毒气体。', '一氧化碳、二氧化碳、氧化钡。 合适的灭火介质:干粉、二氧化碳、耐醇泡沫或水喷雾。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:08', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5551, 5686, '爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:08', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5552, 5687, '遇明火、高热可燃。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、氧化汞。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:08', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5553, 5688, '的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5554, 5689, '易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与强氧化剂接触可 发生化学反应。', '一氧化碳、二氧化碳。', '用水喷射逸出液体，使其稀释成不燃性混合物，并用雾状水保护消防人员。灭火剂：雾状水、 抗溶性泡沫、干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5555, 5690, '易燃，遇明火、高热有引起燃烧爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5556, 5691, '的危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5557, 5692, '遇明火、高热可燃。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、氧化汞。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:10', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5558, 5693, '猛烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 采用抗溶性泡沫、二氧化碳、干粉、砂土灭火。用水灭火无效，但可用水保持火场中容器', '冷却。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5559, 5694, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳、耐醇泡沫或水喷雾。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5560, 5695, '受热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氧化铍。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5561, 5696, '遇明火、高热可燃。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、氧化铅。', '雾状水、泡沫、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5562, 5697, '的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5563, 5698, '遇明火、高热可燃。受热分解产生有毒气体。', '合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5564, 5699, '遇明火、高热可燃。受热分解产生有毒的氧化锡烟雾。与氧化剂可发生反应。', '一氧化碳、二氧化碳、氧化锡烟雾', '干粉、二氧化碳、耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5565, 5700, '生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '采用泡沫、二氧化碳、干粉、砂土灭火。用水灭火无效，但可用水保持火场中容器冷却。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5566, 5701, '其蒸气与空气形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。 其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源引着回燃。若遇高热，可能发生聚 合反应，出现大量放热现象，引起容器破裂和爆炸事故。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5567, 5702, '遇明火、高热可燃。受热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氧化汞。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:15', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5568, 5703, '遇明火、高热可燃。受热分解，放出有毒的烟气。', '一氧化碳、二氧化碳、氧化铊。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:15', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5569, 5704, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '抗溶性泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:15', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5570, 5705, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。', '一氧化碳、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:15', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5571, 5706, '易燃液体，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂能发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:17', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5572, 5707, '易燃，遇明火、高热可放出大量放热现象，引起容器破裂和爆炸事故。其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。', '一氧化碳、二氧化碳。', '雾状水、二氧化碳、泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:17', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5573, 5708, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '采用抗溶性泡沫、二氧化碳、干粉、砂土灭火。用水灭火无效，但可用水保持火场中容器冷却。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:17', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5574, 5709, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '采用泡沫、二氧化碳、干粉、砂土灭火。用水灭火无效，但可用水保持火场中容器冷却。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:17', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5575, 5710, '生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。具 有腐蚀性。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：泡沫、干粉、二氧化碳、砂', '土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5576, 5711, '生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 采用抗溶性泡沫、二氧化碳、干粉、砂土灭火。用水灭火无效，但可用水保持火场中容器', '冷却。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5577, 5712, '生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 采用抗溶性泡沫、二氧化碳、干粉、砂土灭火。用水灭火无效，但可用水保持火场中容器', '冷却。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:20', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5578, 5713, '和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5579, 5714, '生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。具 有腐蚀性。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：泡沫、干粉、二氧化碳、砂', '土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5580, 5715, '生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '采用泡沫、二氧化碳、干粉、砂土灭火。用水灭火无效，但可用水保持火场中容器冷却。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:23', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5581, 5716, '易燃，与空气混合能形成爆炸性混合物，遇热源和明火有燃烧爆炸的危险。与氟、氯等接 触会发生剧烈的化学反应。', '一氧化碳、二氧化碳。 切断气源。若不能切断气源，则不允许熄灭泄漏处的火焰。喷水冷却容器，可能的话将容', '器从火场移至空旷处。灭火剂：雾状水、泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:23', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5582, 5717, '其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压 增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氯化氢。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:23', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5583, 5718, '的危险。与氟、氯等接触会发生剧烈的化学反应。', '一氧化碳、二氧化碳。 切断气源。若不能切断气源，则不允许熄灭泄漏处的火焰。喷水冷却容器，可能的话将容', '器从火场移至空旷处。灭火剂：雾状水、泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:23', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5584, 5719, '爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:24', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5585, 5720, '其蒸气与空气形成爆炸性混合物，遇明火、高热极易燃烧爆炸。在空气中非常容易氧化生成 过氧化物，受热或撞击、甚至轻微摩擦即发生爆炸。能与浓硫酸、发烟硝酸猛烈反应，甚至 发生爆炸。在精馏操作过程中，易发生自聚，引起事故，应加阻聚剂。', '一氧化碳、二氧化碳。 切断气源。若不能立即切断气源，则不允许熄灭正在燃烧的气体，喷水冷却容器，可能的话将', '容器从火场移至空旷处。雾状水、泡沫、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:24', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5586, 5721, '而增加火势和/或蒸气的浓度。蒸气可能会移动到着火源并回闪。液体和蒸气易燃。加热 时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5587, 5722, '的危险。', '一氧化碳、二氧化碳、氧化硅。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5588, 5723, '遇明火、高热可燃。燃烧分解时，放出有毒的氮氧化物。', '一氧化碳、二氧化碳、氧化氮。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5589, 5724, '触火焰可能会产生膨胀或爆炸性分解。', '无资料', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5590, 5725, '容器爆破。', '一氧化碳、二氧化碳。 由于火场中可能发生容器爆破的情况，消防人员须在有防爆掩蔽处操作。灭火剂：泡沫、', '干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5591, 5726, '分解释出剧毒的光气和氯化氢气体。遇水、水蒸气或乙醇剧烈反应甚至爆炸。其蒸气比空 气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳、氯化氢、光气。', '采用二氧化碳、干粉、1211灭火剂、砂土灭火。禁止用水和泡沫灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5592, 5727, '遇明火、高热可燃。受热分解产生有毒的氮氧化物和硫氧化物烟气。', '氮氧化物、硫氧化物、一氧化碳、二氧化碳', '干粉、二氧化碳、泡沫、砂土。用水灭火可能无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5593, 5728, '遇水或空气中的二氧化碳作用生成亚砷酸。受高热或接触酸或酸雾放出剧毒的烟雾。', '一氧化碳、二氧化碳、氧化砷、氧化铜。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5594, 5729, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。若遇高热，容器内压增大，有开裂和爆炸 的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5595, 5730, '遇明火、高热可燃。受热分解产生有毒气体。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5596, 5731, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5597, 5732, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳', '泡沫、二氧化碳、干粉、砂土。喷水冷却容器，可能的话将容器从火场移至空旷处。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5598, 5733, '遇火源引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳、硫化氢、氧化硫', '泡沫、二氧化碳、干粉、1211灭火剂、砂土。喷水冷却容器，可能的话将容器从火场移至空旷处。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5599, 5734, '在空气中久置后能生成有爆炸性的过氧化物。在火场中，受热的容器有爆炸危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳', '抗溶性泡沫、二氧化碳、干粉、砂土。用水灭火无效。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5600, 5735, '能发生聚合反应，出现大量放热现象，引起容器破裂和爆炸事故。流速过快，容易产生和积聚静电。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳', '泡沫、干粉、二氧化碳、砂土。用水灭火无效。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5601, 5736, '易燃，其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。受热分解，放出高毒的烟气。受热分解产生有毒的氧化磷、氧化硫等气体。', '一氧化碳、二氧化碳、氧化磷、氧化硫', '抗溶性泡沫、干粉、砂土。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。禁止使用酸碱灭火剂。用水灭火无效，但可用水保持火场中容器冷却。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:32', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5602, 5737, '易燃，遇明火、高热能引起燃烧爆炸。与氧化剂发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。具腐蚀性。', '一氧化碳、二氧化碳、氧化氮', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：抗溶性泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:32', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5603, 5738, '若遇高热，容器内压增大，有开裂和爆炸的危险。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:32', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5604, 5739, '液体和蒸气易燃。受热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。蒸气可能会移动到着火源并回闪。', '一氧化碳、二氧化碳。', '干粉、二氧化碳或耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:32', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5605, 5740, '危险性的过氧化物。遇高热能发生聚合反应，出现大量放热现象，引起容器破裂或爆炸事故。', '一氧化碳、二氧化碳。', '干粉、二氧化碳或耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5606, 5741, '其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳、氧化氮。', '消防人员必须佩戴过滤式防毒面具（全面罩）或隔离式呼吸器、穿全身防火防毒服，在上风向灭火。灭火剂：二氧化碳、干粉、砂土。用水灭火无效，但须用水保持火场容器冷却。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5607, 5742, '极度易燃，其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳', '遇到大火，消防人员须在有防爆掩蔽处操作。灭火剂：抗溶性泡沫、二氧化碳、干粉、砂土。用水灭火无效。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:35', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5608, 5743, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。具有腐蚀性。', '一氧化碳、二氧化碳', '喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、抗溶性泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:36', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5609, 5744, '易燃，遇明火、高热能引起燃烧。遇低级醇和水起化学反应而分解。具有腐蚀性。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳', '喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：水、二氧化碳、泡沫、干粉、砂土。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:37', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5610, 5745, '易燃，遇高热、明火及强氧化剂易引起燃烧。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳', '采用泡沫、二氧化碳、干粉、砂土灭火。用水灭火无效，但须用水保持火场容器冷却。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5611, 5746, '易燃，遇高热、明火及强氧化剂易引起燃烧。', '一氧化碳、二氧化碳。', '采用泡沫、二氧化碳、干粉、砂土灭火。用水灭火无效，但须用水保持火场容器冷却。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5612, 5747, '易燃，遇高热、明火及强氧化剂易引起燃烧。容器可能爆炸。暴露于火中的容器可能会通过压力安全阀泄漏出内容物。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳', '采用泡沫、二氧化碳、干粉、砂土灭火。用水灭火无效，但须用水保持火场容器冷却。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5613, 5748, '易燃，遇明火、高热能引起燃烧爆炸。与氧化剂发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：泡沫、干粉、二氧化碳、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5614, 5749, '易燃，遇高热、明火及强氧化剂易引起燃烧。容器可能爆炸。暴露于火中的容器可能会通过压力安全阀泄漏出内容物。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳', '采用泡沫、二氧化碳、干粉、砂土灭火。用水灭火无效，但须用水保持火场容器冷却。喷水冷却容器，可能的话将容器从火场移至空旷处。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:38', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5615, 5750, '易燃气体。与空气混合能形成爆炸性混合物，遇热源和明火有燃烧爆炸的危险。气体比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳', '切断气源。若不能切断气源，则不允许熄灭泄漏处的火焰。喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5616, 5751, '聚合反应。与氧化剂接触猛烈反应。气体比空气重，能在较低处扩散到相当远的地方，遇 火源会着火回燃。', '一氧化碳、二氧化碳。 切断气源。若不能切断气源，则不允许熄灭泄漏处的火焰。喷水冷却容器，可能的话将容', '器从火场移至空旷处。灭火剂：雾状水、泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5617, 5752, '遇明火、高热易燃。与氧化剂能发生强烈反应。遇水反应发热放出有毒的腐蚀性气体。若 遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氯化氢、光气。', '二氧化碳、干粉、砂土、1211灭火剂。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5618, 5753, '遇明火、高热可燃。遇水、潮气、触媒和高热易发生聚合。受高热分解，放出有毒的烟气。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氮氧化物、氰化氢', '干粉、二氧化碳或耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5619, 5754, '易燃，遇明火、高热能引起燃烧爆炸。与氧化剂发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：泡沫、干粉、二氧化碳、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:40', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5620, 5755, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳', '雾状水、泡沫、二氧化碳、干粉、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:41', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5621, 5756, '其蒸气与空气形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '采用泡沫、二氧化碳、干粉、砂土灭火。用水灭火无效，但须用水保持火场容器冷却。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5622, 5757, '遇明火、高热可燃。与强氧化剂可发生反应。受高热分解。接触酸及酸气时，能放出有毒的氰化物及氧化硫烟气。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氧化氮、氧化硫、氰化氢', '泡沫、二氧化碳、砂土、干粉。禁止使用酸碱灭火剂。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5623, 5758, '易燃，其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。受热分解，放出高毒的烟气。受高热或与酸接触会产生剧毒的氰化物气体。', '一氧化碳、二氧化碳、氮氧化物、氰化氢、氧化硫', '泡沫、干粉、二氧化碳、砂土。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。禁止使用酸碱灭火剂。用水灭火无效，但可用水保持火场中容器冷却。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5624, 5759, '易燃，其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。受热分解，放出高毒的烟气。受高热或与酸接触会产生剧毒的氰化物气体。', '一氧化碳、二氧化碳、氮氧化物、氰化氢、氧化硫', '泡沫、干粉、二氧化碳、砂土。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。禁止使用酸碱灭火剂。用水灭火无效，但可用水保持火场中容器冷却。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:42', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5625, 5760, '易燃，其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。受热分解，放出高毒的烟气。受高热或与酸接触会产生剧毒的氰化物气体。', '一氧化碳、二氧化碳、氮氧化物、氰化氢、硫化物', '泡沫、干粉、二氧化碳、砂土。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。禁止使用酸碱灭火剂。用水灭火无效，但可用水保持火场中容器冷却。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:44', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5626, 5761, '遇明火、高热可燃。与强氧化剂可发生反应。受高热分解放出有毒的气体。', '一氧化碳、二氧化碳、氧化氮', '泡沫、二氧化碳、干粉、砂土。禁止使用酸碱灭火剂。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火时，应佩戴呼吸面具并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:44', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5627, 5762, '遇明火、高热可燃。受热分解释放出有毒的氮氧化物和氯化物气体。', '一氧化碳、二氧化碳、氮氧化物、氯化氢', '干粉、二氧化碳或耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:44', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5628, 5763, '加热至沸点以上时即分解释出有毒的亚硝酸蒸气。与酸类、胺类、醇、碱类和水发生强烈反应，有引起燃烧爆炸的危险。遇水或水蒸气分解放出有毒的气体', '一氧化碳、二氧化碳、氮氧化物、氰化氢', '干粉、二氧化碳。禁止用水、泡沫和酸碱灭火剂灭火。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:44', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5629, 5764, '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、氮氧化物、氰化氢', '干粉、二氧化碳、耐醇泡沫或水喷雾。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:44', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5630, 5765, '遇明火、高热可燃。受高热分解，放出高毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、氰化氢、溴化氢', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火剂：干粉、二氧化碳、砂土。禁止用水、泡沫、酸碱灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:45', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5631, 5766, '遇明火、高热可燃。受高热分解，放出高毒的烟气。', '一氧化碳、二氧化碳、氯化氢、氮氧化物、氰化氢', '干粉、二氧化碳或耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:46', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5632, 5767, '受高热分解，放出高毒的烟气，有爆炸的危险。有腐蚀性', '一氧化碳、二氧化碳、氮氧化物、氰化氢', '干粉、二氧化碳或耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:46', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5633, 5768, '易燃，遇明火、高热能引起燃烧爆炸。受热分解放出有毒的气体。遇水或水蒸气反应放出有毒和易燃的气体。在火场中，受热的容器有爆炸危险。', '一氧化碳、二氧化碳、氮氧化物、氰化氢', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：泡沫、干粉、二氧化碳、砂土。禁止用水、酸碱灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:46', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5634, 5769, '遇高热、明火或氧化剂，有引起燃烧的危险。受高热分解，放出高毒的烟气。', '一氧化碳、二氧化碳、氰化氢、氟化氢、氮氧化物', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火剂：干粉、二氧化碳、砂土。禁止用水、泡沫、酸碱灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:46', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5635, 5770, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。受热分解产生有毒的氮氧化物和氰化氢气体。与水、醇、胺类等反应剧烈，产生二氧化碳和相应的胺类化合物。', '一氧化碳、二氧化碳、氮氧化物、氰化氢', '干粉、二氧化碳、耐醇泡沫或水喷雾。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:48', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5636, 5771, '遇明火、高热易燃。其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。受热分解，放出高毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、氰化氢', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火剂：干粉、二氧化碳、砂土。禁止用水、泡沫、酸碱灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:48', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5637, 5772, '遇明火、高热易燃。与强氧化剂可发生反应。遇水或水蒸气反应放出有毒的或易燃的气体。若遇高热可发生剧烈分解，引起容器破裂或爆炸事故。', '一氧化碳、二氧化碳、氮氧化物、氰化氢', '二氧化碳、干粉、砂土。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:48', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5638, 5773, '比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。受热分解，放出高毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、氰化氢', '干粉、二氧化碳或耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:48', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5639, 5774, '易燃，并伴生毒气，容器在火中爆炸', '一氧化碳、二氧化碳、氮氧化物、氰化氢', '干粉、二氧化碳或耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:49', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5640, 5775, '遇高热可发生剧烈分解，引起容器破裂或爆炸事故', '一氧化碳、二氧化碳、氮氧化物、氰化氢', '二氧化碳、干粉、砂土。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:50', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5641, 5776, '遇高热可发生剧烈分解，引起容器破裂或爆炸事故', '一氧化碳、二氧化碳、氮氧化物、氰化氢', '二氧化碳、干粉、砂土。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:50', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5642, 5777, '遇火或摩擦极易引燃，其粉体与空气混合，能形成爆炸性混合物。加热时，容器可能爆炸。暴露于火中的容器可能会通过压力安全阀泄漏出内容物。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、氮氧化物', '干粉、二氧化碳、水喷雾或耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:50', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5643, 5778, '其蒸气与空气形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。若遇高热，容器内压增大，有开裂和爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:51', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5644, 5779, '易燃，遇明火、高热能引起燃烧爆炸。与氧化剂发生强烈反应。具有腐蚀性。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳、氧化氮', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：抗溶性泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:52', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5645, 5780, '遇水、潮气、酸类发生剧烈反应，放出易燃气体。遇明火、高热有燃烧爆炸危险。', '一氧化碳、二氧化碳、氧化钠', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火剂：干粉、二氧化碳、砂土。禁止用水、泡沫、酸碱灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:54', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5646, 5781, '易燃，遇明火、高热能引起燃烧爆炸。受热分解产生有毒的氰化氢和氮氧化物气体。与氧化剂发生强烈反应。', '一氧化碳、二氧化碳、氰化氢、氮氧化物', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：泡沫、干粉、二氧化碳、砂土。禁止使用酸碱灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:54', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5647, 5782, '易燃，遇明火、高热有燃烧爆炸危险。与氧化剂能发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳', '用泡沫、二氧化碳、干粉、砂土灭火。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5648, 5783, '易燃，遇明火、高热能引起燃烧爆炸。与氧化剂发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5649, 5784, '易燃，遇明火、高热能引起燃烧爆炸。与氧化剂发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：干粉、二氧化碳、耐醇泡沫、砂土。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5650, 5785, '易燃，遇明火、高热能引起燃烧爆炸。受热分解产生有毒的氯化氢和光气气体。具有强腐蚀性。', '一氧化碳、二氧化碳、氯化氢、光气', '消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：干粉、二氧化碳、耐醇泡沫、砂土。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:55', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5651, 5786, '容器可能爆炸。暴露于火中的容器可能会通过压力安全阀泄漏出内容物。受热或接触火焰可能会产生膨胀或爆炸性分解。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳', '干粉、二氧化碳或耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:56', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5652, 5787, '若遇高热，可发生聚合反应，放出大量热量而引起容器破裂和爆炸事故。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳', '泡沫、干粉、二氧化碳、砂土。用水灭火无效，但可用水保持火场中容器冷却。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:56', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5653, 5788, '遇明火、高热可燃。与氧化剂能发生强烈反应。有腐蚀性。', '一氧化碳、二氧化碳。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:56', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5654, 5789, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。受热分解产生有毒的氮氧化物和氰化氢气体。', '一氧化碳、二氧化碳、氧化氮、氰化氢', '雾状水、泡沫、二氧化碳、干粉、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:58', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5655, 5790, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。受热分解产生一氧化碳和二氧化碳。', '一氧化碳、二氧化碳', '雾状水、泡沫、二氧化碳、干粉、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:58', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5656, 5791, '爆炸性分解。受热分解或爆炸性分解。', '一氧化碳、二氧化碳、氮氧化物、汞蒸气等有毒气体。合适的灭火介质：干粉、二氧化碳或耐醇泡沫。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:48:58', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5657, 5792, '遇明火、高热易燃。受热分解产生有毒气体。', '一氧化碳、二氧化碳。', '干粉、二氧化碳或耐醇泡沫。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5658, 5793, '遇明火、高热易燃。受热分解产生有毒气体。其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。', '一氧化碳、二氧化碳。', '干粉、二氧化碳或耐醇泡沫。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5659, 5794, '遇明火、高热易燃。受热分解产生有毒气体。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '泡沫、干粉、二氧化碳、砂土。喷水冷却容器，可能的话将容器从火场移至空旷处。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5660, 5795, '遇明火、高热易燃。受热分解产生有毒气体。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '干粉、二氧化碳或耐醇泡沫。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:00', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5661, 5796, '爆炸性分解。遇高热、明火或与氧化剂接触，有引起燃烧的危险。受热分解产生有毒的烟气。', '一氧化碳、二氧化碳、氮氧化物、锡氧化物', '干粉、二氧化碳、耐醇泡沫。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:01', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5662, 5797, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。燃烧分解时，放出有毒的烟雾。', '一氧化碳、二氧化碳', '泡沫、二氧化碳、干粉、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5663, 5798, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。燃烧分解时，放出有毒的氮氧化物。', '一氧化碳、二氧化碳、氧化氮', '雾状水、泡沫、二氧化碳、干粉、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5664, 5799, '易燃，蒸气能扩散到远处，遇点火源着火，并引起回燃。储存容器及其部件可能向四面八方飞射很远。受热分解产生有毒的烟气。', '一氧化碳、二氧化碳等有毒气体', '干粉、二氧化碳、砂土。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5665, 5800, '蒸气可能会移动到着火源并回闪。液体和蒸气易燃。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳。', '干粉、二氧化碳或耐醇泡沫。禁止使用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5666, 5801, '极端易燃，有爆炸危险。剧毒。受热分解产生有毒的锗化合物和氢气。', '受热分解产生锗化合物、氢气等有毒气体。', '消防人员须穿全身消防服，佩戴正压自给式呼吸器，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。切断气源。若不能切断气源，则不允许熄灭泄漏处的火焰。喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:02', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5667, 5802, '爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:03', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5668, 5803, '爆炸性分解。', '合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在 安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5669, 5804, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。', '一氧化碳、二氧化碳', '泡沫、二氧化碳、干粉、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5670, 5805, '其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂能发生强烈反应。在相当远的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5671, 5806, '其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。与次氯酸钙、氢氧化钙发生剧烈反应。', '一氧化碳、二氧化碳、氧化硫。', '泡沫、二氧化碳、干粉、1211灭火剂、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:04', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5672, 5807, '在空气中久置后能生成有爆炸性的过氧化物。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '抗溶性泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5673, 5808, '易燃，遇高温、明火、强氧化剂有燃烧爆炸危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。具腐蚀性。', '一氧化碳、二氧化碳、氧化氮。', '喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：抗溶性泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5674, 5809, '猛烈反应。在火场中，受热的容器有爆炸危险。', '一氧化碳、二氧化碳。 用水喷射逸出液体，使其稀释成不燃性混合物，并用雾状水保护消防人员。灭火剂：抗溶', '性泡沫、干粉、二氧化碳、雾状水、1211灭火剂、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5675, 5810, '易燃，遇高热、明火及强氧化剂易引起燃烧。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。喷水冷却容器，可能的话将容器从火场移至空旷处。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5676, 5811, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。用水灭火无效，但须用水保持火场容器冷却。用雾状水保护消防人员，用砂土堵逸出液体。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:06', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5677, 5812, '触空气或在光照条件下可生成具有潜在爆炸危险性的过氧化物。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源引着回燃。若遇高热，可能发生聚合反应，出现大量放热现象，引起容器破裂和爆炸事故。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:08', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5678, 5813, '易燃，遇高热、明火、氧化剂有引起燃烧的危险。', '一氧化碳、二氧化碳、氧化氮、氰化氢等有毒气体', '消防人员必须佩戴过滤式防毒面具（全面罩）或隔离式呼吸器、穿全身防火防毒服，在上风向灭火。灭火剂：二氧化碳、干粉、砂土。用水灭火无效，但须用水保持火场容器冷却。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:09', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5679, 5814, '易燃，遇高热、明火及强氧化剂易引起燃烧。受热、接触酸或酸雾会放出剧毒的烟雾。', '一氧化碳、二氧化碳、硫化氢、氧化硫。', '喷水冷却容器，可能的话将容器从火场移至空旷处。泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:10', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5680, 5815, '强烈反应。接触空气或在光照条件下可生成具有潜在爆炸危险性的过氧化物。其蒸气比空 气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：抗溶性泡沫、二氧化碳、干', '粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5681, 5816, '烈反应。若遇高热，可发生聚合反应，放出大量热量而引起容器破裂和爆炸事故。其蒸气 比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。 尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。处在火场中的', '容器若已变色或从安全泄压装置中产生声音，必须马上撤离。灭火剂：抗溶性泡沫、干粉、 二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:11', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5682, 5817, '遇明火、高热可燃。对大多数金属有腐蚀性。', '一氧化碳、二氧化碳', '雾状水、抗溶性泡沫、干粉、二氧化碳、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5683, 5818, '炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '采用泡沫、二氧化碳、干粉、砂土灭火。用水灭火无效，但可用水保持火场中容器冷却。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:13', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5684, 5819, '易燃液体，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '雾状水、二氧化碳、泡沫、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5685, 5820, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。', '一氧化碳、二氧化碳', '泡沫、干粉、二氧化碳、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5686, 5821, '易燃，遇明火、高热能引起燃烧爆炸。与氧化剂可发生反应。', '一氧化碳、二氧化碳', '泡沫、干粉、二氧化碳、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5687, 5822, '易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触猛烈反应。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：泡沫、干粉、二氧化碳、砂', '泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:14', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5688, 5823, '炸危险。', '一氧化碳、二氧化碳。 喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：泡沫、干粉、二氧化碳、砂', '土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:15', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5689, 5824, '易燃，与空气混合能形成爆炸性混合物，遇热源和明火有燃烧爆炸的危险。与氧化剂接触猛烈反应。气体比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '切断气源。若不能切断气源，则不允许熄灭泄漏处的火焰。喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：雾状水、泡沫、二氧化碳、干粉。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:15', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5690, 5825, '遇热，容器内压增大，有开裂和爆炸的危险。遇水反应剧烈，放出氯化氢气体。', '一氧化碳、二氧化碳、氯化氢、光气等有毒气体', '二氧化碳、1211灭火剂、干粉、砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:15', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5691, 5826, '遇明火、高热易引起燃烧爆炸。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。与氧化剂接触发生剧烈反应。', '一氧化碳、二氧化碳、氮氧化物。', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:15', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5692, 5827, '遇明火、高热能引起燃烧爆炸。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:17', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5693, 5828, '遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:17', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5694, 5829, '遇明火、高热极易引起燃烧爆炸。高速冲击、流动、激荡后可因产生静电火花放电引起燃烧爆炸。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:17', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5695, 5830, '遇明火、高热易燃。遇水、醇类发生化学反应而分解。在火场中，受热的容器有爆炸危险。', '一氧化碳、二氧化碳、氧化硅。', '二氧化碳、干粉、砂土。禁止用水。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:17', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5696, 5831, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。受热容器有爆炸危险。', '一氧化碳、二氧化碳。', '雾状水、泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:17', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5697, 5832, '受热容器有爆炸危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。液体和蒸气易燃。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:18', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5698, 5833, '其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。具有腐蚀性。', '一氧化碳、二氧化碳、氧化氮。', '雾状水、泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5699, 5834, '遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5700, 5835, '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。在潮湿空气中缓慢分解。', '一氧化碳、二氧化碳。', '泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5701, 5836, '遇高热、明火有引起燃烧的危险。受热分解放出有毒的氧化氮烟气。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:19', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5702, 5837, '遇高热、明火有引起燃烧的危险。受热放出辛辣的腐蚀性烟雾。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5703, 5838, '易燃液体，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂能发生强烈反应,甚至引起燃烧。在火场中，受热的容器有爆炸危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5704, 5839, '遇金属反应放出氢气，能与空气形成爆炸性混合物。受热分解产生剧毒的氧化磷烟气。具有腐蚀性。', '氧化磷', '用雾状水保持火场中容器冷却。用大量水灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5705, 5840, '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', '一氧化碳、二氧化碳', '雾状水、泡沫、二氧化碳、干粉、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:21', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5706, 5841, '蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳。', '干粉、二氧化碳、耐醇泡沫、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:22', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5707, 5842, '受热容器有爆炸危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳。', '泡沫、干粉、二氧化碳、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:23', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5708, 5843, '受热容器有爆炸危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。液体和蒸气易燃。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳。', '干粉、二氧化碳或耐醇泡沫。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:23', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5709, 5844, '遇明火、高热易燃。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳', '雾状水、泡沫、二氧化碳、干粉、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:24', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5710, 5845, '遇明火、高热易燃。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、氧化氮', '干粉、二氧化碳、耐醇泡沫', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:25', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5711, 5846, '遇明火、高热易燃。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', '一氧化碳、二氧化碳、硫化氢、氧化硫', '泡沫、二氧化碳、干粉、砂土', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:26', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5712, 5847, '遇明火、高热易燃。高速冲击、流动、激荡后可因产生静电火花放电引起燃烧爆炸。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳', '泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5713, 5848, '遇明火、高热可燃。受热分解，放出有毒烟气。加热时，容器可能爆炸。', '一氧化碳、二氧化碳', '干粉、二氧化碳、耐醇泡沫。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。尽可能将容器从火场移至空旷处。喷水保持火场容器冷却，直至灭火结束。灭火时，应佩戴呼吸面具（符合MSHA/NIOSH要求的或相当的）并穿上全身防护服。在安全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5714, 5849, '易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', '一氧化碳、二氧化碳、氧化氮。', '喷水冷却容器，可能的话将容器从火场移至空旷处。灭火剂：抗溶性泡沫、二氧化碳、干粉、砂土。用水灭火无效。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:27', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5715, 5850, '易燃，遇高热、明火及强氧化剂易引起燃烧。', '一氧化碳、二氧化碳。', '泡沫、二氧化碳、干粉、砂土。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5716, 5851, '加强并让火焰自身维持。灭火行动对已发生的火灾可能无效。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '受热分解产生有毒的碘化物气体', '合适的灭火介质：使用大量水、泡沫、干粉灭火器。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5717, 5852, '加强并让火焰自身维持。灭火行动对已发生的火灾可能无效。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '受热分解产生碘化氢等有毒气体。', '水、泡沫、干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5718, 5853, '火会产生刺激性、毒性或腐蚀性的气体。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', '一氧化碳、二氧化碳、氮氧化物', '合适的灭火介质：小火：干式化学灭火剂、二氧化碳、水或抗溶泡沫灭火剂；大火：水、水雾或抗溶泡沫灭火剂。不合适的灭火介质：避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:28', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5719, 5854, '受热，接触明火、高热或受到摩擦震动、撞击时可发生爆炸。', '一氧化碳、二氧化碳、氧化氮。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5720, 5855, '金属或粗糙的物品表面即能引起爆炸。', '一氧化碳、二氧化碳、氮气。', '遇大火，消防人员须在有防护掩蔽处操作。灭火剂：雾状水、干粉、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5721, 5856, '遇明火、高热可燃。急剧加热时可发生爆炸。接触酸或酸气能产生有毒气体。', '一氧化碳、二氧化碳、氧化氮。 合适的灭火介质:干粉、二氧化碳或耐醇泡沫。 不合适的灭火介质:避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。', '灭火时，应佩戴呼吸面具（(符合MSHA/NIOSH要求的或相当的)）并穿上全身防护服。在安 全距离处、有充足防护的情况下灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:30', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5722, 5857, '遇强酸接触会自燃。与硝酸盐、氯酸盐接触剧烈反应。', '氮氧化物。', '采用雾状水、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5723, 5858, '强氧化剂。与有机物、还原剂、易燃物如硫、磷等接触时，有引起燃烧爆炸的危险。', '可能产生有害的毒性烟雾。', '雾状水、砂土、二氧化碳。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5724, 5859, '硫、磷或金属粉末等混合可形成爆炸性混合物。有水时与硫化钠混合能引起自燃。与硝酸 盐、氯酸盐接触剧烈反应。具有较强的腐蚀性。', '可能产生有害的毒性烟雾。', '采用雾状水、砂土灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:31', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5725, 5860, '加强并让火焰自身维持。灭火行动对已发生的火灾可能无效。加热时，容器可能爆炸。受 热或接触火焰可能会产生膨胀或爆炸性分解。', '灭火方法： 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:32', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5726, 5861, '强氧化剂。与有机物、还原剂、易燃物如硫、磷等接触或混合时有引起燃烧爆炸的危险。受高热分解，放出有毒的烟气。', '可能产生有害的燃烧产物，包括含铬化合物、氮氧化物等', '消防人员必须穿全身防火防毒服，在上风向灭火。灭火时尽可能将容器从火场移至空旷处。根据周围环境选择合适的灭火剂。禁止使用酸碱灭火剂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:32', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5727, 5862, '强氧化剂。遇强酸或高温时能释出氧气，促使有机物燃烧。与还原剂、有机物、易燃物如硫、磷或金属粉末等混合可形成爆炸性混合物。有水时与硫化钠混合能引起自燃。与硝酸盐、氯酸盐接触剧烈反应。具有较强的腐蚀性。受热分解产生有毒的铬氧化物烟雾。', '铬氧化物（三氧化铬、氧化铬等）', '采用雾状水、砂土灭火。禁止使用易燃液体或压缩空气灭火。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:32', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5728, 5863, '加强并让火焰自身维持。灭火行动对已发生的火灾可能无效。加热时，容器可能爆炸。受 热或接触火焰可能会产生膨胀或爆炸性分解。', '灭火方法： 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5729, 5864, '加强并让火焰自身维持。灭火行动对已发生的火灾可能无效。加热时，容器可能爆炸。受 热或接触火焰可能会产生膨胀或爆炸性分解。', '灭火方法： 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5730, 5865, '加强并让火焰自身维持。灭火行动对已发生的火灾可能无效。加热时，容器可能爆炸。受 热或接触火焰可能会产生膨胀或爆炸性分解。', '灭火方法： 合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', '合适的灭火介质：使用适合火灾类型的合适的灭火剂。不合适的灭火介质：无特别说明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:34', '', NULL);
INSERT INTO `msds_fire_fighting` VALUES (5731, 5866, '受热或接触火焰可能会产生膨胀或爆炸性分解。受热分解产生有毒气体。遇明火、高热可燃。', '一氧化碳、二氧化碳、氮氧化物、氯化氢。', '采用干粉、二氧化碳、耐醇泡沫灭火。避免用太强烈的水汽灭火，因为它可能会使火苗蔓延分散。消防人员须佩戴防毒面具、穿全身消防服，在上风向灭火。防止消防水污染地表和地下水系统。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:34', '', NULL);
INSERT INTO `msds_first_aid` VALUES (2893, 3021, '用肥皂水及清水彻底冲洗。就医。', '拉开眼睑，用流动清水冲洗15分钟。就医。', '脱离现场至空气新鲜处。密切观察。就医。', '误服者，饮适量温水，催吐。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (2894, 3022, '脱去污染的衣物，用肥皂水及清水彻底冲洗。就医。', '拉开眼睑，用流动清水冲洗15分钟。就医。', '脱离现场至空气新鲜处。呼吸困难时给输氧。呼吸停止时，立即进行人工呼吸。就医。', '误服者，饮适量温水，催吐。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (2895, 3023, '立即脱去污染的衣着，用肥皂水和清水彻底冲洗皮肤。就医。', '提起眼睑，用流动清水或生理盐水冲洗。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即 进行人工呼吸。就医。', '饮足量温水，催吐。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (2896, 3024, '用肥皂水及清水彻底冲洗。就医。', '拉开眼睑，用流动清水冲洗15分钟。就医。', '脱离现场至空气新鲜处。就医。', '误服者，饮适量温水，催吐。洗胃。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (2897, 3025, '立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。', '用大量水彻底冲洗至少15分钟。如有不适，就医。', '立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止，立即进行心肺复苏术。立即就医。', '禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (2898, 3026, '脱去污染的衣着，用肥皂水及清水彻底冲洗。', '立即翻开上下眼睑，用流动清水冲洗15分钟。就医。', '脱离现场至空气新鲜处。呼吸困难时给输氧。呼吸停止时，立即进行人工呼吸。就医。', '误服者给饮牛奶或蛋清。立即就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (2899, 3027, '用肥皂水及清水彻底冲洗。就医。', '拉开眼睑，用流动清水冲洗15分钟。就医。', '脱离现场至空气新鲜处。呼吸困难时给输氧。呼吸停止时，立即进行人工呼吸。就医。', '误服者，饮适量温水，催吐。洗胃。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (2900, 3028, '脱去污染的衣着，用肥皂水及清水彻底冲洗。若有灼伤，就医治疗。', '立即提起眼睑，用流动清水或生理盐水冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。必要时进行人工呼吸。就医。', '患者清醒时立即漱口，给饮牛奶或蛋清。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (2901, 3029, '脱去污染的衣着，用大量流动清水彻底冲洗。就医。', '立即翻开上下眼睑，用流动清水或生理盐水冲洗。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。呼吸困难时给输氧。呼吸停止时，立即进 行人工呼吸。就医。', '误服者立即漱口，给饮牛奶或蛋清。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (2902, 3030, '脱去污染的衣着，用大量流动清水彻底冲洗。就医。', '立即翻开上下眼睑，用流动清水或生理盐水冲洗。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。呼吸困难时给输氧。呼吸停止时，立即进行 人工呼吸。就医。', '误服者立即漱口，给饮牛奶或蛋清。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (2903, 3031, '若液化气体接触皮肤，立即用温水缓慢冲洗至少15分钟，勿揉搓冻伤部位，可覆盖干燥敷料，就医。', '立即提起眼睑，用流动温水或生理盐水冲洗不少于15分钟。持续疼痛或视力模糊时及时就医。', '迅速脱离现场至空气新鲜处，保持呼吸道通畅。如呼吸困难，给输氧；呼吸停止，立即进行人工呼吸或心肺复苏。就医。', '通常以气体形式暴露，如误吞液体，勿催吐，漱口后立即就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (2904, 3032, '立即脱去污染的衣着，用大量流动清水冲洗至少15分钟。就医。', '立即提起眼睑，用大量流动清水或生理盐水彻底冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进 行人工呼吸。就医。', '误服者立即漱口，给牛奶、蛋清等口服。立即就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (2905, 3033, '脱去污染的衣着，用流动清水冲洗。', '立即翻开上下眼睑，用流动清水或生理盐水冲洗。', '脱离现场至空气新鲜处。就医。', '给饮足量温水，催吐，就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (2906, 3034, '立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。', '用大量水彻底冲洗至少15分钟。如有不适，就医。 立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物', '质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。', '禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (2907, 3035, '脱去污染的衣着，用肥皂水和清水彻底冲洗皮肤。', '提起眼睑，用流动清水或生理盐水冲洗。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '饮足量温水，催吐。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (2908, 3036, '脱去污染的衣着，用流动清水冲洗。', '立即提起眼睑，用大量流动清水彻底冲洗。', '脱离现场至空气新鲜处。必要时进行人工呼吸。就医。', '误服者给饮大量温水，催吐，就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (2909, 3037, '立即脱去污染的衣着，用肥皂水和清水彻底冲洗皮肤至少15分钟。如有不适感，就医。保持患者温暖和安静。', '立即提起眼睑，用流动清水或生理盐水彻底冲洗至少15分钟。如有不适感，就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '用水漱口，给饮牛奶或蛋清。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (2910, 3038, '脱去污染的衣着，用大量流动清水彻底冲洗。就医。', '立即翻开上下眼睑，用流动清水或生理盐水冲洗。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。呼吸困难时给输氧。呼吸停止时，立即进行 人工呼吸。就医。', '误服者立即漱口，给饮牛奶或蛋清。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (2911, 3039, '立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。', '用大量水彻底冲洗至少15分钟。如有不适，就医。 立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸', '入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。', '禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (2912, 3040, '用肥皂水及清水彻底冲洗。就医。', '拉开眼睑，用流动清水冲洗15分钟。就医。', '脱离现场至空气新鲜处。呼吸困难时给输氧。呼吸停止时，立即进行人工呼吸。就医。', '误服者，饮适量温水，催吐。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (2913, 3041, '脱去污染的衣着，用肥皂水和流动清水冲洗。', '立即翻开上下眼睑，用流动清水冲洗15分钟。', '脱离现场至空气新鲜处。就医。', '误服者给饮足量温水，催吐，就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (2914, 3042, '脱去污染的衣着，用流动清水冲洗。就医。', '立即翻开上下眼睑，用流动清水冲洗15分钟。就医。', '脱离现场至空气新鲜处。就医。', '误服者给饮足量温水，催吐，就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (2915, 3043, '脱去污染的衣着，用大量流动清水彻底冲洗。就医。', '立即翻开上下眼睑，用流动清水或生理盐水冲洗。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。呼吸困难时给输氧。呼吸停止时，立即进行 人工呼吸。就医。', '误服者立即漱口，给饮牛奶或蛋清。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (2916, 3044, '脱去污染的衣着，用大量流动清水彻底冲洗。就医。', '立即翻开上下眼睑，用流动清水或生理盐水冲洗。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。呼吸困难时给输氧。呼吸停止时，立即进行 人工呼吸。就医。', '误服者立即漱口，给饮牛奶或蛋清。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (2917, 3045, '脱去污染的衣着，用大量流动清水彻底冲洗至少15分钟。如有不适，就医。', '立即翻开上下眼睑，用流动清水或生理盐水彻底冲洗至少15分钟。立即就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '误服者立即漱口，切勿催吐。给饮牛奶或蛋清。立即就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (2918, 3046, '脱去污染的衣着，用肥皂水和清水彻底冲洗皮肤。如有不适感，就医。', '立即提起眼睑，用大量流动清水或生理盐水彻底冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '无资料', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (2919, 3047, '脱去污染的衣着，用流动清水冲洗。', '提起眼睑，用流动清水或生理盐水冲洗。 迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，', '立即进行人工呼吸。就医。', '饮足量温水，催吐。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (2920, 3048, '立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。', '用大量水彻底冲洗至少15分钟。如有不适，就医。 立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸', '入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就医。', '禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (2921, 3049, '立即脱去污染的衣着，用大量流动清水冲洗至少15分钟。如有不适，就医。', '立即提起眼睑，用大量流动清水或生理盐水彻底冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '用水漱口，禁止催吐。给饮用牛奶或蛋清。立即就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (2922, 3050, '脱去污染的衣着，用大量流动清水彻底冲洗。', '立即提起眼睑，用流动清水冲洗。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。必要时进行人工呼吸。就医。', '误服者给饮大量温水，催吐，就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
