INSERT INTO `msds_first_aid` VALUES (2926, 3054, '脱去污染的衣着，用流动清水冲洗。如有不适，就医。', '提起眼睑，用流动清水或生理盐水冲洗至少15分钟。如感不适，就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '饮足量温水，催吐。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
