INSERT INTO `msds_first_aid` VALUES (3061, 3189, '脱去污染的衣着，用流动清水冲洗。', '立即提起眼睑，用大量流动清水彻底冲洗。', '脱离现场至空气新鲜处。必要时进行人工呼吸。就医。', '误服者给饮大量温水，催吐，就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (3062, 3190, '用肥皂水及清水彻底冲洗。就医。', '拉开眼睑，用流动清水冲洗15分钟。就医。', '脱离现场至空气新鲜处。就医。', '误服者，饮适量温水，催吐。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (3063, 3191, '脱去污染的衣着，用流动清水冲洗。', '立即翻开上下眼睑，用流动清水冲洗15分钟。就医。', '脱离现场至空气新鲜处。呼吸困难时给输氧。呼吸停止时，立即进行人工呼吸。就医。', '误服者给饮足量温水，催吐，就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (3064, 3192, '若有冻伤，就医治疗。', '立即翻开上下眼睑，用流动清水冲洗15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人 工呼吸。就医。', '无资料', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (3065, 3193, '脱去污染的衣着，用流动清水冲洗。', '立即翻开上下眼睑，用流动清水冲洗15分钟。就医。', '脱离现场至空气新鲜处。呼吸困难时给输氧。呼吸停止时，立即进行人工呼吸。就医。', '误服者给饮足量温水，催吐，就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (3066, 3194, '无资料', '无资料 迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进', '行人工呼吸。就医。', '无资料', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (3067, 3195, '脱去污染的衣着，立即用大量流动清水彻底冲洗至少15分钟。就医.', '立即翻开上下眼睑，用流动清水或生理盐水冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。呼吸困难时给输氧。呼吸停止时，立即进行人工呼吸。就医。', '立即用水漱口，给饮牛奶或蛋清。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
