INSERT INTO `msds_first_aid` VALUES (3157, 3285, '立即脱去污染的衣着，用肥皂水及流动清水彻底冲洗污染的皮肤、头发、指甲等。就医。', '立即提起眼睑，用流动清水冲洗10分钟或用2％碳酸氢钠溶液冲洗。', '迅速脱离现场至空气新鲜处。注意保暖，呼吸困难时给输氧。呼吸停止时，立即进行人工 呼吸。就医。', '患者清醒时给饮大量温水，催吐，可用温水或1：5000高锰酸钾液彻底洗胃。立即就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
