INSERT INTO `msds_first_aid` VALUES (3190, 3318, '用肥皂水及清水彻底冲洗。再用甘油浸洗10min。就医。', '拉开眼睑，用流动清水冲洗15分钟。就医。', '脱离现场至空气新鲜处。就医。', '误服者，口服植物油15～30ml，催吐。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
