INSERT INTO `msds_first_aid` VALUES (3306, 3435, '后用水彻底清洗。或用大量流动清水冲洗至少15分钟。就医。', '立即提起眼睑，用大量流动清水或生理盐水彻底冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即 进行人工呼吸。就医。', '立即给饮植物油15～30mL。催吐。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
