INSERT INTO `msds_first_aid` VALUES (3357, 3486, '脱去污染的衣着，立即用流动清水彻底冲洗。', '立即提起眼睑，用大量流动清水彻底冲洗。', '迅速脱离现场至空气新鲜处。呼吸困难时给输氧。呼吸停止时，立即进行人工呼吸。就医。', '误服者给饮大量温水，催吐，就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
