INSERT INTO `msds_first_aid` VALUES (3913, 4043, '用肥皂水及清水彻底冲洗。就医。', '拉开眼睑，用流动清水冲洗15分钟。就医。', '脱离现场至空气新鲜处。呼吸困难时给输氧。呼吸停止时，立即进行人工呼吸。就医。', '误服者，给饮牛奶或蛋清。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (3914, 4044, '立即脱去污染的衣着，用甘油、聚乙烯乙二醇或聚乙烯乙二醇和酒精混合液 (7:3)抹洗， 然后用水彻底清洗。或用大量流动清水冲洗至少15分钟。就医。', '立即提起眼睑，用大量流动清水或生理盐水彻底冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即 进行人工呼吸。就医。', '立即给饮植物油15～30mL。催吐。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
