INSERT INTO `msds_first_aid` VALUES (3949, 4080, '立即脱去污染的衣着，用肥皂水及清水彻底冲洗。注意手、足和指甲等部位。', '立即提起眼睑，用大量流动清水或生理盐水冲洗。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。必要时进行人工呼吸。就医。', '误服者给漱口，饮水，洗胃后口服活性炭，再给以导泻。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
