INSERT INTO `msds_first_aid` VALUES (3964, 4095, '脱去污染的衣着，立即用水冲洗至少15分钟。', '立即提起眼睑，用流动清水或生理盐水冲洗至少15分钟。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。必要时进行人工呼吸。就医。', '误服者给饮大量温水，催吐，就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
