INSERT INTO `msds_first_aid` VALUES (4056, 4187, '脱去污染的衣着，用流动清水冲洗。', '立即翻开上下眼睑，用流动清水冲洗15分钟。就医。', '脱离现场至空气新鲜处。就医。', '误服者用水漱口，饮足量温水，催吐。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
