INSERT INTO `msds_first_aid` VALUES (4066, 4197, '脱去污染的衣着，用流动清水冲洗。', '立即翻开上下眼睑，用流动清水冲洗。', '脱离现场至空气新鲜处。', '误服者给饮足量温水，催吐，就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4067, 4198, '脱去污染的衣着，用肥皂水及清水彻底冲洗。', '立即翻开上下眼睑，用流动清水冲洗15分钟。就医。', '脱离现场至空气新鲜处。注意保暖，静卧休息。就医。', '误服者用水漱口，饮牛奶或蛋清，立即就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
