INSERT INTO `msds_first_aid` VALUES (4102, 4233, '立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤至少15分钟。如有不适，就医。', '用大量水彻底冲洗至少15分钟。如有不适，就医。', '立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给予吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止，立即进行心肺复苏术。立即就医。', '禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4103, 4234, '立即脱去污染的衣着，用肥皂水和清水彻底冲洗皮肤至少15分钟。就医。', '立即提起眼睑，用流动清水或生理盐水彻底冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处，保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '漱口，禁止催吐。切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4104, 4235, '脱去污染的衣着，用肥皂水和清水彻底冲洗皮肤。', '提起眼睑，用流动清水或生理盐水冲洗。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即 进行人工呼吸。就医。', '饮足量温水，催吐。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4105, 4236, '脱去污染的衣着，用流动清水冲洗至少15分钟。若有灼伤，就医治疗。', '立即翻开上下眼睑，用流动清水冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处，保持呼吸道通畅。注意保暖，呼吸困难时给输氧。呼吸停止时，立即进行人工呼吸。就医。', '误服者给饮牛奶或蛋清。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4106, 4237, '立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤至少15分钟。如有不适，就医。', '用大量水彻底冲洗至少15分钟。提起眼睑，确保彻底冲洗。如有不适，就医。', '立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止，立即进行心肺复苏术。立即就医。', '禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4107, 4238, '立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。', '用大量水彻底冲洗至少15分钟。如有不适，就医。', '立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给予吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止，立即进行心肺复苏术。立即就医。', '禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4108, 4239, '立即脱去被污染的衣着和鞋袜。用大量肥皂水和流动清水彻底冲洗皮肤至少15-20分钟。特别注意清洗皮肤皱褶处、指甲缝和毛发等容易残留污染物的部位。避免使用有机溶剂（如乙醇、丙酮等）清洗，因为它们可能增加皮肤对多氯联苯的吸收。冲洗后立即就医。就医时应告知医生接触了多氯联苯，并提供相关的化学品安全技术说明书。被污染的衣物和鞋袜应妥善处理，不得重复使用，以免造成二次污染。', '立即提起眼睑，用大量流动清水或生理盐水彻底冲洗眼睛至少15-20分钟。冲洗时应将眼睑完全翻开，确保清水能够充分接触眼球的所有表面。冲洗时应转动眼球，使清水能够冲洗到眼球的各个部位。冲洗过程中应避免用力揉擦眼睛。冲洗后立即就医，并告知医生接触了多氯联苯。就医时应携带本化学品安全技术说明书，以便医生了解化学品的性质和毒性。多氯联苯对眼睛具有极强的刺激性和毒性，可能导致严重的眼部损伤，因此必须立即进行专业医疗处理。', '迅速将患者脱离现场至空气新鲜处，保持呼吸道通畅。如呼吸困难，应立即给氧。如呼吸停止，应立即进行人工呼吸或使用呼吸机辅助呼吸。立即就医，并告知医生患者吸入了多氯联苯。在等待医疗救援期间，应让患者保持安静，避免剧烈活动，以减少毒物的吸收和分布。密切观察患者的呼吸、脉搏、血压等生命体征。如患者出现意识丧失、呼吸困难、发绀等症状，应立即进行心肺复苏。就医时应提供详细的接触情况，包括接触时间、接触浓度、暴露环境等信息。', '立即漱口，清除口腔内的残留物。切勿催吐，因为多氯联苯具有极高的毒性，催吐可能导致毒物再次进入呼吸道，引起吸入性肺炎。切勿给患者饮用牛奶、蛋清或植物油，因为这些物质可能增加毒物的吸收。立即就医，并告知医生患者误服了多氯联苯。就医时应携带本化学品安全技术说明书。在等待医疗救援期间，应让患者保持安静，避免剧烈活动。密切观察患者的意识状态、呼吸、脉搏、血压等生命体征。如患者出现意识丧失、呼吸困难、发绀等症状，应立即进行心肺复苏。医生可能会根据患者的具体情况采取洗胃、活性炭吸附、血液净化等治疗措施。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4109, 4240, '立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤至少15分钟。如有不适，就医。', '立即提起眼睑，用大量流动清水或生理盐水彻底冲洗至少15分钟。如有不适，就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
