INSERT INTO `msds_first_aid` VALUES (4161, 4292, '立即脱去污染的衣着，用肥皂水和大量流动清水彻底冲洗皮肤至少15分钟。就医。', '立即提起眼睑，用大量流动清水或生理盐水彻底冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '误服者，立即漱口，禁止催吐。给饮牛奶或蛋清。就医。砷化合物中毒应立即就医，不可自行处理。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
