INSERT INTO `msds_first_aid` VALUES (4233, 4365, '脱去污染的衣着，立即用大量流动清水彻底冲洗至少15分钟。就医。', '立即翻开上下眼睑，用流动清水或生理盐水冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。呼吸困难时给输氧。呼吸停止时，立即进行人 工呼吸。就医。', '误服者漱口，饮牛奶或蛋清。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4234, 4366, '脱去污染的衣着，用流动清水冲洗。', '立即提起眼睑，用流动清水冲洗。', '脱离现场至空气新鲜处。必要时进行人工呼吸。就医。', '误服者立即漱口，给饮大量温水，催吐，用清水或硫代硫酸钠溶液洗胃。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4235, 4367, '若有冻伤，就医治疗。', '若有冻伤，就医治疗。 迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人', '工呼吸。就医。', '无资料', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4236, 4368, '脱去污染的衣着，立即用水冲洗至少15分钟。若有灼伤，就医治疗。', '立即提起眼睑，用流动清水或生理盐水冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。注意保暖，保持呼吸道通畅。必要时进行人工呼吸。就医。', '误服者立即漱口，给饮大量温水，催吐，就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4237, 4369, '脱去污染的衣着，用大量流动清水彻底冲洗。', '立即翻开上下眼睑，用流动清水或生理盐水冲洗。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。呼吸困难时给输氧。呼吸停止时，立即进行人 工呼吸。就医。', '误服者漱口，饮牛奶或蛋清足量温水，催吐，就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
