INSERT INTO `msds_first_aid` VALUES (4340, 4473, '脱去污染的衣着，用肥皂水和清水彻底冲洗皮肤。', '提起眼睑，用流动清水或生理盐水冲洗。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '饮足量温水，催吐。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4341, 4474, '脱去污染的衣着，用大量流动清水冲洗。', '提起眼睑，用流动清水或生理盐水冲洗。就医。', '进行人工呼吸。就医。', '饮足量温水，催吐。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4342, 4475, '脱去污染的衣着，用大量流动清水冲洗。', '提起眼睑，用流动清水或生理盐水冲洗。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '饮足量温水，催吐。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4343, 4476, '立即脱去污染的衣着，用大量流动清水冲洗至少15分钟。就医。', '立即提起眼睑，用大量流动清水或生理盐水彻底冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '用水漱口，给饮牛奶或蛋清。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4344, 4477, '脱去污染的衣着，用肥皂水和清水彻底冲洗皮肤。', '立即提起眼睑，用大量流动清水或生理盐水彻底冲洗至少15分钟。就医。', '进行人工呼吸。就医。', '饮足量温水，催吐。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4345, 4478, '立即脱去污染的衣着，用大量流动清水冲洗至少15分钟。就医。', '立即提起眼睑，用大量流动清水或生理盐水彻底冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即 进行人工呼吸。就医。', '用水漱口，给饮牛奶或蛋清。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4346, 4479, '用肥皂水及清水彻底冲洗。就医。', '拉开眼睑，用流动清水冲洗15分钟。就医。', '脱离现场至空气新鲜处。就医。', '禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4347, 4480, '脱去污染的衣着，用大量流动清水冲洗至少15分钟。如有灼伤，就医。', '立即提起眼睑，用大量流动清水或生理盐水彻底冲洗至少15分钟。冲洗时应轻轻转动眼球，确保清除所有残留物。如果佩戴隐形眼镜，应立即取下。高锰酸钙为强氧化剂，对眼睛有强烈刺激性和腐蚀性，可能导致角膜上皮缺损及角膜溃疡。无论症状如何，冲洗后必须立即就医，进行专业眼科检查和治疗。避免揉眼或自行使用任何眼药水。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '切勿催吐，因为高锰酸钙为强氧化剂，催吐可能导致食道和口腔的二次损伤。立即用清水漱口，饮用足量温水或牛奶稀释胃内物质。若患者意识清醒且无抽搐，可给予活性炭吸附。高锰酸钙具有腐蚀性，可能造成消化道灼伤，必须立即就医。就医时应告知医护人员摄入的化学品种类、时间和数量，以便进行针对性治疗。密切观察患者的生命体征和意识状态。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4348, 4481, '立即脱去污染的衣着，用大量流动清水冲洗至少15分钟。就医。', '立即提起眼睑，用大量流动清水或生理盐水彻底冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '用水漱口，给饮牛奶或蛋清。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4349, 4482, '立即脱去污染的衣着，用大量流动清水冲洗至少15分钟。就医。', '立即提起眼睑，用大量流动清水或生理盐水彻底冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '用水漱口，给饮牛奶或蛋清。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
