INSERT INTO `msds_first_aid` VALUES (4362, 4495, '脱去污染的衣着，立即用流动清水彻底冲洗。就医。', '立即提起眼睑，用大量流动清水或生理盐水冲洗。就医。', '迅速脱离现场至空气新鲜处。注意保暖，必要时进行人工呼吸。就医。', '误服者立即漱口，给饮牛奶或蛋清。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
