INSERT INTO `msds_first_aid` VALUES (4475, 4608, '脱去污染的衣着，用流动清水冲洗。', '提起眼睑，用流动清水或生理盐水冲洗。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '饮足量温水，催吐。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4476, 4609, '脱去污染的衣着，用肥皂水和清水彻底冲洗皮肤。', '提起眼睑，用流动清水或生理盐水冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '饮足量温水，催吐。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4477, 4610, '脱去污染的衣着，用肥皂水和大量清水彻底冲洗皮肤至少15分钟。如有不适，就医。', '立即提起眼睑，用大量流动清水或生理盐水彻底冲洗至少15分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '立即漱口并饮用大量水。切勿催吐。如发生呕吐，应保持头部低于臀部以防误吸。立即就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4478, 4611, '脱去污染的衣着，用肥皂水和清水彻底冲洗皮肤。', '提起眼睑，用流动清水或生理盐水冲洗。就医。', '脱离现场至空气新鲜处。就医。', '饮足量温水，催吐。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4479, 4612, '立即脱去污染的衣着，用大量流动清水冲洗至少15分钟。就医。', '立即提起眼睑，用大量流动清水或生理盐水彻底冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。呼吸心跳停止时，立即进行人工呼吸和胸外心脏按压术。', '误服者给饮大量温水，催吐，就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4480, 4613, '立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。', '用大量水彻底冲洗至少15分钟。如有不适，就医。 立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给于吸氧。如患者食入或', '吸入本物质，不得进行口对口人工呼吸。如果呼吸停止。立即进行心肺复苏术。立即就 医。', '禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4481, 4614, '立即脱去污染的衣着，用肥皂水和清水彻底冲洗皮肤至少15分钟。就医。', '立即提起眼睑，用流动清水或生理盐水彻底冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4482, 4615, '立即脱去污染的衣着，用流动清水或5%硫代硫酸钠溶液彻底冲洗至少20分钟。就医。', '提起眼睑，用流动清水或生理盐水冲洗。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。呼吸心跳停止时，立即进行人工呼吸（勿用口对口）和胸外心脏按压术。给吸入亚硝酸异戊酯，就医。', '饮足量温水，催吐。用1:5000高锰酸钾或5%硫代硫酸钠溶液洗胃。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4483, 4616, '立即脱去污染的衣着，用肥皂水和流动清水彻底冲洗皮肤至少15分钟。就医。', '立即翻开上下眼睑，用流动清水或生理盐水彻底冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '误服者漱口，饮牛奶或蛋清。禁止催吐。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4484, 4617, '立即脱去污染的衣着，用肥皂水和清水彻底冲洗皮肤至少15分钟。若有灼伤，按酸灼伤处理。就医。', '立即提起眼睑，用流动清水或生理盐水彻底冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '禁止催吐。误服者，口服牛奶、豆浆或蛋清。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4485, 4618, '立即脱去污染的衣着，用肥皂水和清水彻底冲洗皮肤至少15分钟。就医。', '立即提起眼睑，用流动清水或生理盐水彻底冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '禁止催吐。误服者，饮蛋清或牛奶。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4486, 4619, '立即脱去污染的衣着，用流动清水或5%硫代硫酸钠溶液彻底冲洗至少２０分钟。就医。', '提起眼睑，用流动清水或生理盐水冲洗。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。呼吸心跳停止时， 立即进行人工呼吸（勿用口对口）和胸外心脏按压术。给吸入亚硝酸异戊酯，就医。', '饮足量温水，催吐。用1:5000高锰酸钾或５％硫代硫酸钠溶液洗胃。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4487, 4620, '立即脱去污染的衣着，用肥皂水和清水彻底冲洗皮肤至少15分钟。就医。', '立即提起眼睑，用大量流动清水或生理盐水彻底冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '禁止催吐。误服者，饮蛋清或牛奶。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4488, 4621, '脱去污染的衣着，用大量流动清水彻底冲洗。', '立即翻开上下眼睑，用流动清水或生理盐水冲洗。就医。', '脱离现场至空气新鲜处。就医。', '误服者漱口，给饮牛奶或蛋清，就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4489, 4622, '立即脱去污染的衣着，用肥皂水和清水彻底冲洗皮肤至少15分钟。就医。', '立即提起眼睑，用流动清水或生理盐水彻底冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '禁止催吐。误服者漱口，给饮牛奶或蛋清。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4490, 4623, '脱去污染的衣着，用肥皂水及清水彻底冲洗。', '立即翻开上下眼睑，用流动清水冲洗15分钟。就医。', '迅速脱离现场至空气新鲜处。呼吸困难时给输氧。呼吸停止时，立即进行人工呼吸。就医。', '误服者给饮牛奶或蛋清。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4491, 4624, '脱去污染的衣着，用肥皂水及清水彻底冲洗。若有灼伤，就医治疗。', '立即提起眼睑，用流动清水或生理盐水冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。必要时进行人工呼吸。就医。', '患者清醒时立即漱口，给饮牛奶或蛋清。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4492, 4625, '立即脱去污染的衣着，用大量流动清水彻底冲洗皮肤至少15分钟。如有不适，就医。', '立即提起眼睑，用大量流动清水或生理盐水彻底冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处，保持呼吸道通畅。如呼吸困难，给氧。如呼吸停止，立即进行人工呼吸。就医。', '漱口，禁止催吐。切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
