INSERT INTO `msds_first_aid` VALUES (4554, 4687, '立即脱去污染的衣着，用大量流动清水彻底冲洗至少15分钟。就医。', '立即提起眼睑，用流动清水或生理盐水彻底冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '禁止催吐。误服者立即漱口，给饮牛奶或蛋清。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4555, 4688, '脱去污染的衣着，立即用流动清水彻底冲洗。注意手、足和指甲等部位。就医。', '立即提起眼睑，用流动清水冲洗10分钟或用2％碳酸氢钠溶液冲洗。就医。', '迅速脱离现场至空气新鲜处。给予2～4％碳酸氢钠溶液雾化吸入。呼吸困难时给输氧。呼吸停 止时，立即进行人工呼吸。就医。', '患者清醒时给饮大量温水，催吐，可用温水或1：5000高锰酸钾液彻底洗胃。或用2％碳酸氢钠 反复洗胃。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4556, 4689, '脱去污染的衣着，用肥皂水和清水彻底冲洗皮肤。', '提起眼睑，用流动清水或生理盐水冲洗。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即 进 行人工呼吸。就医。', '饮足量温水，催吐。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4557, 4690, '用流动清水冲洗。', '用流动清水冲洗。', '脱离现场。', '误服者给饮大量温水，催吐，就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
