INSERT INTO `msds_first_aid` VALUES (4576, 4710, '脱去污染的衣着，用肥皂水及清水彻底冲洗。', '立即翻开上下眼睑，用流动清水冲洗15分钟。就医。', '脱离现场至空气新鲜处。呼吸困难时给输氧。呼吸停止时，立即进行人工呼吸。就医。', '误服者用水漱口，饮足量温水，催吐，就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4577, 4711, '冻伤时，用大量水冲洗，不要脱去衣服，给予医疗护理。', '先用大量水冲洗几分钟，然后就医。', '新鲜空气，休息，必要时进行人工呼吸，给予医疗护理。', '禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
