INSERT INTO `msds_first_aid` VALUES (4580, 4714, '立即脱去污染的衣着，用肥皂水及流动清水彻底冲洗污染的皮肤、头发、指甲等。就医。', '提起眼睑，用流动清水或生理盐水冲洗。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即 进行人工呼吸。就医。', '饮足量温水，催吐。用清水或2％～5％碳酸氢钠溶液洗胃。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
