INSERT INTO `msds_first_aid` VALUES (4600, 4734, '脱去污染的衣着，用肥皂水及清水彻底冲洗。', '立即翻开上下眼睑，用流动清水冲洗15分钟。就医。', '迅速脱离现场至空气新鲜处。呼吸困难时给输氧。呼吸停止时，立即进行人工呼吸。就医。', '误服者给饮牛奶或蛋清。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
