INSERT INTO `msds_first_aid` VALUES (4674, 4808, '立即脱去污染的衣着，用大量流动清水冲洗至少15分钟。就医。', '立即提起眼睑，用大量流动清水或生理盐水彻底冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '误服者，用水漱口，给饮牛奶或蛋清。催吐。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4675, 4809, '用流动清水冲洗。就医。', '拉开眼睑，用流动清水冲洗15分钟。就医。', '脱离现场至空气新鲜处。呼吸困难时给输氧。呼吸停止时，立即进行人工呼吸。就医。', '误服者，饮牛奶或蛋清。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4676, 4810, '脱去污染的衣着，用大量流动清水彻底冲洗。', '立即翻开上下眼睑，用流动清水或生理盐水冲洗。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。呼吸困难时给输氧。呼吸停止时，立即进行人工呼吸。就医。', '切勿给失去知觉者从嘴里喂食任何东西。用水漱口。切勿催吐。立即就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4677, 4811, '脱去污染的衣着，用流动清水冲洗。', '立即翻开上下眼睑，用流动清水冲洗15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。呼吸困难时给输氧。呼吸停止时，立即进行人工呼吸。就医。', '无资料', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4678, 4812, '脱去污染的衣着，用肥皂水和大量清水彻底冲洗皮肤。如有不适，就医。', '提起眼睑，用流动清水或生理盐水冲洗至少15分钟。如有不适，就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '无资料。本品为气体，一般不会经口摄入。如发生误服，立即就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4679, 4813, '脱去污染的衣着，用肥皂水和清水彻底冲洗皮肤。如有不适，就医。', '立即提起眼睑，用大量流动清水或生理盐水彻底冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处，保持呼吸道通畅。如呼吸困难，给氧。如呼吸停止，立即进行人工呼吸。就医。', '误服后，立即漱口，禁止催吐。给饮牛奶或蛋清。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4680, 4814, '立即脱去污染的衣着，用大量流动清水彻底冲洗至少20-30分钟。特别注意清洗皮肤皱褶处、指甲缝等隐蔽部位。冲洗时应避免水流将污染物扩散到身体其他部位。如果出现皮肤灼伤，按照化学灼伤处理：用大量清水冲洗后，用2.5%葡萄糖酸钙凝胶涂抹灼伤部位，反复涂抹直至疼痛缓解。立即就医，并告知医生接触了六氟化铀。就医时应携带MSDS资料。对污染的衣物和物品应按放射性废物处理。', '立即翻开上下眼睑，用流动清水或生理盐水冲洗至少20-30分钟。冲洗时应让水流充分冲洗眼球和眼睑内侧，确保彻底清除化学物质。如果出现眼睑痉挛，可使用眼睑撑开器。冲洗后立即就医，并告知医生接触了六氟化铀。就医时应携带MSDS资料。眼部灼伤可能需要眼科专科治疗。', '迅速脱离现场至空气新鲜处，将受害人转移到上风处。保持呼吸道通畅，解开衣领。呼吸困难时给输氧，氧流量4-6L/min。如出现呼吸停止，立即进行人工呼吸或使用呼吸机。立即就医，并告知医生接触了六氟化铀。就医时应携带MSDS资料。医院应进行胸部X光检查、血气分析、肺功能检查等。密切观察24-48小时，警惕迟发性肺水肿。对严重中毒者，应进行血液净化治疗（如血液透析）以清除氟化物。', '误服者立即漱口，但不要催吐（因六氟化铀具有强腐蚀性，催吐可能导致食管穿孔）。给饮足量温水或牛奶，以稀释胃内容物。立即送放射病专科医院或职业病防治院就医。就医时应携带MSDS资料。医院应进行胃镜检查、血氟检测、肾功能检查、肝功能检查等。对严重中毒者，应进行血液净化治疗。密切监测生命体征，特别是心率和心律（氟化物可导致低钙血症和心律失常）。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4681, 4815, '脱去污染的衣着，用肥皂水和清水彻底冲洗皮肤。如有不适，就医。', '立即提起眼睑，用大量流动清水或生理盐水彻底冲洗至少15分钟。如有不适，就医。', '迅速脱离现场至空气新鲜处，保持呼吸道通畅。如呼吸困难，给氧。如呼吸停止，立即进行人工呼吸。就医。', '误服后，立即漱口，禁止催吐。给饮牛奶或蛋清。就医。', NULL, NULL, '如出现窒息症状，应立即就医。在等待医疗救援时，确保患者处于通风良好的环境中，必要时进行人工呼吸或心肺复苏。', NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4682, 4816, '立即脱去污染的衣着，用肥皂水和大量流动清水彻底冲洗皮肤。就医。', '立即提起眼睑，用大量流动清水或生理盐水彻底冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '漱口，禁止催吐，给饮牛奶或蛋清。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4683, 4817, '脱去污染的衣着，用肥皂水和清水彻底冲洗皮肤。', '提起眼睑，用流动清水或生理盐水冲洗。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '饮足量温水，催吐。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4684, 4818, '立即脱去污染的衣着，用肥皂水和大量清水彻底冲洗皮肤至少15分钟。就医。', '立即提起眼睑，用大量流动清水或生理盐水彻底冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '立即漱口，禁止催吐。给饮牛奶或蛋清。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4685, 4819, '立即脱去污染的衣着，用肥皂水和大量清水彻底冲洗皮肤至少15分钟。如有灼伤，应按照化学灼伤处理。冲洗时应注意避免化学品扩散到未污染的皮肤区域。就医。如出现皮肤刺激、红肿、水疱等症状，应立即就医。', '立即提起眼睑，用大量流动清水或生理盐水彻底冲洗至少15分钟。冲洗时应将眼睑充分翻开，确保眼球和结膜囊得到充分冲洗。避免揉擦眼睛。冲洗后立即就医。如出现眼睛疼痛、红肿、流泪、视力模糊等症状，应立即就医。', '迅速脱离现场至空气新鲜处，保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸，并尽快就医。就医时应告知医生患者接触了六氯-1,3-丁二烯，以便医生采取相应的治疗措施。如出现咳嗽、胸闷、呼吸困难、意识障碍等症状，应立即就医。', '误服者，立即漱口，禁止催吐，以免引起吸入性肺炎。给饮牛奶、豆浆或蛋清，以保护胃黏膜。立即就医。就医时应告知医生患者误服了六氯-1,3-丁二烯，并携带产品标签或安全技术说明书。如出现口腔灼伤、恶心、呕吐、腹痛、腹泻等症状，应立即就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4686, 4820, '脱去污染的衣着，用肥皂水和清水彻底冲洗皮肤。', '提起眼睑，用流动清水或生理盐水冲洗。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行 人工呼吸。就医。', '漱口，禁止催吐，给饮牛奶或蛋清。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4687, 4821, '立即脱去污染的衣着，用大量流动清水彻底冲洗。就医。', '立即分开眼睑，用流动清水或生理盐水彻底冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '误服者，饮足量温水，催吐。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4688, 4822, '脱去污染的衣着，用大量流动清水彻底冲洗。', '立即翻开上下眼睑，用流动清水或生理盐水冲洗。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。呼吸困难时给输氧。呼吸停止时，立即进行人 工呼吸。就医。', '给饮足量温水，催吐，就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4689, 4823, '脱去污染的衣着，用肥皂水和清水彻底冲洗皮肤。', '立即提起眼睑，用大量流动清水或生理盐水彻底冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '漱口，禁止催吐。给饮牛奶或蛋清。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4690, 4824, '脱去污染的衣着，用肥皂水和清水彻底冲洗皮肤。', '立即提起眼睑，用大量流动清水或生理盐水彻底冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '漱口，禁止催吐。给饮牛奶或蛋清。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4691, 4825, '立即脱去污染的衣着，用大量肥皂水和清水彻底冲洗皮肤至少15分钟。如有不适，就医。', '立即提起眼睑，用大量流动清水或生理盐水彻底冲洗至少15分钟。如有不适，就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。立即就医。', '禁止催吐。切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4692, 4826, '立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。', '用大量水彻底冲洗至少15分钟。如有不适，就医。', '立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给予吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止，立即进行心肺复苏术。立即就医。', '禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4693, 4827, '脱去污染的衣着，用肥皂水和清水彻底冲洗皮肤。', '提起眼睑，用流动清水或生理盐水冲洗。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '禁止催吐。漱口，给饮牛奶或蛋清。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
