INSERT INTO `msds_first_aid` VALUES (4726, 4860, '脱去污染的衣着，用大量流动清水彻底冲洗。就医。', '立即翻开上下眼睑，用流动清水或生理盐水冲洗。 迅速脱离现场至空气新鲜处。保持呼吸道通畅。呼吸困难时给输氧。呼吸停止时，立即进', '行人工呼吸。就医。', '误服者给饮牛奶或蛋清。洗胃。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
