INSERT INTO `msds_first_aid` VALUES (4728, 4862, '立即脱去污染的衣物。用大量肥皂水和清水冲洗皮肤。如有不适，就医。', '用大量水彻底冲洗至少15分钟。如有不适，就医。', '立即将患者移到新鲜空气处，保持呼吸畅通。如果呼吸困难，给予吸氧。如患者食入或吸入本物质，不得进行口对口人工呼吸。如果呼吸停止，立即进行心肺复苏术。立即就医。', '禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4729, 4863, '立即脱去污染的衣着，用肥皂水和大量流动清水彻底冲洗皮肤至少15分钟。就医。', '立即提起眼睑，用大量流动清水或生理盐水彻底冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '患者清醒时立即漱口，禁止催吐。给饮牛奶或蛋清。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4730, 4864, '用肥皂水及清水彻底冲洗。就医。', '拉开眼睑，用流动清水冲洗15分钟。就医。', '脱离现场至空气新鲜处。呼吸困难时给输氧。呼吸停止时，立即进行人工呼吸。就医。', '误服者，饮适量温水，催吐。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4731, 4865, '立即脱去污染的衣着，用大量流动清水冲洗至少15分钟。就医。', '立即提起眼睑，用大量流动清水或生理盐水彻底冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人 工呼吸。就医。', '误服者立即漱口，给牛奶、蛋清、植物油等口服，不可催吐。立即就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4732, 4866, '立即脱去污染的衣着，用肥皂水和清水彻底冲洗皮肤。就医。', '立即提起眼睑，用大量流动清水或生理盐水彻底冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。呼吸心跳停止时，立即进 行人工呼吸（勿用口对口）和胸外心脏按压术。给吸入亚硝酸异戊酯，就医。', '饮足量温水，催吐。用1:5000高锰酸钾或５％硫代硫酸钠溶液洗胃。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4733, 4867, '脱去污染的衣着，立即用大量流动清水彻底冲洗至少15分钟，就医。', '立即翻开上下眼睑，用流动清水或生理盐水冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。呼吸困难时给输氧。呼吸停止时，立即进行人工呼吸。就医。', '误服者立即嗽口，给饮牛奶或蛋清。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4734, 4868, '立即脱去污染的衣着，用大量流动清水冲洗至少15分钟。就医。', '立即提起眼睑，用大量流动清水或生理盐水彻底冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行 人工呼吸。就医。', '饮足量温水，催吐。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
