INSERT INTO `msds_first_aid` VALUES (4820, 4954, '脱去污染的衣着，用肥皂水和清水彻底冲洗皮肤。就医。', '立即提起眼睑，用大量流动清水或生理盐水彻底冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '饮足量温水，催吐。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4821, 4955, '脱去污染的衣着，立即用水冲洗至少15分钟。就医。', '立即提起眼睑，用流动清水或生理盐水冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。呼吸困难时给输氧。呼吸停止时，立即进行人工呼吸。就医。', '患者清醒时给充分漱口、饮水，就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4822, 4956, '立即脱去污染的衣着，用大量流动清水彻底冲洗皮肤至少15分钟。如有不适，就医。', '立即提起眼睑，用大量流动清水或生理盐水彻底冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '禁止催吐。切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4823, 4957, '脱去污染的衣着，立即用流动清水彻底冲洗。', '立即提起眼睑，用流动清水或生理盐水冲洗至少15分钟。就医。', '脱离现场至空气新鲜处。保持呼吸道通畅。必要时进行人工呼吸。就医。', '误服者立即漱口，给饮牛奶或蛋清。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
