INSERT INTO `msds_first_aid` VALUES (4856, 4990, '脱去污染的衣着，用大量流动清水彻底冲洗。就医。', '立即翻开上下眼睑，用流动清水或生理盐水冲洗。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。呼吸困难时给输氧。呼吸停止时，立即进行人工呼吸。就医。', '误服者立即漱口，给饮牛奶或蛋清。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4857, 4991, '立即脱去污染的衣着，用大量流动清水冲洗至少15分钟。就医。', '立即提起眼睑，用大量流动清水或生理盐水彻底冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '用水漱口，给饮牛奶或蛋清。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4858, 4992, '用肥皂水及清水彻底冲洗。就医。', '拉开眼睑，用流动清水冲洗15分钟。就医。', '脱离现场至空气新鲜处。就医。', '误服者，饮适量温水，催吐。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4859, 4993, '脱去污染的衣着，用流动清水冲洗15分钟。', '立即翻开上下眼睑，用流动清水冲洗15分钟。就医。', '脱离现场至空气新鲜处。如呼吸困难，给输氧。就医。', '误服者用水漱口，给饮牛奶或蛋清。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4860, 4994, '立即脱去污染的衣着，用流动清水或5%硫代硫酸钠溶液彻底冲洗至少20分钟。就医。', '立即提起眼睑，用大量流动清水或生理盐水彻底冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。呼吸心跳停止时，立即进行人工呼吸（勿用口对口）和胸外心脏按压术。给吸入亚硝酸异戊酯，就医。', '饮足量温水，催吐。用1:5000高锰酸钾或5%硫代硫酸钠溶液洗胃。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4861, 4995, '立即脱去污染的衣着，用大量流动清水冲洗至少15分钟。就医。', '立即提起眼睑，用大量流动清水或生理盐水彻底冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '用水漱口，给饮牛奶或蛋清。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4862, 4996, '脱去污染的衣着，用肥皂水和清水彻底冲洗皮肤。就医。', '提起眼睑，用流动清水或生理盐水冲洗。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '饮足量温水，催吐。用2％～5％硫酸钠溶液洗胃，导泻。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
