INSERT INTO `msds_first_aid` VALUES (4929, 5063, '脱去污染的衣着，用大量流动清水彻底冲洗。', '立即翻开上下眼睑，用流动清水或生理盐水冲洗。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。呼吸困难时给输氧。呼吸停止时，立即进行人 工呼吸。就医。', '误服者漱口，饮牛奶或蛋清，就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4930, 5064, '脱去污染的衣着，用肥皂水和清水彻底冲洗皮肤。', '提起眼睑，用流动清水或生理盐水冲洗。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '饮足量温水，催吐。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4931, 5065, '立即脱去污染的衣着，用大量流动清水冲洗20-30分钟。如有条件，可先用肥皂水清洗，再用清水彻底冲洗。如有灼伤或不适感，立即就医。注意：三苯基氯硅烷接触皮肤会水解产生氯化氢，可能造成化学灼伤。', '立即翻开上下眼睑，用大量流动清水或生理盐水彻底冲洗至少15分钟。冲洗时转动眼球，确保彻底清除化学品。冲洗后立即就医，即使没有明显症状。注意：三苯基氯硅烷接触眼睛会水解产生氯化氢，可能导致角膜严重损伤。', '迅速脱离现场至空气新鲜处，保持呼吸道通畅。如呼吸困难，给予氧气。如呼吸停止，立即进行人工呼吸。注意保暖并立即就医。注意：三苯基氯硅烷蒸气或水解产生的氯化氢气体可引起呼吸道严重刺激和肺部损伤。', '切勿催吐。立即给予牛奶、蛋清或活性炭悬浮液(200-300g溶于200-300ml水中)以稀释和保护胃黏膜。立即就医。注意：三苯基氯硅烷在胃中会水解产生氯化氢，可能导致严重胃肠道损伤。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4932, 5066, '用肥皂水及清水彻底冲洗。就医。', '拉开眼睑，用流动清水冲洗15分钟。就医。', '脱离现场至空气新鲜处。就医。', '误服者，饮适量温水，催吐。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4933, 5067, '脱去污染的衣着，用流动清水冲洗。', '立即翻开上下眼睑，用流动清水或生理盐水冲洗。就医。', '脱离现场至空气新鲜处。就医。', '给饮足量温水，催吐，就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (4934, 5068, '立即脱去污染的衣着，用大量肥皂水和清水冲洗皮肤。如有不适，就医。', '立即提起眼睑，用大量流动清水或生理盐水彻底冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '误服者，口服牛奶、豆浆或蛋清。切勿给失去知觉者从嘴里喂食任何东西。立即就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
