INSERT INTO `msds_first_aid` VALUES (5040, 5174, '立即用水冲洗至少15分钟。或用2%碳酸氢钠溶液冲洗。若有灼伤，就医治疗。', '立即提起眼睑，用流动清水或生理盐水冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。呼吸困难时给输氧。给予2-4%碳酸氢钠溶液雾化吸入。就医。', '误服者给牛奶、蛋清、植物油等口服，不可催吐。立即就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
