INSERT INTO `msds_first_aid` VALUES (5115, 5249, '脱去污染的衣着，用肥皂水及清水彻底冲洗。', '立即翻开上下眼睑，用流动清水冲洗15分钟。就医。', '脱离现场至空气新鲜处。注意保暖，静卧休息。严重者立即就医。', '误服者用水漱口，立即就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
