INSERT INTO `msds_first_aid` VALUES (5208, 5343, '脱去污染的衣着，用流动清水冲洗。', '提起眼睑，用流动清水或生理盐水冲洗。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人 工呼吸。就医。', '无资料', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (5209, 5344, '脱去污染的衣着，用肥皂水及清水彻底冲洗。', '立即翻开上下眼睑，用流动清水冲洗15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。呼吸困、难时给输氧。呼吸停止时，立即 进行人工呼吸。就医。注意防治肺水肿。', '无资料', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (5210, 5345, '无资料', '立即翻开上下眼睑，用流动清水冲洗15分钟。就压。 迅速脱离现场至空气新鲜处。保持呼吸道通畅。呼吸困难时给输氧。呼吸停止时，立即进', '行人工呼吸。就医。', '无资料', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (5211, 5346, '脱去污染的衣着，用流动清水冲洗。', '立即提起眼睑，用流动清水冲洗。', '迅速脱离现场至空气新鲜处。注意保暖，保持呼吸道通畅。必要时进行人工呼吸。就医。', '误服者给饮大量温水，催吐，就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
