INSERT INTO `msds_first_aid` VALUES (5342, 5477, '用肥皂水及清水彻底冲洗。就医。', '拉开眼睑，用流动清水冲洗15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '误服者，口服牛奶、豆浆或蛋清，催吐。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
