INSERT INTO `msds_first_aid` VALUES (5508, 5643, '脱去污染的衣着，用大量流动清水彻底冲洗。就医。', '立即翻开上下眼睑，用流动清水或生理盐水冲洗。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。呼吸困难时给输氧。呼吸停止时，立即进行人工呼吸。就医。', '漱口，给饮牛奶或蛋清。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (5509, 5644, '脱去污染的衣着，用大量流动清水彻底冲洗。', '立即翻开上下眼睑，用流动清水或生理盐水冲洗。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。呼吸困难时给输氧。呼吸停止时，立即进行人工呼吸。就医。', '误服者漱口，给饮牛奶或蛋清，就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (5510, 5645, '无资料', '无资料 迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，', '立即进行人工呼吸。就医。', '无资料', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
