INSERT INTO `msds_first_aid` VALUES (5560, 5695, '用肥皂水及清水彻底冲洗。就医。', '拉开眼睑，用流动清水冲洗15分钟。就医。', '脱离现场至空气新鲜处。呼吸困难时给输氧。就医。', '误服者，饮适量温水，催吐。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (5561, 5696, '脱去污染的衣者，用肥皂水及清水彻底冲洗。', '立即提起眼睑，用大量流动清水或生理盐水冲洗。', '脱离现场至空气新鲜处。必要时进行人工呼吸。就医。', '误服者给饮大量温水，催吐，用清水或硫代硫酸钠溶液洗胃。给饮牛奶或蛋清。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_first_aid` VALUES (5562, 5697, '脱去污染的衣着，用肥皂水和清水彻底冲洗皮肤。如有不适，就医。', '立即提起眼睑，用大量流动清水或生理盐水彻底冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', '饮足量温水，催吐。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
