INSERT INTO `msds_first_aid` VALUES (5731, 5866, '立即脱去污染的衣着，用肥皂水和清水彻底冲洗皮肤至少15分钟。就医。', '立即翻开上下眼睑，用流动清水或生理盐水彻底冲洗至少15分钟。就医。', '迅速脱离现场至空气新鲜处。保持呼吸道通畅。呼吸困难时给输氧。呼吸停止时，立即进行人工呼吸。就医。', '禁止催吐，切勿给失去知觉者从嘴里喂食任何东西。立即呼叫医生或中毒控制中心。就医。', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_handling_storage` VALUES (2887, 3021, '操作人员必须经过专门培训，严格遵守操作规程。建议操作人员佩戴自吸过滤式防毒面具（全面罩），穿连衣式胶布防毒衣，戴橡胶手套。远离火种、热源，工作场所严禁吸烟。使用防爆型的通风系统和设备。防止蒸气泄漏到工作场所空气中。避免与氧化剂、酸类、碱类接触。搬运时要轻装轻卸，防止包装及容器损坏。配备相应品种和数量的消防器材及泄漏应急处理设备。倒空的容器可能残留有害物。操作现场不得吸烟、饮水、进食。', '储存于阴凉、通风仓间内。远离火种、热源。专人保管。保持容器密封。防止受潮和雨淋。 防止阳光曝晒。应与氧化剂、酸类、碱类分开存放。不能与粮食、食物、种子、饲料、各 种日用品混装、混运。操作现场不得吸烟、饮水、进食。搬运时要轻装轻卸，防止包装及 容器损坏。分装和搬运作业要注意个人防护。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:27', '', NULL);
INSERT INTO `msds_handling_storage` VALUES (2888, 3022, '操作人员必须经过专门培训，严格遵守操作规程。建议操作人员佩戴自吸过滤式防毒面具（半面罩），戴化学安全防护眼镜，穿防毒物渗透工作服，戴橡胶耐油手套。远离火种、热源，工作场所严禁吸烟。使用防爆型的通风系统和设备。避免与氧化剂、碱类接触。搬运时要轻装轻卸，防止包装及容器损坏。配备相应品种和数量的消防器材及泄漏应急处理设备。倒空的容器可能残留有害物。', '储存于阴凉、通风仓间内。远离火种、热源。专人保管。保持容器密封。防潮、防晒。应 与氧化剂、碱类、食用化工原料分开存放。不能与粮食、食物、种子、饲料、各种日用 品混装、混运。操作现场不得吸烟、饮水、进食。搬运时要轻装轻卸，防止包装及容器损 坏。分装和搬运作业要注意个人防护。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:27', '', NULL);
INSERT INTO `msds_handling_storage` VALUES (2889, 3023, '操作人员必须经过专门培训，严格遵守操作规程。建议操作人员佩戴自吸过滤式防毒面具（全面罩），穿聚乙烯防毒服，戴橡胶手套。远离火种、热源，工作场所严禁吸烟。使用防爆型的通风系统和设备。避免与氧化剂、酸类接触。搬运时要轻装轻卸，防止包装及容器损坏。配备相应品种和数量的消防器材及泄漏应急处理设备。倒空的容器可能残留有害物。应严格执行极毒物品\"五双\"管理制度。', '储存于阴凉、通风的库房。远离火种、热源。包装密封。应与氧化剂、酸类、食用化学品分开存放，切忌混储。配备相应品种和数量的消防器材。储区应备有合适的材料收容泄漏物。应严格执行极毒物品\"五双\"管理制度。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:28', '', NULL);
INSERT INTO `msds_handling_storage` VALUES (2890, 3024, '操作人员必须经过专门培训，严格遵守操作规程。建议操作人员佩戴自吸过滤式防毒面具（全面罩），穿聚乙烯防毒服，戴橡胶手套。远离火种、热源，工作场所严禁吸烟。使用防爆型的通风系统和设备。避免与氧化剂接触。搬运时要轻装轻卸，防止包装及容器损坏。配备相应品种和数量的消防器材及泄漏应急处理设备。倒空的容器可能残留有害物。应严格执行极毒物品\"五双\"管理制度。', '储存于阴凉、通风仓间内。远离火种、热源。管理应按“五双”管理制度执行。保持容器 密封。防止受潮和雨淋。防止阳光曝晒。应与氧化剂、食用化工原料分开存放。不能与粮 食、食物、种子、饲料、各种日用品混装、混运。操作现场不得吸烟、饮水、进食。搬运 时要轻装轻卸，防止包装及容器损坏。分装和搬运作业要注意个人防护。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:28', '', NULL);
INSERT INTO `msds_handling_storage` VALUES (2891, 3025, '操作人员必须经过专门培训，严格遵守操作规程。建议操作人员佩戴自吸过滤式防毒面具（全面罩），戴化学安全防护眼镜，穿防毒物渗透工作服，戴橡胶耐油手套。远离火种、热源，工作场所严禁吸烟。使用防爆型的通风系统和设备。防止粉尘泄漏到工作场所空气中。避免与氧化剂、碱类接触。搬运时要轻装轻卸，防止包装及容器损坏。配备相应品种和数量的消防器材及泄漏应急处理设备。倒空的容器可能残留有害物。', '储存于阴凉、通风的库房。远离火种、热源。保持容器密闭。储存在干燥、阴凉和通风处。远离热源、火花、明火和热表面。存储于远离不相容材料和食品容器的地方。储存温度一般不应高于32℃，相对湿度一般不应高于80%。应与氧化剂、碱类、食用化学品分开存放，切忌混储。配备相应品种和数量的消防器材。储区应备有合适的材料收容泄漏物。应严格执行极毒物品\"五双\"管理制度。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:28', '', NULL);
INSERT INTO `msds_handling_storage` VALUES (2892, 3026, '操作人员必须经过专门培训，严格遵守操作规程。建议操作人员佩戴自吸过滤式防毒面具（半面罩），戴化学安全防护眼镜，穿防毒物渗透工作服，戴防化学品手套。远离火种、热源，工作场所严禁吸烟。使用防爆型的通风系统和设备。防止粉尘泄漏到工作场所空气中。避免与氧化剂接触。搬运时要轻装轻卸，防止包装及容器损坏。配备相应品种和数量的消防器材及泄漏应急处理设备。倒空的容器可能残留有害物。', '储存于阴凉、通风仓间内。远离火种、热源。保持容器密封。防潮、防晒。寒冷季节要 注意保持库温在结晶点以上，防止冻裂容器及变质。专人保管。搬运时要轻装轻卸，防 止包装及容器损坏。分装和搬运作业要注意个人防护。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:28', '', NULL);
INSERT INTO `msds_handling_storage` VALUES (2893, 3027, '操作人员必须经过专门培训，严格遵守操作规程。建议操作人员佩戴自吸过滤式防毒面具（半面罩），戴化学安全防护眼镜，穿防毒物渗透工作服，戴防化学品手套。远离火种、热源，工作场所严禁吸烟。使用防爆型的通风系统和设备。防止粉尘泄漏到工作场所空气中。避免与氧化剂、碱类接触。搬运时要轻装轻卸，防止包装及容器损坏。配备相应品种和数量的消防器材及泄漏应急处理设备。倒空的容器可能残留有害物。', '储存于阴凉、通风仓间内。远离火种、热源。专人保管。保持容器密封。避光保存。防止 受潮和雨淋。防止阳光曝晒。应与氧化剂、碱类、食用化工原料分开存放。不能与粮食、 食物、种子、饲料、各种日用品混装、混运。操作现场不得吸烟、饮水、进食。搬运时要 轻装轻卸，防止包装及容器损坏。分装和搬运作业要注意个人防护。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:29', '', NULL);
INSERT INTO `msds_handling_storage` VALUES (2894, 3028, '操作人员必须经过专门培训，严格遵守操作规程。建议操作人员佩戴自吸过滤式防毒面具（全面罩），戴化学安全防护眼镜，穿工作服(防腐材料制作)，戴橡皮手套。远离火种、热源，工作场所严禁吸烟。使用防爆型的通风系统和设备。防止蒸气泄漏到工作场所空气中。避免与氧化剂、水、强碱接触。搬运时要轻装轻卸，防止包装及容器损坏。配备相应品种和数量的消防器材及泄漏应急处理设备。倒空的容器可能残留有害物。', '储存于阴凉、通风仓间内。远离火种、热源。防止阳光直射。保持容器密封。应与氧化剂、 碱类、食用化工原料分开存放。分装和搬运作业要注意个人防护。搬运时要轻装轻卸，防止 包装及容器损坏。运输按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:30', '', NULL);
INSERT INTO `msds_handling_storage` VALUES (2895, 3029, '操作人员必须经过专门培训，严格遵守操作规程。建议操作人员佩戴自吸过滤式防毒面具（半面罩），戴化学安全防护眼镜，穿防静电工作服，戴橡胶耐油手套。远离火种、热源，工作场所严禁吸烟。使用防爆型的通风系统和设备。防止蒸气泄漏到工作场所空气中。避免与还原剂、促进剂、强酸、强碱接触。搬运时要轻装轻卸，防止包装及容器损坏，避免摩擦、震动、撞击。配备相应品种和数量的消防器材及泄漏应急处理设备。倒空的容器可能残留有害物。', '火花、明火和热表面。采取措施防止静电积累。 保持容器密闭。储存在干燥、阴凉和通风处。远离热源、火花、明火和热表面。存储于远 离不相容材料和食品容器的地方。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:30', '', NULL);
INSERT INTO `msds_handling_storage` VALUES (2896, 3030, '操作人员必须经过专门培训，严格遵守操作规程。建议操作人员佩戴自吸过滤式防毒面具（半面罩），戴化学安全防护眼镜，穿防静电工作服，戴橡胶耐油手套。远离火种、热源，工作场所严禁吸烟。使用防爆型的通风系统和设备。防止蒸气泄漏到工作场所空气中。避免与还原剂、促进剂、强酸、强碱接触。搬运时要轻装轻卸，防止包装及容器损坏，避免摩擦、震动、撞击。配备相应品种和数量的消防器材及泄漏应急处理设备。倒空的容器可能残留有害物。', '火花、明火和热表面。采取措施防止静电积累。 保持容器密闭。储存在干燥、阴凉和通风处。远离热源、火花、明火和热表面。存储于远 离不相容材料和食品容器的地方。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:30', '', NULL);
INSERT INTO `msds_handling_storage` VALUES (2897, 3031, '操作人员须经过专门培训，严格遵守操作规程。保持系统密闭并配备局部排风。使用防爆型设备并对钢瓶、管线进行接地跨接，防止静电。避免吸入高浓度蒸气，避免与氧化剂接触。搬运钢瓶时应佩戴安全帽、装设防震环，防止跌落、滚动和撞击。工作场所严禁吸烟及明火。', '储存于阴凉、干燥、通风良好的不燃库房，远离火种、热源和直射阳光。采用防爆型照明、通风设施，禁止使用易产生火花的工具。钢瓶应直立固定，阀门加防护罩。与氧化剂、强酸等分开存放。储区应备有泄漏应急处理设备、空气呼吸器及适当的收容材料。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:30', '', NULL);
INSERT INTO `msds_handling_storage` VALUES (2898, 3032, '无资料', '储存于阴凉、通风仓间内。远离火种、热源。保持容器密封。防潮、防晒。专人保管。应 与氧化剂、碱类、食用化工原料分开存放。不能与粮食、食物、种子、饲料、各种日用品 混装、混运。操作现场不得吸烟、饮水、进食。搬运时要轻装轻卸，防止包装及容器损坏。 分装和搬运作业要注意个人防护。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:31', '', NULL);
INSERT INTO `msds_handling_storage` VALUES (2899, 3033, '操作人员必须经过专门培训，严格遵守操作规程。建议操作人员佩戴防毒面具，戴化学安全防护眼镜，穿工作服，戴防护手套。远离火种、热源，工作场所严禁吸烟。使用防爆型的通风系统和设备。防止粉尘泄漏到工作场所空气中。避免与氧化剂、酸类、碱类接触。避免粉尘与空气形成爆炸性混合物。搬运时要轻装轻卸，防止包装及容器损坏。配备相应品种和数量的消防器材及泄漏应急处理设备。倒空的容器可能残留有害物。', '储存于阴凉、通风仓间内。远离火种，热源。防止阳光直射。保持容器密封。应与氧化剂、酸类、碱类分开存放。搬运时轻装轻卸，防止包装破损。储区应备有泄漏应急处理设备和合适的收容材料。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:31', '', NULL);
INSERT INTO `msds_handling_storage` VALUES (2900, 3034, '操作人员必须经过专门培训，严格遵守操作规程。建议操作人员佩戴自吸过滤式防毒面具（全面罩），戴化学安全防护眼镜，穿阻燃防静电防护服和抗静电的防护靴，戴橡胶耐油手套。远离火种、热源，工作场所严禁吸烟。使用防爆型的通风系统和设备。防止粉尘泄漏到工作场所空气中。避免与氧化剂、碱类、还原剂接触。搬运时要轻装轻卸，防止包装及容器损坏。配备相应品种和数量的消防器材及泄漏应急处理设备。倒空的容器可能残留有害物。', '火花、明火和热表面。采取措施防止静电积累。 保持容器密闭。储存在干燥、阴凉和通风处。远离热源、火花、明火和热表面。存储于远 离不相容材料和食品容器的地方。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:32', '', NULL);
INSERT INTO `msds_handling_storage` VALUES (2901, 3035, '操作人员必须经过专门培训，严格遵守操作规程。建议操作人员佩戴直接式防毒面具（半面罩），戴安全防护眼镜，穿防毒物渗透工作服，戴防化学品手套。远离火种、热源，工作场所严禁吸烟。使用防爆型的通风系统和设备。防止蒸气泄漏到工作场所空气中。避免与氧化剂、碱类、活性金属粉末接触。搬运时要轻装轻卸，防止包装及容器损坏。配备泄漏应急处理设备。倒空的容器可能残留有害物。', '储存于阴凉、通风的库房。远离火种、热源。保持容器密封。应与氧化剂、碱类、活性金属粉末、食用化学品分开存放，切忌混储。储区应备有泄漏应急处理设备和合适的收容材料。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:32', '', NULL);
INSERT INTO `msds_handling_storage` VALUES (2902, 3036, '密闭操作，保持良好通风。避免吸入蒸气，避免与皮肤、眼睛接触。禁止在使用区域吸烟和产生火花，防止静电积聚。搬运钢瓶须戴好安全帽、防震圈并固定。', '储存于阴凉、通风、不燃库房，远离火种、热源并避光保存。保持容器密封，直立固定。应与活性金属、氧化剂分开存放，采用防爆型照明与通风设备。储区备有泄漏应急装置和空气呼吸器。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:32', '', NULL);
INSERT INTO `msds_handling_storage` VALUES (2903, 3037, '操作人员必须经过专门培训，严格遵守操作规程。建议操作人员佩戴自吸过滤式防毒面具（半面罩），戴化学安全防护眼镜，穿防静电工作服，戴橡胶耐油手套。远离火种、热源，工作场所严禁吸烟。使用防爆型的通风系统和设备。所有金属部件都要接地。使用防爆设备。在通风良好处进行操作。防止蒸气泄漏到工作场所空气中。避免与氧化剂、酸类、碱类接触。搬运时要轻装轻卸，防止包装及容器损坏。配备相应品种和数量的消防器材及泄漏应急处理设备。倒空的容器可能残留有害物。', '避免接触皮肤和进入眼睛。远离热源、火花、明火和热表面。采取措施防止静电积累。 储存于阴凉、通风仓间内。远离火种、热源。仓温不宜超过30℃。保持容器密封。应与氧 化剂分开存放。储存间内的照明、通风等设施应采用防爆型。罐储时要有防火防爆技术措 施。禁止使用易产生火花的机械设备和工具。搬运时要轻装轻卸，防止包装及容器损坏。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:32', '', NULL);
INSERT INTO `msds_handling_storage` VALUES (2904, 3038, '操作人员必须经过专门培训，严格遵守操作规程。建议操作人员佩戴自吸过滤式防毒面具（半面罩），戴化学安全防护眼镜，穿防静电工作服，戴橡胶耐油手套。远离火种、热源，工作场所严禁吸烟。使用防爆型的通风系统和设备。防止蒸气泄漏到工作场所空气中。避免与还原剂、促进剂、强酸、强碱接触。搬运时要轻装轻卸，防止包装及容器损坏，避免摩擦、震动、撞击。配备相应品种和数量的消防器材及泄漏应急处理设备。倒空的容器可能残留有害物。', '火花、明火和热表面。 采取措施防止静电积累。 保持容器密闭。储存在干燥、阴凉和通风处。远离热源、火花、明火和热表面。存储于远 离不相容材料和食品容器 的地方。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:33', '', NULL);
INSERT INTO `msds_handling_storage` VALUES (2905, 3039, '操作人员必须经过专门培训，严格遵守操作规程。建议操作人员佩戴自吸过滤式防毒面具（半面罩），戴化学安全防护眼镜，穿防静电工作服，戴橡胶耐油手套。远离火种、热源，工作场所严禁吸烟。使用防爆型的通风系统和设备。防止蒸气泄漏到工作场所空气中。避免与还原剂、促进剂、强酸、强碱接触。搬运时要轻装轻卸，防止包装及容器损坏，避免摩擦、震动、撞击。配备相应品种和数量的消防器材及泄漏应急处理设备。倒空的容器可能残留有害物。', '火花、明火和热表面。 保持容器密闭。储存在干燥、阴凉和通风处。远离热源、火花、明火和热表面。存储于远离 不相容材料和食品容器的地方。储存温度一般不应高于30℃，相对湿度一般不应高于80%。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:33', '', NULL);
INSERT INTO `msds_handling_storage` VALUES (2906, 3040, '密闭操作并提供局部排风。操作人员佩戴自吸过滤式防毒面具、化学安全护目镜和防化手套，避免吸入蒸气或与皮肤接触。远离火源、热源，采取防静电措施。操作现场不得吸烟、饮水、进食。', '储存于阴凉、干燥、通风良好的不燃库房，远离火种、热源并避光保存。保持容器密封，与氧化剂、食用化工原料、日用品等分开存放。搬运时轻装轻卸，防止包装破损。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:34', '', NULL);
INSERT INTO `msds_handling_storage` VALUES (2907, 3041, '操作人员必须经过专门培训，严格遵守操作规程。建议操作人员佩戴自吸过滤式防毒面具（半面罩），戴化学安全防护眼镜，穿防静电工作服，戴橡胶耐油手套。远离火种、热源，工作场所严禁吸烟。使用防爆型的通风系统和设备。防止蒸气泄漏到工作场所空气中。避免与氧化剂、酸类接触。搬运时要轻装轻卸，防止包装及容器损坏。配备相应品种和数量的消防器材及泄漏应急处理设备。倒空的容器可能残留有害物。', '储存于阴凉、通风仓间内。远离火种、热源。防止阳光直射。保持容器密封。应与氧化剂、 酸类分开存放。储存间内的照明、通风等设施应采用防爆型。搬运时要轻装轻卸，防止包装 及容器损坏。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:34', '', NULL);
INSERT INTO `msds_handling_storage` VALUES (2908, 3042, '密闭操作并保持良好通风。远离火种、热源，严禁吸烟。采用防爆型设备并接地防静电，避免与氧化剂、强酸接触。', '储存于阴凉、通风仓间内，远离火种、热源和直射阳光。容器密封，防止空气进入。与氧化剂、强酸分开存放，使用防爆型照明及通风设施。搬运时轻装轻卸，防止包装损坏。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:34', '', NULL);
INSERT INTO `msds_handling_storage` VALUES (2909, 3043, '操作人员必须经过专门培训，严格遵守操作规程。建议操作人员佩戴自吸过滤式防毒面具（半面罩），戴化学安全防护眼镜，穿防静电工作服，戴橡胶耐油手套。远离火种、热源，工作场所严禁吸烟。使用防爆型的通风系统和设备。防止蒸气泄漏到工作场所空气中。避免与还原剂、促进剂、强酸、强碱接触。搬运时要轻装轻卸，防止包装及容器损坏，避免摩擦、震动、撞击。配备相应品种和数量的消防器材及泄漏应急处理设备。倒空的容器可能残留有害物。', '火花、明火和热表面。采取措施防止静电积累。 保持容器密闭。储存在干燥、阴凉和通风处。远离热源、火花、明火和热表面。存储于远 离不相容材料和食品容器的地方。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:34', '', NULL);
INSERT INTO `msds_handling_storage` VALUES (2910, 3044, '操作人员必须经过专门培训，严格遵守操作规程。建议操作人员佩戴自吸过滤式防毒面具（半面罩），戴化学安全防护眼镜，穿防静电工作服，戴橡胶耐油手套。远离火种、热源，工作场所严禁吸烟。使用防爆型的通风系统和设备。防止蒸气泄漏到工作场所空气中。避免与还原剂、促进剂、强酸、强碱接触。搬运时要轻装轻卸，防止包装及容器损坏，避免摩擦、震动、撞击。配备相应品种和数量的消防器材及泄漏应急处理设备。倒空的容器可能残留有害物。', '火花、明火和热表面。采取措施防止静电积累。 保持容器密闭。储存在干燥、阴凉和通风处。远离热源、火花、明火和热表面。存储于远 离不相容材料和食品容器的地方。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:36', '', NULL);
INSERT INTO `msds_handling_storage` VALUES (2911, 3045, '密闭操作，提供充分的局部排风。防止蒸气泄漏到工作场所空气中。操作人员必须经过专门培训，严格遵守操作规程。建议操作人员佩戴化学安全防护眼镜，穿防静电工作服，戴橡胶耐油手套。远离火种、热源，工作场所严禁吸烟。使用防爆型的通风系统和设备。避免产生粉尘。避免与氧化剂、还原剂、酸类、碱类接触。搬运时要轻装轻卸，防止包装及容器损坏。配备相应品种和数量的消防器材及泄漏应急处理设备。', '储存于阴凉、通风的库房。远离火种、热源。库温不宜超过30℃。保持容器密封。应与氧化剂、还原剂、酸类、碱类分开存放，切忌混储。采用防爆型照明、通风设施。禁止使用易产生火花的机械设备和工具。储区应备有泄漏应急处理设备和合适的收容材料。储存区应设置\"易燃\"、\"危险\"等警示标识。储存容器必须接地，防止静电积聚。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:37', '', NULL);
INSERT INTO `msds_handling_storage` VALUES (2912, 3046, '操作人员必须经过专门培训，严格遵守操作规程。建议操作人员佩戴自吸过滤式防毒面具（半面罩），戴化学安全防护眼镜，穿防静电工作服，戴一般作业防护手套。远离火种、热源，工作场所严禁吸烟。使用防爆型的通风系统和设备。防止气体泄漏到工作场所空气中。避免与强氧化剂、强酸接触。在传送过程中，钢瓶和容器必须接地和跨接，防止产生静电。搬运时戴好钢瓶安全帽和防震橡皮圈，防止钢瓶碰撞、损坏。配备相应品种和数量的消防器材及泄漏应急处理设备。倒空的容器可能残留有害物。注意：本品能发生聚合反应，需添加阻聚剂防止聚合。', '储存于阴凉、干燥、通风良好的不燃库房。远离火种、热源。应与氧化剂、酸类分开存放，切忌混储。采用防爆型照明、通风设施。禁止使用易产生火花的机械设备和工具。储区应备有泄漏应急处理设备。注意：本品能发生聚合反应，需添加阻聚剂防止聚合。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:37', '', NULL);
INSERT INTO `msds_handling_storage` VALUES (2913, 3047, '操作人员必须经过专门培训，严格遵守操作规程。建议操作人员佩戴自吸过滤式防毒面具（半面罩），戴化学安全防护眼镜，穿防静电工作服，戴橡胶耐油手套。远离火种、热源，工作场所严禁吸烟。使用防爆型的通风系统和设备。防止蒸气泄漏到工作场所空气中。避免与氧化剂、酸类、碱类接触。搬运时要轻装轻卸，防止包装及容器损坏。配备相应品种和数量的消防器材及泄漏应急处理设备。倒空的容器可能残留有害物。', '储存于阴凉、通风的库房。远离火种、热源。库温不宜超过30℃。保持容器密封。应与氧化剂、酸类、碱类等分开存放，切忌混储。采用防爆型照明、通风设施。禁止使用易产生火花的机械设备和工具。储区应备有泄漏应急处理设备和合适的收容材料。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:37', '', NULL);
INSERT INTO `msds_handling_storage` VALUES (2914, 3048, '操作人员必须经过专门培训，严格遵守操作规程。建议操作人员佩戴自吸过滤式防毒面具（半面罩），戴化学安全防护眼镜，穿防静电工作服，戴橡胶耐油手套。远离火种、热源，工作场所严禁吸烟。使用防爆型的通风系统和设备。防止蒸气泄漏到工作场所空气中。避免与氧化剂、酸类、碱类接触。所有金属部件都要接地。使用防爆设备。在通风良好处进行操作。搬运时要轻装轻卸，防止包装及容器损坏。配备相应品种和数量的消防器材及泄漏应急处理设备。倒空的容器可能残留有害物。', '保持容器密闭。储存在干燥、阴凉和通风处。远离热源、火花、明火和热表面。存储于远离不相容材料和食品容器的地方。应与氧化剂、酸类、碱类等分开存放，切忌混储。采用防爆型照明、通风设施。禁止使用易产生火花的机械设备和工具。储区应备有泄漏应急处理设备和合适的收容材料。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:38', '', NULL);
INSERT INTO `msds_handling_storage` VALUES (2915, 3049, '密闭操作，提供充分的局部排风。防止蒸气泄漏到工作场所空气中。操作人员必须经过专门培训，严格遵守操作规程。建议操作人员佩戴自吸过滤式防毒面具（全面罩），穿防静电工作服，戴橡胶耐油手套。远离火种、热源，工作场所严禁吸烟。使用防爆型的通风系统和设备。防止蒸气泄漏到工作场所空气中。避免与氧化剂、酸类接触。灌装时应控制流速，且有接地装置，防止静电积聚。配备相应品种和数量的消防器材及泄漏应急处理设备。', '储存于阴凉、通风的库房。远离火种、热源。库温不宜超过37℃。保持容器密封。应与氧化剂、酸类分开存放，切忌混储。采用防爆型照明、通风设施。禁止使用易产生火花的机械设备和工具。储区应备有泄漏应急处理设备和合适的收容材料。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:38', '', NULL);
INSERT INTO `msds_handling_storage` VALUES (2916, 3050, '操作人员必须经过专门培训，严格遵守操作规程。建议操作人员佩戴自吸过滤式防毒面具（半面罩），戴化学安全防护眼镜，穿防静电工作服，戴橡胶耐油手套。远离火种、热源，工作场所严禁吸烟。使用防爆型的通风系统和设备。防止蒸气泄漏到工作场所空气中。避免与氧化剂、酸类接触。搬运时要轻装轻卸，防止包装及容器损坏。配备相应品种和数量的消防器材及泄漏应急处理设备。倒空的容器可能残留有害物。注意：接触空气或在光照条件下可生成具有潜在爆炸危险性的过氧化物，需添加稳定剂。', '通常商品加有稳定剂。储存于阴凉、通风仓间内。远离火种、热源。仓温不宜超过30℃。防 止阳光直射。包装要求密封，不可与空气接触。应与氧化剂、酸类分开存放。储存间内的照 明、通风等设施应采用防爆型，开关设在仓外。配备相应品种和数量的消防器材。罐储时要 有防火防爆技术措施。禁止使用易产生火花的机械设备和工具。灌装时应注意流速(不超过3m ／s)，且有接地装置，防止静电积聚。搬运时要轻装轻卸，防止包装及容器损坏。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:38', '', NULL);
INSERT INTO `msds_handling_storage` VALUES (2917, 3051, '操作人员必须经过专门培训，严格遵守操作规程。建议操作人员佩戴自给式呼吸器，穿化学防护服，戴安全防护眼镜，必要时戴防化学品手套。远离火种、热源，工作场所严禁吸烟。使用防爆型的通风系统和设备。防止蒸气泄漏到工作场所空气中。避免与氧化剂、强还原剂接触。搬运时要轻装轻卸，防止包装及容器损坏。配备相应品种和数量的消防器材及泄漏应急处理设备。倒空的容器可能残留有害物。', '搬运时要轻装轻卸，防止包装及容器损坏。分装和搬运作业要注意个人防护。运输按规定路线行驶，中途不得停驶。储存区应备有泄漏应急处理设备和合适的收容材料。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:38', '', NULL);
INSERT INTO `msds_handling_storage` VALUES (2918, 3052, '操作人员必须经过专门培训，严格遵守操作规程。建议操作人员佩戴防毒口罩，戴化学安全防护眼镜，穿相应的防护服，戴防护手套。远离火种、热源，工作场所严禁吸烟。使用防爆型的通风系统和设备。防止粉尘泄漏到工作场所空气中。避免与氧化剂、碱类接触。搬运时要轻装轻卸，防止包装及容器损坏。配备相应品种和数量的消防器材及泄漏应急处理设备。倒空的容器可能残留有害物。操作现场不得吸烟、饮水、进食。', '储存于阴凉、通风仓间内。远离火种、热源。保持容器密封。专人保管。应与氧化剂、碱 类、食用化工原料分开存放。不能与粮食、食物、种子、饲料、各种日用品混装、混运。 操作现场不得吸烟、饮水、进食。搬运时轻装轻卸，保持包装完整，防止洒漏。分装和搬 运作业要注意个人防护。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:39', '', NULL);
INSERT INTO `msds_handling_storage` VALUES (2919, 3053, '有金属部件都要接地。使用防爆设备。在通风良好处进行操作。穿戴合适的个人防护用具。', '避免接触皮肤和进入眼睛。远离热源、火花、明火和热表面。 保持容器密闭。储存在干燥、阴凉和通风处。远离热源、火花、明火和热表面。存储于远 离不相容材料和食品容器的地方。储存温度一般不应高于32℃，相对湿度一般不应高于80%。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:39', '', NULL);
INSERT INTO `msds_handling_storage` VALUES (2920, 3054, '操作人员必须经过专门培训，严格遵守操作规程。建议操作人员佩戴自吸过滤式防毒面具（半面罩），戴化学安全防护眼镜，穿防静电工作服，戴橡胶耐油手套。远离火种、热源，工作场所严禁吸烟。使用防爆型的通风系统和设备。防止蒸气泄漏到工作场所空气中。避免与氧化剂、酸类、碱类接触。灌装时应控制流速，且有接地装置，防止静电积聚。搬运时要轻装轻卸，防止包装及容器损坏。配备相应品种和数量的消防器材及泄漏应急处理设备。倒空的容器可能残留有害物。', '储存于阴凉、通风的库房。远离火种、热源。库温不超过30℃，相对湿度不超过85％。保持容器密封。应与氧化剂、酸类、碱类分开存放，切忌混储。采用防爆型照明、通风设施。禁止使用易产生火花的机械设备和工具。储区应备有泄漏应急处理设备和合适的收容材料。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:39', '', NULL);
INSERT INTO `msds_handling_storage` VALUES (2921, 3055, '操作人员必须经过专门培训，严格遵守操作规程。建议操作人员佩戴过滤式防毒面具（半面罩），戴化学安全防护眼镜，穿防静电工作服，戴橡胶耐油手套。远离火种、热源，工作场所严禁吸烟。使用防爆型的通风系统和设备。防止蒸气泄漏到工作场所空气中。避免与氧化剂、酸类、碱类接触。灌装时应控制流速，且有接地装置，防止静电积聚。搬运时要轻装轻卸，防止包装及容器损坏。配备相应品种和数量的消防器材及泄漏应急处理设备。倒空的容器可能残留有害物。', '储存于阴凉、通风的库房。远离火种、热源。库温不宜超过30℃。包装要求密封，不可与空气接触。应与氧化剂、酸类、碱类分开存放，切忌混储。不宜久存，以免变质。采用防爆型照明、通风设施。禁止使用易产生火花的机械设备和工具。储区应备有泄漏应急处理设备和合适的收容材料。注意：本品能发生聚合反应，需添加阻聚剂防止聚合。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:39', '', NULL);
INSERT INTO `msds_handling_storage` VALUES (2922, 3056, '好处进行操作。穿戴合适的个人防护用具。避免接触皮肤和进入眼睛。远离热源、火花、明', '火和热表面。 保持容器密闭。储存在干燥、阴凉和通风处。远离热源、火花、明火和热表面。存储于远离 不相容材料和食品容器的地方。储存温度不应高于35℃。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:40', '', NULL);
INSERT INTO `msds_handling_storage` VALUES (2923, 3057, '无资料', '储存于阴凉、通风仓间内。远离火种、热源。防止阳光直射。保持容器密封。应与氧化剂、 食用化工原料分开存放。搬运时要轻装轻卸，防止包装及容器损坏。分装和搬运作业要注意 个人防护。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:40', '', NULL);
INSERT INTO `msds_handling_storage` VALUES (2924, 3058, '严加密闭，提供充分的局部排风。操作人员必须经过专门培训，严格遵守操作规程。建议操作人员佩戴自吸过滤式防毒面具（全面罩），穿胶布防毒衣，戴橡胶手套。远离火种、热源，工作场所严禁吸烟。使用防爆型的通风系统和设备。避免产生粉尘。避免与氧化剂、酸类、碱类接触。搬运时要轻装轻卸，防止包装及容器损坏。配备相应品种和数量的消防器材及泄漏应急处理设备。倒空的容器可能残留有害物，需进行无害化处理。本品为剧毒有机氯农药，确认致癌物1类（IARC），操作时需特别谨慎，避免任何形式的暴露。', '储存于阴凉、通风仓间内。远离火种、热源。防止阳光直射。保持容器密封。应与氧化剂分 开存放。不可混储混运。搬运时要轻装轻卸，防止包装及容器损坏。分装和搬运作业要注意 个人防护。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:41', '', NULL);
INSERT INTO `msds_handling_storage` VALUES (2925, 3059, '操作人员必须经过专门培训，严格遵守操作规程。建议操作人员佩戴自吸过滤式防毒面具（全面罩），穿连衣式胶布防毒衣，戴橡胶耐油手套。远离火种、热源，工作场所严禁吸烟。使用防爆型的通风系统和设备。防止蒸气泄漏到工作场所空气中。避免与氧化剂、酸类、碱类接触。搬运时要轻装轻卸，防止包装及容器损坏。配备相应品种和数量的消防器材及泄漏应急处理设备。倒空的容器可能残留有害物，需进行彻底清洗和处置。', '火花、明火和热表面。采取措施防止静电积累。 保持容器密闭。储存在干燥、阴凉和通风处。远离热源、火花、明火和热表面。存储于远 离不相容材料和食品容器的地方。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:41', '', NULL);
