INSERT INTO `msds_handling_storage` VALUES (3107, 3241, '在通风良好的区域进行操作。避免接触皮肤和眼睛。避免吸入粉尘。操作后彻底清洗。', '保持容器密闭。储存在干燥、阴凉和通风处。远离热源、火花、明火和热表面。存储于远离不相容材料和食品容器的地方。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:43', '', NULL);
