INSERT INTO `msds_handling_storage` VALUES (3154, 3288, '无资料', '储存于阴凉、通风仓间内。远离火种、热源。仓温不宜超过30℃。防止阳光直射。保持容 器密封。应与氧化剂、酸类、碱类分开存放。储存间内的照明、通风等设施应采用防爆型。 禁止使用易产生火花的机械设备和工具。搬运时要轻装轻卸，防止包装及容器损坏。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:31:03', '', NULL);
