INSERT INTO `msds_handling_storage` VALUES (3380, 3515, '在通风良好处进行操作。穿戴合适的个人防护用具。避免接触皮肤和进入眼睛。远离热源、', '火花、明火和热表面。采取措施防止静电积累。 储存于阴凉、通风仓间内。远离火种、热源。专人保管。保持容器密封。避光保存。防止 阳光曝晒。应与酸类、氧化剂、食用化工原料等分开存放。操作现场不得吸烟、饮水、进 食。搬运时要轻装轻卸，防止包装及容器损坏。分装和搬运作业要注意个人防护。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:32:40', '', NULL);
