INSERT INTO `msds_handling_storage` VALUES (3975, 4110, '无资料', '储存于阴凉、通风仓间内。远离火种、热源。防止阳光直射。保持容器密封。应与氧化剂分开 存放。搬运时要轻装轻卸，防止包装及容器损坏。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:36:45', '', NULL);
