INSERT INTO `msds_handling_storage` VALUES (4109, 4244, '无资料', '储存于阴凉、干燥、通风良好的库房。远离火种、热源。专人保管。保持容器密封。应与 氧化剂、食用化工原料分开存放。搬运时要轻装轻卸，防止包装及容器损坏。操作现场不 得吸烟、饮水、进食。分装和搬运作业要注意个人防护。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:46', '', NULL);
