INSERT INTO `msds_handling_storage` VALUES (4111, 4246, '无资料', '储存于阴凉、通风仓间内。远离火种、热源。保持容器密封。专人保管。应与氧化剂、食 用化工原料分开存放。不能与粮食、食物、种子、饲料、各种日用品混装、混运。操作现 场不得吸烟、饮水、进食。搬运时要轻装轻卸，防止包装及容器损坏。分装和搬运作业要 注意个人防护。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:37:47', '', NULL);
