INSERT INTO `msds_handling_storage` VALUES (4354, 4489, '无资料', '储存于阴凉、通风仓间内。远离火种、热源。保持容器密封。应与易燃、可燃物分开存放。 搬运时要轻装轻卸，防止包装及容器损坏。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:39:41', '', NULL);
