INSERT INTO `msds_handling_storage` VALUES (4590, 4725, '无资料', '储存于阴凉、通风仓间内。远离火种、热源。专人保管。保持容器密封。防止阳光直射。 应与氧化剂、酸类、食用化工原料分开存放。操作现场不得吸烟、饮水、进食。搬运时要 轻装轻卸，防止包装及容器损坏。分装和搬运作业要注意个人防护。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:41:31', '', NULL);
