INSERT INTO `msds_hazard` VALUES (3240, 3346, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入 食入 经皮吸收\n吸入、摄入或经皮肤吸收对身体有害，对眼睛有刺激作用，对皮肤可能有刺激作用。中毒表现', '有头痛、恶心和呕吐。慢性影响：实验表明有诱变作用。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
