INSERT INTO `msds_hazard` VALUES (3245, 3351, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入 食入 经皮吸收\n吸入、摄入或经皮肤吸收对身体有害。蒸气或雾对眼、粘膜和上呼吸道有刺激性，对皮肤有', '刺激性。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
