INSERT INTO `msds_hazard` VALUES (3247, 3353, NULL, NULL, NULL, NULL, NULL, '有机过氧化物，D型。', '吸入、食入、皮肤接触、眼睛接触', '吸入该物质可能会引起对健康有害的影响或呼吸道不适。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。误服可引起消化道刺激症状。', '该物质对环境可能有危害，应特别注意对水体的污染。', '遇明火、高热可燃。受热分解产生有毒气体。具有爆炸性，遇热、摩擦、震动或杂质可能发生爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3248, 3354, NULL, NULL, NULL, NULL, NULL, '有机过氧化物，C型。', '吸入、食入、皮肤接触、眼睛接触\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3249, 3355, NULL, NULL, NULL, NULL, NULL, '有机过氧化物，D型。', '吸入、食入、皮肤接触、眼睛接触\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
