INSERT INTO `msds_hazard` VALUES (3256, 3362, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入', NULL, NULL, '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3257, 3363, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入食入经皮吸收', '恶心，呕吐，指端、口唇、耳廓紫绀，呼吸困难等。慢性影响：患者有神经衰弱综合征表\n现，伴有轻度紫绀、贫血和肝、脾肿大。', NULL, '本品可燃，有毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3258, 3364, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。对人体有毒，对眼睛、皮肤、粘膜和上呼吸道有刺激作用。受热分解出有毒气体。吸入后可引起咳嗽、呼吸困难、头痛、头晕、恶心、呕吐等症状。皮肤接触可引起刺激、红肿、疼痛。眼睛接触可引起严重刺激、流泪、视力模糊。吞食后可引起口腔、咽喉、胃肠道刺激，出现恶心、呕吐、腹痛等症状。长期接触可能对肝脏、肾脏有影响。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '2,5-二氯苯酚对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。在水生生物中可能发生生物蓄积。', '本品可燃，有毒，具刺激性。遇明火、高热可燃。与强氧化剂可发生反应。受高热分解产生有毒的腐蚀性气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3259, 3365, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '刺激作用。皮肤接触可引起红斑、大疱，或发生湿疹。', '无资料', '本品有毒、刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3260, 3367, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。吸', '收后在体内可形成高铁血红蛋白而致紫绀。', '无资料', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3261, 3368, NULL, NULL, NULL, NULL, NULL, '吞咽有害', '吸入 食入', '本品对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '无资料', '可燃', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3262, 3369, NULL, NULL, NULL, NULL, NULL, '第4.1类 易燃固体', '吸入 食入 经皮吸收\n有毒。接触或吸入其蒸气、粉尘或雾滴或经皮肤吸收均会引起中毒。中毒时大量出汗、发', '烧、口渴、烦躁不安、全身乏力、抽搐、肌肉强直等。长期接触可引起皮炎、周围神经炎。', NULL, '本品易燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3263, 3370, NULL, NULL, NULL, NULL, NULL, '急毒性-口服，类别3；皮肤腐蚀/刺激，类别2；眼损伤/眼刺激，类别2A；特定目标器官毒', '吸入、食入、皮肤接触、眼睛接触\n吸入粉尘或烟雾(尤其是长期接触)可能引起呼吸道刺激，偶尔出现呼吸窘迫。吸入该物质\n可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3264, 3371, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有剧毒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3265, 3372, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, '对水生物有毒，对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3266, 3373, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收', '心、呕吐、腹痛、衰竭、昏迷等症状。对皮肤可造成腐蚀性灼伤。', '无资料', '本品可燃、有毒、为可疑致癌物、具有腐蚀性、刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3267, 3374, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入 食入', '高浓度蒸气具有麻醉性。', '无资料', '本品易燃', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3268, 3375, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入食入经皮吸收', NULL, NULL, '本品易燃，有毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3269, 3376, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入经皮吸收', '并引起头痛、眩晕、恶心、呕吐、精神迟钝、腹痛、腹泻等。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3270, 3377, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入 食入 经皮吸收', NULL, '无资料', '本品易燃、刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3271, 3378, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入 食入 经皮吸收\n吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用，', '接触后可引起头痛、恶心、呕吐、烧灼感、喉炎、气短等，甚至发生化学性肺炎、肺水肿。', '无资料', '本品可燃、具有腐蚀性、刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3272, 3379, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入食入经皮吸收', '恶心、呕吐、指端、口唇、耳廓紫绀、呼吸困难等。慢性影响：患者有神经衰弱综合征表\n现，伴有轻度发绀、贫血和肝、脾肿大。', NULL, '本品可燃，有毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3273, 3380, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n吸入、摄入或经皮肤吸收对身体有害。对眼睛、粘膜、呼吸道及皮肤有刺激作用，严重者可', '引起灼伤。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3274, 3381, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入食入经皮吸收', '对眼有刺激作用。皮肤接触可引起红斑、大疱，或发生湿疹。', NULL, '本品可燃，有毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3275, 3382, NULL, NULL, NULL, NULL, NULL, '剧毒化学品；急性毒性类别1（口服）；急性毒性类别1（经皮）；急性毒性类别2（吸入）', '可经口、皮肤接触、吸入途径进入人体', '吞食后有剧毒，成人致死量约为5毫克。可引起剧烈抽搐、呼吸困难、昏迷甚至死亡。是一种神经毒素，作用于中枢神经系统，引起癫痫样发作。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '遇明火、高热可燃。受高热分解，产生有毒的氮氧化物和硫氧化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3276, 3383, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入', '心和眩晕。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3277, 3384, NULL, NULL, NULL, NULL, NULL, '第6.4类；毒害品', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收后，可引起中毒死亡。对眼睛、粘膜、呼吸道及皮肤有刺激作用。吸收进入体内引起高铁血红蛋白血症，出现紫绀。中毒表现有恶心、眩晕、头痛等。', '对水生生物有毒害作用，可能对水体环境造成长期不良影响。', '本品可燃，有毒，具刺激性。遇明火、高热可燃。与强氧化剂可发生反应。急剧加热时可发生爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3278, 3385, NULL, NULL, NULL, NULL, NULL, '第5.1类 易燃固体', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜有强烈刺激性。可引起高铁血红蛋白血症，出现紫绀、头痛、眩晕、恶心等症状。高浓度可致死。', '对水生物有剧毒,对水生环境可能会引起长期有害作用', '高度易燃，其粉体与空气混合，能形成爆炸性混合物', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3279, 3386, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', NULL, '无资料', '本品易燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3280, 3387, NULL, NULL, NULL, NULL, NULL, '第4.1类 易燃固体', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜有刺激性。长期接触可引起皮肤过敏反应。吸入粉尘可引起呼吸道刺激。', '对水生生物有毒害作用，可能对水体环境造成长期不良影响', '本品易燃、具有刺激性，燃烧产生有毒烟气', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3281, 3388, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '高毒杀鼠剂。误服或皮肤接触会中毒。受热分解释出氯烟雾。急性中毒可出现恶心、呕吐、腹痛、腹泻、便血、呼吸困难、紫绀、抽搐、昏迷等症状。', '对水生生物有极高毒性，可能对水体环境造成长期不良影响。', '本品可燃、高毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3282, 3389, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后中毒，引起头痛、恶心、呕吐、血压升高，重者可引起惊厥、昏迷、呼吸困难、甚至死亡。对眼睛、皮肤和粘膜有刺激作用。', '对水生生物有毒性，可能对水生环境造成长期不利影响。', '遇明火、高热可燃。受高热分解，放出有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3283, 3390, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收', '吸入、摄入或经皮肤吸收后会中毒，引起头痛、恶心、呕吐、血压升高，重者可引起惊厥、\n昏迷、呼吸困难、甚至死亡。对眼睛、皮肤和粘膜有刺激作用。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3284, 3391, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。长期接触可引起皮肤变应性皮炎。本品可通过皮肤吸收。', '2-氨基苯酚对水生生物有毒性。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品可燃，有毒，具致敏性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3285, 3392, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、皮肤接触、眼睛接触', '对人体有毒。有刺激作用。资料报道，为可疑致癌物。对眼睛、皮肤、粘膜有刺激性。长期接触可引起砷中毒症状，包括皮肤损伤、周围神经病变、肝肾功能损害等。', '对水生生物有极高毒性，可能对水体环境产生长期不良影响。砷化合物在环境中持久存在，不易降解。', '遇明火、高热可燃。受热分解产生有毒的砷氧化物、氮氧化物和砷化氢等烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3286, 3393, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。接触本品对眼、鼻、喉有刺激作用，吸入或经皮吸收，出现头痛、头昏、迟钝、四肢无力、惊厥、昏迷，甚至引起死亡。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '2-氨基吡啶对水生生物有毒性。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3287, 3394, NULL, NULL, NULL, NULL, NULL, '第3.1类 低闪点易燃液体', '吸入 食入 经皮吸收\n吸入', NULL, '无资料', '本品极度易燃、强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3288, 3395, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。资料报道有致突变作用。受热分解释出氮氧化物。', '2-氨基蒽醌对水生生物有毒性。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品可燃，有毒，具致突变性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3289, 3396, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '本品可经皮肤、呼吸道和消化道吸收。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期接触可引起膀胱癌。', NULL, '遇明火、高热可燃。受热分解产生有毒的氮氧化物烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3290, 3397, NULL, NULL, NULL, NULL, NULL, '第8.2类 碱性腐蚀品', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。蒸气对眼、鼻有刺激性。眼接触液状本品可引起严重损害，甚至失明。皮肤接触可引起刺激、红肿、疼痛，严重者可致灼伤。对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激性和腐蚀性。长期接触可引起肝、肾功能损害，神经系统损伤等。本品可通过皮肤吸收。', '2-氨基乙醇对水生生物有毒性。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品腐蚀性、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3291, 3398, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。溅入眼内可产生刺激作用。对皮肤有刺激性，直接接触后，局部红肿，出疹及脱屑；炎症消退后可出现白斑。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '2-苯基苯酚对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品可燃、具有刺激性。遇高热、明火或与氧化剂接触，有引起燃烧的危险。受高热分解放出有毒的气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3292, 3399, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期接触可能对肝脏、肾脏有影响。', '2-苯基丙烯对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。挥发后可参与形成光化学烟雾。', '本品易燃、具有刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。与氧化剂能发生强烈反应。若遇高热，可能发生聚合反应，出现大量放热现象，引起容器破裂和爆炸事故。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3293, 3400, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、皮肤接触、眼睛接触', '有毒，并对皮肤有刺激性。会引起皮肤烧伤，有严重损害眼睛的危险。跟皮肤接触可能会引起敏化作用。对眼睛、皮肤、粘膜和上呼吸道有刺激性。吸入、食入或经皮肤吸收可引起中毒。', '对水生物有毒，对水生环境可能会引起长期有害作用。', '本品可燃、有毒、具有刺激性。受热或接触火焰可能会产生膨胀或爆炸性分解。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3294, 3401, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生生物有害。', '本品可燃、有毒、具有刺激性。遇高热、明火或与氧化剂接触，有引起燃烧的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3295, 3402, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入', '有毒，并对皮肤有刺激性。经口摄入会中毒。', '对环境有危害，对水体可造成污染。', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3296, 3403, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。接触高浓度蒸气出现头痛、倦睡、共济失调以及眼、鼻、喉刺激症状。口服可致恶心、呕吐、腹痛、腹泻；倦睡、昏迷甚至死亡。长期皮肤接触可致皮肤干燥、皲裂。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '2-丙醇（异丙醇）对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃、刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3297, 3404, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入 食入 经皮吸收', '高浓度丙炔醇对眼睛、皮肤、粘膜和呼吸道有强烈的刺激作用。中毒表现有烧灼感、咳嗽、\n喘息、喉炎、气短：头痛、恶心和呕吐。严重者可能致死。', '对水生生物有毒，可能对水体环境产生长期不良影响', '本品易燃、剧毒、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3298, 3405, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入 食入 经皮吸收', '鼻刺激；可致急性结膜炎，点状角膜炎，并可使角膜发生迟发性坏死，液体沾染眼睛可致严重\n灼伤。皮肤较长时间接触后可引起疼痛及接触性皮炎或灼伤。', '无资料', '本品易燃、剧毒、强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3299, 3406, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入、食入、经皮吸收', '具有刺激性。接触后可引起头痛、恶心和呕吐。对眼睛、皮肤和粘膜有刺激作用。', '对水生生物有毒，具有生物富集性', '本品易燃，具有刺激性。遇明火、高热能引起燃烧爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3300, 3407, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入经皮吸收', '眼结膜及鼻、咽部充血。重者除上述症状加重外，出现四肢阵发性强直抽搐、昏迷。液体\n污染皮肤，可致皮炎，局部出现红斑、丘疹或水疱。慢性中毒：尚无定论。长期接触，部\n分工人出现神衰综合征，低血压等。对肝脏影响未肯定。', '对水生生物有极高毒性，可能对水体环境产生长期不良影响。', '本品易燃，高毒，为可疑致癌物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3301, 3408, NULL, NULL, NULL, NULL, NULL, '第3类易燃液体', '吸入、食入、皮肤接触、眼睛接触', '对皮肤有刺激性。跟皮肤接触可能会引起敏化作用。对呼吸道有刺激作用。', '对水生物有毒，对水生环境可能会引起长期有害作用。', '高度易燃,其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3302, 3409, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '对皮肤有刺激性。对眼睛有严重刺激性。对呼吸道有刺激作用。', '对水生物有剧毒,对水生环境可能会引起长期有害作用', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3303, 3410, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收对身体有害。蒸气或雾对眼、粘膜和上呼吸道有刺激性。对皮肤有刺激性。接触后引起烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3304, 3411, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入 食入', '对眼睛、皮肤和粘膜具刺激性。误服或吸入会中毒。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3305, 3412, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入 食入 经皮吸收', '恶心、呕吐、咳嗽、气短、喉炎等症状。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3306, 3413, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。对兔皮肤无刺激性，但对兔眼有严重损伤。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。高浓度接触可能引起头痛、眩晕、恶心等症状。长期接触可引起肝、肾功能损害，神经系统损伤等。本品可通过皮肤吸收。', '2-丁醇（仲丁醇）对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3307, 3414, NULL, NULL, NULL, NULL, NULL, '第3.1类 低闪点易燃液体', '吸入、食入、经皮吸收', '蒸气或雾对眼、粘膜和上呼吸道有刺激性。高浓度吸入可引起头痛、头晕、恶心、呕吐、甚至昏迷。对皮肤有刺激性。', '对水生生物有毒，可能对水体环境造成长期不良影响。', '本品极度易燃、具有刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3308, 3415, NULL, NULL, NULL, NULL, NULL, '第3.1类低闪点易燃液体', '吸入、食入、经皮吸收', '高浓度蒸气对眼睛、皮肤、粘膜和呼吸道有刺激性。接触可引起头痛、眩晕、恶心、呼吸困难等症状。严重时可导致意识丧失。', '对水生生物有毒，可能对水体环境造成长期不良影响。', '本品极度易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3309, 3416, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '对眼、鼻、喉、粘膜有刺激性。长期接触可致皮炎。强己酮-[2]引起的周围神经病现象，但单独接触丁酮未发现有周围神经病现象。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3310, 3417, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤、粘膜和上呼吸道有刺激作用。接触可引起头痛、头晕、恶心、呕吐等症状。长期或反复接触可能引起肝、肾损害。', '对水生生物有毒，可能对水体环境造成长期不良影响。', '受热分解释放出有毒的氮氧化物气体。遇明火、高热可燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3311, 3418, NULL, NULL, NULL, NULL, NULL, '第2.1类 易燃气体', '吸入、食入、经皮吸收', '有轻度麻醉和刺激作用，并可引起窒息。急性中毒：出现粘膜刺激症状、嗜睡、血压稍升高、心率增快。高浓度吸入可引起窒息、昏迷。慢性影响：长期接触以丁烯为主的混合性气体，工人有头痛、头晕、嗜睡或失眠、易兴奋、易疲倦、全身乏力、记忆力减退。有时有粘膜慢性刺激症状。', '2-丁烯(顺式)对水生生物有毒性，对鱼类、甲壳类、藻类等水生生物有毒性作用。该物质在环境中较难降解，在土壤中可长期残留。可通过食物链在生物体内富集，对生态系统造成危害。对鸟类、哺乳动物等陆生生物也有毒性。应避免进入水体、土壤和地下水。该物质对环境有危害，应特别注意对地表水、土壤、大气和饮用水的污染。', '本品易燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3312, 3419, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入、食入、经皮吸收', '高浓度丁烯醇对眼睛、皮肤、粘膜和呼吸道有强烈的刺激作用。中毒表现有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '2-丁烯-1-醇（巴豆醇）对水生生物有毒性，对鱼类、甲壳类、藻类等水生生物有毒性作用。该物质在环境中可生物降解，但在高浓度下可能对水生生态系统造成危害。应避免进入水体、土壤和地下水。该物质对环境有危害，应特别注意对水体的污染。', '本品易燃、刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3313, 3420, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '该物质对呼吸道有刺激性，可引起咳嗽、呼吸困难等症状。高浓度接触可能导致呼吸道炎症和肺水肿。对眼睛和皮肤有强烈刺激性，可能导致灼伤。长期或反复接触可能引起过敏反应。', '2-丁烯醛（巴豆醛）对水生生物有毒性，对鱼类、甲壳类、藻类等水生生物有毒性作用。该物质在环境中可生物降解，但在高浓度下可能对水生生态系统造成危害。应避免进入水体、土壤和地下水。该物质对环境有危害，应特别注意对水体的污染。', '本品易燃，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3314, 3421, NULL, NULL, NULL, NULL, NULL, '急毒性-皮肤，类别3；皮肤腐蚀/刺激，类别1；眼损伤/眼刺激，类别1。', '吸入、食入、皮肤接触、眼睛接触', '吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激性和腐蚀性。眼接触液状本品可引起严重损害，甚至失明。皮肤接触可引起刺激、红肿、疼痛，严重者可致灼伤。吸入后可引起头痛、头晕、恶心、呕吐、咳嗽、喘息、喉炎、气短等症状。长期接触可引起肝、肾功能损害，神经系统损伤等。本品可通过皮肤吸收。', '2-丁烯酸（巴豆酸）对水生生物有毒性。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品可燃，具腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3315, 3422, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '本品对皮肤、眼睛和呼吸道有刺激性。长期接触可引起皮炎、头痛、眩晕、乏力等症状。高浓度接触可引起中枢神经系统抑制。', '对水生生物有毒，可能对水体环境造成长期不良影响。', '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3316, 3423, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '激。口服出现头痛、恶心，口腔和胃刺激。', '无资料', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3317, 3424, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '有毒。对皮肤有刺激作用，其蒸气或烟雾对眼睛、粘膜和上呼吸道有刺激作用。进入体内，可形成高铁血红蛋白而致紫绀。', '无资料', '本品易燃、具有刺激性。遇高热、明火或氧化剂，有引起燃烧的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3318, 3425, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。蒸气或雾对眼睛、皮肤、粘膜和上呼吸道有刺激性。接触后可引起头痛、头晕、恶心、呕吐、嗜睡等症状。高浓度接触可引起麻醉作用。', '对水生生物有害，可能对水体环境造成长期不利影响。', '易燃，遇明火、高热能引起燃烧爆炸。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。与氧化剂能发生强烈反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3319, 3426, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。本品主要为麻醉和刺激作用。吸入高浓度蒸气可致深度麻醉，可引起头痛、头晕、恶心、呕吐、倦睡、不安等症状。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。皮肤接触可引起刺激、红肿、疼痛。眼睛接触可引起刺激、流泪、视力模糊。长期接触可引起肝、肾功能损害，神经系统损伤等。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '对水生生物有毒性，对鱼类、甲壳类、藻类等水生生物有毒性作用。该物质在环境中较难降解，在土壤中可长期残留。可通过食物链在生物体内富集，对生态系统造成危害。对鸟类、哺乳动物等陆生生物也有毒性。应避免进入水体、土壤和地下水。该物质对环境有危害，应特别注意对水体的污染。', '本品易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3320, 3427, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入、食入、经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。本品易燃、具有刺激性。吸入或口服对身体有害，可引起麻醉，伴眼和呼吸道粘膜刺激、眩晕、呕吐及紫绀。对皮肤有刺激性。吸入后可引起头痛、头晕、恶心、呕吐、倦睡、不安等症状。皮肤接触可引起刺激、红肿、疼痛。眼睛接触可引起刺激、流泪、视力模糊。长期接触可引起肝、肾功能损害，神经系统损伤等。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '对水生生物有毒性，对鱼类、甲壳类、藻类等水生生物有毒性作用。该物质在环境中较难降解，在土壤中可长期残留。可通过食物链在生物体内富集，对生态系统造成危害。对鸟类、哺乳动物等陆生生物也有毒性。应避免进入水体、土壤和地下水。该物质对环境有危害，应特别注意对水体的污染。', '本品易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3321, 3428, NULL, NULL, NULL, NULL, NULL, '第3类易燃液体（高闪点液体）', '吸入、食入、皮肤接触', '吸入、摄入或经皮肤吸收可能对身体有害。蒸气可引起头晕、头痛、恶心和麻醉作用。高浓度接触可能引起中枢神经系统抑制。', '对水生生物有毒性。该物质可能对环境造成危害，特别是在水生环境中。', '易燃，其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3322, 3429, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '吸入、食入或经皮肤吸收后对身体有害。本品对眼睛、皮肤、粘膜和上呼吸道具刺激作用。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '2-环己烯-1-酮对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃、有毒、具有刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。与氧化剂能发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3323, 3430, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。接触可引起头痛、头晕、恶心、呼吸困难。高浓度接触可引起麻醉作用。', '对环境有危害，对水体可造成污染', '易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂可发生反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3324, 3431, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入、食入、经皮吸收', '急性中毒时，具有粘膜刺激和麻醉作用，引起眼和上呼吸道的刺激症状。慢性作用：出现肢端麻木、刺痛、足根烧灼感、寒冷感、上下肢无力等周围神经炎表现。', '无资料', '本品易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3325, 3432, NULL, NULL, NULL, NULL, NULL, '第3.1类 低闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '吸入、食入或经皮肤吸收后对身体有害。蒸气或雾对眼和上呼吸道有刺激性，接触后出现烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。对呼吸道粘膜和眼结膜有刺激作用。皮肤接触可引起刺激、红肿、疼痛。眼睛接触可引起刺激、流泪、视力模糊。长期接触可引起肝、肾功能损害，神经系统损伤等。本品可通过皮肤吸收。', '对水生生物有毒性。该物质在环境中较难降解，在土壤中可长期残留。可通过食物链在生物体内富集，对生态系统造成危害。应避免进入水体、土壤和地下水。', '易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触猛烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3326, 3433, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入、食入、经皮吸收', '吸入或摄入对身体有害。对皮肤有刺激性。蒸气或雾对眼、粘膜、上呼吸道有刺激性。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3327, 3434, NULL, NULL, NULL, NULL, NULL, '第8.3类 其它腐蚀品', '吸入 食入 经皮吸收', '蒸气或雾对眼、粘膜、上呼吸道和皮肤有刺激性。接触后引起头痛、恶心、呕吐。', '无资料', '本品可燃、有毒、具有强腐蚀性、刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3328, 3435, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。可引起头痛、头晕、恶心、呕吐、腹痛、腹泻、虚脱、体温下降和昏迷，并可引起肺水肿。可经皮肤吸收引起中毒。慢性影响：可引起消化道功能障碍，肝、肾损害和皮疹。', '2-甲酚对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，应特别注意对水体的污染。在水生生物中可能发生生物蓄积。', '本品可燃，高毒，具腐蚀性、强刺激性，可致人体灼伤。遇明火、高热可燃。具有腐蚀性。受高热分解放出有毒的气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3329, 3436, NULL, NULL, NULL, NULL, NULL, '第3.1类低闪点易燃液体', '吸入、食入、经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。麻醉前的兴奋症状，如烦躁不安、大声哭闹、肌肉抽搐、震颤等；严重者昏迷。一般在数小时后逐步清醒。通常无后遗症。本品可引起皮肤充血与水肿，其后可有轻度剥脱。可经完整皮肤吸收。本品可通过皮肤吸收。', '2-甲基-1,3-丁二烯（异戊二烯）对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。挥发后可参与形成光化学烟雾。', '本品极度易燃，具刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。与氧化剂能发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。能发生聚合反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3330, 3437, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。较高浓度蒸气对眼睛、皮肤、粘膜和上呼吸道有刺激作用。眼角膜表层形成空泡，还可引起食欲减退和体重减轻。涂于皮肤，引起局部轻度充血及红斑。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '2-甲基-1-丙醇（异丁醇）对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃，具刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。与氧化剂能发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3331, 3438, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '蒸气或雾对眼、粘膜和上呼吸道有刺激性。对皮肤有刺激性。接触后可引起恶心和呕吐。高浓度接触可引起头痛、头晕、意识模糊等中枢神经系统症状。长期接触可能影响肝、肾功能。', '2-甲基-1-丙硫醇（异丁硫醇）对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃，具刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂接触发生反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3332, 3439, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '吸入、食入或经皮肤吸收后对身体有害。刺激眼睛、皮肤和呼吸道，影响中枢神经系统，可形成高铁血红蛋白。各种侵入途径都能引起中毒。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。长期接触可引起肝、肾功能损害，神经系统损伤等。本品可通过皮肤吸收。', '2-甲基-1-丁醇（活性戊醇）对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃，具刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂接触发生反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3333, 3440, NULL, NULL, NULL, NULL, NULL, '第3.2类 高闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '高浓度蒸气可引起头痛、头晕、恶心、呕吐、嗜睡等中枢神经系统症状。对眼睛、皮肤、粘膜有强烈刺激性。长期接触可引起皮肤干燥、脱屑。', '对水生生物有害。', '高度易燃，其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3334, 3441, NULL, NULL, NULL, NULL, NULL, '第3.1类低闪点易燃液体', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。高浓度蒸气可引起头痛、头晕、嗜睡、恶心、乏力等症状。对眼睛、皮肤、粘膜有刺激性。', '对水生生物有害。挥发后可参与形成光化学烟雾。', '本品极度易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3335, 3442, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。长期接触可引起肝、肾功能损害，神经系统损伤等。本品可通过皮肤吸收。', '2-甲基-1-戊醇对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3336, 3443, NULL, NULL, NULL, NULL, NULL, '第3.1类 低闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '蒸气或雾对眼、粘膜和上呼吸道有刺激性，接触后出现烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '该物质对环境可能有危害，对水体应给予特别注意。', '其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触猛烈反应。流速过快，容易产生和积聚静电。容易自聚，聚合反应随着温度的上升而急骤加剧。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3337, 3444, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。吸入或口服对身体有害。对眼睛、皮肤、粘膜和呼吸道有刺激作用。中毒表现可有头痛、恶心、眩晕。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '2-甲基-2-丙醇（叔丁醇）对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃，具刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。与氧化剂能发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3338, 3445, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。对眼睛、皮肤和粘膜有刺激作用。一般临床症状有头痛、眩晕、乏力、恶心、呕吐等。浓度高时有麻醉作用。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。长期接触可引起肝、肾功能损害，神经系统损伤等。本品可通过皮肤吸收。', '2-甲基-2-丁醇（叔戊醇）对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃、具有刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂接触发生反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3339, 3446, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '液体及其蒸气对眼睛、皮肤和呼吸道有刺激作用，吸入后影响神经系统。热解、遇酸产生有毒的氧化硫气体。', '对水生生物可能有害。应避免进入水体、土壤和地下水。', '本品易燃、具有刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3340, 3447, NULL, NULL, NULL, NULL, NULL, '第3.1类低闪点易燃液体', '吸入食入经皮吸收\n对眼睛、粘膜、呼吸道及皮肤有刺激作用，可引起化学性肺炎，对中枢神经系统有抑制作', '用。', '无资料', '本品极度易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3341, 3448, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点液体', '吸入、食入、经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。毒性与其他己醇异构物相似。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。高浓度蒸气可引起头痛、头晕、嗜睡、恶心、呼吸困难等。', '该物质对环境可能有危害，应特别注意对水体的污染。', '易燃，遇明火、高热有引起燃烧爆炸的危险。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3342, 3449, NULL, NULL, NULL, NULL, NULL, '第3.1类低闪点易燃液体', '吸入、食入、经皮吸收', '吸入或摄入对身体有害。蒸气或雾对眼、粘膜和上呼吸道有刺激性。对皮肤有刺激性。接触后出现烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '对水生生物有毒性。该物质对环境有危害，应特别注意对水体的污染。', '本品易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3343, 3450, NULL, NULL, NULL, NULL, NULL, '第3类 易燃液体', '吸入 食入 经皮吸收', '本品对眼睛、皮肤有刺激作用。吸入、摄入或经皮肤吸收后对身体有害。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3344, 3451, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入 食入 经皮吸收', '本品受热分解能释出有剧烈刺激作用的烟雾。', '无资料', '本品易燃', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3345, 3452, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。本品对眼睛、皮肤有刺激作用。未见有关毒性报道，可能其毒性与其他己醇异构物相似。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。长期接触可引起肝、肾功能损害，神经系统损伤等。本品可通过皮肤吸收。', '2-甲基-3-戊醇对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3346, 3453, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收', '本品对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生生物有害。', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3347, 3454, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '吸入蒸气可引起中毒。属烃类化合物，吸入高浓度蒸气可引起轻度呼吸道刺激、头晕、欣快感、精神错乱、恶心和呼吸困难；极高浓度吸入可致昏迷甚至死亡。对眼睛、皮肤和呼吸道有刺激性。', '对环境有危害，对大气可造成污染。', '本品易燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3348, 3455, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '昏迷、最后血压下降而死亡。长期接触可引起皮炎、周围神经炎。', '无资料', '本品可燃、高毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3349, 3456, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收', '本品有毒，并对眼睛和皮肤有刺激作用。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3350, 3457, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。污染而吸收引起。自觉脸部灼热、剧烈头痛、头晕、呼吸困难，呈现紫绀症。以后出现血尿、尿闭、精神障碍、肌肉抽搐。慢性中毒：可引起膀胱刺激症状。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '2-甲基苯胺对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，建议不要让其进入环境。在水生生物中可能发生生物蓄积。', '本品可燃，有毒。遇明火、高热可燃。受高热分解放出有毒的气体。与硝酸反应强烈。与强氧化剂、酸类接触可发生反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3351, 3458, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。高浓度接触可能引起头痛、眩晕、恶心、呕吐、中枢神经系统抑制、意识丧失等。长期接触可引起肝、肾功能损害，神经系统损伤等。本品可通过皮肤吸收。', '2-甲基吡啶对水生生物有毒性。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3352, 3459, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入、食入、经皮吸收', '毒作用似丙烯腈。动物急性中毒开始表现短时间兴奋，然后出现无力、气喘、紫绀、阵发性强直性抽搐、昏迷、死亡。实验表明，本品易通过兔和豚鼠皮肤吸收，局部无明显刺激反应，只有轻度充血。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '该物质对环境有危害，应特别注意对水体和土壤的污染。', '本品易燃、高毒。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，可能发生聚合反应，出现大量放热现象，引起容器破裂和爆炸事故。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3353, 3460, NULL, NULL, NULL, NULL, NULL, '第3.1类低闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '本品属低毒类。主要有麻醉及轻度刺激作用。可引起眼和呼吸道的刺激症状，重者有麻醉症状，甚至意识丧失。慢性影响：眼和呼吸道的轻度刺激。皮肤长期接触可发生轻度皮炎。', '对环境有危害，对水体可造成污染。', '本品极度易燃。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3354, 3461, NULL, NULL, NULL, NULL, NULL, '第3.1类 低闪点易燃液体', '吸入、食入、经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。资料报道，有致突变作用。受热分解放出具腐蚀性的烟雾。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。长期接触可引起肝、肾功能损害，神经系统损伤等。本品可通过皮肤吸收。', '2-甲基呋喃对水生生物有毒性。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品极度易燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3355, 3462, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入、食入、经皮吸收', '毒性似正辛烷。属低毒类。有麻醉作用。对眼睛、皮肤、粘膜有刺激作用。急性吸入后可由于心跳停止、呼吸麻痹、窒息而迅速死亡。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3356, 3463, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入经皮吸收', '本品有刺激和麻醉作用。', NULL, '本品极度易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3357, 3464, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '对皮肤、眼、粘膜、上呼吸道有刺激性。慢性作用：实验表明有致突变作用。长期接触可能引起肝、肾损害。', '对水生生物有毒性，可能对水体造成污染。', '遇明火、高热可燃。受热分解产生有毒的氮氧化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3358, 3465, NULL, NULL, NULL, NULL, NULL, '第4.1类易燃固体', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。在空气中实际能达到的浓度，未产生急性中毒效应。腹腔注射时，大鼠急性中毒征象为：软弱、共济失调、呼吸困难、体温下降。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。长期接触可引起肝、肾功能损害，神经系统损伤等。本品可通过皮肤吸收。', '2-甲基萘对水生生物有毒性。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3359, 3466, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '蒸气或雾对眼、粘膜和上呼吸道有刺激作用。对皮肤有刺激性。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3360, 3467, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入 食入 经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。蒸气和烟雾对眼睛、粘膜和上呼吸道有刺激作用。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3361, 3468, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、食入、经皮吸收可引起中毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。高浓度吸入可引起头痛、头晕、恶心、呕吐、嗜睡等症状。', '对水生生物有害。避免该物质进入环境。', '本品易燃、具有刺激性。遇明火、高热易燃烧爆炸。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3362, 3469, NULL, NULL, NULL, NULL, NULL, '第3.1类低闪点易燃液体', '吸入、食入、经皮吸收', '蒸气或雾对眼和上呼吸道有刺激性。对皮肤有刺激性。接触后出现烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '2-甲基戊烷（异己烷）对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品极度易燃，具刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3363, 3470, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。接触可引起头痛、头晕、恶心、呕吐、嗜睡等症状。高浓度接触可引起意识丧失。', '对水生生物有毒。该物质对环境可能有危害，应特别注意对水体的污染。', '易燃，遇明火、高热有燃烧爆炸的危险。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触猛烈反应。受高热分解产生有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3364, 3471, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品。', '吸入 食入 经皮吸收', NULL, '无资料', '本品可燃、有毒、具有刺激性、致敏性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3365, 3472, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入经皮吸收\n吸入、口服或经皮肤吸收对身体有害。其蒸气或雾对眼睛、粘膜和呼吸道有刺激性。中毒', '表现有头痛、恶心和呕吐。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3366, 3473, NULL, NULL, NULL, NULL, NULL, '第4.1类 易燃固体', '吸入 食入', '吸收后有微毒，可能引起过敏反应，有刺激作用。接触后可引起头痛、恶心、呕吐及惊厥。', '无资料', '本品易燃、具有刺激性、致敏性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3367, 3474, NULL, NULL, NULL, NULL, NULL, '第4.1类易燃固体', '吸入食入经皮吸收\n樟脑蒸气可造成急性重症中毒，出现意识丧失，牙关紧闭，甚至死亡。口服引起眩晕、精', '神错乱、谵妄、惊厥、昏迷，最后因呼吸衰竭而死亡。', '无资料', '本品易燃，有毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3368, 3475, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '本品有刺激作用。接触后可引起恶心、头痛、呕吐。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3369, 3476, NULL, NULL, NULL, NULL, NULL, '第3.1类低闪点易燃液体', '吸入、食入、经皮吸收', '以中枢神经系统抑制和呼吸道刺激作用为主。急性中毒：短期吸入高浓度蒸气出现流泪、咽干痛、胸闷、呼吸困难；结膜及咽部充血；肺部散在罗音；并有头昏、头痛、乏力、四肢麻木、步态不稳、恶心、呕吐、昏迷、抽搐等。个别发生急性肺水肿而死亡。急性期后可出现肝、肾功能损害。慢性影响：长期接触可出现神经衰弱综合征、肝肿大、肝功能异常、脱发等。皮肤接触可引起皮炎。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激性。', '对水生生物有毒性。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品极度易燃，具刺激性。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3370, 3477, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。对眼有刺激性。可引起皮肤刺激。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。长期接触可引起肝、肾功能损害，神经系统损伤等。本品可通过皮肤吸收。', '对水生生物有毒性。应避免进入水体、土壤和地下水。', '本品易燃、有毒、具有刺激性。遇明火、高热能引起燃烧爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3371, 3478, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。高浓度接触可引起头痛、头晕、恶心、呕吐等症状。', '对水生生物有毒性。应避免进入水体、土壤和地下水。', '本品易燃，其蒸气与空气混合，能形成爆炸性混合物。遇明火、高热能引起燃烧爆炸。受热分解产生有毒的氯化氢、溴化氢等气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3372, 3479, NULL, NULL, NULL, NULL, NULL, '第3.1类低闪点易燃液体', '吸入、食入、经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。高浓度接触可引起头痛、头晕、恶心、呕吐等症状。受热分解释放出有毒的氯化氢气体。', '对水生生物有毒性。应避免进入水体、土壤和地下水。', '本品易燃，其蒸气与空气混合，能形成爆炸性混合物。遇明火、高热能引起燃烧爆炸。受热分解产生有毒的氯化氢等气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3373, 3480, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '吞食后有剧毒。对眼睛、皮肤和呼吸道有刺激作用。长期或反复接触可能对中枢神经系统、肝脏和肾脏造成损害。', '对水生生物有毒性，可能对环境造成长期不利影响。', '可燃，受热分解释放出有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3374, 3481, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、皮肤接触、眼睛接触', '暴露严重损伤中枢神经，导致痉挛，可致死。症状有坐立不安、恐惧、肌肉僵硬、怕光、怕噪音、出冷汗。对眼睛、皮肤和呼吸道有刺激作用。', '对水生生物有毒性，可能对环境造成长期不利影响。', '可燃，受热分解释放出有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3375, 3482, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n对眼睛、皮肤、粘膜、上呼吸道有刺激性。进入体内可导致形成高铁血红蛋白血症。高浓度时', '可引起发绀，这种症状可持续2～4小时或更长时间。', '无资料', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3376, 3483, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤和呼吸道有刺激作用。可能导致高铁血红蛋白血症，出现紫绀。', '对水生生物有毒，可能对水体环境产生长期不良影响。', '本品可燃，有毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3377, 3484, NULL, NULL, NULL, NULL, NULL, '第8类 腐蚀性物质', '吸入 食入 经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤和粘膜有强烈刺激作用。吸入可引起喉、支气管痉挛、炎症，化学性肺炎、肺水肿等。', '对水生生物有毒，可能对水体环境产生长期不良影响', '本品可燃，具强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3378, 3485, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '吸入后，出现咳嗽和呼吸困难，对眼有刺激性，引起结膜刺激和流泪。', '对水生生物有毒，可能对水体环境产生长期不良影响', '本品可燃、高毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3379, 3486, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '生产工人可发生接触性湿疹。其蒸气和气溶胶对眼睛、粘膜、呼吸道和皮肤有刺激作用。吸入可能引起呼吸道刺激、头痛、头晕、恶心和呕吐。食入可能引起胃肠道刺激、恶心、呕吐和腹痛。皮肤接触可能引起刺激和过敏反应。眼睛接触可能引起刺激、发红和疼痛。', '无资料', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3380, 3487, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。吸入后可引起咳嗽、气短、头痛、恶心和呕吐。皮肤接触可引起灼伤、红肿、疼痛。眼睛接触可引起严重刺激、流泪、视力模糊。吞食后可引起口腔、咽喉、胃肠道刺激，出现恶心、呕吐、腹痛等症状。长期或反复接触可能对肝、肾造成损害。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '2-氯丙酸对水生生物有毒性。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。在水生生物中可能发生生物蓄积。', '本品可燃，具腐蚀性、强刺激性，可致人体灼伤。遇明火、高热可燃。与强氧化剂、强碱接触可发生反应。受热分解产生有毒的腐蚀性气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3381, 3488, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。吸入、摄入或经皮肤吸收后会中毒。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。吸入，可致喉、支气管炎、化学性肺炎、肺水肿等。皮肤接触可引起刺激、红肿、疼痛。眼睛接触可引起严重刺激、流泪、视力模糊。吞食后可引起口腔、咽喉、胃肠道刺激，出现恶心、呕吐、腹痛等症状。长期或反复接触可能对肝、肾造成损害。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '2-氯丙酸甲酯对水生生物有毒性。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。在水生生物中可能发生生物蓄积。', '本品易燃，具强刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。受高热分解，放出有毒的烟气。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3382, 3489, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和呼吸道有强烈的刺激作用。吸入后，可能因咽喉、支气管的痉挛、水肿，化学性肺炎、肺水肿而致死。中毒表现有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。皮肤接触可引起刺激、红肿、疼痛。眼睛接触可引起严重刺激、流泪、视力模糊。吞食后可引起口腔、咽喉、胃肠道刺激，出现恶心、呕吐、腹痛等症状。长期或反复接触可能对肝、肾造成损害。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '2-氯丙酸乙酯对水生生物有毒性。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。在水生生物中可能发生生物蓄积。', '本品易燃，具刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。受高热分解产生有毒的腐蚀性气体。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3383, 3490, NULL, NULL, NULL, NULL, NULL, '第3类易燃液体，类别3（高闪点液体）', '吸入、食入、皮肤接触、眼睛接触', '吸入、食入或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激性。吸入后可因喉、支气管的痉挛、炎症和水肿，化学性肺炎或肺水肿而致死。接触后可引起烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '对水生生物可能有毒性，可能对环境造成长期不利影响。', '易燃液体，其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3384, 3491, NULL, NULL, NULL, NULL, NULL, '第3类易燃液体', '吸入、食入、皮肤接触、眼睛接触', '吸入该物质可能会引起对健康有害的影响或呼吸道不适。对眼睛、皮肤和呼吸道有刺激作用。', '对水生生物可能有毒性，可能对环境造成长期不利影响。', '易燃液体，其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3385, 3492, NULL, NULL, NULL, NULL, NULL, '第3.1类低闪点易燃液体', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。引起疼痛和刺激症状。对眼睛、皮肤、粘膜有刺激作用。具麻醉性。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '2-氯丙烷对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。挥发后可参与形成光化学烟雾。', '本品极度易燃，具麻醉性。其蒸气与空气可形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。与氧化剂能发生强烈反应。受高热分解产生有毒的氯化物气体。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3386, 3493, NULL, NULL, NULL, NULL, NULL, '第3.1类低闪点易燃液体', '吸入食入经皮吸收', '喘息、喉炎、气短、头痛、恶心和呕吐。', '无资料', '本品极度易燃，具腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3387, 3494, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。长期接触可引起肝、肾功能损害，神经系统损伤等。本品可通过皮肤吸收。', '2-氯丁烷（仲丁基氯）对水生生物有毒性。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。在水生生物中可能发生生物蓄积。', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3388, 3495, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入 食入 经皮吸收', '吸入、口服或经皮肤吸收对身体有害。蒸气或雾对眼睛、粘膜和上呼吸道有刺激性。对皮肤有刺激性。慢性影响：对肝、肾有损害。', '对水生生物有害，可能对水体环境产生长期不良影响', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3389, 3496, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '对眼睛、皮肤和粘膜有强烈刺激作用。吸入、摄入或经皮肤吸收后对身体有害。', '对水生物有毒，对水生环境可能会引起长期有害作用。', '可燃，遇高热、明火有燃烧危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3390, 3497, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '胸痛、肺水肿。', '无资料', '本品易燃、有毒、强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3391, 3498, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。高浓度蒸气对眼、上呼吸道有刺激性。高浓度吸入出现头痛、头晕、嗜睡、恶心、呕吐，继之乏力、呼吸困难、紫绀、共济失调、抽搐、昏迷。重者发生脑和肺水肿。皮肤接触可出现皮肤红斑；可经皮吸收引起中毒。慢性影响有头痛、乏力、胃纳减退、血压降低和消瘦等。本品可通过皮肤吸收。', '2-氯乙醇对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。在水生生物中可能发生生物蓄积。', '本品易燃、剧毒、具有刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。与氧化剂能发生强烈反应。受高热分解产生有毒的腐蚀性烟气（光气、氯化氢）。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3392, 3499, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '本品对人体有毒。受热能分解出有毒烟雾。', '无资料', '本品可燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3393, 3500, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。本品有引起高铁血红蛋白血症的作用。中毒症状有紫绀、排尿困难。本品为确认致癌物，可导致膀胱癌。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '2-萘胺对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，不要让该物质进入环境。在水生生物中可能发生生物蓄积。', '本品可燃，有毒，为致癌物。遇明火、高热可燃。受高热分解放出有毒的气体。与氧化剂可发生反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3394, 3501, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入食入经皮吸收', '如吸入、摄入或经皮肤吸收后可致死。对眼睛、皮肤有刺激作用。本品为剧毒化学品，含氰基，可产生氰化氢，导致急性中毒。急性中毒：轻者有头痛、头晕、恶心、呕吐、胸闷、乏力、心悸等；重者出现意识障碍、抽搐、呼吸困难、血压下降、昏迷，甚至死亡。长期接触可能对肝脏、肾脏有影响。', '2-羟基丙腈对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。含氰基，可产生氰化氢，对水生生物有极高毒性。', '本品可燃，有毒，具刺激性。遇明火、高热可燃。受高热分解放出有毒的氰化氢气体。与强氧化剂、强还原剂、强酸、强碱接触可发生反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3395, 3502, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收对身体有害。蒸气或雾对眼、粘膜和上呼吸道有刺激性。对皮肤有刺激性。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3396, 3503, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。吸入能造成灼伤。皮肤较长时间接触有刺激性。大量口服引起恶心、呕吐。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '2-羟基丙酸乙酯对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃，具刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。与强氧化剂发生反应，可引起燃烧。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3397, 3504, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入、食入、经皮吸收', '造成皮肤刺激。造成严重眼刺激。可引起呼吸道刺激。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3398, 3505, NULL, NULL, NULL, NULL, NULL, '第8类腐蚀性品', '吸入、食入、皮肤接触、眼睛接触', '对皮肤、眼睛和呼吸道有强烈刺激作用。可引起皮肤灼伤、眼睛灼伤。吸入可引起呼吸道刺激，严重者可引起肺水肿。食入可引起消化道灼伤。', '对水生生物有毒性。', '遇明火、高热可燃。受热分解产生有毒的硫氧化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3399, 3506, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '本品受热分解释出有毒的氧化硫烟雾。对眼睛、皮肤、粘膜和呼吸道有强烈刺激作用。吸入可引起头痛、头晕、恶心、呼吸困难。严重者可引起肺水肿。食入可引起消化道灼伤。', '对水生生物有毒性，可能对水体环境造成长期不良影响。', '本品可燃、有毒。遇明火、高热有燃烧爆炸危险。受热分解产生有毒的硫氧化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3400, 3507, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入 食入 经皮吸收', '本品有刺激作用，高浓度时有麻醉性。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3401, 3508, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生物有毒，对水生环境可能会引起长期有害作用。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3402, 3509, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n有毒。对眼睛、皮肤和粘膜有中等刺激作用。吸入可引起喉、支气管的痉挛、炎症、化学', '性肺炎、肺水肿等。', '无资料', '本品可燃、具有腐蚀性、刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3403, 3510, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触', '本品为高毒除草剂。吸入、摄入或经皮肤吸收后会中毒。受热分解释出氮氧化物烟雾。', '对水生生物有极高毒性，可能导致长期不良影响。该物质可能在环境中造成持久性污染。', '本品可燃，有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3404, 3511, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、皮肤接触、眼睛接触', '高毒杀虫剂。误食后，可引起：一类为急性型，感心慌、头昏、恶心、低热，食欲不振，全身皮疹；重者腹痛、不省人事；另一为亚急性型，表现为各脏器及皮下广泛出血。', '对水生生物有剧毒。对水生环境可能会引起长期有害作用。使用适当的容器，以预防污染环境。', '本品可燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3405, 3512, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。其蒸气或雾对眼睛、皮肤、粘膜和上呼吸道有刺激作用，还可引起头痛、头晕、呼吸困难、咳嗽、恶心、呕吐、腹泻等；严重者有复视、耳聋、谵妄等，有时出现高铁血红蛋白血症。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。长期接触可引起肝、肾功能损害，神经系统损伤等。本品可通过皮肤吸收。', '2-戊醇（仲戊醇）对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3406, 3513, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。本品易燃，具刺激性。高浓度接触可引起头痛、头晕、恶心、呕吐、嗜睡、昏迷。对眼及皮肤有刺激性。未见慢性中毒病例。长期接触可致皮炎。', '对水生生物有毒性。该物质在环境中可被微生物分解，具有中等生物降解性。生物富集性较低。', '本品易燃，具刺激性。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3407, 3514, NULL, NULL, NULL, NULL, NULL, '第3.1类低闪点易燃液体', '吸入食入', '吸入、食入或经皮肤吸收后对身体有害。本品极度易燃，具刺激性。吸入后可引起头痛、头晕、恶心、呕吐、倦睡、不安、四肢无力等症状。对呼吸道粘膜和眼结膜有刺激作用。皮肤接触可引起刺激、红肿、疼痛。眼睛接触可引起刺激、流泪、视力模糊。长期接触可引起肝、肾功能损害，神经系统损伤等。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '2-戊烯对水生生物有毒性，对鱼类、甲壳类、藻类等水生生物有毒性作用。该物质在环境中较难降解，在土壤中可长期残留。可通过食物链在生物体内富集，对生态系统造成危害。对鸟类、哺乳动物等陆生生物也有毒性。应避免进入水体、土壤和地下水。该物质对环境有危害，应特别注意对地表水、土壤、大气和饮用水的污染。', '本品极度易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3408, 3515, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入\n对人体有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。吸收进入体内后可形成高铁血', '红蛋白而致紫绀。', '无资料', '本品可燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3409, 3516, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤和粘膜有刺激作用。', '无资料', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3410, 3517, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '本品有毒，对眼睛、皮肤有刺激作用。吸入、摄入或经皮肤吸收后可能对身体有害。可能引起高铁血红蛋白血症，出现紫绀。', '对水生环境可能会引起长期有害作用。', '可燃，遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3411, 3518, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。进入体内可形成高铁血红蛋白，致紫绀。长期接触可引起贫血、肝脾肿大等。', '对水生生物有极高毒性。对环境可能有危害，建议不要让其进入环境。', '本品可燃，有毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3412, 3519, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用。吸入可引起喉、支气管的炎症、水肿、痉挛，化学性肺炎或肺水肿。接触后可引起头痛、头晕、恶心、呕吐、咳嗽、气短。长期接触可引起高铁血红蛋白血症，出现紫绀。', '对水生生物有毒性，可能对水体环境造成长期不利影响。', '本品易燃，有毒，具强刺激性。遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3413, 3520, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、经皮吸收', '有毒。吸入、摄入或经皮肤吸收后会中毒。能腐蚀眼睛、皮肤和呼吸道粘膜，吸入后会发生化学性肺炎、肺水肿等。', '无资料', '本品可燃、有毒、具有腐蚀性、刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3414, 3521, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入食入经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期接触可引起高铁血红蛋白血症，出现紫绀、头晕、头痛、乏力等症状。', '对水生环境可能会引起长期有害作用。', '本品可燃，有毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3415, 3522, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入、食入、经皮吸收', '具腐蚀性。蒸气和粉尘对眼睛、皮肤和粘膜有刺激性。遇水反应释出氯化氢气体，受热分解出氯气和氮氧化物。吸入可引起喉、支气管痉挛、炎症、化学性肺炎、肺水肿等。', '该物质对环境有危害，应特别注意对水体的污染。遇水反应释出氯化氢气体，对水体和土壤造成酸化污染。受热分解产生氮氧化物和氯化氢等有害气体，对大气环境造成污染。该物质属于腐蚀性物质，对水生生物有毒性影响。', '本品可燃、有毒、具有腐蚀性、刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3416, 3523, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、上呼吸道和皮肤有刺激性。吸入可引起呼吸道刺激。误服可引起恶心、呕吐、腹痛等胃肠道症状。长期或反复接触可能引起皮肤过敏。', '对水生生物有毒性。该物质可能在环境中造成持久性污染。避免释放到土壤、水体和大气中。', '本品可燃，有毒，具刺激性。遇明火、高热可燃。受热分解产生有毒的氮氧化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3417, 3524, NULL, NULL, NULL, NULL, NULL, '急性毒性-经口,类别3；皮肤腐蚀/刺激,类别2；严重眼损伤/眼刺激,类别2；对水环境的危害-急性毒性,类别1；对水环境的危害-慢性毒性,类别1', '吸入、食入、经皮吸收', '吞食后有毒。吸入有毒。对眼睛、皮肤和呼吸道有刺激作用。砷化合物具有毒性，长期接触可能导致砷中毒。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '可燃，受热可能发生爆炸性分解。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3418, 3525, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期接触可引起神经系统损害。', '无资料', '本品可燃，有毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3419, 3526, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。本品为可疑致癌物（IARC分类：2B类，可能对人类致癌）。急性中毒主要损害中枢神经系统和肝脏。吸入高浓度蒸气可引起头痛、眩晕、恶心、呕吐、嗜睡、共济失调、意识模糊、昏迷等。严重者可出现肝损害，表现为黄疸、肝功能异常。长期接触可引起肝、肾功能损害，神经系统损伤。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '2-硝基丙烷对水生生物有毒性。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。在水生生物中可能发生生物蓄积。', '本品易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。受热分解产生有毒的氮氧化物气体。与氧化剂接触猛烈反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3420, 3527, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收后对身体有害。对眼睛和皮肤有刺激作用。可引起高铁血红蛋白血症而出现紫绀。易经皮肤吸收中毒。', '无资料', '本品可燃，有毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3421, 3528, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入 食入 经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤和粘膜有刺激作用。蒸气可引起呼吸道刺激。', NULL, '易燃,其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3422, 3529, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收，可能引起中毒死亡。蒸气或雾对眼睛、粘膜和上呼吸道有刺激性。对皮肤有刺激性。吸收进入人体后，可引起高铁血红蛋白血症，出现紫绀。', '对水生生物有毒性。可能对水生环境造成长期不利影响。', '本品可燃，有毒，具刺激性。遇明火、高热可燃。受热分解产生有毒的氮氧化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3423, 3530, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。对眼睛、呼吸道和皮肤有刺激作用。吸收进入体内可引起高铁血红蛋白血症，出现紫绀。严重中毒者可致死。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '2-硝基甲苯对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，应特别注意对水体的污染。在水生生物中可能发生生物蓄积。', '本品可燃，有毒，具刺激性。遇明火、高热可燃。受高热分解放出有毒的气体。与强氧化剂、强还原剂、强碱接触可发生反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3424, 3531, NULL, NULL, NULL, NULL, NULL, '第4.1类易燃固体', '吸入 食入 经皮吸收', '吸入、口服或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期接触可引起神经系统损害。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3425, 3532, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '对粘膜和皮肤有刺激作用。吸收后，产生高铁血红蛋白血症。急性中毒病人可有头痛、头昏、乏力、皮肤粘膜有紫绀、手指麻木等症状。重者可出现胸闷、呼吸困难、心悸，甚至休克。长期接触可引起肝、肾功能损害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。本品可通过皮肤吸收。', '对水生生物有毒性。该物质对环境有危害，应特别注意对水体的污染。在环境中可能持久存在，不易降解。对土壤和地下水可能造成污染。', '遇明火、高热可燃。与强氧化剂可发生反应。受高热分解，产生有毒的氮氧化物和氯化物气体。有腐蚀性。其蒸气与空气可形成爆炸性混合物，遇明火、高热有燃烧爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3426, 3533, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '吸入、摄入对身体有害。对眼睛、皮肤、粘膜及呼吸道有刺激作用。中毒表现有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。吸入后可能由于喉、支气管的痉挛、炎症和水肿，化学性肺炎、肺水肿而致死。', '无资料', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3427, 3534, NULL, NULL, NULL, NULL, NULL, '第4.1类易燃固体', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激性。进入体内可形成高铁血红蛋白，致紫绀。长期接触可引起贫血、肝脾肿大等。', '对水生生物有极高毒性。', '本品易燃，具刺激性。遇明火、高热可燃。受热分解放出有毒的氧化氮烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3428, 3535, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。对眼睛和皮肤有刺激作用。经皮肤吸收迅速，吸收后引起高铁血红蛋白血症，出现紫绀。急性中毒主要表现为头痛、头晕、恶心、呕吐、乏力、发绀等症状。严重者可出现呼吸困难、抽搐、昏迷。长期接触可引起贫血、肝肾功能损害。', '对水生生物有毒性。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品可燃，有毒，具刺激性。遇明火、高热可燃。受热分解产生有毒的氮氧化物和溴化氢气体。与氧化剂接触可发生化学反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3429, 3536, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '无资料', '本品具有刺激作用，有轻度麻醉作用。高浓度时有窒息效应。', '无资料', '本品易燃，具刺激性，具窒息性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3430, 3537, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入 食入 经皮吸收', '本品对人皮肤及眼仅引起轻微刺激作用。', '无资料', '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3431, 3538, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入 食入', '吸入、食入或经皮肤吸收后对身体有害。本品易燃，具刺激性。对呼吸道粘膜和眼结膜有轻度刺激作用。中毒表现有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。皮肤接触可引起刺激、红肿、疼痛。眼睛接触可引起刺激、流泪、视力模糊。长期接触可引起肝、肾功能损害，神经系统损伤等。本品可通过皮肤吸收。', '2-辛烯对水生生物有毒性，对鱼类、甲壳类、藻类等水生生物有毒性作用。该物质在环境中较难降解，在土壤中可长期残留。可通过食物链在生物体内富集，对生态系统造成危害。对鸟类、哺乳动物等陆生生物也有毒性。应避免进入水体、土壤和地下水。该物质对环境有危害，应特别注意对水体的污染。', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3432, 3539, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '本品有毒。有腐蚀性。受高热放出有毒气体。', '无资料', '本品易燃、有毒、具有腐蚀性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3433, 3540, NULL, NULL, NULL, NULL, NULL, '第3类 易燃液体', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤和粘膜有刺激作用。', '对水生生物有害', '高度易燃液体和蒸气。其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3434, 3541, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '误服、蒸气经吸入或皮肤吸收都能引起中毒。进入体内能形成高铁血红蛋白，可引起紫绀。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '该物质对环境有危害，应特别注意对水体的污染。', '本品可燃、有毒。遇明火、高热可燃。受热分解，放出有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3435, 3542, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入食入', '对眼睛、皮肤、粘膜、上呼吸道有刺激性。长期接触可引起眼睛的强烈刺激或灼伤。', '无资料', '本品可燃，有毒，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3436, 3543, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入 食入 经皮吸收\n有腐蚀性。蒸气对眼睛、皮肤和粘膜有强烈刺激性。吸入，可引起喉、支气管炎症、痉挛，', '化学性肺炎、肺水肿等。', '无资料', '本品可燃、具有腐蚀性、强刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3437, 3544, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '本品对粘膜、上呼吸道、眼和皮肤有强烈的刺激性。吸入后，可因喉及支气管的痉挛、炎症、水肿，化学性肺炎或肺水肿而致死。接触后可引起烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。能引起皮肤灼伤。', '该物质对水生生物可能具有毒性作用。由于具有中等亲脂性（log Kow=0.92），可能在生物体内有一定程度的生物富集。应避免该物质进入环境，特别是水体。', '本品可燃，有毒，具强刺激性。遇明火、高热可燃。受高热分解产生有毒的溴化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3438, 3545, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。其蒸气或雾对眼睛、粘膜和上呼吸道有刺激作用。接触后有可能引起神经系统功能紊乱。长期接触可能对肝脏、肾脏有影响。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '2-溴丙烷对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。挥发后可参与形成光化学烟雾。', '本品易燃，具刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。与氧化剂能发生强烈反应。受高热分解产生有毒的溴化物气体。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3439, 3546, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收对身体有害。可引起灼伤。对粘膜、上呼吸道、眼、皮肤等组织有极强的破坏作用。吸入后可能因喉、支气管的炎症、水肿、痉挛，化学性肺炎、肺水肿而致死。中毒表现有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心、呕吐。', '对水生生物有毒性。遇水分解产生溴化氢，对水体环境造成污染。', '本品可燃、具有强腐蚀性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3440, 3547, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入 食入 经皮吸收', '气体可能会引起头晕或窒息。', '对水生生物有毒性。该物质对环境有危害，应特别注意对水体的污染。', '高度易燃,其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3441, 3548, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、食入、经皮吸收后对眼睛、皮肤、粘膜和上呼吸道有刺激性。高浓度吸入可引起中枢神经系统抑制。', '对水生生物有害。避免该物质进入环境。', '本品可燃，有毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3442, 3549, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入 食入 经皮吸收', NULL, '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3443, 3550, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '对粘膜、上呼吸道、眼睛和皮肤有强烈刺激性。吸入后可由于喉和支气管的痉挛、炎症和水肿以及化学性肺炎、肺水肿而致死。中毒表现有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '无资料', '本品可燃，有毒，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3444, 3551, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入 食入 经皮吸收', '吸入、口服或经皮吸收，对机体有危害。对眼和皮肤有刺激性（来源：道客巴巴）', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3445, 3552, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '2-乙基-1，3-己二醇对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '遇高热、明火或与氧化剂接触，有引起燃烧的危险。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3446, 3553, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。吸入、摄入或经皮肤吸收，对机体可能有害。对皮肤有刺激性。对眼有强烈刺激作用，接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。长期接触可引起肝、肾功能损害，神经系统损伤等。本品可通过皮肤吸收。', '2-乙基-1-丁醇对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3447, 3554, NULL, NULL, NULL, NULL, NULL, '第3.1类低闪点易燃液体', '吸入 食入 经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对环境有危害，对水体、土壤和大气可造成污染。', '本品极度易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3448, 3555, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '对眼睛有强烈的刺激作用。对粘膜、上呼吸道有刺激性。吸收进入体内可引起高铁血红蛋白血症，出现紫绀。', '对环境可能有危害，在环境中能被生物降解。', '本品易燃，有毒，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3449, 3556, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '有毒，对眼睛，皮肤和粘膜有刺激作用。接触可引起头痛、恶心和呕吐等。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3450, 3557, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收对身体有害。吸入后可因喉、支气管的痉挛和水肿，化学性肺炎或肺水肿而致死。长时间接触可引起强烈刺激或灼伤。', '2-乙基丁胺对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃，遇高热、明火或与氧化剂接触，有引起燃烧的危险。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3451, 3558, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '本品对皮肤有刺激作用。其蒸气或烟雾对眼睛、上呼吸道粘膜有刺激作用。', '无资料', '本品易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。若遇高热，可发生聚合反应，放出大量热量而引起容器破裂和爆炸事故。具有刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3452, 3559, NULL, NULL, NULL, NULL, NULL, '第8.2类 碱性腐蚀品', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和呼吸道有强烈的刺激作用。吸入可引起咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '对环境有危害，对水体可造成污染。', '本品易燃，具腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3453, 3560, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有毒。', '对水生物有剧毒, 对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3454, 3561, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n短暂吸入', '有运动失调、呼吸困难和抽搐。可致皮肤灼伤，患处呈棕红色，对皮肤有致敏作用。', '无资料', '本品易燃、有毒、刺激性、致敏性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3455, 3562, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3456, 3563, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '本品对胆碱酯酶有抑制作用。吸入、摄入或经皮肤吸收后可引起中毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。急性中毒可出现头痛、头晕、乏力、恶心、呕吐、流涎、多汗、瞳孔缩小、肌肉震颤等症状。严重者可出现肺水肿、呼吸衰竭、昏迷。', '对水生生物有毒性。可能对水生环境造成长期不利影响。', '本品可燃、有毒、具有刺激性。遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3457, 3564, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n直接作用于能量代谢过程，吸收后基础代谢率明显增加，体温增加，', NULL, '无资料', '本品易燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3458, 3565, NULL, NULL, NULL, NULL, NULL, '自反应物质和混合物', '吸入、食入、皮肤接触、眼睛接触', '吸入有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。接触可引起过敏反应。', '对水生生物有害。', '遇热有火灾危险。遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3459, 3566, NULL, NULL, NULL, NULL, NULL, '自反应物质和混合物B型', '吸入、食入、皮肤接触、眼睛接触', '吸入有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。接触可引起过敏反应。具有爆炸性，可能引起严重的眼部损伤和皮肤灼伤。', '对水生生物有害。对环境有危害。', '遇热有火灾或爆炸危险。遇明火、高热可燃。受热分解产生有毒气体。具有爆炸性，在常温下可能发生自反应分解。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3460, 3567, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。接触可引起过敏反应。', '对水生生物有害。可能对水生环境造成长期不利影响。', '遇明火、高热可燃。受热分解产生有毒气体。遇热有火灾或爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3461, 3568, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。接触可引起过敏反应。', '对水生生物有害。可能对水生环境造成长期不利影响。', '遇明火、高热可燃。受热分解产生有毒气体。遇热有火灾或爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3462, 3569, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '本品为高毒杀鼠剂。误服或接触可引起中毒。中毒症状包括鼻出血、牙龈出血、皮下出血、便血、尿血等出血倾向。严重者可因内脏出血而死亡。对眼睛、皮肤有刺激性。', '对水生生物有极高毒性，可能对水体环境造成长期不良影响。对鸟类和哺乳动物有毒性。', '遇明火、高热可燃。受高热分解，放出有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3463, 3570, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '本品为高毒杀虫剂。中毒症状包括恶心、呕吐、腹痛、腹泻、眩晕、头痛、出汗、流涎、肌肉震颤、惊厥、呼吸困难等。严重者可因呼吸衰竭而死亡。对眼睛、皮肤、粘膜有刺激性。', '对水生生物有极高毒性，可能对水体环境造成长期不良影响。对鸟类和哺乳动物有毒性。', '本品不燃。受高热分解，放出高毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3464, 3571, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吞食后有毒。跟皮肤接触有毒。中毒症状包括恶心、呕吐、腹痛、腹泻、眩晕、头痛、出汗、流涎、肌肉震颤、惊厥、呼吸困难等。对眼睛、皮肤、粘膜有刺激性。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。对鸟类和哺乳动物有毒性。', '遇明火、高热可燃。受热分解产生有毒的氮氧化物、一氧化碳、二氧化碳等气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3465, 3572, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吞食后有毒。对眼睛、皮肤、粘膜有刺激性。中毒症状包括恶心、呕吐、腹痛、腹泻、眩晕、头痛、出血倾向（如鼻出血、牙龈出血、皮肤瘀斑、血尿、便血等）、关节疼痛、肌肉疼痛等。严重中毒可导致内出血、休克、昏迷甚至死亡。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。对鸟类和哺乳动物有毒性。', '遇明火、高热可燃。受热分解产生有毒的氮氧化物、一氧化碳、二氧化碳等气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3466, 3573, NULL, NULL, NULL, NULL, NULL, '第5.2类有机过氧化物，D型', '吸入、食入、皮肤接触、眼睛接触', '吸入该物质可能会引起对健康有害的影响或呼吸道不适。皮肤接触可能引起刺激。眼睛接触可能引起严重刺激。食入可能引起胃肠道刺激。', '可能对水生环境造成危害', '受热、摩擦、撞击或接触污染可能引起火灾或爆炸。与可燃物、还原剂、酸类、胺类等接触可能发生剧烈反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3467, 3574, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '对动物有强致癌作用，对人为可疑致癌物。接触本品可引起皮炎。', '无资料', '本品可燃', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3468, 3575, NULL, NULL, NULL, NULL, NULL, '第8.2类 碱性腐蚀品', '吸入、食入、经皮吸收', '本品具有强腐蚀性，可致人体灼伤。对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用。吸入可引起喉、支气管痉挛、炎症、水肿，化学性肺炎或肺水肿。接触可引起灼伤、咳嗽、喘息、喉炎、气短、头痛、恶心、呕吐等。', '对水生生物有害。该物质对环境有危害，应特别注意对水体的污染。', '本品可燃、具有腐蚀性、可致人体灼伤。遇明火、高热有引起燃烧的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3469, 3576, NULL, NULL, NULL, NULL, NULL, '第5.2类 有机过氧化物，D型', '吸入、食入、经皮吸收', '对皮肤、眼睛和呼吸道有刺激性。高浓度接触可能导致严重灼伤。长期或反复接触可能引起皮肤过敏。', '对水生生物可能有害，可能导致长期不良影响。', '易燃，受热、摩擦、撞击或与杂质接触可能发生爆炸。燃烧产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3470, 3577, NULL, NULL, NULL, NULL, NULL, '第5.2类有机过氧化物，D型；第3类易燃液体；危害水生环境-急性毒性，类别2', '吸入、食入、皮肤接触、眼睛接触', '吸入该物质可能会引起对健康有害的影响或呼吸道不适。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期接触可能对肝脏、肾脏有影响。', '对水生生物有害。', '接触火焰可能会产生膨胀或爆炸性分解。遇明火、高热极易燃烧爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3471, 3578, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入、食入、经皮吸收', '如果被吞食，可能会造成严重肺部损伤。对皮肤有刺激性。气体可能会引起头晕或窒息。', '对水生物有剧毒,对水生环境可能会引起长期有害作用。', '易燃,其蒸气与空气混合，能形成爆炸性混合物', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3472, 3579, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入、食入、经皮吸收', '如果被吞食，可能会造成严重肺部损伤。对皮肤有刺激性。气体可能会引起头晕或窒息。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '高度易燃，其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3473, 3580, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入、食入、经皮吸收', '吸入可引起支气管炎或肺水肿。高浓度蒸气对眼有轻度刺激性；液体可引起眼部暂时性红肿和疼痛。液体对皮肤有轻度刺激性；反复接触可致皮炎。口服引起恶心、呕吐、腹胀和头痛等。', '该物质对环境有危害，对水体可造成污染。', '本品易燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3474, 3581, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入 食入 经皮吸收', '本品具有刺激性。', '无资料', '本品易燃', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3475, 3582, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '本品具有强烈的刺激性和腐蚀性。吸入蒸气可引起呼吸道刺激、头痛、头晕、恶心、呕吐、腹痛、衰竭、昏迷等症状。对皮肤可造成腐蚀性灼伤。眼睛接触可引起严重刺激和灼伤。长期反复接触可引起皮肤脱脂和干燥。', '对水生生物有毒性，可能对水生环境造成长期不良影响。', '本品可燃、有毒、为可疑致癌物、具有腐蚀性、刺激性、可致人体灼伤。遇高热、明火有燃烧危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3476, 3583, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后可引起中毒。刺激眼睛、皮肤和呼吸系统。损害神经系统、肝和肾。', '对水生生物有害，可能对水体造成污染。', '易燃，遇明火、高热可燃。受热分解产生有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3477, 3584, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入、食入、经皮吸收', '对粘膜有刺激作用，高浓度时有麻醉作用。', '对水生物有剧毒,对水生环境可能会引起长期有害作用。', '易燃,其蒸气与空气混合，能形成爆炸性混合物', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3478, 3585, NULL, NULL, NULL, NULL, NULL, '第3.2类 高闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '吸入有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。高浓度蒸气可引起麻醉作用，出现头痛、头晕、嗜睡、意识模糊等症状。长期或反复接触可能对中枢神经系统造成损害。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。该物质在环境中可能持久存在，并在生物体内蓄积。', '高度易燃，其蒸气与空气混合，能形成爆炸性混合物。遇明火、高热极易燃烧爆炸。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3479, 3586, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '属低毒类。对眼睛、皮肤、粘膜和上呼吸道有刺激性。不易经皮肤吸收。吸入、皮肤接触及吞食有害。', '该物质对环境可能有危害，对水体应给予特别注意。', '遇高热、明火或与氧化剂接触，有引起燃烧的危险。受热分解产生有毒的氰化氢、氧化氮等气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3480, 3587, NULL, NULL, NULL, NULL, NULL, '第6.1类：毒害品', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。可引起呕吐、指端、口唇、耳廓紫绀，呼吸困难等。吸入后可引起咳嗽、呼吸困难、头痛、头晕、恶心、呕吐等症状。皮肤接触可引起刺激、红肿、疼痛。眼睛接触可引起严重刺激、流泪、视力模糊。吞食后可引起口腔、咽喉、胃肠道刺激，出现恶心、呕吐、腹痛等症状。长期接触可能对肝脏、肾脏、血液系统有影响。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。本品为可疑致癌物2B类。', '3,4-二氯苯胺对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。在水生生物中可能发生生物蓄积。', '本品可燃，有毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3481, 3588, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '对人体有毒。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。受热分解放出有毒气体。', '无资料', '本品可燃、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3482, 3589, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品，急性毒性-口服，类别2。', '吸入、食入、皮肤接触、眼睛接触', '吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '该物质对环境可能有危害，对水体应给予特别注意。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3483, 3590, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入\n有毒。有强麻醉作用。极微含量时即能刺激皮肤、眼睛和粘膜。接触症状包括烧灼感、咳\n嗽、眩晕、喉炎、气短、头痛、恶心和呕吐。吸入可引起喉炎，支气管炎，化学性肺炎，', '肺水肿。', '无资料', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3484, 3591, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入食入经皮吸收', '对眼有刺激性。皮肤接触可引起红斑、大疱，或发生湿疹。', NULL, '本品可燃，有毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3485, 3592, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '对皮肤、粘膜及呼吸道有刺激作用。吸收后导致体内形成高铁血红蛋白，足量的高铁血红蛋白引起紫绀。', '对水生生物有害。', '遇明火、高热可燃。与强氧化剂可发生反应。受高热分解，产生有毒的氮氧化物和氯化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3486, 3593, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。长期接触可引起肝、肾功能损害，神经系统损伤等。本品可通过皮肤吸收。', '3,5,5-三甲基己醇对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃，具刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3487, 3594, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收', '本品对皮肤、粘膜有强烈的刺激作用和腐蚀作用。吸入后可引起呼吸道刺激、咳嗽、胸闷、呼吸困难，重者可引起肺水肿。食入后可引起口腔、咽喉、食道和胃部灼伤，出现恶心、呕吐、腹痛、衰竭、昏迷等症状。长期接触可引起慢性中毒，表现为头痛、头晕、乏力、失眠等症状。', '对水生生物有毒，可能对水体造成污染。', '本品可燃、有毒、为可疑致癌物、具有腐蚀性、刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3488, 3595, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后会中毒。进入体内，可形成高铁血红蛋白致发生紫绀、头痛、眩晕、恶心等。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生生物有害，可能对水体环境造成长期不良影响。', '本品可燃、有毒。遇明火、高热可燃。与氧化剂可发生反应。受高热分解，放出有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3489, 3596, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、经皮吸收', '吸入、摄入或经皮吸收后有害。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用，可引起皮肤灼伤和眼部严重损伤。可能引起皮肤致敏作用。', '该物质对环境可能有危害，对水体应给予特别注意。', '遇明火、高热可燃。受热分解产生有毒的氯化氢气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3490, 3597, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。其蒸气或雾对眼睛、皮肤、粘膜和上呼吸道有刺激作用，可引起头痛、眩晕、恶心、呕吐、精神迟钝、腹痛、腹泻等。高浓度接触可引起神经系统损害，出现抽搐、昏迷等症状。', '该物质对环境可能有危害，对水体应给予特别注意。在环境中可被生物降解，但降解速度较慢。', '本品易燃，具刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触猛烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3491, 3598, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入、食入、经皮吸收', '对粘膜有刺激作用，高浓度时有麻醉作用。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃、具有刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3492, 3599, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。可引起高铁血红蛋白血症，出现紫绀、头晕、呼吸困难等症状。', '对水生物有毒，对水生环境可能会引起长期有害作用', '遇明火、高热可燃。受热分解产生有毒的氮氧化物和氯化氢气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3493, 3600, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收后，可引起中毒死亡。对眼睛、粘膜、呼吸道及皮肤有刺激作用。吸收进入体内引起高铁血红蛋白血症，出现紫绀。中毒表现有恶心、眩晕、头痛等。', '对水生生物有害。避免进入水体、土壤和地下水。', '本品可燃，有毒，具刺激性。遇明火、高热可燃。受热分解产生有毒的氮氧化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3494, 3601, NULL, NULL, NULL, NULL, NULL, '第8类 腐蚀品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。吸入后，可引起喉、支气管的痉挛、炎症和水肿、化学性肺炎、肺水肿等。遇水或潮湿空气产生氯化氢气体，对呼吸道有强烈刺激作用。', '对水生生物有害。避免进入水体、土壤和地下水。', '本品易燃、有毒、具有强刺激性。遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3495, 3602, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '属中等毒类。对眼睛、皮肤、粘膜和上呼吸道有刺激性。吸入、摄入或经皮肤吸收后对身体有害。中毒表现有头痛、头晕、乏力、恶心、呕吐、腹痛等症状。', '该物质对环境有危害，对水体应给予特别注意。', '遇明火、高热可燃。受高热分解，放出有毒的氮、溴化物烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3496, 3603, NULL, NULL, NULL, NULL, NULL, '第5.2类有机过氧化物，D型', '吸入、食入、皮肤接触、眼睛接触', '吸入该物质可能会引起对健康有害的影响或呼吸道不适。对眼睛、皮肤和呼吸道有刺激性。长期或反复接触可能引起皮肤过敏。有机过氧化物具有氧化性，可能引起灼伤。', '对水生生物有害。避免进入水体、土壤和地下水。', '接触火焰可能会产生膨胀或爆炸性分解。受热、撞击、摩擦可能引起爆炸。与还原剂、有机物、易燃物等接触可能发生剧烈反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3497, 3604, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期接触可引起头痛、头晕、乏力等神经系统症状。', '对水生生物有毒，可能对水体环境造成长期不良影响。', '遇明火、高热可燃。受热分解产生有毒的氰化物和氮氧化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3498, 3605, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '本品为第二代抗凝血杀鼠剂，毒性较大。误食可引起内出血，表现为牙龈出血、鼻衄、皮下瘀斑、血尿、便血等。严重者可因内脏出血而死亡。对皮肤和眼睛有轻微刺激性。具有抗凝血作用，可引起凝血功能障碍。', '对水生生物有剧毒，对水生环境可能会引起长期有害作用。对土壤生物可能有害。', '遇明火、高热可燃。受热分解产生有毒烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3499, 3606, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入，眼睛及皮肤接触', '恶心、呕吐、血中尿素氮量提高，刺激皮肤', '对水生生物有毒，可能对水体环境产生长期不良影响。对生态系统可能造成长期有害影响，特别是对水生生态系统。在环境中具有中等持久性，可被生物降解，但降解速度较慢。具有生物富集潜力，可能在生物体内积累。', '本品有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3500, 3607, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收', '本品为高毒杀鼠剂，吸入、摄入或经皮肤吸收后会中毒。能影响凝血作用。', '无资料', '本品可燃、剧毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3501, 3608, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '高毒抗凝血类杀鼠剂。急性中毒潜伏期较长，一般为1-7天。中毒后可抑制凝血酶原合成，导致毛细血管损害和凝血功能障碍。临床表现包括鼻出血、牙龈出血、咯血、便血、尿血、皮肤瘀斑及紫癜、关节周围出血、月经过多等出血症状。严重者可出现消化道大出血、颅内出血、多器官功能障碍，危及生命。具有致畸、致突变、致癌作用。', '对水生生物有极高毒性，在环境中具有持久性和生物富集性。', '本品可燃、高毒、具有刺激性。遇明火、高热可燃。受高热分解，放出有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3502, 3609, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品；皮肤腐蚀/刺激，类别2；严重眼损伤/眼刺激，类别2；特异性靶器官毒性-单次接触，类别3', '吸入、食入、皮肤接触、眼睛接触', '本品不易经皮肤吸收。吸入过量本品粉尘，可引起高铁血红蛋白血症。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。接触可引起头痛、头晕、恶心、呕吐、紫绀等症状。长期接触可引起贫血、肝肾功能损害。', '对水生生物有毒性。对环境有害。', '遇明火、高热可燃。受热分解放出有毒的氧化氮烟气。与强氧化剂接触可发生化学反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3503, 3610, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '有毒。对眼睛、皮肤、粘膜有刺激作用。进入体内，可形成高铁血红蛋白致紫绀。受热分解出氮氧化物和氰烟雾。', '对水生生物有毒性。', '遇明火、高热可燃。受高热分解，放出有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3504, 3611, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品；急性毒性-口服，类别3；急性毒性-吸入，类别3；危害水生环境-急性毒性，类别1；危害水生环境-慢性毒性，类别1', '吸入、食入、皮肤接触', '对人体有毒。有刺激作用。资料报道，为可疑致癌物。吞咽会中毒，吸入会中毒。', '对水生生物毒性极大并具有长期持续影响。对环境有害。', '不易燃，遇明火、高热可燃。受热分解放出有毒的砷和氧化氮烟雾。受高热或接触酸或酸雾放出剧毒的烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3505, 3612, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '有毒。对皮肤、粘膜有刺激作用，并有麻醉作用。', '无资料', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3506, 3613, NULL, NULL, NULL, NULL, NULL, '第3.1类低闪点易燃液体', '吸入、食入、经皮吸收', '蒸气对眼及上呼吸道有强刺激性，严重者伴有恶心、眩晕、头痛等。接触可发生接触性皮炎。', '无资料', '本品极度易燃，剧毒，具腐蚀性、强刺激性，可导致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3507, 3614, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。受热分解释出氮氧化物。', '无资料', '本品可燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3508, 3615, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入 食入 经皮吸收', '本品及其蒸气对眼睛、皮肤和上呼吸道系统有强烈的刺激作用。', '对环境有危害，对水体和大气可能造成污染。', '本品易燃、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3509, 3616, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '本品对眼睛、皮肤、呼吸道粘膜具刺激作用。其毒性大于甲基异丙烯甲酮。', '对水生生物有毒性，可能对水体造成污染。', '易燃，蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3510, 3617, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '头痛、恶心和呕吐。吸入、口服或经皮吸收后，严重中毒者均可能死亡。', '对水生生物有毒性，可能对水体造成污染。', '本品易燃，蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3511, 3618, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激性。吸入可引起头痛、头晕、恶心、呼吸困难，严重者可致肺水肿、呼吸衰竭。高浓度接触可引起中枢神经系统抑制，出现意识模糊、抽搐甚至死亡。', '对水生生物有极高毒性。可能对水环境造成长期不良影响。在环境中可能通过生物富集和生物放大作用在食物链中累积。', '本品有毒、刺激性。易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触猛烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3512, 3619, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '本品属低毒物质。对眼睛有刺激作用。受热分解放出有毒的溴和氮氧化物。吞咽有害。皮肤接触可能引起刺激。', '该物质对环境可能有危害，对水体应给予特别注意。', '受热分解，放出有毒的烟气。与氧化剂可发生反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3513, 3620, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入，食入，皮肤及眼睛接触\n暴露症状为腹泻、恶心、呕吐、多涎、头痛、瞳孔缩小、肌肉运动失调，吸入和食入引起', '中毒，并抑制胆碱酯酶的活性，影响神经系统，导致死亡', NULL, '本品有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3514, 3621, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有刺激作用。吸收进入体内后，可形成高铁血红蛋白而引起紫绀。', '对环境可能有危害，对水体应给予特别注意。', '本品可燃、有毒、具有刺激性。遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3515, 3622, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。其蒸气或烟雾对眼睛、皮肤、粘膜和呼吸道有刺激作用。', '对环境可能有危害，对水体应给予特别注意。', '本品易燃、具有刺激性。遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3516, 3623, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入 食入 经皮吸收\n其蒸气对眼睛、皮肤、粘膜和上呼吸道有刺激性；对皮肤有脱脂作用，长期接触可致皮炎。', '未见人的中毒报道。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3517, 3624, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '吸入或口服对身体有害。对皮肤有刺激作用。其蒸气或雾对眼睛、粘膜和上呼吸道有刺激作用，高浓度有麻醉作用。', '对环境有危害，对水体可造成污染。', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3518, 3625, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '吸入、口服或经皮肤吸收对身体有害。蒸气和液体有刺激性。', '对水生生物有中等毒性，可能对水生生态系统造成长期影响。', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3519, 3626, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收对身体有害。蒸气或雾对眼睛、粘膜和上呼吸道有刺激性。接触后可引起头痛、头晕、恶心、呕吐、嗜睡等。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃，具刺激性。遇高热、明火有引起燃烧的危险。与强氧化剂接触可发生化学反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3520, 3627, NULL, NULL, NULL, NULL, NULL, '第8.3类 其它腐蚀品', '吸入、食入', '有刺激性。', '无资料', '本品可燃，具强腐蚀性、刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3521, 3628, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。可引起头痛、头晕、恶心、呕吐、腹痛、腹泻、虚脱、体温下降和昏迷，并可引起肺水肿。可经皮肤吸收引起中毒。慢性影响：可引起消化道功能障碍，肝、肾损害和皮疹。', '3-甲酚对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，应特别注意对水体的污染。在水生生物中可能发生生物蓄积。', '本品可燃，高毒，具腐蚀性、强刺激性，可致人体灼伤。遇明火、高热可燃。具有腐蚀性。受高热分解放出有毒的气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3522, 3629, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。吸入、口服或经皮肤吸收有麻醉作用。其蒸气或雾对眼睛、皮肤、粘膜和呼吸道有刺激作用，可引起神经系统功能紊乱，长时间接触有麻醉作用。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。长期接触可引起肝、肾功能损害，神经系统损伤等。本品可通过皮肤吸收。', '3-甲基-1-丁醇（异戊醇）对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3523, 3630, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入', '对眼和皮肤有刺激作用，接触后可引起头痛、恶心和呕吐。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3524, 3631, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入、食入。吸入或摄入对身体有害。其蒸气或烟雾对眼睛、粘膜和呼吸道有刺激作用。中毒表现可能有头晕、头痛、恶心、呼吸困难等症状。（来源：检索补充）', '烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3525, 3632, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入 食入 经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对皮肤、眼睛具刺激作用。（来源：检索补充）', '对环境有害。（来源：检索补充）', '本品易燃、有毒、具有刺激性，其蒸气与空气混合，能形成爆炸性混合物。容易自聚。（来源：检索补充）', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3526, 3633, NULL, NULL, NULL, NULL, NULL, '第3.1类低闪点易燃液体', '吸入 食入 经皮吸收\n吸入或误服', '吸入、食入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和呼吸道有刺激作用。高浓度蒸气可引起头痛、头晕、恶心、呕吐、气短等症状。长期接触可能对中枢神经系统造成损害。（来源：检索补充）', '无资料', '本品极度易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3527, 3634, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。误服或吸入有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长时间接触可引起头痛、恶心和呕吐。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。长期接触可引起肝、肾功能损害，神经系统损伤等。本品可通过皮肤吸收。', '3-甲基-2-丁醇对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3528, 3635, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入经皮吸收', '蒸气或雾对眼、粘膜及上呼吸道有刺激性。对皮肤有刺激作用。', '无资料', '本品易燃，具刺激性。与空气混合能形成爆炸性混合物，遇明火、高热极易燃烧爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3529, 3636, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入 食入 经皮吸收', '本品具有刺激性。', '对环境有危害，对大气可造成污染。（来源：检索补充）', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3530, 3637, NULL, NULL, NULL, NULL, NULL, '第3.1类 低闪点易燃液体', '吸入 食入 经皮吸收\n吸入、摄入或经皮肤吸收对身体有害。蒸气或雾对眼、粘膜和上呼吸道有刺激性。对皮肤有', '刺激性。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3531, 3638, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收', '有毒。误服或吸入会中毒。对眼睛和皮肤有刺激性。', '对环境可能有危害，对水体可造成污染。', '本品可燃、具有强腐蚀性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3532, 3639, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。本品对眼睛、皮肤有刺激作用。未见有关中毒报道，可能其毒性与其他己醇异构物相似。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。长期接触可引起肝、肾功能损害，神经系统损伤等。本品可通过皮肤吸收。', '3-甲基-3-戊醇对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3533, 3640, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '致紫绀。', '无资料', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3534, 3641, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。污染而吸收引起。自觉脸部灼热、剧烈头痛、头晕、呼吸困难，呈现紫绀症。以后出现血尿、尿闭、精神障碍、肌肉抽搐。慢性中毒：可引起膀胱刺激症状。本品为可疑致癌物，需严格控制接触。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '3-甲基苯胺对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，建议不要让其进入环境。在水生生物中可能发生生物蓄积。', '本品可燃，有毒。遇明火、高热可燃。受高热分解放出有毒的气体。与强氧化剂、酸类接触可发生反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3535, 3642, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '对皮肤有刺激性。对眼睛有严重刺激性。对呼吸道有刺激作用。吸入、摄入或经皮肤吸收后对身体有害。其蒸气或烟雾可引起眼睛、皮肤、粘膜和上呼吸道刺激。', '对水生生物有毒。', '遇明火、高热可燃。受热分解产生有毒的氰化物和氮氧化物气体。与氧化剂可发生反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3536, 3643, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收、眼睛接触', '吸入、摄入或经皮肤吸收后对身体有害。其蒸气或雾对眼睛、皮肤、粘膜和上呼吸道有刺激作用。接触后可引起头痛、头晕、恶心、呕吐、呼吸困难、意识丧失等。（来源：检索补充）', '对水生生物有极高毒性。（来源：检索补充）', '本品易燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3537, 3644, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '接触本品蒸气可引起胸部压迫感、上呼吸道刺激、眩晕、头痛、恶心、呕吐、疲倦无力等。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3538, 3645, NULL, NULL, NULL, NULL, NULL, '第3.1类 低闪点易燃液体', '吸入、食入、经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。本品对眼睛、皮肤、粘膜和上呼吸道有刺激作用。高浓度接触可引起头痛、头晕、恶心、呕吐、乏力等症状。小鼠接触本品150g/m3引起翻正反射丧失，250g/m3致死。', '对环境有危害，对水体可造成污染。', '本品易燃，具刺激性。与空气混合能形成爆炸性混合物，遇明火、高热极易燃烧爆炸。是非常活泼的物质，容易产生聚合。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3539, 3646, NULL, NULL, NULL, NULL, NULL, '侵入途径：', '如果被吞食，可能会造成严重肺部损伤。 对皮肤有刺激性。气体可能会引起头晕或窒', '息。', '对水生物有剧毒,对水生环境可能会引起长期有害作用', '高度易燃,其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3540, 3647, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '本品蒸气能刺激皮肤、眼睛和粘膜，高浓度蒸气具有麻醉作用，对血象有轻度影响。', '可能对水体环境产生长期不良影响。（来源：检索补充）', '本品易燃、具有刺激性。遇明火、高热可燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3541, 3648, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入 食入 经皮吸收\n吸入、摄入或经皮肤吸收对身体有害。蒸气或雾对眼、粘膜和上呼吸道有刺激性。对皮肤有刺', '激性。', '无资料', '本品易燃、刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3542, 3649, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入 食入 经皮吸收', '本品具有刺激性。接触后能引起头痛、恶心、呕吐。', '无资料', '本品易燃', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3543, 3650, NULL, NULL, NULL, NULL, NULL, '第8类腐蚀品', '吸入、食入、经皮吸收', '本品对眼睛、皮肤及粘膜有刺激作用。吸入、摄入或经皮肤吸收后对身体有害。对皮肤有腐蚀性。', '对水生生物有毒。', '遇明火、高热可燃。受热分解产生有毒气体。与氧化剂可发生反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3544, 3651, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '对眼睛、粘膜、呼吸道及皮肤有刺激性，接触后可引起烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '对环境有危害，对水体可造成污染。', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3545, 3652, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', NULL, '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3546, 3653, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收。', '吸入、摄入或经皮肤吸收对身体有害。对皮肤有刺激作用。其蒸气或气溶胶对眼睛、粘膜、呼吸道有刺激作用。吸进体内导致形成高铁血红蛋白而引起发绀。慢性影响：可引起呼吸系统、皮肤的过敏反应。', '无资料', '本品可燃、有毒、具有刺激性、致敏性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3547, 3654, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '本品对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对环境有危害，对水体可造成污染。', '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3548, 3655, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入', '本品对眼睛、粘膜有刺激作用。', '对环境有危害，对水体可造成污染。', '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。（来源：检索补充）', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3549, 3656, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后会中毒。对肺、肝、肾和脑都有影响。吸入蒸气能产生恶心、头痛、呕吐、眩晕、昏迷等症状。吸入蒸气可致肺水肿，严重者可致死。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生生物有毒性。对环境有害。', '本品易燃、高毒、为可疑致癌物。遇明火、高热易燃。受高热分解，放出有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3550, 3657, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。蒸气或雾对眼、粘膜和上呼吸道有刺激性。对皮肤有刺激性。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。长期接触可引起肝、肾功能损害，神经系统损伤等。本品可通过皮肤吸收。吞咽有害（危险类别码R22）。对眼睛、呼吸道和皮肤有刺激性（危险类别码R36/37/38）。', '对水生生物可能有害。', '遇明火、高热可燃。受热分解产生有毒的腐蚀性气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3551, 3658, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对皮肤有刺激作用，其蒸气和烟雾对眼睛、粘膜和呼吸道有刺激作用。中毒表现可能有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。慢性作用：有诱变作用。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3552, 3659, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入 食入 经皮吸收', '本品受高热分解释出高毒的氯化物气体。误服、吸入或与皮肤接触会中毒。蒸气的刺激性很强，能对眼睛、皮肤、粘膜造成危害', '无资料', '本品易燃、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3553, 3660, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后会中毒。对眼睛、皮肤有刺激作用。受热分解释出氮氧化物和氯烟雾。本品进入体内能形成高铁血红蛋白，可致紫绀。', '该物质对环境有危害，对水体应给予特别注意。', '本品可燃、具有刺激性。遇明火、高热可燃。受高热分解，放出有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3554, 3661, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。可引起高铁血红蛋白血症，出现紫绀。', '对水生生物有毒性作用。', '本品可燃，有毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3555, 3662, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '未见人中毒的报道。给动物染毒后几分钟即出现不安和呼吸加速，继之无力、震颤、阵挛\n性抽搐、气急、昏迷直至死亡。易经皮肤吸收。', '对水生生物有极高毒性（经检索ICSC、NIOSH、ECHA、中国化学品安全网等数据库，未找到3-氯苯酚的精确环境危害数据）。', '本品可燃，有毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3556, 3663, NULL, NULL, NULL, NULL, NULL, '第5.2类有机过氧化物，B型。', '吸入、食入、皮肤接触、眼睛接触', '吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入该物质可能对健康有害。皮肤接触可引起刺激或灼伤。眼睛接触可引起严重刺激或灼伤。', '无资料（经检索ICSC、NIOSH、ECHA、中国化学品安全网等数据库，未找到3-氯苯过氧甲酸的生态危害数据）', '遇明火、高热可燃。受热分解产生有毒气体。与还原剂、有机物、酸类等接触可能发生剧烈反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3557, 3664, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。本品对皮肤、粘膜和眼睛有刺激作用。吸入后可引起咳嗽、气短、头痛、恶心和呕吐。皮肤接触可引起刺激、红肿、疼痛。眼睛接触可引起刺激、流泪、视力模糊。吞食后可引起口腔、咽喉、胃肠道刺激，出现恶心、呕吐、腹痛等症状。长期或反复接触可能对肝、肾造成损害。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '3-氯丙酸对水生生物有毒性。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。在水生生物中可能发生生物蓄积。', '本品可燃，具腐蚀性、刺激性，可致人体灼伤。遇明火、高热、或与氧化剂接触能燃烧，并散发出有毒气体。受热分解产生有毒的腐蚀性气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3558, 3665, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。本品对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。吸入后可引起咳嗽、气短、头痛、头晕、恶心和呕吐。高浓度吸入可引起肺水肿。皮肤接触可引起刺激、红肿、疼痛，长期接触可引起皮炎。眼睛接触可引起严重刺激、疼痛、流泪、视力模糊，严重者可导致角膜损伤。吞食后可引起口腔、咽喉、胃肠道刺激，出现恶心、呕吐、腹痛等症状。长期或反复接触可能对肝、肾、神经系统造成损害。', '3-氯丙酸乙酯对水生生物有毒性。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。在水生生物中可能发生生物蓄积。', '本品易燃、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3559, 3666, NULL, NULL, NULL, NULL, NULL, '第3.1类低闪点易燃液体', '吸入、食入、经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。高浓度对皮肤粘膜具有刺激性，并有轻度麻醉作用。接触者觉咽干、鼻子发呛、胸闷，可出现头晕、头沉、嗜睡、全身无力等。溅入眼内，出现流泪、疼痛等严重眼刺激症状。慢性中毒：引起中毒性肝炎，肝功能异常，尿中可有蛋白、红细胞等。本品为可疑致癌物，需严格控制接触。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '3-氯丙烯对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。挥发后可参与形成光化学烟雾。', '本品极度易燃，具刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。与氧化剂能发生强烈反应。遇酸性催化剂如路易斯催化剂、齐格勒催化剂、硫酸、氯化铁、氯化铝等都能产生猛烈聚合，放出大量热量。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3560, 3667, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。本品对眼睛、皮肤、粘膜和上呼吸道有刺激作用。吸入后可引起咳嗽、气短、头痛、头晕、恶心和呕吐。高浓度蒸气可引起头晕、头痛、恶心、麻醉作用。皮肤接触可引起刺激、红肿、疼痛。眼睛接触可引起严重刺激、疼痛、流泪、视力模糊。吞食后可引起口腔、咽喉、胃肠道刺激，出现恶心、呕吐、腹痛等症状。长期或反复接触可能对肝、肾、神经系统造成损害。', '3-氯氟苯对水生生物有毒性。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。在水生生物中可能发生生物蓄积。', '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3561, 3668, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收对身体可能有害，可能有刺激症状。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。高浓度接触可引起头痛、头晕、恶心、呕吐、嗜睡等症状。长期或反复接触可能对肝、肾、神经系统造成损害。', '对水生生物有害。在环境中可能持久存在，具有生物蓄积性。', '本品易燃、具有刺激性。遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3562, 3669, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。高浓度时，对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。本品与空气中水分接触能释出有毒和腐蚀性氟化氢气体。', '该物质对环境有危害，对水体应给予特别注意。', '本品易燃、具有强刺激性。遇高热、明火或氧化剂，有引起燃烧的危险。遇水或高热能放出大量有毒的气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3563, 3670, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收对身体可能有害，可能有刺激症状。现有眼及上呼吸道刺激症状，头痛，头昏，呼吸困难，紫绀，贫血，血尿，血红蛋白和管型尿，恶心，呕吐，腹部疼痛，嗜睡，兴奋和幻觉，以及肌肉无力和共济失调。高浓度接触可引起高铁血红蛋白血症。', '对水生生物有害。在环境中可能持久存在，不易降解。对水体、土壤和大气环境有污染风险。', '本品可燃，高毒，具刺激性。遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3564, 3671, NULL, NULL, NULL, NULL, NULL, '第5.2类有机过氧化物，E型。', '吸入、食入、皮肤接触、眼睛接触', '吸入该物质可能会引起对健康有害的影响或呼吸道不适。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。意外食入可能引起胃肠道刺激。长期或反复接触可能引起皮肤过敏。', '对水生生物有害。', '接触火焰可能会产生膨胀或爆炸性分解。遇明火、高热有引起燃烧爆炸的危险。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3565, 3672, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '本品对皮肤有刺激作用，其蒸气或烟雾对眼睛、粘膜及上呼吸道有刺激作用。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3566, 3673, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入', '对眼、呼吸道和皮肤有刺激性。', '无资料', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3567, 3674, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '本品有刺激作用，高浓度时有麻醉性。吸入或摄入对身体有害，其蒸气或烟雾对眼睛、皮肤、粘膜和呼吸道有刺激性。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃，具有刺激性。其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3568, 3675, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '本品高浓度时对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。接触后可引起烧灼感、咳\n嗽、喉炎、气短、头痛、恶心和呕吐。由于缺氧可引起紫绀。', '无资料', '本品可燃、有毒、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3569, 3676, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '吸入中等浓度引起头晕、恶心、倦睡；吸入高浓度蒸气引起昏迷，甚至死亡。对眼及皮肤有强烈刺激性。口服引起恶心、呕吐、腹泻及昏睡。', '无资料', '本品易燃，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3570, 3677, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收，可能引起中毒死亡。蒸气或雾对眼睛、粘膜和上呼吸道有刺激性。对皮肤有刺激性。吸收进入人体后，可引起高铁血红蛋白血症，出现紫绀。', '无资料', '本品可燃，有毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3571, 3678, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n吸入、摄入或经皮肤吸收后对眼睛、皮肤和粘膜有刺激作用。吸收进体内可形成高铁血红', '蛋白，致引起紫绀。长期接触可引起眼睛的损伤。', '无资料', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3572, 3679, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤、粘膜和上呼吸道有刺激作用。吸入可引起呼吸道刺激。食入可引起恶心、呕吐、腹痛等消化道症状。', '对水生物有剧毒, 对水生环境可能会引起长期有害作用。', '遇明火、高热可燃。受热分解产生有毒的氮氧化物和氯化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3573, 3680, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '急性毒性：大鼠经口LD50：155mg/kg（来源：检索补充）；鸡经口LD50：110~123mg/kg（来源：检索补充）。对皮肤、眼睛和呼吸道有刺激性。长期接触可造成贫血、皮肤损伤、肾脏损伤（来源：检索补充）。', '对水生生物有毒性。在环境中可降解为砷酸盐，造成土壤和水体污染（来源：检索补充）。', '无特殊燃爆特性（来源：检索补充）', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3574, 3681, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收', '对人体有毒，有刺激性。进入体内可形成高铁血红蛋白，引起紫绀。', '无资料', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3575, 3682, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。进入体内可形成高铁血红蛋白，致紫绀。长期接触可引起头痛、头晕、乏力、失眠等神经衰弱综合征。', '对环境有危害，对水体可造成污染。', '本品可燃，有毒。遇明火、高热可燃。受热分解放出有毒的氧化氮烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3576, 3683, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。可引起高铁血红蛋白血症。接触可引起头痛、头晕、恶心、呕吐、腹痛、发绀等症状。严重时可引起溶血性贫血、肝损害。', '对水生生物有极高毒性，可能对水体环境产生长期不良影响。', '本品易燃，有毒，具强刺激性。遇明火、高热可燃。受热分解放出有毒的氧化氮烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3577, 3684, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后会中毒。对眼睛、皮肤和粘膜有强烈的刺激作用。吸入可引起喉、支气管炎症、化学性肺炎、肺水肿等。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品可燃、有毒、具有腐蚀性、强刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3578, 3685, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期反复接触可引起贫血、高铁血红蛋白血症。', '无资料', '本品可燃，有毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3579, 3686, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收', '本品蒸气和粉尘对眼睛、皮肤和粘膜有刺激性。吸入、摄入或经皮肤吸收后会中毒。吸入后可因喉、支气管的痉挛、炎症或水肿，化学性肺炎、肺水肿而致死。中毒表现有咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。受热分解释出氯和氮氧化物。', '对环境有危害，对水体可造成污染。', '本品可燃、具有腐蚀性、刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3580, 3687, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、粘膜、上呼吸道和皮肤有刺激性。', '对环境有危害，对水体可造成污染。', '本品可燃，有毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3581, 3688, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吞食后有毒。吸入有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生物有剧毒, 对水生环境可能会引起长期有害作用。', '受热分解产生有毒的砷氧化物和氮氧化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3582, 3689, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品（来源：检索补充）', '吸入、食入、皮肤接触、眼睛接触（来源：检索补充）', '吞食后有毒。对皮肤有刺激性。对眼睛有严重刺激性。对呼吸道有刺激作用。', '对水生生物有害（来源：检索补充）', '易燃，其粉体与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3583, 3690, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '有毒。对眼睛、皮肤和粘膜有刺激作用。进入体内能形成高铁血红蛋白，导致紫绀。严重中毒者可致死。', '该物质对环境有危害，应特别注意对水体的污染。', '本品可燃、有毒、具有刺激性。遇明火、高热可燃。受热分解放出有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3584, 3691, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '对眼睛、呼吸道和皮肤有刺激作用。吸收进入体内可引起高铁血红蛋白血症，出现紫绀。严重中毒者可致死。', '该物质对环境有危害，应特别注意对水体的污染。', '本品可燃，有毒，具刺激性。遇明火、高热可燃。受热分解放出有毒的气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3585, 3692, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入、摄入对身体有害。对眼睛、皮肤、粘膜及呼吸道有刺激作用。中毒表现有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。吸入后可能由于喉、支气管的痉挛、炎症和水肿，化学性肺炎、肺水肿而致死。', '对水生生物有害', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3586, 3693, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n吸入、摄入或经皮肤吸收后可能对身体有害。对眼睛和皮肤有刺激作用。经皮肤可能吸收', '迅速，吸收后导致形成高铁血红蛋白而致发绀。', '无资料', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3587, 3694, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入', '本品具有刺激性。有轻度麻醉作用。高浓度时有窒息效应。', '无资料', '本品易燃，具刺激性，具窒息性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3588, 3695, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、眼睛及皮肤接触', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤有刺激性。', '对水生生物有害。', '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3589, 3696, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '肺水肿。空气中本品在0.5ppm时即不能忍耐。', '无资料', '本品可燃、有毒、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3590, 3697, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。吸入可引起喉、支气管痉挛、炎症、水肿，化学性肺炎或肺水肿。接触后可引起头痛、头晕、恶心、呕吐、咳嗽、气短等症状。', '无资料', '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。受高热分解产生有毒的溴化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3591, 3698, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入经皮吸收', '喉炎、气短、头痛、恶心和呕吐。随接触的浓度和时间的不同，其影响可由较轻刺激到严\n重的组织损伤。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3592, 3699, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '吸入、食入、经皮吸收有毒。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。可引起高铁血红蛋白血症。长期接触可引起头痛、头晕、乏力、食欲不振等症状。', '无资料', '本品可燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3593, 3700, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后会中毒。对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用。', '对水生生物有毒。（来源：检索补充）', '遇明火、高热可燃。受热分解产生有毒的溴化氢气体。（来源：检索补充）', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3594, 3701, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '本品对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。毒作用比氯丙腈稍弱。', '无资料', '本品易燃、有毒、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3595, 3702, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入 食入 经皮吸收\n吸入、摄入或经皮肤吸收可致死。', '刺激性。接触后引起烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '无资料', '本品易燃、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3596, 3703, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '头痛、恶心和呕吐。', '无资料', '本品可燃、有毒、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3597, 3704, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、经皮吸收', '本品可引起严重的皮肤灼伤和眼睛损伤。吸入蒸气可引起呼吸道刺激、咳嗽、呼吸困难。食入可引起严重的口腔和消化道灼伤。长期或反复接触可能引起皮肤过敏。', '该物质对环境有危害，应特别注意对水体的污染。', '遇明火、高热可燃。受热分解产生有毒的溴化氢气体。与水反应剧烈，产生腐蚀性烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3598, 3705, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '有毒。有刺激和麻醉作用。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3599, 3706, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。蒸气或雾对眼睛、皮肤、粘膜和上呼吸道有刺激作用。高浓度接触可引起头痛、头晕、恶心、呼吸困难等症状。', '对水生生物有毒性，可能对水体造成污染。', '高度易燃，其蒸气与空气混合，能形成爆炸性混合物。遇明火、高热极易引起燃烧爆炸。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3600, 3707, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '吸入蒸气可能引起瞌睡和头昏眼花，可能伴随嗜睡、警惕性下降、反射作用消失、失去协调性并感到眩晕。在正常生产处理过程中，吞咽可能有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。高浓度接触可引起头痛、头晕、恶心、呼吸困难等症状。', '对水生生物有毒性，可能对水体造成污染。', '高度易燃液体，其蒸气与空气混合，能形成爆炸性混合物。遇明火、高热极易引起燃烧爆炸。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3601, 3708, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。具有中枢神经系统刺激作用，浓缩液能引起肝、肾障碍，长期接触可引起慢性中毒。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '该物质对环境可能有危害，对水体应给予特别注意。由于其水溶性，可能对水生生物造成危害。在环境中可能具有一定的生物降解性，但需要进一步评估。避免该物质进入土壤、水体和排水系统。', '本品易燃，具刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂接触发生反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3602, 3709, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '本品为中等毒杀虫剂。中毒症状有头痛、恶心、呕吐、腹痛、流涎、出汗、瞳孔缩小、步行困难、语言障碍，重者可发生全身痉挛、昏迷。', '对水生生物有极高毒性，可能对水体环境产生长期不良影响。', '遇明火、高热可燃。受热分解产生有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3603, 3710, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吞食后有毒。跟皮肤接触有剧毒。吸入有毒。人中毒后胆碱酯酶活性下降，出现流涎、流泪、肌肉震颤、瞳孔缩小等胆碱能神经兴奋症状。严重者可出现肺水肿、昏迷、呼吸衰竭。', '对水生物有剧毒。该物质对环境可能有危害，应特别注意对水体的污染。', '遇明火、高热可燃。受热分解产生有毒的氮氧化物和一氧化碳气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3604, 3711, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '确认的致癌剂。对眼睛、皮肤和呼吸道有刺激作用，可影响肝、肾，形成高铁血红蛋白。吸入、食入或皮肤接触该物质可引起迟发反应。', '对水生生物有毒性，可能对环境造成长期危害。', '遇明火、高热可燃。受热分解产生有毒的氯化氢和氧化氮气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3605, 3712, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收', '目前，未见职业中毒的报道。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3606, 3713, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收\n吸入、摄入或经皮肤吸收后对身体有害。有误服后引起急性黄疸的报道，也有经皮吸收引', '起中毒性肝炎的报道。本品在体内可形成高铁血红蛋白，致发生紫绀。', '无资料', '本品可燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3607, 3714, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '联苯胺可经呼吸道、胃肠道、皮肤进入人体。对皮肤可引起接触性皮炎；对粘膜有刺激作用；长期接触可引起出血性膀胱炎，膀胱复发性乳头状瘤和膀胱癌。国际癌症研究中心(IARC)已确认为致癌物。', '无资料', '本品有毒、刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3608, 3715, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入 食入 经皮吸收', '对粘膜有刺激作用，高浓度时有麻醉作用。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3609, 3716, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、皮肤接触、眼睛接触', '受高热分解出有毒气体。对人有毒，有刺激性。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生生物有毒性作用。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3610, 3717, NULL, NULL, NULL, NULL, NULL, '第5.2类 有机过氧化物', '吸入、食入、皮肤接触、眼睛接触', '对皮肤、眼睛和呼吸道有刺激性。高浓度接触可引起头痛、头晕、恶心、呼吸困难等症状。长期接触可能对皮肤和眼睛造成损伤。', '对环境可能有危害，对水体应给予特别注意。', '遇热、明火、撞击、摩擦有火灾爆炸危险。受热或接触火焰可能会产生膨胀或爆炸性分解。加热时，容器可能爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3611, 3718, NULL, NULL, NULL, NULL, NULL, '第4.1类 易燃固体', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。有毒。吸入、摄入或经皮肤吸收可引起中毒。中毒表现有盗汗、发烧、呼吸短促、心跳加快等。皮肤接触可引起皮炎、周围神经炎。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。长期接触可引起肝、肾功能损害，神经系统损伤等。本品可通过皮肤吸收。', '4,6-二硝基-2-氨基苯酚对水生生物有毒性。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3612, 3719, NULL, NULL, NULL, NULL, NULL, '第1.1类爆炸品', '吸入、食入、皮肤接触、眼睛接触', '吸入、食入或皮肤接触有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。可引起高铁血红蛋白血症，出现紫绀、呼吸困难等症状。', '对水生生物有害。', '遇明火、高热、摩擦、震动有引起燃烧爆炸的危险。受热分解产生有毒的氮氧化物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3613, 3720, NULL, NULL, NULL, NULL, NULL, '爆炸物，1.3项；急性毒性-经口，类别2；急性毒性-经皮，类别2；急性毒性-吸入，类别3；特异性靶器官毒性-反复接触，类别2；危害水生环境-急性危害', '吸入、食入、经皮吸收', '有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。受热分解可释出有毒的氮氧化物烟雾。长期接触可引起慢性中毒，表现为头痛、头晕、乏力、食欲不振、恶心等症状。', '对水生生物有极高毒性，可能对水生环境造成长期不利影响。', '易燃。受撞击、摩擦，遇明火或其他点火源有爆炸危险。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3614, 3721, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吞食后有剧毒。对中枢神经系统有强烈作用，可引起心律失常、恶心、呕吐、头痛、头晕等症状。高剂量可导致呼吸抑制和心脏骤停。对眼睛、皮肤和呼吸道有刺激性。', '对水生生物有毒性。应避免进入水体和土壤环境。', '遇明火、高热可燃。受热分解产生有毒的氮氧化物和一氧化碳等气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3615, 3722, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入、食入或经皮肤吸收可引起中毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。中毒症状包括咽喉痛、咳嗽、头痛、呼吸困难、恶心、呕吐、腹泻、腹部疼痛、虚弱、头晕、休克或虚脱、发红、疼痛。', '对水生生物有极高毒性。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3616, 3723, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触', '恶心、呕吐、腹部痛性痉挛、腹泻、流涎、盗汗、疲倦和虚弱；吸入时可出现流鼻涕和胸闷、视觉模糊、流泪、眼部和肌肉痉挛、肌肉共济失调、口语不清和肌肉抽搐。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生生物有毒性作用。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3617, 3724, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吞食后有毒。跟皮肤接触有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '遇明火、高热可燃。受热分解产生有毒的氮氧化物和一氧化碳气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3618, 3725, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '对眼睛、粘膜、呼吸道及皮肤有刺激作用。吸收后导致形成高铁血红蛋白而发生青紫。吸\n入、摄入或经皮肤吸收可能致死。', '无资料', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3619, 3726, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入食入\n吸入过量的', '性变应性皮炎。本品不易经皮肤吸收。', '无资料', '本品可燃，有毒，具致敏性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3620, 3727, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入', '本品具有刺激性。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3621, 3728, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', NULL, '无资料', '本品可燃，有毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3622, 3729, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入', '经口摄入或吸入均能引起中毒。能引起视觉缺失。受热分解放出砷和氮氧化物烟雾。', '无资料', '本品不燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3623, 3730, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '如吸入、口服或经皮吸收可中毒死亡。对眼睛、上呼吸道、粘膜和皮肤有刺激性。', '对水生生物有极高毒性，可能对水体环境造成长期不良影响。', '本品可燃，有毒，为致癌物，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3624, 3731, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '对人体有毒。有刺激性。进入体内可形成高铁血红蛋白，引起紫绀。', '无资料', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3625, 3732, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '有毒。对皮肤有刺激作用。受热分解释出氮氧化物。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3626, 3733, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入食入经皮吸收', '致死。', '无资料', '本品可燃，有毒，为致癌物，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3627, 3734, NULL, NULL, NULL, NULL, NULL, '第3类易燃液体', '吸入、食入、经皮', '对皮肤、眼睛和呼吸道有刺激性。高浓度蒸气可能引起头痛、头晕、恶心和麻醉作用。长期或反复接触可能引起皮肤干燥或皲裂。', '对水生生物有毒。对水生环境可能会引起长期有害作用。避免释放到环境中。', '易燃液体和蒸气。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触猛烈反应。流速过快容易产生和积聚静电。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3628, 3735, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入', '对人体具有毒性和刺激性。经口摄入会中毒。受热分解释出氮氧化物。', '无资料', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3629, 3736, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入', '有毒。对眼睛、皮肤和粘膜有刺激作用。', '无资料', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3630, 3737, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮肤吸收', '吞食后有毒。吸入有毒。对眼睛、皮肤和粘膜有刺激作用。长期或反复接触可能对器官造成损害。', '对水生生物有剧毒。对水生环境可能会引起长期有害作用。该物质对环境可能有危害，建议不要让该物质进入环境。', '受热时可能分解产生有毒烟雾（砷氧化物、氮氧化物）。遇明火、高热可燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3631, 3738, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。接触可引起过敏反应。', '对水生生物有害。', '遇热有火灾危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3632, 3739, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激性。进入体内可引起高铁血红蛋白血症，高浓度接触引起紫绀。长期接触可引起贫血、肝脾肿大等慢性中毒症状。', '对水生生物有毒，可能对水体环境造成长期不良影响。', '本品可燃，有毒，具刺激性。遇明火、高热有燃烧爆炸的危险。受热分解放出有毒的氟化物和氮氧化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3633, 3740, NULL, NULL, NULL, NULL, NULL, '第8类腐蚀性物品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有严重刺激作用和腐蚀作用。可引起皮肤灼伤、眼睛灼伤。大量吸入可引起肺水肿，甚至死亡。人可因心跳骤停、抽搐发作时的窒息或中枢性呼吸衰竭而死亡。', '对水生生物有毒，可能对水体环境造成长期不良影响。', '本品可燃，有毒。遇明火、高热有燃烧爆炸的危险。受热分解放出有毒的氟化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3634, 3741, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收后对身体有害。其蒸气或雾对眼睛、皮肤、粘膜和呼吸道有刺激性。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3635, 3742, NULL, NULL, NULL, NULL, NULL, '易燃液体，类别 3；急性毒性－吸入，类别 4', '皮肤接触、眼睛接触、吸入、食入', '吸入有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '该物质对环境有危害，应特别注意对大气的污染。', '易燃，其蒸气与空气混合，能形成爆炸性混合物。遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3636, 3743, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吞食后有剧毒。跟皮肤接触有剧毒。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。吸入可引起喉头水肿、支气管痉挛、化学性肺炎、肺水肿而致死。长期或反复接触可引起过敏反应。', '对水生生物有剧毒。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3637, 3744, NULL, NULL, NULL, NULL, NULL, '第8.3类 其它腐蚀品', '吸入 食入 经皮吸收', '和呕吐。能引起灼伤。', '无资料', '本品可燃，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3638, 3745, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。可引起头痛、头晕、恶心、呕吐、腹痛、腹泻、虚脱、体温下降和昏迷，并可引起肺水肿。可经皮肤吸收引起中毒。慢性影响：可引起消化道功能障碍，肝、肾损害和皮疹。', '4-甲酚对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，应特别注意对水体的污染。在水生生物中可能发生生物蓄积。', '本品可燃，高毒，具腐蚀性、强刺激性，可致人体灼伤。遇明火、高热可燃。具有腐蚀性。受高热分解放出有毒的气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3639, 3746, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入 食入 经皮吸收', '本品的高浓度蒸气对眼睛、皮肤、粘膜有刺激性和麻醉性。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3640, 3747, NULL, NULL, NULL, NULL, NULL, '第3.1类 低闪点易燃液体', '吸入、食入、经皮吸收', '吸入或摄入对身体有害。蒸气或雾对眼、粘膜和上呼吸道有刺激性。对皮肤有刺激性。接触后引起烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '对水生生物有毒，可能对水体产生长期不利影响。', '本品易燃、具有刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3641, 3748, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。高浓度蒸气对眼、鼻、喉和肺有刺激性，并抑制中枢神经系统而呈现麻醉作用，如长时间麻醉可因呼吸衰竭而致死。对眼有强烈刺激性，可导致永久性失明。液体对皮肤有轻度刺激性。摄入有轻度毒性。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。长期接触可引起肝、肾功能损害，神经系统损伤等。本品可通过皮肤吸收。', '4-甲基-2-戊醇（甲基异丁基甲醇）对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃，具刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3642, 3749, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。其蒸气或雾对眼睛、粘膜和上呼吸道有刺激性。高浓度吸入可引起头痛、头晕、恶心、呕吐、食欲不振、腹泻等胃肠道反应，以及呼吸道刺激症状。长期接触可引起慢性影响。', '对环境有危害，对水体和大气可造成污染。', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3643, 3750, NULL, NULL, NULL, NULL, NULL, '第3.1类 低闪点易燃液体', '吸入 食入\n吸入或摄入对身体有害。蒸气或雾对眼、粘膜和上呼吸道有刺激性。对皮肤有刺激性。接触后', '引起烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3644, 3751, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入 食入 经皮吸收', '味；当105mg／m3时，即可引起鼻刺激，胸部不适，对眼有刺激。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3645, 3752, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。污染而吸收引起。自觉脸部灼热、剧烈头痛、头晕、呼吸困难，呈现紫绀症。以后出现血尿、尿闭、精神障碍、肌肉抽搐。慢性中毒：可引起膀胱刺激症状。本品为可疑致癌物，需严格控制接触。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '4-甲基苯胺对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，建议不要让其进入环境。在水生生物中可能发生生物蓄积。', '本品可燃，有毒。遇明火、高热可燃。受高热分解放出有毒的气体。与强氧化剂、酸类接触可发生反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3646, 3753, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期或反复接触可能引起皮肤过敏。', '对水生生物有毒。', '遇明火、高热可燃。受热分解产生有毒的氰化物和氮氧化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3647, 3754, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜和呼吸道有刺激性。具有麻醉作用。接触后引起眼痛、流泪、咽痛、咳嗽等，继之头痛、头晕、恶心、呕吐、全身乏力，严重者可有眩晕、步态蹒跚等。', '该物质对环境可能有危害，对水生生物应给予特别注意。', '本品易燃，具刺激性。若遇高热，可发生聚合反应，放出大量热量而引起容器破裂和爆炸事故。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3648, 3755, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。跟皮肤接触有毒。对皮肤有刺激性。对眼睛有严重刺激性。对呼吸道有刺激作用。吸入后可引起咳嗽、呼吸困难、头痛、头晕、恶心、呕吐等症状。皮肤接触可引起刺激、红肿、疼痛。眼睛接触可引起严重刺激、流泪、视力模糊，严重者可致灼伤。吞食后可引起口腔、咽喉、胃肠道刺激，出现恶心、呕吐、腹痛等症状。长期接触可能对肝、肾、神经系统有影响。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '4-甲基吡啶对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。在水生生物中可能发生生物蓄积。', '本品易燃，有毒，具强刺激性。易燃，其蒸气与空气混合，能形成爆炸性混合物。遇明火、高热能引起燃烧爆炸。与氧化剂接触发生反应。受热分解产生有毒的腐蚀性气体。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3649, 3756, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入 食入 经皮吸收\n毒性似正辛烷。属低毒类。有麻醉作用。对眼睛、皮肤、粘膜有刺激作用。急性吸入后可', '由于心跳停止、呼吸麻痹、窒息而迅速死亡。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3650, 3757, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。人接触较高浓度本品，可引起头痛、眼及上呼吸道刺激。液体对皮肤有刺激性。可经皮肤吸收引起中毒。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。长期接触可引起肝、肾功能损害，神经系统损伤等。本品可通过皮肤吸收。', '4-甲基环己醇对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃，具刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3651, 3758, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '吸入有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。具有致突变作用。受热分解放出氮氧化物烟雾。', '无资料', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3652, 3759, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入 食入 经皮吸收\n吸入、摄入或经皮肤吸收对身体有害。蒸气或雾对眼、粘膜和上呼吸道有刺激性。对皮肤有', '刺激性。', '无资料', '本品易燃、刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3653, 3760, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。其蒸气或雾对眼睛、粘膜和上呼吸道有刺激性。接触后可引起头痛、头晕、恶心、呕吐、呼吸困难等症状。高浓度接触可引起氰化物中毒。', '对水生生物有毒性。该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃、有毒。遇明火、高热易燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3654, 3761, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '对皮肤有刺激性。对眼睛有严重刺激性。对呼吸道有刺激作用。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3655, 3762, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入、食入', '吸入、摄入或经皮肤吸收对身体有害。蒸气或雾对眼睛、粘膜和上呼吸道有刺激作用。接触后可引起头痛、头晕、恶心、呕吐、嗜睡等症状。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3656, 3763, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n吸入、摄入或经皮肤吸收对身体有害。对皮肤有刺激作用。其蒸气或气溶胶对眼睛、粘膜、呼', '吸道有刺激作用。进入体内导致形成高铁血红蛋白而引起紫绀。慢性影响：可引起呼吸系统、\n皮肤的过敏反应。', '无资料', '本品可燃、有毒、具有刺激性、致敏性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3657, 3764, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '跟皮肤接触可能会引起敏化作用。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生生物有害。', '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3658, 3765, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入有毒。对皮肤有刺激性。跟皮肤接触可能会引起敏化作用。有严重损害眼睛的风险。对粘膜和上呼吸道有刺激作用。', '对水生物有剧毒。', '遇明火、高热可燃。受热分解产生有毒的硫化物烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3659, 3766, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。进入体内，能形成高铁血红蛋白，引起紫绀。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。长期接触可引起肝、肾功能损害，神经系统损伤等。本品可通过皮肤吸收。', '4-氯-2-氨基苯酚对水生生物有毒性。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品可燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3660, 3767, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n对眼睛、皮肤、粘膜和上呼吸道有刺激作用。可引起皮炎。进入体内形成高铁血红蛋白，', NULL, '无资料', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3661, 3768, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', NULL, '无资料', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3662, 3769, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '对皮肤有刺激性。对眼睛有严重刺激性。吸入、摄入或经皮肤吸收后对身体有害。长期接触可能引起皮肤过敏。', '该物质对环境有危害，应特别注意对水体的污染。', '遇明火、高热可燃。受热分解产生有毒的氮氧化物和氯化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3663, 3770, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。具刺激作用。进入人体内，可形成高铁血红蛋白，致发生紫绀。', '无资料', '本品可燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3664, 3771, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '本品为高铁血红蛋白形成剂。能经无损皮肤吸叫，对眼有刺激性。', NULL, '本品可燃，为可疑致癌物，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3665, 3772, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n对眼睛、粘膜、呼吸道及皮肤有强烈刺激作用。吸入后可能因喉、支气管的炎症、水肿、', '痉挛，化学性肺炎、肺水肿而致死。中毒表现有烧灼感、咳嗽、喘息、喉炎、头痛、恶心\n和呕吐。', '无资料', '本品可燃、有毒、具有腐蚀性、刺激性、可致人体灼伤、为可疑致癌物', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3666, 3773, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收', '本品具有强烈的腐蚀性和刺激性。对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用和腐蚀作用。吸入可引起喉、支气管炎症、痉挛、水肿，化学性肺炎或肺水肿。接触可引起灼伤。', '对水生生物有剧毒，可能对水体环境造成长期不良影响。', '本品可燃、有毒、具有腐蚀性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3667, 3774, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入', '无资料。', '无资料', '本品可燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3668, 3775, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '本品有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。受热释放出有毒气体。', '对水生生物有毒，可能对水体环境造成长期不良影响。', '本品易燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3669, 3776, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '本品属高毒类。人体吸收后易引起中毒。受热分解放出有毒的氯和汞蒸气。', '无资料', '本品可燃、高毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3670, 3777, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, '对水生物有剧毒,对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3671, 3778, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入经皮吸收', NULL, '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3672, 3779, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n对眼睛、皮肤和粘膜有强烈刺激作用。长期接触可引起灼伤。有致敏作用。受热分解放出', '氯气和光气。', '无资料', '本品可燃、有毒、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3673, 3780, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入\n吸入、摄入或经皮肤吸收后会中毒。受热分解释出氮氧化物和氯烟雾。进入体内形成高铁', '血红蛋白，严重时可致紫绀。', '无资料', '本品可燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3674, 3781, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入 食入 经皮吸收', NULL, '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3675, 3782, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n对粘膜和皮肤有刺激作用，引起高铁血红蛋白血症。急性中毒：病人可有头痛、头昏、乏\n力、皮肤粘膜紫绀、手指麻木等症状。重者可出现胸闷、呼吸困难、心悸，甚至发生心律', NULL, '无资料', '本品可燃、有毒、具有刺激性、腐蚀性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3676, 3783, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入食入', '本品有催泪性和刺激性。其蒸气或雾对眼睛、粘膜和上呼吸道有刺激性。对皮肤有刺激性。', '无资料', '本品易燃，有毒，具刺激性，具催泪性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3677, 3784, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入、食入、经皮吸收', '对眼、鼻、喉粘膜有刺激性。吸入高浓度中毒时可见粘膜刺激、胸闷，严重者可造成麻醉。由呼吸道吸入或经皮肤吸收可引起中毒。', '无资料', '本品易燃、具有刺激性。其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3678, 3785, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。受热分解释出氰化物和氮氧化物烟雾。', '对水生生物有毒性。对环境可能有危害，对水体应给予特别注意。', '遇明火、高热可燃。受热分解释放出有毒的氰化氢和氮氧化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3679, 3786, NULL, NULL, NULL, NULL, NULL, '第3类易燃液体', '吸入、食入、皮肤接触、眼睛接触', '本品有刺激作用，高浓度时有麻醉性。', '对水生生物有害。', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3680, 3787, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品；皮肤腐蚀/刺激，类别2；皮肤致敏物，类别1', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收可致死。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激性。可引起皮肤白斑，有时呈对称性。动物实验证实本品经口或经呼吸道染毒均可引起皮肤白斑。具有致敏作用，长期接触可损害肝脏和肾脏功能。', '对水生生物有毒性作用', '遇明火、高热可燃。受高热分解, 放出刺激性烟气。与氧化剂能发生强烈反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3681, 3788, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入食入经皮吸收\n吸入、口服或经皮肤吸收，可能引起中毒死亡。蒸气或雾对眼、粘膜和上呼吸道有刺激性。', '对皮肤有刺激性。吸收进入人体后，可引起高铁血红蛋白血症，出现紫绀。', '对水生生物有害并具有长期持续影响。', '本品可燃，有毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3682, 3789, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入食入经皮吸收\n吸入、口服或经皮肤吸收，可能引起中毒死亡。蒸气或雾对眼睛、粘膜和上呼吸有刺激性。', '对皮肤有刺激性。吸收进入人体后，可引起高铁血红蛋白血症，出现紫绀。', '对水生生物有害并具有长期持续影响。', '本品可燃，有毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3683, 3790, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。对人体有毒和具有刺激性。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。长期接触可引起肝、肾功能损害，神经系统损伤等。本品可通过皮肤吸收。', '4-硝基-2-氨基苯酚对水生生物有毒性。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3684, 3791, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '本品有毒，可致紫绀。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。吸入可引起头痛、头晕、恶心、呕吐等症状。', '对水生生物有毒性。对环境可能有危害，对水体应给予特别注意。', '本品可燃，有毒，具刺激性。遇明火、高热可燃。受高热分解，放出有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3685, 3792, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '本品有毒，可致紫绀。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。吸入可引起头痛、头晕、恶心、呕吐等症状。', '对水生生物有毒性。对环境可能有危害，对水体应给予特别注意。', '本品可燃、具有刺激性。遇明火、高热可燃。受高热分解，放出有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3686, 3793, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期或反复接触可能引起皮肤过敏。', '对水生生物有毒。', '遇明火、高热可燃。受热分解产生有毒的氮氧化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3687, 3794, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '本品有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。吸入可引起头痛、头晕、恶心、呕吐等症状。长期接触可能对血液系统产生影响，导致高铁血红蛋白血症。', '对水生生物有毒性。对环境可能有危害，对水体应给予特别注意。', '遇明火、高热可燃。受热分解产生有毒的氮氧化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3688, 3795, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', NULL, NULL, '本品可燃，有毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3689, 3796, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期或反复接触可能引起皮肤过敏。本品可引起高铁血红蛋白血症。', '对水生生物有毒。', '遇明火、高热可燃。受热分解产生有毒的氮氧化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3690, 3797, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收', '本品对人体有毒。能腐蚀眼睛、皮肤和呼吸道粘膜，吸入后发生化学性肺炎、肺水肿。', '无资料', '本品可燃、有毒、具有腐蚀性、刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3691, 3798, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入', NULL, '无资料', '本品可燃，有毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3692, 3799, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', NULL, '无资料', '本品可燃，有毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3693, 3800, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n吸入、摄入或经皮肤吸收对身体有害。对眼睛、粘膜、呼吸道及皮肤有强烈刺激作用。吸\n入后可因喉、支气管的痉挛、炎症或水肿，化学性肺炎、肺水肿而致死。中毒表现有咳嗽、', '喘息、喉炎、气短、头痛、恶心和呕吐。慢性影响：实验显示有诱变作用。', '无资料', '本品可燃、有毒、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3694, 3801, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入食入', '对眼睛、上呼吸道、粘膜和皮肤有刺激性。', '无资料', '本品可燃，有毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3695, 3802, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入', '误服会中毒，受热分解出氮氧化物和砷烟雾。', '无资料', '本品可燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3696, 3803, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '本品具有刺激性。', '无资料', '本品可燃、高毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3697, 3804, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '无资料', '无资料。', '无资料', '本品可燃，有毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3698, 3805, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、皮肤接触、眼睛接触', '有毒，并有刺激性。进入体内后，可形成高铁血红蛋白致发生紫绀。', '无资料', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3699, 3806, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。对眼睛、呼吸道和皮肤有刺激作用。吸收进入体内可引起高铁血红蛋白血症，出现紫绀。严重中毒者可致死。本品为可疑致癌物，需严格控制接触。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '4-硝基甲苯对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，应特别注意对水体的污染。在水生生物中可能发生生物蓄积。', '本品可燃，有毒，具刺激性。遇明火、高热可燃。受高热分解放出有毒的气体。与强氧化剂、强还原剂、强碱接触可发生反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3700, 3807, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '有毒，并有刺激性。长期接触可引起皮肤、眼睛和呼吸系统刺激。可能致癌。', '对水生生物有害。', '遇明火、高热可燃。受热分解产生有毒烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3701, 3808, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、皮肤接触', '吸入、摄入对身体有害。对眼睛、皮肤、粘膜及呼吸道有刺激作用。中毒表现有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。吸入后可能由于喉、支气管的痉挛、炎症和水肿，化学性肺炎、肺水肿而致死。', '无资料', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3702, 3809, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收后可能对身体有害。对眼睛和皮肤有刺激性。经皮肤可迅速吸收，引起高铁血红蛋白血症，出现紫绀。', '无资料', '本品可燃，有毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3703, 3810, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入或口服对身体有害。支气管的痉挛、炎症、水肿，化学性肺炎或肺水肿而致死。中毒表现有烧灼感、咳嗽、喘息、气短、头痛、恶心和呕吐。', '无资料', '本品可燃，有毒，具腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3704, 3811, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入、食入、经皮肤吸收', '吸入、摄入或经皮肤吸收后对身体可能有害。蒸气或烟雾对眼睛、粘膜和上呼吸道有刺激作用。', '无资料', '本品易燃、具有刺激性。遇明火、高热易燃烧爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3705, 3812, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。其蒸气或雾对眼睛、粘膜和上呼吸道有刺激性。高浓度吸入可引起肺水肿。空气中本品在0.5ppm时即不能忍耐。', '对环境有危害，对水体和大气可造成污染。', '本品可燃，有毒，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3706, 3813, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '本品有毒，具有腐蚀性。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。吸入可引起喉、支气管炎症、化学性肺炎、肺水肿。接触后可引起头痛、头晕、恶心、呕吐、腹痛、腹泻等症状。', '该物质对环境可能有危害，对水体应给予特别注意。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3707, 3814, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '对皮肤有刺激性。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。吸入可引起呼吸道刺激。误食可引起胃肠道刺激。', '对水生物有剧毒,对水生环境可能会引起长期有害作用。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3708, 3815, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对肝、肾有损害作用。进入体内可形成高铁血红蛋白，导致发生紫绀。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生生物有极大危害，可能对水体环境产生长期不良影响。', '遇明火、高热可燃。受热分解，放出有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3709, 3816, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入食入经皮吸收', '对眼睛、上呼吸道、粘膜和皮肤有刺激性。长时间接触可引起眼睛的强烈刺激或灼伤。', '对水生生物有毒。在环境中可能对生态系统造成长期不利影响。', '本品可燃，有毒，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3710, 3817, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收对身体有害。对眼睛、粘膜、呼吸道和皮肤有强烈刺激作用。吸入后可因喉、支气管的痉挛、炎症、水肿，化学性肺炎、肺水肿而致死。中毒表现有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '对水生生物有极大危害，可能对水体环境产生长期不良影响。', '遇明火、高热可燃。受热分解产生有毒的溴化物和氯化物烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3711, 3818, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '吸入其蒸气对呼吸道有刺激性，可出现兴奋、共济失调等症状。受高热分解产生有毒气体。', '无资料', '本品可燃，有毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3712, 3819, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入、食入、经皮吸收', '有腐蚀性。蒸气对眼睛、皮肤、粘膜有强烈刺激作用。吸入，可引起喉炎、支气管炎、化学性肺炎、肺水肿等。接触后可引起头痛、头晕、恶心、呕吐、咳嗽、气短等症状。', '无资料', '本品可燃、有毒、具有腐蚀性、强刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3713, 3820, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤、粘膜和上呼吸道有刺激作用。吸入可引起喉、支气管炎症、化学性肺炎、肺水肿。接触后可引起气短、头痛、恶心和呕吐。', '该物质对环境可能有危害，对水体应给予特别注意。', '遇明火、高热可燃。受热分解产生有毒的溴化氢气体。有毒，具腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3714, 3821, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入', '对眼睛、皮肤、粘膜和上呼吸道有刺激作用。有毒，并有麻醉作用。', '无资料', '本品可燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3715, 3822, NULL, NULL, NULL, NULL, NULL, '第4.2类 自燃物品；皮肤腐蚀/刺激，类别2', '吸入、食入、皮肤接触、眼睛接触', '吸入、摄入或经皮肤吸收可致死。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激性。可引起高铁血红蛋白血症，出现紫绀、呼吸困难、头痛、头晕、恶心、呕吐等症状。长期接触可损害肝脏和肾脏功能。', '对水生生物有毒性作用', '遇明火、高热可燃。受热分解产生有毒的氮氧化物气体。具有自燃性，暴露在空气中可能自燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3716, 3823, NULL, NULL, NULL, NULL, NULL, '第4.2类 自燃物品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收可致死。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激性。可引起高铁血红蛋白血症，出现紫绀、呼吸困难、头痛、头晕、恶心、呕吐等症状。', '对水生生物有毒性作用', '本品属自燃物品、有毒、具有刺激性。遇明火、高热可燃。受热分解产生有毒的氮氧化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3717, 3824, NULL, NULL, NULL, NULL, NULL, '第4.1类 易燃固体；皮肤腐蚀/刺激，类别2', '吸入、食入、皮肤接触、眼睛接触', '吸入、摄入或经皮肤吸收可致死。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激性。可引起高铁血红蛋白血症，出现紫绀、呼吸困难、头痛、头晕、恶心、呕吐等症状。具有致敏作用，长期接触可损害肝脏和肾脏功能。', '对水生生物有毒性作用', '遇明火、高热可燃。受热分解产生有毒的氮氧化物气体。与酸、碱接触能引起燃烧爆炸。具有自燃性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3718, 3825, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '有毒。对眼睛、皮肤和粘膜有刺激作用。接触可引起头痛、恶心和呕吐等。', '无资料', '本品易燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3719, 3826, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入、食入、经皮吸收', '吸入、摄入或经皮吸收对身体有害。蒸气或雾对眼、粘膜和上呼吸道有刺激性。对皮肤有刺激性。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3720, 3827, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收对身体有害。蒸气或雾对眼、粘膜和上呼吸道有刺激性。对皮肤有刺激性。', '对环境有危害，对水体和大气可造成污染。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3721, 3828, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '对皮肤和眼睛有刺激作用。蒸气能经皮肤吸收。引起类似苯胺的中毒症状，如头痛、眩晕、发绀等。造成轻微皮肤刺激，造成严重眼刺激。吸入可能导致过敏或哮喘病症。', '该物质对环境有危害，建议不要让其进入环境。', '本品可燃、有毒、具有刺激性。遇明火、高热可燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3722, 3829, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。误食可引起中毒症状，包括空间和时间感失常、睡眠时伴有轻微的恶心和呕吐。高剂量可引起中枢神经系统抑制。', '对水生生物有害。', '遇明火、高热可燃。受热分解产生有毒的氮氧化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3723, 3830, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入有毒。对皮肤有刺激性。对眼睛有严重刺激性。对呼吸道有刺激作用。长期或反复接触可能引起皮肤过敏。', '该物质对水生生物可能有毒性。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3724, 3831, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吞食后有剧毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。可引起骨髓抑制、胃肠道反应等。具有致突变性和致癌性。', '对水生生物有剧毒。', '遇明火、高热可燃。受热分解产生有毒的氮氧化物和氯化氢气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3725, 3832, NULL, NULL, NULL, NULL, NULL, '第8类腐蚀性物品', '吸入、食入、皮肤接触、眼睛接触', '对皮肤、眼睛、粘膜和上呼吸道有强烈刺激作用。吸入可引起喉、支气管的炎症、水肿、痉挛，化学性肺炎或肺水肿。接触后可引起头痛、头晕、恶心、呕吐等。长期或反复接触可能引起皮肤过敏。', '本品对水生生物有害并具有长期持续影响。', '易燃。受热分解产生有毒的氧化氮气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3726, 3833, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '高毒有机磷杀虫剂。对胆碱酯酶有抑制作用。轻度中毒出现头痛、头晕、多汗、流涎、视力模糊、乏力、恶心、呕吐等；中度中毒出现肌束震颤、瞳孔缩小、呼吸困难、腹痛、腹泻、神志模糊等；重度中毒出现昏迷、惊厥、肺水肿、呼吸抑制和脑水肿等。', '对水生生物有极高毒性。对环境有危害，对水体和土壤可造成污染。', '本品可燃、高毒。遇明火、高热可燃。受高热分解，放出有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3727, 3834, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点液体', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收对身体有害。蒸气或雾对眼、粘膜和上呼吸道有刺激性，对皮肤有刺激性。', '对水生生物有害。', '遇明火、高热可燃。与氧化剂可发生反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3728, 3835, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、食入或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。吸入可引起咳嗽、气短、呼吸困难等。高浓度接触可引起头痛、头晕、恶心、呕吐等。', '对水生生物有害。避免释放到环境中。', '本品易燃、具有刺激性。遇明火、高热易引起燃烧。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂能发生强烈反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3729, 3836, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。本品对眼睛、皮肤有刺激作用。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '5-甲基-2-己酮对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。挥发后可参与形成光化学烟雾。', '本品易燃、具有刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。与强氧化剂、强还原剂、强碱接触可发生反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3730, 3837, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、皮肤接触、眼睛接触', '对皮肤有刺激性。对眼睛有严重刺激性。对呼吸道有刺激作用。', '无资料', '可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3731, 3838, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。吸入、摄入或经皮肤吸收可致死。对眼睛、皮肤有刺激作用。进入体内可导致形成高铁血红蛋白血症。高浓度时可引起发绀，这种症状可持续2～4小时或更长时间。本品为可疑致癌物，需严格控制接触。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '5-氯-2-甲基苯胺对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，建议不要让其进入环境。在水生生物中可能发生生物蓄积。', '本品可燃、有毒、具有刺激性。遇明火、高热可燃。受高热分解放出有毒的气体。与强氧化剂、酸类接触可发生反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3732, 3839, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后会中毒。对眼睛、皮肤有刺激作用。进入体内能形成高铁血红蛋白，可致紫绀。受热分解释出氮氧化物和氯烟雾。', '对水生生物有毒性。对环境有危害。', '本品可燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3733, 3840, NULL, NULL, NULL, NULL, NULL, '第1.1类爆炸品', '吸入、食入、经皮吸收', '吸入、食入、经皮吸收可引起中毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期接触可引起慢性中毒。', '对水生物有剧毒,对水生环境可能会引起长期有害作用。', '易燃，其粉体与空气混合，能形成爆炸性混合物。受撞击、摩擦，遇明火或其他点火源有爆炸危险。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3734, 3841, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收，可能引起中毒死亡。蒸气或雾对眼、粘膜和上呼吸道有刺激性。对皮肤有刺激性。吸收进入人体后，可引起高铁血红蛋白血症，出现紫绀。', '对水生生物有害。', '遇明火、高热可燃。受热分解放出有毒的气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3735, 3842, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。资料报道有致突变作用。受热分解释出氮氧化物。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。长期接触可引起肝、肾功能损害，神经系统损伤等。本品可通过皮肤吸收。', '对水生生物有毒性。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '遇明火、高热可燃。受热分解产生有毒的氮氧化物气体。与氧化剂可发生反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3736, 3843, NULL, NULL, NULL, NULL, NULL, '第1类爆炸品', '吸入、食入、经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。受热分解释出氮氧化物，具刺激性。', '对水生生物有毒性。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '遇明火、高热、摩擦、震动、撞击，有引起燃烧爆炸的危险。受热分解放出有毒的氮氧化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3737, 3844, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。接触后可引起眼部不适、皮肤刺激和呼吸道刺激症状。受热分解释出氮氧化物，具刺激性。', '对环境有严重危害，对水体应给予特别注意。', '遇明火、高热可燃。受热分解产生有毒的氮氧化物气体。与氧化剂可发生反应。粉体与空气可形成爆炸性混合物，当达到一定浓度时，遇火星会发生爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3738, 3845, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '跟皮肤接触可能会引起敏化作用。对眼睛有严重刺激性。可能有损伤胎儿或胚胎的危险。', '对水生物有剧毒, 对水生环境可能会引起长期有害作用。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3739, 3846, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。有毒。对皮肤和眼睛有明显的刺激作用，并可引起较严重的持久性的损害。资料报道有致突变作用。受热分解放出氮氧化物烟雾。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '6-甲基喹啉对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，建议不要让其进入环境。在水生生物中可能发生生物蓄积。', '本品可燃、有毒、具有刺激性。遇明火、高热可燃。受高热分解，放出有毒的烟气。与强氧化剂、强酸接触可发生反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3740, 3847, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '对皮肤有刺激性。对眼睛有严重刺激性。对呼吸道有刺激作用。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3741, 3848, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。对眼睛、皮肤和粘膜有强烈的刺激作用，可致灼伤。吸入，可引起喉、支气管炎症、痉挛，化学性肺炎、肺水肿等。接触后可有头痛、恶心、呕吐、喉炎、气短、咳嗽等症状。具强刺激性，可致人体灼伤。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '6-氯间甲酚对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，应特别注意对水体的污染。在水生生物中可能发生生物蓄积。', '本品可燃、有毒、具有强刺激性。遇明火、高热可燃。受高热分解，放出高毒的烟气。与强氧化剂、强碱、酸酐、酰基氯接触可发生反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3742, 3849, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。有毒。对皮肤和眼睛有明显的刺激作用，并引起较严重的持久性的损害。受热分解放出氮氧化物烟雾。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '7-甲基喹啉对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，建议不要让其进入环境。在水生生物中可能发生生物蓄积。', '本品可燃、有毒、具有刺激性。遇明火、高热可燃。受高热分解，放出有毒的烟气。与强氧化剂、强酸接触可发生反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3743, 3850, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '对皮肤有刺激性。对眼睛有严重刺激性。对呼吸道有刺激作用。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3744, 3851, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吞食后有剧毒。对中枢神经系统有兴奋作用，过量使用可引起惊厥、抽搐等严重反应。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生生物可能有毒性，应避免污染水体。', '遇明火、高热可燃。受热分解产生有毒的氮氧化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3745, 3852, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。有毒。对皮肤和眼睛有明显的刺激作用，并引起较严重的持久性的损害。受热分解放出氮氧化物的烟雾。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '8-甲基喹啉对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，建议不要让其进入环境。在水生生物中可能发生生物蓄积。', '本品可燃、有毒、具有刺激性。遇明火、高热可燃。受高热分解，放出有毒的烟气。与强氧化剂、强酸接触可发生反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3746, 3853, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '对皮肤有刺激性。对眼睛有严重刺激性。对呼吸道有刺激作用。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3747, 3854, NULL, NULL, NULL, NULL, NULL, '第4.2类自热物质和混合物，类别1', '吸入、食入、皮肤接触、眼睛接触', '吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入该物质可能会引起对健康有害的影响或胃肠道不适。皮肤接触该物质可能会引起对健康有害的影响或皮肤刺激。眼睛接触该物质可能会引起对健康有害的影响或眼睛刺激。', '该物质可能对水生生物有害。避免释放到环境中。', '遇明火、高热可燃。受热分解产生有毒气体。与氧化剂接触有发生燃烧和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3748, 3855, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n对皮肤、粘膜有强烈刺激性。引起眼睑水肿、结膜炎、喉炎、支气管炎及哮喘发作。皮肤接触\n后，引起剧痒，皮肤粘膜有时可发生严重炎症，对皮肤有光敏感作用。严重中毒者可有呼', '吸加速，血压升高。', '无资料', '本品可燃、有毒、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3749, 3856, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '对皮肤有刺激性。跟皮肤接触可能会引起敏化作用。', '对水生物有剧毒,对水生环境可能会引起长期有害作用。', '易燃,其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3750, 3857, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '致突变作用。受热分解释出有毒的氯气和氮氧化物。', '无资料', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3751, 3858, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、皮肤接触、食入', '对眼睛、皮肤、呼吸道有刺激性。长期接触可能对肝脏、肾脏和神经系统造成损害。', '对水生物有毒，对水生环境可能会引起长期有害作用。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3752, 3859, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、皮肤接触、食入', '对皮肤有刺激性。跟皮肤接触可能会引起敏化作用。对呼吸道有刺激作用。长期接触可能对肝脏、肾脏和神经系统造成损害。', '对水生物有毒，对水生环境可能会引起长期有害作用。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3753, 3860, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '释出氯和氮氧化物烟雾。', '无资料', '本品可燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3754, 3861, NULL, NULL, NULL, NULL, NULL, '第6.1 类毒害品', '吸入、皮肤接触、食入', '对眼睛、皮肤、呼吸道有刺激性。长期接触可引起神经系统损害、肝肾功能损害。具有致癌性。', '对水生生物有毒，可能对水环境造成长期不良影响。', '本品可燃，有毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3755, 3862, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吞食后有毒。对皮肤有刺激性。对眼睛有严重刺激作用。长期接触可能对中枢神经系统产生影响。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。对土壤生物有害。', '可燃，遇明火、高热可燃。燃烧时产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3756, 3863, NULL, NULL, NULL, NULL, NULL, '侵入途径： 食入', '食入', '吞食后有剧毒', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3757, 3864, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜和呼吸道有强烈刺激性。吸入后可引起喉、支气管的炎症、水肿、痉挛，化学性肺炎或肺水肿。接触后可引起烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心、呕吐等。', '该物质对环境可能有危害，对水体应给予特别注意。', '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3758, 3865, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入', '对眼睛、皮肤、粘膜及上呼吸道有刺激作用。可发生皮炎。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3759, 3866, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '对皮肤有刺激性。对眼睛有严重刺激性。对呼吸道有刺激作用。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3760, 3867, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入 食入', '本品有腐蚀性，对眼睛、粘膜、皮肤有刺激性。误服、吸入能引起中毒。', '无资料', '本品易燃，具腐蚀性、刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3761, 3868, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、摄入或经皮吸收后引起中毒，可能引起刺激作用。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '无资料', '本品易燃、高毒、强刺激性。遇高热、明火或与氧化剂接触，有引起燃烧的危险。受热分解产生有毒的氰化氢、氮氧化物烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3762, 3869, NULL, NULL, NULL, NULL, NULL, '第8.2类 碱性腐蚀品', '吸入、食入、经皮吸收', '对皮肤、眼睛和粘膜有强烈刺激性，可引起严重灼伤。吸入蒸气可刺激呼吸道，引起咳嗽、呼吸困难，严重时可导致喉痉挛、肺水肿。长期接触可致皮肤过敏。误服可引起消化道灼伤。', '可能对水生环境造成危害', '易燃，遇明火、高热有燃烧爆炸的危险。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3763, 3870, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激性。吸入后可引起头痛、头晕、恶心、呼吸困难。', '对水生生物有害。', '高度易燃，其蒸气与空气混合，能形成爆炸性混合物。遇明火、高热极易燃烧爆炸。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3764, 3871, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收后对身体有害。其蒸气或雾对眼睛、粘膜和上呼吸道有刺激性。对皮肤有刺激性。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3765, 3872, NULL, NULL, NULL, NULL, NULL, '第3.2类高闪点易燃液体；皮肤腐蚀/刺激类别2；严重眼损伤/眼刺激类别2A', '吸入、食入、经皮吸收', '本品对皮肤有刺激作用，蒸气或烟雾对眼睛、粘膜和上呼吸道有刺激作用。长期接触可能引起皮肤过敏。', '该物质对环境可能有危害，对水体应给予特别注意。', '易燃，遇明火、高热可燃。受热分解产生有毒气体。蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3766, 3873, NULL, NULL, NULL, NULL, NULL, '第8.2类 碱性腐蚀品', '吸入 食入 经皮吸收', '本品对粘膜、上呼吸道、眼和皮肤有强烈的刺激性。吸入后，可因喉及支气管的痉挛、炎症、水肿，化学性肺炎或肺水肿而致死。接触后出现烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '无资料', '本品易燃，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3767, 3874, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入经皮吸收\n急性中毒：主要有眼和上呼吸道刺激症状、头痛、焦虑、恶心、呕吐、腹痛、便秘等。肝\n损害一般在中毒数日后出现，肝脏肿大，肝区痛，可出现黄疸。经皮肤吸收中毒者，皮肤', '出现水泡、水肿、粘糙，局部麻木、瘙痒、灼痛。慢性影响：有皮肤、粘膜刺激，神经衰\n弱综合征，血压偏低。还有恶心、呕吐、胸闷、食欲不振、胃痛、便秘及肝大和肝功能变\n化。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3768, 3875, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '吸入、摄入或经皮肤吸收可致死。具有刺激性。', '无资料', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3769, 3876, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入经皮吸收', '支气管的炎症、水肿、痉挛，化学性肺炎、肺水肿等。对皮肤有致敏作用。', '无资料', '本品易燃，具强刺激性，具致敏性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3770, 3877, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入经皮吸收\n吸入、口服或经皮肤吸收后对身体有害。', '激作用。吸入后，可引起喉、支气管的炎症、水肿、痉挛、化学性肺炎、肺水肿。接触\n后可有烧灼感、咳嗽、眩晕、气短、头痛、恶心和呕吐等。', '无资料', '本品易燃，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3771, 3878, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期或反复接触可能引起皮肤过敏。可能对器官造成损害。', '可能对水生生物有害。避免释放到环境中。', '遇明火、高热可燃。受热分解产生有毒气体，包括氮氧化物和一氧化碳。与氧化剂接触有发生火灾和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3772, 3879, NULL, NULL, NULL, NULL, NULL, '第4.1类易燃固体', '吸入食入', '本品热解能放出有毒的氮氧化物烟雾。口服具有中等毒性。', '无资料', '本品易燃，具爆炸性，有毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3773, 3880, NULL, NULL, NULL, NULL, NULL, '第8.2类 碱性腐蚀品', '吸入 食入 经皮吸收', '有毒。有腐蚀性。对眼睛、皮肤和粘膜有刺激作用。', '无资料', '本品易燃、具有腐蚀性、刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3774, 3881, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, '对水生物有毒，对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3775, 3882, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入食入经皮吸收\n吸入、口服或经皮肤吸收可致死。蒸气或雾对眼、粘膜和上呼吸道有刺激性。吸收进入体', '内引起高铁血红蛋白血症，出现紫绀。', '无资料', '本品易燃，有毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3776, 3883, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 经皮吸收', '本品受热能分解出有毒气体。', '无资料', '本品可燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3777, 3884, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收', '分解放出氯、氮氧化物和氧化硫。', '无资料', '本品可燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3778, 3885, NULL, NULL, NULL, NULL, NULL, 'GHS分类：皮肤刺激性第2类、眼睛刺激性第2类', '吸入 食入 经皮吸收', '本品对皮肤有刺激作用。蒸气或烟雾对眼睛、粘膜和上呼吸道有刺激作用。', '对水生生物有毒，可能导致对水生环境的长期不利影响。', '本品闪点>110℃，不属于易燃液体。遇高热、明火或与氧化剂接触，有引起燃烧的危险。燃烧分解时，放出有毒的氮氧化物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3779, 3886, NULL, NULL, NULL, NULL, NULL, '皮肤腐蚀/刺激，类别2；眼损伤/眼刺激，类别2A。', '吸入、食入、皮肤接触、眼睛接触\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3780, 3887, NULL, NULL, NULL, NULL, NULL, '第8.2类 碱性腐蚀品', '吸入 食入 经皮吸收\n对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用，接触后可引起头痛、头晕、恶心、呕吐、', '咳嗽等。', '无资料', '本品易燃、强腐蚀性、强刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3781, 3888, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入经皮吸收', '人吸入1000mg/m3的本品几秒钟，即出现恶心和呕吐。', '无资料', '本品易燃，具腐蚀性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3782, 3889, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '吸入、摄入或经皮吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激性。吸入后可引起咳嗽、喘息、气短、头痛、恶心和呕吐。', '该物质对环境可能有危害，对水体应给予特别注意。', '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3783, 3890, NULL, NULL, NULL, NULL, NULL, '第8.3类 其它腐蚀品', '吸入 食入 经皮吸收', '误服或吸入有毒。对眼睛、皮肤和粘膜有刺激性和腐蚀性。', '无资料', '本品易燃、具有腐蚀性、刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3784, 3891, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '本品具有刺激性。', '无资料', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3785, 3892, NULL, NULL, NULL, NULL, NULL, '侵入途径：', '跟皮肤接触可能会引起敏化作用。可能有损伤胎儿或胚胎的危险。长期暴露有损伤健康', NULL, '对水生物有剧毒, 对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3786, 3893, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品，GHS危险性类别：急性毒性-吸入(类别2)、皮肤腐蚀/刺激(类别2)、严重眼睛损伤/眼刺激(类别2)、皮肤致敏(类别1)', '吸入、食入、皮肤接触、眼睛接触', '跟皮肤接触可能会引起敏化作用。对眼睛有严重刺激性。对皮肤有刺激性。对呼吸道有刺激性。急性毒性，吸入有害。长期接触和吸入可能引起皮肤过敏反应、眼部损伤、呼吸系统受损等症状。', '对水生物有剧毒。对水体环境可能造成长期不良影响。', '受热分解产生有毒气体，包括氟化氢、氯化氢、氧化硫、氧化氮等。遇明火、高热可燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3787, 3894, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有剧毒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3788, 3895, NULL, NULL, NULL, NULL, NULL, '第8.3类其它腐蚀品', '无资料', '可刺激眼睛和呼吸系统，可致突变。', '无资料', '本品易燃、有毒、具有腐蚀性、刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3789, 3896, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入食入经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有刺激性。对皮肤有致敏作用。', '无资料', '本品可燃，有毒，具刺激性，具致敏性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3790, 3897, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入对上呼吸道有刺激性。高剂量摄入可引起高铁血红蛋白血症和骨髓增生。反复接触可发生紫绀。对皮肤有刺激性，可致皮炎。', '无资料', '本品有毒、具有刺激性。遇高热、明火或与氧化剂接触，有引起燃烧的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3791, 3898, NULL, NULL, NULL, NULL, NULL, '急性经口毒性 类别4；危害水生环境——急性危险 类别1', '吸入、食入、皮肤接触', '吞咽有害。对水生生物毒性极大并具有长期持续影响。', '对水生物有剧毒，对水生环境可能会引起长期有害作用', '可燃，燃烧分解物包括一氧化碳、二氧化碳、氯化物、氮氧化物', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3792, 3899, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吞食后有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期或反复接触可能引起皮肤过敏。', '对水生环境可能会引起长期有害作用', '遇明火、高热可燃。受热分解产生有毒的氮氧化物烟气。与氧化剂可发生反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3793, 3900, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收\n属高毒类。吸入其蒸气可引起眼、呼吸道刺激，恶心、呕吐，甚至出现迟发性肺水肿；人', '误服数毫克本品，即可产生恶心、呕吐和腹泻。对皮肤、粘膜有强烈刺激和糜烂作用。', '无资料', '本品可燃、高毒、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3794, 3901, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '持续暴露于二环己基胺亚硝酸盐类蒸气会影响中枢神经系统、红血球、高铁血红蛋白，使肝、肾功能和血压降低。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '该物质对环境可能有危害，对水体应给予特别注意。', '遇明火、高热可燃。受热分解产生有毒的氮氧化物烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3795, 3902, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '毒性与苯胺相似，可形成高铁血红蛋白，造成组织缺氧；引起中枢神经系统、心血管系统和其它脏器损害。急性中毒：表现为口唇、指端、耳廓紫绀，出现恶心、呕吐、手指麻木、精神恍惚；重者皮肤、粘膜严重紫绀，出现呼吸困难、抽搐等，甚至昏迷、休克。慢性影响：长期接触可引起贫血、肝、肾损害。', '对水生生物有毒性作用。', '本品易燃，有毒。遇高热、明火或与氧化剂接触，有引起燃烧的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3796, 3903, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入、食入、经皮吸收', '对皮肤、眼睛和呼吸道有刺激性，可能对中枢神经系统有影响。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3797, 3904, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '吸入本品蒸气或雾对呼吸道有刺激性。眼和皮肤接触有刺激作用。口服对机体有害。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3798, 3905, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入、食入、经皮吸收', '误服、吸入或与皮肤接触对身体有害。本品对眼睛、皮肤和粘膜有刺激性。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3799, 3906, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吞咽有害。皮肤接触有害。造成皮肤刺激。造成严重眼刺激。吸入有害。可引起呼吸道刺激。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。该物质属于PFOS类化学品，具有持久性、生物累积性和毒性。', '遇明火、高热可燃。受热分解产生有毒的氟化物、氮氧化物和硫氧化物烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3800, 3907, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收后对身体有害。吸入后，可因喉及支气管的痉挛、炎症、水肿，化学性肺炎或肺水肿而致死。长时间接触可引起强烈刺激或灼伤。', '无资料', '本品易燃，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3801, 3908, NULL, NULL, NULL, NULL, NULL, '侵入途径： 吸入，食入，皮肤接触', '吸入，食入，皮肤接触\n导致气喘性过敏，呼吸短促、喘鸣、咳嗽、胸闷，并损害肝、肾；暴露会刺激皮肤，引起', '过敏', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3802, 3909, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '对人体有刺激性和毒性。受热分解释出有毒的氮氧化物气体。有可疑的致癌作用。', '无资料', '本品可燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3803, 3910, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', NULL, '无资料', '本品有毒、刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3804, 3911, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收', NULL, '无资料', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3805, 3912, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, '对水生物有毒，对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3806, 3913, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n毒性与苯胺相似，但稍弱。能引起高铁血红蛋白血症，造成组织缺氧，对中枢神经系统及', NULL, '无资料', '本品可燃，有毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3807, 3914, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, '对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3808, 3915, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收', '血红蛋白，可致发生氰紫症。', '无资料', '本品可燃、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3809, 3916, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入 食入 经皮吸收', '水肿、化学性肺炎或肺水肿而致死。中毒表现有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶\n心和呕吐等。', '无资料', '本品易燃', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3810, 3917, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入经皮吸收', '蒸气或雾对眼、上呼吸道有刺激性。对皮肤有刺激性。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3811, 3918, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, '对水生物有毒，对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3812, 3919, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有剧毒。跟皮肤接触有剧毒。吸入有剧毒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3813, 3920, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '无资料', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3814, 3921, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '本品为低毒除草剂。中毒症状有头痛、头晕、恶心、呕吐、胸闷、紫绀、抽搐及昏迷等。', '无资料', '本品可燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3815, 3922, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品；GHS分类：急性毒性-经口第4类、皮肤刺激性第2类、眼睛刺激性第2类（根据LD50数据推断）', '吸入、食入、经皮吸收', '误服、与皮肤接触或吸入蒸气会中毒。对皮肤、眼睛有强烈刺激作用。遇热分解释出有毒的氮氧化物烟雾。', '对环境有危害，对水体可造成污染。', '本品可燃、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3816, 3923, NULL, NULL, NULL, NULL, NULL, '侵入途径：', '吞食后有毒。跟皮肤接触有毒。对皮肤有刺激性。有严重损害眼睛的危险。吸入有剧毒。', '对呼吸道有刺激作用。', '对水生生物有害', '可燃液体，遇明火、高热可燃', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3817, 3924, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收', '烟雾。', '无资料', '本品可燃、高毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3818, 3925, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n抑制胆碱酯酶，造成神经生理功能紊乱。出现毒蕈碱样和烟碱样症状。急性中毒：短期内\n接触大量引起急性中毒。表现有头痛、头昏、食欲减退、恶心、呕吐、腹痛、腹泻、流涎、\n瞳孔缩小、呼吸道分泌物增多、多汗、肌束震颤等。重者出现肺水肿、脑水肿、昏迷、呼', NULL, NULL, '本品可燃，有毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3819, 3926, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '有机磷农药抑制胆碱酯酶活性，造成神经生理功能紊乱。急性中毒：短期内接触(口服、吸入、皮肤、粘膜)大量引起急性中毒。表现有头痛、头昏、食欲减退、恶心、呕吐、腹痛、腹泻、流涎、瞳孔缩小、呼吸道分泌物增多、多汗、肌束震颤等。重者出现肺水肿、脑水肿、昏迷。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品可燃，高毒。受热分解，放出磷、硫的氧化物等毒性气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3820, 3927, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '少数人有腹痛，腹泻。', '无资料', '本品可燃、剧毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3821, 3928, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收\n过量接触刺激上呼吸道。高浓度引起肺刺激，出现咳嗽、不适、呼吸困难等。患呼吸系统疾', '病者，对本毒物的敏感性增加。', '无资料', '本品腐蚀性、刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3822, 3929, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '抑制胆碱酯酶，引起神经生理功能紊乱。中毒症状有头晕、无力、视物模糊、恶心、呕吐、\n瞳孔缩小、肌纤颤等。严重者出现肺水肿、大小便失禁、昏迷等。', '二溴磷对水生生物高毒，应避免进入水体、土壤和地下水。该物质对环境有严重危害，应特别注意对水体的污染。有机磷化合物在环境中可能发生水解和生物降解，但降解速度较慢。在水生生物中可能发生生物蓄积。', '本品可燃，有毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3823, 3930, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n抑制体内胆碱酯酶，造成神经生理功能紊乱。急性中毒多系误服引起。中毒表现有头痛、\n头昏、食欲减退、恶心、呕吐，腹痛、腹泻、流涎、瞳孔缩小、呼吸道分泌物增多、多汗、\n肌束震颤等。重症出现肺水肿、昏迷、呼吸麻痹、脑水肿。血胆碱酯酶活性降低。少数重', '度中毒者在临床症状消失后数周出现周围神经病。本品可引起变应性接触性皮炎。慢性中\n毒：接触工人可因持续经呼吸道及皮肤进入而中毒。表现有头晕、头痛、无力、失眠、多\n汗、四肢麻木、肌肉跳动等。血胆碱酯酶活性降低。', '无资料', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3824, 3931, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '本品为间接抑制剂，其有机磷中毒症状出现较迟，作用慢，但持续时间长，并且症状常', '无资料', '本品可燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3825, 3932, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n抑制胆碱酯酶活性，引起神经功能紊乱，发生与胆碱能神经过度兴奋相似的症状。急性中毒；\n轻度：有头痛、头晕、恶心、呕吐、多汗、胸闷、视力模糊、无力等症状，全血胆碱酯酶活性\n在50～70％；中度：除上述症状外，有肌束震颤、瞳孔缩小、轻度呼吸困难、流涎、腹痛、腹', '泻等，全血胆碱酯酶活性在30～50％；重度：上述症状加重，可有肺水肿或昏迷或呼吸麻痹或\n脑水肿，全血胆碱酯酶活性在30％以下。慢性影响：可有神经衰弱综合征、腹胀、多汗、肌纤\n维震颤等，全血胆碱酯酶活性降至50％以下。', '无资料', '本品有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3826, 3933, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n抑制体内胆碱酯酶，造成神经功能紊乱。大鼠经口中毒，出现震颤、肌肉痉挛、呼吸困难', '等。', '无资料', '本品剧毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3827, 3934, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入，眼睛及皮肤接触\n症状为：恶心、呕吐、腹痛、痉挛、腹泻、多涎、头痛、头昏、头晕、无力、肌肉扭曲、', '呼吸困难、胸闷、视觉模糊和昏暗、肌肉失调，甚至因严重呼吸瘫痪和衰竭，导致支气管\n紧缩而致死', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3828, 3935, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有剧毒。跟皮肤接触有毒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3829, 3936, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '另外，有的病例可出现迟发性神经病。', '无资料', '本品可燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3830, 3937, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '对人的致死剂量估计为0.2g，中毒情况与一般有机磷农药相同。', '无资料', '本品可燃、高毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3831, 3938, NULL, NULL, NULL, NULL, NULL, '急毒性-口服，类别2；危害水生环境-急性毒性，类别1。', '吸入、食入、皮肤接触、眼睛接触\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3832, 3939, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有毒。跟皮肤接触有毒。吸入有毒。', '对水生物有剧毒,对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3833, 3940, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收', '呕吐、流涎、瞳孔缩小、腹痛、抽搐等。', '无资料', '本品可燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3834, 3941, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收\n人经口或经皮吸收后可引起急性中毒，出现头痛、头晕、无力、烦躁、恶心、呕吐、出\n汗、流涎、瞳孔缩小、肌肉颤抖、抽搐、痉挛、呼吸困难、紫绀，重者常伴有肺水肿和', '脑水肿，死于呼吸衰竭。全血胆碱酯酶活性下降。', '无资料', '本品可燃、高毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3835, 3942, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有剧毒', '对水生物有剧毒, 对水生环境可能会引起长期有害作用', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3836, 3943, NULL, NULL, NULL, NULL, NULL, '急毒性-口服，类别2；急毒性-皮肤，类别1。', '吸入、食入、皮肤接触、眼睛接触\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3837, 3944, NULL, NULL, NULL, NULL, NULL, '急毒性-口服，类别2；急毒性-皮肤，类别1；危害水生环境-急性毒性，类别2；危害水生', '皮肤接触、眼睛接触、吸入、食入\n吸入引起头痛、头昏、神经质、视力模糊、恶心、呕吐、痛性痉挛、腹泻、胸部不适，严', '重者惊厥、昏迷、失去反应、括约肌失控', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3838, 3945, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有剧毒。跟皮肤接触有剧毒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3839, 3946, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有剧毒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3840, 3947, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '中毒性肝炎、阵发性心房颤动以及精神病后遗症等。慢性接触可出现头痛、无力及消化不良，\n植物神经功能紊乱，部分工人血压偏低等。', '无资料', '本品剧毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3841, 3948, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收', '脑水肿，可死于呼吸衰竭。', '无资料', '本品可燃、高毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3842, 3949, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收', '外，有的病例可出现迟发性神经病。', '无资料', '本品可燃、高毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3843, 3950, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有剧毒。跟皮肤接触有剧毒。', '对水生物有剧毒,对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3844, 3951, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '抑制胆碱酯酶活性，造成神经生理功能紊乱。急性中毒：短期内接触(口服、吸入、皮肤、粘膜)大量引起急性中毒。表现有头痛、头昏、食欲减退、恶心、呕吐、腹痛、腹泻、流涎、瞳孔缩小、呼吸道分泌物增多、多汗、肌束震颤等。重者出现肺水肿、脑水肿、昏迷、呼吸麻痹而死亡。可引起接触性皮炎。慢性中毒：长期接触可引起神经衰弱综合征、多汗、震颤、瞳孔缩小、肌束震颤等。', '对水生生物有极高毒性。可能对环境造成长期危害。该物质对环境有危害，应特别注意对水体的污染。', '本品可燃，剧毒。遇明火、高热可燃。受热分解，放出磷、硫的氧化物等毒性气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3845, 3952, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '流涎、多汗、瞳孔缩小、肺水肿、肌束震颤等。', '无资料', '本品可燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3846, 3953, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品（剧毒）', '食入、吸入、皮肤接触', '恶心、呕吐、腹痛、痉挛、腹泻、多涎、头痛、头晕、无力、脑闷、视力模糊、瞳孔缩小、肌肉失调、呼吸困难、抽筋、昏迷直至死亡。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。有机磷农药中毒症状包括胆碱酯酶抑制、流涎、流泪、恶心、呕吐、腹痛、腹泻、呼吸困难、肌肉震颤、抽搐等。', '对水生生物有极高毒性，可能对水体环境造成长期不利影响。', '遇明火、高热可燃。受热分解产生有毒的氧化磷、氯化物等气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3847, 3954, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '呕吐、出汗、流涎、瞳孔缩小、抽搐、呼吸困难、紫绀，重者常伴有肺水肿、脑]水肿，\n可死于呼吸衰竭。', '无资料', '本品可燃、高毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3848, 3955, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收', '水肿，死于呼吸衰竭。', '无资料', '本品可燃、高毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
