INSERT INTO `msds_hazard` VALUES (3853, 3960, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n抑制胆碱酯酶活性，引起神经功能紊乱，发生与胆碱能神经过度兴奋相似的症状。急性中毒：\n轻度：有头痛、头晕、恶心、呕吐、多汗、胸闷、视力模糊、无力等症状，全血胆碱酯酶活性\n在50～70％；中度：除上述症状外，有肌束震颤、瞳孔缩小、轻度呼吸困难、流涎、腹痛、腹', '泻等，全血胆碱酯酶活性在30～50％；重度：上述症状加重，可有肺水肿或昏迷或呼吸麻痹或\n脑水肿，全血胆碱酯酶活性在30％以下。慢性影响：可有神经衰弱综合征、腹胀、多汗、肌纤\n维震颤等，全血胆碱酯酶活性降至50％以下。', '无资料', '本品剧毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3854, 3961, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收', '有的病例可出现迟发性神经病。', '无资料', '本品可燃、高毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3855, 3962, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '人经口的MLD为5mg／kg，其中毒表现及全血胆碱酯酶活性的影响同一般的有机磷农药。', '无资料', '本品可燃、高毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3856, 3963, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有剧毒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3857, 3964, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n抑制胆碱酯酶活性，造成神经生理功能紊乱。急性中毒：短期内接触(口服、吸入、皮肤、\n粘膜)大量引起急性中毒。表现有头痛、头昏、食欲减退、恶心、呕吐、腹痛、腹泻、流\n涎、瞳孔缩小、呼吸道分泌物增多、多汗、肌束震颤等。重者出现肺水肿、脑水肿、昏', NULL, '无资料', '本品可燃，剧毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3858, 3965, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n高毒有机磷杀虫剂。对胆碱酯酶有抑制作用。轻度中毒出现头痛、头晕、多汗、流涎、视\n力模糊、乏力、恶心、呕吐等；中度中毒出现肌束震颤、瞳孔缩小、呼吸困难、腹痛、腹', '泻、神志模糊等；重度中毒出现昏迷、惊厥、肺水肿、呼吸抑制和脑水肿等。', '无资料', '本品可燃、高毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3859, 3966, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有剧毒。跟皮肤接触有毒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3860, 3967, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', NULL, '呕吐、出汗、流涎、瞳孔缩小、抽搐、呼吸困难、紫绀，重者常伴有肺水肿、脑水肿，\n可死于呼吸衰竭。', '无资料', '本品可燃、高毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3861, 3968, NULL, NULL, NULL, NULL, NULL, '急毒性-口服，类别2；急毒性-皮肤，类别1；危害水生环境-急性毒性，类别1；危害水生', '吸入，食入，皮肤及眼睛接触\n短时过度暴露症状包括：瞳孔缩小、视觉模糊、头痛、头昏、肌肉痉挛、极度无力、呕吐、', '腹泻、腹痛、癫痫发作、昏迷；口服后，心率减慢；皮肤接触心率增加、胸闷、低血压或\n高血压、气短；吸入、皮肤吸收、吞服可致死', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3862, 3969, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吞食后有剧毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。抑制胆碱酯酶活性，引起神经功能紊乱。', '对水生生物有极高毒性，可能对水体环境造成长期不利影响。', '遇明火、高热可燃。受热分解产生有毒的氧化磷、氧化硫等气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3863, 3970, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '抑制体内胆碱酯酶活性，造成神经生理功能紊乱。急性中毒症状有头痛、头昏、乏力、食欲不振、恶心、呕吐、腹痛、腹泻、流涎、瞳孔缩小、呼吸道分泌物增多等。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '遇明火、高热可燃。受热分解产生有毒的氮、硫、磷氧化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3864, 3971, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有剧毒。跟皮肤接触有剧毒。', '对水生物有剧毒, 对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3865, 3972, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有剧毒。对皮肤有刺激性。对眼睛有严重刺激性。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3866, 3973, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收', '汗、流涎，重者肌肉痉挛、昏迷、呼吸困难、出现肺水肿。', '无资料', '本品可燃、高毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3867, 3974, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n抑制胆碱酯酶活性，造成神经生理功能紊乱。急性中毒：职业中毒不多见，多系口服引起。表\n现有头痛、头昏、食欲减退、恶心、呕吐、腹痛、腹泻、流涎、瞳孔缩小、呼吸道分泌物增多、\n多汗、肌束震颤等。重者出现肺水肿、脑水肿、昏迷、呼吸麻痹。部分病例可有心、肝、肾损', NULL, NULL, '本品可燃，有毒，具刺激性，具致敏性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3868, 3975, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有剧毒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3869, 3976, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '本品为有机磷杀虫剂，抑制胆碱酯酶活性。急性中毒表现有恶心、呕吐、出汗、流涎、瞳孔缩小、抽搐、呼吸困难、紫绀，重者常伴有肺水肿、脑水肿，死于呼吸衰竭。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对环境有危害，对水体可造成污染。对水生生物有极高毒性，可能在水生环境中造成长期不利影响。', '遇明火、高热可燃。受热分解产生有毒气体。与氧化剂能发生强烈反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3870, 3977, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有毒。跟皮肤接触有毒。', '对水生物有剧毒', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3871, 3978, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n抑制胆碱酯酶活性，造成神经生理功能紊乱。急性中毒：短期内接触(口服、吸入、皮肤、\n粘膜)大量引起急性中毒。表现有头痛、头昏、食欲减退、恶心、呕吐、腹痛、腹泻、流\n涎、瞳孔缩小、呼吸道分泌物增多、多汗、肌束震颤等。重者出现肺水肿、脑水肿、昏', NULL, '无资料', '本品可燃，剧毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3872, 3979, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收', '污染的西瓜而中毒。本品有致突变作用。受热分解释出氮氧化物、氧化硫烟雾。', '无资料', '本品可燃、剧毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3873, 3980, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有剧毒。跟皮肤接触有剧毒。', '对水生物有剧毒, 对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3874, 3981, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '腹泻、神志模糊等；重度中毒出现昏迷、惊厥、肺水肿、呼吸抑制和脑水肿等。', '无资料', '本品可燃、高毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3875, 3982, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n人经口的阈作用量为9mg／d。', '经病变。', '无资料', '本品可燃、高毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3876, 3983, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吞食后有毒。跟皮肤接触有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。抑制胆碱酯酶活性，引起神经系统中毒症状。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3877, 3984, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收', '水肿，可死于呼吸衰竭。', '无资料', '本品可燃、高毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3878, 3985, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收', '衰竭、脑水肿等。少数重度中毒者在临床症状消失后数周出现周围神经病。本品可引起变\n应性接触性皮炎。', '无资料', '本品可燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3879, 3986, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有毒。跟皮肤接触有剧毒。跟皮肤接触可能会引起敏化作用。吸入有剧毒。', '对水生物有剧毒, 对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3880, 3987, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有剧毒。跟皮肤接触有剧毒。', '对水生物有剧毒, 对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3881, 3988, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, '对水生物有剧毒, 对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3882, 3989, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '汗、腹痛、腹泻、神志模糊等，以肌束震颤为特征；重度中毒出现昏迷、惊厥、肺水肿、\n呼吸抑制和脑水肿等。', '无资料', '本品可燃、高毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3883, 3990, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', NULL, '无资料', '本品可燃、高毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3884, 3991, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n主要出现胆碱能的危象。主要症状包括流涎、流泪、视力模糊、震颤、惊厥、肌肉失调、精', '神错乱、昏迷、恶心、呕吐、腹泻、腹痛，最后呼吸衰竭而死亡。', '无资料', '本品可燃、高毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3885, 3992, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有毒。跟皮肤接触有剧毒。', '对水生物有剧毒, 对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3886, 3993, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n具腐蚀性的毒物，为可疑致癌物。吸入可引起喉、支气管痉挛、炎症和水肿，化学性肺炎，', '肺水肿。', '无资料', '本品可燃、有毒、具有腐蚀性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3887, 3994, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。接', '触后可引起头痛、头晕、恶心、呕吐、咳嗽、气短等。', '无资料', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3888, 3995, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入、食入、经皮吸收', '对眼、呼吸道粘膜及皮肤有强烈刺激作用。吸入可引起喉、支气管的炎症、水肿和痉挛，化学性肺炎或肺水肿。', '无资料', '本品易燃、有毒、强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3889, 3996, NULL, NULL, NULL, NULL, NULL, '侵入途径：', '吞食后有毒。跟皮肤接触有毒。可能有损伤胎儿或胚胎的危险。长期暴露有损伤健康的', NULL, '对水生物有剧毒,对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3890, 3997, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '有毒。大剂量或过量使用，可引起心率减慢、血压下降、呼吸麻痹。', '无资料', '本品可燃、高毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3891, 3998, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入', NULL, NULL, '本品可燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3892, 3999, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n该物质对粘膜、上呼吸道、眼、皮肤等组织有极强的损坏作用。吸入后可能因喉、支气管\n的炎症、水肿、痉挛，化学性肺炎、肺水肿而致死。中毒表现有烧灼感、咳嗽、喘息、喉', '炎、气短、头痛、恶心、呕吐。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3893, 4000, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入经皮吸收\n吸入、口服或经皮肤吸收对身体有害。高浓度对眼睛、皮肤、粘膜和呼吸道有强烈的刺\n激作用。中毒表现有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。有麻醉作', NULL, '无资料', '本品易燃，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3894, 4001, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '对皮肤有刺激性。对眼睛有严重刺激性。对呼吸道有刺激作用。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3895, 4002, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '本品为有机腈类化合物，具有毒性。动物实验表明，急性中毒可引起兴奋性增强、行为改变、头部震颤、流涎、呼吸加速等症状。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。接触后可引起头痛、头晕、恶心、呕吐、腹痛等中毒症状。严重中毒可导致呼吸抑制、抽搐、昏迷，甚至死亡。', '对环境有危害，对水体可造成污染。对水生生物有极高毒性，可能在水生环境中造成长期不利影响。', '遇明火、高热可燃。受热分解产生有毒的氰化氢气体。与氧化剂能发生强烈反应。在火场中，受热的容器有爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3896, 4003, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收\n吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。受', '热分解释出氮氧化物和氰。', '无资料', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3897, 4004, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收\n吸入、摄入或经皮肤吸收后可能引起死亡。', '用。吸入后可引起喉、支气管的炎症、水肿、痉挛，化学性肺炎、肺水肿。接触后可有烧灼感、\n咳嗽、喘息、气短、喉炎、头痛、恶心和呕吐。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3898, 4005, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n接触', '尿困难。', '无资料', '本品可燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3899, 4006, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收\n吸入、摄入或经皮肤吸收后对身体可能有害。', '睛、粘膜和上呼吸道有刺激作用。', '无资料', '本品具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3900, 4007, NULL, NULL, NULL, NULL, NULL, '侵入途径：', '吞食后有毒。跟皮肤接触有毒。可能有损伤胎儿或胚胎的危险。长期暴露有损伤健康的', NULL, '对水生物有剧毒,对水生环境可能会引起长期有害作用', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3901, 4008, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入经皮吸收\n吸入、口服或经皮肤吸收对身体有害。高浓度对眼睛、皮肤、粘膜和呼吸道有强烈刺激\n作用。中毒表现有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。有麻醉作用。', NULL, '无资料', '本品易燃，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3902, 4009, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入', NULL, NULL, '本品可燃，有毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3903, 4010, NULL, NULL, NULL, NULL, NULL, '器官毒性-重复接触，类别2；危害水生环境-急性毒性，类别1；危害水生环境-慢性毒性，', '吸入、食入、皮肤接触、眼睛接触\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3904, 4011, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收', '对皮肤有刺激作用。烟雾对眼睛、粘膜和上呼吸道有刺激作用。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3905, 4012, NULL, NULL, NULL, NULL, NULL, '特异性靶器官毒性-反复接触,类别2', '吸入、食入、皮肤接触', '长期或反复接触可能对器官造成损害，具有成瘾性', '对水生生物有害并具有长期持续影响', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3906, 4013, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '误服中毒者，症状为严重头晕、乏力、口唇及四肢麻木、瞳孔缩小、流涎、恶心、呕吐，重者出现抽搐和昏迷。误服后可以在1h后迅速死亡。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生生物有剧毒。对环境可能有危害，对水体应给予特别注意。', '不易燃烧。受高热分解，放出有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3907, 4014, NULL, NULL, NULL, NULL, NULL, '第2.3类 有毒气体', '吸入\n低浓度氨对粘膜有刺激作用，高浓度可造成组织溶解坏死。急性中毒：轻度者出现流泪、咽痛、\n声音嘶哑、咳嗽、咯痰等；眼结膜、鼻粘膜、咽部充血、水肿；胸部 X线征象符合支气管炎或\n支气管周围炎。中度中毒上述症状加剧，出现呼吸困难、紫绀；胸部 X线征象符合肺炎或间质', '性肺炎。严重者可发生中毒性肺水肿，或有呼吸窘迫综合征，患者剧烈咳嗽、咯大量粉红色泡\n沫痰、呼吸窘迫、谵妄、昏迷、休克等。可发生喉头水肿或支气管粘膜坏死脱落窒息。高浓度\n氨可引起反射性呼吸停止。液氨或高浓度氨可致眼灼伤；液氨可致皮肤灼伤。', '对环境有危害，对水体、土壤和大气可造成污染。', '本品易燃，有毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3908, 4015, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期接触可引起溶血性贫血、高铁血红蛋白血症和周围神经炎。', '该物质对环境可能有危害，对水体应给予特别注意。', '遇高热、明火或氧化剂，有引起燃烧的危险。受高热分解，放出有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3909, 4016, NULL, NULL, NULL, NULL, NULL, '易燃固体类别2；呼吸道致敏物类别1；危害水生环境-长期危害类别3', '吸入、食入、皮肤接触、眼睛接触', '有引起过敏、哮喘病症状或呼吸困难的风险。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生环境可能会引起长期有害作用。', '固体，易燃，其粉体与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3910, 4017, NULL, NULL, NULL, NULL, NULL, '遇水放出易燃气体的物质和混合物，类别2', '吸入、食入、皮肤接触、眼睛接触', '吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入本品可能引起毒害作用。本品在正常生产过程中生成的粉尘可对身体产生毒害作用。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生生物可能有害。', '遇水放出易燃气体，遇明火、高热有燃烧爆炸危险。受热分解产生有毒的氮氧化物和氨气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3911, 4018, NULL, NULL, NULL, NULL, NULL, '第4.3类 遇湿易燃物品', '吸入、食入、经皮吸收', '本品对黏膜、上呼吸道、眼睛及皮肤有强烈刺激性。吸入后，可因喉和支气管的痉挛、炎症和水肿，化学性肺炎或肺水肿而致死。中毒表现有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '遇水分解产生氨，对水生环境造成危害。', '本品遇湿易燃、具有强刺激性。遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3912, 4019, NULL, NULL, NULL, NULL, NULL, '遇水放出易燃气体的物质和混合物，类别1；皮肤腐蚀/刺激，类别1B；严重眼损伤/眼刺激，类别1B；对水生环境的危害-急性危害，类别1', '吸入、食入、经皮吸收', '本品具强烈刺激性和腐蚀性。吸入其粉尘，对呼吸道有强烈刺激性，或造成灼伤。眼及皮肤接触可致灼伤。如口服，腐蚀口腔及消化道。', '对水生生物有极大危害。', '遇水剧烈反应，放出易燃的氨气。遇明火、高热可燃。受热分解产生有毒的氨气和氧化钠。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3913, 4020, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品；皮肤腐蚀/刺激，类别2；严重眼损伤/眼刺激，类别2；危害水生环境－急性危害，类别3；危害水生环境－长期危害，类别3', '吸入、食入、经皮吸收', '对皮肤、眼睛和粘膜有强烈的刺激和腐蚀作用。吸入可引起呼吸道刺激、咳嗽、呼吸困难。食入可引起口腔、咽喉、食道和胃部灼伤，出现恶心、呕吐、腹痛等症状。长期接触可能引起皮肤过敏。', '对水生生物有害，可能对水环境造成长期不利影响。', '本品不燃，具腐蚀性、强刺激性，可致人体灼伤。受热分解产生有毒的氮氧化物和硫化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3914, 4021, NULL, NULL, NULL, NULL, NULL, '急性毒性-经口，类别4；皮肤腐蚀/刺激，类别2；严重眼损伤/眼刺激，类别2', '吸入、食入、皮肤接触、眼睛接触', '吸入有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。接触可引起头痛、恶心和呕吐。', '对水生生物有毒。', '遇明火、高热可燃。受热分解产生有毒的氮氧化物和氨气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3915, 4022, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有刺激作用。资料报道，有致畸、致突变作用。受热分解释出氮氧化物。IARC致癌性评价：2B类（可能对人类致癌）。', '该物质对环境可能有危害，对水体应给予特别注意。', '遇明火、高热可燃。受高热分解，放出有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3916, 4023, NULL, NULL, NULL, NULL, NULL, '有害', '吸入、食入、皮肤接触', '具刺激作用。目前，未见职业危害的报道。曾有报道误服本品20mg/kg 未出现中毒症状。吞咽有害。造成皮肤刺激。造成严重眼刺激。可能引起呼吸道刺激。', '对水生生物有毒作用', '可燃，其粉体与空气混合，能形成爆炸性混合物', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3917, 4024, NULL, NULL, NULL, NULL, NULL, '第8.2类 碱性腐蚀品', '吸入、食入、经皮吸收', '吸入后对鼻、喉和肺有刺激性，引起咳嗽、气短和哮喘等；重者发生喉头水肿、肺水肿及心、肝、肾损害。溅入眼内可造成灼伤。皮肤接触可致灼伤。口服灼伤消化道。慢性影响：反复低浓度接触，可引起支气管炎；可致皮炎。', '对水生生物有毒，可能对水体环境产生长期不良影响', '本品不燃，具腐蚀性、刺激性，可致人体灼伤。受热分解产生有毒的氮氧化物和氨气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3918, 4025, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入、食入、经皮吸收', '对粘膜和上呼吸道有刺激作用。对眼睛、皮肤有刺激作用。目前，未见职业性中毒报道。', '该物质对环境可能有危害，对水体应给予特别注意。', '遇明火、高热可燃。受高热分解产生有毒的腐蚀性烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3919, 4026, NULL, NULL, NULL, NULL, NULL, '第2.2类 不燃气体', '吸入', '热解能放出有毒的F烟雾。', '无资料', '本品不燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3920, 4027, NULL, NULL, NULL, NULL, NULL, '第2.2类 不燃气体', '吸入', '吸入高浓度本品气体有麻醉作用。', '对环境可能有危害，对大气臭氧层有潜在破坏作用。', '本品不燃', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3921, 4028, NULL, NULL, NULL, NULL, NULL, '第2.2类 不燃气体', '吸入', '目前，未见职业中毒的报道，但热解时能放出高毒的F-烟雾。', '无资料', '本品不燃', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3922, 4029, NULL, NULL, NULL, NULL, NULL, '第2.2类 不燃气体', '吸入、皮肤接触、眼睛接触、食入', '八氟异丁烯是一种剧毒气体，吸入后可有头晕、恶心、胸闷、咳嗽等感冒样症状，但数小时后可发生急性化学性肺炎或肺水肿，甚至发生成人呼吸窘迫综合征(ARDS)。对眼睛、皮肤和呼吸道有强烈刺激性。长期反复接触可引起慢性支气管炎、肺纤维化等慢性肺部疾病。急性毒性极高，LC50：24.54mg/m³, 1小时(大鼠吸入)；7.36mg/m³，2小时(小鼠吸入)。', '对环境可能有危害，对大气臭氧层有潜在破坏作用。对水生生物有高毒性。在环境中不易生物降解，持久存在，具有生物富集性。', '本品不燃、高毒。在贮存、运输和操作处置过程中，受热可聚合，产生意外的危害。受热分解产生氟化氢、四氟化碳等有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3923, 4030, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品；GHS分类：急性毒性-经口,类别2；急性毒性-经皮,类别1；特异性靶器官毒性-反复接触,类别2', '吸入、食入、经皮吸收', '抑制胆碱酯酶活性，引起神经功能紊乱，发生与胆碱能神经过度兴奋相似的症状。急性中毒：轻度：有头痛、头晕、恶心、呕吐、多汗、胸闷、视力模糊、无力等症状，全血胆碱酯酶活性在50～70％；中度：除上述症状外，有肌束震颤、瞳孔缩小、轻度呼吸困难、流涎、腹痛、腹泻等，全血胆碱酯酶活性在30～50％；重度：上述症状加重，可有肺水肿或昏迷或呼吸麻痹或脑水肿，全血胆碱酯酶活性在30％以下。慢性影响：可有神经衰弱综合征、腹胀、多汗、肌纤维震颤等，全血胆碱酯酶降至50％以下。', '对水生生物有毒性。可能对环境造成危害。', '遇明火、高热可燃。受热分解，放出氮、磷的氧化物等毒性气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3924, 4031, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '植物引起中毒的报告，另有儿童误服致死的报道。', '对水生生物毒性极大并具有长期持续影响，对环境有危害，对水体和大气可造成污染。', '本品可燃、高毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3925, 4032, NULL, NULL, NULL, NULL, NULL, 'GHS危险性类别：皮肤腐蚀/刺激，类别2；致癌性，类别1B；生殖毒性，类别2', '吸入、食入、皮肤接触、眼睛接触', '对皮肤有刺激性，可引起皮肤瘙痒、红肿。对眼睛有刺激性，可引起眼睛发红、疼痛。吸入可引起头痛、头晕、恶心、呕吐等症状。具有致癌性，长期接触可能致癌。具有生殖毒性，可能影响生育能力。', '对水生生物有毒性，在环境中持久存在，不易降解。被列入中国禁止或严格限制的有毒化学品名录。', '不易燃。受热分解会产生有毒的溴化氢气体和含溴有机物。在火场中，容器可能爆炸或破裂。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3926, 4033, NULL, NULL, NULL, NULL, NULL, '第4.2类自燃物品', '吸入、食入、经皮吸收', '属剧毒类。急性吸入中毒表现有呼吸道刺激症状、头痛、头晕、全身无力、呕吐、心动过缓、上腹疼痛、黄疸、肝肿大。重症出现急性肝坏死、中毒性肺水肿等。口服中毒出现口腔糜烂、急性胃肠炎，甚至发生食道、胃穿孔。数天后出现肝、肾损害。重者发生肝、肾功能衰竭等。本品可致皮肤灼伤，磷经灼伤皮肤吸收引起中毒，重者发生中毒性肝病、肾损害、急性溶血等，以致死亡。慢性中毒：神经衰弱综合征、消化功能紊乱、中毒性肝病。引起骨骼损害，尤以下颌骨显著，后期出现下颌骨坏死及齿槽萎缩。', '对环境有危害，对大气可造成污染。对水生生物有极强的毒性作用。', '本品属自燃物品，剧毒，具刺激性。接触空气易自燃，30℃即会自燃，释放出酸性烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3927, 4034, NULL, NULL, NULL, NULL, NULL, '第4.3类遇湿易燃物品', '食入\n金属钡几乎没有毒性。可溶性钡盐如氯化钡、硝酸钡等(碳酸钡遇胃酸形成氯化钡，可经\n消化道吸收)，食入后可发生严重中毒，出现消化道刺激症状、进行性肌麻痹、心肌受累、\n低血钾等。呼吸肌麻痹、心肌损害可导致死亡。吸入可溶性钡化合物的粉尘，可引起急性', '钡中毒，表现与口服中毒相仿，但消化道反应较轻。长期接触钡化合物的工人出现流涎、\n无力、气促、口腔粘膜肿胀、糜烂、鼻炎、心动过速、血压增高、脱发等。长期吸入不溶\n性钡化合物粉尘，如硫酸钡，可致钡尘肺。', '无资料', '本品遇湿易燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3928, 4035, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '高浓度苯对中枢神经系统有麻醉作用，引起急性中毒；长期接触苯对造血系统有损害，引起慢性中毒。急性中毒：轻者有头痛、头晕、恶心、呕吐、轻度兴奋、步态蹒跚等酒醉状态；严重者发生昏迷、抽搐、血压下降，以致呼吸和循环衰竭。慢性中毒：主要表现有神经衰弱综合征，造血系统改变，白细胞、血小板减少，重者出现再生障碍性贫血。苯可引起白血病。', '对水生生物有毒。对水生环境可能造成长期不利影响。', '本品易燃，为致癌物。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂能发生强烈反应。易产生和聚集静电，有燃烧爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3929, 4036, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', NULL, NULL, '本品可燃，有毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3930, 4037, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收', '具刺激作用。实验资料报道，对动物致癌。对人有致突变作用。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3931, 4038, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收', '有毒。对眼睛、皮肤和粘膜有刺激作用。受热分解释出有腐蚀性、刺激性的烟雾。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3932, 4039, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入 食入 经皮吸收', '吸入、摄入或经皮肤吸收后会中毒。具刺激作用。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3933, 4040, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入', '误服会中毒。资料报道有致突变作用。受热分解释出氮氧化物。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3934, 4041, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '吸入、摄入或经皮肤吸收后会中毒。对眼睛、粘膜有刺激作用。受热分解释出氮氧化物和\n氧化硫。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3935, 4042, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3936, 4043, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3937, 4044, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n苯酚对皮肤、粘膜有强烈的腐蚀作用，可抑制中枢神经或损害肝、肾功能。急性中毒：吸\n入高浓度蒸气可致头痛、头晕、乏力、视物模糊、肺水肿等。误服引起消化道灼伤，出现', NULL, NULL, '本品可燃，高毒，具强腐蚀性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3938, 4045, NULL, NULL, NULL, NULL, NULL, '下：皮肤腐蚀/刺激 ， 类别 1；眼损伤/眼刺激 ，类别 1。', '吸入、食入、皮肤接触、眼睛接触', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3939, 4046, NULL, NULL, NULL, NULL, NULL, '第8.3类 其它腐蚀品', '吸入 食入', NULL, '无资料', '本品可燃，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3940, 4047, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入 食入 经皮吸收\n吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤粘膜和呼吸道有强烈的破坏作用。吸入\n后可因咽喉、支气管的痉挛、水肿，化学性肺炎、肺水肿而致死。中毒表现有烧灼感、咳', '嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '无资料', '本品易燃、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3941, 4048, NULL, NULL, NULL, NULL, NULL, '无资料', '无资料\n吸入、摄入或经皮肤吸收后对身体有害。', '烧灼感、咳嗽、喘息、气短、喉炎、头痛、恶心和呕吐。', NULL, '本品不燃，有毒，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3942, 4049, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收', NULL, '无资料', '本品可燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3943, 4050, NULL, NULL, NULL, NULL, NULL, '第4.1类易燃固体', '吸入食入经皮吸收', '具有刺激性。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3944, 4051, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收', NULL, '无资料', '本品可燃，具强腐蚀性、刺激性，可致人体灼伤，具致敏性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3945, 4052, NULL, NULL, NULL, NULL, NULL, '易燃液体、皮肤腐蚀/刺激、严重眼睛损伤/眼睛刺激性', '吸入、皮肤接触、眼睛接触、食入\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '易燃液体，其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3946, 4053, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n对眼睛、粘膜、呼吸道及皮肤有强烈的刺激作用，吸入后可引起喉、支气管痉挛、水肿，', '化学性肺炎、肺水肿而致死。中毒表现有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心\n和呕吐。', '无资料', '本品易燃，剧毒，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3947, 4054, NULL, NULL, NULL, NULL, NULL, '侵入途径： 食入', '食入\n吞食后有毒。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。长期暴', NULL, '对水生物有剧毒，对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3948, 4055, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收', '蒸气对呼吸道有刺激性。皮肤或眼接触可致灼伤。口服灼伤口腔和消化道。', '无资料（建议向供应商索取或查询专业数据库）', '本品可燃，具强腐蚀性、刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3949, 4056, NULL, NULL, NULL, NULL, NULL, '根据GB30000-2013化学品分类和标签规范系列标准（参阅第十六部分），该产品分类如下：', '吸入、食入、皮肤接触、\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3950, 4057, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收\n吸入、摄入或经皮肤吸收后对身体有害。', '起烧灼感、咳嗽、喘息、气短、头痛、恶心和呕吐。', '无资料', '本品可燃、具有强腐蚀性、强刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3951, 4058, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n有因衣服沾染了', '性。皮肤较长时间接触有刺激作用。动物吸入蒸气或小剂量灌胃，主要为麻醉作用。大剂\n量引起痉挛。', NULL, '本品可燃，有毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3952, 4059, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入经皮吸收', '本品具有刺激性。未见急性中毒报道。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3953, 4060, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '高毒。误服或吸入会中毒，受热分解释出有毒的汞蒸气。', '无资料', '本品可燃、高毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3954, 4061, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', NULL, '无资料', '本品可燃，有毒，具刺激性，具致敏性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3955, 4062, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收\n对眼睛、皮肤、粘膜和呼吸道有强烈的刺激作用。吸入可因喉、支气管的痉挛、水肿、炎症，\n化学性肺炎、肺水肿而致死。中毒表现有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕', '吐。', '无资料', '本品可燃，有毒，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3956, 4063, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', NULL, NULL, '本品可燃，有毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3957, 4064, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入\n极低的浓度可刺激人的眼、鼻、咽的粘膜。在30mg／m3下1分钟以上人即不能耐受，可致头', NULL, '无资料', '本品可燃、有毒、强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3958, 4065, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '肿胀、丘疹和水疱。长时间接触可引起坏死。口服可致死。', NULL, '本品可燃，高毒，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3959, 4066, NULL, NULL, NULL, NULL, NULL, '根据GB30000-2013化学品分类和标签规范系列标准（参阅第十六部分），该产品分类如下：', '吸入、食入、皮肤接触、眼睛接触\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3960, 4067, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n急性中毒可出现恶心、呕吐、腹痛、腹泻等胃肠炎症状，重者可引起休克、肾功能损害。\n神经系统损害的表现有头痛、头昏、口周围麻木、全身酸痛等。砷中毒3日至3周出现急性', NULL, '无资料', '本品不燃、剧毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3961, 4068, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收\n急性中毒可出现恶心、呕吐、腹痛、腹泻等胃肠炎症状，重者可引起休克、肾功能损害。\n神经系统损害的表现有头痛、头昏、口周围麻木、全身酸痛等。砷中毒3日至3周出现急性', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3962, 4069, NULL, NULL, NULL, NULL, NULL, '急毒性-口服，类别3；急毒性-吸入，类别3；危害水生环境-急性毒性，类别1；危害水生', '食入、眼睛及皮肤接触\n食入后产生吞咽困难、腹痛、呕吐、腹泻、脱水、干渴、痛性痉挛、头昏、说胡话、僵木、', '心跳过速、头痛、昏迷、肾损伤，重者致死。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3963, 4070, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '本品对粘膜、上呼吸道、眼睛和皮肤有刺激性。', '无资料', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3964, 4071, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入', '本品对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', NULL, '本品可燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3965, 4072, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '对眼睛有刺激性，可引起皮肤和粘膜充血、疼痛、呼吸急促、头痛、头晕等。', '无资料', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3966, 4073, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '毒作用与氢氰酸相似，并有局部刺激作用。吸入后出现头痛、头晕、恶心、呕吐、倦睡、上呼吸道刺激、神志丧失等，可引起死亡。对眼和皮肤有刺激性。可经皮肤迅速吸收。口服可有消化道刺激症状。', '对水生生物有毒害作用，可能对水体环境造成长期不良影响。', '本品可燃，高毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3967, 4074, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收对身体有害。其蒸气或雾对眼睛、粘膜和呼吸道有刺激作用。中毒表现有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '对水生生物有毒。对水生环境可能造成长期不利影响。', '本品易燃，具刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂能发生强烈反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3968, 4075, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入 食入 经皮吸收\n对眼和上呼吸道粘膜有刺激和麻醉作用。急性中毒：高浓度时，立即引起眼及上呼吸道粘\n膜的刺激，出现眼痛、流泪、流涕、喷嚏、咽痛、咳嗽等，继之头痛、头晕、恶心、呕吐、', '全身乏力等；严重者可有眩晕、步态蹒跚。眼部受苯乙烯液体污染时，可致灼伤。慢性影\n响：常见神经衰弱综合征，有头痛、乏力、恶心、食欲减退、腹胀、忧郁、健忘、指颤等。\n对呼吸道有刺激作用，长期接触有时引起阻塞性肺部病变。皮肤粗糙、皲裂和增厚。', NULL, '本品易燃，为可疑致癌物，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3969, 4076, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收', NULL, '无资料', '本品可燃，有毒，具腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3970, 4077, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收', '本品是局部麻醉药。全身毒性低，但有轻度致敏作用。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3971, 4078, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入、食入、经皮吸收', '有强烈刺激性；能麻醉中枢神经系统。对眼及上呼吸道有刺激作用。高浓度吸入后，轻者有欣快或窒息感，继之出现抑郁、肌无力、呕吐；重者意识丧失、大小便失禁、强直性痉挛、血压下降等。', '无资料', '本品易燃、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3972, 4079, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收对身体有害，其蒸气或烟雾对眼睛、粘膜和呼吸道有刺激作用，反复接触可引起中枢神经系统抑制。', '对环境有危害，对水体可造成污染。', '本品易燃、具有刺激性。遇明火、高热易燃。与氧化剂能发生强烈反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3973, 4080, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n吸入、摄入或经皮肤吸收对身体有害，对眼睛、粘膜、呼吸道及皮肤有强烈刺激作用。吸入后', '可能因喉、支气管的炎症、痉挛、水肿，化学性肺炎、肺水肿而致死。中毒表现有烧灼感、咳\n嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '无资料', '本品易燃、有毒、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3974, 4081, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n蒸气或雾对眼、粘膜和上呼吸道有刺激性。接触后可引起烧灼感、咳嗽、喘息、喉炎、气短、', '头痛、恶心和呕吐。', NULL, '本品易燃，有毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3975, 4082, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3976, 4083, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入、食入、经皮吸收', '动物中毒表现以中枢神经系统抑制为主，可致眼、呼吸道刺激和肾损害。对眼睛有刺激性，可引起结膜刺激和暂时性角膜混浊。对皮肤有刺激性。吸入可引起呼吸道刺激、头痛、头晕、恶心、乏力等症状。高浓度接触可引起麻醉作用。', '无资料', '本品易燃、刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3977, 4084, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '本品毒性似氰化物。氰化物的特异作用为抑制细胞呼吸，造成组织缺氧。大鼠皮下注射近\n致死量的本品，出现呼吸困难、紫绀和抽搐，尿中硫氰酸盐排出量增加。', NULL, '本品可燃，高毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3978, 4085, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤、粘膜和上呼吸道有刺激作用。吸入后可引起喉炎、化学性肺炎、肺水肿等。接触后的症状：烧灼感、咳嗽、眩晕、气短、头痛、恶心和呕吐等。', '对水生生物有害。', '受高热分解，放出刺激性烟气。粉体与空气可形成爆炸性混合物，当达到一定的浓度时，遇火星会发生爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3979, 4086, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '铊化合物属高毒类。可经呼吸道、消化道和皮肤吸收。急性中毒：表现为胃肠道症状，随后出现神经系统症状，如感觉异常、无力、脱发、周围神经病变等。慢性中毒：主要表现为多发性神经炎、脱发、指甲出现白色横纹（米氏线）、视力减退、肝肾功能损害等。对眼睛、皮肤、粘膜有刺激性。', '对水生生物有极高毒性。铊及其化合物在环境中具有持久性，可在生物体内富集，对生态系统造成长期危害。严禁未经处理直接排放到环境中。', '本品可燃、高毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3980, 4087, NULL, NULL, NULL, NULL, NULL, '第2.1类；易燃气体', '吸入', '有单纯窒息、麻醉和刺激作用。吸入后引起头痛、头晕、倦睡、流涎、呕吐、神志不清。可因缺氧而窒息死亡。眼和皮肤接触液态本品，可致冻伤。', NULL, '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3981, 4088, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜有强刺激性，可引起皮肤灼伤。吸入后可引起喉炎、化学性肺炎、肺水肿等。接触后的症状：烧灼感、咳嗽、眩晕、气短、头痛、恶心和呕吐等。遇水分解释出有刺激性和腐蚀性的氯化氢烟雾。', '无资料', '本品易燃、有毒、具有强腐蚀性、刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3982, 4089, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。遇水或水蒸气放出有刺激性和腐蚀性的氯化氢气体。接触后，可引起头痛、咳嗽、喉炎、气短、恶心、呕吐等症状。', '无资料', '本品易燃、有毒、具有腐蚀性、强刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3983, 4090, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '食入；吸入', '吸入、食入有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。砷化合物具有致癌性。', '对水生物有剧毒，对水生环境可能会引起长期有害作用', '遇明火、高热可燃。受热分解产生有毒的砷氧化物烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3984, 4091, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入经皮吸收', '加快、头痛、头晕、胸闷；呼吸困难期：血压上升、脉速、心悸、皮肤呈鲜红色、胸部\n压迫感、呼吸困难、紫绀、昏迷等；麻痹期：持续昏迷、全身肌肉松驰、呼吸心跳停止\n而死亡。眼和皮肤接触可致灼伤，吸收后可引起中毒。', '无资料', '本品易燃，剧毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3985, 4092, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入经皮吸收\n低浓度接触对眼、鼻有刺激性。高浓度接触有麻醉作用，以及引起支气管炎、肺炎、肺水', '肿。可致眼、皮肤灼伤。易经完整皮肤吸收。', NULL, '本品极度易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3986, 4093, NULL, NULL, NULL, NULL, NULL, '第2.1类 易燃气体', '吸入', '急性吸入可刺激呼吸道，引起支气管炎及肺炎；并有麻醉作用。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3987, 4094, NULL, NULL, NULL, NULL, NULL, '易燃气体，类别1；高压气体，压缩气体；特定目标器官毒性-单次接触：麻醉效应，类别3。', '吸入、皮肤及眼睛接触', '激动、失去方向性，昏昏欲睡，冻疮。刺激眼睛、皮肤和呼吸道，接触液体可致冻伤。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3988, 4095, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收', '水肿，化学性肺炎或肺水肿而致死。接触后出现烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶\n心和呕吐。', '无资料', '本品腐蚀性、刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3989, 4096, NULL, NULL, NULL, NULL, NULL, '第8，1类 酸性腐蚀品。', '吸入 食入 经皮吸收\n吸入', NULL, NULL, '本品易燃，具腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3990, 4097, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3991, 4098, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收', '大鼠吸入本品饱和蒸气，１小时后死亡。其蒸气对眼睛、皮肤有明显的刺激作用。', NULL, '本品易燃，具腐蚀性、刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3992, 4099, NULL, NULL, NULL, NULL, NULL, '第3，2类中闪点易燃液体。', '吸入食入经皮吸收', '具有刺激性，接触时间过长有麻醉作用。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3993, 4100, NULL, NULL, NULL, NULL, NULL, '易燃液体，类别2。', '吸入、食入、皮肤接触、眼睛接触\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3994, 4101, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收', '人，吸入0.4g／m3 1分钟，能引起呼吸道刺激症状。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3995, 4102, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入经皮吸收\n高浓度蒸气有刺激性，引起眼、鼻、咽喉刺痛，可有恶心、呕吐。此外可发生头昏、倦\n睡、共济失调以及昏迷。眼及皮肤直接接触有刺激性。口服有中等毒性，引起恶心、呕', '吐、腹部不适、腹泻、头昏、倦睡、共济失调、昏迷。长期反复接触对皮肤有脱脂作用，\n引起皮肤皲裂、角化。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3996, 4103, NULL, NULL, NULL, NULL, NULL, '易燃液体，类别2。', '吸入、食入、皮肤接触、眼睛接触', '吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入该物质可能会对健康有害。皮肤接触可能会引起皮肤刺激或过敏。眼睛接触可能会引起眼睛刺激或损伤。', '该物质对水生生物有害。', '易燃液体和蒸气。其蒸气与空气混合，能形成爆炸性混合物。遇明火、高热极易燃烧爆炸。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3997, 4104, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入', '高浓度时有麻醉作用，具有中等程度刺激性。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3998, 4105, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入经皮吸收', '在高浓度下有麻醉性，有中等程度刺激性。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (3999, 4106, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入\n在工业生产中未发现对人的危害。给动物致死量时发生皮毛粗糙、共济失调、气急、呼吸', '困难、抽搐和体温降低。', '无资料', '本品易燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4000, 4107, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '在工业生产中未发现对人的危害。给动物致死剂量时发生皮毛粗糙、共济失调、气急、呼吸困难、抽搐和体温降低等表现。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '无资料', '本品易燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4001, 4108, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, '易燃,其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4002, 4109, NULL, NULL, NULL, NULL, NULL, '第3.1类低闪点易燃液体', '吸入食入经皮吸收\n急性中毒主要表现为对中枢神经系统的麻醉作用，出现乏力、恶心、头痛、头晕、易激\n动。重者发生呕吐、气急、痉挛，甚至昏迷。对眼、鼻、喉有刺激性。口服后，先有口', '唇、咽喉有烧灼感，后出现口干、呕吐、昏迷、酸中毒和酮症。慢性影响：长期接触该\n品出现眩晕、灼烧感、咽炎、支气管炎、乏力、易激动等。皮肤长期反复接触可致皮炎。', '无资料', '本品极度易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4003, 4110, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收\n急性属低毒类，慢性毒作用有：严重的神经系统损害，生殖细胞损害，皮炎等。', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4004, 4111, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '退，严重者可致死，可引起皮炎。', '无资料', '本品易燃、高毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4005, 4112, NULL, NULL, NULL, NULL, NULL, '第2.1类 易燃气体', '吸入', '度头晕；接触高浓度时可出现麻醉状态、意识丧失；极高浓度时可致窒息。', '无资料', '本品易燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4006, 4113, NULL, NULL, NULL, NULL, NULL, '第2.1类 易燃气体', '吸入', '吐。慢性影响：长期接触可引起头昏、乏力、全身不适、思维不集中。个别人胃肠道功能发生\n紊乱。', NULL, '本品易燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4007, 4114, NULL, NULL, NULL, NULL, NULL, '第3.1类低闪点易燃液体', '吸入食入经皮吸收', NULL, NULL, '本品极度易燃，高毒，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4008, 4115, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收', '本品对皮肤、眼睛和呼吸道有强烈刺激作用。', '无资料', '本品易燃，具腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4009, 4116, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。接触后可引起烧灼感、咳嗽、喘息、气短、头痛、恶心和呕吐等。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期接触可引起皮肤过敏。', '对水生生物有毒性，对水生环境可能会引起长期有害作用', '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。受热分解产生有毒的烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4010, 4117, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, '易燃,其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4011, 4118, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入经皮吸收\n高浓度接触，引起流涎、眼及呼吸道的刺激症状，严重者口唇发白、呼吸困难、痉挛，', NULL, '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4012, 4119, NULL, NULL, NULL, NULL, NULL, '侵入途径：', '吞食后有毒。跟皮肤接触有毒。会引起皮肤烧伤，有严重损害眼睛的危险。跟皮肤接触可', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4013, 4120, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入经皮吸收\n对呼吸道有刺激性，高浓度吸入引起肺水肿。有麻醉作用。眼直接接触可致灼伤。对皮肤', '有明显的刺激和致敏作用。口服强烈刺激口腔及消化道，可出现头晕、呼吸困难、神经过\n敏。', '无资料', '本品易燃，具刺激性，具致敏性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4014, 4121, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入经皮吸收\n吸入、口服或经皮肤吸收对身体有害。其蒸气或雾对眼睛、粘膜和呼吸道有刺激作用。中毒', '表现有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4015, 4122, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入经皮吸收\n吸入、口服或经皮肤吸收对身体有害。其蒸气或雾对眼睛、粘膜和呼吸道有刺激作用。中', '毒表现有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4016, 4123, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '现四肢麻木，感觉异常，腱反射减弱或消失，抽搐，瘫痪等。重度中毒出现以小脑病变为\n主的中毒性脑病。出现震颤、步态反紊乱、共济失调，甚至大小便失禁或小便潴留。皮肤\n接触本品，可发生粗糙、角化、脱屑。本品中毒主要因皮肤吸收引起。', '无资料', '本品可燃，有毒，为可疑致癌物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4017, 4124, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入、食入有毒。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。吸入可引起喉炎、支气管炎、肺炎、肺水肿，严重者可因喉头水肿窒息而死亡。误服可引起消化道灼伤。', '对水生物有剧毒，对水生环境可能会引起长期有害作用', '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。受热分解产生有毒的氯化物、光气等烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4018, 4125, NULL, NULL, NULL, NULL, NULL, '第3.2类 ，中闪点易燃液体', '吸入 食入 经皮吸收\n急性中毒极少见。眼内溅入，能引起角膜损害。对上呼吸道有刺激作用。吸入中毒症状有：', '胸闷、下肢无力、上肢麻木，怕冷、倦怠、恶心、喉干等。', '无资料', '本品易燃、剧毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4019, 4126, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收', '对眼睛和皮肤可能有刺激作用。吸入有轻度毒性。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4020, 4127, NULL, NULL, NULL, NULL, NULL, '第3，2类 中闪点易燃液体', '吸入 食入 经皮吸收', '本品蒸气对呼吸道和眼有强烈的刺激性，吸入后引起咳嗽、呼吸困难。可致皮肤灼伤。', '无资料', '本品易燃、有毒、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4021, 4128, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4022, 4129, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收', '生尿毒症。可在体内与钙离子结合而发生低血钙。长期吸入蒸气引起神经衰弱综合征、头痛、\n呕吐、鼻粘膜溃疡、尿中出现蛋白、贫血等。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4023, 4130, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, '对水生物有毒，对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4024, 4131, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, '对水生物有毒，对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4025, 4132, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, '跟可燃物质接触容易引起火灾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4026, 4133, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, '跟可燃物质接触容易引起火灾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4027, 4134, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、皮肤接触、眼睛接触', '腐蚀物能引起呼吸道刺激，伴有咳嗽、呼吸道阻塞和粘膜损伤。吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入本品可能对个体健康有害。皮肤直接接触造成严重皮肤灼伤。通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。眼睛直接接触本品能造成严重化学灼伤。如果未得到及时、适当的治疗，可能造成永久性失明。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '跟可燃物质接触可能会引起火灾。受热或接触火焰可能会产生膨胀或爆炸性分解。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4028, 4135, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、皮肤接触、眼睛接触', '可加剧燃烧，氧化剂，吞咽有害，造成严重的皮肤灼伤和眼损伤。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激性。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品助燃，具刺激性。受热、遇酸或日光照射会分解放出剧毒的氯气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4029, 4136, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、皮肤接触、眼睛接触', '腐蚀物能引起呼吸道刺激，伴有咳嗽、呼吸道阻塞和粘膜损伤。吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入本品可能对个体健康有害。皮肤直接接触造成严重皮肤灼伤。通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。眼睛直接接触本品能造成严重化学灼伤。如果未得到及时、适当的治疗，可能造成永久性失明。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '跟可燃物质接触可能会引起火灾。受热或接触火焰可能会产生膨胀或爆炸性分解。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4030, 4137, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、皮肤接触、眼睛接触', '腐蚀物能引起呼吸道刺激，伴有咳嗽、呼吸道阻塞和粘膜损伤。吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入本品可能对个体健康有害。皮肤直接接触造成严重皮肤灼伤。通过割伤、擦伤或病变处进入血液，可能产生全身损伤的有害作用。眼睛直接接触本品能造成严重化学灼伤。如果未得到及时、适当的治疗，可能造成永久性失明。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '跟可燃物质接触可能会引起火灾。受热或接触火焰可能会产生膨胀或爆炸性分解。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4031, 4138, NULL, NULL, NULL, NULL, NULL, '第8.3类其它腐蚀品', '吸入、食入、皮肤接触、眼睛接触', '具有腐蚀性，可致人体灼伤，具致敏性。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激性。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品不燃，具腐蚀性，可致人体灼伤，具致敏性。受高热分解产生有毒的腐蚀性烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4032, 4139, NULL, NULL, NULL, NULL, NULL, '侵入途径：', '吞食后有毒。对眼睛有严重刺激性。对呼吸道有刺激作用。可能有损伤胎儿或胚胎的危险。', NULL, '对水生物有剧毒，对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4033, 4140, NULL, NULL, NULL, NULL, NULL, '第4.2类自热物质，具有第4.3类遇水反应的次要危险性；GHS分类：急性毒性-经口（类别5）、急性毒性-吸入（类别4）、皮肤过敏（类别1）', '吸入、食入、皮肤接触、眼睛接触', '对皮肤和粘膜有刺激作用，接触后可发生皮炎、发痒、皮疹、红肿等。长期接触可能引起神经系统损害。具有致敏性，可引起皮肤过敏反应。', '对水生生物有毒，可能对水生环境造成长期不利影响。', '本品属自热物质，在空气中发热并自燃。受热分解，放出氮、硫的氧化物等毒性气体。具有刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4034, 4141, NULL, NULL, NULL, NULL, NULL, '有机过氧化物，B型。', '皮肤接触、眼睛接触、吸入、食入\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4035, 4142, NULL, NULL, NULL, NULL, NULL, '第2.2类不燃气体', '吸入', '空气中氮气含量过高，使吸入气氧分压下降，引起缺氧窒息。吸入氮气浓度不太高时，患者最初感胸闷、气短、疲软无力；继而有烦躁不安、极度兴奋、乱跑、叫喊、神情恍惚、步态不稳，可能出现进入昏迷状态。如果吸入浓度很高，可迅速昏迷、因呼吸和心跳停止而死亡。', '该物质对环境无危害。', '本品不燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4036, 4143, NULL, NULL, NULL, NULL, NULL, '第4.3类 遇湿易燃物品', '吸入、食入、经皮吸收', '遇水或潮气产生有刺激性、腐蚀性的氨毒气。对眼睛、粘膜和呼吸系统有腐蚀性和毒性。皮肤接触可引起灼伤。', '对环境有害。遇水分解产生的氨气对水体和大气可造成污染。', '遇水剧烈反应，产生高度易燃的氨气。遇湿易燃，有毒，具腐蚀性，可致人体灼伤。受高热分解，放出有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4037, 4144, NULL, NULL, NULL, NULL, NULL, '第4.3类 遇湿易燃物品', '吸入、食入、皮肤接触、眼睛接触', '对皮肤有刺激性。对眼睛有严重刺激性。对呼吸道有刺激作用。遇水或潮气产生有刺激性、腐蚀性的氨毒气。', '无资料', '高度易燃，其粉体与空气混合，能形成爆炸性混合物。遇湿易燃、有毒、具有腐蚀性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4038, 4145, NULL, NULL, NULL, NULL, NULL, '第2.1类易燃气体', '吸入', '在高浓度下可引起窒息。应使患者移到通风地方，安置休息并保暖。如发生冻伤，须就医诊治。', '对环境无特殊危害。', '本品易燃。与氟、氯、溴等卤素会剧烈反应。高浓度时有窒息作用。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4039, 4146, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '食入', '暴露可引起恶心、呕吐、头痛、疲劳、虚弱、昏昏欲睡、腹部不适、视力障碍（模糊、色象差、晕轮）、情绪失调、精神错乱、定向力障碍、失语症、说胡话、幻觉、痉挛。', '该物质对水生生物有毒。避免释放到环境中。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4040, 4147, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有刺激性。接触后可出现头痛、头晕、恶心、呕吐等症状。皮肤接触可引起刺激、红肿、疼痛。眼睛接触可导致严重眼部损伤。食入可引起恶心、呕吐、腹痛。高剂量接触可引起幻视、口唇紫绀、胸闷、谵语、抽搐、意识模糊、甚至昏迷。', '该物质对环境可能有危害，对水体应给予特别注意。避免排放到周围环境中。', '遇明火、高热可燃。受热分解，放出有毒烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4041, 4148, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '高毒性。对眼、皮肤、粘膜和上呼吸道有刺激性。吸入、摄入或经皮肤吸收后对身体有害。接触后可出现头痛、头晕、恶心、呕吐等症状。皮肤接触可引起刺激、红肿、疼痛。眼睛接触可导致严重眼部损伤。食入可引起恶心、呕吐、腹痛、胃肠功能紊乱。接触者可发生皮炎、鼻粘膜出血、指甲改变和延迟伤口愈合。本品对人的致死量约6～12g。中毒途径包括皮肤接触、吸入、误食等，可导致消化道黏膜烧灼、肝肾衰竭、中枢神经损伤及多器官功能衰竭。', '对水生生物有毒性。该物质对环境可能有危害，对水体应给予特别注意。避免排放到周围环境中。', '不易燃烧。受高热分解，放出有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4042, 4149, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '低毒。对眼、皮肤、粘膜和上呼吸道有刺激性。吸入、摄入或经皮肤吸收后对身体有害。接触后可出现头痛、头晕、恶心、呕吐等症状。皮肤接触可引起刺激、红肿、疼痛。眼睛接触可导致严重眼部损伤。食入可引起恶心、呕吐、腹痛。浓度高时刺激眼及粘膜。', '对水生生物有毒性。该物质对环境可能有危害，对水体应给予特别注意。避免排放到周围环境中。', '遇明火、高热可燃。受高热分解，放出有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4043, 4150, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '中等毒杀菌剂。对皮肤有致敏性，吸入对呼吸道有刺激性。对眼、皮肤、粘膜和上呼吸道有刺激性。接触后可出现头痛、头晕、恶心、呕吐等症状。皮肤接触可引起刺激、红肿、疼痛、过敏反应。眼睛接触可导致严重眼部损伤。食入可引起恶心、呕吐、腹痛。长期或反复接触可能对肝脏、肾脏和神经系统造成损害。', '对水生生物有毒性。该物质对环境可能有危害，对水体应给予特别注意。避免排放到周围环境中。', '不易燃烧。受高热分解，放出有毒的烟气。加热时，容器可能爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4044, 4151, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '中等毒性。对眼、皮肤、粘膜和上呼吸道有刺激性。吸入、摄入或经皮肤吸收后对身体有害。接触后可出现头痛、头晕、恶心、呕吐等症状。皮肤接触可引起刺激、红肿、疼痛。眼睛接触可导致严重眼部损伤。食入可引起恶心、呕吐、腹痛。动物中毒表现为萎靡，嗜睡，严重者有抽搐或昏迷。对人的致死量估计为2克。', '该物质对环境可能有危害，对水体应给予特别注意。避免排放到周围环境中。', '遇明火、高热可燃。受热分解，放出氮、硫的氧化物等毒性气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4045, 4152, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入\n碲可与血浆中的蛋白和含巯基的酶结合。其毒性与砷、硒相似，但毒性比砷、硒低。大量吸入，\n可刺激上呼吸道发生炎症；严重者发生化学性肺炎。患者呼气有蒜臭味。慢性中毒：长期接触', '低浓度碲，可有口干、呼气蒜臭味、恶心、食欲不振、无汗、皮肤干燥发痒、便秘，嗜睡、无\n力等表现。', '无资料', '本品可燃，高毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4046, 4153, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, '对水生物有剧毒,对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4047, 4154, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n高毒。吸入、摄入或经皮肤吸收后会中毒。吸入时，神经系统最早受损；误服，首先出现', NULL, '无资料', '本品不燃、高毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4048, 4155, NULL, NULL, NULL, NULL, NULL, '高压气体，压缩气体；皮肤腐蚀/刺激，类别1A；眼损伤/眼刺激，类别1；特定目标器官毒', '皮肤接触、眼睛接触、吸入、食入\n吸入蒸气(尤其是长期接触)可能引起呼吸道刺激，偶尔出现呼吸窘迫。腐蚀物能引起呼吸道\n刺激，伴有咳嗽、呼吸道阻塞和粘膜损伤。吸入该物质可能会引起对健康有害的影响或呼吸\n道不适。意外食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4049, 4156, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, '对水生物有剧毒,对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4050, 4157, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', NULL, '无资料', '本品不燃，剧毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4051, 4158, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入', '使支气管发生坏疸。遇水或水蒸气产生有毒或腐蚀性的烟雾。', '无资料', '本品可燃、具有强腐蚀性、刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4052, 4159, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入食入经皮吸收', NULL, '无资料', '本品可燃，有毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4053, 4160, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入食入经皮吸收', '对眼、粘膜、皮肤和上呼吸道有刺激性。', '无资料', '本品助燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4054, 4161, NULL, NULL, NULL, NULL, NULL, '氧化性固体，类别2。', '皮肤接触、眼睛接触、吸入、食入\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4055, 4162, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入食入经皮吸收\n急性中毒时，出现流涎、呕吐、腹痛、激烈腹泻、痉挛、震颤、血压升高、肠胃及肾脏内', '出血等。对皮肤有刺激性。', '无资料', '本品助燃，剧毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4056, 4163, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入食入', '本品有毒，对眼睛、皮肤、粘膜有强刺激作用。', '无资料', '本品助燃，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4057, 4164, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '无资料\n粉尘对呼吸系统有刺激作用。误服能产生流涎、窒息、呕吐、腹痛、腹泻等症状。经常接', NULL, '无资料', '本品助燃，高毒，具腐蚀性、刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4058, 4165, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入食入经皮吸收\n对上呼吸道、眼及皮肤有刺激性。口服引起头痛、恶心、呕吐、眩晕及胃肠道刺激。可致', NULL, '无资料', '本品助燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4059, 4166, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入食入', '本品有毒,具腐蚀性。', '无资料', '本品助燃，具强腐蚀性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4060, 4167, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '无资料', '本品有毒。对皮肤、粘膜有刺激作用。', '无资料', '本品助燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4061, 4168, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, '跟可燃物质接触可能会引起火灾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4062, 4169, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入食入经皮吸收', '对眼睛、上呼吸道、粘膜和皮肤有刺激性。', '无资料', '本品助燃，具腐蚀性、刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4063, 4170, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '无资料\n铅及其化合物损害造血、神经、消化系统及肾脏。职业中毒主要为慢性。神经系统主要表\n现为神经衰弱综合征、周围神经病(以运动功能受累较明显)，重者出现铅中毒性脑病。消', NULL, '无资料', '本品助燃，高毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4064, 4171, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '无资料', '本品有毒。对皮肤、粘膜有刺激作用。', '无资料', '本品助燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4065, 4172, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '无资料', '本品有毒。对皮肤、粘膜有刺激作用。', '无资料', '本品助燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4066, 4173, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '无资料', '本品有毒。对皮肤、粘膜有刺激作用。', '无资料', '本品助燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4067, 4174, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '无资料\n眼接触有刺激性。长期接触银化合物，吸入或食入，可发生皮肤、眼、呼吸道全身性银质', '沉着症。皮肤色素沉着呈灰黑色或浅石板色。', '无资料', '本品助燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4068, 4175, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收', '心、呕吐。', '无资料', '本品可燃，具腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4069, 4176, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入 食入 经皮吸收', '碘乙酸乙酯，可引起肺水肿而死亡。', '无资料', '本品易燃、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4070, 4177, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', NULL, '无资料', '本品可燃，有毒，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4071, 4178, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入', '热解时，放出有毒的Nox烟雾，对眼睛、上呼吸道有刺激作用，甚至发生肺水肿。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4072, 4179, NULL, NULL, NULL, NULL, NULL, '第1类爆炸品', '吸入、食入、经皮吸收', '高毒。对皮肤和粘膜有刺激性。吸收进入体内，可影响神经系统、心脏和肾脏，重者可引起惊厥和死亡。吸入可影响肺功能。钡化合物可引起钡中毒，表现为肌肉无力、心律失常、呼吸肌麻痹等。', '对水生生物有极高毒性。可能对环境造成长期危害。', '受热、接触明火、高热或受到摩擦震动、撞击时可发生爆炸。遇酸产生剧毒、易燃的叠氮酸。干燥状态下极不稳定，极易爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4073, 4180, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '可引起眼睛、皮肤的刺激症状。如吸入、摄入或经皮肤吸收，可致死。急性中毒表现：眩晕、虚弱无力、视觉模糊、呼吸困难、昏厥、血压降低、心动过缓等。慢性作用：动物实验显示，叠氮化钠产生低血压作用，使中枢神经的神经纤维脱鞘、睾丸损伤、失明、大脑皮层受损等。', '对水生生物有极高毒性。对水生生物可能造成长期不利影响。', '本品不燃、剧毒、具有爆炸性、刺激性。受热、接触明火、高热或受到摩擦震动、撞击时可发生爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4074, 4181, NULL, NULL, NULL, NULL, NULL, '第1.1类爆炸品', '吸入、食入、皮肤接触、眼睛接触', '有剧毒。经口、吸入或经皮肤吸收可引起中毒。对中枢神经系统、血液系统、肾脏和肝脏有损害。可引起铅中毒，表现为贫血、腹痛、神经系统症状等。受热分解放出高毒的氮氧化物和铅。', '对水生生物有剧毒。对环境有危害，特别是对水体和土壤可造成污染。', '干燥时，接触明火、高热或受到摩擦震动、撞击时可发生爆炸。含水或乙醇≥20%时相对稳定，但仍为爆炸品。遇火、受热、摩擦、撞击有燃烧爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4075, 4182, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮接触', '动物实验示有麻醉作用，可致肝、肾损害，对眼有中度刺激性，对皮肤有轻度刺激性。高浓度蒸气可引起头痛、头晕、恶心等症状。', '对水生生物可能有害。避免该物质进入水体。', '易燃。其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂接触发生剧烈反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4076, 4183, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮接触', '引起动物嗜睡，出现刺激症状，可引起肺、肝、肾损害。液体滴入兔眼内，引起眼损害。未见人体慢性中毒报告。高浓度蒸气可引起头痛、头晕、恶心等症状。', '对水生生物可能有害。避免该物质进入水体。', '易燃。其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂接触发生剧烈反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4077, 4184, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。本品动物实验小剂量引起中枢神经系统兴奋，大剂量引起抑制，致死剂量引起抽搐、窒息。在大鼠和兔体内本品约有60％转化为氰化物。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '丁二腈对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境有危害，应特别注意对水体的污染。在水生生物中可能发生生物蓄积。', '本品可燃，有毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4078, 4185, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮接触', '本品的水溶液对眼睛、皮肤有较强刺激作用。因其蒸气压较低，故吸入中毒的危险性减少。吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对环境有危害，对水体可造成污染。', '易燃。遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4079, 4186, NULL, NULL, NULL, NULL, NULL, '第2.1类易燃气体', '吸入、皮肤接触、眼睛接触', '本品属不饱和脂肪烃类，具有单纯窒息和麻醉作用。高浓度吸入可引起头痛、头晕、乏力、恶心、呕吐，甚至意识丧失。', '对环境有危害，对水体可造成污染。', '高度易燃，与空气混合能形成爆炸性混合物，遇明火、高热极易燃烧爆炸。在2～20kPa大气压下可发生爆炸性分解。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4080, 4187, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。大剂量口服可引起非特异性呕吐和腹泻。对眼睛、皮肤、粘膜有一定的刺激作用。在工业上使用未见职业中毒报道。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '丁二酸对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品可燃，具刺激性。粉体与空气可形成爆炸性混合物，当达到一定的浓度时，遇火星会发生爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4081, 4188, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点液体', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜有刺激作用。目前，未见工业中毒的报道。高浓度蒸气可能引起头痛、头晕、恶心等症状。', '对水生生物可能有害。应避免进入水体、土壤和地下水。', '遇明火、高热可燃。受热分解产生有毒气体。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4082, 4189, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点液体', '吸入、食入、经皮吸收', '经口，无高度毒性，对皮肤和眼睛亦无特殊刺激作用。未见职业中毒报道。高浓度蒸气可能引起头痛、头晕、恶心等症状。', '对水生生物可能有害。应避免进入水体、土壤和地下水。', '遇明火、高热可燃。受热分解产生有毒气体。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4083, 4190, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入、食入、经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和呼吸道有强烈的刺激作用。吸入后可因喉、支气管的痉挛、水肿、炎症，化学性肺炎、肺水肿而致死。中毒表现有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。具强腐蚀性、强刺激性，可致人体灼伤。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '丁二酰氯对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境有危害，应特别注意对水体的污染。遇水分解生成腐蚀性物质。', '本品可燃，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4084, 4191, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤、粘膜和上呼吸道有刺激性。当高浓度的热蒸气及烟雾吸入时，感到头晕、目眩、头痛。经消化道进入时，除上述症状外，尚有恶心、呕吐、腹泻等症状。', '无资料', '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4085, 4192, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入、食入、皮肤接触、眼睛接触', '在生产环境中，本品蒸气对人没有危险，未见其对人有损害的报道。', '无资料', '本品可燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4086, 4193, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入\n未稀释的', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4087, 4194, NULL, NULL, NULL, NULL, NULL, '第4.2类自燃物品', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。可引起化学灼伤。吸入后，可因喉、支气管的炎症、痉挛、水肿，化学性肺炎、肺水肿而致死。中毒表现有烧灼感、咳嗽、喘息、气短、喉炎、头痛、恶心和呕吐，可引起神经系统的紊乱。', '对环境有危害，对水体可造成污染。', '本品易燃，具强刺激性。遇水、潮湿空气剧烈反应，放出氢气和热量，可引起燃烧或爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4088, 4195, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入、食入、经皮吸收', '具腐蚀性的毒物。对皮肤、眼睛和粘膜有腐蚀性。遇热分解释出高毒的烟雾。吸入可引起呼吸道刺激，严重者可发生化学性肺炎。误服可引起消化道灼伤，严重者可出现休克。长期接触可引起慢性影响。', '对环境有危害，对水体可造成污染。', '遇明火、高热可燃。受热分解，放出有毒的烟气。具有强腐蚀性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4089, 4196, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、经皮接触', '本品具有强烈的腐蚀性和刺激性。吸入、摄入或经皮肤吸收后对身体有害。蒸气或烟雾对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用，可引起灼伤。遇潮气分解产生氯化氢，对呼吸道有严重刺激作用。', '对环境有危害，对水体可造成污染。', '易燃。遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。受热分解产生有毒的氯化氢和氯气烟雾。遇潮气分解产生氯化氢，对大多数金属有腐蚀性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4090, 4197, NULL, NULL, NULL, NULL, NULL, '第3类易燃液体', '吸入、食入、皮肤接触、眼睛接触', '本品对人的粘膜和皮肤无刺激作用。在生产环境中的蒸气实际上没有危险。属微毒类。', '对水生生物可能有轻微危害', '遇明火、高热可燃。与氧化剂可发生反应。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4091, 4198, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入 食入', '吸入、食入或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激性。吸入后可引起头痛、头晕、恶心、呕吐、咳嗽、胸闷等症状。高浓度接触可引起肺水肿。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4092, 4199, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤和粘膜有强烈的刺激作用。吸入后，可引起喉、支气管痉挛、炎症，化学性肺炎、肺水肿。接触后可引起烧灼感、咳', '该物质对环境有危害，应特别注意对水体的污染。', '本品可燃，具腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4093, 4200, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入 食入 经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '无资料', '本品易燃、刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4094, 4201, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入经皮吸收\n危害：在工业生产中未发现对人的危害。给动物致死量时发生皮毛粗造、共济失调、气急、', '呼吸困难、抽搐和体温降低。', '无资料', '本品易燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4095, 4202, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入、食入、经皮吸收', '具腐蚀性。对眼睛、皮肤、粘膜有强刺激性，可引起皮肤灼伤。遇水分解释出有刺激性和腐蚀性的氯化物烟雾。吸入可引起呼吸道刺激，严重者可发生化学性肺炎。误服可引起消化道灼伤，严重者可出现休克。', '对环境有危害，对水体可造成污染。', '本品可燃，具有腐蚀性和强刺激性，可致人体灼伤。受热分解，放出高毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4096, 4203, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。吸入后可引起喉、支气管的痉挛、炎症、水肿、化学性肺炎，肺水肿。接触后可引起烧灼感、咳嗽、喉炎、气短、头痛、恶心和呕吐等。', '对环境有危害，对水体可造成污染。', '遇明火、高热可燃。受热分解产生有毒气体。与氧化剂能发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4097, 4204, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。蒸气或雾对眼、粘膜和上呼吸道有刺激性。对皮肤有刺激性。接触后表现有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '对环境有危害，对水体可造成污染。', '易燃，其蒸气与空气形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4098, 4205, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。蒸气具有刺激性，能强烈刺激眼睛。误服可引起中毒，出现虚脱、呼吸困难、中枢神经兴奋等症状。', '对环境有危害，对水体可造成污染。', '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4099, 4206, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。高浓度吸入可引起头痛、头晕、恶心、呕吐、嗜睡等症状，严重者可致昏迷。', '对环境有危害，对水体可造成污染。', '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4100, 4207, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。接触后可引起烧灼感、咳嗽、喉炎、气短、头痛、恶心和呕吐等。', '对环境有危害，对水体可造成污染。', '遇明火、高热可燃。受热分解产生有毒气体。与氧化剂能发生强烈反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4101, 4208, NULL, NULL, NULL, NULL, NULL, '第3类 易燃液体', '吸入 食入 经皮吸收', '吸入、食入、经皮吸收可引起中毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。高浓度接触可引起头痛、头晕、恶心、呕吐、乏力等症状。长期接触可引起慢性中毒。', '对水生生物有毒，对水生环境可能会引起长期有害作用。', '遇明火、高热可燃。受热分解产生有毒气体。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4102, 4209, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '心脏病症，伴随血清中钾过多，症状包括：错乱、昏迷、呕吐、惊厥、呼吸困难。对眼睛、皮肤、粘膜和呼吸道有刺激作用。', '对环境有危害，应特别注意对水体的污染。', '受热或接触火焰可能会产生膨胀或爆炸性分解。遇明火、高热有引起燃烧爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4103, 4210, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '心脏病症，伴随血清中钾过多，症状包括：错乱、昏迷、呕吐、惊厥、呼吸困难。对眼睛、皮肤、粘膜和呼吸道有刺激作用。', '对环境有危害，应特别注意对水体的污染。', '受热或接触火焰可能会产生爆炸性分解。遇明火、高热有引起燃烧爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4104, 4211, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后会中毒。对眼睛、皮肤和粘膜有刺激作用。中毒症状可能包括恶心、呕吐、腹痛、头晕、头痛等。', '对水生生物有毒性，可能对水体产生长期不良影响。', '遇明火、高热可燃。受高热分解，放出有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4105, 4212, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吞食后有剧毒。对眼睛、皮肤、粘膜和上呼吸道有刺激性。接触后可出现头痛、头晕、恶心、呕吐、腹痛、腹泻等症状。重度中毒者可出现抽搐、昏迷、呼吸麻痹。', '该物质对环境可能有危害，对水体应给予特别注意。避免排放到周围环境中。', '受热分解产生有毒的烟气。遇明火、高热可燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4106, 4213, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入、食入或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期接触可引起肝、肾损害。有轻微致癌性风险。', '对水生生物有剧毒。对环境可能有危害，对水体应给予特别注意。', '遇明火、高热可燃。受热分解产生有毒的氯化氢烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4107, 4214, NULL, NULL, NULL, NULL, NULL, '第8类腐蚀性物质', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。可引起皮肤灼伤。误服可引起消化道损伤。', '对水生生物可能有毒性。', '受热分解，放出氮、硫的氧化物等毒性气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4108, 4215, NULL, NULL, NULL, NULL, NULL, '非危险化学品', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有刺激作用，未见职业中毒的报道。属低毒类。皮肤接触可能有害。', '对环境有危害，对水体和大气可造成污染。', '本品可燃，具刺激性。遇明火、高热可燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4109, 4216, NULL, NULL, NULL, NULL, NULL, '第8类腐蚀性物质', '吸入、食入、经皮吸收', '本品对粘膜、上呼吸道、眼和皮肤有强烈的刺激性。吸入后，可因喉及支气管的痉挛、炎症、水肿，化学性肺炎或肺水肿而致死。造成严重的皮肤灼伤和眼损伤。能引起灼伤。', '对水生生物可能有毒性。该物质对环境有危害，应特别注意对水体的污染。', '本品可燃，具强腐蚀性、强刺激性，可致人体灼伤。遇水产生刺激性气体。遇水发生剧烈化学反应。具有腐蚀性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4110, 4217, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点液体', '吸入、食入、经皮吸收', '本品对眼睛和上呼吸道粘膜具有一定的刺激作用。高浓度蒸气可能引起头痛、头晕、恶心等不适症状。长期接触可能对皮肤和眼睛造成刺激。', '对水生生物可能有毒性，应避免排放到环境中。', '遇高热、明火或与氧化剂接触，有引起燃烧的危险。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4111, 4218, NULL, NULL, NULL, NULL, NULL, '第8类腐蚀性物质', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有刺激作用。高浓度蒸气可能引起头痛、头晕、恶心等不适症状。长期接触可能对皮肤和眼睛造成刺激。', '对水生生物可能有毒性，应避免排放到环境中。', '遇明火、高热可燃。受高热分解产生有毒的硫化物烟气。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4112, 4219, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点液体', '吸入、食入、经皮吸收', '本品对眼睛、皮肤、粘膜和上呼吸道有刺激作用。高浓度蒸气可能引起头痛、头晕、恶心等不适症状。长期接触可能对皮肤和眼睛造成刺激。', '对水生生物可能有毒性，应避免排放到环境中。', '遇高热、明火或与氧化剂接触，有引起燃烧的危险。受高热分解，放出腐蚀性、刺激性的烟雾。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4113, 4220, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点液体', '吸入、食入、经皮吸收', '本品对眼睛、皮肤和上呼吸道粘膜有刺激性。高浓度蒸气可能引起头痛、头晕、恶心等不适症状。长期接触可能对皮肤和眼睛造成刺激。', '对水生生物可能有毒性，应避免排放到环境中。', '遇高热、明火或与氧化剂接触，有引起燃烧的危险。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4114, 4221, NULL, NULL, NULL, NULL, NULL, '第8类腐蚀性物质', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用。可引起皮肤灼伤。吸入其粉尘或蒸气可能导致呼吸道刺激，长期接触可能对肺部造成损伤。误服可引起消化道损伤。症状包括：刺激、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '对水生生物可能有毒性。', '受高热分解产生有毒的硫化物烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4115, 4222, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有刺激作用。对皮肤有致敏作用。高浓度的蒸气可能引起头痛、恶心、呕吐等症状。', '对水生生物可能有毒性。', '受高热分解产生有毒的硫化物烟气。遇明火、高热可燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4116, 4223, NULL, NULL, NULL, NULL, NULL, '第8类腐蚀性物质', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。可引起皮肤灼伤。误服可引起消化道损伤。', '对水生生物可能有毒性。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4117, 4224, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '属低毒类。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。误服可引起消化道损伤。', '对水生生物可能有毒性。', '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4118, 4225, NULL, NULL, NULL, NULL, NULL, '第3类易燃液体', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收本品后对身体可能有害，具有刺激性。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生生物可能有毒性。', '遇高热、明火或与氧化剂接触，有引起燃烧的危险。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4119, 4226, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '本品蒸气有恶臭，对眼睛和上呼吸道有刺激性。急性中毒是由于其解离产生的氰化物所致，后者抑制呼吸酶，造成组织缺氧。对皮肤有刺激性，可引起小丘疹、发痒。', '对水生生物可能有毒性。', '本品可燃，有毒，具刺激性。遇明火能燃烧。接触酸和酸雾产生剧毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4120, 4227, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。可引起皮肤灼伤。误服可引起消化道损伤。吸入该物质可能会引起对健康有害的影响或呼吸道不适。具刺激性恶臭。', '对水生生物有毒性。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4121, 4228, NULL, NULL, NULL, NULL, NULL, '有机过氧化物，类别C型；皮肤腐蚀/刺激，类别2；严重眼损伤/眼刺激，类别1；特异性靶器官毒性-单次接触，类别3', '吸入、食入、皮肤接触、眼睛接触', '液体。会引起皮肤烧伤，有严重损害眼睛的危险。吸入蒸气或雾对呼吸道有强烈刺激性。眼直接接触液体可致不可逆损伤甚至失明。口服中毒出现腹痛、胸口痛、呼吸困难、呕吐、腹泻等症状。长期暴露可能对皮肤和眼睛造成慢性损害。', '对水生生物有毒性。对环境有危害，应避免进入水体。', '遇热有火灾危险。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。与还原剂、酸类、碱类、金属粉末等接触可能发生剧烈反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4122, 4229, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '腐蚀物能引起呼吸道刺激，伴有咳嗽、呼吸道阻塞和粘膜损伤。吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入有害。造成严重皮肤灼伤和眼损伤。具有生殖毒性，可能对生育能力或胎儿造成损害。', '对水生生物毒性极大。对水生生物毒性极大并具有长期持续影响。', '受热或接触火焰可能会产生膨胀或爆炸性分解。遇明火、高热可燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4123, 4230, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '本品可燃，具腐蚀性、刺激性。对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用，可引起皮肤灼伤。误服可引起消化道损伤。长期接触可能对肝脏、肾脏和血液系统造成损害。能经皮肤和呼吸道吸收，可引起高铁血红蛋白血症。', '对水生生物可能有毒性。', '受热或接触火焰可能会产生膨胀或爆炸性分解。受热分解产生有毒的氧化氮烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4124, 4231, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤、粘膜和上呼吸道有刺激作用。误服可引起消化道损伤。长期接触可能对肝脏、肾脏和血液系统造成损害。可能引起高铁血红蛋白血症。', '对水生生物可能有毒性。', '受热或接触火焰可能会产生膨胀或爆炸性分解。受热分解产生有毒的氧化氮烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4125, 4232, NULL, NULL, NULL, NULL, NULL, '第8类腐蚀性物质', '吸入、食入、皮肤接触、眼睛接触', '腐蚀物能引起呼吸道刺激，伴有咳嗽、呼吸道阻塞和粘膜损伤。吸入该物质可能会引起对健康有害的影响或呼吸道不适。对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用，可引起皮肤灼伤。误服可引起消化道损伤。', '对水生生物可能有毒性。', '受热或接触火焰可能会产生膨胀或爆炸性分解。受热分解产生有毒的氧化氮烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4126, 4233, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '对皮肤有刺激性。对眼睛有严重刺激性。对呼吸道有刺激作用。加热时可能产生有毒烟雾。', '对水生生物可能有毒性。', '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4127, 4234, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入或经皮肤吸收本品可引起中毒。能引起高铁血红蛋白血症，贫血。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生生物有毒性，对环境有危害，应特别注意对水体的污染。', '遇明火、高热可燃。受高热分解产生有毒的腐蚀性烟气。与强氧化剂接触可发生化学反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4128, 4235, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入', '本品受高热分解放出有毒气体，对人体有刺激作用和毒性。', '无资料', '本品可燃，有毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4129, 4236, NULL, NULL, NULL, NULL, NULL, '第8类腐蚀性物质', '吸入、食入、经皮吸收', '本品对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用。长时间接触可造成眼的损伤，灼伤。造成严重的皮肤灼伤和眼损伤。', '对水生生物可能有毒性，应避免排放到环境中。', '本品可燃、具有腐蚀性、强刺激性、可致人体灼伤。遇明火、高热能燃烧，并产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4130, 4237, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '粉尘能刺激眼睛、皮肤和呼吸道。吸入和口服可致死亡。吸入可引起咳嗽、胸痛、呼吸困难、口中金属味和精神症状，对肝、肾有损害。长期接触可能引起慢性中毒，表现为消化系统、神经系统症状。', '对水生生物有毒性，可能在环境中持久存在。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4131, 4238, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '多硫化铵溶液具有强烈的刺激性气味，对眼睛、皮肤、粘膜和上呼吸道有严重的刺激作用。吸入可引起咳嗽、呼吸困难、胸闷等症状。食入可引起恶心、呕吐、腹痛、腹泻等症状。皮肤接触可引起红肿、瘙痒、灼伤。眼睛接触可引起疼痛、红肿、流泪、视力模糊。长期或反复接触可引起慢性呼吸道疾病、皮肤过敏等。', '对水生生物有剧毒。对水环境有极严重的危害。', '遇明火、高热可燃。受热分解产生硫化氢、氨气、二氧化硫等有毒气体。与氧化剂接触可能发生剧烈反应或爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4132, 4239, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '多氯联苯具有极高的毒性，对人类健康造成严重危害。急性毒性：经口摄入可引起严重的全身中毒症状，包括恶心、呕吐、腹痛、腹泻、头痛、头晕、乏力等。长期或反复接触可导致：1）致癌性：国际癌症研究机构（IARC）将多氯联苯列为1类致癌物，可导致多种癌症，包括肝癌、肺癌、恶性黑色素瘤等；2）生殖毒性：可影响生殖系统功能，导致生育能力下降、流产、胎儿发育异常、新生儿体重降低等；3）内分泌干扰：作为内分泌干扰物，可干扰甲状腺激素、性激素等内分泌系统的正常功能；4）免疫系统毒性：可抑制免疫系统功能，降低机体对感染和疾病的抵抗力；5）皮肤毒性：可引起氯痤疮、皮肤色素沉着、多毛症等皮肤病变；6）神经系统毒性：可引起头痛、头晕、乏力、感觉异常、周围神经病变等症状。眼睛接触可引起严重的眼部刺激和损伤。皮肤接触可引起皮肤刺激、过敏和全身吸收中毒。', '多氯联苯对环境具有极严重的危害性。持久性：在环境中具有极强的持久性，难以通过自然降解过程分解，可在环境中存在数十年甚至更长时间。生物富集性：具有极强的生物富集能力，可在生物体内逐级放大，在食物链顶端生物（如人类、大型食肉动物）体内的浓度可比环境浓度高出数百万倍。远距离迁移：可通过大气、水体等介质进行远距离迁移，在远离污染源的地区也能检测到其存在。生态毒性：对水生生物、陆生生物和鸟类具有极高的毒性，可导致种群数量下降、生态系统结构破坏、生物多样性减少。土壤污染：可在土壤中长期残留，污染农作物和地下水，对农业生产和人类健康造成长期威胁。已被《斯德哥尔摩公约》列为全球禁止或严格限制生产和使用的持久性有机污染物。', '多氯联苯可燃，遇明火、高热可燃。受热分解温度约为500-700℃，分解产生的烟雾和气体具有极强的毒性和腐蚀性。在火灾情况下，多氯联苯可能通过挥发、烟雾传播等方式扩散到周围环境中，造成严重的环境污染和人员中毒。火灾现场的温度和压力可能加速多氯联苯的分解和扩散，增加其危害性。此外，多氯联苯在高温下可能与其他物质发生反应，生成新的有毒物质。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4133, 4240, NULL, NULL, NULL, NULL, NULL, '特定目标器官毒性-重复接触，类别2；危害水生环境-急性毒性，类别1；危害水生环境-慢性毒性，类别1', '吸入、食入、皮肤接触、眼睛接触', '吸入、食入或经皮肤吸收可引起中毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期接触可引起神经系统、肝脏、皮肤损害。多氯三联苯具有生物蓄积性，可在人体内长期存在。', '对水生生物有极高毒性，可能在水生环境中造成长期不利影响。具有持久性、生物蓄积性和毒性（PBT）。在环境中难以降解，可通过食物链富集。', '遇明火、高热可燃。受热分解产生有毒的氯化氢气体和光气。燃烧时产生大量浓烟。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4134, 4241, NULL, NULL, NULL, NULL, NULL, '第4.1类易燃固体', '吸入食入', '本品对眼睛、皮肤、粘膜和上呼吸道有刺激性。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4135, 4242, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, '遇热有火灾危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4136, 4243, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, '遇热有火灾或爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4137, 4244, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收', '对人可引起眼和呼吸道急性刺激及痊愈很慢的皮肤灼伤。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4138, 4245, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, '遇热有火灾或爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4139, 4246, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收', '对人体有毒。对眼睛、皮肤、粘膜有刺激作用，可损伤角膜。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4140, 4247, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4141, 4248, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '遇热有火灾危险', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4142, 4249, NULL, NULL, NULL, NULL, NULL, '有机过氧化物，F型。', '吸入、食入、皮肤接触、眼睛接触\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4143, 4250, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, '对水生物有毒，对水生环境可能会引起长期有害作用。', '遇热有火灾危险', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4144, 4251, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入食入\n对眼、皮肤和粘膜有强烈的刺激作用。当浓度为470mg/m3时1～2分钟接触即可引起致死性', NULL, '无资料', '本品易燃，有毒，为致癌物，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4145, 4252, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4146, 4253, NULL, NULL, NULL, NULL, NULL, '第5.2类 有机过氧化物', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤、粘膜和上呼吸道有刺激作用。吸入可引起呼吸道刺激。长期或反复接触可能引起皮肤过敏。', '对水生生物可能有害。', '遇明火、高热可燃。受热分解产生有毒气体。与还原剂、促进剂、有机物、可燃物等反应剧烈，有燃烧爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4147, 4254, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, '在空气中容易发生自热反应,有引发火灾的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4148, 4255, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收\n接触者可有头痛，头昏，恶心、呕吐、腹泻、消瘦等症状。长期接触后皮肤粘膜出现刺激现象，', '也可引起膀胱癌，出现尿频或血尿等症状。', '无资料', '本品可燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4149, 4256, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有毒。吸入有毒', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4150, 4257, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收', '吸入本品蒸气对呼吸道有强烈刺激性。皮肤或眼接触可致灼伤。口服灼伤口腔和消化道。', '无资料', '本品腐蚀性、刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4151, 4258, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', NULL, '无资料', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4152, 4259, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', NULL, '无资料', '本品有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4153, 4260, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入\n较大量吸入，能引起头痛、眼痛、咳嗽、呼吸困难等。严重者可发生支气管炎和弥漫性肺', '炎，对粘膜有强烈刺激作用，有致敏作用，有报道可发生支气管哮喘。', '无资料', '本品可燃、有毒、强刺激性、致敏性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4154, 4261, NULL, NULL, NULL, NULL, NULL, '类别1；特定目标器官毒性-单次接触：呼吸道刺激，类别3；致癌性，类别2；特定目标器官', '食入、吸入、皮肤接触、眼睛接触\n吸入粉尘或烟雾(尤其是长期接触)可能引起呼吸道刺激，偶尔出现呼吸窘迫。吸入粉尘或烟\n雾可能导致过敏、哮喘病症状或呼吸困难。吸入该物质可能会引起对健康有害的影响或呼吸\n道不适。意外食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4155, 4262, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '本品的刺激性和毒性都很强，吸入可引起头痛、恶心、呕吐及呼吸障碍等。', '无资料', '本品可燃、高毒、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4156, 4263, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, '在空气中容易自身燃烧,有引发火灾的危险。会跟水激烈反应, 生成高度易燃的气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4157, 4264, NULL, NULL, NULL, NULL, NULL, '第8.3类 其它腐蚀品', '吸入 食入 经皮吸收', '气管炎、化学性肺炎、肺水肿等。', '无资料', '本品可燃、有毒、具有腐蚀性，可致人体灼伤、具有催泪性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4158, 4265, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4159, 4266, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收\n多年观察表明，除难闻的气味外，未见对人有明显的危害，但其不适气味使人感到恶心。有资', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4160, 4267, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4161, 4268, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入', '皮肤刺激性小。对人无不良作用。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4162, 4269, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入经皮吸收', NULL, '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4163, 4270, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有毒。吸入有毒。', '对水生物有剧毒,对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4164, 4271, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', NULL, NULL, '本品不燃，高毒，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4165, 4272, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '高浓度时有麻醉和刺激作用。大鼠腹腔注射血中产生碳氧血红蛋白。', NULL, '本品可燃，有毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4166, 4273, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收\n急性中毒时主要表现为中枢神经系统症状，有头痛、头晕、乏力、精神萎靡、恶心等。长', '期慢性接触可引起神经衰弱综合征。对皮肤可致接触性皮炎和过敏性皮炎。', '无资料', '本品可燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4167, 4274, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收\n对眼睛、皮肤和粘膜有刺激作用，并可灼伤皮肤。中毒表现有头晕、剧烈的头痛、失眠、', '记忆力减退、乏力、多汗等神经衰弱综合征，重症者可出现中毒性脑病。', '无资料', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4168, 4275, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '对眼睛和皮肤有刺激作用，高浓度时有强烈刺激作用。中毒症状有剧烈头痛、恶心、呕吐、嗜睡，甚至昏迷。', '对水生生物有毒性，可能对水生环境造成长期不良影响。', '本品可燃、高毒、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4169, 4276, NULL, NULL, NULL, NULL, NULL, '氧化性气体，类别1；高压气体，压缩气体；皮肤腐蚀/刺激，类别1；眼损伤/眼刺激，类', '吸入、食入、皮肤接触、眼睛接触\n在正常生产处理过程中，吸入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4170, 4277, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, '极端易燃,有爆炸危险。高压，遇热有爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4171, 4278, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入 食入 经皮吸收', '本品为腐蚀性刺激物，误服或皮肤吸收会中毒。', '无资料', '本品不燃、有毒、具有腐蚀性、刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4172, 4279, NULL, NULL, NULL, NULL, NULL, '第3.1类 低闪点易燃液体', '吸入 食入', '充血、疼痛等症状，并能去皮脂。', '无资料', '本品极度易燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4173, 4280, NULL, NULL, NULL, NULL, NULL, '第8.2类 碱性腐蚀品', '吸入 食入 经皮吸收', NULL, NULL, '本品可燃，具腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4174, 4281, NULL, NULL, NULL, NULL, NULL, '第2.1类 易燃气体', '吸入 食入 经皮吸收', '伤、混浊。', '无资料', '本品易燃，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4175, 4282, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。二甲苯对皮肤、粘膜有刺激作用，对中枢神经系统有麻醉作用。急性中毒：短期内吸入较高浓度本品可出现眼及上呼吸道明显的刺激症状、眼结膜及咽充血、头晕、头痛、恶心、呕吐、胸闷、四肢无力、意识模糊、步态蹒跚。重者可有躁动、抽搐或昏迷。有的有癔病样发作。慢性影响：长期接触有神经衰弱综合征，女工有月经异常，工人常发生皮肤干燥、皲裂、皮炎。对皮肤有刺激性。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '二甲苯异构体混合物对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。挥发后可参与形成光化学烟雾。对水生物有毒。', '本品易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与强氧化剂接触可发生反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4176, 4283, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有剧毒。跟皮肤接触有剧毒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4177, 4284, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收\n对眼睛、粘膜、呼吸道和皮肤有强烈刺激作用。吸入后，可因喉、支气管的痉挛、炎症、水肿，', '化学性肺炎、肺水肿而致死。中毒表现有咳嗽、喘息、气短、喉炎、头痛、恶心和呕吐。', '无资料', '本品腐蚀性、强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4178, 4285, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入.经皮吸收\n动物中毒表现为无力、步态不稳、呼吸急促、最后昏迷。对皮肤略有刺激，但无致敏作用。对', '兔眼的刺激并不严重。接触时应注意皮肤的防护，防止经皮吸收。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4179, 4286, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '破坏血液携氧能力，引起头痛、头昏、恶心，导致皮肤、嘴唇发紫；高浓度暴露导致呼吸困难、虚脱，甚至死亡；高浓度重复暴露，损伤肝功能。对眼睛、皮肤、粘膜有刺激性。', '对水生生物有极高毒性，可能在水生环境中造成长期不利影响。', '遇明火、高热可燃。受热分解产生有毒的氮氧化物烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4180, 4287, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, '易燃,其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4181, 4288, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入经皮吸收\n对呼吸道和眼睛、皮肤粘膜有强烈的刺激作用。吸入后可有喉、支气管的痉挛、水肿、', '炎症，化学性肺炎、肺水肿而致死。接触本品的工人可有眼痛、流泪、咳嗽、头痛、恶心、\n呕吐、喘息、易激动、皮肤发痒等症状。', '无资料', '本品易燃，具腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4182, 4289, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入经皮吸收\n吸入、口服或经皮肤吸收对身体有害。蒸气或雾对眼、粘膜和上呼吸道有刺激性。对皮肤', '有刺激性。长时间接触引起恶心、头晕、头痛和胃肠功能紊乱。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4183, 4290, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、食入、经皮吸收后对眼睛、皮肤、粘膜和上呼吸道有刺激作用。高浓度蒸气对中枢神经系统有麻醉作用。', '对水生生物有毒性，可能对水体环境造成不利影响。', '本品易燃、具有刺激性。遇明火、高热有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4184, 4291, NULL, NULL, NULL, NULL, NULL, '第4.2类自燃物品', '吸入 食入 经皮吸收\n对粘膜有刺激作用。未见工业上镁中毒的病例报告。误服后，可引起上腹痛、呕吐、腹泻、', '烦渴、呼吸困难等。', '无资料', '本品属自燃物品，有毒，具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4185, 4292, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '对人有毒。可致癌。有刺激作用。据报道，有致畸作用。砷化合物可引起慢性中毒，表现为皮肤色素沉着、掌跖角化、周围神经病变等。', '对水生生物有极高毒性，可能在水生环境中造成长期不利影响。', '本品不燃、有毒、具有刺激性。受热分解产生有毒的砷化合物烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4186, 4293, NULL, NULL, NULL, NULL, NULL, '第4.2类自燃物品', '吸入、食入、经皮吸收', '有毒。受热分解放出有毒的氧化锌烟雾。对眼睛、皮肤、粘膜有强烈刺激性。', '对水生生物有极高毒性，可能在水生环境中造成长期不利影响。', '暴露在空气中能自燃。遇水、酸类、氧化剂发生剧烈反应，有燃烧爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4187, 4294, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入 食入 经皮吸收', '具有刺激性。接触后可引起恶心、头痛和呕吐。', '无资料', '本品易燃、刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4188, 4295, NULL, NULL, NULL, NULL, NULL, '第2.1类 易燃气体', '吸入', '对中枢神经系统有抑制作用，麻醉作用弱。吸入后可引起麻醉、窒息感。对皮肤有刺激性。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4189, 4296, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收', '本品为低毒除草剂。对眼睛和皮肤具刺激作用。有致突变作用，为可疑致癌物。', '无资料', '本品可燃、有毒，具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4190, 4297, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '对眼睛、皮肤有刺激作用。吸入、摄入或经皮肤吸收后可能致死。', '无资料', '本品剧毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4191, 4298, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入', '有毒。吸入后呼出气有大蒜气味。可引起头痛、头晕、恶心、呕吐等症状。小鼠惊厥，可在几小时内死亡。对眼睛、皮肤、粘膜有刺激性。', '对水生生物有极高毒性，可能在水生环境中造成长期不利影响。', '遇高热、明火或与氧化剂接触，有引起燃烧的危险。受热分解放出有毒的氧化硒烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4192, 4299, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收\n吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。可引', '起肺和皮肤的过敏反应。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4193, 4300, NULL, NULL, NULL, NULL, NULL, '第3.1类低闪点易燃液体', '吸入食入经皮吸收', NULL, '无资料', '本品极度易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4194, 4301, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有剧毒。吸入有剧毒。', '对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4195, 4302, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入 食入 经皮吸收', '本品有毒。其蒸气和烟雾对皮肤、眼睛和粘膜有刺激作用。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4196, 4303, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入 食入 经皮吸收\n接触高浓度', NULL, '无资料', '本品易燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4197, 4304, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入', '对眼睛有强烈刺激作用，摄入有毒。', '无资料', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4198, 4305, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入 食入', '触后可引起头痛、恶心和呕吐。', '无资料', '本品易燃、高毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4199, 4306, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, '在空气中容易发生自热反应,有引发火灾的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4200, 4307, NULL, NULL, NULL, NULL, NULL, '第3.1类低闪点易燃液体', '吸入食入经皮吸收\n二硫化碳是损害神经和血管的毒物。急性中毒：轻度中毒有头晕、头痛、眼及鼻粘膜刺激\n症状；中度中毒尚有酒醉表现；重度中毒可呈短时间的兴奋状态，继之出现谵妄、昏迷、\n意识丧失，伴有强直性及阵挛性抽搐。可因呼吸中枢麻痹而死亡。严重中毒后可遗留神衰', '吸入、食入或经皮肤吸收后对身体有害。二硫化碳是损害神经和血管的毒物。急性中毒：轻度中毒有头晕、头痛、眼及鼻粘膜刺激症状；中度中毒尚有酒醉表现；重度中毒可呈短时间的兴奋状态，继之出现谵妄、昏迷、意识丧失，伴有强直性及阵挛性抽搐。可因呼吸中枢麻痹而死亡。严重中毒后可遗留神衰综合征，中枢和周围神经永久性损害。慢性中毒：表现有神经衰弱综合征，植物神经功能紊乱，周围神经病，中毒性脑病，视网膜微动脉瘤，动脉硬化性视网膜病变。血液中二硫化碳增高，但测定血和尿中的二硫化碳及其代谢物（2-硫代噻唑烷-4-羧酸TTCA）可作为接触指标。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '二硫化碳对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对植物应给予特别注意。在水生生物中可能发生生物蓄积。', '本品极度易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4201, 4308, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '本品对眼睛、皮肤、粘膜有强烈刺激作用，误服可引起中毒。', '无资料', '本品不燃、高毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4202, 4309, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有毒。跟皮肤接触有毒。吸入有毒。', '对水生物有毒，对水生环境可能会引起长期有害作用', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4203, 4310, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收', NULL, '无资料', '本品可燃、有毒、具有腐蚀性、刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4204, 4311, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收', '本品对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4205, 4312, NULL, NULL, NULL, NULL, NULL, '第2.2类 不燃气体', '吸入\n是一种对心脏毒作用强烈而又迅速的物质。能引起动物心律不齐、室性心动过速、心动过缓、', '房室传导阻滞、急性心力衰竭、血压降低等心血管系统的改变。国外有大量吸入引起致命性心\n律紊乱、虚脱、心动骤停而死亡的病例报道。', NULL, '本品不燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4206, 4313, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入', '动物实验有麻醉作用。热解或遇水、水蒸气能放出有毒、有腐蚀性的氯烟雾。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4207, 4314, NULL, NULL, NULL, NULL, NULL, '第2.3类 有毒气体', '吸入\n对上下呼吸道、皮肤和眼睛有腐蚀性和刺激性。', '（盐酸）。盐酸可致皮肤灼伤和粘膜刺激。接触后表现有流泪、咳嗽、咳痰、呼吸困难、流涎\n等。可引起肺炎或肺水肿。眼接触可致灼伤，导致失明。', '无资料', '本品易燃，有毒，具腐蚀性、刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4208, 4315, NULL, NULL, NULL, NULL, NULL, '第8.3类 其它腐蚀品', '吸入 食入', '有毒。误服或吸入会中毒。有腐蚀性，对皮肤、眼睛和粘膜有刺激性。', '无资料', '本品可燃、有毒、具有刺激性、腐蚀性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4209, 4316, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收', '对眼和上呼吸道粘膜有强烈的刺激性，少数严重者可引起肺水肿。可致皮肤严重灼伤。', '无资料', '本品不燃，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4210, 4317, NULL, NULL, NULL, NULL, NULL, '第4.2类自燃物品', '吸入 食入 经皮吸收\n吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。', '接触后的症状有烧灼感，咳嗽，喉炎、气短、头痛、恶心和呕吐等。能灼伤皮肤。', '无资料', '本品属自燃物品，具有强腐蚀性、强刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4211, 4318, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。可引起化学性支气管炎。重者昏迷，可有肺水肿。血中碳氧血红蛋白含量增高。慢性影响：长期接触主要有头痛、乏力、眩晕、食欲减退、动作迟钝、嗜睡等。对皮肤有脱脂作用，引起干燥、脱屑和皲裂等。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '二氯甲烷对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，应特别注意对大气的污染。在水生生物中可能发生生物蓄积。', '本品可燃，有毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4212, 4319, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '头痛、恶心和呕吐等。', '无资料', '本品可燃、有毒、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4213, 4320, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收', '有腐蚀性，对皮肤有严重的刺激性，对眼睛、粘膜有刺激性。', '无资料', '本品可燃，具腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4214, 4321, NULL, NULL, NULL, NULL, NULL, '第2.2类 不燃气体', '吸入', '未见急性中毒病例报道。但可引起皮肤冻伤。', NULL, '本品不燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4215, 4322, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4216, 4323, NULL, NULL, NULL, NULL, NULL, '第2.2类 不燃气体', '吸入\n有迅速的窒息作用。高浓度吸入可引起定向障碍、恶心、呕吐、麻醉作用、心律紊乱、低血', '压，甚至死亡。', '该物质对大气臭氧层破坏力极强。', '本品不燃，具窒息性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4217, 4324, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '大鼠经口给予本品，出现嗜眠、昏迷和呼吸抑制。', '无资料', '本品有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4218, 4325, NULL, NULL, NULL, NULL, NULL, '第8.3类 其它腐蚀品', '吸入 食入 经皮吸收', '本品具有刺激性。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4219, 4326, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4220, 4327, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收', NULL, '无资料', '本品可燃，具腐蚀性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4221, 4328, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '头痛、恶心和呕吐。', '无资料', '本品易燃，有毒，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4222, 4329, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '对眼睛有严重刺激性。对呼吸道有刺激作用。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4223, 4330, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收\n吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用，可引起\n灼伤。吸入后能引起喉、支气管的炎症、水肿、痉挛、化学性肺炎、肺水肿，接触后可引', '起烧灼感、咳嗽、喘息、气短、头痛、恶心和呕吐等。', '无资料', '本品可燃、强腐蚀性、刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4224, 4331, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入', NULL, '无资料', '本品有毒、刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4225, 4332, NULL, NULL, NULL, NULL, NULL, '第5.1类 氧化剂', '吸入 食入 经皮吸收\n粉尘能强烈刺激眼睛、皮肤和呼吸系统。对胃肠道有刺激作用。遇热释放出氯气和一氧化', '碳。', '无资料', '本品助燃、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4226, 4333, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n人，经口的MLD为50mg／kg。', '一般有机磷农药。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4227, 4334, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收\n吸入、摄入或经皮肤吸收后可能对身体有害。对眼睛、皮肤、粘膜和上呼吸道具有刺激作', '用。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4228, 4335, NULL, NULL, NULL, NULL, NULL, '有机过氧化物，F型。', '吸入、食入、皮肤接触、眼睛接触\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4229, 4336, NULL, NULL, NULL, NULL, NULL, '第5.2类 有机过氧化物', '吸入 食入 经皮吸收', NULL, '无资料', '本品具有爆炸性、易燃、强刺激性、可疑致癌物', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4230, 4337, NULL, NULL, NULL, NULL, NULL, '有机过氧化物，D型。', '吸入、食入、皮肤接触、眼睛接触\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4231, 4338, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, '遇热有火灾危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4232, 4339, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4233, 4340, NULL, NULL, NULL, NULL, NULL, '易燃液体，类别3。', '吸入、食入、经皮吸收', '本品对眼睛、皮肤、粘膜和上呼吸道有刺激作用，高浓度蒸气对中枢神经系统有麻醉作用。', '对水生生物有毒性，可能对水体环境造成不利影响。', '遇高热、明火或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4234, 4341, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4235, 4342, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入 食入 经皮吸收\n吸入', NULL, '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4236, 4343, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '呕吐、呼吸加快、氰胺对皮肤粘膜有刺激性或腐蚀性，可致皮炎，可经皮吸收。', '无资料', '本品有毒、腐蚀性、刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4237, 4344, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n吸入、摄入或经皮肤吸收对身体有害。', '吸道、眼和皮肤。接触后引起烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '无资料', '本品易燃、有毒、强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4238, 4345, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入 食入 经皮吸收', '蒸气或雾对眼和上呼吸道有刺激性。对皮肤有刺激性。', '无资料', '本品易燃、刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4239, 4346, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, '对水生物有剧毒,对水生环境可能会引起长期有害作用', '通过打击、摩擦、火灾或其他着火源有极大爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4240, 4347, NULL, NULL, NULL, NULL, NULL, '第1.1类爆炸品', '吸入、食入、皮肤接触、眼睛接触', '粉尘对眼睛、皮肤、粘膜和上呼吸道有刺激作用。吸入可引起呼吸道刺激。高浓度吸入可引起肺水肿。长期接触可能引起慢性影响。', '对水生生物有毒。避免进入水体、土壤和大气。', '通过打击、摩擦、火灾或其他着火源有极大爆炸危险。遇明火、高热极易引起燃烧爆炸。与氧化剂能发生强烈反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4241, 4348, NULL, NULL, NULL, NULL, NULL, '第1类 爆炸品', '吸入 食入 经皮吸收', '本品有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '无资料', '本品属爆炸品，易燃，有毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4242, 4349, NULL, NULL, NULL, NULL, NULL, '第4.1类 易燃固体', '吸入 食入 经皮吸收', '对人体有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激性。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4243, 4350, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入食入经皮吸收', '有毒。吸入、摄入或经皮肤吸收会中毒。本品受热分解会放出有毒的Nox和氨烟雾。', '无资料', '本品可燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4244, 4351, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。可引起头痛、头晕、恶心、呕吐、腹痛、腹泻。高浓度接触可引起高铁血红蛋白血症、紫绀。长期接触可影响肝、肾功能。', '对水生生物有极高毒性，可能在水生环境中造成长期不利影响。', '遇明火、高热可燃。受热分解产生有毒的氮氧化物和氧化钾烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4245, 4352, NULL, NULL, NULL, NULL, NULL, '爆炸物，类别1.1项。', '食入、吸入、皮肤接触、眼睛接触\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4246, 4353, NULL, NULL, NULL, NULL, NULL, '第1类 爆炸品', '吸入 食入\n未见毒理学资料。同时接触环三次甲基三硝基胺(黑索金)粉尘的工人，有消化系统和造血系统', '障碍的表现。皮肤接触可发生皮炎。', '无资料', '本品属爆炸品，易燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4247, 4354, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', NULL, '无资料', '本品有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4248, 4355, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入', NULL, NULL, '本品不燃，有毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4249, 4356, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n经呼吸道和皮肤吸收。主要损伤睾丸、肝脏和肾脏。主要症状有腹痛、恶心、呕吐、肝区压', '痛，严重者出现肾功能衰竭及休克而死亡。', '无资料', '本品可燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4250, 4357, NULL, NULL, NULL, NULL, NULL, '易燃液体，类别3；特定目标器官毒性-单次接触，类别1；特定目标器官毒性-重复接触，类别1', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。本品有毒，对眼睛、皮肤和呼吸道有强烈刺激作用。吸入后可引起咳嗽、呼吸困难、头痛、头晕、恶心、呕吐等症状。皮肤接触可引起灼伤、红肿、疼痛。眼睛接触可引起严重刺激、流泪、视力模糊。吞食后可引起口腔、咽喉、胃肠道刺激，出现恶心、呕吐、腹痛等症状。特定目标器官毒性-单次接触，类别1；特定目标器官毒性-重复接触，类别1。长期或反复接触可能对中枢神经系统、肝、肾造成损害。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '1,3-二溴丙烷对水生生物可能有害，应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。在环境中可能发生分解，产生有害物质。', '本品易燃，具刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与强氧化剂接触发生化学反应或引起燃烧。在火场中，受热的容器有爆炸危险。受热或接触火焰可能会产生膨胀或爆炸性分解。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4251, 4358, NULL, NULL, NULL, NULL, NULL, '第1类 爆炸品', '吸入 食入 经皮吸收\n高铁血红蛋白形成剂，引起肝损害。患者的粘膜、皮肤出现紫绀，有头痛、头晕、耳鸣、全身', '无力、心悸、恶心、呕吐，甚至休克、昏迷。', '无资料', '本品属爆炸品，易燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4252, 4359, NULL, NULL, NULL, NULL, NULL, '第8.2类 碱性腐蚀品', '吸入 食入 经皮吸收\n蒸气或雾对鼻、喉和粘膜有腐蚀性，可蒸气或雾对鼻、喉和粘膜有腐蚀性，可引起支气管炎、\n化学性肺炎或肺水肿。蒸气、雾或液体对眼有强烈腐蚀性，重者可导致失明。皮肤接触可造成\n灼伤；对皮肤有致敏性。口服灼伤口腔和消化道，出现剧烈腹痛、恶心、呕吐和虚脱。慢性影', '响：本品有明显的致敏作用。引起支气管炎、化学性肺炎或肺水肿。蒸气、雾或液体对眼有强\n烈腐蚀性，重者可导致失明。皮肤接触可造成灼伤；对皮肤有致敏性。口服灼伤口腔和消化道，\n出现剧烈腹痛、恶心、呕吐和虚脱。', '无资料', '本品腐蚀性、刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4253, 4360, NULL, NULL, NULL, NULL, NULL, '第2.3类 有毒气体', '吸入\n氮氧化物主要损害呼吸道。吸入气体初期仅有轻微的眼及上呼吸道刺激症状，如咽部不适、干\n咳等。常经数小时至十几小时或更长时间潜伏期后发生迟发性肺水肿、成人呼吸窘迫综合征，', '出现胸闷、呼吸窘迫、咳嗽、咯泡沫痰、紫绀等。可并发气胸及纵隔气肿。肺水肿消退后两周\n左右可出现迟发性阻塞性细支气管炎。慢性作用：主要表现为神经衷弱综合征及慢性呼吸道炎\n症。个别病例出现肺纤维化。可引起牙齿酸蚀症。', NULL, '本品助燃，有毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4254, 4361, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸人 食入 经皮吸收\n动物实验示', '类放射线作用。人在事故性少量接触本品后6小时，出现眼睑水肿、眼痛和上呼吸道刺激。', '无资料', '本品易燃、有毒、强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4255, 4362, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收', '动物实验对眼、皮肤有轻度刺激性。人接触本品未见皮炎和过敏反应。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4256, 4363, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4257, 4364, NULL, NULL, NULL, NULL, NULL, '第2.3类 有毒气体', '吸入\n易被湿润的粘膜表面吸收生成亚硫酸、硫酸。对眼及呼吸道粘膜有强烈的刺激作用。大量吸入\n可引起肺水肿、喉水肿、声带痉挛而致窒息。急性中毒：轻度中毒时，发生流泪、畏光、咳嗽，', '咽、喉灼痛等；严重中毒可在数小时内发生肺水肿；极高浓度吸入可引起反射性声门痉挛而致\n窒息。皮肤或眼接触发生炎症或灼伤。慢性影响：长期低浓度接触，可有头痛、头昏、乏力等\n全身症状以及慢性鼻炎、咽喉炎、支气管炎、嗅觉及味觉减退等。少数工人有牙齿酸蚀症。', '对大气可造成严重污染。', '本品不燃，有毒，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4258, 4365, NULL, NULL, NULL, NULL, NULL, '第5.1类 氧化剂', '吸入 食入', '对呼吸道产生严重损伤浓度的本品气体，可能对皮肤有刺激性。皮肤接触或摄入本品的高浓度\n溶液，可能引起强烈刺激和腐蚀。长期接触可导致慢性支气管炎。', '无资料', '本品不燃、强腐蚀性、强刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4259, 4366, NULL, NULL, NULL, NULL, NULL, '第5.1类 氧化剂', '吸入 食入\n损害造血、神经、消化系统及肾脏。职业中毒主要为慢性。神经系统主要表现为神经衰弱综合\n征、周围神经病(以运动功能受累较明显)，重者出现铅中毒性脑病。消化系统表现有齿龈铅线、', NULL, '无资料', '本品有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4260, 4367, NULL, NULL, NULL, NULL, NULL, '第2.2类 不燃气体', '吸入\n在低浓度时，对呼吸中枢呈兴奋作用, 高浓度时则产生抑制甚至麻痹作用。中毒机制中还兼有\n缺氧的因素。急性中毒：人进入高浓度二氧化碳环境，在几秒钟内迅速昏迷倒下，反射消失、\n瞳孔扩大或缩小、大小便失禁、呕吐等，更严重者出现呼吸停止及休克，甚至死亡。固态(干', '冰)和液态二氧化碳在常压下迅速汽化，能造成-80～-43℃低温，引起皮肤和眼睛严重的冻伤。\n慢性影响: 经常接触较高浓度的二氧化碳者，可有头晕、头痛、失眠、易兴奋、无力等神经功\n能紊乱等。但在生产中是否存在慢性中毒国内外均未见病例报道。', '无资料', '本品不燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4261, 4368, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入\n对皮肤粘膜有较强的刺激性。大量吸入', '肿。进入眼内可引起结膜炎。可引起接触性皮炎。', '无资料', '本品有毒、刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4262, 4369, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收\n吸入、摄入或经皮肤吸收对身体有害。蒸气或雾对眼、粘膜和上呼吸道有刺激性。对皮肤有刺', '激性。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4263, 4370, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入\n铀及其化合物有放射性危害作用。大量吸入二氧化铀，出现恶心、呕吐、巩膜轻度黄染和蛋', '白尿。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4264, 4371, NULL, NULL, NULL, NULL, NULL, '第3.1类低闪点易燃液体', '吸入食入经皮吸收', '起眼刺激或灼伤。长时间皮肤接触可致灼伤。口服灼伤消化道。慢性影响：皮肤反复接\n触，可引起变应性皮炎。', '无资料', '本品极度易燃，具腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4265, 4372, NULL, NULL, NULL, NULL, NULL, '第3类易燃液体', '吸入 食入 经皮吸收', '对眼睛、皮肤有轻微刺激性。大量接触可能引起头痛、头晕、恶心等症状。', '对水生生物可能有轻微毒性。', '可燃，遇明火、高热有燃烧危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4266, 4373, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入', '本品对兔眼有明显刺激性。工业接触和使用时，未见对人有不良影响。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4267, 4374, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入', '对兔眼刺激轻微，工业接触和使用时，未见对人不良影响。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4268, 4375, NULL, NULL, NULL, NULL, NULL, '第1类 爆炸品', '吸入 食入 经皮吸收', '摄入本品可引起中毒，致血压下降和心功能紊乱。', '无资料', '本品属爆炸品、易燃', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4269, 4376, NULL, NULL, NULL, NULL, NULL, '无资料', '无资料', '未见职业中毒的资料报道。', '无资料', '本品易燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4270, 4377, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收\n动物实验', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4271, 4378, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '化物气体，应引起注意，接触水或水蒸气能产生有腐蚀性、有毒的气体。', '无资料', '本品易燃、有毒、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4272, 4379, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收\n摄入、吸入或经皮肤吸收后对身体有害。', '灼感、喘息、喉炎、咳嗽、气短、头痛、恶心和呕吐。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4273, 4380, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。可引起过敏反应。长期接触可能引起皮肤致敏。', '对水生生物有害。', '遇明火、高热可燃。受热分解产生有毒的氮氧化物和硫氧化物烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4274, 4381, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收\n吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。', '接触后可引起头痛、恶心、呕吐、烧灼感、喉炎、气短等，甚至发生化学性肺炎、肺水肿。', '无资料', '本品易燃、具有腐蚀性、强刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4275, 4382, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '大鼠吸入后，出现兴奋，共济失调和呼吸困难。', '无资料', '本品剧毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4276, 4383, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4277, 4384, NULL, NULL, NULL, NULL, NULL, '第4.2类自燃物品', '吸入食入经皮吸收\n至今尚未见工业镁中毒的病例报告，但误服过量二乙基镁可引起中毒，出现上腹痛、呕吐、腹', '泻、烦渴、紫绀等现象。', '无资料', '本品易燃、有毒、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4278, 4385, NULL, NULL, NULL, NULL, NULL, '易燃液体，类别2；急毒性-口服，类别3；急毒性-皮肤，类别3；特定目标器官毒性-重复', '吸入、食入、皮肤接触、眼睛接触\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4279, 4386, NULL, NULL, NULL, NULL, NULL, '第4.2类 自燃物品', '吸入 食入 经皮吸收\n摄入、吸入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜有强烈刺激作用。吸入可引', '起喉和支气管的痉挛、炎症和水肿，化学性肺炎、肺水肿。', '无资料', '本品易自燃、有毒、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4280, 4387, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入 食入 经皮吸收', '蒸气对眼、粘膜和上呼吸道有刺激性。对皮肤有刺激性。接触后可引起头痛、恶心和呕吐。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4281, 4388, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入、食入、经皮吸收', '动物实验具有麻醉作用和轻度刺激作用。未见人急性中毒报道。长期接触上呼吸道刺激症状；皮肤脱脂、粗糙和皲裂。', '对环境有危害，对水体和土壤可造成污染。', '易燃，遇明火、高热有燃烧爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4282, 4389, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入', NULL, '无资料', '本品极度易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4283, 4390, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收', '摄入具中等毒性。对眼和皮肤有刺激作用。目前，未见职业中毒病例报道。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4284, 4391, NULL, NULL, NULL, NULL, NULL, '第3.1类 低闪点易燃液体', '吸入 食入 经皮吸收', '蒸气或雾对眼、粘膜和上呼吸道有刺激性。对皮肤有刺激性。', '无资料', '本品易燃、刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4285, 4392, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入经皮吸收\n对呼吸道有刺激性，吸入蒸气可引起肺水肿。蒸气对眼有刺激性；液体可引起眼灼伤。', '皮肤接触可致灼伤。口服引起恶心、呕吐、腹泻、腹痛、虚弱和虚脱。皮肤反复接触可\n引起变应性皮炎。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4286, 4393, NULL, NULL, NULL, NULL, NULL, '第8.2类 碱性腐蚀品', '吸入 食入 经皮吸收', '成灼伤。口服出现恶心、呕吐和腹痛。', NULL, '本品可燃，具腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4287, 4394, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入经皮，吸收', '惊厥。', '无资料', '本品易燃，具腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4288, 4395, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入 食入 经皮吸收\n蒸气对眼、鼻有轻度刺激性；高浓度时造成麻醉、呼吸中枢抑制。反复接触发生恶心、眩', '晕。对肝、肾可有轻度影响。', '无资料', '本品易燃、刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4289, 4396, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入\n误服可发生中毒。中毒后出现头晕、恶心、呕吐、视物不清、瞳孔散大、呼吸困难、苍白，继', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4290, 4397, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入经皮吸收', NULL, '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4291, 4398, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收', '对眼睛、皮肤、粘膜有刺激性和腐蚀性。', '无资料', '本品可燃、具有腐蚀性、刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4292, 4399, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入经皮吸收\n吸入', '恶心、虚弱、焦虑等症状。口服刺激口腔和胃。眼接触有强烈的刺激性，角膜发生水肿。\n对皮肤有强烈的刺激作用，可引起坏死。', '无资料', '本品易燃，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4293, 4400, NULL, NULL, NULL, NULL, NULL, '有机过氧化物，C型。', '吸入、食入、皮肤接触、眼睛接触\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4294, 4401, NULL, NULL, NULL, NULL, NULL, '第8.2类 碱性腐蚀品', '吸入 食入 经皮吸收\n吸入后出现鼻、喉和肺刺激，恶心，头痛。液体对皮肤有强烈刺激性，短期接触即可引起灼伤。', NULL, '无资料', '本品易燃，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4295, 4402, NULL, NULL, NULL, NULL, NULL, '有机过氧化物，D型。', '吸入、食入、皮肤接触、眼睛接触\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4296, 4403, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入', '无资料。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4297, 4404, NULL, NULL, NULL, NULL, NULL, '第6.1 类毒害品', '无资料', NULL, '无资料', '本品易燃，有毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4298, 4405, NULL, NULL, NULL, NULL, NULL, '易燃液体，类别3；危害水生环境-急性毒性，类别2。', '吸入、食入、皮肤接触、眼睛接触\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4299, 4406, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品，氧化性液体类别1', '吸入、食入、皮肤接触、眼睛接触', '强腐蚀性。对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激和腐蚀作用。吸入其蒸气可引起呼吸道刺激、肺水肿。食入可引起严重的消化道灼伤、出血、休克。长期或反复接触可引起牙齿酸蚀症、慢性支气管炎。', '该物质对水生生物有剧毒。避免排放到水体、土壤和大气环境中。', '强氧化剂，与可燃物、还原剂、有机物等接触有燃烧爆炸危险。本身不燃烧，但能助燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4300, 4407, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有毒。吸入有毒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4301, 4408, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有剧毒。跟皮肤接触有剧毒。吸入有剧毒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4302, 4409, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吞食后有剧毒。对眼、皮肤、粘膜和上呼吸道有刺激性。接触后可出现头痛、头晕、恶心、呕吐等症状。皮肤接触可引起刺激、红肿、疼痛。眼睛接触可导致严重眼部损伤。食入可引起恶心、呕吐、腹痛。具有致癌和致畸变作用。骨髓抑制为剂量限制性毒性，血小板及粒细胞减少。胃肠道反应多见于每次剂量超过500μg时，表现为恶心、呕吐、腹泻，少数有口腔溃疡。脱发始于给药后7-10天，可逆。少数出现胃炎、肠炎或皮肤红斑、脱屑、色素沉着、肝肾功能损害等。', '该物质对环境可能有危害，对水体应给予特别注意。避免排放到周围环境中。', '受热分解，放出有毒烟气。加热时，容器可能爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4303, 4410, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '具较高的毒性。动物试验证明是致癌和致畸变物质。对眼睛、皮肤、粘膜和上呼吸道有刺激性。接触后可引起恶心、呕吐、腹泻、腹痛等胃肠道症状。长期接触可能引起骨髓抑制、肝肾功能损害。具有生殖毒性，可能影响生育能力。', '该物质对环境可能有危害，对水体应给予特别注意。', '受热或接触火焰可能会产生膨胀或爆炸性分解。在火场中，受热的容器有爆炸危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4304, 4411, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4305, 4412, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收', '对眼睛、皮肤、粘膜有刺激作用。目前未见工业中毒的报道。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4306, 4413, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收', '对眼睛、皮肤、粘膜有刺激作用。未见职业工业中毒报道。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4307, 4414, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入\n接触加工或使用', NULL, '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4308, 4415, NULL, NULL, NULL, NULL, NULL, '易燃液体; 有毒品', '吸入 食入 皮肤接触', '吞咽有害。皮肤接触可能有害。对皮肤有轻微刺激性。吸入可能有害。', '无资料', '遇高热、明火或与氧化剂接触，有引起燃烧的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4309, 4416, NULL, NULL, NULL, NULL, NULL, '第3.1类低闪点易燃液体', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。具有麻醉作用。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '无资料', '本品极度易燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4310, 4417, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和呼吸道有强烈的刺激作用。吸入可能由于喉、支气管的痉挛、水肿、炎症，化学性肺炎、肺水肿而致死。中毒表现有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '无资料', '本品可燃、具有强腐蚀性、强刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4311, 4418, NULL, NULL, NULL, NULL, NULL, '第2.3类有毒气体', '吸入、经皮吸收', '吸入可引起严重灼伤。慢性影响：可引起慢性鼻炎、咽炎、喉炎、气管炎、植物神经功能紊乱和骨骼改变。尿氟可增高。', '对环境有危害。', '本品助燃，剧毒，具强刺激性。与水或杂质接触时，可发生激烈反应而燃烧，使容器破裂。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4312, 4419, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '高浓度的蒸气可能引起头晕、头痛、恶心、麻醉作用。对眼睛、皮肤和呼吸道有刺激性。', '对环境有危害，对水体和土壤可造成污染。', '本品易燃，其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4313, 4420, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。引起眼睛、皮肤、粘膜和呼吸道的刺激作用。高浓度接触可引起麻醉作用。', '该物质对水体有轻微的危害。', '高度易燃，其蒸气与空气混合，能形成爆炸性混合物。受热、明火或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4314, 4421, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入', '误服或吸入粉尘会中毒。氟化物对皮肤及粘膜有刺激及腐蚀作用。在人体内能干扰多种酶的活性，影响糖代谢、细胞呼吸功能，引起钙、磷代谢的紊乱及氟骨症。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品不燃、有毒、具有腐蚀性、刺激性、可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4315, 4422, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收', '皮肤直接接触，引起发红，局部有烧灼感，重者有溃疡形成。对机体的作用似氢氟酸，但较弱。', '无资料', '本品不燃，具强腐蚀性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4316, 4423, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入', '误服或吸入粉尘会中毒。粉尘能强烈刺激眼睛和呼吸系统。与酸类反应，散发出刺激性和腐蚀性的氟化氢和四氟化硅气体。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品不燃、有毒、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4317, 4424, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入', '误服或吸入粉尘会中毒。粉尘能强烈刺激眼睛和呼吸系统。与酸类反应，散发出刺激性和腐蚀性的氟化氢和四氟化硅气体。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品不燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4318, 4425, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入', '误服引起急性胃肠炎样的急性中毒症状。可致死。皮肤接触可致皮炎或干裂。', '对环境有危害，对水体和土壤可造成污染。', '本品不燃、有毒。受高热或接触酸或酸雾放出剧毒的烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4319, 4426, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '有毒。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。吸入，可引起喉、支气管的炎症、痉挛，化学性肺炎、肺水肿等。接触后，引起头痛、恶心、呕吐、咳嗽、眩晕、气短等。', '无资料', '本品不燃、有毒、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4320, 4427, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。过量接触，可引起唾液分泌增加、恶心、呕吐、腹痛、发烧、呼吸困难、血清中钙含量减少。其粉尘、蒸气或烟雾可引起鼻中膈穿孔。慢性影响可致骨、韧带、肌腱钙化。', '对水生生物有毒。', '本品不燃、有毒、具有强刺激性。受高热分解，放出有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4321, 4428, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入', '有毒。误服或吸入会中毒。目前，工业上未见有锆中毒的报道。本品受热分解放出氟，对皮肤和粘膜有刺激及腐蚀作用。', '无资料', '本品不燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4322, 4429, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '有毒。误服或吸入会中毒。吸入，可出现呼吸道刺激症状和肺水肿；误服，出现急性胃肠炎。', '对环境有危害，对水体可造成污染', '本品不燃、有毒、为致癌物、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4323, 4430, NULL, NULL, NULL, NULL, NULL, '第8.3类 其它腐蚀品', '吸入 食入', '具有腐蚀性。受高热分解生成氟化氢等有毒气体。', NULL, '本品不燃，具强腐蚀性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4324, 4431, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '高毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。吸入、摄入或经皮肤吸收可引起中毒。汞化合物可引起中枢神经系统损害、肾脏损害等。慢性影响：可引起神经系统损害、肾脏损害、口腔炎等。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。对环境有危害，对水体和土壤可造成污染。', '受高热分解，放出有毒的烟气。不燃，但受热分解产生有毒的氟化物和汞蒸气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4325, 4432, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '有毒。误服会中毒。遇水或潮气反应产生氢氟酸。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。', '对水生生物有毒性作用。可能对水体环境造成长期不利影响。', '本品不燃、有毒、具有腐蚀性、强刺激性、可致人体灼伤。遇水或潮气反应产生氢氟酸，遇高温分解产生有毒的氟化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4326, 4433, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、皮肤接触、眼睛接触', '气短、头痛、恶心和呕吐。本品对粘膜、上呼吸道、眼睛、皮肤组织有极强的破坏作用。', '对水生生物有毒。可能对水体产生长期不良影响。', '本品不燃，有毒，具刺激性，严重损害粘膜、上呼吸道、眼睛和皮肤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4327, 4434, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '对皮肤有刺激性。对眼睛有严重刺激性。吸入可能引起呼吸道刺激。食入可能引起胃肠道刺激。', '对水生生物有毒。', '遇明火、高热可燃。受热分解产生有毒氟化物烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4328, 4435, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后会中毒。具刺激作用。大剂量可引起眩晕、虚脱。对肾脏有损害。', '无资料', '本品不燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4329, 4436, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入', '分解产物氟化氢有刺激性，可引起眼睛、呼吸道粘膜刺激症状，严重者可发生支气管炎、\n肺炎，甚至产生反射性窒息。', '无资料', '本品不燃，有毒，具刺激性，严重损害粘膜、上呼吸道、眼睛和皮肤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4330, 4437, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '急性中毒：多为误服所致。服后立即出现剧烈恶心、呕吐、腹痛、腹泻。重者休克、呼吸困难、紫绀。如不及时抢救可致死亡。部分患者出现荨麻疹，吞咽肌麻痹，手足抽搐或四肢肌肉痉挛。短期内吸入大量本品粉尘，引起呼吸道刺激症状，并伴有头昏、头痛、无力及消化道症状。慢性影响：长期较高浓度吸入可引起氟骨症。可致皮炎，重者出现溃疡或大疱。', '对环境有危害，对水体和土壤可造成污染。', '本品不燃，高毒，具刺激性，严重损害粘膜、上呼吸道、眼睛和皮肤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4331, 4438, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、皮肤接触、眼睛接触', '铅及其化合物损害造血、神经、消化系统及肾脏。职业中毒主要为慢性。神经系统主要表现为神经衰弱综合征、周围神经病(以运动功能受累较明显)，重者出现铅中毒性脑病。消化系统表现为腹痛、便秘、齿龈铅线等。肾脏损害主要表现为近端肾小管功能障碍。', '对水生生物有毒。可能对水体产生长期不良影响。', '本品不燃，有毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4332, 4439, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、皮肤接触、眼睛接触', '对呼吸道粘膜及皮肤有强烈的刺激和腐蚀作用。急性中毒：吸入较高浓度氟化氢，可引起眼及呼吸道粘膜刺激症状，严重者可发生支气管炎、肺炎或肺水肿，甚至发生反射性窒息。眼接触局部剧烈疼痛，重者角膜损伤，甚至发生穿孔。氢氟酸皮肤灼伤初期皮肤潮红、干燥。创面苍白，坏死，继而呈紫黑色或灰黑色。深部灼伤或处理不当时，可形成难以愈合的深溃疡，损及骨膜和骨质。本品灼伤疼痛剧烈。慢性影响：眼和上呼吸道刺激症状，或有鼻衄，嗅觉减退。可有牙齿酸蚀症。骨骼X线异常与工业性氟病少见。', '对环境有危害，对水体和土壤可造成污染。', '本品不燃，高毒，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4333, 4440, NULL, NULL, NULL, NULL, NULL, '第8.3类其它腐蚀品', '吸入、食入', '对皮肤、粘膜有强烈的刺激性和腐蚀性。吸入、摄入或经皮肤吸收后对身体有害。可引起呼吸道刺激、皮肤灼伤、眼睛损伤等。', '对环境有危害，对水体和土壤可造成污染。', '本品不燃、具有腐蚀性、强刺激性、可致人体灼伤。受热分解产生有毒的氟化物、氮氧化物和氨气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4334, 4441, NULL, NULL, NULL, NULL, NULL, '第8.3类其它腐蚀品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后会中毒。对眼睛、皮肤、粘膜有强烈的刺激作用。吸入，可引起喉、支气管痉挛、炎症，化学性肺炎、肺水肿等。', '对环境有危害，对水体和土壤可造成污染。', '本品不燃、高毒、具有腐蚀性、强刺激性、可致人体灼伤。受热分解产生有毒的腐蚀性烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4335, 4442, NULL, NULL, NULL, NULL, NULL, '第8.3类其它腐蚀品', '吸入、食入、经皮吸收', '对眼睛、皮肤和呼吸道有强烈的刺激性和腐蚀性。误服，对人体具高毒，可致死。', '对环境有危害，对水体和土壤可造成污染。', '本品不燃、高毒、具有腐蚀性强刺激性、可致人体灼伤。受热分解产生有毒的氟化物烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4336, 4443, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '未见有职业或非职业中毒的报道。', '无资料', '本品不燃，有毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4337, 4444, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收对身体有害。对粘膜、上呼吸道、眼和皮肤有严重损害。吸入后可因喉、支气管痉挛、炎症和水肿，化学性肺炎或肺水肿而致死。接触后引起烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '无资料', '本品不燃，有毒，严重损害粘膜、上呼吸道、眼睛和皮肤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4338, 4445, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '误服或吸入会中毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。过量接触，可引起唾液分泌增加、恶心、呕吐、腹痛、发烧、呼吸困难。其粉尘、蒸气或烟雾可引起鼻中膈穿孔。', '无资料', '本品不燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4339, 4446, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入', '本品对眼睛、皮肤有刺激作用。吸入、口服或经皮肤吸收后可能致死。中毒表现有流涎、\n恶心、呕吐、腹痛、发热等。可引起血钙偏低、氟骨症等。', '无资料', '本品不燃，有毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4340, 4447, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入', '吸入、摄入有毒。对皮肤及粘膜有刺激和腐蚀作用。', '对环境有危害，对水体和土壤可造成污染。', '本品不燃、有毒、具有腐蚀性、刺激性、可致人体灼伤。受高热分解，放出有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4341, 4448, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和呼吸道有强烈的刺激作用。吸入后可因喉、支气管的痉挛、水肿、炎症、化学性肺炎、肺水肿而致死。中毒表现有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品不燃，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4342, 4449, NULL, NULL, NULL, NULL, NULL, '第2.1类易燃气体', '吸入', '本品燃烧时，产生氟化氢气体。高浓度时有麻醉作用。遇热分解，释放出剧毒的氟化氢烟雾。对眼睛、皮肤、粘膜和上呼吸道有刺激性。', '对环境可能有危害，对水体应给予特别注意。对水生环境可能会引起长期有害作用。', '易燃，其蒸气与空气混合，能形成爆炸性混合物。受热分解产生有毒的烟气。遇明火、高热可燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4343, 4450, NULL, NULL, NULL, NULL, NULL, '第8类腐蚀品', '吸入、食入、皮肤接触、眼睛接触', '吞咽有害。会导致灼伤。对眼睛、皮肤、粘膜和呼吸道有强烈刺激作用。吸入其蒸气可引起呼吸道刺激、咳嗽、呼吸困难。长期接触可引起牙齿腐蚀。', '该物质对环境可能有危害，对水体应给予特别注意。', '不燃、具强腐蚀性、强刺激性、可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4344, 4451, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜和呼吸道有强烈刺激作用。吸入后可因喉、支气管的痉挛、水肿、炎症，化学性肺炎、肺水肿而致死。中毒表现有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品不燃，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4345, 4452, NULL, NULL, NULL, NULL, NULL, '第4.1类易燃固体', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤、粘膜和上呼吸道有刺激作用。遇热分解产生有毒气体。', '该物质对环境可能有危害，对水体应给予特别注意。', '遇热有火灾危险。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4346, 4453, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吞咽有害。吸入有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。镉化合物可引起肾损伤、骨痛病（痛痛病）。长期接触可导致慢性镉中毒。', '对水生生物毒性极大并具有长期持续影响。', '不燃、有毒、为致癌物、具有刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4347, 4454, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入', '吸入、食入或经皮吸收可引起铅中毒。对眼睛、皮肤、粘膜和呼吸道有刺激作用。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品不燃、高毒、具有腐蚀性、刺激性、可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4348, 4455, NULL, NULL, NULL, NULL, NULL, '第8类腐蚀品', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤、粘膜和呼吸道有刺激性。', '该物质对环境可能有危害，对水体应给予特别注意。', '不燃、具腐蚀性、刺激性、可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4349, 4456, NULL, NULL, NULL, NULL, NULL, '第8类腐蚀品', '吸入、食入、皮肤接触、眼睛接触', '吞咽有害。会导致灼伤。对眼睛、皮肤、粘膜和呼吸道有强烈刺激作用。', '该物质对环境可能有危害，对水体应给予特别注意。', '不燃、具强腐蚀性、强刺激性、可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4350, 4457, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吞食后有毒。对皮肤有刺激性。跟皮肤接触可能会引起敏化作用。对眼睛有严重刺激性。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。吸入可引起鼻炎、气管炎、化学性支气管炎、支气管肺炎、肺水肿。铍化合物可引起慢性铍病，表现为肺纤维化、肉芽肿性肺炎、皮肤肉芽肿等。铍粉尘被吸入人体后，会大量沉积在肺部，滞留时间长，半衰期数年，很难有效清除，期间，铍会让肺部一点点纤维化，最终导致肺炎，可能恶化成肺癌。', '对水生物有毒，对水生环境可能会引起长期有害作用。', '不燃、有毒、为致癌物、具有刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4351, 4458, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吞食后有毒。对皮肤有刺激性。跟皮肤接触可能会引起敏化作用。对眼睛有严重刺激性。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。吸入可引起鼻炎、气管炎、化学性支气管炎、支气管肺炎、肺水肿。铍化合物可引起慢性铍病，表现为肺纤维化、肉芽肿性肺炎、皮肤肉芽肿等。铍粉尘被吸入人体后，会大量沉积在肺部，滞留时间长，半衰期数年，很难有效清除，期间，铍会让肺部一点点纤维化，最终导致肺炎，可能恶化成肺癌。', '对水生物有毒，对水生环境可能会引起长期有害作用。', '不燃、有毒、为致癌物、具有刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4352, 4459, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入', '七氟钽酸钾的粉末对呼吸道粘膜有刺激作用。长时间接触钽及其化合物，有资料报道可引起尘肺病。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品不燃、具有刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4353, 4460, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吞食后有剧毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对环境有危害。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4354, 4461, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吞食后有剧毒。跟皮肤接触有剧毒。吸入有剧毒。', '对环境有危害，对水体和土壤可造成污染。', '易燃，其蒸气与空气混合，能形成爆炸性混合物。受热分解放出有毒的氟化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4355, 4462, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '剧毒。吸入、摄入或经皮肤吸收后会严重中毒。引起恶心、呕吐、目视不清、眼球震颤、低血压、肌痉挛、抽搐、昏迷等。', '对环境有危害，对水体和土壤可造成污染。', '本品可燃、剧毒，受热分解放出有毒的氟化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4356, 4463, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '高毒。对人能引起恶心、呕吐、上腹痛、视力不清、低血压、心律紊乱、肌痉挛、抽搐、昏迷等。潜伏期一般约为6小时。', '对环境有危害，对水体和土壤可造成污染。', '本品可燃、高毒，受热分解放出有毒的氟化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4357, 4464, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '高毒。蒸气和液体对眼睛和呼吸系统有刺激作用。', '对环境有危害，对水体和土壤可造成污染。', '本品易燃、高毒、具有刺激性。受高热分解，放出高毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4358, 4465, NULL, NULL, NULL, NULL, NULL, '第2.1类易燃气体', '吸入', '本品有麻醉性。遇热分解，释放出剧毒的氟化氢烟雾。', '对环境有危害。', '本品易燃。其蒸气与空气形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4359, 4466, NULL, NULL, NULL, NULL, NULL, '第2.1类易燃气体', '吸入', '热解可放出有毒的氟离子烟雾。高浓度吸入可引起麻醉作用。', '对环境有危害。', '本品易燃。比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，可能发生聚合反应，出现大量放热现象，引起容器破裂和爆炸事故。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4360, 4467, NULL, NULL, NULL, NULL, NULL, '第4.2类自燃物品', '吸入食入\n吸入', NULL, '无资料', '本品属自燃物品，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4361, 4468, NULL, NULL, NULL, NULL, NULL, '第3类易燃液体', '吸入、食入、经皮吸收', '国内未见症状，轻者似乙醇中毒表现，重者迅速产生昏迷抽搐，最后死亡；第二阶段，心肺症状明显，严重病例可有肺水肿，支气管肺炎，心力衰竭，第三阶段主要表现为不同程度肾功能衰竭。人的本品一次口服致死量估计为1.4ml/kg(1.56g/kg)。长期或反复接触可引起肾脏损害。', '对环境有危害，对水体可造成污染。', '遇明火、高热可燃。燃烧产生有毒烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4362, 4469, NULL, NULL, NULL, NULL, NULL, '爆炸物，类别1.1项。', '吸入、食入、皮肤接触、眼睛接触', '吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入该物质可能会对健康有害。', '对环境有危害，对水体、土壤和大气可造成污染。', '接触火焰可能会产生膨胀或爆炸性分解。遇明火、高热、撞击、摩擦有引起爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4363, 4470, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、经皮吸收', '具有强烈刺激和腐蚀性。皮肤和眼接触有强烈刺激性或造成灼伤。口服引起口腔及消化道灼伤。吸入后可引起呼吸道损害，出现烧灼感、咳嗽、喘息、气短、喉炎、头痛、恶心和呕吐等。', '高碘酸为强氧化剂，对水生生物可能有害。应避免进入水体、土壤和地下水。高碘酸在水中可能释放碘离子，对水生生态系统造成影响。', '本品助燃，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4364, 4471, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂、第6.1类毒害品', '吸入、食入、经皮吸收', '吸入后可引起呼吸道损害，出现烧灼感、咳嗽、喘息、气短、喉炎、头痛、恶心和呕吐等。对眼睛、皮肤和粘膜有刺激作用。钡化合物具有高毒性，可导致肌肉麻痹、心律失常等严重症状。口服可引起恶心、呕吐、腹泻、腹痛等症状，严重者可导致死亡。', '高碘酸钡为强氧化剂和高毒物质，对水生生物具有高毒性。应避免进入水体、土壤和地下水。钡离子对水生生态系统有严重危害，可能导致鱼类和其他水生生物死亡。对土壤和地下水可能造成长期污染。', '跟可燃物质接触可能会引起火灾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4365, 4472, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、经皮吸收', '本品对眼、上呼吸道、粘膜和皮肤有刺激性。', '高碘酸钠为强氧化剂，对水生生物可能有害。应避免进入水体、土壤和地下水。高碘酸钠在水中可能释放碘离子，对水生生态系统造成影响。', '本品助燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4366, 4473, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、经皮吸收', '吸入后可引起呼吸道损害，出现烧灼感、咳嗽、喘息、气短、喉炎、头痛、恶心和呕吐等。对眼睛、皮肤和粘膜有刺激作用。', '高氯酸钙为强氧化剂，对水生生物可能有害。应避免进入水体、土壤和地下水。高氯酸钙在水中可能释放氯离子，对水生生态系统造成影响。', '本品助燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4367, 4474, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、经皮吸收', '本品对眼睛、皮肤、粘膜和上呼吸道有刺激性。', '高氯酸锂为强氧化剂，对水生生物可能有害。应避免进入水体、土壤和地下水。高氯酸锂在水中可能释放氯离子和锂离子，对水生生态系统造成影响。', '本品助燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4368, 4475, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、经皮吸收', '吸入后可引起呼吸道损害，出现烧灼感、咳嗽、喘息、气短、喉炎、头痛、恶心和呕吐等。对眼睛、皮肤和粘膜有刺激作用。', '高氯酸镁为强氧化剂，对水生生物可能有害。应避免进入水体、土壤和地下水。高氯酸镁在水中可能释放氯离子和镁离子，对水生生态系统造成影响。', '本品助燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4369, 4476, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、经皮吸收', '本品对皮肤粘膜有强烈刺激性。', '高氯酸钠为强氧化剂，对水生生物可能有害。应避免进入水体、土壤和地下水。高氯酸钠在水中可能释放氯离子，对水生生态系统造成影响。', '本品助燃，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4370, 4477, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、经皮吸收', '吸入后可引起呼吸道损害，出现烧灼感、咳嗽、喘息、气短、喉炎、头痛、恶心和呕吐等。对眼睛、皮肤和粘膜有强刺激性。铅化合物具有高毒性，可导致铅中毒，出现头痛、失眠、记忆力减退、贫血、腹痛、便秘等症状。长期接触可导致慢性铅中毒，影响神经系统、造血系统和肾脏。', '高氯酸铅为强氧化剂和高毒物质，对水生生物具有高毒性。应避免进入水体、土壤和地下水。铅离子对水生生态系统有严重危害，可能导致鱼类和其他水生生物死亡。对土壤和地下水可能造成长期污染。', '本品助燃，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4371, 4478, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、经皮吸收', '吸入后可引起呼吸道损害，出现烧灼感、咳嗽、喘息、气短、喉炎、头痛、恶心和呕吐等。对眼睛、皮肤和粘膜有刺激作用。长期接触银化合物可引起皮肤、眼、呼吸道全身性银质沉着。皮肤色素沉着，呈灰黑色或浅石板色。', '高氯酸银为强氧化剂，对水生生物可能有害。应避免进入水体、土壤和地下水。银离子对水生生物具有毒性，可能对水生生态系统造成影响。', '本品助燃，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4372, 4479, NULL, NULL, NULL, NULL, NULL, '第5.1类 氧化剂', '吸入 食入 经皮吸收', '吸入后可引起呼吸道损害，出现烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐等。对眼睛、皮肤和粘膜有刺激作用。钡化合物具有剧毒性，可导致肌肉麻痹、心律失常等严重症状。口服可引起恶心、呕吐、腹泻、腹痛等症状，严重者可导致死亡。', '高锰酸钡为强氧化剂和剧毒物质，对水生生物具有高毒性。应避免进入水体、土壤和地下水。钡离子对水生生态系统有严重危害，可能导致鱼类和其他水生生物死亡。对土壤和地下水可能造成长期污染。', '本品助燃、剧毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4373, 4480, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、经皮吸收', '吸入后可引起呼吸道损害，出现烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐等。溅落眼睛内，刺激结膜，重者致灼伤。刺激皮肤。浓溶液或结晶对皮肤有腐蚀性。口服腐蚀口腔和消化道。', '高锰酸钙为强氧化剂，对水生生物可能有害。应避免进入水体、土壤和地下水。高锰酸钙在水中会分解产生二氧化锰沉淀，可能对水生生态系统造成影响。', '本品助燃，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4374, 4481, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、经皮吸收', '吸入后可引起呼吸道损害。溅落眼睛内，刺激结膜，重者致灼伤。刺激皮肤。浓溶液或结晶对皮肤有腐蚀性。口服腐蚀口腔和消化道，出现口内烧灼感、上腹痛、恶心、呕吐、口咽肿胀等。口服剂量大者，口腔粘膜呈棕黑色、肿胀糜烂，剧烈腹痛，呕吐，血便，休克，最后死于循环衰竭。高锰酸钾纯品致死量约为10g。', '高锰酸钾为强氧化剂，对水生生物可能有害。应避免进入水体、土壤和地下水。高锰酸钾在水中会分解产生二氧化锰沉淀，可能对水生生态系统造成影响。', '本品助燃，具腐蚀性、刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4375, 4482, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、经皮吸收', '吸入后可引起呼吸道损害，出现烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐等。溅落眼睛内，刺激结膜，重者致灼伤。刺激皮肤。浓溶液或结晶对皮肤有腐蚀性。口服腐蚀口腔和消化道。', '高锰酸钠为强氧化剂，对水生生物可能有害。应避免进入水体、土壤和地下水。高锰酸钠在水中会分解产生二氧化锰沉淀，可能对水生生态系统造成影响。', '本品助燃，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4376, 4483, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、经皮吸收', '吸入后可引起呼吸道损害，出现烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐等。溅落眼睛内，刺激结膜，重者致灼伤。刺激皮肤。浓溶液或结晶对皮肤有腐蚀性。口服腐蚀口腔和消化道。银化合物可能引起皮肤和眼睛的永久性变色（银质沉着病）。', '高锰酸银为强氧化剂，对水生生物可能有害。应避免进入水体、土壤和地下水。银离子对水生生物具有毒性，可能对水生生态系统造成影响。', '跟可燃物质接触可能会引起火灾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4377, 4484, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入镉燃烧形成的氧化镉烟雾，可引起急性肺水肿和化学性肺炎。个别病例可伴有肝、肾损害。对眼有刺激性。用镀镉器调制或贮存酸性食物或饮料，食入后可引起急性中毒症状。有恶心、呕吐、腹痛、腹泻、大汗、虚脱、甚至抽搐、休克。长期吸入较高浓度镉烟尘可引起慢性镉中毒，主要损害肾脏和肺部。', '对水生生物有极高毒性，可能在水生环境中造成长期不利影响。', '本品有毒。其粉体遇高热、明火能燃烧甚至爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4378, 4485, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, '对水生物有剧毒, 对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4379, 4486, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n对眼睛、皮肤和粘膜具腐蚀性，可造成严重灼伤。误服，可引起头痛、头晕、恶心、呕吐、\n腹痛、呼吸急促、紫绀、肾功能衰竭、休克、昏迷等。皮肤接触性皮炎和湿疹。六价铬化', '合物属致癌物。', '无资料', '本品助燃、有毒、为致癌物、具腐蚀性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4380, 4487, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收\n对眼睛、皮肤和粘膜具腐蚀性，可造成严重灼伤。误服，可引起头痛、头晕、恶心、呕吐、\n腹痛、呼吸急促、紫绀、肾功能衰竭、休克、昏迷等。对皮肤可引起接触性皮炎和湿疹。', '六价铬化合物属致癌物。', '无资料', '本品助燃、有毒、为致癌物、具有腐蚀性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4381, 4488, NULL, NULL, NULL, NULL, NULL, '侵入途径：', '吞食后有毒。对皮肤有刺激性。跟皮肤接触可能会引起敏化作用。对眼睛有严重刺激性。', NULL, '对水生物有剧毒,对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4382, 4489, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入\n急性中毒：吸入后对上呼吸道有刺激性，摄入后可引起头晕、头痛、恶心、呕吐、胃肠\n道刺激，可致死。慢性影响：可引起贫血、肾损害、铅蓄积、铅中毒，可引起皮肤发炎', '和湿疹。国际癌症研究中心(IARC)将“铬和某些铬化合物”列入对人类致癌的化学物质。', '无资料', '本品不燃、为致癌物、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4383, 4490, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入 食入 经皮吸收\n对眼睛、皮肤和粘膜具腐蚀性，可造成严重灼伤。误服，可引起头痛、头晕、恶心、呕吐、\n腹痛、呼吸急促、紫绀、肾功能衰竭、休克、昏迷等。对皮肤可引起接触性皮炎和湿疹。', '六价铬化合物属致癌物。', '无资料', '本品助燃、有毒、为致癌物、具有腐蚀性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4384, 4491, NULL, NULL, NULL, NULL, NULL, '危害水生环境-急性毒性，类别1；危害水生环境-慢性毒性，类别1。', '吸入，眼睛及皮肤接触，皮肤吸收\n灼烧皮肤，引起坏死、溃疡；吸入可导致困倦、麻木、恶心、腹泻，并腐蚀粘膜，产生过', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4385, 4492, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '粘膜和上呼吸道有刺激作用。', '无资料', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4386, 4493, NULL, NULL, NULL, NULL, NULL, '侵入途径：', '吞食后有毒。跟皮肤接触有毒。对皮肤有刺激性。对眼睛有严重刺激性。吸入有毒。对呼', '吸道有刺激作用。', NULL, '易燃,其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4387, 4494, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入 食入 经皮吸收\n吸入、摄入或经皮肤吸收后会中毒。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。吸', '入，可引起喉、支气管的炎症、痉挛，化学性肺炎、肺水肿等。', '无资料', '本品可燃、具有强腐蚀性、刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4388, 4495, NULL, NULL, NULL, NULL, NULL, '第8.3类其它腐蚀品', '吸入、食入、经皮吸收', '急性中毒：病人有头痛、头晕、乏力、多梦、发热等全身症状，并有明显口腔炎表现。可有食欲不振、恶心、腹痛、腹泻等。部分患者皮肤出现红色斑丘疹，少数严重者可发生间质性肺炎及肾脏损伤。慢性中毒：最早出现头痛、头晕、乏力、记忆减退等神经衰弱综合征；汞毒性震颤；另外可有口腔炎，少数病人有肝、肾损伤。吸入致命。', '对水生生物有剧毒，对水生环境可能会引起长期有害作用。对环境有严重危害，特别是对水体。', '本品不燃、有毒。常温下有蒸气挥发，高温下能迅速挥发。与氯酸盐、硝酸盐、热硫酸等混合可发生爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4389, 4496, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '剧毒。对眼、皮肤、粘膜和上呼吸道有强烈的刺激作用。吸入、摄入或经皮肤吸收后对身体有害。接触后可出现头痛、头晕、恶心、呕吐、呼吸困难等症状。皮肤接触可引起刺激、红肿、疼痛。眼睛接触可导致严重眼部损伤。食入可引起恶心、呕吐、腹痛、消化道灼伤。可抑制胆碱酯酶活性。', '对水生物有毒，对水生环境可能会引起长期有害作用。该物质对环境可能有危害，对水体应给予特别注意。避免排放到周围环境中。', '遇明火、高热可燃。受热分解，放出有毒烟气。加热时，容器可能爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4390, 4497, NULL, NULL, NULL, NULL, NULL, '第4.1类易燃固体', '吸入、食入', '本品对人体无毒。高浓度吸入引起呼吸道轻度刺激，进入眼内作为异物有刺激作用。粉尘对呼吸道有刺激性。', '对水生生物有毒性。', '本品易燃。粉体与空气可形成爆炸性混合物，遇明火、高热有燃烧爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4391, 4498, NULL, NULL, NULL, NULL, NULL, '第4.3类遇湿易燃物品', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤和粘膜有刺激性和腐蚀性。吸入粉尘可引起呼吸道刺激。食入可引起消化道刺激。', '对水生生物有毒性作用，可能对水体环境产生长期不良影响。', '遇水放出易燃气体。跟水接触会生成高度易燃的气体。受热分解，放出有毒的蒸气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4392, 4499, NULL, NULL, NULL, NULL, NULL, '第4.3类遇湿易燃物品', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤和粘膜有刺激性和腐蚀性。遇水或潮湿空气会产生氢气和硅烷等易燃气体，可引起爆炸。粉尘对呼吸道有刺激性。', '对水生生物有毒性。', '遇湿易燃，遇水或潮湿空气会释放易燃气体，可引起火灾或爆炸。粉体与空气可形成爆炸性混合物。具有腐蚀性和刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4393, 4500, NULL, NULL, NULL, NULL, NULL, '第4.3类遇湿易燃物品', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤和粘膜有刺激性和腐蚀性。遇水或潮湿空气会产生氢气和硅烷等易燃气体，可引起爆炸。粉尘对呼吸道有刺激性。', '对水生生物有毒性。', '遇湿易燃，跟水接触会生成高度易燃的气体（氢气、硅烷等）。粉体与空气可形成爆炸性混合物，遇明火、高热有燃烧爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4394, 4501, NULL, NULL, NULL, NULL, NULL, '第4.3类遇湿易燃物品', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤和粘膜有刺激性和腐蚀性。遇水或潮湿空气会产生氢气和硅烷等易燃气体，可引起爆炸。粉尘对呼吸道有刺激性。', '对水生生物有毒性。', '遇湿易燃，跟水接触会生成高度易燃的气体（氢气、硅烷等）。粉体与空气可形成爆炸性混合物，遇明火、高热有燃烧爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4395, 4502, NULL, NULL, NULL, NULL, NULL, '第4.3类遇湿易燃物品', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤和粘膜有刺激性和腐蚀性。吸入粉尘可引起呼吸道刺激。长期接触可能对肺部造成损害。', '对水生生物有毒性作用。', '遇水放出易燃气体。受热分解放出有毒蒸气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4396, 4503, NULL, NULL, NULL, NULL, NULL, '第4.3类遇湿易燃物品', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤和粘膜有刺激性和腐蚀性。吸入粉尘可引起呼吸道刺激。食入可引起消化道刺激。', '对水生生物有毒性作用，可能对水体环境产生长期不良影响。', '遇水放出易燃气体。跟水接触会生成高度易燃的气体。受热分解，放出有毒的蒸气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4397, 4504, NULL, NULL, NULL, NULL, NULL, '第4.3类遇湿易燃物品', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤和粘膜有刺激性和腐蚀性。吸入粉尘可引起呼吸道刺激。长期接触可能对肺部造成损害。', '对水生生物有毒性作用。', '遇水放出易燃气体。受热分解放出有毒蒸气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4398, 4505, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '铅及其化合物损害造血、神经系统、消化系统及肾脏。职业中毒主要为慢性，神经系统主要表现为神经衰弱综合征，周围神经病（以运动功能受累较明显），重者出现铅中毒性脑病。消化系统表现有齿龈铅线、食欲不振、恶心、腹胀、腹泻或便秘；腹绞痛见于中等及较重病例。长期接触可引起贫血、肾功能损害、生殖系统毒性。对眼睛、皮肤有刺激性。', '对水生生物有剧毒，对环境有持久性危害，在土壤和沉积物中可长期残留。', '本品不燃，受高热分解产生有毒的氧化铅和氧化硅烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4399, 4506, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '铅及其化合物损害造血、神经系统、消化系统及肾脏。职业中毒主要为慢性神经系统，主要表现为神经衰弱综合征，周围神经病(以运动功能受累较明显)，重者出现铅中毒性脑病。消化系统表现有齿龈铅线、食欲不振、恶心、腹胀、腹泻或便秘；腹绞痛见于中等及较重病例。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生生物有毒性作用，可能对水体环境产生长期不良影响。', '本品不燃、有毒。受高热分解，放出有毒的蒸气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4400, 4507, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收对身体有害。对皮肤有刺激作用。其蒸气或雾对眼睛、粘膜和呼吸道有刺激作用。接触后能引起头痛、恶心和呕吐。', '对水生生物有毒性。', '本品易燃，具刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4401, 4508, NULL, NULL, NULL, NULL, NULL, '第4.3类遇湿易燃物品', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤和粘膜有刺激性和腐蚀性。吸入粉尘可引起呼吸道刺激。食入可引起消化道刺激。', '对水生生物有毒性作用，可能对水体环境产生长期不良影响。', '遇水放出易燃气体。跟水接触会生成高度易燃的气体。受热分解，放出有毒的蒸气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4402, 4509, NULL, NULL, NULL, NULL, NULL, '第4.3类遇湿易燃物品', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤和粘膜有刺激性和腐蚀性。吸入粉尘可引起呼吸道刺激。食入可引起消化道刺激。', '对水生生物有毒性作用，可能对水体环境产生长期不良影响。', '遇水放出易燃气体。跟水接触会生成高度易燃的气体。受热分解，放出有毒的蒸气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4403, 4510, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、皮肤接触、眼睛接触', '属中等毒类。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激性和腐蚀性。吸入可引起咳嗽、呼吸困难、喉痉挛、化学性肺炎、肺水肿等。食入可引起口腔、咽喉、食道和胃部灼伤，伴有剧烈疼痛、恶心、呕吐、腹泻等症状。皮肤接触可引起灼伤、红肿、疼痛、水疱等。眼睛接触可引起严重灼伤、疼痛、红肿、流泪，严重者可导致角膜损伤甚至失明。', '对环境有危害，对水体可造成污染。遇水反应生成癸二酸和盐酸，可能对水生生物造成危害。', '本品可燃、具有强腐蚀性、强刺激性、可致人体灼伤。遇明火、高热、氧化剂能燃烧，并散发出有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4404, 4511, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入食入经皮吸收\n对皮肤粘膜有刺激性和腐蚀性。吸入后引起鼻炎、喉炎、气短和咳嗽等。眼、皮肤接触可', '引起强烈刺激、疼痛甚至灼伤。口服引起腹痛、恶心和呕吐。长期皮肤接触可引起变应性\n皮炎。', '无资料', '本品助燃，具腐蚀性、刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4405, 4512, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入食入经皮吸收\n吸入', '激口腔及胃肠道，引起腹痛、恶心和呕吐。慢性影响：过敏性体质者接触可发生皮疹。', '无资料', '本品助燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4406, 4513, NULL, NULL, NULL, NULL, NULL, '第5.2类 有机过氧化物', '吸入 食入 经皮吸收', '对眼睛、皮肤和粘膜有刺激性，属低毒物质。受热分解放出有腐蚀性和刺激性的烟雾。', '无资料', '本品易燃、具有爆炸性、刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4407, 4514, NULL, NULL, NULL, NULL, NULL, '有机过氧化物，D型。', '食入、吸入、皮肤接触、眼睛接触\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4408, 4515, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, '遇热有火灾危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4409, 4516, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, '跟可燃物质接触可能会引起火灾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4410, 4517, NULL, NULL, NULL, NULL, NULL, '第5.2类有机过氧化物', '吸入食入', '无资料。', '无资料', '本品易燃，具爆炸性，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4411, 4518, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入食入经皮吸收', '哮喘。', '无资料', '本品助燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4412, 4519, NULL, NULL, NULL, NULL, NULL, '第2.3类 有毒气体', '吸入', '实验动物急性中毒时见高铁血红蛋白血症，引起缺氧，出现紫绀。', '无资料', '本品助燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4413, 4520, NULL, NULL, NULL, NULL, NULL, '第5.1类 氧化剂', '吸入 食入', '吸入、摄入有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激性。', '无资料', '本品助燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
