INSERT INTO `msds_hazard` VALUES (4419, 4526, NULL, NULL, NULL, NULL, NULL, '根据GB30000-2013化学品分类和标签规范系列标准（参阅第十六部分），该产品分类如下：', '吸入、食入、皮肤接触、眼睛接触\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4420, 4527, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入食入\n口服后急性中毒表现为恶心、呕吐、腹痛、腹泻、脉缓、进行性肌麻痹、心律紊乱、血\n钾明显降低等。可致死。', '至造成灼伤。慢性影响：长期接触钡化合物的工人，可有无力、气促、流涎、口腔粘膜\n肿胀糜烂、鼻炎、结膜炎、腹泻、心动过速、血压增高、脱发等。', '无资料', '本品助燃，高毒，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
