INSERT INTO `msds_hazard` VALUES (4430, 4537, NULL, NULL, NULL, NULL, NULL, '第5.2类 有机过氧化物', '吸入 食入 经皮吸收', '对眼睛和粘膜有强烈刺激作用，受热分解释出有腐蚀性的烟雾。', '无资料', '本品易燃、具有爆炸性、强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4431, 4538, NULL, NULL, NULL, NULL, NULL, '第5.2类 有机过氧化物', '吸入 食入 经皮吸收', '动物实验表明，本品对眼有强烈刺激性。', '无资料', '本品易燃、具有爆炸性、强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4432, 4539, NULL, NULL, NULL, NULL, NULL, '有机过氧化物，D型；皮肤腐蚀/刺激，类别1；眼损伤/眼刺激，类别1。', '吸入、食入、皮肤接触、眼睛接触\n高浓度溶液可引起严重眼睛危害，刺激皮肤。', '性：4', '无资料', '强氧化剂', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4433, 4540, NULL, NULL, NULL, NULL, NULL, '有机过氧化物，F型；皮肤腐蚀/刺激，类别2；眼损伤/眼刺激，类别2A；危害水生环境-急性危害，类别2。', '吸入、食入、皮肤接触、眼睛接触', '吸入该物质可能会引起对健康有害的影响或呼吸道不适。对眼睛、皮肤和粘膜有刺激性。高浓度接触可能引起中枢神经系统抑制。意外食入该物质可能对健康有害。', '该物质可能对水生生物有害。', '有机过氧化物，具有强氧化性。遇热、明火、摩擦、撞击或与还原剂接触可能发生剧烈分解或爆炸。受热分解产生易燃和有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4434, 4541, NULL, NULL, NULL, NULL, NULL, '根据GB30000-2013化学品分类和标签规范系列标准（参阅第十六部分），该产品分类如下：', '吸入、食入、皮肤接触、眼睛接触', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4435, 4542, NULL, NULL, NULL, NULL, NULL, '有机过氧化物，F型。', '吸入、食入、皮肤接触、眼睛接触\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4436, 4543, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, '遇热有火灾危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4437, 4544, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入食入', NULL, '无资料', '本品助燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4438, 4545, NULL, NULL, NULL, NULL, NULL, '第5.2类有机过氧化物', '吸入食入经皮吸收\n吸入、口服或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。', '吸入后，可引起喉、支气管的炎症，水肿、痉挛、化学性肺炎、肺水肿。接触后可引起烧\n灼感、咳嗽、喘息、气短、头痛、恶心与呕吐等。', '无资料', '本品易燃，具爆炸性，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4439, 4546, NULL, NULL, NULL, NULL, NULL, '有机过氧化物，D型。', '吸入、食入、皮肤接触、眼睛接触\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4440, 4547, NULL, NULL, NULL, NULL, NULL, '有机过氧化物，B型；皮肤腐蚀/刺激，类别1；眼损伤/眼刺激，类别1；危害水生环境-急', '吸入、食入、皮肤接触、眼睛接触\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4441, 4548, NULL, NULL, NULL, NULL, NULL, '有机过氧化物，F型。', '吸入、食入、皮肤接触、眼睛接触\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4442, 4549, NULL, NULL, NULL, NULL, NULL, '有机过氧化物，D型。', '吸入、食入、皮肤接触、眼睛接触\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4443, 4550, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入食入\n对局部有刺激和腐蚀性。刺激眼和呼吸道，腐蚀鼻中隔；皮肤直接接触可引起灼伤；误服', '可造成消化道灼伤。', '无资料', '本品助燃，具腐蚀性、刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4444, 4551, NULL, NULL, NULL, NULL, NULL, '第5.1类 氧化剂', '吸入 食入', '本品粉尘刺激眼睛、皮肤和呼吸系统。水溶液为碱性腐蚀液体。', '无资料', '本品助燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4445, 4552, NULL, NULL, NULL, NULL, NULL, '第5.2类 有机过氧化物', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤、粘膜和上呼吸道有刺激作用。接触可引起皮肤灼伤、眼睛灼伤。吸入可引起呼吸道刺激、咳嗽、呼吸困难。食入可引起消化道刺激、恶心、呕吐。', '对水生生物有害，可能对水体环境造成长期不利影响。', '遇热、明火、高热有火灾或爆炸危险。受热分解产生有毒气体。与还原剂、酸类、金属粉末等反应剧烈，有爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4446, 4553, NULL, NULL, NULL, NULL, NULL, '第5.1类 氧化剂', '吸入 食入', '本品对眼睛、皮肤和呼吸道有刺激作用。至今尚未见中毒的病例报告。', '无资料', '本品助燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4447, 4554, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入食入', '伤。', '无资料', '本品助燃，具腐蚀性、刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4448, 4555, NULL, NULL, NULL, NULL, NULL, '第5.2类 有机过氧化物', '吸入 食入', '无资料。', '无资料', '本品易燃、有毒、具有爆炸性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4449, 4556, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4450, 4557, NULL, NULL, NULL, NULL, NULL, '有机过氧化物，D型；眼损伤/眼刺激，类别2A。', '吸入、食入、皮肤接触、眼睛接触\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', '眼刺激。眼睛直接接触可能会造成严重的炎症并伴随有疼痛。眼睛直接接触本品可导致暂\n时不适。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4451, 4558, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入食入\n吸入', '服中毒出现腹痛、胸口痛、呼吸困难、呕吐、一时性运动和感觉障碍、体温升高等。个别\n病例出现视力障碍、癫痫样痉挛、轻瘫。长期接触本品可致接触性皮炎。', '无资料', '本品助燃，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4452, 4559, NULL, NULL, NULL, NULL, NULL, '别1；急毒性-吸入，类别3；生殖细胞致突变性，类别2；特定目标器官毒性-单次接触，类', '吸入、食入、皮肤接触、眼睛接触\n吸入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4453, 4560, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, '对水生物有剧毒,对水生环境可能会引起长期有害作用。', '遇热有火灾危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4454, 4561, NULL, NULL, NULL, NULL, NULL, '第5.2类 有机过氧化物', '吸入 食入 经皮吸收\n吸入、摄入或经皮吸收 后对身体有害。高浓度时，对眼睛、皮肤、粘膜和上呼吸道有强烈', '刺激作用。接触后可引起烧灼感、咳嗽、喉炎、头痛、恶心和呕吐。', '无资料', '本品易燃、具有爆炸性、有毒、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4455, 4562, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '对皮肤有刺激性。', '对水生物有剧毒,对水生环境可能会引起长期有害作用。', '遇热有火灾危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4456, 4563, NULL, NULL, NULL, NULL, NULL, '有机过氧化物，D型。', '吸入、食入、皮肤接触、眼睛接触\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4457, 4564, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入食入', '本品粉尘对眼睛、皮肤和呼吸系统有刺激作用。水溶液为碱性腐蚀液体。', '无资料', '本品助燃，具腐蚀性、刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4458, 4565, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, '跟可燃物质接触可能会引起火灾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4459, 4566, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入食入\n吸入', '恶心、呕吐。反复接触其粉尘对皮肤有刺激性。', '无资料', '本品助燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4460, 4567, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, '遇热有火灾危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4461, 4568, NULL, NULL, NULL, NULL, NULL, '第5.2类 有机过氧化物', '吸入 食入\n误服和吸入', '雾。', '无资料', '本品具有爆炸性、易燃、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4462, 4569, NULL, NULL, NULL, NULL, NULL, '有机过氧化物，D型；眼损伤/眼刺激，类别1。', '吸入、食入、皮肤接触、眼睛接触\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4463, 4570, NULL, NULL, NULL, NULL, NULL, '有机过氧化物，D型。', '吸入、食入、皮肤接触、眼睛接触\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4464, 4571, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, '遇热有火灾危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4465, 4572, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, '遇热有火灾危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4466, 4573, NULL, NULL, NULL, NULL, NULL, '有机过氧化物，D型。', '吸入、食入、皮肤接触、眼睛接触\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4467, 4574, NULL, NULL, NULL, NULL, NULL, '有机过氧化物，C型。', '吸入、食入、皮肤接触、眼睛接触\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4468, 4575, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, '遇热有火灾或爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4469, 4576, NULL, NULL, NULL, NULL, NULL, '第5.2类有机过氧化物', '吸入食入经皮吸收', '本品有毒。对眼睛、皮肤和粘膜有刺激作用。', '无资料', '本品具爆炸性、易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4470, 4577, NULL, NULL, NULL, NULL, NULL, '第5.2类有机过氧化物', '吸入食入经皮吸收', '水肿、痉挛，化学性肺炎、肺水肿。接触后可引起烧灼感、咳嗽、喘息、喉炎、气短、头\n痛、恶心和呕吐。', '无资料', '本品易燃，具爆炸性，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4471, 4578, NULL, NULL, NULL, NULL, NULL, '有机过氧化物，C型；眼损伤/眼刺激，类别2A；急毒性-吸入，类别3；特定目标器官毒性-', '吸入、食入、皮肤接触、眼睛接触\n吸入蒸气(尤其是长期接触)可能引起呼吸道刺激，偶尔出现呼吸窘迫。吸入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4472, 4579, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吞食后有剧毒。跟皮肤接触有剧毒。吸入有剧毒。急性中毒表现为头痛、头晕、乏力、恶心、呕吐、腹痛等。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。对环境有严重危害，特别是对水体。', '遇高热、明火或与氧化剂接触，有引起燃烧的危险。受热分解产生有毒气体。爆炸性分解。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4473, 4580, NULL, NULL, NULL, NULL, NULL, '第2.2类不燃气体', '吸入', '现呼吸加快、注意力不集中、共济失调；继之出现疲倦无力、烦躁不安、恶心、呕吐、昏迷、抽搐，以致死亡。', '对环境无害。', '本品不燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4474, 4581, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '汞化合物对中枢神经系统有毒性，可引起汞中毒。对眼睛、皮肤、粘膜和上呼吸道有刺激性。长期接触可引起神经系统损害、肾脏损害。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。该物质对环境有危害，应特别注意对水体的污染。', '受热分解产生有毒的汞蒸气。遇明火、高热有引起燃烧爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4475, 4582, NULL, NULL, NULL, NULL, NULL, '无资料', '无资料', '如制品不纯时可含少量黄磷，可致黄磷中毒。经常吸入红磷尘，可引起慢性磷中毒。', '无资料', '本品易燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4476, 4583, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4477, 4584, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '本品蒸气或烟雾对眼睛、皮肤、粘膜和上呼吸道有刺激作用。目前，未见职业中毒报道。', '对环境有危害，对水体可造成污染。', '易燃液体，遇明火、高热可燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4478, 4585, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, '对水生物有剧毒,对水生环境可能会引起长期有害作用', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4479, 4586, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入 食入 经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛和皮肤有刺激作用。', '无资料', '本品易燃、具有刺激性。其蒸气与空气形成爆炸性混合物，遇明火、高热有燃烧爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4480, 4587, NULL, NULL, NULL, NULL, NULL, '第2.1类 易燃气体', '吸入', '具有麻醉作用。动物吸入超过一定浓度时引起血压下降，导致呼吸麻痹而死亡。在工业生产和环境中，高浓度吸入可导致麻醉效应，表现为头晕、嗜睡等症状。', '对环境有危害，对大气可造成污染。', '本品易燃，与空气混合能形成爆炸性混合物，遇热源和明火有燃烧爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4481, 4588, NULL, NULL, NULL, NULL, NULL, '第2.1类易燃气体', '吸入、食入、皮肤接触、眼睛接触', '吸入该物质可能会引起对健康有害的影响或呼吸道不适。高浓度可引起头痛、头晕、乏力、意识模糊等。对眼睛、皮肤、粘膜和上呼吸道有刺激性。', '对环境有危害。', '易燃气体，与空气混合能形成爆炸性混合物。遇明火、高热极易燃烧爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4482, 4589, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入', '对眼睛、皮肤有刺激作用。', '对环境有危害，对水体可造成污染。', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4483, 4590, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入', '吸入本品有麻醉作用。对眼睛、皮肤有刺激性。', '对环境有危害，对水体可造成污染。', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4484, 4591, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收对身体有害。对眼和皮肤有刺激性。', '对环境有危害，对水体应给予特别注意。', '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。可发生聚合反应，放出大量热量而引起容器破裂和爆炸事故。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4485, 4592, NULL, NULL, NULL, NULL, NULL, '第8.2类碱性腐蚀品', '吸入、食入、经皮吸收', '吸入、食入或经皮吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。可引起视力模糊、萎靡、语言障碍。人体斑贴试验见25%本品溶液引起严重的皮肤刺激，并可能致过敏反应。长期接触可引起皮肤过敏。', '对水生生物有害，可能在水生环境中造成长期不利影响。', '本品易燃，具强腐蚀性、强刺激性，可致人体灼伤，具致敏性。遇明火、高热有燃烧爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4486, 4593, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '对人体有毒性和腐蚀性。吸入、摄入或经皮肤吸收后对身体有害。对皮肤、眼睛有强烈刺激性，可引起灼伤。', '无资料', '本品可燃、具有腐蚀性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4487, 4594, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入经皮吸收\n吸入、口服或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有剧烈刺激作用。', '接触后可引起烧灼感、咳嗽、眩晕、喉炎、气短、头痛、恶心和呕吐。', '该物质对水生生物可能有害并可能导致长期不良影响。', '本品易燃，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4488, 4595, NULL, NULL, NULL, NULL, NULL, '易燃液体，类别3。', '吸入、食入、皮肤接触、眼睛接触\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', '吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入本品可能对胃肠道造成刺激，引起恶心、呕吐和腹泻。皮肤接触可能导致刺激和皮炎。眼睛接触可能导致严重刺激和损伤。', '该物质对水生生物可能有害并可能导致长期不良影响。', '易燃液体，其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4489, 4596, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入经皮吸收', '吸入、口服或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激性。长期接触可引起皮炎。', '对环境可能有危害，对水体应给予特别注意。', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4490, 4597, NULL, NULL, NULL, NULL, NULL, '第3.1类低闪点易燃液体', '吸入、食入、经皮吸收', '吸入、食入或经皮吸收对身体有害。对眼和上呼吸道有轻度刺激作用。持续吸入可引起头晕、恶心、倦睡和其他一些麻醉症状。液体污染皮肤可引起痒感。', '对环境有危害，对水体可造成污染。', '极度易燃。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与强氧化剂发生强烈反应，甚至引起燃烧。在火场中，受热的容器有爆炸危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4491, 4598, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入经皮吸收', '本品有麻醉作用，吸入后引起恶心、呕吐、头痛和神志丧失。对眼和皮肤有刺激性。', '该物质对环境有危害，对水生生物可能有害并可能导致长期不良影响。', '本品极度易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4492, 4599, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入、食入、经皮吸收', '具腐蚀性和刺激作用。受热分解释出氯气。', '对环境有害。', '本品可燃、具有腐蚀性、刺激性、可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4493, 4600, NULL, NULL, NULL, NULL, NULL, '第1类 爆炸品', '吸入 食入', '吸入后中毒，可发生癫痫样发作；误服可引起头晕、恶心、呕吐、流涎、多汗，重者发生\n抽搐。', '无资料', '本品属爆炸品、可燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4494, 4601, NULL, NULL, NULL, NULL, NULL, '第1类爆炸品', '吸入、食入、皮肤接触、眼睛接触', '吸入该物质可能会引起对健康有害的影响或呼吸道不适。误食入后中毒，可发生癫痫样发作；误服可引起头晕、恶心、呕吐、流涎、多汗，重者发生抽搐。对眼睛、皮肤、粘膜和上呼吸道有刺激性。', '对环境有危害，对水体和土壤应给予特别注意。', '通过打击、摩擦、火灾或其他着火源有极大爆炸危险。受热，接触明火、高热或受到摩擦震动、撞击时可发生爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4495, 4602, NULL, NULL, NULL, NULL, NULL, '第4.1类 易燃固体', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤、粘膜和上呼吸道有刺激性。钴化合物可能引起过敏反应。', '对环境有危害，对水体可造成污染。', '遇明火、高热易燃。受高热分解，放出有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4496, 4603, NULL, NULL, NULL, NULL, NULL, '第4.1类 易燃固体', '吸入、食入、皮肤接触、眼睛接触', '具刺激作用，目前，未见有对人体损害的报道。对眼睛、皮肤、粘膜和上呼吸道有刺激性。', '对环境有危害，对水体可造成污染。', '遇明火、高热易燃。受高热分解，放出有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4497, 4604, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。吸入后可引起头痛、头晕、恶心、呕吐、呼吸困难等。高浓度接触可引起肺水肿。', '对环境有危害，对水体和大气可造成污染。', '高度易燃液体，其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4498, 4605, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。高浓度接触可引起头痛、头晕、恶心、呕吐、呼吸困难等。', '对环境有危害，对水体和大气可造成污染。', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4499, 4606, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。高浓度接触可引起头痛、头晕、恶心、呕吐、呼吸困难等。', '对环境有危害，对水体和大气可造成污染。', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4500, 4607, NULL, NULL, NULL, NULL, NULL, '第3.1类 低闪点易燃液体', '吸入、食入、经皮吸收', '吸入后可引起头痛、头晕、定向力障碍、兴奋、倦睡、共济失调和麻醉作用。呼吸系统和心脏可受到影响。对眼有轻度刺激作用。口服致中枢神经系统抑制、粘膜出血和腹泻等。本品对皮肤有脱脂作用，引起皮肤干燥、发红等。', '对环境有危害，对水体和大气可造成污染。', '本品极度易燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4501, 4608, NULL, NULL, NULL, NULL, NULL, '第3.1类 低闪点易燃液体', '吸入 食入 经皮吸收', '本品恶臭，较低浓度时已难耐受，因此一般不易发生中毒、嗅阈为36.14mg/m3。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对环境有危害，对水体和大气可造成污染。', '本品极度易燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4502, 4609, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收对身体有害。对眼睛和皮肤有刺激性。高浓度吸入可引起头痛、头晕、恶心、呼吸困难等症状。', '对环境有危害，对水体、土壤和大气可造成污染。', '易燃液体，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触猛烈反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4503, 4610, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '蒸气或雾对眼睛、皮肤、粘膜和上呼吸道有刺激性。高浓度吸入可引起头痛、头晕、恶心、呼吸困难。', '对环境有危害，对水体可造成污染。', '易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触猛烈反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4504, 4611, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '制备和使用环氧树脂的工人，可有头痛、恶心、食欲不振、眼灼痛、眼睑水肿、上呼吸道刺激症状。皮肤接触可引起过敏性皮炎。长期接触可引起皮肤干燥、皲裂。对眼睛有刺激性。', '对水生生物有害。避免释放到环境中。', '本品易燃，具刺激性，具致敏性。遇明火、高热易引起燃烧爆炸。其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4505, 4612, NULL, NULL, NULL, NULL, NULL, '第2.1类 易燃气体', '吸入、经皮吸收', '是一种中枢神经抑制剂、刺激剂和原浆毒物。急性中毒：患者有剧烈的搏动性头痛、头晕、恶心和呕吐、流泪、呛咳、胸闷、呼吸困难；重者全身肌肉颤动、言语障碍、共济失调、出汗、神志不清，以致昏迷。还可见心肌损害和肝功能异常。抢救恢复后可能出现短暂精神失常或中枢性偏瘫。皮肤接触迅速发生红肿，数小时后起泡，反复接触可致敏。液体溅入眼内，可致角膜灼伤。慢性影响：长期少量接触，可见有神经衰弱综合征和植物神经功能紊乱。', '对环境有危害，对水体和大气可造成污染。', '本品易燃，有毒，为致癌物，具刺激性，具致敏性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4506, 4613, NULL, NULL, NULL, NULL, NULL, '第8.2类有机碱性腐蚀品', '吸入、食入、经皮吸收', '腐蚀物能引起呼吸道刺激，伴有咳嗽、呼吸道阻塞和粘膜损伤。意外食入本品可能对个体健康有害。皮肤直接接触造成严重皮肤灼伤。', '对水生生物可能有毒性。', '本品易燃，具有腐蚀性。遇明火、高热易燃。与氧化剂能发生强烈反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4507, 4614, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '高浓度对眼、呼吸道有刺激作用。吸入、摄入或经皮肤吸收后对身体有害。', '对水生生物可能有毒性。该物质对环境有危害，应特别注意对水体的污染。', '本品可燃，有毒，具刺激性。遇明火、高热可燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4508, 4615, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。本品动物实验可引起中枢神经系统抑制，大剂量可引起抽搐、窒息。可通过皮肤吸收，引起中毒。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。', '己二腈对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境有危害，应特别注意对水体的污染。在水生生物中可能发生生物蓄积。', '本品可燃，有毒。遇明火能燃烧。遇高热分解释出剧毒的气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4509, 4616, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '其蒸气对眼睛、粘膜有刺激作用。个别人可引起恶心、头痛、胸骨后疼痛和呼吸困难等。吸入、摄入或经皮肤吸收后对身体有害。', '对水生生物可能有毒性。该物质对环境有危害，应特别注意对水体的污染。', '易燃，遇明火、高热可燃。受热分解放出有毒气体。蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4510, 4617, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、经皮吸收', '具腐蚀性。蒸气能刺激眼睛、皮肤和粘膜，可引起灼伤。吸入可引起喉、支气管痉挛、炎症、化学性肺炎、肺水肿等。', '对水生生物可能有毒性。该物质对环境有危害，应特别注意对水体的污染。', '本品可燃、有毒、具有腐蚀性、刺激性、可致人体灼伤。遇明火、高热可燃。受高热分解，放出高毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4511, 4618, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、经皮吸收', '遇水反应，放出有毒的、有腐蚀性的氯和氯化氢气体。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。吸入可引起喉、支气管痉挛、炎症，化学性肺炎、肺水肿等。', '对水生生物可能有毒性。该物质对环境有危害，应特别注意对水体的污染。', '本品可燃、有毒、具有腐蚀性、强刺激性、可致人体灼伤。遇明火、高热可燃。受高热分解产生有毒的腐蚀性烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4512, 4619, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', NULL, '无资料', '本品易燃，有毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4513, 4620, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '对皮肤和粘膜有强刺激性，并有腐蚀性。吸入、摄入或经皮肤吸收后对身体有害。高浓度可致麻醉，甚至死亡。', '对水生生物可能有毒性。该物质对环境有危害，应特别注意对水体的污染。', '本品易燃、有毒、具有腐蚀性、强刺激性、可致人体灼伤。遇明火、高热可燃。接触酸或酸气能产生有毒气体。受高热分解放出有毒的气体。有腐蚀性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4514, 4621, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。经常接触本品可致神衰综合征。主要表现为头痛、头晕、乏力、记忆力减退、失眠、食欲不振等。对皮肤有刺激性，可引起皮肤干燥、皲裂、皮炎等。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '己内酰胺对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品可燃，具刺激性。与空气可形成爆炸性混合物，当达到一定的浓度时，遇火星会发生爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4515, 4622, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生生物可能有毒性。该物质对环境有危害，应特别注意对水体的污染。', '易燃，其蒸气与空气形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4516, 4623, NULL, NULL, NULL, NULL, NULL, '第8类腐蚀性物质', '吸入、食入、经皮吸收', '摄入、吸入或经皮肤吸收对身体有害。本品对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用。可引起喉、支气管的炎症、水肿、痉挛、化学性肺炎、肺水肿。接触后可引起烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '对水生生物有毒性。', '本品可燃，具有腐蚀性、刺激性、可致人体灼伤。遇高热、明火或与氧化剂接触，有引起燃烧的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4517, 4624, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收\n对眼睛、皮肤、粘膜和呼吸道有强烈的刺激作用。吸入、摄入或经皮肤吸收对身体有害。吸入\n可能由于喉、支气管的痉挛、水肿、炎症，化学性肺炎、肺水肿而致死。中毒表现有烧灼', '感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '无资料', '本品腐蚀性、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4518, 4625, NULL, NULL, NULL, NULL, NULL, '爆炸物，类别1.1项', '吸入、食入、皮肤接触、眼睛接触', '吸入粉尘可引起头痛、头晕、恶心、呼吸困难。对眼睛、皮肤和粘膜有刺激性。长期接触可能对心血管系统、神经系统造成影响。作为硝酸酯类药物，可能引起血管扩张、头痛、低血压等反应。', '对水生生物有毒性。爆炸可能对环境造成破坏。', '通过打击、摩擦、火灾或其他着火源有极大爆炸危险。遇明火、高热、撞击、摩擦极易发生爆炸。与氧化剂接触能发生剧烈反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4519, 4626, NULL, NULL, NULL, NULL, NULL, '侵入途径：', '吸入、皮肤接触、食入', '正常情况下适量接触无害，长期或过量暴露可能产生负面影响；高浓度或通过吸入/皮肤接触可能危害健康', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4520, 4627, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。对中枢神经系统有麻醉作用；对视神经和视网膜有特殊选择作用，引起病变；可致代谢性酸中毒。急性中毒：短时大量吸入出现轻度眼上呼吸道刺激症状（口服有胃肠道刺激症状）；经一段时间潜伏期后出现头痛、头晕、乏力、眩晕、酒醉感、意识朦胧、谵妄，甚至昏迷。视神经及视网膜病变，可有视物模糊、复视等，重者失明。代谢性酸中毒时出现二氧化碳结合力下降、呼吸加速等。慢性影响：神经衰弱综合征，植物神经功能失调，粘膜刺激，视力减退等。皮肤出现脱脂、皮炎等。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '甲醇对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。挥发后可参与形成光化学烟雾。', '本品易燃，具刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触猛烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4521, 4628, NULL, NULL, NULL, NULL, NULL, '第8.2类碱性腐蚀品', '吸入、食入、经皮吸收', '吸入、食入或经皮吸收后对身体有害。对眼睛、皮肤和粘膜有强烈的腐蚀性和刺激性。可引起严重的眼部损伤、皮肤灼伤、呼吸道刺激。大量口服可致失明和死亡。慢性影响有中枢神经系统抑制作用。', '对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃、具有强腐蚀性和强刺激性，可致人体灼伤。遇水、潮湿空气、酸类、氧化剂、高热及明火能引起燃烧。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。在空气中容易发生自热反应，有引发火灾的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4522, 4629, NULL, NULL, NULL, NULL, NULL, '第8.2类碱性腐蚀品', '吸入、食入、经皮吸收', '吸入、食入或经皮吸收后对身体有害。对眼睛、皮肤和粘膜有强烈的腐蚀性和刺激性。可引起严重的眼部损伤、皮肤灼伤、呼吸道刺激。大量口服可致失明和死亡。慢性影响有中枢神经系统抑制作用。', '对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃、具有强腐蚀性和强刺激性，可致人体灼伤。遇水、潮湿空气、酸类、氧化剂、高热及明火能引起燃烧。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4523, 4630, NULL, NULL, NULL, NULL, NULL, '第3.1类低闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '吸入、食入或经皮吸收后对身体有害。对眼睛、皮肤和粘膜有刺激作用。高浓度蒸气对神经系统有损害作用，受热分解出具腐蚀性的烟雾。吸入后可引起头痛、头晕、恶心、呕吐、嗜睡、神志丧失等。对眼睛和皮肤有刺激性。口服刺激口腔和胃，引起中枢神经系统抑制。', '对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃、有毒、具有强刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触猛烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4524, 4631, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、皮肤接触、眼睛接触', '本品对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用和腐蚀作用。即使接触极低水平的本品，也能引起皮肤刺痒和皮疹。吸入可引起喉痉挛、炎症，化学性肺炎、肺水肿等。高浓度接触可引起头痛、头晕、恶心、呕吐等症状。对中枢神经系统有影响。长期接触可能引起皮肤过敏反应。', '对环境有危害，对水体可造成污染。', '本品易燃，具腐蚀性、刺激性，可致人体灼伤。受热可能发生聚合反应，出现大量放热现象，引起容器破裂和爆炸事故。遇明火、高热可燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4525, 4632, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。蒸气或雾对眼睛、粘膜和上呼吸道有刺激作用。可引起头痛、头晕、胸闷、意识障碍。慢性影响：长期接触可引起血压增高、萎缩性鼻炎、结膜炎和植物神经功能障碍。', '对水生生物有害，可能对水体环境产生长期不良影响。避免释放到环境中。', '本品易燃，具刺激性。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。在紫外线的作用下易发生聚合，粘度逐渐增加，严重时整个容器的单体可全部发生不规则爆发性聚合。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4526, 4633, NULL, NULL, NULL, NULL, NULL, '第1.1类爆炸品', '吸入、食入、皮肤接触、眼睛接触', '属中等毒类。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。吸入可引起喉痉挛、炎症，化学性肺炎、肺水肿等。高浓度接触可引起腹痛、头痛、头晕、恶心、呕吐等症状。对中枢神经系统有影响。', '对环境有危害，对水体可造成污染。', '通过打击、摩擦、火灾或其他着火源有极大爆炸危险。接触火焰可能会产生膨胀或爆炸性分解。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4527, 4634, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品；第3类易燃液体', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收对身体有害。对眼睛、皮肤有刺激性。高浓度吸入可引起头痛、头晕、恶心、呕吐等症状。', '对环境有危害，对水体可造成污染。', '易燃，具刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触猛烈反应。若遇高热，可能发生聚合反应，出现大量放热现象，引起容器破裂和爆炸事故。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4528, 4635, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '吸入、口服或经皮肤吸收后对身体有害。其蒸气或雾对眼睛、粘膜和上呼吸道有刺激性。中毒表现有烧灼感、咳嗽、喘息、气短、喉炎、头痛、恶心和呕吐。可引起过敏反应。对中枢神经系统有影响。长期接触可能引起皮肤过敏反应。', '对环境有危害，对水体可造成污染。', '本品易燃，具刺激性，具致敏性。紫外线的作用下易发生聚合，粘度逐渐增加，严重时整个容器的单体可全部发生不规则爆发性聚合。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4529, 4636, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '吸入、口服或经皮肤吸收对身体有害。蒸气或雾对眼睛、粘膜和上呼吸道有刺激性。中毒表现有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。对中枢神经系统有影响。长期接触可能引起皮肤过敏反应。', '对环境有危害，对水体可造成污染。', '本品易燃，具刺激性。可全部发生不规则爆发性聚合。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4530, 4637, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收对身体有害。对眼睛、皮肤有刺激性。高浓度吸入可引起头痛、头晕、恶心、呕吐等症状。', '对环境有危害，对水体可造成污染。', '易燃，具刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触猛烈反应。若遇高热，可能发生聚合反应，出现大量放热现象，引起容器破裂和爆炸事故。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4531, 4638, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '本品对眼睛、皮肤有刺激作用。对中枢神经系统有影响。高浓度接触可引起头痛、头晕、恶心、呕吐等症状。长期接触可能引起皮肤过敏反应。', '对环境有危害，对水体可造成污染。', '高热，可能发生聚合反应，出现大量放热现象，引起容器破裂和爆炸事故。遇明火、高热可燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4532, 4639, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吞食后有剧毒。对心脏有强烈的强心作用，可引起恶心、呕吐、腹泻、头痛、视觉障碍、心律失常等中毒症状。过量可导致心脏骤停。', '对环境有危害，对水体可造成污染。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4533, 4640, NULL, NULL, NULL, NULL, NULL, '第4.3类遇湿易燃物品', '吸入、食入', '吸入、食入对身体有害。对眼睛、皮肤有刺激性。高浓度吸入可引起头痛、头晕、恶心、呕吐等症状。', '对环境有危害，对水体可造成污染。', '极度易燃，具强刺激性。遇水或潮湿空气会剧烈反应并放出易燃气体和腐蚀性烟雾。与氧化剂接触猛烈反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4534, 4641, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '本品属剧毒类。对中枢神经系统有严重的毒性作用，可引起震颤、共济失调、视力障碍、听力减退、感觉异常等症状。对肾脏、肝脏也有损害作用。可穿过胎盘屏障，对胎儿有致畸作用。长期接触可引起慢性中毒，表现为神经系统损害、记忆力减退、情绪不稳等。', '对环境有严重危害，对水体、土壤和大气可造成长期污染。对水生生物有剧毒，在生物体内有高度生物富集性，可通过食物链传递和放大。', '受高热、明火会产生剧毒的汞蒸气。遇明火、高热可燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4535, 4642, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。对皮肤有刺激性。高浓度蒸气可能会引起头晕、头痛、恶心、呕吐、倦睡、不安等症状。皮肤接触可引起刺激、红肿、疼痛。眼睛接触可引起刺激、流泪、视力模糊。长期接触可引起肝、肾功能损害，神经系统损伤等。本品可通过皮肤吸收。', '甲基环己醇对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃，具刺激性。易燃，其蒸气与空气混合，能形成爆炸性混合物。遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4536, 4643, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '对皮肤有刺激性。对眼睛有严重刺激性。对呼吸道有刺激作用。高浓度蒸气可能会引起头晕、头痛、恶心、麻醉作用。', '对水生生物有毒。对水生生物有害并具有长期持续影响。', '易燃，其蒸气与空气混合，能形成爆炸性混合物。受热或接触火焰可能会产生膨胀或爆炸性分解。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4537, 4644, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '吸入、食入或经皮肤吸收对身体有害。高浓度蒸气可引起头痛、头晕、恶心、麻醉作用。皮肤接触可引起发红、干燥皲裂、溃疡等。对眼睛有刺激性。', '对环境有危害，对水体和土壤可造成污染。', '本品易燃。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。因产生静电火花放电引起燃烧爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4538, 4645, NULL, NULL, NULL, NULL, NULL, '第3.1类低闪点易燃液体', '吸入、食入、经皮吸收', '本品具有刺激作用。对眼睛、皮肤、粘膜和上呼吸道有刺激性。', '对环境有危害，对水体可造成污染。', '本品易燃。蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，可能发生聚合反应，出现大量放热现象，引起容器破裂和爆炸事故。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4539, 4646, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '吸入高浓度蒸气可引起眼及上呼吸道刺激、中枢神经系统抑制，表现为头痛、头晕、恶心、呕吐等。长期接触可能引起皮肤干燥、皲裂。', '对环境有危害，对水体可造成污染。', '本品极度易燃，具刺激性。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。因产生静电火花放电引起燃烧爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4540, 4647, NULL, NULL, NULL, NULL, NULL, '第2.1类易燃气体', '吸入、食入、皮肤接触、眼睛接触', '本品具有强烈的刺激性和腐蚀性。对眼睛、皮肤、粘膜和上呼吸道有严重的刺激作用，可引起灼伤。吸入可引起呼吸道刺激、肺水肿，甚至窒息。接触可引起皮肤灼伤和眼睛损伤。', '对环境有危害，对水体和土壤可造成污染。', '本品易燃，具刺激性。其蒸气与空气可形成爆炸性混合物。遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。遇水或水蒸气反应放热并产生有毒的腐蚀性气体。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4541, 4648, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '对呼吸道和眼结膜有强烈刺激作用。接触者可有流泪、咳嗽、头痛、恶心、呕吐、喘息、易激动、皮肤发痒等症状。吸入后可因喉、支气管的痉挛、水肿，化学性肺炎、肺水肿而致死。对皮肤、粘膜和上呼吸道有强烈刺激性和腐蚀性。', '对环境有危害，对水体可造成污染。', '本品易燃，具腐蚀性、强刺激性，可致人体灼伤。遇明火、高热易引起燃烧爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4542, 4649, NULL, NULL, NULL, NULL, NULL, '第3类易燃液体', '吸入、食入、皮肤接触、眼睛接触', '本品对皮肤有刺激作用。其蒸气或烟雾对眼睛、粘膜和上呼吸道有刺激作用。', '对环境有危害，对水体可造成污染。', '本品易燃、有毒、具有刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4543, 4650, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、食入、经皮吸收对身体有害。对眼睛、皮肤有刺激性。高浓度吸入可引起头痛、头晕、恶心、呕吐等症状。', '对环境有危害，对水体可造成污染。', '易燃，具刺激性。遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4544, 4651, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '本品蒸气或雾对眼睛、粘膜和上呼吸道有刺激作用，可引起化学性肺炎。对皮肤有刺激性。', '对水生生物有害，可能对水体环境产生长期不良影响。避免释放到环境中。', '本品易燃，具刺激性。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4545, 4652, NULL, NULL, NULL, NULL, NULL, '第3.1类低闪点易燃液体', '吸入、食入、经皮吸收', '本品具有刺激性。对皮肤、眼睛、粘膜和上呼吸道有刺激性。', '对环境有危害，对水体可造成污染。', '高度易燃，其蒸气与空气混合，能形成爆炸性混合物。蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4546, 4653, NULL, NULL, NULL, NULL, NULL, '第4.3类遇湿易燃物品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用。接触后可引起烧灼感、咳嗽、喉炎、化学性肺炎、肺水肿、头痛、恶心和呕吐等。同时，还要考虑乙醚的麻醉作用。', '对环境有危害，对水体可造成污染。', '本品易燃、有毒、具有强刺激性。遇水或潮湿空气会分解放热并产生易燃的乙醚蒸气，有燃烧爆炸的危险。遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4547, 4654, NULL, NULL, NULL, NULL, NULL, '第2.1类易燃气体', '吸入', '吸入对身体有害，能引起快速的窒息。中毒表现有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '对环境有危害，对水体可造成污染。', '易燃，具刺激性。与空气混合能形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4548, 4655, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '具有刺激作用，吸入液体可致化学性肺炎。对皮肤有原发性刺激损害，低浓度长期接触可致皮肤干燥、脱脂和红斑。', '对环境有危害，对水体可造成污染。', '本品易燃、具有刺激性。遇明火、高热可燃，受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4549, 4656, NULL, NULL, NULL, NULL, NULL, '第3.1类低闪点易燃液体', '吸入、食入、经皮吸收', '未见职业中毒的资料报道。对眼睛、皮肤、粘膜和上呼吸道有刺激性。', '对环境有危害，对水体可造成污染。', '本品易燃。蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4550, 4657, NULL, NULL, NULL, NULL, NULL, '第3.1类低闪点易燃液体', '吸入、食入、经皮吸收', '本品具有刺激作用。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对环境有危害，对水体可造成污染。', '本品易燃。蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，可能发生聚合反应，出现大量放热现象，引起容器破裂和爆炸事故。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4551, 4658, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '本品具有刺激性。发生明显刺激，整天接触可能较严重。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对环境有危害，对水体可造成污染。', '本品易燃、有毒、具有刺激性。蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，可能发生聚合反应，出现大量放热现象，引起容器破裂和爆炸事故。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4552, 4659, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '本品具有麻醉和刺激作用。对眼睛、皮肤、粘膜和上呼吸道有刺激性。', '对环境有危害，对水体可造成污染。', '本品易燃，具刺激性。其蒸气与空气混合，能形成爆炸性混合物。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。与氧化剂能发生强烈反应。接触空气或在光照条件下可生成具有潜在爆炸危险性的过氧化物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4553, 4660, NULL, NULL, NULL, NULL, NULL, '第8.3类 其它腐蚀品', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。本品对粘膜、上呼吸道、眼睛和皮肤有强烈刺激性。接触其蒸气，引起结膜炎、角膜炎、鼻炎、支气管炎；重者发生喉痉挛、声门水肿和肺炎等。对皮肤有原发性刺激和致敏作用；浓溶液可引起皮肤凝固性坏死。口服灼伤口腔和消化道，可发生胃肠道穿孔，休克，肾和肝脏损害。长期接触低浓度甲醛可有轻度眼、鼻、咽喉刺激症状，皮肤干燥、皲裂、甲软化等。具强腐蚀性、强刺激性，可致人体灼伤，具致敏性。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '甲醛溶液对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境有危害，应特别注意对水体的污染。挥发后可参与形成光化学烟雾。', '本品易燃，具强腐蚀性、强刺激性，可致人体灼伤，具致敏性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4554, 4661, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、食入或经皮吸收后对身体有害。摄入或经皮肤接触有中等毒性。高浓度时，可能有麻醉作用。对眼睛、皮肤和粘膜有刺激性。热解产物（烟雾）有腐蚀性、刺激性。', '对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃、有毒、具有刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触猛烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4555, 4662, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、食入或经皮吸收后对身体有害。对眼睛、粘膜和皮肤有刺激作用，具麻醉作用。高浓度蒸气对神经系统有损害作用，受热分解出具腐蚀性的烟雾。吸入后可引起头痛、头晕、恶心、呕吐、嗜睡、神志丧失等。对眼睛和皮肤有刺激性。口服刺激口腔和胃，引起中枢神经系统抑制。高浓度时有显著刺激作用。目前，未见职业中毒报道。', '对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃、有毒、具有强刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触猛烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4556, 4663, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '吸入、食入或经皮吸收后对身体有害。对眼睛、粘膜和皮肤有刺激作用，具麻醉作用。高浓度蒸气对神经系统有损害作用，受热分解出具腐蚀性的烟雾。吸入后可引起头痛、头晕、恶心、呕吐、嗜睡、神志丧失等。对眼睛和皮肤有刺激性。口服刺激口腔和胃，引起中枢神经系统抑制。', '对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃、有毒、具有强刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触猛烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4557, 4664, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '摄入和皮肤接触有中度毒性。对眼睛有强烈刺激作用，对皮肤有轻度刺激作用。未见职业中毒的报道。对中枢神经系统有影响。', '对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害。', '其蒸气与空气形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。若遇高热，可能发生聚合反应，出现大量放热现象，引起容器破裂和爆炸事故。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4558, 4665, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '其蒸气与液体能严重刺激眼、鼻和呼吸系统，高浓度蒸气对神经系统有损害作用，受热分解出具腐蚀性的烟雾。属低毒类，对眼睛、皮肤、粘膜和上呼吸道有刺激性。', '对环境有危害，对水体可造成污染。', '本品易燃、有毒、具有强刺激性。遇明火、高热极易燃烧爆炸。受热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4559, 4666, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '吸入、口服或经皮肤吸收后对身体有害。可引起灼伤。对呼吸道有强烈的刺激作用，吸入后可引起喉、支气管的痉挛、炎症、水肿，化学性肺炎、肺水肿。中毒表现有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。对眼睛和皮肤有刺激性。', '对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。挥发后可参与形成光化学烟雾。', '本品易燃，具强刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触猛烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4560, 4667, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '对眼睛、皮肤和上呼吸道粘膜有刺激作用。吸入后可引起头痛、头晕、恶心、呕吐、嗜睡、神志丧失等。对眼睛和皮肤有刺激性。口服刺激口腔和胃，引起中枢神经系统抑制。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。挥发后可参与形成光化学烟雾。', '本品易燃，具刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触猛烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4561, 4668, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '吸入、口服或经皮吸收后对身体有害。对皮肤有刺激性。其蒸气或雾对眼睛、粘膜和上呼吸道有刺激性。', '对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃、有毒、具有强刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触猛烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4562, 4669, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '具有麻醉和刺激作用。其蒸气与液体能严重刺激眼、鼻和呼吸系统，高浓度蒸气对神经系统有损害作用，受热分解出具腐蚀性的烟雾。吸入后可引起头痛、头晕、恶心、呕吐、嗜睡、神志丧失等。对眼睛和皮肤有刺激性。口服刺激口腔和胃，引起中枢神经系统抑制。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。挥发后可参与形成光化学烟雾。', '本品易燃、有毒、具有强刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触猛烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4563, 4670, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、食入或经皮吸收后对身体有害。对眼睛、皮肤和粘膜有刺激作用。高浓度蒸气对神经系统有损害作用，受热分解出具腐蚀性的烟雾。吸入后可引起头痛、头晕、恶心、呕吐、嗜睡、神志丧失等。对眼睛和皮肤有刺激性。口服刺激口腔和胃，引起中枢神经系统抑制。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。', '对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃、有毒、具有强刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触猛烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4564, 4671, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、食入或经皮吸收后对身体有害。对眼睛、粘膜和皮肤有刺激作用，具麻醉作用。高浓度蒸气对神经系统有损害作用，受热分解出具腐蚀性的烟雾。吸入后可引起头痛、头晕、恶心、呕吐、嗜睡、神志丧失等。对眼睛和皮肤有刺激性。口服刺激口腔和胃，引起中枢神经系统抑制。', '对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃、有毒、具有强刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触猛烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4565, 4672, NULL, NULL, NULL, NULL, NULL, '第2.1类易燃气体', '吸入、食入、皮肤接触、眼睛接触', '对皮肤、粘膜有刺激作用；对中枢神经系统有抑制、麻醉作用。', '对环境有危害，对水体应给予特别注意。', '本品易燃，具刺激性。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4566, 4673, NULL, NULL, NULL, NULL, NULL, '第4.3类遇湿易燃物品', '吸入食入', '水肿。对眼和皮肤有强烈刺激和腐蚀性，可致灼伤。', '无资料', '本品遇湿易燃，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4567, 4674, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有剧毒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4568, 4675, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, '会跟水激烈反应,生成高度易燃的气体', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4569, 4676, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收', '困难等。', '无资料', '本品可燃、具有腐蚀性、强刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4570, 4677, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '急性中毒：能引起呕吐、体温低、无力、共济失调、紫绀、昏迷、窒息，甚至死亡。长期\n接触可出现贫血、黄疸等；对皮肤有致敏性，引起湿疹。', '无资料', '本品可燃，有毒，具致敏性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4571, 4678, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。人接触过高浓度本品，可引起头痛、眼及上呼吸道刺激。液体对皮肤有刺激性。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。长期接触可引起肝、肾功能损害，神经系统损伤等。本品可通过皮肤吸收。', '间甲基环己醇对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃、有毒、具有刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4572, 4679, NULL, NULL, NULL, NULL, NULL, '第8，1类 酸性腐蚀品', '吸入 食入 经皮吸收\n对粘膜、上呼吸道、眼睛和皮肤有强烈刺激作用。吸入后可因喉、支气管的炎症、水肿、痉挛，\n化学性肺炎、肺水肿而致死。中毒表现有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶', '心、呕吐。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4573, 4680, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入', '本品对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', NULL, '本品可燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4574, 4681, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收', '吸入、摄入或经皮肤吸收后会中毒。对皮肤和粘膜有刺激作用，对眼睛有强烈刺激作用。', '无资料', '本品可燃、有毒、具有强腐蚀性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4575, 4682, NULL, NULL, NULL, NULL, NULL, '第8.3类 其它腐蚀品', '吸入 食入 经皮吸收', '本品对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长时间的接触可引起眼的损伤，灼伤。', '无资料', '本品可燃、具有腐蚀性、刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4576, 4683, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收', '对眼睛、皮肤、粘膜有刺激作用。目前，未见工业中毒的报道。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4577, 4684, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入、食入、皮肤接触、眼睛接触', '本品对眼睛、皮肤、粘膜和上呼吸道有刺激作用。口服引起恶心、呕吐、腹痛和腹泻。受热分解放出氧化磷和氧化钠的烟雾。', '对环境可能有危害，对水体应给予特别注意。', '受高热分解，放出有毒的烟气。不燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4578, 4685, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '剧毒。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激性。吸入可引起喉炎、化学性肺炎和肺水肿。接触后可发生头痛、恶心、呕吐、咳嗽、气短等症状。皮肤接触可引起灼伤。眼睛接触可引起严重灼伤，甚至失明。汞化合物可引起神经系统损害、肾脏损害。', '对水生生物有剧毒。对环境有危害，对水体可造成污染。', '受热分解产生有毒气体。遇明火、高热有燃烧爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4579, 4686, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '剧毒。吞食后有毒。吸入有毒。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激性。吸入可引起喉炎、化学性肺炎和肺水肿。接触后可发生头痛、恶心、呕吐、咳嗽、气短等症状。皮肤接触可引起灼伤。眼睛接触可引起严重灼伤，甚至失明。', '对水生生物有剧毒。对环境有危害，对水体可造成污染。', '受热分解产生有毒气体。遇明火、高热有燃烧爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4580, 4687, NULL, NULL, NULL, NULL, NULL, '第8类腐蚀品', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤、粘膜和上呼吸道有强烈刺激性。吸入可引起喉炎、化学性肺炎和肺水肿。接触后可发生头痛、恶心、呕吐、咳嗽、气短等症状。皮肤接触可引起灼伤。眼睛接触可引起严重灼伤，甚至失明。', '对水生生物有毒性。对环境有危害，对水体可造成污染。', '可燃，受热发出有毒气体，有腐蚀性。遇明火、高热有燃烧爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4581, 4688, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n芥子气为靡烂性毒剂，对眼、呼吸道和皮肤都有作用，能引起红肿、起泡以至溃烂。如进入体', '内，可引起全身中毒，如全身不适、疲乏、头痛、头晕、恶心、呕吐、抑郁、嗜睡等中枢抑制\n及副交感神经兴奋等症状。中毒严重可引起死亡。国际癌症研究中心(IARC)已确认为致癌物。', '无资料', '本品有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4582, 4689, NULL, NULL, NULL, NULL, NULL, '易燃固体，类别2。', '吸入、食入、皮肤接触、眼睛接触\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '遇火或摩擦可被引燃，其粉体与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4583, 4690, NULL, NULL, NULL, NULL, NULL, '第4.2类 自燃物品', '吸入 食入 经皮吸收', '对眼和皮肤有刺激性。', '无资料', '本品易自燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4584, 4691, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, '对水生物有剧毒,对水生环境可能会引起长期有害作用。', '易燃,其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4585, 4692, NULL, NULL, NULL, NULL, NULL, '第4.1类 易燃固体', '吸入 食入\n主要为慢性中毒，损害中枢神经系统。主要表现为头痛、头晕、记忆减退、嗜睡、心动\n过速、多汗、两腿沉重、走路速度减慢、口吃、易激动等。重者出现“锰性帕金森氏综', '合征”，特点为面部呆板，无力，情绪冷淡，语言含糊不情，四肢僵直，肌颤，走路前\n冲，后退极易跌倒，书写困难等。', '无资料', '本品易燃', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4586, 4693, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入 食入', '目前未见职业中毒病例报告。对眼睛、皮肤、粘膜和呼吸道有刺激作用。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4587, 4694, NULL, NULL, NULL, NULL, NULL, '第4.3类遇湿易燃物品', '吸入食入', '至今尚未证明铷对人体有任何毒性，未见中毒病例报道', '无资料', '本品遇湿易燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4588, 4695, NULL, NULL, NULL, NULL, NULL, '第4.3类遇湿易燃物品', '吸入食入经皮吸收\n尚未见铯中毒的病例报告。工人长期接触未见对健康有影响。动物急性中毒表现以神经、', '肌肉的兴奋为特征。', '无资料', '本品易燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4589, 4696, NULL, NULL, NULL, NULL, NULL, '性-单次接触 ，类别 1；危害水生环境-急性毒性 ，类别 1；危害水生环境-慢性毒性 ，', '吸入、食入、皮肤接触、眼睛接触\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '易燃液体，其蒸气与空气混合，能形成爆炸性混合物。可遇水反应生成高度易燃的气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4590, 4697, NULL, NULL, NULL, NULL, NULL, '第4.3类遇湿易燃物品', '吸入食入经皮吸收\n迄今尚无职业中毒的报道。在动物实验中，急性锶中毒的症状是共济失调，肌肉异常软弱', '无力，甚至转为肌肉抽搐以致死亡。死因主要是呼吸衰竭。', '无资料', '本品遇湿易燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4591, 4698, NULL, NULL, NULL, NULL, NULL, '第4.1类易燃固体', '吸入食入', '吸入后对上呼吸道有刺激性，引起咳嗽、胸部紧束感或疼痛。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4592, 4699, NULL, NULL, NULL, NULL, NULL, '第8.3类 其它腐蚀品', '吸入 食入 经皮吸收', '纯品基本无毒。工业品因含有菲、咔唑等杂质，毒性明显增大。由于本品蒸气压很低，故经吸\n入中毒可能性很小。对皮肤、粘膜有刺激性；易引起光感性皮炎。', NULL, '本品可燃，具强腐蚀性、刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4593, 4700, NULL, NULL, NULL, NULL, NULL, '第3.2类高闪点易燃液体；第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。可引起皮肤过敏反应。长期或反复接触可能对器官造成伤害。可能致癌。', '对水生生物有毒。对水生环境可能造成长期不利影响。', '易燃液体，其蒸气与空气混合，能形成爆炸性混合物。遇明火、高热有燃烧爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4594, 4701, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有毒。', '对水生物有毒，对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4595, 4702, NULL, NULL, NULL, NULL, NULL, '侵入途径：', '吞食后有毒。可能有发生不可逆性作用的危险。短期暴露有严重损伤健康的危险。长期暴露', NULL, '对水生物有毒，对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4596, 4703, NULL, NULL, NULL, NULL, NULL, '易燃固体，类别1。', '吸入、食入、皮肤接触、眼睛接触\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '遇火或摩擦极易引燃，其粉体与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4597, 4704, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, '对水生环境可能会引起长期有害作用。', '易燃，其粉体与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4598, 4705, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4599, 4706, NULL, NULL, NULL, NULL, NULL, '第4.1类易燃固体', '吸入、食入、经皮吸收', '对眼、鼻、咽喉有刺激性。高浓度接触引起头痛、恶心、兴奋、出汗。极高浓度接触出现意识障碍、抽搐。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4600, 4707, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入 食入 经皮吸收', NULL, '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4601, 4708, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入经皮吸收\n蒸气有强烈的刺激性，并有麻醉作用。动物吸入、经口或经皮肤吸收均可引起急性中毒，\n表现有呼吸道刺激、肺水肿、肝损害、中枢神经系统损害、呼吸中枢麻痹，以致死亡。', NULL, '无资料', '本品易燃，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4602, 4709, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品（剧毒）', '吸入、食入、经皮吸收', '剧毒。吸入、摄入或经皮肤吸收后可致命。对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激性和腐蚀性。', '该物质对环境可能有危害，对水体应给予特别注意。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4603, 4710, NULL, NULL, NULL, NULL, NULL, '第3类易燃液体', '吸入、食入、经皮', '对眼睛、皮肤、粘膜和上呼吸道有刺激作用。高浓度蒸气可引起头痛、头晕、恶心、麻醉作用。长期接触可能引起慢性影响。', '对水生生物有毒，可能对水生环境造成长期不利影响。', '易燃，遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4604, 4711, NULL, NULL, NULL, NULL, NULL, '第2.2类不燃气体', '吸入', '高浓度时可能引起窒息。在密闭空间内，由于氧气浓度降低，可能导致头晕、头痛、呼吸困难、意识丧失甚至死亡。', '该物质对环境无危害。', '高压，遇热有爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4605, 4712, NULL, NULL, NULL, NULL, NULL, '第1类 爆炸品', '吸入 食入 经皮吸收', '劳，厌食等。', '无资料', '本品属爆炸品，易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4606, 4713, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '蒸气对鼻、喉有刺激性。吸入后可引起头痛、头晕、恶心。对眼睛、皮肤有刺激性。口服刺激口腔和胃。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品可燃，有毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4607, 4714, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n抑制体内胆碱酯酶活性，造成神经生理功能紊乱。大量误服出现典型急性有机磷中毒症状。\n表现有头痛、头昏、乏力、食欲不振、恶心、呕吐、腹痛、腹泻、流涎、瞳孔缩小、呼吸', '道分泌物增多、多汗、肌束震颤等。重度中毒者出现肺水肿、昏迷、呼吸麻痹、脑水肿。\n血胆碱酯酶活性降低。本品毒性较低，经皮服吸收缓慢，职业中毒不多见。', '无资料', '本品可燃，有毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4608, 4715, NULL, NULL, NULL, NULL, NULL, '1.1项爆炸品；第6.1类毒害品', '吸入、食入、皮肤接触', '急性中毒可引起头痛、头晕、恶心、呕吐、腹痛、呼吸困难等症状；长期接触可引起神经系统损害、肾脏损害；具有爆炸性，受热、摩擦或撞击极易爆炸', '对水生生物有害并具有长期持续影响；对环境造成危害', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4609, 4716, NULL, NULL, NULL, NULL, NULL, '第4.3类遇湿易燃物品', '吸入食入', '本品具有强烈腐蚀性，眼和皮肤接触引起刺激或灼伤。', '无资料', '本品遇湿易燃，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4610, 4717, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, '在空气中容易发生自热反应,有引发火灾的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4611, 4718, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, '在空气中容易发生自热反应,有引发火灾的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4612, 4719, NULL, NULL, NULL, NULL, NULL, '第4.2类自燃物品', '吸入食入', '本品对眼、呼吸道和皮肤有刺激性，接触后可引起头痛、恶心和呕吐。', '无资料', '本品属自燃物品，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4613, 4720, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, '对水生物有剧毒,对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4614, 4721, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n对皮肤、粘膜有轻度刺激性，高浓度吸入，主要损害神经系统和肝脏，可致过敏性或接\n触性皮炎。急性中毒主要表现为神经系统和消化系统症状，如头晕、头痛、眩晕、嗜睡、\n恶心、呕吐等，有时可出现肝功能障碍。高浓度接触，对呼吸道和眼睛有明显刺激，长', '期接触可引起头痛、乏力、失眠等以及呼吸道刺激症状。', '无资料', '本品易燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4615, 4722, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', NULL, '本品可燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4616, 4723, NULL, NULL, NULL, NULL, NULL, '根据GB30000-2013化学品分类和标签规范系列标准（参阅第十六部分），该产品分类如下：', '吸入、食入、皮肤接触、眼睛接触', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4617, 4724, NULL, NULL, NULL, NULL, NULL, '剧毒化学品，具有剧烈急性毒性危害', '吸入、皮肤接触、食入', '吞食后有剧毒。属于单端孢霉烯族毒素，可以引起人或动物急性、慢性毒性作用，部分霉菌毒素已证明具有致突变性及致癌性。', '对水生生物可能有害', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4618, 4725, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n有毒，并有腐蚀性。对角质有溶解作用，能使蛋白质变质。吸收进入体内，可形成高铁血', '红蛋白而致紫绀。', '无资料', '本品可燃、有毒、具有腐蚀性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4619, 4726, NULL, NULL, NULL, NULL, NULL, '侵入途径：', '吞食后有毒。跟皮肤接触有毒。跟皮肤接触可能会引起敏化作用。有严重损害眼睛的危', NULL, '对水生物有剧毒。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4620, 4727, NULL, NULL, NULL, NULL, NULL, '侵入途径：', '健康危害： 热解能放出有腐蚀性的烟和雾。\n环境危害：\n燃爆危险：', '热解能放出有腐蚀性的烟和雾。', NULL, '本品可燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4621, 4728, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入', '复接触对皮肤有致敏作用。可引起慢性支气管炎和哮喘。', '无资料', '本品可燃，具腐蚀性、刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4622, 4729, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收', '水肿，化学性肺炎或肺水肿而致死。接触后出现烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶\n心和呕吐。能引起灼伤。', '无资料', '本品可燃、强腐蚀性、强刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4623, 4730, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n吸入、摄入或经皮肤吸收后对身体有害。对皮肤有轻微刺激作用，对眼睛、粘膜有刺激作', '用。', '无资料', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4624, 4731, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4625, 4732, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。人接触过高浓度，可引起头痛、眼及上呼吸道刺激；有麻醉作用。对皮肤有刺激性。摄入后引起中枢神经系统抑制。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。长期接触可引起肝、肾功能损害，神经系统损伤等。本品可通过皮肤吸收。', '邻甲基环己醇对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃、有毒、具有刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4626, 4733, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', NULL, NULL, '无资料', '本品易燃、有毒、刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4627, 4734, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入', '本品对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4628, 4735, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4629, 4736, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4630, 4737, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4631, 4738, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入食入经皮吸收', '血。停止接触容易恢复。', NULL, '本品可燃，有毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4632, 4739, NULL, NULL, NULL, NULL, NULL, '第8.3类 其它腐蚀品', '吸入 食入 经皮吸收', '痛、恶心和呕吐等。长时间接触引起眼睛的损伤，激烈的刺激和灼伤。', '无资料', '本品可燃、具有腐蚀性、强刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4633, 4740, NULL, NULL, NULL, NULL, NULL, '侵入途径： 粉尘吸入，眼睛及皮肤接触', '粉尘吸入，眼睛及皮肤接触\n遇水和空气中湿气会放出有毒磷化氢，是急性局部刺激剂，可引起情绪急躁、颤抖、疲乏、', '肠胃痛、腹泻、昏迷及痉挛', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4634, 4741, NULL, NULL, NULL, NULL, NULL, '第4.3类 遇湿易燃物品', '吸入 食入\n吸入、误服磷化钾时，在胃及肺中可与胃酸和水反应生成剧毒的磷化氢。中毒表现为口\n渴、恶心、胃痛、呕吐、腹泻、呼吸困难、瞳孔散大、痉挛、昏迷等。通常在出现窒息', NULL, '无资料', '本品遇湿易燃、高毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4635, 4742, NULL, NULL, NULL, NULL, NULL, '第4.3类 遇湿易燃物品', '吸入 食入', '心律紊乱。', '无资料', '本品遇湿易燃', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4636, 4743, NULL, NULL, NULL, NULL, NULL, '第4.3类 遇湿易燃物品', '吸入 食入\n吸入、误服磷化镁，在胃及肺中可与胃酸和水反应生成剧毒的磷化氢，引起磷化氢中毒。', NULL, '无资料', '本品遇湿易燃、高毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4637, 4744, NULL, NULL, NULL, NULL, NULL, '第4.3类 遇湿易燃物品', '吸入、食入', '吸入、误服磷化钠时，在胃及肺中可与胃酸和水反应生成剧毒的磷化氢。中毒表现为口渴、恶心、呕吐、腹泻、呼吸困难、瞳孔散大、痉挛、昏迷等。通常在出现窒息和严重呼吸困难前可导致死亡。', '对水生生物有毒害作用，可能对水体环境造成长期不良影响。', '本品遇湿易燃、高毒。与水或潮湿空气接触会放出易燃的磷化氢气体，遇火源可能引起燃烧或爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4638, 4745, NULL, NULL, NULL, NULL, NULL, '第2.3类 有毒气体', '吸入 食入\n磷化氢作用于细胞酶，影响细胞代谢，发生内窒息。其主要损害神经系统、呼吸系统、心脏、\n肾脏及肝脏。10mg/m3接触6小时，有中毒症状；409~846mg/m3时，半至１时发生死亡。急性中', NULL, '无资料', '本品易燃，剧毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4639, 4746, NULL, NULL, NULL, NULL, NULL, '第4.3类 遇湿易燃物品', '吸入 食入\n吸入、误服磷化锶，在胃及肺中可与胃酸和水反应生成剧毒的磷化氢，引起磷化氢中毒。', NULL, '无资料', '本品遇湿易燃、高毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4640, 4747, NULL, NULL, NULL, NULL, NULL, '第4.3类 遇湿易燃物品', '吸入 食入\n吸入、误服磷化锡，在胃及肺中可与胃酸和水反应生成剧毒的磷化氢，引起磷化氢中毒。', NULL, '无资料', '本品遇湿易燃、高毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4641, 4748, NULL, NULL, NULL, NULL, NULL, '第4.3类 遇湿易燃物品', '吸入 食入\n吸入、误服磷化锌可致磷化氢中毒，表现有不同程度的胃肠症状，以及发热、畏寒、头晕、', '兴奋及心律紊乱等。严重者有气急、少尿、抽搐、休克及昏迷等。', '无资料', '本品遇湿易燃、高毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4642, 4749, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', NULL, NULL, '本品可燃，有毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4643, 4750, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', NULL, '无资料', '本品可燃，有毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4644, 4751, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, '对水生物有剧毒, 对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4645, 4752, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4646, 4753, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入', '属剧毒类。吞食后有毒。吸入有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。可引起钡中毒，表现为恶心、呕吐、腹痛、肌肉无力、心律失常等症状。', '对水生生物有剧毒。对水生环境可能造成长期不利影响。', '遇明火、高热可燃。遇酸类放出易燃、有毒的硫化氢气体。受高热分解，放出有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4647, 4754, NULL, NULL, NULL, NULL, NULL, '第3类易燃液体', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生生物有害。', '高度易燃，其蒸气与空气混合，能形成爆炸性混合物。遇明火、高热极易引起燃烧爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4648, 4755, NULL, NULL, NULL, NULL, NULL, '第3类易燃液体；第8.3类其它腐蚀品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用和腐蚀性。高浓度接触可引起肺水肿。', '对水生生物有害。', '易燃液体，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂能发生强烈反应。有腐蚀性。受高热分解，放出有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4649, 4756, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '接触后主要出现皮肤、粘膜尤其是眼和上呼吸道的刺激症状和体征。蒸气对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。吸入可引起咳嗽、胸闷、呼吸困难等。食入可引起恶心、呕吐、腹痛、腹泻等。高浓度接触可引起肺水肿。', '对水生生物有害。', '易燃液体，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触猛烈反应。受热分解产生硫化氢、氧化硫等有毒气体。具有腐蚀性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4650, 4757, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '吸入后可引起呼吸道痉挛、水肿、化学性肺炎、肺水肿。对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用。重复接触可引起哮喘、引起过敏反应等。高浓度接触可引起严重灼伤。', '对水生生物有害。', '本品易燃、有毒、具有强刺激性、致敏性。遇明火、高热有燃烧爆炸的危险。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4651, 4758, NULL, NULL, NULL, NULL, NULL, '第8类腐蚀品；第3类易燃液体', '吸入、食入、皮肤接触、眼睛接触', '吸入、食入或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用。吸入后可引起喉、支气管的炎症、水肿、痉挛，化学性肺炎或肺水肿。接触可引起灼伤。', '对水生生物有害。', '易燃，其蒸气与空气混合，能形成爆炸性混合物。遇明火、高热极易燃烧爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4652, 4759, NULL, NULL, NULL, NULL, NULL, '第8.2类碱性腐蚀品', '吸入、食入、经皮吸收', '急性中毒：主要由误服引起。中毒表现有恶心、呕吐、腹痛、腹泻、脉缓、进行性肌麻痹、心律紊乱、血钾明显降低等。可因心律紊乱和呼吸麻痹而死亡。肾脏可受损害。吸入粉尘可引起中毒，但消化道症状不明显。慢性影响：长期接触钡化合物的工人，可有无力、气促、流涎、口腔粘膜肿胀糜烂、鼻炎、结膜炎、腹泻、心动过速、血压增高、脱发等。', '对水生生物有害。', '本品易燃，高毒，具强腐蚀性、刺激性，可致人体灼伤。在潮湿空气中或酸雾中能发生强烈的化学反应，可能引起燃烧。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4653, 4760, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入后引起呼吸道刺激症状，可发生化学性肺炎、肺水肿；误服后可引起剧烈的胃肠刺激症状，有恶心、呕吐、腹泻、腹痛、里急后重、全身乏力、肌肉疼痛和虚脱等。慢性中毒：慢性中毒以肺气肿、肾功能损害(蛋白尿)为主要表现；其次还有缺铁性贫血、嗅觉减退或丧失等。', '对水生生物有害。', '本品不燃、有毒、具有刺激性。受高热分解产生有毒的硫化物烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4654, 4761, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '汞化合物剧毒。吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期接触可引起汞中毒，表现为神经系统损害、肾功能损害等。', '对水生生物有剧毒，对水生环境可能会引起长期有害作用。', '受高热分解产生有毒的汞蒸气和硫化物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4655, 4762, NULL, NULL, NULL, NULL, NULL, '第8.2类碱性腐蚀品；第4.2类自燃物品（无水物）', '吸入、食入、经皮吸收', '本品粉尘对眼、鼻、喉有刺激性，接触后引起喷嚏、咳嗽和喉炎等。高浓度吸入引起肺水肿。眼和皮肤接触可致灼伤。慢性影响：长期接触可发生鼻粘膜溃疡。对眼睛、皮肤和粘膜有强烈腐蚀性。', '对水生生物有害。', '本品易燃，具强腐蚀性、刺激性，可致人体灼伤。无水物为自燃物品，其粉尘易在空气中自燃。遇酸分解，放出剧毒的易燃气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4656, 4763, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '本品属低毒类。工业上常引起局部的刺激，未见钼中毒的报道。长期接触本品粉尘，部分工人可出现尘肺病变。', '对水生生物有害。', '与过氧化氢发生剧烈反应。与硝酸钠的混合物是一种炸药。受高热分解，放出有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4657, 4764, NULL, NULL, NULL, NULL, NULL, '第8.2类碱性腐蚀品', '吸入、食入、经皮吸收', '本品在胃肠道中能分解出硫化氢，口服后能引起硫化氢中毒。对皮肤和眼睛有腐蚀作用。', '对水生生物有害。', '本品易燃，具强腐蚀性、刺激性，可致人体灼伤。遇酸分解，放出剧毒的易燃气体。粉尘与空气可形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4658, 4765, NULL, NULL, NULL, NULL, NULL, '第2.1类易燃气体；第6.1类毒害品', '吸入、经皮吸收', '强烈的神经毒物，对粘膜有强烈刺激作用。高浓度吸入可致人闪电式死亡。长期接触可引起头痛、头晕、乏力、记忆力减退、多汗、皮肤潮湿、易激动等。对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用。', '对水生生物有害。', '易燃气体，与空气混合能形成爆炸性混合物，遇明火、高热极易引起燃烧爆炸。与浓硝酸、发烟硫酸或其它强氧化剂剧烈反应，发生爆炸。气体比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4659, 4766, NULL, NULL, NULL, NULL, NULL, '第4.2类自燃物品；第6.1类毒害品', '吸入、食入、经皮吸收', '属低毒类，具刺激作用。误服可引起胃肠刺激症状。长期吸入该粉尘，可能引起尘肺改变。对眼睛、皮肤和粘膜有刺激性。', '对水生生物有害。', '接触酸或酸气能产生有毒气体。受高热分解，放出有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4660, 4767, NULL, NULL, NULL, NULL, NULL, '第4.1类易燃固体', '吸入、食入、经皮吸收', '因其能在肠内部分转化为硫化氢而被吸收，故大量口服可致硫化氢中毒。急性硫化氢中毒的全身毒作用表现为中枢神经系统症状，有头痛、头晕、乏力、呕吐、共济失调、昏迷等。本品可引起眼结膜炎、皮肤湿疹。对皮肤有弱刺激性。生产中长期吸入硫粉尘一般无明显毒性作用。', '对水生生物有害。', '本品易燃。粉尘或蒸气与空气或氧化剂混合形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4661, 4768, NULL, NULL, NULL, NULL, NULL, '第8.2类碱性腐蚀品', '吸入、食入、皮肤接触、眼睛接触', '吸入、食入或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用和腐蚀性。吸入后可引起喉、支气管的炎症、水肿、痉挛，化学性肺炎或肺水肿。接触可引起灼伤。', '对水生生物有害。', '受热分解产生硫化氢等有毒气体。遇酸分解，放出剧毒的易燃气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4662, 4769, NULL, NULL, NULL, NULL, NULL, '第4.2类 自燃物品', '吸入、食入、经皮吸收', '对眼、皮肤、粘膜和上呼吸道有强烈刺激作用。吸入后，可引起喉、支气管的痉挛、炎症和水肿，化学性肺炎、肺水肿。中毒的症状可有烧灼感、喘息、喉炎、气短、头痛、恶心、呕吐、腹痛等。', '对水生生物有害。', '本品属自燃物品、高毒、具有强刺激性。暴露在空气中会发生氧化反应，甚至自燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4663, 4770, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '病例出现肝萎缩。慢性作用：早期有汞毒性神经衰弱综合征，同时发生震颤。对眼睛、皮肤、粘膜有刺激性。', '对水生生物有害。', '本品不燃、高毒。接触酸或酸气能产生有毒气体。受高热分解，放出高毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4664, 4771, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用。受热分解产生氮氧化物、氧化硫和氰化物等有毒气体。', '对水生生物有害。', '本品可燃、高毒、具有强刺激性。遇高热、明火或氧化剂，有引起燃烧的危险。受高热分解，放出高毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4665, 4772, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '其毒作用与氰化物不同。无剧毒。急性中毒：动物出现呼吸困难、痉挛、腹泻、血压降低，然后血压升高，心脏活动障碍，可在一昼夜内死亡。慢性中毒：出现甲状腺的损伤。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生生物有害。', '本品不燃、有毒。受热分解放出有毒的气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4666, 4773, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用。汞化合物具有蓄积性，长期接触可引起慢性汞中毒。主要损害神经系统、肾脏和消化系统。', '对水生生物有剧毒，对水生环境可能会引起长期有害作用。', '受热分解产生硫化氢、氰化氢等有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4667, 4774, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用。汞化合物具有蓄积性，长期接触可引起慢性汞中毒。主要损害神经系统、肾脏和消化系统。', '对水生生物有剧毒，对水生环境可能会引起长期有害作用。', '受热分解产生硫化氢、氰化氢等有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4668, 4775, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '呼吸抑制，常发生窒息、痉挛和死亡。对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用。', '对水生生物有害。', '本品易燃，有毒。遇明火、高热极易燃烧爆炸。受高热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4669, 4776, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '呼吸抑制，常发生窒息、痉挛和死亡。大鼠涂皮后可出现抑制和呼吸障碍，有时发生痉挛、死亡。对眼睛、皮肤、粘膜有刺激性。', '对水生生物有害。', '本品易燃，有毒。遇明火易燃。受高热燃烧并分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4670, 4777, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、皮肤接触、眼睛接触', '对皮肤、粘膜等组织有强烈的刺激和腐蚀作用。蒸气或雾可引起结膜炎、结膜水肿、角膜混浊，以致失明；引起呼吸道刺激，重者发生呼吸困难和肺水肿；高浓度引起喉痉挛或声门水肿而窒息死亡。口服后引起消化道烧伤以致溃疡形成；严重者可能有胃穿孔、腹膜炎、肾损害、休克等。皮肤灼伤轻者出现红斑、重者形成溃疡，愈后癍痕收缩影响功能。溅入眼内可造成灼伤，甚至角膜穿孔、全眼炎以至失明。慢性影响：牙齿酸蚀症、慢性支气管炎、肺气肿和肺硬化。', '对水体和土壤造成污染，对水生生物有害。', '本品助燃，具强腐蚀性、强刺激性，可致人体灼伤。遇水大量放热，可发生沸溅。与易燃物（如苯、糖和纤维素等）接触会发生剧烈反应，甚至引起燃烧。遇电石、高氯酸盐、雷酸盐、硝酸盐、苦味酸盐、金属粉末等猛烈反应，发生爆炸或燃烧。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4671, 4778, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '对人体有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。受热分解出有毒气体。', '对水生生物有害。该物质对环境可能有危害。', '遇明火、高热可燃。受高热分解，放出有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4672, 4779, NULL, NULL, NULL, NULL, NULL, '第5.2类有机过氧化物', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有刺激作用。重氮化合物具有潜在致癌性。', '对水生生物有害。该物质对环境可能有危害。', '遇热有火灾危险。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。遇明火、高热可燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4673, 4780, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '对人体有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。受热分解出有毒气体。', '对水生生物有剧毒，对水生环境可能会引起长期有害作用。', '遇明火、高热可燃。受高热分解，放出有毒的烟气。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4674, 4781, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吞食后有毒。跟皮肤接触有毒。对皮肤有刺激性。对眼睛有严重刺激性。吸入有毒。对呼吸道有刺激作用。长期或反复接触可能引起皮肤过敏。可能对血液造成影响。', '对水生生物有害。', '受热分解产生有毒的氮氧化物和硫氧化物。与氧化剂能发生强烈反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4675, 4782, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入粉尘或烟雾可引起呼吸道刺激、咳嗽、呼吸困难。对眼睛有严重刺激性，可引起结膜炎、角膜损伤。皮肤接触可引起严重灼伤。食入可引起消化道灼伤、恶心、呕吐、腹痛。具有溶血作用，可引起高铁血红蛋白血症。长期接触可引起贫血、黄疸。苯胺类化合物具有致癌性。', '对水生生物有剧毒。对水生环境可能造成长期不利影响。', '遇明火、高热可燃。受热分解产生有毒的氮氧化物和硫氧化物。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4676, 4783, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吞食后有毒。跟皮肤接触有毒。对皮肤有刺激性。跟皮肤接触可能会引起敏化作用。对眼睛有严重刺激性。吸入粉尘或烟雾可引起呼吸道刺激、咳嗽、呼吸困难。具有溶血作用，可引起高铁血红蛋白血症。长期接触可引起贫血、黄疸。', '对水生生物有剧毒。对水生环境可能造成长期不利影响。', '遇明火、高热可燃。受热分解产生有毒的氮氧化物和硫氧化物。具有爆炸性分解的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4677, 4784, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吞食后有毒。跟皮肤接触有毒。对皮肤有刺激性。对眼睛有严重刺激性。吸入有毒。对呼吸道有刺激作用。长期或反复接触可能引起皮肤过敏。可能对血液造成影响。', '对水生生物有剧毒，对水生环境可能会引起长期有害作用。', '受热分解产生有毒的氮氧化物和硫氧化物。与氧化剂能发生强烈反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4678, 4785, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '剧毒。对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用。吸入后可引起咳嗽、胸闷、气急、紫绀，可发生喉头水肿或支气管粘膜脱落致窒息，肺水肿，成人呼吸窘迫征，并可并发皮下气肿、气胸、纵隔气肿。误服灼伤消化道。可致眼、皮肤灼伤。慢性影响：长期接触低浓度，可有眼和上呼吸道刺激。', '对水生生物有剧毒。该物质对环境有危害，应特别注意对水体和土壤的污染。', '本品可燃，高毒，具强刺激性。遇明火、高热可燃。受热分解产生有毒的氧化硫气体。与氧化剂可发生反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4679, 4786, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '高毒。对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用。吸入、摄入或经皮肤吸收后对身体有害。可引起头痛、头晕、恶心、呕吐、腹痛和虚脱。长期或反复接触可引起神经系统损害。', '对水生生物有毒性。该物质对环境可能有危害，应特别注意对水体和土壤的污染。', '本品可燃，有毒，具强刺激性。遇明火、高热可燃。受热分解产生有毒的氧化硫气体。与氧化剂可发生反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4680, 4787, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '急性中毒：吸入可引起呼吸道刺激症状，可发生化学性肺炎，肺水肿；误食后可引起剧烈的胃肠道刺激症状，有恶心、呕吐、腹泻、腹痛、里急后重、全身乏力、肌肉疼痛和虚脱等。慢性中毒：慢性中毒以肺气肿、肾功能损害（蛋白尿）为主要表现，其次还有缺铁性贫血、嗅觉减退或丧失等。镉及其化合物属致癌物。', '对水生生物有剧毒，对水生环境可能造成长期不利影响。', '本品不燃、有毒、具有刺激性。受热分解产生有毒的硫化物烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4681, 4788, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '汞化合物具有高毒性。吸入粉尘或烟雾可引起呼吸道刺激、咳嗽、呼吸困难。慢性中毒表现为神经衰弱综合征、易兴奋症、震颤、口腔炎、齿龈有汞线等。对眼睛有刺激性。皮肤接触可引起刺激和过敏。食入可引起消化道刺激、恶心、呕吐、腹痛。汞化合物对神经系统、肾脏有严重毒性作用。', '对水生生物有剧毒。对水生环境可能造成长期不利影响。汞具有生物富集性。', '本身不燃，但受热分解产生有毒的汞蒸气和硫氧化物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4682, 4789, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入粉尘或烟雾可引起呼吸道刺激、咳嗽、呼吸困难。对眼睛有严重刺激性，可引起结膜炎、角膜损伤。皮肤接触可引起过敏性皮炎、接触性皮炎。食入可引起消化道刺激、恶心、呕吐、腹痛。钴化合物对心脏、甲状腺、血液系统有毒性作用。长期接触可引起过敏反应、哮喘。', '对水生生物有害。避免释放到环境中。', '本身不燃，但受热分解产生有毒的硫氧化物。具有刺激性和毒性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4683, 4790, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吞食后有毒。跟皮肤接触有毒。对眼睛有严重刺激性。吸入有毒。可引起皮肤过敏反应。长期或反复接触可能对器官造成伤害。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '遇明火、高热可燃。受热分解产生有毒的氮氧化物和硫氧化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4684, 4791, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吞食后有剧毒。吸入有剧毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。可引起肌肉痉挛、惊厥、呼吸麻痹等中毒症状。', '对水生环境可能会引起长期有害作用。', '遇明火、高热可燃。受热分解产生有毒的氮氧化物和硫氧化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4685, 4792, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '摄入大量本品可引起恶心、呕吐和眩晕。镍及其盐类为确认的职业性致癌物。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。皮肤接触可引起过敏性皮炎。长期接触可引起慢性鼻炎、咽炎、支气管炎。镍化合物可引起肺癌和鼻咽癌。', '对水生生物有剧毒。对水生环境可能造成长期不利影响。', '本品不燃、具有刺激性。受热分解产生有毒的硫化物烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4686, 4793, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '属高毒类。中毒表现有头痛、头晕、全身酸痛、疲乏无力、心悸、低热，吸入可引起化学性支气管炎、化学性肺炎，皮肤接触可引起接触性皮炎、铍溃疡和皮肤肉芽肿。铍及其化合物属致癌物。', '对水生生物有毒。对水生环境可能造成长期不利影响。', '本品不燃、高毒、为致癌物。受热分解产生有毒的硫氧化物和铍化合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4687, 4794, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入粉尘或烟雾可引起呼吸道刺激、咳嗽、呼吸困难。对眼睛有严重刺激性，可引起结膜炎、角膜损伤。皮肤接触可引起过敏性皮炎、接触性皮炎。食入可引起消化道刺激、恶心、呕吐、腹痛。铍化合物具有高度毒性，可引起铍肺病、铍肉芽肿病。长期接触可引起肺癌。', '对水生生物有剧毒。对水生环境可能造成长期不利影响。', '本身不燃，但受热分解产生有毒的硫氧化物。具有刺激性和毒性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4688, 4795, NULL, NULL, NULL, NULL, NULL, '第8类腐蚀性物质', '吸入、食入、皮肤接触、眼睛接触', '损害造血、神经、消化系统及肾脏。职业中毒主要为慢性。神经系统主要表现为神经衰弱综合征，周围神经病(以运动功能受累较明显)，重者出现铅中毒性脑病。消化系统表现为齿龈铅线、食欲不振、恶心、腹胀、腹泻或便秘；腹绞痛见于中等及较重病例。对眼睛有严重刺激性，可引起结膜炎、角膜损伤。皮肤接触可引起严重灼伤。', '对水生生物有剧毒。对水生环境可能造成长期不利影响。', '本身不燃，但受热分解产生有毒的硫化物烟气。具有强腐蚀性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4689, 4796, NULL, NULL, NULL, NULL, NULL, '第8类腐蚀性物质', '吸入、食入、皮肤接触、眼睛接触', '吸入粉尘或烟雾可引起呼吸道刺激、咳嗽、呼吸困难。对眼睛有严重刺激性，可引起结膜炎、角膜损伤。皮肤接触可引起严重灼伤。食入可引起消化道灼伤、恶心、呕吐、腹痛。具有腐蚀性和刺激性。', '对水生生物有害。避免释放到环境中。', '本身不燃，但受热分解产生有毒的硫氧化物和氮氧化物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4690, 4797, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、经皮吸收', '本品对眼睛、皮肤、粘膜和上呼吸道具强烈刺激作用和腐蚀性。可引起眼部严重损伤、皮肤灼伤、呼吸道刺激。误食可引起消化道灼伤。', '对水生生物有毒性。对水生环境可能会引起有害作用。', '本品不燃，具有腐蚀性、强刺激性，可致人体灼伤。受高热分解，放出有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4691, 4798, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、经皮吸收', '本品对眼睛、皮肤、粘膜和上呼吸道具强烈刺激作用和腐蚀性。可引起眼部严重损伤、皮肤灼伤、呼吸道刺激。误食可引起消化道灼伤。', '对水生生物有毒性。对水生环境可能会引起有害作用。', '本品不燃，具有腐蚀性、强刺激性，可致人体灼伤。受高热分解，放出有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4692, 4799, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '高毒。对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用。慢性影响：神经衰弱综合征。可引起中枢神经系统损害。', '对水生生物有害。对环境有危害。', '本品可燃、高毒、具有刺激性。遇明火、高热可燃。加热分解产生毒性气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4693, 4800, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吞食后有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。汞化合物可引起中枢神经系统损害、肾功能损害和消化系统损害。长期接触可引起慢性汞中毒，表现为震颤、牙龈炎、记忆力减退等症状。', '对水生生物有剧毒，对水生环境可能会引起长期有害作用。该物质对环境有危害，应特别注意对水体和土壤的污染。', '受热分解产生有毒的氧化硫和汞蒸气。与氧化剂可发生反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4694, 4801, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入粉尘或烟雾可引起呼吸道刺激、咳嗽、结痰，吸入较高浓度导致肺炎或肺水肿，甚至死亡。对眼睛有严重刺激性，可引起结膜炎、角膜损伤。皮肤接触可引起刺激和过敏。食入可引起消化道刺激、恶心、呕吐、腹痛。钒化合物对呼吸系统、肾脏、肝脏有毒性作用。', '对水生生物有害。避免释放到环境中。', '本身不燃，但受热分解产生有毒的硫氧化物。与氧化剂接触可能发生剧烈反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4695, 4802, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品（剧毒）', '吸入、食入、皮肤接触、眼睛接触', '亦有毒作用。急性中毒患者在吸入本品后出现明显的窒息性呼吸功能障碍，伴消化系统功能紊\n乱及腰骶部神经根疼痛。治愈者可残留肺部纤维化病变。', '无资料', '本品不燃、剧毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4696, 4803, NULL, NULL, NULL, NULL, NULL, '第2.3类 有毒气体', '吸入、皮肤接触、眼睛接触', '对眼睛、皮肤、粘膜和呼吸道有强烈的刺激作用。吸入后可能因咽喉、支气管的痉挛、水肿，化学性肺炎、肺水肿而致死。症状有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。高浓度接触可引起肺水肿、呼吸衰竭。长期接触可引起慢性支气管炎、肺纤维化。', '该物质对水生生物有毒性。避免释放到环境中。应特别注意避免污染水体和土壤。', '本品有毒、刺激性。遇水反应生成水合六氟丙酮，并放出热量。遇醇类、胺类等活性氢化合物发生剧烈反应。遇强氧化剂有发生火灾爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4697, 4804, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '对皮肤有刺激性。对眼睛有严重刺激性。可能有损伤胎儿或胚胎的危险。短期暴露有严重危害。', '对水生生物有毒性。', '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4698, 4805, NULL, NULL, NULL, NULL, NULL, '第2.2类 不燃气体', '吸入', '生产工人短时间吸入较多的六氟丙烯，有头昏、无力、睡眠欠佳等症状。', '对大气可造成污染。', '本品不燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4699, 4806, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入', '有毒。误服或吸入粉尘会中毒。与酸类反应，散发出刺激性和腐蚀性氟化氢和四氟化硅。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生生物有剧毒。该物质对环境有危害，应特别注意对水体的污染。避免该物质进入地下水、地表水和土壤。', '本品不燃、有毒。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4700, 4807, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入', '分解产物氟化氢及四氟化硅有刺激作用。', '无资料', '本品不燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4701, 4808, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入', '有毒。误服或吸入粉尘会中毒。遇热分解释出有毒的氟和氧化锌烟雾。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生生物有剧毒。该物质对环境有危害，应特别注意对水体的污染。避免该物质进入地下水、地表水和土壤。', '本品不燃、有毒。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4702, 4809, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入、食入、经皮吸收', '有毒，误服会中毒。对皮肤、眼睛和粘膜会起严重烧伤。遇热分解释出高毒的氟化物和氧化磷烟雾。', '无资料', '本品不燃、有毒、具有强腐蚀性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4703, 4810, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '吸入低浓度本品导致白细胞及血小板减少。接触本品人员血液的凝血能力下降。本品对皮肤有刺激作用，其蒸气或雾对眼睛、粘膜和上呼吸道有刺激作用。', '该物质对环境有危害，应特别注意对水体的污染。', '易燃，遇明火、高热有燃烧爆炸危险。受热分解产生有毒的氟化氢气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4704, 4811, NULL, NULL, NULL, NULL, NULL, '第2.3类 有毒气体', '吸入\n吸入高浓度可引起头痛、头晕、无力、恶心、呕吐、呼吸困难、呼气蒜臭味、口内金属味等', '症状，严重时肝、肾受损。对皮肤、眼睛、粘膜有强烈刺激性。', '无资料', '本品不燃、有毒、强腐蚀性、强刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4705, 4812, NULL, NULL, NULL, NULL, NULL, '第2.2类 不燃气体', '吸入', '纯品基本无毒。但产品中如混杂低氟化硫、氟化氢，特别是十氟化硫时，则毒性增强。在密闭空间中可能导致窒息。接触后可能引起头痛、头晕、呼吸困难。在高浓度环境下，可能导致窒息，甚至死亡。', '该物质是一种强效温室气体，对全球变暖有显著影响。其全球变暖潜势（GWP）约为23500（以CO2为基准）。避免释放到环境中。应特别注意避免排放到大气中。', '本品不燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4706, 4813, NULL, NULL, NULL, NULL, NULL, '第2.3类 有毒气体', '吸入', '对粘膜有强烈刺激作用。动物吸入引起呼吸困难，可因肺水肿而致死。接触后可引起头痛、恶心、眩晕、呼吸困难。在高浓度环境下，可能导致肺水肿、呼吸衰竭，甚至死亡。对眼睛、皮肤和呼吸道有刺激性。', '该物质对水生生物有极高毒性。避免释放到环境中。应特别注意避免排放到水体和土壤中。', '本品不燃、高毒、刺激性。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4707, 4814, NULL, NULL, NULL, NULL, NULL, '第7类 放射性物品', '吸入、食入、皮肤接触、眼睛接触、辐射暴露', '铀及其化合物具有放射性危害和化学毒性双重危害。六氟化铀可致严重的呼吸道和肾脏损害。急性中毒症状包括：剧烈咳嗽、呼吸困难、胸痛、发绀、肺水肿。严重病例出现蛋白尿、氮质血症、急性肾功能衰竭。对眼有强烈刺激性，接触后立即出现剧烈疼痛、流泪、畏光，严重时角膜上皮坏死脱落形成溃疡，可导致失明。可致皮肤灼伤，接触部位出现红肿、水泡、坏死。具有放射性危害，长期接触可导致辐射病、骨髓抑制、白血病等。六氟化铀遇水分解产生剧毒的氟化氢气体，可引起严重的化学灼伤和系统性氟中毒。氟化氢中毒可导致低钙血症、心律失常、呼吸衰竭甚至死亡。放射性危害包括：急性放射病、慢性放射病、致癌效应（特别是肺癌、骨癌）、遗传效应。', '对环境有严重危害。具有放射性污染风险，可对土壤、水体、大气造成长期污染。放射性物质在环境中长期存在，通过食物链富集，对生态系统和人类健康造成长期影响。六氟化铀遇水分解产生的氟化氢对水生生物有剧毒，可导致水生生物大量死亡。铀化合物在环境中迁移转化，可污染地下水和地表水。放射性污染难以清除，需要专业处理。对植物生长有抑制作用，可导致土壤微生物群落结构改变。', '本身不燃，但受高热、明火会产生剧毒的氟化氢蒸气和放射性气溶胶。具有强腐蚀性，遇水分解产生剧毒和腐蚀性气体。容器受热可能发生爆炸。与水、潮气反应剧烈，产生氟化氢气体和铀酰化合物，反应放热。与有机物、还原剂接触可能发生剧烈反应。火灾时产生剧毒、腐蚀性和放射性烟雾，对消防人员和周围环境造成严重危害。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4708, 4815, NULL, NULL, NULL, NULL, NULL, '第2.2类 不燃气体', '吸入', '本品可引起快速窒息。接触后引起头痛、恶心和眩晕。在高浓度环境下，可能导致缺氧、意识丧失，甚至死亡。对眼睛、皮肤和呼吸道无刺激性。', '该物质属于温室气体，对全球气候变暖有影响。避免释放到环境中。应特别注意避免排放到大气中。', '本品不燃，但在高温或高压下容器可能发生爆炸。遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4709, 4816, NULL, NULL, NULL, NULL, NULL, '第4.1类易燃固体', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期反复接触可引起皮肤过敏。', '对水生生物有毒作用。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4710, 4817, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收后对身体有害。对皮肤有刺激性。其蒸气或雾对眼睛、粘膜和上呼吸道有刺激性。', '对水生生物有毒性。该物质对环境可能有危害，对水体应给予特别注意。避免该物质进入土壤、地下水或地表水体。在环境中可能具有挥发性，可在大气中降解。', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4711, 4818, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入 食入 经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。高浓度蒸气可引起麻醉作用。长期接触可能对皮肤和呼吸道产生刺激。', '对环境有危害，对水体可造成污染。该物质在环境中不易降解，可能对水生生物产生毒性影响。', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4712, 4819, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收。六氯-1,3-丁二烯可通过呼吸道吸入、皮肤接触和食入等途径进入人体。吸入高浓度蒸气可引起急性中毒，主要损害中枢神经系统、肝脏和肾脏。皮肤接触可引起刺激和灼伤。食入可引起胃肠道刺激和全身中毒症状。', '急性毒性：属高毒类物质，对中枢神经系统、肝脏、肾脏有严重损害。吸入高浓度蒸气可引起头痛、头晕、乏力、恶心、呕吐、腹痛、腹泻等症状，严重者可出现意识障碍、抽搐、昏迷，甚至死亡。皮肤接触可引起红斑、水疱、灼伤等。眼睛接触可引起结膜炎、角膜损伤。食入可引起口腔、咽喉灼伤，恶心、呕吐、腹痛、腹泻等胃肠道症状。慢性毒性：长期反复接触可引起慢性中毒，主要表现为肝脏损害（肝功能异常、脂肪肝、肝硬化）、肾脏损害（蛋白尿、肾功能不全）、神经系统损害（头痛、头晕、记忆力减退、周围神经病变）和皮肤损害（接触性皮炎、皮肤干燥、皲裂）。六氯-1,3-丁二烯具有潜在的致癌性和生殖毒性，可能对人类致癌（IARC 2B组）。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。吸入可引起喉、支气管炎症、痉挛，化学性肺炎、肺水肿等。接触后可出现烧灼感、咳嗽、头痛、恶心和呕吐。', '对水生生物有极高毒性，可能对水生环境造成长期不利影响。在环境中持久存在，不易降解，具有生物富集潜力。对土壤和地下水有污染风险。对大气环境有潜在影响，蒸气可参与光化学反应。对鸟类和陆生生物也有毒性。属于持久性有机污染物（POPs）候选物质，对生态系统和人类健康构成潜在威胁。', '本品可燃、有毒、具有强刺激性。遇明火、高热可燃。受热分解产生有毒的氯化氢烟气。与氧化剂接触可发生剧烈反应，甚至爆炸。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。燃烧时产生大量浓烟和有毒气体，包括氯化氢、一氧化碳、二氧化碳、光气等。在密闭空间内，蒸气与空气可形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4713, 4820, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入', '接触后引起眼刺激、烧灼感、口鼻发干、疲乏、头痛、恶心等。中毒时可影响肝脏、中枢神经\n系统和心血管系统。可致皮肤溃疡。', NULL, '本品可燃，为可疑致癌物，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4714, 4821, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '吞咽会中毒。接触皮肤可能有害。对皮肤、眼睛和呼吸道有刺激性。过量接触需采取特殊急救措施和进行医疗随访。', '对水生生物有毒。', '本品可燃、具有刺激性。遇明火、高热可燃。受高热分解，放出有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4715, 4822, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', NULL, '无资料', '本品可燃、剧毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4716, 4823, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '长期、反复、过量与皮肤接触可引起皮炎（痤疮样皮损）且奇痒。至今未见全身中毒的病例。', '对水生生物有毒，在环境中持久存在，可能发生生物蓄积。', '本品可燃，接触可引起皮炎，奇痒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4717, 4824, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '步态不稳、后肢轻瘫；亦可见痉挛、心率加快、昏睡、腹泻、食欲减退等。', '对水生生物有毒，在环境中持久存在，可能发生生物蓄积。', '本品不燃，有毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4718, 4825, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触', '剧毒。误服或吸入可引起呕吐、腹痛、休克、便血、喉和胃疼痛、舌头肿大起泡、咽吞困难、多涎、尿慢疼痛、口渴、胡说、晕厥、破伤风性痉挛。刺激眼睛，引起眼睑肿。皮肤接触后，先肿胀，24小时后起水疱。', '对水生生物有剧毒。该物质对环境有危害，应特别注意对水体的污染。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4719, 4826, NULL, NULL, NULL, NULL, NULL, '第1.1类爆炸品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生生物有毒作用。', '通过打击、摩擦、火灾或其他着火源有极大爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4720, 4827, NULL, NULL, NULL, NULL, NULL, '第1类 爆炸品', '吸入 食入 经皮吸收', '吸入、食入、经皮吸收可引起中毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期接触可引起神经系统、血液系统损害。', '对水生生物毒性极大并具有长期持续影响。本品属于硝基芳香族化合物，该类化合物具有生物毒性大的特点，被许多国家列为优先控制的污染物。对水体可造成污染。', '本品属爆炸品，可燃，有毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4721, 4828, NULL, NULL, NULL, NULL, NULL, '第1类 爆炸品', '吸入 食入 经皮吸收', '吸入、食入、经皮吸收可引起中毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期接触可引起神经系统、血液系统损害。', '对水生物有毒，对水生环境可能会引起长期有害作用。', '通过打击、摩擦、火灾或其他着火源有极大爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4722, 4829, NULL, NULL, NULL, NULL, NULL, '第l类 爆炸品', '吸入 食入', '吸入或误服会中毒。参见芳烃酌硫化物及硝基化合物。', '无资料', '本品属爆炸品、易燃', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4723, 4830, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '对眼睛有刺激性。吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入本品可能对个体健康有害。长期接触可能对肝脏、甲状腺和神经系统造成损害。属于持久性有机污染物，具有生物富集性。', '对水生生物有极高毒性。在环境中持久存在，不易降解，属于持久性有机污染物（POPs）。具有生物富集潜力，可能对生态系统造成长期危害。', '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。受热分解产生有毒的溴化氢气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4724, 4831, NULL, NULL, NULL, NULL, NULL, '危险货物分类：第6.1类毒害品（UN编号：UN 3077，环境危害物质，固体，毒性物质）', '暴露途径：吸入粉尘、食入、经皮吸收。主要危险来自粉尘吸入和误食。', '健康危害：对眼睛有刺激性，可能引起眼部红肿、疼痛和流泪。吸入粉尘可能引起呼吸道刺激，导致咳嗽、呼吸困难、喉咙疼痛。长期或反复接触可能对肝脏、甲状腺、神经系统和生殖系统造成损害。动物实验表明，六溴环十二烷具有肝毒性、甲状腺毒性、神经毒性和生殖毒性。可能影响内分泌系统，干扰激素平衡。国际癌症研究机构（IARC）将其列为2B类致癌物（可能对人类致癌）。属于持久性有机污染物（POPs），具有生物富集性，在生物体内长期累积。', '环境危害：对水生生物有极高毒性，对水生环境可能会引起长期有害作用。在环境中持久存在，不易降解，属于持久性有机污染物（POPs）。具有生物富集潜力，在食物链中累积，可能对生态系统造成长期危害。可通过大气、水体和土壤进行长距离迁移，污染远离污染源的地区。对土壤生物也有毒性。可能对鸟类和哺乳动物造成内分泌干扰效应。', '火灾爆炸危险：本身不燃，但受热分解会产生有毒的溴化氢气体和溴化物。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。分解产物包括溴化氢、溴化物、一氧化碳、二氧化碳等有毒气体。在火灾情况下，会产生大量有毒烟雾，对消防人员和周围人员构成严重威胁。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4725, 4832, NULL, NULL, NULL, NULL, NULL, '危险货物分类：第6.1类毒害品（UN编号：UN 3151，毒性物质，有机的，固体）', '暴露途径：吸入粉尘、食入、经皮吸收。主要危险来自粉尘吸入和误食。', '健康危害：对眼睛有刺激性，可能引起眼部红肿、疼痛和流泪。吸入粉尘可能引起呼吸道刺激，导致咳嗽、呼吸困难、喉咙疼痛。长期或反复接触可能对肝脏、甲状腺、神经系统和生殖系统造成损害。动物实验表明，六溴联苯具有肝毒性、甲状腺毒性、神经毒性和生殖毒性。可能影响内分泌系统，干扰激素平衡。国际癌症研究机构（IARC）将其列为2B类致癌物（可能对人类致癌）。属于持久性有机污染物（POPs），具有生物富集性，在生物体内长期累积。', '环境危害：对水生生物有极高毒性，对水生环境可能会引起长期有害作用。在环境中持久存在，不易降解，属于持久性有机污染物（POPs）。具有生物富集潜力，在食物链中累积，可能对生态系统造成长期危害。可通过大气、水体和土壤进行长距离迁移，污染远离污染源的地区。对土壤生物也有毒性。可能对鸟类和哺乳动物造成内分泌干扰效应。', '火灾爆炸危险：本身不燃，但受热分解会产生有毒的溴化氢气体和溴化物。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。分解产物包括溴化氢、溴化物、一氧化碳、二氧化碳等有毒气体。在火灾情况下，会产生大量有毒烟雾，对消防人员和周围人员构成严重威胁。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4726, 4833, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激性。吸入可引起喉、支气管的炎症、水肿、痉挛，化学性肺炎、肺水肿。有致敏作用。', '对水生生物有毒性。可能对环境造成危害。', '遇明火、高热可燃。受热分解，放出有毒的氮氧化物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4727, 4834, NULL, NULL, NULL, NULL, NULL, '第4.1类易燃固体', '吸入、食入、皮肤接触、眼睛接触', '生产条件下，主要引起皮炎和湿疹。皮疹多为多形性，奇痒，初起局限于接触部位，以后可蔓延，甚至遍及全身。对皮肤、眼睛有刺激性。', '对水生生物有毒性。可能对环境造成危害。', '本品易燃，具腐蚀性，可致人体灼伤，接触可引起皮炎，奇痒。遇明火、高热有燃烧爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4728, 4835, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入', '吸入、摄入或经皮肤吸收对身体有害。对皮肤、粘膜和眼睛有强烈刺激性。可致皮肤灼伤。吸入可引起喉、支气管的炎症、水肿、痉挛，化学性肺炎、肺水肿。', '对水生生物有毒性。可能对环境造成危害。', '遇明火、高热易燃。受热分解，放出有毒的氮氧化物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4729, 4836, NULL, NULL, NULL, NULL, NULL, '第4.3类遇湿易燃物品', '吸入食入\n长期吸入可致铝尘肺。表现为消瘦、极易疲劳、呼吸困难、咳嗽、咳痰等。溅入眼内，', '可发生局灶性坏死，角膜色素沉着，晶体膜改变及玻璃体混浊。对鼻、口、性器官粘膜\n有刺激性，甚至发生溃疡。可引起痤疮、湿疹、皮炎。', '无资料', '本品遇湿易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4730, 4837, NULL, NULL, NULL, NULL, NULL, '皮肤腐蚀/刺激，类别1；眼损伤/眼刺激，类别1。', '吸入、食入、皮肤接触、眼睛接触\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4731, 4838, NULL, NULL, NULL, NULL, NULL, '第2.3类 有毒气体', '吸入、皮肤接触、眼睛接触', '对眼、呼吸道粘膜有刺激作用。急性中毒：轻度者有流泪、咳嗽、咳少量痰、胸闷，出现气管炎和支气管炎的表现；中度中毒发生支气管肺炎或间质性肺水肿，病人除有上述症状的加重外，出现呼吸困难、轻度紫绀等；重者发生肺水肿、昏迷和休克，可出现气胸、纵隔气肿等并发症。吸入极高浓度的氯气，可引起迷走神经反射性心跳骤停或喉头痉挛而发生\"电击样\"死亡。皮肤接触液氯或高浓度氯，在暴露部位可有灼伤或急性皮炎。慢性影响：长期低浓度接触，可引起慢性支气管炎、支气管哮喘等；可引起职业性痤疮及牙齿酸蚀症。', '对环境有危害，对水体、土壤和大气可造成污染。', '本品助燃，剧毒，具刺激性。氯气能与许多化学品如乙炔、松节油、乙醚、氨、燃料气、烃类、氢气、金属粉末等猛烈反应发生爆炸或生成爆炸性物质。它几乎对金属和非金属都有腐蚀作用。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4732, 4839, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '对中枢神经系统有抑制和麻醉作用；对皮肤和粘膜有刺激性。急性中毒：接触高浓度可引起麻醉症状，甚至昏迷。脱离现场，积极救治后，可较快恢复，但数日内仍有头痛、头晕、无力、嗜睡等症状。液体对皮肤有轻度刺激性。慢性影响：长期或反复接触可引起头痛、头晕、乏力、失眠、记忆力减退等神经衰弱综合征。', '对水生生物有毒性，可能对水体环境产生长期不良影响。', '易燃，遇明火、高热有燃烧爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4733, 4840, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、经皮吸收', '具强刺激性的毒物。对眼睛、皮肤和粘膜有腐蚀性。受热分解放出氯烟雾。吸入可引起呼吸道刺激，高浓度可致肺水肿。皮肤接触可引起灼伤。眼睛接触可引起严重灼伤。', '对水生生物有毒性，可能对水体环境产生长期不良影响。', '遇明火、高热可燃。受热分解产生有毒的氯化氢和氧化硅烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4734, 4841, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。可引起过敏反应。', '无资料', '本品不燃、有毒、具有腐蚀性、刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4735, 4842, NULL, NULL, NULL, NULL, NULL, '侵入途径： 吸入，皮肤及眼睛接触', '吸入，皮肤及眼睛接触', '露后，心跳加快、胸痛、低血压或高血压、呼吸短促，甚至瘫痪；接触后，严重刺激灼伤\n皮肤、眼、粘膜', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4736, 4843, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入 食入 经皮吸收', NULL, '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4737, 4844, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入 食入 经皮吸收', NULL, '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4738, 4845, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入经皮吸收\n吸入、口服或经皮肤吸收对身体有害，对眼睛、皮肤、粘膜和呼吸道有刺激作用。中毒表', '现可有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4739, 4846, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '剧毒。与皮肤接触后可使皮肤呈黑色；受高热后放出有毒气体。', '无资料', '本品不燃、剧毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4740, 4847, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入', '热解能放出非常有毒的氟、氯、溴离子烟雾。', '无资料', '本品不燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4741, 4848, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '中毒，表现有：神经衰弱综合征；易兴奋症；震颤；口腔炎、齿龈有汞线等。', '无资料', '本品不燃、高毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4742, 4849, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入', '对各种肌肉组织产生刺激和兴奋作用。对中枢神经系统先是兴奋，后转为抑制。长期接触，对上呼吸道和眼结膜有刺激作用，引起口腔炎、结膜炎、支气管炎、食欲不振及消化不良等症状，或有气短、心悸、血压升高、传导功能障碍等。摄入引起恶心、呕吐、腹痛、腹泻，继而头晕、耳鸣、四肢无力、心悸、气短，重者可因呼吸麻痹而致死。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4743, 4850, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后会中毒。吸入时，神经系统最早受损；误服，首先出现消化道症状。消化道症状有上腹灼痛、恶心、呕吐、食欲不振、腹泻、口腔炎、甚至便血。神经系统症状有头痛、头晕、乏力、嗜睡、甚至昏迷。可致肾脏损害。', '无资料', '本品可燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4744, 4851, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n持续吸入高浓度蒸气可出现呼吸道炎症，甚至发生肺水肿。蒸气对眼有刺激性，液体溅入眼内\n引起结膜和角膜蛋白变性。皮肤接触可引起红斑、大疱，或发生湿疹。口服引起胃肠道刺激反', NULL, '无资料', '本品可燃，高毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4745, 4852, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收', '对眼睛、皮肤、粘膜有刺激性，本品是具腐蚀性的毒物。', '无资料', '本品不燃、有毒、具有强腐蚀性、刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4746, 4853, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有剧毒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4747, 4854, NULL, NULL, NULL, NULL, NULL, '第4.2类 自燃物品', '吸入 食入', '感和剧烈疼痛，但无全身中毒表现。目前，未见慢性影响报道。', '无资料', '本品属自燃物品、有毒、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4748, 4855, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品；皮肤腐蚀/刺激，类别 2；严重眼损伤/眼刺激，类别 2A；生殖毒性，类别 1B；特异性靶器官毒性-反复接触，类别 1；致癌性，类别 1B；危害水生环境-急性毒性，类别 1；危害水生环境-慢性毒性，类别 1', '吸入、食入、皮肤接触、眼睛接触。', '急性中毒：吸入可引起呼吸道刺激症状，可发生化学性肺炎、肺水肿；误食后可引起急剧的胃肠道刺激症状，有恶心、呕吐、腹痛、腹泻、里急后重、全身乏力、肌肉疼痛和虚脱等，重者可因呼吸衰竭而死亡。慢性中毒：长期接触可引起肺气肿、肾功能损害、嗅觉丧失、贫血、骨骼改变（镉中毒性骨痛病）等。镉及其化合物为已知的人类致癌物，可引起肺癌和前列腺癌。', '对水生生物有极高毒性。在环境中持久存在，不易降解。对土壤和水体造成长期污染。镉具有生物富集性，可通过食物链富集。', '本品不燃，有毒，具刺激性。受高热分解产生有毒的腐蚀性烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4749, 4856, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n汞离子可使含巯基的酶丧失活性，失去功能；还能与酶中的氨基、二巯基、羧基、羟基以及细\n胞内的磷酰基结合，引起相应的损害。急性中毒：有头痛、头晕、乏力、失眠、多梦、口腔炎、\n发热等全身症状。可有食欲不振、恶心、腹痛、腹泻等。部分患者皮肤出现红色斑丘疹。严重', NULL, NULL, '本品不燃，剧毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4750, 4857, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤和粘膜有刺激作用，长时间或反复接触可引起过敏反应。大量接触可抑制红细胞的产生。', '无资料', '本品不燃、有毒、具有刺激性、致敏性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4751, 4858, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有剧毒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4752, 4859, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入 食入', '本品蒸气有毒。本品经受热分解出有毒气体。对眼睛和皮肤可能有刺激作用。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4753, 4860, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', NULL, '无资料', '本品可燃、高毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4754, 4861, NULL, NULL, NULL, NULL, NULL, '侵入途径：', '吞食后有剧毒。会引起皮肤烧伤，有严重损害眼睛的危险。有严重损害眼睛的危险。长期', NULL, '对水生物有剧毒,对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4755, 4862, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、皮肤接触、眼睛接触', '汞化合物剧毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。吸入、摄入或经皮肤吸收后可引起中毒。可引起神经系统损害、肾脏损害等。慢性中毒可引起震颤、牙龈炎、记忆力减退等症状。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '受热或接触火焰可能会产生膨胀或爆炸性分解。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4756, 4863, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品；皮肤致敏作用，类别1；呼吸敏化作用，类别1；生殖细胞致突变性，类别2；致癌性，类别1A；生殖毒性，类别1B；特异性靶器官毒性-反复接触，类别1', '吸入、食入、皮肤接触、眼睛接触', '吸入粉尘或烟雾可能导致过敏、哮喘病症状或呼吸困难。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期接触可引起皮炎、湿疹、呼吸道炎症。镍化合物是已确认的人类致癌物，可导致肺癌和鼻咽癌。', '对水生生物有极高毒性。对水生环境可能会造成长期不利影响。在环境中可能持久存在。', '不燃。受热分解产生有毒的氯化物烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4757, 4864, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '高毒类。短期、大量的接触，可引起急性铍病，主要表现为急性化学性肺炎。粉尘可经伤口进入，使伤口久不愈合。皮肤接触可引起接触性皮炎或过敏性皮炎。铍及其化合物属致癌物。', '对环境有危害，对水体和土壤可造成污染。对水生生物有极高毒性。', '本品不燃、有毒、为致癌物', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4758, 4865, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入', '见溃疡或混浊。皮肤直接接触可出现大量粟粒样红色小丘疹而呈潮红痛热。慢性影响：长期较\n高浓度接触，可引起慢性支气管炎、胃肠功能障碍及牙齿酸蚀症。', NULL, '本品不燃，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4759, 4866, NULL, NULL, NULL, NULL, NULL, '第2.3类 有毒气体', '吸入 食入 经皮吸收', '流泪、咳嗽、呼吸困难、肺水肿，甚至迅速死亡。慢性影响：可有不同程度的呕吐、腹泻、尿\n痛、咳嗽、头痛、体重减轻等。', NULL, '本品不燃，剧毒，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4760, 4867, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入该物质可能会引起对健康有害的影响。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4761, 4868, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入', '本品毒作用及中毒症状目前不详。硒化合物对呼吸道、皮肤和粘膜有强烈刺激性。', '无资料', '本品不燃，高毒，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4762, 4869, NULL, NULL, NULL, NULL, NULL, '第8.3类 其它腐蚀品', '吸入 食入 经皮吸收', '本品有强烈的腐蚀性和刺激性。吸入粉尘可引起呼吸道刺激、咳嗽、呼吸困难。食入可引起口腔、咽喉、食道和胃部严重灼伤，严重者可致死。皮肤接触可引起灼伤、红肿、疼痛。眼睛接触可引起严重灼伤、角膜损伤。', '对水生生物有毒性。可能对水环境造成长期不良影响。', '本品不燃、有毒、具有腐蚀性、刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4763, 4870, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', NULL, '遇热有火灾危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4764, 4871, NULL, NULL, NULL, NULL, NULL, '第4.1类自反应物质和混合物', '吸入、食入、皮肤接触、眼睛接触', '吸入、食入或皮肤接触有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期或反复接触可能对器官造成损害。', '对水生生物有害。可能对水生环境造成长期不利影响。', '遇热、摩擦、撞击或接触火焰可能发生爆炸或分解。受热分解产生有毒气体。具有自反应性，可能发生放热反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4765, 4872, NULL, NULL, NULL, NULL, NULL, '第4.1类自反应物质和混合物', '吸入、食入、皮肤接触、眼睛接触', '吸入、食入或皮肤接触有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期或反复接触可能对器官造成损害。', '对水生生物有害。可能对水生环境造成长期不利影响。', '遇热、摩擦、撞击或接触火焰可能发生爆炸或分解。受热分解产生有毒气体。具有自反应性，可能发生放热反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4766, 4873, NULL, NULL, NULL, NULL, NULL, '第4.1类自反应物质，d型', '吸入、食入、皮肤接触、眼睛接触', '重氮盐大都有较强的毒性，有些是烈性致癌物。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。吸入、摄入或经皮肤吸收后对身体有害。受热分解释放出有毒气体。', '对水生生物有毒性。可能对水环境造成长期不良影响。', '遇热有火灾危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4767, 4874, NULL, NULL, NULL, NULL, NULL, '第4.1类自反应物质', '吸入、食入、皮肤接触、眼睛接触', '吸入有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。接触可引起眼睛红肿、疼痛，皮肤接触可引起刺激和过敏。重氮盐类化合物有些是烈性致癌物。', '对水生生物有毒。重氮盐类化合物可能对水生环境造成长期不良影响。', '遇热有火灾危险。受热分解可能产生氮氧化物、氯化氢、锌化合物等有毒烟雾。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4768, 4875, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期或反复接触可能对肝脏、肾脏、神经系统造成损害。', '对水生生物可能有害。避免该物质进入环境。', '遇热、摩擦、撞击或接触火焰可能发生爆炸或分解。干燥状态下不稳定，具有自反应性。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4769, 4876, NULL, NULL, NULL, NULL, NULL, '第2.3类 有毒气体', '吸入 食入', '眼睛和粘膜有强烈的刺激性和腐蚀性。', '无资料', '本品不燃，有毒，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4770, 4877, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收\n吸入、口服或经皮吸收后对身体有害。对眼睛、粘膜、皮肤和上呼吸道有强烈的刺激作用，可\n引起灼伤。吸入后，可能因喉、支气管痉挛、炎症和水肿而致死。中毒表现可有烧灼感、咳嗽、', '头晕、喉炎、气短、头痛、恶心和呕吐。', '无资料', '本品不燃，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4771, 4878, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入\n吸入后引起胸痛、胸部紧束感、咳嗽、呼吸困难，可致死。对眼和皮肤有刺激性。摄入可\n致急性胃肠炎、中枢神经系统抑制，可致死。慢性中毒：长期接触可在脑、肝和肾中蓄积。', '中毒后出现头痛、记忆力下降、震颤、牙齿脱离、食欲不振，可引起皮肤疾病等。', '无资料', '本品不燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4772, 4879, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '神失常、晕厥等。全身毛发脱落是其中毒的特征，但眉毛内侧l／3不受侵犯。', '无资料', '本品不燃、高毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4773, 4880, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', NULL, NULL, '本品不燃，高毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4774, 4881, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入、食入、经皮吸收', '其蒸气对粘膜和呼吸道有明显刺激作用。临床表现有气短、咳嗽、胸痛、咽干痛以及流泪、流涕、痰中带血、恶心、无力等。吸入高浓度可引起化学性肺炎、甚至可发展为肺水肿。皮肤接触液体可致重度灼伤。', '对环境有危害，对水体和大气可造成污染。', '本品助燃，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4775, 4882, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体，第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有剧毒。可引起化学性肺炎、肺水肿，抢救不及时可死亡。眼及皮肤接触可致灼伤。慢性影响：长期接触本品可引起支气管炎。本品可致肺癌。', '该物质对环境可能有危害，应特别注意对水体的污染。', '本品易燃，剧毒、为致癌物，具强刺激性。遇明火、高热有引起燃烧爆炸的危险。受热分解产生有毒的甲醛和氯化氢气体。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4776, 4883, NULL, NULL, NULL, NULL, NULL, '第3类易燃液体，第8.1类酸性腐蚀品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后会中毒。对眼睛、皮肤和粘膜有强烈刺激作用。吸入可引起喉、支气管痉挛、炎症，化学性肺炎、肺水肿。接触后可有头痛、恶心、呕吐、咳嗽、气短等。高浓度接触可引起化学灼伤。', '该物质对环境可能有危害，应特别注意对水体的污染。', '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。受热分解产生有毒的氯化氢和氧化硅烟气。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4777, 4884, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '吸入、口服或经皮吸收对身体有害。蒸气或雾对眼、粘膜和上呼吸道有刺激性。接触后可引起烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '该物质对环境可能有危害，应特别注意对水体的污染。', '本品易燃，具刺激性。遇明火、高热有引起燃烧爆炸的危险。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4778, 4885, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品；第8类 腐蚀性物品', '吸入、食入、经皮吸收', '具有强腐蚀性。吸入可引起喉、支气管的炎症、痉挛，化学性肺炎、肺水肿等。对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用。皮肤接触可引起灼伤。食入可引起消化道灼伤。', '对环境有危害，对水体和大气可造成污染。', '本品可燃、有毒、具有腐蚀性、强刺激性、可致人体灼伤。遇明火、高热可燃。受热分解产生有毒的腐蚀性烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4779, 4886, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后会中毒。对眼睛、皮肤和粘膜有强烈刺激作用，可引起灼伤。吸入会引起喉、支气管炎症、痉挛，化学性肺炎、肺水肿。', '无资料', '本品可燃、有毒、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4780, 4887, NULL, NULL, NULL, NULL, NULL, '第3.2类高闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生生物有毒性。', '易燃,其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4781, 4888, NULL, NULL, NULL, NULL, NULL, '第3类易燃液体；第6.1类毒害品；第8类腐蚀性物品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。蒸气或雾对眼睛、粘膜和上呼吸道有强烈的刺激作用。可引起化学性肺炎、肺水肿。高浓度接触可引起喉头水肿、支气管痉挛，甚至窒息。长期或反复接触可引起皮肤过敏、呼吸道过敏。本品可经呼吸道、消化道和皮肤吸收，对中枢神经系统、肝、肾、心血管系统有损害作用。', '对水生生物有极强毒性。对环境有危害，应特别注意对水体的污染。', '本品易燃，剧毒、具强刺激性。遇明火、高热极易燃烧爆炸。与氧化剂能发生强烈反应。受热分解产生有毒的氯化氢和光气等气体。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4782, 4889, NULL, NULL, NULL, NULL, NULL, '第3类易燃液体；第6.1类毒害品；第8类腐蚀性物品', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和呼吸道有强烈的刺激作用。吸入、口服或经皮肤吸收后可致死。吸入后可因喉、支气管的痉挛、水肿，化学性肺炎、肺水肿而致死。可致皮肤和眼灼伤。', '该物质对环境有危害，应特别注意对水体的污染。', '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。受热分解产生有毒的氯化物、光气等气体。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4783, 4890, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品；第8类 腐蚀性物品', '吸入、食入、经皮吸收', '窒息性毒剂。主要作用于呼吸器官，引起急性中毒性肺水肿，严重者窒息死亡。对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用。皮肤接触可引起灼伤。食入可引起消化道灼伤。吸入高浓度可迅速致死。', '对环境有危害，对水体和大气可造成污染。', '本品不燃、高毒、具有强腐蚀性、强刺激性。受热分解能放出剧毒的光气。遇水反应发热放出有毒的腐蚀性气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4784, 4891, NULL, NULL, NULL, NULL, NULL, '第3类易燃液体；第6.1类毒害品；第8类腐蚀性物品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用。吸入可引起喉、支气管痉挛、炎症、水肿，化学性肺炎或肺水肿。接触可引起灼伤。', '对环境有危害，对水体和大气可造成污染。', '易燃，其蒸气与空气混合，能形成爆炸性混合物。受热或接触火焰可能会产生膨胀或爆炸性分解。遇水反应发热放出有毒的腐蚀性气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4785, 4892, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入、食入、皮肤接触、眼睛接触', '化学性肺炎、肺水肿等。接触后，可引起头痛、恶心、呕吐、咳嗽、气短等症状。', '对环境有危害，对水体可造成污染。', '本品易燃、有毒、具有腐蚀性、强刺激性、可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4786, 4893, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '吸入、食入、经皮吸收。人接触后主要中毒表现为眼及上呼吸道刺激；高浓度时可发生肺水肿。涂于豚鼠皮肤可引起严重刺激。', '对环境有危害，对水体和大气可造成污染。', '本品易燃，剧毒、具刺激性。遇明火、高热易引起燃烧爆炸。受热分解能放出剧毒的光气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4787, 4894, NULL, NULL, NULL, NULL, NULL, '第3类易燃液体；第6.1类毒害品；第8类腐蚀性物品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用。吸入可引起喉、支气管痉挛、炎症、水肿，化学性肺炎或肺水肿。接触可引起灼伤。', '对环境有危害，对水体和大气可造成污染。', '易燃，其蒸气与空气混合，能形成爆炸性混合物。受热或接触火焰可能会产生膨胀或爆炸性分解。遇水反应发热放出有毒的腐蚀性气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4788, 4895, NULL, NULL, NULL, NULL, NULL, '第3类易燃液体；第6.1类毒害品；第8类腐蚀性物品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用。吸入可引起喉、支气管痉挛、炎症、水肿，化学性肺炎或肺水肿。接触可引起灼伤。', '对环境有危害，对水体和大气可造成污染。', '易燃，其蒸气与空气混合，能形成爆炸性混合物。受热或接触火焰可能会产生膨胀或爆炸性分解。遇水反应发热放出有毒的腐蚀性气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4789, 4896, NULL, NULL, NULL, NULL, NULL, '第3类易燃液体；第6.1类毒害品；第8类腐蚀性物品', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和呼吸道有强烈的刺激作用。吸入、口服或经皮肤吸收后可致死。吸入后可因喉、支气管的痉挛、水肿，化学性肺炎、肺水肿而致死。可致皮肤和眼灼伤。', '该物质对环境有危害，应特别注意对水体的污染。', '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。受热分解产生有毒的氯化物、光气等气体。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4790, 4897, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '吸入、食入或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。吸入可引起喉、支气管痉挛、炎症、水肿，化学性肺炎或肺水肿。接触后可引起烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '对水生生物有极大危害。', '本品易燃，有毒，具腐蚀性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4791, 4898, NULL, NULL, NULL, NULL, NULL, '第3类易燃液体', '吸入、食入、皮肤接触、眼睛接触', '吸入、食入或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。吸入可引起喉、支气管痉挛、炎症、水肿，化学性肺炎或肺水肿。接触后可引起烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '对水生生物有极大危害。', '易燃,其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4792, 4899, NULL, NULL, NULL, NULL, NULL, '第2.3类 有毒气体', '吸入、皮肤接触', '急性中毒：轻度中毒有头痛、头晕、乏力、恶心、步态蹒跚、视力模糊等症状。中度中毒表现为短暂兴奋状态，言语增多、面部潮红、步态不稳、意识障碍等。重度中毒可出现躁动、抽搐、震颤、视力障碍、昏迷，呼气中有酮体味。尿中检出甲酸盐和酮体有助于诊断。皮肤接触可因氯甲烷在体表迅速蒸发而致冻伤。慢性影响：低浓度长期接触，可发生困倦、嗜睡、头痛、感觉异常、情绪不稳等症状，较重者有步态蹒跚、视力障碍及震颤等症状。', '对环境有危害，对水体和大气可造成污染。', '易燃，与空气混合能形成爆炸性混合物。遇热源和明火有燃烧爆炸的危险。受热分解产生有毒的氯化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4793, 4900, NULL, NULL, NULL, NULL, NULL, '第2.2类不燃气体；危害臭氧层，类别1。', '吸入、皮肤接触、眼睛接触', '吸入该物质可能会引起对健康有害的影响或呼吸道不适。由于该物质是窒息性气体，在高浓度环境下可能引起缺氧、头晕、头痛、恶心、意识模糊，严重时可导致窒息死亡。接触液体可能引起冻伤。', '该物质对臭氧层有严重危害，属于受控的消耗臭氧层物质。对水生生物可能有害。', '高压压缩气体，遇热有爆炸危险。容器受热可能发生爆炸。本身不燃，但可助燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4794, 4901, NULL, NULL, NULL, NULL, NULL, '第2.2类不燃气体', '吸入', '在常温常压下无毒。高浓度时可能引起窒息。接触热分解产物可引起严重的呼吸道刺激和肺水肿。分解产物氯化氢和氟化氢具有强腐蚀性，可对眼睛、皮肤和呼吸道造成严重损伤。', '该物质对臭氧层有破坏作用，是温室气体。对环境有潜在危害。', '不燃。受热分解产生有毒的腐蚀性烟气。容器受热有爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4795, 4902, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入', '口服急性中毒，表现为高铁血红蛋白血症，胃肠炎，肝肾损伤，甚至窒息。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水体可造成污染。', '本品助燃。遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4796, 4903, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、皮肤接触、眼睛接触', '属可溶性钡盐，有较高毒性。吸入后刺激上呼吸道。眼和皮肤接触有刺激性。口服可引起腹痛、恶心、呕吐、腹泻、脉缓、面色苍白、紫绀、呼吸困难、流涎、惊厥、昏迷、胃肠出血、进行性肌麻痹、心律紊乱等。可致死。慢性影响：长期接触钡化合物的工人，可有无力、气促、流涎、口腔粘膜肿胀、糜烂、鼻炎、结膜炎、腹泻、心动过速、血压增高、脱发等。', '对水生生物有害。该物质对环境可能有危害，对水体应给予特别注意。', '强氧化剂。与可燃物、还原剂、有机物等混合可形成爆炸性混合物。与硫酸接触容易发生爆炸。急剧加热时可发生爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4797, 4904, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、皮肤接触、眼睛接触', '粉尘对眼睛、皮肤、粘膜和上呼吸道有刺激作用。吸入可引起呼吸道刺激，高浓度可致肺水肿。皮肤接触可引起刺激。眼睛接触可引起严重刺激。食入可引起消化道刺激。', '对水生生物有毒性，可能对水体环境产生长期不良影响。', '强氧化剂。与可燃物、有机物、金属粉末或其他易氧化物形成爆炸性混合物。遇火源或受热可能引起爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4798, 4905, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、经皮吸收', '对人的致死量约10g。口服急性中毒表现为高铁血红蛋白血症，胃肠炎，肝肾损害，甚至窒息。粉尘对呼吸道有刺激性。', '对水生生物有害。该物质对环境可能有危害，对水体应给予特别注意。', '强氧化剂。与可燃物、还原剂、有机物等混合可形成爆炸性混合物。与磷或金属粉末等混合可形成爆炸性混合物。急剧加热时可发生爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4799, 4906, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、皮肤接触、眼睛接触', '吸入、食入或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。误服可引起高铁血红蛋白血症，出现紫绀、呼吸困难、头痛、头晕、恶心、呕吐等症状。', '对水生生物有害。该物质对环境可能有危害，对水体应给予特别注意。', '强氧化剂。与可燃物、还原剂、有机物等混合可形成爆炸性混合物。急剧加热时可发生爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4800, 4907, NULL, NULL, NULL, NULL, NULL, '第5.1类 氧化剂', '吸入、食入、皮肤接触、眼睛接触', '对呼吸道有刺激性；为高铁血红蛋白形成剂。接触后出现头痛、头昏、虚弱；高浓度可致呼吸紊乱、虚脱甚至死亡。眼和皮肤接触有刺激性，可致灼伤。', '对水生生物有毒性。该物质对环境有危害，应特别注意对水体的污染。', '本品助燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4801, 4908, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有刺激作用。吸入可引起呼吸道刺激，甚至肺水肿。误服可引起消化道刺激症状，严重时可引起肝肾损伤，甚至发生窒息。', '对水生生物有害。该物质对环境可能有危害，对水体应给予特别注意。', '强氧化剂。与可燃物、还原剂、有机物等混合可形成爆炸性混合物。急剧加热时可发生爆炸。遇火源可引起燃烧或爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4802, 4909, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤、粘膜和上呼吸道有刺激作用。吸入可引起呼吸道刺激，甚至肺水肿。误服可引起消化道刺激症状，严重时可引起肝肾损伤，甚至发生窒息。', '对水生生物有害。该物质对环境可能有危害，对水体应给予特别注意。', '强氧化剂。与可燃物、还原剂、有机物等混合可形成爆炸性混合物。急剧加热时可发生爆炸。遇火源可引起燃烧或爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4803, 4910, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、皮肤接触、眼睛接触', '具强腐蚀性。对眼睛、皮肤和粘膜有强烈刺激作用。吸入可引起呼吸道刺激，高浓度可致肺水肿。皮肤接触可引起严重灼伤。眼睛接触可致失明。食入可引起消化道灼伤。', '对水生生物有毒性，可能对水体环境产生长期不良影响。', '本身不燃，但能助燃。与有机物、还原剂、易燃物等接触可发生剧烈反应，甚至爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4804, 4911, NULL, NULL, NULL, NULL, NULL, '第5.1类 氧化剂', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤、粘膜和上呼吸道有刺激作用。误服可引起消化道刺激症状。', '对水生生物有毒性。该物质对环境有危害，应特别注意对水体的污染。', '跟可燃物质接触可能会引起火灾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4805, 4912, NULL, NULL, NULL, NULL, NULL, '第5.1类 氧化剂', '吸入 食入 经皮吸收', '具刺激作用。误服可引起恶心、胃部不适。目前，尚无职业中毒的报告。', '无资料', '本品助燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4806, 4913, NULL, NULL, NULL, NULL, NULL, '第5.1类 氧化剂', '吸入、食入、经皮吸收', '粉尘对眼睛、粘膜有刺激作用。吸入、摄入或经皮吸收后均可引起中毒。可引起心、肝、肾损害。全身毛发脱落是其中毒的特征，但眉毛内侧1/3常不受累。急性中毒：出现胃肠道反应（腹痛、恶心、呕吐）、神经系统症状（头痛、头晕、失眠、多梦）、周围神经炎（肢体麻木、疼痛）、脱发等症状。慢性中毒：可引起周围神经炎、脱发、指甲出现白色横纹（Mees线）、精神症状等。', '铊是一种典型的有毒金属，对水生生物和陆生生物均有毒性。铊会在生物体内富集，通过食物链放大效应，对处于食物链较高位置的生物包括人类造成更大危害。在冶炼废水中常见且难以处理，对环境造成长期污染。', '摩擦、撞击可引起燃烧或爆炸。与硫酸接触容易发生爆炸。受高热分解，放出有毒的烟气。本品助燃、高毒、具有刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4807, 4914, NULL, NULL, NULL, NULL, NULL, '第5.1类 氧化剂', '吸入 食入\n对眼睛、粘膜有刺激作用。溅入眼内可引起结膜炎、角膜溃疡和角膜混浊。可发生接触性', '皮炎；误服可致急性胃肠炎；长期吸入尚可引起肺部纤维组织增生。', '无资料', '本品助燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4808, 4915, NULL, NULL, NULL, NULL, NULL, '第5.1类 氧化剂', '吸入 食入\n对眼睛、皮肤和粘膜有刺激作用。吸入可引起支气管肺炎。误服可引起恶心、呕吐、腹痛、', '腹泻等急性胃肠炎的症状。', '无资料', '本品助燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4809, 4916, NULL, NULL, NULL, NULL, NULL, '第5.1类 氧化剂', '吸入、食入、经皮吸收', '引起全身银质沉着症：皮肤及眼结膜(或角膜)色素沉着，慢性支气管炎等。', '无资料', '本品助燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4810, 4917, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和呼吸道有刺激作用。长期接触可引起贫血、肝脾肿大等损害。', '对水生生物有毒性，可能对水体环境产生长期不良影响。', '遇明火、高热可燃。受热分解产生有毒的氮氧化物和氯化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4811, 4918, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入可引起头痛、头晕、恶心、呕吐、乏力等症状。高浓度吸入可引起麻醉作用，甚至昏迷。对眼睛和皮肤有刺激性。食入可引起胃肠道刺激症状。长期接触可能对肝脏、肾脏和神经系统造成损害。', '对水生生物有毒性。在环境中不易降解，可能对水体造成长期污染。', '本品不燃，有毒，具刺激性。受高热分解产生有毒的腐蚀性烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4812, 4919, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n如吸入、摄入或经皮肤吸收，可能引起死亡。蒸气或雾对眼、粘膜和上呼吸道有刺激性。', '接触后可出现烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。可引起紫绀。', '无资料', '本品易燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4813, 4920, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收\n吸入高浓度', '患者可有抽搐、昏迷、休克、血尿和肾功能衰竭。酸雾可致眼部刺激症状和角膜灼伤。皮肤灼\n伤可出现水疱，1～2周后水疱吸收。慢性影响：经常接触低浓度本品酸雾，可有头痛、头晕现\n象。', '无资料', '本品可燃，具腐蚀性、刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4814, 4921, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '跟皮肤接触有剧毒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4815, 4922, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收', '心和呕吐。', '无资料', '本品可燃，具腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4816, 4923, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n吸入、口服或经皮肤吸收对身体有害。对眼睛、粘膜、呼吸道及皮肤有强烈刺激作用。吸入后\n可因喉和支气管的痉挛、炎症及水肿，化学性肺炎、肺水肿而致死。中毒表现有烧灼感、咳嗽、', '喘息、喉炎、气短、头痛、恶心、呕吐。', '无资料', '本品易燃，有毒，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4817, 4924, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入', '本品对眼睛、皮肤、粘膜和上呼吸道有刺激作用和腐蚀作用。', '无资料', '本品不燃、有毒、具有刺激性、腐蚀性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4818, 4925, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n吸入、摄入或经皮肤吸收后对身体有害。其蒸气或烟雾对眼睛、粘膜和上呼吸道有刺激作', '用。接触后可引起烧灼感、咳嗽、喉炎、头痛、恶心和呕吐等。', '无资料', '本品易燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4819, 4926, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, '易燃,其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4820, 4927, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '对眼睛、呼吸道粘膜有强烈的刺激作用，重者可引起肺水肿。对豚鼠皮肤有中度刺激性。可经\n皮肤吸收。', '无资料', '本品易燃，有毒，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4821, 4928, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有毒。对皮肤有刺激性。对眼睛有严重刺激性。对呼吸道有刺激作用。', NULL, '易燃,其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4822, 4929, NULL, NULL, NULL, NULL, NULL, '第2.1类 易燃气体', '吸入、皮肤接触、眼睛接触', '有刺激和麻醉作用。高浓度损害心、肝、肾。吸入2％～4％浓度时可引起运动失调、轻度痛觉减退，并很快出现知觉消失，但其刺激作用可引起反射性呼吸停止。长期接触可引起神经衰弱综合征。', '对环境有危害，对水体可造成污染。', '本品易燃，具刺激性。遇明火、高热极易燃烧爆炸。与氧化剂接触猛烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4823, 4930, NULL, NULL, NULL, NULL, NULL, '第2.1类易燃气体；致癌性类别1；生殖毒性类别1。', '吸入、经皮吸收。', '急性毒性表现为麻醉作用；长期接触可引起氯乙烯病。急性中毒：轻度中毒时病人出现眩晕、胸闷、嗜睡、步态蹒跚等；严重中毒可发生昏迷、抽搐，甚至造成死亡。皮肤接触氯乙烯液体可致红斑、水肿或坏死。慢性中毒：表现为神经衰弱综合征、肝肿大、肝功能异常、消化功能障碍、雷诺氏现象及肢端溶骨症。皮肤可出现干燥、皲裂、脱屑、湿疹等。本品为致癌物，可致肝血管肉瘤。', '氯乙烯在环境中能参与光化学烟雾反应。对水生生物有害。', '本品易燃，为致癌物。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4824, 4931, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收\n对眼睛、皮肤、粘膜和呼吸道有强烈的刺激作用。吸入后可能由于喉、支气管的痉挛、水肿、\n炎症，化学性肺炎或肺水肿而致死。中毒表现有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶', '心和呕吐。', '无资料', '本品不燃，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4825, 4932, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜有刺激作用。有资料报道，似能引起致敏作用。', '马来酸二丁酯对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品可燃，具刺激性。其蒸气与空气可形成爆炸性混合物，当达到一定的浓度时，遇火星会发生爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4826, 4933, NULL, NULL, NULL, NULL, NULL, '刺激性物质', '吸入 食入 经皮吸收', '蒸气或烟雾对眼睛、皮肤、粘膜和上呼吸道有刺激作用。目前，未见职业中毒报道。', '无资料', '易燃液体，蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4827, 4935, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收', '接接触有明显刺激作用，并引起灼伤。慢性影响：慢性结膜炎，鼻粘膜溃疡和炎症；有致敏性，\n可引起皮疹和哮喘。', '马来酸酐对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '本品可燃、有毒、具有腐蚀性、刺激性、致敏性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4828, 4936, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '致死。蒸气、雾或液体对眼有强烈刺激性，严重者可导致失明。皮肤接触可发生灼伤。吞咽本品液体可灼伤消化道，大量吞咽可致死。', '对环境有危害，对水体可造成污染。', '本品易燃，有毒、具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4829, 4937, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '苯酚对皮肤、粘膜有猛烈的腐蚀作用，可抑制中枢神经系统或损害肝、肾功能。吸入高浓度蒸气可引起头痛、头晕、乏力、视物模糊、肺水肿等。长期接触可引起皮炎、痤疮、毛囊炎、光毒性皮炎、中毒性黑皮病、疣赘及肿瘤。可引起鼻中隔损伤。对眼睛、皮肤、粘膜和上呼吸道有刺激性。', '对水生生物有毒。', '遇明火、高热易燃。与强氧化剂发生反应，可引起燃烧。有腐蚀性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4830, 4938, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、经皮吸收、眼睛接触', '作用于皮肤，引起皮炎、痤疮、毛囊炎、光毒性皮炎、中毒性黑皮病、疣赘及肿瘤。可引起鼻中隔损伤。国际癌症研究中心(IARC)已确认为I类致癌物。对眼睛、皮肤、粘膜和上呼吸道有刺激性。', '对水生生物毒性极大且会有长期持续影响。', '本品易燃、为致癌物。遇明火、高热易燃。与强氧化剂发生反应，可引起燃烧。有腐蚀性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4831, 4939, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入该物质可能对个体健康有害。长期接触可引起皮炎、痤疮、毛囊炎、光毒性皮炎、中毒性黑皮病、疣赘及肿瘤。可引起鼻中隔损伤。国际癌症研究中心(IARC)已确认为I类致癌物。对眼睛、皮肤、粘膜和上呼吸道有刺激性。', '对水生生物有毒。', '高度易燃液体，其蒸气与空气混合，能形成爆炸性混合物。遇明火、高热易燃。与强氧化剂发生反应，可引起燃烧。有腐蚀性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4832, 4940, NULL, NULL, NULL, NULL, NULL, '第3类易燃液体', '吸入、食入、经皮吸收', '吸入高浓度煤油蒸气，常先有兴奋，后转入抑制，表现为乏力、头痛、酩酊感、神志恍惚、肌肉震颤、共济运动失调，严重者出现定向力障碍、谵妄、意识模糊等。蒸气对眼睛、皮肤和呼吸道有刺激性。口服引起恶心、呕吐、腹痛、腹泻等症状。', '对环境可能有危害，对水体应给予特别注意。', '本品易燃，具有刺激性。遇明火、高热有燃烧爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4833, 4941, NULL, NULL, NULL, NULL, NULL, '第4.3类遇湿易燃物品', '吸入、食入、皮肤接触、眼睛接触', '吸入镁烟可引起金属烟热，出现发热、咳嗽、寒战、口内有金属味。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期反复接触可引起皮炎。', '对水生生物有毒。', '本品遇湿易燃，具刺激性。遇水、潮湿空气或酸类物质反应剧烈，放出氢气，引起燃烧或爆炸。粉体与空气可形成爆炸性混合物，当达到一定浓度时，遇火星会发生爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4834, 4942, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入 食入', '本品对皮肤具刺激作用。摄入有毒。热解能放出有强刺激性的烟雾。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4835, 4943, NULL, NULL, NULL, NULL, NULL, '爆炸物，类别1.1项；危害水生环境-急性毒性，类别1；危害水生环境-慢性毒性，类别1。', '吸入、食入、皮肤接触、眼睛接触\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '通过打击、摩擦、火灾或其他着火源有极大爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4836, 4944, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、皮肤接触、眼睛接触', '涎、高血压、呕吐、呼吸加快等症状。对中枢神经系统有毒性作用，可导致抽搐、昏迷，甚至引起死亡。', '该物质对环境可能有危害，对水体应给予特别注意。避免排放到周围环境中。', '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4837, 4945, NULL, NULL, NULL, NULL, NULL, '第8.3类其它腐蚀品', '吸入、食入、经皮吸收', '本品有腐蚀性，大量口服可刺激食道和胃部，以致心肌衰竭、虚脱而致死。造成严重皮肤灼伤和眼损伤。对皮肤、眼睛有刺激性。', '对环境有害。对水生环境可能会引起长期有害作用。', '可燃，受热、同硝酸等强氧化剂有引起燃烧的危险。受热分解产生有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4838, 4946, NULL, NULL, NULL, NULL, NULL, '第4.3类遇湿易燃物品', '吸入食入\n在空气中能自燃，燃烧产生的烟（主要含氧化钠）对鼻、喉及上呼吸道有腐蚀作用及极强', '的刺激作用。同潮湿皮肤或衣服接触可燃烧，造成烧伤。', '无资料', '本品遇湿易燃，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4839, 4947, NULL, NULL, NULL, NULL, NULL, '皮肤腐蚀/刺激，类别1；眼损伤/眼刺激，类别1。', '吸入、食入、皮肤接触、眼睛接触\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4840, 4948, NULL, NULL, NULL, NULL, NULL, '第2.2类不燃气体', '吸入', '在高浓度下可引起窒息。症状包括：头晕、头痛、呼吸困难、共济失调。继之疲倦乏力、烦躁不安、恶心、呕吐、昏迷、抽搐，以致死亡。', '对环境无特殊危害。', '本品不燃，具窒息性。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4841, 4949, NULL, NULL, NULL, NULL, NULL, '第4.1类易燃固体', '吸入食入经皮吸收\n具有刺激作用，高浓度致溶血性贫血及肝、肾损害。急性中毒：吸入高浓度萘蒸气或粉\n尘时，出现眼及呼吸道刺激、角膜混浊、头痛、恶心、呕吐、食欲减退、腰痛、尿频，尿\n中出现蛋白及红、白细胞。亦可发生视神经炎和视网膜炎。重者可发生中毒性脑病和肝损', NULL, NULL, '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4842, 4950, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收\n吸入、摄入或经皮肤吸收后会中毒。对眼睛有强烈的刺激作用。受热分解释出汞和氧化硫', '烟雾。', '无资料', '本品可燃、有毒、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4843, 4951, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收', '及绿色尿。慢性影响：长期接触有头痛、不舒服及上呼吸道刺激。可有特殊的绿色尿，可\n致皮炎。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4844, 4952, NULL, NULL, NULL, NULL, NULL, '第4.2类自燃物品', '吸入、食入、经皮吸收', '可引起镍皮炎，又称镍\"痒疹\"。皮肤剧痒，后出现丘疹、疱疹及红斑，重者化脓、溃烂。长期吸入镍粉可致呼吸道刺激、慢性鼻炎，甚至发生鼻中隔穿孔。尚可引起变态反应性肺炎、支气管炎、哮喘等。', '该物质对环境有危害，应特别注意对水体的污染。', '本品属自燃物品，具刺激性，接触可引起皮炎，奇痒。粉尘可燃，能与空气形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4845, 4953, NULL, NULL, NULL, NULL, NULL, '第4.1类易燃固体；皮肤腐蚀/刺激，类别2；严重眼损伤/眼刺激，类别2；特异性靶器官毒性-反复接触，类别2', '吸入、食入、皮肤接触、眼睛接触', '受热分解释出氮氧化物和一氧化碳。资料报道有致突变作用。对眼睛、皮肤和呼吸道有刺激性。高浓度接触可能引起哮喘。长期接触可能对呼吸系统造成损害。', '对水生环境可能会引起长期有害作用。', '本品易燃，遇明火、高热易燃烧爆炸。受热分解，放出有毒的烟气。若遇高热可发生剧烈分解，引起容器破裂或爆炸事故。与氧化剂接触有发生燃烧爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4846, 4954, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '对眼睛和皮肤有强烈刺激性并是升压剂。小剂量可刺激交感和副交感神经节，大剂量反而有抑制作用，误服后可引起虚弱、恶心、流涎、呼吸困难、肌肉瘫痪和窒息。', '无资料', '本品易燃，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4847, 4955, NULL, NULL, NULL, NULL, NULL, '第8.2类 碱性腐蚀品', '吸入 食入 经皮吸收\n大量接触', '眼接触引起严重刺激和灼伤。对皮肤有刺激性。慢性影响：本品粉尘或液体，对皮肤和肺\n有致敏性，引起皮肤刺痒、皮疹和哮喘。', '无资料', '本品可燃、具有腐蚀性、刺激性、致敏性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4848, 4956, NULL, NULL, NULL, NULL, NULL, '第4.3类遇湿易燃物品', '吸入、食入、经皮吸收', '吞食后有毒。跟皮肤接触有毒。对眼睛有严重刺激性。吸入有毒。对呼吸道有严重刺激作用。遇水或酸类分解放出氢气，可引起化学性肺炎或肺水肿。口服腐蚀消化道。', '对水生生物有毒，对水生环境可能会引起长期有害作用。', '遇水、潮湿空气、酸类、氧化剂，高热及明火能引起燃烧。遇水或酸类分解放出氢气，有燃烧爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4849, 4957, NULL, NULL, NULL, NULL, NULL, '第4.3类 遇湿易燃物品', '吸入 食入 经皮吸收', '头痛、恶心和呕吐等。', '无资料', '本品遇湿易燃、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4850, 4958, NULL, NULL, NULL, NULL, NULL, '第4.2类自燃物品', '吸入 食入', '吸入会中毒。遇水、水蒸气或酸类反应放出热、毒气或氢气。', '无资料', '本品易燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4851, 4959, NULL, NULL, NULL, NULL, NULL, '第4.3类遇湿易燃物品', '吸入、食入、经皮吸收', '吞食后有毒。跟皮肤接触有毒。对眼睛有严重刺激性。吸入有毒。对呼吸道有严重刺激作用。遇水或酸类分解放出氢气，可引起化学性肺炎或肺水肿。口服腐蚀消化道。', '对水生生物有毒，对水生环境可能会引起长期有害作用。', '遇水、潮湿空气、酸类、氧化剂，高热及明火能引起燃烧。遇水或酸类分解放出氢气，有燃烧爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4852, 4960, NULL, NULL, NULL, NULL, NULL, '急性毒性类别4；皮肤腐蚀/刺激类别2；严重眼损伤/眼刺激类别2A；生殖毒性类别1B', '吸入、食入、经皮吸收', '口服引起急性中毒，主要表现为胃肠道症状，有恶心、呕吐、腹痛、腹泻等，继之发生脱水、休克、昏迷或急性肾功能衰竭，可有高热、肝肾损害和惊厥。皮肤出现广泛鲜红色疹，重者成剥脱性皮炎。长期接触可引起慢性中毒，表现为神经系统损害、肾脏损害和生殖系统影响。', '对水生生物有毒并可能在水生环境中造成长期不利影响', '本品不燃，受高热分解放出有毒的气体', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4853, 4961, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收对身体有害。蒸气或雾对眼、粘膜和上呼吸道有刺激性。对皮肤有刺激性。', '对水生生物有毒性。对水生环境可能造成不利影响。', '易燃，其蒸气与空气可形成爆炸性混合物。遇明火、高热极易燃烧爆炸。与氧化剂接触猛烈反应。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4854, 4962, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入 食入 经皮吸收', '对眼和皮肤有刺激性。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4855, 4963, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入 食入 经皮吸收', NULL, '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4856, 4964, NULL, NULL, NULL, NULL, NULL, '第6.1 类毒害品', '无资料\n短期大量接触可引起急性铍病，主要表现为急性化学性支气管炎或肺炎。肝脏往往肿大，有压\n痛，甚至出现黄疸。长期接触小量铍可发生慢性铍病。除无力、消瘦、食欲不振外，常有胸闷、', '胸痛、气短和咳嗽。X 线肺部检查分三型：颗粒型、网织型和结节型。晚期可发生右心衰竭。\n皮肤病变有皮炎、溃疡及皮肤肉芽肿。', NULL, '本品易燃，高毒，为致癌物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4857, 4965, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收', '粉尘能刺激眼睛和粘膜。误服能产生呕吐、流涎与腹泻。皮肤接触可引起荨麻疹。吸入和口服可致死亡。吸入可引起咳嗽、胸痛、呼吸困难、口中金属味和精神症状，对肝、肾有损害。', '对环境有危害，对水体可造成污染。对水生生物有毒性作用，对鱼类和藻类有危害。', '本品不燃、有毒、具有刺激性。有氧化性，接触有机物有引起燃烧危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4858, 4966, NULL, NULL, NULL, NULL, NULL, 'GHS危险性类别：急性毒性-经口，类别2；皮肤腐蚀/刺激，类别2；严重眼损伤/眼刺激，类别2；特异性靶器官毒性-单次暴露，类别3（呼吸道刺激）；特异性靶器官毒性-反复接触，类别1；致癌性，类别1A；生殖毒性，类别2', '吸入、食入、经皮吸收', '吞咽有害。造成严重眼刺激。吸入有害。怀疑对生育能力或胎儿造成伤害。长期或反复接触会对器官造成伤害。对皮肤有刺激性。对眼睛有严重刺激性。对呼吸道有刺激作用。可能致癌。', '对水生环境可能会引起长期有害作用。', '本身不燃，但受热分解可能产生有毒烟雾。与有机物、还原剂等接触可能发生剧烈反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4859, 4967, NULL, NULL, NULL, NULL, NULL, '氧化性固体，类别2；皮肤腐蚀/刺激，类别2；严重眼损伤/眼刺激，类别2', '吸入、食入、皮肤接触、眼睛接触', '吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入该物质可能造成对消化道的损害。皮肤接触可引起刺激。眼睛接触可引起严重刺激。高浓度接触严重损害粘膜、上呼吸道、眼睛和皮肤。接触后引起烧灼感、咳嗽、喘息、喉炎、气短。', '对水生环境可能会引起长期有害作用。', '本身不燃，但为强氧化剂，与可燃物、还原剂等接触可能发生剧烈反应，甚至引起燃烧或爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4860, 4968, NULL, NULL, NULL, NULL, NULL, 'GHS危险性类别：皮肤腐蚀/刺激，类别1b；严重眼损伤/眼刺激，类别1；特异性靶器官毒性-单次暴露，类别3（呼吸道刺激）', '吸入、食入、皮肤接触、眼睛接触', '引起皮肤烧伤，有严重损害眼睛的危险。对呼吸道有刺激作用。误服可引起消化道灼伤、出血或穿孔。', '对水生生物有毒性。', '本身不燃，遇水或水蒸气反应放热，产生有毒和腐蚀性烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4861, 4969, NULL, NULL, NULL, NULL, NULL, 'GHS危险性类别：皮肤腐蚀/刺激，类别1b；严重眼损伤/眼刺激，类别1；特异性靶器官毒性-单次暴露，类别3（呼吸道刺激）', '吸入、食入、经皮吸收', '具有强腐蚀性。对粘膜、呼吸道、眼睛和皮肤有强烈刺激性。吸入可引起呼吸道刺激、咳嗽、呼吸困难，严重时可导致肺水肿。食入可引起口腔、咽喉、食道和胃部严重灼伤。皮肤接触可引起严重灼伤和疼痛。眼睛接触可引起严重灼伤，甚至导致失明。', '对水生生物有害。', '本身不燃，但遇水或湿气会剧烈反应产生磷酸，放热。受热分解产生剧毒的氧化磷烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4862, 4970, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吞食后有毒。吸入有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期接触可引起慢性砷中毒。', '对水生物有剧毒,对水生环境可能会引起长期有害作用。', '本身不燃，但受热分解产生有毒气体。与还原剂、有机物、易燃物等接触有燃烧爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4863, 4971, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '口服砷化合物引起急性胃肠炎、休克、周围神经病、中毒性心肌炎、肝炎，以及抽搐、昏迷等，甚至死亡。大量吸入亦可引起急性中毒，但消化道症状较轻。砷酸钠对眼、呼吸道及皮肤有刺激作用。', '对水生生物有剧毒，对水生环境可能会引起长期有害作用。', '本品不燃，高毒。受高热分解放出有毒的气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4864, 4972, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, '对水生物有剧毒,对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4865, 4973, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收\n具腐蚀性的毒物。对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用。可引起皮肤溃疡和', '坏死，以及化脓性坏死性角膜结膜炎。', '无资料', '本品不燃、具有腐蚀性，强刺激性，可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4866, 4974, NULL, NULL, NULL, NULL, NULL, '第4.1类 易燃固体', '吸入 食入\n误服或吸入', '激。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4867, 4975, NULL, NULL, NULL, NULL, NULL, '环境危险物质，可能对环境造成长期影响', '吸入、皮肤接触、眼睛接触、食入', '长期接触可能对肝脏、甲状腺等器官造成影响；可能引起皮肤刺激；吸入粉尘可能引起呼吸道刺激', '对水生生物有极高毒性，可能在水生环境中造成长期有害影响；具有生物累积性；持久性有机污染物特性', '不易燃，但在高温下可能分解产生有毒的溴化氢气体；燃烧时可能产生一氧化碳、二氧化碳和溴化物', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4868, 4976, NULL, NULL, NULL, NULL, NULL, '侵入途径：', '吞食后有剧毒。跟皮肤接触有剧毒。吸入有剧毒。有轻微致癌性风险。长期暴露有损伤', NULL, '对水生物有剧毒,对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4869, 4977, NULL, NULL, NULL, NULL, NULL, '侵入途径： 吸入', '吸入\n暴露引起症状与氰化物相似，为呕吐、心悸、错乱、精神不安、头晕、呼吸由急促变慢并', '感到吃力，随后还可以引起窒息死亡；本品为剧毒品', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4870, 4978, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。', '接触后，可引起烧灼感、咳嗽、喉炎、气短、头痛、恶心和呕吐。', '无资料', '本品可燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4871, 4979, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有剧毒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4872, 4980, NULL, NULL, NULL, NULL, NULL, '第2.1类易燃气体', '吸入、皮肤接触、眼睛接触', '氢气本身无毒，但在高浓度下可引起窒息。液氢接触可导致严重冻伤。如发生冻伤，须就医诊治。', '对环境可能有害，对水体应给予特别注意。', '本品易燃，其蒸气与空气混合能形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氟、氯、溴等卤素会剧烈反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4873, 4981, NULL, NULL, NULL, NULL, NULL, '第5.2类有机过氧化物', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤和呼吸系统有刺激性。可能引起皮肤灼伤和眼损伤。', '对环境有危害，对水体应给予特别注意。', '遇热有火灾危险。受热可能发生爆炸性分解。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4874, 4982, NULL, NULL, NULL, NULL, NULL, '第4.3类遇湿易燃物品', '吸入、食入、经皮吸收', '本品有毒。粉尘能刺激眼睛和上呼吸道。误服或经皮肤吸收会中毒，出现低血钾综合征，可导致四肢软瘫、心肌受累及呼吸麻痹。', '对环境可能有害。', '本品遇湿易燃、有毒、具有刺激性。遇水或潮湿空气产生氢气，遇火源会引起燃烧或爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4875, 4983, NULL, NULL, NULL, NULL, NULL, '第4.3类遇水放出易燃气体的物质', '吸入、食入、皮肤接触、眼睛接触', '本品对粘膜、上呼吸道、眼和皮肤有强烈的刺激性。吸入后可引起咳嗽、喘息、喉炎、气短、头痛、恶心、呕吐等。严重者可引起化学性肺炎或肺水肿而致死。接触后引起烧灼感。', '对环境可能有害。', '本品遇湿易燃，具强腐蚀性、强刺激性，可致人体灼伤。遇水或潮湿空气产生氢气，遇火源会引起燃烧或爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4876, 4984, NULL, NULL, NULL, NULL, NULL, '第4.1类易燃固体', '吸入、食入、皮肤接触、眼睛接触', '本品具有刺激作用。目前，工业上未见有中毒病例报道。', '对环境可能有害。', '具有强还原性。与氧化剂能发生强烈反应。受热或遇潮气、酸类放出氢气和热量，可引起燃烧或爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4877, 4985, NULL, NULL, NULL, NULL, NULL, '第4.3类遇湿易燃物品', '吸入、食入、皮肤接触、眼睛接触', '本品对粘膜、上呼吸道、眼和皮肤有强烈的刺激性。吸入后，可因喉及支气管的痉挛、水肿，化学性肺炎或肺水肿而致死。接触后引起烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心、呕吐。', '对环境有害。', '本品遇湿易燃，具强腐蚀性、强刺激性，可致人体灼伤。接触空气易自燃。遇水剧烈反应，可引起燃烧或爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4878, 4986, NULL, NULL, NULL, NULL, NULL, '第4.3类遇湿易燃物品', '吸入、食入、皮肤接触、眼睛接触', '对皮肤粘膜有强烈的刺激与腐蚀作用。吸入后引起喷嚏、咳嗽、呼吸困难、支气管炎。可引起鼻中隔穿孔。眼接触可致结膜炎或灼伤。可致皮肤灼伤。口服中毒出现无力、眩晕、视力模糊、恶心、呕吐等，重者昏迷、抽搐或精神障碍。', '对环境可能有害。', '本品遇湿易燃，具强腐蚀性、强刺激性，可致人体灼伤。遇湿气和水分生成氢氧化物，腐蚀性很强。与氧化剂能发生强烈反应，引起燃烧或爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4879, 4987, NULL, NULL, NULL, NULL, NULL, '第4.3类遇湿易燃物品', '吸入、食入、皮肤接触、眼睛接触', '本品粉尘对眼睛、鼻、皮肤和呼吸系统有刺激作用，长期作用可引起尘肺。', '对环境可能有害。', '本品遇湿易燃、有毒、具有刺激性。暴露在空气中能自燃。遇水或酸发生反应放出氢气及热量，能引起燃烧。与氧化剂能发生强烈反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4880, 4988, NULL, NULL, NULL, NULL, NULL, '第4.3类遇湿易燃物品', '吸入、食入、经皮吸收', '水肿、痉挛，化学性肺炎或肺水肿而致死。接触后引起烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐等。', '对环境可能有害。', '本品遇湿易燃，具强刺激性。与空气、水、醇、酸类接触，即发生放热反应并放出氢气而燃烧或爆炸。与强氧化剂接触猛烈反应而爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4881, 4989, NULL, NULL, NULL, NULL, NULL, '第4.3类遇湿易燃物品', '吸入、食入、皮肤接触、眼睛接触', '暴露刺激眼、鼻、喉、皮肤；如潮湿时，手接触本品，会引起灼伤。', '对环境可能有害。', '遇氧化剂、酸或水有引起燃烧爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4882, 4990, NULL, NULL, NULL, NULL, NULL, '第4.3类遇湿易燃物品', '吸入、食入、皮肤接触、眼睛接触', '氢化镁粉尘对眼睛、鼻、皮肤和呼吸系统有强烈刺激作用。', '对环境可能有害。', '本品遇湿易燃、有毒、具有强刺激性。遇水或受热放出氢气，能引起燃烧或爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4883, 4991, NULL, NULL, NULL, NULL, NULL, '第4.3类遇湿易燃物品', '吸入、食入、皮肤接触、眼睛接触', '对眼和呼吸道有刺激性。皮肤直接接触引起灼伤。误服造成消化道灼伤。', '对环境可能有害。', '本品遇湿易燃，具强刺激性。化学反应活性很高，在潮湿空气中能自燃。受热或与潮气、酸类接触即放出热量和氢气，引发燃烧和爆炸。与氧化剂能发生强烈反应，引发燃烧或爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4884, 4992, NULL, NULL, NULL, NULL, NULL, '第4.1类易燃固体', '吸入、食入、皮肤接触、眼睛接触', '吸入、摄入有害。动物实验表明，长期接触可能发生肺纤维化。对眼睛、皮肤有刺激性。', '对环境可能有害。', '本品易燃、有毒。遇潮气、酸类放出氢气和热量，可引起燃烧或爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4885, 4993, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '本品对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对环境有危害，对水体应给予特别注意。', '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4886, 4994, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '抑制呼吸酶，造成细胞内窒息。急性中毒：高浓度吸入可引起骤死。非骤死者临床表现分为4期：前驱期有粘膜刺激、呼吸加快加深、乏力、头痛；口服有舌尖、口腔麻木等。呼吸困难期有呼吸困难、血压升高、皮肤粘膜呈鲜红色等。惊厥期出现抽搐、昏迷、呼吸衰竭。麻痹期全身肌肉松弛，呼吸心跳停止而死亡。可致眼、皮肤灼伤，吸收引起中毒。慢性中毒：神经衰弱综合征，皮炎。', '对环境有危害，对水体应给予特别注意。', '本品易燃，高毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4887, 4995, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、皮肤接触、眼睛接触', '可引起皮肤、粘膜的刺激或灼伤。长期低浓度接触可引起呼吸道刺激症状和消化功能障碍。', '对环境有危害，对水体应给予特别注意。', '本品不燃，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4888, 4996, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '口服后急性中毒表现为恶心、呕吐、腹痛、腹泻、脉缓、进行性肌麻痹、心律紊乱、血钾明显降低等。可因心律紊乱和呼吸麻痹而死亡。吸入烟尘可引起中毒，但消化道症状不明显。慢性影响：长期接触钡化合物的工人，可有无力、气促、流涎、口腔粘膜肿胀糜烂、鼻炎、结膜炎、腹泻、心动过速。血压增增高、脱发等。', '对环境可能有害。', '本品不燃，高毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4889, 4997, NULL, NULL, NULL, NULL, NULL, '第8.2类碱性腐蚀品', '吸入、食入、皮肤接触、眼睛接触', '可造成消化道灼伤，粘膜糜烂、出血，休克。', '对水体可造成污染。', '本品不燃，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4890, 4998, NULL, NULL, NULL, NULL, NULL, '第8.2类碱性腐蚀品', '吸入、食入、经皮吸收', '可引起喉、支气管炎症、痉挛，化学性肺炎、肺水肿等。皮肤接触可造成严重灼伤和眼损伤。', '对水体可造成污染。', '本品不燃、具有强腐蚀性、可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4891, 4999, NULL, NULL, NULL, NULL, NULL, '第8.2类碱性腐蚀品', '吸入、食入、皮肤接触、眼睛接触', '误服可造成消化道灼伤，粘膜糜烂、出血和休克。', '对水体可造成污染。', '本品不燃，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4892, 5000, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '短期大量接触可引起急性铍病，主要表现为急性化学性支气管炎或肺炎。肝脏往往肿大，有压痛，甚至出现黄疸。长期接触小量铍可发生慢性铍病。除无力、消瘦、食欲不振外，常有胸闷、胸痛、气短和咳嗽。X线肺部检查分为三型：颗粒型、网织型和结节型。晚期可发生右心衰竭。皮肤病变有皮炎、溃疡及皮肤肉芽肿。', '对环境可能有害。', '本品不燃，高毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4893, 5001, NULL, NULL, NULL, NULL, NULL, '第8.2类碱性腐蚀品', '吸入、食入、经皮吸收', '可引起呼吸道刺激，伴有咳嗽、呼吸道阻塞和粘膜损伤。吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入可造成消化道灼伤，粘膜糜烂、出血和休克。皮肤接触可造成严重灼伤和眼损伤。', '对水体可造成污染。', '本品不燃、具有强腐蚀性、可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4894, 5002, NULL, NULL, NULL, NULL, NULL, '第8.2类碱性腐蚀品', '吸入、食入、经皮吸收', '可引起呼吸道刺激，伴有咳嗽、呼吸道阻塞和粘膜损伤。吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入可造成消化道灼伤，粘膜糜烂、出血和休克。', '对水体可造成污染。', '本品不燃、具有强腐蚀性、可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4895, 5003, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '在正常生产处理过程中，吸入粉尘可引起中毒。铊化合物为剧毒，可经呼吸道、消化道和皮肤吸收，对中枢神经系统、消化系统、肾脏和心脏等器官造成损害。', '对环境可能有害。', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4896, 5004, NULL, NULL, NULL, NULL, NULL, '第2.3类 有毒气体', '吸入', '氰的刺激性比氰化氢略弱，而毒性则小得多。氰的轻度中毒，病人出现乏力、头痛、头昏、胸闷及粘膜刺激症状；严重中毒者，呼吸困难、意识丧失、出现惊厥，最后可因呼吸中枢麻痹而死亡。', '无资料', '本品易燃、高毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4897, 5005, NULL, NULL, NULL, NULL, NULL, '第4.3类遇湿易燃物品', '吸入、食入', '吸入、摄入或经皮肤吸收均有毒。对眼睛、皮肤有刺激作用。口服有毒，可引起头痛、眩晕、恶心、呕吐、呼吸困难等症状。长期接触可引起慢性中毒，影响神经系统、肾脏和肝脏。', '对环境有危害，对水体和土壤可造成污染。对水生生物有极高毒性。', '本品遇湿易燃、具有刺激性。本身不燃烧，但遇水或潮气、酸类产生易燃气体并放热，有发生燃烧爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4898, 5006, NULL, NULL, NULL, NULL, NULL, '第6.1类剧毒化学品', '吸入、食入、皮肤接触、眼睛接触', '吸入、摄入或经皮肤吸收均有剧毒。皮肤长期接触产生水疱；食入后恶心和腹痛，伴随呕吐和腹泻；唇、肢体有难忍的灼伤和刺痛感，出现错乱、幻觉、易激动、睡眠及肌肉失调、失去记忆、视域变窄、情绪不稳、注意力不集中，甚至僵木、昏迷。长期接触可引起慢性汞中毒，影响神经系统、肾脏和消化系统。', '对环境有严重危害，对水体和土壤可造成污染。对水生生物有极高毒性。汞及其化合物在环境中具有持久性和生物富集性。', '本身不燃烧，但受热分解产生剧毒的氰化氢、汞蒸气和氮氧化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4899, 5007, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '氰化物抑制呼吸酶，造成细胞内窒息。吸入、口服或经皮肤吸收均可引起中毒。中毒表现有头痛、眩晕、恶心、呕吐、呼吸困难、心悸、阵发性和强直性痉挛、昏迷、紫绀、呼吸心跳停止。', '无资料', '本品不燃，剧毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4900, 5008, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入、摄入或经皮肤吸收本品可能致死。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '该物质对环境有危害，应特别注意对水体的污染。', '受高热分解，放出腐蚀性、刺激性的烟雾。受热分解产生剧毒的氰化氢气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4901, 5009, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '抑制呼吸酶。造成细胞内窒息。吸入、口服或经皮吸收均可引起急性中毒。大剂量接触引起骤死。非骤死者临床分为4期：前驱期有粘膜刺激、呼吸加快加深、乏力、头痛；口服有舌尖、咽喉发麻、流涎、恶心、呕吐、腹痛、腹泻等；呼吸困难期出现呼吸困难、紫绀、脉搏加快、意识模糊；麻痹期出现昏迷、抽搐、大小便失禁、呼吸心跳停止。', '无资料', '本品不燃，高毒。遇酸或露置空气中能吸收水分和二氧化碳分解出剧毒的氰化氢气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4902, 5010, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收均有毒。对眼睛、皮肤有刺激作用。口服剧毒，非骤死者，先出现感觉无力、头痛、眩晕、恶心、呕吐、四肢沉重以及呼吸困难等症状，随后面色苍白、失去知觉、甚至呼吸停止而死亡。长期接触可引起慢性中毒，影响神经系统、肾脏和肝脏。镉化合物可引起镉中毒，主要损害肾脏和骨骼。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。对环境有危害，对水体和土壤可造成污染。', '本品不燃、剧毒。遇酸或露置空气中能吸收水分和二氧化碳分解出剧毒的氰化氢气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4903, 5011, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '接触后氰化物和汞中毒的症状均可出现。吸入：惊厥、呼气呈苦杏仁味。口服：腹痛、呕吐、严重腹泻及上述氰化物中毒症状。眼接触：引起角膜溃疡和水肿。对皮肤有刺激性，可引起皮炎；经皮吸收可引起中毒。', '对环境有危害，对水体可造成污染。', '本品不燃，剧毒，具刺激性。遇酸或露置空气中能吸收水分和二氧化碳分解出剧毒的氰化氢气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4904, 5012, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。汞中毒可引起中枢神经系统损害、肾功能损害等。氰化物中毒可引起组织缺氧、细胞窒息。', '对水生生物有极高毒性。在环境中可持久存在，具有生物富集性。对土壤和地下水造成污染。', '本品不燃。受热分解产生有毒的氰化氢和汞蒸气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4905, 5013, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吞食后有剧毒。跟皮肤接触有剧毒。吸入有剧毒。有轻微致癌性风险。氰化物抑制呼吸酶，造成细胞内窒息。中毒表现有头痛、眩晕、恶心、呕吐、呼吸困难、心悸、阵发性和强直性痉挛、昏迷、紫绀、呼吸心跳停止。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '本品不燃，剧毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4906, 5014, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吞食后有剧毒。跟皮肤接触有剧毒。吸入有剧毒。可能有发生不可逆性作用的危险。有轻微致癌性风险。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生物有剧毒,对水生环境可能会引起长期有害作用。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4907, 5015, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '抑制呼吸酶，造成细胞内窒息。吸入、口服或经皮吸收均可引起急性中毒。口服50～100mg即可引起猝死。非骤死者临床分为4期：前驱期有粘膜刺激、呼吸加深加快、乏力、头痛；口服有舌尖、口腔发麻等。呼吸困难期有呼吸困难、血压升高、皮肤粘膜呈鲜红色等。惊厥期出现抽搐、昏迷、呼吸衰竭。麻痹期全身肌肉松弛，呼吸心跳停止而死亡。长期接触小量氰化物出现神经衰弱综合征、眼及上呼吸道刺激。可引起皮疹、皮肤溃疡。', '对环境有危害，对水体和土壤可造成污染。', '本品不燃，高毒，具刺激性。遇酸或露置空气中能吸收水分和二氧化碳分解出剧毒的氰化氢气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4908, 5016, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吞食后有剧毒。跟皮肤接触有剧毒。吸入有剧毒。', '对水生物有剧毒,对水生环境可能会引起长期有害作用。', '遇明火、高热可燃。受热分解产生有毒的氰化氢和氮氧化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4909, 5017, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吞食后有剧毒。跟皮肤接触有剧毒。吸入有剧毒。', '对水生物有剧毒,对水生环境可能会引起长期有害作用。', '遇明火、高热可燃。受热分解产生剧毒的氰化氢气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4910, 5018, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '服有舌尖、口腔发麻等。呼吸困难期有呼吸困难、血压升高、皮肤粘膜呈鲜红色等。惊厥期\n出现抽搐、昏迷、呼吸衰竭。麻痹期全身肌肉松弛，呼吸心跳停止而死亡。长期接触小量氰\n化物出现神经衰弱综合征、眼及上呼吸道刺激。可引起皮疹。', '对水生生物有极高毒性。氰化物对水生生态系统有严重危害，可能导致鱼类和其他水生生物大量死亡。氰化物污染地下水后，会对饮用水源造成严重威胁。在环境中可被生物降解，但降解速度较慢。', '本品不燃，剧毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4911, 5019, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、误服可致死。非骤死者，先出现无力、头痛、眩晕、恶心、四肢沉重、呼吸困难，随后出现阵发性抽搐、昏迷、呼吸停止而死亡。镍化合物属致癌物。长期接触可引起慢性中毒，影响神经系统、肾脏和肝脏。', '对环境有危害，对水体和土壤可造成污染。对水生生物有极高毒性。', '本品不燃、剧毒。遇酸或露置空气中能吸收水分和二氧化碳分解出剧毒的氰化氢气体。受高热分解，放出高毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4912, 5020, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吞食后有毒。跟皮肤接触可能会引起敏化作用。有引起过敏、哮喘病症状或呼吸困难的风险。吸入、摄入或经皮肤吸收均有毒。对眼睛、皮肤有刺激作用。口服剧毒，非骤死者，先出现感觉无力、头痛、眩晕、恶心、呕吐、四肢沉重以及呼吸困难等症状，随后面色苍白、失去知觉、甚至呼吸停止而死亡。镍化合物属致癌物。长期接触可引起慢性中毒，影响神经系统、肾脏和肝脏。', '对水生环境可能会引起长期有害作用。对环境有危害，对水体和土壤可造成污染。对水生生物有极高毒性。', '本品不燃、剧毒。遇酸或露置空气中能吸收水分和二氧化碳分解出剧毒的氰化氢气体。受高热可能发生爆炸性分解。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4913, 5021, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入', '属剧毒物质。吸入、误服可致死。非骤死者，先出现无力、头痛、眩晕、恶心、呕吐、四肢沉重、呼吸困难，随后失去知觉，呼吸停止。长期慢性吸入，可能引起铅中毒。', '对环境有危害，对水体和土壤可造成污染。', '本品不燃、剧毒。遇酸或露置空气中能吸收水分和二氧化碳分解出剧毒的氰化氢气体。受高热分解，放出高毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4914, 5022, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入', '属剧毒物质。吸入、误服可致死。非骤死者，先出现无力、头痛、眩晕、恶心、呕吐、四肢沉重、呼吸困难，随后失去知觉，呼吸停止。氰化物能抑制细胞呼吸，造成组织缺氧。', '对环境有危害，对水体和土壤可造成污染。', '本品不燃、剧毒。遇酸或露置空气中能吸收水分和二氧化碳分解出剧毒的氰化氢气体。受高热分解，放出高毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4915, 5023, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '蒸气对呼吸道有刺激性。吸入后可引起氰化物中毒，出现头痛、乏力、呼吸困难、皮肤粘膜呈鲜红色、抽搐、昏迷等。高浓度吸入可立即引起呼吸心跳停止而死亡。可引起皮肤和眼灼伤。口服可致死。长期接触可引起慢性中毒，影响神经系统、肾脏和肝脏。', '对环境有危害，对水体和土壤可造成污染。对水生生物有极高毒性。', '本品不燃，高毒，具刺激性。遇酸或露置空气中能吸收水分和二氧化碳分解出剧毒的氰化氢气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4916, 5024, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '毒作用似氢氰酸，并有明显刺激性。吸入后引起紫绀、头痛、头晕、恶心、呕吐、虚弱、神志不清、惊厥、呼吸困难、咳嗽，重者发生肺水肿，可致死。对眼和皮肤有强烈刺激性，可致灼伤。口服后引起口腔和胃刺激或灼伤，可引起死亡。', '对水生生物有极高毒性。在环境中可持久存在，具有生物富集性。对土壤和地下水造成污染。', '本品不燃，高毒，具强刺激性。受热分解产生剧毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4917, 5025, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。氰化物抑制细胞呼吸，可导致组织缺氧。对眼睛、皮肤、粘膜和上呼吸道有刺激性。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '遇明火、高热可燃。受高热分解放出有毒的氰化氢气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4918, 5026, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '吸入后引起紫绀、头痛、头晕、恶心、呕吐、虚弱、惊厥、昏迷、咳嗽、呼吸困难。对呼吸道有强烈刺激性，可引起肺水肿而致死。对皮肤、眼有强烈刺激性，可致灼伤。口服出现紫绀、头痛、头晕、恶心、呕吐、虚弱、昏迷、呼吸困难、血压下降等；刺激口腔和消化道或造成灼伤。', '对水生生物有极高毒性。', '本品不燃，高毒，具强刺激性。遇酸或露置空气中能吸收水分和二氧化碳分解出剧毒的氰化氢气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4919, 5027, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收均有毒。口服剧毒。非骤死者，先出现感觉无力、头痛、眩晕、恶心、呕吐、四肢沉重以及呼吸困难等症状，随后面色苍白、失去知觉，甚至呼吸停止而死亡。氰化物通过抑制细胞色素氧化酶，阻断细胞呼吸，导致组织缺氧，主要影响中枢神经系统、心血管系统和甲状腺。', '对水生生物有极高毒性。氰化物对水生生态系统有严重危害，可能导致鱼类和其他水生生物大量死亡。氰化物污染地下水后，会对饮用水源造成严重威胁。', '本品不燃、剧毒。受高热或接触酸或酸雾放出剧毒的氰化氢烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4920, 5028, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收均有毒。口服剧毒。非骤死者，先出现感觉无力、头痛、眩晕、恶心、呕吐、四肢沉重以及呼吸困难等症状，随后面色苍白，失去知觉，甚至呼吸停止而死亡。氰化物通过抑制细胞色素氧化酶，阻断细胞呼吸，导致组织缺氧，主要影响中枢神经系统、心血管系统和甲状腺。', '对水生生物有极高毒性。氰化物对水生生态系统有严重危害，可能导致鱼类和其他水生生物大量死亡。氰化物污染地下水后，会对饮用水源造成严重威胁。', '本品不燃、剧毒。受高热或接触酸或酸雾放出剧毒的氰化氢烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4921, 5029, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入', '受高热或与酸接触，可产生氰化物气体，吸入后引起氰化物中毒，出现头痛、乏力、呼吸困难、皮肤粘膜呈鲜红色、抽搐、昏迷，甚至死亡。对眼和皮肤有刺激性。长期接触可引起慢性中毒。', '对环境有危害，对水体和土壤可造成污染。', '本品不燃，高毒，具刺激性。遇酸或露置空气中能吸收水分和二氧化碳分解出剧毒的氰化氢气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4922, 5030, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收均有毒。对眼睛、皮肤有刺激作用。口服剧毒，非骤死者，先出现感觉无力、头痛、眩晕、恶心、呕吐、四肢沉重以及呼吸困难等症状，随后面色苍白、失去知觉、甚至呼吸停止而死亡。长期接触可引起慢性中毒，影响神经系统、肾脏和肝脏。', '对环境有危害，对水体和土壤可造成污染。对水生生物有极高毒性。', '本品不燃、剧毒。遇酸或露置空气中能吸收水分和二氧化碳分解出剧毒的氰化氢气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4923, 5031, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收均有毒。对眼睛、皮肤有刺激作用。口服有毒，可引起头痛、眩晕、恶心、呕吐、呼吸困难等症状。长期接触可引起慢性中毒，影响神经系统、肾脏和肝脏。', '对环境有危害，对水体和土壤可造成污染。对水生生物有极高毒性。', '本品可燃、有毒，具刺激性。遇明火能燃烧。受潮或受高热分解释出剧毒的乙氰蒸气。具有腐蚀性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4924, 5032, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '兔皮下注射，最低致死量为1410mg/kg，出现痉挛性麻痹和呼吸兴奋。吸入、摄入或经皮肤吸收均有毒。对眼睛、皮肤有刺激作用。口服有毒，可引起头痛、眩晕、恶心、呕吐、呼吸困难等症状。长期接触可引起慢性中毒，影响神经系统、肾脏和肝脏。', '对环境有危害，对水体和土壤可造成污染。对水生生物有极高毒性。', '本品可燃、有毒。遇明火、高热可燃。与强氧化剂可发生反应。受高热分解放出有毒的气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4925, 5033, NULL, NULL, NULL, NULL, NULL, '非危险化学品', '吸入、食入', '吸入、摄入或经皮肤吸收可能有轻微毒性。对眼睛、皮肤有轻微刺激作用。口服可能引起轻微不适。长期接触可能对健康产生影响。', '对环境可能有轻微危害，对水体和土壤可能造成污染。对水生生物可能有毒性。', '受热分解放出剧毒的氰化物气体。遇明火、高热可燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4926, 5034, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入', '本品对眼睛、皮肤和呼吸道有强腐蚀性。易吸潮发热，能被水分解释放出有毒性和腐蚀性的氯化氢气体。接触后可引起喉炎、化学性肺炎、肺水肿等。吸入、摄入或经皮肤吸收均有毒。对眼睛、皮肤有刺激作用。口服有毒，可引起头痛、眩晕、恶心、呕吐、呼吸困难等症状。长期接触可引起慢性中毒，影响呼吸系统。', '对环境有危害，对水体和土壤可造成污染。对水生生物有极高毒性。', '本品可燃、有毒、具有强腐蚀性、可致人体灼伤。遇明火、高热可燃。受热分解产生有毒的氯化氢气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4927, 5035, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '蒸气或雾对眼、粘膜和上呼吸道有刺激性。对皮肤有刺激性。吸入、摄入或经皮吸收后可能引起中毒。氰基化合物具有抑制细胞呼吸的作用，可导致组织缺氧。', '该物质对环境可能有危害，应特别注意对水体的污染。氰基化合物对水生生物有毒性，在环境中可能持久存在。', '遇明火、高热可燃。与强氧化剂可发生反应。受高热分解放出有毒的气体，包括氰化氢等有毒物质。蒸气与空气可形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4928, 5036, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品；皮肤腐蚀/刺激，类别2；严重眼损伤/眼刺激，类别2；特异性靶器官毒性-反复接触，类别2', '吸入、食入、皮肤接触、眼睛接触', '吸入、食入或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。接触可引起皮肤灼伤、眼睛灼伤。长期或反复接触可能对呼吸系统、肝脏、肾脏造成损害。可能具有致癌性。', '对水生物有毒，对水生环境可能会引起长期有害作用。在环境中难以降解，具有生物累积性。', '遇明火、高热可燃。受热分解产生有毒的氟化氢、二氧化硫等气体。与氧化剂接触有发生燃烧爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4929, 5037, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吞咽有害。吸入有害。怀疑会致癌。可能对母乳喂养的儿童造成伤害。长期或反复接触会对器官造成损害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。可能影响内分泌系统和生殖系统。', '对水生物有毒，对水生环境可能会引起长期有害作用。对土壤和地下水可能造成污染。具有持久性、生物富集性和毒性（PBT）特性。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4930, 5038, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期或反复接触可能对器官造成损害。', '对水生物有毒，对水生环境可能会引起长期有害作用。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4931, 5039, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期接触可能影响肝脏、内分泌系统和生殖系统。', '对水生物有毒，对水生环境可能会引起长期有害作用。属于持久性有机污染物（POPs），在环境中难以降解，具有生物富集性。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4932, 5040, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入、食入或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期接触可能影响肝脏、内分泌系统和生殖系统。属于持久性有机污染物（POPs），在环境中难以降解，具有生物富集性。', '对水生物有毒，对水生环境可能会引起长期有害作用。属于持久性有机污染物（POPs），在环境中难以降解，具有生物富集性。对土壤和地下水可能造成长期污染。', '受热分解产生有毒的氟化物和硫氧化物烟雾。遇明火、高热可燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4933, 5041, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期接触可能对肝脏、甲状腺、免疫系统等造成损害。具有生殖毒性、发育毒性和致癌性。', '对水生物有毒，对水生环境可能会引起长期有害作用。', '受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4934, 5042, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品；皮肤腐蚀/刺激，类别2；严重眼损伤/眼刺激，类别2；特异性靶器官毒性-反复接触，类别2', '吸入、食入、皮肤接触、眼睛接触', '吸入、食入或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。接触可引起皮肤灼伤、眼睛灼伤。长期或反复接触可能对呼吸系统、肝脏、肾脏造成损害。可能具有致癌性。', '对水生物有毒，对水生环境可能会引起长期有害作用。在环境中难以降解，具有生物累积性。', '遇明火、高热可燃。受热分解产生有毒的氟化氢、二氧化硫等气体。与氧化剂接触有发生燃烧爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4935, 5043, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '因喉和支气管的痉挛、炎症和水肿，化学性肺炎或肺水肿而致死。接触后可引起烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '该物质对环境有危害，应特别注意对水体和土壤的污染。对水生生物有剧毒，可能对水生环境造成长期不利影响。在环境中不易生物降解，可能在水体中持久存在。', '本品不燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4936, 5044, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '具有致畸、致突变作用。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期接触可能引起慢性中毒，影响肝脏、肾脏和神经系统功能。', '对水生生物有剧毒，可能对水生环境造成长期不利影响。属于持久性有机污染物（POPs），在环境中难降解，具有生物富集性。', '本品可燃、有毒。受高热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4937, 5045, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收对身体有害。蒸气或雾对眼、粘膜和上呼吸道有刺激性。对皮肤有刺激性。', '对环境有危害，对水体可造成污染。', '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4938, 5046, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入、食入', '对眼睛、皮肤和粘膜有刺激性。', '无资料', '遇明火、高热可燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4939, 5047, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收', '对眼睛、皮肤、粘膜有刺激作用。未见职业中毒的报道。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4940, 5048, NULL, NULL, NULL, NULL, NULL, '第9类杂项危险物质和物品', '吸入 食入 经皮吸收', '对眼睛、皮肤、粘膜有刺激作用。目前，未见工业中毒的报道。', '无资料', '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4941, 5049, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入', '目前，未见职业中毒的报道。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4942, 5050, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有刺激作用。可引起皮肤过敏。长期接触可能影响生殖系统。吸入可引起头痛、头晕、恶心等症状。食入可引起胃肠道刺激。', '对水生物有毒，对水生环境可能会引起长期有害作用。', '遇明火、高热可燃。受热分解产生有毒气体。与氧化剂可发生反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4943, 5051, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '对皮肤有刺激性。对眼睛有严重刺激性。可能有损伤胎儿或胚胎的危险。长期暴露有损害健康的风险。', '对水生物有毒，对水生环境可能会引起长期有害作用。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4944, 5052, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入 食入 经皮吸收', '本品对眼睛、皮肤和粘膜有腐蚀和刺激作用。受热分解放出有毒的氯气烟雾。', '无资料', '本品可燃、有毒、具有腐蚀性、刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4945, 5053, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入', '未见职业中毒的资料报道。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4946, 5054, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入经皮吸收', '大鼠吸入8100mg/m3浓度引起轻度震颤、共济矢调和眼刺激。无人的资料。', '对水生生物有害。', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4947, 5055, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, '对水生物有毒，对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4948, 5056, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, '对水生物有毒，对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4949, 5057, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入 食入 经皮吸收', '本品对皮肤有刺激作用。受热分解放出有腐蚀性、刺激性的烟雾。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4950, 5058, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入、食入、经皮吸收', '麻醉剂，也具有引起兴奋和痉挛的作用。其蒸气刺激呼吸道粘膜。对造血系统亦有毒性作用(刺激骨髓中白细胞的生成)。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4951, 5059, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有剧毒。跟皮肤接触有剧毒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4952, 5060, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '本品对眼睛、皮肤和粘膜有刺激作用。对人有致突变作用。可引起睾丸萎缩和不育。具有致癌性，被列入《优先控制化学品名录(第三批)》。', '对水生生物有毒性作用，可能对水环境造成长期不利影响。', '遇明火、高热可燃。受高热分解，放出高毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4953, 5061, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '有毒，摄入、吸入或经皮肤吸收可引起中毒。对胆碱酯酶有抑制作用，引起有机磷中毒的症状。', '对环境有危害。', '本品可燃、有毒。遇明火、高热可燃。受高热分解，放出有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4954, 5062, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '本品为有机锡化合物，具有毒性。摄入或与皮肤接触可引起中毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。急性中毒可出现头痛、头晕、恶心、呕吐、腹痛、腹泻等症状。严重中毒可导致神经系统损害、肝肾功能损伤。遇热分解释出有毒的氮氧化物烟雾和锡化合物。', '对环境有危害，对水体可造成污染。对水生生物有极高毒性，可能在水生环境中造成长期不利影响。有机锡化合物对水生生态系统具有持久性和生物富集性。', '遇明火、高热可燃。受高热分解，放出有毒的烟气，包括一氧化碳、二氧化碳、氮氧化物和氧化锡。在火场中，受热的容器有爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4955, 5063, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4956, 5064, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '对眼、上呼吸道、粘膜和皮肤有刺激性。有神经毒效应。', '无资料', '本品可燃，有毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4957, 5065, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入', '本品有刺激性和腐蚀性，对眼睛、皮肤、粘膜和上呼吸道有刺激作用，遇火散发出有毒气体。', '对水生生物有害，可能对水体环境造成长期不良影响。水解产物氯化氢可能对水体造成酸化影响。', '本品可燃、具有强腐蚀性、刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4958, 5066, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n主要引起神经系统的损害。其临床表现有头痛、头晕、精神萎靡、乏力、恶心、食欲减退', '等。对皮肤可引起接触性皮炎、过敏性皮炎。长期接触，可引起神经衰弱综合征。', '无资料', '本品可燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4959, 5067, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入', '对眼和皮肤无刺激性。未见中毒病例报道。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4960, 5068, NULL, NULL, NULL, NULL, NULL, '第4.2类自燃物品', '吸入、食入、经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。吸入其蒸气，可引起类似金属烟尘热的表现。', '对水生生物有剧毒，对水生环境可能会引起长期有害作用。', '本品易燃、有毒、具有强刺激性。遇空气自燃，遇水剧烈反应放出易燃气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4961, 5069, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '吸入、摄入或经皮肤吸收后会中毒。受热分解释出氯烟雾。', '无资料', '本品可燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4962, 5070, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n无机砷化合物口服中毒表现为急性胃肠炎、休克、中毒性心肌炎、肝炎，以及抽搐、昏迷等，', NULL, NULL, '本品不燃，高毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4963, 5071, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, '对水生物有毒，对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4964, 5072, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入', '本品有腐蚀性和毒性。对眼睛、粘膜、皮肤和上呼吸道有强烈刺激作用。', '无资料', '本品不燃，具腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4965, 5073, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n对呼吸道有刺激性，吸入后出现咳嗽、呼吸困难、胸痛，重者发生肺水肿。高浓度接触可\n引起神经系统改变，出现精神错乱、兴奋、头痛、幻觉、共济失调等。对眼有刺激性。口', NULL, '无资料', '本品不燃，有毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4966, 5074, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入', '本品对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '无资料', '本品不燃、有毒、具有腐蚀性、刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4967, 5075, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '本品为高毒类有机锡化合物。急性中毒患者可出现头痛、头晕、乏力、恶心、呕吐、腹痛、腹泻等症状，严重者可引起中毒性脑病，表现为意识障碍、抽搐、昏迷等。对皮肤、眼睛和呼吸道有刺激作用。长期接触可引起慢性中毒，影响神经系统、肝脏和肾脏功能。遇热分解释出有毒的氟化氢和锡化合物烟雾。', '对水生生物有极高毒性，可能对水体环境造成长期不利影响。对土壤和地下水有污染风险。在环境中具有持久性，不易降解。', '遇明火、高热可燃。受高热分解，放出有毒的氟化氢、锡化合物、一氧化碳、二氧化碳等烟气。与氧化剂接触有燃烧爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4968, 5076, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收\n吸入、摄入或经皮吸收后对身体有害。', '嗽、喉炎、气短、头痛、恶心和呕吐。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4969, 5077, NULL, NULL, NULL, NULL, NULL, '第4.2类自燃物品，第4.3类遇水放出易燃气体的物质', '吸入、食入、经皮吸收', '本品为有机铝化合物，具有高度反应性。吸入蒸气可引起呼吸道刺激、咳嗽、呼吸困难。皮肤接触可引起严重灼伤。眼睛接触可引起严重刺激和灼伤。食入可引起严重的胃肠道刺激、灼伤。长期接触可能对神经系统、肝脏和肾脏造成损害。遇水分解释放出易燃气体，可能引发火灾或爆炸。', '对水生生物有极高毒性，可能对水体环境造成长期不利影响。在环境中具有持久性，不易降解。', '在空气中极易自燃，遇水剧烈反应放出易燃气体（氢气），有引发火灾和爆炸的危险。受热或接触火焰可能产生膨胀或爆炸性分解。与氧化剂、酸类、碱类、卤素等接触有燃烧爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4970, 5078, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '本品为高毒类有机锡化合物。急性中毒患者可出现头痛、头晕、乏力、恶心、呕吐、腹痛、腹泻等症状，严重者可引起中毒性脑病，表现为意识障碍、抽搐、昏迷等。对皮肤、眼睛和呼吸道有刺激作用。长期接触可引起慢性中毒，影响神经系统、肝脏和肾脏功能。遇热分解释出有毒的氯化氢和锡化合物烟雾。', '对水生生物有极高毒性，可能对水体环境造成长期不利影响。对土壤和地下水有污染风险。在环境中具有持久性，不易降解。', '遇明火、高热可燃。受高热分解，放出有毒的氯化氢、锡化合物、一氧化碳、二氧化碳等烟气。与氧化剂接触有燃烧爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4971, 5079, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, '在空气中容易自身燃烧,有引发火灾的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4972, 5080, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, '对水生物有剧毒,对水生环境可能会引起长期有害作用。', '易燃,其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4973, 5081, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、食入或经皮肤吸收可引起中毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期接触可影响神经系统。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4974, 5082, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, '对水生物有剧毒,对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4975, 5083, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, '对水生物有剧毒,对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4976, 5084, NULL, NULL, NULL, NULL, NULL, '侵入途径：', '吞食后有毒。跟皮肤接触有毒。对皮肤有刺激性。对眼睛有严重刺激性。吸入有剧毒。', NULL, '对水生物有剧毒,对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4977, 5085, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吞食后有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。对水生物有剧毒。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4978, 5086, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入 食入 经皮吸收', '吸入、食入、经皮吸收。对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用。吸入后可引起头痛、头晕、恶心、呕吐、咳嗽、胸闷、呼吸困难等。高浓度吸入可引起肺水肿。对中枢神经系统有抑制作用。', '对环境有危害，对水体可造成污染。', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4979, 5087, NULL, NULL, NULL, NULL, NULL, '第8类腐蚀性物质', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤、粘膜有强烈腐蚀性和刺激性。吸入粉尘可引起呼吸道刺激、咳嗽、呼吸困难。遇水分解产生氟化氢，可引起严重的化学灼伤。长期或反复接触可能引起慢性氟中毒，表现为氟斑牙、氟骨症等。', '该物质对环境有危害，应特别注意对水体和土壤的污染。氟化物对水生生物有毒性。', '不燃。受热分解产生有毒的氟化氢烟雾。遇水分解产生氟化氢，具有强腐蚀性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4980, 5088, NULL, NULL, NULL, NULL, NULL, '第2.3类 有毒气体', '吸入', '吸入后可引起头痛、头晕、恶心、呕吐、乏力等。高浓度吸入可引起肺水肿、呼吸衰竭。对眼睛、皮肤、粘膜有刺激性。', '对大气可造成污染。', '强氧化剂。与易燃物、可燃物、还原剂等接触发生剧烈反应，甚至引起燃烧爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4981, 5089, NULL, NULL, NULL, NULL, NULL, '第2.3类有毒气体', '吸入、皮肤接触、眼睛接触', '对皮肤、眼睛、粘膜呈强烈刺激作用，吸入可引起上、下呼吸道炎症及肺水肿。高浓度接触可引起化学性肺炎、肺水肿，甚至死亡。', '该物质对环境有危害，应特别注意对水体和空气的污染。', '本品不燃，但遇火源会分解产生有毒气体。具有强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4982, 5090, NULL, NULL, NULL, NULL, NULL, '第2.3类 有毒气体', '吸入、皮肤接触、眼睛接触', '吸入有毒。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。吸入可引起肺水肿、喉头水肿而窒息。高浓度接触可引起化学性肺炎。', '对水生生物有害。对大气臭氧层有潜在破坏作用。', '强氧化剂。与可燃物、还原剂、有机物等接触能发生剧烈反应，引起燃烧或爆炸。遇水剧烈反应，放出剧毒和腐蚀性的烟雾。遇火源会助燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4983, 5091, NULL, NULL, NULL, NULL, NULL, '第2.3类有毒气体', '吸入、皮肤接触、眼睛接触', '急性中毒：主要症状有干咳、气急、胸闷、胸部紧迫感；部分患者出现恶心、食欲减退、流涎。吸入量多时，有震颤及抽搐，亦可引起肺炎。皮肤接触可致灼伤。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激和腐蚀作用。吸入可引起喉头水肿、支气管痉挛、化学性肺炎、肺水肿等。', '对水生生物有毒性。可能对水环境造成长期不利影响。', '本品不燃，有毒。遇水发生爆炸性分解。暴露在空气中遇潮气时迅速水解成氟硼酸与硼酸，产生白色烟雾。腐蚀性很强，冷时也能腐蚀玻璃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4984, 5092, NULL, NULL, NULL, NULL, NULL, '第8类腐蚀品', '吸入、食入、皮肤接触、眼睛接触', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用和腐蚀作用。吸入可引起喉、支气管痉挛、炎症、水肿，化学性肺炎或肺水肿。接触可引起灼伤。', '该物质对环境可能有危害，对水体应给予特别注意。', '极端易燃，有爆炸危险。会跟水激烈反应，生成高度易燃的气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4985, 5093, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用和腐蚀作用。吸入可引起喉、支气管的炎症、水肿、痉挛，化学性肺炎或肺水肿。接触可引起灼伤。长期反复接触可引起皮肤干燥、皲裂和皮炎。', '对水生生物有毒性。对环境有危害，应特别注意对水体的污染。', '遇明火、高热可燃。受热分解产生有毒的氟化氢、氮氧化物等气体。具有腐蚀性和强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4986, 5094, NULL, NULL, NULL, NULL, NULL, '第3类易燃液体', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤、粘膜有强烈刺激作用和腐蚀性。吸入可引起呼吸道刺激、咳嗽、呼吸困难。误服可引起口腔、咽喉、食道和胃部灼伤。长期接触可能导致皮肤过敏。', '对水生生物有害，可能对水体环境造成长期不良影响。避免释放到环境中。', '易燃,其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4987, 5095, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤、粘膜有强烈刺激作用和腐蚀性。吸入可引起呼吸道刺激、咳嗽、呼吸困难。误服可引起口腔、咽喉、食道和胃部灼伤。长期接触可能导致皮肤过敏。', '对水生生物有害，可能对水体环境造成长期不良影响。避免释放到环境中。', '遇明火、高热可燃。受热分解产生有毒气体。具有强腐蚀性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4988, 5096, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、经皮吸收、眼睛接触', '对眼睛、皮肤、粘膜有强腐蚀性。误服会中毒。能严重灼伤皮肤、眼睛和粘膜。吸入蒸气可引起呼吸道刺激、咳嗽、呼吸困难。长期接触可能导致皮肤过敏。', '对水生生物有害，可能对水体环境造成长期不良影响。避免释放到环境中。', '遇明火、高热可燃。受热分解产生有毒气体。具有强腐蚀性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4989, 5097, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '吸入、食入、经皮吸收均有毒。无机砷化合物口服中毒表现为急性胃肠炎、休克、中毒性心肌炎、肝炎，以及抽搐、昏迷等，甚至死亡。可在急性中毒的1～3周内发生周围神经病。大量吸入亦可引起急性中毒。慢性中毒：长期接触可引起皮肤色素沉着、掌跖角化、多发性神经病、肝损害等。砷化合物可致皮肤癌、肺癌。', '对环境有危害，对水体可造成污染。', '本品不燃，高毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4990, 5098, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入、摄入或经皮肤吸收可致死。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激性。吸入可引起喉头水肿、支气管痉挛、化学性肺炎、肺水肿。可引起头痛、恶心、呕吐、腹痛、腹泻。长期接触可引起慢性氟中毒，表现为氟斑牙、氟骨症等。锑化合物可对心血管系统、肝脏、肾脏造成损害。', '该物质对环境有危害，应特别注意对水体和土壤的污染。', '不燃。受热分解产生有毒的氟化氢烟雾。遇水或潮湿空气分解产生氟化氢。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4991, 5099, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入 食入', '有毒的氟和溴烟雾。', '无资料', '本品助燃、有毒、具有强腐蚀性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4992, 5100, NULL, NULL, NULL, NULL, NULL, '第2.2类 不燃气体', '吸入', '接触后可引起头痛、恶心和呕吐，有麻醉作用。', '对大气可造成污染。', '本品不燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4993, 5101, NULL, NULL, NULL, NULL, NULL, '第2.1类 易燃气体', '吸入', '接触高浓度三氟氯乙烯，出现头昏、眩晕、恶心、乏力、睡眠障碍等，一般都能恢复。高浓度接触可引起麻醉作用，对中枢神经系统有影响。', '该物质对环境有危害，对大气臭氧层有破坏作用。应特别注意对大气的污染。', '本品易燃，与空气混合能形成爆炸性混合物，遇明火、高热极易燃烧爆炸。受热分解产生有毒的氟化物和氯化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4994, 5102, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入、食入、经皮吸收', '吸入、口服或经皮吸收对身体有害。对眼睛、粘膜、呼吸道和皮肤有强烈刺激作用。吸入后可能因喉、支气管的痉挛、炎症、水肿，化学性肺炎、肺水肿而死亡。症状有烧灼感、咳嗽、喘息、气短、喉炎、头痛、恶心和呕吐。可致皮肤灼伤。', '对环境有害。对水生生物可能造成危害。', '本品不燃，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4995, 5103, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入、食入、皮肤接触、眼睛接触', '本品对皮肤、眼睛、粘膜和上呼吸道有强烈刺激作用和腐蚀性。吸入可引起呼吸道刺激、咳嗽、胸闷、呼吸困难，严重时可引起肺水肿。皮肤接触可引起灼伤、红肿、疼痛。眼睛接触可引起严重灼伤、角膜损伤。食入可引起口腔、食道和胃部灼伤。', '对环境有危害。对水体和大气可造成污染，应特别注意对水体的污染。', '本品不燃，具强腐蚀性、强刺激性，可致人体灼伤，具催泪性。遇水或醇类剧烈反应，产生三氟乙酸和相应的醇。受热分解产生有毒的氟化氢气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4996, 5104, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期或反复接触可能引起铬过敏。三价铬化合物毒性相对较低，但仍具有潜在危害。', '对水生物有剧毒,对水生环境可能会引起长期有害作用。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4997, 5105, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入 食入 经皮吸收', '咳嗽、喉炎、气短、头痛、恶心和呕吐等。', '对水体和大气可造成污染。', '本品易燃、具有腐蚀性、强刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4998, 5106, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '无资料', '本品可燃，有毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (4999, 5107, NULL, NULL, NULL, NULL, NULL, '第2.3类 有毒气体', '吸入', '对眼睛、皮肤、粘膜和上呼吸道具有剧烈的刺激作用。吸入后可引起喉、支气管的炎症、水肿和痉挛，化学性肺炎、肺水肿。接触后可有烧灼感、咳嗽、喘息、气短、头痛、恶心和呕吐。', '无资料', '本品不燃、有毒、强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5000, 5108, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '跟皮肤接触有剧毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期或反复接触可能引起皮肤过敏。对肝脏、肾脏有损害作用。', '对水生物有剧毒,对水生环境可能会引起长期有害作用。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5001, 5109, NULL, NULL, NULL, NULL, NULL, '第2.1类 易燃气体', '吸入 食入 经皮吸收\n对人体的主要危害是对眼、鼻、咽喉和呼吸道的刺激作用。浓三甲胺水溶液能引起皮肤剧烈的', '烧灼感和潮红，洗去溶液后皮肤上仍可残留点状出血。长期接触感到眼、鼻、咽喉干燥不适。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5002, 5110, NULL, NULL, NULL, NULL, NULL, '第3类易燃液体', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有刺激作用。吸入可引起呼吸道刺激。高浓度接触可引起头痛、头晕、恶心、呕吐等症状。', '无资料', '遇明火、高热可燃。受热分解产生有毒的氮氧化物烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5003, 5111, NULL, NULL, NULL, NULL, NULL, '第4.2类自燃物品', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。吸入可引起呼吸道刺激、咳嗽、呼吸困难。高浓度接触可引起肺水肿。接触可引起化学灼伤。', '无资料', '在空气中容易自身燃烧，有引发火灾的危险。会跟水激烈反应，生成高度易燃的气体。遇空气、湿气或水可能燃烧。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5004, 5112, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '对呼吸道、眼睛、皮肤粘膜有强烈刺激性。吸入后可因喉、支气管的痉挛、水肿、炎症、化学性肺炎、肺水肿而致死。接触工人往往有眼痛、流泪、咳嗽、头痛、易激动、皮肤发痒等。', '无资料', '本品极度易燃，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5005, 5113, NULL, NULL, NULL, NULL, NULL, '第4.2类 自燃物品', '吸入', '本品易燃、易爆，能使人烧伤。', '无资料', '本品有毒、属自燃物质', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5006, 5114, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。吸入，可引起喉、支气管痉挛、炎症，化学性肺炎、肺水肿。接触后可有烧灼感，出现咳嗽、气短、喉炎、头痛、恶心和呕吐等症状。遇热放出氯气；与水反应，放出氯化氢气体，造成腐蚀性灼伤。', '无资料', '本品易燃、具有腐蚀性、强刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5007, 5115, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, '高度易燃,其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5008, 5116, NULL, NULL, NULL, NULL, NULL, '第4.1类 易燃固体', '吸入 食入 经皮吸收\n吸入、摄入或经皮肤吸收对身体有害。', '呼吸道、眼和皮肤。接触后引起烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '无资料', '本品易燃、具强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5009, 5117, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入', '接触者可发生皮炎。未见职业中毒报道。注意，本品在高温下能分解产生高毒的氰化物气体。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5010, 5118, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收\n有毒。吸入有害。刺激眼睛、皮肤和呼吸系统。当接触酸或酸雾以及受高热时能分解释出\n有', '毒的氰化物、氮氧化物气体。', '无资料', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5011, 5119, NULL, NULL, NULL, NULL, NULL, '易燃液体，类别3。', '吸入、食入、皮肤接触、眼睛接触\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '易燃液体，其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5012, 5120, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, '易燃,其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5013, 5121, NULL, NULL, NULL, NULL, NULL, '第4.1类 易燃固体', '吸入 食入 经皮吸收\n误服或吸入', '皮肤接触有毒。', '无资料', '本品易燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5014, 5122, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入\n接触锑及其化合物可致眼结膜和呼吸道刺激，发生支气管炎，较重者出现胸痛、呼吸困难，口\n服中毒有急性胃肠炎，肝脏、肾脏和心肌损害。慢性影响：长期接触锑化合物粉尘可致鼻炎，', NULL, '无资料', '本品易燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5015, 5123, NULL, NULL, NULL, NULL, NULL, '第4.1类 易燃固体', '吸入 食入 经皮吸收', '前，未见其他严重症状报导。', '无资料', '本品易燃、高毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5016, 5124, NULL, NULL, NULL, NULL, NULL, '第4.3类遇湿易燃物品', '吸入食入经皮吸收\n对眼和呼吸道粘膜有强烈刺激作用。高浓度下，引起角膜混浊、呼吸道炎症，甚至肺水肿。', '并可伴有头昏、头痛、乏力、恶心、呕吐、心慌等症状。溅在皮肤上，可引起坏死，溃疡\n长期不愈。动物慢性中毒见慢性卡他性气管炎、支气管炎及早期肺硬化。', '无资料', '本品易燃，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5017, 5125, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入、食入、皮肤接触、眼睛接触', '本品具有刺激作用。对皮肤有强腐蚀性。加热分解成一氯化碘和极毒的氯气。', '无资料', '本品不燃，具腐蚀性、刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5018, 5126, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入', '摄入有毒。对眼睛、皮肤、粘膜有强烈的刺激作用。', '无资料', '本品不燃、有毒、具有腐蚀性、强刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5019, 5127, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入、食入、经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。三氯化磷在空气中可生成盐酸雾。对皮肤、粘膜有刺激腐蚀作用。短期内吸入大量蒸气可引起上呼吸道刺激症状，出现咽喉炎、支气管炎，严重者可发生喉头水肿致窒息、肺炎或肺水肿。皮肤及眼接触，可引起刺激症状或灼伤。严重眼灼伤可致失明。慢性影响：长期低浓度接触可引起眼及呼吸道刺激症状。可引起磷毒性口腔病。具强腐蚀性、强刺激性，可致人体灼伤。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '三氯化磷对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境有危害，应特别注意对水体的污染。在水生生物中可能发生生物蓄积。', '本品不燃，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5020, 5128, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入、食入、经皮吸收', '本品对皮肤、粘膜有强烈的刺激和腐蚀作用。吸入可引起呼吸道刺激症状，重者可发生化学性肺炎、肺水肿。误服可造成消化道灼伤。', '对水生生物有毒性作用，可能对水体环境造成长期不良影响。', '遇水或水蒸气反应放热并产生有毒的腐蚀性气体。对很多金属尤其是潮湿空气存在下有腐蚀性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5021, 5129, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期或反复接触可引起过敏反应。', '对水生生物有毒性作用。', '遇明火、高热可燃。受热分解产生有毒、腐蚀性烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5022, 5130, NULL, NULL, NULL, NULL, NULL, '第2.2类 不燃气体', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收对身体有害。可引起化学灼伤。对眼睛、皮肤、粘膜和上呼吸道有强烈的腐蚀作用。吸入后可因喉、支气管的痉挛、水肿，化学性肺炎、肺水肿而致死。中毒表现有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。慢性影响：具有神经毒性。', '无资料', '本品不燃，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5023, 5131, NULL, NULL, NULL, NULL, NULL, '第4.2类 自燃物品', '吸入、食入、经皮吸收', '遇热分解放出有毒的氯烟雾。吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用，可引起灼伤。吸入，可引起喉炎、化学性肺炎、肺水肿等。', '无资料', '本品极度易燃、有毒、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5024, 5132, NULL, NULL, NULL, NULL, NULL, '第4.2类自燃物品', '吸入、食入、皮肤接触、眼睛接触', '吸入、摄入或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。吸入可引起喉、支气管炎症、化学性肺炎、肺水肿。接触可引起头痛、头晕、恶心、呕吐、腹痛、腹泻等症状。', '对水生生物有极高毒性。', '在空气中容易自身燃烧,有引发火灾的危险。会跟水激烈反应,生成高度易燃的气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5025, 5133, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '蒸气对眼、呼吸道粘膜有强烈刺激性，可引起喉水肿致窒息。大量接触可引起神经损害、食欲不振、恶心、呕吐、腹痛、腹泻，甚至死亡。对皮肤有强烈刺激性，可致灼伤。可经皮肤吸收引起中毒。可致眼灼伤。本品在有酸或酸雾存在时，可产生溶血性毒物砷化氢。', '对环境有危害，对水体可造成污染。', '本品不燃，高毒，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5026, 5134, NULL, NULL, NULL, NULL, NULL, '第4.2类自燃物品', '吸入、食入、经皮吸收', '炎症、水肿，化学性肺炎或肺水肿而致死。接触后引起烧灼感、咳嗽、喘息、喉炎、气短、\n头痛、恶心、呕吐。', '无资料', '本品属自燃物品，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5027, 5135, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。可引起皮肤灼伤。长期接触可引起肝肿大，肝功能异常。', '无资料', '本品不燃，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5028, 5136, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、皮肤接触、眼睛接触', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。可引起灼伤。长期接触可引起慢性支气管炎、肺功能损害。', '对水生生物有毒性作用。对环境有危害。', '本品不燃，具腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5029, 5137, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收有毒。对眼睛、皮肤、粘膜均有腐蚀性。吸入蒸气会产生咽喉痛、咳嗽、呼吸困难，产生肺水肿，重者死亡。误服，可引起恶心、呕吐、腹痛、也可引起肺炎。', '无资料', '本品可燃、具有腐蚀性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5030, 5138, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。主要作用于中枢神经系统，具有麻醉作用，对心、肝、肾有损害。急性中毒：吸入或经皮肤吸收引起急性中毒。初期有头痛、头晕、恶心、呕吐、兴奋、皮肤湿热和粘膜刺激症状。以后呈现精神紊乱、呼吸表浅、反射消失、昏迷等，重者发生呼吸麻痹、心室纤维性颤动。同时可伴有肝、肾损害。误饮时，胃有烧灼感，伴恶心、呕吐、腹痛、腹泻。以后出现麻醉症状。液态可致皮炎、湿疹，甚至皮肤灼伤。慢性影响：主要引起肝脏损害，并有消化不良、乏力、头痛、失眠等症状，少数有肾损害及嗜氯仿癖。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '三氯甲烷对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境有危害，应特别注意对水体的污染。在水环境中很难被生物降解。破坏敏感水生生物的呼吸系统。蔬菜也能造成污染。在水生生物中可能发生生物蓄积。', '本品不燃，有毒，为可疑致癌物，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5031, 5139, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '动共济失调，在呼吸困难的情况下发生痉挛。死亡动物出现内脏器官充血，肺出血及较大块的\n水肿。', NULL, '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5032, 5140, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入\n蒸气强烈刺激眼和肺，具有全身毒作用。损害中、小支气管，导致中毒性肺炎和肺水肿。急性\n中毒：出现眼与咽喉部刺激症状、头痛、恶心、呕吐、腹痛、呼吸困难、心悸、气促、胸部紧', '束感等。严重者发生肺水肿，往往由于肺水肿而致死。可引起角膜炎和虹膜炎。皮肤接触可致\n灼伤。', '无资料', '本品不燃，剧毒，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5033, 5141, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、经皮吸收', '误服会中毒。对眼睛、皮肤、粘膜有刺激性和强腐蚀性。', '对环境有危害，对水体可造成污染。', '本品不燃、有毒、具有强腐蚀性、刺激性、可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5034, 5142, NULL, NULL, NULL, NULL, NULL, '第2.2类 不燃气体', '吸入', '高浓度可诱发心律不齐和抑制呼吸功能。对人的慢性影响未见报道。', '对大气臭氧层有极强的破坏作用，是受控的消耗臭氧层物质。', '本品不燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5035, 5143, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '咳嗽和气急。', NULL, '本品易燃，有毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5036, 5144, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '吸入、摄入或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。吸入可引起喉、支气管炎症、化学性肺炎、肺水肿。接触可引起头痛、头晕、恶心、呕吐、腹痛、腹泻等症状。长期或反复接触可能引起肝、肾损害。', '无资料', '本品不燃，有毒，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5037, 5145, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收\n吸入', '现剧烈腹痛、呕吐和虚脱。', '无资料', '本品可燃，具腐蚀性、刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5038, 5146, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收', NULL, '无资料', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5039, 5147, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', NULL, NULL, '本品可燃，有毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5040, 5148, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入 食入 经皮吸收\n毒性强。对眼睛、皮肤、粘膜有强烈刺激作用。吸入，可引起喉、支气管炎症、痉挛，\n化学性肺炎、肺水肿。接触后，可引起烧灼感、喉炎、气短、头痛、恶心和呕吐。反复', '接触可引起哮喘，过敏反应。', '无资料', '本品不燃、具有腐蚀性、强刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5041, 5149, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。吸入可引起喉、支气管痉挛、炎症、水肿，化学性肺炎或肺水肿。接触后可引起烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '对水生生物有毒性作用。', '本品助燃、具强刺激性。遇水或潮湿空气会分解产生氯气，遇热会分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5042, 5150, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入、食入、经皮吸收', '吸入引起中毒。摄入本品液体,引起口腔及消化道烧灼感,并出现恶心、头痛、眩晕等症状。对眼睛、皮肤、粘膜有刺激性。', '对环境有危害，对水体可造成污染。', '本品易燃、有毒、具有刺激性。遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5043, 5151, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, '通过打击、摩擦、火灾或其他着火源有极大爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5044, 5152, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, '通过打击、摩擦、火灾或其他着火源有极大爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5045, 5153, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, '通过打击、摩擦、火灾或其他着火源有极大爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5046, 5154, NULL, NULL, NULL, NULL, NULL, '第l类爆炸品', '吸入 食入 经皮吸收', '本品有毒，遇热分解出有毒的氮氧化物烟雾。', '无资料', '本品属爆炸品、易燃', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5047, 5155, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, '通过打击、摩擦、火灾或其他着火源有极大爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5048, 5156, NULL, NULL, NULL, NULL, NULL, '第1类 爆炸品', '吸入 食入 经皮吸收', NULL, '无资料', '本品属爆炸品，易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5049, 5157, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入、食入、皮肤接触、眼睛接触', '本品有腐蚀性，其蒸气对眼睛、皮肤和粘膜有极强的刺激性。遇水放出有毒的溴化氢。', '无资料', '本品不燃、具有强腐蚀性、强刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5050, 5158, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和呼吸道有强烈的刺激作用。吸入后可能由于喉、支气管的痉挛、水肿、炎症，化学性肺炎、肺水肿而致死。中毒表现有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '无资料', '本品不燃，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5051, 5159, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入、食入、经皮吸收', '对眼睛、粘膜、呼吸道和皮肤有强烈刺激作用。吸入可能由于喉、支气管的炎症、痉挛、水肿，化学性肺炎、肺水肿而致死。中毒表现有烧灼感、咳嗽、喘息、气短、喉炎、头痛、恶心和呕吐。', '无资料', '本品不燃，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5052, 5160, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和呼吸道有强烈的刺激作用。吸入后可能由于喉、支气管的痉挛、水肿、炎症，化学性肺炎、肺水肿而致死。中毒表现有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '无资料', '本品不燃，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5053, 5161, NULL, NULL, NULL, NULL, NULL, '第4.2类自燃物品', '吸入 食入', '遇热分解放出有毒的溴烟雾。', '无资料', '本品易燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5054, 5162, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '有毒。吸入、摄入或经皮肤吸收后会中毒。遇水分解会散发出腐蚀性和有毒的溴化氢气体。本品有致癌作用。', '无资料', '本品不燃、高毒。遇水或高热能放出大量有毒的气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5055, 5163, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、粘膜、呼吸道和皮肤有刺激作用。吸入可引起喉、支气管的炎症、痉挛、水肿，化学性肺炎、肺水肿而致死。中毒表现有烧灼感、咳嗽、喘息、气短、喉炎、头痛、恶心和呕吐。', '对环境有危害，对水体可造成污染。', '本品不燃，具腐蚀性、刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5056, 5164, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '对中枢神经系统有麻醉作用，对肝脏和肾脏有损害。重者可有恶心、呕吐、昏迷、抽搐等。可致死。', '对环境有危害，对水体可造成污染。', '本品不燃，有毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5057, 5165, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '有毒性和腐蚀性。受热分解释出有催泪性和腐蚀性气体。', '无资料', '本品可燃、有毒、具有腐蚀性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5058, 5166, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入', '二个月心肌、肝脏、呼吸系统发生改变。本品对皮肤有刺激作用。', '无资料', '本品可燃，有毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5059, 5167, NULL, NULL, NULL, NULL, NULL, '第8.2类 碱性腐蚀品', '吸入 食入 经皮吸收\n吸入', '者可致失明。皮肤接触可发生灼伤；对皮肤有强致敏作用；可经皮肤吸收引起中毒。口服液体\n灼伤消化道。慢性影响：本品有显著的致敏作用。', '无资料', '本品可燃，具强腐蚀性、刺激性，可致人体灼伤，具致敏性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5060, 5168, NULL, NULL, NULL, NULL, NULL, '第2.3类 有毒气体', '吸入、皮肤接触、眼睛接触', '氮氧化物主要损害呼吸道。吸入初期仅有轻微的眼及呼吸道刺激症状，如咽部不适、干咳等。常经数小时至十几小时或更长时间潜伏期后发生迟发性肺水肿、成人呼吸窘迫综合征，出现胸闷、呼吸窘迫、咳嗽、咯泡沫痰、紫绀等。可并发气胸及纵隔气肿。肺水肿消退后两周左右可出现迟发性阻塞性细气支气管炎。慢性影响：主要表现为神经衰弱综合征及慢性呼吸道炎症。个别病例出现肺纤维化。可引起牙齿酸蚀症。', '对环境有危害，对水体可造成污染。', '本品助燃，有毒。受热分解产生有毒的氮氧化物烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5061, 5169, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '钒化合物可引起呼吸道刺激、眼和皮肤刺激。吸入钒化合物粉尘可引起咳嗽、胸闷、气短、鼻衄等症状。长期接触可引起慢性支气管炎、肺气肿。对肾脏、肝脏有损害作用。', '对环境有危害，对水体可造成污染。', '本品不燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5062, 5170, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入 食入', '误服或吸入会中毒。对眼睛、皮肤、粘膜有强烈刺激性和腐蚀性。', '无资料', '本品不燃、有毒、具有腐蚀性、强刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5063, 5171, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触', '损害造血、神经、消化系统及肾脏。职业中毒主要为慢性。神经系统主要表现为神经衰弱综合症、周围神经病(以运动功能受累较明显)，重者出现铅中毒脑病。消化系统表现有齿龈铅线、腹痛、便秘、恶心、呕吐等。造血系统表现为贫血、血红蛋白尿等。肾脏损害表现为蛋白尿、管型尿等。', '对环境有危害，对水体可造成污染。', '受高热分解，放出有毒的蒸气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5064, 5172, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。主要影响神经系统和毛细血管通透性，对皮肤和粘膜有刺激作用。急性中毒：口服中毒出现恶心，呕吐，腹痛，\"米泔\"样大便，有时混有血液，四肢痛性痉挛，少尿，无尿，昏迷、抽搐，呼吸麻痹而死亡。可在急性中毒的１～３周内发生周围神经病。可发生中毒性心肌炎、肝炎。吸入中毒表现为咳嗽、喷嚏、胸痛、呼吸困难以及头痛、头晕、全身衰弱，甚至烦躁不安、痉挛和昏迷。可致死。慢性中毒：消化系统症状，肝肾损害，皮肤色素沉着、角化过度或疣状增生，以及多发性周围神经炎。可致肺癌、皮肤癌。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '三氧化二砷对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境有危害，对鱼类和哺乳动物应给予特别注意。在水生生物中可能发生生物蓄积。', '本品不燃，剧毒，为致癌物，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5065, 5173, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、经皮吸收', '急性中毒：吸入后可引起急性呼吸道刺激症状、鼻出血、声音嘶哑、鼻粘膜萎缩，有时出现哮喘和紫绀。重者可发生化学性肺炎。口服可刺激和腐蚀消化道，引起恶心、呕吐、腹痛、腹泻，重者可致消化道穿孔、腹膜炎、休克等。皮肤接触可引起皮炎、湿疹、铬溃疡。长期接触可引起铬中毒，表现为头痛、头晕、消瘦、食欲不振、胃肠道功能紊乱、肝大、贫血等。六价铬化合物有致癌性。', '对环境有危害，对水体可造成污染。', '本品助燃，高毒，为致癌物，具腐蚀性、刺激性，可致人体灼伤。遇明火、高热可燃。受热分解产生有毒的铬化合物烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5066, 5174, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入、食入', '其毒性表现与硫酸同。对皮肤、粘膜等组织有强烈的刺激和腐蚀作用。可引起结膜炎、水肿、角膜混浊，以致失明；引起呼吸道刺激症状，重者发生呼吸困难和肺水肿；高浓度引起喉痉挛或声门水肿而窒息死亡。口服后引起消化道烧伤以致溃疡形成；严重者可有胃穿孔、腹膜炎、喉痉挛和声门水肿、肾损害或休克等。', '对环境有危害，对水体可造成污染。', '本品有毒、腐蚀性、刺激性。与水能发生强烈反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5067, 5175, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、皮肤接触', '本品具有腐蚀性。对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用。', '对环境有危害，对水体可造成污染。', '受高热分解，放出有毒的蒸气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5068, 5176, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入经皮吸收\n对呼吸道有强烈的刺激性，吸入后可引起肺水肿甚至死亡。口服腐蚀口腔、食道及胃。眼', '及皮肤接触可引起化学性灼伤。', '无资料', '本品易燃，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5069, 5177, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入', '触中吸入中毒的可能性不大。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5070, 5178, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收', NULL, '无资料', '本品可燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5071, 5179, NULL, NULL, NULL, NULL, NULL, '第4.2类自燃物品', '吸入\n具有强烈刺激和腐蚀作用，主要损害呼吸道和眼结膜，高浓度吸入可引起肺水肿。吸入其', '烟雾可致烟雾热。皮肤接触可致灼伤，产生充血水肿和起水疱，疼痛剧烈。', '无资料', '本品极度易燃，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5072, 5180, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '本品为高毒类有机锡化合物。吸入、食入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。重者可出现昏迷、抽搐等。慢性影响可有神衰综合征。', '对水生生物有剧毒，对水生环境可能会引起长期有害作用。', '遇明火、高热可燃。燃烧分解时，放出有毒的刺激性氯化物烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5073, 5181, NULL, NULL, NULL, NULL, NULL, '第4.2类自燃物品', '吸入 食入', '本品蒸气刺激上呼吸道及眼。遇高温或水能分解，并释放出易燃气体，该气体有毒。', '无资料', '本品极度易燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5074, 5182, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '本品为高毒类砷化合物。吸入、食入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。重者可出现昏迷、抽搐等。慢性影响可有神衰综合征。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '遇明火、高热可燃。燃烧分解时，放出有毒的刺激性砷氧化物烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5075, 5183, NULL, NULL, NULL, NULL, NULL, '第4.2类自燃物品', '吸入食入', '本品有毒，具有腐蚀性。热解时能释放出有毒的锑烟雾。', '无资料', '本品极度易燃，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5076, 5184, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5077, 5185, NULL, NULL, NULL, NULL, NULL, '第8类腐蚀性物质', '吸入、食入、经皮吸收', '吸入蒸气对呼吸道有刺激性。对眼有强烈刺激性，能引起中度角膜损害。短时皮肤接触，可致皮肤刺激。反复或长期接触可能引起皮肤干燥、皲裂。', '对水生生物有害，可能对水体环境造成长期不利影响。', '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5078, 5186, NULL, NULL, NULL, NULL, NULL, '第4.2类自燃物品', '吸入', '肺水肿。吸入其烟雾可发生金属烟雾热。皮肤接触可致灼伤，产生充血、水肿和水疱，疼\n痛剧烈。', '无资料', '本品极度易燃，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5079, 5187, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '蒸气或雾对眼、粘膜和上呼吸道有刺激性。对皮肤有刺激性。吞咽会中毒，皮肤接触会中毒，吸入会中毒，可造成严重的皮肤灼伤和眼损伤。', '对环境有害。', '本品易燃，其蒸气与空气混合，能形成爆炸性混合物。具腐蚀性、刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5080, 5188, NULL, NULL, NULL, NULL, NULL, '第8.2类碱性腐蚀品', '吸入、食入、经皮吸收', '本品对粘膜、上呼吸道、眼和皮肤有强烈的刺激性。吸入后，可因喉及支气管的痉挛、炎症、水肿，化学性肺炎或肺水肿而致死。接触后出现烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。可致灼伤。', '对环境有危害，对水体可造成污染。', '本品易燃，其蒸气与空气混合，能形成爆炸性混合物。具腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5081, 5189, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '本品为有机磷杀虫剂，抑制胆碱酯酶活性。中毒症状有头痛、头晕、无力、失眠、多汗、四肢麻木、肌肉跳动等。严重中毒可出现肺水肿、脑水肿、昏迷、呼吸麻痹。少数重度中毒者在临床症状消失后数周出现神经病。接触有机磷农药工人可有头晕、头痛、无力、失眠、多汗、四肢麻木、肌肉跳动等。血胆碱酯酶活性降低。', '对环境有害。对水生生物有毒性，对水生环境可能会引起长期有害作用。对蜜蜂、家蚕有毒。', '遇明火、高热可燃。受热分解，放出氮、磷的氧化物等毒性气体。在火场中，容器内压增大有开裂或爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5082, 5190, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '本品为有机磷杀虫剂，抑制体内胆碱酯酶活性，造成神经生理功能紊乱。急性中毒表现有头痛、头昏、乏力、食欲不振、恶心、呕吐、腹痛、腹泻、流涎、瞳孔缩小、呼吸道分泌物增多、多汗、肌束震颤等。重度中毒者出现肺水肿、昏迷、呼吸麻痹、脑水肿。血胆碱酯酶活性降低。', '对环境有害。对水生生物有毒性，对水生环境可能会引起长期有害作用。对蜜蜂、家蚕有毒。在鱼类体内发生生物蓄积。', '可燃。含有机溶剂的液体制剂可能易燃。受热分解产生有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5083, 5191, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '元素砷不溶于水，无毒性。口服砷化合物引起急性胃肠炎、休克、周围神经病、中毒性心肌炎、肝炎以及抽搐、昏迷等，甚至死亡。大量吸入亦可引起急性中毒，但消化道症状较轻。慢性中毒表现为皮肤色素沉着、指甲出现白色横纹、掌跖部皮肤过度角化、周围神经炎、肝损害等。', '对环境有危害，对水体、土壤和大气可造成污染。', '本品可燃，有毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5084, 5192, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '高毒。砷化汞含有砷和汞两种有毒元素。急性中毒可引起恶心、呕吐、腹痛、腹泻、头痛、头晕、乏力等症状。砷中毒可引起溶血、肝肾功能损害。汞中毒可引起中枢神经系统损害、肾功能损害。慢性中毒可引起贫血、肝脾肿大、周围神经炎、记忆力减退等。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5085, 5193, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '砷化镓含有砷元素，具有砷的毒性特征。急性中毒可引起恶心、呕吐、腹痛、腹泻、头痛、头晕、乏力等症状。砷中毒可引起溶血、肝肾功能损害。慢性中毒可引起贫血、肝脾肿大、周围神经炎、记忆力减退等。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5086, 5194, NULL, NULL, NULL, NULL, NULL, '第2.3类有毒气体', '吸入', '属高毒类。吸入后主要引起溶血和高铁血红蛋白血症。急性中毒表现为头痛、头晕、乏力、恶心、呕吐、腹痛、腹泻、腰痛、酱油色尿、黄疸、肝脾肿大、肾功能损害等。严重者可出现昏迷、抽搐、休克、急性肾功能衰竭。慢性中毒主要表现为贫血、肝脾肿大、周围神经炎等。', '对环境有危害，对水体可造成污染。', '本品易燃，高毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5087, 5195, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '高毒。砷化锌含有砷元素，具有砷的毒性特征。急性中毒可引起恶心、呕吐、腹痛、腹泻、头痛、头晕、乏力等症状。砷中毒可引起溶血、肝肾功能损害。慢性中毒可引起贫血、肝脾肿大、周围神经炎、记忆力减退等。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5088, 5196, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '砷及其化合物对体内酶蛋白巯基有特殊亲和力。大量吸入砷化合物可致咳嗽、胸痛、呼吸困难、头痛、眩晕、全身衰弱、烦躁、痉挛和昏迷；可有消化道症状；重者可致死。口服致急性胃肠炎，严重者可因休克、呼吸循环衰竭而死亡。慢性中毒表现为皮肤色素沉着、指甲出现白色横纹、掌跖部皮肤过度角化、周围神经炎、肝损害等。', '对环境有危害，对水体可造成污染。', '本品不燃，高毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5089, 5197, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '砷酸铵含有砷元素，具有砷的毒性特征。急毒性-口服，类别3；急毒性-吸入，类别3；致癌性，类别1A。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期接触可引起慢性砷中毒，表现为皮肤色素沉着、掌跖角化、周围神经病变、肝肾功能损害等。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '受热分解产生有毒的砷氧化物和氨气。受热或接触火焰可能会产生膨胀或爆炸性分解。本品不燃，高毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5090, 5198, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '砷酸钡含有砷和钡两种有毒元素，具有砷和钡的毒性特征。急性中毒可引起恶心、呕吐、腹痛、腹泻、头痛、头晕、乏力等症状。砷中毒可引起溶血、肝肾功能损害。钡中毒可引起肌肉麻痹、心律失常。慢性中毒可引起贫血、肝脾肿大、周围神经炎、记忆力减退等。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '受热分解产生有毒的砷氧化物烟雾。遇明火、高热可燃。与还原剂、金属粉末等可发生反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5091, 5199, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '砷酸二氢钾含有砷元素，具有砷的毒性特征。急性中毒可引起恶心、呕吐、腹痛、腹泻、头痛、头晕、乏力等症状。砷中毒可引起溶血、肝肾功能损害。慢性中毒可引起贫血、肝脾肿大、周围神经炎、记忆力减退等。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '受热分解产生有毒的砷氧化物烟雾。遇明火、高热可燃。与还原剂、金属粉末等可发生反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5092, 5200, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '砷酸二氢钠含有砷元素，具有砷的毒性特征。急性中毒可引起恶心、呕吐、腹痛、腹泻、头痛、头晕、乏力等症状。砷中毒可引起溶血、肝肾功能损害。慢性中毒可引起贫血、肝脾肿大、周围神经炎、记忆力减退等。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '受热分解产生有毒的砷氧化物烟雾。遇明火、高热可燃。与还原剂、金属粉末等可发生反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5093, 5201, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '砷酸钙含有砷元素，具有砷的毒性特征。急性中毒可引起恶心、呕吐、腹痛、腹泻、头痛、头晕、乏力等症状。砷中毒可引起溶血、肝肾功能损害。慢性中毒可引起贫血、肝脾肿大、周围神经炎、记忆力减退等。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '受热分解产生有毒的砷氧化物烟雾。遇明火、高热可燃。与还原剂、金属粉末等可发生反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5094, 5202, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '砷酸汞含有砷和汞两种有毒元素，具有砷和汞的毒性特征。急性中毒可引起恶心、呕吐、腹痛、腹泻、头痛、头晕、乏力等症状。砷中毒可引起溶血、肝肾功能损害。汞中毒可引起神经系统损害、肾功能损害。慢性中毒可引起贫血、肝脾肿大、周围神经炎、记忆力减退等。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '受热分解产生有毒的砷氧化物和汞烟雾。遇明火、高热可燃。与还原剂、金属粉末等可发生反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5095, 5203, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '砷酸镁含有砷和镁两种元素，具有砷的毒性特征。高毒。吸入、摄入会中毒，引起吞咽困难、腹痛、突发性呕吐、休克、麻痹等症状。砷化合物属致癌物。受热分解释出有毒的砷烟雾。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '受热分解产生有毒的砷氧化物和氧化镁烟雾。本品不燃，高毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5096, 5204, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '砷酸钠含有砷元素，具有砷的毒性特征。急性中毒可引起恶心、呕吐、腹痛、腹泻、头痛、头晕、乏力等症状。砷中毒可引起溶血、肝肾功能损害。慢性中毒可引起贫血、肝脾肿大、周围神经炎、记忆力减退等。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。可能有损伤胎儿或胚胎的危险。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '受热分解产生有毒的砷氧化物烟雾。遇明火、高热可燃。与还原剂、金属粉末等可发生反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5097, 5205, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '砷酸铅含有铅和砷两种有毒元素，具有铅和砷的毒性特征。急性中毒表现有恶心、呕吐、腹痛、腹泻、肌肉痉挛、兴奋、定向力障碍等。皮肤接触引起接触性皮炎。慢性影响：厌食、体重减轻、贫血、肝脾肿大、周围神经炎、记忆力减退等。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。该物质对环境有危害，对鱼类、鸟类及植物应给予特别注意。', '受热分解产生有毒的砷氧化物和铅氧化物烟雾。本品不燃，高毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5098, 5206, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '砷酸氢二铵含有砷元素，具有砷的毒性特征。急性中毒可引起恶心、呕吐、腹痛、腹泻、头痛、头晕、乏力等症状。砷中毒可引起溶血、肝肾功能损害。慢性中毒可引起贫血、肝脾肿大、周围神经炎、记忆力减退等。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '受热分解产生有毒的砷氧化物、氮氧化物和氨烟雾。遇明火、高热可燃。与还原剂、金属粉末等可发生反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5099, 5207, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '砷酸氢二钠含有砷元素，具有砷的毒性特征。急性中毒可引起恶心、呕吐、腹痛、腹泻、头痛、头晕、乏力等症状。砷中毒可引起溶血、肝肾功能损害。慢性中毒可引起贫血、肝脾肿大、周围神经炎、记忆力减退等。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '受热分解产生有毒的砷氧化物烟雾。遇明火、高热可燃。与还原剂、金属粉末等可发生反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5100, 5208, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '砷酸锑含有砷和锑两种元素，具有砷和锑的毒性特征。吞食后有毒。吸入有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。砷化合物属致癌物。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '受热分解产生有毒的砷氧化物和锑氧化物烟雾。本品不燃，高毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5101, 5209, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '砷酸铁含有砷元素，具有砷的毒性特征。高毒。误服或吸入粉尘会中毒，引起吞咽困难、腹痛、突发性呕吐、休克、麻痹等症状。砷化合物属致癌物。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '受热分解产生有毒的砷氧化物烟雾。本品不燃、高毒、为致癌物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5102, 5210, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '砷酸铜含有砷和铜两种有毒元素，具有砷和铜的毒性特征。吞食后有毒。对眼睛有严重刺激性。吸入有毒。可能有损伤胎儿或胚胎的危险。短期暴露可能导致严重的健康影响。对皮肤、粘膜和上呼吸道有刺激作用。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '受热分解产生有毒的砷氧化物和铜氧化物烟雾。本品不燃，高毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5103, 5211, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '砷酸锌含有砷和锌两种元素，具有砷的毒性特征。高毒。吸入、摄入会中毒，引起吞咽困难、腹痛、突发性呕吐、休克、麻痹等症状。砷化合物属致癌物。受热分解释出有毒的砷和氧化锌烟雾。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '受热分解产生有毒的砷氧化物和氧化锌烟雾。本品不燃，高毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5104, 5212, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '砷酸亚铁含有砷元素，具有砷的毒性特征。急性中毒可引起恶心、呕吐、腹痛、腹泻、头痛、头晕、乏力等症状。砷中毒可引起溶血、肝肾功能损害。慢性中毒可引起贫血、肝脾肿大、周围神经炎、记忆力减退等。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '受热分解产生有毒的砷氧化物烟雾。遇明火、高热可燃。与还原剂、金属粉末等可发生反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5105, 5213, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '砷酸银含有砷和银两种元素，具有砷的毒性特征。吞食后有毒。吸入有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。砷化合物属致癌物。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '受热分解产生有毒的砷氧化物烟雾。本品不燃，高毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5106, 5214, NULL, NULL, NULL, NULL, NULL, '二级易燃固体', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤有刺激性。长期接触可能引起皮肤过敏反应。', '对环境有危害，对水体可造成污染。', '二级易燃固体，遇火种、高温、氧化剂有引起燃烧危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5107, 5215, NULL, NULL, NULL, NULL, NULL, '第3类易燃液体', '吸入、食入、皮肤接触、眼睛接触', '对眼和皮肤有刺激性。吸入、摄入或经皮肤吸收对身体有害。', '对水生生物有害。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5108, 5216, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。吸入可引起化学性肺炎和肺水肿等。遇水或水蒸气能生成有毒的腐蚀性烟雾，遇热可释出有毒的氯烟雾。', '对水生生物有害。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5109, 5217, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收', '水肿，化学性肺炎或肺水肿而致死。接触后出现烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶\n心和呕吐。', '无资料', '本品腐蚀性、刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5110, 5218, NULL, NULL, NULL, NULL, NULL, '第3类易燃液体', '吸入、食入、皮肤接触、眼睛接触', '吸入、摄入或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生生物有害。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5111, 5219, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '本品基本无毒。其浓溶液对皮肤有一定刺激作用。目前，未见职业中毒报道。', '对水生生物有毒性。', '遇明火、高热可燃。受高热分解放出有毒的气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5112, 5220, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。可引起哮喘。长期反复接触可致皮炎。高浓度接触可引起神志丧失。', '对环境有危害，对水体可造成污染。', '本品易燃，有毒，具刺激性。遇明火、高热有燃烧爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5113, 5221, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收', '对粘膜和上呼吸道有刺激作用，对眼和皮肤有刺激作用。可引起呼吸系统过敏性反应。误服可引起恶心、呕吐、腹痛、腹泻等消化道症状。', '对水生生物有毒，对水生环境可能会引起长期有害作用。', '遇明火、高热可燃。受高热分解放出有毒的气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5114, 5222, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入 食入 经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。引起头痛、恶心、呕吐、咳嗽、喉炎及气短等。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用和腐蚀作用。', '对水生生物有毒，对水生环境可能会引起长期有害作用。', '本品可燃、有毒、具有腐蚀性、强刺激性、可致人体灼伤。受高热分解产生有毒的腐蚀性烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5115, 5223, NULL, NULL, NULL, NULL, NULL, '第8类腐蚀性物质', '吸入、食入、皮肤接触、眼睛接触', '吸入有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生生物有害。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5116, 5224, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入 食入 经皮吸收', '盐酸烟雾。', '无资料', '本品可燃、有毒，具有腐蚀性、强刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5117, 5225, NULL, NULL, NULL, NULL, NULL, '第8类腐蚀品', '吸入、食入、皮肤接触、眼睛接触', '对皮肤有刺激性。跟皮肤接触可能会引起敏化作用。对眼睛、粘膜和上呼吸道有刺激作用。吸入可引起呼吸道刺激。', '对水生生物有毒性。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5118, 5226, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入经皮吸收', '高浓度蒸气对眼有刺激性。慢性影响：长期接触可引起周围神经病。对胃肠道有影响。皮\n肤接触可引起小水疱、湿疹、皮肤脱脂。对肾脏可能有影响。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5119, 5227, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收', '炎症，化学性肺炎、肺水肿等。接触后可有烧灼感、咳嗽、气短、头痛、恶心和呕吐。', '无资料', '本品可燃、有毒、具有腐蚀性、强刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5120, 5228, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '皮肤吸收、吸入、食入', '对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期接触可影响神经系统、肝脏和甲状腺功能。动物实验显示具有生殖毒性和内分泌干扰作用。', '对水生生物有剧毒。该物质在环境中持久存在，不易降解，具有生物富集性。已被《斯德哥尔摩公约》列为持久性有机污染物。', '遇明火、高热可燃。受热分解产生有毒的溴化氢气体和含溴有机物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5121, 5229, NULL, NULL, NULL, NULL, NULL, '第4.1类易燃固体', '吸入、食入、皮肤接触、眼睛接触', '低毒。石蜡中含有一定量的杂环化合物，主要是吡啶、吡咯、噻吩等，有的有致癌作用。吸入高浓度蒸气，引起头痛、眩晕、咳嗽、食欲减退、呕吐腹泻，长期接触导致皮肤损害。有报道：石蜡工人发生皮肤癌的情况，在石蜡净化车间工作10年以上的工人，患阴囊癌者高于工龄少的工人及当地居民。', '对环境有危害，对水体可造成污染。', '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5122, 5230, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入', '长期接触石棉者可引起石棉肺，病人有咳嗽、胸痛、呼吸困难等，重者发生呼吸和循环衰竭。国际癌症研究中心(IARC)已确认为致癌物。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生生物有剧毒。对环境可能有危害，对水体应给予特别注意。', '本品有毒、为致癌物。不燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5123, 5231, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '吸入、口服或经皮肤吸收对身体有害。蒸气或雾对眼睛、粘膜和上呼吸道有刺激性。高浓度吸入可引起头痛、头晕、恶心、呼吸困难、紫绀等缺氧症状。长期接触可引起神经系统损害。', '对环境有危害，对水体、土壤和大气可造成污染。', '本品易燃，具刺激性。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。与氧化剂接触猛烈反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5124, 5232, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '其蒸气或雾对眼睛、粘膜和呼吸道有刺激性。中毒表现可有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。本品可引起周围神经炎。对皮肤有强烈刺激性。', '对水生生物有剧毒。对环境可能有危害，对水体应给予特别注意。', '本品极度易燃，具强刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂能发生强烈反应。高速冲击、流动、激荡后可因产生静电火花放电引起燃烧爆炸。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5125, 5233, NULL, NULL, NULL, NULL, NULL, '第2.1类易燃气体', '吸入、皮肤接触、眼睛接触', '对眼睛、皮肤、粘膜和上呼吸道有刺激作用。高浓度时有麻醉作用。如果吸入含有丁烷5%-6%的空气达30分钟，即稍现意志消沉、抑郁。', '对水生生物有剧毒。对环境可能有危害，对水体应给予特别注意。', '本品易燃、具有麻醉性。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5126, 5234, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤、粘膜和上呼吸道有刺激作用。吸入蒸气可引起头痛、头晕、恶心、呕吐、意识模糊等症状。长期接触可引起皮肤干燥、脱脂、皮炎。高浓度蒸气可引起麻醉作用。', '对水生生物有剧毒。对环境可能有危害，对水体应给予特别注意。', '本品易燃。遇高热、明火有燃烧危险。能与氧化剂反应。遇热分解释出有毒的烟雾。吸入大量蒸气能引起神经症状。其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5127, 5235, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收可能致死。对眼睛、皮肤、粘膜和呼吸道有强烈刺激作用。吸入后可引起喉、支气管的痉挛、水肿，化学性肺炎、肺水肿而致死。中毒表现有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '无资料', '本品易燃，高毒，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5128, 5236, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入 食入 经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激性。高浓度接触可引起头晕、头痛、恶心、呕吐、乏力、嗜睡等症状。长期或反复接触可能对中枢神经系统、肝脏、肾脏造成损害。可引起皮肤干燥、脱脂、皲裂。可引起眼睛刺激、红肿、流泪。可引起呼吸道刺激、咳嗽、胸闷、呼吸困难。', '对水生生物可能具有毒性。对环境可能造成危害。', '本品易燃、具有刺激性。遇明火、高热极易燃烧爆炸。与氧化剂能发生强烈反应。蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5129, 5237, NULL, NULL, NULL, NULL, NULL, '有机过氧化物，C型。', '吸入、食入、皮肤接触、眼睛接触', '吸入该物质可能会引起对健康有害的影响或呼吸道不适。对眼睛、皮肤和呼吸道有刺激作用。意外食入可能引起胃肠道刺激。', '对水生生物有害。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5130, 5238, NULL, NULL, NULL, NULL, NULL, '有机过氧化物，E型。', '吸入、食入、皮肤接触、眼睛接触', '吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入该物质可能会引起对健康有害的影响。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。接触可引起眼睛灼伤。长期或反复接触可能引起皮肤过敏。', '无资料', '易燃易爆。对热、震动、摩擦和冲击极为敏感。受热分解可能产生爆炸。遇火源、热源或火花可能发生燃烧或爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5131, 5239, NULL, NULL, NULL, NULL, NULL, 'GHS危险性类别：易燃液体类别3，皮肤腐蚀/刺激性类别2，特异性靶器官毒性-反复接触类别3', '侵入途径：吸入、食入、经皮吸收', '健康危害：本品对眼睛、皮肤和呼吸道有刺激性。高浓度接触可引起头痛、头晕、恶心、呕吐等症状。长期或反复接触可能对肝脏、肾脏和神经系统造成损害。本品属于有机过氧化物，具有氧化性和易燃性，遇热、摩擦、撞击或接触某些物质可能发生爆炸或剧烈反应。', '环境危害：对水生生物有毒。可能对水体环境产生长期不良影响。', '燃爆危险：易燃，遇热、明火、氧化剂有燃烧爆炸的危险。受热或接触火焰可能会产生膨胀或爆炸性分解。加热时，容器可能爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5132, 5240, NULL, NULL, NULL, NULL, NULL, '第5.2类有机过氧化物，D型。', '吸入、食入、皮肤接触、眼睛接触。吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入该物质可能会造成对健康有害的影响。皮肤接触该物质可能会造成对健康有害的影响。眼睛接触该物质可能会造成对健康有害的影响。', '对眼睛、皮肤、粘膜和上呼吸道有刺激作用。接触可能引起皮肤刺激、眼睛刺激、呼吸道刺激。长期或反复接触可能引起皮肤过敏。高浓度接触可能对中枢神经系统产生影响。有机过氧化物具有强氧化性，可引起燃烧或爆炸。', '对水生生物有害。避免释放到环境中。', '遇明火、高热可燃。受热分解产生有毒气体。与还原剂、酸类、碱类、易燃物、有机物等发生剧烈反应，有燃烧爆炸危险。摩擦、撞击或震动有爆炸危险。有机过氧化物本身不稳定，容易发生自加速分解，导致火灾或爆炸。在包装件中可发生热爆炸。接触火焰可能会产生膨胀或爆炸性分解。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5133, 5241, NULL, NULL, NULL, NULL, NULL, '第5.2类有机过氧化物，B型。', '吸入、食入、皮肤接触、眼睛接触。吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入该物质可能会造成对健康有害的影响。皮肤接触该物质可能会造成对健康有害的影响。眼睛接触该物质可能会造成对健康有害的影响。', '对眼睛、皮肤、粘膜和上呼吸道有刺激作用。接触可能引起皮肤刺激、眼睛刺激、呼吸道刺激。长期或反复接触可能引起皮肤过敏。高浓度接触可能对中枢神经系统产生影响。有机过氧化物具有强氧化性，可引起燃烧或爆炸。', '对水生生物有害。避免释放到环境中。', '遇明火、高热可燃。受热分解产生有毒气体。与还原剂、酸类、碱类、易燃物、有机物等发生剧烈反应，有燃烧爆炸危险。摩擦、撞击或震动有爆炸危险。有机过氧化物本身不稳定，容易发生自加速分解，导致火灾或爆炸。在包装件中可发生热爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5134, 5242, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入 食入 经皮吸收', '具刺激作用，误服会中毒。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5135, 5243, NULL, NULL, NULL, NULL, NULL, '第3.1类低闪点易燃液体', '吸入、食入、皮肤接触、眼接触', '叔丁基硫醇具有强烈的刺激性气味，吸入高浓度蒸气可引起呼吸道刺激、头痛、头晕、恶心、呕吐等症状。严重时可导致意识丧失。液体接触皮肤可引起刺激和灼伤。溅入眼睛可引起严重眼刺激，甚至造成角膜损伤。口服可引起消化道刺激、恶心、呕吐、腹痛等症状。长期或反复接触可能对中枢神经系统、肝脏和肾脏造成损害。', '该物质对水生生物有毒，可能对水生环境造成长期不利影响。泄漏到土壤或水体中会造成环境污染。蒸气可在大气中扩散，对空气质量造成影响。', '叔丁基硫醇极度易燃，闪点-24℃，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。燃烧时产生一氧化碳、二氧化碳、硫化氢、氧化硫等有毒有害气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5136, 5244, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、经皮吸收', '该物质对粘膜、上呼吸道、眼、皮肤等组织有极强的破坏作用。吸入后可能因喉、支气管的炎症、水肿、痉挛，化学性肺炎、肺水肿而致死。中毒表现有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心、呕吐。', '该物质对环境可能有危害，对水体应给予特别注意。', '遇高热、明火或与氧化剂接触，有引起燃烧的危险。遇水反应发热放出有毒的腐蚀性气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5137, 5245, NULL, NULL, NULL, NULL, NULL, '第5.2类有机过氧化物', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收后对身体有害。对眼睛、皮肤和粘膜有刺激作用。', NULL, '遇热有火灾危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5138, 5246, NULL, NULL, NULL, NULL, NULL, '有机过氧化物，E型；危害水生环境-急性毒性，类别2；危害水生环境-慢性毒性，类别2。', '吸入、食入、皮肤接触、眼睛接触', '吸入该物质可能会引起对健康有害的影响或呼吸道不适。皮肤接触可能有害，可能引起皮肤刺激。眼睛接触可能引起眼睛刺激。食入可能有害。', '对水生生物有毒并具有长期持续影响。', '加热可能起火或爆炸。与可燃物混合可能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5139, 5247, NULL, NULL, NULL, NULL, NULL, '有机过氧化物，C型。', '吸入、食入、皮肤接触、眼睛接触\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '有爆炸性，遇热有火灾危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5140, 5248, NULL, NULL, NULL, NULL, NULL, '有机过氧化物，D型。', '吸入、食入、皮肤接触、眼睛接触\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5141, 5249, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入、食入、经皮吸收', '接触皮肤、眼睛有刺激作用；吸入引起面部潮红，恶心、眩晕、头痛、支气管炎，亦可出现呼吸困难、肺水肿等。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5142, 5250, NULL, NULL, NULL, NULL, NULL, '第4.1类易燃固体', '吸入、食入、皮肤接触、眼睛接触', '粉尘对眼睛、皮肤和呼吸道有刺激性。长期接触可能对呼吸系统造成损害。误食可能对胃肠道造成刺激。', '该物质对环境可能有危害，应特别注意对水体的污染。对水生环境可能会引起长期有害作用。', '易燃，其粉体与空气混合，能形成爆炸性混合物。遇明火、高热有引起燃烧爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5143, 5251, NULL, NULL, NULL, NULL, NULL, '第4.1类 易燃固体', '吸入、食入', '对眼睛和粘膜有刺激作用。可引起咽炎、呼吸道刺激和胃肠道刺激症状。钴化合物对中枢神经系统有毒性，可引起钴中毒。', '对环境有害。对水生环境可能会引起长期有害作用。', '易燃，具有刺激性。遇高热、明火或氧化剂，有引起燃烧的危险。暴露在空气中能自燃。沾染植物纤维（如棉花）会自燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5144, 5252, NULL, NULL, NULL, NULL, NULL, '第4.1类易燃固体', '吸入、食入、皮肤接触、眼睛接触', '粉尘对眼睛、皮肤和呼吸道有刺激性。长期接触可能对呼吸系统造成损害。误食可能对胃肠道造成刺激。', '该物质对环境可能有危害，应特别注意对水体的污染。对水生环境可能会引起长期有害作用。', '易燃，其粉体与空气混合，能形成爆炸性混合物。遇明火、高热有引起燃烧爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5145, 5253, NULL, NULL, NULL, NULL, NULL, '第4.1类易燃固体', '吸入、食入、皮肤接触、眼睛接触', '粉尘对眼睛、皮肤和呼吸道有刺激性。长期接触可能对呼吸系统造成损害。锰化合物对中枢神经系统有毒性，可引起锰中毒。', '该物质对环境可能有危害，应特别注意对水体的污染。', '易燃，其粉体与空气混合，能形成爆炸性混合物。遇明火、高热有引起燃烧爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5146, 5254, NULL, NULL, NULL, NULL, NULL, '第4.1类易燃固体', '吸入、食入、皮肤接触、眼睛接触', '粉尘对眼睛、皮肤和呼吸道有刺激性。长期接触可能对呼吸系统造成损害。误食可能对胃肠道造成刺激。', '该物质对环境可能有危害，应特别注意对水体的污染。', '易燃，其粉体与空气混合，能形成爆炸性混合物。遇明火、高热有引起燃烧爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5147, 5255, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '胆碱酯酶抑制剂。吸入、摄入或经皮肤吸收后可能致死。中毒表现有咳嗽、胸痛、呼吸困难、头痛、恶心、呕吐、眩晕、腹泻、胃痛、惊厥。', '对水生生物有害。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5148, 5256, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。可引起呼吸道炎症、肺水肿。长期接触可引起造血系统损害。', '对水生生物有极高毒性。对环境有危害，对水体可造成污染。', '遇明火、高热可燃。受高热分解，放出有毒的烟气。与氧化剂可发生反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5149, 5257, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '对呼吸道、皮肤、胃肠道有明显刺激作用，可抑制白细胞生成，大剂量误服可损害中枢神经系统，心脏、肝脏和内分泌腺，吸入后可产生过敏性。急性中毒少见，中毒后可有头痛、多汗，心动过速，心律不齐，呕吐、呼吸困难、支气管炎，荨麻疹等。口服大剂量后有恶心、呕吐、腹痛、腹泻等症状。可引起皮肤过敏反应。', '对水生生物有毒性，可能对水体环境造成长期不良影响。', '遇明火、高热可燃。受热分解产生有毒的硫化物和氮氧化物烟气。具有刺激性、致敏性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5150, 5258, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '本品为高毒有机磷杀虫剂。抑制胆碱酯酶活性，造成神经生理功能紊乱。急性中毒表现有头痛、头晕、乏力、恶心、呕吐、腹痛、腹泻、流涎、多汗、视力模糊、瞳孔缩小、呼吸困难、支气管痉挛、肺水肿、昏迷等。可因呼吸衰竭和肺水肿而死亡。对眼睛、皮肤、粘膜有刺激作用。', '对水生生物有极高毒性，可能对水体环境产生长期不良影响。', '遇明火、高热可燃。受高热分解，放出有毒的氮、磷氧化物和氟化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5151, 5259, NULL, NULL, NULL, NULL, NULL, '第5.2类有机过氧化物，D型', '吸入、食入、皮肤接触、眼睛接触', '吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入可能引起恶心、呕吐、腹痛。对眼睛、皮肤和粘膜有刺激作用。长期或反复接触可能导致皮肤过敏或化学灼伤。', '该物质对水生生物可能有害。避免排放到环境中。', '遇明火、高热可燃。受热分解产生有毒气体。强氧化剂，与还原剂、金属粉末、酸类、碱类等物质接触有燃烧爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5152, 5260, NULL, NULL, NULL, NULL, NULL, '第5.2类有机过氧化物，D型', '吸入、食入、皮肤接触、眼睛接触', '吸入该物质可能会引起对健康有害的影响或呼吸道不适。对眼睛、皮肤、粘膜有强烈刺激作用。意外食入可能引起胃肠道刺激、恶心、呕吐、腹痛。长期或反复接触可能引起皮肤过敏或化学灼伤。有机过氧化物具有氧化性，可引起组织损伤。', '对水生生物可能有毒性。该物质对环境有危害，应特别注意对水体的污染。', '遇明火、高热有燃烧爆炸危险。受热或接触还原剂、有机物、金属粉末等可能发生爆炸性分解。强氧化剂，与可燃物、还原剂、有机物等接触有燃烧爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5153, 5261, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入', NULL, '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5154, 5262, NULL, NULL, NULL, NULL, NULL, '第8.2类碱性腐蚀品', '吸入、食入、经皮吸收', '皮肤吸收引起中毒。可致皮炎。口服引起头晕、恶心，以后出现暂时性中枢性呼吸抑制、心律紊乱，以及中枢神经系统症状，如嗜睡、运动障碍、共济失调、麻木等。肝功能可出现异常。慢性影响：长期接触可出现神经衰弱综合征，肝大及肝功能异常。', '对环境有危害，对水体和土壤可造成污染。对水生生物有极高毒性。', '本品可燃，高毒，具强腐蚀性、刺激性，可致人体灼伤。遇明火、高热可燃。具有强还原性。与氧化剂能发生强烈反应，引起燃烧或爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5155, 5263, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '本品对呼吸道有刺激性，吸入后引起咳嗽、胸痛。对眼和皮肤有刺激性。皮肤接触会中毒。吞咽有害。造成严重眼刺激。怀疑对生育能力或胎儿造成伤害。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品可燃，有毒，具刺激性。遇高热、明火及强氧化剂易引起燃烧并放出有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5156, 5264, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入、食入', '对眼睛、皮肤、粘膜有刺激性。大量服用能引起呕吐、腹泻、腹痛、呼吸困难、酸中毒症和兴奋。还可引起耳鸣、尿中含蛋白的多尿症。长期接触可引起慢性中毒。', '对环境有危害，对水体和土壤可造成污染。', '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5157, 5265, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '固体吞食后有剧毒。跟皮肤接触有剧毒。吸入有剧毒。汞化合物具有蓄积性，长期接触可引起慢性中毒，主要损害神经系统、肾脏和肝脏。急性中毒表现为头痛、头晕、乏力、恶心、呕吐、腹痛、口腔炎、牙龈炎、震颤等。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。对环境有严重危害，特别是对水体。', '遇高热、明火或与氧化剂接触，有引起燃烧的危险。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5158, 5266, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吞食后有剧毒。跟皮肤接触有剧毒。吸入有剧毒。本品属神经毒，作用于植物神经、中枢神经及运动神经末梢，先兴奋，后抑制。能经消化道、呼吸道和皮肤很快吸收，引起中毒。急性中毒表现有头痛、头晕、无力、恶心、呕吐、腹痛、呼吸困难、流涎、出汗、肌肉震颤、抽搐等。严重时可出现昏迷、呼吸麻痹而死亡。', '对水生物有毒，对水生环境可能会引起长期有害作用。', '遇高热、明火或与氧化剂接触，有引起燃烧的危险。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5159, 5267, NULL, NULL, NULL, NULL, NULL, '第9类杂项危险物质', '吸入、食入', '静脉给药具有中等毒性。目前，未见工业应用的中毒报道。对眼睛、皮肤、粘膜有刺激性。', '对水生生物有毒并具有长期持续影响。对水生环境可能会引起长期有害作用。', '遇高热，明火或与氧化剂接触，有引起燃烧的危险。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5160, 5268, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜有刺激性。口服可引起头晕、恶心、呕吐、腹痛、过敏反应等症状。长期接触可能对肝脏和肾脏造成损害。', '对环境有危害，对水体和土壤可造成污染。', '遇高热、明火或与氧化剂接触，有引起燃烧的危险，燃烧分解时，放出有毒的氮氧化物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5161, 5269, NULL, NULL, NULL, NULL, NULL, '侵入途径： 眼睛及皮肤接触，吸入', '眼睛及皮肤接触，吸入', '痛、发烧、厌食，有些患者还会产生脱发、皮肤腐烂生痂、感觉迟钝、呼吸困难、咳嗽和\n肺炎', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5162, 5270, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '对粘膜有刺激作用，可产生皮肤过敏反应。中毒症状有：头痛、头晕、失眠、乏力、多汗等神经衰弱综合征；重症患者，可出现中毒性脑病。', '对水生生物有极高毒性，可能对水体环境产生长期不良影响。', '本品可燃，具有刺激性、致敏性。受热分解产生有毒的烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5163, 5271, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入', '本品有腐蚀性。遇高热能产生有毒烟气。', '对水生生物有毒性。可能对水环境造成长期不良影响。', '本品不燃，具腐蚀性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5164, 5272, NULL, NULL, NULL, NULL, NULL, '第8.2类碱性腐蚀品', '吸入 食入 经皮吸收', '支气管炎症、痉挛，化学性肺炎及肺水肿等。', '无资料', '本品不燃，具有强腐蚀性、强刺激性，可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5165, 5273, NULL, NULL, NULL, NULL, NULL, '第8类腐蚀性物质', '吸入、食入、皮肤接触、眼睛接触', '具有强腐蚀性和强碱性。对皮肤、眼睛、粘膜和上呼吸道有严重刺激作用。皮肤接触可引起严重化学灼伤。眼睛接触可导致永久性损伤甚至失明。吸入可引起呼吸道刺激、肺水肿。食入可引起消化道灼伤。', '对水生生物有害。', '遇酸反应产生热和烟雾。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5166, 5274, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '有毒。吸入、摄入或经皮肤吸收会中毒。对粘膜有刺激作用，可产生皮肤过敏反应。中毒症状有：剧烈头痛、头晕、失眠、乏力、多汗等神经衰弱综合征；重症患者，可出现中毒性脑病。', '无资料', '本品可燃、有毒、具有刺激性、致敏性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5167, 5275, NULL, NULL, NULL, NULL, NULL, '第2.3类 有毒气体', '吸入', '本品剧毒。热解放出高毒的F-和Nox烟雾。', '无资料', '本品不燃、剧毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5168, 5276, NULL, NULL, NULL, NULL, NULL, '第2.3类 有毒气体', '吸入', '本品有毒。在潮湿空气中产生氟化氢烟雾，对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。吸入可引起喉头水肿、支气管痉挛、化学性肺炎、肺水肿。高浓度接触可引起窒息甚至死亡。', '对水生生物有极高毒性。在潮湿空气中水解产生氟化氢，可污染水体和土壤，对环境造成危害。氟化物可导致水体酸化，影响水生生态系统。', '本品不燃，有毒，具腐蚀性、刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5169, 5277, NULL, NULL, NULL, NULL, NULL, '第2.3类 有毒气体', '吸入 食入', '具有强烈毒性的刺激性气体，可引起类似光气的呼吸道损害。实验动物有明显的肺水肿改变。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。', '无资料', '本品不燃、剧毒、具有强腐蚀性、强刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5170, 5278, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '铅化合物对神经系统有毒。吸入、经口和经皮肤吸收均可引起中毒。长期或反复接触会对器官造成伤害。可能对生育能力或胎儿造成伤害。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。使用适当的容器，以预防污染环境。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5171, 5279, NULL, NULL, NULL, NULL, NULL, '第7类 放射性物品', '吸入 食入', '具有放射性和化学毒性。吸入可导致肺部损伤和肾脏损害。长期接触可引起慢性铀中毒，表现为肾功能损害、肝脏损害和造血系统损害。对眼睛、皮肤、粘膜有刺激作用。摄入可引起胃肠道刺激和肾脏损伤。', '无资料', '受高热、明火会产生剧毒的蒸气。具有强腐蚀性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5172, 5280, NULL, NULL, NULL, NULL, NULL, '第2.2类 不燃气体', '吸入', '能引起快速窒息。接触后可引起头痛、恶心和呕吐。', '无资料', '本品不燃，具窒息性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5173, 5281, NULL, NULL, NULL, NULL, NULL, '第1类爆炸品', '吸入、食入、皮肤接触、眼睛接触', '重氮化合物有毒，接触或吸入可能引起中毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。可能引起过敏反应。长期或反复接触可能对器官造成伤害。', '对水生物有毒，对水生环境可能会引起长期有害作用。', '遇热有火灾危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5174, 5282, NULL, NULL, NULL, NULL, NULL, '第2.1类 易燃气体', '吸入\n急性中毒：轻者有咳嗽、胸闷、头晕、乏力、恶心等；较重者出现化学性肺炎或间质型肺水肿;\n严重者出现肺水肿及心肌损害。吸入有机氟聚合物热解物后，可引起氟聚合物烟尘热。慢性中毒：长期接触可引起慢性支气管炎、肺功能损害、心肌损害等。高浓度接触可引起肺水肿、心肌损害，严重者可导致死亡。', '急性毒性：属低毒类，但高浓度吸入可引起严重肺水肿和心肌损害。吸入有机氟聚合物热解物可引起氟聚合物烟尘热，表现为发热、寒战、肌肉酸痛等。慢性影响：长期接触可能引起慢性支气管炎、肺功能下降、心肌损害等。皮肤接触：液态四氟乙烯可引起冻伤。眼睛接触：液态四氟乙烯可引起眼部冻伤和刺激。吸入：高浓度可引起头晕、头痛、乏力、咳嗽、胸闷，严重者可出现肺水肿、心肌损害，甚至死亡。GHS分类：易燃气体类别1，特异性靶器官毒性-反复接触类别3（如适用）。', '对大气可造成污染。该物质对环境有危害，应特别注意对大气的污染。在上层大气中可被能量更大的紫外线分解。对臭氧层可能有潜在影响。', '本品易燃。与空气混合能形成爆炸性混合物，遇热源和明火有燃烧爆炸的危险。气体比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。受热可发生聚合反应，放出大量热量，有爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5175, 5283, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '本品为神经毒。吸入、经口和经皮肤吸收均可引起中毒。四甲铅引起人中毒迄今尚未见报\n道。动物实验四甲铅中毒与四乙铅相似，实验动物出现兴奋、痉挛、共济失调、震颤、昏\n迷等。', '无资料', '本品易燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5176, 5284, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收', '重者可出现昏迷、抽搐等。对皮肤、粘膜有刺激作用。慢性影响可有神衰综合征。', '该物质对环境有危害，应特别注意对水体的污染。', '遇高热、明火或与氧化剂接触，有引起燃烧的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5177, 5285, NULL, NULL, NULL, NULL, NULL, '第3类易燃液体', '吸入、食入、皮肤接触、眼睛接触', '吸入、食入或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。高浓度接触可引起头痛、头晕、恶心、呼吸困难等症状。', '对水生物有剧毒,对水生环境可能会引起长期有害作用。', '易燃,其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5178, 5286, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收', '本品为高毒类有机磷酸酯类化合物。抑制胆碱酯酶活性，引起神经功能紊乱。急性中毒表现有头晕、头痛、乏力、恶心、呕吐、腹痛、流涎、多汗、瞳孔缩小、肌束震颤、呼吸困难、肺水肿等。严重者可出现昏迷、呼吸衰竭、抽搐等症状。', '对水生生物有极高毒性。可能对水环境造成长期不良影响。', '本品可燃、高毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5179, 5287, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n抑制中枢神经系统；刺激呼吸道粘膜。对动物能导致呼吸道刺激、运动性兴奋及呼吸加速，然', '后呼吸极度困难、共济失调、轻瘫、四肢麻痹。本品对皮肤有强烈刺激性。可经皮吸收。', '无资料', '本品可燃，有毒，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5180, 5288, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收', '中毒。接触者及中毒者，其呼气中出现严重的蒜臭味。', '无资料', '本品不燃、具有腐蚀性、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5181, 5289, NULL, NULL, NULL, NULL, NULL, '侵入途径： 吸入，皮肤接触', '吸入，皮肤接触\n刺激眼睛、鼻、咽喉、肺，引起咳嗽、呼吸短促、眼睛损害；吸入较高浓度该物质，导致', '肺炎及肺水肿，甚至死亡', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5182, 5290, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入、食入、皮肤接触、眼睛接触', '吸入后引起呼吸道刺激。对眼有强烈刺激性。皮肤直接接触有强烈刺激性，可致灼伤。口服出现口腔和咽喉烧灼感、恶心、呕吐、水样便、血便、虚脱和惊厥。慢性影响：对呼吸道有轻度刺激作用。', '对水生生物有害，避免污染水体。', '本品不燃，具腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5183, 5291, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收\n对眼睛及上呼吸道有强烈刺激作用。高浓度可引起角膜混浊，呼吸道炎症，甚至肺水肿。眼直\n接接触可致角膜及眼睑严重灼伤。皮肤接触后可引起组织坏死。', '血。', '无资料', '本品不燃，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5184, 5292, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入', '有毒。对皮肤、眼睛和粘膜有强刺激性和腐蚀性。吸入会中毒。', '无资料', '本品不燃、有毒、具有腐蚀性、刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5185, 5293, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 皮肤接触 眼睛接触', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。吸入可引起喉、支气管炎症、化学性肺炎、肺水肿等。接触可引起头痛、头晕、恶心、呕吐等。长期或反复接触可引起慢性铅中毒，影响神经系统、血液系统、肾脏等。', '对水生生物有极高毒性，可能在水生环境中造成长期不利影响。铅化合物在环境中持久存在，具有生物富集性。', '本品腐蚀性、具有刺激性。受高热发生剧烈分解，甚至发生爆炸。遇水反应发热放出有毒的腐蚀性气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5186, 5294, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入、食入、皮肤接触、眼睛接触', '对皮肤、眼睛、粘膜和上呼吸道有强烈的刺激作用。吸入可引起喉、支气管的炎症、水肿、痉挛，化学性肺炎或肺水肿。接触可引起严重灼伤，治愈后可见有黄色色素沉着。', '无资料', '本品不燃，高毒，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5187, 5295, NULL, NULL, NULL, NULL, NULL, '第8类腐蚀性物质', '吸入、食入、皮肤接触、眼睛接触', '吸入有毒。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。吸入蒸气可引起呼吸道刺激、咳嗽、呼吸困难，高浓度可引起肺水肿。眼直接接触可致严重灼伤。皮肤接触可引起灼伤和组织损伤。长期接触可能影响肝脏和肾脏功能。硒化合物可能引起硒中毒，表现为神经系统症状、消化系统症状和皮肤病变。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。遇水水解产生氯化氢和硒化合物，对水生生态系统有严重影响。', '遇水或潮湿空气分解产生氯化氢和硒化合物，释放出有毒烟雾。受热分解产生有毒的硒氧化物和氯化物烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5188, 5296, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入食入\n对眼睛、皮肤、粘膜和呼吸道有强烈的刺激作用。吸入可能由于喉、支气管的痉挛、水', '肿、炎症，化学性肺炎、肺水肿而致死。中毒表现有烧灼感、咳嗽、喘息、喉炎、气短、\n头痛、恶心和呕吐。', '对环境有危害，对水体可造成污染。遇水剧烈反应生成盐酸和氢氧化锡，影响水体pH值，对水生生物有毒害作用。', '本品不燃，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5189, 5297, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用和腐蚀作用。眼睛及皮肤接触后引起严重灼伤。吸入会刺激咽喉、支气管，引起咳嗽及呼吸困难。重复暴露可导致X光胸部透视出现异常，可能引起慢性支气管炎、肺气肿等呼吸系统疾病。', '对水体和土壤有污染作用。', '本身不燃，受热分解产生有毒的氯化物烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5190, 5298, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、皮肤接触、眼睛接触', '对呼吸道有强烈刺激作用，可引起支气管炎和肺炎。对皮肤和眼睛有强烈刺激性，可致灼伤。吸入后可引起喉、支气管的痉挛、炎症、水肿，化学性肺炎或肺水肿。接触后可引起烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心、呕吐等。', '无资料', '本品不燃，具强腐蚀性、刺激性，可致人体灼伤。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5191, 5299, NULL, NULL, NULL, NULL, NULL, '侵入途径：', '跟皮肤接触可能会引起敏化作用。有严重损害眼睛的危险。有引起过敏、哮喘病症状或', '呼吸困难的风险。', '对水生物有剧毒,对水生环境可能会引起长期有害作用。', '无资料（基于结构分析，本品为含氯有机化合物，受热分解可能产生有毒的氯化氢气体和光气，建议评估其燃烧特性）', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5192, 5300, NULL, NULL, NULL, NULL, NULL, '无资料（建议基于重氮化合物特性评估，可能具有爆炸性、刺激性和毒性）', '无资料（建议考虑吸入、皮肤接触、眼睛接触和食入途径）', '无资料（建议基于重氮化合物和锌盐特性评估，可能对皮肤、眼睛和呼吸道有刺激性）', '无资料（建议评估对水生环境的潜在危害，含锌化合物可能对水生生物有害）', '遇热有火灾危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5193, 5301, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', NULL, '无资料', '本品可燃，有毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5194, 5302, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入 食入 经皮吸收', '对皮肤粘膜有刺激性和腐蚀性。吸入后可引起呼吸道灼伤。皮肤或眼接触可致灼伤。', '无资料', '本品易燃、有毒、具有腐蚀性、刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5195, 5303, NULL, NULL, NULL, NULL, NULL, '第3.1类低闪点易燃液体', '吸入 食入 经皮吸收', '本品具刺激作用，其蒸气有麻醉作用。', '无资料', '本品极度易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5196, 5304, NULL, NULL, NULL, NULL, NULL, '第3.1类低闪点易燃液体', '吸入食入经皮吸收', NULL, '无资料', '本品极度易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5197, 5305, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入 食入 经皮吸收', NULL, '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5198, 5306, NULL, NULL, NULL, NULL, NULL, '侵入途径：', '跟皮肤接触可能会引起敏化作用。有严重损害眼睛的危险。有引起过敏、哮喘病症状或', '呼吸困难的风险。', '对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5199, 5307, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入经皮吸收', '性中毒实验中，小鼠表现为行为异常、体重增长停顿及肝功能改变。对皮肤有弱刺激性。', '对水体可造成污染。', '本品易燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5200, 5308, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收', '吐、喉炎、气短，可引起青紫。', '对水生生物有害，可能对水生环境造成长期不良影响。含氰化合物对环境的潜在危害较大。', '本品可燃、高毒、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5201, 5309, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入食入经皮吸收', '吸入、摄入或经皮肤吸收均会中毒。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。吸入可引起肺水肿、喉头水肿而窒息。高浓度接触可引起高铁血红蛋白血症，出现紫绀、呼吸困难、头痛、头晕、乏力、恶心、呕吐等症状。严重者可因呼吸衰竭而死亡。', '无资料', '本品易燃，剧毒，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5202, 5310, NULL, NULL, NULL, NULL, NULL, '第1类爆炸品', '吸入 食入 经皮吸收', '对眼睛、皮肤、粘膜有刺激作用。受热分解放出有毒的氮氧化物烟雾。', '无资料', '本品属爆炸品、易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5203, 5311, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、皮肤接触、眼睛接触、食入', '可能对甲状腺功能和神经系统造成影响；长期接触可能导致肝脏和肾脏损伤。对眼睛、皮肤、呼吸道有刺激性。', '对水生生物有毒，可能在水生环境中造成长期有害影响；具有生物累积性。持久性有机污染物。', '遇明火、高热可燃。燃烧时可能释放有毒的溴化氢气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5204, 5312, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤和粘膜有强烈刺激作用。可能引起呼吸道刺激、头痛、恶心、呕吐等症状。', '对环境有危害。对水生生物有毒性，可能对水体造成污染。溴化物排放会对水生生物造成伤害，通过生物富集作用和食物链在生物体内蓄积。', '本品不燃，高毒，具刺激性。遇高热分解产生有毒的溴化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5205, 5313, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入', '水肿，化学性肺炎、肺水肿。接触后可引起咳嗽、喘息、烧灼感、气短、头痛、恶心和呕吐。', '无资料', '本品不燃，具腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5206, 5314, NULL, NULL, NULL, NULL, NULL, '第8类腐蚀品', '吸入、食入、皮肤接触、眼睛接触', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用和腐蚀作用。吸入可引起喉、支气管炎症、化学性肺炎、肺水肿。接触可引起灼伤、咳嗽、喘息、气短、头痛、恶心、呕吐。长期或反复接触可能引起皮肤过敏、哮喘等过敏性疾病。', '对水生生物有毒性。可能对水环境造成长期不利影响。', '遇明火、高热可燃。受热分解产生有毒的氮氧化物烟雾。与氧化剂可发生反应。燃烧产生一氧化碳、二氧化碳、氮氧化物等有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5207, 5315, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n对眼睛、粘膜、呼吸道及皮肤有强烈刺激作用。可引起眼结膜炎、支气管炎、肺炎等，可因肺', NULL, '无资料', '本品剧毒、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5208, 5316, NULL, NULL, NULL, NULL, NULL, '氧化性气体，类别1；高压气体，压缩气体；皮肤腐蚀/刺激，类别1B；眼损伤/眼刺激，类', '吸入、食入、皮肤接触、眼睛接触\n吸入', NULL, '无资料', '跟可燃物质接触可能会引起火灾。高压压缩气体，遇热有爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5209, 5317, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入\n铅及其化合物损害造血、神经、消化系统及肾脏。职业中毒主要为慢性。神经系统主要表\n现为神经衰弱综合征、周围神经病(以运动功能受累较明显)，重者出现铅中毒性脑病。消', NULL, '无资料', '本品不燃，有毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5210, 5318, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收', '抑制胆碱酯酶活性，引起神经功能紊乱，出现头晕、头痛、乏力、恶心、呕吐、腹痛、腹泻、流涎、多汗、瞳孔缩小、肌肉震颤、抽搐、呼吸困难、肺水肿、脑水肿等。', '无资料', '本品可燃、剧毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5211, 5319, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '发生中毒性脑病，出现谵妄、精神异常、昏迷、抽搐等。可有心脏和呼吸功能障碍，高浓度下\n可立即死亡。慢性中毒：主要表现为神经衰弱综合征和植物神经功能紊乱。可有“三低征”和\n脑电图异常。', NULL, '本品可燃，剧毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5212, 5320, NULL, NULL, NULL, NULL, NULL, '第8.2类碱性腐蚀品', '吸入 食入 经皮吸收', '支气管炎症、痉挛，化学性肺炎及肺水肿等。', '无资料', '本品不燃、具有强腐蚀性，强刺激性，可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5213, 5321, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吞食后有剧毒。吸入有剧毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '易燃，其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5214, 5322, NULL, NULL, NULL, NULL, NULL, '第1类爆炸品', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤、粘膜和上呼吸道有刺激作用。吸入、食入或经皮肤吸收可能引起中毒。', '对水生生物有害。', '通过打击、摩擦、火灾或其他着火源有爆炸危险。受热或接触火焰可能会产生膨胀或爆炸性分解。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5215, 5323, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有刺激性。接触后可出现头痛、头晕、恶心、呕吐等症状。皮肤接触可引起刺激、红肿、疼痛。眼睛接触可导致眼部刺激。食入可引起恶心、呕吐、腹痛。长期接触可能对肝脏、肾脏造成损害。', '对水生环境可能会引起长期有害作用。', '易燃，其蒸气与空气混合，能形成爆炸性混合物。受热分解产生有毒的烟气，遇明火、高热可燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5216, 5324, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '高浓度蒸气可引起麻醉作用，出现平衡失调、四肢痉挛性抽搐、流涎、头痛、眩晕。可引起膀胱炎，有时有肾损害。还可出现眼及上呼吸道刺激症状。液体溅入眼内，可引起结膜炎及角膜灼伤。长期接触可发生呼吸道刺激症状及乏力、嗜睡、头痛、眩晕、食欲减退等。还可能有尿频及蛋白尿。对皮肤有原发性刺激作用，引起脱脂、干燥发红等。可引起过敏性皮炎，表现为红斑或丘疹，有瘙痒感；重者可发生水疱或脓疱；特别敏感者可发生全身性皮炎。', '该物质对环境可能有危害，对水体应给予特别注意。对水生环境可能会引起长期有害作用。', '易燃，其蒸气与空气混合，能形成爆炸性混合物。受热分解产生有毒的烟气。遇明火、高热可燃。与硝酸发生剧烈反应或立即燃烧。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5217, 5325, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有刺激性。高浓度蒸气可引起麻醉作用，出现头痛、头晕、恶心、呕吐等症状。长期接触可引起皮肤干燥、脱脂、红肿。液体溅入眼内可引起结膜炎及角膜灼伤。', '对环境可能有危害，对水体应给予特别注意。对水生环境可能会引起长期有害作用。', '易燃，其蒸气与空气混合，能形成爆炸性混合物。受热分解产生有毒的烟气。遇明火、高热可燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5218, 5326, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有刺激性。接触后可出现头痛、头晕、恶心、呕吐等症状。皮肤接触可引起刺激、红肿、疼痛。眼睛接触可导致眼部刺激。食入可引起恶心、呕吐、腹痛。', '该物质对环境可能有危害，对水体应给予特别注意。对水生环境可能会引起长期有害作用。', '易燃，其蒸气与空气混合，能形成爆炸性混合物。受热分解产生有毒的烟气。遇明火、高热可燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5219, 5327, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有刺激性。接触后可出现头痛、头晕、恶心、呕吐等症状。皮肤接触可引起刺激、红肿、疼痛。眼睛接触可导致眼部刺激。食入可引起恶心、呕吐、腹痛。', '该物质对环境可能有危害，对水体应给予特别注意。对水生环境可能会引起长期有害作用。', '高度易燃，其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5220, 5328, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有剧毒。跟皮肤接触有剧毒。吸入有剧毒。', '对水生物有剧毒,对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5221, 5329, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n为强烈的神经毒物，对肝、肾有损害作用。吸入、口服可引起急性中毒；可经皮肤吸收。急性\n中毒：口服出现恶心、呕吐、腹部绞痛、厌食等。3～5天后出现多发性颅神经和周围神经损害。', NULL, '无资料', '本品易燃，高毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5222, 5330, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入经皮吸收', '无资料。', NULL, '本品易燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5223, 5331, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入经皮吸收', NULL, NULL, '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5224, 5332, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入经皮吸收\n吸入、口服或经皮肤吸收后对身体有害。对皮肤有刺激性。其蒸气或雾对眼睛、粘膜和上', '呼吸道有刺激作用。', NULL, '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5225, 5333, NULL, NULL, NULL, NULL, NULL, '第4.3类遇湿易燃物品', '吸入食入经皮吸收\n损害皮肤，引起皮肤瘙痒、炎症、“鸟眼”样溃疡、黑皮病。皮肤灼伤表现为创面长期不', NULL, '无资料', '本品遇湿易燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5226, 5334, NULL, NULL, NULL, NULL, NULL, '第4.3类遇湿易燃物品', '吸入食入', '对眼睛、粘膜和上呼吸道有刺激性。', '无资料', '本品遇湿易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5227, 5335, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入\n口服后与胃酸起反应，变为氯化钡而发生中毒。急性中毒表现有恶心、呕吐、腹痛、腹泻、脉\n缓、进行性肌麻痹、心律紊乱、血钾明显降低等。可因心律紊乱和呼吸肌麻痹而死亡。重症可', '并发急性肾功能衰竭、缺氧性脑病、酸中毒等。吸入高浓度本品粉尘可发生急性中毒。慢性影\n响：长期接触钡化合物的工人，可有无力、气促、流涎、口腔粘膜肿胀、糜烂、鼻炎、结膜炎、\n腹泻、心动过速、血压增高、脱发等。', '无资料', '本品不燃，高毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5228, 5336, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5229, 5337, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入经皮吸收\n吸入、口服或经皮肤吸收后对身体有害。其蒸气或雾对眼睛、皮肤、粘膜和呼吸道有刺激', '性。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5230, 5338, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入经皮吸收\n吸入、口服或经皮肤吸收对身体有害。', '和上呼吸道有刺激性。大鼠在29.7g/m3浓度下很快发生喘息，共济失调，口、鼻出现泡\n沫，肺水肿，在2小时内死亡。', NULL, '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5231, 5339, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入经皮吸收', '高浓度蒸气对眼有刺激性。口服刺激胃肠道。皮肤长期反复接触有刺激性。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5232, 5340, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收\n急性中毒的表现主要为急性化学性支气管炎和支气管肺炎(急性铍病)。长期小量接触，\n可引起慢性铍病，出现无力，消瘦、食欲不振、胸闷、胸痛、咳嗽和气短等，对皮肤的', NULL, '无资料', '本品不燃、高毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5233, 5341, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收\n铊的口服致死量约在0.2～1.0g。急性中毒最初出现胃肠道刺激症状：恶心、呕吐、腹绞\n痛 等。以后出现神经系统损害，呈多发性颅神经和周围神经损害的表现，严重时有谵妄、\n精神失常、晕厥和呼吸肌麻痹。同时，尚有心、肝、肾的损害。脱发是其中毒的特征表现，', '可累及全身毛发，但眉毛内侧1／3不受侵犯。', '无资料', '本品不燃、高毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5234, 5342, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, '易燃,其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5235, 5343, NULL, NULL, NULL, NULL, NULL, '第2.3类 有毒气体', '吸入 经皮吸收\n主要损害呼吸道，导致化学性支气管炎、肺炎、肺水肿。急性中毒：轻度中毒，患者有流泪、\n畏光、咽部不适、咳嗽、胸闷等；中度中毒，除上述症状加重外，患者出现轻度呼吸困难、轻', '度紫绀；重度中毒出现肺水肿或成人呼吸窘迫综合征，患者剧烈咳嗽、咯大量泡沫痰、呼吸窘\n迫、明显紫绀。肺水肿发生前有一段时间的症状缓解期(一般 1～24小时)。可并发纵隔及皮下\n气肿。', NULL, '本品不燃，剧毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5236, 5344, NULL, NULL, NULL, NULL, NULL, '第2.3类 有毒气体', '吸入', '本品对呼吸道粘膜具有强烈的刺激作用。急性中毒可致化学性肺炎和肺水肿。因本品常', '无资料', '本品不燃、剧毒、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5237, 5345, NULL, NULL, NULL, NULL, NULL, '第2.3类 有毒气体', '吸入', '吸麻痹而死亡。', '无资料', '本品易燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5238, 5346, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n对呼吸道有刺激作用，并有全身毒作用，可导致肺、肝、脑损害。如肺水肿抢救不及时，\n可引起死亡。急性中毒：早期表现有头痛、头晕、步态不稳、视力模糊、眼刺激、恶心、', '心 悸、胸闷、气短等。迟发的症状主要有明显的胸闷、气短、严重呼吸困难、紫绀、咳\n嗽、咳大量粉红色泡沫痰，心动过速等，这些是肺水肿及弥漫性间质肺炎的表现。镍及其\n化合物已被国际癌症研究中心(IARC)确认为致癌物。', '无资料', '本品易燃、高毒、为致癌物、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5239, 5347, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、皮肤接触、眼睛接触', '锑对粘膜有刺激作用，可引起内脏损害。急性中毒：接触较高浓度引起化学性结膜炎、鼻炎、咽炎、喉炎、支气管炎、肺炎。口服引起急性胃肠炎。全身症状有疲乏无力、头晕、头痛、四肢麻木等。', '该物质对环境有危害，对水体和土壤可造成污染，对鱼类和哺乳动物应给予特别注意。', '遇明火、高热可燃。粉体与空气可形成爆炸性混合物，当达到一定浓度时，遇火星会发生爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5240, 5348, NULL, NULL, NULL, NULL, NULL, '第2.3类 有毒气体', '吸入', '吸入较高浓度的锑化氢，可发生溶血。表现头痛，恶心，呕吐，无力，呼吸减慢、微弱，脉不规则，腹绞痛以及血红蛋白尿。最后可造成急性溶血性贫血和急性肾功能衰竭。吸入高浓度可迅速致死。', '对环境有一定危害，对水体和土壤可造成污染。', '本品易燃，高毒。遇明火、高热极易燃烧爆炸。与氧化剂、氯气、硝酸、臭氧、氨剧烈反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5241, 5349, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤、粘膜和上呼吸道有刺激作用。误服可引起恶心、呕吐、腹泻等消化道症状。长期接触可能对肝脏、肾脏和神经系统造成损害。', '对水生生物有毒性，可能在水生环境中造成长期不利影响。对蜜蜂和其他有益昆虫有毒。', '遇明火、高热可燃。受热分解产生有毒的氯化氢、二氧化硫等气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5242, 5350, NULL, NULL, NULL, NULL, NULL, '第2.1类易燃气体；高压气体，压缩气体', '吸入、食入、皮肤接触、眼睛接触', '甲烷对人基本无毒，但浓度过高时，使空气中氧含量明显降低，使人窒息。当空气中甲烷达25%-30%时，可引起头痛、头晕、乏力、呼吸加速、运动失调等症状。高浓度可引起窒息、昏迷甚至死亡。单纯性窒息作用。', '对大气环境有影响，可能导致温室效应。泄漏到大气中会形成爆炸性混合物。', '极端易燃气体，有爆炸危险。高压压缩气体，遇热有爆炸危险。与空气混合能形成爆炸性混合物，遇明火、高热极易燃烧爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5243, 5351, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入 食入', '摄入有中等毒性。热解能放出腐蚀性烟和刺激性雾。', '无资料', '本品易燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5244, 5352, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, '易燃,其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5245, 5353, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, '高度易燃，其粉体与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5246, 5354, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5247, 5355, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吞食后有毒。跟皮肤接触有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。中毒症状有：头痛、头晕、恶心、呕吐、腹痛、腹泻等。严重者可出现抽搐、昏迷。', '对水生生物有极高毒性，可能对水体环境产生长期不良影响。', '遇明火、高热可燃。受热分解产生有毒的烟雾。爆炸性分解。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5248, 5356, NULL, NULL, NULL, NULL, NULL, '第7类 放射性物品', '吸入 食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5249, 5357, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '等。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5250, 5358, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有剧毒。吸入有剧毒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5251, 5359, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入', '有毒。对眼睛、粘膜和呼吸系统有强烈刺激作用。遇水剧烈反应产生剧毒的氟化氢气体。', '无资料', '本品不燃、有毒、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5252, 5360, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入 食入 经皮吸收\n对皮肤、眼睛和粘膜有强烈的刺激性和腐蚀性，与水或潮湿空气剧烈反应，放出剧毒和腐', '蚀性烟雾，吸入会中毒。遇热分解释出高毒的氟、碘烟雾。', '无资料', '本品助燃、有毒、具有腐蚀性、强刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5253, 5361, NULL, NULL, NULL, NULL, NULL, '第2.3类 有毒气体', '吸入\n在潮湿空气中产生有毒和腐蚀性的氟化氢。', '后可引起呼吸道炎症，肺水肿。', '无资料', '本品不燃，有毒，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5254, 5362, NULL, NULL, NULL, NULL, NULL, '第2.3类 有毒气体', '吸入', '烟', '无资料', '本品助燃、有毒、具有腐蚀性、强刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5255, 5363, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收\n对眼睛、皮肤、粘膜和呼吸道有强烈的刺激作用。吸入可能由于喉、支气管的痉挛、水肿、炎', '症，化学性肺炎、肺水肿而致死。中毒表现有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心\n和呕吐。', '无资料', '本品腐蚀性、刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5256, 5364, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入 食入', '皮肤、粘膜有强烈刺激作用并可引起灼伤。', '无资料', '本品助燃、有毒、具有强腐蚀性、强刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5257, 5365, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, '易燃,其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5258, 5366, NULL, NULL, NULL, NULL, NULL, '第4.3类遇湿易燃物品', '吸入食入经皮吸收', '对眼、呼吸道及皮肤有刺激性。', '无资料', '本品遇湿易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5259, 5367, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入\n接触锑及其化合物可致眼结膜和呼吸道刺激，发生支气管炎，较重者出现胸痛、呼吸困难。口', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5260, 5368, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, '对水生物有剧毒,对水生环境可能会引起长期有害作用。', '高度易燃，其粉体与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5261, 5369, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n吸入或经皮肤吸收可引起头痛、疲倦、眼睛、粘膜及皮肤的刺激症状、神经痛、多汗、呼吸', NULL, '无资料', '本品剧毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5262, 5370, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, '对水生物有剧毒,对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5263, 5371, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5264, 5372, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '烦躁不安、肌肉强直性痉挛、血压下降，昏迷，可致死。皮肤接触可致接触性皮炎。国外资料\n报道长期接触者可有周围神经病。', '无资料', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5265, 5373, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收\n其蒸气和烟尘可引起眼结膜刺激症状。刺激咽喉引起灼痛、失音或吞咽困难。可引起支气管炎，\n严重者发生肺炎、肺水肿，喉头水肿可致窒息。眼和皮肤接触可致灼伤。慢性影响：长期低浓', '度接触可引起眼及呼吸道刺激症状。可引起磷毒性口腔病。', NULL, '本品不燃，具强腐蚀性、刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5266, 5374, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入', '本品对眼睛、皮肤、粘膜和上呼吸道有刺激性。', '无资料', '本品不燃，具腐蚀性、刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5267, 5375, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入', '目前，尚未见引起人中毒的报告，粉尘和蒸气对皮肤、眼睛和粘膜有刺激性。', '无资料', '本品不燃、强腐蚀性、刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5268, 5376, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入', '本品有毒。遇水能产生氯化氢，对皮肤和粘膜有刺激作用。', '无资料', '本品不燃、具有腐蚀性、刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5269, 5377, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收\n对眼睛、皮肤、粘膜和呼吸道有强烈的刺激作用。吸入可能由于喉、支气管的痉挛、水肿、炎\n症，化学性肺炎、肺水肿而致死。中毒表现有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心', '和呕吐。', '无资料', '本品不燃，剧毒、具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5270, 5378, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收\n长期接触', '脸肿、皮肤痤疮、胃肠功能紊乱等。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5271, 5379, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n主要损害心血管系统、中枢神经系统、肝和肾。小白鼠急性中毒时，出现呼吸加快、发绀、颤', '抖、痉挛性抽搐、共济运动失调，甚至死亡。慢性作用下，初期红细胞数和血红蛋白含量增加，\n随后抑制造血功能，衰竭、抽搐，部分动物可致死。', '无资料', '本品有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5272, 5380, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', NULL, '对水体可造成污染。', '本品可燃，有毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5273, 5381, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, '对水生物有剧毒,对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5274, 5382, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收\n吸入、摄入或经无伤皮肤吸收后对身体有剧毒。有强烈的刺激作用。能引起化学性肺炎，', '急性肺水肿等。在生产条件下，本品的中毒情况与CO中毒症状相似。', '无资料', '本品易燃、高毒、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5275, 5383, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, '对水生物有剧毒, 对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5276, 5384, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入', '遇水或水蒸气后释放出有毒和腐蚀性烟雾。加热分解释出高毒的溴化物烟雾。对眼睛、皮肤和\n粘膜有强烈刺激性和腐蚀性。', NULL, '本品不燃，剧毒，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5277, 5385, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入\n急性中毒：轻度时，仅有轻微的眼和上呼吸道刺激症状；中度时，出现头痛、咳嗽及胸部不适', '感，经过一段潜伏期，可发生肺水肿，引起死亡。慢性作用：主要表现为神经衰弱综合征及慢\n性呼吸道炎症。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5278, 5386, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, '跟可燃物质接触可能会引起火灾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5279, 5387, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n对呼吸系统和皮肤有损害作用。急性中毒：可引起鼻、咽、肺部刺激症状，多数工人有咽 痒、\n干咳、胸闷、全身不适、倦怠等表现，部分患者可引起肾炎、肺炎。慢性中毒：长期接', NULL, '无资料', '本品有毒、刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5280, 5388, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收', NULL, '无资料', '本品不燃，具强腐蚀性、刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5281, 5389, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n砷及其化合物对体内酶蛋白的巯基有特殊亲和力。急性中毒：口服致急性胃肠炎、休克、周围\n神经病、贫血及中毒性肝病, 心肌炎等。可因呼吸中枢麻痹而死亡。短期内大量吸入可致咳嗽、', NULL, NULL, '本品不燃，剧毒，为致癌物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5282, 5390, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入\n对粘膜有刺激作用，可引起内脏损害。急性中毒：接触较高浓度可引起化学性结膜炎、鼻炎、\n咽炎、喉炎、气管炎、肺炎。口服引起胃肠炎。全身症状有疲乏无力、头晕、头痛、四肢肌肉', NULL, '无资料', '本品不燃，有毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5283, 5391, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '属中等毒类。对眼、皮肤、粘膜和上呼吸道有刺激性。接触后可引起烧灼感、头痛、头晕、咳嗽、气短、恶心、呕吐等症状。皮肤接触可引起灼伤、红肿、疼痛。眼睛接触可导致严重眼部损伤。食入可引起恶心、呕吐、腹痛。受热或与酸接触会产生剧毒的氰化物气体。', '该物质对环境有危害，应特别注意对水体的污染。', '本品可燃、有毒、具刺激性。遇明火能燃烧。受高热或与酸接触会产生剧毒的氰化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5284, 5392, NULL, NULL, NULL, NULL, NULL, '第8类腐蚀品；第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤和粘膜有强烈的刺激作用。吸入，可引起喉、支气管的炎症、痉挛、化学性肺炎、肺气肿等。本品可引起过敏反应。吞咽有害。吸入有毒。会导致灼伤。吸入和皮肤接触会导致过敏。', '该物质对环境可能有危害，应避免排放到周围环境中。', '本品可燃、有毒、具有强刺激性。遇明火、高热可燃。受热分解产生有毒气体。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5285, 5393, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入、食入、经皮吸收', '对眼、皮肤、粘膜和上呼吸道有刺激性。接触后可引起烧灼感、头痛、头晕、咳嗽、气短、恶心、呕吐等症状。皮肤接触可引起红肿、疼痛。眼睛接触可导致眼部损伤。食入可引起恶心、呕吐、腹痛。', '该物质对环境可能有危害，应避免排放到周围环境中。', '一定的浓度时，遇火星会发生爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5286, 5394, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、经皮吸收', '氯硅烷类单体对眼、上呼吸道粘膜有强烈刺激性。局部可出现充血、水肿，甚至坏死。长时间接触高浓度，可引起鼻粘膜萎缩、支气管炎、肺充血和肺水肿。粘膜和皮肤接触其液体，可致皮炎和灼伤。', '该物质对环境可能有危害，应避免排放到周围环境中。', '本品易燃、强腐蚀性、强刺激性、可致人体灼伤。遇高热、明火或与氧化剂接触，有引起燃烧的危险。吸潮或遇水会产生大量的腐蚀性烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5287, 5395, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '属中等毒类。对眼睛、皮肤、粘膜和上呼吸道有刺激性。吸入、摄入或经皮肤吸收后对身体有害。皮肤接触可引起灼伤、红肿、疼痛。眼睛接触可导致严重眼部损伤。食入可引起恶心、呕吐、腹痛。高浓度吸入可引起意识丧失。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃、有毒、具刺激性。遇明火、高热易燃。其蒸气与空气混合，能形成爆炸性混合物。受热分解产生有毒的氰化物气体。其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5288, 5396, NULL, NULL, NULL, NULL, NULL, '第4.2类自燃物品；第6.1类毒害品', '吸入、食入、经皮吸收', '急性中毒：出现神经系统症状，主要表现有头痛、头晕、嗜睡、眼肌麻痹、皮肤感觉过敏，重者出现共济失调、肌痉挛、抽搐、角弓反张、意识障碍或精神错乱。可有神经炎及心、肝、肾损害。对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用。', '该物质对环境可能有危害，应避免排放到周围环境中。', '本品易燃，剧毒，具强刺激性。剧烈分解，引起容器破裂或爆炸事故。与强氧化剂如铬酸酐、氯酸盐和高锰酸钾等接触，能发生强烈反应，引起燃烧或爆炸。与水和水蒸气反应，放出易爆炸着火的氢气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5289, 5397, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼、皮肤、粘膜和上呼吸道有刺激性。接触后可出现头痛、头晕、恶心、呕吐等症状。皮肤接触可引起刺激、红肿、疼痛。眼睛接触可导致眼部损伤。食入可引起恶心、呕吐、腹痛。', '对水体可造成污染。该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃、具刺激性。遇明火、高热易燃。其蒸气与空气可形成爆炸性混合物。其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。受热分解，放出烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5290, 5398, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '尚未见职业中毒报道。对眼、皮肤、粘膜和上呼吸道有刺激性。接触后可出现头痛、头晕、恶心、呕吐等症状。皮肤接触可引起刺激、红肿、疼痛。眼睛接触可导致眼部损伤。食入可引起恶心、呕吐、腹痛。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃、具刺激性。遇明火、高热易燃。其蒸气与空气可形成爆炸性混合物。其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。受热分解，放出烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5291, 5399, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后会中毒。对眼、皮肤、粘膜和上呼吸道有强烈的腐蚀性和刺激性。吸入可引起喉和支气管的痉挛、炎症、水肿，化学性肺炎或肺水肿。皮肤接触可引起灼伤、红肿、疼痛。眼睛接触可导致严重眼部损伤。食入可引起恶心、呕吐、腹痛、消化道灼伤。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃、有毒、具有腐蚀性、刺激性、可致人体灼伤。遇明火、高热易燃。受热分解，放出高毒的氯化氢、光气等烟气。其蒸气与空气可形成爆炸性混合物。其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5292, 5400, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n主要是抑制胆碱酯酶，使乙酰胆碱在组织中蓄积。主要症状为流涎、恶心、流泪、瞳孔缩 小、\n视力模糊、痉挛等。其抑制胆碱酯酶的作用持续时间较短，停止接触后，胆碱酯酶恢复', '较快。', '无资料', '本品可燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5293, 5401, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '硒对皮肤粘膜有较强的刺激性。大量吸入可引起急性中毒，出现鼻塞、流涕、咽痛、咳嗽、眼刺痛，头痛、头晕、恶心、呕吐等症状。慢性中毒：长期接触一定浓度的硒，可有头痛、头晕、无力、恶心、呕吐、食欲减退、腹泻等症状。还可有肝大、肝功能异常、低血压、心动过缓等植物神经功能紊乱的表现。', '对水生生物有毒性作用', '本品可燃、有毒、强刺激性。在高温下可燃烧，受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5294, 5402, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入或口服对身体有害。具有刺激性。接触可引起恶心、头痛和呕吐。慢性影响：肾和肺脏损伤。长期接触可引起镉中毒和硒中毒，表现为头痛、头晕、乏力、贫血、腹痛、脱发、指甲脱落、皮肤病变、神经系统损害、肾功能损害等症状。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '本品可燃，高毒，具刺激性。受热或遇酸能产生剧毒的硒化氢气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5295, 5403, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入粉尘可引起呼吸道刺激。长期接触可引起铅中毒和硒中毒，表现为头痛、头晕、乏力、贫血、腹痛、脱发、指甲脱落、皮肤病变、神经系统损害等症状。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '遇明火、高热可燃。受热分解产生有毒的铅化合物和硒化物烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5296, 5404, NULL, NULL, NULL, NULL, NULL, '第2.3类有毒气体', '吸入、皮肤接触、眼睛接触', '对上呼吸道粘膜和眼结膜有强烈的刺激作用。急性中毒：接触数分钟至3小时内，陆续出现中毒症状：流泪、咽痛、咳嗽，伴有胸闷、胸痛。重者进一步发展为化学性肺炎或中毒性肺水肿，患者出现呼吸困难，心跳加快，面色苍白，皮肤粘膜紫绀。接触本晶可引起皮疹。', '对水生生物有毒性作用', '本品易燃、有毒、强刺激性。与空气混合能形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5297, 5405, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入粉尘可引起呼吸道刺激。长期接触可引起硒中毒，表现为脱发、指甲脱落、皮肤病变、神经系统损害等症状。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '遇明火、高热可燃。受热分解产生有毒的硒化物和氧化硒烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5298, 5406, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收、皮肤接触、眼睛接触', '皮肤经常接触可引起皮炎。如遇稀硝酸，易分解散发出剧毒的硒化氢气体。对眼睛、呼吸道粘膜有刺激作用。长期接触可引起硒中毒，表现为头痛、头晕、乏力、贫血、腹痛、脱发、指甲脱落、皮肤病变、神经系统损害等症状。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '遇稀硝酸分解散发出剧毒的硒化氢气体。本品不燃、有毒、具有刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5299, 5407, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吞咽致命。吸入会中毒。长期或反复接触可能损害器官。对皮肤、眼睛和呼吸道有刺激性。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '可燃，遇明火、高热可燃。受热分解产生有毒烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5300, 5408, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、经皮吸收', '具有强腐蚀性。吸入可引起呼吸道刺激症状，严重者可发生化学性肺炎、肺水肿。食入可引起口腔、咽喉、食管和胃部灼伤，出现恶心、呕吐、腹痛、腹泻等症状，严重者可导致休克。皮肤接触可引起严重灼伤。眼睛接触可引起角膜灼伤，严重者可导致失明。长期接触可引起硒中毒，表现为食欲减退、乏力、贫血、脱发、指甲脱落、皮肤病变、神经系统损害等症状。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '本品不燃，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5301, 5409, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '硒酸钡吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤和粘膜有刺激作用。吞食后有剧毒。吸入有毒。长期暴露有损伤健康的危险。可引起钡中毒和硒中毒，表现为食欲减退、乏力、贫血、脱发、指甲脱落、皮肤病变、神经系统损害、肌肉无力、心律失常等症状。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '不燃，受高热分解时会释放有毒烟气。燃烧（分解）产物包括氧化硒、二氧化硒、氧化钡等有毒烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5302, 5410, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '误服或吸入会中毒。溶液能灼伤皮肤。中毒时可见上呼吸道和眼粘膜刺激症状、头痛、眩晕、恶心、呕吐、全身虚弱等。长期接触可引起硒中毒，表现为食欲减退、乏力、贫血、脱发、指甲脱落、皮肤病变、神经系统损害等症状。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '不燃，受高热分解时会释放有毒烟气。燃烧（分解）产物包括氧化硒、二氧化硒等有毒烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5303, 5411, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '硒酸钠吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤和粘膜有刺激作用。吞食后有剧毒。吸入有毒。长期暴露有损伤健康的危险。可引起硒中毒，表现为食欲减退、乏力、贫血、脱发、指甲脱落、皮肤病变、神经系统损害等症状。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '不燃，受高热分解时会释放有毒烟气。燃烧（分解）产物包括氧化硒、二氧化硒等有毒烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5304, 5412, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '硒酸铜吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤和粘膜有刺激作用。吞食后有剧毒。吸入有毒。长期暴露有损伤健康的危险。可引起硒中毒和铜中毒，表现为食欲减退、乏力、贫血、脱发、指甲脱落、皮肤病变、神经系统损害、肌肉无力、心律失常等症状。意外食入本品可导致严重的毒性反应。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '不燃，受高热分解时会释放有毒烟气。燃烧（分解）产物包括氧化硒、二氧化硒、氧化铜等有毒烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5305, 5413, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、皮肤接触、眼睛接触', '吸入、摄入或经皮肤吸收后会中毒。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。吸入可引起喉炎、化学性肺炎和肺水肿。接触后可发生头痛、恶心、呕吐、咳嗽、气短等症状。皮肤接触可引起灼伤。眼睛接触可引起严重灼伤，甚至失明。', '对水生生物有毒性。对环境有危害，对水体可造成污染。', '易燃。遇明火、高热有燃烧爆炸的危险。受热分解产生有毒的氯化物烟雾。遇水或水蒸气反应产生氯化氢气体，具有强腐蚀性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5306, 5414, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有剧烈刺激作用。吸入后可引起喉、支气管的炎症、水肿、痉挛，化学性肺炎、肺水肿等。大量接触可引起皮炎。对中枢神经有抑制作用。皮肤致敏物。', '对水生生物有毒性。对环境可能有危害，对水体应给予特别注意。', '易燃。遇明火、高热有燃烧爆炸的危险。受热分解产生有毒气体。若遇高热，容器内压增大，有开裂和爆炸的危险。可能形成爆炸性的过氧化物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5307, 5415, NULL, NULL, NULL, NULL, NULL, '第2.2类不燃气体', '吸入', '在高浓度下可引起窒息。人吸入混有70%氙气的氧，引起轻度麻醉，约经3分钟即意识丧失。', '对环境无特殊危害。', '本品不燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5308, 5416, NULL, NULL, NULL, NULL, NULL, '第1.1类爆炸物', '吸入、食入、皮肤接触、眼睛接触', '吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入可引起消化道刺激。长期接触可能对皮肤、眼睛有刺激作用。', '对水生生物有毒性，对环境有危害。', '通过打击、摩擦、火灾或其他着火源有极大爆炸危险。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5309, 5417, NULL, NULL, NULL, NULL, NULL, '第1.1类爆炸物', '吸入、食入、经皮吸收', '少量吸收即可引起剧烈的搏动性头痛，常有恶心、心悸，有时有呕吐和腹痛，面部发热、潮红；较大量产生低血压、抑郁、精神错乱，偶见谵妄、高铁血红蛋白血症和紫绀。饮酒后，上述症状加剧，并可发生躁狂。本品易经皮肤吸收，应防止皮肤接触。慢性影响：可有头痛、疲乏等不适。', '对水生生物有毒性，对环境有危害。', '撞击、摩擦，遇明火、高热时，均有引起爆炸的危险。与强酸接触能发生强烈反应，引起燃烧或爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5310, 5418, NULL, NULL, NULL, NULL, NULL, '第8类腐蚀性品', '吸入、食入、皮肤接触、眼睛接触', '吸入蒸气或雾对呼吸道有强烈刺激性。直接接触液体可引起严重灼伤。食入可引起严重消化道灼伤。', '对水生生物有毒性，对环境有危害。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5311, 5419, NULL, NULL, NULL, NULL, NULL, '第1.3类爆炸物', '吸入、食入、皮肤接触、眼睛接触', '吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入可引起消化道刺激。长期接触可能对皮肤、眼睛有刺激作用。', '对水生生物有毒性，对环境有危害。', '通过打击、摩擦、火灾或其他着火源有极大爆炸危险。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5312, 5420, NULL, NULL, NULL, NULL, NULL, '第4.1类易燃固体', '吸入、食入、皮肤接触、眼睛接触', '燃烧时产生有毒烟雾，对眼睛、皮肤和粘膜有刺激性。长期接触可能对呼吸系统有损害作用。', '对水生生物有毒性，对环境有危害。', '遇明火、高热极易燃烧。燃速很快。与氧化剂接触发生强烈反应，甚至引起燃烧。久储会逐渐发热，若积热不散会引起自燃。其粉体化学活性很高，在空气中能自燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5313, 5421, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '主要引起高铁血红蛋白血症。可引起溶血及肝损害。急性中毒：有头痛、头晕、乏力、皮肤粘膜紫绀、手指麻木等症状；严重时可出现胸闷、呼吸困难、心悸，甚至心律紊乱、昏迷、抽搐、呼吸麻痹。有时中毒后出现溶血性贫血、黄疸、中毒性肝炎。慢性中毒：可有神经衰弱综合征；慢性溶血时，可出现贫血、黄疸；还可引起中毒性肝炎。', '对水生生物有毒性，对环境有危害。', '本品可燃，有毒。遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5314, 5422, NULL, NULL, NULL, NULL, NULL, '第4.1类 易燃固体', '吸入、食入、皮肤接触、眼睛接触', '本品对人有毒，具刺激作用，受热分解会释出有毒的氮氧化物烟雾。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生生物有毒性，对环境有危害。', '遇高热、明火或与氧化剂接触，有引起燃烧的危险。震动撞击时可发生爆炸。受热分解产生有毒的氮氧化物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5315, 5423, NULL, NULL, NULL, NULL, NULL, '第1类爆炸品', '吸入、食入、皮肤接触、眼睛接触', '吸入、食入、皮肤接触和眼睛接触均有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。受热分解产生有毒的氮氧化物。', '对水生生物有毒性，对环境有危害。', '本品属爆炸品，可燃，具强刺激性。受热、接触明火、或受到摩擦、震动、撞击时可发生爆炸。受高热分解，产生有毒的氮氧化物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5316, 5424, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '高浓度蒸气对眼睛、皮肤和粘膜有刺激性。长期接触可能对中枢神经系统有损害作用。', '对水生生物有毒性，对环境有危害。', '本品易燃，具刺激性。胺类及三氯化铝、六甲基苯等均能引起燃烧爆炸。燃烧分解时，放出有毒的氮氧化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5317, 5425, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吞食后有剧毒。跟皮肤接触有剧毒。吸入有剧毒。主要影响中枢神经系统，可引起肌肉痉挛、呼吸麻痹，严重时可导致死亡。', '对水生生物有毒性，对环境有危害。', '受热分解可能产生有毒气体。遇明火、高热可燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5318, 5426, NULL, NULL, NULL, NULL, NULL, '第1.1类爆炸物', '吸入、食入、皮肤接触、眼睛接触', '吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入可引起消化道刺激。长期接触可能对皮肤、眼睛有刺激作用。', '对水生生物有毒性，对环境有危害。', '通过打击、摩擦、火灾或其他着火源有极大爆炸危险。受热分解产生有毒的氮氧化物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5319, 5427, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入可引起消化道刺激。长期接触可能对皮肤、眼睛有刺激作用。对中枢神经系统有影响，可能引起头痛、头晕、恶心等症状。', '对水生生物有毒性，对环境有危害。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5320, 5428, NULL, NULL, NULL, NULL, NULL, '第1.1类爆炸物', '吸入、食入、皮肤接触、眼睛接触', '吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入可引起消化道刺激。长期接触可能对皮肤、眼睛有刺激作用。', '对水生生物有毒性，对环境有危害。', '通过打击、摩擦、火灾或其他着火源有极大爆炸危险。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5321, 5429, NULL, NULL, NULL, NULL, NULL, '第8类腐蚀性物质', '吸入、食入、皮肤接触、眼睛接触', '吸入、食入、皮肤接触和眼睛接触均有害。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。可引起皮肤灼伤、眼睛损伤、呼吸道刺激。', '对水生生物有毒性，对环境有危害。', '受热分解产生有毒气体。遇金属反应可能产生易燃气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5322, 5430, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '本品有麻醉作用，有轻度刺激性。未见职业中毒报道。对眼睛、皮肤和粘膜有刺激性。对中枢神经系统有影响，可能引起头痛、头晕、恶心等症状。', '对水生生物有毒性，对环境有危害。', '本品易燃。遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5323, 5431, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、皮肤接触、眼睛接触', '其蒸气有刺激作用，引起眼和上呼吸道刺激症状，如流泪、咽喉刺激感、呛咳，并伴有头痛、头晕、胸闷等。口服引起腹部剧痛，严重者可有胃穿孔、腹膜炎、喉痉挛、肾损害、休克以及窒息。皮肤接触引起灼伤。慢性影响：长期接触可引起牙齿酸蚀症。', '对水生生物有毒性，对环境有危害。', '本品助燃，具强腐蚀性、强刺激性，可致人体灼伤。与还原剂、可燃物如糖、纤维素、木屑、棉花、稻草或废纱头等接触，引起燃烧并散发出剧毒的棕色烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5324, 5432, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对呼吸道、眼及皮肤有刺激性。接触后可引起恶心、呕吐、头痛、虚弱、无力和虚脱等。大量接触可引起高铁血红蛋白血症，影响血液的携氧能力，出现紫绀、头痛、头晕、虚脱，甚至死亡。口服引起剧烈腹痛、呕吐、血便、休克、全身抽搐、昏迷，甚至死亡。', '对环境有危害，对水体可造成污染。', '强氧化剂。助燃。与可燃物、还原剂、有机物等混合能形成爆炸性混合物，遇明火、高热有燃烧爆炸危险。受强烈震动也会起爆。急剧加热时可发生爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5325, 5433, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、皮肤接触、眼睛接触', '本品具有刺激性。迄今未见引起职业中毒的报告。对皮肤有刺激性。热解释出剧毒的氮氧化物气体，对呼吸道有刺激性。对眼睛、皮肤和粘膜有刺激性。', '该物质对环境可能有危害，在地下水中有蓄积作用。', '本品助燃，具刺激性。遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5326, 5434, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、经皮吸收', '本品具有高毒性和刺激性。误服后表现为恶心、呕吐、腹痛、腹泻、脉缓、头痛、眩晕等。严重中毒出现进行性肌麻痹、心律紊乱、血压降低、血钾明显降低等。可死于心律紊乱和呼吸肌麻痹。肾脏可能受损。大量吸入本品粉尘亦可引起中毒，但消化道反应较轻。长期接触可致口腔炎、鼻炎、结膜炎、腹泻、心动过速、脱发等。', '该物质对环境可能有危害，在地下水中有蓄积作用。', '本品助燃，高毒。遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5327, 5435, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吞食后有毒。跟皮肤接触有毒。跟皮肤接触可能会引起敏化作用。有严重损害眼睛的危险。吸入、摄入或经皮肤吸收后对身体有害。可引起高铁血红蛋白血症，表现为紫绀、头晕、头痛、乏力、恶心、呕吐、呼吸困难等。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激性。长期接触可引起慢性中毒，表现为贫血、肝脾肿大、神经系统损害等。', '对水生生物有剧毒。对环境有危害，对水体可造成污染。', '遇明火、高热可燃。受热分解，放出有毒的氮氧化物气体。有燃烧爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5328, 5436, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '本品为高毒类有机汞化合物。吸入、摄入或经皮肤吸收后对身体有害。可引起中枢神经系统损害，表现为头痛、头晕、乏力、失眠、多梦、记忆力减退、易激动、手指震颤、口腔炎、牙龈炎、流涎增多、恶心、呕吐、腹痛、腹泻等。严重者可出现谵妄、昏迷，以及接触性皮炎等。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激性。长期接触可引起慢性汞中毒，表现为神经衰弱综合征、易兴奋症、汞毒性震颤、口腔炎、牙龈炎等。', '对环境有严重危害，对水体可造成污染。汞及其化合物在环境中具有持久性和生物富集性。', '本品可燃、有毒。遇明火、高热可燃。受高热分解，放出高毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5329, 5437, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤、粘膜和上呼吸道有刺激性。至今未发现有职业中毒报导。非职业性中毒可引起恶心、呕吐、腹痛、腹泻等症状。', '该物质对环境可能有危害，在地下水中有蓄积作用。对水生生物有毒性。', '本品助燃，具刺激性。遇明火、高热可燃。受热分解产生有毒气体。与还原剂、有机物、易燃物或金属粉末等混合可形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5330, 5438, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、经皮吸收', '有毒。对眼睛、皮肤和粘膜有刺激性。长期接触可能对健康造成影响。', '对水生生物有害。', '跟可燃物质接触可能会引起火灾。与有机物、还原剂及易燃物硫、磷等混和后，摩擦、撞击，有引起燃烧爆炸的危险。遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5331, 5439, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、皮肤接触、眼睛接触', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期或反复接触可能引起器官损害。', '对水生生物有害。', '跟可燃物质接触可能会引起火灾。与有机物、还原剂及易燃物硫、磷等混和后，摩擦、撞击，有引起燃烧爆炸的危险。遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5332, 5440, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、经皮吸收', '本品具有刺激性。长期反复接触粉尘对皮肤有刺激性。吸入、摄入或经皮肤吸收后对身体有害。受热分解产生有毒的氮氧化物气体，对呼吸道有刺激性。对眼睛、皮肤和粘膜有刺激性。', '该物质对环境可能有危害，在地下水中有蓄积作用。', '本品助燃，具刺激性。遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5333, 5441, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、皮肤接触、眼睛接触', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。在高温下可分解，释放出剧毒的氮氧化物气体，吸入后可引起中毒。', '对环境有危害，对水体可造成污染。', '强氧化剂。助燃。与可燃物、还原剂、有机物等混合能形成爆炸性混合物，遇明火、高热有燃烧爆炸危险。受热分解产生有毒的氮氧化物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5334, 5442, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、经皮吸收', '有毒。急性中毒：吸入可引起呼吸道刺激症状，可发生化学性肺炎，肺水肿；误食后可引起急剧的胃肠道刺激症状，有恶心、呕吐、腹泻、腹痛、里急后重、全身乏力、肌肉疼痛和虚脱。对眼睛、皮肤和粘膜有刺激性。长期接触可引起慢性镉中毒，主要影响肾脏和骨骼。', '对水生生物有极高毒性。', '本品助燃、具刺激性。与有机物、还原剂及易燃物硫、磷等混和后，摩擦、撞击，有引起燃烧爆炸的危险。遇明火、高热可燃。受热分解产生有毒气体。与可燃物、还原剂、活性金属粉末、硫、磷等混合可形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5335, 5443, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。吸入有害，刺激和灼伤呼吸道。对眼和皮肤有刺激性，可致灼伤。对皮肤有致敏性。口服灼伤消化道。受热分解放出氮氧化物和铬烟雾。资料报道有致突变作用。为可疑致癌物。', '对环境有危害，对水体可造成污染。', '本品助燃、有毒、为可疑致癌物。跟可燃物质接触可能会引起火灾。与有机物、还原剂及易燃物硫、磷等混和后，摩擦、撞击，有引起燃烧爆炸的危险。遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5336, 5444, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '汞离子可使含巯基的酶丧失活性，失去功能；还能与酶中的氨基、二巯基、羧基、羟基以及细胞膜内的磷酰基结合，引起相应的损害。急性中毒：有头痛、头晕、乏力、失眠、多梦、口腔炎、发热等全身症状。可有食欲不振、恶心、腹痛、腹泻等。部分患者皮肤出现红色斑丘疹。', '对水生生物有极高毒性，对环境有严重危害。', '本品助燃，高毒。受热分解放出有毒的汞蒸气和氮氧化物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5337, 5445, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、皮肤接触、眼睛接触', '本品具有刺激性。对眼、呼吸道和皮肤有刺激性。吸入后引起气短、咳嗽等。口服引起腹痛、呕吐。长期接触可能引起钴中毒，表现为甲状腺功能异常、心肌病变等。', '该物质对环境可能有危害，在地下水中有蓄积作用。对水生生物有毒性。', '本品助燃，具刺激性。遇明火、高热可燃。受热分解产生有毒气体。与还原剂、有机物、易燃物或金属粉末等混合可形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5338, 5446, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、皮肤接触、眼睛接触', '本品具有刺激性。吸入、摄入或经皮肤吸收后对身体有害。受热分解产生有毒的氮氧化物气体，对呼吸道有刺激性。高浓度接触可引起头痛、头晕、恶心、呕吐等症状。对眼睛、皮肤和粘膜有刺激性。', '对环境可能有危害，对水体可造成污染。', '本品助燃，具刺激性。与硝基化合物和氯酸盐组成的混合物对震动和摩擦敏感并可能爆炸。受高热分解，产生有毒的氮氧化物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5339, 5447, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、皮肤接触、眼睛接触', '吸入、口服或经皮肤吸收后对身体有害。具有刺激性，可引起头痛、头晕、恶心、呕吐等症状。高浓度接触可引起麻醉作用。', '对水生生物有毒性，对环境有危害。', '受热或接触火焰可能会产生膨胀或爆炸性分解。具有强氧化性，与可燃物、还原剂等接触可能引起燃烧爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5340, 5448, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、皮肤接触、眼睛接触', '本品具有刺激性。口服引起剧烈腹痛、呕吐、血便、休克、全身抽搐、昏迷，甚至死亡。对皮肤和眼睛有强烈刺激性，甚至造成灼伤。皮肤反复接触引起皮肤干燥、皲裂和皮疹。大量摄入可引起高铁血红蛋白血症，出现紫绀、呼吸困难、虚脱，甚至死亡。', '该物质对环境可能有危害，在地下水中有蓄积作用。对水生生物有毒性。', '本品助燃，具刺激性。遇明火、高热可燃。受热分解产生有毒气体。与还原剂、有机物、易燃物或金属粉末等混合时有引起燃烧爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5341, 5449, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、经皮吸收', '有毒。人吸入镧及其化合物烟尘可出现头痛和恶心等症状。大鼠急性镧中毒的症状有立即排便、运动失调、呼吸困难，常因呼吸衰竭或心力衰竭而死亡。对眼睛、皮肤和粘膜有刺激性。长期接触可能对健康造成影响。', '对水生生物有害。', '本品助燃。跟可燃物质接触可能会引起火灾。与有机物、还原剂及易燃物硫、磷等混和后，摩擦、撞击，有引起燃烧爆炸的危险。遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5342, 5450, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、皮肤接触、眼睛接触', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期或反复接触可能引起器官损害。', '对水生生物有害。', '跟可燃物质接触可能会引起火灾。遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5343, 5451, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、皮肤接触、眼睛接触', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。接触后可引起恶心、呕吐、头痛、虚弱、无力和虚脱等。大量接触可引起高铁血红蛋白血症，影响血液的携氧能力，出现紫绀、头痛、头晕、虚脱，甚至死亡。', '对环境有危害，对水体可造成污染。', '强氧化剂。助燃。与可燃物、还原剂、有机物等混合能形成爆炸性混合物，遇明火、高热有燃烧爆炸危险。受热分解产生有毒的氮氧化物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5344, 5452, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。受热分解放出氮氧化物，对呼吸系统有刺激作用。', '对水生生物有害。', '强氧化剂，与可燃物、还原剂、有机物等接触可能引起燃烧或爆炸。受热分解产生有毒的氮氧化物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5345, 5453, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。本品粉尘对上呼吸道有刺激性，吸入后引起咳嗽和胸部不适。长期接触对皮肤有刺激性。', '对水生生物有害。', '本品助燃、具刺激性。与有机物、还原剂及易燃物硫、磷等混和后，摩擦、撞击，有引起燃烧爆炸的危险。遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5346, 5454, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入食入经皮吸收', '量口服出现腹痛、腹泻、呕吐、紫绀、血压下降、眩晕、惊厥和虚脱。', '无资料', '本品助燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5347, 5455, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激性。可引起呼吸道炎症和肺炎。', '对环境有危害，对水体可造成污染。', '强氧化剂。助燃。与可燃物、还原剂、有机物等混合能形成爆炸性混合物，遇明火、高热有燃烧爆炸危险。受热分解产生有毒的氮氧化物。具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5348, 5456, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、经皮吸收', '本品具有刺激性。对皮肤、粘膜有刺激性。大量口服中毒时，患者剧烈腹痛、呕吐、血便、休克、全身抽搐、昏迷，甚至死亡。受热分解产生有毒的氮氧化物气体，对呼吸道有刺激性。', '该物质对环境可能有危害，在地下水中有蓄积作用。', '本品助燃，具刺激性。遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5349, 5457, NULL, NULL, NULL, NULL, NULL, '第1类爆炸品', '吸入、食入、皮肤接触、眼睛接触', '本品具有刺激作用。吸入、摄入或经皮肤吸收后对身体有害。热解能放出有毒的氮氧化物气体，对呼吸道有刺激性。高浓度接触可引起头痛、头晕、恶心、呕吐等症状。对眼睛、皮肤和粘膜有刺激性。', '对环境可能有危害，对水体可造成污染。', '本品属爆炸品，易燃，具刺激性。受热、撞击、摩擦或与氧化剂接触有燃烧爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5350, 5458, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、经皮吸收', '有毒。刺激肠道，引起呕吐、腹泻。粉尘对眼有刺激性，水溶液可引起灼伤。皮肤接触可引起皮炎。慢性影响：有皮炎、哮喘、慢性支气管炎、慢性鼻炎等。对眼睛、皮肤和粘膜有刺激性。长期接触可引起镍过敏。', '对水生生物有毒。', '本品助燃、具刺激性。与有机物、还原剂及易燃物硫、磷等混和后，摩擦、撞击，有引起燃烧爆炸的危险。遇明火、高热可燃。受热分解产生有毒气体。与可燃物、还原剂、活性金属粉末、硫、磷等混合可形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5351, 5459, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、皮肤接触、眼睛接触', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。受热分解放出氮氧化物，对呼吸系统有刺激作用。高浓度接触可引起头痛、头晕、恶心、呼吸困难等症状。', '对水生生物有害。', '强氧化剂，与可燃物、还原剂、有机物等接触可能引起燃烧或爆炸。受热分解产生有毒的氮氧化物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5352, 5460, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、皮肤接触、眼睛接触', '本品具有刺激性。吸入、摄入或经皮肤吸收后对身体有害。受热分解产生有毒的氮氧化物气体，对呼吸道有刺激性。高浓度接触可引起头痛、头晕、恶心、呕吐等症状。对眼睛、皮肤和粘膜有刺激性。', '对环境可能有危害，对水体可造成污染。', '跟可燃物质接触可能会引起火灾。遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5353, 5461, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、经皮吸收', '短期大量接触，可发生急性铍痛。主要表现为急性化学性肺炎。肝脏往往肿大，有压痛，甚至出现黄疸。口服可溶性铍盐可引起胃粘膜出血坏死。进入眼内可致结膜炎，重者可致灼伤。长期接触小量铍可发生慢性铍病。除有无力、消瘦、食欲不振外，常有胸闷、胸痛、气短和咳嗽。X线检查分为三型：颗粒型、网织型和结节型。晚期可发生右心衰竭。皮肤病变有皮炎、溃疡及皮肤肉芽肿。', '该物质对环境有危害，在地下水中有蓄积作用。对水生生物有极高毒性。', '本品助燃，高毒，具刺激性。遇明火、高热可燃。受热分解产生有毒气体。与还原剂、有机物、易燃物或金属粉末等混合可形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5354, 5462, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、经皮吸收', '有毒。对眼睛、皮肤和粘膜有刺激性。长期接触可能对健康造成影响。', '对水生生物有害。', '跟可燃物质接触可能会引起火灾。与有机物、还原剂及易燃物硫、磷等混和后，摩擦、撞击，有引起燃烧爆炸的危险。遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5355, 5463, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、皮肤接触、眼睛接触', '铅及其化合物损害造血、神经、消化系统及肾脏。职业中毒主要为慢性。神经系统主要表现为神经衰弱综合征、周围神经病（以运动功能受累较明显），重者出现铅中毒性脑病。消化系统表现有齿龈铅线、食欲不振、恶心、腹胀、腹泻或便秘；腹绞痛见于较重病例。对皮肤和眼睛有刺激性。', '该物质对环境有危害，对水体可造成污染。在地下水中有蓄积作用。对水生生物有毒性。', '本品助燃，具刺激性。遇明火、高热可燃。受热分解产生有毒气体。与还原剂、有机物、易燃物或金属粉末等混合可形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5356, 5464, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、皮肤接触、眼睛接触', '本品具有强腐蚀性和毒性。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激性。吸入可引起喉炎、化学性肺炎和肺水肿。接触后可发生头痛、恶心、呕吐、咳嗽、气短等症状。皮肤接触可引起灼伤。眼睛接触可引起严重灼伤，甚至失明。误服可引起口腔、咽喉、食管和胃部灼伤，严重者可引起休克和死亡。', '对环境有危害，对水体可造成污染。', '本品不燃。受高热发生剧烈分解，甚至发生爆炸。具有强腐蚀性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5357, 5465, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。吸入本品粉尘，对鼻、喉及呼吸道有刺激性，引起咳嗽及胸部不适等。对眼有刺激性。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。迄今未见中毒的病例报告；工业生产中，也未见职业中毒报道。', '对水生生物有害。', '本品助燃、具刺激性。与有机物、还原剂及易燃物硫、磷等混和后，摩擦、撞击，有引起燃烧爆炸的危险。遇明火、高热可燃。受热分解产生有毒气体。与可燃物、还原剂、活性金属粉末、硫、磷等混合可形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5358, 5466, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、皮肤接触、眼睛接触', '本品具有刺激性。吸入、摄入或经皮肤吸收后对身体有害。受热分解产生有毒的氮氧化物气体，对呼吸道有刺激性。高浓度接触可引起头痛、头晕、恶心、呕吐等症状。对眼睛、皮肤和粘膜有刺激性。', '对环境可能有危害，对水体可造成污染。', '跟可燃物质接触可能会引起火灾。遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5359, 5467, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、皮肤接触、眼睛接触', '至今尚未见铈及其化合物职业性中毒的报告。但高浓度时对肝脏有毒性作用。对皮肤和眼睛有刺激性。', '该物质对环境可能有危害，在地下水中有蓄积作用。对水生生物有毒性。', '本品助燃，具刺激性。遇明火、高热可燃。受热分解产生有毒气体。与还原剂、有机物、易燃物或金属粉末等混合可形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5360, 5468, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、皮肤接触、眼睛接触', '目前，尚未见职业性中毒的病例报告。对皮肤和眼睛有刺激性。', '该物质对环境可能有危害，在地下水中有蓄积作用。对水生生物有毒性。', '本品助燃，具刺激性。遇明火、高热可燃。受热分解产生有毒气体。与还原剂、有机物、易燃物或金属粉末等混合可形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5361, 5469, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、经皮吸收', '有毒。对眼睛、皮肤和粘膜有刺激作用。吸入、摄入或经皮肤吸收后对身体有害。目前，未见职业性锶中毒的病例报道。', '对水生生物有害。', '本品助燃、具刺激性。与有机物、还原剂及易燃物硫、磷等混和后，摩擦、撞击，有引起燃烧爆炸的危险。遇明火、高热可燃。受热分解产生有毒气体。与可燃物、还原剂、活性金属粉末、硫、磷等混合可形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5362, 5470, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '急性中毒时，表现为胃肠炎、上行性神经麻痹、精神障碍。慢性中毒主要表现为多发性神经炎和脱发。对皮肤和眼睛有刺激性。', '该物质对环境有危害，对水生生物有极高毒性，在土壤中具有持久性，在生物体内有生物富集作用。', '本品助燃、高毒。遇明火、高热可燃。受热分解产生有毒气体。与还原剂、有机物、易燃物或金属粉末等混合可形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5363, 5471, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、皮肤接触、眼睛接触', '本品具有刺激性。大量铁在体内蓄积可引起胃痛、恶心、便秘等。可引起高铁血红蛋白血症，出现紫绀、呼吸困难、虚脱、惊厥，重者可致死。对皮肤和眼睛有刺激性。', '该物质对环境可能有危害，在地下水中有蓄积作用。对水生生物有毒性。', '本品助燃，具刺激性。遇明火、高热可燃。受热分解产生有毒气体。与还原剂、有机物、易燃物或金属粉末等混合时有引起燃烧爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5364, 5472, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、皮肤接触、眼睛接触', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤和粘膜有强刺激性。误服可引起急性胃肠炎。长期吸入其粉尘，可引起肺部纤维组织增生。皮肤接触可引起接触性皮炎。', '对水生生物有害。', '本品助燃、具有腐蚀性、强刺激性、可致人体灼伤。易于氧化物品接触发生剧烈反应，引起着火。浸没过硝酸铜酒精溶液的纸，干燥后会产生自燃现象。与硫磺、木炭或其他可燃性物混合后，摩擦、撞击，有引起燃烧爆炸的危险。遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5365, 5473, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、皮肤接触、眼睛接触', '吸入、摄入或经皮肤吸收后对身体有害。本品有腐蚀性。在高温下分解产生有刺激和剧毒的氮氧化物气体，吸入引起中毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对环境有危害，对水体可造成污染。', '强氧化剂。助燃。与可燃物、还原剂、有机物等混合能形成爆炸性混合物，遇明火、高热有燃烧爆炸危险。受热分解产生有毒的氮氧化物。具腐蚀性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5366, 5474, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '硝酸亚汞对眼睛、粘膜、呼吸道和皮肤有刺激作用。吸入、口服或经皮肤吸收后可能引起中毒死亡。', '对水生生物有极高毒性，对环境有严重危害。', '本品助燃，高毒，具刺激性。受热分解产生有毒的汞蒸气和氮氧化物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5367, 5475, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、皮肤接触、眼睛接触', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤和粘膜有刺激性。长期或反复接触可能引起皮肤过敏。', '对水生生物有毒性，对环境有危害。', '跟可燃物质接触可能会引起火灾。受热或接触火焰可能会产生膨胀或爆炸性分解。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5368, 5476, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '吸入本品后可引起头痛、呕吐和麻醉。可引起高铁血红蛋白血症。对皮肤、眼睛和粘膜有刺激性。', '对水生生物有毒性，对环境有危害。', '本品易燃。遇明火、高热极易燃烧爆炸。与还原剂能发生强烈反应。受热分解放出有毒的氧化氮烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5369, 5477, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入', '本品具有刺激性。吸入、摄入后对身体有害。在高温下能放出氮氧化物。目前，工业上未见有钇中毒的病例报告。只是一些动物实验资料。对眼睛、皮肤和粘膜有刺激性。', '对环境可能有危害，对水体可造成污染。', '本品助燃，具刺激性。遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5370, 5478, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '吸入、口服或经皮肤吸收后对身体有害。上呼吸道有刺激性。可引起头痛、头晕、恶心、呕吐等症状。', '对水生生物有毒性，对环境有危害。', '本品易燃，具刺激性。具有强氧化性。遇明火、高热会引起燃烧爆炸。与还原剂能发生强烈反应。受热分解放出有毒的氧化氮烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5371, 5479, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。高浓度接触可引起头痛、头晕、恶心、呼吸困难等症状。长期接触可能对心血管系统有影响。', '对水生生物有毒性，对环境有危害。', '易燃，其蒸气与空气混合，能形成爆炸性混合物。遇明火、高热极易燃烧爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5372, 5480, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。受热分解放出氮氧化物，对呼吸系统有刺激作用。', '对水生生物有害。', '强氧化剂，与可燃物、还原剂、有机物等接触可能引起燃烧或爆炸。受热分解产生有毒的氮氧化物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5373, 5481, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。受热分解放出氮氧化物，对呼吸系统有刺激作用。', '对水生生物有害。', '强氧化剂，与可燃物、还原剂、有机物等接触可能引起燃烧或爆炸。受热分解产生有毒的氮氧化物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5374, 5482, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、皮肤接触、眼睛接触', '吸入、摄入或经皮肤吸收后对身体有害。本品对眼睛、皮肤、粘膜和上呼吸道有刺激作用。目前尚未见铟及其化合物的职业中毒报道。', '对水生生物有害。', '本品助燃、具有刺激性。与有机物、还原剂及易燃物硫、磷等混和后，摩擦、撞击，有引起燃烧爆炸的危险。遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5375, 5483, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、经皮吸收', '误服硝酸银可引起剧烈腹痛、呕吐、血便，甚至发生胃肠道穿孔。可造成皮肤和眼灼伤。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期接触可引起银质沉着病。', '对环境有危害，对水体可造成污染。', '强氧化剂。与可燃物、还原剂、有机物等混合能形成爆炸性混合物，遇明火、高热有燃烧爆炸危险。受高热分解，产生有毒的氮氧化物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5376, 5484, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '具有刺激性；能引起高铁血红蛋白血症。吸入后出现头痛、恶心、低血压等症状。高浓度接触可引起麻醉作用。', '对水生生物有毒性，对环境有危害。', '本品易燃，具刺激性。具有强氧化性。遇明火、高热会引起燃烧爆炸。受热分解放出有毒的氧化氮烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5377, 5485, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '本品有毒。吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。受热分解出氮氧化物。', '对水生生物有毒性，对环境有危害。', '本品易燃，其蒸气与空气混合，能形成爆炸性混合物。遇高热、明火或氧化剂，有引起燃烧的危险。与路易氏酸（如三氟化硼、氯化铝等）发生爆炸性反应。受高热分解，放出有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5378, 5486, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '有报道人在接触可见肝、肾、脑的弥漫性病变，肺充血和水肿。吸入、口服或经皮肤吸收后对身体有害。具有刺激性，可引起头痛、头晕、恶心、呕吐等症状。高浓度接触可引起麻醉作用。', '对水生生物有毒性，对环境有危害。', '本品易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。受热分解放出有毒的氧化氮烟气。其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5379, 5487, NULL, NULL, NULL, NULL, NULL, '第1类爆炸品', '吸入、食入、皮肤接触、眼睛接触', '本品具有刺激性。吸入、摄入或经皮肤吸收后对身体有害。受热分解产生有毒的氮氧化物气体，对呼吸道有刺激性。高浓度接触可引起头痛、头晕、恶心、呕吐等症状。对眼睛、皮肤和粘膜有刺激性。', '对环境可能有危害，对水体可造成污染。', '通过打击、摩擦、火灾或其他着火源有极大爆炸危险。受热、撞击、摩擦或与氧化剂接触有燃烧爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5380, 5488, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '膜和上呼吸道有刺激作用。', '无资料', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5381, 5489, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入 食入 经皮吸收', '本品属低毒类。对眼睛、皮肤和粘膜有刺激作用。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5382, 5490, NULL, NULL, NULL, NULL, NULL, '第8.3类其它腐蚀品', '吸入 食入 经皮吸收\n有毒性。对皮肤、眼睛和粘膜有腐蚀性，可引起充血、疼痛、烧灼感、视力模糊。大量\n吸入其蒸气，会引起咳嗽、气短呼吸困难，严重者会引起肺水肿。误服会中毒。常与皮', '肤接触能使皮肤脱色。遇热分解放出高毒的酚烟雾。', '无资料', '本品可燃、具有腐蚀性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5383, 5491, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入 食入 经皮吸收', '具腐蚀性、刺激性。蒸气强烈刺激皮肤、眼睛和粘膜。受热分解释出氯气。', '无资料', '本品可燃、有毒，具有腐蚀性、强刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5384, 5492, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入经皮吸收', '对呼吸道、眼和皮肤有刺激性。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5385, 5493, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收', '有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '无资料', '本品可燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5386, 5494, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入 食入 经皮吸收\n吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤和粘膜有强烈的刺激作用。吸入，', '可引起喉、支气管痉挛、炎症，化学性肺炎、肺水肿等。', '无资料', '本品可燃、有毒、具有腐蚀性、强刺激性，可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5387, 5495, NULL, NULL, NULL, NULL, NULL, '第4.3类遇湿易燃物品；自热物质和混合物，类别1；遇水放出易燃气体的物质和混合物，类别1', '吸入、食入、皮肤接触、眼睛接触', '吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入本品可能对胃肠道造成刺激。长期或反复接触可能导致金属烟热。', '对水生生物有毒害作用，可能对水体环境造成长期不良影响。', '遇湿易燃，接触水、潮湿空气或酸类物质可能放出易燃的氢气，有燃烧爆炸危险。粉尘与空气形成爆炸性混合物，遇明火、高热或氧化剂接触有燃烧爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5388, 5496, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、经皮吸收', '对皮肤、粘膜有强烈刺激作用和腐蚀作用。吸入较低浓度，很快发生眼和呼吸道粘膜的刺激症状，并有头痛、眩晕、全身无力、胸部发紧、干咳、恶心和呕吐等症状；吸入高浓度时有剧咳、呼吸困难、哮喘。严重时可发生窒息、肺炎、肺水肿。可出现中枢神经系统症状。皮肤接触高浓度溴蒸气或液态溴可造成严重灼伤。长期吸入，除粘膜刺激症状外，还伴有神经衰弱综合征。', '对水生生物有毒性。对环境有危害，特别是对水体和土壤。', '本品助燃，具强腐蚀性、强刺激性，可致人体灼伤。和氢、甲烷、硫磺、锑、砷、磷、钠、钾及其它金属粉末剧烈反应，甚至引起燃烧爆炸。与还原剂能发生强烈反应。能腐蚀大多数金属及有机组织。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5389, 5497, NULL, NULL, NULL, NULL, NULL, '第3类易燃液体', '吸入、食入、经皮吸收', '吸入或雾对眼睛有刺激性。较长时间接触对皮肤有刺激性。口服引起恶心、呕吐、腹痛、腹泻、头痛、迟钝、中枢神经系统影响，甚至发生死亡。', '对水生生物有毒性。', '本品易燃，具刺激性。遇高热、明火及强氧化剂易引起燃烧。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5390, 5498, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、粘膜、呼吸道及皮肤有强烈刺激作用。吸入后可由于喉和支气管的痉挛、炎症及水肿，化学性肺炎或肺水肿而致死。', '对水生生物有害。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5391, 5499, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '对皮肤有刺激作用，可引起水疱、皮炎及荨麻疹。对眼睛、粘膜和上呼吸道有强烈刺激作用。吸入高浓度可引起眩晕、定向障碍、共济失调、麻醉作用、恶心或呕吐。', '对水生生物有毒性。对环境有危害，特别是对水体和土壤。', '本品易燃，有毒，具强刺激性，具强烈催泪性。遇明火易燃。受高热燃烧并分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5392, 5500, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有刺激作用。吸入后可引起头痛、头晕、恶心、呕吐、嗜睡等症状。', '对水生生物有毒性。对环境有危害，特别是对水体和土壤。', '本品易燃，具刺激性。遇明火、高热可燃。受热分解产生有毒的溴化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5393, 5501, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用和腐蚀作用。吸入可引起呼吸道刺激、咳嗽、呼吸困难，严重时可引起肺水肿。有催泪作用。皮肤接触可引起皮炎和荨麻疹。', '对水生生物有毒性。对环境有危害，特别是对水体。', '本品可燃，有毒，具刺激性，具催泪性。遇明火、高热可燃。受高热分解产生有毒的溴化物气体。与强氧化剂接触可发生化学反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5394, 5502, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、经皮吸收', '对眼睛、粘膜、呼吸道和皮肤有刺激作用，可引起烧灼伤。对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用和腐蚀作用。', '对水生生物有毒性。对环境有危害，特别是对水体和土壤。', '本品有毒、腐蚀性、刺激性。遇明火、高热易燃。受热或遇水分解放热，放出有毒的腐蚀性烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5395, 5503, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '急性中毒：病人有头痛、头晕、乏力、发热等全身症状，并有明显口腔炎表现。可有食欲不振、恶心、腹痛、腹泻等。部分患者出现全身性皮疹，少数严重者可发生间质性肺炎及肾损害。慢性中毒：主要表现为神经衰弱综合征，易兴奋症，震颤，口腔炎，牙龈炎，牙齿松动，脱发等。', '对水生生物有极高毒性。对环境有危害，特别是对水体和土壤。', '本品不燃、高毒。受高热分解，放出高毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5396, 5504, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有刺激作用。吸入可引起呼吸道刺激、咳嗽、呼吸困难。高浓度接触可引起头晕、头痛、恶心、呕吐等症状。', '对水生生物有毒性。对环境有危害，特别是对水体。', '本品易燃、具有刺激性。遇高热、明火或与氧化剂接触，有引起燃烧的危险。受高热分解产生有毒的溴化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5397, 5505, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用和腐蚀作用。吸入可引起呼吸道刺激、咳嗽、呼吸困难，严重时可引起肺水肿。高浓度接触可引起头晕、头痛、恶心、呕吐等症状。', '对水生生物有极高毒性。对水生环境可能会引起长期有害作用。', '遇明火、高热可燃。受热分解产生有毒的硒化物和溴化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5398, 5506, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '汞离子可使含巯基的酶丧失活性，失去功能；还能与酶中的氨基、二巯基、羧基、羟基以及细胞膜内的磷酰基结合，引起相应的损害。急性中毒：有头痛、头晕、乏力、失眠、多梦、口腔炎、发热等全身症状。可有食欲不振、恶心、腹痛、腹泻等。部分患者皮肤出现红色斑丘疹。慢性中毒：易兴奋症、震颤、口腔炎、肾损害等。', '对水生生物有极高毒性。对环境有危害，特别是对水体和土壤。', '本品不燃，有毒。受高热升华产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5399, 5507, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '铊及其化合物为强烈的神经毒，对肝肾有损害。急性中毒：表现有恶心、呕吐、腹部绞痛、厌食等症状，肢体及躯干有感觉、痛觉过敏；重者可发生中毒性脑病、中毒性神经病。脱发为其特征性表现。慢性中毒：主要表现为周围神经炎、脱发、指甲出现白色横纹（米氏线）、视力减退等。', '对水生生物有极高毒性。对环境有危害，特别是对水体和土壤。', '本品不燃，高毒。受高热分解产生有毒的溴化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5400, 5508, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、经皮吸收', '对眼睛、皮肤和粘膜有明显的刺激作用。吸入可引起呼吸道的明显危害。中毒表现有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用和腐蚀作用。', '对水生生物有毒性。对环境有危害，特别是对水体和土壤。', '本品具有腐蚀性。遇明火、高热易燃。受热或遇水分解放热，放出有毒的腐蚀性烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5401, 5509, NULL, NULL, NULL, NULL, NULL, '第2.3类有毒气体', '吸入、食入、经皮吸收', '主要损害中枢及周围神经系统；对皮肤、粘膜、肺、肾、肝、心血管等也有损害。以中枢神经系统和肺最早受到损害，也最为严重。急性中毒：轻度有头痛、头晕、恶心、全身无力、嗜睡、震颤、咳嗽、咯痰等；较重者出现兴奋、谵妄、共济失调、肌痉挛，并可伴有肺水肿、脑水肿、昏迷甚至死亡。慢性中毒：长期接触低浓度溴甲烷，可能对神经系统、肝脏、肾脏等造成慢性损害。', '对环境有危害，应特别注意对大气的污染。对臭氧层有破坏作用。', '本品易燃，有毒。与活性金属粉末（如镁、铝等）能发生反应，引起分解。与碱金属接触受冲击时会着火燃烧。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5402, 5510, NULL, NULL, NULL, NULL, NULL, '第2.2类不燃气体', '吸入', '对皮肤有刺激作用，其蒸气或对眼睛、粘膜和上呼吸道有刺激作用。有迅速的窒息作用。吸入高浓度的三氟溴甲烷可引起眩晕、定向障碍、共济失调、麻醉作用、恶心或呕吐。', '对水生生物有毒性。对环境有危害，特别是对大气和水体。', '本品具有刺激性。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5403, 5511, NULL, NULL, NULL, NULL, NULL, '第8类腐蚀品', '吸入、食入、皮肤接触、眼睛接触', '对皮肤、眼睛和呼吸道有强烈腐蚀性。吸入蒸气可引起呼吸道灼伤、肺水肿。食入可引起消化道灼伤、出血、休克。', '对水生生物有害。', '强氧化剂，与易燃物（如苯）和有机物质（如糖、纤维素等）接触会引起剧烈反应，甚至爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5404, 5512, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、皮肤接触、眼睛接触', '吸入后刺激上呼吸道。眼和皮肤接触有刺激性。口服引起腹痛、恶心、呕吐、腹泻、脉缓、面色苍白、紫绀、呼吸困难、流涎、惊厥、昏迷、胃肠出血、进行性肌麻痹、心律紊乱等。可致死。慢性影响：长期接触钡化合物的工人，可有无力、气促、流涎、口腔粘膜肿胀糜烂、鼻炎、结膜炎、腹泻、心动过速、血压增高、脱发等。', '对水生生物有害。', '强氧化剂，高毒，具刺激性。摩擦或受热易引起燃烧或爆炸。与硫酸接触容易发生爆炸。能与铝、砷、铜、碳、金属硫化物、有机物、磷、硒、硫剧烈反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5405, 5513, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、皮肤接触、眼睛接触', '高毒。误服能产生流涎、呕吐、腹痛、腹泻、窒息等症状。经常接触低浓度粉尘能损害肺部和肾脏，并使牙齿变黄。镉化合物损害造血、神经、消化系统及肾脏。职业中毒主要为慢性。神经系统主要表现为神经衰弱综合征、周围神经病(以运动功能受累较明显)，重者出现镉中毒性脑病。消化系统表现有齿龈铅线、食欲不振、恶心、腹胀、腹泻或便秘；腹绞痛见于中度及重度中毒。', '对环境有危害，对水体和土壤可造成污染。镉化合物在环境中不易降解，可长期残留。', '强氧化剂。与铵盐、金属粉末、可燃物、有机物或其它易氧化物形成爆炸性混合物，经摩擦或受热易引起燃烧或爆炸。与硫酸接触容易发生爆炸。能与铝、砷、铜、碳、金属硫化物、有机物、磷、硒、硫剧烈反应。具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5406, 5514, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、皮肤接触、眼睛接触', '本品助燃，具刺激性。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。误服可引起恶心、呕吐、腹痛、腹泻等消化道症状。长期接触可能对肾脏、肝脏造成损害。', '对水生生物有毒性。对环境有危害，特别是对水体。', '本品助燃，具刺激性。与还原剂、易燃或可燃物、活性金属粉末、硫、磷等物质接触有引起燃烧或爆炸的危险。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5407, 5515, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、皮肤接触、眼睛接触', '粉尘对眼睛和呼吸道有刺激作用。过量口服可引起上腹痛、呕吐、腹泻、烦渴、呼吸困难等症状。', '对环境有危害，对水体可造成污染。', '强氧化剂。与铵盐、金属粉末、可燃物、有机物或其它易氧化物形成爆炸性混合物，经摩擦或受热易引起燃烧或爆炸。与硫酸接触容易发生爆炸。能与铝、砷、铜、碳、金属硫化物、有机物、磷、硒、硫剧烈反应。具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5408, 5516, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、皮肤接触、眼睛接触', '粉尘对眼睛和呼吸道有刺激性。对皮肤有刺激性。', '对水生生物有害。', '强氧化剂，与易燃物、还原剂、有机物接触会引起剧烈反应，甚至爆炸。摩擦或受热易引起燃烧或爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5409, 5517, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入', '属剧毒类。铅及其化合物损害造血、神经、消化系统及肾脏。职业中毒主要为慢性。神经系统主要表现为神经衰弱综合征、周围神经病(以运动功能受累较明显)，重者出现铅中毒性脑病。消化系统表现有齿龈铅线、食欲不振、恶心、腹胀、腹泻或便秘；腹绞痛见于中度及重度中毒。', '对环境有危害，对水体和土壤可造成污染。', '强氧化剂。能与可燃物、有机物或易氧化物质形成爆炸性混合物，经摩擦和与少量水接触可导致燃烧或爆炸。高毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5410, 5518, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入', '粉尘对眼睛和呼吸道有刺激性。目前尚未见职业中毒报道。', '对环境有危害，对水体可造成污染。', '强氧化剂。与铵盐、金属粉末、可燃物、有机物或其它易氧化物形成爆炸性混合物，经摩擦或受热易引起燃烧或爆炸。与硫酸接触容易发生爆炸。能与铝、砷、铜、碳、金属硫化物、有机物、磷、硒、硫剧烈反应。具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5411, 5519, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入', '粉尘对眼睛和呼吸道有刺激性。口服刺激胃肠道，引起腹痛、恶心、呕吐等症状。', '对环境有危害，对水体可造成污染。', '强氧化剂。与铵盐、金属粉末、可燃物、有机物或其它易氧化物形成爆炸性混合物，经摩擦或受热易引起燃烧或爆炸。与硫酸接触容易发生爆炸。能与铝、砷、铜、碳、金属硫化物、有机物、磷、硒、硫剧烈反应。具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5412, 5520, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入', '粉尘对眼睛和呼吸道有刺激性。口服刺激胃肠道，引起腹痛，甚至有呕吐、剧烈胃痛、出血性胃炎的表现。', '对环境有危害，对水体可造成污染。', '强氧化剂。与铵盐、金属粉末、可燃物、有机物或其它易氧化物形成爆炸性混合物，经摩擦或受热易引起燃烧或爆炸。与硫酸接触容易发生爆炸。能与铝、砷、铜、碳、金属硫化物、有机物、磷、硒、硫剧烈反应。具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5413, 5521, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、经皮吸收', '对眼睛、呼吸道和皮肤有刺激作用。直接接触可引起灼伤。', '对水生生物有毒性。对环境有危害，特别是对水体和土壤。', '本品可燃，具腐蚀性、刺激性，可致人体灼伤。遇明火、高热可燃。受高热分解产生有毒的溴化物气体。与强氧化剂接触可发生化学反应。遇潮时对大多数金属有腐蚀性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5414, 5522, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '对眼睛、呼吸道粘膜有强烈的刺激作用，重者可引起肺水肿。对皮肤、粘膜有刺激作用和腐蚀作用。', '对水生生物有毒性。对环境有危害，特别是对水体和土壤。', '本品易燃，高毒，具强刺激性。遇明火、高热可燃。受高热分解产生有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5415, 5523, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '本品有毒。有腐蚀性。受高热放出有毒气体。对眼睛、皮肤、粘膜和上呼吸道有刺激作用和腐蚀作用。', '对水生生物有毒性。对环境有危害，特别是对水体和土壤。', '本品易燃，有毒，具腐蚀性，可致人体灼伤。遇明火易燃。受高热燃烧并分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5416, 5524, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '对眼睛、呼吸道粘膜有强烈的刺激作用，重者可引起肺水肿。', '对水生生物有毒性。对环境有危害，特别是对水体和土壤。', '本品易燃，高毒，具强刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。受高热分解产生有毒的溴化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5417, 5525, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤和粘膜有刺激作用。吸入后，可引起喉、支气管炎症、痉挛，化学性肺炎、肺水肿等。', '对水生生物有毒性。对环境有危害，特别是对水体和土壤。', '本品可燃、具有腐蚀性、刺激性、可致人体灼伤。遇明火、高热可燃。有腐蚀性。受高热分解，放出有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5418, 5526, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '本品有毒。有腐蚀性。受高热放出有毒气体。对眼睛、皮肤、粘膜和上呼吸道有刺激作用和腐蚀作用。', '对水生生物有毒性。对环境有危害，特别是对水体和土壤。', '本品可燃，有毒，具腐蚀性，可致人体灼伤。遇明火能燃烧。受高热分解产生有毒的溴化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5419, 5527, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '本品有毒。有腐蚀性。受高热能放出有毒气体。对眼睛、皮肤、粘膜和上呼吸道有刺激作用和腐蚀作用。', '对水生生物有毒性。对环境有危害，特别是对水体和土壤。', '本品可燃，有毒，具腐蚀性，可致人体灼伤。遇明火能燃烧。受高热分解产生有毒的溴化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5420, 5528, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入可引起呼吸困难、紫绀、虚脱，甚至呼吸麻痹。慢性中毒：表现有头痛、头晕、四肢乏力和麻木、身体沉重感。随病情发展，可有四肢无力加剧、肌力减退、行走困难、腱反射亢进。可发生语言障碍，眼球、手指震颤，流涎。', '对水生生物有毒性。对环境有危害，特别是对水体和土壤。', '本品极度易燃，有毒，具刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。受高热分解产生有毒的溴化物气体。受光照或火焰下易分解生成溴化氢和碳酰溴。与强氧化剂接触可发生化学反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5421, 5529, NULL, NULL, NULL, NULL, NULL, '第2.1类易燃气体', '吸入、食入、经皮吸收', '高浓度吸入可造成麻醉，甚至致死。对眼睛、皮肤有刺激性。对粘膜和上呼吸道有刺激作用。', '对水生生物有毒性。对环境有危害，特别是对大气和水体。', '本品易燃，具刺激性。燃烧或无抑制剂时可发生剧烈聚合。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5422, 5530, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。吸入可引起喉、支气管炎症、痉挛，化学性肺炎、肺水肿等。', '对水生生物有毒性。对环境有危害，特别是对水体和土壤。', '本品可燃、具有强刺激性。遇明火、高热可燃。受高热放出大量催泪性毒气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5423, 5531, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用和腐蚀作用。可引起眼睛、呼吸道炎症、痉挛，化学性肺炎，肺水肿等。', '对水生生物有毒性。对环境有危害，特别是对水体和土壤。', '本品可燃，有毒，具有腐蚀性、强刺激性、可致人体灼伤。与乙醇发生剧烈反应，释出具有刺激性、腐蚀性的溴化氢烟气。遇潮时对大多数金属有腐蚀性。受高热分解，放出有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5424, 5532, NULL, NULL, NULL, NULL, NULL, '第4.1类 易燃固体', '吸入 食入 经皮吸收', '对皮肤有强烈刺激性，使皮肤对光敏感。本品本身并未列入具有致癌作用的化合物，但其\n某些衍生物在动物实验中表现出致癌作用。', '无资料', '本品易燃、有毒、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5425, 5533, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期或反复接触可能对器官造成损害。吸入本品粉尘或烟雾可导致严重毒害作用，甚至可致命。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5426, 5534, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n高毒。误服或吸入会中毒，中毒症状有：呼气蒜臭味、恶心、呕吐、昏迷、呼吸困难、明', '显紫绀等。', '无资料', '本品不燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5427, 5535, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收', NULL, NULL, '本品不燃，具腐蚀性、刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5428, 5536, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入 食入 经皮吸收', '头痛、恶心和呕吐。', '无资料', '本品易燃、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5429, 5537, NULL, NULL, NULL, NULL, NULL, '第4.1类 易燃固体', '吸入 食入', '本品有毒。误服后能产生铅中毒症状。', '无资料', '本品易燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5430, 5538, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收\n如吸入、摄入或经皮肤吸收后对人体有害，对眼睛、粘膜、皮肤和上呼吸道有刺激作用。', '目前，未见生产性中毒报道。', '无资料', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5431, 5539, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入 食入 经皮吸收\n吸入、摄入或经皮肤吸收对身体有害，有强烈的刺激作用。高浓度亚磷酸三甲酯对眼睛、皮肤、', '粘膜和呼吸道有强烈的刺激作用。中毒表现有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心、\n呕吐、化学性肺炎。', '无资料', '本品易燃、有毒、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5432, 5540, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入 食入 经皮吸收', '蒸气或雾对眼、上呼吸道有刺激性。对皮肤有刺激性。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5433, 5541, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收\n对眼睛、皮肤、粘膜和呼吸道有强烈的刺激作用。吸入后可因喉、支气管的痉挛、水肿、炎症，\n化学性肺炎、肺水肿而致死。中毒表现有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕', '吐。', NULL, '本品不燃，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5434, 5542, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '对皮肤有刺激性。对眼睛有严重刺激性。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5435, 5543, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入 食入\n有毒。误服会中毒。蒸气刺激眼睛和粘膜。液体能腐蚀眼睛、皮肤和粘膜。受热分解放出', '氧化硫烟雾。', '无资料', '本品不燃、具有腐蚀性、刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5436, 5544, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '对皮肤有刺激性。对眼睛有严重刺激性。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5437, 5545, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '对皮肤有刺激性。对眼睛有严重刺激性。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5438, 5546, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入 食入\n对眼睛、皮肤和粘膜有腐蚀性。误服会中毒。有致敏作用。资料报道有致突变作用。能散', '发出有毒的二氧化硫气体。', '无资料', '本品不燃、具有腐蚀性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5439, 5547, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '对皮肤有刺激性。对眼睛有严重刺激性。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5440, 5548, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '刺激眼睛、皮肤和呼吸道。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5441, 5549, NULL, NULL, NULL, NULL, NULL, '侵入途径：', '跟可燃物质接触可能会引起火灾。吞食后有毒。跟皮肤接触有剧毒。对皮肤有刺激性。', NULL, '对水生物有剧毒。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5442, 5550, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有毒。吸入有毒。', '对水生物有剧毒,对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5443, 5551, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n砷及其化合物对体内酶蛋白的巯基有特殊亲和力。大量吸入砷化合物可致咳嗽、胸痛、呼吸困\n难、头痛、眩晕、全身衰弱、烦躁、痉挛和昏迷；可有消化道症状；重者可致死。摄入致急性\n胃肠炎、休克、周围神经病、贫血及中毒性肝病、心肌炎等。可因呼吸中枢麻痹而死亡。长期', NULL, NULL, '本品不燃，剧毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5444, 5552, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n对眼及上呼吸道有刺激性。引起结膜炎、鼻炎、喉炎和支气管炎。对皮肤有刺激和损害作用。\n口服引起口干、口腔刺激、吞咽困难、呕吐、腹痛、腹泻、四肢疼痛、头痛、惊厥、肌无力和', NULL, NULL, '本品不燃，高毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5445, 5553, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '性毒物砷化氢。皮肤接触可引起烧灼感、刺痒和色素改变。', NULL, '本品不燃，高毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5446, 5554, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入', '癌物。受热分解释放出砷和铅烟雾。', '无资料', '本品不燃、剧毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5447, 5555, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入\n吸入，主要引起呼吸道及神经系统症状，常有咳嗽、胸痛、呼吸困难、头痛、眩晕、全\n身衰弱等。重者出现呼吸中枢和血管舒缩中枢麻痹而死亡。误服后，主要表现为胃肠炎', '症状，严重者出现中枢神经系统症状，也可因呼吸中枢麻痹而死亡。属致癌物。', '无资料', '本品不燃、高毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5448, 5556, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有毒。吸入有毒。', '对水生物有毒，对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5449, 5557, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入\n吸入，主要引起呼吸道及神经系统症状，带有咳嗽、胸痛、呼吸困难、头痛、眩晕、全\n身衰弱等，重者出现呼吸中枢和血管舒缩中枢麻痹而死亡。误服后，主要表现为胃肠炎', '症状，严重者出现中枢神经系统症状，也可因呼吸中枢麻痹而死亡。属致癌物。', '无资料', '本品不燃、剧毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5450, 5558, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入\n吸入，主要引起呼吸道及神经系统症状，常有咳嗽、胸痛、呼吸困难、头痛、眩晕、全\n身衰弱等，重者出现呼吸中枢和血管舒缩中枢麻痹而死亡。误服后，主要表现为胃肠炎', '症状，严重者出现中枢神经系统症状，也可因呼吸中枢麻痹而死亡。属致癌物。', '无资料', '本品不燃、剧毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5451, 5559, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有毒。吸入有毒。', '对水生物有毒，对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5452, 5560, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期或反复接触可能对器官造成损害。可引起锑中毒，表现为胃肠道症状、心脏损害、皮肤损害等。', '对水生生物有剧毒，对水生环境可能会引起长期有害作用。', '本身不燃，但受热分解产生有毒气体。与还原剂、酸类、碱类等禁配物接触有火灾和爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5453, 5561, NULL, NULL, NULL, NULL, NULL, '侵入途径： 吸入，皮肤及眼睛接触', '吸入，皮肤及眼睛接触\n亚硒酸及其盐可渗入皮肤使人中毒；口服呈剧毒；无机硒化合物可造成皮炎；接触后呼吸', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5454, 5562, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '虚弱、恶心、呕吐、呼出气和皮肤有大蒜味等。皮肤接触后可引起皮炎。', '无资料', '本品不燃、高毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5455, 5563, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, '对水生物有剧毒,对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
