INSERT INTO `msds_hazard` VALUES (5465, 5573, NULL, NULL, NULL, NULL, NULL, '第5.1类 氧化剂', '吸入 食入 经皮吸收', '具刺激作用。误服可引起高铁血红蛋白症。受热分解释出氮氧化物和氨烟雾。', '无资料', '本品助燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5466, 5574, NULL, NULL, NULL, NULL, NULL, '第5.1类 氧化剂', '吸入 食入 经皮吸收', '部和皮肤有刺激作用。', '无资料', '本品助燃、剧毒、有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5467, 5575, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '无资料', '无资料。', '无资料', '本品助燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5468, 5576, NULL, NULL, NULL, NULL, NULL, '第2.1类 易燃气体', '吸入', '人接触本品后，初期症状有眩晕，后期为头痛、心悸等。', '无资料', '本品易燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5469, 5577, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入食入经皮吸收\n口服刺激口腔和胃肠道。大量口服可引起亚硝酸盐中毒，表现有紫绀、血压下降、呼吸困', '难、恶心、呕吐、头晕、腹痛、心率快、心律不齐、惊厥、昏迷，甚至死亡。吸入本品粉\n尘对呼吸道有刺激性；高浓度吸入的毒作用类似口服。本品对眼及皮肤有刺激性。', '无资料', '本品助燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5470, 5578, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入食入\n毒作用为麻痹血管运动中枢、呼吸中枢及周围血管；形成高铁血红蛋白。急性中毒表现为', NULL, '无资料', '本品助燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5471, 5579, NULL, NULL, NULL, NULL, NULL, '第5.1类 氧化剂', '吸入 食入\n加热分解放出有毒的氧化氮烟雾，吸入会中毒。', '皮炎或过敏性湿疹。', '无资料', '本品助燃、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5472, 5580, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, '跟可燃物质接触可能会引起火灾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5473, 5581, NULL, NULL, NULL, NULL, NULL, '第3.1类低闪点易燃液体', '吸入食入', '性中毒的特点为头痛、心动过速、高铁血红蛋白血症，可致死。', '无资料', '本品极度易燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5474, 5582, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入', '剂量可引起高铁血红蛋白血症。', '无资料', '本品易燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5475, 5583, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入', '剂量可引起高铁血红蛋白血症。', '无资料', '本品易燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5476, 5584, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入', '量吸入后，出现颜面潮红、搏动性头痛、心动过速、紫绀、软弱、躁动、昏厥、虚脱等。\n口服可在消化道破坏而失去作用。未见职业中毒的报道。', '无资料', '本品易燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5477, 5585, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入', '剂量可引起高铁血红蛋白血症。', '无资料', '本品易燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5478, 5586, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入', '剂量可引起高铁血红蛋白血症。', '无资料', '本品极度易燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5479, 5587, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入 食入\n接触后迅速引起皮肤潮红、搏动性头痛、头晕、血压下降、脉快。继续接触出现精神错乱、虚\n脱、休克。', '接触出现流泪、红肿、视力模糊。对皮肤有刺激性。慢性影响：贫血、皮肤过敏。长期接触可\n对其产生耐受性，如突然停止接触，可发生心绞痛。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5480, 5588, NULL, NULL, NULL, NULL, NULL, '第2.3类 有毒气体', '吸入 食入', '肿及出血。', '无资料', '本品不燃，高毒，具腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5481, 5589, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入', '对人皮肤有刺激作用，摄入可引起恶心和呕吐。', NULL, '本品可燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5482, 5590, NULL, NULL, NULL, NULL, NULL, '第2.2类不燃气体', '吸入\n常气压下无毒。高浓度时，使氧分压降低而发生窒息。氩浓度达50％以上，引起严重症状；\n75％以上时，可在数分钟内死亡。当空气中氩浓度增高时，先出现呼吸加速，注意力不', '集中，共济失调。继之，疲倦乏力、烦躁不安、恶心、呕吐、昏迷、抽搐，以至死亡。液\n态氩可致皮肤冻伤；眼部接触可引起炎症。', '无资料', '本品不燃，具窒息性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5483, 5591, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '剧毒。吞食后有剧毒。跟皮肤接触有剧毒。吸入有剧毒。对眼睛、皮肤、粘膜和呼吸道有强烈刺激性。高浓度接触可引起中枢神经系统症状，如头痛、头晕、恶心、呕吐、神志不清等。', '对水生生物有毒性。对环境有危害，对水体可造成污染。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5484, 5592, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '对人体有毒。受高热分解释出氮氧化物和氯化氢烟雾。具有高铁血红蛋白形成作用，吸入后可能导致紫绀。液体刺激眼睛。对皮肤无刺激性。长期暴露可能引起膀胱癌。', '对水生生物有毒性。对水生环境可能会引起长期有害作用。对环境有危害，对水体可造成污染。', '遇明火、高热可燃。其粉体与空气可形成爆炸性混合物，当达到一定浓度时，遇火星会发生爆炸。受高热分解放出有毒的气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5485, 5593, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '对皮肤有刺激性。对眼睛有严重刺激性。对呼吸道有刺激作用。吞咽有害。吸入有害。长期或反复接触可能对器官造成损害。', '对水生生物有毒性', '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5486, 5594, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '具有中等毒性。对眼睛、呼吸道和皮肤产生刺激和损伤。吸入或接触大量该化合物可能导致中毒症状，如头痛、恶心、呼吸困难和皮肤刺激。吞咽有害，吸入有害。', '对环境有危害，对水体可造成污染。', '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5487, 5595, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '对人体有毒。具有致癌性。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期接触可能引起膀胱癌。', '对水生生物有毒性。对水生环境可能会引起长期有害作用。对环境有危害，对水体可造成污染。', '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5488, 5596, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、食入或经皮吸收后对身体有害。对眼睛、皮肤和粘膜有强烈的腐蚀性和刺激性。可引起严重的眼部损伤、皮肤灼伤、呼吸道刺激。大量口服可致失明和死亡。慢性影响有中枢神经系统抑制作用。该物质可能致癌。', '对水生生物有剧毒，对水生环境可能会引起长期有害作用。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。', '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5489, 5597, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '有毒。对人体有刺激性。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生生物有毒，对水生环境可能会引起长期有害作用。', '加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5490, 5598, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收', '有毒。对人体有刺激性。实验表明，本品为可疑致癌物。', '无资料', '本品可燃、有毒、为可疑致癌物、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5491, 5599, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '对人体有毒。对动物有强致癌作用，对人为可疑致癌物。接触本品可引起皮炎。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对环境有危害，对水体可造成污染。', '本品可燃、有毒。一般不会燃烧，但长时间暴露在明火及高温下仍能燃烧。受高热分解放出有毒的气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5492, 5600, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吞食后有毒。跟皮肤接触有毒。对皮肤有刺激性。对眼睛有严重刺激性。吸入有毒。对呼吸道有刺激作用。能引起高铁血红蛋白血症，对肝、肾有损害。', '对水生生物有极高毒性，可能对水体环境产生长期不良影响。', '受热分解产生有毒的氯化氢、氮氧化物烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5493, 5601, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '对人体有毒。对动物有强致癌作用，对人为可疑致癌物。接触本品可引起皮炎。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。能引起高铁血红蛋白血症，对肝、肾有损害。', '对水生生物有极高毒性，可能对水体环境产生长期不良影响。', '受热分解产生有毒的氯化氢、氮氧化物烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5494, 5602, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '有毒。对眼睛、皮肤和粘膜有刺激作用。', '无资料', '本品可燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5495, 5603, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入、食入或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。可引起皮肤过敏反应。', '对环境可能有危害，对水体应给予特别注意。', '遇明火、高热可燃。受热分解产生有毒的氮氧化物和氯化氢烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5496, 5604, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入、食入或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。可引起高铁血红蛋白血症、紫绀、溶血性贫血。可引起皮肤过敏反应。', '对水生生物有剧毒。对环境可能有危害，对水体应给予特别注意。', '遇明火、高热可燃。受热分解产生有毒的氮氧化物和氯化氢烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5497, 5605, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收可能致死，对眼睛、粘膜、呼吸道及皮肤有刺激作用。可使机体缺氧而青紫(唇和皮肤呈蓝灰色)。中毒表现有头痛、眩晕、恶心。可引起高铁血红蛋白血症、溶血性贫血。', '对水生生物有剧毒。对环境可能有危害，对水体应给予特别注意。', '本品可燃、有毒、具有刺激性。遇明火、高热可燃。受热分解产生有毒的氮氧化物和氯化氢烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5498, 5606, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入、食入或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。可引起高铁血红蛋白血症、紫绀、溶血性贫血。可引起皮肤过敏反应。长期接触可引起肝、肾损害。', '对水生生物有剧毒。对环境可能有危害，对水体应给予特别注意。', '遇明火、高热可燃。受热分解产生有毒的氮氧化物和氯化氢烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5499, 5607, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入、食入或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。可引起高铁血红蛋白血症、紫绀、溶血性贫血。可引起皮肤过敏反应。', '对水生生物有剧毒，对水生环境可能会引起长期有害作用。', '遇明火、高热可燃。受热分解产生有毒的氮氧化物和氯化氢烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5500, 5608, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入、食入或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。可引起高铁血红蛋白血症、紫绀、溶血性贫血。可引起皮肤过敏反应。长期接触可引起肝、肾损害。', '对水生生物有剧毒。对环境可能有危害，对水体应给予特别注意。', '遇明火、高热可燃。受热分解产生有毒的氮氧化物和氯化氢烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5501, 5609, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入、食入或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。可引起高铁血红蛋白血症、紫绀、溶血性贫血。可引起皮肤过敏反应。长期接触可引起肝、肾损害。', '对水生生物有剧毒。对环境可能有危害，对水体应给予特别注意。', '遇明火、高热可燃。受热分解产生有毒的氮氧化物和氯化氢烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5502, 5610, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吞食后有剧毒。吸入有剧毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。可引起高铁血红蛋白血症、紫绀、溶血性贫血。长期接触可引起肝、肾损害。', '对水生生物有剧毒。对环境可能有危害，对水体应给予特别注意。', '遇明火、高热可燃。受热分解产生有毒的氮氧化物和氯化氢烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5503, 5611, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入、食入或经皮肤吸收对身体有害。症状有：恶心、呕吐、腹泻、肌肉乏力、疼痛、血压过低、心口痛、心动过速。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对环境可能有危害，对水体应给予特别注意。', '遇明火、高热可燃。受热分解产生有毒的氮氧化物和氯化氢烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5504, 5612, NULL, NULL, NULL, NULL, NULL, '第2.2类不燃气体', '吸入', '常压下，当氧的浓度超过40％时，有可能发生氧中毒。吸入40％～60％的氧时，出现胸骨后不适感、轻咳，进而胸闷、胸骨后烧灼感和呼吸困难，咳嗽加剧；严重时可发生肺水肿，甚至出现窒息。', '对环境无害。', '本品助燃。与易燃物、可燃物等形成有爆炸性的混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5505, 5613, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入', '急性中毒：经口中毒出现流涎、食道灼痛、胃痛、恶心、呕吐、腹泻、血压升高、痉挛、出冷汗、步态不稳、视力及言语模糊、呼吸困难、头晕、耳鸣，严重者可死亡。对眼睛、上呼吸道和皮肤有刺激作用。慢性影响：长期接触可能影响心血管系统和神经系统。', '对水生生物可能有害，钡化合物对环境有潜在毒性。', '本品不燃、高毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5506, 5614, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入 食入 经皮吸收', '吸入可引起咳嗽、喉炎及气短等呼吸道刺激症状。皮肤接触可引起刺激和过敏反应。食入可引起胃肠道刺激症状。', '对水生生物可能有害，避免进入水体。', '本品易燃、具有刺激性、致敏性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5507, 5615, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入、食入', '吸入高浓度可引起头痛、头晕、无力、恶心、呕吐、呼吸困难、呼吸蒜臭味、口内金属味等症状。严重时肝、肾受损。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5508, 5616, NULL, NULL, NULL, NULL, NULL, '第8.2类 碱性腐蚀品', '吸入，食入', '对皮肤、眼睛和呼吸道有强烈刺激性。可导致皮肤皲裂、指甲变形（匙甲）。食入可引起口腔、咽喉和胃肠道灼伤。', '对水生生物可能有害，遇水会放热，可能改变水体pH值。', '本品不燃，具腐蚀性、刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5509, 5617, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入', '对眼睛、皮肤、粘膜和上呼吸道有刺激作用。吸入，可引起化学性肺炎和肺水肿。误服，可引起急性胃肠刺激症状，有恶心、呕吐、腹痛、腹泻、全身疲乏、肌肉疼痛和虚脱等。', '对水生生物有剧毒。', '本品不燃、有毒、为致癌物、具有刺激性。与镁的混合物加热时可能发生爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5510, 5618, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '急性中毒：起病急，有头痛、头晕、乏力、失眠、多梦、发热等全身症状。明显的口腔炎及胃肠症状。部分患者出现全身性皮疹。重症者可发生化学性肺炎、肺水肿。慢性影响：主要是以易兴奋及汞性震颤为主的精神神经障碍和口腔炎的症候群。其蒸气可引起接触过敏性皮炎。', '对环境有危害，对水体和土壤可造成污染。', '本品不燃、剧毒。接触有机物有引起燃烧危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5511, 5619, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入 食入 经皮吸收', '吸入、摄入或经皮肤吸收后会中毒。对眼睛和皮肤有刺激作用。', '该物质对环境有危害，对水生生物可能有害并可能导致长期不良影响。', '本品易燃、为可疑致癌物、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5512, 5620, NULL, NULL, NULL, NULL, NULL, '第8.3类 其他腐蚀品', '吸入 食入 皮肤接触', '对皮肤、眼睛和呼吸道有强烈刺激性。吸入可引起呼吸道刺激、咳嗽和呼吸困难。食入可引起口腔、咽喉和胃肠道灼伤。皮肤接触可引起严重灼伤。', '对水生生物可能有害。', '与水剧烈反应产生氢气，可能引起火灾或爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5513, 5621, NULL, NULL, NULL, NULL, NULL, '第8.2类碱性腐蚀品', '吸入 食入', '对人体有强烈刺激性和腐蚀性。对眼睛、皮肤、粘膜能造成严重灼伤。接触后可引起头痛、恶心、呕吐、咳嗽、喉炎、气短等症状。', '对水生生物可能有害，遇水会放热，可能改变水体pH值。', '本品不燃、具有腐蚀性、强刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5514, 5622, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '误服或吸入粉尘会严重中毒。粉尘经伤口进入，使伤口久不愈合，急性中毒可发生支气管炎、支气管周围炎及支气管肺炎等。皮肤接触可有接触性皮炎和过敏性皮炎。慢性接触可引起肺内弥漫性肉芽肿性病变。铍及其化合物属致癌物。', '无资料', '本品不燃、高毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5515, 5623, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '属高毒类。误服，出现急性胃肠道刺激症状：腹痛、恶心、呕吐，几天后出现口唇及四肢无力、麻木、痛觉敏感，严重时有谵妄、精神失常、晕厥和呼吸肌麻痹；同时对心、肝、肾有损害。', '无资料', '本品不燃、高毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5516, 5624, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '高毒。误服或吸入会中毒。受高热会放出剧毒汞蒸气。急性中毒起病急，有头痛、头晕、乏力、低热等全身症状；明显的口腔炎及胃肠症状；部分患者出现全身性皮疹；重症者发生化学性肺炎。慢性影响主要是以易兴奋及汞性震颤为主的精神神经障碍和口腔炎的症候群。其蒸气可引起接触过敏性皮炎。', '对环境有危害，对水体和土壤可造成污染。', '本品不燃、高毒。受高热会放出剧毒汞蒸气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5517, 5625, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '为强烈的神经毒物，对肝、肾有损害作用。吸入、摄入可引起急性中毒。表现有恶心、呕吐、腹部纹痛、厌食等症状；肢体及躯干有感觉痛觉过敏现象；重症者可发生中毒性脑病。有时有脱发、周围神经炎等表现。', '对环境有危害，对水体和土壤可造成污染。', '本品不燃、剧毒。受高热、明火会产生剧毒的蒸气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5518, 5626, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化性物质', '吸入、食入、经皮吸收', '对眼睛、皮肤和呼吸道有刺激性。吞咽有害。', '对水生生物有毒。', '跟可燃物质接触可能会引起火灾。不燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5519, 5627, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入 经皮吸收', '吸入、口服或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜和呼吸道有强烈的刺激作用。吸入后可因喉、支气管的痉挛、水肿、炎症，化学性肺炎、肺水肿而致死。中毒表现有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '对水生生物有剧毒，可能对水体环境造成长期不利影响。', '本品助燃，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5520, 5628, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入', '对眼和上呼吸道粘膜有强烈的刺激性，重者可引起肺水肿。可致皮肤严重灼伤。', '对水生生物有剧毒，可能对水体环境造成长期不利影响。', '本品助燃，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5521, 5629, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、经皮吸收', '本品为强烈的起泡剂及糜烂性液体，易使皮肤受损发生灼伤；对粘膜有刺激作用；对人经皮吸收的致死量约为0.2ml。', '对水生生物有剧毒，可能对水体环境造成长期不利影响。', '本品不燃，高毒，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5522, 5630, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入', '重中毒，出现氰化物、汞的中毒表现。', '对水生生物有剧毒，可能对水体环境造成长期不利影响。', '本品可燃、剧毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5523, 5631, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后会中毒。对眼睛、粘膜和皮肤有强烈刺激作用。受热分解释出溴和氧化磷烟雾。', '对水生生物有毒性，可能对水生环境造成长期不利影响', '本品助燃、有毒、具有腐蚀性、强刺激性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5524, 5632, NULL, NULL, NULL, NULL, NULL, '侵入途径：', '对皮肤有刺激性。跟皮肤接触可能会引起敏化作用。对眼睛有严重刺激性。对呼吸道有', '刺激作用。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5525, 5633, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有剧毒。跟皮肤接触有剧毒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5526, 5634, NULL, NULL, NULL, NULL, NULL, '第2.1类 易燃气体', '吸入', '吸道灼伤。对眼和皮肤有强烈刺激和腐蚀性，可致严重灼伤。口服溶液可致口、咽、食\n道灼伤。', '无资料', '本品易燃，具强腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5527, 5635, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。本品有毒，对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用，具有强烈催泪性。吸入后可引起咳嗽、呼吸困难、头痛、头晕、恶心、呕吐等症状。皮肤接触可引起灼伤、红肿、疼痛。眼睛接触可引起严重刺激、流泪、视力模糊。吞食后可引起口腔、咽喉、胃肠道刺激，出现恶心、呕吐、腹痛等症状。长期或反复接触可能对肝、肾造成损害。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '一氯丙酮对水生生物有毒性。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。在水生生物中可能发生生物蓄积。', '本品易燃，有毒，具强烈催泪性。其蒸气与空气可形成爆炸性混合物，遇明火、高热能引起燃烧爆炸。与氧化剂接触发生反应。受热分解产生有毒的腐蚀性气体。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5528, 5636, NULL, NULL, NULL, NULL, NULL, '第2.2类 不燃气体', '吸入', '生肺炎、肺水肿，呼吸窘迫综合征，后期有纤维增生征象。可引起聚合物烟热。', '对大气臭氧层有极强破坏力。', '本品不燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5529, 5637, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '长期、反复、过量与皮肤接触引起皮肤发生痤疮样变且奇痒。接触或吸入该物质可能导致眼睛、皮肤和呼吸道刺激。', '对环境有害。', '本品可燃，有毒。受热分解放出氯烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5530, 5638, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入、食入、经皮吸收', '本品对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用和腐蚀性。受热分解放出氯和碘烟雾。', '对水生生物有毒。', '不燃，但具有强氧化性。接触有机物有引起燃烧危险。遇潮时对大多数金属有腐蚀性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5531, 5639, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入、食入、经皮吸收', '具有窒息性气味，对眼和上呼吸道粘膜有强烈的刺激性，并可致严重皮肤烧伤。少数严重者可引起肺水肿。', '对水生生物有毒。', '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5532, 5640, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '氟苯化合物多为麻醉剂，加入氟原子后麻醉作用不变，但细胞毒性加大，且影响卟啉代谢。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对环境有危害，对水体可造成污染。', '遇明火、高热可燃。受高热分解，放出有毒的氟化物和氯化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5533, 5641, NULL, NULL, NULL, NULL, NULL, '第2.2类 不燃气体', '吸入', '吸入高浓度本品，有可能引起心律不齐，昏迷甚至死亡。接触本品液体可致冻伤。', '对大气臭氧层有极强破坏力。', '本品不燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5534, 5642, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '本品有相当高的急性毒作用和强烈的皮肤刺激作用。实验动物可有血液血改变，支气管炎和肺\n炎。', '无资料', '本品可燃，有毒，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5535, 5643, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入、食入', '本品对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。', '对环境有害，危害水生环境急性危害类别1。', '本品不燃，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5536, 5644, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收对身体有害。蒸气或雾对眼、粘膜和上呼吸道有刺激性，对皮肤有刺激性。', '对水生生物有毒。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5537, 5645, NULL, NULL, NULL, NULL, NULL, '第2.3类有毒气体', '吸入', '咳嗽、咯泡沫痰、紫绀等。可并发气胸及纵隔气肿。肺水肿消退后两周左右可出现迟发\n性阻塞性细支气管炎。一氧化氮浓度高可致高铁血红蛋白血症。慢性影响：主要表现为\n神经衰弱综合征及慢性呼吸道炎症。个别病例出现肺纤维化。可引起牙齿酸蚀症。', NULL, '本品助燃，有毒，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5538, 5646, NULL, NULL, NULL, NULL, NULL, '第2.2类不燃气体', '吸入\n作为吸入麻醉剂在医药上应用了很久，但目前已少用。吸入', '中氧浓度很低时可引起窒息；吸入80％本品和氧气的混合物引起深麻醉，苏醒后一般无\n后遗作用。', NULL, '本品助燃，具麻醉性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5539, 5647, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、皮肤接触、眼睛接触', '铅及其化合物损害造血、神经、消化系统及肾脏。职业中毒主要为慢性。神经系统主要表现为神经衰弱综合征，周围神经病（以运动功能受累较明显），重者出现铅中毒性脑病。消化系统表现为腹绞痛、口腔金属味、齿龈铅线、食欲不振、恶心、呕吐、便秘。造血系统表现为低色素性贫血。肾脏损害主要表现为蛋白尿、管型尿、肾功能减退。女性可引起月经失调、流产。儿童对铅较成人敏感，可影响儿童生长发育。', '对水生生物有极高毒性，可能对水体环境产生长期不良影响。', '本品不燃，有毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5540, 5648, NULL, NULL, NULL, NULL, NULL, '第2.1类易燃气体', '吸入食入经皮吸收\n接触乙胺蒸气可产生眼部刺激、角膜损伤和上呼吸道刺激。液体溅入眼内，可致严重灼伤；', '皮肤接触可致灼伤。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5541, 5649, NULL, NULL, NULL, NULL, NULL, '无资料', '无资料', NULL, NULL, '本品易燃，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5542, 5650, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。本品为中枢神经系统抑制剂。首先引起兴奋，随后抑制。急性中毒：急性中毒多发生于口服。一般可分为兴奋、催眠、麻醉、窒息四阶段。患者进入第三或第四阶段，出现意识丧失、瞳孔扩大、呼吸不规律、休克、心力循环衰竭及呼吸停止。慢性影响：在生产中长期接触高浓度本品可引起鼻、眼、粘膜刺激症状，以及头痛、头晕、疲乏、易激动、震颤、恶心等。长期酗酒可引起多发性神经病、慢性胃炎、脂肪肝、肝硬化、心肌损害及器质性精神病等。皮肤长期接触可引起干燥、脱屑、皲裂和皮炎。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '乙醇对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。挥发后可参与形成光化学烟雾。', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5543, 5651, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, '在空气中容易发生自热反应,有引发火灾的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5544, 5652, NULL, NULL, NULL, NULL, NULL, '第8.2类 碱性腐蚀品', '吸入 食入', '肤及眼睛接触时会引起皮肤和眼结膜充血、疼痛、视力模糊、皮肤灼伤。', '无资料', '本品易燃、具有腐蚀性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5545, 5653, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入经皮吸收\n吸入', '迟钝、嗜睡。误服可致死。慢性中毒：神经衰弱综合征、大细胞性贫血、白细胞减少；严\n重者呈中毒性脑病和脑萎缩。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5546, 5654, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '无资料', '本品易燃，遇明火、高热能引起燃烧爆炸。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5547, 5655, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入经皮吸收', '使用本品除引起粘膜刺激和头痛外，未见急性中毒病例。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5548, 5656, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入', '本品对人的皮肤刺激作用不明显。眼刺激作用也不明显。未见职业中毒的资料。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5549, 5657, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入 食入 经皮吸收', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5550, 5658, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '无资料', '本品可燃，有毒，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5551, 5659, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '恶心和呕吐。', '无资料', '本品可燃，有毒，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5552, 5660, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', '喘息、喉炎、气短、头痛、恶心和呕吐。', '无资料', '本品可燃，有毒，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5553, 5661, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入 食入\n具有强烈的刺激性，可引起皮肤和粘膜的严重灼伤。少量吸入，引起食欲减退，以后出现咳嗽、', '呼吸困难、易疲劳、腹泻、呕吐、头痛、气喘、视力减退等。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5554, 5662, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, '对水生物有剧毒,对水生环境可能会引起长期有害作用。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5555, 5663, NULL, NULL, NULL, NULL, NULL, '皮肤腐蚀/刺激，类别1；眼损伤/眼刺激，类别1。', '吸入、食入、皮肤接触、眼睛接触\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', '造成严重皮肤灼伤和眼损伤。吸入可能引起呼吸道刺激。长期或反复接触可能对器官造成伤害。', '对水生生物有害。可能对水生环境产生长期有害影响。', '可燃液体。遇明火、高热可燃。遇水反应，放出有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5556, 5664, NULL, NULL, NULL, NULL, NULL, '第3.1类 低闪点易燃液体', '吸入 食入', '大量接触本品对眼睛、粘膜有刺激作用。对神经系统有影响。', '无资料', '本品易燃、刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5557, 5665, NULL, NULL, NULL, NULL, NULL, '第4.3类遇湿易燃物品', '吸入食入\n对眼、上呼吸道粘膜有强烈刺激作用。局部可出现充血、水肿，甚至溃疡、坏死。长时', '间高浓度接触，可引起鼻粘膜萎缩，支气管炎，肺充血和肺水肿。皮肤接触其液体，可\n发生皮炎和灼伤。', '无资料', '本品易燃，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5558, 5666, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入 食入 经皮吸收\n误服、与皮肤接触或吸入会严重中毒。强烈刺激粘膜，引起呼吸困难及支气管炎。在高\n浓度时，可能因出血性肺水肿及化脓性支气管炎而死亡。', '胂和光气，遇水或水蒸气会产生有毒和腐蚀性烟雾。', '无资料', '本品可燃、有毒、具有强刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5559, 5667, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入 食入\n无', '睡；极高浓度吸入可引起死亡。蒸气或液体对眼睛有刺激性。液体对皮肤有轻度刺激性；反复\n接触可致皮炎。摄入引起恶心和呕吐。', '无资料', '本品易燃、有毒、刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5560, 5668, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入 食入\n无', '至引起死亡。蒸气或液体对眼睛有刺激性。液体对皮肤有轻度刺激性；反复接触可致皮炎，摄\n入引起恶心和呕吐。', '无资料', '本品易燃、有毒、刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5561, 5669, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入 食入 经皮吸收', '痛、恶心和呕吐。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5562, 5670, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收', '本品的毒性作用主要为刺激性，高浓度时有麻醉作用，其气味可使人头痛、恶心。少数情\n况下产生严重的全身反应。皮肤接触可有干燥、皲裂、皮炎。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5563, 5671, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入经皮吸收', '化学性肺炎、肺水肿而致死。接触本品工人往往有眼痛、流泪、咳嗽、头痛、易激动、皮\n肤发痒。', '无资料', '本品易燃，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5564, 5672, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入 食入 经皮吸收', '无资料。', '无资料', '本品易燃', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5565, 5673, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入 食入', '对眼和皮肤有刺激性。对粘膜和上呼吸道有刺激作用。', '无资料', '本品易燃', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5566, 5674, NULL, NULL, NULL, NULL, NULL, '下：易燃液体 ，类别 2。', '吸入、食入、皮肤接触、眼睛接触\n吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入', NULL, '无资料', '高度易燃液体，其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5567, 5675, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '乙腈急性中毒发病较氢氰酸慢，可有数小时潜伏期。主要症状为衰弱、无力、面色灰白、恶心、呕吐、腹痛、腹泻、胸闷、胸痛；严重者呼吸及循环系统紊乱，呼吸浅、慢而不规则，血压下降，脉搏细而慢，体温下降，阵发性抽搐，昏迷。可有尿频、蛋白尿等。可因呼吸循环衰竭而死亡。皮肤接触可引起皮炎。', '对环境有危害，对水体可造成污染。', '本品易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂能发生强烈反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5568, 5676, NULL, NULL, NULL, NULL, NULL, '第3.1类 低闪点易燃液体', '吸入 食入 经皮吸收', '本品有麻醉作用。中毒者可发生呕吐、腹泻，尿中出现蛋白、管型及血尿。', '无资料', '本品易燃、刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5569, 5677, NULL, NULL, NULL, NULL, NULL, '第3.1类，低闪点易燃液体', '吸入食入经皮吸收', '易激动或抑郁、流涎、呕吐、食欲下降和多汗等。液体或高浓度蒸气对眼有刺激性。慢\n性影响：长期低浓度吸入，有头痛、头晕、疲倦、嗜睡、蛋白尿、红细胞增多症。长期\n皮肤接触，可发生皮肤干燥、皲裂。', '无资料', '本品极度易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5570, 5678, NULL, NULL, NULL, NULL, NULL, '第2.1类易燃气体', '吸入经皮吸收\n吸入高浓度乙硼烷出现胸闷、气短、干咳、心前区不适；可出现恶心、头痛、发热等症', NULL, '无资料', '本品易燃，剧毒。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5571, 5679, NULL, NULL, NULL, NULL, NULL, '第3.1类低闪点易燃液体', '吸入食入经皮吸收\n低浓度引起眼、鼻及上呼吸道刺激症状及支气管炎。高浓度吸入尚有麻醉作用。表现有\n头痛、嗜睡、神志不清及支气管炎、肺水肿、腹泻、蛋白尿肝和心肌脂肪性变。可致死。', '吸入、食入或经皮肤吸收后对身体有害。低浓度引起眼、鼻及上呼吸道刺激症状及支气管炎。高浓度吸入尚有麻醉作用。表现有头痛、嗜睡、神志不清及支气管炎、肺水肿、腹泻、蛋白尿肝和心肌脂肪性变。可致死。慢性影响：长期低浓度接触，可有类似慢性酒精中毒的表现。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '乙醛对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境有危害，应特别注意对水体的污染。挥发后可参与形成光化学烟雾。', '本品极度易燃，具刺激性，具致敏性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5572, 5680, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入 食入 经皮吸收', '吸入后对鼻、咽喉、肺部有刺激作用。皮肤和眼接触有刺激性。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5573, 5681, NULL, NULL, NULL, NULL, NULL, '第2.1类易燃气体', '吸入', '具有弱麻醉作用。高浓度吸入可引起单纯窒息。急性中毒：暴露于20%浓度时，出现明显缺氧症状；吸入高浓度，初期兴奋、多语、哭笑不安，后出现眩晕、头痛、恶心、呕吐、共济失调、嗜睡；严重者昏迷、紫绀、瞳孔对光反应消失、脉弱而不齐。当混有磷化氢、硫化氢时，毒性增大，应予以注意。', '该物质对环境可能有危害，对水体应给予特别注意。', '易燃，与空气混合能形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氟、氯等接触会发生剧烈的化学反应。与铜、银、汞等的化合物生成爆炸性物质。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5574, 5682, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入', '乙炔银分解时，放出刺激性的烟雾。', '无资料', '本品易燃', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5575, 5683, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。吸入后对鼻、喉和呼吸道有刺激性。对眼有强烈刺激作用。皮肤接触，轻者出现红斑，重者引起化学灼伤。误服浓乙酸，口腔和消化道可产生糜烂，重者可因休克而致死。慢性影响：眼睑水肿、结膜充血、慢性咽炎和支气管炎。长期反复接触，可致皮肤干燥、脱脂和皮炎。具腐蚀性、强刺激性，可致人体灼伤。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '乙酸对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境有危害，应特别注意对水体的污染。在水生生物中可能发生生物蓄积。', '本品易燃，具腐蚀性、强刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5576, 5684, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '摄入、吸入或经皮肤吸收后对身体有害。有刺激作用。其烟雾对眼睛、粘膜和上呼吸道有刺激作用。', '对水生生物有毒性。', '遇高热、明火或与氧化剂接触，有引起燃烧的危险。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5577, 5685, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入\n乙酸钡具有局部刺激和全身性毒作用。工业中毒少见，多由误服引起。误服后出现进行\n性肌麻痹、心律紊乱、血压降低等，可死于心律紊乱和呼吸肌麻痹。肾脏可能受损。大\n量吸入粉尘亦可引起中毒，但消化道反应较轻。长期接触可致钡尘肺、口腔炎、鼻炎、', '结膜炎、脱发等。', '无资料', '本品可燃', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5578, 5686, NULL, NULL, NULL, NULL, NULL, '侵入途径：', '吞食后有毒。跟皮肤接触有毒。跟皮肤接触可能会引起敏化作用。有严重损害眼睛的危', NULL, '对水生物有剧毒。', NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5579, 5687, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', NULL, '无资料', '本品可燃、高毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5580, 5688, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入 经皮吸收', NULL, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5581, 5689, NULL, NULL, NULL, NULL, NULL, '第8.1类 酸性腐蚀品', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。吸入后对呼吸道有刺激作用，引起咳嗽、胸痛、呼吸困难。蒸气对眼有刺激性。眼和皮肤直接接触液体可致灼伤。口服灼伤口腔和消化道，出现腹痛、恶心、呕吐和休克等。慢性影响：受本品蒸气慢性作用的工人，可有结膜炎、畏光、上呼吸道刺激等。具腐蚀性、刺激性，可致人体灼伤。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '乙酸酐对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境有危害，应特别注意对水体的污染。在水生生物中可能发生生物蓄积。', '本品易燃，具腐蚀性、刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5582, 5690, NULL, NULL, NULL, NULL, NULL, '第3类易燃液体', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激性。', '对水生生物有毒性，可能对水生环境造成长期不利影响。', '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5583, 5691, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入 食入 经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '无资料', '本品易燃、具刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5584, 5692, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收', NULL, '无资料', '本品可燃、高毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5585, 5693, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入经皮吸收\n具有麻醉和刺激作用。接触', '心悸、忧郁、中枢神经抑制。由其分解产生的甲醇可引起视力减退、视野缩小和视神经萎\n缩等。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5586, 5694, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '对皮肤有刺激性。对眼睛有严重刺激性。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5587, 5695, NULL, NULL, NULL, NULL, NULL, '第6。1类 毒害品', '吸入 食入 经皮吸收\n剧毒。吸入引起的急性中毒可发生支气管炎、支气管肺炎，使之发生呼吸困难，发绀等\n症状。皮肤接触可引起接触性皮炎和过敏性皮炎。若粉尘经伤口进入，使伤口久不愈合。', '长期接触粉尘引起慢性铍肺，其潜伏期长1-10年，甚至更长。属致癌物。', '无资料', '本品可燃、剧毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5588, 5696, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入 食入 经皮吸收\n损害造血、神经、消化系统及肾脏。职业中毒主要为慢性。神经系统主要表现为神经衰弱综合\n征、周围神经病(以运动功能受累较明显)，重者出现铅中毒性脑病。消化系统表现有齿龈铅线、', NULL, '无资料', '本品可燃、有毒、刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5589, 5697, NULL, NULL, NULL, NULL, NULL, '第3类易燃液体', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激性。热解的烟雾有刺激作用。', '对水生生物有毒性，可能对水生环境造成长期不利影响。', '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5590, 5698, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吞食后有剧毒。跟皮肤接触有剧毒。吸入有剧毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。可引起中枢神经系统损害、肝肾功能损害。', '对水生物有剧毒, 对水生环境可能会引起长期有害作用。', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5591, 5699, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吞食后有剧毒。跟皮肤接触有剧毒。吸入有剧毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期或反复接触可引起中枢神经系统、肝脏和肾脏损害。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。避免释放到环境中。', '遇明火、高热可燃。受热分解产生有毒的氧化锡烟雾。与氧化剂可发生反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5592, 5700, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '吸入、食入或经皮吸收后可出现头痛、头晕等症状。眼及皮肤接触有刺激性。皮肤长期反复接触可发生皮疹。', '对水生生物有毒性。在水环境中可能造成长期不良影响。', '易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂接触猛烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5593, 5701, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入 食入 经皮吸收', '高浓度吸入可发生肺水肿，出现严重的呼吸困难。对皮肤有刺激性。', '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5594, 5702, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '吸入、食入、经皮吸收均有毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。汞化合物可引起慢性中毒，主要损害神经系统、肾脏和消化系统。长期接触可引起汞中毒症状，如震颤、口腔炎、肾功能损害等。', '对水生生物有极高毒性，可能对水体环境造成长期不利影响。', '遇明火、高热可燃。受热分解产生有毒的汞蒸气和刺激性烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5595, 5703, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '粉尘能刺激眼睛、鼻，产生恶心，腹痛等症状。易经皮肤吸收。中毒多半是由误服引起，主要损害中枢神经系统、周围神经、胃肠道和肾脏。出现腿和躯干的异样感，腿无力，严重时可瘫痪，严重中毒病例可很快出现谵妄、惊厥和昏迷。此外，引起脱发、皮疹。', '对水生生物有极高毒性。对环境有危害，对水体可造成污染。', '遇明火、高热可燃。受热分解，放出有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5596, 5704, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收对身体有害。具有刺激性。中毒表现有头痛、恶心和呕吐。慢性影响：有可能引起生殖功能紊乱。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水生生物有毒性。对环境有危害，应特别注意对水体的污染。', '本品易燃，具刺激性。遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5597, 5705, NULL, NULL, NULL, NULL, NULL, '第3.2类易燃液体', '吸入、食入、皮肤接触、眼睛接触', '吸入、食入或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对水体有污染。', '易燃,其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5598, 5706, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入经皮吸收', '吸入、食入或经皮肤吸收后对身体有害。对眼、鼻、咽喉有刺激作用。高浓度吸入可引进行性麻醉作用，急性肺水肿，肝、肾损害。持续大量吸入，可致呼吸麻痹。误服者可产生恶心、呕吐、腹痛、腹泻等。有致敏作用，因血管神经障碍而致牙龈出血；可致湿疹样皮炎。慢性影响：长期接触本品有时可致角膜混浊、继发性贫血、白细胞增多等。接触后可能引起眼部不适、皮肤刺激和呼吸道刺激症状。本品可通过皮肤吸收。', '乙酸乙酯对水生生物可能有害。应避免进入水体、土壤和地下水。该物质对环境可能有危害，对水体应给予特别注意。挥发后可参与形成光化学烟雾。', '本品易燃，具刺激性，具致敏性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5599, 5707, NULL, NULL, NULL, NULL, NULL, '第3类易燃液体', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤有刺激作用，长时间接触可引起头痛、眩晕、恶心以及麻醉作用。', '对水生生物有毒性，可能对水生环境造成长期不利影响。', '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5600, 5708, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '蒸气对呼吸道有刺激性。吸入高浓度蒸气可出现头痛、头晕、恶心、呕吐及麻醉作用。对眼睛、皮肤有刺激作用。', '对水生生物有毒性，可能对水生环境造成长期不利影响。', '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5601, 5709, NULL, NULL, NULL, NULL, NULL, '第3类易燃液体', '吸入、食入、经皮吸收', '蒸气对眼及上呼吸道有刺激性。高浓度吸入有麻醉作用，引起头痛、头晕、恶心、呕吐等。大量口服引起头痛、恶心、呕吐，甚至发生昏迷。皮肤较长时间接触有刺激性。', '对水生生物有毒性，可能对水生环境造成长期不利影响。', '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5602, 5710, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入经皮吸收\n蒸气对眼及上呼吸道粘膜有刺激性。有麻醉作用。接触后出现咳嗽、胸闷、疲乏、眼烧', '灼感。高浓度时，则有头晕、发烧感、脉速、心悸、头痛、耳鸣、震颤、恶心、食欲丧失。\n可引起皮肤干燥、皮炎、湿疹。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5603, 5711, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入经皮吸收\n对眼和上呼吸道粘膜有刺激作用。吸入高浓度时，感恶心、眼部灼热感、胸闷、疲乏无力，', '并可引起麻醉。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5604, 5712, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入经皮吸收\n对眼及上呼吸道均有强烈的刺激作用，有麻醉作用。吸入高浓度', '嗽、胸闷、气短等，严重者出现心血管和神经系统的症状。可引起结膜炎、角膜炎，角膜\n上皮有空泡形成。皮肤接触可引起皮肤干燥。', '无资料', '本品易燃，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5605, 5713, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入 食入 经皮吸收', NULL, '无资料', '本品易燃、刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5606, 5714, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '对眼及上呼吸道粘膜有刺激作用，可引起结膜炎、鼻炎、咽喉炎等，重者伴有头痛、嗜睡、胸闷、心悸、食欲不振、恶心、呕吐等症状。皮肤长期接触可致皮炎或湿疹。有的可发生贫血和嗜酸性粒细胞增多。', '对水生生物有毒作用。', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5607, 5715, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收对身体有害。其蒸气或雾对眼睛、皮肤、粘膜和上呼吸道有刺激作用。接触后可引起头痛、头晕、恶心、呕吐、嗜睡等症状。高浓度接触可引起麻醉作用。', '对水生生物有害。该物质对环境可能有危害，对水体应给予特别注意。', '易燃，其蒸气与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。与氧化剂能发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5608, 5716, NULL, NULL, NULL, NULL, NULL, '第2.1类易燃气体', '吸入\n高浓度时，有单纯性窒息作用。空气中浓度大于6％时，出现眩晕、轻度恶心、麻醉症状；', '达40％以上时，可引起惊厥，甚至窒息死亡。', '无资料', '本品易燃，具窒息性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5609, 5717, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入 食入 经皮吸收\n吸入、摄入或经皮吸收对身体有害。蒸气或雾对眼、粘膜、上呼吸道有刺激性。接触后引起烧', '灼感、咳嗽、喘息、喉炎、气短、头痛、恶心、呕吐。', '无资料', '本品易燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5610, 5718, NULL, NULL, NULL, NULL, NULL, '第2.1类易燃气体', '吸入\n具有较强的麻醉作用。急性中毒：吸入高浓度乙烯可立即引起意识丧失，无明显的兴奋期，\n但吸入新鲜空气后，可很快苏醒。对眼及呼吸道粘膜有轻微刺激性。液态乙烯可致皮肤', '冻伤。慢性影响：长期接触，可引起头昏、全身不适、乏力、思维不集中。个别人有胃肠\n道功能紊乱。', NULL, '本品易燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5611, 5719, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有剧毒。跟皮肤接触有剧毒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5612, 5720, NULL, NULL, NULL, NULL, NULL, '第2.1类 易燃气体', '吸入\n急性中毒的表现：头痛、眩晕、腿无力、颌关节痛、出汗、咽喉干燥，有时有恶心、呕吐及', '腹泻。长时间接触后，可发生神经衰弱综合征，低血压等。', '无资料', '本品易燃', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5613, 5721, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, '易燃,其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5614, 5722, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入 食入\n吸入后引起头痛、头昏、恶心和共济失调。大量吸入可能致死。对眼有刺激性，摄入对机体', NULL, '无资料', '本品易燃、具刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5615, 5723, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤有刺激性。', '无资料', '遇明火、高热可燃。受热分解产生有毒的氮氧化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5616, 5724, NULL, NULL, NULL, NULL, NULL, '第5.2类有机过氧化物', '吸入、食入、皮肤接触、眼睛接触', '吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入该物质可能会引起对健康有害的影响或呼吸道不适。皮肤接触可能引起刺激。眼睛接触可能引起严重刺激。', '无资料', '受热、撞击或摩擦可能发生爆炸。与还原剂、有机物、酸类、碱类等发生剧烈反应。遇火源可能发生爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5617, 5725, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '蒸气对眼和呼吸道有剧烈的刺激作用，有眼灼痛、头痛、窒息感，伴咳嗽、胸痛、眼结膜充血、流泪、流涕，肺部有干湿罗音。严重者引起肺水肿。吸入后到产生症状前有短暂的潜伏期。高浓度与皮肤接触，可引起皮炎或溃疡；眼接触可致角膜化学性灼伤。长期较高浓度接触可能发生肺硬化。', '无资料', '本品易燃，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5618, 5726, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入经皮吸收', '本品对上呼吸道有刺激性，吸入后引起咳嗽、胸痛。口服引起口腔及消化道灼伤。', '无资料', '本品易燃，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5619, 5727, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吞食后有剧毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。长期接触可能引起慢性中毒。', '对水生生物有剧毒。', '遇明火、高热可燃。受热分解产生有毒的氮氧化物和硫氧化物烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5620, 5728, NULL, NULL, NULL, NULL, NULL, '第6.1类 毒害品', '吸入、食入、经皮吸收', '在水中起水解或受空气中碳酸气的作用，生成亚砷酸，对皮肤及粘膜有刺激性，能引起皮炎、结膜炎等。剧毒。吸入或误服会中毒。', '无资料', '本品可燃、高毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5621, 5729, NULL, NULL, NULL, NULL, NULL, '无资料', '吸入 食入', '对眼睛、皮肤、粘膜有刺激作用。', '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5622, 5730, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、食入、经皮吸收有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对环境可能有危害，对水体应给予特别注意', '遇明火、高热可燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5623, 5731, NULL, NULL, NULL, NULL, NULL, '易燃液体（类别3）', '吸入、食入、经皮吸收', '对皮肤有刺激作用，吸入、摄入或经皮肤吸收后可能对身体有害。其烟雾对眼睛、粘膜和上呼吸道有刺激作用。', '该物质对环境可能有危害，对水体应给予特别注意。', '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5624, 5732, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '急性中毒表现与苯、甲苯相似，但麻醉作用出现较慢而持久。表现有粘膜刺激症状以及头晕、头痛、恶心、呕吐、步态蹒跚等。严重中毒可发生昏迷、抽搐等。本品对造血系统影响不明显。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5625, 5733, NULL, NULL, NULL, NULL, NULL, '第3.1类低闪点易燃液体', '吸入、食入、经皮吸收', '吸入后，引起嗅觉丧失、肌无力、惊厥、呼吸麻痹。口服引起恶心、呕吐。对眼和皮肤有刺激性。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品极度易燃、具有刺激性。遇火源引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5626, 5734, NULL, NULL, NULL, NULL, NULL, '第3.1类低闪点易燃液体', '吸入、食入、经皮吸收', '蒸气或雾对眼睛、粘膜、皮肤和上呼吸道有刺激性。接触后能引起恶心、头痛、呕吐和麻醉作用。皮肤反复接触，可引起接触性皮炎。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品极度易燃，具刺激性。在空气中久置后能生成有爆炸性的过氧化物。在火场中，受热的容器有爆炸危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5627, 5735, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '吸入、食入或经皮肤吸收对身体有害。蒸气或雾对眼、粘膜和上呼吸道有刺激性。接触后可引起头痛、头晕、恶心、呕吐、咳嗽、胸闷、呼吸困难等症状。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃、有毒、具有刺激性。能发生聚合反应，出现大量放热现象，引起容器破裂和爆炸事故。流速过快，容易产生和积聚静电。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5628, 5736, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后会中毒。对眼、皮肤、粘膜和上呼吸道有刺激性。大鼠吸入后，出现嗜睡、共济失调和呼吸困难。可引起头痛、头晕、恶心、呕吐、腹痛等症状。长期接触可影响神经系统功能。', '该物质对环境有危害，应特别注意对水体的污染。对水生生物有毒。', '本品可燃、有毒。遇明火、高热可燃。受热分解产生有毒的氧化磷、氧化硫等气体。其蒸气与空气可形成爆炸性混合物。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5629, 5737, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '对呼吸道有刺激性，吸入后引起咳嗽、胸痛；可引起肺水肿。心脏抑制和引起惊厥作用。口服引起恶心、流涎。对眼有强烈刺激性，引起角膜水肿。对皮肤有强烈的刺激性。', '对水生生物可能有毒性。该物质对环境有危害，应特别注意对水体的污染。', '本品易燃，具强刺激性。其蒸气与空气形成爆炸性混合物，遇明火、高热极易燃烧爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5630, 5738, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入 食入 经皮吸收', '本品有毒。有刺激和麻醉作用。受热分解释出有腐蚀性的烟雾。', '无资料', '本品易燃、有毒、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5631, 5739, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, NULL, NULL, '高度易燃,其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5632, 5740, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入 食入 经皮吸收', NULL, '无资料', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5633, 5741, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '抑制呼吸酶。急性中毒出现眩晕、恶心、步态不稳、呕吐、血压升高、脉速、意识丧失、呼吸困难、强直性痉挛、紫绀，以致呼吸抑制。对粘膜和皮肤刺激较弱。', '对水生生物可能有毒性。该物质对环境有危害，应特别注意对水体的污染。', '本品易燃。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5634, 5742, NULL, NULL, NULL, NULL, NULL, '第3.1类低闪点易燃液体', '吸入、食入、经皮吸收', '低浓度对眼、鼻和呼吸道有轻微刺激；高浓度吸入有麻醉作用。脱离接触后，迅速恢复正常。有致敏性。', '该物质对环境可能有危害，建议不要让其进入环境。', '本品极度易燃，具刺激性，具致敏性。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5635, 5743, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用。吸入后可引起喉、支气管的炎症、痉挛、水肿，化学性肺炎、肺水肿而致死。接触后引起烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心、呕吐。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃，具腐蚀性、强刺激性，可致人体灼伤。遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5636, 5744, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '本品对粘膜、上呼吸道、眼和皮肤有强烈的刺激性。接触后引起烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心、呕吐。高浓度接触可引起化学性肺炎或肺水肿而致死。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃，具强刺激性。遇明火、高热能引起燃烧。遇低级醇和水起化学反应而分解。具有腐蚀性。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5637, 5745, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有刺激性。高浓度接触可引起麻醉作用。吸入后可引起头痛、头晕、恶心、嗜睡等。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃，具刺激性。遇高热、明火及强氧化剂易引起燃烧。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5638, 5746, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有刺激性。吸入后可引起头痛、头晕、恶心、呕吐、嗜睡等。高浓度接触可引起麻醉作用。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃，具刺激性。遇高热、明火及强氧化剂易引起燃烧。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5639, 5747, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '吸入该物质可能会引起对健康有害的影响或呼吸道不适。对眼睛、皮肤、粘膜和上呼吸道有刺激性。高浓度蒸气可能引起头痛、头晕、恶心、呕吐、嗜睡等不适症状。误服可引起消化道刺激症状。', '该物质对环境可能有危害，应特别注意对水体的污染。', '高度易燃液体，其蒸气与空气混合，能形成爆炸性混合物。遇明火、高热可燃。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5640, 5748, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有刺激性。高浓度接触可引起麻醉作用。吸入后可引起头痛、头晕、恶心、嗜睡等。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃，具刺激性。遇高热、明火及强氧化剂易引起燃烧。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5641, 5749, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '本品在高浓度时有刺激和麻醉作用。对眼睛、皮肤、粘膜和上呼吸道有刺激性。吸入后可引起头痛、头晕、恶心、嗜睡等。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃，具刺激性。遇高热、明火及强氧化剂易引起燃烧。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5642, 5750, NULL, NULL, NULL, NULL, NULL, '第2.1类易燃气体', '吸入', '具有弱刺激和麻醉作用。急性中毒：主要表现为头痛、头晕、嗜睡、恶心、酒醉状态，严重者可出现昏迷。慢性影响：出现头痛、头晕、睡眠不佳、易疲倦。', '对水生生物可能有毒性。该物质对环境有危害，应特别注意对水体的污染。', '本品易燃。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5643, 5751, NULL, NULL, NULL, NULL, NULL, '第2.1类易燃气体', '吸入\n主要作用是窒息、弱麻醉和弱刺激。急性中毒：出现粘膜刺激症状、嗜睡、血压稍升高，', '有时脉速。高浓度中毒可引起昏迷。慢性影响：长期接触异丁烯，工人有头痛、头晕、\n嗜睡或失眠、易兴奋、易疲倦、全身乏力、记忆力减退。有时有粘膜刺激症状。', NULL, '本品易燃，具窒息性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5644, 5752, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用。吸入后可引起喉、支气管的炎症、痉挛、水肿，化学性肺炎、肺水肿。接触后可引起烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃、具有强刺激性。遇明火、高热易燃。与氧化剂能发生强烈反应。遇水反应发热放出有毒的腐蚀性气体。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5645, 5753, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。蒸气或烟雾对眼睛、粘膜和上呼吸道有强烈刺激作用。皮肤接触可引起灼伤。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品可燃、具有强刺激性。遇明火、高热可燃。遇水、潮气、触媒和高热易发生聚合。受高热分解，放出有毒的烟气。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5646, 5754, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有刺激性。高浓度接触可引起麻醉作用。吸入后可引起头痛、头晕、恶心、嗜睡等。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃，具刺激性。遇高热、明火及强氧化剂易引起燃烧。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5647, 5755, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '本品对皮肤有刺激作用。雾对眼睛、粘膜和上呼吸道有刺激作用。吸入、摄入或经皮肤吸收对身体有害。', '对环境有危害，对水体应给予特别注意。', '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5648, 5756, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收对身体有害。蒸气或雾对眼睛、粘膜和上呼吸道有刺激性。高浓度蒸气可引起头痛、头晕、恶心、麻醉作用。', '该物质对环境可能有危害，对水体应给予特别注意。', '高度易燃，其蒸气与空气混合，能形成爆炸性混合物。液体和蒸气易燃。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。蒸气可能会移动到着火源并回闪。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5649, 5757, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '属中等毒类。对眼、皮肤、粘膜和上呼吸道有刺激性。吸入后可引起喉和支气管的炎症、痉挛、水肿，化学性肺炎或肺水肿。接触后可出现烧灼感、头痛、头晕、咳嗽、气短、恶心、呕吐等。皮肤接触可引起灼伤、红肿、疼痛。眼睛接触可导致严重眼部损伤。食入可引起恶心、呕吐、腹痛。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品可燃、有毒、具刺激性。遇明火、高热可燃。与强氧化剂可发生反应。受高热分解。接触酸及酸气时，能放出有毒的氰化物及氧化硫烟气。其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。受热分解，放出高毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5650, 5758, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤接触、眼睛接触', '吸入本品对呼吸道有强烈刺激性，可引起肺水肿。对眼和皮肤有刺激性，可引起灼伤。口服刺激和灼伤口腔和消化道。皮肤接触可引起灼伤、红肿、疼痛。眼睛接触可导致严重眼部损伤。食入可引起恶心、呕吐、腹痛。具有致敏性，可引起皮肤过敏反应。慢性影响：肝、肾损害。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品可燃、有毒、具强刺激性。遇明火、高热可燃。受高热或与酸接触会产生剧毒的氰化物气体。其蒸气与空气可形成爆炸性混合物。其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。受热分解，放出高毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5651, 5759, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后会中毒。对眼、皮肤、粘膜和上呼吸道有刺激性。对呼吸道有刺激性，引起鼻炎、咽喉炎、支气管炎等。接触后可出现烧灼感、头痛、头晕、咳嗽、气短、恶心、呕吐等。皮肤接触可引起灼伤、红肿、疼痛。眼睛接触可导致严重眼部损伤。食入可引起恶心、呕吐、腹痛。具有致敏性，可引起皮肤过敏反应。', '该物质对环境有危害，应特别注意对水体的污染。', '本品易燃、有毒、具刺激性、具致敏性。遇明火、高热易燃。受高热或与酸接触会产生剧毒的氰化物气体。其蒸气与空气可形成爆炸性混合物。其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。受热分解，放出高毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5652, 5760, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后会中毒。对眼、皮肤、粘膜和上呼吸道有刺激性。吸入后可引起喉和支气管的痉挛、炎症、水肿，化学性肺炎、肺水肿，严重者可致死。接触后可出现烧灼感、头痛、头晕、咳嗽、气短、恶心、呕吐等。皮肤接触可引起灼伤、红肿、疼痛。眼睛接触可导致严重眼部损伤。食入可引起恶心、呕吐、腹痛。', '该物质对环境有危害，应特别注意对水体的污染。', '本品易燃、有毒、具强刺激性。遇明火、高热易燃。受高热或与酸接触会产生剧毒的氰化物气体。其蒸气与空气可形成爆炸性混合物。其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。受热分解，放出高毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5653, 5761, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '蒸气或雾对眼、粘膜和上呼吸道有刺激性。对皮肤有刺激性。吸入、摄入或经皮肤吸收对身体有害。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品可燃、有毒、具有刺激性。遇明火、高热可燃。与强氧化剂可发生反应。受高热分解放出有毒的气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5654, 5762, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤及眼睛接触', '吸入后会影响健康；对眼睛、皮肤、粘膜和上呼吸道有强烈刺激性。可能引起呼吸道刺激、咳嗽、呼吸困难。皮肤接触可引起灼伤、红肿、疼痛。眼睛接触可导致严重眼部损伤。食入可引起恶心、呕吐、腹痛。长期或反复接触可能引起过敏反应。', '该物质对环境可能有危害，对水体应给予特别注意。', '遇明火、高热可燃。受热分解释放出有毒的氮氧化物和氯化物气体。与水、醇、胺类等反应剧烈，产生二氧化碳和相应的胺类化合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5655, 5763, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入本品后对呼吸道有强烈刺激性，可引起肺水肿。对眼和皮肤有刺激性，可引起灼伤。口服刺激和灼伤口腔和消化道。皮肤接触可引起灼伤、红肿、疼痛。眼睛接触可导致严重眼部损伤。食入可引起恶心、呕吐、腹痛。吸入可能导致过敏或哮喘症状或呼吸困难，可能导致皮肤过敏反应。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃、有毒、具强刺激性。其蒸气与空气可形成爆炸性混合物。遇明火、高热能引起燃烧爆炸。加热至沸点以上时即分解释出有毒的亚硝酸蒸气。与酸类、胺类、醇、碱类和水发生强烈反应，有引起燃烧爆炸的危险。遇水或水蒸气分解放出有毒的气体。其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。受热分解，放出高毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5656, 5764, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '对皮肤有刺激性。对眼睛有严重刺激性。对呼吸道有刺激作用。吸入、摄入或经皮肤吸收后会中毒。可引起呼吸道刺激、咳嗽、呼吸困难。皮肤接触可引起灼伤、红肿、疼痛。眼睛接触可导致严重眼部损伤。食入可引起恶心、呕吐、腹痛。长期或反复接触可能引起过敏反应。', '该物质对环境可能有危害，对水体应给予特别注意。', '遇明火能燃烧。遇潮湿、水或水蒸气会分解释放出有毒气体。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。与水、醇、胺类等反应剧烈，产生二氧化碳和相应的胺类化合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5657, 5765, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '对皮肤有刺激性。对眼睛有严重刺激性。对呼吸道有刺激作用。吸入、摄入或经皮肤吸收后会中毒。可引起呼吸道刺激、咳嗽、呼吸困难。皮肤接触可引起灼伤、红肿、疼痛。眼睛接触可导致严重眼部损伤。食入可引起恶心、呕吐、腹痛。长期或反复接触可能引起过敏反应。', '该物质对环境可能有危害，对水体应给予特别注意。', '遇明火、高热可燃。受热分解，放出高毒的烟气。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。与水、醇、胺类等反应剧烈，产生二氧化碳和相应的胺类化合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5658, 5766, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后会中毒。刺激作用较强，人在0.66mg/m3浓度下暴露1min即可感到刺激作用，而毒性较异氰酸酯的一氯衍生物低。对眼睛、皮肤、粘膜和上呼吸道有刺激性。可引起呼吸道刺激、咳嗽、呼吸困难。皮肤接触可引起灼伤、红肿、疼痛。眼睛接触可导致严重眼部损伤。食入可引起恶心、呕吐、腹痛。长期或反复接触可能引起过敏反应。', '该物质对环境可能有危害，对水体应给予特别注意。', '遇明火、高热可燃。受高热分解，放出高毒的烟气。与水、醇、胺类等反应剧烈，产生二氧化碳和相应的胺类化合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5659, 5767, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '有毒。吸入、摄入或经皮肤吸收后会中毒。强烈刺激和腐蚀皮肤、眼睛和粘膜。可引起过敏反应。接触后，出现烧灼感、头痛、头晕、咳嗽、气短、恶心、呕吐等，长时间接触，可引起哮喘。皮肤接触可引起灼伤、红肿、疼痛。眼睛接触可导致严重眼部损伤。食入可引起恶心、呕吐、腹痛。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃、有毒、具有刺激性。受高热分解，放出高毒的烟气，有爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。与水、醇、胺类等反应剧烈，产生二氧化碳和相应的胺类化合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5660, 5768, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体，第6.1类毒害品', '吸入、食入、经皮吸收', '吸入低浓度可引起严重的肺水肿而致死。蒸气对眼有强烈的刺激性，引起流泪、角膜上皮水肿、角膜云翳。液态对皮肤有强烈的刺激性。口服刺激胃肠道。高浓度吸入可因支气管和喉的炎症、痉挛、化学性肺炎或肺水肿而死亡。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃、剧毒、具强刺激性。遇明火、高热易燃。与氧化剂能发生强烈反应。受热分解放出有毒的气体。遇水或水蒸气反应放出有毒和易燃的气体。在火场中，受热的容器有爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5661, 5769, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后会中毒。高浓度时对眼睛、皮肤、粘膜和上呼吸道有强烈刺激性。可引起呼吸道刺激、咳嗽、呼吸困难。皮肤接触可引起灼伤、红肿、疼痛。眼睛接触可导致严重眼部损伤。食入可引起恶心、呕吐、腹痛。长期或反复接触可能引起过敏反应。', '该物质对环境可能有危害，对水体应给予特别注意。', '遇高热、明火或氧化剂，有引起燃烧的危险。受高热分解，放出高毒的烟气。与水、醇、胺类等反应剧烈，产生二氧化碳和相应的胺类化合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5662, 5770, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、皮肤及眼睛接触', '吸入、摄入或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激性。可能引起呼吸道刺激、咳嗽、呼吸困难。皮肤接触可引起灼伤、红肿、疼痛。眼睛接触可导致严重眼部损伤。食入可引起恶心、呕吐、腹痛。长期或反复接触可能引起过敏反应。', '该物质对环境可能有危害，对水体应给予特别注意。', '遇高热、明火或与氧化剂接触，有引起燃烧的危险。受热分解产生有毒的氮氧化物和氰化氢气体。与水、醇、胺类等反应剧烈，产生二氧化碳和相应的胺类化合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5663, 5771, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品，第3类易燃液体', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后会中毒。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。可引起过敏反应。长时间接触，引起头痛、头晕、咳嗽、胸痛及肺水肿等。皮肤接触可引起灼伤、红肿、疼痛。眼睛接触可导致严重眼部损伤。食入可引起恶心、呕吐、腹痛。长期或反复接触可能引起过敏反应。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃、有毒、具有强刺激性、致敏性。遇明火、高热易燃。其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。受热分解，放出高毒的烟气。与水、醇、胺类等反应剧烈，产生二氧化碳和相应的胺类化合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5664, 5772, NULL, NULL, NULL, NULL, NULL, '第3.1类低闪点易燃液体', '吸入、食入、经皮吸收', '本品对呼吸道有刺激性，高浓度吸入可致肺水肿甚至死亡。对眼及皮肤有刺激性。可引起呼吸道刺激、咳嗽、呼吸困难。皮肤接触可引起灼伤、红肿、疼痛。眼睛接触可导致严重眼部损伤。食入可引起恶心、呕吐、腹痛。长期或反复接触可能引起过敏反应。', '该物质对环境可能有危害，对水体应给予特别注意。', '遇明火、高热易燃。与强氧化剂可发生反应。遇水或水蒸气反应放出有毒的或易燃的气体。若遇高热可发生剧烈分解，引起容器破裂或爆炸事故。与水、醇、胺类等反应剧烈，产生二氧化碳和相应的胺类化合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5665, 5773, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体，第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后会中毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。有致敏作用，可引起哮喘。长时间接触，能引起头痛、头晕、恶心、肺水肿及胸痛等。皮肤接触可引起灼伤、红肿、疼痛。眼睛接触可导致严重眼部损伤。食入可引起恶心、呕吐、腹痛。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃、有毒、具有刺激性、致敏性。比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。受热分解，放出高毒的烟气。与水、醇、胺类等反应剧烈，产生二氧化碳和相应的胺类化合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5666, 5774, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点液体，第6.1类毒害品', '吸入、食入、经皮吸收', '接触会刺激眼睛、皮肤、鼻腔、口腔、咽喉，产生类似气喘状肺部过敏。吸入、摄入或经皮肤吸收后会中毒。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。可引起过敏反应。长时间接触，引起头痛、头晕、咳嗽、胸痛及肺水肿等。皮肤接触可引起灼伤、红肿、疼痛。眼睛接触可导致严重眼部损伤。食入可引起恶心、呕吐、腹痛。', '该物质对环境可能有危害，对水体应给予特别注意。', '易燃，并伴生毒气，容器在火中爆炸。其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。受热分解，放出高毒的烟气。与水、醇、胺类等反应剧烈，产生二氧化碳和相应的胺类化合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5667, 5775, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体，第6.1类毒害品', '吸入、食入、经皮吸收', '蒸气或雾对眼、粘膜和呼吸道有刺激性。吸入后可因喉和支气管的炎症、痉挛和水肿，化学性肺炎或肺水肿而死亡。目前尚无对呼吸道致敏的报道。长时间接触本品有强烈的刺激性或造成灼伤。皮肤接触可引起灼伤、红肿、疼痛。眼睛接触可导致严重眼部损伤。食入可引起恶心、呕吐、腹痛。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃、有毒、具有刺激性。遇高热可发生剧烈分解，引起容器破裂或爆炸事故。其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。受热分解，放出高毒的烟气。与水、醇、胺类等反应剧烈，产生二氧化碳和相应的胺类化合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5668, 5776, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体，第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后会中毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。有致敏作用，可引起哮喘。长时间接触，引起头痛、头晕、恶心、胸痛，甚至发生肺水肿而死亡。皮肤接触可引起灼伤、红肿、疼痛。眼睛接触可导致严重眼部损伤。食入可引起恶心、呕吐、腹痛。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃、有毒、具有刺激性、致敏性。遇高热可发生剧烈分解，引起容器破裂或爆炸事故。其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。受热分解，放出高毒的烟气。与水、醇、胺类等反应剧烈，产生二氧化碳和相应的胺类化合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5669, 5777, NULL, NULL, NULL, NULL, NULL, '第4.1类易燃固体', '吸入、食入、皮肤接触、眼睛接触', '吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入后可能引起头痛、头晕、面部潮红、恶心、呕吐等。还可能导致体位性低血压，引起心悸、乏力等不适。对眼睛、皮肤和呼吸道有刺激性。', '该物质对环境可能有危害，对水体应给予特别注意。', '遇火或摩擦极易引燃，其粉体与空气混合，能形成爆炸性混合物。加热时，容器可能爆炸。暴露于火中的容器可能会通过压力安全阀泄漏出内容物。受热或接触火焰可能会产生膨胀或爆炸性分解。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5670, 5778, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收对身体有害。蒸气或雾对眼睛、粘膜和上呼吸道有刺激性。', '该物质对环境可能有危害，对水体应给予特别注意。', '其蒸气与空气形成爆炸性混合物，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。若遇高热，容器内压增大，有开裂和爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5671, 5779, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '接触低浓度蒸气时表现有眼及上呼吸道刺激症状，高浓度可致角膜水肿、溃疡、喉头声带水肿和支气管肺炎。神经系统受损时表现为意识障碍、瞳孔散大、视力模糊、四肢肌无力。对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用。吸入后可引起喉、支气管的炎症、痉挛、水肿，化学性肺炎、肺水肿。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃，具腐蚀性、刺激性，可致人体灼伤。遇明火、高热能引起燃烧爆炸。与氧化剂发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5672, 5780, NULL, NULL, NULL, NULL, NULL, '第8类腐蚀品', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有强烈刺激性。接触可引起灼伤。吸入可引起呼吸道刺激、咳嗽、呼吸困难。', '该物质对环境可能有危害，对水体应给予特别注意。', '遇水、潮气、酸类发生剧烈反应，放出易燃气体。遇明火、高热有燃烧爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5673, 5781, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '抑制呼吸酶。急性中毒出现眩晕、恶心、步态不稳、呕吐、血压升高、脉速、意识丧失、呼吸困难、强直性痉挛、紫绀，以致呼吸抑制。对粘膜和皮肤刺激较弱。兔皮下注射，最低致死量为43.4mg/kg，出现呼吸兴奋和痉挛性麻痹。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃，有毒。遇明火、高热易引起燃烧。受热分解产生有毒的氰化氢和氮氧化物气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5674, 5782, NULL, NULL, NULL, NULL, NULL, '第3.2类 中闪点易燃液体', '吸入、食入、经皮吸收', '吸入、误服本品能引起中毒。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。受热分解释出具有腐蚀性的烟雾。', '该物质对环境可能有危害，对水体应给予特别注意。', '易燃，遇明火、高热有燃烧爆炸危险。与氧化剂能发生强烈反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5675, 5783, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有刺激性。吸入后可引起喉、支气管的炎症、痉挛、水肿，化学性肺炎、肺水肿。接触后可引起头痛、头晕、恶心、呕吐等。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃，具刺激性。遇明火、高热能引起燃烧爆炸。与氧化剂发生强烈反应。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5676, 5784, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有刺激性。吸入后可引起喉、支气管的炎症、痉挛、水肿，化学性肺炎、肺水肿。接触后可引起头痛、头晕、恶心、呕吐等。', '该物质对环境可能有危害，对水体应给予特别注意。', '易燃，其蒸气与空气混合，能形成爆炸性混合物。遇明火、高热能引起燃烧爆炸。与氧化剂发生强烈反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5677, 5785, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、经皮吸收', '蒸气与液体能刺激眼睛、皮肤和呼吸系统，可引起灼伤。吸入可发生喉和支气管的痉挛、炎症和水肿，化学性肺炎和肺水肿。接触后可引起头痛、恶心、呕吐、咳嗽、眩晕、气短等。对眼睛、皮肤、粘膜和上呼吸道有强烈的腐蚀性和刺激性。', '该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃、有毒、具有腐蚀性、刺激性、可致人体灼伤。遇明火、高热易引起燃烧。受热分解产生有毒的氯化氢和光气气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5678, 5786, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '吸入蒸气可能引起瞌睡和头昏眼花，可能伴随嗜睡、警惕性下降、反射作用消失、失去协调性并感到眩晕。高浓度可引起麻醉作用。对眼、皮肤、粘膜和上呼吸道有刺激性。属低毒类，毒性略大于正辛烷。空气中最高容许浓度500ppm。', '该物质对环境有危害，应特别注意对水体的污染。对水生生物有毒，可以在水生环境中造成长期不利影响。', '高度易燃液体，其蒸气与空气混合，能形成爆炸性混合物。遇明火、高热易燃。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。如果遇强氧化剂，也会引起燃烧爆炸。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5679, 5787, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '本品有刺激性，高浓度时有麻醉作用。对眼、皮肤、粘膜和上呼吸道有刺激性。接触后可引起头痛、头晕、恶心、呕吐等症状。高浓度吸入可引起意识丧失。', '该物质对环境有危害，应特别注意对水体的污染。', '本品易燃、具刺激性。遇明火、高热易燃。若遇高热，可发生聚合反应，放出大量热量而引起容器破裂和爆炸事故。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5680, 5788, NULL, NULL, NULL, NULL, NULL, '第8.3类其它腐蚀品', '吸入 食入 经皮吸收', '吸入、摄入或经皮肤吸收后会中毒。具腐蚀性。资料报道有致突变作用。', '无资料', '本品可燃、具有腐蚀性、可致人体灼伤', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5681, 5789, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吞食后有毒。跟皮肤接触有毒。对眼睛有严重刺激性。吸入有毒。对呼吸道有刺激作用。本品有中枢神经系统损害，并具有明显刺激性，对眼、呼吸道、皮肤、消化道均可造成化学性灼伤。轻者表现为头痛、头晕、恶心、呕吐等症状。', '对水生生物有剧毒，对水生环境可能会引起长期有害作用。', '遇高热、明火或与氧化剂接触，有引起燃烧的危险。受热分解产生有毒的氮氧化物和氰化氢气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5682, 5790, NULL, NULL, NULL, NULL, NULL, '一般化学品', '吸入、食入、皮肤接触、眼睛接触', '工业上广泛使用未见有危害。对眼睛、皮肤、粘膜和上呼吸道有轻微刺激作用。大量摄入可能引起胃肠道不适。', '对水生生物可能有轻微毒性。避免释放到环境中。', '遇高热、明火或与氧化剂接触，有引起燃烧的危险。受热分解产生一氧化碳和二氧化碳。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5683, 5791, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '固体吞食后有剧毒。跟皮肤接触有剧毒。吸入有剧毒。汞化合物具有蓄积性，长期接触可引起慢性中毒，主要损害神经系统、肾脏和肝脏。急性中毒表现为头痛、头晕、乏力、恶心、呕吐、腹痛、口腔炎、牙龈炎、震颤等。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。对环境有严重危害，特别是对水体。', '遇高热、明火或与氧化剂接触，有引起燃烧的危险。受热分解产生有毒气体。爆炸性分解。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5684, 5792, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点液体', '吸入、食入、皮肤接触、眼睛接触', '吸入该物质可能会引起对健康有害的影响或呼吸道不适。意外食入该物质可能会引起对健康有害的影响或呼吸道不适。皮肤接触可能引起刺激。眼睛接触可能引起严重刺激。', '对水生生物有害。', '遇明火、高热易燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5685, 5793, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。避免眼睛接触，因其极易水解放出甲醇，甲醇可致眼睛失明。', '对水生生物有害。', '遇明火、高热易燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5686, 5794, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点液体', '吸入、食入、皮肤接触、眼睛接触', '口服可引起呼吸困难及软弱。对皮肤无刺激性。对眼睛、粘膜和上呼吸道有刺激作用。', '对水生生物有害。', '遇明火、高热易燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5687, 5795, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '吸入、摄入或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用。本品易水解产生甲醇，甲醇可致失明。', '对水生生物有害。', '遇明火、高热易燃。受热分解产生有毒气体。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5688, 5796, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有刺激性。接触后可出现头痛、头晕、恶心、呕吐等症状。皮肤接触可引起刺激、红肿、疼痛、变应性皮炎。眼睛接触可导致严重眼部损伤、结膜炎。食入可引起恶心、呕吐、腹痛。有机锡中毒的主要临床表现有：眼和鼻黏膜的刺激症状；中毒性神经衰弱综合征；重症出现中毒性脑病。对水生生物有剧毒，对水生环境可能会引起长期有害作用。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。该物质对环境可能有危害，对水体应给予特别注意。避免排放到周围环境中。', '遇高热、明火或与氧化剂接触，有引起燃烧的危险。受热分解产生有毒的烟气。爆炸性分解。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5689, 5797, NULL, NULL, NULL, NULL, NULL, '一般化学品', '吸入、食入', '在工业生产中未发现不良作用，未查见职业中毒资料。热解可释放出有腐蚀性和刺激性的烟雾。对皮肤、眼睛可能有轻微刺激性。', '该物质对环境可能有危害，对水体应给予特别注意。避免排放到周围环境中。', '遇高热、明火或与氧化剂接触，有引起燃烧的危险。燃烧分解时，放出有毒的烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5690, 5798, NULL, NULL, NULL, NULL, NULL, '不燃固体', '吸入、食入、经皮吸收', '目前，无职业中毒的报道。对皮肤、眼睛有刺激性。', '该物质对环境可能有危害，对水体应给予特别注意。', '遇高热、明火或与氧化剂接触，有引起燃烧的危险。燃烧分解时，放出有毒的氮氧化物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5691, 5799, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有刺激性。接触后可出现头痛、头晕、恶心、呕吐等症状。皮肤接触可引起刺激、红肿、疼痛。眼睛接触可导致眼部刺激。食入可引起恶心、呕吐、腹痛。', '该物质对环境可能有危害，对水体应给予特别注意。避免排放到周围环境中。', '易燃，蒸气能扩散到远处，遇点火源着火，并引起回燃。储存容器及其部件可能向四面八方飞射很远。受热分解产生有毒的烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5692, 5800, NULL, NULL, NULL, NULL, NULL, '第3类易燃液体', '吸入、食入、皮肤接触、眼睛接触', '属于很强的一个挥发性精油，可能经由皮肤吸收，甚至不小心吃进去的吸收，产生很严重的中毒。对眼睛、皮肤、粘膜和上呼吸道有刺激性。误食樟脑油可能致命。', '该物质对环境可能有危害，应特别注意对水体的污染。', '易燃，其蒸气与空气混合，能形成爆炸性混合物。遇明火、高热有引起燃烧爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5693, 5801, NULL, NULL, NULL, NULL, NULL, '第2.3类 有毒气体', '吸入、皮肤接触、眼睛接触', '剧毒。吸入可引起头痛、头晕、恶心、呕吐、呼吸困难等症状。高浓度吸入可导致肺水肿、呼吸衰竭。对眼睛、皮肤和呼吸道有刺激性。', '该物质对环境有危害，对水体和土壤可造成污染。', '极端易燃，有爆炸危险。气体与空气可形成爆炸性混合物，遇明火、高热极易燃烧爆炸。受热分解产生有毒的锗化合物和氢气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5694, 5802, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有剧毒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5695, 5803, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '吞食后有剧毒。有轻微致癌性风险。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5696, 5804, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '对眼和上呼吸道有刺激性，对中枢神经系统有麻醉作用。吸入后可引起头痛、头晕、恶心、嗜睡等。高浓度接触可引起麻醉作用。皮肤接触可引起刺激。', '对水生生物有毒性。该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃，具刺激性。遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5697, 5805, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、皮肤接触、眼睛接触', '吸入有关烃类化合物蒸气时可引起轻度呼吸道刺激、头晕、恶心和倦睡；极高浓度可引起昏迷甚至死亡。高浓度蒸气对眼有刺激性；液体可引起眼部暂时性红肿和疼痛。液体对皮肤有轻度刺激性；反复接触可致皮炎，摄入引起恶心和腹泻。', '对环境有危害，应特别注意对水体的污染。', '本品易燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5698, 5806, NULL, NULL, NULL, NULL, NULL, '第3.1类低闪点易燃液体', '吸入、食入、经皮吸收', '蒸气或雾对眼及上呼吸道有刺激性。对皮肤有刺激性。接触后出现头痛、恶心、呕吐。高浓度蒸气可引起中枢神经系统抑制，表现为头痛、头晕、乏力、恶心、呕吐等症状，严重时可导致意识丧失。', '对环境有危害，应特别注意对水体的污染。', '本品易燃、具强刺激性。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5699, 5807, NULL, NULL, NULL, NULL, NULL, '第3.1类低闪点易燃液体', '吸入、食入、经皮吸收', '蒸气或雾对眼及上呼吸道有刺激性。对皮肤有刺激性。接触后出现头痛、头晕、恶心、呕吐等症状。高浓度蒸气可引起中枢神经系统抑制，表现为头痛、头晕、乏力、恶心、呕吐等症状，严重时可导致意识丧失。', '对环境有危害，应特别注意对水体的污染。', '极度易燃，在空气中久置后能生成有爆炸性的过氧化物。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5700, 5808, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '对呼吸道有强烈的刺激性，吸入后引起咳嗽、呼吸困难、胸痛、肺水肿、昏迷。对眼和皮肤有强烈刺激性甚至引起灼伤。口服刺激和腐蚀消化道。', '对环境有危害。', '本品易燃，具强刺激性。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。具腐蚀性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5701, 5809, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入经皮吸收', '头痛、头晕和嗜睡，手部可发生接触性皮炎。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5702, 5810, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '蒸气对眼、粘膜和上呼吸道有刺激性。对皮肤有刺激性。长时间接触本品有麻醉作用。动物实验表明本品后，造成不可逆的前肢麻痹。', '对水生生物有毒性。', '本品易燃。遇高热、明火及强氧化剂易引起燃烧。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5703, 5811, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入', '蒸气对眼、粘膜和上呼吸道有刺激性。对皮肤有刺激性。长时间接触本品有麻醉作用。', '对环境有危害，对水体、土壤和大气可造成污染。', '本品易燃。遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5704, 5812, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '蒸气或雾对眼、粘膜和上呼吸道有刺激性。对皮肤有刺激性。长时间接触本品有麻醉作用。', '对水生生物有毒性。', '本品易燃。触空气或在光照条件下可生成具有潜在爆炸危险性的过氧化物。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源引着回燃。若遇高热，可能发生聚合反应，出现大量放热现象，引起容器破裂和爆炸事故。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5705, 5813, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '动物经口、经皮、腹腔注射后中毒表现为：无力、震颤、血管扩张、呼吸困难，临死时四肢抽搐。大鼠吸入本品蒸气后，出现氰类中毒症状，并迅速死亡。对眼和皮肤有轻微刺激作用。', '对环境有害。对水生环境可能会引起长期有害作用。', '易燃，具强刺激性。遇高热、明火、氧化剂有引起燃烧的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5706, 5814, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入', '吸入本品蒸气后，可引起头痛、恶心及麻醉作用。高浓度吸入后可因呼吸麻痹而死亡。对眼睛、皮肤和呼吸道有刺激性。', '对水体可造成污染。', '本品易燃。受热、接触酸或酸雾会放出剧毒的烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5707, 5815, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入\n吸入', '灼伤。', '无资料', '本品易燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5708, 5816, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入经皮吸收\n对眼、呼吸道粘膜及皮肤有强烈刺激性。吸入可引起喉、支气管的炎症、水肿和痉挛，化', '对眼、呼吸道粘膜及皮肤有强烈刺激性。吸入可引起喉、支气管的炎症、水肿和痉挛，化学性肺炎，肺水肿。长期或反复接触对个别敏感者可引起变态反应。', NULL, '本品极度易燃，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5709, 5817, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、经皮吸收', '对皮肤、眼睛和呼吸道有强烈的刺激作用和腐蚀作用。吸入可引起咳嗽、呼吸困难、化学性肺炎。口服可引起恶心、呕吐、腹痛。', '对环境有害。对水生环境可能会引起长期有害作用。', '可燃，具腐蚀性、刺激性，可致人体灼伤。遇明火、高热可燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5710, 5818, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入食入经皮吸收', '蒸气或雾对眼、粘膜和上呼吸道有刺激性。对皮肤有刺激性。对人的刺激阈浓度为70mg/m3。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5711, 5819, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入、食入、经皮吸收', '对皮肤、眼睛和粘膜有刺激作用。吸入、摄入或经皮肤吸收后对身体有害。接触后可出现头痛、头晕、恶心、呕吐等症状。皮肤接触可引起刺激、红肿、疼痛。眼睛接触可导致严重眼部损伤。', '对水生生物有毒性。该物质对环境可能有危害，对水体应给予特别注意。避免排放到周围环境中。', '本品易燃、具有刺激性。遇明火、高热可燃。受热分解产生有毒气体。其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5712, 5820, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '在工业生产中未发现对人的危害。给动物致死量时发生皮毛粗糙、共济失调、气急、呼吸困难、抽搐和体温降低。对眼睛、皮肤和粘膜有刺激作用。', '对环境有害。对水生环境可能会引起长期有害作用。', '易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5713, 5821, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '对皮肤、眼睛和粘膜有刺激性。吸入、摄入或经皮肤吸收后对身体有害。接触后可出现头痛、头晕、恶心、呕吐等症状。皮肤接触可引起刺激、红肿、疼痛。眼睛接触可导致严重眼部损伤。', '对水生生物有毒性。该物质对环境可能有危害，对水体应给予特别注意。避免排放到周围环境中。', '易燃，遇明火、高热能引起燃烧爆炸。与氧化剂可发生反应。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5714, 5822, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入经皮吸收\n在工业生产中未发现对人的危害。给动物致死量时发生皮毛粗糙、共济失调、气急、呼吸', '困难、抽搐和体温降低。', '无资料', '本品易燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5715, 5823, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入食入经皮吸收\n在工业生产中未发现对人的危害。动物中毒的表现为暂时的兴奋，共济失调，上呼吸道刺', '激，迅速发展至呼吸紊乱。', '无资料', '本品易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5716, 5824, NULL, NULL, NULL, NULL, NULL, '第2.1类易燃气体', '吸入', '高浓度有窒息和麻醉作用。急性中毒：主要症状有头晕、头痛、嗜睡和酒醉状态、严重者可昏迷。慢性影响：接触以丁烷为主的工人有头晕、头痛、睡眠不佳、疲倦等。', '对环境有危害。', '本品易燃，具窒息性。与空气混合能形成爆炸性混合物，遇热源和明火有燃烧爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5717, 5825, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用。吸入可引起喉、支气管的痉挛、炎症、水肿，化学性肺炎、肺水肿而死亡。可致皮肤灼伤。口服后可引起恶心、呕吐和腹痛。', '该物质对环境可能有危害，应特别注意对水体的污染。', '本品有毒、易燃、具强刺激性。遇热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5718, 5826, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '对皮肤、粘膜有刺激作用。人口服2毫克即出现心悸、口干、头痛、四肢麻木、血压略有增高。高浓度蒸气可引起麻醉作用，出现头痛、头晕、步态蹒跚，甚至出现意识丧失。对眼睛有刺激性。', '对环境有危害，应特别注意对水体的污染。', '本品易燃，有毒，具刺激性。遇明火、高热极易引起燃烧爆炸。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5719, 5827, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害，对眼睛、皮肤有刺激作用。高浓度蒸气可引起头痛、头晕、恶心等症状。', '对环境有危害，应特别注意对水体的污染。', '遇高热、明火或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5720, 5828, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收后对身体有害。对眼睛、皮肤、粘膜和上呼吸道有刺激作用，引起咳嗽、流泪、流涎；个别人有恶心、头痛、胸骨后疼痛和呼吸困难等症状。', '对环境有危害，应特别注意对水体的污染。', '本品易燃，具刺激性。遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5721, 5829, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '高浓度蒸气可引起麻醉作用，出现头痛、头晕、步态蹒跚，甚至出现意识丧失和木僵状态。对皮肤有轻度刺激性。慢性影响：长期接触可引起神经衰弱综合征。少数人有轻度中性白细胞减少，消化不良。', '对环境有危害，应特别注意对水体的污染。', '本品易燃，具刺激性。遇明火、高热极易引起燃烧爆炸。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5722, 5830, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜和呼吸道有强烈刺激作用。', '对环境有危害，应特别注意对水体的污染。', '本品易燃，具强刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热有引起燃烧爆炸的危险。遇水、醇类发生化学反应而分解。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5723, 5831, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体有害。有强烈刺激作用，接触后可引起烧灼感、咳嗽、喉炎、气短、头痛、恶心和呕吐。', '对环境有危害，应特别注意对水体的污染。', '本品易燃，具刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热有引起燃烧爆炸的危险。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5724, 5832, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收对身体有害，其蒸气或雾对眼睛、皮肤、粘膜和呼吸道有刺激作用。吸入后可引起化学性肺炎、肺水肿。', '对环境有危害，应特别注意对地表水、土壤、大气和饮用水的污染。', '本品易燃，具刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热有引起燃烧爆炸的危险。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5725, 5833, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体，第8类腐蚀性液体', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜和呼吸道有强烈刺激作用。吸入后可因喉、支气管的痉挛、水肿、化学性肺炎、肺水肿而致死。中毒表现有烧灼感、咳嗽、喘息、喉炎、气短、头痛、恶心和呕吐。', '对水生生物有毒性。该物质对环境可能有危害，对水体应给予特别注意。', '本品易燃，具腐蚀性、强刺激性，可致人体灼伤。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5726, 5834, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收对身体有害，引起眼睛、粘膜和呼吸道的刺激症状，对眼睛有损伤。高浓度蒸气可引起头痛、头晕、恶心等症状。', '对环境有危害，应特别注意对水体的污染。', '本品易燃。遇明火、高热能引起燃烧爆炸。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5727, 5835, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收后对身体有害。其蒸气或雾对眼睛、粘膜和上呼吸道有刺激作用，引起咳嗽、流泪、流涎；个别人有恶心、头痛、胸骨后疼痛和呼吸困难等症状。', '对环境有危害，应特别注意对水体的污染。', '本品易燃，具刺激性。遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5728, 5836, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '对呼吸道、眼和皮肤有刺激性。高浓度蒸气可引起头痛、头晕、恶心等症状。', '对环境有危害，应特别注意对水体的污染。', '本品易燃，具刺激性。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5729, 5837, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '对呼吸道、眼和皮肤有刺激性。高浓度蒸气可引起头痛、头晕、恶心等症状。', '对环境有危害，应特别注意对水体的污染。', '本品易燃，具刺激性。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5730, 5838, NULL, NULL, NULL, NULL, NULL, '第3.1类低闪点易燃液体', '吸入食入经皮吸收', '麻木，触、痛、震动和位置等感觉减退，尤以下肢为甚，上肢较少受累。进一步发展为下\n肢无力，肌肉疼痛，肌肉萎缩及运动障碍。神经-肌电图检查示感觉神经及运动神经传导\n速度减慢。', '无资料', '本品极度易燃，具刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5731, 5839, NULL, NULL, NULL, NULL, NULL, '第8.1类酸性腐蚀品', '吸入、食入、经皮吸收', '蒸气或雾对眼、鼻、喉有刺激性。口服液体可引起恶心、呕吐、腹痛、血便或休克。皮肤或眼接触可致灼伤。慢性影响：鼻粘膜萎缩、鼻中隔穿孔。长期反复皮肤接触，可引起皮肤刺激。', '对环境有危害，应特别注意对水体的污染。', '本品不燃，具腐蚀性、刺激性，可致人体灼伤。遇金属反应放出氢气，能与空气形成爆炸性混合物。受热分解产生剧毒的氧化磷烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5732, 5840, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '本品对粘膜有刺激作用，经口有轻度毒性。吸入、摄入或经皮肤吸收后对身体有害。接触后可出现头痛、头晕、恶心、呕吐等症状。', '对水生生物有毒性。该物质对环境可能有危害，对水体应给予特别注意。', '遇高热、明火或与氧化剂接触，有引起燃烧的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5733, 5841, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收后对身体可能有害。对人的刺激作用阈浓度为20mg/m³。对眼睛、皮肤有刺激作用。', '对环境有危害，对水体应给予特别注意。', '本品易燃，具刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热有引起燃烧爆炸的危险。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5734, 5842, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收对身体有害，对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对环境有危害，对水体应给予特别注意。', '本品易燃，具刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热有引起燃烧爆炸的危险。受热容器有爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5735, 5843, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '吸入、摄入或经皮肤吸收对身体有害，对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对环境有危害，对水体应给予特别注意。', '本品易燃，具刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热有引起燃烧爆炸的危险。受热容器有爆炸危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5736, 5844, NULL, NULL, NULL, NULL, NULL, '第3类易燃液体', '吸入、食入、经皮吸收', '对眼睛、皮肤、粘膜和上呼吸道有刺激作用。', '对环境有危害，应特别注意对水体的污染。', '本品易燃，具刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热有引起燃烧爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5737, 5845, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜和呼吸道有强烈刺激作用。高浓度接触可引起头痛、头晕、恶心、呼吸困难等症状。', '对环境有危害，应特别注意对水体的污染。', '本品易燃，有毒，具刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热有引起燃烧爆炸的危险。受热分解产生有毒的氧化氮烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5738, 5846, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜和呼吸道有强烈刺激作用。高浓度接触可引起头痛、头晕、恶心、呼吸困难等症状。', '对环境有危害，应特别注意对水体的污染。', '本品易燃，有毒，具强刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热有引起燃烧爆炸的危险。受热分解产生有毒的硫化氢和氧化硫烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5739, 5847, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '对人的眼睛、呼吸道粘膜有刺激作用，有麻醉和肺部刺激作用。', '对环境有危害，应特别注意对地表水、土壤、大气和饮用水的污染。', '本品易燃，具刺激性。其蒸气与空气可形成爆炸性混合物，遇明火、高热有引起燃烧爆炸的危险。蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5740, 5848, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品', '吸入、食入、经皮吸收', '对眼、皮肤、粘膜和上呼吸道有刺激性。接触后可出现头痛、头晕、恶心、呕吐等症状。皮肤接触可引起刺激、红肿、疼痛。眼睛接触可导致严重眼部损伤。食入可引起恶心、呕吐、腹痛。可能对生殖系统造成损害。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。该物质对环境有危害，对水体应给予特别注意。避免排放到周围环境中。', '遇明火、高热可燃。受热分解，放出有毒烟气。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5741, 5849, NULL, NULL, NULL, NULL, NULL, '第3.2类中闪点易燃液体', '吸入、食入、经皮吸收', '吸入、口服或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜及呼吸道有强烈刺激性。吸入后可因喉、支气管的痉挛、水肿，化学性肺炎、肺水肿而致死。长时间接触可引起局部严重刺激或灼伤。', '无资料', '本品易燃，具强刺激性。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5742, 5850, NULL, NULL, NULL, NULL, NULL, '第3.3类高闪点易燃液体', '吸入、食入、经皮吸收', '蒸气或雾对眼、粘膜和上呼吸道有刺激性。接触后可引起头痛、头晕、恶心、呕吐、嗜睡等。对皮肤有刺激性。', '该物质对环境可能有危害，对水体应给予特别注意。', '易燃，遇高热、明火及强氧化剂易引起燃烧。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5743, 5851, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤、粘膜有强烈刺激性。吸入可引起呼吸道刺激。食入可引起胃肠道刺激。', '对水生生物有害。', '跟可燃物质接触可能会引起火灾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5744, 5852, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤、粘膜有强烈刺激性。吸入可引起呼吸道刺激。食入可引起胃肠道刺激。', '对水生生物有害。', '跟可燃物质接触可能会引起火灾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5745, 5853, NULL, NULL, NULL, NULL, NULL, '第3类易燃液体', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。吸入可引起呼吸道刺激，高浓度吸入可引起肺水肿。食入可引起恶心、呕吐、腹痛等。', '对水生生物有毒。', '易燃，其蒸气与空气混合，能形成爆炸性混合物。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5746, 5854, NULL, NULL, NULL, NULL, NULL, '第4.1类 易燃固体', '吸入 食入', '起角膜炎。', '无资料', '本品易燃、具爆炸性、有毒', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5747, 5855, NULL, NULL, NULL, NULL, NULL, '第1类 爆炸品', '吸入\n吸入对呼吸道有强烈刺激作用，对中枢神经系统有抑制作用。急性中毒出现剧烈刺激性咳嗽、', '呼吸困难、胸痛。伴有疲乏无力、呕吐、冷汗、脉快而弱等症状。严重者发生肺炎、肺水肿、\n休克、昏迷，甚至死亡。', '无资料', '本品属爆炸品，可燃，高毒，具强刺激性。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5748, 5856, NULL, NULL, NULL, NULL, NULL, '第3.3类 高闪点易燃液体', '吸入 食入 经皮吸收', '刺激作用。', '无资料', '本品易燃、有毒、具爆炸性、刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5749, 5857, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入.食入经皮吸收\n急性中毒：吸入后可引起急性呼吸道刺激症状、鼻出血、声音嘶哑、鼻粘膜萎缩，有时\n出现哮喘和紫绀。重者可发生化学性肺炎。口服可刺激和腐蚀消化道，引起恶心、呕吐、', NULL, '无资料', '本品助燃，为致癌物，具强腐蚀性、刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5750, 5858, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入 食入 经皮吸收\n有毒。吸入粉尘或烟雾，可引起急性呼吸道刺激症状和过敏性哮喘；误服对胃肠有刺激\n作用，严重者可出现休克、紫绀、呼吸困难。吸入其粉尘或烟雾可发生鼻中膈穿孔。', '尚有致癌作用。', '无资料', '本品助燃、具有刺激性', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5751, 5859, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、经皮吸收', '急性中毒：吸入后可引起急性呼吸道刺激症状、鼻出血、声音嘶哑、鼻粘膜萎缩，有时出现哮喘和紫绀。重者可发生化学性肺炎。口服可刺激和腐蚀消化道，引起恶心、呕吐、腹痛、腹泻、便血等。重者可致消化道穿孔、腹膜炎、休克等。皮肤接触可引起皮炎、湿疹、铬溃疡。眼睛接触可引起结膜炎、角膜损伤。慢性中毒：长期接触可引起铬鼻病（鼻中隔穿孔）、皮肤过敏、职业性哮喘、肺癌等。', '对水生生物有毒，可能对水生环境造成长期不利影响', '本品助燃，为致癌物，具强腐蚀性、刺激性，可致人体灼伤。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5752, 5860, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '跟皮肤接触可能会引起敏化作用。', '对水生物有剧毒, 对水生环境可能会引起长期有害作用', '跟可燃物质接触可能会引起火灾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5753, 5861, NULL, NULL, NULL, NULL, NULL, '第5.1类 氧化剂', '吸入、食入、经皮吸收', '急性中毒：吸入后可引起急性呼吸道刺激，并可致过敏性哮喘。口服刺激和腐蚀消化道，引起恶心、呕吐、腹痛、腹泻、血便等。重者出现呼吸困难、紫绀、休克、肝损害及急性肾功能衰竭等。慢性影响：有接触性皮炎、铬溃疡、鼻炎、鼻中隔穿孔及呼吸道炎症等。', '对水生生物有害，可能对水体环境造成长期不良影响', '强氧化剂，与可燃物混合可能引起火灾或爆炸', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5754, 5862, NULL, NULL, NULL, NULL, NULL, '第5.1类氧化剂', '吸入、食入、皮肤接触、眼睛接触', '吸入、食入或经皮肤吸收对身体有害。对眼睛、皮肤、粘膜和上呼吸道有强烈刺激作用。吸入可引起喉、支气管炎症、化学性肺炎、肺水肿。长期接触可引起铬中毒，表现为皮肤溃疡、鼻中隔穿孔、肺癌等。六价铬化合物被IARC列为1类致癌物。', '对水生物有剧毒，对水生环境可能会引起长期有害作用。对土壤和地下水环境有潜在危害。', '强氧化剂，与可燃物、还原剂、有机物、金属粉末等接触可能发生剧烈反应，引起燃烧或爆炸。受热分解产生有毒的铬氧化物烟雾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5755, 5863, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '跟皮肤接触可能会引起敏化作用。', '对水生物有剧毒,对水生环境可能会引起长期有害作用。', '跟可燃物质接触可能会引起火灾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5756, 5864, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '跟皮肤接触可能会引起敏化作用。', '对水生物有剧毒,对水生环境可能会引起长期有害作用。', '跟可燃物质接触可能会引起火灾。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5757, 5865, NULL, NULL, NULL, NULL, NULL, '侵入途径：', NULL, '跟皮肤接触可能会引起敏化作用', '对水生物有剧毒, 对水生环境可能会引起长期有害作用', '跟可燃物质接触可能会引起火灾', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_hazard` VALUES (5758, 5866, NULL, NULL, NULL, NULL, NULL, '第6.1类毒害品；致癌性类别1', '吸入、食入、皮肤接触、眼睛接触', '对眼睛、皮肤、粘膜和上呼吸道有强烈的刺激作用，可引起皮肤灼伤。误服可引起消化道损伤。长期接触可能对肝脏、肾脏和血液系统造成损害。具有致癌性。属于烷化剂类化疗药，可能对生殖系统造成损害。', '对水生生物可能有毒性。对环境有危害。', '受热或接触火焰可能会产生膨胀或爆炸性分解。受热分解产生有毒气体。遇明火、高热可燃。', NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_leak_response` VALUES (2883, 3021, NULL, NULL, NULL, '隔离泄漏污染区，周围设警告标志，建议应急处理人员戴自给式呼吸器，穿化学防护服。 不要直接接触泄漏物，小心扫起，避免扬尘，收集于干燥净洁有盖的容器中，转移到安全 场所。用水刷洗泄漏污染区，经稀释的污水放入废水系统。如大量泄漏，收集回收或无害 处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:29:27', '', NULL);
INSERT INTO `msds_leak_response` VALUES (2884, 3022, NULL, NULL, NULL, '隔离泄漏污染区，周围设警告标志，建议应急处理人员戴好防毒面具，穿化学防护服。 用不燃性分散剂制成的乳液刷洗，经稀释的污水放入废水系统。如大量泄漏，利用围堤 收容，然后收集、转移、回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:29:27', '', NULL);
INSERT INTO `msds_leak_response` VALUES (2885, 3023, NULL, NULL, NULL, '隔离泄漏污染区，限制出入。切断火源。建议应急处理人员戴防尘面具（全面罩），穿防 毒服。不要直接接触泄漏物。小量泄漏：避免扬尘，小心扫起，置于袋中转移至安全场所。 大量泄漏：收集回收或运至废物处理场所处置。', NULL, NULL, NULL, NULL, '2026-03-06 14:29:28', '', NULL);
INSERT INTO `msds_leak_response` VALUES (2886, 3024, NULL, NULL, NULL, '隔离泄漏污染区，周围设警告标志，切断火源。建议应急处理人员戴自给式呼吸器，穿化 学防护服。不要直接接触泄漏物，用砂土吸收，倒至空旷地方深埋。在污染区撒上石灰， 用大量水冲洗，经稀释的污水放入废水系统。如大量泄漏，收集回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:29:28', '', NULL);
INSERT INTO `msds_leak_response` VALUES (2887, 3025, NULL, NULL, NULL, '应急处理：迅速撤离泄漏污染区人员至安全区，并进行隔离，严格限制出入。切断火源。建议应急处理人员戴自给正压式呼吸器，穿防毒物渗透工作服。不要直接接触泄漏物。尽可能切断泄漏源。防止流入下水道、排洪沟等限制性空间。保证充分的通风。清除所有点火源。迅速将人员撤离到安全区域，远离泄漏区域并处于上风向。采取措施防止进一步的泄漏或溢出。避免排放到周围环境中。少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。清除所有点火源，并采用防火花工具和防爆设备。', NULL, NULL, NULL, NULL, '2026-03-06 14:29:28', '', NULL);
INSERT INTO `msds_leak_response` VALUES (2888, 3026, NULL, NULL, NULL, '疏散泄漏污染区人员至安全区，禁止无关人员进入污染区，切断火源。应急处理人员戴 正压自给式呼吸器，穿化学防护服。不要直接接触泄漏物，在确保安全情况下堵漏。喷 雾状水， 减少蒸发。用砂土或其它不燃性吸附剂混合吸收，然后收集于干燥洁净有盖的 容器中，运至废物处理场所。如大量泄漏，利用围堤收容，然后收集、转移、回收或无 害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:29:28', '', NULL);
INSERT INTO `msds_leak_response` VALUES (2889, 3027, NULL, NULL, NULL, '疏散泄漏污染区人员至安全区，禁止无关人员进入污染区，建议应急处理人员戴自给式呼 吸器，穿化学防护服。不要直接接触泄漏物，用砂土吸收，铲入提桶，倒至空旷地方深埋。 也可以用大量水冲洗，经稀释的污水放入废水系统。如大量泄漏，利用围堤收容，然后收 集、转移、回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:29:29', '', NULL);
INSERT INTO `msds_leak_response` VALUES (2890, 3028, NULL, NULL, NULL, '疏散泄漏污染区人员至安全区，禁止无关人员进入污染区，切断火源。建议应急处理人员戴 正压自给式呼吸器，穿厂商特别推荐的化学防护服(完全隔离)。不要直接接触泄漏物，在确 应急处理： 保安全情况下堵漏。喷雾状水，减少蒸发。用沙土、蛭石或其它惰性材料吸收，然后收集运 至废物处理场所处置。也可以用不燃性分散剂制成的乳液刷洗，经稀释的洗水放入废水系统。 如大量泄漏，利用围堤收容，然后收集、转移、回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:29:30', '', NULL);
INSERT INTO `msds_leak_response` VALUES (2891, 3029, NULL, NULL, NULL, '保证充分的通风。清除所有点火源。迅速将人员撤离到安全区域，远离泄漏区域并处于上 采取措施防止进一步的泄漏或溢出。避免排放到周围环境中。少量泄漏时，可采用干砂或 惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。附着物或收集物应存放在合适的密闭 容器中，并根据当地相关法律法规废弃处置。清除所有点火源，并采用防火花工具和防暴', NULL, NULL, NULL, NULL, '2026-03-06 14:29:30', '', NULL);
INSERT INTO `msds_leak_response` VALUES (2892, 3030, NULL, NULL, NULL, '保证充分的通风。清除所有点火源。迅速将人员撤离到安全区域，远离泄漏区域并处于上风 应急处理： 措施防止进一步的泄漏或溢出。避免排放到周围环境中。少量泄漏时，可采用干砂或惰性吸 附材料吸收泄漏物，大量泄漏时需筑堤控制。附着物或收集物应存放在合适的密闭容器中， 并根据当地相关法律法规废弃处置。清除所有点火源，并采用防火花工具和防暴设备。', NULL, NULL, NULL, NULL, '2026-03-06 14:29:30', '', NULL);
INSERT INTO `msds_leak_response` VALUES (2893, 3031, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至上风处，并进行隔离，严格限制出入。切断火源。建议应急处理人员佩戴自给正压式呼吸器，穿防静电工作服。尽可能切断泄漏源。加强通风，加速扩散。如无爆炸危险，可用雾状水喷射稀释蒸气并保护现场人员，但不可直接喷射泄漏点。将泄漏气体经导管或水封引至安全处所。必要时通知相关部门。', NULL, NULL, NULL, NULL, '2026-03-06 14:29:30', '', NULL);
