INSERT INTO `msds_leak_response` VALUES (3060, 3199, NULL, NULL, NULL, '疏散泄漏污染区人员至安全区，禁止无关人员进入污染区，建议应急处理人员戴好防毒 面具，穿化学防护服。用砂土、蛭石或其它惰性材料吸收，收集运至废物处理场所。也可 以用不燃性分散剂制成的乳液刷洗，经稀释的洗水放入废水系统。如大量泄漏，利用围堤 收容，然后收集、转移、回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:30:25', '', NULL);
