INSERT INTO `msds_leak_response` VALUES (3215, 3355, NULL, NULL, NULL, '疏散泄漏污染区人员至安全区，禁止无关人员进入污染区，切断火源。建议应急处理人员 戴好防毒面具，穿一般消防防护服。禁止泄漏物进入受限制的空间(如下水道等)，以避免 泄漏污染区，对污染地带进行通风。如大量泄漏，利用围堤收容，然后收集、转移、回收 或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:31:31', '', NULL);
