INSERT INTO `msds_leak_response` VALUES (3425, 3566, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至安全区，并进行隔离，严格限制出入。消除所有点火源。建议应急处理人员戴正压式空气呼吸器，穿防毒、防静电服。作业时使用的工具应为无火花工具。尽可能切断泄漏源。防止泄漏物进入下水道、地下室或限制性空间。小量泄漏：用干燥的砂土、惰性吸收剂或其它不燃材料收集，置于密闭容器中。大量泄漏：构筑围堤或挖坑收容。用泡沫覆盖，降低蒸气灾害。用防爆泵转移至槽车或专用收集器内，回收或运至废物处理场所处置。', NULL, NULL, NULL, NULL, '2026-03-06 14:33:01', '', NULL);
INSERT INTO `msds_leak_response` VALUES (3426, 3567, NULL, NULL, NULL, '迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。使用个人防护装备。不要触摸或穿越泄漏物。不要触摸破损的容器或泄漏物质除非穿着合适的防护服。', NULL, NULL, NULL, NULL, '2026-03-06 14:33:01', '', NULL);
INSERT INTO `msds_leak_response` VALUES (3427, 3568, NULL, NULL, NULL, '隔离泄漏污染区，限制出入。建议应急处理人员戴自给正压式呼吸器，穿防毒服。避免直接接触泄漏物。', NULL, NULL, NULL, NULL, '2026-03-06 14:33:03', '', NULL);
INSERT INTO `msds_leak_response` VALUES (3428, 3569, NULL, NULL, NULL, '隔离泄漏污染区，限制出入。切断火源。建议应急处理人员戴防尘口罩（全面罩），穿防毒服。避免扬尘，小心扫起，置于袋中转移至安全场所。若大量泄漏，用塑料布、帆布覆盖。收集回收或运至废物处理场所处置。', NULL, NULL, NULL, NULL, '2026-03-06 14:33:03', '', NULL);
INSERT INTO `msds_leak_response` VALUES (3429, 3570, NULL, NULL, NULL, '隔离泄漏污染区，限制出入。建议应急处理人员戴防尘口罩（全面罩），穿防毒服。避免扬尘，小心扫起，置于袋中转移至安全场所。若大量泄漏，用塑料布、帆布覆盖。收集回收或运至废物处理场所处置。', NULL, NULL, NULL, NULL, '2026-03-06 14:33:03', '', NULL);
INSERT INTO `msds_leak_response` VALUES (3430, 3571, NULL, NULL, NULL, '隔离泄漏污染区，限制出入。切断火源。建议应急处理人员戴防尘口罩（全面罩），穿防毒服。不要直接接触泄漏物。小量泄漏：避免扬尘，用洁净的铲子收集于干燥、洁净、有盖的容器中。大量泄漏：用塑料布、帆布覆盖，减少飞散。然后收集回收或运至废物处理场所处置。', NULL, NULL, NULL, NULL, '2026-03-06 14:33:03', '', NULL);
INSERT INTO `msds_leak_response` VALUES (3431, 3572, NULL, NULL, NULL, '泄漏污染区人员迅速撤离至安全区，并进行隔离，严格限制出入。切断火源。建议应急处理人员戴自给正压式呼吸器，穿防毒服。不要直接接触泄漏物。', NULL, NULL, NULL, NULL, '2026-03-06 14:33:05', '', NULL);
INSERT INTO `msds_leak_response` VALUES (3432, 3573, NULL, NULL, NULL, '保证充分的通风。清除所有点火源。迅速将人员撤离到安全区域，远离泄漏区域并处于上风位置。应急处理：措施防止进一步的泄漏或溢出。避免排放到周围环境中。少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。附着物或收集物应存放在合适的密闭容器中，并根据当地相关法规法律规定的处置。清除所有点火源，并采用防火花工具和防暴设备。', NULL, NULL, NULL, NULL, '2026-03-06 14:33:05', '', NULL);
INSERT INTO `msds_leak_response` VALUES (3433, 3574, NULL, NULL, NULL, '隔离泄漏污染区，周围设警告标志，建议应急处理人员戴自给式呼吸器，穿化学防护服。 不要直接接触泄漏物，小心扫起，避免扬尘，倒至空旷地方深埋。用水刷洗泄漏污染区， 经稀释的污水放入废水系统。如大量泄漏，收集回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:33:06', '', NULL);
INSERT INTO `msds_leak_response` VALUES (3434, 3575, NULL, NULL, NULL, '疏散泄漏污染区人员至安全区，并进行隔离，严格限制出入。切断火源。应急处理人员戴正压自给式呼吸器，穿防毒服。不要直接接触泄漏物。', NULL, NULL, NULL, NULL, '2026-03-06 14:33:06', '', NULL);
INSERT INTO `msds_leak_response` VALUES (3435, 3576, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至安全区，并进行隔离，严格限制出入。切断火源。建议应急人员戴自给正压式呼吸器，穿防毒服。避免吸入蒸气、烟雾、气体或风尘。', NULL, NULL, NULL, NULL, '2026-03-06 14:33:06', '', NULL);
INSERT INTO `msds_leak_response` VALUES (3436, 3577, NULL, NULL, NULL, '保证充分的通风。清除所有点火源。迅速将人员撤离到安全区域，远离泄漏区域并处于上风位置。应急处理措施：立即停止泄漏源，切断电源。采取措施防止进一步的泄漏或溢出。避免排放到周围环境中。少量泄漏时，可采用干砂、蛭石等惰性吸收材料吸收泄漏物，大量泄漏时需筑堤控制。附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。清除所有点火源，并采用防火花工具和防爆设备。', NULL, NULL, NULL, NULL, '2026-03-06 14:33:08', '', NULL);
INSERT INTO `msds_leak_response` VALUES (3437, 3578, NULL, NULL, NULL, '消除所有点火源。根据液体流动和蒸气扩散的影响区域划定警戒区，无关人员从侧风、上风向撤离至安全区。建议应急处理人员戴正压自给式呼吸器，穿防毒、防静电服。作业时使用的工具应为无火花工具。禁止直接接触泄漏物。尽可能切断泄漏源。防止流入下水道、排洪沟等限制性空间。', NULL, NULL, NULL, NULL, '2026-03-06 14:33:08', '', NULL);
INSERT INTO `msds_leak_response` VALUES (3438, 3579, NULL, NULL, NULL, '下的溢漏和泄漏应穿着蒸气防护服，且完全密封。不要触摸或穿越泄漏物。不要触摸破损 的容器或泄漏物质除非穿着合适的防护服。保证充分的通风。清除所有点火源。采取防静 电措施。迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。使用个人防护装备。', NULL, NULL, NULL, NULL, '2026-03-06 14:33:08', '', NULL);
INSERT INTO `msds_leak_response` VALUES (3439, 3580, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至安全区，并进行隔离，严格限制出入。切断火源。建议应急处理人员戴自吸过滤式防毒面具（全面罩），穿防静电工作服。尽可能切断泄漏源。防止流入下水道、排洪沟等限制性空间。小量泄漏：用不燃性分散剂制成的乳液刷洗，洗液稀释后放入废水系统。或在保证安全情况下，就地焚烧。大量泄漏：构筑围堤或挖坑收容。撒湿冰或冰水冷却。用防爆泵转移至槽车或专用收集器内，回收或运至废物处理场所处置。', NULL, NULL, NULL, NULL, '2026-03-06 14:33:09', '', NULL);
INSERT INTO `msds_leak_response` VALUES (3440, 3581, NULL, NULL, NULL, '疏散泄漏污染区人员至安全区，禁止无关人员进入污染区，切断火源。建议应急处理人员戴 应急处理： 低泄漏物在受限制空间内的易燃性。用沙土、干燥石灰或苏打灰混合，然后收集运至废物处 理场所处置，也可以用不燃性分散剂制成的乳液刷洗，经稀释的洗水放入废水系统。如大量 泄漏，利用围堤收容，然后收集、转移、回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:33:09', '', NULL);
INSERT INTO `msds_leak_response` VALUES (3441, 3582, NULL, NULL, NULL, '隔离泄漏污染区，周围设警告标志，建议应急处理人员戴自给式呼吸器，穿化学防护服。 不要直接接触泄漏物，用砂土吸收，铲入提桶，倒至空旷地方深埋。也可以用大量水冲洗， 经稀释的污水放入废水系统。如大量泄漏，收集回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:33:09', '', NULL);
