INSERT INTO `msds_leak_response` VALUES (3570, 3711, NULL, NULL, NULL, '隔离泄漏污染区，周围设警告标志，建议应急处理人员戴正压自给式呼吸器，穿防毒服。不要直接接触泄漏物，避免扬尘，小心扫起，置于袋中转移至安全场所。如大量泄漏，收集回收或按致癌物处理。清除所有点火源，并采用防火花工具和防暴设备。避免排放到周围环境中。', NULL, NULL, NULL, NULL, '2026-03-06 14:34:03', '', NULL);
INSERT INTO `msds_leak_response` VALUES (3571, 3712, NULL, NULL, NULL, '切断火源。戴好防毒面具，穿化学防护服。在确保安全情况下堵漏。喷雾状水，减少蒸发。 应急处理： 用不燃性分散剂制成的乳液刷洗，经稀释的洗液放入废水系统。如大量泄漏，利用围堤收容， 然后收集、转移、回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:34:05', '', NULL);
