INSERT INTO `msds_leak_response` VALUES (3795, 3936, NULL, NULL, NULL, '疏散泄漏污染区人员至安全区，禁止无关人员进入污染区，建议应急处理人员戴自给式 呼吸器，穿化学防护服。喷雾状水，减少蒸发。不要直接接触泄漏物，用砂土或其它不 燃性吸附剂混合吸收，收集倒至空旷地方深埋。被污染地面用肥皂或洗涤剂刷洗，经稀 释的污水放入废水系统。如果大量泄漏，小心扫起，装入备用袋中。', NULL, NULL, NULL, NULL, '2026-03-06 14:35:33', '', NULL);
