INSERT INTO `msds_leak_response` VALUES (3871, 4013, NULL, NULL, NULL, '隔离泄漏污染区，周围设警告标志，建议应急处理人员戴自给式呼吸器，穿化学防护服。不要直接接触泄漏物，小心扫起，避免扬尘，置于袋中转移至安全场所。用水刷洗泄漏污染区，经稀释的污水放入废水系统。如大量泄漏，收集回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:36:09', '', NULL);
INSERT INTO `msds_leak_response` VALUES (3872, 4014, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至上风处，并立即隔离150m，严格限制出入。切断火源。建议应急处理人员戴自给正压式呼吸器，穿防静电工作服。尽可能切断泄漏源。合理通风，加速扩散。高浓度泄漏区，喷含盐酸的雾状水中和、稀释、溶解。构筑围堤或挖坑收容产生的大量废水。如有可能，将残余气或漏出气用排风机送至水洗塔或与塔相连的通风橱内。', NULL, NULL, NULL, NULL, '2026-03-06 14:36:09', '', NULL);
INSERT INTO `msds_leak_response` VALUES (3873, 4015, NULL, NULL, NULL, '隔离泄漏污染区，周围设警告标志，建议应急处理人员戴好防毒面具，穿化学防护服。不 要直接接触泄漏物，小心扫起，运至废物处理场所。也可以用不燃性分散剂制成的乳液刷 洗，经稀释的洗水放入废水系统。如大量泄漏，收集回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:36:10', '', NULL);
INSERT INTO `msds_leak_response` VALUES (3874, 4016, NULL, NULL, NULL, '保证充分的通风。清除所有点火源。迅速将人员撤离到安全区域，远离泄漏区域并处于上风向。采取措施防止进一步的泄漏或溢出。避免排放到周围环境中。少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。清除所有点火源，并采用防火花工具和防爆设备。', NULL, NULL, NULL, NULL, '2026-03-06 14:36:10', '', NULL);
INSERT INTO `msds_leak_response` VALUES (3875, 4017, NULL, NULL, NULL, '保证充分的通风。清除所有点火源。迅速将人员撤离到安全区域，远离泄漏区域并处于上 采取措施防止进一步的泄漏或溢出。避免排放到周围环境中。少量泄漏时，可采用干砂或 惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。附着物或收集物应存放在合适的密闭 容器中，并根据当地相关法律法规废弃处置。清除所有点火源，并采用防火花工具和防暴', NULL, NULL, NULL, NULL, '2026-03-06 14:36:10', '', NULL);
INSERT INTO `msds_leak_response` VALUES (3876, 4018, NULL, NULL, NULL, '隔离泄漏污染区，周围设警告标志，建议应急处理人员戴好防毒面具，穿化学防护服。不 要直接接触泄漏物，禁止向泄漏物直接喷水，更不要让水进入包装容器内。避免扬尘，使 用无火花工具收集于干燥净洁有盖的容器中，逐渐加入干燥的异丙醇内，放置24小时，经 稀释后放入废水系统。如果大量泄漏，收集于密闭容器中作好标记，等待处理。', NULL, NULL, NULL, NULL, '2026-03-06 14:36:11', '', NULL);
INSERT INTO `msds_leak_response` VALUES (3877, 4019, NULL, NULL, NULL, '隔离泄漏污染区，周围设警告标志，切断火源。建议应急处理人员戴好防毒面具，穿化学 防护服。不要直接接触泄漏物，转移未破损的包装，禁止向泄漏物直接喷水，更不要让水 进入包装容器内。用清洁的铲子收集于干燥净洁有盖的容器中，转移至安全地带。如果大 量泄漏，用塑料布、帆布覆盖，在技术人员指导下清除。', NULL, NULL, NULL, NULL, '2026-03-06 14:36:11', '', NULL);
INSERT INTO `msds_leak_response` VALUES (3878, 4020, NULL, NULL, NULL, '隔离泄漏污染区，限制出入。切断火源。建议应急处理人员戴防尘面具（全面罩），穿防酸碱工作服。不要直接接触泄漏物。小量泄漏：小心扫起，收集于干燥、洁净、有盖的容器中。也可以用大量水冲洗，洗水稀释后放入废水系统。大量泄漏：收集回收或运至废物处理场所处置。', NULL, NULL, NULL, NULL, '2026-03-06 14:36:11', '', NULL);
INSERT INTO `msds_leak_response` VALUES (3879, 4021, NULL, NULL, NULL, '隔离泄漏污染区，限制出入。建议应急处理人员戴防尘口罩，穿防毒服。避免扬尘，使用无火花工具收集于干燥、洁净、有盖的容器中。若大量泄漏，用塑料布、帆布覆盖。收集回收或运至废物处理场所处置。', NULL, NULL, NULL, NULL, '2026-03-06 14:36:11', '', NULL);
INSERT INTO `msds_leak_response` VALUES (3880, 4022, NULL, NULL, NULL, '隔离泄漏污染区，周围设警告标志，建议应急处理人员戴好防毒面具，穿化学防护服。小 心扫起，避免扬尘，收集运至废物处理场所。用水刷洗泄漏污染区，经稀释的污水放入废 水系统。如大量泄漏，收集回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:36:11', '', NULL);
INSERT INTO `msds_leak_response` VALUES (3881, 4023, NULL, NULL, NULL, '隔离泄漏污染区，周围设警告标志，建议应急处理人员戴好口罩、护目镜，穿工作服。小 心扫起，装入备用袋中。也可以用水冲洗，经稀释的洗水放入废水系统。如大量泄漏，收 集回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:36:12', '', NULL);
INSERT INTO `msds_leak_response` VALUES (3882, 4024, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至安全区，并进行隔离，严格限制出入。建议应急处理人员戴自给正压式呼吸器，穿防酸碱工作服。不要直接接触泄漏物。尽可能切断泄漏源。', NULL, NULL, NULL, NULL, '2026-03-06 14:36:13', '', NULL);
INSERT INTO `msds_leak_response` VALUES (3883, 4025, NULL, NULL, NULL, '切断火源。戴好防毒面具和手套。用清洁的铲子收集运到空旷处焚烧。如大量泄漏，收集回收 或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:36:13', '', NULL);
INSERT INTO `msds_leak_response` VALUES (3884, 4026, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至上风处，并隔离直至气体散尽。应急处理人员戴自给式呼吸器，穿化学防护服。切断气源，抽排(室内)或强力通风(室外)。将漏气的容器移至空旷处，注意通风。漏气容器要妥善处理，修复、检验后再用。', NULL, NULL, NULL, NULL, '2026-03-06 14:36:13', '', NULL);
INSERT INTO `msds_leak_response` VALUES (3885, 4027, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至上风处，并进行隔离，严格限制出入。建议应急处理人员戴自给正压式呼吸器，穿一般作业工作服。尽可能切断泄漏源。合理通风，加速扩散。如有可能，将漏出气用排风机送至空旷地方或装设适当喷头烧掉。漏气容器要妥善处理，修复、检验后再用。', NULL, NULL, NULL, NULL, '2026-03-06 14:36:13', '', NULL);
INSERT INTO `msds_leak_response` VALUES (3886, 4028, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至上风处，并进行隔离，严格限制出入。应急处理人员戴正压自给式呼吸器，穿一般作业工作服。尽可能切断泄漏源。合理通风，加速扩散。如有可能，将漏出气用排风机送至空旷地方。漏气容器要妥善处理，修复、检验后再用。', NULL, NULL, NULL, NULL, '2026-03-06 14:36:15', '', NULL);
INSERT INTO `msds_leak_response` VALUES (3887, 4029, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至上风处，并立即进行隔离，严格限制出入。建议应急处理人员戴正压自给式呼吸器，穿防毒服。从上风处进入现场。尽可能切断泄漏源。合理通风，加速扩散。喷雾状水稀释、溶解。构筑围堤或挖坑收容产生的大量废水。如有可能，将残余气或漏出气用排风机送至水洗塔或与塔相连的通风橱内。漏气容器要妥善处理，修复、检验后再用。', NULL, NULL, NULL, NULL, '2026-03-06 14:36:15', '', NULL);
INSERT INTO `msds_leak_response` VALUES (3888, 4030, NULL, NULL, NULL, '疏散泄漏污染区人员至安全区，禁止无关人员进入污染区，切断火源。建议应急处理人员戴自给式呼吸器，穿化学防护服。不要直接接触泄漏物，在确保安全情况下堵漏。喷水雾会减少蒸发，但不能降低泄漏物在受限制空间内的易燃性。用沙土或其它不燃性吸附剂混合吸收，然后收集运至废物处理场所处置。也可以用大量水冲洗，经稀释的洗水放入废水系统。如大量泄漏，利用围堤收容，然后收集、转移、回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:36:15', '', NULL);
INSERT INTO `msds_leak_response` VALUES (3889, 4031, NULL, NULL, NULL, '隔离泄漏污染区，周围设警告标志，切断火源。应急处理人员戴好防毒面具，穿化学防护服。不要直接接触泄漏物，用清洁的铲子收集于干燥洁净有盖的容器中，运至废物处理场所。如大量泄漏，收集回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:36:15', '', NULL);
INSERT INTO `msds_leak_response` VALUES (3890, 4032, NULL, NULL, NULL, '保证充分的通风。清除所有点火源。迅速将人员撤离到安全区域，远离泄漏区域并处于上风向。采取措施防止进一步的泄漏或溢出。避免排放到周围环境中。少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。清除所有点火源，并采用防火花工具和防爆设备。', NULL, NULL, NULL, NULL, '2026-03-06 14:36:16', '', NULL);
INSERT INTO `msds_leak_response` VALUES (3891, 4033, NULL, NULL, NULL, '隔离泄漏污染区，限制出入。切断火源。建议应急处理人员戴自给正压式呼吸器，穿防毒服。不要直接接触泄漏物。小量泄漏：用水、潮湿的沙或泥土覆盖。收入金属容器并保存于水或矿物油中。大量泄漏：在专家指导下清除。', NULL, NULL, NULL, NULL, '2026-03-06 14:36:17', '', NULL);
INSERT INTO `msds_leak_response` VALUES (3892, 4034, NULL, NULL, NULL, '隔离泄漏污染区，限制出入。切断火源。建议应急处理人员戴自给正压式呼吸器，穿化学 应急处理： 防护服。不要直接接触泄漏物。小量泄漏：避免扬尘，用洁净的铲子收集于干燥、洁净、 有盖的容器中。转移回收。大量泄漏：用塑料布、帆布覆盖。使用无火花工具转移回收。', NULL, NULL, NULL, NULL, '2026-03-06 14:36:17', '', NULL);
INSERT INTO `msds_leak_response` VALUES (3893, 4035, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至安全区，并进行隔离，严格限制出入。切断火源。建议应急处理人员戴自给正压式呼吸器，穿防毒服。尽可能切断泄漏源。防止流入下水道、排洪沟等限制性空间。小量泄漏：用活性炭或其它惰性材料吸收。也可以用不燃性分散剂制成的乳液刷洗，洗液稀释后放入废水系统。大量泄漏：构筑围堤或挖坑收容。用泡沫覆盖，降低蒸气灾害。喷雾状水或泡沫冷却和稀释蒸汽、保护现场人员。用防爆泵转移至槽车或专用收集器内，回收或运至废物处理场所处置。', NULL, NULL, NULL, NULL, '2026-03-06 14:36:17', '', NULL);
INSERT INTO `msds_leak_response` VALUES (3894, 4036, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至安全区，并进行隔离，严格限制出入。切断火源。建议应急处 理人员戴自给正压式呼吸器，穿防毒服。不要直接接触泄漏物。尽可能切断泄漏源。防止 流入下水道、排洪沟等限制性空间。小量泄漏：用砂土或其它不燃材料吸附或吸收。大量 泄漏：构筑围堤或挖坑收容。喷雾状水或泡沫冷却和稀释蒸汽、保护现场人员。用泵转移 至槽车或专用收集器内，回收或运至废物处理场所处置。', NULL, NULL, NULL, NULL, '2026-03-06 14:36:18', '', NULL);
INSERT INTO `msds_leak_response` VALUES (3895, 4037, NULL, NULL, NULL, '隔离泄漏污染区，周围设警告标志，建议应急处理人员戴自给式呼吸器，穿化学防护服。 小心扫起，避免扬尘，置于袋中转移至安全场所。用水刷洗泄漏污染区，对污染地带进行 通风，如大量泄漏，收集回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:36:18', '', NULL);
