INSERT INTO `msds_leak_response` VALUES (4059, 4202, NULL, NULL, NULL, '疏散泄漏污染区人员至安全区，禁止无关人员进入污染区，建议应急处理人员戴好防毒面 具，穿化学防护服。不要直接接触泄漏物，禁止向泄漏物直接喷水，更不要让水进入包装 应急处理： 容器内。撒上足量的小苏打，将其混匀在地面摊开，再用大量水冲洗，经稀释的污水放入 废水系统。也可以用弱还原剂(低亚硫酸钠、重亚硫酸盐)覆盖，转移到一个盛有水的容器 中，用纯碱中和。如大量泄漏，利用围堤收容，然后收集、转移、回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:37:25', '', NULL);
