INSERT INTO `msds_leak_response` VALUES (4150, 4293, NULL, NULL, NULL, '隔离泄漏污染区，限制出入。消除所有点火源。建议应急处理人员戴正压自给式呼吸器，穿防毒、防静电服。作业时使用的工具应为无火花工具。禁止直接向泄漏物喷水。禁止让水进入包装容器内。用干燥的砂土或类似物质吸收，收集于密闭容器中。如大量泄漏，利用围堤收容，然后收集、转移、回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:38:08', '', NULL);
