INSERT INTO `msds_leak_response` VALUES (4211, 4354, NULL, NULL, NULL, '疏散泄漏污染区人员至安全区，禁止无关人员进入污染区，建议应急处理人员戴自给式呼吸 应急处理： 器，穿化学防护服。不要直接接触泄漏物，在确保安全情况下堵漏。用沙土、干燥石灰或苏 打灰混合，然后收集运至废物处理场所处置。', NULL, NULL, NULL, NULL, '2026-03-06 14:38:41', '', NULL);
