INSERT INTO `msds_leak_response` VALUES (4269, 4412, NULL, NULL, NULL, '应急处理： 剂混合吸收，然后运至空旷的地方掩埋、蒸发、或焚烧。如大量泄漏，利用围堤收容，然后 收集、转移、回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:39:06', '', NULL);
