INSERT INTO `msds_leak_response` VALUES (4305, 4448, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至安全区，并进行隔离，严格限制出入。建议应急处理人员戴自给正 压式呼吸器，穿防酸碱工作服。不要直接接触泄漏物。尽可能切断泄漏源。小量泄漏：用砂土、 蛭石或其它惰性材料吸收。大量泄漏：构筑围堤或挖坑收容。在专家指导下清除。', NULL, NULL, NULL, NULL, '2026-03-06 14:39:23', '', NULL);
