INSERT INTO `msds_leak_response` VALUES (4321, 4464, NULL, NULL, NULL, '疏散泄漏污染区人员至安全区，禁止无关人员进入污染区，切断火源。建议应急处理人员戴自给式呼吸器，穿化学防护服。不要直接接触泄漏物，喷雾状水，减少蒸发。用砂土吸收，使用不产生火花的工具收集于一个密闭的容器中，运至废物处理场所。用水刷洗泄漏污染区，对污染地带进行通风。如大量泄漏，利用围堤收容，然后收集、转移、回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:39:28', '', NULL);
