INSERT INTO `msds_leak_response` VALUES (4346, 4489, NULL, NULL, NULL, '隔离泄漏污染区，周围设警告标志，应急处理人员戴正压自给式呼吸器，穿化学防护服。 不要直接接触泄漏物，避免扬尘，用清洁的铲子收集于干燥洁净有盖的容器中，运至废 物处理场所。如大量泄漏，收集回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:39:41', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4347, 4490, NULL, NULL, NULL, '疏散泄漏污染区人员至安全区，禁止无关人员进入污染区，建议应急处理人员戴自给式呼 吸器，穿化学防护服。不要直接接触泄漏物，用砂土吸收，铲入提桶，倒至空旷地方深埋。 用水刷洗泄漏污染区，经稀释的污水放入废水系统。如大量泄漏，利用围堤收容，然后收 集、转移、回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:39:42', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4348, 4491, NULL, NULL, NULL, '保证充分的通风。清除所有点火源。迅速将人员撤离到安全区域，远离泄漏区域并处于上 采取措施防止进一步的泄漏或溢出。避免排放到周围环境中。少量泄漏时，可采用干砂或 惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。附着物或收集物应存放在合适的密闭 容器中，并根据当地相关法律法规废弃处置。清除所有点火源，并采用防火花工具和防暴', NULL, NULL, NULL, NULL, '2026-03-06 14:39:42', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4349, 4492, NULL, NULL, NULL, '疏散泄漏污染区人员至安全区，禁止无关人员进入污染区，切断火源。应急处理人员戴自给 式呼吸器，穿化学防护服。不要直接接触泄漏物，在确保安全情况下堵漏。用干燥的砂土或 类似物质吸收，然后收集于密闭容器中作好标记，等待处理。如大量泄漏，利用围堤收容， 然后收集、转移、回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:39:43', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4350, 4493, NULL, NULL, NULL, '无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。不要触摸或穿越泄漏物。不 要触摸破损的容器或泄漏物质除非穿着合适的防护服。保证充分的通风。清除所有点火源。 采取防静电措施。迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。使用个人', NULL, NULL, NULL, NULL, '2026-03-06 14:39:43', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4351, 4494, NULL, NULL, NULL, '疏散泄漏污染区人员至安全区，禁止无关人员进入污染区，建议应急处理人员戴自给式呼 吸器，穿化学防护服。用不燃性分散剂制成的乳液刷洗，或用砂土、蛭石或其它惰性材料 吸 收，运至废物处理场所。用水刷洗泄漏污染区，经稀释的污水放入废水系统。如大量 泄漏，利用围堤收容，然后收集、转移、回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:39:44', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4352, 4495, NULL, NULL, NULL, '疏散泄漏污染区人员至安全区，禁止无关人员进入污染区，建议应急处理人员戴自给式呼吸器，穿化学防护服。不要直接接触泄漏物，在确保安全情况下堵漏。收集转移回收。无法收集的泄漏物应妥善处理，防止污染环境。', NULL, NULL, NULL, NULL, '2026-03-06 14:39:45', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4353, 4496, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至安全区，并进行隔离，严格限制出入。切断火源。建议应急处理人员戴自给正压式呼吸器，穿防毒服。不要直接接触泄漏物。尽可能切断泄漏源。防止流入下水道、排洪沟等限制性空间。小量泄漏：用砂土或其它不燃材料吸附或吸收。大量泄漏：构筑围堤或挖坑收容。用泵转移至槽车或专用收集器内，回收或运至废物处理场所处置。', NULL, NULL, NULL, NULL, '2026-03-06 14:39:45', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4354, 4497, NULL, NULL, NULL, '切断火源。戴好防毒面具，穿一般消防防护服。在确保安全情况下堵漏。用不燃性分散剂制成的孔液刷洗，经稀释的洗液放入废水系统。如大量泄漏，利用围堤收容，然后收集、转移、回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:39:45', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4355, 4498, NULL, NULL, NULL, '严禁用水处理。隔离泄漏污染区，限制出入。不要在泄漏物上喷水或让水进入容器中。消除所有点火源。建议应急处理人员戴防尘口罩（全面罩），穿防静电工作服。避免吸入粉尘。用干燥的砂土或其他不燃材料覆盖泄漏物，然后收集于密闭容器中。如大量泄漏，收集回收或运至废物处理场所处置。', NULL, NULL, NULL, NULL, '2026-03-06 14:39:45', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4356, 4499, NULL, NULL, NULL, '应急处理人员必须佩戴正压自给式呼吸器，穿全身防毒服。隔离泄漏污染区，周围设警告标志。切断火源。不要直接接触泄漏物。禁止向泄漏物直接喷水，更不要让水进入包装容器内。迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。', NULL, NULL, NULL, NULL, '2026-03-06 14:39:47', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4357, 4500, NULL, NULL, NULL, '严禁用水处理。应急处理人员必须佩戴正压自给式呼吸器，穿全身防毒服。隔离泄漏污染区，限制出入。不要在泄漏物上喷水或让水进入容器中。迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。', NULL, NULL, NULL, NULL, '2026-03-06 14:39:47', '', NULL);
