INSERT INTO `msds_leak_response` VALUES (4359, 4502, NULL, NULL, NULL, '应急处理：隔离泄漏污染区，限制出入。不要在泄漏物上喷水或让水进入容器中。建议应急处理人员戴自给正压式呼吸器，穿防静电工作服。避免扬尘，小心扫起，置于袋中转移至安全场所。若大量泄漏，用塑料布、帆布覆盖。收集回收或运至废物处理场所处置。', NULL, NULL, NULL, NULL, '2026-03-06 14:39:47', '', NULL);
