INSERT INTO `msds_leak_response` VALUES (4569, 4712, NULL, NULL, NULL, '隔离泄漏污染区，限制出入。切断火源。建议应急处理人员戴防尘面具（全面罩），穿防毒服。 应急处理： 不要直接接触泄漏物。避免震动、撞击和摩擦。小量泄漏：使用无火花工具收集于干燥、洁净、 有盖的容器中，转移至安全场所。大量泄漏：与有关技术部门联系，确定清除方法。', NULL, NULL, NULL, NULL, '2026-03-06 14:41:27', '', NULL);
