INSERT INTO `msds_leak_response` VALUES (4604, 4747, NULL, NULL, NULL, '隔离泄漏污染区，周围设警告标志，切断火源。建议应急处理人员戴好防毒面具，穿一般 消防防护服。禁止向泄漏物直接喷水，更不要让水进入包装容器内。用干燥砂土混合，使 用不产生火花的工具收集于一个密闭的容器中，倒至空旷地方深埋。被污染地面用肥皂或 洗涤剂刷洗，经稀释的污水放入废水系统。如大量泄漏，收集回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:41:38', '', NULL);
