INSERT INTO `msds_leak_response` VALUES (4607, 4750, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至安全区，并进行隔离，严格限制出入。切断火源。建议应急处 理人员戴自给正压式呼吸器，穿防毒服。不要直接接触泄漏物。尽可能切断泄漏源。防止 应急处理： 流入下水道、排洪沟等限制性空间。小量泄漏：用砂土、干燥石灰或苏打灰混合。大量泄 漏：构筑围堤或挖坑收容。用泡沫覆盖，降低蒸气灾害。用泵转移至槽车或专用收集器内， 回收或运至废物处理场所处置。', NULL, NULL, NULL, NULL, '2026-03-06 14:41:40', '', NULL);
