INSERT INTO `msds_leak_response` VALUES (4659, 4802, NULL, NULL, NULL, '疏散泄漏污染区人员至安全区，禁止无关人员进入污染区，应急处理人员戴自给式呼吸器，穿 厂商特别推荐的化学防护服(完全隔离)。不要直接接触泄漏物，在确保安全情况下堵漏。撒 湿冰或冰水冷却，用干燥的砂土或类似物质吸收，然后收集运至废物处理场所。如大量泄漏， 利用围堤收容，然后收集、转移、回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:42:02', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4660, 4803, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至上风处，并隔离直至气体散尽。建议应急处理人员戴正压自给式呼吸器，穿厂商特别推荐的化学防护服（完全隔离）。切断气源，喷水雾稀释溶解，但不要对泄漏点直接喷水。然后抽排（室内）或强力通风（室外）。如有可能，将残余气或漏出气用排风机送至通风橱内。', NULL, NULL, NULL, NULL, '2026-03-06 14:42:02', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4661, 4804, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至上风处，并进行隔离，严格限制出入。建议应急处理人员戴正压自给式呼吸器，穿防毒服。尽可能切断泄漏源。防止流入下水道、排洪沟等限制性空间。小量泄漏：用砂土、蛭石或其他惰性材料吸收。大量泄漏：构筑围堤或挖坑收容。用泵转移至槽车或专用收集器内，回收或运至废物处理场所处置。', NULL, NULL, NULL, NULL, '2026-03-06 14:42:04', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4662, 4805, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至上风处，并进行隔离，严格限制出入。建议应急处理人员戴自给正压式呼吸器，穿一般作业工作服。尽可能切断泄漏源。合理通风，加速扩散。如有可能，即时使用工具将漏出气体送至通风橱内或排风机处。', NULL, NULL, NULL, NULL, '2026-03-06 14:42:04', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4663, 4806, NULL, NULL, NULL, '隔离泄漏污染区，周围设警告标志，建议应急处理人员戴好防毒面具，穿化学防护服。用 大量水冲洗，经稀释的污水放入废水系统。也可以小心扫起，倒至空旷地方深埋。如大量 泄漏，收集回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:42:04', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4664, 4807, NULL, NULL, NULL, '戴好防毒面具和手套。用洁净的铲子收集于干燥净洁有盖的容器中，运至废物处理场所。如大量泄漏，收集回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:42:05', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4665, 4808, NULL, NULL, NULL, '隔离泄漏污染区，限制出入。建议应急处理人员戴防尘口罩（全面罩），穿防毒服。避免直接接触泄漏物。小量泄漏：避免扬尘，用洁净的铲子收集于干燥、洁净、有盖的容器中。大量泄漏：用塑料布、帆布覆盖，减少飞散。然后收集回收或运至废物处理场所处置。', NULL, NULL, NULL, NULL, '2026-03-06 14:42:05', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4666, 4809, NULL, NULL, NULL, '疏散泄漏污染区人员至安全区，禁止无关人员进入污染区，建议应急处理人员戴自给式呼吸器，穿化学防护服。禁止向泄漏物直接喷水，更不要让水进入包装容器内。不要直接接触泄漏物，用砂土、蛭石或其它惰性材料吸收，收集于密闭容器中作好标记，等待处理。也可以将污染地面撒上苏打灰，用水冲洗，经稀释的洗水放入废水系统。如大量泄漏，利用围堤收容，然后收集、转移、回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:42:05', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4667, 4810, NULL, NULL, NULL, '疏散泄漏污染区人员至安全区，禁止无关人员进入污染区，切断火源。应急处理人员戴自给式呼吸器，穿化学防护服。不要直接接触泄漏物，在确保安全情况下堵漏。禁止泄漏物进入受限制的空间（如下水道等），以避免发生爆炸。喷水雾可减少蒸发。用不燃性分散剂制成的乳液刷洗，经稀释的洗液放入废水系统。如大量泄漏，利用围堤收容，然后收集、转移、回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:42:06', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4668, 4811, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至上风处，并隔离直至气体散尽，应急处理人员戴正压自给式呼吸 器，穿化学防护服。在确保安全情况下堵漏。喷水雾减慢挥发(或扩散)，但不要对泄漏物或 泄漏点直接喷水。抽排(室内)或强力通风(室外)。漏气容器不能再用，且要经过技术处理以', NULL, NULL, NULL, NULL, '2026-03-06 14:42:06', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4669, 4812, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至上风处，并进行隔离，严格限制出入。建议应急处理人员戴自给正压式呼吸器，穿一般作业工作服。尽可能切断泄漏源。合理通风，加速扩散。如有可能，即时使用专用回收装置收集泄漏气体，避免排放到大气中。泄漏容器应妥善处理，修复、检验合格后方可重新使用。', NULL, NULL, NULL, NULL, '2026-03-06 14:42:06', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4670, 4813, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至上风处，并隔离直至气体散尽。应急处理人员戴正压自给式呼吸器，穿化学防护服。在确保安全情况下堵漏。喷水雾减慢挥发（或扩散），但不要对泄漏物或泄漏点直接喷水。抽排（室内）或强力通风（室外）。漏气容器不能再用，且要经过技术处理以清除可能剩下的气体。', NULL, NULL, NULL, NULL, '2026-03-06 14:42:07', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4671, 4814, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:07', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4672, 4815, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至上风处，并进行隔离，严格限制出入。切断火源。建议应急处理人员戴自给正压式呼吸器，穿一般作业工作服。尽可能切断泄漏源。合理通风，加速扩散。如有可能，将漏出气用排风机送至空旷地方或装设适当喷头烧掉。漏气容器要妥善处理，修复、检验后再用。', NULL, NULL, NULL, NULL, '2026-03-06 14:42:07', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4673, 4816, NULL, NULL, NULL, '切断火源。戴好口罩和手套。用砂土、干燥石灰或苏打灰混合，然后在专用废弃场所深层掩埋。 如大量泄漏，收集回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:42:07', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4674, 4817, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至安全区，并进行隔离，严格限制出入。切断火源。建议应急处理人员戴自给正压式呼吸器，穿防毒服。尽可能切断泄漏源。防止流入下水道、排洪沟等限制性空间。小量泄漏：用砂土、蛭石或其它惰性材料吸收。或在保证安全情况下，就地焚烧。大量泄漏：构筑围堤或挖坑收容。用泡沫覆盖，降低蒸气灾害。用防爆泵转移至槽车或专用收集器内，回收或运至废物处理场所处置。', NULL, NULL, NULL, NULL, '2026-03-06 14:42:07', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4675, 4818, NULL, NULL, NULL, '疏散泄漏污染区人员至安全区，禁止无关人员进入污染区，切断火源。建议应急处理人员 戴好防毒面具，穿一般消防防护服。用砂土吸收，使用不产生火花的工具铲入提桶，运至 水系统。如大量泄漏，利用围堤收容，然后收集、转移、回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:42:09', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4676, 4819, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至安全区，并进行隔离，严格限制出入。切断火源。建议应急处理人员戴正压自给式空气呼吸器（SCBA），穿防毒、防化服。不要直接接触泄漏物。尽可能切断泄漏源。防止流入下水道、排洪沟等限制性空间。小量泄漏：用砂土、蛭石或其他惰性材料吸收，收集于密闭容器中。大量泄漏：构筑围堤或挖坑收容，用泵转移至槽车或专用收集器内，回收或运至废物处理场所处置。泄漏区域应进行通风，并监测空气中有毒蒸气浓度。被污染的地面和设备应使用适当的清洁剂进行清洗，清洗废液应作为危险废物处理。', NULL, NULL, NULL, NULL, '2026-03-06 14:42:09', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4677, 4820, NULL, NULL, NULL, '隔离泄漏污染区，限制出入。切断火源。建议应急处理人员戴防尘面具（全面罩），穿防毒服。 小量泄漏：用洁净的铲子收集于干燥、洁净、有盖的容器中。大量泄漏：收集回收或运至废物', NULL, NULL, NULL, NULL, '2026-03-06 14:42:09', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4678, 4821, NULL, NULL, NULL, '疏散泄漏污染区人员至安全区，禁止无关人员进入污染区，建议应急处理人员戴好防毒面 具，穿化学防护服。用砂土、蛭石或其它惰性材料吸收，然后收集运至废物处理场所。也 可以用大量水冲洗，经稀释的污水放入废水系统。如大量泄漏，利用围堤收容，然后收集、 转移、回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:42:09', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4679, 4822, NULL, NULL, NULL, '疏散泄漏污染区人员至安全区，禁止无关人员进入污染区，切断火源。应急处理人员戴自给式 呼吸器，穿一般消防防护服。不要直接接触泄漏物，在确保安全情况下堵漏。喷雾状水，减少 应急处理： 蒸发。用砂土或其它不燃性吸附剂混合吸收，然后收集运至废物处理场所。如大量泄漏，利用 围堤收容，然后收集、转移、回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:42:11', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4680, 4823, NULL, NULL, NULL, '隔离泄漏污染区，限制出入。切断火源。建议应急处理人员戴自吸过滤式防毒面具（全面罩），穿防毒服。避免扬尘，小心扫起，置于袋中转移至安全场所。若大量泄漏，用塑料布、帆布覆盖，减少飞散。收集回收或运至废物处理场所处置。', NULL, NULL, NULL, NULL, '2026-03-06 14:42:11', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4681, 4824, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至安全区，并进行隔离，严格限制出入。切断火源。建议应急处理人员戴自给正压式呼吸器，穿防毒服。不要直接接触泄漏物。尽可能切断泄漏源。', NULL, NULL, NULL, NULL, '2026-03-06 14:42:11', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4682, 4825, NULL, NULL, NULL, '保证充分的通风。清除所有点火源。迅速将人员撤离到安全区域，远离泄漏区域并处于上风向。采取措施防止进一步的泄漏或溢出。避免排放到周围环境中。少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。清除所有点火源，并采用防火花工具和防爆设备。', NULL, NULL, NULL, NULL, '2026-03-06 14:42:11', '', NULL);
