INSERT INTO `msds_leak_response` VALUES (4749, 4892, NULL, NULL, NULL, '疏散泄漏污染区人员至安全区，禁止无关人员进入污染区，切断火源。建议应急处理人员戴自给式呼吸器，穿化学防护服。不要直接接触泄漏物，禁止泄漏物进入受限制的空间（如下水道、地下室等）。用沙土、干燥石灰或苏打灰混合，收集于密闭容器中作好标记，等待处理。用水刷洗泄漏污染区，对污染地带进行通风。如大量泄漏，利用围堤收容，然后收集、转移、回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:42:38', '', NULL);
