INSERT INTO `msds_leak_response` VALUES (4798, 4941, NULL, NULL, NULL, '隔离泄漏污染区，限制出入。切断火源。建议应急处理人员戴自给正压式呼吸器，穿防静电工作服。不要直接接触泄漏物。小量泄漏：避免扬尘，用洁净的铲子收集于干燥、洁净、有盖的容器中。转移回收。大量泄漏：用塑料布、帆布覆盖。在专家指导下清除。', NULL, NULL, NULL, NULL, '2026-03-06 14:42:58', '', NULL);
