INSERT INTO `msds_leak_response` VALUES (4825, 4968, NULL, NULL, NULL, '隔离泄漏污染区，限制出入。建议应急处理人员戴防尘口罩（全面罩），穿防酸碱工作服。不要直接接触泄漏物。小量泄漏：避免扬尘，用洁净的铲子收集于干燥、洁净、有盖的容器中。大量泄漏：用塑料布、帆布覆盖，减少飞散。在专家指导下清除。', NULL, NULL, NULL, NULL, '2026-03-06 14:43:11', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4826, 4969, NULL, NULL, NULL, '隔离泄漏污染区，周围设警告标志，建议应急处理人员戴好防毒面具，穿化学防护服。不 要直接接触泄漏物，用大量水冲洗，经稀释的洗水放入废水系统。也可以用沙土、干燥石 灰或苏打灰混合，然后以少量加入大量水中，调节至中性，再放入废水系统。如大量泄漏， 收集回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:43:11', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4827, 4970, NULL, NULL, NULL, '无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。不要触摸或穿越泄漏物。不要触摸破损的容器或泄漏物质除非穿着合适的防护服。保证充分的通风。清除所有点火源。采取防静电措施。迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。使用个人防护装备。避免吸入粉尘。用惰性吸附材料吸收泄漏物。将泄漏物收集到合适的容器中，按照危险废物处理。', NULL, NULL, NULL, NULL, '2026-03-06 14:43:11', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4828, 4971, NULL, NULL, NULL, '隔离泄漏污染区，限制出入。建议应急处理人员戴防尘面具（全面罩），穿防毒服。不要直接 接触泄漏物。小量泄漏：避免扬尘，用洁净的铲子收集于干燥、洁净、有盖的容器中。大量泄 漏：用塑料布、帆布覆盖。然后收集回收或运至废物处理场所处置。', NULL, NULL, NULL, NULL, '2026-03-06 14:43:11', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4829, 4972, NULL, NULL, NULL, '无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。不要触摸或穿越泄漏物。 不要触摸破损的容器或泄漏物质除非穿着合适的防护服。保证充分的通风。清除所有点 火源。采取防静电措施。迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。', NULL, NULL, NULL, NULL, '2026-03-06 14:43:13', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4830, 4973, NULL, NULL, NULL, '疏散泄漏污染区人员至安全区，禁止无关人员进入污染区，建议应急处理人员戴好防毒 面具，穿化学防护服。禁止向泄漏物直接喷水，更不要让水进入包装容器内。不要直接接 触泄漏物，用砂土吸收，铲入提桶，倒至空旷地方深埋。被污染地面用肥皂或洗涤剂刷洗， 应急处理： 经稀释的污水放入废水系统。如大量泄漏，利用围堤收容，然后收集、转移、回收或无害 处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:43:13', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4831, 4974, NULL, NULL, NULL, '隔离泄漏污染区，周围设警告标志，切断火源。应急处理人员戴自给式呼吸器，穿化学防护 应急处理： 服。不要直接接触泄漏物，用清洁的铲子收集于干燥洁净有盖的容器中，运至废物处理场所。 如大量泄漏，收集回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:43:13', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4832, 4975, NULL, NULL, NULL, '立即疏散泄漏区域人员至安全区域，建立隔离区（建议半径≥50米）。应急处理人员必须佩戴自给式呼吸器（SCBA）、化学防护服和丁腈手套。从上风向进入现场，避免直接接触泄漏物。切断火源，禁止无关人员进入。如泄漏量大或进入水体，应立即报告当地环保部门（中国环保举报热线：12369）', NULL, NULL, NULL, NULL, '2026-03-06 14:43:13', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4833, 4976, NULL, NULL, NULL, '无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。不要触摸或穿越泄漏物。 不要触摸破损的容器或泄漏物质除非穿着合适的防护服。保证充分的通风。清除所有点 火源。采取防静电措施。迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。', NULL, NULL, NULL, NULL, '2026-03-06 14:43:14', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4834, 4977, NULL, NULL, NULL, '大量泄漏时，围堤防止蔓延；喷水减少泄漏物挥发量；避免吸入气体和接触泄漏物；处理', NULL, NULL, NULL, NULL, '2026-03-06 14:43:14', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4835, 4978, NULL, NULL, NULL, '疏散泄漏污染区人员至安全区，禁止无关人员进入污染区，建议应急处理人员戴好防毒面 具，穿化学防护服。不要直接接触泄漏物，用大量水冲洗，经稀释的污水放入废水系统。 如大量泄漏，利用围堤收容，然后收集、转移、回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:43:14', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4836, 4979, NULL, NULL, NULL, '无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。不要触摸或穿越泄漏物。 不要触摸破损的容器或泄漏物质除非穿着合适的防护服。保证充分的通风。清除所有点 火源。采取防静电措施。迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。', NULL, NULL, NULL, NULL, '2026-03-06 14:43:15', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4837, 4980, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至上风处，并进行隔离，严格限制出入。切断火源。建议应急处理人员戴自给正压式呼吸器，穿防静电工作服。尽可能切断泄漏源。合理通风，加速扩散。', NULL, NULL, NULL, NULL, '2026-03-06 14:43:16', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4838, 4981, NULL, NULL, NULL, '迅速撤离泄漏区域并处于上风方向。使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。小量泄漏：用砂土或其它不燃材料吸附或吸收。收集于密闭容器中。大量泄漏：构筑围堤或挖坑收容。', NULL, NULL, NULL, NULL, '2026-03-06 14:43:17', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4839, 4982, NULL, NULL, NULL, '隔离泄漏污染区，周围设警告标志，切断火源。建议应急处理人员戴自给式呼吸器，穿化学防护服。禁止向泄漏物直接喷水，更不要让水进入包装容器内。用干燥砂土混合，小心扫起，使用不产生火花的工具收集送至空旷地方，倒入大量水中，静置24h后加硫酸钠使钡盐沉淀后掩埋，经稀释的污水放入废水系统。如大量泄漏，收集回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:43:17', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4840, 4983, NULL, NULL, NULL, '隔离泄漏污染区，限制出入。切断火源。建议应急处理人员戴自给正压式呼吸器，穿化学防护服。不要直接接触泄漏物。小量泄漏：避免扬尘，使用无火花工具收集于干燥、洁净、有盖的容器中，转移至安全场所。大量泄漏：用塑料布、帆布覆盖。与有关技术部门联系。', NULL, NULL, NULL, NULL, '2026-03-06 14:43:17', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4841, 4984, NULL, NULL, NULL, '隔离泄漏污染区，周围设警告标志，切断火源。建议应急处理人员戴好口罩、护目镜，穿工作服。禁止向泄漏物直接喷水，更不要让水进入包装容器内。用干燥砂土混合，小心扫起，使用不产生火花的工具收集倒至空旷地方深埋。将污染地面撒上无水碳酸钠，用水冲洗，经稀释的污水放入废水系统。如大量泄漏，收集回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:43:17', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4842, 4985, NULL, NULL, NULL, '隔离泄漏污染区，限制出入。切断火源。建议应急处理人员戴自给正压式呼吸器，穿防毒服。不要直接接触泄漏物。小量泄漏：避免扬尘，使用无火花工具收集于干燥、洁净、有盖的容器中，转移至安全场所。大量泄漏：用塑料布、帆布覆盖。与有关技术部门联系。', NULL, NULL, NULL, NULL, '2026-03-06 14:43:18', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4843, 4986, NULL, NULL, NULL, '隔离泄漏污染区，限制出入。切断火源。建议应急处理人员戴自给正压式呼吸器，穿防毒服。不要直接接触泄漏物。小量泄漏：避免扬尘，使用无火花工具收集于干燥、洁净、有盖的容器中，转移至安全场所。大量泄漏：用塑料布、帆布覆盖。与有关技术部门联系。', NULL, NULL, NULL, NULL, '2026-03-06 14:43:19', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4844, 4987, NULL, NULL, NULL, '隔离泄漏污染区，周围设警告标志，切断火源。建议应急处理人员戴好防毒面具，穿化学防护服。禁止向泄漏物直接喷水，更不要让水进入包装容器内。用干燥砂土混合，小心扫起，使用不产生火花的工具收集送至空旷地方，倒入大量水中，经分解稀释后的污水放入废水系统。如大量泄漏，收集回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:43:19', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4845, 4988, NULL, NULL, NULL, '隔离泄漏污染区，限制出入。切断火源。建议应急处理人员戴自给正压式呼吸器，穿化学防护服。不要直接接触泄漏物。小量泄漏：避免扬尘，使用无火花工具收集于干燥、洁净、有盖的容器中，转移至安全场所。大量泄漏：用塑料布、帆布覆盖。与有关技术部门联系。', NULL, NULL, NULL, NULL, '2026-03-06 14:43:19', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4846, 4989, NULL, NULL, NULL, '保证充分的通风。清除所有点火源。迅速将人员撤离到安全区域，远离泄漏区域并处于上风处。采取措施防止进一步的泄漏或溢出。避免排放到周围环境中。少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。清除所有点火源，并采用防火花工具和防爆设备。', NULL, NULL, NULL, NULL, '2026-03-06 14:43:19', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4847, 4990, NULL, NULL, NULL, '隔离泄漏污染区，周围设警告标志，切断火源。建议应急处理人员戴好防毒面具，穿一般消防防护服。禁止向泄漏物直接喷水，更不要让水进入包装容器内。用干燥的砂土或类似材料收集，小心扫起，使用不产生火花的工具收集倒至空旷地方深埋。将污染地面撒上无水碳酸钠，用水冲洗，经稀释的污水放入废水系统。如大量泄漏，收集回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:43:21', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4848, 4991, NULL, NULL, NULL, '隔离泄漏污染区，限制出入。切断火源。建议应急处理人员戴自给正压式呼吸器，穿防毒服。小量泄漏：避免扬尘，使用无火花工具收集于干燥、洁净、有盖的容器中，转移至安全场所。大量泄漏：用塑料布、帆布覆盖。与有关技术部门联系，确定清除方法。', NULL, NULL, NULL, NULL, '2026-03-06 14:43:21', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4849, 4992, NULL, NULL, NULL, '隔离泄漏污染区，周围设警告标志，切断火源。建议应急处理人员戴好口罩、护目镜，穿工作服。冷却，防止震动、撞击和摩擦，禁止向泄漏物直接喷水，更不要让水进入包装容器内。用干燥砂土混合，小心扫起，收集倒至空旷地方深埋。将污染地面撒上无水碳酸钠，用水冲洗，经稀释的污水放入废水系统。如大量泄漏，收集回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:43:21', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4850, 4993, NULL, NULL, NULL, '切断火源。戴好口罩和手套。用砂土、干燥石灰或苏打灰混合，然后在专用废弃场所深层掩埋。如大量泄漏，收集回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:43:21', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4851, 4994, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至安全区，并立即隔离150m，严格限制出入。切断火源。建议应急处理人员戴自给正压式呼吸器，穿防毒服。不要直接接触泄漏物。尽可能切断泄漏源。防止流入下水道、排洪沟等限制性空间。小量泄漏：用砂土或其它不燃材料吸附或吸收。收集于密闭容器中。大量泄漏：构筑围堤或挖坑收容。用泡沫覆盖，降低蒸气灾害。喷雾状水冷却和稀释蒸气，保护现场人员，但不要对泄漏点直接喷水。用防爆泵转移至槽车或专用收集器内，回收或运至废物处理场所处置。', NULL, NULL, NULL, NULL, '2026-03-06 14:43:22', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4852, 4995, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至安全区，并进行隔离，严格限制出入。建议应急处理人员戴自给正压式呼吸器，穿防酸碱工作服。不要直接接触泄漏物。尽可能切断泄漏源。小量泄漏：用砂土、干燥石灰或苏打灰混合。也可以用大量水冲洗，洗水稀释后放入废水系统。大量泄漏：构筑围堤或挖坑收容。用泵转移至槽车或专用收集器内，回收或运至废物处理场所处置。', NULL, NULL, NULL, NULL, '2026-03-06 14:43:23', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4853, 4996, NULL, NULL, NULL, '隔离泄漏污染区，限制出入。建议应急处理人员戴防尘面具（全面罩），穿防酸碱工作服。不要直接接触泄漏物。小量泄漏：避免扬尘，用洁净的铲子收集于干燥、洁净、有盖的容器中。大量泄漏：用塑料布、帆布覆盖。然后收集回收或运至废物处理场所处置。', NULL, NULL, NULL, NULL, '2026-03-06 14:43:23', '', NULL);
