INSERT INTO `msds_leak_response` VALUES (4888, 5031, NULL, NULL, NULL, '隔离泄漏污染区，限制出入。切断火源。建议应急处理人员戴防尘面具（全面罩），穿防毒服。小量泄漏：用洁净的铲子收集于干燥、洁净、有盖的容器中。大量泄漏：收集回收或运至废物处理场所处置。', NULL, NULL, NULL, NULL, '2026-03-06 14:43:37', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4889, 5032, NULL, NULL, NULL, '疏散泄漏污染区人员至安全区，禁止无关人员进入污染区，切断火源。建议应急处理人员戴自给式呼吸器，穿化学防护服。不要直接接触泄漏物，在确保安全情况下堵漏。喷雾状水，减少蒸发。用沙土或其它不燃性吸附剂混合吸收，然后收集运至废物处理场所处置。如大量泄漏，利用围堤收容，然后收集、转移、回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:43:37', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4890, 5033, NULL, NULL, NULL, '戴好口罩和手套。使用无火花工具收集运到空旷处焚烧。如大量泄漏，收集回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:43:37', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4891, 5034, NULL, NULL, NULL, '隔离泄漏污染区，周围设警告标志，切断火源。应急处理人员戴好防毒面具，穿化学防护服。不要直接接触泄漏物，用洁净的铲子收集于干燥净洁有盖的容器中，运至废物处理场所。如大量泄漏，收集回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:43:38', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4892, 5035, NULL, NULL, NULL, '疏散泄漏污染区人员至安全区，禁止无关人员进入污染区，切断火源。建议应急处理人员戴自给式呼吸器，穿化学防护服。不要直接接触泄漏物，在确保安全情况下堵漏。用沙土、干燥石灰或苏打灰混合，然后收集运至废物处理场所处置。也可以用不燃性分散剂制成的乳液刷洗，经稀释的洗水放入废水系统。如大量泄漏，利用围堤收容，然后收集、转移、回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:43:39', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4893, 5036, NULL, NULL, NULL, '迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。不要触摸或穿越泄漏物。不要触摸破损的容器或泄漏物质除非穿着合适的防护服。保证充分的通风。清除所有点火源。采取防静电措施。', NULL, NULL, NULL, NULL, '2026-03-06 14:43:39', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4894, 5037, NULL, NULL, NULL, '隔离泄漏污染区，限制出入。建议应急处理人员戴防尘口罩（全面罩），穿防毒服。避免扬尘，小心扫起，置于袋中转移至安全场所。若大量泄漏，用塑料布、帆布覆盖。收集回收或运至废物处理场所处置。', NULL, NULL, NULL, NULL, '2026-03-06 14:43:39', '', NULL);
INSERT INTO `msds_leak_response` VALUES (4895, 5038, NULL, NULL, NULL, '消除所有点火源。根据液体流动和蒸气扩散的影响区域划定警戒区，无关人员从侧风、上风向撤离至安全区。应急处理人员戴正压自给式呼吸器，穿防毒服。作业时使用的工具应为无火花工具。不要直接接触泄漏物。', NULL, NULL, NULL, NULL, '2026-03-06 14:43:40', '', NULL);
