INSERT INTO `msds_leak_response` VALUES (4987, 5130, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至上风处，并立即隔离150m，严格限制出入。建议应急处理人员戴自给正压式呼吸器，穿防酸碱工作服。尽可能切断泄漏源。若是气体，合理通风，加速扩散。如有可检验后再用。若是液体，用砂土、蛭石或其它惰性材料吸收。若大量泄漏，构筑围堤或挖坑收容。喷雾状水冷却和稀释蒸汽，保护现场人员，但不要对泄漏点直接喷水。用防爆泵转移至槽车或专用收集器内，回收或运至废物处理场所处置。', NULL, NULL, NULL, NULL, '2026-03-06 14:44:18', '', NULL);
