INSERT INTO `msds_leak_response` VALUES (5083, 5226, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至安全区，并进行隔离，严格限制出入。切断火源。建议应急处 理人员戴自给正压式呼吸器，穿防静电工作服。尽可能切断泄漏源。防止流入下水道、排 应急处理： 洪沟等限制性空间。小量泄漏：用砂土、干燥石灰或苏打灰混合。也可以用不燃性分散剂 制成的乳液刷洗，洗液稀释后放入废水系统。大量泄漏：构筑围堤或挖坑收容。用泡沫覆 盖，降低蒸气灾害。用防爆泵转移至槽车或专用收集器内，回收或运至废物处理场所处置。', NULL, NULL, NULL, NULL, '2026-03-06 14:45:00', '', NULL);
INSERT INTO `msds_leak_response` VALUES (5084, 5227, NULL, NULL, NULL, '疏散泄漏污染区人员至安全区，禁止无关人员进入污染区，建议应急处理人员戴自给式呼 吸器，穿化学防护服。不要直接接触泄漏物，禁止向泄漏物直接喷水，更不要让水进入包 装容器内。用砂土、干燥石灰或苏打灰混合，使用不产生火花的工具收集于一个密闭的容 应急处理： 器中，运至废物处理场所。也可以用不燃性分散剂制成的乳液刷洗，如大量泄漏，利用围 堤收容，然后收集、转移、回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:45:00', '', NULL);
INSERT INTO `msds_leak_response` VALUES (5085, 5228, NULL, NULL, NULL, '隔离泄漏污染区，限制出入。建议应急处理人员戴防尘口罩，穿防毒服。避免直接接触泄漏物。小量泄漏：避免扬尘，用洁净的铲子收集于干燥、洁净、有盖的容器中。大量泄漏：用塑料布、帆布覆盖，减少飞散。收集回收或运至废物处理场所处置。', NULL, NULL, NULL, NULL, '2026-03-06 14:45:00', '', NULL);
INSERT INTO `msds_leak_response` VALUES (5086, 5229, NULL, NULL, NULL, '切断火源。戴好口罩和手套。收集回收。', NULL, NULL, NULL, NULL, '2026-03-06 14:45:00', '', NULL);
INSERT INTO `msds_leak_response` VALUES (5087, 5230, NULL, NULL, NULL, '隔离泄漏污染区，周围设警告标志，建议应急处理人员戴好防毒面具，穿相应的工作服，避免扬尘，小心扫起，回收。', NULL, NULL, NULL, NULL, '2026-03-06 14:45:02', '', NULL);
INSERT INTO `msds_leak_response` VALUES (5088, 5231, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至安全区，并进行隔离，严格限制出入。切断火源。建议应急处理人员戴自给正压式呼吸器，穿防静电工作服。尽可能切断泄漏源。防止流入下水道、排洪沟等限制性空间。', NULL, NULL, NULL, NULL, '2026-03-06 14:45:02', '', NULL);
INSERT INTO `msds_leak_response` VALUES (5089, 5232, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至安全区，并进行隔离，严格限制出入。切断火源。建议应急处理人员戴自给正压式呼吸器，穿防静电工作服。尽可能切断泄漏源。防止流入下水道、排洪沟等限制性空间。小量泄漏：用活性炭或其它惰性材料吸收。也可以用不燃性分散剂制成的乳液刷洗，洗液稀释后放入废水系统。大量泄漏：构筑围堤或挖坑收容。用泡沫覆盖，降低蒸气灾害。用防爆泵转移至槽车或专用收集器内，回收或运至废物处理场所处置。', NULL, NULL, NULL, NULL, '2026-03-06 14:45:02', '', NULL);
INSERT INTO `msds_leak_response` VALUES (5090, 5233, NULL, NULL, NULL, '首先切断一切火源，戴好防毒面具与手套；勿使其燃烧，同时关闭阀门等措施，制止渗漏；并用雾状水保护关闭阀门的人员。对残余废气或钢瓶泄漏出来的气体用排风机排送至空旷处。', NULL, NULL, NULL, NULL, '2026-03-06 14:45:04', '', NULL);
INSERT INTO `msds_leak_response` VALUES (5091, 5234, NULL, NULL, NULL, '首先切断一切火源，戴好防毒面具与手套；用砂土吸收，倒至空旷地方掩埋；对污染地面用肥皂或洗涤刷洗，经稀释的污水放入废水系统。', NULL, NULL, NULL, NULL, '2026-03-06 14:45:04', '', NULL);
INSERT INTO `msds_leak_response` VALUES (5092, 5235, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至安全区，并进行隔离，严格限制出入。切断火源。建议应急处理人员戴自给正压式呼吸器，穿防毒服。不要直接接触泄漏物。尽可能切断泄漏源。防止流入下水道、排洪沟等限制性空间。小量泄漏：用砂土、干燥石灰或苏打灰混合。也可以用大量水冲洗，洗水稀释后放入废水系统。大量泄漏：构筑围堤或挖坑收容。用泡沫覆盖，降低蒸气灾害。用防爆泵转移至槽车或专用收集器内，回收或运至废物处理场所处置。', NULL, NULL, NULL, NULL, '2026-03-06 14:45:05', '', NULL);
INSERT INTO `msds_leak_response` VALUES (5093, 5236, NULL, NULL, NULL, '疏散泄漏污染区人员至安全区，禁止无关人员进入污染区，切断火源。建议应急处理人员 戴好防毒面具，穿一般消防防护服。在确保安全情况下堵漏。喷水雾会减少蒸发，但不能 降低泄漏物在受限制空间内的易燃性。用活性炭或其它惰性材料吸收，然后收集运至废物 处理场所处置。如大量泄漏，利用围堤收容，然后收集、转移、回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:45:05', '', NULL);
INSERT INTO `msds_leak_response` VALUES (5094, 5237, NULL, NULL, NULL, '消除所有点火源。根据液体流动和蒸气扩散的影响区域划定警戒区，无关人员从侧风、上风向撤离至安全区。建议应急处理人员戴正压自给式呼吸器，穿防毒、防静电服。作业时使用的工具应为无火花工具。禁止直接接触泄漏物。', NULL, NULL, NULL, NULL, '2026-03-06 14:45:05', '', NULL);
INSERT INTO `msds_leak_response` VALUES (5095, 5238, NULL, NULL, NULL, '保证充分的通风。清除所有点火源。迅速将人员撤离到安全区域，远离泄漏区域并处于上风处。采取措施防止进一步的泄漏或溢出。避免排放到周围环境中。少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。清除所有点火源，并采用防火花工具和防爆设备。', NULL, NULL, NULL, NULL, '2026-03-06 14:45:06', '', NULL);
INSERT INTO `msds_leak_response` VALUES (5096, 5239, NULL, NULL, NULL, '消除所有火源。根据液体流动和蒸气扩散的影响区域划定警戒区，无关人员从侧风、上风向撤离至安全区。应急处理人员戴正压自给式呼吸器，穿防毒服。作业时使用的工具应为无火花工具。不要直接接触泄漏物。尽可能切断泄漏源。防止泄漏物进入下水道、地下室或限制性空间。', NULL, NULL, NULL, NULL, '2026-03-06 14:45:08', '', NULL);
INSERT INTO `msds_leak_response` VALUES (5097, 5240, NULL, NULL, NULL, '保证充分的通风。清除所有点火源。迅速将人员撤离到安全区域，远离泄漏区域并处于上风处。防止进一步的泄漏或溢出。避免排放到周围环境中。少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。清除所有点火源，并采用防火花工具和防暴设备。', NULL, NULL, NULL, NULL, '2026-03-06 14:45:10', '', NULL);
INSERT INTO `msds_leak_response` VALUES (5098, 5241, NULL, NULL, NULL, '保证充分的通风。清除所有点火源。迅速将人员撤离到安全区域，远离泄漏区域并处于上风。措施防止进一步的泄漏或溢出。避免排放到周围环境中。少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。清除所有点火源，并采用防火花工具和防暴设备。', NULL, NULL, NULL, NULL, '2026-03-06 14:45:10', '', NULL);
INSERT INTO `msds_leak_response` VALUES (5099, 5242, NULL, NULL, NULL, '疏散泄漏污染区人员至安全区，禁止无关人员进入污染区，切断火源。建议应急处理人 员戴好防毒面具，穿一般消防防护服。禁止泄漏物进入受限制的空间(如下水道等)，以 避免发生爆炸。用砂土、蛭石或其它惰性材料吸收，收集于密闭容器中作好标记，等待 处理。对污染地带进行通风。如大量泄漏，利用围堤收容，然后收集、转移、回收或无 害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:45:11', '', NULL);
INSERT INTO `msds_leak_response` VALUES (5100, 5243, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至安全区，并进行隔离，严格限制出入。切断火源。建议应急处理人员戴自给正压式呼吸器，穿防静电工作服。不要直接接触泄漏物。尽可能切断泄漏源。防止流入下水道、排洪沟等限制性空间。小量泄漏：用活性炭或其它惰性材料吸收。也可以用大量水冲洗，洗水稀释后放入废水系统。大量泄漏：构筑围堤或挖坑收容。用泡沫覆盖，降低蒸气灾害。用防爆泵转移至槽车或专用收集器内，回收或运至废物处理场所。', NULL, NULL, NULL, NULL, '2026-03-06 14:45:11', '', NULL);
INSERT INTO `msds_leak_response` VALUES (5101, 5244, NULL, NULL, NULL, '疏散泄漏污染区人员至安全区，禁止无关人员进入污染区，切断火源。建议应急处理人员戴自给式呼吸器，穿化学防护服。不要直接接触泄漏物，在确保安全情况下堵漏。喷水雾能减少蒸发但不要使水进入储存容器内。用沙土、干燥石灰或苏打灰混合，然后收集运至废物处理场所处置。也可以用不燃性分散剂制成的乳液刷洗，经稀释的洗水放入废水系统。如大量泄漏，利用围堤收容，然后收集、转移、回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:45:11', '', NULL);
INSERT INTO `msds_leak_response` VALUES (5102, 5245, NULL, NULL, NULL, '离泄漏区域并处于上风方向。使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。', NULL, NULL, NULL, NULL, '2026-03-06 14:45:12', '', NULL);
