INSERT INTO `msds_leak_response` VALUES (5107, 5250, NULL, NULL, NULL, '隔离泄漏污染区，周围设警告标志，切断火源。建议应急处理人员戴好口罩、护目镜， 具小心扫起，避免扬尘，装入备用袋中。用水刷洗泄漏污染区，经稀释的污水放入废水 系统。如大量泄漏，收集回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:45:14', '', NULL);
