INSERT INTO `msds_leak_response` VALUES (5110, 5253, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至安全区，并进行隔离，严格限制出入。切断火源。建议应急处理人员戴防尘口罩（全面罩），穿防静电工作服。避免吸入粉尘。避免接触眼睛、皮肤。避免泄漏物进入下水道、排洪沟等限制性空间。小量泄漏：避免扬尘，用洁净的铲子收集于干燥、洁净、有盖的容器中。大量泄漏：用塑料布、帆布覆盖，减少飞散。在专家指导下清除。', NULL, NULL, NULL, NULL, '2026-03-06 14:45:14', '', NULL);
