INSERT INTO `msds_leak_response` VALUES (5145, 5288, NULL, NULL, NULL, '隔离泄漏污染区，周围设警告标志，建议应急处理人员戴自给式呼吸器，穿化学防护服。 不要直接接触泄漏物，禁止向泄漏物直接喷水，更不要让水进入包装容器内。用砂土吸收， 铲入提桶，送至空旷地方，慢慢倒入大量水中，经分解稀释后的污水放入废水系统。如大 量泄漏，收集回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:45:28', '', NULL);
