INSERT INTO `msds_leak_response` VALUES (5279, 5422, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至安全区，并进行隔离，严格限制出入。切断火源。建议应急处理人员戴自给正压式呼吸器，穿防静电工作服。尽可能切断泄漏源。防止流入下水道、排洪沟等限制性空间。', NULL, NULL, NULL, NULL, '2026-03-06 14:46:15', '', NULL);
INSERT INTO `msds_leak_response` VALUES (5280, 5423, NULL, NULL, NULL, '隔离泄漏污染区，限制出入。切断火源。建议应急处理人员戴防尘面具（全面罩），穿防毒服。不要直接接触泄漏物。避免震动、撞击和摩擦。小量泄漏：用干石灰、苏打灰覆盖，使用无火花工具收集于干燥、洁净、有盖的容器中。运至空旷处引爆。也可以用大量水冲洗，洗水稀释后放入废水系统。大量泄漏：在专家指导下清除。', NULL, NULL, NULL, NULL, '2026-03-06 14:46:15', '', NULL);
INSERT INTO `msds_leak_response` VALUES (5281, 5424, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至安全区，并进行隔离，严格限制出入。切断火源。建议应急处理人员戴自给正压式呼吸器，穿防毒服。尽可能切断泄漏源。防止流入下水道、排洪沟等限制性空间。小量泄漏：用砂土、蛭石或其它惰性材料吸收。大量泄漏：用泡沫覆盖，降低蒸气灾害。构筑围堤或挖坑收容。喷雾状水冷却和稀释蒸汽、保护现场人员、把泄漏物稀释成不燃物。用防爆泵转移至槽车或专用收集器内，回收或运至废物处理场所处置。', NULL, NULL, NULL, NULL, '2026-03-06 14:46:15', '', NULL);
INSERT INTO `msds_leak_response` VALUES (5282, 5425, NULL, NULL, NULL, '无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。不要触摸或穿越泄漏物。不要触摸破损的容器或泄漏物质除非穿着合适的防护服。保证充分的通风。清除所有点火源。采取防静电措施。迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。', NULL, NULL, NULL, NULL, '2026-03-06 14:46:16', '', NULL);
INSERT INTO `msds_leak_response` VALUES (5283, 5426, NULL, NULL, NULL, '隔离泄漏污染区，周围设警告标志，建议应急处理人员戴好防毒面具，穿相应的工作服。切断火源。使用无火花工具收集于密闭容器中作好标记，等待处理或在保证安全情况下，就地焚烧。如大量泄漏，收集回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:46:16', '', NULL);
INSERT INTO `msds_leak_response` VALUES (5284, 5427, NULL, NULL, NULL, '保证充分的通风。清除所有点火源。迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。应急处理措施防止进一步的泄漏或溢出。避免排放到周围环境中。少量泄漏时，可采用干砂或惰性吸附材料吸收泄漏物，大量泄漏时需筑堤控制。附着物或收集物应存放在合适的密闭容器中，并根据当地相关法律法规废弃处置。清除所有点火源，并采用防火花工具和防暴设备。', NULL, NULL, NULL, NULL, '2026-03-06 14:46:16', '', NULL);
INSERT INTO `msds_leak_response` VALUES (5285, 5428, NULL, NULL, NULL, '隔离泄漏污染区，周围设警告标志，建议应急处理人员戴好防毒面具，穿相应的工作服。切断火源。使用无火花工具收集于密闭容器中作好标记，等待处理或在保证安全情况下，就地焚烧。如大量泄漏，收集回收或无害处理后废弃。离泄漏区域并处于上风方向。使用个人防护装备。避免吸入蒸气、烟雾、气体或风尘。', NULL, NULL, NULL, NULL, '2026-03-06 14:46:16', '', NULL);
INSERT INTO `msds_leak_response` VALUES (5286, 5429, NULL, NULL, NULL, '无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。不要触摸或穿越泄漏物。不要触摸破损的容器或泄漏物质除非穿着合适的防护服。保证充分的通风。清除所有点火源。采取防静电措施。迅速将人员撤离到安全区域，远离泄漏区域并处于上风向。', NULL, NULL, NULL, NULL, '2026-03-06 14:46:16', '', NULL);
INSERT INTO `msds_leak_response` VALUES (5287, 5430, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至安全区，并进行隔离，严格限制出入。切断火源。建议应急处理人员戴自给正压式呼吸器，穿防毒服。尽可能切断泄漏源。防止流入下水道、排洪沟等限制性空间。小量泄漏：用砂土、蛭石或其它惰性材料吸收。大量泄漏：构筑围堤或挖坑收容。用泡沫覆盖，降低蒸气灾害。喷雾状水或泡沫冷却和稀释蒸汽、保护现场人员。用防爆泵转移至槽车或专用收集器内，回收或运至废物处理场所处置。', NULL, NULL, NULL, NULL, '2026-03-06 14:46:17', '', NULL);
INSERT INTO `msds_leak_response` VALUES (5288, 5431, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至安全区，并进行隔离，严格限制出入。建议应急处理人员戴自给正压式呼吸器，穿防酸碱工作服。从上风处进入现场。尽可能切断泄漏源。防止流入下水道、排洪沟等限制性空间。小量泄漏：将地面洒上苏打灰，然后用大量水冲洗，洗水稀释后放入废水系统。大量泄漏：构筑围堤或挖坑收容。喷雾状水冷却和稀释蒸汽、保护现场人员、把泄漏物稀释成不燃物。用泵转移至槽车或专用收集器内，回收或运至废物处理场所处置。', NULL, NULL, NULL, NULL, '2026-03-06 14:46:18', '', NULL);
INSERT INTO `msds_leak_response` VALUES (5289, 5432, NULL, NULL, NULL, '隔离泄漏污染区，限制出入。建议应急处理人员戴防尘面具（全面罩），穿防毒服。不要直接接触泄漏物。勿使泄漏物与还原剂、有机物、易燃物或金属粉末接触。小量泄漏：小心扫起，收集于干燥、洁净、有盖的容器中。大量泄漏：收集回收或运至废物处理场所处置。', NULL, NULL, NULL, NULL, '2026-03-06 14:46:18', '', NULL);
