INSERT INTO `msds_leak_response` VALUES (5316, 5459, NULL, NULL, NULL, '隔离泄漏污染区，周围设警告标志，建议应急处理人员戴好防毒面具，穿化学防护服。用砂土、干燥石灰或苏打灰混合，然后在专用废弃场所深层掩埋。被污染地面用肥皂或洗涤剂刷洗，经稀释的污水放入废水系统。如大量泄漏，收集回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:46:29', '', NULL);
