INSERT INTO `msds_leak_response` VALUES (5382, 5525, NULL, NULL, NULL, '疏散泄漏污染区人员至安全区，禁止无关人员进入污染区，建议应急处理人员戴自给式呼吸器，穿化学防护服。用砂土吸收，倒至空旷地方深埋。被污染地面用肥皂或洗涤剂刷洗，经稀释的污水放入废水系统。如大量泄漏，利用围堤收容，然后收集、转移、回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:46:59', '', NULL);
