INSERT INTO `msds_leak_response` VALUES (5516, 5659, NULL, NULL, NULL, '隔离泄漏污染区，限制出入。切断火源。建议应急处理人员戴防尘面具（全面罩），穿防毒服。 不要直接接触泄漏物。小量泄漏：用洁净的铲子收集于干燥、洁净、有盖的容器中。大量泄漏： 收集回收或运至废物处理场所处置。', NULL, NULL, NULL, NULL, '2026-03-06 14:47:56', '', NULL);
