INSERT INTO `msds_leak_response` VALUES (5562, 5705, NULL, NULL, NULL, '消除所有点火源。根据液体流动和蒸气扩散的影响区域划定警戒区，无关人员从侧风、上风向撤离至安全区。建议应急处理人员戴正压自给式呼吸器，穿防毒、防静电服。作业时使用的工具应为防爆工具。禁止接触或跨越泄漏物。尽可能切断泄漏源。防止泄漏物进入水体、下水道、地下室或限制性空间。小量泄漏：用砂土或其它不燃材料吸附或吸收。大量泄漏：构筑围堤或挖坑收容。用泡沫覆盖，降低蒸气灾害。用防爆泵转移至槽车或专用收集器内。', NULL, NULL, NULL, NULL, '2026-03-06 14:48:15', '', NULL);
