INSERT INTO `msds_leak_response` VALUES (5570, 5713, NULL, NULL, NULL, '疏散泄漏污染区人员至安全区，禁止无关人员进入污染区，切断火源。建议应急处理人员戴 好防毒面具，穿一般消防防护服。在确保安全情况下堵漏。用活性炭或其它惰性材料吸收，然 后收集运至废物处理场所处置。也可以用不燃性分散剂制成的乳液刷洗，经稀释的洗水放入 废水系统。如大量泄漏，利用围堤收容，然后收集、转移、回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:48:21', '', NULL);
