INSERT INTO `msds_leak_response` VALUES (5607, 5750, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至上风处，并进行隔离，严格限制出入。切断火源。建议应急处理人员戴自给正压式呼吸器，穿防静电工作服。尽可能切断泄漏源。用工业覆盖层或吸附/吸收剂盖住泄漏点附近的下水道等地方，防止气体进入。合理通风，加速扩散。喷雾状水稀释、溶解。构筑围堤或挖坑收容产生的大量废水。如有可能，将漏出气用排风机送至空旷处。', NULL, NULL, NULL, NULL, '2026-03-06 14:48:40', '', NULL);
