INSERT INTO `msds_leak_response` VALUES (5647, 5790, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至安全区，并进行隔离，严格限制出入。切断火源。建议应急处理人员戴自给正压式呼吸器，穿防毒服。不要直接接触泄漏物。', NULL, NULL, NULL, NULL, '2026-03-06 14:48:58', '', NULL);
INSERT INTO `msds_leak_response` VALUES (5648, 5791, NULL, NULL, NULL, '无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。不要触摸或穿越泄漏物。不要触摸破损的容器或泄漏物质除非穿着合适的防护服。保证充分的通风。清除所有点火源。采取防静电措施。迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。使用个人防护装备。', NULL, NULL, NULL, NULL, '2026-03-06 14:48:58', '', NULL);
INSERT INTO `msds_leak_response` VALUES (5649, 5792, NULL, NULL, NULL, '用砂土或其它不燃性吸附剂混合吸收，然后收集运到空旷处焚烧。如大量泄漏，利用围 堤收容，然后收集、转移、回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:49:00', '', NULL);
INSERT INTO `msds_leak_response` VALUES (5650, 5793, NULL, NULL, NULL, '疏散泄漏污染区人员至安全区，禁止无关人员进入污染区，切断火源。建议应急处理人员戴自给式呼吸器，穿化学防护服。禁止泄漏物进入受限制的空间（如下水道等），以避免发生爆炸。禁止向泄漏物直接喷水，更不要让水进入包装容器内。用砂土、干燥石灰或苏打灰混合，使用不产生火花的工具收集于一个密闭的容器中，运至废物处理场所。如大量泄漏，利用围堤收容，然后收集、转移、回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:49:00', '', NULL);
INSERT INTO `msds_leak_response` VALUES (5651, 5794, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至安全区，并进行隔离，严格限制出入。切断火源。建议应急处 理人员戴自给正压式呼吸器，穿防静电工作服。尽可能切断泄漏源。防止流入下水道、排 应急处理： 洪沟等限制性空间。小量泄漏：用砂土或其它不燃材料吸附或吸收。也可以用大量水冲洗， 洗水稀释后放入废水系统。大量泄漏：构筑围堤或挖坑收容。用泡沫覆盖，降低蒸气灾害。 用防爆泵转移至槽车或专用收集器内，回收或运至废物处理场所处置。', NULL, NULL, NULL, NULL, '2026-03-06 14:49:00', '', NULL);
INSERT INTO `msds_leak_response` VALUES (5652, 5795, NULL, NULL, NULL, '疏散泄漏污染区人员至安全区，禁止无关人员进入污染区，切断火源。建议应急处理人 员戴自给式呼吸器，穿化学防护服。禁止向泄漏物直接喷水，更不要让水进入包装容器 内。用砂土、干燥石灰或苏打灰混合，使用不产生火花的工具收集于一个密闭的容器中， 运至废物处理场所。如大量泄漏，利用围堤收容，然后收集、转移、回收或无害处理后 废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:49:00', '', NULL);
INSERT INTO `msds_leak_response` VALUES (5653, 5796, NULL, NULL, NULL, '隔离泄漏污染区，周围设警告标志，建议应急处理人员戴正压自给式呼吸器，穿防毒服。不要直接接触泄漏物。不要触摸或穿越泄漏物。不要触摸破损的容器或泄漏物质除非穿着合适的防护服。保证充分的通风。清除所有点火源。采取防静电措施。迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。使用无火花工具收集泄漏物，置于袋中转移至安全场所。也可以用大量水冲洗，经稀释的污水放入废水系统。如大量泄漏，收集回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:49:01', '', NULL);
INSERT INTO `msds_leak_response` VALUES (5654, 5797, NULL, NULL, NULL, '隔离泄漏污染区，周围设警告标志，切断火源。应急处理人员戴好防毒面具，穿一般消防防护服。用惰性吸附剂混合吸收，然后收集运至废物处理场所。也可以用不燃性分散剂制成的乳液刷洗，经稀释的洗液放入废水系统。如大量泄漏，利用围堤收容，然后收集、转移、回收或无害处理后废弃。', NULL, NULL, NULL, NULL, '2026-03-06 14:49:02', '', NULL);
INSERT INTO `msds_leak_response` VALUES (5655, 5798, NULL, NULL, NULL, '隔离泄漏污染区，周围设警告标志，切断火源。建议应急处理人员戴防尘口罩，穿一般作业工作服。避免扬尘，小心扫起，置于袋中转移至安全场所。如大量泄漏，收集回收或运至废物处理场所处置。', NULL, NULL, NULL, NULL, '2026-03-06 14:49:02', '', NULL);
INSERT INTO `msds_leak_response` VALUES (5656, 5799, NULL, NULL, NULL, '隔离泄漏污染区，限制出入。建议应急处理人员戴防尘口罩（全面罩），穿防毒服。避免扬尘，小心扫起，置于袋中转移至安全场所。若大量泄漏，用塑料布、帆布覆盖。收集回收或运至废物处理场所处置。', NULL, NULL, NULL, NULL, '2026-03-06 14:49:02', '', NULL);
INSERT INTO `msds_leak_response` VALUES (5657, 5800, NULL, NULL, NULL, '迅速撤离泄漏污染区人员至安全区，并进行隔离，严格限制出入。切断火源。建议应急处理人员戴自给正压式呼吸器，穿防静电工作服。避免吸入蒸气。避免接触眼睛、皮肤。避免泄漏物进入下水道、排洪沟等限制性空间。小量泄漏：用砂土、蛭石或其它惰性材料吸收，并收集于密闭容器中。大量泄漏：构筑围堤或挖坑收容，用泡沫覆盖，降低蒸气灾害，用防爆泵转移至槽车或专用收集器内，回收或运至废物处理场所处置。', NULL, NULL, NULL, NULL, '2026-03-06 14:49:02', '', NULL);
INSERT INTO `msds_leak_response` VALUES (5658, 5801, NULL, NULL, NULL, '应急处理：首先切断一切火源，戴好氧气防毒面具与手套。迅速撤离泄漏污染区人员至安全区，并进行隔离，严格限制出入。建议应急处理人员戴自给正压式呼吸器，穿防毒服。尽可能切断泄漏源。合理通风，加速扩散。喷雾状水稀释、溶解。构筑围堤或挖坑收容产生的大量废水。如有可能，将残余气或漏出气用排风机送至水洗塔或与塔相连的通风橱内。漏气容器要妥善处理，修复、检验后再用。', NULL, NULL, NULL, NULL, '2026-03-06 14:49:02', '', NULL);
INSERT INTO `msds_leak_response` VALUES (5659, 5802, NULL, NULL, NULL, '无火灾状况下的溢漏和泄漏应穿着蒸气防护服，且完全密封。不要触摸或穿越泄漏物。不 要触摸破损的容器或泄漏物质除非穿着合适的防护服。保证充分的通风。清除所有点火源。 采取防静电措施。迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。使用个人', NULL, NULL, NULL, NULL, '2026-03-06 14:49:03', '', NULL);
