INSERT INTO `msds_leak_response` VALUES (5708, 5851, NULL, NULL, NULL, '确保可燃物（木头、纸、油等）远离泄漏物。保证充分的通风。清除所有点火源。采取防静电措施。迅速将人员撤离到安全区域，远离泄漏区域并处于上风方向。使用个人防护装备。避免吸入粉尘。用惰性材料（如沙子、泥土）吸收泄漏物。将泄漏物收集到适当的容器中。避免泄漏物进入下水道、地下室或密闭空间。', NULL, NULL, NULL, NULL, '2026-03-06 14:49:28', '', NULL);
