INSERT INTO `msds_other_info` VALUES (1153, 3047, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '本说明书基于当前科学知识和法规要求编制，仅供参考使用\n        使用者应根据具体应用场景评估适用性，并遵守相关法律法规\n        本品为易燃液体，使用时需远离火源，采取适当防护措施\n        如需获取最新版本或有疑问，请联系供应商或专业机构', '', NULL, '', NULL);
INSERT INTO `msds_other_info` VALUES (1154, 3048, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '本说明书基于当前科学知识和法规要求编制，仅供参考使用\n        使用者应根据具体应用场景评估适用性，并遵守相关法律法规\n        本品为高度易燃液体，闪点-7℃，使用时需远离火源，采取适当防护措施\n        如需获取最新版本或有疑问，请联系供应商或专业机构', '', NULL, '', NULL);
INSERT INTO `msds_other_info` VALUES (1155, 3049, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1. 本说明书基于现有科学数据编制，仅供安全操作参考。2. 用户应根据实际使用情况评估风险并采取适当防护措施。3. 本产品为可疑致癌物2B类（IARC），长期接触可增加患癌风险，应严格控制接触。4. 本说明书内容会随着科学认知的发展而更新，请定期查阅最新版本。', '', NULL, '', NULL);
INSERT INTO `msds_other_info` VALUES (1156, 3050, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1. 本说明书基于现有科学资料编制，仅供安全操作参考，不构成产品性能保证。\n        2. 用户应根据具体使用条件和法规要求，采取适当的安全防护措施。\n        3. 本产品为低闪点易燃液体，接触空气或在光照条件下可生成具有潜在爆炸危险性的过氧化物，需添加稳定剂。\n        4. 使用前请仔细阅读并理解本说明书，如有疑问请联系供应商或专业人士。', '', NULL, '', NULL);
INSERT INTO `msds_other_info` VALUES (1157, 3052, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '本说明书提供的信息基于现有科学知识和数据，仅供用户安全使用本化学品参考\n        用户应根据实际使用条件和当地法规要求，采取适当的安全预防措施\n        本说明书中的信息可能随着科学研究的进展而更新，建议定期获取最新版本\n        对于特殊用途或未在本说明书中涵盖的应用场景，请咨询相关专业机构或专家', '', NULL, '', NULL);
INSERT INTO `msds_other_info` VALUES (1158, 3055, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '本说明书基于当前科学知识和法规要求编制，仅供参考使用\n        使用者应根据具体应用场景评估适用性，并遵守相关法律法规\n        本产品能发生聚合反应，需添加阻聚剂防止聚合，使用时应特别注意\n        如需获取最新版本或有疑问，请联系供应商或专业机构', '', NULL, '', NULL);
INSERT INTO `msds_other_info` VALUES (1159, 3058, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '本安全技术说明书所提供的信息基于当前科学知识和技术水平，仅供参考使用。\n        使用者应根据实际使用情况，采取适当的安全防护措施。\n        本产品属于第6.1类毒害品，剧毒，确认致癌物1类（IARC），对人类健康和环境具有严重危害，使用时需格外谨慎。\n        本品属于持久性有机污染物（POPs），已被列入《斯德哥尔摩公约》禁用名单，禁止生产、使用和进出口。', '', NULL, '', NULL);
INSERT INTO `msds_other_info` VALUES (1160, 3059, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '本安全技术说明书所提供的信息基于当前科学知识和技术水平，仅供参考使用。\n        使用者应根据实际使用情况，采取适当的安全防护措施。\n        本产品属于第6.1类毒害品，剧毒，可疑致癌物2B类（IARC），对人类健康和环境具有严重危害，使用时需格外谨慎。\n        本品属于持久性有机污染物（POPs），在环境中极难降解，对生态系统造成长期危害。', '', NULL, '', NULL);
