INSERT INTO `msds_other_info` VALUES (1185, 3146, NULL, '中国化学品安全网、国际化学品安全卡（ICSC）、欧洲化学品管理局（ECHA）数据库、美国国立职业安全卫生研究所（NIOSH）等权威数据库。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '本安全技术说明书提供的信息基于现有的知识和数据，仅供参考。使用者应根据实际情况进行风险评估，并遵守相关法规。对于因使用本信息而导致的任何损失或损害，我们不承担责任。', '', NULL, '', NULL);
