INSERT INTO `msds_other_info` VALUES (1193, 3195, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '本MSDS提供的信息基于目前所掌握的知识，但不排除存在未知的风险。使用者应根据实际情况采取适当的安全防护措施。', '', NULL, '', NULL);
INSERT INTO `msds_other_info` VALUES (1194, 3203, NULL, '国际化学品安全卡(ICSC)、美国国立职业安全卫生研究所(NIOSH)、欧洲化学品管理局(ECHA)、中国化学品安全网、PubChem数据库、RTECS数据库、供应商技术文档、科学文献数据库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '本MSDS信息基于现有数据和专业知识编制，仅供参考。使用者应根据实际使用条件和法规要求，结合专业判断，确定适当的安全措施。对于因使用本信息而导致的任何损失或损害，编制者不承担责任。本品为可疑致癌物2B类（IARC），使用时应特别注意防护。', '', NULL, '', NULL);
INSERT INTO `msds_other_info` VALUES (1195, 3204, NULL, '国际化学品安全卡(ICSC)、美国国立职业安全卫生研究所(NIOSH)、欧洲化学品管理局(ECHA)、中国化学品安全网、PubChem数据库、供应商技术文档、科学文献数据库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '本MSDS信息基于现有数据和专业知识编制，仅供参考。使用者应根据实际使用条件和法规要求，结合专业判断，确定适当的安全措施。对于因使用本信息而导致的任何损失或损害，编制者不承担责任。本品的致癌性分类为IARC 2B类（可疑致癌物），使用时应特别注意防护。', '', NULL, '', NULL);
