INSERT INTO `msds_other_info` VALUES (1392, 3565, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '本MSDS文档已按照国家标准要求进行补全和修正', NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_other_info` VALUES (1393, 3566, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1. 化学品基本信息（中英文名称、CAS号、分子式、分子量）来源于ICSC国际化学品安全卡数据库。2. 理化特性数据（外观、熔点、沸点、相对密度、溶解性等）来源于权威化学品数据库和文献资料。3. 危险性分类和标签信息依据《危险化学品目录（2015版）》和GHS分类标准。4. 运输信息（UN编号、包装类别等）依据《危险货物道路运输规则》(JT/T 617)。5. 急救措施、消防措施、泄漏应急处理、操作处置与储存、接触控制/个体防护等内容依据化学品安全技术说明书编制指南和同类化学品安全资料。6. 毒理学信息、生态学资料、稳定性和反应活性等数据部分来源于权威数据库，部分因缺乏具体实验数据标注为\"无资料\"。7. 供应商信息字段统一标注为\"无资料\"。', NULL, NULL, NULL, '', NULL, '', NULL);
