INSERT INTO `msds_other_info` VALUES (1461, 3683, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '本安全技术说明书提供的资料基于现有知识，仅供参考。使用者应自行评估使用本化学品的风险，并采取适当的安全措施。对于因使用本化学品而造成的任何损失或伤害，我们不承担任何责任。', '', NULL, '', NULL);
