INSERT INTO `msds_other_info` VALUES (1659, 4318, NULL, '国际化学品安全卡（ICSC）、美国国立职业安全卫生研究所（NIOSH）、欧洲化学品管理局（ECHA）、中国化学品安全网等权威数据库', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '本MSDS数据仅供参考，实际使用时应以最新法规要求和供应商提供信息为准。使用者有责任根据实际使用情况评估本产品的安全性。', '', NULL, '', NULL);
