INSERT INTO `msds_other_info` VALUES (1664, 4380, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '本SDS按照GB/T 16483-2008标准编制。', NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_other_info` VALUES (1665, 4388, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '无', NULL, '本品通常加有阻聚剂（如对叔丁基邻苯二酚）以防止聚合。储存过程中应定期检查阻聚剂含量，确保其有效性。使用前应充分摇匀，确保阻聚剂分布均匀。废弃处置时应咨询当地环保部门，按照相关法规要求进行处置。本化学品安全技术说明书仅适用于该化学品，不适用于其混合物或衍生物。如有疑问，请咨询专业技术人员或供应商。', '本安全技术说明书所提供的信息基于现有知识和数据，仅供用户参考。使用者应根据实际情况自行评估风险并采取适当的安全措施。对于因使用本说明书信息而造成的任何损失或损害，编制方不承担责任。本说明书将根据最新研究成果和法规要求进行更新，请使用最新版本。', '', NULL, '', NULL);
