INSERT INTO `msds_other_info` VALUES (1670, 4410, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '本安全技术说明书依据GB/T 16483-2008标准编制，内容符合《化学品安全技术说明书 内容和项目顺序》和《化学品分类和危险性公示 通则》的要求。放线菌素D为抗肿瘤抗生素，具有致癌性和致畸变性，应特别注意其健康和环境影响。', NULL, NULL, NULL, '', NULL, '', NULL);
