INSERT INTO `msds_other_info` VALUES (2045, 5292, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '本化学品安全技术说明书依据GB/T 16483-2008标准编制，所提供的信息基于现有知识和经验。使用者应自行评估使用本化学品的风险，并采取适当的安全防护措施。本说明书不构成任何形式的保证或承诺。对于因使用本化学品而造成的任何损失或损害，编制方不承担责任。', '', NULL, '', NULL);
INSERT INTO `msds_other_info` VALUES (2046, 5294, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '本安全技术说明书所提供的信息基于现有知识和技术，仅供用户参考。使用者应根据具体情况采取适当的安全措施。对于因使用本说明书信息而造成的任何损失或损害，编制方不承担责任。使用者应遵守所有适用的法律法规要求。', '', NULL, '', NULL);
INSERT INTO `msds_other_info` VALUES (2047, 5297, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_other_info` VALUES (2048, 5308, NULL, '基于四氰基代乙烯分子结构和氰化物特性进行科学评估\n          参考《危险化学品安全管理条例》等相关法规\n          参考OECD测试指南推荐测试方法', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '本MSDS仅供参考，具体数据建议向供应商索取或开展相关测试获取', '', NULL, '', NULL);
INSERT INTO `msds_other_info` VALUES (2049, 5311, NULL, '国际化学品安全卡(ICSC)数据库\n        欧洲化学品管理局(ECHA)数据库\n        美国国家职业安全卫生研究所(NIOSH)数据库\n        化学结构相似化合物类比数据', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '本MSDS信息仅基于现有数据编制，仅供参考。使用者应根据实际使用情况评估其适用性和完整性，并承担相应责任。', '', NULL, '', NULL);
