INSERT INTO `msds_physical_chemical` VALUES (2840, 3021, '二种异构体的混合物，是棕色结晶。', NULL, NULL, '70～100', '449.7ºC at 760mmHg', '1.745(20℃)', NULL, NULL, NULL, '几乎不溶于水，溶于大多数有机溶剂如丙酮、苯、二甲苯、氯仿等', NULL, NULL, NULL, '225.8ºC', NULL, NULL, NULL, NULL, NULL, NULL, 'C9H6Cl6O3S', NULL, NULL, '无资料（高温下分解，难以测定）', '可燃，但不易燃烧', '406.91', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_physical_chemical` VALUES (2841, 3022, '黄色油状液体，有萜烯味。', NULL, NULL, '-48℃', '95／7.98×0.001kPa', '1.1465(25／4℃)', NULL, NULL, NULL, '不溶于水，易溶于醇、苯、氯仿、醚。', NULL, NULL, NULL, '82', NULL, NULL, NULL, NULL, NULL, NULL, 'C13H19NO2S', NULL, NULL, '无资料（建议开展自燃温度测试）', '可燃', '253.39', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_physical_chemical` VALUES (2842, 3023, '工业品为褐色固体。', NULL, NULL, '175～176', '无资料', '1.75', NULL, NULL, NULL, '几乎不溶于水（0.186 mg/L），易溶于大多数有机溶剂如丙酮、苯、二甲苯、氯仿等', NULL, NULL, NULL, '无意义', NULL, NULL, NULL, NULL, NULL, NULL, 'C12H8Cl6O', NULL, NULL, '无资料', '可燃', '380.91', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_physical_chemical` VALUES (2843, 3024, '白色结晶。', NULL, NULL, '245(分解)', '无资料', '1.65(25℃)', NULL, NULL, NULL, '几乎不溶于水（0.25 mg/L），易溶于大多数有机溶剂如丙酮、苯、二甲苯、氯仿等', NULL, NULL, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, 'C12H8Cl6O', NULL, NULL, '无资料', '不燃', '380.90', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_physical_chemical` VALUES (2844, 3025, '白色结晶性粉末或无色结晶', NULL, NULL, '204~205', '35', '不适用', NULL, NULL, NULL, '易溶于水，微溶于乙醇，几乎不溶于乙醚、氯仿', NULL, NULL, NULL, '不适用', NULL, NULL, NULL, NULL, NULL, NULL, 'C6H15ClN2O2', NULL, NULL, '无资料', '不燃', '182.65', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
