INSERT INTO `msds_physical_chemical` VALUES (3427, 3614, NULL, NULL, NULL, '84-94℃（84℃甲苯中析出者，94℃水中析出者）', '无资料', '无资料', NULL, NULL, NULL, '溶于乙醚、乙醇和氯仿，溶液微带蓝色荧光，加入酸类甚至二氧化碳也能增强荧光，溶液转变成黄色。微溶于水。', NULL, NULL, NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, 'C9H8N2', NULL, NULL, NULL, NULL, '144.18', NULL, NULL, NULL, NULL, '', NULL, '', NULL);
