INSERT INTO `msds_regulatory` VALUES (2597, 3057, '《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录》（2015版）、《危险货物品名表》（GB 12268-2012）、《危险货物运输包装通用技术条件》（GB 12463-2009）、《危险货物道路运输安全管理办法》（交通运输部令2019年第29号）、《斯德哥尔摩公约》。本品属于第6.1类毒害品，剧毒，可疑致癌物2B类（IARC），需\"五双\"管理。本品属于持久性有机污染物（POPs），已被列入《斯德哥尔摩公约》禁用名单，禁止生产、使用和进出口。应按照相关法规进行生产、储存、运输和使用。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (2598, 3058, '《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录》（2015版）、《危险货物品名表》（GB 12268-2012）、《危险货物运输包装通用技术条件》（GB 12463-2009）、《危险货物道路运输安全管理办法》（交通运输部令2019年第29号）、《斯德哥尔摩公约》。本品属于第6.1类毒害品，剧毒，确认致癌物1类（IARC），可致肺癌、皮肤癌，需\"五双\"管理。本品属于持久性有机污染物（POPs），已被列入《斯德哥尔摩公约》禁用名单，禁止生产、使用和进出口。应按照相关法规进行生产、储存、运输和使用。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (2599, 3059, '《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录》（2015版）、《危险货物品名表》（GB 12268-2012）、《危险货物运输包装通用技术条件》（GB 12463-2009）、《危险货物道路运输安全管理办法》（交通运输部令2019年第29号）。本品属于第6.1类毒害品，剧毒，可疑致癌物2B类（IARC），需\"五双\"管理。本品属于持久性有机污染物（POPs），应按照相关法规进行生产、储存、运输和使用。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (2600, 3060, '《危险化学品安全管理条例》\n          《危险化学品目录》（2015版）\n          《危险废物鉴别标准》（GB 5085）\n          《危险废物焚烧污染控制标准》（GB 18484）\n          《工作场所有害因素职业接触限值》（GBZ 2.1）\n        \n        \n          欧盟REACH法规（EC 1907/2006）\n          欧盟CLP法规（EC 1272/2008）\n          美国有毒物质控制法案（TSCA）\n          《国际海运危险货物规则》（IMDG Code）\n        \n        \n          \n            易燃液体：类别4\n            特定目标器官毒性-单次接触：类别3\n            危害水生环境-急性危害：类别2\n            危害水生环境-长期危害：类别2\n          \n        \n        \n          中国现有化学物质名录（IECSC）：列入\n          欧洲化学物质名录（EINECS）：列入\n          美国TSCA名录：列入', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
