INSERT INTO `msds_regulatory` VALUES (2725, 3228, '《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录》（2015版）、《危险货物品名表》（GB 12268-2012）、《危险货物运输包装通用技术条件》（GB 12463-2009）、《危险货物道路运输安全管理办法》（交通运输部令2019年第29号）。本品属于第6.1类毒害品，剧毒类氨基甲酸酯类杀虫剂（异索威），应按照相关法规进行生产、储存、运输和使用。应严格执行极毒物品\"五双\"管理制度。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
