INSERT INTO `msds_regulatory` VALUES (2770, 3288, '国内法规：\n1. 《危险化学品目录》(2022调整版)：危险化学品目录序号976\n2. 《危险货物道路运输规则》(JT/T 617)：\n   - UN编号：2622\n   - 包装类别：Ⅱ\n   - 运输分类：第3.3类 高闪点易燃液体\n3. 《危险化学品安全管理条例》\n4. 《工作场所安全使用化学品规定》\n\n国际法规：\n1. 《全球化学品统一分类和标签制度》(GHS)：\n   - 易燃液体类别3\n   - 皮肤腐蚀/刺激类别2\n   - 严重眼损伤/眼刺激类别2A\n   - 特异性靶器官毒性—单次接触类别3\n2. 《国际海运危险货物规则》(IMDG Code)\n3. 《国际空运危险货物规则》(IATA DGR)\n4. 《关于危险货物运输的建议书·规章范本》(TDG)', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
