INSERT INTO `msds_regulatory` VALUES (2827, 3358, '国内化学品管理法规：\n1. 《危险化学品安全管理条例》：本品属于危险化学品，应严格按照相关法规进行管理\n2. 《危险化学品目录》（2015版）：列入目录，序号未明确\n3. 《工作场所安全使用化学品规定》：工作场所空气中最高容许浓度为5mg/m³[皮]\n4. 《化学品安全技术说明书内容和项目顺序》GB/T 16483-2008：MSDS编制标准\n\n国际法规：\n1. 欧盟REACH法规：需完成注册、评估、授权和限制程序\n2. 全球化学品统一分类和标签制度（GHS）：\n   - 急性毒性－经口，类别4\n   - 急性毒性－经皮，类别4\n   - 特异性靶器官毒性－反复接触，类别2\n   - 危害水生环境－急性危害，类别2\n   - 危害水生环境－长期危害，类别2\n\n其他法规信息：\n1. 危险性类别：第6.1类毒害品\n2. UN编号：1711\n3. 包装类别：II\n4. 海关编码：2921499090', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
