INSERT INTO `msds_regulatory` VALUES (2850, 3382, '国内法规：\n1. 《剧毒化学品目录》（2015版）：列入序号1\n2. 《危险化学品目录》（2015版）：列入序号1\n3. 《危险化学品安全管理条例》：严格管控\n4. 《禁止、限制和控制类危险化学品目录》：列入禁止类危险化学品\n5. 《农业农村部公告第199号》：明令禁止在灭鼠药等农药中添加毒鼠强\n\n国际法规：\n1. GHS分类：急性毒性类别1（口服）、急性毒性类别1（经皮）、急性毒性类别2（吸入）\n2. 欧盟REACH法规：高度关注物质\n3. 国际海事组织危险品规则：严格管控', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
