INSERT INTO `msds_regulatory` VALUES (2865, 3397, '《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录》（2015版）、《危险货物品名表》（GB 12268-2012）、《危险货物运输包装通用技术条件》（GB 12463-2009）、《危险货物道路运输安全管理办法》（交通运输部令2019年第29号）。本品属于第8.2类碱性腐蚀品，具腐蚀性和刺激性，应按照相关法规进行生产、储存、运输和使用。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (2866, 3398, NULL, '危险化学品安全管理条例\n        列入《危险化学品目录》，需按照危险化学品进行管理\n        危险化学品登记管理办法\n        需进行危险化学品登记\n        工作场所安全使用化学品规定\n        工作场所空气中最高容许浓度：2mg/m³', NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (2867, 3399, '《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录》（2015版）、《危险货物品名表》（GB 12268-2012）、《危险货物运输包装通用技术条件》（GB 12463-2009）、《危险货物道路运输安全管理办法》（交通运输部令2019年第29号）。本品属于第3.3类高闪点易燃液体，应按照相关法规进行生产、储存、运输和使用。注意：能发生聚合反应，需添加阻聚剂。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (2868, 3400, '1. 中国法规：《危险化学品安全管理条例》、《危险化学品目录（2015版）》、《危险货物品名表》（GB12268）、《化学品安全技术说明书内容和项目顺序》（GB/T 16483-2008）、《化学品安全技术说明书编写规定》（GB/T 17519-2013）。\n2. 国际法规：联合国《关于危险货物运输的建议书》（TDG）、全球化学品统一分类和标签制度（GHS）。\n3. 本化学品属于危险化学品，应严格按照相关法规要求进行生产、储存、运输、使用和废弃处置。\n4. 作业人员应经过专门培训，并取得相应资质后方可上岗操作。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (2869, 3401, '国内化学品安全管理法规：危险化学品安全管理条例、工作场所安全使用化学品规定等。国际法规：联合国GHS制度、国际海运危险货物规则(IMDG Code)等。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (2870, 3402, '《危险化学品安全管理条例》（国务院令第591号）、《易制毒化学品管理条例》（国务院令第445号）、《废弃危险化学品污染环境防治办法》、《中华人民共和国安全生产法》、《危险化学品目录（2015版）》、《危险化学品目录（2022调整版）》。该化学品属于第6.1类毒害品，受国家危险化学品安全管理法规管制。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (2871, 3403, '《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录》（2015版）、《危险货物品名表》（GB 12268-2012）、《危险货物运输包装通用技术条件》（GB 12463-2009）、《危险货物道路运输安全管理办法》（交通运输部令2019年第29号）。本品属于第3.2类中闪点易燃液体，属微毒类，应按照相关法规进行生产、储存、运输和使用。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (2872, 3404, '《危险化学品安全管理条例》（国务院令第591号，2011年12月1日起施行）；《化学品分类和标签规范》（GB 30000系列标准）；《工作场所安全使用化学品规定》（劳部发[1996]423号）等法规。针对危险化学品的安全使用、生产、储存、运输、装卸等方面均作了相应规定。《化学品分类和标签规范》系列标准，将该物质划为：易燃液体，类别3；急性毒性-经口，类别2；急性毒性-经皮，类别2；急性毒性-吸入，类别2；皮肤腐蚀/刺激，类别2；严重眼损伤/眼刺激，类别2。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
