INSERT INTO `msds_regulatory` VALUES (2895, 3428, '危险化学品目录序号：946。GHS危险性分类：易燃液体类别3（高闪点液体）。该化学品受《危险化学品安全管理条例》监管。运输受《危险货物运输规则》监管。使用和储存应遵守相关法律法规要求。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (2896, 3429, '《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录》（2015版）、《危险货物品名表》（GB 12268-2012）、《危险货物运输包装通用技术条件》（GB 12463-2009）、《危险货物道路运输安全管理办法》（交通运输部令2019年第29号）。本品属于第3.2类中闪点易燃液体，应按照相关法规进行生产、储存、运输和使用。本品有毒，需严格控制接触。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
