INSERT INTO `msds_regulatory` VALUES (2901, 3434, '国内法规：危险化学品安全管理条例、危险化学品目录（2015版）；国际法规：美国有毒物质控制法案(TSCA)目录', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (2902, 3435, '《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录》（2015版）、《危险货物品名表》（GB 12268-2012）、《危险货物运输包装通用技术条件》（GB 12463-2009）、《危险货物道路运输安全管理办法》（交通运输部令2019年第29号）。本品属于第6.1类毒害品，应按照相关法规进行生产、储存、运输和使用。本品为高毒化学品，具腐蚀性，可致人体灼伤，需严格控制接触。本品为可疑致癌物（IARC分类：2B类），需严格控制接触。应严格执行极毒物品\"五双\"管理制度。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (2903, 3436, '《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录》（2015版）、《危险货物品名表》（GB 12268-2012）、《危险货物运输包装通用技术条件》（GB 12463-2009）、《危险货物道路运输安全管理办法》（交通运输部令2019年第29号）。本品属于第3.1类低闪点易燃液体，应按照相关法规进行生产、储存、运输和使用。注意：能发生聚合反应，需添加阻聚剂。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (2904, 3437, '《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录》（2015版）、《危险货物品名表》（GB 12268-2012）、《危险货物运输包装通用技术条件》（GB 12463-2009）、《危险货物道路运输安全管理办法》（交通运输部令2019年第29号）。本品属于第3.3类高闪点易燃液体，应按照相关法规进行生产、储存、运输和使用。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (2905, 3438, '危险化学品安全管理条例（国务院令第591号），工作场所安全使用化学品规定([1996]劳部发423号）等法规，针对危险化学品的安全使用、生产、储存、运输、装卸等方面均作了相应规定。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (2906, 3439, '国内化学品管理法规：\n1. 《危险化学品安全管理条例》（国务院令第591号）\n2. 《危险化学品目录》（2015版）序号：1035\n3. 《易制毒化学品管理条例》（国务院令第445号）\n4. 《重点监管的危险化学品名录》\n\n国家标准：\n1. GB 13690-2009《化学品分类和危险性公示 通则》\n2. GB 15258-2009《化学品安全标签编写规定》\n3. GB 16483-2008《化学品安全技术说明书 内容和项目顺序》\n4. GB/T 17519-2013《化学品安全技术说明书编写指南》\n5. GB 6944-2012《危险货物分类和品名编号》\n6. GB 12268-2012《危险货物品名表》\n\n国际法规：\n1. UN GHS（全球化学品统一分类和标签制度）\n2. IATA-DGR（国际航空运输危险物品规则）\n3. IMDG Code（国际海运危险货物规则）\n4. ADR（国际公路运输危险货物协定）\n5. RID（国际铁路运输危险货物规则）\n6. OSHA HCS（美国职业安全与健康管理局危险通信标准）\n7. EU REACH法规\n8. EU CLP法规\n\n特殊法规要求：\n- 危险性分类：第3类易燃液体（Class 3）\n- 包装类别：III类（PG 3）\n- 联合国编号：UN 1105\n- 危险货物编号：33553\n- 危险化学品目录序号：1035\n- GHS分类：易燃液体，类别3；特异性靶器官毒性-一次接触，类别3', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (2907, 3440, '国内法规：《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录（2015版）》（序号1037）、《易制毒化学品管理条例》、《危险化学品经营许可证管理办法》、《危险化学品登记管理办法》、《工作场所安全使用化学品规定》、《危险化学品包装物、容器定点生产管理办法》。国际法规：联合国《关于危险货物运输的建议书》（TDG）、《全球化学品统一分类和标签制度》（GHS）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (2908, 3441, '《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录》（2015版）、《危险货物品名表》（GB 12268-2012）、《危险货物运输包装通用技术条件》（GB 12463-2009）、《危险货物道路运输安全管理办法》（交通运输部令2019年第29号）。本品属于第3.1类低闪点易燃液体，应按照相关法规进行生产、储存、运输和使用。注意：能发生聚合反应，需添加阻聚剂。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (2909, 3442, '《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录》（2015版）、《危险货物品名表》（GB 12268-2012）、《危险货物运输包装通用技术条件》（GB 12463-2009）、《危险货物道路运输安全管理办法》（交通运输部令2019年第29号）。本品属于第3.3类高闪点易燃液体，属低毒类，具刺激性，应按照相关法规进行生产、储存、运输和使用。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
