INSERT INTO `msds_regulatory` VALUES (2922, 3455, '该化学品属于《危险化学品目录（2015版）》中标注为剧毒的化学品，危险化学品目录序号：1071。生产、储存、经营、运输、使用和废弃处置等活动，应严格遵守《危险化学品安全管理条例》、《剧毒化学品购买和公路运输许可证件管理办法》、《易制毒化学品管理条例》等相关法律法规的规定。应向当地安全生产监督管理部门、公安机关、环境保护部门等有关部门办理相关许可手续。该物质属于第6.1类毒害品，联合国编号UN 1598。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (2923, 3456, '国内化学品安全管理法规：《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录（2015版）》、《易制毒化学品管理条例》。国际法规：联合国《关于危险货物运输的建议书》（TDG）、《全球化学品统一分类和标签制度》（GHS）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (2924, 3457, '《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录》（2015版）、《危险货物品名表》（GB 12268-2012）、《危险货物运输包装通用技术条件》（GB 12463-2009）、《危险货物道路运输安全管理办法》（交通运输部令2019年第29号）。本品属于第6.1类毒害品，应按照相关法规进行生产、储存、运输和使用。本品为可疑致癌物（IARC分类：2B类），需严格控制接触。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (2925, 3458, '《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录》（2015版）、《危险货物品名表》（GB 12268-2012）、《危险货物运输包装通用技术条件》（GB 12463-2009）、《危险货物道路运输安全管理办法》（交通运输部令2019年第29号）。本品属于第3.3类高闪点易燃液体，属低毒类，应按照相关法规进行生产、储存、运输和使用。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (2926, 3459, NULL, '化学危险物品安全管理条例(1987年2月17日国务院发布)，化学危险物品安全管理条例实施细则(化劳发[1992]677号)，工作场所安全使用化学品规定([1996]劳部发423号)，危险化学品安全管理条例(国务院令第591号)等。', NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (2927, 3460, NULL, '危险化学品安全管理条例（国务院令344号，2002年1月26日发布），针对化学危险品的安全使用、生产、储存、运输、装卸等方面均作了相应规定；危险货物品名表（GB12268）；危险化学品目录。', NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (2928, 3461, '《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录》（2015版）、《危险货物品名表》（GB 12268-2012）、《危险货物运输包装通用技术条件》（GB 12463-2009）、《危险货物道路运输安全管理办法》（交通运输部令2019年第29号）。本品属于第3.1类低闪点易燃液体，极度易燃，资料报道有致突变作用，应按照相关法规进行生产、储存、运输和使用。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (2929, 3462, '危险化学品安全管理条例(国务院令第591号)，工作场所安全使用化学品规定([1996]劳部发423号)等法规，针对化学危险品的安全使用、生产、储存、运输、装卸等方面均作了相应规定；常用危险化学品的分类及标志(GB 13690-92)将该物质划为第3.2类中闪点易燃液体。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
