INSERT INTO `msds_regulatory` VALUES (2999, 3535, '国内法规：危险化学品安全管理条例（国务院令第591号）；常用危险化学品贮存通则（GB 15603-2022）；化学品安全技术说明书内容和项目顺序（GB/T 16483-2008）；化学品安全技术说明书编写规定（GB/T 17519-2013）。国际法规：联合国全球化学品统一分类和标签制度（GHS）；国际海运危险货物规则（IMDG Code）；国际空运危险货物规则（IATA-DGR）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
