INSERT INTO `msds_regulatory` VALUES (3028, 3565, '遵守《中华人民共和国危险化学品安全管理条例》。遵守《危险化学品目录（2015版）》相关规定。遵守GB/T 16483-2008《化学品安全技术说明书 内容和项目顺序》和GB/T 17519-2013《化学品安全技术说明书编写指南》标准要求。其他适用法规：《工作场所安全使用化学品规定》、《易制毒化学品管理条例》等。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3029, 3566, '本化学品属于危险化学品，分类为自反应物质和混合物B型（危险品编号112）。应遵守《危险化学品安全管理条例》、《易制爆危险化学品治安管理办法》、《危险货物道路运输规则》（JT/T 617）等相关法律法规。在生产、储存、运输、使用和废弃处置过程中，应严格遵守国家有关危险化学品安全管理的规定。该物质涉及重氮工艺，属于重点监管的危险化工工艺。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3030, 3567, NULL, '危险化学品安全管理条例（国务院令第591号）；危险化学品目录（2015版）；化学品安全技术说明书内容和项目顺序（GB/T 16483-2008）；化学品安全技术说明书编写指南（GB/T 17519-2013）。', NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3031, 3568, NULL, '《危险化学品安全管理条例》、《危险化学品目录》、《易制毒化学品管理条例》、《危险货物道路运输安全管理办法》', NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3032, 3569, NULL, '《危险化学品安全管理条例》（国务院令第591号）；《危险化学品目录（2015版）》；《农药管理条例》；《剧毒化学品目录》。', NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3033, 3570, '国内法规：危险化学品安全管理条例（国务院令第591号）；易制毒化学品管理条例；农药管理条例。国际法规：联合国《关于危险货物运输的建议书》（TDG）；联合国《全球化学品统一分类和标签制度》（GHS）；国际海事组织《国际海运危险货物规则》（IMDG Code）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3034, 3571, '1. 国内法规：《中华人民共和国农药管理条例》（1997年5月8日起施行，最新修订于2022年）、《危险化学品安全管理条例》（国务院令第591号）、《中华人民共和国职业病防治法》、《中华人民共和国环境保护法》等。2. 国际法规：欧盟REACH法规（化学品注册、评估、授权和限制法规，EC No 1907/2006）、美国TSCA法案（有毒物质控制法案，Toxic Substances Control Act）等。3. 本产品属于氨基甲酸酯类杀虫剂，应严格按照农药标签标注的使用范围、使用方法和剂量、使用技术要求和注意事项使用，不得扩大使用范围、加大用药剂量或改变使用方法。4. 生产、经营和使用本产品必须取得相应的农药登记证、生产许可证和经营许可证。5. 运输和储存必须符合危险化学品安全管理相关规定。6. 本产品列入《危险化学品目录（2022年调整版）》，序号：1113。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3035, 3572, '国内法规：危险化学品安全管理条例、易制毒化学品管理条例、农药管理条例。国际法规：欧盟CLP法规（EC）No 1272/2008、美国TSCA、日本化审法。GHS分类：急性毒性类别3（经口），生殖毒性类别1B，特异性靶器官毒性-反复接触类别2。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3036, 3573, '危险化学品目录（2015版）列入。列入《重点环境管理危险化学品目录》。列入《限制和控制危险化学品目录》。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3037, 3574, '危险化学品目录序号：542。该物质为致癌物，对动物有强致癌作用，对人为可疑致癌物。IARC致癌性分类：2B组（可能对人类致癌）。该物质被列入《危险化学品目录》和《易制毒化学品目录》。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3038, 3575, '国内法规：《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录（2015版）及2022年调整版》、《危险货物品名表》（GB12268）、《化学品分类和危险性公示通则》（GB13690）、《化学品安全技术说明书内容和项目顺序》（GB/T16483-2008）、《化学品安全技术说明书编写规定》（GB/T17519-2013）。该化学品属于第8.2类碱性腐蚀品，需按照危险化学品进行管理。列入《危险化学品目录（2015版）及2022年调整版》。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3039, 3576, '《危险化学品安全管理条例》、《危险化学品目录》（2022年调整版）', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3040, 3577, '国内法规：列入《危险化学品目录（2015版）》，CAS号67567-23-1。适用《危险化学品安全管理条例》（国务院令第591号）、《危险化学品安全管理条例实施细则》、《危险化学品经营许可证管理办法》等法规。国际法规：符合联合国《关于危险货物运输的建议书》（TDG）、《国际海运危险货物规则》（IMDG Code）、《国际空运危险货物规则》（IATA DGR）和欧盟《化学品注册、评估、授权和限制法规》（REACH）的要求。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3041, 3578, '危险化学品安全管理条例（国务院令第591号）、易制毒化学品管理条例、危险化学品目录（2022年调整版）、危险货物分类和品名编号（GB 6944）、危险货物品名表（GB 12268）、化学品安全技术说明书内容和项目顺序（GB/T 16483）、化学品安全标签编写规定（GB 15258）、工作场所安全使用化学品规定（〔1996〕劳部发423号）', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3042, 3579, '列入《危险化学品目录（2022版）》，危险化学品目录序号：458。危险货物编号：32009。UN编号：1262。该化学品属于易燃液体，需按照《危险化学品安全管理条例》进行管理。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3043, 3580, '危险化学品安全管理条例(国务院令第591号)、工作场所安全使用化学品规定([1996]劳部发423号)等法规，针对危险化学品的安全使用、生产、储存、运输、装卸等方面均作了相应规定；常用危险化学品的分类及标志(GB 13690)将该物质划为第3.2类中闪点易燃液体；车间空气中3,3-二甲基戊烷卫生标准(GB 16231-1996)，规定了车间空气中该物质的最高容许浓度及检测方法。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
