INSERT INTO `msds_regulatory` VALUES (3071, 3608, NULL, '列入《危险化学品目录（2022调整版）》，标注为\"剧毒\"。受《危险化学品安全管理条例》（国务院令第591号）监管。剧毒化学品的生产、经营、储存、使用、运输等活动必须取得相应的许可证，并严格遵守\"五双\"管理制度（双人收发、双人记账、双人双锁、双人运输、双人使用）。', NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
