INSERT INTO `msds_regulatory` VALUES (3081, 3618, '列入《危险化学品目录（2022调整版）》，危险性类别：易燃液体，类别3；急性毒性-经口，类别3；严重眼损伤/眼刺激，类别1。受《危险化学品安全管理条例》（国务院令第591号）监管。危险化学品的生产、经营、储存、使用、运输等活动必须取得相应的许可证，并严格遵守相关法规要求。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3082, 3619, '国内法规：危险化学品安全管理条例（国务院令第591号）；易制毒化学品管理条例；农药管理条例。国际法规：联合国关于危险货物运输的建议书（TDG）；全球化学品统一分类和标签制度（GHS）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3083, 3620, '本品属于危险化学品，需按照相关法规进行管理。作为农药，需遵守农药管理条例的相关规定。', '危险化学品安全管理条例、农药管理条例', NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
