INSERT INTO `msds_regulatory` VALUES (3126, 3663, '国内法规：《危险化学品安全管理条例》、《危险化学品目录（2015版）》、《危险货物分类和品名编号》（GB 6944）、《危险货物品名表》（GB 12268）、《危险化学品安全管理条例》（国务院令第591号）、《易制毒化学品管理条例》、《危险废物经营许可证管理办法》。国际法规：《联合国关于危险货物运输的建议书》（TDG）、《国际海运危险货物规则》（IMDG Code）、《国际空运危险货物规则》（IATA DGR）、《全球化学品统一分类和标签制度》（GHS）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3127, 3664, '《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录》（2015版）、《危险货物品名表》（GB 12268-2012）、《危险货物运输包装通用技术条件》（GB 12463-2009）、《危险货物道路运输安全管理办法》（交通运输部令2019年第29号）。本品属于第8.1类酸性腐蚀品，具腐蚀性、刺激性，可致人体灼伤，应按照相关法规进行生产、储存、运输和使用。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3128, 3665, '国内化学品安全管理法规：《危险化学品安全管理条例》、《易制毒化学品管理条例》、《危险化学品目录（2015版）》等。海关编码：29159080。国际法规：符合联合国《关于危险货物运输的建议书》（UNRTDG）和GHS全球化学品统一分类和标签制度的要求。危险品运输编码：UN 3272。WGK德国：3。危险类别码：R10（易燃）、R36/37/38（刺激眼睛、呼吸系统和皮肤）。安全说明：S26（万一接触眼睛，立即使用大量清水冲洗并就医）、S36（穿戴适当的防护服）、S37/39（戴手套和护目镜或面具）、S16（远离火源）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3129, 3666, '《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录》（2015版）、《危险货物品名表》（GB 12268-2012）、《危险货物运输包装通用技术条件》（GB 12463-2009）、《危险货物道路运输安全管理办法》（交通运输部令2019年第29号）。本品属于第3.1类低闪点易燃液体，应按照相关法规进行生产、储存、运输和使用。本品为可疑致癌物（IARC分类：2B类），需严格控制接触。注意：能发生聚合反应，需添加阻聚剂。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3130, 3667, '国内法规：《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录（2015版）》、《易制毒化学品管理条例》（国务院令第445号）、《工作场所安全使用化学品规定》（劳部发[1996]423号）、《危险化学品安全管理条例》（国务院令第645号）、《危险化学品登记管理办法》（国家安监总局令第53号）、《危险化学品经营许可证管理办法》（国家安监总局令第55号）、《危险化学品生产企业安全生产许可证实施办法》（国家安监总局令第41号）。国际法规：联合国《关于危险货物运输的建议书规章范本》（TDG）、《全球化学品统一分类和标签制度》（GHS）、《国际海运危险货物规则》（IMDG Code）、《国际空运危险货物规则》（IATA-DGR）。技术标准：GB 6944-2012《危险货物分类和品名编号》、GB 13690-2009《化学品分类和危险性公示 通则》、GB 30000.2-2013《化学品分类和标签规范 第2部分：易燃气体》、GB 30000.3-2013《化学品分类和标签规范 第3部分：易燃气溶胶》、GB 30000.4-2013《化学品分类和标签规范 第4部分：氧化性气体》、GB 30000.5-2013《化学品分类和标签规范 第5部分：压力下气体》、GB 30000.7-2013《化学品分类和标签规范 第7部分：易燃液体》、GB 30000.8-2013《化学品分类和标签规范 第8部分：自反应物质和混合物》、GB 30000.9-2013《化学品分类和标签规范 第9部分：自燃液体》、GB 30000.10-2013《化学品分类和标签规范 第10部分：自燃固体》、GB 30000.11-2013《化学品分类和标签规范 第11部分：自热物质和混合物》、GB 30000.12-2013《化学品分类和标签规范 第12部分：遇水放出易燃气体的物质和混合物》、GB 30000.13-2013《化学品分类和标签规范 第13部分：氧化性液体》、GB 30000.14-2013《化学品分类和标签规范 第14部分：氧化性固体》、GB 30000.15-2013《化学品分类和标签规范 第15部分：有机过氧化物》、GB 30000.16-2013《化学品分类和标签规范 第16部分：金属腐蚀剂》、GB 30000.18-2013《化学品分类和标签规范 第18部分：急性毒性》、GB 30000.19-2013《化学品分类和标签规范 第19部分：皮肤腐蚀/刺激》、GB 30000.20-2013《化学品分类和标签规范 第20部分：严重眼损伤/眼刺激》、GB 30000.21-2013《化学品分类和标签规范 第21部分：呼吸道或皮肤致敏》、GB 30000.22-2013《化学品分类和标签规范 第22部分：生殖细胞致突变性》、GB 30000.23-2013《化学品分类和标签规范 第23部分：致癌性》、GB 30000.24-2013《化学品分类和标签规范 第24部分：生殖毒性》、GB 30000.25-2013《化学品分类和标签规范 第25部分：特异性靶器官毒性 一次接触》、GB 30000.26-2013《化学品分类和标签规范 第26部分：特异性靶器官毒性 反复接触》、GB 30000.27-2013《化学品分类和标签规范 第27部分：对水环境的危害》、GB 30000.28-2013《化学品分类和标签规范 第28部分：对水环境的危害（慢性毒性）》、GB 15603-1995《常用化学危险品贮存通则》、GB 18218-2018《危险化学品重大危险源辨识》、GB/T 16483-2008《化学品安全技术说明书 内容和项目顺序》、GB/T 17519-2013《化学品安全技术说明书编写指南》、AQ 3015-2008《氯碱生产企业安全标准化实施指南》。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
