INSERT INTO `msds_regulatory` VALUES (3132, 3669, '《危险化学品安全管理条例》（国务院令第591号），针对危险化学品的安全生产、使用、储存、运输、经营和进出口等方面均有相关规定。《危险化学品目录（2015版）》，列入第3.3类高闪点易燃液体。《易制毒化学品管理条例》，未列入管制。《剧毒化学品目录》，未列入管制。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
