INSERT INTO `msds_regulatory` VALUES (3141, 3678, '国内化学品安全管理法规：《危险化学品安全管理条例》（国务院令第591号），针对危险化学品的安全生产、使用、储存、运输、经营和废弃处置等方面的管理。工作场所安全使用化学品规定：《工作场所安全使用化学品规定》([1996]劳部发423号），规定了工作场所使用化学品的安全要求。危险货物运输管理：《危险货物分类和品名编号》（GB 6944）、《危险货物品名表》（GB 12268）等标准。国际法规：符合联合国《关于危险货物运输的建议书》（TDG）和全球化学品统一分类和标签制度（GHS）的要求。（来源：检索补充）', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
