INSERT INTO `msds_regulatory` VALUES (3177, 3714, '国内法规：危险化学品安全管理条例（国务院令第591号），工作场所安全使用化学品规定（劳部发[1996]423号），危险化学品目录（2015版）。国际法规：欧盟REACH法规（EC）No 1907/2006，欧盟CLP法规（EC）No 1272/2008。联苯胺被列入《国际癌症研究机构（IARC）致癌物清单》第1组。被列入《中国优先控制化学品名录（第一批）》。被列入《斯德哥尔摩公约》持久性有机污染物清单。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3178, 3715, '危险化学品安全管理条例（国务院令第591号），工作场所安全使用化学品规定（〔1996〕劳部发423号）等法规，针对化学危险品的安全使用、生产、储存、运输、装卸等方面均作了相应规定。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
