INSERT INTO `msds_regulatory` VALUES (3180, 3717, NULL, '国内化学品管理法规：危险化学品安全管理条例（国务院令第591号）、危险化学品目录（2022调整版）、危险化学品安全管理条例实施细则、危险化学品登记管理办法、危险化学品经营许可证管理办法、危险化学品安全使用许可证实施办法、危险化学品生产、储存装置个人可接受风险标准和社会可接受风险标准（试行）', NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3181, 3718, '《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录》（2015版）、《危险货物品名表》（GB 12268-2012）、《危险货物运输包装通用技术条件》（GB 12463-2009）、《危险货物道路运输安全管理办法》（交通运输部令2019年第29号）。本品属于第4.1类易燃固体，干燥状态下受摩擦、震动、撞击可引起爆炸，有毒，应按照相关法规进行生产、储存、运输和使用。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3182, 3719, '《危险化学品安全管理条例》、《民用爆炸物品安全管理条例》、《危险货物道路运输安全管理办法》', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3183, 3720, '国内法规：《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录（2015版）》、《易制爆危险化学品名录》、《危险化学品禁止、限制和控制目录》等。该化学品被列为爆炸物，1.3项，属于严格管控的高风险危险化学品，在多个地区被列入禁止或限制引进目录。国际法规：符合联合国《关于危险货物运输的建议书》（TDG）和《全球化学品统一分类和标签制度》（GHS）的相关要求。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3184, 3721, '按照《危险化学品安全管理条例》、《易制毒化学品管理条例》等相关法律法规进行管理。属于第6.1类毒害品，UN编号2811。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
