INSERT INTO `msds_regulatory` VALUES (3205, 3743, '危险化学品安全管理条例、易制毒化学品管理条例、剧毒化学品目录（2015版）。该化学品被列入《剧毒化学品目录（2015版）》，属于剧毒化学品，生产、经营、储存、运输、使用等环节需严格遵守相关法律法规。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3206, 3745, NULL, '《危险化学品安全管理条例》（国务院令第591号）\n        《危险化学品目录》（2015版）\n        《危险货物品名表》（GB 12268-2012）\n        《危险货物运输包装通用技术条件》（GB 12463-2009）\n        《危险货物道路运输安全管理办法》（交通运输部令2019年第29号）\n        本品属于第6.1类毒害品，应按照相关法规进行生产、储存、运输和使用\n        本品为高毒化学品，具腐蚀性，可致人体灼伤，需严格控制接触。本品为可疑致癌物（IARC分类：2B类），需严格控制接触\n        应严格执行极毒物品\"五双\"管理制度', NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3207, 3746, '无资料', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3208, 3747, '国内法规：《危险化学品安全管理条例》、《工作场所安全使用化学品规定》、《常用危险化学品的分类及标志》(GB 13690-92)等法规，针对危险化学品的安全使用、生产、储存、运输、装卸等方面均作了相应规定。国际法规：欧盟REACH法规、美国TSCA法规、日本化审法等。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3209, 3748, '《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录》（2015版）、《危险货物品名表》（GB 12268-2012）、《危险货物运输包装通用技术条件》（GB 12463-2009）、《危险货物道路运输安全管理办法》（交通运输部令2019年第29号）。本品属于第3.3类高闪点易燃液体，对眼有强烈刺激性可导致永久性失明，有麻醉作用，应按照相关法规进行生产、储存、运输和使用。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3210, 3749, '危险化学品安全管理条例、易制毒化学品管理条例、危险化学品登记管理办法。符合联合国《关于危险货物运输的建议书》和GHS（全球化学品统一分类和标签制度）要求。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
