INSERT INTO `msds_regulatory` VALUES (3274, 3817, '危险化学品安全管理条例（国务院令第591号），工作场所安全使用化学品规定（〔1996〕劳部发423号），危险化学品目录（2015版），易制爆危险化学品名录（2017版），剧毒化学品目录（2015版）等。本产品符合《危险化学品安全管理条例》的相关规定。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
