INSERT INTO `msds_regulatory` VALUES (3276, 3819, '危险化学品安全管理条例（国务院令第591号）工作场所安全使用化学品规定（[1996]劳部发423号）等法规，针对化学危险品的安全使用、生产、储存、运输、装卸等方面均作了相应规定。危险化学品目录（2015版）：该物质列入危险化学品目录。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3277, 3821, '国内化学品安全管理法规：《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录（2015版）》、《工作场所安全使用化学品规定》（〔1996〕劳部发423号）。国际法规：联合国关于危险货物运输的建议书（TDG）、全球化学品统一分类和标签制度（GHS）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3278, 3822, '危险化学品目录（2015版）：第2481号。易制爆危险化学品名录（2017版）：未列入。剧毒化学品目录（2015版）：未列入。中国GHS分类：第4.2类自燃物品；皮肤腐蚀/刺激，类别2。国际法规：UN1369，IMDG Code Class 4.2，PG II。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3279, 3823, '国内法规：《危险化学品安全管理条例》、《危险化学品目录（2015版）》；国际法规：联合国《关于危险货物运输的建议书》、欧盟REACH法规', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3280, 3824, '危险化学品目录（2015版）：第2482号。易制爆危险化学品名录（2017版）：未列入。剧毒化学品目录（2015版）：未列入。中国GHS分类：第4.1类易燃固体；皮肤腐蚀/刺激，类别2。国际法规：UN3236，IMDG Code Class 4.1，PG III。本化学品安全技术说明书按照 GB/T 16483、GB/T 17519 标准编制。列入美国有毒物质控制法案(TSCA)目录。列入《化妆品禁用原料目录2021》。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3281, 3825, '危险化学品安全管理条例（国务院令第591号）；危险货物分类和品名编号（GB 6944）；危险货物品名表（GB 12268）；危险化学品目录（2015版）；工作场所安全使用化学品规定（[1996]劳部发423号）等法规的规定。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3282, 3826, '危险化学品目录（2015版）：序号2664。危险化学品安全管理条例：该化学品属于危险化学品，应严格遵守《危险化学品安全管理条例》等相关法律法规。GB 6944-2012《危险货物分类和品名编号》：第3类易燃液体。GB 12268-2012《危险货物品名表》：UN 3295。工作场所安全使用化学品规定：应遵守《工作场所安全使用化学品规定》的相关要求。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3283, 3827, '危险化学品安全管理条例（国务院令第591号）；危险货物分类和品名编号（GB 6944）；危险货物品名表（GB 12268）；危险化学品目录（2015版）；工作场所安全使用化学品规定（[1996]劳部发423号）等法规的规定。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3284, 3828, '国内法规：《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录（2015版）》。国际法规：联合国《关于危险货物运输的建议书》（TDG）、《国际海运危险货物规则》（IMDG Code）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3285, 3829, '列入《危险化学品目录（2015版）》，属于危险化学品。根据《危险化学品安全管理条例》进行管理。根据《易制毒化学品管理条例》进行管理。根据《剧毒化学品购买和公路运输许可证件管理办法》进行管理。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3286, 3830, '国内法规：《危险化学品安全管理条例》（国务院令第591号）、《安全生产法》、《危险化学品目录（2015版）》、《化学品安全技术说明书 内容和项目顺序》（GB/T 16483-2008）、《化学品分类和危险性公示 通则》（GB 13690-2009）。国际法规：联合国《全球化学品统一分类和标签制度》（GHS）、《国际海运危险货物规则》（IMDG Code）、《国际空运危险货物规则》（IATA DGR）。该化学品属于第6.1类毒害品，需按照相关法规要求进行管理、储存、运输和使用。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3287, 3831, '国内法规：危险化学品安全管理条例、易制毒化学品管理条例、工作场所安全使用化学品规定、危险货物运输规则、危险化学品目录（2015版）、GB/T 16483-2008化学品安全技术说明书 内容和项目顺序、GB 6944-2012危险货物分类和品名编号、GB 13690-2009化学品分类和危险性公示 通则。国际法规：联合国关于危险货物运输的建议书、国际化学品安全卡（ICSC）、全球化学品统一分类和标签制度（GHS）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3288, 3832, '国内法规：列入《危险化学品目录（2015版）》。根据《危险化学品安全管理条例》进行管理。国际法规：UN No. 2289，Class 8，Packing Group III。GHS危险性类别：皮肤腐蚀/刺激，类别2；严重眼损伤/眼刺激，类别1；特异性靶器官毒性-一次接触，类别3（呼吸道）；对水环境的危害-急性危害，类别2；对水环境的危害-慢性危害，类别2。安全说明：S26：万一接触眼睛，立即使用大量清水冲洗并征求医生意见。S36/37/39：穿戴适当的防护服、手套和护目镜或面罩。S45：发生意外或感到不适时，立即就医（可能时出示标签）。S61：避免释放到环境中，参阅特别说明/安全数据表。危险说明：R21/22：皮肤接触及吞食有害。R34：引起灼伤。R43：与皮肤接触可能致敏。R52/53：对水生生物有害，可能对水体环境产生长期不良影响。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3289, 3833, NULL, '危险化学品安全管理条例（国务院令第591号），易制毒化学品管理条例，剧毒化学品购买和公路运输许可证件管理办法，危险化学品目录（2015版），剧毒化学品目录（2015版）。', NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3290, 3834, '国内法规：《危险化学品安全管理条例》（国务院令第591号）、《易制毒化学品管理条例》（国务院令第445号）、《工作场所安全使用化学品规定》（[1996]劳部发423号）、《危险化学品登记管理办法》（国家安全生产监督管理总局令第53号）、《危险化学品经营许可证管理办法》（国家安全生产监督管理总局令第55号）、《危险化学品安全管理条例》（国务院令第591号）、《易制毒化学品管理条例》（国务院令第445号）。国际法规：联合国关于危险货物运输的建议书（TDG）、全球化学品统一分类和标签制度（GHS）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3291, 3835, '该物质列入《危险化学品目录（2015版）》。依据《危险化学品安全管理条例》（国务院令第591号）进行管理。危险货物分类符合《危险货物分类和品名编号》（GB 6944-2025）和《危险货物品名表》（GB 12268）的要求。MSDS编制符合《化学品安全技术说明书内容和项目顺序》（GB/T 16483-2008）和《化学品安全技术说明书项目及内容要求》（GB/T 17519-2013）标准。该物质也列入美国有毒物质控制法案（TSCA）目录。使用、储存、运输等环节应严格遵守相关法律法规要求。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3292, 3836, '《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录》（2015版）、《危险货物品名表》（GB 12268-2012）、《危险货物运输包装通用技术条件》（GB 12463-2009）、《危险货物道路运输安全管理办法》（交通运输部令2019年第29号）。本品属于第3.3类高闪点易燃液体，应按照相关法规进行生产、储存、运输和使用。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3293, 3837, '危险化学品安全管理条例（国务院令第591号），工作场所安全使用化学品规定（[1996]劳部发423号）等法规，针对化学危险品的安全使用、生产、储存、运输、装卸等方面均作了相应规定。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3294, 3838, NULL, '《危险化学品安全管理条例》（国务院令第591号）\n        《危险化学品目录》（2015版）\n        《危险货物品名表》（GB 12268-2012）\n        《危险货物运输包装通用技术条件》（GB 12463-2009）\n        《危险货物道路运输安全管理办法》（交通运输部令2019年第29号）\n        本品属于第6.1类毒害品，应按照相关法规进行生产、储存、运输和使用\n        本品为可疑致癌物（IARC分类：2B类），需严格控制接触\n        应严格执行极毒物品\"五双\"管理制度', NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3295, 3839, NULL, '危险化学品安全管理条例（国务院令第591号）；危险化学品目录（2015版）；易制毒化学品管理条例；工作场所安全使用化学品规定；危险货物运输安全管理条例。', NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3296, 3840, '国内法规：该化学品属于危险化学品，适用《危险化学品安全管理条例》（国务院令第591号）、《安全生产法》、《环境保护法》等相关法律法规。生产、储存、使用、经营和运输该化学品必须严格遵守国家相关法律法规要求，取得相应的许可证和资质。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
