INSERT INTO `msds_regulatory` VALUES (3316, 3861, '国内法规：危险化学品安全管理条例（国务院令第591号）、易制毒化学品管理条例、农药管理条例。国际法规：欧盟REACH法规、国际海运危险货物规则（IMDG Code）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3317, 3862, '本品应遵守《危险化学品安全管理条例》、《工作场所安全使用化学品规定》等相关法规。使用、储存、运输和废弃处置应符合国家有关危险化学品管理的法律法规要求。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3318, 3863, '【国内法规】\n    \n    《化学品安全技术说明书内容和项目顺序》GB/T 16483-2008\n    《化学品分类和危险性公示通则》GB 13690-2009\n    《全球化学品统一分类和标签制度》（GHS）\n    《危险化学品安全管理条例》（国务院令第591号）\n    《工作场所安全使用化学品规定》（劳动部发[1996]423号）\n    《化学品分类和标签规范》GB 30000系列\n    《化学品安全技术说明书编写规定》GB/T 17519-2013\n    《危险化学品目录》（2015版）\n    《化学品环境管理办法》（环境保护部令第2号）\n    《化学品物理危险性鉴定与分类管理办法》（国家安监总局令第60号）\n    \n    【国际法规】\n    \n    联合国《关于危险货物运输的建议书·规章范本》\n    国际海事组织《国际海运危险货物规则》（IMDG Code）\n    国际民用航空组织《危险物品安全航空运输技术细则》（ICAO TI）\n    欧洲联盟《化学品注册、评估、授权和限制法规》（REACH）\n    欧洲联盟《分类、标签和包装法规》（CLP）\n    美国《职业安全健康法》（OSHA）\n    美国《联邦杀虫剂、杀菌剂和杀鼠剂法》（FIFRA）\n    日本《化学物质审查规制法》（CSCL）\n    加拿大《环境保护法》（CEPA）\n    澳大利亚《工业化学品法》（ICNA）\n    \n    【特殊监管要求】\n    \n    由于该化学品缺乏完整的毒理学和生态毒理学数据，建议在使用前进行全面的安全评估，并建立相应的风险管理措施。在使用过程中应严格遵守相关法规要求，确保人员安全和环境保护。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3319, 3864, '国内化学品安全管理法规：危险化学品安全管理条例。国际法规：联合国关于危险货物运输的建议书（TDG）、全球化学品统一分类和标签制度（GHS）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3320, 3865, '国内化学品安全管理法规：危险化学品安全管理条例、工作场所安全使用化学品规定等。国际法规：GHS全球化学品统一分类和标签制度。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
