INSERT INTO `msds_regulatory` VALUES (3344, 3893, '国内法规：该化学品属于危险化学品，适用《危险化学品安全管理条例》（国务院令第591号）。作为农药类化学品，适用《农药管理条例》和《农药登记管理办法》，生产、经营和使用需取得农药登记证。储存、运输和使用需符合《易制爆危险化学品治安管理办法》（公安部令第154号）及相关国家标准《毒害性商品储存养护技术条件》（GB 17916-2013）等要求。国际法规：运输需符合《国际海运危险货物规则》（IMDG Code）和联合国《关于危险货物运输的建议书》（TDG）等国际运输法规要求。数据来源：危险化学品安全管理条例、农药管理条例、农药登记管理办法', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
