INSERT INTO `msds_regulatory` VALUES (3346, 3895, '国内法规：列入《危险化学品目录(2022版)》，危险化学品目录序号：36。属于第8类腐蚀性物质。生产、经营、储存、运输和使用需遵守《危险化学品安全管理条例》、《易制毒化学品管理条例》等相关法律法规。需办理危险化学品经营许可证、安全生产许可证等相关资质。国际法规：UN编号2815，IMDG Code第8类腐蚀性物质，IATA-DGR第8类腐蚀性物质。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3347, 3896, '国标编号：61834。该物质列入《危险化学品目录(2022调整版)》。适用《危险化学品安全管理条例》、《易制毒化学品管理条例》等相关法律法规。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
