INSERT INTO `msds_regulatory` VALUES (3349, 3898, '国内法规：列入《危险化学品目录（2022年调整版）》，危险化学品目录序号：77。依照《危险化学品安全管理条例》（国务院令第591号）有关规定进行管理。国际法规：GHS分类：急性经口毒性类别4；危害水生环境——急性危险类别1，危害水生环境——长期危险类别1。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
