INSERT INTO `msds_regulatory` VALUES (3453, 4013, '国内化学品管理法规：危险化学品安全管理条例、危险化学品目录（2015版）、危险货物品名表（GB 12268-2012）、危险货物运输包装通用技术条件（GB 12463-2009）、危险货物道路运输安全管理办法。国际法规：联合国关于危险货物运输的建议书（TDG）、国际海事组织国际海运危险货物规则（IMDG Code）、国际民用航空组织危险物品安全航空运输技术细则（ICAO TI/IATA DGR）。GHS危险性分类：急性毒性-经口类别2；急性毒性-经皮类别3；皮肤腐蚀/刺激类别2；严重眼损伤/眼刺激类别2A；特异性靶器官毒性-一次接触类别3；对水环境的危害-急性毒性类别1。Hazard Statements：H300（吞咽致命）、H311（皮肤接触有毒）、H315（造成皮肤刺激）、H319（造成严重眼刺激）、H335（可能引起呼吸道刺激）、H410（对水生生物毒性极大并具有长期持续影响）。Precautionary Statements：P201（在使用前获取特别指示）、P202（在阅读并明了所有安全措施前切勿处置）、P260（不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾）、P264（作业后彻底清洗）、P270（使用本产品时不要进食、饮水或吸烟）、P273（避免释放到环境中）、P280（穿戴防护手套/防护服/护眼/防护面具）、P301+P310（如误吞咽：立即呼叫解毒中心或医生）、P302+P352（如皮肤沾染：用大量肥皂和水清洗）、P305+P351+P338（如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗）、P308+P313（如接触到或有疑虑：求医/就诊）、P310（立即呼叫解毒中心或医生）、P321（具体治疗）、P322（具体措施）、P330（漱口）、P332+P313（如发生皮肤刺激：求医/就诊）、P337+P313（如发生眼刺激：求医/就诊）、P362（脱掉沾染的衣服，清洗后方可重新使用）、P363（沾染的衣服清洗后方可重新使用）、P391（收集溢出物）、P405（存放处须加锁）、P501（按当地法规处置内装物/容器）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3454, 4014, '危险化学品安全管理条例（国务院令第591号），工作场所安全使用化学品规定（[1996]劳部发423号）等法规，针对危险化学品的安全使用、生产、储存、运输、装卸等方面均作了相应规定。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3455, 4015, '国内法规：危险化学品安全管理条例（国务院令第591号），工作场所安全使用化学品规定（劳部发[1996]423号）等法规，针对危险化学品的安全使用、生产、储存、运输、装卸等方面均作了相应规定。国际法规：联合国关于危险货物运输的建议书（TDG），国际海事组织（IMO）国际海运危险货物规则（IMDG Code），国际民航组织（ICAO）国际空运危险货物规则（IATA DGR），欧盟化学品注册、评估、授权和限制法规（REACH），全球化学品统一分类和标签制度（GHS）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3456, 4016, '列入《危险化学品目录（2015版）》，序号2828。EC号：219-956-7。该化学品属于易燃固体类别2、呼吸道致敏物类别1、危害水生环境-长期危害类别3。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3457, 4017, '国内法规：《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录（2015版）》、《危险化学品登记管理办法》。国际法规：联合国《关于危险货物运输的建议书》（TDG）、《全球化学品统一分类和标签制度》（GHS）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3458, 4018, '国内法规：危险化学品安全管理条例（国务院令第591号）。本产品列入《危险化学品目录（2015版）》。技术说明书编码：1129。国际法规：IMDG Code（国际海运危险货物规则），IATA-DGR（国际空运危险货物规则），ADR（国际公路运输危险货物规则）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3459, 4019, '危险化学品名录。UN 3129，危险类别4.3，包装类别II。GHS危险性类别：遇水放出易燃气体的物质和混合物，类别1；皮肤腐蚀/刺激，类别1B；严重眼损伤/眼刺激，类别1B；对水生环境的危害-急性危害，类别1。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3460, 4020, '国内法规：危险化学品安全管理条例（国务院令第591号），危险化学品目录（2015版），易制毒化学品管理条例；氨基磺酸属于第8.1类酸性腐蚀品，需按照危险化学品进行管理。产品标准：HG/T 2527-2011《工业氨基磺酸》。国际法规：欧盟REACH法规，美国TSCA法规，日本化审法（CSCL）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3461, 4021, '危险化学品目录（2015版）序号27。依据《危险化学品安全管理条例》进行管理。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
