INSERT INTO `msds_regulatory` VALUES (3472, 4032, '国内法规：列入《危险化学品目录》。属于持久性有机污染物，按照《关于持久性有机污染物的斯德哥尔摩公约》和《持久性有机污染物防治条例》进行管理。已禁止生产、使用和进出口。国际法规：列入《斯德哥尔摩公约》附件A（消除类）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
