INSERT INTO `msds_regulatory` VALUES (3544, 4142, '国内法规：危险化学品安全管理条例（国务院令第591号），工作场所安全使用化学品规定（劳部发[1996]423号）等法规，针对危险化学品的安全使用、生产、储存、运输、装卸等方面均作了相应规定。国际法规：联合国关于危险货物运输的建议书（TDG），国际海事组织（IMO）国际海运危险货物规则（IMDG Code），国际民航组织（ICAO）国际空运危险货物规则（IATA DGR），欧盟化学品注册、评估、授权和限制法规（REACH），全球化学品统一分类和标签制度（GHS）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3545, 4143, '国内法规：危险化学品安全管理条例（国务院令第591号）、易制爆危险化学品治安管理办法（公安部令第154号）、危险化学品目录（2015版）。国际法规：联合国关于危险货物运输的建议书（TDG）、国际海运危险货物规则（IMDG Code）、国际民航组织危险物品安全航空运输技术细则（ICAO-TI）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3546, 4144, '国内法规：危险化学品安全管理条例（国务院令第591号）、易制爆危险化学品治安管理办法（公安部令第154号）、危险化学品目录（2015版）。国际法规：联合国关于危险货物运输的建议书（TDG）、国际海运危险货物规则（IMDG Code）、国际民航组织危险物品安全航空运输技术细则（ICAO-TI）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3547, 4145, '国内化学品管理法规：危险化学品安全管理条例、易制毒化学品管理条例、危险化学品登记管理办法。国际法规：联合国关于危险货物运输的建议书（TDG）、国际海运危险货物规则（IMDG Code）、国际空运危险货物规则（IATA-DGR）。GHS危险性分类：易燃气体类别1。Hazard Statements：H220 极易燃气体。Precautionary Statements：P210 远离热源/火花/明火/热表面。禁止吸烟。P280 戴防护手套/穿防护服/戴护目镜/戴面罩。P403+P235 存放在通风良好的地方。保持低温。P410+P403 防日晒。存放于通风良好处。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3548, 4146, '国内法规：《危险化学品安全管理条例》、《药品管理法》；国际法规：GHS（全球化学品统一分类和标签制度）、ADR（国际公路运输危险货物协定）', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3549, 4147, '国内化学品管理法规：危险化学品安全管理条例、易制毒化学品管理条例、工作场所安全使用化学品规定、危险化学品登记管理办法。国际法规：联合国关于危险货物运输的建议书（橙皮书）、国际海运危险货物规则（IMDG Code）、国际空运危险货物规则（IATA-DGR）。GHS危险性分类：急性毒性类别4；皮肤腐蚀/刺激类别2；严重眼损伤/眼刺激类别2；对水环境的危害-急性类别1；对水环境的危害-慢性类别1。Hazard Statements: H302 吞咽有害。H315 造成皮肤刺激。H319 造成严重眼刺激。H410 对水生生物毒性极大并具有长期持续影响。Precautionary Statements: P260 不要吸入粉尘、烟、气体、烟雾、蒸气、喷雾。P264 作业后彻底清洗。P270 禁止本产品使用时进食、饮水或吸烟。P273 避免释放到环境中。P280 戴防护手套/穿防护服/戴护目镜/戴面罩。P301+P312 如误吞咽：如感觉不适，呼叫中毒控制中心或医生。P302+P352 如皮肤沾染：用大量肥皂和水清洗。P305+P351+P338 如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。P312 如感觉不适，呼叫中毒控制中心或医生。P332+P313 如发生皮肤刺激：求医/就诊。P337+P313 如仍觉眼刺激：求医/就诊。P391 收集溢出物。P501 按当地法规处置内装物/容器。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3550, 4148, '国内化学品管理法规：危险化学品安全管理条例、易制毒化学品管理条例、工作场所安全使用化学品规定、危险化学品登记管理办法。国际法规：联合国关于危险货物运输的建议书（橙皮书）、国际海运危险货物规则（IMDG Code）、国际空运危险货物规则（IATA-DGR）。GHS危险性分类：急性毒性类别2；皮肤腐蚀/刺激类别2；严重眼损伤/眼刺激类别2A。Hazard Statements: H302 吞咽有害。H312 皮肤接触有害。H332 吸入有害。H315 造成皮肤刺激。H319 造成严重眼刺激。H335 可能引起呼吸道刺激。Precautionary Statements: P260 不要吸入粉尘、烟、气体、烟雾、蒸气、喷雾。P264 作业后彻底清洗。P270 禁止本产品使用时进食、饮水或吸烟。P280 戴防护手套/穿防护服/戴护目镜/戴面罩。P301+P312 如误吞咽：如感觉不适，呼叫中毒控制中心或医生。P302+P352 如皮肤沾染：用大量肥皂和水清洗。P304+P340 如误吸入：将人转移到空气新鲜处，保持呼吸舒适体位。P312 如感觉不适，呼叫中毒控制中心或医生。P403+P235 存放在通风良好的地方。保持低温。P501 按当地法规处置内装物/容器。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3551, 4149, '国内化学品管理法规：危险化学品安全管理条例、易制毒化学品管理条例、工作场所安全使用化学品规定、危险化学品登记管理办法。国际法规：联合国关于危险货物运输的建议书（橙皮书）、国际海运危险货物规则（IMDG Code）、国际空运危险货物规则（IATA-DGR）。GHS危险性分类：急性毒性类别4；皮肤腐蚀/刺激类别2；严重眼损伤/眼刺激类别2A；对水环境危害-急性类别2。Hazard Statements: H302 吞咽有害。H315 造成皮肤刺激。H319 造成严重眼刺激。H335 可能引起呼吸道刺激。H410 对水生生物毒性极大并具有长期持续影响。Precautionary Statements: P260 不要吸入粉尘、烟、气体、烟雾、蒸气、喷雾。P264 作业后彻底清洗。P270 禁止本产品使用时进食、饮水或吸烟。P280 戴防护手套/穿防护服/戴护目镜/戴面罩。P301+P312 如误吞咽：如感觉不适，呼叫中毒控制中心或医生。P302+P352 如皮肤沾染：用大量肥皂和水清洗。P304+P340 如误吸入：将人转移到空气新鲜处，保持呼吸舒适体位。P312 如感觉不适，呼叫中毒控制中心或医生。P403+P235 存放在通风良好的地方。保持低温。P501 按当地法规处置内装物/容器。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3552, 4150, '国内化学品管理法规：危险化学品安全管理条例、易制毒化学品管理条例、工作场所安全使用化学品规定、危险化学品登记管理办法。国际法规：联合国关于危险货物运输的建议书（橙皮书）、国际海运危险货物规则（IMDG Code）、国际空运危险货物规则（IATA-DGR）。GHS危险性分类：急性毒性类别3；皮肤腐蚀/刺激类别2；严重眼损伤/眼刺激类别2A；皮肤致敏类别1；对水环境危害-急性类别2。Hazard Statements: H301 吞咽有毒。H315 造成皮肤刺激。H319 造成严重眼刺激。H317 可能导致皮肤过敏反应。H335 可能引起呼吸道刺激。H410 对水生生物毒性极大并具有长期持续影响。Precautionary Statements: P260 不要吸入粉尘、烟、气体、烟雾、蒸气、喷雾。P261 避免吸入粉尘、烟、气体、烟雾、蒸气、喷雾。P264 作业后彻底清洗。P270 禁止本产品使用时进食、饮水或吸烟。P271 只能在室外或通风良好的地方使用。P280 戴防护手套/穿防护服/戴护目镜/戴面罩。P301+P310 如误吞咽：立即呼叫中毒控制中心或医生。P302+P352 如皮肤沾染：用大量肥皂和水清洗。P304+P340 如误吸入：将人转移到空气新鲜处，保持呼吸舒适体位。P312 如感觉不适，呼叫中毒控制中心或医生。P321 具体治疗（见本标签上的……）。P330 漱口。P361+P364 立即脱掉所有沾染的衣服，清洗后方可重新使用。P403+P235 存放在通风良好的地方。保持低温。P501 按当地法规处置内装物/容器。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3553, 4151, '国内化学品管理法规：危险化学品安全管理条例、易制毒化学品管理条例、工作场所安全使用化学品规定、危险化学品登记管理办法。国际法规：联合国关于危险货物运输的建议书（橙皮书）、国际海运危险货物规则（IMDG Code）、国际空运危险货物规则（IATA-DGR）。GHS危险性分类：急性毒性类别3；皮肤腐蚀/刺激类别2；严重眼损伤/眼刺激类别2A。Hazard Statements: H301 吞咽有害。H311 皮肤接触有害。H331 吸入有害。H315 造成皮肤刺激。H319 造成严重眼刺激。H335 可能引起呼吸道刺激。Precautionary Statements: P260 不要吸入粉尘、烟、气体、烟雾、蒸气、喷雾。P264 作业后彻底清洗。P270 禁止本产品使用时进食、饮水或吸烟。P280 戴防护手套/穿防护服/戴护目镜/戴面罩。P301+P310 如误吞咽：立即呼叫中毒控制中心或医生。P302+P352 如皮肤沾染：用大量肥皂和水清洗。P304+P340 如误吸入：将人转移到空气新鲜处，保持呼吸舒适体位。P312 如感觉不适，呼叫中毒控制中心或医生。P321 具体治疗（见本标签上的急救说明）。P361+P364 如衣物沾染：立即脱掉所有沾染的衣服。P403+P235 存放在通风良好的地方。保持低温。P501 按当地法规处置内装物/容器。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
