INSERT INTO `msds_regulatory` VALUES (3563, 4179, '国内法规：《危险化学品安全管理条例》、《易制爆危险化学品治安管理办法》、《危险货物分类和品名编号》(GB 6944)、《危险货物品名表》(GB 12268)、《危险化学品目录》。国际法规：联合国《关于危险货物运输的建议书》(TDG)、国际海事组织《国际海运危险货物规则》(IMDG Code)。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
