INSERT INTO `msds_regulatory` VALUES (3565, 4181, '国内法规：危险化学品安全管理条例（国务院令第591号）；民用爆炸物品安全管理条例（国务院令第466号）；易制爆危险化学品名录（2017年版）。国际法规：联合国关于危险货物运输的建议书（TDG）；国际海运危险货物规则（IMDG Code）；国际民航组织危险物品安全航空运输技术细则（ICAO TI）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3566, 4182, '国内法规：危险化学品安全管理条例（国务院令第591号），工作场所安全使用化学品规定（〔1996〕劳部发423号），危险化学品目录（2015版），易制毒化学品管理条例。国际法规：联合国关于危险货物运输的建议书（TDG），全球化学品统一分类和标签制度（GHS），国际海事危险货物规则（IMDG Code）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3567, 4183, '国内化学品安全管理法规：危险化学品安全管理条例（国务院令第591号），工作场所安全使用化学品规定（[1996]劳部发423号），危险化学品安全技术说明书编写规定（GB/T 16483-2008），常用危险化学品的分类及标志（GB 13690-2009），危险货物包装标志（GB 190-2009），危险货物运输包装通用技术条件（GB 12463-2009）。国际法规：联合国关于危险货物运输的建议书（TDG），全球化学品统一分类和标签制度（GHS）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3568, 4184, '《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录》（2015版）、《危险货物品名表》（GB 12268-2012）、《危险货物运输包装通用技术条件》（GB 12463-2009）、《危险货物道路运输安全管理办法》（交通运输部令2019年第29号）。本品属于第6.1类毒害品，应按照相关法规进行生产、储存、运输和使用。本品可燃，有毒，需严格控制接触。受高热或与酸接触会产生剧毒的氰化物气体，需特别注意。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3569, 4186, '危险化学品安全管理条例（国务院令第591号），危险化学品目录（2015版），易制爆危险化学品名录（2017年版）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3570, 4187, '《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录》（2015版）、《危险货物品名表》（GB 12268-2012）、《危险货物运输包装通用技术条件》（GB 12463-2009）、《危险货物道路运输安全管理办法》（交通运输部令2019年第29号）。本品属于第8.1类酸性腐蚀品，应按照相关法规进行生产、储存、运输和使用。粉体与空气可形成爆炸性混合物，需特别注意。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
