INSERT INTO `msds_regulatory` VALUES (3573, 4190, '《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录》（2015版）、《危险货物品名表》（GB 12268-2012）、《危险货物运输包装通用技术条件》（GB 12463-2009）、《危险货物道路运输安全管理办法》（交通运输部令2019年第29号）。本品属于第8.1类酸性腐蚀品，应按照相关法规进行生产、储存、运输和使用。本品可燃，具强腐蚀性、强刺激性，可致人体灼伤，需严格控制接触。遇水猛烈分解，需特别注意。包装必须密封，切勿受潮。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3574, 4191, '国内法规：危险化学品安全管理条例、易制毒化学品管理条例。国际法规：危险品标志Xi（刺激性），危险类别码R36/37/38（对眼睛、呼吸系统和皮肤有刺激性），安全说明S22-S24/25（切勿吸入粉尘；避免与皮肤和眼睛接触），危险性防范说明P261,P264,P271,P280,P302+P352,P304+P3。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
