INSERT INTO `msds_regulatory` VALUES (3717, 4357, '《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录》（2015版）、《危险货物品名表》（GB 12268-2012）、《危险货物运输包装通用技术条件》（GB 12463-2009）、《危险货物道路运输安全管理办法》（交通运输部令2019年第29号）。本品属于易燃液体，类别3；特定目标器官毒性-单次接触，类别1；特定目标器官毒性-重复接触，类别1，UN号1993，应按照相关法规进行生产、储存、运输和使用。本品有毒，具刺激性，需严格控制接触。在火场中，受热的容器有爆炸危险。受热或接触火焰可能会产生膨胀或爆炸性分解。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
