INSERT INTO `msds_regulatory` VALUES (3752, 4406, '国内法规：《危险化学品安全管理条例》（国务院令第591号）、《易制爆危险化学品治安管理办法》、《危险化学品目录（2015版）》、《危险货物分类和品名编号》（GB 6944）、《危险货物品名表》（GB 12268）、《化学品安全技术说明书 内容和项目顺序》（GB/T 16483）、《化学品安全技术说明书 编写规定》（GB/T 17519）、《工作场所安全使用化学品规定》、《职业病防治法》、《大气污染防治法》、《水污染防治法》、《土壤污染防治法》、《固体废物污染环境防治法》。国际法规：《联合国关于危险货物运输的建议书》（TDG）、《国际海运危险货物规则》（IMDG）、《国际空运危险货物规则》（IATA-DGR）、《国际铁路运输危险货物规则》（RID）、《国际公路运输危险货物规则》（ADR）、《化学品分类及标记全球协调制度》（GHS）、《欧盟化学品注册、评估、授权和限制法规》（REACH）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
