INSERT INTO `msds_regulatory` VALUES (3817, 4474, '高氯酸锂属于危险化学品，应按照《危险化学品安全管理条例》进行管理。高氯酸锂属于危险废物，应按照《危险废物经营许可证管理办法》进行管理。高氯酸锂属于氧化剂，应按照《危险货物道路运输规则》进行运输。高氯酸锂对环境有害，应按照《中华人民共和国环境保护法》进行管理。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
