INSERT INTO `msds_regulatory` VALUES (3820, 4477, '《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录》（2015版）、《危险货物品名表》（GB 12268-2012）、《危险货物运输包装通用技术条件》（GB 12463-2009）、《危险货物道路运输安全管理办法》（交通运输部令2019年第29号）。本品属于第5.1类氧化剂和第6.1类毒害品，应按照相关法规进行生产、储存、运输和使用。铅化合物为高毒物质，需特别管理。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
