INSERT INTO `msds_regulatory` VALUES (3911, 4584, '国内化学品管理法规：危险化学品安全管理条例、易制毒化学品管理条例、危险化学品目录（2015版）。国际法规：联合国关于危险货物运输的建议书（TDG）、国际海事组织国际海运危险货物规则（IMDG Code）、国际民用航空组织危险物品安全航空运输技术细则（ICAO TI/IATA DGR）。GHS危险性分类：易燃液体类别3；皮肤腐蚀/刺激类别2；严重眼损伤/眼刺激类别2A。Hazard Statements：H225（高度易燃液体和蒸气）、H315（造成皮肤刺激）、H319（造成严重眼刺激）。Precautionary Statements：P201（使用前取得特别说明）、P202（在阅读所有明了安全措施前切勿操作）、P210（远离热源/火花/明火/热表面。禁止吸烟）、P233（保持容器密闭）、P240（容器和接收设备接地/等势连接）、P241（使用防爆的电气/通风/照明设备）、P242（只能使用不产生火花的工具）、P243（采取防止静电放电的措施）、P261（避免吸入粉尘/烟/气体/烟雾/蒸气/喷雾）、P305+P351+P338（如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗）、P403+P235（存放在通风良好的地方。保持低温）、P501（按当地法规处置内装物/容器）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3912, 4585, '无资料', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3913, 4586, '国内化学品管理法规：《危险化学品安全管理条例》、《工作场所安全使用化学品规定》、《常用危险化学品的分类及标志》(GB 13690)等法规，针对危险化学品的安全使用、生产、储存、运输、装卸等方面均作了相应规定。国际法规：联合国关于危险货物运输的建议书（TDG）、国际海事组织国际海运危险货物规则（IMDG Code）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3914, 4587, '国内化学品管理法规：危险化学品安全管理条例、工作场所安全使用化学品规定等。国际法规：联合国关于危险货物运输的建议书（TDG）、国际海事组织国际海运危险货物规则（IMDG Code）、国际民用航空组织危险物品安全航空运输技术细则（ICAO TI/IATA DGR）。GHS危险性分类：易燃气体类别1；急性毒性类别4；特异性靶器官毒性-单次接触类别3。Hazard Statements：H220（极度易燃气体）；H336（可能引起嗜睡或头晕）。Precautionary Statements：P201（使用前取得特别说明）；P202（在阅读所有明了安全措施前切勿操作）；P210（远离热源、火花、明火、热表面。禁止吸烟）；P261（避免吸入粉尘/烟/气体/烟雾/蒸气/喷雾）；P371+P380（火灾时：撤离现场）；P410+P403（防晒。存放在通风良好的地方）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3915, 4588, '国内化学品管理法规：危险化学品安全管理条例、危险化学品目录（2015版）。国际法规：联合国关于危险货物运输的建议书（TDG）、国际海事组织国际海运危险货物规则（IMDG Code）、国际民用航空组织危险物品安全航空运输技术细则（ICAO TI/IATA DGR）。GHS危险性分类：易燃气体类别1；特异性靶器官毒性-反复接触类别2。Hazard Statements：H220（极易燃气体）；H336（可能引起嗜睡或头晕）。Precautionary Statements：P201（使用前取得特别说明）；P202（在阅读所有明了安全措施前切勿操作）；P210（远离热源、火花、明火、热表面。禁止吸烟）；P260（不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾）；P261（避免吸入粉尘/烟/气体/烟雾/蒸气/喷雾）；P264（作业后彻底清洗）；P271（只能在室外或通风良好的地方使用）；P280（戴防护手套/穿防护服/戴防护眼罩/戴防护面具）；P304+P340（如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的休息姿势）；P310+P330（立即呼叫中毒控制中心或医生）；P371+P380（火灾时：撤离现场）；P403+P233（存放在通风良好的地方。保持容器密闭）；P410+P403（防晒。存放在通风良好的地方）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3916, 4589, '《危险化学品安全管理条例》（国务院令第591号），工作场所安全使用化学品规定（[1996]劳部发423号）等法规，针对化学危险品的安全使用、生产、储存、运输、装卸等方面均作了相应规定；《常用危险化学品的分类及标志》（GB 13690-2009）将该物质划为第3.3类高闪点易燃液体。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3917, 4590, '国内化学品管理法规：危险化学品安全管理条例、危险化学品目录（2015版）。国际法规：联合国关于危险货物运输的建议书（TDG）、国际海事组织国际海运危险货物规则（IMDG Code）、国际民用航空组织危险物品安全航空运输技术细则（ICAO TI/IATA DGR）。GHS危险性分类：易燃液体类别2；特异性靶器官毒性-单次接触类别3。Hazard Statements：H225（高度易燃液体和蒸气）；H336（可能引起嗜睡或头晕）。Precautionary Statements：P201（使用前取得特别说明）；P202（在阅读所有明了安全措施前切勿操作）；P210（远离热源、火花、明火、热表面。禁止吸烟）；P233（保持容器密闭）；P240（接地/等电位连接容器和接收设备）；P241（使用防爆电气/通风/照明设备）；P242（只能使用不产生火花的工具）；P243（采取防止静电放电的措施）；P261（避免吸入粉尘/烟/气体/烟雾/蒸气/喷雾）；P264（作业后彻底清洗）；P270（禁止在本产品/容器上进食、饮水或吸烟）；P271（只能在室外或通风良好之处使用）；P280（戴防护手套/穿防护服/戴护目镜/戴面罩）；P301+P310（如误吞咽：立即呼叫解毒中心或医生）；P331（不得诱导呕吐）；P304+P340（如误吸入：将人移到空气新鲜处，保持呼吸舒适体位）；P312（如感觉不适，呼叫解毒中心或医生）；P370+P380（火灾：爆炸时，立即撤离到安全区域）；P403+P235（存放在通风良好的地方。保持低温）；P403+P233（存放在通风良好的地方。保持容器密闭）；P405（存放处须加锁）；P501（通过焚烧或填埋方式处置内装物/容器）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
