INSERT INTO `msds_regulatory` VALUES (3965, 4638, '国内化学品管理法规：危险化学品安全管理条例、危险化学品目录（2015版）。国际法规：联合国关于危险货物运输的建议书（TDG）、国际海事组织国际海运危险货物规则（IMDG Code）、国际民用航空组织危险物品安全航空运输技术细则（ICAO TI/IATA DGR）。GHS危险性分类：急性毒性类别4；皮肤腐蚀/刺激类别2；严重眼损伤/眼刺激类别2A。Hazard Statements：H302（吞咽有害）；H315（造成皮肤刺激）；H319（造成严重眼刺激）。Precautionary Statements：P261（避免吸入粉尘/烟/气体/烟雾/蒸气/喷雾）、P264（作业后彻底清洗）、P270（使用本产品时不要进食、饮水或吸烟）、P280（穿戴防护手套/防护服/护眼/防护面具）、P305+P351+P338（如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗）、P310+P330（立即呼叫中毒控制中心或医生）、P501（按当地法规处置内装物/容器）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (3966, 4639, '国内化学品管理法规：危险化学品安全管理条例、危险化学品目录（2015版）、工作场所安全使用化学品规定。国际法规：联合国关于危险货物运输的建议书（TDG）、国际海事组织国际海运危险货物规则（IMDG Code）、国际民用航空组织危险物品安全航空运输技术细则（ICAO TI/IATA DGR）。GHS危险性分类：急性毒性-经口类别1；急性毒性-经皮类别2；急性毒性-吸入类别2；特异性靶器官毒性-反复接触类别2。Hazard Statements：H300（吞食致命）；H310（致命皮肤接触）；H330（吸入致命）；H410（对水生生物毒性极大并具有长期持续影响）。Precautionary Statements：P260（不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾）；P264（作业后彻底清洗）；P270（使用本产品时禁止进食、饮水或吸烟）；P284（戴呼吸防护装置）；P301+P310（如果吞咽：立即呼叫解毒中心/医生）；P302+P352（如皮肤沾染：用大量肥皂和水清洗）；P304+P340（如误吸入：将人转移到空气新鲜处，如呼吸停止，进行人工呼吸）；P310（立即呼叫中毒控制中心或医生）；P320（紧急具体治疗）；P321（具体治疗）；P330（漱口）；P361+P364（立即脱掉所有沾染的衣服，清洗后方可重新使用）；P370+P380（火灾：疏散到安全区域）；P391（收集溢出物）；P405（存放处须加锁）；P501（按当地法规处置内装物/容器）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
