INSERT INTO `msds_regulatory` VALUES (3980, 4653, '国内化学品管理法规：危险化学品安全管理条例、危险化学品目录（2015版）、工作场所安全使用化学品规定。国际法规：联合国关于危险货物运输的建议书（TDG）、国际海事组织国际海运危险货物规则（IMDG Code）、国际民用航空组织危险物品安全航空运输技术细则（ICAO TI/IATA DGR）。GHS危险性分类：易燃液体类别2；皮肤腐蚀/刺激类别2；严重眼损伤/眼刺激类别2；特异性靶器官毒性-一次接触类别3。Hazard Statements：H225（高度易燃液体和蒸气）；H315（造成皮肤刺激）；H319（造成严重眼刺激）；H335（可能引起呼吸道刺激）。Precautionary Statements：P210（远离热源、火花、明火、热表面。禁止吸烟）；P220（远离服装和其他可燃材料）；P221（采取一切防范措施，避免与可燃物混合）；P261（避免吸入粉尘/烟/气体/烟雾/蒸气/喷雾）；P264（作业后彻底清洗）；P271（只能在室外或通风良好之处使用）；P280（戴防护手套/穿防护服/戴护目镜/戴面罩）；P301+P310（如果吞咽：立即呼叫解毒中心/医生）；P302+P352（如皮肤沾染：用大量肥皂和水清洗）；P304+P340（如误吸入：将人转移到空气新鲜处，如呼吸停止，进行人工呼吸）；P312（如感觉不适，呼叫中毒控制中心或医生）；P321（具体治疗）；P330（漱口）；P361+P364（立即脱掉所有沾染的衣服，清洗后方可重新使用）；P370+P380（火灾：疏散到安全区域）；P403+P235（存放在通风良好的地方）；P405（存放处须加锁）；P501（按当地法规处置内装物/容器）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
