INSERT INTO `msds_regulatory` VALUES (3999, 4672, '国内化学品管理法规：危险化学品安全管理条例、危险化学品目录（2015版）。国际法规：联合国关于危险货物运输的建议书（TDG）、国际海事组织国际海运危险货物规则（IMDG Code）、国际民用航空组织危险物品安全航空运输技术细则（ICAO TI/IATA DGR）。GHS危险性分类：易燃气体类别1。Hazard Statements：H220（极易燃气体）、H222（极高浓度可引起窒息）、H229（压力下气体）。Precautionary Statements：P210（远离热源/火花/明火/热表面。禁止吸烟）、P220（远离服装和其他可燃材料）、P221（采取一切防范措施，避免与可燃物混合）、P377（泄漏气体着火：切勿灭火，除非泄漏可以安全地制止）、P381（即使没有火，也要消除所有火源）、P410（防日晒）、P501（按当地法规处置内装物/容器）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
