INSERT INTO `msds_regulatory` VALUES (4029, 4710, '危险品标志：Xn（有害）。危险类别码：10-20/21/22-36/37/38。安全说明：26-36/37-36。WGK Germany：3。海关编码：29333999。美国有毒物质控制法案(TSCA)目录。危险化学品安全管理条例。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4030, 4711, '国内法规：危险化学品安全管理条例（国务院令第591号），工作场所安全使用化学品规定（劳部发[1996]423号）等法规，针对危险化学品的安全使用、生产、储存、运输、装卸等方面均作了相应规定。国际法规：联合国关于危险货物运输的建议书（TDG），国际海事组织（IMO）国际海运危险货物规则（IMDG Code），国际民航组织（ICAO）国际空运危险货物规则（IATA DGR），欧盟化学品注册、评估、授权和限制法规（REACH），全球化学品统一分类和标签制度（GHS）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4031, 4713, '1. 国内法规：列入《危险化学品目录(2022调整版)》，危险化学品编号：61847。根据《危险化学品安全管理条例》进行管理。2. 国际法规：UN 2656，IMDG Class 6.1，第6.1类毒害品。3. 其他法规：应遵守国家有关环境保护、职业健康安全等相关法律法规。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
