INSERT INTO `msds_regulatory` VALUES (4084, 4774, '国内化学品管理法规：危险化学品安全管理条例（国务院令第591号）、危险化学品目录（2015版）、危险货物品名表（GB 12268-2012）、危险货物运输包装通用技术条件（GB 12463-2009）、危险货物道路运输安全管理办法、工作场所安全使用化学品规定（[1996]劳部发423号）、汞及其化合物环境污染防治技术政策。国际法规：联合国关于危险货物运输的建议书（TDG）、国际海事组织国际海运危险货物规则（IMDG Code）、国际民用航空组织危险物品安全航空运输技术细则（ICAO TI/IATA DGR）。GHS危险性分类：急性毒性类别2；皮肤腐蚀/刺激类别2；严重眼损伤/眼刺激类别2A；特异性靶器官毒性-反复接触类别1。Hazard Statements：H300（吞咽致命）、H310（皮肤接触致命）、H330（吸入致命）、H372（长期或反复接触对器官造成伤害）、H410（对水生生物毒性极大并具有长期持续影响）。Precautionary Statements：P201（在使用前获取特别指示）、P202（在阅读并明了所有安全措施前切勿处置）、P260（不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾）、P264（作业后彻底清洗）、P270（使用本产品时不要进食、饮水或吸烟）、P273（避免释放到环境中）、P280（穿戴防护手套/防护服/护眼/防护面具）、P301+P312（如误吞咽：如感觉不适，呼叫解毒中心或医生）、P302+P352（如皮肤沾染：脱去所有沾染的衣服。用水清洗皮肤/淋浴）、P304+P340（如误吸入：将人转移到空气新鲜处，保持呼吸舒适的体位）、P305+P351+P338（如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗）、P310（立即呼叫解毒中心或医生）、P321（具体治疗）、P322（具体措施）、P361+P364（如皮肤（或头发）沾染：立即脱掉所有沾染的衣服。清洗后方可重新使用）、P370+P380（火灾时：撤离现场）、P371+P380+P375（火灾时：若火势无法控制，撤离现场）、P391（收集溢出物）、P405（存放处须加锁）、P501（按当地法规处置内装物/容器）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4085, 4775, '国内化学品管理法规：危险化学品安全管理条例（国务院令第591号）、危险化学品目录（2015版）、危险货物品名表（GB 12268-2012）、危险货物运输包装通用技术条件（GB 12463-2009）、危险货物道路运输安全管理办法、工作场所安全使用化学品规定（[1996]劳部发423号）。国际法规：联合国关于危险货物运输的建议书（TDG）、国际海事组织国际海运危险货物规则（IMDG Code）、国际民用航空组织危险物品安全航空运输技术细则（ICAO TI/IATA DGR）。GHS危险性分类：易燃液体类别3；急性毒性类别3；皮肤腐蚀/刺激类别2；严重眼损伤/眼刺激类别2A。Hazard Statements：H225（高度易燃液体和蒸气）、H302（吞咽有害）、H312（皮肤接触有害）、H332（吸入有害）、H410（对水生生物毒性极大并具有长期持续影响）。Precautionary Statements：P201（在使用前获取特别指示）、P202（在阅读并明了所有安全措施前切勿处置）、P210（远离热源、火花、明火、热表面。禁止吸烟）、P233（保持容器密闭）、P240（搬运前接地和连接电气设备）、P241（使用防爆电气设备/通风设备/照明设备）、P261（避免吸入粉尘/烟/气体/烟雾/蒸气/喷雾）、P264（作业后彻底清洗）、P270（使用本产品时不要进食、饮水或吸烟）、P271（只能在室外或通风良好的地方使用）、P273（避免释放到环境中）、P280（穿戴防护手套/防护服/护眼/防护面具）、P301+P312（如误吞咽：如感觉不适，呼叫解毒中心或医生）、P302+P352（如皮肤沾染：脱去所有沾染的衣服。用水清洗皮肤/淋浴）、P304+P340（如误吸入：将人转移到空气新鲜处，保持呼吸舒适的体位）、P305+P351+P338（如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗）、P310（立即呼叫解毒中心或医生）、P321（具体治疗）、P322（具体措施）、P361+P364（如皮肤（或头发）沾染：立即脱掉所有沾染的衣服。清洗后方可重新使用）、P370+P380（火灾时：撤离现场）、P371+P380+P375（火灾时：若火势无法控制，撤离现场）、P391（收集溢出物）、P405（存放处须加锁）、P501（按当地法规处置内装物/容器）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4086, 4776, '国内化学品管理法规：危险化学品安全管理条例（国务院令第591号）、危险化学品目录（2015版）、危险货物品名表（GB 12268-2012）、危险货物运输包装通用技术条件（GB 12463-2009）、危险货物道路运输安全管理办法、工作场所安全使用化学品规定（[1996]劳部发423号）。国际法规：联合国关于危险货物运输的建议书（TDG）、国际海事组织国际海运危险货物规则（IMDG Code）、国际民用航空组织危险物品安全航空运输技术细则（ICAO TI/IATA DGR）。GHS危险性分类：易燃液体类别3；急性毒性类别3；皮肤腐蚀/刺激类别2；严重眼损伤/眼刺激类别2A；特异性靶器官毒性-一次接触类别3。Hazard Statements：H226（易燃液体和蒸气）、H311（皮肤接触会中毒）、H331（吸入会中毒）、H319（造成严重眼刺激）。Precautionary Statements：P201（在使用前获取特别指示）、P202（在阅读并明了所有安全措施前切勿处置）、P210（远离热源、火花、明火、热表面。禁止吸烟）、P233（保持容器密闭）、P240（容器和装载设备接地/等势连接）、P241（使用防爆电气、通风和照明设备）、P242（只能使用不产生火花的工具）、P243（采取防止静电放电的措施）、P260（不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾）、P261（避免吸入粉尘/烟/气体/烟雾/蒸气/喷雾）、P264（作业后彻底清洗）、P270（使用本产品时不要进食、饮水或吸烟）、P271（只能在室外或通风良好的地方使用）、P273（避免释放到环境中）、P280（穿戴防护手套/防护服/护眼/防护面具）、P301+P312（如误吞咽：如感觉不适，呼叫解毒中心或医生）、P302+P352（如皮肤沾染：脱去所有沾染的衣服。用水清洗皮肤/淋浴）、P304+P340（如误吸入：将人转移到空气新鲜处，保持呼吸舒适的体位）、P305+P351+P338（如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗）、P310（立即呼叫解毒中心或医生）、P321（具体治疗）、P322（具体措施）、P361+P364（如皮肤（或头发）沾染：立即脱掉所有沾染的衣服。清洗后方可重新使用）、P370+P380（火灾时：撤离现场）、P371+P380+P375（火灾时：若火势无法控制，撤离现场）、P403+P235（存放在通风良好的地方）、P405（存放处须加锁）、P501（按当地法规处置内装物/容器）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4087, 4777, '国内化学品管理法规：危险化学品安全管理条例（国务院令第591号）、危险化学品目录（2015版）、危险货物品名表（GB 12268-2012）、危险货物运输包装通用技术条件（GB 12463-2009）、危险货物道路运输安全管理办法、工作场所安全使用化学品规定（[1996]劳部发423号）。国际法规：联合国关于危险货物运输的建议书（TDG）、国际海事组织国际海运危险货物规则（IMDG Code）、国际民用航空组织危险物品安全航空运输技术细则（ICAO TI/IATA DGR）。GHS危险性分类：皮肤腐蚀/刺激类别1；严重眼损伤/眼刺激类别1；特异性靶器官毒性-一次接触类别3。Hazard Statements：H314（造成严重皮肤灼伤和眼损伤）、H318（造成严重眼损伤）、H335（可能引起呼吸道刺激）。Precautionary Statements：P260（不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾）、P264（作业后彻底清洗）、P280（穿戴防护手套/防护服/护眼/防护面具）、P301+P330+P331（如误吞咽：漱口。不要诱导呕吐）、P303+P361+P353（如皮肤（或头发）沾染：脱掉所有沾染的衣服。用水清洗皮肤/淋浴）、P304+P340（如误吸入：将人转移到空气新鲜处，保持呼吸舒适的体位）、P305+P351+P338（如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗）、P310（立即呼叫解毒中心或医生）、P321（具体治疗）、P363（切勿将水喷洒在泄漏物上）、P370+P380（火灾时：撤离现场）、P371+P380+P375（火灾时：若火势无法控制，撤离现场）、P405（存放处须加锁）、P501（按当地法规处置内装物/容器）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
