INSERT INTO `msds_regulatory` VALUES (4090, 4780, '国内化学品管理法规：危险化学品安全管理条例（国务院令第591号）、危险化学品目录（2015版）、危险货物品名表（GB 12268-2012）、危险货物运输包装通用技术条件（GB 12463-2009）、危险货物道路运输安全管理办法、工作场所安全使用化学品规定（[1996]劳部发423号）。国际法规：联合国关于危险货物运输的建议书（TDG）、国际海事组织国际海运危险货物规则（IMDG Code）、国际民用航空组织危险物品安全航空运输技术细则（ICAO TI/IATA DGR）。GHS危险性分类：急性毒性类别3；皮肤腐蚀/刺激类别2；严重眼损伤/眼刺激类别2A；特异性靶器官毒性-反复接触类别2。Hazard Statements：H301（吞咽会中毒）、H311（皮肤接触会中毒）、H319（造成严重眼刺激）、H335（可能引起呼吸道刺激）、H372（长期或反复接触对器官造成伤害）。Precautionary Statements：P201（在使用前获取特别指示）、P202（在阅读并明了所有安全措施前切勿处置）、P261（避免吸入粉尘/烟/气体/烟雾/蒸气/喷雾）、P264（作业后彻底清洗）、P270（使用本产品时不要进食、饮水或吸烟）、P280（穿戴防护手套/防护服/护眼/防护面具）、P301+P330+P331（如误吞咽：漱口。不要诱导呕吐）、P302+P352（如皮肤沾染：脱去所有沾染的衣服。用水清洗皮肤/淋浴）、P304+P340（如误吸入：将人转移到空气新鲜处，保持呼吸舒适的体位）、P305+P351+P338（如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗）、P310（立即呼叫解毒中心或医生）、P321（具体治疗）、P322（具体措施）、P361+P364（如皮肤（或头发）沾染：立即脱掉所有沾染的衣服。清洗后方可重新使用）、P370+P380（火灾时：撤离现场）、P371+P380+P375（火灾时：若火势无法控制，撤离现场）、P405（存放处须加锁）、P501（按当地法规处置内装物/容器）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
