INSERT INTO `msds_regulatory` VALUES (4114, 4804, '国内法规：危险化学品安全管理条例（国务院令第591号），工作场所安全使用化学品规定（[1996]劳部发423号），危险化学品目录（2015版），易制毒化学品管理条例。国际法规：联合国关于危险货物运输的建议书（TDG），全球化学品统一分类和标签制度（GHS）。该化学品属于危险化学品，在生产、储存、运输、使用和废弃处置过程中必须严格遵守上述法规要求。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
