INSERT INTO `msds_regulatory` VALUES (4120, 4810, '国内法规：危险化学品安全管理条例、易制毒化学品管理条例、危险化学品目录（2015版）、危险货物品名表（GB 12268-2012）、危险货物分类和品名编号（GB 6944-2012）。国际法规：联合国关于危险货物运输的建议书（TDG）、国际海运危险货物规则（IMDG Code）、国际民航组织危险物品安全航空运输技术细则（ICAO TI）、国际航空运输协会危险物品规则（IATA DGR）。欧盟法规：REACH法规、CLP法规（EC 1272/2008）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4121, 4811, NULL, '国内化学品安全管理法规:化学危险物品安全管理条例(1987年2月17日国务院发布),化学危险物品安全管理条例实施细则(化劳发[1992]677号),工作场所安全使用化学品规定([1996]劳部发423号)等法规,针对化学危险品的安全使用、生产、储存、运输、装卸等方面均作了相应规定;常用危险化学品的分类及标志(GB13690-92)将该物质划为第2.3类有毒气体。', NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4122, 4812, '国内法规：《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录（2015版）》、《工作场所安全使用化学品规定》（[1996]劳部发423号）、《危险货物分类和品名编号》（GB 6944）、《危险货物品名表》（GB 12268）、《六氟化硫气体回收与再利用技术规范》（GB/T 39005）。国际法规：联合国《关于危险货物运输的建议书》（TDG）、《全球化学品统一分类和标签制度》（GHS）、《京都议定书》（作为受控温室气体）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4123, 4813, '国内法规：《危险化学品安全管理条例》、《危险化学品目录（2015版）》、《工作场所安全使用化学品规定》、《危险货物分类和品名编号》（GB 6944）、《危险货物品名表》（GB 12268）。国际法规：联合国《关于危险货物运输的建议书》（TDG）、《全球化学品统一分类和标签制度》（GHS）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4124, 4814, '法规信息：六氟化铀（UF6）属于放射性物质和危险化学品，受多项国际和国内法规的监管。以下为主要法规清单：', '国内法规（中国）：1）《中华人民共和国放射性污染防治法》：规定了放射性污染的防治措施、责任主体、监督管理等。2）《中华人民共和国核安全法》：规定了核设施的安全要求、核材料的管理、核事故的应急处理等。3）《放射性物品运输安全管理条例》：规定了放射性物品的运输许可、包装、运输、应急处理等。4）《放射性同位素与射线装置安全和防护条例》：规定了放射性同位素与射线装置的安全和防护要求。5）《危险化学品安全管理条例》：规定了危险化学品的生产、储存、使用、经营、运输等安全管理要求。6）《职业病防治法》：规定了职业病防治措施、职业健康监护、职业病诊断与鉴定等。7）《放射性废物管理条例》：规定了放射性废物的分类、收集、储存、运输、处置等。8）《核材料管制条例》：规定了核材料的管理、使用、运输、储存等。9）《放射性环境监测管理办法》：规定了放射性环境监测的要求、方法、报告等。10）《放射性工作人员健康管理规定》：规定了放射性工作人员的健康管理、剂量监测、职业健康监护等。', NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4125, 4815, '危险化学品安全管理条例（国务院令第591号），工作场所安全使用化学品规定，危险货物运输规则（联合国危险货物运输建议书），GB 6944-2012《危险货物分类和品名编号》，GB 13690-2009《化学品分类和危险性公示 通则》，GB 15603-1995《常用化学危险品贮存通则》，GB/T 16483-2008《化学品安全技术说明书 内容和项目顺序》。', '根据《危险化学品安全管理条例》，本产品属于危险化学品，生产、经营、储存、运输、使用和废弃处置必须遵守相关法律法规。', NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4126, 4816, '危险化学品安全管理条例（2011年国务院令第591号）；易制毒化学品管理条例（国务院令第445号）；易制爆危险化学品治安管理办法（公安部令第154号）；GB 6944-2012 危险货物分类和品名编号；GB 12268-2012 危险货物品名表；GB 13690-2009 化学品分类和危险性公示 通则；GB 15258-2009 化学品安全标签编写规定；GB/T 16483-2008 化学品安全技术说明书 内容和项目顺序；GB 30000系列 化学品分类和标签规范；AQ 3014-2008 危险化学品安全标签编写规定。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4127, 4817, '危险化学品安全管理条例（2011年国务院令第591号）；易制毒化学品管理条例（国务院令第445号）；易制爆危险化学品治安管理办法（公安部令第154号）；GB 6944-2012 危险货物分类和品名编号；GB 12268-2012 危险货物品名表；GB 13690-2009 化学品分类和危险性公示 通则；GB 15258-2009 化学品安全标签编写规定；GB/T 16483-2008 化学品安全技术说明书 内容和项目顺序；GB 30000系列 化学品分类和标签规范；AQ 3014-2008 危险化学品安全标签编写规定。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4128, 4818, NULL, '《危险化学品安全管理条例》\n        国务院令第591号，对危险化学品的生产、储存、使用、经营和运输实施安全管理。\n        《易制毒化学品管理条例》\n        国务院令第445号，对易制毒化学品的生产、经营、购买、运输和进口、出口行为进行规范。\n        《易制爆危险化学品安全管理条例》\n        对易制爆危险化学品的生产、储存、使用、经营和运输实施安全管理。\n        《危险化学品目录》\n        危险化学品目录序号：1347', NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4129, 4819, '国内法规：《危险化学品安全管理条例》、《危险化学品目录（2015版）》、《危险货物分类和品名编号》（GB 6944）、《危险货物运输包装通用技术条件》（GB 12463）、《工作场所有害因素职业接触限值 第1部分：化学有害因素》（GBZ 2.1）、《持久性有机污染物环境风险管控要求》（生态环境部公告2023年第20号）。国际法规：联合国《关于危险货物运输的建议书》（TDG）、《全球化学品统一分类和标签制度》（GHS）、《国际海运危险货物规则》（IMDG Code）、《国际航空运输危险物品规则》（IATA-DGR）。六氯-1,3-丁二烯属于持久性有机污染物（POPs）候选物质，自2023年6月6日起实施环境风险管控。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4130, 4820, '国内化学品管理法规：《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录（2015版）》、《工作场所安全使用化学品规定》（劳部发〔1996〕423号）、《持久性有机污染物防治条例》。国际法规：联合国《关于危险货物运输的建议书》（TDG）、联合国《全球化学品统一分类和标签制度》（GHS）、斯德哥尔摩公约（持久性有机污染物）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
