INSERT INTO `msds_regulatory` VALUES (4134, 4824, '危险化学品安全管理条例（国务院令第591号），工作场所安全使用化学品规定（[1996]劳部发423号）等法规，针对化学危险品的安全使用、生产、储存、运输、装卸等方面均作了相应规定。列入《危险化学品目录（2015版）》，危险货物编号：61558，UN编号：2811。属于持久性有机污染物（POPs）候选物质，受《关于持久性有机污染物的斯德哥尔摩公约》管控。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
