INSERT INTO `msds_regulatory` VALUES (4137, 4827, '危险化学品目录序号：1365。本品属于爆炸品，受《危险化学品安全管理条例》、《民用爆炸物品安全管理条例》等法规管理。生产、销售、购买、运输、储存和使用必须取得相应许可证。运输、储存和使用应符合《危险货物分类和品名编号》(GB6944)、《危险货物品名表》(GB12268)、《危险货物运输包装通用技术条件》(GB12463)等国家标准要求。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
