INSERT INTO `msds_regulatory` VALUES (4169, 4863, '国内法规：危险化学品安全管理条例（国务院令第591号）；易制毒化学品管理条例；工作场所安全使用化学品规定；危险化学品目录（2015版）。国际法规：欧盟REACH法规；欧盟CLP法规（EC No 1272/2008）；国际海运危险货物规则（IMDG Code）；国际空运危险货物规则（IATA DGR）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4170, 4864, '国内化学品管理法规：危险化学品安全管理条例、易制毒化学品管理条例、危险化学品目录（2015版）、剧毒化学品目录（2015版）、工作场所安全使用化学品规定。国际法规：联合国关于危险货物运输的建议书（TDG）、国际海事组织国际海运危险货物规则（IMDG Code）、国际民用航空组织危险物品安全航空运输技术细则（ICAO TI/IATA DGR）。GHS危险性分类：急性毒性-经口类别2；急性毒性-吸入类别2；皮肤腐蚀/刺激类别2；严重眼损伤/眼刺激类别2；特异性靶器官毒性-反复接触类别1；致癌性类别1A。Hazard Statements：H300（吞咽致命）；H330（吸入致命）；H315（造成皮肤刺激）；H319（造成严重眼刺激）；H335（可能引起呼吸道刺激）；H350（可能致癌）；H372（长期或反复接触对器官造成伤害）。Precautionary Statements：P260（不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾）；P264（作业后彻底清洗）；P270（使用本产品时不要进食、饮水或吸烟）；P271（只能在室外或通风良好之处使用）；P280（戴防护手套/穿防护服/戴护目镜/戴面罩）；P301+P310（如果吞咽：立即呼叫解毒中心/医生）；P304+P340（如误吸入：将人转移到空气新鲜处，如呼吸停止，进行人工呼吸）；P312（如感觉不适，呼叫中毒控制中心或医生）；P321（具体治疗）；P330（漱口）；P361+P364（立即脱掉所有沾染的衣服，清洗后方可重新使用）；P405（存放处须加锁）；P501（按当地法规处置内装物/容器）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4171, 4867, '国内法规：《危险化学品安全管理条例》、《危险化学品目录》、《化学品安全技术说明书内容和项目顺序》（GB/T 16483-2008）、《化学品安全技术说明书编写规定》（GB/T 17519-2013）。国际法规：联合国《关于危险货物运输的建议书》（TDG）、《全球化学品统一分类和标签制度》（GHS）、《国际海运危险货物规则》（IMDG Code）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4172, 4869, '国内法规：该化学品属于危险化学品，受《危险化学品安全管理条例》（国务院令第591号）管理。生产、经营、储存、运输、使用和处置废弃危险化学品必须遵守该条例和国家有关安全生产的法律、行政法规的规定。该化学品属于腐蚀性危险化学品，危化品目录号为1480。国际法规：运输时需遵守联合国《关于危险货物运输的建议书》（TDG）和国际海事组织《国际海运危险货物规则》（IMDG Code）的相关规定。标签和分类需符合全球化学品统一分类和标签制度（GHS）要求。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4173, 4870, '无资料', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4174, 4871, '国内法规：危险化学品安全管理条例（2011年修订），易制爆危险化学品名录（2017年版），危险化学品目录（2015版），重点环境管理危险化学品目录。国际法规：联合国关于危险货物运输的建议书（TDG），国际海事组织国际海运危险货物规则（IMDG Code），国际民用航空组织危险物品安全航空运输技术细则（ICAO TI），全球化学品统一分类和标签制度（GHS）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4175, 4872, '国内法规：《危险化学品安全管理条例》（国务院令第591号）、《易制毒化学品管理条例》（国务院令第445号）、《危险化学品目录》（2015版）。该化学品可能被列入危险化学品目录，应按照相关法规进行管理。国际法规：联合国《关于危险货物运输的建议书》（TDG）、《全球化学品统一分类和标签制度》（GHS）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4176, 4873, '本化学品属于危险化学品，受《危险化学品安全管理条例》等法规管理。生产、储存、运输、使用和处置本化学品必须遵守相关法律法规的要求。本化学品可能属于易制毒化学品或易制爆化学品，需办理相应的许可手续。建议关注最新的法律法规更新。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4177, 4874, '国内法规：该化学品属于危险化学品，受《危险化学品安全管理条例》（国务院令第591号）管理。生产、经营、储存、运输、使用和处置废弃危险化学品必须遵守该条例和国家有关安全生产的法律、行政法规的规定。该化学品属于自反应物质和混合物，d型，受《易制爆危险化学品管理办法》管理。国际法规：运输时需遵守联合国《关于危险货物运输的建议书》（TDG）和国际海事组织《国际海运危险货物规则》（IMDG Code）的相关规定。标签和分类需符合全球化学品统一分类和标签制度（GHS）要求。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
