INSERT INTO `msds_regulatory` VALUES (4197, 4897, '国内化学品安全管理法规：《危险化学品安全管理条例》（国务院令第591号）、《工作场所安全使用化学品规定》（劳部发[1996]423号）等法规，针对化学危险品的安全使用、生产、储存、运输、装卸等方面均作了相应规定；常用危险化学品的分类及标志（GB 13690-92）将该物质划为第3类易燃液体、第6.1类毒害品、第8类腐蚀性物品。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
