INSERT INTO `msds_regulatory` VALUES (4200, 4901, '国内法规：该化学品属于危险化学品，受《危险化学品安全管理条例》（国务院令第591号）管理。生产、经营、储存、运输、使用和处置废弃危险化学品必须遵守该条例和国家有关安全生产的法律、行政法规的规定。该化学品属于不燃气体，危化品目录号为22042。该物质是消耗臭氧层物质，受《消耗臭氧层物质管理条例》管理，生产和进口需取得配额许可证。国际法规：运输时需遵守联合国《关于危险货物运输的建议书》（TDG）和国际海事组织《国际海运危险货物规则》（IMDG Code）的相关规定。标签和分类需符合全球化学品统一分类和标签制度（GHS）要求。该物质受《蒙特利尔议定书》管控，属于逐步淘汰的消耗臭氧层物质。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4201, 4902, '危险化学品安全管理条例（国务院令第591号），工作场所安全使用化学品规定（〔1996〕劳部发423号）等法规，针对化学危险品的安全使用、生产、储存、运输、装卸等方面均作了相应规定。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4202, 4903, '国内化学品安全管理法规：危险化学品安全管理条例、易制毒化学品管理条例、剧毒化学品购买和公路运输许可证件管理办法。国际法规：联合国关于危险货物运输的建议书（橙皮书）、国际海运危险货物规则（IMDG Code）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
