INSERT INTO `msds_regulatory` VALUES (4224, 4930, '国内法规：危险化学品安全管理条例、易制毒化学品管理条例、工作场所安全使用化学品规定、危险化学品目录。国际法规：联合国关于危险货物运输的建议书(橙皮书)、国际海运危险货物规则(IMDG Code)、国际空运危险货物规则(IATA-DGR)、欧洲国际铁路危险货物运输规则(RID)、国际公路危险货物运输规则(ADR)。氯乙烯被列入《危险化学品目录》和《剧毒化学品目录》。属于重点监管的危险化学品。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4225, 4932, '《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录》（2015版）、《危险货物品名表》（GB 12268-2012）、《危险货物运输包装通用技术条件》（GB 12463-2009）、《危险货物道路运输安全管理办法》（交通运输部令2019年第29号）。本品属于第6.1类毒害品，应按照相关法规进行生产、储存、运输和使用。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
