INSERT INTO `msds_regulatory` VALUES (4227, 4936, '危险化学品安全管理条例（国务院令第591号），工作场所安全使用化学品规定（[1996]劳部发423号）等法规，针对化学危险品的安全使用、生产、储存、运输、装卸等方面均作了相应规定；常用危险化学品的分类及标志（GB13690-92）将该物质划为第3.3类高闪点易燃液体。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4228, 4937, '国内化学品管理法规：危险化学品安全管理条例、危险化学品目录（2015版）。国际法规：联合国关于危险货物运输的建议书（TDG）、国际海事组织国际海运危险货物规则（IMDG Code）、国际民用航空组织危险物品安全航空运输技术细则（ICAO TI/IATA DGR）。GHS危险性分类：易燃液体类别2；皮肤腐蚀/刺激类别2；严重眼损伤/眼刺激类别1；特异性靶器官毒性-反复接触类别2。Hazard Statements：H225（高度易燃液体和蒸气）；H314（造成严重皮肤灼伤和眼损伤）；H318（造成严重眼损伤）；H335（可能引起呼吸道刺激）。Precautionary Statements：P201（使用前取得特别说明）；P202（在阅读所有明了安全措施前切勿操作）；P210（远离热源、火花、明火、热表面。禁止吸烟）；P260（不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾）；P264（作业后彻底清洗）；P280（戴防护手套/穿防护服/戴防护眼罩/戴防护面具）；P305+P351+P338（如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗）；P310+P330（立即呼叫中毒控制中心或医生）；P370+P380（火灾时：撤离现场）；P403+P233（存放在通风良好的地方。保持容器密闭）；P405（存放处须加锁）；P501（按当地法规处置内装物/容器）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4229, 4938, '国内化学品管理法规：危险化学品安全管理条例、危险化学品目录（2015版）。国际法规：联合国关于危险货物运输的建议书（TDG）、国际海事组织国际海运危险货物规则（IMDG Code）、国际民用航空组织危险物品安全航空运输技术细则（ICAO TI/IATA DGR）。GHS危险性分类：易燃液体类别3；致癌性类别1A。Hazard Statements：H225（高度易燃液体和蒸气）；H350（可能致癌）；H315（造成皮肤刺激）；H319（造成严重眼刺激）；H336（可能引起嗜睡或眩晕）；H351（怀疑致癌）；H410（对水生生物毒性极大并具有长期持续影响）。Precautionary Statements：P201（使用前取得特别说明）；P202（在阅读所有明了安全措施前切勿操作）；P210（远离热源、火花、明火、热表面。禁止吸烟）；P261（避免吸入粉尘/烟/气体/烟雾/蒸气/喷雾）；P273（避免释放到环境中）；P280（戴防护手套/穿防护服/戴防护眼罩/戴防护面具）；P305+P351+P338（如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗）；P308+P313（如接触到或有疑虑：求医/就诊）；P403+P233（存放在通风良好的地方。保持容器密闭）；P405（存放处须加锁）；P501（按当地法规处置内装物/容器）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4230, 4939, '国内化学品管理法规：危险化学品安全管理条例、危险化学品目录（2015版）。国际法规：联合国关于危险货物运输的建议书（TDG）、国际海事组织国际海运危险货物规则（IMDG Code）、国际民用航空组织危险物品安全航空运输技术细则（ICAO TI/IATA DGR）。GHS危险性分类：易燃液体类别2；致癌性类别1A；危害水生环境-急性毒性类别2；危害水生环境-慢性毒性类别2。Hazard Statements：H225（高度易燃液体和蒸气）；H350（可能致癌）；H315（造成皮肤刺激）；H319（造成严重眼刺激）；H336（可能引起嗜睡或眩晕）；H351（怀疑致癌）；H410（对水生生物毒性极大并具有长期持续影响）。Precautionary Statements：P201（使用前取得特别说明）；P202（在阅读所有明了安全措施前切勿操作）；P210（远离热源、火花、明火、热表面。禁止吸烟）；P261（避免吸入粉尘/烟/气体/烟雾/蒸气/喷雾）；P273（避免释放到环境中）；P280（戴防护手套/穿防护服/戴防护眼罩/戴防护面具）；P305+P351+P338（如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗）；P308+P313（如接触到或有疑虑：求医/就诊）；P403+P233（存放在通风良好的地方。保持容器密闭）；P405（存放处须加锁）；P501（按当地法规处置内装物/容器）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4231, 4940, '国内化学品管理法规：危险化学品安全管理条例、危险化学品目录（2015版）。国际法规：联合国关于危险货物运输的建议书（TDG）、国际海事组织国际海运危险货物规则（IMDG Code）、国际民用航空组织危险物品安全航空运输技术细则（ICAO TI/IATA DGR）。GHS危险性分类：易燃液体类别3。Hazard Statements：H226（易燃液体和蒸气）；H304（吞咽并进入呼吸道可能致命）；H315（造成皮肤刺激）；H319（造成严重眼刺激）；H336（可能引起嗜睡或眩晕）。Precautionary Statements：P201（使用前取得特别说明）；P202（在阅读所有明了安全措施前切勿操作）；P210（远离热源、火花、明火、热表面。禁止吸烟）；P261（避免吸入粉尘/烟/气体/烟雾/蒸气/喷雾）；P305+P351+P338（如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗）；P403+P233（存放在通风良好的地方。保持容器密闭）；P405（存放处须加锁）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4232, 4941, '国内化学品管理法规：危险化学品安全管理条例、危险化学品目录（2015版）、易制爆危险化学品名录（2017版）。国际法规：联合国关于危险货物运输的建议书（TDG）、国际海事组织国际海运危险货物规则（IMDG Code）、国际民用航空组织危险物品安全航空运输技术细则（ICAO TI/IATA DGR）。GHS危险性分类：遇水放出易燃气体的物质和混合物类别1。Hazard Statements：H250（遇水放出易燃气体）；H260（与水接触可能自燃）。Precautionary Statements：P210（远离热源、火花、明火、热表面。禁止吸烟）；P222+P224（严禁与水接触）；P231+P232（在惰性气体中操作）；P370+P378（火灾时：使用干砂、干粉灭火剂）；P422（存放于干燥惰性气体中）；P501（按当地法规处置内装物/容器）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
