INSERT INTO `msds_regulatory` VALUES (4241, 4952, '国内法规：《危险化学品安全管理条例》、《危险化学品目录》；国际法规：IARC 1类致癌物', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4242, 4953, '国内法规：《危险化学品安全管理条例》（国务院令第591号），适用危险化学品生产、储存、使用、经营和运输的安全管理。《危险化学品目录（2015版）》，列入第4.1类易燃固体。国际法规：联合国《关于危险货物运输的建议书》（TDG），UN 3242，第4.1类易燃固体，II类包装。欧盟REACH法规，欧盟CLP法规（EC）No 1272/2008。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4243, 4954, '危险化学品安全管理条例（国务院令第591号），工作场所安全使用化学品规定（[1996]劳部发423号）等法规，针对危险化学品的安全使用、生产、储存、运输、装卸等方面均作了相应规定；常用危险化学品的分类及标志（GB13690-92）将该物质划为第3.2类中闪点易燃液体。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4244, 4955, '《危险化学品安全管理条例》（国务院令第591号）、《危险货物分类和品名编号》（GB 6944-2012）、《危险化学品目录》（2015版）、《工作场所安全使用化学品规定》（劳部发[1996]423号）等法律法规。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4245, 4956, '国内化学品管理法规：危险化学品安全管理条例（国务院令第591号）、危险化学品目录（2015版）、危险货物品名表（GB 12268-2012）、危险货物运输包装通用技术条件（GB 12463-2009）、危险货物道路运输安全管理办法、工作场所安全使用化学品规定（[1996]劳部发423号）。国际法规：联合国关于危险货物运输的建议书（TDG）、国际海事组织国际海运危险货物规则（IMDG Code）、国际民用航空组织危险物品安全航空运输技术细则（ICAO TI/IATA DGR）。GHS危险性分类：急性毒性类别3；皮肤腐蚀/刺激类别2；严重眼损伤/眼刺激类别2A；特异性靶器官毒性-反复接触类别2。Hazard Statements：H260（遇水释放易燃气体）、H314（造成严重皮肤灼伤和眼损伤）、H335（可能引起呼吸道刺激）、H372（长期或反复接触对器官造成伤害）。Precautionary Statements：P223（切勿与水接触）、P231+P232（在惰性气体中处理）、P260（不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾）、P264（作业后彻底清洗）、P280（穿戴防护手套/防护服/护眼/防护面具）、P305+P351+P338（如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗）、P321（具体治疗）、P370+P380（火灾时：撤离现场）、P371+P380+P375（火灾时：若火势无法控制，撤离现场）、P405（存放处须加锁）、P501（按当地法规处置内装物/容器）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4246, 4957, '无资料', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4247, 4958, NULL, '《危险化学品安全管理条例》\n        《危险货物道路运输规则》\n        《化学品安全技术说明书内容和项目顺序》GB/T 16483-2008\n        《化学品分类和危险性公示通则》GB 13690-2009', NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4248, 4959, '国内化学品管理法规：危险化学品安全管理条例（国务院令第591号）、危险化学品目录（2015版）、危险货物品名表（GB 12268-2012）、危险货物运输包装通用技术条件（GB 12463-2009）、危险货物道路运输安全管理办法、工作场所安全使用化学品规定（[1996]劳部发423号）。国际法规：联合国关于危险货物运输的建议书（TDG）、国际海事组织国际海运危险货物规则（IMDG Code）、国际民用航空组织危险物品安全航空运输技术细则（ICAO TI/IATA DGR）。GHS危险性分类：急性毒性类别3；皮肤腐蚀/刺激类别2；严重眼损伤/眼刺激类别2A；特异性靶器官毒性-反复接触类别2。Hazard Statements：H260（遇水释放易燃气体）、H314（造成严重皮肤灼伤和眼损伤）、H335（可能引起呼吸道刺激）、H372（长期或反复接触对器官造成伤害）。Precautionary Statements：P223（切勿与水接触）、P231+P232（在惰性气体中处理）、P260（不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾）、P264（作业后彻底清洗）、P280（穿戴防护手套/防护服/护眼/防护面具）、P305+P351+P338（如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗）、P321（具体治疗）、P370+P380（火灾时：撤离现场）、P371+P380+P375（火灾时：若火势无法控制，撤离现场）、P405（存放处须加锁）、P501（按当地法规处置内装物/容器）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4249, 4960, '国内化学品管理法规：危险化学品安全管理条例（国务院令第591号）、危险化学品目录（2015版）、危险货物品名表（GB 12268-2012）、危险货物运输包装通用技术条件（GB 12463-2009）、危险货物道路运输安全管理办法、工作场所安全使用化学品规定（[1996]劳部发423号）。国际法规：联合国关于危险货物运输的建议书（TDG）、国际海事组织国际海运危险货物规则（IMDG Code）、国际民用航空组织危险物品安全航空运输技术细则（ICAO TI/IATA DGR）。GHS危险性分类：急性毒性类别4；皮肤腐蚀/刺激类别2；严重眼损伤/眼刺激类别2A；生殖毒性类别1B。Hazard Statements：H302（吞咽有害）、H315（造成皮肤刺激）、H319（造成严重眼刺激）、H360（可能对生育能力或胎儿造成伤害）。Precautionary Statements：P201（使用前取得特别说明）、P202（在阅读并明了所有安全措施前切勿搬动）、P260（不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾）、P264（作业后彻底清洗）、P270（使用本产品时不要进食、饮水或吸烟）、P280（穿戴防护手套/防护服/护眼/防护面具）、P305+P351+P338（如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗）、P308+P313（如接触到或有疑虑：就医/出示此容器或标签）、P321（具体治疗）、P405（存放处须加锁）、P501（按当地法规处置内装物/容器）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4250, 4961, '国内化学品管理法规：危险化学品安全管理条例（国务院令第591号）、危险化学品目录（2015版）、危险货物品名表（GB 12268-2012）、危险货物运输包装通用技术条件（GB 12463-2009）、危险货物道路运输安全管理办法、工作场所安全使用化学品规定（[1996]劳部发423号）。国际法规：联合国关于危险货物运输的建议书（TDG）、国际海事组织国际海运危险货物规则（IMDG Code）、国际民用航空组织危险物品安全航空运输技术细则（ICAO TI/IATA DGR）。GHS危险性分类：易燃液体类别2；皮肤腐蚀/刺激类别2；严重眼损伤/眼刺激类别2A；特异性靶器官毒性-一次接触类别3。Hazard Statements：H225（高度易燃液体和蒸气）、H312（皮肤接触有害）、H315（造成皮肤刺激）、H319（造成严重眼刺激）、H336（可能引起嗜睡或头晕）。Precautionary Statements：P201（在使用前获取特别指示）、P202（在阅读并明了所有安全措施前切勿处置）、P210（远离热源、火花、明火、热表面。禁止吸烟）、P233（保持容器密闭）、P240（容器和接收设备接地/等电位连接）、P241（使用防爆电气、通风、照明设备）、P242（使用无火花工具）、P243（采取防止静电放电的措施）、P261（避免吸入粉尘/烟/气体/烟雾/蒸气/喷雾）、P264（作业后彻底清洗）、P270（使用本产品时不要进食、饮水或吸烟）、P271（只能在室外或通风良好的地方使用）、P273（避免释放到环境中）、P280（穿戴防护手套/防护服/护眼/防护面具）、P303+P361+P353（如皮肤（或头发）沾染：立即脱掉所有沾染的衣服。用水清洗皮肤/淋浴）、P304+P340（如误吸入：将人转移到空气新鲜处，保持呼吸舒适的体位）、P305+P351+P338（如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗）、P310（立即呼叫解毒中心或医生）、P321（具体治疗）、P331（切勿诱导呕吐）、P370+P380（火灾时：撤离现场）、P405（存放处须加锁）、P501（按当地法规处置内装物/容器）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
