INSERT INTO `msds_regulatory` VALUES (4263, 4975, '列入《危险化学品目录》，需按照危险化学品管理要求执行\n          需进行新化学物质登记（如适用）\n          可能列入重点环境管理危险化学品\n          作为溴代阻燃剂，需遵守斯德哥尔摩公约相关规定\n        \n        \n          列入持久性有机污染物（POPs）候选清单\n          需遵守事先知情同意程序\n          需进行注册评估（如出口欧盟）\n          列入有毒物质控制法管理范围\n          需进行化学物质审查（如出口日本）\n        \n        \n          中国：未制定具体限值；建议参考同类化合物标准\n          按照GHS标准分类：环境危险类别1，长期水生危害类别1', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
