INSERT INTO `msds_regulatory` VALUES (4293, 5005, '国内法规：危险化学品安全管理条例、易制毒化学品管理条例、危险化学品目录（2015版）。国际法规：IARC致癌性分类：3组（无法分类）；GHS危险性分类：急性毒性-经口、经皮、吸入（类别3）；皮肤腐蚀/刺激（类别2）；严重眼损伤/眼刺激（类别2）；特异性靶器官毒性-反复接触（类别2）；对水环境的危害-急性（类别1）；对水环境的危害-慢性（类别1）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4294, 5006, '国内法规：危险化学品安全管理条例、易制毒化学品管理条例、剧毒化学品购买和运输管理办法、危险化学品目录（2015版）、剧毒化学品名录（2022版）。国际法规：IARC致癌性分类：3组（无法分类）；GHS危险性分类：急性毒性-经口、经皮、吸入（类别1）；皮肤腐蚀/刺激（类别2）；严重眼损伤/眼刺激（类别2）；特异性靶器官毒性-反复接触（类别1）；对水环境的危害-急性（类别1）；对水环境的危害-慢性（类别1）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
