INSERT INTO `msds_regulatory` VALUES (4296, 5008, '国内法规：《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录（2015版）》、《剧毒化学品目录（2015版）》、《易制毒化学品管理条例》。国际法规：联合国《关于危险货物运输的建议书》（TDG）、《全球化学品统一分类和标签制度》（GHS）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
