INSERT INTO `msds_regulatory` VALUES (4298, 5010, '国内法规：危险化学品安全管理条例、易制毒化学品管理条例、危险化学品目录（2015版）。国际法规：IARC致癌性分类：1组（对人类致癌）；GHS危险性分类：急性毒性-经口、经皮、吸入（类别1）；皮肤腐蚀/刺激（类别2）；严重眼损伤/眼刺激（类别2）；特异性靶器官毒性-反复接触（类别1）；致癌性（类别1A）；生殖毒性（类别1B）；对水环境的危害-急性（类别1）；对水环境的危害-慢性（类别1）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4299, 5011, '国内法规：危险化学品安全管理条例（国务院令第591号）；剧毒化学品购买和公路运输许可证件管理办法；剧毒化学品目录（2015版）；危险化学品目录（2015版）；工作场所安全使用化学品规定；化学品安全技术说明书编写规定（GB/T 16483-2008）；化学品安全技术说明书内容和项目顺序（GB/T 17519-2013）。氰化汞属于剧毒化学品，购买、运输、储存、使用需严格遵守相关法律法规，办理相关许可证件。汞化合物属于重点环境管理危险化学品，需遵守水俣公约相关要求。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4300, 5012, '国内法规：危险化学品安全管理条例、易制毒化学品管理条例、剧毒化学品购买和运输管理办法、危险化学品目录（2015版）、工作场所安全使用化学品规定、常用危险化学品的分类及标志（GB 13690-2009）、化学品安全技术说明书内容和项目顺序（GB/T 16483-2008）、化学品安全技术说明书编写规定（GB/T 17519-2013）。国际法规：联合国关于危险货物运输的建议书（TDG）、全球化学品统一分类和标签制度（GHS）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
