INSERT INTO `msds_regulatory` VALUES (4353, 5065, NULL, '列入《危险化学品目录》（2015版），危险化学品编号：81133\n        生产、储存、使用单位需遵守《危险化学品安全管理条例》（国务院令第591号）\n        运输需遵守《危险货物道路运输规则》（JT/T 617）和《危险货物运输包装通用技术条件》（GB 12463）\n        排放需遵守《危险废物贮存污染控制标准》（GB 18597）和《危险废物焚烧污染控制标准》（GB 18484）\n        工作场所接触限值需遵守《工作场所有害因素职业接触限值》（GBZ 2.1）', NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
