INSERT INTO `msds_regulatory` VALUES (4408, 5124, NULL, '危险化学品安全管理条例\n        三氯硅烷属于危险化学品目录（2015版）中的化学品，需按照《危险化学品安全管理条例》进行管理\n        工作场所安全使用化学品规定\n        工作场所空气中三氯硅烷的时间加权平均容许浓度(PC-TWA)为1.5 mg/m³\n        危险化学品登记管理办法\n        三氯硅烷需进行危险化学品登记\n        中华人民共和国环境保护法\n        三氯硅烷的生产、使用和处置需符合环境保护要求', NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4409, 5125, '国内法规：危险化学品安全管理条例（国务院令第591号），工作场所安全使用化学品规定（〔1996〕劳部发423号），危险化学品目录（2015版）。国际法规：联合国关于危险货物运输的建议书（TDG），全球化学品统一分类和标签制度（GHS）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4410, 5126, '国内化学品安全管理法规：《危险化学品安全管理条例》、《工作场所安全使用化学品规定》等。国际法规：联合国GHS制度、欧盟CLP法规等。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4411, 5127, '《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录》（2015版）、《危险货物品名表》（GB 12268-2012）、《危险货物运输包装通用技术条件》（GB 12463-2009）、《危险货物道路运输安全管理办法》（交通运输部令2019年第29号）。本品属于第8.1类酸性腐蚀品，应按照相关法规进行生产、储存、运输和使用。本品不燃，具强腐蚀性、强刺激性，可致人体灼伤，需严格控制接触。遇水猛烈分解，产生大量的热和浓烟，甚至爆炸，需特别注意。包装必须密封，切勿受潮。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4412, 5128, '《危险化学品安全管理条例》（国务院令第591号）危险化学品目录：第8类腐蚀性物质。工作场所安全使用化学品规定：第8类腐蚀性物质。中华人民共和国安全生产法。中华人民共和国环境保护法。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
