INSERT INTO `msds_regulatory` VALUES (4471, 5194, '国内化学品管理法规：危险化学品安全管理条例、危险化学品目录（2015版）。国际法规：联合国关于危险货物运输的建议书（TDG）、国际海事组织国际海运危险货物规则（IMDG Code）、国际民用航空组织危险物品安全航空运输技术细则（ICAO TI/IATA DGR）。GHS危险性分类：急性毒性-吸入类别1；易燃气体类别1；皮肤腐蚀/刺激类别2；严重眼损伤/眼刺激类别2。Hazard Statements：H220（极易燃气体）、H330（吸入致命）、H315（造成皮肤刺激）、H319（造成严重眼刺激）。Precautionary Statements：P201（在使用前获取特别指示）、P202（在阅读并明了所有安全措施前切勿处置）、P210（远离热源、火花、明火、热表面。禁止吸烟）、P260（不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾）、P264（作业后彻底清洗）、P271（只能在室外或通风良好之处使用）、P280（穿戴防护手套/防护服/护眼/防护面具）、P304+P340（如误吸入：将受害人转移到空气新鲜处，保持呼吸舒适的体位）、P310（立即呼叫解毒中心或医生）、P321（具体治疗）、P405（存放处须加锁）、P410+P403（防日晒。存放于通风良好处）、P501（按当地法规处置内装物/容器）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
