INSERT INTO `msds_regulatory` VALUES (4491, 5214, '国内化学品管理法规：危险化学品安全管理条例、危险化学品目录（2015版）。国际法规：联合国关于危险货物运输的建议书（TDG）、国际海事组织国际海运危险货物规则（IMDG Code）、国际民用航空组织危险物品安全航空运输技术细则（ICAO TI/IATA DGR）。GHS危险性分类：易燃固体类别2。Hazard Statements：H228（易燃固体）、H315（造成皮肤刺激）、H319（造成严重眼刺激）。Precautionary Statements：P210（远离热源/火花/明火/热表面。禁止吸烟）、P261（避免吸入粉尘/烟/气体/烟雾/蒸气/喷雾）、P305+P351+P338（如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗）、P403+P235（存放在通风良好的地方。保持低温）、P501（按当地法规处置内装物/容器）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
