INSERT INTO `msds_regulatory` VALUES (4503, 5226, '国内法规：危险化学品安全管理条例（国务院令第591号）；工作场所安全使用化学品规定（劳部发[1996]423号）；危险化学品目录（2015版）；易制毒化学品管理条例（国务院令第445号）；危险化学品安全管理条例（国务院令第591号）。国际法规：国际海事组织（IMO）国际海运危险货物规则（IMDG Code）；国际民用航空组织（ICAO）国际航空运输危险物品规则（IATA-DGR）；联合国关于危险货物运输的建议书（橙皮书）；全球化学品统一分类和标签制度（GHS）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4504, 5227, '国内法规：危险化学品安全管理条例（国务院令第591号）；工作场所安全使用化学品规定（劳部发[1996]423号）；危险化学品目录（2015版）；易制毒化学品管理条例（国务院令第445号）；危险化学品安全管理条例（国务院令第591号）。国际法规：国际海事组织（IMO）国际海运危险货物规则（IMDG Code）；国际民用航空组织（ICAO）国际航空运输危险物品规则（IATA-DGR）；联合国关于危险货物运输的建议书（橙皮书）；全球化学品统一分类和标签制度（GHS）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4505, 5228, '国内法规：危险化学品安全管理条例、危险化学品目录（2015版）、新化学物质环境管理登记办法、持久性有机污染物（POPs）污染防治管理办法。国际法规：斯德哥尔摩公约（已列为持久性有机污染物，被禁用）、鹿特丹公约、欧盟REACH法规、美国TSCA法案（已禁用）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4506, 5229, '国内化学品管理法规：危险化学品安全管理条例、危险化学品目录（2015版）。国际法规：联合国关于危险货物运输的建议书（TDG）、国际海事组织国际海运危险货物规则（IMDG Code）、国际民用航空组织危险物品安全航空运输技术细则（ICAO TI/IATA DGR）。GHS危险性分类：易燃固体类别2；皮肤腐蚀/刺激类别2；严重眼损伤/眼刺激类别2；特异性靶器官毒性-一次接触类别3。Hazard Statements：H228（易燃固体）、H315（造成皮肤刺激）、H319（造成严重眼刺激）、H335（可能引起呼吸道刺激）。Precautionary Statements：P201（在使用前获取特别指示）、P202（在阅读并明了所有安全措施前切勿处置）、P210（远离热源/火花/明火/热表面。禁止吸烟）、P261（避免吸入粉尘/烟/气体/烟雾/蒸气/喷雾）、P264（作业后彻底清洗）、P270（使用本产品时不要进食、饮水或吸烟）、P280（穿戴防护手套/防护服/护眼/防护面具）、P305+P351+P338（如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗）、P501（按当地法规处置内装物/容器）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4507, 5230, '国内化学品管理法规：危险化学品安全管理条例、危险化学品目录（2015版）、危险货物品名表（GB 12268-2012）、危险货物运输包装通用技术条件（GB 12463-2009）、危险货物道路运输安全管理办法。国际法规：联合国关于危险货物运输的建议书（TDG）、国际海事组织国际海运危险货物规则（IMDG Code）、国际民用航空组织危险物品安全航空运输技术细则（ICAO TI/IATA DGR）。GHS危险性分类：致癌性类别1A；特异性靶器官毒性-反复接触类别1；对水环境的危害-急性毒性类别1。Hazard Statements：H350（可能致癌）、H372（长期或反复接触对器官造成伤害）、H410（对水生生物毒性极大并具有长期持续影响）。Precautionary Statements：P201（在使用前获取特别指示）、P202（在阅读并明了所有安全措施前切勿处置）、P260（不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾）、P264（作业后彻底清洗）、P270（使用本产品时不要进食、饮水或吸烟）、P273（避免释放到环境中）、P280（穿戴防护手套/防护服/护眼/防护面具）、P308+P313（如接触到或有疑虑：求医/就诊）、P314（如感觉不适，求医/就诊）、P361（脱掉沾染的所有衣服）、P362（脱掉沾染的衣服，清洗后方可重新使用）、P363（沾染的衣服清洗后方可重新使用）、P391（收集溢出物）、P405（存放处须加锁）、P501（按当地法规处置内装物/容器）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4508, 5231, '国内化学品管理法规：危险化学品安全管理条例、危险化学品目录（2015版）。国际法规：联合国关于危险货物运输的建议书（TDG）、国际海事组织国际海运危险货物规则（IMDG Code）、国际民用航空组织危险物品安全航空运输技术细则（ICAO TI/IATA DGR）。GHS危险性分类：易燃液体类别2；皮肤腐蚀/刺激类别2；严重眼损伤/眼刺激类别2；特异性靶器官毒性-一次接触类别3。Hazard Statements：H225（高度易燃液体和蒸气）、H315（造成皮肤刺激）、H319（造成严重眼刺激）、H335（可能引起呼吸道刺激）。Precautionary Statements：P201（在使用前获取特别指示）、P202（在阅读并明了所有安全措施前切勿处置）、P210（远离热源/火花/明火/热表面。禁止吸烟）、P233（保持容器密闭）、P261（避免吸入粉尘/烟/气体/烟雾/蒸气/喷雾）、P264（作业后彻底清洗）、P270（使用本产品时不要进食、饮水或吸烟）、P280（穿戴防护手套/防护服/护眼/防护面具）、P305+P351+P338（如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗）、P501（按当地法规处置内装物/容器）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4509, 5232, '国内化学品管理法规：危险化学品安全管理条例、危险化学品目录（2015版）、危险货物品名表（GB 12268-2012）、危险货物运输包装通用技术条件（GB 12463-2009）、危险货物道路运输安全管理办法。国际法规：联合国关于危险货物运输的建议书（TDG）、国际海事组织国际海运危险货物规则（IMDG Code）、国际民用航空组织危险物品安全航空运输技术细则（ICAO TI/IATA DGR）。GHS危险性分类：易燃液体类别1；皮肤腐蚀/刺激类别2；严重眼损伤/眼刺激类别2A；特异性靶器官毒性-一次接触类别3；对水环境的危害-急性毒性类别1。Hazard Statements：H225（高度易燃液体和蒸气）、H315（造成皮肤刺激）、H319（造成严重眼刺激）、H335（可能引起呼吸道刺激）、H410（对水生生物毒性极大并具有长期持续影响）。Precautionary Statements：P201（在使用前获取特别指示）、P202（在阅读并明了所有安全措施前切勿处置）、P210（远离热源、火花、明火、热表面。禁止吸烟）、P233（保持容器密闭）、P240（容器和接收设备接地/等势连接）、P241（使用防爆电气/通风/照明设备）、P242（只能使用不产生火花的工具）、P243（采取防止静电放电的措施）、P260（不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾）、P261（避免吸入粉尘/烟/气体/烟雾/蒸气/喷雾）、P264（作业后彻底清洗）、P270（使用本产品时不要进食、饮水或吸烟）、P273（避免释放到环境中）、P280（穿戴防护手套/防护服/护眼/防护面具）、P301+P310（如误吞咽：立即呼叫解毒中心或医生）、P302+P352（如皮肤沾染：用大量肥皂和水清洗）、P305+P351+P338（如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗）、P308+P313（如接触到或有疑虑：求医/就诊）、P310（立即呼叫解毒中心或医生）、P321（具体治疗）、P322（具体措施）、P330（漱口）、P332+P313（如发生皮肤刺激：求医/就诊）、P337+P313（如发生眼刺激：求医/就诊）、P361（脱掉沾染的所有衣服）、P362（脱掉沾染的衣服，清洗后方可重新使用）、P363（沾染的衣服清洗后方可重新使用）、P370+P380（火灾时：撤离现场）、P371+P380（火灾时：如果安全，消除火源）、P371（火灾时：如爆炸危险，撤离现场）、P371+P380+P375（火灾时：如爆炸危险，撤离现场。如安全，消除火源。由于爆炸危险，从侧面和背面灭火）、P403+P235（存放在通风良好的地方）、P405（存放处须加锁）、P501（按当地法规处置内装物/容器）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4510, 5233, '国内化学品管理法规：危险化学品安全管理条例、危险化学品目录（2015版）、危险货物品名表（GB 12268-2012）、危险货物运输包装通用技术条件（GB 12463-2009）、危险货物道路运输安全管理办法。国际法规：联合国关于危险货物运输的建议书（TDG）、国际海事组织国际海运危险货物规则（IMDG Code）、国际民用航空组织危险物品安全航空运输技术细则（ICAO TI/IATA DGR）。GHS危险性分类：易燃气体类别1；皮肤腐蚀/刺激类别2；严重眼损伤/眼刺激类别2A；特异性靶器官毒性-一次接触类别3；对水环境的危害-急性毒性类别1。Hazard Statements：H220（极易燃气体）、H315（造成皮肤刺激）、H319（造成严重眼刺激）、H335（可能引起呼吸道刺激）、H410（对水生生物毒性极大并具有长期持续影响）。Precautionary Statements：P201（在使用前获取特别指示）、P202（在阅读并明了所有安全措施前切勿处置）、P210（远离热源、火花、明火、热表面。禁止吸烟）、P220（远离热源、火花、明火、热表面）、P233（保持容器密闭）、P240（容器和接收设备接地/等势连接）、P241（使用防爆电气/通风/照明设备）、P242（只能使用不产生火花的工具）、P243（采取防止静电放电的措施）、P260（不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾）、P261（避免吸入粉尘/烟/气体/烟雾/蒸气/喷雾）、P264（作业后彻底清洗）、P270（使用本产品时不要进食、饮水或吸烟）、P273（避免释放到环境中）、P280（穿戴防护手套/防护服/护眼/防护面具）、P301+P310（如误吞咽：立即呼叫解毒中心或医生）、P302+P352（如皮肤沾染：用大量肥皂和水清洗）、P305+P351+P338（如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗）、P308+P313（如接触到或有疑虑：求医/就诊）、P310（立即呼叫解毒中心或医生）、P321（具体治疗）、P322（具体措施）、P330（漱口）、P332+P313（如发生皮肤刺激：求医/就诊）、P337+P313（如发生眼刺激：求医/就诊）、P361（脱掉沾染的所有衣服）、P362（脱掉沾染的衣服，清洗后方可重新使用）、P363（沾染的衣服清洗后方可重新使用）、P370+P380（火灾时：撤离现场）、P371+P380（火灾时：如果安全，消除火源）、P371（火灾时：如爆炸危险，撤离现场）、P371+P380+P375（火灾时：如爆炸危险，撤离现场。如安全，消除火源。由于爆炸危险，从侧面和背面灭火）、P403+P235（存放在通风良好的地方）、P405（存放处须加锁）、P501（按当地法规处置内装物/容器）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
