INSERT INTO `msds_regulatory` VALUES (4526, 5249, '国内法规：危险化学品安全管理条例、易制毒化学品管理条例。国际法规：联合国GHS分类标准、国际海运危险货物规则（IMDG Code）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4527, 5250, '国内化学品管理法规：危险化学品安全管理条例、工作场所安全使用化学品规定、危险化学品登记管理办法。国际法规：联合国关于危险货物运输的建议书（橙皮书）、国际海运危险货物规则（IMDG Code）、国际空运危险货物规则（IATA-DGR）。GHS危险性分类：第4.1类易燃固体。Hazard Statements: H228 易燃固体。H315 造成皮肤刺激。H319 造成严重眼刺激。Precautionary Statements: P210 远离热源、火花、明火、热表面。禁止吸烟。P240 容器和装载设备接地/等势连接。P241 使用防爆的电气、通风和照明设备。P242 只能使用不产生火花的工具。P243 采取防止静电放电的措施。P261 避免吸入粉尘、烟、气体、烟雾、蒸气、喷雾。P264 作业后彻底清洗。P270 禁止本产品使用时进食、饮水或吸烟。P271 只能在室外或通风良好的地方使用。P280 戴防护手套/穿防护服/戴护目镜/戴面罩。P301+P310 如误吞咽：立即呼叫中毒控制中心或医生。P302+P352 如皮肤沾染：用大量肥皂和水清洗。P305+P351+P338 如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。P312 如感觉不适，呼叫中毒控制中心或医生。P321 具体治疗（见本标签上的……）。P332+P313 如发生皮肤刺激：求医/就诊。P337+P313 如仍觉眼刺激：求医/就诊。P370+P376 在火灾爆炸时：穿戴呼吸防护装备。P403+P235 存放在通风良好的地方。P403+P235 存放在通风良好的地方。保持低温。P501 按当地法规处置内装物/容器。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4528, 5251, '国内化学品管理法规：危险化学品安全管理条例、工作场所安全使用化学品规定、危险化学品登记管理办法。国际法规：联合国关于危险货物运输的建议书（橙皮书）、国际海运危险货物规则（IMDG Code）、国际空运危险货物规则（IATA-DGR）。GHS危险性分类：第4.1类易燃固体。Hazard Statements: H228 易燃固体。H315 造成皮肤刺激。H319 造成严重眼刺激。Precautionary Statements: P210 远离热源、火花、明火、热表面。禁止吸烟。P240 容器和装载设备接地/等势连接。P241 使用防爆的电气、通风和照明设备。P242 只能使用不产生火花的工具。P243 采取防止静电放电的措施。P261 避免吸入粉尘、烟、气体、烟雾、蒸气、喷雾。P264 作业后彻底清洗。P270 禁止本产品使用时进食、饮水或吸烟。P271 只能在室外或通风良好的地方使用。P280 戴防护手套/穿防护服/戴护目镜/戴面罩。P301+P310 如误吞咽：立即呼叫中毒控制中心或医生。P302+P352 如皮肤沾染：用大量肥皂和水清洗。P305+P351+P338 如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。P312 如感觉不适，呼叫中毒控制中心或医生。P321 具体治疗（见本标签上的……）。P332+P313 如发生皮肤刺激：求医/就诊。P337+P313 如仍觉眼刺激：求医/就诊。P370+P376 在火灾爆炸时：穿戴呼吸防护装备。P403+P235 存放在通风良好的地方。P403+P235 存放在通风良好的地方。保持低温。P501 按当地法规处置内装物/容器。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4529, 5252, '国内化学品管理法规：危险化学品安全管理条例、工作场所安全使用化学品规定、危险化学品登记管理办法。国际法规：联合国关于危险货物运输的建议书（橙皮书）、国际海运危险货物规则（IMDG Code）、国际空运危险货物规则（IATA-DGR）。GHS危险性分类：第4.1类易燃固体。Hazard Statements: H228 易燃固体。H315 造成皮肤刺激。H319 造成严重眼刺激。Precautionary Statements: P210 远离热源、火花、明火、热表面。禁止吸烟。P240 容器和装载设备接地/等势连接。P241 使用防爆的电气、通风和照明设备。P242 只能使用不产生火花的工具。P243 采取防止静电放电的措施。P261 避免吸入粉尘、烟、气体、烟雾、蒸气、喷雾。P264 作业后彻底清洗。P270 禁止本产品使用时进食、饮水或吸烟。P271 只能在室外或通风良好的地方使用。P280 戴防护手套/穿防护服/戴护目镜/戴面罩。P301+P310 如误吞咽：立即呼叫中毒控制中心或医生。P302+P352 如皮肤沾染：用大量肥皂和水清洗。P305+P351+P338 如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。P312 如感觉不适，呼叫中毒控制中心或医生。P321 具体治疗（见本标签上的……）。P332+P313 如发生皮肤刺激：求医/就诊。P337+P313 如仍觉眼刺激：求医/就诊。P370+P376 在火灾爆炸时：穿戴呼吸防护装备。P403+P235 存放在通风良好的地方。P403+P235 存放在通风良好的地方。保持低温。P501 按当地法规处置内装物/容器。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
