INSERT INTO `msds_regulatory` VALUES (4540, 5263, '国内法规：危险化学品安全管理条例、危险化学品目录（2015版）。国际法规：IARC致癌性分类：无资料。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
