INSERT INTO `msds_regulatory` VALUES (4550, 5273, '1. 国内法规：列入《危险化学品目录(2022调整版)》，危险化学品编号：2021。根据《危险化学品安全管理条例》进行管理。2. 国际法规：UN 3267，IMDG Class 8，第8类腐蚀性物质。3. 其他法规：应遵守国家有关环境保护、职业健康安全等相关法律法规。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4551, 5274, '危险化学品安全管理条例、工作场所安全使用化学品规定等法规。该物质属于有毒化学品，应按照相关法规进行管理。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
