INSERT INTO `msds_regulatory` VALUES (4556, 5279, '《放射性物品运输安全管理条例》；GB11806-2019《放射性物品安全运输规程》；GB30000—2013《化学品分类和标签规范》；GB/T 16483—2008《化学品安全技术说明书内容和项目顺序》；GB/T 17519—2013《化学品安全技术说明书编写指南》', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4557, 5281, NULL, NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4558, 5282, '国内化学品管理法规：《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录（2015版）》、《工作场所安全使用化学品规定》（[1996]劳部发423号）、《易制毒化学品管理条例》、《易制爆危险化学品管理条例》。国际法规：UN 1081（第2.1类易燃气体），IMDG Code 2.1类，IATA-DGR 2.1类，ADR 2.1类。GHS分类：易燃气体类别1，压力下气体。标签要素：易燃气体，火焰图标。警示词：危险。危险说明：极易燃气体；含压力下气体，如受热可爆炸。防范说明：远离火种、热源；使用防爆型设备；保持容器密闭；使用防爆型电气设备；避免吸入蒸气。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4559, 5283, '危险化学品安全管理条例（国务院令第591号），工作场所安全使用化学品规定（〔1996〕劳部发423号）等法规，针对危险化学品的安全使用、生产、储存、运输、装卸等方面均作了相应规定。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4560, 5284, '国内法规：危险化学品安全管理条例（国务院令第591号）；危险化学品目录（2015版）；工作场所安全使用化学品规定（[1996]劳部发423号）。国际法规：GHS危险性类别：易燃液体，类别2；特异性靶器官毒性-反复接触，类别2；对水环境危害-急性危害，类别2。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4561, 5285, '《危险化学品安全管理条例》、《危险货物分类和品名编号》(GB 6944-2012)、《危险化学品目录》', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4562, 5286, '危险化学品安全管理条例（国务院令第591号），工作场所安全使用化学品规定（劳部发[1996]423号）等法规，针对化学危险品的安全使用、生产、储存、运输、装卸等方面均作了相应规定；常用危险化学品的分类及标志（GB 13690-92）将该物质划为第6.1类毒害品；剧毒化学品目录（2015版）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4563, 5288, '危险化学品安全管理条例：本品属于第8类腐蚀性物质，危险货物编号81044。生产、储存、使用、经营和运输应遵守相关安全管理规定。适用法规：《危险化学品安全管理条例》(国务院令第591号)、《危险货物品名表》(GB12268)、《化学品安全技术说明书内容和项目顺序》(GB/T 16483-2008)、《危险化学品目录(2015版)》', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
