INSERT INTO `msds_regulatory` VALUES (4568, 5294, '国内法规：《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录（2015版）》、《易制毒化学品管理条例》、《危险废物经营许可证管理办法》、《危险货物运输规则》（JT/T 617）、《道路危险货物运输管理规定》、《工作场所安全使用化学品规定》、《职业病防治法》。国际法规：联合国《关于危险货物运输的建议书》（TDG）、《国际海运危险货物规则》（IMDG Code）、《国际航空运输危险物品规则》（IATA-DGR）、欧盟《化学品注册、评估、授权和限制法规》（REACH）、《全球化学品统一分类和标签制度》（GHS）。四氯化钛属于第8类腐蚀性物质，UN编号1838，国内危险货物编号81051。生产、储存、运输、使用和处置本物质必须遵守相关法律法规要求。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
