INSERT INTO `msds_regulatory` VALUES (4755, 5509, '国内化学品管理法规：危险化学品安全管理条例、易制毒化学品管理条例、危险化学品目录（2015版）。国际法规：UN 1062（有毒气体，类别2.3）、GHS危险性分类：易燃气体类别1、急性毒性-吸入类别2、特异性靶器官毒性-反复接触类别2、危害臭氧层。Hazard Statements：H220（极易燃气体）、H330（吸入致命）、H331（吸入中毒）、H373（可能对器官造成伤害）、H410（对水生生物毒性极大并具有长期持续影响）。Precautionary Statements：P210（远离热源、火花、明火、热表面。禁止吸烟）、P220（远离服装和其他可燃材料）、P260（不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾）、P261（避免吸入粉尘/烟/气体/烟雾/蒸气/喷雾）、P271（只能在室外或通风良好之处使用）、P304+P340（如误吸入：将人转移到空气新鲜处，如呼吸停止，进行人工呼吸）、P403+P233（存放在通风良好的地方。保持容器密闭）、P405（存放处须加锁）、P501（处置内装物/容器按照当地法规）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
