INSERT INTO `msds_regulatory` VALUES (4769, 5523, '国内化学品管理法规：危险化学品安全管理条例、危险化学品目录（2015版）。国际法规：UN 1993（易燃液体，类别3）、GHS危险性分类：易燃液体类别3、皮肤腐蚀/刺激类别2、严重眼损伤/眼刺激类别2。Hazard Statements：H225（高度易燃液体和蒸气）、H315（造成皮肤刺激）、H319（造成严重眼刺激）、H335（可能引起呼吸道刺激）。Precautionary Statements：P210（远离热源、火花、明火、热表面。禁止吸烟）、P233（保持容器密闭）、P240（容器和接收设备接地/等势连接）、P241（使用防爆的电气、通风、照明设备）、P242（只能使用不产生火花的工具）、P243（采取防止静电放电的措施）、P261（避免吸入粉尘/烟/气体/烟雾/蒸气/喷雾）、P264（作业后彻底清洗）、P270（使用本产品时不要进食、饮水或吸烟）、P271（只能在室外或通风良好之处使用）、P280（戴防护手套/穿防护服/戴防护眼罩/戴面罩）、P301+P312（如误吞咽：如感觉不适，呼叫解毒中心或医生）、P302+P352（如皮肤沾染：用大量肥皂和水清洗）、P305+P351+P338（如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗）、P312（如感觉不适，呼叫解毒中心或医生）、P321（具体治疗）、P330（漱口）、P333+P313（如发生皮肤刺激：求医/就诊）、P337+P313（如仍觉眼刺激：求医/就诊）、P362+P364（如沾染衣物：立即脱去所有沾染的衣物）、P370+P378（火灾时：使用灭火器灭火）、P403+P233（存放在通风良好的地方。保持容器密闭）、P405（存放处须加锁）、P501（处置内装物/容器按照当地法规）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
