INSERT INTO `msds_regulatory` VALUES (4823, 5590, '国内法规：危险化学品安全管理条例（国务院令第591号），工作场所安全使用化学品规定（劳部发[1996]423号）等法规，针对危险化学品的安全使用、生产、储存、运输、装卸等方面均作了相应规定。国际法规：联合国关于危险货物运输的建议书（TDG），国际海事组织（IMO）国际海运危险货物规则（IMDG Code），国际民航组织（ICAO）国际空运危险货物规则（IATA DGR），欧盟化学品注册、评估、授权和限制法规（REACH），全球化学品统一分类和标签制度（GHS）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4824, 5591, '国内化学品管理法规：危险化学品安全管理条例、易制毒化学品管理条例、危险化学品目录（2015版）。国际法规：联合国关于危险货物运输的建议书（TDG）、国际海事组织国际海运危险货物规则（IMDG Code）、国际民用航空组织危险物品安全航空运输技术细则（ICAO TI/IATA DGR）。GHS危险性分类：急性毒性-经口类别1；急性毒性-经皮类别2；急性毒性-吸入类别1；皮肤腐蚀/刺激类别2；严重眼损伤/眼刺激类别2；特异性靶器官系统毒性-反复接触类别2。Hazard Statements：H300（吞咽致命）；H310（皮肤接触致命）；H330（吸入致命）；H315（造成皮肤刺激）；H319（造成严重眼刺激）；H336（可能引起嗜睡或眩晕）。Precautionary Statements：P201（使用前取得特别说明）；P202（在阅读所有明了安全措施前切勿操作）；P260（不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾）；P264（作业后彻底清洗）；P270（使用本产品时不要进食、饮水或吸烟）；P271（只能在室外或通风良好之处使用）；P280（戴防护手套/穿防护服/戴护目镜/戴面罩）；P301+P310（如果吞咽：立即呼叫解毒中心/医生）；P302+P352（如皮肤沾染：用大量肥皂和水清洗）；P304+P340（如误吸入：将人转移到空气新鲜处，如呼吸停止，进行人工呼吸）；P305+P351+P338（如进入眼睛：小心用水冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗）；P310（立即呼叫解毒中心/医生）；P321（具体治疗）；P330（漱口）；P361+P364（立即脱掉所有沾染的衣服，清洗后方可重新使用）；P370+P380（火灾：疏散到安全区域）；P391（收集溢出物）；P405（存放处须加锁）；P501（按当地法规处置内装物/容器）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4825, 5592, '国内化学品安全管理法规：《危险化学品安全管理条例》、《工作场所安全使用化学品规定》等。国际法规：EC编号209-014-3。该化学品属于第6.1类毒害品，应按照相关法规进行管理和使用。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4826, 5593, '国内化学品管理法规：危险化学品安全管理条例、危险化学品目录（2015版）、危险货物品名表（GB 12268-2012）、危险货物运输包装通用技术条件（GB 12463-2009）、危险货物道路运输安全管理办法。国际法规：联合国关于危险货物运输的建议书（TDG）、国际海事组织国际海运危险货物规则（IMDG Code）、国际民用航空组织危险物品安全航空运输技术细则（ICAO TI/IATA DGR）。GHS危险性分类：皮肤腐蚀/刺激类别2；严重眼损伤/眼刺激类别2A；特异性靶器官毒性-一次接触类别3。Hazard Statements：H315（造成皮肤刺激）、H319（造成严重眼刺激）、H335（可能引起呼吸道刺激）。Precautionary Statements：P201（在使用前获取特别指示）、P202（在阅读并明了所有安全措施前切勿处置）、P260（不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾）、P264（作业后彻底清洗）、P270（使用本产品时不要进食、饮水或吸烟）、P280（穿戴防护手套/防护服/护眼/防护面具）、P301+P330+P331（如误吞咽：漱口。切勿诱导呕吐）、P303+P361+P353（如皮肤（或头发）沾染：立即脱掉所有沾染的衣服。用水清洗皮肤/淋浴）、P304+P340（如误吸入：将人转移到空气新鲜处，保持呼吸舒适的体位）、P305+P351+P338（如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗）、P310（立即呼叫解毒中心或医生）、P321（具体治疗）、P362（脱掉沾染的衣服，清洗后方可重新使用）、P363（沾染的衣服清洗后方可重新使用）、P405（存放处须加锁）、P501（按当地法规处置内装物/容器）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4827, 5594, '国内化学品安全管理法规：《危险化学品安全管理条例》、《工作场所安全使用化学品规定》等。该化学品属于第6.1类毒害品，应按照相关法规进行管理和使用。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4828, 5595, '国内化学品管理法规：危险化学品安全管理条例、危险化学品目录（2015版）、危险货物品名表（GB 12268-2012）、危险货物运输包装通用技术条件（GB 12463-2009）、危险货物道路运输安全管理办法。国际法规：联合国关于危险货物运输的建议书（TDG）、国际海事组织国际海运危险货物规则（IMDG Code）、国际民用航空组织危险物品安全航空运输技术细则（ICAO TI/IATA DGR）。GHS危险性分类：皮肤腐蚀/刺激类别2；严重眼损伤/眼刺激类别2A；特异性靶器官毒性-重复接触类别2；致癌性类别1B。Hazard Statements：H301（吞咽中毒）、H311（皮肤接触中毒）、H331（吸入中毒）、H315（造成皮肤刺激）、H319（造成严重眼刺激）、H351（怀疑致癌）、H370（对器官造成损害）。Precautionary Statements：P201（在使用前获取特别指示）、P202（在阅读并明了所有安全措施前切勿处置）、P260（不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾）、P264（作业后彻底清洗）、P270（使用本产品时不要进食、饮水或吸烟）、P280（穿戴防护手套/防护服/护眼/防护面具）、P301+P330+P331（如误吞咽：漱口。切勿诱导呕吐）、P303+P361+P353（如皮肤（或头发）沾染：立即脱掉所有沾染的衣服。用水清洗皮肤/淋浴）、P304+P340（如误吸入：将人转移到空气新鲜处，保持呼吸舒适的体位）、P305+P351+P338（如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗）、P310（立即呼叫解毒中心或医生）、P321（具体治疗）、P362（脱掉沾染的衣服，清洗后方可重新使用）、P363（沾染的衣服清洗后方可重新使用）、P405（存放处须加锁）、P501（按当地法规处置内装物/容器）。IARC分类：1类致癌物（对人类致癌）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4829, 5596, '国内化学品管理法规：危险化学品安全管理条例、危险化学品目录（2015版）、危险货物品名表（GB 12268-2012）、危险货物运输包装通用技术条件（GB 12463-2009）、危险货物道路运输安全管理办法。国际法规：联合国关于危险货物运输的建议书（TDG）、国际海事组织国际海运危险货物规则（IMDG Code）、国际民用航空组织危险物品安全航空运输技术细则（ICAO TI/IATA DGR）。GHS危险性分类：皮肤腐蚀/刺激类别2；严重眼损伤/眼刺激类别2A；特异性靶器官毒性-重复接触类别2；致癌性类别1B。Hazard Statements：H301（吞咽中毒）、H311（皮肤接触中毒）、H331（吸入中毒）、H315（造成皮肤刺激）、H319（造成严重眼刺激）、H351（怀疑致癌）、H370（对器官造成损害）。Precautionary Statements：P201（在使用前获取特别指示）、P202（在阅读并明了所有安全措施前切勿处置）、P260（不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾）、P264（作业后彻底清洗）、P270（使用本产品时不要进食、饮水或吸烟）、P280（穿戴防护手套/防护服/护眼/防护面具）、P301+P330+P331（如误吞咽：漱口。切勿诱导呕吐）、P303+P361+P353（如皮肤（或头发）沾染：立即脱掉所有沾染的衣服。用水清洗皮肤/淋浴）、P304+P340（如误吸入：将人转移到空气新鲜处，保持呼吸舒适的体位）、P305+P351+P338（如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗）、P310（立即呼叫解毒中心或医生）、P321（具体治疗）、P362（脱掉沾染的衣服，清洗后方可重新使用）、P363（沾染的衣服清洗后方可重新使用）、P405（存放处须加锁）、P501（按当地法规处置内装物/容器）。IARC分类：2B组致癌物（可能对人类致癌）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
