INSERT INTO `msds_regulatory` VALUES (4853, 5620, '《危险化学品安全管理条例》《危险化学品目录》《工作场所安全使用化学品规定》', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4854, 5621, '《危险化学品安全管理条例》《危险化学品目录》《工作场所安全使用化学品规定》', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4855, 5622, '国内化学品管理法规：危险化学品安全管理条例、工作场所安全使用化学品规定、危险化学品登记管理办法。国际法规：联合国关于危险货物运输的建议书（橙皮书）、国际海运危险货物规则（IMDG Code）、国际空运危险货物规则（IATA-DGR）。GHS危险性分类：第6.1类毒害品。Hazard Statements: H301 吞咽致命。H311 皮肤接触致命。H331 吸入致命。H350 可能致癌。H370 对器官造成损害。H410 对水生生物毒性极大并具有长期持续影响。Precautionary Statements: P260 不要吸入粉尘、烟、气体、烟雾、蒸气、喷雾。P264 作业后彻底清洗。P270 使用本产品时禁止进食、饮水或吸烟。P271 只能在室外或通风良好之处使用。P280 戴防护手套/穿防护服/戴护目镜/戴面罩。P301+P310 如误吞咽：立即呼叫中毒控制中心或医生。P302+P352 如皮肤沾染：用大量肥皂和水清洗。P304+P340 如误吸入：将人转移到空气新鲜处，保持呼吸舒适体位。P305+P351+P338 如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。P308+P311 如暴露或关注：呼叫中毒控制中心。P321 具体治疗（见本标签上的……）。P330 漱口。P361+P364 脱掉沾染的衣服，清洗后方可重新使用。P403+P233 存放在通风良好的地方。P405 存放处须加锁。P501 按当地法规处置内装物/容器。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4856, 5623, '《危险化学品安全管理条例》《危险化学品目录》《工作场所安全使用化学品规定》《剧毒化学品目录》', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4857, 5624, '国内化学品管理法规：危险化学品安全管理条例、易制毒化学品管理条例、危险化学品目录（2015版）。国际法规：IARC致癌性分类：3组（无法分类）；GHS危险性分类：急性毒性-经口、经皮、吸入（类别2）；皮肤腐蚀/刺激（类别2）；严重眼损伤/眼刺激（类别2）；特异性靶器官毒性-反复接触（类别2）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4858, 5625, '国内化学品管理法规：危险化学品安全管理条例、易制毒化学品管理条例、危险化学品目录（2015版）。国际法规：IARC致癌性分类：3组（无法分类）；GHS危险性分类：急性毒性-经口、经皮、吸入（类别1）；皮肤腐蚀/刺激（类别2）；严重眼损伤/眼刺激（类别2）；特异性靶器官毒性-反复接触（类别1）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4859, 5626, '国内化学品管理法规：危险化学品安全管理条例、工作场所安全使用化学品规定、危险化学品登记管理办法。国际法规：联合国关于危险货物运输的建议书（橙皮书）、国际海运危险货物规则（IMDG Code）、国际空运危险货物规则（IATA-DGR）。GHS危险性分类：第5.1类氧化性物质。Hazard Statements: H272 可能加剧燃烧；氧化剂。H302 吞咽有害。H315 造成皮肤刺激。H319 造成严重眼刺激。H335 可能引起呼吸道刺激。Precautionary Statements: P210 远离热源、火花、明火、热表面。P220 切勿与可燃物、还原剂、酸类、有机物等接触。P261 避免吸入粉尘、烟、气体、烟雾、蒸气、喷雾。P264 作业后彻底清洗。P270 使用本产品时禁止进食、饮水或吸烟。P271 只能在室外或通风良好之处使用。P280 戴防护手套/穿防护服/戴护目镜/戴面罩。P301+P312 如误吞咽：如感觉不适，呼叫中毒控制中心或医生。P302+P352 如皮肤沾染：用大量肥皂和水清洗。P304+P340 如误吸入：将人转移到空气新鲜处，保持呼吸舒适体位。P305+P351+P338 如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。P321 具体治疗（见本标签上的……）。P330 漱口。P361+P364 脱掉沾染的衣服，清洗后方可重新使用。P370+P380 火灾时：撤离现场。P371+P380 在发生火灾时：如果火势很大且无法扑灭，请撤离现场。P378 灭火时使用……。P403+P235 存放在通风良好的地方。P405 存放处须加锁。P501 按当地法规处置内装物/容器。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4860, 5627, '危险化学品安全管理条例（2002年1月26日国务院第344号令公布，自2002年3月15日起施行）', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4861, 5628, '国内化学品管理法规：危险化学品安全管理条例、工作场所安全使用化学品规定、危险化学品登记管理办法。国际法规：联合国关于危险货物运输的建议书（橙皮书）、国际海运危险货物规则（IMDG Code）、国际空运危险货物规则（IATA-DGR）。GHS危险性分类：第8.1类酸性腐蚀品。Hazard Statements: H314 造成严重皮肤灼伤和眼损伤。H335 可能引起呼吸道刺激。H400 对水生生物毒性极大。H410 对水生生物毒性极大并具有长期持续影响。Precautionary Statements: P260 不要吸入粉尘、烟、气体、烟雾、蒸气、喷雾。P264 作业后彻底清洗。P270 使用本产品时禁止进食、饮水或吸烟。P271 只能在室外或通风良好之处使用。P280 戴防护手套/穿防护服/戴护目镜/戴面罩。P301+P330+P331 如误吞咽：漱口。不要催吐。P303+P361+P353 如皮肤（或头发）沾染：立即脱掉所有沾染的衣服。用水清洗皮肤/淋浴。P304+P340 如误吸入：将人转移到空气新鲜处，保持呼吸舒适体位。P305+P351+P338 如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。P310 立即呼叫中毒控制中心或医生。P362+P364 脱掉沾染的衣服，清洗后方可重新使用。P390 吸收溢出物，防止材料损坏。P403+P235 存放在通风良好的地方。P405 存放处须加锁。P501 按当地法规处置内装物/容器。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4862, 5629, '国内化学品管理法规：危险化学品安全管理条例、工作场所安全使用化学品规定、危险化学品登记管理办法。国际法规：联合国关于危险货物运输的建议书（橙皮书）、国际海运危险货物规则（IMDG Code）、国际空运危险货物规则（IATA-DGR）。GHS危险性分类：第8.1类酸性腐蚀品。Hazard Statements: H314 造成严重皮肤灼伤和眼损伤。H335 可能引起呼吸道刺激。H400 对水生生物毒性极大。H410 对水生生物毒性极大并具有长期持续影响。Precautionary Statements: P260 不要吸入粉尘、烟、气体、烟雾、蒸气、喷雾。P264 作业后彻底清洗。P270 使用本产品时禁止进食、饮水或吸烟。P271 只能在室外或通风良好之处使用。P280 戴防护手套/穿防护服/戴护目镜/戴面罩。P301+P330+P331 如误吞咽：漱口。不要催吐。P303+P361+P353 如皮肤（或头发）沾染：立即脱掉所有沾染的衣服。用水清洗皮肤/淋浴。P304+P340 如误吸入：将人转移到空气新鲜处，保持呼吸舒适体位。P305+P351+P338 如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。P310 立即呼叫中毒控制中心或医生。P362+P364 脱掉沾染的衣服，清洗后方可重新使用。P390 吸收溢出物，防止材料损坏。P403+P235 存放在通风良好的地方。P405 存放处须加锁。P501 按当地法规处置内装物/容器。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
