INSERT INTO `msds_regulatory` VALUES (4900, 5679, '《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录》（2015版）、《危险货物品名表》（GB 12268-2012）、《危险货物运输包装通用技术条件》（GB 12463-2009）、《危险货物道路运输安全管理办法》（交通运输部令2019年第29号）。本品属于第3.1类低闪点易燃液体，应按照相关法规进行生产、储存、运输和使用。本品为可疑致癌物（IARC分类：2B类），需严格控制接触。注意：能发生聚合反应，需添加阻聚剂。在空气中久置后能生成有爆炸性的过氧化物。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
