INSERT INTO `msds_regulatory` VALUES (4917, 5697, '国内化学品安全管理法规：《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录（2015版）》、《危险化学品安全管理条例实施细则》。国际法规：联合国《关于危险货物运输的建议书》（TDG）、《国际海运危险货物规则》（IMDG Code）、《国际空运危险货物规则》（IATA-DGR）。GHS分类：易燃液体类别3，皮肤腐蚀/刺激类别2，严重眼损伤/眼刺激类别2A，特异性靶器官毒性-反复接触类别3。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
