INSERT INTO `msds_regulatory` VALUES (4919, 5699, '国内法规：危险化学品安全管理条例、易制毒化学品管理条例、工作场所安全使用化学品规定。国际法规：联合国关于危险货物运输的建议书（TDG）、国际海运危险货物规则（IMDG Code）、国际民航组织危险物品安全航空运输技术细则（ICAO TI）。GHS分类：急性毒性-经口，类别3；急性毒性-经皮，类别3；急性毒性-吸入，类别2；皮肤腐蚀/刺激，类别2；严重眼损伤/眼刺激，类别2；特异性靶器官毒性-反复接触，类别2；危害水生环境-急性毒性，类别1；危害水生环境-慢性毒性，类别1。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4920, 5700, '国内法规：危险化学品安全管理条例（国务院令第591号），危险化学品目录（2015版）。工作场所安全使用化学品规定（〔1996〕劳部发423号），危险化学品安全管理条例实施细则（化劳发〔1992〕677号），工作场所职业病危害警示标识（GBZ 158-2003），常用危险化学品的分类及标志（GB 13690-2009），危险货物运输包装通用技术条件（GB 12463-2009），危险货物分类和品名编号（GB 6944-2012），危险货物品名表（GB 12268-2012），危险货物运输包装类别划分方法（GB/T 15098-2008）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
