INSERT INTO `msds_regulatory` VALUES (4924, 5704, '国内法规：《危险化学品安全管理条例》（国务院令第591号），针对危险化学品的生产、储存、使用、经营和运输等方面的安全管理；《易制毒化学品管理条例》（国务院令第445号），针对易制毒化学品的分类和管理；《工作场所安全使用化学品规定》（劳部发[1996]423号），规定了工作场所化学品的安全使用要求；《危险化学品目录》（2015版），列出了危险化学品的分类和目录。国际法规：欧盟REACH法规（EC No 1907/2006），关于化学品注册、评估、许可和限制；欧盟CLP法规（EC No 1272/2008），关于化学品分类、标签和包装；美国OSHA危害传递标准（29 CFR 1910.1200），规定了危害传递的要求；联合国GHS（全球化学品统一分类和标签制度），提供了全球统一的化学品分类和标签标准。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4925, 5705, '国内法规：《危险化学品安全管理条例》（国务院令第591号），针对危险化学品的生产、储存、使用、经营和运输等方面的安全管理；《易制毒化学品管理条例》（国务院令第445号），针对易制毒化学品的分类和管理；《工作场所安全使用化学品规定》（劳部发[1996]423号），规定了工作场所化学品的安全使用要求；《危险化学品目录》（2015版），列出了危险化学品的分类和目录。国际法规：欧盟REACH法规（EC No 1907/2006），关于化学品注册、评估、许可和限制；欧盟CLP法规（EC No 1272/2008），关于化学品分类、标签和包装；美国OSHA危害传递标准（29 CFR 1910.1200），规定了危害传递的要求；联合国GHS（全球化学品统一分类和标签制度），提供了全球统一的化学品分类和标签标准。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
