INSERT INTO `msds_regulatory` VALUES (4946, 5731, '国内法规：危险化学品安全管理条例（国务院令第591号）；工作场所安全使用化学品规定（劳部发[1996]423号）；危险化学品目录（2015版）；易制毒化学品管理条例；国际法规：联合国关于危险货物运输的建议书（TDG）；全球化学品统一分类和标签制度（GHS）', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4947, 5732, '国内化学品管理法规：《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录（2015版）》、《工作场所安全使用化学品规定》（[1996]劳部发423号）。国际法规：IMDG Code、ICAO TI、IATA-DGR。GHS危险性分类：第3.3类高闪点易燃液体、皮肤腐蚀/刺激类别2、严重眼损伤/眼刺激类别2A、特异性靶器官毒性-反复接触类别2、致癌性类别2。Hazard Statements: H226 易燃液体和蒸气。H315 造成皮肤刺激。H319 造成严重眼刺激。H351 可能致癌。Precautionary Statements: P210 远离热源/火花/明火/热表面。禁止吸烟。P233 保持容器密闭。P240 容器和接收设备接地/等势连接。P241 使用防爆的电气/通风/照明设备。P242 只能使用不产生火花的工具。P261 避免吸入粉尘/烟/气体/烟雾/蒸气/喷雾。P280 戴防护手套/穿防护服/戴护目镜/戴面罩。P305+P351+P338 如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。P403+P235 存放在通风良好的地方。保持低温。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4948, 5733, '国内化学品管理法规：危险化学品安全管理条例、易制毒化学品管理条例、工作场所安全使用化学品规定、危险化学品登记管理办法。国际法规：联合国关于危险货物运输的建议书（橙皮书）、国际海运危险货物规则（IMDG Code）、国际空运危险货物规则（IATA-DGR）。GHS危险性分类：易燃液体类别1、皮肤腐蚀/刺激类别2、严重眼损伤/眼刺激类别2A、特异性靶器官毒性-反复接触类别3。Hazard Statements: H225 高度易燃液体和蒸气。H315 造成皮肤刺激。H319 造成严重眼刺激。H336 可能引起嗜睡或头晕。Precautionary Statements: P210 远离热源/火花/明火/热表面。禁止吸烟。P233 保持容器密闭。P240 容器和接收设备接地/等势连接。P241 使用防爆的电气/通风/照明设备。P242 只能使用不产生火花的工具。P261 避免吸入粉尘/烟/气体/烟雾/蒸气/喷雾。P280 戴防护手套/穿防护服/戴护目镜/戴面罩。P305+P351+P338 如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。P403+P235 存放在通风良好的地方。保持低温。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4949, 5734, '《危险化学品安全管理条例》、《易制毒化学品管理条例》、《危险货物分类和品名编号》（GB6944）、《危险货物品名表》（GB12268）等法规', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4950, 5735, '《危险化学品安全管理条例》、《易制毒化学品管理条例》、《危险货物分类和品名编号》（GB6944）、《危险货物品名表》（GB12268）等法规', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4951, 5736, '国内化学品管理法规：危险化学品安全管理条例、易制毒化学品管理条例、工作场所安全使用化学品规定、危险化学品登记管理办法。国际法规：联合国关于危险货物运输的建议书（橙皮书）、国际海运危险货物规则（IMDG Code）、国际空运危险货物规则（IATA-DGR）。GHS危险性分类：急性毒性-经口，类别3；急性毒性-经皮，类别3；急性毒性-吸入，类别3；特异性靶器官毒性-反复接触类别3。Hazard Statements: H311 皮肤接触会中毒。H331 吸入会中毒。H301 吞咽会中毒。H335 可能引起呼吸道刺激。Precautionary Statements: P260 不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。P264 作业后彻底清洗。P270 禁止本产品使用时进食、饮水或吸烟。P280 戴防护手套/穿防护服/戴护目镜/戴面罩。P301+P310 如误吞咽：立即呼叫中毒控制中心或医生。P302+P352 如皮肤沾染：用大量肥皂和水清洗。P304+P340 如误吸入：将人转移到空气新鲜处，保持呼吸舒适体位。P312 如感觉不适，呼叫中毒控制中心或医生。P321 具体治疗（见本标签上的急救说明）。P361+P364 如衣物沾染：立即脱掉所有沾染的衣服。P403+P235 存放在通风良好的地方。保持低温。P501 按当地法规处置内装物/容器。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4952, 5737, '国内化学品管理法规：《危险化学品安全管理条例》（国务院令第591号）、《危险化学品目录（2015版）》、《工作场所安全使用化学品规定》（[1996]劳部发423号）。国际法规：IMDG Code、ICAO TI、IATA-DGR。GHS危险性分类：第3.2类中闪点易燃液体。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4953, 5738, '危险化学品安全管理条例（国务院令第591号），工作场所安全使用化学品规定（〔1996〕劳部发423号）等法规，针对化学危险品的安全使用、生产、储存、运输、装卸等方面均作了相应规定。GHS危险性分类：易燃液体（类别3）；皮肤刺激（类别2）；眼睛刺激（类别2A）；特异性靶器官系统毒性（一次接触）（类别3）。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
