INSERT INTO `msds_regulatory` VALUES (4965, 5750, '国内化学品管理法规：危险化学品安全管理条例、易制毒化学品管理条例、工作场所安全使用化学品规定、危险化学品登记管理办法。国际法规：联合国关于危险货物运输的建议书（橙皮书）、国际海运危险货物规则（IMDG Code）、国际空运危险货物规则（IATA-DGR）。GHS危险性分类：易燃气体类别1。Hazard Statements: H220 极易燃气体。Precautionary Statements: P210 远离热源/火花/明火/热表面。禁止吸烟。P280 戴防护手套/穿防护服/戴护目镜/戴面罩。P403+P235 存放在通风良好的地方。保持低温。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4966, 5751, '危险化学品安全管理条例（国务院令第591号），工作场所安全使用化学品规定（〔1996〕劳部发423号）等法规，针对化学危险品的安全使用、生产、储存、运输、装卸等方面均作了相应规定。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4967, 5752, '危险化学品安全管理条例（国务院令第591号），工作场所安全使用化学品规定（〔1996〕劳部发423号）等法规，针对化学危险品的安全使用、生产、储存、运输、装卸等方面均作了相应规定。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4968, 5753, '国内化学品管理法规：《危险化学品安全管理条例》（国务院令第591号）、《易制毒化学品管理条例》、《危险货物分类和品名编号》（GB6944）、《危险货物品名表》（GB12268）、《危险化学品目录》、《化学品安全技术说明书内容和项目顺序》（GB/T 16483-2008）、《化学品分类和危险性公示 通则》（GB13690）。国际法规：联合国《关于危险货物运输的建议书》（TDG）、《全球化学品统一分类和标签制度》（GHS）。GHS危险性分类：皮肤腐蚀/刺激类别2、严重眼损伤/眼刺激类别2A、特异性靶器官毒性-反复接触类别3、呼吸道致敏类别1、皮肤致敏类别1。Hazard Statements: H315 造成皮肤刺激。H317 可能导致皮肤过敏反应。H319 造成严重眼刺激。H335 可能引起呼吸道刺激。Precautionary Statements: P201 使用前取得特别说明。P260 不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。P261 避免吸入粉尘/烟/气体/烟雾/蒸气/喷雾。P264 作业后彻底清洗。P272 禁止将受污染的工作服带出工作场所。P280 戴防护手套/穿防护服/戴护目镜/戴面罩。P284 戴呼吸防护装置。P302+P352 如皮肤沾染：用大量肥皂和水清洗。P305+P351+P338 如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。P321 具体治疗（见本标签上的急救说明）。P333+P313 如发生皮肤刺激或皮疹：求医/就诊。P362+P364 脱掉沾染的衣服，清洗后方可重新使用。P403+P235 存放在通风良好的地方。P405 存放时加锁。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4969, 5754, '国内化学品管理法规：危险化学品安全管理条例、易制毒化学品管理条例、工作场所安全使用化学品规定、危险化学品登记管理办法。国际法规：联合国关于危险货物运输的建议书（橙皮书）、国际海运危险货物规则（IMDG Code）、国际空运危险货物规则（IATA-DGR）。GHS危险性分类：易燃液体类别2、皮肤腐蚀/刺激类别2、严重眼损伤/眼刺激类别2A。Hazard Statements: H225 高度易燃液体和蒸气。H315 造成皮肤刺激。H319 造成严重眼刺激。Precautionary Statements: P210 远离热源/火花/明火/热表面。禁止吸烟。P233 保持容器密闭。P240 容器和接收设备接地/等势连接。P241 使用防爆的电气/通风/照明设备。P242 只能使用不产生火花的工具。P261 避免吸入粉尘/烟/气体/烟雾/蒸气/喷雾。P280 戴防护手套/穿防护服/戴护目镜/戴面罩。P305+P351+P338 如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。P403+P235 存放在通风良好的地方。保持低温。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_regulatory` VALUES (4970, 5755, '《危险化学品安全管理条例》、《危险货物分类和品名编号》（GB6944）、《危险货物品名表》（GB12268）等法规', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
