INSERT INTO `msds_regulatory` VALUES (5000, 5785, '国内化学品管理法规：危险化学品安全管理条例、易制毒化学品管理条例、工作场所安全使用化学品规定、危险化学品登记管理办法。国际法规：联合国关于危险货物运输的建议书（橙皮书）、国际海运危险货物规则（IMDG Code）、国际空运危险货物规则（IATA-DGR）。GHS危险性分类：易燃液体类别2、皮肤腐蚀/刺激类别1B、严重眼损伤/眼刺激类别1、特异性靶器官毒性-一次接触类别3。Hazard Statements: H225 高度易燃液体和蒸气。H314 造成严重皮肤灼伤和眼损伤。H319 造成严重眼刺激。H335 可能引起呼吸道刺激。Precautionary Statements: P210 远离热源/火花/明火/热表面。禁止吸烟。P233 保持容器密闭。P240 容器和接收设备接地/等势连接。P241 使用防爆的电气/通风/照明设备。P242 只能使用不产生火花的工具。P260 不要吸入粉尘/烟/气体/烟雾/蒸气/喷雾。P264 作业后彻底清洗。P280 戴防护手套/穿防护服/戴护目镜/戴面罩。P305+P351+P338 如进入眼睛：用水小心冲洗几分钟。如戴隐形眼镜并可方便地取出，取出隐形眼镜。继续冲洗。P310 立即呼叫中毒控制中心或医生。P403+P235 存放在通风良好的地方。保持低温。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
