INSERT INTO `msds_regulatory` VALUES (5065, 5852, '危险化学品目录（2015版）序号：2806。该物质属于危险化学品，受《危险化学品安全管理条例》等法律法规监管。运输分类：UN 1479，氧化剂，包装类别II。GHS分类：氧化性固体-类别2；皮肤腐蚀/刺激-类别2；严重眼损伤/眼刺激-类别2A。', NULL, NULL, 0, 0, NULL, 0, NULL, NULL, NULL, '', NULL, '', NULL);
