INSERT INTO `msds_stability_reactivity` VALUES (2887, 3021, '稳定', NULL, '强氧化剂、强酸、强碱、潮湿空气。', '避免接触强氧化剂、强酸、强碱、潮湿空气。避免受热分解。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳、氯化氢、氧化硫等有毒气体。', NULL, NULL, '2026-03-06 14:29:27', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2888, 3022, '稳定', NULL, '强氧化剂、强碱。', '避免接触明火、高热。避免与强氧化剂、强碱接触。避免受热分解。', NULL, '不能出现', NULL, '受热分解产生有毒的氮氧化物、氧化硫烟雾和氰化物。', NULL, NULL, '2026-03-06 14:29:27', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2889, 3023, '稳定', NULL, '强氧化剂、强酸。', '避免接触明火、高热。避免与强氧化剂、强酸接触。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳、氯化氢等有毒气体。', NULL, NULL, '2026-03-06 14:29:28', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2890, 3024, '稳定', NULL, '强氧化剂。', '避免接触明火、高热。避免与强氧化剂接触。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳、氯化氢等有毒气体。', NULL, NULL, '2026-03-06 14:29:28', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2891, 3025, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强碱。与胆碱酯酶抑制剂（如有机磷农药）同时使用会增强毒性。', '避免接触明火、高热。避免与强氧化剂、强碱接触。避免受热分解。', NULL, '不能出现', NULL, '受热分解产生氯化氢、氮氧化物、一氧化碳、二氧化碳等有毒气体。', NULL, NULL, '2026-03-06 14:29:28', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2892, 3026, '稳定', NULL, '强氧化剂。', '避免接触明火、高热。避免与强氧化剂接触。避免受热分解。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳、氧化氮、氧化磷等有毒气体。', NULL, NULL, '2026-03-06 14:29:29', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2893, 3027, '稳定', NULL, '强氧化剂、强碱。', '光照。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳、氮氧化物、氯化氢、氰化物等有毒气体。', NULL, NULL, '2026-03-06 14:29:29', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2894, 3028, '稳定', NULL, '强氧化剂、水、强碱。', '避免接触明火、高热。避免与强氧化剂、水、强碱接触。避免受热分解。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、氧化硫、氯化氢、氧化磷等有毒气体。遇水分解产生氯化氢和磷酸。', NULL, NULL, '2026-03-06 14:29:30', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2895, 3029, '在正确的使用和存储条件下是稳定的。', NULL, '还原剂、促进剂、强酸、强碱、金属粉末、胺类、硫化物等。', '避免接触明火、高热、摩擦、震动、撞击。避免与还原剂、促进剂、强酸、强碱接触。避免受热分解。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳、有机过氧化物分解产物等。可能发生爆炸性分解。', NULL, NULL, '2026-03-06 14:29:30', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2896, 3030, '在正确的使用和存储条件下是稳定的。', NULL, '还原剂、促进剂、强酸、强碱、金属粉末、胺类、硫化物等。', '避免接触明火、高热、摩擦、震动、撞击。避免与还原剂、促进剂、强酸、强碱接触。避免受热分解。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳、有机过氧化物分解产物等。可能发生爆炸性分解。', NULL, NULL, '2026-03-06 14:29:30', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2897, 3031, '稳定', NULL, '强氧化剂。', '高温、火焰、静电火花、阳光暴晒以及与强氧化剂接触。', NULL, '不能出现', NULL, '受热分解产生氟化氢、一氧化碳、二氧化碳以及光气等有毒烟气。', NULL, NULL, '2026-03-06 14:29:30', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2898, 3032, '稳定', NULL, '氧化剂、碱类。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:29:31', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2899, 3033, '稳定', NULL, '强氧化剂、强酸。', '避免接触明火、高热。避免与强氧化剂、强酸、强碱接触。避免粉尘与空气形成爆炸性混合物。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳等有毒气体。', NULL, NULL, '2026-03-06 14:29:31', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2900, 3034, '在正确的使用和存储条件下是稳定的。', NULL, '强氧化剂、强碱、强还原剂。', '避免接触明火、高热。避免与强氧化剂、强碱、强还原剂接触。避免受热分解。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳、氟化氢、氧化硫等有毒气体。', NULL, NULL, '2026-03-06 14:29:32', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2901, 3035, '稳定', NULL, '强氧化剂、强碱、钾、钠。', '避免接触明火、高热。避免光照。避免与强氧化剂、强碱、钾、钠接触。', NULL, '不能发生', NULL, '受热分解产生一氧化碳、二氧化碳、氯化氢。在潮湿空气中，特别在日光照射下，可能释放出腐蚀性很强的氯化氢烟雾。', NULL, NULL, '2026-03-06 14:29:32', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2902, 3036, '稳定', NULL, '活性金属粉末、铝、镁、锌、钾、钠。', '高温、火焰、强紫外线、静电火花以及与活性金属接触。', NULL, '不能出现', NULL, '受热或燃烧产生氯化氢、氟化氢、一氧化碳、二氧化碳及光气。', NULL, NULL, '2026-03-06 14:29:32', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2903, 3037, '在常温常压下稳定，但在高温下可分解', NULL, '强氧化剂、强酸、强碱、碱金属、卤素化合物。', '受热、光照、与强氧化剂、强酸、强碱、碱金属接触。避免接触空气，防止氧化。', NULL, '不能发生', NULL, '受热分解产生一氧化碳、二氧化碳、氧化硫等有毒气体，包括有毒的硫化物气体。可能产生硫化氢等剧毒气体。', NULL, NULL, '2026-03-06 14:29:33', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2904, 3038, '在正确的使用和存储条件下是稳定的。', NULL, '还原剂、促进剂、强酸、强碱、金属粉末、胺类、硫化物等。', '避免接触明火、高热、摩擦、震动、撞击。避免与还原剂、促进剂、强酸、强碱接触。避免受热分解。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳、有机过氧化物分解产物等。可能发生爆炸性分解。', NULL, NULL, '2026-03-06 14:29:33', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2905, 3039, '在正确的使用和存储条件下是稳定的', NULL, '还原剂、促进剂、强酸、强碱、金属粉末、胺类、硫化物等。', '避免接触明火、高热、摩擦、震动、撞击。避免与还原剂、促进剂、强酸、强碱接触。避免受热分解。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳、有机过氧化物分解产物等。可能发生爆炸性分解。', NULL, NULL, '2026-03-06 14:29:33', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2906, 3040, '稳定', NULL, '强氧化剂。', '高温、光照、火花。', NULL, '不能出现', NULL, '受热分解产生氯化氢、一氧化碳、二氧化碳。', NULL, NULL, '2026-03-06 14:29:34', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2907, 3041, '稳定', NULL, '强氧化剂、强酸。', '避免接触明火、高热。避免与强氧化剂、强酸接触。避免受热分解。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳等有毒气体。', NULL, NULL, '2026-03-06 14:29:34', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2908, 3042, '稳定', NULL, '强氧化剂、强酸。', '高温、明火、静电火花、与氧化剂接触。避免受热分解。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳等有毒气体。', NULL, NULL, '2026-03-06 14:29:34', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2909, 3043, '在正确的使用和存储条件下是稳定的。', NULL, '还原剂、促进剂、强酸、强碱、金属粉末、胺类、硫化物等。', '避免接触明火、高热、摩擦、震动、撞击。避免与还原剂、促进剂、强酸、强碱接触。避免受热分解。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳、有机过氧化物分解产物等。可能发生爆炸性分解。', NULL, NULL, '2026-03-06 14:29:34', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2910, 3044, '在正确的使用和存储条件下是稳定的。', NULL, '还原剂、促进剂、强酸、强碱、金属粉末、胺类、硫化物等。', '避免接触明火、高热、摩擦、震动、撞击。避免与还原剂、促进剂、强酸、强碱接触。避免受热分解。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳、有机过氧化物分解产物等。可能发生爆炸性分解。', NULL, NULL, '2026-03-06 14:29:36', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2911, 3045, '在正常储存和使用条件下稳定。受热、摩擦、震动、撞击时可能发生爆炸性分解反应。', NULL, '强氧化剂、强还原剂、强酸、强碱、金属粉末、促进剂等。', '受热、摩擦、震动、撞击、明火、火花、静电积聚。', NULL, '不会发生危险的聚合反应。', NULL, '一氧化碳、二氧化碳、有机过氧化物分解产物等有毒气体。', NULL, NULL, '2026-03-06 14:29:37', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2912, 3046, '稳定', NULL, '强氧化剂、强酸。', '避免接触明火、高热、摩擦、震动、撞击。避免与强氧化剂、强酸接触。避免受热分解。避免聚合反应。', NULL, '能发生聚合反应，放出大量热量而引起容器破裂和爆炸事故。需添加阻聚剂防止聚合。', NULL, '受热分解产生一氧化碳、二氧化碳、氟化氢等有毒气体。聚合反应可能产生大量热量。', NULL, NULL, '2026-03-06 14:29:37', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2913, 3047, '稳定', NULL, '强氧化剂、强酸、强碱、卤素。', '避免接触明火、高热。避免与强氧化剂、强酸、强碱、卤素接触。避免受热分解。', NULL, '不能发生', NULL, '受热分解产生一氧化碳、二氧化碳等有毒气体。', NULL, NULL, '2026-03-06 14:29:37', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2914, 3048, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强酸、强碱、卤素等。', '避免接触明火、高热、摩擦、震动、撞击。避免与强氧化剂、强酸、强碱接触。避免受热分解。', NULL, '不能发生', NULL, '受热分解产生一氧化碳、二氧化碳等有毒气体。与强氧化剂、强酸、强碱接触可发生剧烈反应。', NULL, NULL, '2026-03-06 14:29:38', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2915, 3049, '在正常储存和使用条件下稳定，但易被空气氧化，在光照和高温条件下会加速分解。', NULL, '强氧化剂（如过氧化物、高锰酸盐、氯酸盐等）、强酸、铜及其合金、铝及其合金、铁、铁盐、重金属盐类。', '避免接触明火、高热、强氧化剂、金属粉末。避免受热分解。避免光照和空气长时间接触。避免静电积聚。', NULL, '不能发生', NULL, '受热分解产生一氧化碳、二氧化碳、氮氧化物(NOx)、氨气等有毒气体。与氧化剂接触可能产生爆炸性反应。', NULL, NULL, '2026-03-06 14:29:38', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2916, 3050, '稳定', NULL, '强氧化剂、强酸。', '避免接触明火、高热。避免与强氧化剂、强酸接触。避免光照、接触空气，防止生成过氧化物。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳等有毒气体。接触空气或在光照条件下可生成具有潜在爆炸危险性的过氧化物。', NULL, NULL, '2026-03-06 14:29:38', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2917, 3051, '在正常储存和操作条件下稳定。受热、摩擦、撞击或接触催化剂可能引起分解。', NULL, '强氧化剂、强还原剂、酸类、碱类、金属催化剂、重金属离子、易燃物。', '避免受热、摩擦、撞击、阳光直射、接触火源。避免与不相容物质接触。避免静电积累。', NULL, '不能发生', NULL, '一氧化碳、二氧化碳、氧化氮、氯化氢、有机物分解产生的有毒气体、自由基。', NULL, NULL, '2026-03-06 14:29:38', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2918, 3052, '稳定', NULL, '强氧化剂、强碱。', '避免接触明火、高热。避免与强氧化剂、强碱接触。避免受热分解。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳、氯化氢等有毒的腐蚀性烟气。', NULL, NULL, '2026-03-06 14:29:39', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2919, 3053, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强碱、强还原剂、金属粉末等。', '受热、光照、与不相容物质接触。', NULL, '不能发生', NULL, '受高热分解放出有毒的气体（氯化氢、一氧化碳、二氧化碳）。与强氧化剂、强碱接触可发生剧烈反应。在火场中，受热的容器有爆炸危险。', NULL, NULL, '2026-03-06 14:29:39', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2920, 3054, '稳定，但在高温下可能分解。', NULL, '强氧化剂、强酸、强碱。', '高温、明火、静电。', NULL, '不会发生聚合反应。', NULL, '一氧化碳、二氧化碳、氯化氢、光气等有毒的腐蚀性烟气。', NULL, NULL, '2026-03-06 14:29:39', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2921, 3055, '稳定', NULL, '强氧化剂、酸类、碱类。', '受热、光照。', NULL, '能发生聚合反应，需添加阻聚剂防止聚合。', NULL, '受热分解产生一氧化碳、二氧化碳、氯化氢、光气。与氧化剂接触猛烈反应。', NULL, NULL, '2026-03-06 14:29:39', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2922, 3056, '在正确的使用和存储条件下是稳定的', NULL, '无资料', '不相容物质，热、火焰和火花', NULL, '无资料', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物', NULL, NULL, '2026-03-06 14:29:40', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2923, 3057, '在常温常压下稳定，但在高温下可分解', NULL, '强氧化剂、强酸、强碱、潮湿空气、水。', '受热、光照、与强氧化剂接触、接触潮湿空气。', NULL, '不能发生', NULL, '受高热分解放出有毒的气体（氯化氢、一氧化碳、二氧化碳等）。在火场中，受热的容器有爆炸危险。', NULL, NULL, '2026-03-06 14:29:40', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2924, 3058, '在常温常压下稳定，但在高温下可分解', NULL, '强氧化剂、强酸、强碱。', '受热、光照、与强氧化剂接触。', NULL, '不能发生', NULL, '受高热分解放出有毒的气体（氯化氢、一氧化碳、二氧化碳等）。在火场中，受热的容器有爆炸危险。', NULL, NULL, '2026-03-06 14:29:41', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2925, 3059, '在常温常压下稳定，但在高温下可分解', NULL, '强氧化剂、强酸、强碱。', '受热、光照、与强氧化剂接触。', NULL, '不能发生', NULL, '受高热分解放出有毒的气体（氯化氢、一氧化碳、二氧化碳等）。在火场中，受热的容器有爆炸危险。', NULL, NULL, '2026-03-06 14:29:41', '', NULL);
