INSERT INTO `msds_stability_reactivity` VALUES (2950, 3084, '在常温常压下稳定，但在高温下可分解', NULL, '强氧化剂、强酸、强碱、铝。', '受热、光照、与强氧化剂接触。', NULL, '不能发生', NULL, '受高热分解放出有毒的气体（氯化氢、一氧化碳、二氧化碳等）。在火场中，受热的容器有爆炸危险。', NULL, NULL, '2026-03-06 14:29:48', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2951, 3085, '稳定', NULL, '强氧化剂、酸类、碱类、铝。', '避免接触明火、高热。避免与强氧化剂、酸类、碱类、铝接触。避免受热分解。', NULL, '不能发生', NULL, '受热分解产生一氧化碳、二氧化碳、氯化氢、光气等有毒的腐蚀性气体。', NULL, NULL, '2026-03-06 14:29:48', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2952, 3086, '不稳定，在光照、空气中可能分解', NULL, '强氧化剂、强酸。', '光照、空气。', NULL, '能发生', NULL, '受热分解释出剧毒的光气和氯化氢气体。与氧化剂能发生强烈反应。与铜及其合金有可能生成具有爆炸性的氯乙炔。', NULL, NULL, '2026-03-06 14:29:49', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2953, 3087, '在正确的使用和存储条件下是稳定的', NULL, '无资料', '不相容物质，热、火焰和火花', NULL, '无资料', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物', NULL, NULL, '2026-03-06 14:29:49', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2954, 3088, '稳定', NULL, '强氧化剂、酸类、碱类。', '受热、光照。', NULL, '能发生聚合反应，需添加阻聚剂防止聚合。', NULL, '受热分解产生一氧化碳、二氧化碳、氯化氢、光气等有毒的腐蚀性气体。与氧化剂接触发生反应。', NULL, NULL, '2026-03-06 14:29:49', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2955, 3089, '稳定', NULL, '强氧化剂、强还原剂、强碱。', '避免接触明火、高热。避免与强氧化剂、强还原剂、强碱接触。避免震动、撞击和摩擦。', NULL, '不能发生', NULL, '受热分解产生有毒的氧化氮气体。与强氧化剂、强还原剂、强碱接触可发生剧烈反应或爆炸。', NULL, NULL, '2026-03-06 14:29:50', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2956, 3090, '稳定', NULL, '强氧化剂。', '受热、光照、与不相容物质接触。分解温度53℃。', NULL, '不能发生', NULL, '受高热分解放出有毒的气体（溴化氢、一氧化碳、二氧化碳）。与强氧化剂接触可发生剧烈反应。在火场中，受热的容器有爆炸危险。分解温度53℃。', NULL, NULL, '2026-03-06 14:29:50', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2957, 3091, '稳定', NULL, '强氧化剂。', '避免接触明火、高热。避免与强氧化剂接触。避免受热分解。', NULL, '不能发生', NULL, '受高热分解放出有毒的气体（溴化氢、一氧化碳、二氧化碳）。与强氧化剂接触可发生反应。在火场中，受热的容器有爆炸危险。', NULL, NULL, '2026-03-06 14:29:50', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2958, 3092, '在常温常压下稳定，但在高温下可分解，避免光照', NULL, '强碱、强氧化剂、强酸、镁。', '受热、光照、与强氧化剂、强碱接触。', NULL, '不能发生', NULL, '受高热分解放出有毒的气体（溴化氢、一氧化碳、二氧化碳等）。在火场中，受热的容器有爆炸危险。', NULL, NULL, '2026-03-06 14:29:51', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2959, 3093, '稳定', NULL, '碱金属、强氧化剂。', '光照。', NULL, '不能出现', NULL, '受热分解产生有毒的溴化物气体（如溴化氢）。与强氧化剂接触可发生化学反应。', NULL, NULL, '2026-03-06 14:29:51', '', NULL);
