INSERT INTO `msds_stability_reactivity` VALUES (2978, 3112, '在正确的使用和存储条件下是稳定的', NULL, '无资料', '不相容物质，热、火焰和火花', NULL, '无资料', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物', NULL, NULL, '2026-03-06 14:29:56', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2979, 3113, '稳定', NULL, '强氧化剂。', '避免接触明火、高热。避免与强氧化剂接触。避免受热分解。', NULL, '不能发生', NULL, '受热分解产生一氧化碳、二氧化碳、氟化氢等有毒气体。与强氧化剂发生反应，可引起燃烧。', NULL, NULL, '2026-03-06 14:29:56', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2980, 3114, '在正确的使用和存储条件下是稳定的', NULL, '无资料', '不相容物质，热、火焰和火花', NULL, '无资料', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物', NULL, NULL, '2026-03-06 14:29:56', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2981, 3115, '稳定', NULL, '强氧化剂、酸类、碱类。', '受热。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:29:56', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2982, 3116, '稳定', NULL, '强氧化剂。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:29:57', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2983, 3117, '稳定', NULL, '酸类、酰基氯、酸酐、二氧化碳、强氧化剂。', '无资料（建议开展稳定性测试，参考GB/T 21845-2008）', NULL, '不能出现', NULL, '无资料（建议开展热分解产物分析，参考GB/T 21847-2008）', NULL, NULL, '2026-03-06 14:29:57', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2984, 3118, '稳定', NULL, '强氧化剂。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:29:58', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2985, 3119, '在正确的使用和存储条件下是稳定的', NULL, '无资料', '不相容物质，热、火焰和火花', NULL, '无资料', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物', NULL, NULL, '2026-03-06 14:29:58', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2986, 3120, '稳定', NULL, '强氧化剂。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:29:59', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2987, 3121, '稳定', NULL, '强酸、强氧化剂、强还原剂、酰基氯、酸酐。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:30:00', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2988, 3122, '稳定', NULL, '强氧化剂、强酸、强碱', '光照、接触空气。', NULL, '能发生', NULL, '无资料', NULL, NULL, '2026-03-06 14:30:00', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2989, 3123, '稳定', NULL, '强氧化剂、铝。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:30:01', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2990, 3124, '稳定', NULL, '强氧化剂、强碱、还原剂。', '避免接触明火、高热、潮湿空气。避免与强氧化剂、强碱、还原剂接触。避免受热分解。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳、氯化物等有毒气体。与强氧化剂、强碱、还原剂接触可发生剧烈反应。', NULL, NULL, '2026-03-06 14:30:02', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2991, 3125, '稳定', NULL, '强氧化剂、酸类、碱类、铝。', '避免接触明火、高热。避免与强氧化剂、酸类、碱类、铝接触。避免受热分解。', NULL, '不能发生', NULL, '受热分解能放出剧毒的光气。与氧化剂能发生强烈反应。', NULL, NULL, '2026-03-06 14:30:02', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2992, 3126, '稳定', NULL, '强氧化剂、酸类。', '光照、空气。', NULL, '能发生', NULL, '受热分解产生一氧化碳、二氧化碳、氯化氢、光气等有毒的腐蚀性气体。与氧化剂接触发生反应。', NULL, NULL, '2026-03-06 14:30:02', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2993, 3127, '稳定', NULL, '强氧化剂、强还原剂、强碱。', '避免接触明火、高热。避免与强氧化剂、强还原剂、强碱接触。避免震动、撞击和摩擦。', NULL, '不能发生', NULL, '受热分解产生有毒的氧化氮气体。与强氧化剂、强还原剂、强碱接触可发生剧烈反应或爆炸。', NULL, NULL, '2026-03-06 14:30:03', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2994, 3128, '不稳定', NULL, '强氧化剂、强还原剂、强酸、强碱、胺类。', '受热、光照、摩擦、撞击、与不相容物质接触。胺类及三氯化铝、六甲基苯等均能引起燃烧爆炸。', NULL, '不能发生', NULL, '受高热分解放出有毒的气体（氮氧化物、一氧化碳、二氧化碳）。与强氧化剂、强还原剂、强酸、强碱、胺类接触可发生剧烈反应或爆炸。胺类及三氯化铝、六甲基苯等均能引起燃烧爆炸。在火场中，受热的容器有爆炸危险。燃烧分解时，放出有毒的氮氧化物气体。', NULL, NULL, '2026-03-06 14:30:03', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2995, 3129, '稳定', NULL, '酸类、强氧化剂。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:30:03', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2996, 3130, '稳定', NULL, '强氧化剂。', '避免接触明火、高热。避免与强氧化剂接触。避免受热分解。', NULL, '不能发生', NULL, '受热分解产生一氧化碳、二氧化碳等有毒气体。与强氧化剂发生反应，可引起燃烧。', NULL, NULL, '2026-03-06 14:30:03', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2997, 3131, '稳定', NULL, '强氧化剂。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:30:04', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2998, 3132, '稳定', NULL, '强氧化剂、酸类。', '受热、光照。', NULL, '能发生', NULL, '无资料', NULL, NULL, '2026-03-06 14:30:04', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (2999, 3133, '稳定', NULL, '强氧化剂、酸类。', '受热、光照。', NULL, '能发生', NULL, '无资料', NULL, NULL, '2026-03-06 14:30:04', '', NULL);
