INSERT INTO `msds_stability_reactivity` VALUES (3015, 3149, '稳定', NULL, '强氧化剂、强还原剂、强碱。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:30:09', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3016, 3150, '稳定', NULL, '强氧化剂、强还原剂、卤素。', '避免接触明火、高热。避免与强氧化剂、强还原剂、卤素接触。避免光照、接触空气，防止生成过氧化物。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳等有毒气体。接触空气或在光照条件下可生成具有潜在爆炸危险性的过氧化物。', NULL, NULL, '2026-03-06 14:30:09', '', NULL);
