INSERT INTO `msds_stability_reactivity` VALUES (3028, 3162, '在正确的使用和存储条件下是稳定的。', NULL, '无资料', '不相容物质，热、火焰和火花。', NULL, '无资料', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。', NULL, NULL, '2026-03-06 14:30:13', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3029, 3163, '稳定', NULL, '酸类、酰基氯、酸酐、强氧化剂。', '避免接触明火、高热。避免与酸类、酰基氯、酸酐、强氧化剂接触。避免受热分解。', NULL, '不能出现', NULL, '加热分解产生易燃的有毒气体（如氧化氮）。与强氧化剂接触可发生反应。', NULL, NULL, '2026-03-06 14:30:13', '', NULL);
