INSERT INTO `msds_stability_reactivity` VALUES (3031, 3165, '稳定', NULL, '强氧化剂。', '避免接触明火、高热。避免与强氧化剂接触。避免受热分解。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳等有毒气体。与强氧化剂接触可发生反应。', NULL, NULL, '2026-03-06 14:30:13', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3032, 3166, '稳定', NULL, '强氧化剂、强酸、强碱、水。', '接触潮气可分解。', NULL, '不能出现', NULL, '在潮湿空气中缓慢分解。受热分解产生一氧化碳、二氧化碳等有毒气体。与氧化剂混合能形成有爆炸性的混合物。', NULL, NULL, '2026-03-06 14:30:14', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3033, 3167, '稳定', NULL, '酸类、酸酐、酰基氯、强氧化剂、二氧化碳。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:30:14', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3034, 3168, '稳定', NULL, '强氧化剂、酸类、酸酐、酰基氯。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:30:14', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3035, 3169, '在正确的使用和存储条件下是稳定的', NULL, '无资料', '不相容物质，热、火焰和火花', NULL, '无资料', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物', NULL, NULL, '2026-03-06 14:30:14', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3036, 3170, '稳定', NULL, '强氧化剂、酸酐、酸类、卤素。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:30:16', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3037, 3171, '稳定', NULL, '强氧化剂。', '光照。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:30:16', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3038, 3172, '稳定', NULL, '强氧化剂、强碱。', '避免接触明火、高热。避免与强氧化剂、强碱接触。避免受热分解。避免光照。', NULL, '不能出现', NULL, '受高热分解产生有毒的碘化物气体（碘化氢、一氧化碳、二氧化碳等）。与强氧化剂、强碱接触可发生反应。在火场中，受热的容器有爆炸危险。', NULL, NULL, '2026-03-06 14:30:16', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3039, 3173, '稳定', NULL, '强氧化剂、强碱。', '避免接触明火、高热。避免与强氧化剂、强碱接触。避免受热分解。避免光照。', NULL, '不能出现', NULL, '受高热分解产生有毒的碘化物气体（碘化氢、一氧化碳、二氧化碳等）。与强氧化剂、强碱接触可发生反应。在火场中，受热的容器有爆炸危险。', NULL, NULL, '2026-03-06 14:30:16', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3040, 3174, '稳定', NULL, '强氧化剂、强碱。', '避免接触明火、高热。避免与强氧化剂、强碱接触。避免受热分解。避免光照。', NULL, '不能出现', NULL, '受高热分解产生有毒的碘化物气体（碘化氢、一氧化碳、二氧化碳等）。与强氧化剂、强碱接触可发生反应。在火场中，受热的容器有爆炸危险。', NULL, NULL, '2026-03-06 14:30:17', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3041, 3175, '稳定', NULL, '强氧化剂、卤素、氯代烃。', '无资料', NULL, '能发生', NULL, '无资料', NULL, NULL, '2026-03-06 14:30:17', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3042, 3176, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强还原剂、强酸、强碱。', '热、火焰和火花。', NULL, '无资料', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物', NULL, NULL, '2026-03-06 14:30:17', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3043, 3177, '在常温常压下稳定，但在高温下可分解。能发生聚合反应，需添加阻聚剂。', NULL, '强氧化剂、强酸、强碱。', '受热、光照、与强氧化剂、强酸接触。避免聚合反应。', NULL, '能发生聚合反应，需添加阻聚剂。若遇高热，可发生聚合反应，放出大量热量而引起容器破裂和爆炸事故。', NULL, '受高热分解放出有毒的气体（一氧化碳、二氧化碳等）。若遇高热，可发生聚合反应，放出大量热量而引起容器破裂和爆炸事故。与氧化剂接触猛烈反应。气体比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, '2026-03-06 14:30:17', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3044, 3178, '稳定', NULL, '酸类、酸酐、酰基氯、强氧化剂、二氧化碳。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:30:18', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3045, 3179, '稳定', NULL, '强氧化剂、强碱。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:30:19', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3046, 3180, '稳定', NULL, '强氧化剂。', '受热、光照。', NULL, '能发生', NULL, '无资料', NULL, NULL, '2026-03-06 14:30:19', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3047, 3181, '在常温常压下稳定，但在高温下可分解。能发生聚合反应，需添加阻聚剂。包装要求密封，不可与空气接触。', NULL, '强氧化剂、强酸、强碱。', '受热、光照、与强氧化剂、酸类接触。避免与空气接触，避免聚合反应。', NULL, '能发生聚合反应，需添加阻聚剂。若遇高热，可发生聚合反应，放出大量热量而引起容器破裂和爆炸事故。', NULL, '受高热分解放出有毒的气体（一氧化碳、二氧化碳等）。若遇高热，可发生聚合反应，放出大量热量而引起容器破裂和爆炸事故。', NULL, NULL, '2026-03-06 14:30:19', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3048, 3182, '在常温常压下稳定，但在高温下可分解', NULL, '强氧化剂、强酸、强碱。', '受热、光照、与强氧化剂接触。', NULL, '不能发生', NULL, '受高热分解放出有毒的气体（一氧化碳、二氧化碳等）。易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。在火场中，受热的容器有爆炸危险。', NULL, NULL, '2026-03-06 14:30:19', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3049, 3183, '稳定', NULL, '强氧化剂。', '受热、光照。', NULL, '能发生', NULL, '无资料', NULL, NULL, '2026-03-06 14:30:20', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3050, 3184, '在常温常压下稳定，但在高温下可分解。能发生聚合反应，需添加阻聚剂。包装要求密封，不可与空气接触。', NULL, '强氧化剂、强酸、强碱。', '受热、光照、与强氧化剂、酸类接触。避免聚合反应。', NULL, '能发生聚合反应，需添加阻聚剂。若遇高热，可发生聚合反应，放出大量热量而引起容器破裂和爆炸事故。', NULL, '受高热分解放出有毒的气体（一氧化碳、二氧化碳等）。若遇高热，可发生聚合反应，放出大量热量而引起容器破裂和爆炸事故。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, '2026-03-06 14:30:20', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3051, 3185, '在常温常压下稳定，但在高温下可分解。能发生聚合反应，需添加阻聚剂。', NULL, '强氧化剂、强酸、强碱。', '受热、光照、与强氧化剂接触。避免聚合反应。', NULL, '能发生聚合反应，需添加阻聚剂。', NULL, '受高热分解放出有毒的气体（一氧化碳、二氧化碳等）。其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, '2026-03-06 14:30:20', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3052, 3186, '在常温常压下稳定，但在高温下可分解', NULL, '强氧化剂、强酸、强碱。', '受热、光照、与强氧化剂接触。', NULL, '不能发生', NULL, '受高热分解放出有毒的气体（一氧化碳、二氧化碳等）。易燃，其蒸气与空气混合，能形成爆炸性混合物。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', NULL, NULL, '2026-03-06 14:30:20', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3053, 3187, '在常温常压下稳定，但在高温下可分解', NULL, '强氧化剂、强酸、强碱。', '受热、光照、与强氧化剂接触。', NULL, '不能发生', NULL, '受高热分解放出有毒的气体（一氧化碳、二氧化碳等）。易燃，其蒸气与空气混合，能形成爆炸性混合物。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解。', NULL, NULL, '2026-03-06 14:30:20', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3054, 3188, '稳定', NULL, '强氧化剂。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:30:22', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3055, 3189, '在常温常压下稳定，但在高温下可分解', NULL, '酸类、酰基氯、强氧化剂、酸酐、强碱。', '受热、光照、与强氧化剂、酸类、酰基氯、酸酐接触。', NULL, '不能发生', NULL, '受高热分解放出有毒的气体（一氧化碳、二氧化碳等）。遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, '2026-03-06 14:30:22', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3056, 3190, '在常温常压下稳定，但在高温下可分解', NULL, '强氧化剂、强酸、强碱。', '受热、光照、与强氧化剂、强酸接触。', NULL, '不能发生', NULL, '受高热分解，放出有毒的烟气（一氧化碳、二氧化碳、氮氧化物等）。遇明火、高热可燃。', NULL, NULL, '2026-03-06 14:30:22', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3057, 3191, '稳定', NULL, '强氧化剂、强酸。', '无资料', NULL, '能发生', NULL, '无资料', NULL, NULL, '2026-03-06 14:30:22', '', NULL);
