INSERT INTO `msds_stability_reactivity` VALUES (3059, 3193, '稳定', NULL, '强氧化剂、酸类。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:30:23', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3060, 3194, '稳定', NULL, '强氧化剂、镁铜及其合金。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:30:23', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3061, 3195, '在常温常压下稳定，但在高温下可分解，能发生聚合反应，需添加阻聚剂', NULL, '强酸、强碱、氨、胺类、铜、镁、铝和它们的合金、强氧化剂。', '受热、光照、与强氧化剂、强酸、强碱接触，避免聚合反应。', NULL, '能发生聚合反应，需添加阻聚剂防止聚合', NULL, '受高热分解放出有毒的气体（氯化氢、一氧化碳、二氧化碳等）。在火场中，受热的容器有爆炸危险。能发生聚合反应，放出大量热量，可能引起爆炸。', NULL, NULL, '2026-03-06 14:30:23', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3062, 3196, '在常温常压下稳定，但在高温下可分解，已知在150℃下受强烈震动能引起爆炸', NULL, '强氧化剂、强酸、强碱、强还原剂。', '受热、光照、与强氧化剂、强还原剂、强碱接触，避免强烈震动。', NULL, '不能发生', NULL, '受高热分解放出有毒的气体（氯化氢、一氧化碳、二氧化碳、氮氧化物等）。已知在150℃下受强烈震动能引起爆炸。在火场中，受热的容器有爆炸危险。', NULL, NULL, '2026-03-06 14:30:24', '', NULL);
