INSERT INTO `msds_stability_reactivity` VALUES (3076, 3210, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强还原剂、强碱。', '热、火焰和火花。', NULL, '无资料', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物', NULL, NULL, '2026-03-06 14:30:28', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3077, 3211, '在常温常压下稳定，但在高温下可分解。能发生聚合反应，需添加阻聚剂。', NULL, '强氧化剂、强酸、强碱。', '受热、光照、与强氧化剂接触。避免聚合反应。', NULL, '能发生聚合反应，需添加阻聚剂。若遇高热，可发生聚合反应，放出大量热量而引起容器破裂和爆炸事故。', NULL, '受高热分解放出有毒的气体（一氧化碳、二氧化碳等）。若遇高热，可发生聚合反应，放出大量热量而引起容器破裂和爆炸事故。', NULL, NULL, '2026-03-06 14:30:29', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3078, 3212, '在常温常压下稳定，但在高温下可分解', NULL, '强酸、强氧化剂、酰基氯、酸酐、强碱。', '受热、光照、与强氧化剂、强酸、酰基氯、酸酐接触。', NULL, '不能发生', NULL, '受高热分解放出有毒的气体（一氧化碳、二氧化碳等）。与氧化剂接触猛烈反应。在火场中，受热的容器有爆炸危险。', NULL, NULL, '2026-03-06 14:30:29', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3079, 3213, '在常温常压下稳定，但在高温下可分解', NULL, '强碱、强氧化剂、碱金属、强酸。', '受热、光照、与强氧化剂、强碱、碱金属接触。', NULL, '不能发生', NULL, '受高热分解放出有毒的气体（一氧化碳、二氧化碳、硫化氢、氧化硫等）。', NULL, NULL, '2026-03-06 14:30:29', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3080, 3214, '在常温常压下稳定，但在高温下可分解。能发生聚合反应，需添加阻聚剂。包装要求密封，不可与空气接触。', NULL, '强氧化剂、强碱、强还原剂、氧、强酸。', '受热、光照、与强氧化剂、强碱、强还原剂、氧接触。避免与空气接触，避免聚合反应。', NULL, '能发生聚合反应，需添加阻聚剂。若遇高热，可发生聚合反应，放出大量热量而引起容器破裂和爆炸事故。', NULL, '受高热分解放出有毒的气体（一氧化碳、二氧化碳等）。若遇高热，可发生聚合反应，放出大量热量而引起容器破裂和爆炸事故。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, '2026-03-06 14:30:29', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3081, 3215, '稳定', NULL, '强氧化剂、酸类。', '受热、光照。', NULL, '能发生', NULL, '无资料', NULL, NULL, '2026-03-06 14:30:31', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3082, 3216, '在常温常压下稳定，但在高温下可分解。能发生聚合反应，需添加阻聚剂。包装要求密封，不可与空气接触。', NULL, '强氧化剂、强酸、强碱。', '受热、光照、与强氧化剂接触。避免聚合反应。', NULL, '能发生聚合反应，需添加阻聚剂。', NULL, '受高热分解放出有毒的气体（一氧化碳、二氧化碳等）。由于流动、搅拌等，可能产生静电。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, '2026-03-06 14:30:31', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3083, 3217, '不稳定，在常温常压下可分解。能发生聚合反应，需添加阻聚剂。通常商品加有阻聚剂。避光保存。', NULL, '强氧化剂、强酸、强碱、强还原剂。', '受热、光照、与强氧化剂、强酸、强碱、还原剂接触。避免聚合反应。', NULL, '能发生聚合反应，需添加阻聚剂。若遇高热，可发生聚合反应，出现大量放热现象，引起容器破裂或爆炸事故。', NULL, '受高热分解放出有毒的气体（一氧化碳、二氧化碳等）。光照可分解。若遇高热，可发生聚合反应，出现大量放热现象，引起容器破裂或爆炸事故。', NULL, NULL, '2026-03-06 14:30:31', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3084, 3218, '稳定', NULL, '强氧化剂、强碱。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:30:32', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3085, 3219, '稳定', NULL, '强氧化剂、强还原剂', '热、火焰、火花、明火、摩擦、撞击', NULL, '不会发生聚合反应', NULL, '受热分解产生一氧化碳、二氧化碳、氮氧化物等有毒气体', NULL, NULL, '2026-03-06 14:30:33', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3086, 3220, '稳定', NULL, '强氧化剂。', '受热、光照。', NULL, '能发生', NULL, '无资料', NULL, NULL, '2026-03-06 14:30:34', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3087, 3221, '在常温常压下稳定，但在高温下可分解。能发生聚合反应，需添加阻聚剂。', NULL, '强氧化剂、强酸、强碱。', '受热、光照、与强氧化剂、酸类接触。避免聚合反应。', NULL, '能发生聚合反应，需添加阻聚剂。', NULL, '受高热分解放出有毒的气体（一氧化碳、二氧化碳等）。冲击、流动、激荡后可因产生静电火花放电引起燃烧爆炸。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, '2026-03-06 14:30:34', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3088, 3222, '在正常储存和使用条件下稳定，但对光敏感，应避光保存。受热或燃烧时会分解。', NULL, '强氧化剂（如过氧化物、高锰酸盐等）、强还原剂、强酸（如硫酸、盐酸等）、强碱（如氢氧化钠、氢氧化钾等）、金属粉末、胺类化合物。', '避免受热、光照、摩擦、撞击。避免与不相容物质接触。避免产生粉尘。避免静电积聚。', NULL, '不会发生聚合反应', NULL, '分解时可能产生一氧化碳、二氧化碳、溴化氢、氮氧化物、光气等有毒有害气体。', NULL, NULL, '2026-03-06 14:30:34', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3089, 3223, '在常温常压下稳定，但遇光、热、空气可能缓慢分解。对湿气敏感，在潮湿环境中可能水解生成相应的醇和氢溴酸。对金属有腐蚀性，特别是对铜、铁等金属。', NULL, '强氧化剂（如高锰酸钾、过氧化氢、硝酸等）、强酸（如硫酸、盐酸等）、强碱（如氢氧化钠、氢氧化钾等）、强还原剂、金属粉末（如铝粉、镁粉等）、胺类化合物、醇类化合物（在酸性条件下）', '避免接触明火、高热、火花、静电积聚。避免光照，特别是紫外线照射。避免潮湿环境。避免与不相容物质接触。避免在密闭容器中加热。', NULL, '不会发生聚合反应', NULL, '受热分解产生溴化氢、一氧化碳、二氧化碳、溴代烃类化合物。燃烧时产生有毒的溴化氢气体和刺激性烟雾。与强氧化剂接触可能产生爆炸性混合物。', NULL, NULL, '2026-03-06 14:30:34', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3090, 3224, '在常温常压下稳定，但在高温下可分解，受热分解释出有毒的溴气体', NULL, '强氧化剂、强酸、强碱、镁。', '受热、光照、与强氧化剂、强碱接触。', NULL, '不能发生', NULL, '受高热分解放出有毒的气体（溴化氢、一氧化碳、二氧化碳等）。若遇高热，容器内压增大，有开裂和爆炸的危险。在火场中，受热的容器有爆炸危险。', NULL, NULL, '2026-03-06 14:30:36', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3091, 3225, '在常温常压下稳定，但在高温下可分解', NULL, '强氧化剂、强酸、强碱、钾、钠、镁等活性金属粉末。', '受热、光照、与强氧化剂、强碱、活性金属粉末接触。', NULL, '不能发生', NULL, '受高热分解产生有毒的溴化物气体（溴化氢、一氧化碳、二氧化碳等）。在火场中，受热的容器有爆炸危险。', NULL, NULL, '2026-03-06 14:30:36', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3092, 3226, '在常温常压下稳定，但在高温下可分解', NULL, '强氧化剂、强酸、强碱、钾、钠、镁等活性金属粉末。', '受热、光照、与强氧化剂、强碱、活性金属粉末接触。', NULL, '不能发生', NULL, '受高热分解产生有毒的溴化物气体（溴化氢、一氧化碳、二氧化碳等）。在火场中，受热的容器有爆炸危险。', NULL, NULL, '2026-03-06 14:30:36', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3093, 3227, '稳定', NULL, '强氧化剂、酸类、酸酐、酰基氯。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:30:36', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3094, 3228, '在正确的使用和存储条件下是稳定的', NULL, '无资料', '不相容物质，热、火焰和火花', NULL, '无资料', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物', NULL, NULL, '2026-03-06 14:30:36', '', NULL);
