INSERT INTO `msds_stability_reactivity` VALUES (3258, 3393, '稳定', NULL, '强氧化剂、酸类。', '避免接触明火、高热。避免与强氧化剂、酸类接触。避免光照。避免受热分解。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳、氧化氮等有毒气体。', NULL, NULL, '2026-03-06 14:31:47', '', NULL);
