INSERT INTO `msds_stability_reactivity` VALUES (3260, 3395, '常温常压下稳定。', NULL, '强氧化剂、强酸。', '避免接触明火、高热。避免与氧化剂、酸类接触。', NULL, '不能出现', NULL, '一氧化碳、二氧化碳、氮氧化物。', NULL, NULL, '2026-03-06 14:31:47', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3261, 3396, '稳定', NULL, '强氧化剂、酰基氯、酸酐、酸类。', '避免高温、明火、静电。', NULL, '不能出现', NULL, '一氧化碳、二氧化碳、氮氧化物。', NULL, NULL, '2026-03-06 14:31:47', '', NULL);
