INSERT INTO `msds_stability_reactivity` VALUES (3275, 3410, '稳定', NULL, '强氧化剂、强酸、强碱。', '光照、高温、明火。', NULL, '不能出现', NULL, '一氧化碳、二氧化碳、碘化氢。', NULL, NULL, '2026-03-06 14:31:55', '', NULL);
