INSERT INTO `msds_stability_reactivity` VALUES (3277, 3412, '稳定', NULL, '强氧化剂、强碱。', '光照。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:31:56', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3278, 3413, '稳定', NULL, '酸类、酰基氯、酸酐、强氧化剂、卤素。', '明火、高热、强氧化剂', NULL, '不能出现', NULL, '一氧化碳、二氧化碳', NULL, NULL, '2026-03-06 14:31:56', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3279, 3414, '稳定', NULL, '强氧化剂、强酸。', '在空气中缓慢分解', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:31:56', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3280, 3415, '稳定', NULL, '强氧化剂、酸类。', '受热、光照。', NULL, '能发生', NULL, '无资料', NULL, NULL, '2026-03-06 14:31:56', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3281, 3416, '稳定', NULL, '强氧化剂、碱类、强还原剂。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:31:56', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3282, 3417, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强酸、强碱', '不相容物质，热、火焰和火花', NULL, '不能出现', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物', NULL, NULL, '2026-03-06 14:31:58', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3283, 3418, '稳定', NULL, '强氧化剂、强酸。', '避免接触明火、高热。避免与强氧化剂、强酸接触。避免受热分解。避免聚合反应。', NULL, '能发生聚合反应，需添加阻聚剂。若遇高热，可发生聚合反应，放出大量热量而引起容器破裂和爆炸事故。', NULL, '受热分解产生一氧化碳、二氧化碳等有毒气体。能发生聚合反应，需添加阻聚剂防止聚合。', NULL, NULL, '2026-03-06 14:31:58', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3284, 3419, '稳定', NULL, '强酸、强氧化剂、强还原剂、酰基氯、酸酐。', '避免接触明火、高热。避免与强酸、强氧化剂、强还原剂、酰基氯、酸酐接触。避免受热分解。避免聚合反应。', NULL, '能发生聚合反应，需添加阻聚剂。若遇高热，可发生聚合反应，放出大量热量而引起容器破裂和爆炸事故。', NULL, '受热分解产生一氧化碳、二氧化碳等有毒气体。能发生聚合反应，需添加阻聚剂防止聚合。', NULL, NULL, '2026-03-06 14:31:58', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3285, 3420, '稳定', NULL, '强氧化剂、碱类、氧。', '受热、空气。', NULL, '能发生', NULL, '受热分解产生一氧化碳、二氧化碳等有毒气体。在火场高温下，能发生聚合放热，使容器破裂。', NULL, NULL, '2026-03-06 14:32:00', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3286, 3421, '在正确的使用和存储条件下是稳定的。', NULL, '强氧化剂、碱类、还原剂。', '不相容物质，热、火焰和火花。', NULL, '无资料', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。', NULL, NULL, '2026-03-06 14:32:00', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3287, 3422, '稳定', NULL, '强氧化剂、强酸、酰基氯、酸酐、卤素。', '接触空气。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:32:00', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3288, 3423, '稳定', NULL, '酰基氯、氧、酸类。', '接触空气。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:32:00', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3289, 3424, '稳定', NULL, '强氧化剂、强酸、酸酐、酰基氯。', '避免接触明火、高热、氧化剂。避免光照。', NULL, '不会发生聚合反应', NULL, '高温分解产生一氧化碳、二氧化碳、氮氧化物、氟化氢等有毒气体。', NULL, NULL, '2026-03-06 14:32:00', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3290, 3425, '稳定', NULL, '强氧化剂、强酸、强碱。', '避免接触明火、高热、静电。', NULL, '不能出现', NULL, '一氧化碳、二氧化碳、氟化氢。', NULL, NULL, '2026-03-06 14:32:02', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3291, 3426, '稳定', NULL, '强氧化剂、强还原剂、强碱。', '受热、光照、与强氧化剂接触。避免聚合反应。', NULL, '不能出现', NULL, '受高热分解放出有毒的气体（一氧化碳、二氧化碳等）。冲击、流动、激荡后可因产生静电火花放电引起燃烧爆炸。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, '2026-03-06 14:32:02', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3292, 3427, '稳定', NULL, '强氧化剂。', '受热、光照、与强氧化剂接触。避免聚合反应。', NULL, '能发生聚合反应，需添加阻聚剂。', NULL, '受高热分解放出有毒的气体（一氧化碳、二氧化碳等）。冲击、流动、激荡后可因产生静电火花放电引起燃烧爆炸。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, '2026-03-06 14:32:02', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3293, 3428, '在正确的使用和存储条件下是稳定的', NULL, '无资料', '不相容物质，热、火焰和火花', NULL, '无资料', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物', NULL, NULL, '2026-03-06 14:32:02', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3294, 3429, '稳定', NULL, '强氧化剂、强碱、强还原剂。', '避免接触明火、高热。避免与强氧化剂、强碱、强还原剂接触。避免受热分解。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳等有毒气体。与强氧化剂、强碱、强还原剂接触可发生反应。', NULL, NULL, '2026-03-06 14:32:03', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3295, 3430, '稳定', NULL, '强氧化剂、酸类、铜、银或其盐类', '避免接触热、火焰、火花、强氧化剂、酸类、铜、银及其盐类', NULL, '能发生聚合反应', NULL, '受热分解产生一氧化碳、二氧化碳等有毒气体', NULL, NULL, '2026-03-06 14:32:04', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3296, 3431, '稳定', NULL, '强氧化剂、强还原剂、强碱。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:32:04', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3297, 3432, '稳定', NULL, '强氧化剂、酸类。', '受热、光照、与强氧化剂、酸类接触。避免聚合反应。', NULL, '能发生聚合反应，需添加阻聚剂。若遇高热，可发生聚合反应，放出大量热量而引起容器破裂和爆炸事故。', NULL, '受高热分解放出有毒的气体（一氧化碳、二氧化碳等）。若遇高热，可发生聚合反应，放出大量热量而引起容器破裂和爆炸事故。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。', NULL, NULL, '2026-03-06 14:32:04', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3298, 3433, '稳定', NULL, '强氧化剂、铜和它们的合金、锌、酸类。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:32:04', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3299, 3434, '稳定', NULL, '强氧化剂、强碱。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:32:04', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3300, 3435, '稳定', NULL, '强氧化剂、碱类。', '光照、空气。', NULL, '不能出现', NULL, '受高热分解放出有毒的气体（一氧化碳、二氧化碳）。与强氧化剂、碱类接触可发生反应。', NULL, NULL, '2026-03-06 14:32:06', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3301, 3436, '稳定', NULL, '强氧化剂、酸类、卤素、酰基氯、碱金属。', '受热、光照。', NULL, '能发生', NULL, '受热分解产生一氧化碳、二氧化碳等有毒气体。与强氧化剂接触可发生反应。能发生聚合反应。', NULL, NULL, '2026-03-06 14:32:06', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3302, 3437, '稳定', NULL, '强酸、强氧化剂、酸酐、酰基氯。', '避免接触明火、高热。避免与强氧化剂、强酸接触。避免受热分解。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳等有毒气体。与强氧化剂接触可发生反应。', NULL, NULL, '2026-03-06 14:32:06', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3303, 3438, '稳定', NULL, '强氧化剂、碱、碱金属、强酸', '避免明火、高热、静电积聚。避免与氧化剂、碱类、碱金属接触', NULL, '不能出现', NULL, '一氧化碳、二氧化碳、硫化氢、氧化硫', NULL, NULL, '2026-03-06 14:32:06', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3304, 3439, '稳定，在正常储存条件下稳定。避免接触空气和水分。应避免光照和高温。', NULL, '强氧化剂（如高氯酸、硝酸、过氧化氢等）、强酸、强碱、卤素、金属粉末、金属盐类。', '避免接触明火、高热、氧化剂、强酸、强碱。避免静电积聚。避免光照和高温。', NULL, '无聚合危害', NULL, '高温分解产生一氧化碳、二氧化碳、醛类等有毒有害气体。', NULL, NULL, '2026-03-06 14:32:07', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3305, 3440, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强酸、强碱', '明火、高热、氧化剂', NULL, '不会发生聚合反应', NULL, '一氧化碳、二氧化碳、硫化物', NULL, NULL, '2026-03-06 14:32:08', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3306, 3441, '稳定', NULL, '强氧化剂、酸类。', '受热、光照。', NULL, '能发生', NULL, '受热分解产生一氧化碳、二氧化碳等有毒气体。与强氧化剂接触可发生反应。能发生聚合反应。', NULL, NULL, '2026-03-06 14:32:08', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3307, 3442, '稳定', NULL, '氧化剂、酸类、酰基氯。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:32:09', '', NULL);
