INSERT INTO `msds_stability_reactivity` VALUES (3309, 3444, '稳定', NULL, '酸类、酸酐、强氧化剂。', '避免接触明火、高热。避免与强氧化剂、酸类接触。避免受热分解。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳等有毒气体。与强氧化剂接触可发生反应。', NULL, NULL, '2026-03-06 14:32:10', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3310, 3445, '稳定', NULL, '强氧化剂。', '避免接触明火、高热、强氧化剂。避免受热，防止容器内压增大。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳等有毒气体。遇高热容器内压增大，有开裂和爆炸的危险。', NULL, NULL, '2026-03-06 14:32:11', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3311, 3446, '稳定', NULL, '强氧化剂、还原剂、碱类、碱金属、强酸', '避免明火、高热、静电积聚。避免与氧化剂、还原剂、碱类、碱金属接触', NULL, '不能出现', NULL, '一氧化碳、二氧化碳、硫化氢、氧化硫', NULL, NULL, '2026-03-06 14:32:11', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3312, 3447, '稳定', NULL, '强氧化剂。', '受热。', NULL, '能发生', NULL, '无资料', NULL, NULL, '2026-03-06 14:32:11', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3313, 3448, '稳定', NULL, '氧化剂、酸类、酸酐、酰基氯。', '明火、高热、氧化剂、强酸。', NULL, '不能出现', NULL, '一氧化碳、二氧化碳。', NULL, NULL, '2026-03-06 14:32:11', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3314, 3449, '稳定', NULL, '氧化剂、酸类。', '避免接触明火、高热。避免与强氧化剂、酸类接触。避免受热分解。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:32:11', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3315, 3450, '稳定', NULL, '强氧化剂、强碱、强酸。', '接触空气。', NULL, '能发生', NULL, '无资料', NULL, NULL, '2026-03-06 14:32:13', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3316, 3451, '稳定', NULL, '强氧化剂、强酸、强还原剂、酰基氯、酸酐。', '受热、接触空气。', NULL, '能发生', NULL, '一氧化碳、二氧化碳', NULL, NULL, '2026-03-06 14:32:13', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3317, 3452, '稳定', NULL, '氧化剂、酸类、酸酐、酰基氯。', '无资料', NULL, '不能出现', NULL, '一氧化碳、二氧化碳', NULL, NULL, '2026-03-06 14:32:13', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3318, 3453, '稳定', NULL, '强氧化剂、强酸、空气。', '接触空气。', NULL, '能发生', NULL, '一氧化碳、二氧化碳', NULL, NULL, '2026-03-06 14:32:13', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3319, 3454, '稳定', NULL, '强氧化剂、强酸。', '明火、高热', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:32:14', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3320, 3455, '稳定', NULL, '氧化剂、还原剂、强碱。', '避免受热、明火、高温。避免与氧化剂、还原剂、强碱接触。', NULL, '不能出现', NULL, '受热分解产生氮氧化物(NOx)、一氧化碳(CO)、二氧化碳(CO2)等有毒有害气体。', NULL, NULL, '2026-03-06 14:32:14', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3321, 3456, '稳定', NULL, '酸类、酰基氯、强氧化剂、强碱。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:32:14', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3322, 3457, '稳定', NULL, '强氧化剂、酸类、酰基氯、酸酐、氯仿。', '光照、空气。', NULL, '不能出现', NULL, '受高热分解放出有毒的气体（一氧化碳、二氧化碳、氧化氮）。与硝酸反应强烈。与强氧化剂、酸类接触可发生反应。', NULL, NULL, '2026-03-06 14:32:14', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3323, 3458, '稳定', NULL, '酸类、酰基氯、强氧化剂、氯仿。', '避免接触明火、高热、强氧化剂、酸类。避免产生静电火花。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳、氧化氮等有毒气体。', NULL, NULL, '2026-03-06 14:32:16', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3324, 3459, '稳定', NULL, '强氧化剂、强还原剂、强酸、强碱。', '受热、接触空气。', NULL, '能发生', NULL, '无资料', NULL, NULL, '2026-03-06 14:32:16', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3325, 3460, '稳定', NULL, '强氧化剂。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:32:16', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3326, 3461, '稳定', NULL, '氧化剂、强酸、强碱。', '避免接触明火、高热、强氧化剂、强酸、强碱。避免阳光直射，防止生成过氧化物。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳。在空气中或阳光照射下可生成过氧化物，具有潜在爆炸危险。', NULL, NULL, '2026-03-06 14:32:16', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3327, 3462, '稳定', NULL, '氧化剂。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:32:16', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3328, 3463, '稳定', NULL, '强氧化剂。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:32:18', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3329, 3464, '稳定', NULL, '强氧化剂、强酸、酰基氯。', '光照、接触空气。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:32:18', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3330, 3465, '稳定', NULL, '强氧化剂。', '避免接触明火、高热、强氧化剂。避免产生粉尘，防止粉尘与空气形成爆炸性混合物。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳等有毒气体。粉体与空气可形成爆炸性混合物，遇火星会发生爆炸。', NULL, NULL, '2026-03-06 14:32:18', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3331, 3466, '稳定', NULL, '强氧化剂、强酸、酸酐、二氧化碳。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:32:18', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3332, 3467, '稳定', NULL, '强氧化剂、潮湿空气。', '接触空气。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:32:19', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3333, 3468, '稳定', NULL, '强氧化剂、强还原剂、强碱。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:32:20', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3334, 3469, '稳定', NULL, '强氧化剂。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:32:20', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3335, 3470, '不稳定', NULL, '氧化剂、酸类、酸酐、酰基氯。', '避免接触明火、高热、氧化剂、酸类。避免光照。', NULL, '能发生', NULL, '受热分解产生一氧化碳、二氧化碳等有毒气体。', NULL, NULL, '2026-03-06 14:32:20', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3336, 3471, '稳定', NULL, '酰基氯、酸酐、氯仿、强酸、强氧化剂。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:32:20', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3337, 3472, '稳定', NULL, '酸类、碱类、强氧化剂。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:32:20', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3338, 3473, '稳定', NULL, '强氧化剂。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:32:22', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3339, 3474, '稳定', NULL, '强氧化剂、强还原剂、卤化物、氯苯。', '光照。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:32:22', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3340, 3475, '在常温下相对稳定，但在高温、阳光和氧气的作用下容易发生分解。', NULL, '氧化剂、还原剂、碱类、碱金属。', '避免接触高温、阳光直射、氧气、明火、热源。', NULL, '不能出现', NULL, '一氧化碳、二氧化碳、硫化氢、氧化硫。', NULL, NULL, '2026-03-06 14:32:22', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3341, 3476, '稳定', NULL, '强氧化剂、酸类。', '受热、光照。', NULL, '能发生', NULL, '一氧化碳、二氧化碳、氯化氢。', NULL, NULL, '2026-03-06 14:32:22', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3342, 3477, '稳定', NULL, '强氧化剂、酰基氯、酸酐、强碱。', '接触潮湿空气。', NULL, '不能出现', NULL, '一氧化碳、二氧化碳、氯化氢。', NULL, NULL, '2026-03-06 14:32:22', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3343, 3478, '在正确的使用和存储条件下是稳定的。', NULL, '强氧化剂、强碱、强酸、金属粉末、胺类。', '避免接触明火、高热、火花、静电放电。避免与不相容物质接触。', NULL, '不会发生危险的聚合反应。', NULL, '高温分解产生一氧化碳、二氧化碳、氯化氢、溴化氢等有毒有害气体。', NULL, NULL, '2026-03-06 14:32:24', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3344, 3479, '稳定', NULL, '强氧化剂、强酸。', '避免接触明火、高热。避免与氧化剂、酸类接触。', NULL, '不能出现', NULL, '受热分解产生氯化氢、一氧化碳、二氧化碳等有毒气体。', NULL, NULL, '2026-03-06 14:32:24', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3345, 3480, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强酸', '不相容物质，热、火焰和火花', NULL, '不会发生', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。受热分解产生有毒的氯化物、氮氧化物和一氧化碳气体。', NULL, NULL, '2026-03-06 14:32:24', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3346, 3481, '常温常压下相对稳定，但会受光、热和氧化等因素的影响', NULL, '强氧化剂、强酸、强碱', '避免受热、明火、高温、光照', NULL, '不会发生聚合反应', NULL, '受热分解产生氯化氢、氮氧化物、一氧化碳等有毒气体', NULL, NULL, '2026-03-06 14:32:24', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3347, 3482, '稳定', NULL, '强氧化剂、强碱。', '光照。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:32:24', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3348, 3483, '稳定', NULL, '酸类、酰基氯、酸酐、氯仿、强氧化剂。', '高温、明火、强氧化剂、强酸、强碱', NULL, '不能出现', NULL, '一氧化碳、二氧化碳、氮氧化物、氯化氢', NULL, NULL, '2026-03-06 14:32:26', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3349, 3484, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强碱、水、醇类、胺类', '不相容物质，热、火焰和火花', NULL, '不会发生聚合反应', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物', NULL, NULL, '2026-03-06 14:32:27', '', NULL);
