INSERT INTO `msds_stability_reactivity` VALUES (3351, 3486, '稳定', NULL, '强氧化剂、强酸', '避免明火、高热', NULL, '不能出现', NULL, '一氧化碳、二氧化碳、氧化氮、氯化氢', NULL, NULL, '2026-03-06 14:32:28', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3352, 3487, '稳定', NULL, '强氧化剂、强碱。', '避免接触明火、高热。避免与强氧化剂、强碱接触。避免受热分解。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳、氯化氢等有毒的腐蚀性气体。与强氧化剂、强碱接触可发生剧烈反应。', NULL, NULL, '2026-03-06 14:32:29', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3353, 3488, '稳定', NULL, '强氧化剂、强还原剂、强酸、强碱。', '避免接触明火、高热。避免与强氧化剂、强还原剂、强酸、强碱接触。避免受热分解。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳、氯化氢等有毒的腐蚀性气体。与强氧化剂、强还原剂、强酸、强碱接触可发生剧烈反应。', NULL, NULL, '2026-03-06 14:32:29', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3354, 3489, '稳定', NULL, '酸类、碱类、强氧化剂、强还原剂。', '避免接触明火、高热。避免与酸类、碱类、强氧化剂、强还原剂接触。避免受热分解。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳、氯化氢等有毒的腐蚀性气体。与酸类、碱类、强氧化剂、强还原剂接触可发生剧烈反应。', NULL, NULL, '2026-03-06 14:32:29', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3355, 3490, '在正确的使用和存储条件下是稳定的。', NULL, '强氧化剂、强酸、强碱', '不相容物质，热、火焰和火花。', NULL, '不会发生聚合反应', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。受热分解产生一氧化碳、二氧化碳、氯化氢等有毒气体。', NULL, NULL, '2026-03-06 14:32:29', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3356, 3491, '在正确的使用和存储条件下是稳定的。', NULL, '强氧化剂、强酸、强碱、金属粉末、胺类、醇类', '不相容物质，热、火焰和火花。', NULL, '不会发生危险的聚合反应', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。受热分解产生一氧化碳、二氧化碳、氯化氢等有毒气体。', NULL, NULL, '2026-03-06 14:32:31', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3357, 3492, '稳定', NULL, '强氧化剂、强碱。', '避免接触明火、高热。避免与强氧化剂、强碱接触。避免受热分解。', NULL, '不能出现', NULL, '受高热分解产生有毒的氯化物气体（如氯化氢）。与强氧化剂、强碱接触可发生反应。', NULL, NULL, '2026-03-06 14:32:31', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3358, 3493, '稳定', NULL, '强氧化剂、酸类、碱。', '无资料', NULL, '能发生', NULL, '无资料', NULL, NULL, '2026-03-06 14:32:31', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3359, 3494, '稳定', NULL, '强氧化剂、强碱。', '避免接触明火、高热。避免与强氧化剂、强碱接触。避免受热分解。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳、氯化氢等有毒的腐蚀性烟气。与氧化剂能发生强烈反应。', NULL, NULL, '2026-03-06 14:32:31', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3360, 3495, '稳定', NULL, '强氧化剂、强酸、强碱。', '明火、高热、阳光直射', NULL, '不能出现', NULL, '一氧化碳、二氧化碳、氯化氢', NULL, NULL, '2026-03-06 14:32:33', '', NULL);
