INSERT INTO `msds_stability_reactivity` VALUES (3362, 3497, '稳定', NULL, '强氧化剂、强碱。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:32:33', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3363, 3498, '稳定', NULL, '碱、强氧化剂。', '接触潮湿空气。', NULL, '不能出现', NULL, '受高热分解产生有毒的腐蚀性烟气（光气、氯化氢）。与强氧化剂、碱接触可发生反应。', NULL, NULL, '2026-03-06 14:32:33', '', NULL);
