INSERT INTO `msds_stability_reactivity` VALUES (3365, 3500, '稳定', NULL, '强氧化剂、酸类、酸酐。', '避免接触明火、高热。避免与强氧化剂、酸类、酸酐接触。避免受热分解。', NULL, '不能出现', NULL, '受高热分解放出有毒的气体（一氧化碳、二氧化碳、氧化氮）。与氧化剂可发生反应。', NULL, NULL, '2026-03-06 14:32:34', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3366, 3501, '在正常储存和操作条件下稳定。避免接触强氧化剂、强酸、强碱。受热或燃烧时可能分解产生有毒气体。', NULL, '强氧化剂（如高氯酸盐、高锰酸盐）、强酸（如硫酸、硝酸）、强碱（如氢氧化钠、氢氧化钾）、强还原剂、重金属盐类。', '避免接触明火、高热、火花、静电。避免与强氧化剂、强还原剂、强酸、强碱接触。避免受热分解。避免长时间暴露在阳光下。', NULL, '不会发生聚合反应', NULL, '受高热分解放出有毒的氰化氢气体、一氧化碳、二氧化碳、氮氧化物。与强氧化剂接触可能产生剧烈反应。', NULL, NULL, '2026-03-06 14:32:34', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3367, 3502, '稳定', NULL, '强氧化剂、强酸、强碱', '明火、高热', NULL, '不能出现', NULL, '一氧化碳、二氧化碳', NULL, NULL, '2026-03-06 14:32:34', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3368, 3503, '稳定', NULL, '强氧化剂、酸类、碱类。', '避免接触明火、高热。避免与强氧化剂、酸类、碱类接触。避免受热分解。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳等有毒气体。与强氧化剂接触可发生反应。', NULL, NULL, '2026-03-06 14:32:35', '', NULL);
