INSERT INTO `msds_stability_reactivity` VALUES (3379, 3514, '稳定', NULL, '强氧化剂、强酸。', '受热、光照、与强氧化剂、酸类接触。避免聚合反应。', NULL, '能发生聚合反应，需添加阻聚剂。', NULL, '受高热分解放出有毒的气体（一氧化碳、二氧化碳等）。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, '2026-03-06 14:32:40', '', NULL);
