INSERT INTO `msds_stability_reactivity` VALUES (3387, 3522, '稳定', NULL, '强氧化剂、强碱、水。', '接触潮湿空气。', NULL, '不能出现', NULL, '受热分解产生氯化氢、氮氧化物、一氧化碳、二氧化碳等有毒有害气体。遇水分解产生氯化氢和2-硝基苯甲酸。', NULL, NULL, '2026-03-06 14:32:42', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3388, 3523, '稳定', NULL, '强氧化剂、强酸、强还原剂。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:32:43', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3389, 3524, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强还原剂、强酸、强碱、重金属盐类', '不相容物质，热、火焰和火花，高温环境', NULL, '不会发生聚合反应', NULL, '受热分解时可能产生砷氧化物（如三氧化二砷）、氮氧化物、一氧化碳、二氧化碳等有毒有害气体。', NULL, NULL, '2026-03-06 14:32:43', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3390, 3525, '稳定', NULL, '强氧化剂、强还原剂、强酸、强碱。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:32:43', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3391, 3526, '稳定', NULL, '强氧化剂、强碱、强酸、胺类、铜。', '避免受热、明火、火花、静电放电。', NULL, '不能出现', NULL, '一氧化碳、二氧化碳、氮氧化物。', NULL, NULL, '2026-03-06 14:32:43', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3392, 3527, '稳定', NULL, '强氧化剂、强还原剂、强碱。', '避免受热、明火、火花。避免与强氧化剂、强还原剂、强碱接触。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳、氮氧化物、碘化氢等有毒气体。', NULL, NULL, '2026-03-06 14:32:43', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3393, 3528, '在正确的使用和存储条件下是稳定的', NULL, '无资料', '不相容物质，热、火焰和火花', NULL, '无资料', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物', NULL, NULL, '2026-03-06 14:32:45', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3394, 3529, '稳定', NULL, '强氧化剂、强碱。', '避免明火、高热', NULL, '不能出现', NULL, '一氧化碳、二氧化碳、氧化氮', NULL, NULL, '2026-03-06 14:32:45', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3395, 3530, '在常温常压下稳定', NULL, '强氧化剂、强还原剂、强碱', '避免接触明火、高热。避免与强氧化剂、强还原剂、强碱接触。避免受热分解。', NULL, '不会发生聚合反应', NULL, '受高热分解放出有毒的气体（一氧化碳、二氧化碳、氧化氮）', NULL, NULL, '2026-03-06 14:32:45', '', NULL);
