INSERT INTO `msds_stability_reactivity` VALUES (3397, 3532, '稳定', NULL, '强氧化剂、强碱、强还原剂。', '避免高温、明火、强氧化剂。', NULL, '不能出现', NULL, '受高热分解产生有毒的氮氧化物和氯化物气体。', NULL, NULL, '2026-03-06 14:32:46', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3398, 3533, '稳定', NULL, '强氧化剂、强还原剂、强碱。', '接触潮湿空气。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:32:47', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3399, 3534, '稳定', NULL, '强氧化剂、强还原剂。', '受热', NULL, '不能出现', NULL, '氮氧化物', NULL, NULL, '2026-03-06 14:32:47', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3400, 3535, '稳定', NULL, '强氧化剂、强还原剂、强碱。', '避免受热、明火、火花。避免与强氧化剂、强还原剂、强碱接触。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳、氮氧化物、溴化氢等有毒气体。', NULL, NULL, '2026-03-06 14:32:47', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3401, 3536, '无资料', NULL, '强氧化剂、酸类、铜、银或其盐类。', '无资料', NULL, '无资料', NULL, '无资料', NULL, NULL, '2026-03-06 14:32:47', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3402, 3537, '稳定', NULL, '强氧化剂、强还原剂、强碱。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:32:47', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3403, 3538, '稳定', NULL, '强氧化剂。', '受热、光照、与强氧化剂接触。避免聚合反应。', NULL, '能发生聚合反应，需添加阻聚剂。', NULL, '受高热分解放出有毒的气体（一氧化碳、二氧化碳等）。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃。若遇高热，容器内压增大，有开裂和爆炸的危险。', NULL, NULL, '2026-03-06 14:32:49', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3404, 3539, '稳定', NULL, '氧化剂、还原剂、酸类、碱类。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:32:50', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3405, 3540, '在正确的使用和存储条件下是稳定的', NULL, '无资料', '不相容物质，热、火焰和火花', NULL, '无资料', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物', NULL, NULL, '2026-03-06 14:32:51', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3406, 3541, '稳定', NULL, '强氧化剂、酸类、酸酐、酰基氯。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:32:51', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3407, 3542, '稳定', NULL, '酰基氯、酸酐、强氧化剂。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:32:51', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3408, 3543, '稳定', NULL, '强碱、氧化剂、水、醇类。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:32:53', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3409, 3544, '稳定', NULL, '碱、强还原剂、强氧化剂。', '受热', NULL, '不能出现', NULL, '分解温度：203°C，分解产物：溴化物气体', NULL, NULL, '2026-03-06 14:32:53', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3410, 3545, '稳定', NULL, '强氧化剂、强酸、强碱。', '避免接触明火、高热。避免与强氧化剂、强酸、强碱接触。避免受热分解。', NULL, '不能出现', NULL, '受高热分解产生有毒的溴化物气体（如溴化氢）。与强氧化剂、强酸、强碱接触可发生反应。', NULL, NULL, '2026-03-06 14:32:53', '', NULL);
