INSERT INTO `msds_stability_reactivity` VALUES (3429, 3564, '稳定', NULL, '强氧化剂、强酸。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:33:01', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3430, 3565, '在正确的使用和存储条件下是稳定的', NULL, '无资料', '不相容物质，热、火焰和火花', NULL, '无资料', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物', NULL, NULL, '2026-03-06 14:33:01', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3431, 3566, '在正确的使用和存储条件下相对稳定，但属于自反应物质B型，在常温下可能发生自反应分解。', NULL, '强氧化剂、强还原剂、强酸、强碱、金属粉末、有机物、胺类、醇类、酚类等不相容物质。', '避免受热、摩擦、撞击、火焰、火花、静电放电。避免与不相容物质接触。避免光照。避免高温环境。', NULL, '无聚合危害', NULL, '受热分解产生一氧化碳、二氧化碳、氮氧化物、氯化氢、硫氧化物、氯化氢气体等有毒有害气体。', NULL, NULL, '2026-03-06 14:33:01', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3432, 3567, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强酸、强碱', '不相容物质，热、火焰和火花', NULL, '无资料', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物', NULL, NULL, '2026-03-06 14:33:01', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3433, 3568, '在正确的使用和存储条件下是稳定的。该物质属于自反应物质和混合物b型，具有分解爆炸危险性。', NULL, '强氧化剂、强酸、强碱、金属粉末、有机胺类', '不相容物质，热、火焰、火花、摩擦、撞击、阳光直射', NULL, '无资料', NULL, '受热分解产生氮氧化物、硫氧化物、氯化氢等有毒气体', NULL, NULL, '2026-03-06 14:33:03', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3434, 3569, '稳定', NULL, '强氧化剂、强酸、强碱。', '避免光照、高温。光照可分解。', NULL, '不会发生聚合反应', NULL, '高温分解可能产生一氧化碳、二氧化碳、氮氧化物等有毒气体。', NULL, NULL, '2026-03-06 14:33:03', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3435, 3570, '在常温常压下稳定。避免受潮。', NULL, '强氧化剂、强碱、强酸。', '避免高温、明火、潮湿环境。避免与氧化剂接触。', NULL, '不能出现', NULL, '高温分解产生一氧化碳、二氧化碳、氮氧化物、氧化硫等有毒气体。', NULL, NULL, '2026-03-06 14:33:03', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3436, 3571, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强酸、强碱', '不相容物质，热、火焰和火花', NULL, '不会发生聚合反应', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。受热分解产生有毒的氮氧化物、一氧化碳、二氧化碳等气体。', NULL, NULL, '2026-03-06 14:33:03', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3437, 3572, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强酸、强碱', '不相容物质，热、火焰和火花', NULL, '不会发生危险的聚合反应', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。受热分解可能产生一氧化碳、二氧化碳、氮氧化物等有毒气体。', NULL, NULL, '2026-03-06 14:33:05', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3438, 3573, '在正确的使用和存储条件下是稳定的。避免受热、摩擦、撞击或接触污染。', NULL, '强氧化剂、强还原剂、强酸、强碱、胺类、金属粉末、硫、磷等', '不相容物质，热、火焰和火花，摩擦，撞击，污染', NULL, '无资料', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。受热分解可能产生有毒气体。', NULL, NULL, '2026-03-06 14:33:05', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3439, 3574, '稳定。在正常储存条件下稳定，但在空气中易氧化变色。（来源：化工百科、人人文库）', NULL, '强氧化剂、强酸。（来源：化工百科、原创力文档）', '明火、高热、强氧化剂、强酸。（来源：化工百科、原创力文档）', NULL, '不能出现', NULL, '受热分解放出有毒的氧化氮烟气。燃烧分解产物：一氧化碳、二氧化碳、氮氧化物、氯化氢。（来源：化工百科、原创力文档）', NULL, NULL, '2026-03-06 14:33:06', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3440, 3575, '稳定', NULL, '氧化剂、酸类、酸酐、酰基氯。', '明火、高热', NULL, '不能出现', NULL, '一氧化碳、二氧化碳、氮氧化物等有毒气体。', NULL, NULL, '2026-03-06 14:33:06', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3441, 3576, '在正常储存和使用条件下稳定，但对热、摩擦、撞击敏感。', NULL, '强氧化剂、强还原剂、胺类、金属粉末、酸类、碱类。', '受热、摩擦、撞击、光照。', NULL, '无资料', NULL, '一氧化碳、二氧化碳、醛类、酮类等有毒气体。', NULL, NULL, '2026-03-06 14:33:06', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3442, 3577, '在正确的使用和存储条件下是稳定的。', NULL, '强还原剂、强酸、强碱、有机物、易燃物', '不相容物质，热、火焰和火花。', NULL, '无资料', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。受热分解可能产生一氧化碳、二氧化碳等有害气体。', NULL, NULL, '2026-03-06 14:33:08', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3443, 3578, '在正确的使用和存储条件下是稳定的', NULL, '无资料', '不相容物质，热、火焰和火花', NULL, '无资料', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物', NULL, NULL, '2026-03-06 14:33:08', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3444, 3579, '在常温常压下稳定，不与强酸、强碱、强氧化剂发生反应。', NULL, '强氧化剂、强酸、强碱、卤素。', '高温、明火、火花、强氧化剂。', NULL, '不会发生聚合反应。', NULL, '高温燃烧或分解时可能产生一氧化碳、二氧化碳等有害气体。', NULL, NULL, '2026-03-06 14:33:08', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3445, 3580, '稳定', NULL, '强氧化剂、强酸、卤素。', '明火、高热', NULL, '不能出现', NULL, '一氧化碳、二氧化碳', NULL, NULL, '2026-03-06 14:33:09', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3446, 3581, '稳定', NULL, '酸类、强氧化剂。', '接触潮湿空气。', NULL, '能发生', NULL, '无资料', NULL, NULL, '2026-03-06 14:33:09', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3447, 3582, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强碱、酸酐、酰氯', '不相容物质，热、火焰和火花', NULL, '不会发生聚合反应', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。高温燃烧时产生一氧化碳、二氧化碳', NULL, NULL, '2026-03-06 14:33:09', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3448, 3583, '稳定', NULL, '氧化剂、酸类、酰基氯。', '光照。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:33:11', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3449, 3584, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强酸、强碱', '不相容物质，热、火焰和火花', NULL, '不会发生聚合反应', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。高温燃烧时产生一氧化碳、二氧化碳', NULL, NULL, '2026-03-06 14:33:11', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3450, 3585, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强酸、强碱、卤素（氟、氯、溴、碘）、臭氧、过氧化物等。避免与这些物质接触，否则可能发生剧烈反应。', '不相容物质、热、火焰、火花、静电积聚、明火、高热。避免在高温、明火或火源附近使用。', NULL, '不会发生危险的聚合反应', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。在高温或燃烧时，可能产生一氧化碳、二氧化碳等有害气体。', NULL, NULL, '2026-03-06 14:33:11', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3451, 3586, '稳定', NULL, '强氧化剂、强酸、强碱。', '避免接触高温、潮湿空气、明火。', NULL, '不能出现', NULL, '氰化物、氰化氢、氧化氮、一氧化碳、二氧化碳。', NULL, NULL, '2026-03-06 14:33:11', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3452, 3587, '稳定', NULL, '酸类、酰基氯、酸酐、强氧化剂。', '避免接触明火、高热。避免与酸类、酰基氯、酸酐、强氧化剂接触。避免受热分解。', NULL, '不能出现', NULL, '受高热分解产生一氧化碳、二氧化碳、氧化氮、氯化氢等有毒的腐蚀性气体。与强氧化剂可发生反应。', NULL, NULL, '2026-03-06 14:33:11', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3453, 3588, '稳定', NULL, '氧化剂、酸酐、酰基氯。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:33:13', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3454, 3589, '在正确的使用和存储条件下是稳定的。', NULL, '无资料', '不相容物质，热、火焰和火花。', NULL, '无资料', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。', NULL, NULL, '2026-03-06 14:33:13', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3455, 3590, '稳定', NULL, '氧化剂、碱、胺类、醇类。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:33:13', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3456, 3591, '稳定', NULL, '强氧化剂、强碱。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:33:13', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3457, 3592, '稳定', NULL, '强氧化剂、强还原剂、强碱。', '避免接触明火、高热。', NULL, '不会发生聚合反应', NULL, '一氧化碳、二氧化碳、氮氧化物、氯化氢。', NULL, NULL, '2026-03-06 14:33:14', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3458, 3593, '稳定', NULL, '强氧化剂、强酸。', '避免接触明火、高热。避免与强氧化剂、强酸接触。避免受热分解。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳等有毒气体。与强氧化剂、强酸接触可发生剧烈反应。', NULL, NULL, '2026-03-06 14:33:15', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3459, 3594, '稳定', NULL, '强氧化剂。', '避免接触明火、高热、氧化剂。避免受潮。', NULL, '不能出现', NULL, '高温分解产生一氧化碳、二氧化碳、苯、甲苯等有毒有害气体。', NULL, NULL, '2026-03-06 14:33:15', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3460, 3595, '稳定', NULL, '强氧化剂、酸类。', '避免明火、高热、强氧化剂。', NULL, '不能出现', NULL, '一氧化碳、二氧化碳、氮氧化物。', NULL, NULL, '2026-03-06 14:33:15', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3461, 3596, '在正确的使用和存储条件下是稳定的，但遇水分解', NULL, '强氧化剂、强碱、醇类、胺类、水、潮湿空气', '不相容物质，热、火焰、火花、潮湿环境', NULL, '不会发生聚合反应', NULL, '遇水分解产生氯化氢和3,5-二甲基苯甲酸；受热分解产生氯化氢、一氧化碳、二氧化碳等有毒气体', NULL, NULL, '2026-03-06 14:33:16', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3462, 3597, '稳定', NULL, '强氧化剂、酸类、酰基氯、酸酐、卤素', '在空气中可氧化。避免接触热、火焰和火花。', NULL, '不会发生危险的聚合反应', NULL, '受热分解产生有毒的氮氧化物、一氧化碳、二氧化碳等。', NULL, NULL, '2026-03-06 14:33:16', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3463, 3598, '稳定', NULL, '强氧化剂。', '避免明火、高热、静电。', NULL, '不会发生聚合反应', NULL, '一氧化碳、二氧化碳。', NULL, NULL, '2026-03-06 14:33:16', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3464, 3599, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强酸、酰氯、酸酐、重金属盐类', '不相容物质，热、火焰和火花', NULL, '不会发生聚合反应', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。高温分解产生氯化氢、氮氧化物、一氧化碳等有毒气体。', NULL, NULL, '2026-03-06 14:33:16', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3465, 3600, '稳定', NULL, '强氧化剂、强酸、酸酐、酰基氯。', '避免受热、明火。', NULL, '不能出现', NULL, '一氧化碳、二氧化碳、氮氧化物。', NULL, NULL, '2026-03-06 14:33:16', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3466, 3601, '稳定', NULL, '强氧化剂、水。', '接触潮湿空气。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:33:18', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3467, 3602, '稳定', NULL, '强氧化剂、强酸。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:33:18', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3468, 3603, '在正确的使用和存储条件下是稳定的。但有机过氧化物本身不稳定，受热、撞击、摩擦可能引起爆炸。', NULL, '强还原剂、易燃物、有机物、酸类、碱类、活性金属粉末、强氧化剂。', '避免受热、撞击、摩擦、明火、火花、静电积聚。避免与不相容物质接触。', NULL, '不会发生聚合反应。', NULL, '受热分解可能产生一氧化碳、二氧化碳、醛类、酮类等有毒烟雾。', NULL, NULL, '2026-03-06 14:33:18', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3469, 3604, '在常温常压下稳定', NULL, '强氧化剂、强还原剂、强酸、强碱。', '避免受热、明火、潮湿环境。', NULL, '不能出现', NULL, '受热分解产生氰化氢、氮氧化物、一氧化碳、二氧化碳等有毒气体。', NULL, NULL, '2026-03-06 14:33:18', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3470, 3605, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强酸、强碱', '不相容物质，热、火焰和火花', NULL, '不会发生危险的聚合反应', NULL, '受热分解可能产生一氧化碳、二氧化碳、氮氧化物等有毒气体。', NULL, NULL, '2026-03-06 14:33:18', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3471, 3606, '在正常储存条件下稳定，避免受潮、受热。', NULL, '强氧化剂、强酸、强碱。', '避免高温、明火、光照、潮湿环境。', NULL, '不聚合', NULL, '受热分解产生氮氧化物（NOx）、一氧化碳（CO）、二氧化碳（CO2）等有害气体。', NULL, NULL, '2026-03-06 14:33:20', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3472, 3607, '稳定', NULL, '强氧化剂。', '明火、高热', NULL, '不能出现', NULL, '一氧化碳、二氧化碳、溴化氢、氮氧化物', NULL, NULL, '2026-03-06 14:33:20', '', NULL);
