INSERT INTO `msds_stability_reactivity` VALUES (3474, 3609, '在正确的使用和存储条件下是稳定的', NULL, '酸类、酰基氯、酸酐、氯仿、强氧化剂', '不相容物质，热、火焰和火花', NULL, '不会发生', NULL, '受热分解放出有毒的氮氧化物烟气。', NULL, NULL, '2026-03-06 14:33:20', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3475, 3610, '稳定', NULL, '强氧化剂、酸类、酸酐、酰基氯。', '明火、高热、强氧化剂。', NULL, '不能出现', NULL, '一氧化碳、二氧化碳、氮氧化物、氰化氢。', NULL, NULL, '2026-03-06 14:33:20', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3476, 3611, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强酸', '不相容物质，热、火焰和火花', NULL, '无资料', NULL, '受热分解放出有毒的砷和氧化氮烟雾。受高热或接触酸或酸雾放出剧毒的烟雾。', NULL, NULL, '2026-03-06 14:33:22', '', NULL);
