INSERT INTO `msds_stability_reactivity` VALUES (3480, 3615, '稳定', NULL, '强氧化剂、强酸。', '光照。', NULL, '能出现', NULL, '一氧化碳、二氧化碳、碘化氢', NULL, NULL, '2026-03-06 14:33:22', '', NULL);
