INSERT INTO `msds_stability_reactivity` VALUES (3483, 3618, '稳定', NULL, '强氧化挤、强酸、强碱、强还原剂。', '避免受热、明火、静电。避免与氧化剂、强酸、强碱、强还原剂接触。避免接触火源。', NULL, '能发生', NULL, '受热分解产生一氧化碳、二氧化碳、氰化氢、氧化氮等有毒气体。', NULL, NULL, '2026-03-06 14:33:26', '', NULL);
