INSERT INTO `msds_stability_reactivity` VALUES (3525, 3660, '稳定', NULL, '强氧化剂。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:33:42', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3526, 3661, '稳定', NULL, '酸类、酰基氯、酸酐、氯仿、强氧化剂。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:33:42', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3527, 3662, '稳定', NULL, '强氧化剂、强酸、酰基氯、酸酐。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:33:42', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3528, 3663, '在正确的使用和存储条件下是稳定的。有机过氧化物，受热可能分解。', NULL, '还原剂、酸类、碱类、有机物、易（可）燃物（数据来源：MSDS文档操作处置与储存部分）', '不相容物质，热、火焰和火花。', NULL, '不会发生聚合', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。受热分解产生一氧化碳、二氧化碳、氯化氢等有毒气体（数据来源：消防措施部分）', NULL, NULL, '2026-03-06 14:33:42', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3529, 3664, '稳定', NULL, '强氧化剂、碱类。', '避免接触明火、高热。避免与强氧化剂、强碱接触。避免受热分解。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳、氯化氢等有毒的腐蚀性气体。与强氧化剂、强碱接触可发生剧烈反应。', NULL, NULL, '2026-03-06 14:33:44', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3530, 3665, '稳定', NULL, '氧化剂、还原剂、酸类、碱类。', '无资料', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳、氯化氢等有毒气体。', NULL, NULL, '2026-03-06 14:33:44', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3531, 3666, '稳定', NULL, '酸类、碱、强氧化剂。', '避免接触明火、高热。避免与强氧化剂、酸类、碱类接触。避免受热分解。避免与酸性催化剂接触。注意：能发生聚合反应，需添加阻聚剂。', NULL, '能发生', NULL, '受高热分解产生有毒的氯化物气体（如氯化氢）。与强氧化剂、酸类、碱类接触可发生反应。遇酸性催化剂如路易斯催化剂、齐格勒催化剂、硫酸、氯化铁、氯化铝等都能产生猛烈聚合，放出大量热量。', NULL, NULL, '2026-03-06 14:33:46', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3532, 3667, '稳定', NULL, '强氧化剂。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:33:46', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3533, 3668, '稳定', NULL, '强氧化剂。', '无资料', NULL, '不能出现', NULL, '高温分解产生一氧化碳、二氧化碳、氯化氢等有毒有害气体。', NULL, NULL, '2026-03-06 14:33:46', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3534, 3669, '稳定', NULL, '强氧化剂、潮湿空气。', '接触潮湿空气。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:33:46', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3535, 3670, '稳定', NULL, '强氧化剂、强碱、强还原剂。', '避免接触明火、高热、强氧化剂、强碱、强还原剂。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳、氧化氮、氯化氢等有毒气体。', NULL, NULL, '2026-03-06 14:33:46', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3536, 3671, '在正常储存条件下稳定，但对热、摩擦、撞击敏感。', NULL, '强氧化剂、还原剂、酸类、碱类、重金属化合物。', '避免接触热源、火花、火焰、摩擦、撞击。', NULL, '可能发生聚合反应。', NULL, '受热分解产生一氧化碳、二氧化碳、有机过氧化物分解产物。', NULL, NULL, '2026-03-06 14:33:48', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3537, 3672, '稳定', NULL, '强氧化剂、强酸、强碱。', '避免高温、明火、静电火花。避免与强氧化剂、强酸、强碱接触。', NULL, '不能出现', NULL, '高温分解可产生一氧化碳、二氧化碳等有毒气体。', NULL, NULL, '2026-03-06 14:33:48', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3538, 3673, '稳定', NULL, '强氧化剂、强酸、酰基氯、酸酐。', '避免高温、明火、静电火花。避免与强氧化剂、强酸、酰基氯、酸酐接触。', NULL, '不能出现', NULL, '高温分解可产生一氧化碳、二氧化碳等有毒气体。', NULL, NULL, '2026-03-06 14:33:48', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3539, 3674, '稳定', NULL, '强氧化剂、强酸、强碱。', '明火、高热、静电。', NULL, '能发生聚合反应', NULL, '一氧化碳、二氧化碳等有毒气体。', NULL, NULL, '2026-03-06 14:33:50', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3540, 3675, '稳定', NULL, '氧化剂、酸类。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:33:50', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3541, 3676, '稳定', NULL, '强氧化剂、强还原剂、强碱。', '明火、高热', NULL, '不能出现', NULL, '一氧化碳、二氧化碳', NULL, NULL, '2026-03-06 14:33:50', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3542, 3677, '稳定', NULL, '强氧化剂、强碱。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:33:50', '', NULL);
