INSERT INTO `msds_stability_reactivity` VALUES (3544, 3679, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强还原剂、强酸、强碱、金属粉末。', '不相容物质，热、火焰和火花', NULL, '无资料', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物', NULL, NULL, '2026-03-06 14:33:52', '', NULL);
