INSERT INTO `msds_stability_reactivity` VALUES (3549, 3684, '稳定', NULL, '强氧化剂、强碱、氰化物。', '接触潮湿空气。', NULL, '不能出现', NULL, '一氧化碳、二氧化碳、氮氧化物、氯化氢、氧化硫', NULL, NULL, '2026-03-06 14:33:54', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3550, 3685, '稳定', NULL, '强氧化剂、强还原剂、强酸、强碱。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:33:54', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3551, 3686, '稳定', NULL, '强氧化剂、强碱、水、醇类。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:33:54', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3552, 3687, '常温常压下稳定。避免接触的条件：受热、明火、光照。', NULL, '强氧化剂、强酸、强还原剂。', '受热、明火、光照', NULL, '无资料', NULL, '受热分解释放出有毒的氮氧化物。', NULL, NULL, '2026-03-06 14:33:54', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3553, 3688, '在正确的使用和存储条件下是稳定的。避免受潮、受热。', NULL, '强氧化剂、强还原剂、强酸、强碱、金属粉末。', '避免接触热源、火焰、火花、静电放电。避免与不相容物质混合。', NULL, '不发生聚合反应。', NULL, '受热分解产生有毒的砷氧化物（如三氧化二砷）和氮氧化物（如一氧化氮、二氧化氮）。在燃烧条件下可能产生其他有害分解产物。', NULL, NULL, '2026-03-06 14:33:54', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3554, 3689, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强酸。（来源：检索补充）', '不相容物质，热、火焰和火花', NULL, '无资料', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物', NULL, NULL, '2026-03-06 14:33:56', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3555, 3690, '稳定', NULL, '强氧化剂、强碱。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:33:56', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3556, 3691, '在常温常压下稳定', NULL, '强氧化剂、强还原剂、强碱', '避免接触明火、高热。避免与强氧化剂、强还原剂、强碱接触。避免受热分解。', NULL, '不会发生聚合反应', NULL, '受高热分解放出有毒的气体（一氧化碳、二氧化碳、氧化氮）', NULL, NULL, '2026-03-06 14:33:56', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3557, 3692, '稳定', NULL, '碱、胺类、强氧化剂、二氧化碳、水。', '接触潮湿空气。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:33:56', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3558, 3693, '稳定', NULL, '强氧化剂、强还原剂。强碱。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:33:56', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3559, 3694, '稳定', NULL, '强氧化剂、酸类、铜、银或其盐类。', '避免高温、明火、静电火花。避免与强氧化剂、酸类、铜、银或其盐类接触。', NULL, '不能出现', NULL, '高温分解可产生一氧化碳、二氧化碳等有毒气体。', NULL, NULL, '2026-03-06 14:33:58', '', NULL);
