INSERT INTO `msds_stability_reactivity` VALUES (3561, 3696, '稳定', NULL, '强氧化剂、强酸。', '无资料', NULL, '不能出现', NULL, '一氧化碳、二氧化碳、溴化氢', NULL, NULL, '2026-03-06 14:33:58', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3562, 3697, '稳定', NULL, '强氧化剂。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:33:58', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3563, 3698, '稳定', NULL, '强氧化剂、强碱。', '受热、光照。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:33:58', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3564, 3699, '稳定', NULL, '强氧化剂、酸类、酸酐、酰基氯。', '光照。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:34:00', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3565, 3700, '稳定', NULL, '强氧化剂、酸酐、酰基氯。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:34:00', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3566, 3701, '稳定', NULL, '强氧化剂、强还原剂、强酸、强碱。', '无资料', NULL, '不能出现', NULL, '受热分解产生溴化氢、氮氧化物、一氧化碳、二氧化碳等有毒气体。（来源：检索补充）', NULL, NULL, '2026-03-06 14:34:00', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3567, 3702, '稳定', NULL, '强氧化剂、强碱。', '无资料', NULL, '能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:34:00', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3568, 3703, '稳定', NULL, '碱、强氧化剂、强还原剂。', '无资料', NULL, '不能出现', NULL, '受热分解产生溴化氢、一氧化碳、二氧化碳等有毒气体。', NULL, NULL, '2026-03-06 14:34:01', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3569, 3704, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强碱、水、醇类', '避免受热、明火、与水接触', NULL, '不会发生聚合反应', NULL, '受热分解产生溴化氢、一氧化碳、二氧化碳等有毒气体', NULL, NULL, '2026-03-06 14:34:02', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3570, 3705, '稳定', NULL, '强氧化剂。', '无资料', NULL, '不能出现', NULL, '受热分解产生溴化氢、一氧化碳、二氧化碳等有毒气体。', NULL, NULL, '2026-03-06 14:34:02', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3571, 3706, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强酸。', '不相容物质，热、火焰和火花', NULL, '不会发生', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。受热分解产生一氧化碳、二氧化碳。', NULL, NULL, '2026-03-06 14:34:02', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3572, 3707, '在正确的使用和存储条件下是稳定的。', NULL, '强氧化剂、强酸、强碱。', '避免接触明火、高热、静电、火花。避免与氧化剂接触。', NULL, '不会发生聚合反应。', NULL, '高温分解产生一氧化碳、二氧化碳等有毒气体。', NULL, NULL, '2026-03-06 14:34:02', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3573, 3708, '在常温常压下稳定。避免受热、光照和潮湿环境。储存时应保持容器密封，防止与空气接触。', NULL, '强氧化剂（如过氧化氢、高氯酸、硝酸等）、强酸（如硫酸、盐酸、硝酸等）、强碱、酰氯、酸酐等。与氧化剂接触可能发生剧烈反应，甚至引起燃烧或爆炸。', '避免高温、明火、火花、静电放电。避免与氧化剂、强酸、强碱接触。避免光照和潮湿环境。避免与不相容物质混合储存或运输。', NULL, '不会发生聚合反应。', NULL, '高温分解时可能产生一氧化碳、二氧化碳、醛类、酮类等有害气体。燃烧产物包括一氧化碳、二氧化碳和水蒸气。', NULL, NULL, '2026-03-06 14:34:03', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3574, 3709, '稳定', NULL, '强氧化剂、强碱。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:34:03', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3575, 3710, '在正确的使用和存储条件下是稳定的。在碱性介质中易分解。', NULL, '强氧化剂、强酸、强碱。', '不相容物质，热、火焰和火花，碱性环境。', NULL, '不会发生聚合反应。', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。受热分解产生有毒的氮氧化物和一氧化碳气体。', NULL, NULL, '2026-03-06 14:34:03', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3576, 3711, '在正常储存条件下稳定，化学性质稳定，不易分解', NULL, '强氧化剂、强酸、强碱', '明火、高热、氧化剂', NULL, '无资料', NULL, '包括有毒的氧化氮和氯化物。', NULL, NULL, '2026-03-06 14:34:03', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3577, 3712, '稳定', NULL, '强氧化剂、强酸、水。', '接触潮湿空气、光照。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:34:05', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3578, 3713, '稳定', NULL, '强氧化剂。', '光照。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:34:05', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3579, 3714, '稳定', NULL, '强氧化剂、酸类、酸酐、酰基氯、氯仿。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:34:05', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3580, 3715, '稳定', NULL, '强氧化剂。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:34:06', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3581, 3716, '稳定', NULL, '强氧化剂、强酸。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:34:06', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3582, 3717, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、还原剂、酸类、碱类、重金属及其化合物', '不相容物质，热、火焰和火花。避免阳光直射。避免受热、撞击、摩擦。', NULL, '不会发生聚合反应', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。受热分解可能产生一氧化碳、二氧化碳、其他有害燃烧产物。', NULL, NULL, '2026-03-06 14:34:06', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3583, 3718, '稳定', NULL, '氧化剂。', '避免接触明火、高热。避免与氧化剂接触。避免震动、撞击和摩擦。避免受热分解。干燥状态下受摩擦、震动、撞击可引起爆炸。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳、氮氧化物等有毒气体。干燥状态下受摩擦、震动、撞击可引起爆炸。', NULL, NULL, '2026-03-06 14:34:06', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3584, 3719, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强还原剂、强酸、强碱', '避免受热、明火、火花、摩擦、撞击', NULL, '不会发生聚合反应', NULL, '受热分解产生有毒的氮氧化物、一氧化碳、二氧化碳', NULL, NULL, '2026-03-06 14:34:08', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3585, 3720, '稳定。含水≥15%时稳定。', NULL, '氧化剂、还原剂、强碱。', '避免受热、明火、撞击、摩擦。', NULL, '不能出现', NULL, '一氧化碳、二氧化碳、氮氧化物、氧化钠。', NULL, NULL, '2026-03-06 14:34:08', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3586, 3721, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强酸、强碱、重金属离子', '不相容物质，热、火焰和火花', NULL, '不会发生聚合反应', NULL, '受热分解产生氮氧化物、一氧化碳、二氧化碳等有毒气体', NULL, NULL, '2026-03-06 14:34:08', '', NULL);
