INSERT INTO `msds_stability_reactivity` VALUES (3878, 4013, '稳定', NULL, '强氧化剂、强碱。', '避免接触不相容物质，高温。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳、氯化氢、氮氧化物等有毒烟雾。', NULL, NULL, '2026-03-06 14:36:09', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3879, 4014, '稳定', NULL, '卤素、酰基氯、酸类、氯仿、强氧化剂。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:36:10', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3880, 4015, '稳定', NULL, '强氧化剂。', '光照。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:36:10', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3881, 4016, '在正确的使用和存储条件下是稳定的。加热不稳定，超过45℃时即逐渐分解。', NULL, '强氧化剂、强酸、强碱', '不相容物质，热、火焰和火花。避免加热超过45℃。', NULL, '无资料', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。受热分解产生碳氧化物、氮氧化物。', NULL, NULL, '2026-03-06 14:36:10', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3882, 4017, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、酸类、水、醇类', '不相容物质，热、火焰和火花，潮湿环境', NULL, '不会发生聚合反应', NULL, '遇水分解产生氨气和氢氧化钙，受热分解产生氨气', NULL, NULL, '2026-03-06 14:36:10', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3883, 4018, '稳定', NULL, '强氧化剂、酸类、水、醇类。', '接触潮气可分解。', NULL, '不能出现', NULL, '氨、氢气', NULL, NULL, '2026-03-06 14:36:11', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3884, 4019, '在空气中不稳定，易氧化', NULL, '强氧化剂、水、空气、强酸、卤素、醇类', '接触潮湿空气、高温', NULL, '不能出现', NULL, '氨气、氧化钠', NULL, NULL, '2026-03-06 14:36:11', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3885, 4020, '稳定', NULL, '强氧化剂、强碱。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:36:11', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3886, 4021, '在干燥空气中稳定，但在湿空气中则放出氨而变成碳酸氢铵。该化合物不稳定，易分解为氨和二氧化碳。', NULL, '强氧化剂、强酸', '潮湿环境、高温', NULL, '无资料', NULL, '氨气、二氧化碳', NULL, NULL, '2026-03-06 14:36:11', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (3887, 4022, '稳定', NULL, '强氧化剂。', '明火、高热', NULL, '不能出现', NULL, '一氧化碳、二氧化碳、氮氧化物。', NULL, NULL, '2026-03-06 14:36:12', '', NULL);
