INSERT INTO `msds_stability_reactivity` VALUES (4041, 4176, '稳定', NULL, '强氧化剂、强还原剂、酸类、碱类。', '光照。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:37:14', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4042, 4177, '稳定', NULL, '强氧化剂、强碱。', '光照、空气。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:37:14', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4043, 4178, '稳定', NULL, '强氧化剂、卤素、硫化物。', '受热。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:37:14', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4044, 4179, '不稳定。干燥状态下极不稳定，极易爆炸。含水50%以上时相对稳定。', NULL, '强氧化剂、空气、酸类、重金属化合物、有机化合物。', '避免受热、摩擦、撞击、震动、明火、火花。避免干燥。避免与酸类接触。', NULL, '不能出现', NULL, '受热分解产生氮气、钡化合物。', NULL, NULL, '2026-03-06 14:37:15', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4045, 4180, '稳定', NULL, '酸类、酰基氯、活性金属粉末、强氧化剂。', '受热。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:37:15', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4046, 4181, '不稳定', NULL, '铜、二氧化碳、强氧化剂。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:37:16', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4047, 4182, '稳定', NULL, '强氧化剂、强酸。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:37:16', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4048, 4183, '稳定', NULL, '强氧化剂、强酸。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:37:18', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4049, 4184, '稳定', NULL, '强氧化剂、强还原剂、强酸、强碱。', '无资料', NULL, '不能出现', NULL, '受高热或与酸接触会产生剧毒的氰化物气体。与强氧化剂、强还原剂、强酸、强碱接触可发生反应。', NULL, NULL, '2026-03-06 14:37:18', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4050, 4185, '稳定', NULL, '强氧化剂、强酸、空气。', '接触空气。', NULL, '能发生', NULL, '无资料', NULL, NULL, '2026-03-06 14:37:18', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4051, 4186, '稳定', NULL, '强氧化剂、卤素。', '无资料', NULL, '能发生', NULL, '无资料', NULL, NULL, '2026-03-06 14:37:18', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4052, 4187, '稳定', NULL, '碱类、氧化剂、还原剂。', '无资料', NULL, '不能出现', NULL, '受高热分解，放出刺激性烟气（一氧化碳、二氧化碳）。与碱类、氧化剂、还原剂接触可发生反应。', NULL, NULL, '2026-03-06 14:37:18', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4053, 4188, '稳定', NULL, '强氧化剂、强酸、强碱、卤素。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:37:20', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4054, 4189, '稳定', NULL, '强氧化剂、强酸、强碱。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:37:20', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4055, 4190, '稳定', NULL, '水、醇类、强氧化剂、强碱。', '潮湿空气。', NULL, '不能出现', NULL, '受热或遇水分解放热，放出有毒的腐蚀性烟气（一氧化碳、二氧化碳、光气、氯化氢）。与水、醇类、强氧化剂、强碱接触可发生反应。具有较强的腐蚀性。', NULL, NULL, '2026-03-06 14:37:20', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4056, 4191, '稳定', NULL, '强氧化剂、酸类、碱类、强还原剂。', '光照。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:37:20', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4057, 4192, '稳定', NULL, '强氧化剂、酰基氯、酸酐、氯仿、强还原剂。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:37:21', '', NULL);
