INSERT INTO `msds_stability_reactivity` VALUES (4071, 4206, '稳定', NULL, '强氧化剂、强酸。', '接触空气。', NULL, '能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:37:25', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4072, 4207, '稳定', NULL, '强氧化剂、强还原剂、酸类、碱。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:37:27', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4073, 4208, '稳定', NULL, '强氧化剂、强碱。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:37:27', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4074, 4209, '常温常压下稳定', NULL, '强氧化剂。', '明火、高热、强氧化剂', NULL, '不会发生聚合反应', NULL, '受热分解产生一氧化碳、二氧化碳、氮氧化物。', NULL, NULL, '2026-03-06 14:37:27', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4075, 4210, '常温常压下稳定', NULL, '强氧化剂。', '明火、高热、强氧化剂', NULL, '不会发生聚合反应', NULL, '受热分解产生一氧化碳、二氧化碳、氮氧化物。', NULL, NULL, '2026-03-06 14:37:27', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4076, 4211, '常温常压下稳定', NULL, '强氧化剂、强酸、酸酐、酰基氯', '明火、高热、强氧化剂、强酸', NULL, '不会发生聚合反应', NULL, '受热分解产生一氧化碳、二氧化碳、氮氧化物、氯化氢', NULL, NULL, '2026-03-06 14:37:27', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4077, 4212, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强酸、强碱', '不相容物质，热、火焰和火花', NULL, '不能出现', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。受热分解产生一氧化碳、二氧化碳等', NULL, NULL, '2026-03-06 14:37:29', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4078, 4213, '在正确的使用和存储条件下是稳定的。', NULL, '强氧化剂、强酸。', '避免接触不相容物质，热、火焰和火花。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳、氯化氢等有毒烟雾。', NULL, NULL, '2026-03-06 14:37:29', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4079, 4214, '常温常压下稳定，避免受热、光照和接触空气。', NULL, '强氧化剂、强酸、强碱。', '明火、高热、光照、接触空气。', NULL, '不能出现', NULL, '一氧化碳、二氧化碳、硫化物、氧化氮等有毒气体。', NULL, NULL, '2026-03-06 14:37:29', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4080, 4215, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、碱类', '避免与不相容物质、热、火焰和火花接触。', NULL, '不会发生聚合反应', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。燃烧时产生一氧化碳、二氧化碳。', NULL, NULL, '2026-03-06 14:37:29', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4081, 4216, '在正确的使用和存储条件下是稳定的', NULL, '水、醇类、强氧化剂、强碱', '避免与不相容物质、热、火焰和火花接触。避免潮湿空气。', NULL, '不会发生聚合反应', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。遇水发生剧烈化学反应，产生刺激性气体。燃烧时产生一氧化碳、二氧化碳、光气、氯化氢。', NULL, NULL, '2026-03-06 14:37:29', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4082, 4217, '常温常压下稳定，避免受热、光照和接触空气。', NULL, '强氧化剂、强酸、强碱、空气。', '明火、高热、光照、接触空气。', NULL, '不能出现', NULL, '一氧化碳、二氧化碳等有毒气体。', NULL, NULL, '2026-03-06 14:37:31', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4083, 4218, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、碱类、金属粉末', '不相容物质，热、火焰、火花、静电', NULL, '不会发生聚合反应', NULL, '受热分解产生一氧化碳、二氧化碳、硫化物等有害气体', NULL, NULL, '2026-03-06 14:37:31', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4084, 4219, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强碱、空气。', '接触空气、光照', NULL, '不会发生', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。燃烧时产生一氧化碳、二氧化碳、氧化氮。', NULL, NULL, '2026-03-06 14:37:31', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4085, 4220, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂。', '不相容物质，热、火焰、火花', NULL, '不会发生', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。燃烧时产生一氧化碳、二氧化碳。', NULL, NULL, '2026-03-06 14:37:31', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4086, 4221, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强碱、潮湿空气', '避免与氧化剂、强碱接触。避免潮湿空气。避免高温。', NULL, '不会发生聚合反应', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。受热分解产生有毒的硫化物烟气。燃烧时产生一氧化碳、二氧化碳、硫化物。', NULL, NULL, '2026-03-06 14:37:33', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4087, 4222, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强酸、强碱', '避免与氧化剂、强酸、强碱接触。避免高温。', NULL, '不会发生聚合反应', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。受热分解产生有毒的硫化物烟气。燃烧时产生一氧化碳、二氧化碳、氧化硫。', NULL, NULL, '2026-03-06 14:37:33', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4088, 4223, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强碱', '避免与氧化剂、强碱接触。避免潮湿空气。避免高温。', NULL, '不会发生聚合反应', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。受热分解放出有毒的气体。燃烧时产生一氧化碳、二氧化碳、氧化硫、氯化氢。', NULL, NULL, '2026-03-06 14:37:33', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4089, 4224, '常温常压下稳定，避免受热、光照和接触空气。', NULL, '强氧化剂、强碱、强酸。', '明火、高热、光照、接触空气。', NULL, '不能出现', NULL, '一氧化碳、二氧化碳等有毒气体。', NULL, NULL, '2026-03-06 14:37:33', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4090, 4225, '在正确的使用和存储条件下是稳定的', NULL, '强碱、强氧化剂、强还原剂、空气', '避免与氧化剂、强碱、强还原剂接触。避免接触空气。避免高温。', NULL, '不会发生聚合反应', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。燃烧时产生一氧化碳、二氧化碳。', NULL, NULL, '2026-03-06 14:37:33', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4091, 4226, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强酸', '避免与不相容物质、热、火焰和火花接触。避免高温。', NULL, '不会发生聚合反应', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。接触酸和酸雾产生剧毒的氰化氢气体。燃烧时产生一氧化碳、二氧化碳、氮氧化物、氰化氢。', NULL, NULL, '2026-03-06 14:37:35', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4092, 4227, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强酸、强碱、重金属及其盐类', '不相容物质，热、火焰、火花、静电', NULL, '不会发生聚合反应', NULL, '受热分解产生一氧化碳、二氧化碳、硫化物、氯化物等有害气体', NULL, NULL, '2026-03-06 14:37:35', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4093, 4228, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、还原剂、酸类、碱类、金属粉末、重金属及其盐类', '不相容物质，热、火焰、火花、撞击、摩擦、静电', NULL, '不会发生聚合反应', NULL, '受热分解产生一氧化碳、二氧化碳等有害气体', NULL, NULL, '2026-03-06 14:37:35', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4094, 4229, '常温常压下稳定，避免受热、光照和接触空气。', NULL, '强氧化剂、强酸、强碱、空气。', '明火、高热、光照、接触空气。', NULL, '不能出现', NULL, '一氧化碳、二氧化碳、苯酚等有毒气体。', NULL, NULL, '2026-03-06 14:37:37', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4095, 4230, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强酸、强碱', '避免与不相容物质、热、火焰和火花接触。避免高温。', NULL, '不会发生聚合反应', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。受热分解产生有毒的氧化氮烟气。燃烧时产生一氧化碳、二氧化碳、氧化氮。', NULL, NULL, '2026-03-06 14:37:37', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4096, 4231, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强酸、强碱', '避免与不相容物质、热、火焰和火花接触。避免高温。', NULL, '不会发生聚合反应', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。受热分解产生有毒的氧化氮烟气。燃烧时产生一氧化碳、二氧化碳、氧化氮。', NULL, NULL, '2026-03-06 14:37:37', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4097, 4232, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强酸、强碱', '避免与不相容物质、热、火焰和火花接触。避免高温。', NULL, '不会发生聚合反应', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。受热分解产生有毒的氧化氮烟气。燃烧时产生一氧化碳、二氧化碳、氧化氮。', NULL, NULL, '2026-03-06 14:37:37', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4098, 4233, '常温常压下稳定，避免受热、光照和接触空气。', NULL, '强氧化剂、强酸、强碱。', '明火、高热、光照、接触空气。', NULL, '不能出现', NULL, '一氧化碳、二氧化碳、氧化氮等有毒气体。', NULL, NULL, '2026-03-06 14:37:37', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4099, 4234, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强还原剂、强碱、强酸', '避免与氧化剂、还原剂、酸类、碱类接触。避免高温。', NULL, '不会发生聚合反应', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。受热分解产生有毒的腐蚀性烟气。燃烧时产生一氧化碳、二氧化碳、氧化氮。', NULL, NULL, '2026-03-06 14:37:39', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4100, 4235, '稳定', NULL, '强氧化剂、酸类。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:37:40', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4101, 4236, '在正确的使用和存储条件下是稳定的', NULL, '氧化剂、酸酐、酰基氯、强酸、强碱', '避免与氧化剂、酸酐、酰基氯接触。避免高温。', NULL, '不会发生', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。燃烧时产生一氧化碳、二氧化碳。', NULL, NULL, '2026-03-06 14:37:41', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4102, 4237, '在正确的使用和存储条件下是稳定的', NULL, '强还原剂、有机物、易燃物、强酸、强碱', '不相容物质，热、火焰和火花', NULL, '不能出现', NULL, '受热分解产生氨气、氮氧化物、钒氧化物等有毒气体', NULL, NULL, '2026-03-06 14:37:41', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4103, 4238, '在正确的使用和存储条件下是稳定的。多硫化铵溶液在空气中不稳定，易分解释放硫化氢和氨气。', NULL, '强氧化剂（如高氯酸、过氧化氢、过氧化钠等）、强酸（如浓硫酸、浓硝酸、盐酸等）、重金属盐（如铜盐、银盐、汞盐等）。与这些物质接触可能引发剧烈反应或分解。', '不相容物质，热、火焰和火花。避免高温、明火、强氧化剂、强酸、重金属盐等条件。', NULL, '无聚合危害', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。受热分解产生硫化氢（H2S）、氨气（NH3）、二氧化硫（SO2）、氧化硫（SO3）等有毒有害气体。', NULL, NULL, '2026-03-06 14:37:43', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4104, 4239, '稳定', NULL, '强氧化剂。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:37:43', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4105, 4240, '在正常的储存和使用条件下相对稳定。具有很高的化学稳定性，耐酸、耐碱、耐氧化。对光敏感，长期暴露在阳光下可能发生光化学反应。受热时可能发生分解，特别是在高温或燃烧条件下。由于其持久性，在环境中可长期存在而不易降解。', NULL, '强氧化剂（如高锰酸钾、过氧化氢、硝酸等）、强酸（如浓硫酸、浓硝酸）、强碱（如氢氧化钠、氢氧化钾）、金属粉末（如铝粉、镁粉）、卤素、还原剂。避免与这些物质接触，以防发生剧烈反应。', '避免接触明火、高热、火花、火焰。避免与强氧化剂、强酸、强碱接触。避免长时间暴露在阳光下或紫外线下。避免在高温环境下储存和使用。避免在密闭空间内加热，以防压力积聚。', NULL, '不会发生聚合反应。多氯三联苯是稳定的氯化芳烃化合物，不会发生自聚合或与其他单体发生聚合反应。', NULL, '受热分解（>300℃）产生氯化氢（HCl）、光气（COCl2）、一氧化碳（CO）、二氧化碳（CO2）、多氯二苯并二恶英（PCDDs）、多氯二苯并呋喃（PCDFs）等剧毒物质。燃烧时会产生大量黑烟和有毒气体。', NULL, NULL, '2026-03-06 14:37:44', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4106, 4241, '稳定', NULL, '强氧化剂。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:37:44', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4107, 4242, '在正确的使用和存储条件下是稳定的', NULL, '无资料', '不相容物质，热、火焰和火花', NULL, '无资料', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物', NULL, NULL, '2026-03-06 14:37:46', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4108, 4243, '在正确的使用和存储条件下是稳定的', NULL, '无资料', '不相容物质，热、火焰和火花', NULL, '无资料', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物', NULL, NULL, '2026-03-06 14:37:46', '', NULL);
