INSERT INTO `msds_stability_reactivity` VALUES (4147, 4282, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、酸类。', '避免接触明火、高热。避免与强氧化剂、酸类接触。避免受热分解。避免不相容物质，热、火焰和火花。', NULL, '不能出现', NULL, '受高热分解放出有毒的气体（一氧化碳、二氧化碳）。与强氧化剂接触可发生反应。', NULL, NULL, '2026-03-06 14:38:03', '', NULL);
