INSERT INTO `msds_stability_reactivity` VALUES (4222, 4357, '在正确的使用和存储条件下是稳定的。', NULL, '强氧化剂、强碱、强还原剂、金属粉末等。', '受热、光照、与不相容物质接触。', NULL, '不能发生', NULL, '受高热分解放出有毒的气体（溴化氢、一氧化碳、二氧化碳）。与强氧化剂、强碱接触可发生剧烈反应。在火场中，受热的容器有爆炸危险。受热或接触火焰可能会产生膨胀或爆炸性分解。', NULL, NULL, '2026-03-06 14:38:43', '', NULL);
