INSERT INTO `msds_stability_reactivity` VALUES (4333, 4468, '在正确的使用和存储条件下是稳定的。', NULL, '强氧化剂、强酸。', '避免明火、高热、强氧化剂、强酸。', NULL, '不会发生聚合反应', NULL, '燃烧产生一氧化碳、二氧化碳。', NULL, NULL, '2026-03-06 14:39:31', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4334, 4469, '在正确的使用和存储条件下是稳定的。', NULL, '强氧化剂、强酸、强碱、还原剂。', '避免不相容物质，热、火焰和火花。', NULL, '不会发生聚合反应', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。燃烧或爆炸时产生氮氧化物、一氧化碳、二氧化碳。', NULL, NULL, '2026-03-06 14:39:31', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4335, 4470, '稳定', NULL, '强还原剂、活性金属粉末、碱类、易燃或可燃物、硫、磷。', '光照。', NULL, '不能出现', NULL, '受热分解产生碘化氢、碘蒸气和氧气。与有机物接触可能发生剧烈反应或爆炸。', NULL, NULL, '2026-03-06 14:39:31', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4336, 4471, '在正确的使用和存储条件下是稳定的', NULL, '强还原剂、活性金属粉末、硫、磷、易燃或可燃物、有机物。', '不相容物质，热、火焰和火花', NULL, '无资料', NULL, '受热分解产生碘化氢、碘蒸气、氧化钡和氧气。急剧加热时可发生爆炸。与有机物接触可能发生剧烈反应或爆炸。', NULL, NULL, '2026-03-06 14:39:31', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4337, 4472, '稳定', NULL, '易燃或可燃物、活性金属粉末、镁硫、磷、强还原剂。', '光照。', NULL, '不能出现', NULL, '受热分解产生碘化氢、碘蒸气和氧气。急剧加热时可发生爆炸。与有机物接触可能发生剧烈反应或爆炸。', NULL, NULL, '2026-03-06 14:39:32', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4338, 4473, '稳定', NULL, '强还原剂、易燃或可燃物、硫、磷、活性金属粉末。', '避免与还原剂、硫、磷、活性金属粉末、易燃或可燃物接触。避免受热、摩擦、撞击。避免接触有机物。防止受潮。避免急剧加热。', NULL, '不能出现', NULL, '受热分解产生氮氧化物、氧气和氧化钙。急剧加热时可发生爆炸。与有机物接触可能发生剧烈反应或爆炸。', NULL, NULL, '2026-03-06 14:39:34', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4339, 4474, '稳定', NULL, '易燃或可燃物、活性金属粉末、硫、磷、肼。', '避免与还原剂、活性金属粉末、硫、磷、肼、易燃或可燃物接触。避免受热、摩擦、撞击。避免接触有机物。防止受潮。', NULL, '不能出现', NULL, '受热分解产生氯化物和氧化锂，放出氧气。与有机物接触可能发生剧烈反应或爆炸。', NULL, NULL, '2026-03-06 14:39:34', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4340, 4475, '稳定', NULL, '还原剂、易燃或可燃物、硫、磷、肼。', '避免与还原剂、硫、磷、肼、易燃或可燃物接触。避免受热、摩擦、撞击。避免接触有机物。防止受潮。', NULL, '不能出现', NULL, '受热分解产生氯化氢、氧化镁和氧气。与有机物接触可能发生剧烈反应或爆炸。', NULL, NULL, '2026-03-06 14:39:34', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4341, 4476, '稳定', NULL, '易燃或可燃物、强酸、强还原剂、活性金属粉末、镁。', '避免与还原剂、活性金属粉末、强酸、醇类、易燃或可燃物接触。避免受热、摩擦、撞击。避免接触有机物。防止受潮。避免急剧加热。', NULL, '不能出现', NULL, '受热分解产生氯化物和氧化钠，放出氧气。急剧加热时可发生爆炸。与有机物接触可能发生剧烈反应或爆炸。', NULL, NULL, '2026-03-06 14:39:34', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4342, 4477, '稳定', NULL, '还原剂、易燃或可燃物。', '避免与还原剂、易燃或可燃物接触。避免受热、摩擦、撞击。避免接触有机物。防止受潮。严禁震动、撞击和摩擦。', NULL, '不能出现', NULL, '受热分解产生氯化氢、氧化铅和氧气。与有机物接触可能发生剧烈反应或爆炸。', NULL, NULL, '2026-03-06 14:39:36', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4343, 4478, '稳定', NULL, '强还原剂、醇类、水、易燃或可燃物、活性金属粉末、硫、磷。', '避免与还原剂、醇类、水、易燃或可燃物、活性金属粉末、硫、磷接触。避免受热、摩擦、撞击。避免接触有机物。防止受潮。严禁震动、撞击和摩擦。', NULL, '不能出现', NULL, '受热分解产生氯化物和氧化银，放出氧气。与有机物接触可能发生剧烈反应或爆炸。', NULL, NULL, '2026-03-06 14:39:36', '', NULL);
