INSERT INTO `msds_stability_reactivity` VALUES (4345, 4480, '稳定', NULL, '易燃或可燃物、强还原剂、磷、硫、活性金属粉末。', '避免与还原剂、活性金属粉末、硫、磷、易燃或可燃物接触。避免受热、摩擦、撞击。避免接触有机物、硫酸、铵盐、过氧化氢、甘油、乙醇。防止受潮。', NULL, '不能出现', NULL, '受热分解产生氧化钙和二氧化锰。与有机物、硫酸、铵盐、过氧化氢、甘油、乙醇接触可能发生剧烈反应或爆炸。', NULL, NULL, '2026-03-06 14:39:37', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4346, 4481, '稳定', NULL, '强还原剂、活性金属粉末、硫、铝、锌、铜及其合金、易燃或可燃物。', '避免与还原剂、活性金属粉末、硫、铝、锌、铜及其合金、易燃或可燃物接触。避免受热、摩擦、撞击。避免接触有机物。', NULL, '不能出现', NULL, '受热分解产生氧化钾和二氧化锰。与有机物接触可能发生剧烈反应。', NULL, NULL, '2026-03-06 14:39:37', '', NULL);
