INSERT INTO `msds_stability_reactivity` VALUES (4348, 4483, '在正确的使用和存储条件下是稳定的', NULL, '强还原剂、活性金属粉末、硫、磷、易燃或可燃物、有机物。', '不相容物质，热、火焰和火花', NULL, '不能出现(无机化合物，不具备聚合性)', NULL, '受热分解产生氧化银和二氧化锰。与有机物接触可能发生剧烈反应或爆炸。', NULL, NULL, '2026-03-06 14:39:37', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4349, 4484, '稳定', NULL, '氧化剂、酸类、硫、锌、钾等。', '接触空气。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:39:39', '', NULL);
