INSERT INTO `msds_stability_reactivity` VALUES (4479, 4614, '在正确的使用和存储条件下是稳定的', NULL, '强酸、强氧化剂、强还原剂、酰基氯、酸酐', '避免与不相容物质、热、火焰和火花接触。避免高温。', NULL, '不会发生聚合反应', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。受热分解产生一氧化碳、二氧化碳。', NULL, NULL, '2026-03-06 14:40:43', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4480, 4615, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强还原剂、强酸、强碱', '避免与不相容物质、热、火焰和火花接触', NULL, '不会发生聚合反应', NULL, '遇高热分解释出剧毒的气体（一氧化碳、二氧化碳、氧化氮、氰化物）。与强氧化剂、强还原剂、强酸、强碱接触可发生反应。', NULL, NULL, '2026-03-06 14:40:43', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4481, 4616, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强酸、强碱', '避免与不相容物质、热、火焰和火花接触。避免接触空气。', NULL, '能发生聚合反应', NULL, '受热分解放出有毒气体。燃烧时产生一氧化碳、二氧化碳。', NULL, NULL, '2026-03-06 14:40:43', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4482, 4617, '在正确的使用和存储条件下是稳定的', NULL, '强碱、氧化剂、水、醇类', '避免与不相容物质、热、火焰和火花接触。避免潮湿空气。', NULL, '不会发生聚合反应', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。遇水发生剧烈化学反应，产生刺激性气体。燃烧时产生一氧化碳、二氧化碳、氯化氢、光气。', NULL, NULL, '2026-03-06 14:40:43', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4483, 4618, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、碱类、水、醇类', '避免与不相容物质、热、火焰和火花接触。避免潮湿空气。', NULL, '不会发生聚合反应', NULL, '遇水反应，放出有毒的、有腐蚀性的氯和氯化氢气体。燃烧时产生一氧化碳、二氧化碳、氯化氢、氧化硅、氯化物。', NULL, NULL, '2026-03-06 14:40:43', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4484, 4619, '稳定', NULL, '强氧化剂、强还原剂、强酸、强碱。', '无资料', NULL, '不能出现', NULL, '一氧化碳、二氧化碳、氮氧化物、氰化氢。', NULL, NULL, '2026-03-06 14:40:45', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4485, 4620, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、还原剂、酸类、碱类、碱金属', '避免与不相容物质、热、火焰和火花接触。避免阳光直射。', NULL, '不会发生聚合反应', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。燃烧时产生一氧化碳、二氧化碳、氧化硫、硫化氢。', NULL, NULL, '2026-03-06 14:40:45', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4486, 4621, '稳定', NULL, '强氧化剂、强碱。', '无资料', NULL, '不能出现', NULL, '受高热分解放出有毒的气体（一氧化碳、二氧化碳、氮氧化物）。与强氧化剂、强碱接触可发生反应。', NULL, NULL, '2026-03-06 14:40:45', '', NULL);
