INSERT INTO `msds_stability_reactivity` VALUES (4491, 4626, '稳定', NULL, '无资料', '潮湿空气（会迅速氧化）', NULL, '不聚合', NULL, '氧化镓（在潮湿空气中）', NULL, NULL, '2026-03-06 14:40:47', '', NULL);
