INSERT INTO `msds_stability_reactivity` VALUES (4494, 4629, '在正确的使用和存储条件下是稳定的', NULL, '水、酸类、氯代烃、强氧化剂', '潮湿空气、水、酸类、氯代烃、高温', NULL, '不会发生聚合反应', NULL, '受热分解产生一氧化碳、二氧化碳等有毒烟雾。', NULL, NULL, '2026-03-06 14:40:49', '', NULL);
