INSERT INTO `msds_stability_reactivity` VALUES (4649, 4784, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强酸', '不相容物质，热、火焰和火花', NULL, '不会发生聚合反应', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。受热分解产生氮氧化物和硫氧化物。', NULL, NULL, '2026-03-06 14:41:54', '', NULL);
