INSERT INTO `msds_stability_reactivity` VALUES (4662, 4797, '稳定', NULL, '水、次氯酸盐、强氧化剂、强碱', '不相容物质，热、火焰和火花', NULL, '不会发生聚合反应', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。受热分解产生氧化硫和氧化钾。', NULL, NULL, '2026-03-06 14:42:00', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4663, 4798, '稳定', NULL, '水、次氯酸盐、强氧化剂、强碱', '不相容物质，热、火焰和火花', NULL, '不会发生聚合反应', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。受热分解产生氧化硫和氧化钠。', NULL, NULL, '2026-03-06 14:42:00', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4664, 4799, '稳定', NULL, '强氧化剂、强碱', '避免接触强氧化剂、强碱，避免受热', NULL, '不会发生聚合反应', NULL, '受热分解产生一氧化碳、二氧化碳、硫化物、氧化锡等有毒气体', NULL, NULL, '2026-03-06 14:42:00', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4665, 4800, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强酸', '不相容物质，热、火焰和火花', NULL, '不会发生聚合反应', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。受热分解产生氧化硫和汞蒸气。', NULL, NULL, '2026-03-06 14:42:02', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4666, 4801, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强酸、强碱', '不相容物质，热、火焰和火花', NULL, '不会发生', NULL, '受热分解产生有毒的硫氧化物和钒氧化物', NULL, NULL, '2026-03-06 14:42:02', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4667, 4802, '稳定', NULL, '强氧化剂。', '光照。', NULL, '不能出现', NULL, '氯化氢、氟化氢、一氧化碳、二氧化碳等有毒气体。', NULL, NULL, '2026-03-06 14:42:02', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4668, 4803, '在正常储存条件下稳定。遇水反应生成水合六氟丙酮。', NULL, '水、醇类、胺类、强氧化剂、碱类、活性氢化合物。', '避免受热、避免接触水、醇类、胺类等活性氢化合物。避免阳光直射。避免与不相容物质接触。', NULL, '不能出现', NULL, '高温分解产生氟化氢、一氧化碳、二氧化碳等有毒气体。氟化氢具有强腐蚀性和毒性。', NULL, NULL, '2026-03-06 14:42:02', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4669, 4804, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强还原剂、强酸、强碱、金属粉末', '避免受热、避免接触不相容物质、避免接触热、火焰和火花。', NULL, '不会发生', NULL, '氟化氢、一氧化碳、二氧化碳等有毒气体。', NULL, NULL, '2026-03-06 14:42:04', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4670, 4805, '稳定', NULL, '强氧化剂、易燃或可燃物。', '无资料', NULL, '能发生', NULL, '无资料', NULL, NULL, '2026-03-06 14:42:04', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4671, 4806, '稳定', NULL, '强酸。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:42:04', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4672, 4807, '稳定', NULL, '强酸、强碱。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:42:05', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4673, 4808, '稳定', NULL, '强酸。', '避免受热、潮湿环境。', NULL, '不能出现', NULL, '受热分解产生氟化氢、氧化锌、氧化硅等有毒气体。', NULL, NULL, '2026-03-06 14:42:05', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4674, 4809, '稳定', NULL, '强碱。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:42:06', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4675, 4810, '在常温常压下稳定。避免受热。', NULL, '强氧化剂。', '避免接触明火、高热、强氧化剂。避免静电积聚。', NULL, '不会发生聚合反应', NULL, '高温分解产生氟化氢、一氧化碳、二氧化碳等有毒气体。', NULL, NULL, '2026-03-06 14:42:06', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4676, 4811, '稳定', NULL, '潮湿空气、强碱、易燃或可燃物。', '接触潮湿空气。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:42:06', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4677, 4812, '稳定。在常温常压下化学性质稳定，不与水、酸、碱反应。', NULL, '强氧化剂、易燃或可燃物。在电弧作用下可能与金属反应。', '避免高温、明火、电弧。避免与强氧化剂接触。', NULL, '不能出现', NULL, '在高温或电弧作用下可能分解产生低氟化硫（如SF4、S2F10）、氟化氢（HF）等有毒物质。', NULL, NULL, '2026-03-06 14:42:06', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4678, 4813, '在常温常压下稳定。在潮湿空气中水解，生成硒酸和氢氟酸。', NULL, '易燃或可燃物、有机物、金属粉末、还原剂、水、潮湿空气。', '避免接触水、潮湿空气、热源、火源、易燃物。避免与有机物、金属粉末、还原剂接触。', NULL, '不会发生聚合反应', NULL, '高温分解产生氟化氢、硒化合物等有毒气体。', NULL, NULL, '2026-03-06 14:42:07', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4679, 4814, '在干燥、密封的条件下稳定。在常温下缓慢升华，在56.54℃以上迅速升华。在密闭容器中稳定，但遇热分解。对金属、玻璃、陶瓷等材料有强腐蚀性。遇水或潮气剧烈反应，产生氟化氢（HF）和铀酰化合物（UO2F2）。在高温下（>200℃）分解为四氟化铀（UF4）和氟气（F2）。具有放射性，放射性衰变不影响化学稳定性。在空气中缓慢水解，产生HF烟雾。对光稳定，不受紫外线影响。在惰性气氛（如氩气、氮气）中稳定。', NULL, '1）水、潮气、湿空气：剧烈反应产生剧毒的HF和UO2F2；2）强氧化剂：如过氧化氢、高氯酸、硝酸等，可能发生剧烈反应；3）强酸：如硫酸、盐酸、硝酸等，可能发生剧烈反应；4）有机物：如醇类、醚类、酮类、烃类等，可能发生剧烈反应或燃烧；5）还原剂：如金属粉末、氢气、一氧化碳等，可能发生剧烈反应；6）金属：如铝、镁、钠、钾等活泼金属，可能发生剧烈反应；7）玻璃、陶瓷：在高温下腐蚀，发生反应；8）橡胶、塑料：在高温下腐蚀，发生反应；9）碳：在高温下反应生成四氟化铀（UF4）和氟化碳；10）氨：在高温下反应生成氟化铵和铀氮化物。', '1）避免接触水、潮气和湿空气；2）避免高温（>56.54℃）和明火；3）避免阳光直射和热源；4）避免机械冲击和振动；5）避免与不相容物质接触；6）避免在非密闭环境中操作；7）避免在非通风环境中操作；8）避免在没有防护措施的情况下操作；9）避免在没有辐射监测的情况下操作；10）避免在没有应急预案的情况下操作。', NULL, '不发生聚合反应。六氟化铀是无机化合物，不具备聚合能力。', NULL, '1）热分解（>200℃）：四氟化铀（UF4）+ 氟气（F2）；2）水解反应：氟化氢（HF）+ 铀酰化合物（UO2F2）+ 氟化铀酰（UO2F2·2H2O）；3）与有机物反应：氟化碳化合物 + 铀化合物；4）与金属反应：金属氟化物 + 铀化合物；5）与还原剂反应：低价铀化合物（如UF4）+ 氟化物；6）辐射分解：在强辐射场中可能分解为低价铀化合物和氟化物。分解产物具有剧毒、腐蚀性和放射性。', NULL, NULL, '2026-03-06 14:42:07', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4680, 4815, '稳定，在常温常压下不分解。在高温下可能分解产生有毒气体。', NULL, '强氧化剂、活泼金属（如钠、钾、镁等）。', '避免高温、明火、强氧化剂。避免与活泼金属接触。', NULL, '不能出现（不会发生聚合反应）', NULL, '高温分解可能产生氟化氢、一氧化碳、二氧化碳等有毒气体。', NULL, NULL, '2026-03-06 14:42:07', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4681, 4816, '稳定', NULL, '强氧化剂。', '明火、高热。', NULL, '不能出现', NULL, '一氧化碳、二氧化碳。', NULL, NULL, '2026-03-06 14:42:07', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4682, 4817, '稳定', NULL, '强酸、强碱、强氧化剂、水、潮湿空气。', '潮湿空气。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳、氧化硅等有毒有害气体。', NULL, NULL, '2026-03-06 14:42:07', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4683, 4818, '稳定', NULL, '强氧化剂、强酸、强碱。', '无资料', NULL, '不能出现', NULL, '一氧化碳、二氧化碳、氧化硅、硅烷类化合物。', NULL, NULL, '2026-03-06 14:42:09', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4684, 4819, '常温常压下稳定，但应避免光照和高温。在避光、阴凉、通风条件下储存可保持稳定。长期储存可能发生聚合反应，应添加阻聚剂。', NULL, '强氧化剂（如过氧化物、高氯酸盐、高锰酸盐等）、强酸、强碱、金属粉末、胺类、醇类等。与强氧化剂接触可能发生剧烈反应，甚至爆炸。与强酸或强碱可能发生水解反应，产生氯化氢等有毒气体。', '避免高温、明火、火花、静电放电。避免光照（紫外线可引发聚合反应）。避免与不相容物质接触。避免吸入蒸气或接触皮肤。避免在密闭空间内使用，防止蒸气积聚。', NULL, '能发生聚合反应，特别是在光照、高温或存在引发剂的情况下。聚合反应可能放热，导致容器内压升高。建议添加适当的阻聚剂以防止聚合。', NULL, '高温分解产生氯化氢、光气、一氧化碳、二氧化碳、氯气等有毒有害气体。燃烧时产生大量浓烟和有毒气体。', NULL, NULL, '2026-03-06 14:42:09', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4685, 4820, '稳定', NULL, '强氧化剂。', '明火、高热', NULL, '不能出现', NULL, '氯化氢、一氧化碳、二氧化碳。', NULL, NULL, '2026-03-06 14:42:09', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4686, 4821, '稳定', NULL, '强氧化剂、强碱。', '避免高温、明火、潮湿环境。', NULL, '不能出现', NULL, '一氧化碳、二氧化碳、氯化氢、光气。', NULL, NULL, '2026-03-06 14:42:09', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4687, 4822, '稳定', NULL, '强氧化剂、潮湿空气、水。', '接触潮湿空气。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:42:11', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4688, 4823, '稳定', NULL, '强氧化剂。', '无资料', NULL, '不能出现', NULL, '一氧化碳、二氧化碳、氯化氢', NULL, NULL, '2026-03-06 14:42:11', '', NULL);
