INSERT INTO `msds_stability_reactivity` VALUES (4731, 4866, '不稳定', NULL, '水、碱类、醇类、酸类。', '潮湿空气。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:42:27', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4732, 4867, '在正确的使用和存储条件下是稳定的。', NULL, '强还原剂、强碱、碱金属、镁粉、铝粉', '避免受热、明火、火花。避免与不相容物质接触。', NULL, '不会发生聚合反应', NULL, '受热分解产生氯化氢气体', NULL, NULL, '2026-03-06 14:42:27', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4733, 4868, '稳定', NULL, '强氧化剂、强酸、强碱、磷、钾。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:42:29', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4734, 4869, '稳定', NULL, '强氧化剂。', '避免接触强氧化剂、强碱、强酸。避免高温和潮湿环境。', NULL, '不能出现', NULL, '受热分解产生氯化氢、氧化锌等有毒腐蚀性气体。', NULL, NULL, '2026-03-06 14:42:29', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4735, 4870, '在正确的使用和存储条件下是稳定的', NULL, '无资料', '不相容物质，热、火焰和火花', NULL, '无资料', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物', NULL, NULL, '2026-03-06 14:42:30', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4736, 4871, '在常温常压下不稳定，受热、摩擦、撞击可能发生爆炸或分解。', NULL, '强氧化剂、强酸、强碱、易燃物、还原剂、金属粉末、有机胺类。', '避免受热、摩擦、撞击、光照、火花、明火。', NULL, '无资料', NULL, '一氧化碳、二氧化碳、氮氧化物、氯化氢、氧化锌等有毒气体。', NULL, NULL, '2026-03-06 14:42:30', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4737, 4872, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强还原剂、金属粉末、有机胺类、强酸、强碱、重金属盐类。避免与这些物质接触，以免发生剧烈反应。', '不相容物质，热、火焰和火花', NULL, '不适用（重氮盐化合物通常不会发生聚合反应，但可能发生分解反应）', NULL, '受热分解产生氮气、氯化氢、一氧化碳、二氧化碳、氯气、芳香族化合物等有毒有害气体。', NULL, NULL, '2026-03-06 14:42:30', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4738, 4873, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强还原剂、酸类、碱类、金属粉末、易燃物、有机物。', '不相容物质，热、火焰和火花。干燥状态下不稳定，受热或震动易分解。', NULL, '无聚合危害', NULL, '受热分解产生氮氧化物、氯化氢、氧化锌等有毒有害气体。', NULL, NULL, '2026-03-06 14:42:30', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4739, 4874, '在常温常压下稳定，但受热或震动可能分解', NULL, '强还原剂、强酸、强碱、氧化剂、金属粉末', '避免受热、震动、摩擦、明火、火花', NULL, '不会发生聚合反应', NULL, '受热分解可能产生氮氧化物、氯化氢、锌化合物等有毒烟雾', NULL, NULL, '2026-03-06 14:42:31', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4740, 4875, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强酸、强碱、重金属盐类。', '不相容物质，热、火焰和火花。避免受热、摩擦、撞击。', NULL, '不会发生聚合反应。', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物', NULL, NULL, '2026-03-06 14:42:31', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4741, 4876, '不稳定', NULL, '易燃或可燃物。', '潮湿空气。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:42:31', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4742, 4877, '稳定', NULL, '空气、水、碱类。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:42:33', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4743, 4878, '稳定', NULL, '强碱、潮湿空气。', '光照、接触潮湿空气。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:42:33', '', NULL);
