INSERT INTO `msds_stability_reactivity` VALUES (4746, 4881, '稳定', NULL, '酸类、碱类、醇类、活性金属粉末、胺类、水、易燃或可燃物。', '潮湿空气。', NULL, '不能出现', NULL, '氯化氢、氧化硫', NULL, NULL, '2026-03-06 14:42:33', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4747, 4882, '在常温常压下稳定', NULL, '强氧化剂、强碱、酸类、水。', '光照、空气、高温。', NULL, '不能出现', NULL, '氯化氢、甲醛、一氧化碳、二氧化碳。', NULL, NULL, '2026-03-06 14:42:34', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4748, 4883, '在常温常压下稳定，遇水或潮湿空气分解。', NULL, '强氧化剂、强酸、强碱、水、潮湿空气。', '避免接触水、潮湿空气、高温、明火。', NULL, '不会发生聚合反应。', NULL, '遇水分解产生氯化氢气体。受热分解产生一氧化碳、二氧化碳、氯化氢、氧化硅等有毒气体。', NULL, NULL, '2026-03-06 14:42:34', '', NULL);
