INSERT INTO `msds_stability_reactivity` VALUES (4818, 4953, '在正常的储存和使用条件下是稳定的。', NULL, '强氧化剂、强酸、强碱。', '高温、明火、摩擦、撞击。', NULL, '不会发生聚合反应。', NULL, '受热分解产生一氧化碳、二氧化碳、氮氧化物、氮气等有毒气体。', NULL, NULL, '2026-03-06 14:43:03', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4819, 4954, '稳定', NULL, '酸类、酸酐、强氧化剂。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:43:05', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4820, 4955, '稳定', NULL, '强氧化剂、强酸、酰基氯、酸酐。', '光照、接触潮湿空气。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:43:05', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4821, 4956, '在干燥空气中稳定，遇水、酸、氧化剂会发生剧烈反应', NULL, '强氧化剂、强酸、水、潮湿空气', '避免接触水分、酸类、氧化剂；避免高温和火源', NULL, '不会发生聚合反应', NULL, '与水反应生成氢气、氢氧化钾和硼酸；与酸反应生成氢气和相应的硼酸盐', NULL, NULL, '2026-03-06 14:43:05', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4822, 4957, '稳定', NULL, '强氧化剂、水、醇类、酸类。', '接触潮湿空气。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:43:05', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4823, 4958, '在空气中自燃，遇水、醇类、酸类剧烈反应', NULL, NULL, '潮湿环境、高温、火源、静电、接触空气、接触水或含氧物质', NULL, NULL, NULL, '氢气、氧化铝、硼氧化物、硼酸', NULL, NULL, '2026-03-06 14:43:05', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4824, 4959, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、水、醇类、酸类、强碱', '接触潮湿空气、水、酸类', NULL, '不会发生聚合反应', NULL, '遇水或酸类分解放出氢气', NULL, NULL, '2026-03-06 14:43:07', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4825, 4960, '在空气中稳定', NULL, '碱类、金属粉末', '避免受热、避免与强碱、强氧化剂接触', NULL, '不会发生聚合反应', NULL, '受热分解产生有毒的硼氧化物烟雾', NULL, NULL, '2026-03-06 14:43:07', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4826, 4961, '稳定', NULL, '强氧化剂、强酸、水、潮湿空气', '避免接触潮湿空气、水、强氧化剂、强酸', NULL, '不会发生聚合反应', NULL, '遇水分解生成硼酸和甲醇，受热分解产生一氧化碳、二氧化碳、氧化硼等', NULL, NULL, '2026-03-06 14:43:07', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4827, 4962, '稳定', NULL, '强氧化剂、强酸。', '接触潮湿空气。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:43:07', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4828, 4963, '稳定', NULL, '强氧化剂、水、潮湿空气。', '接触潮湿空气。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:43:08', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4829, 4964, '无资料', NULL, '酸类、碱、卤素、酰基氯。', '无资料', NULL, '无资料', NULL, '无资料', NULL, NULL, '2026-03-06 14:43:09', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4830, 4965, '常温常压下稳定', NULL, '强氧化剂、强还原剂、强酸、强碱、易燃物、可燃物', NULL, NULL, NULL, NULL, '受热分解产生有毒的氮氧化物和钒氧化物烟雾', NULL, NULL, '2026-03-06 14:43:09', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4831, 4966, '在正确的使用和存储条件下是稳定的。常温常压下稳定。', NULL, '强氧化剂、还原剂、强酸、强碱、有机物', '不相容物质，热、火焰和火花，光照', NULL, '不会发生聚合反应', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。高温分解可能产生钒氧化物、钾氧化物等有毒烟雾。', NULL, NULL, '2026-03-06 14:43:09', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4832, 4967, '在正确的使用和存储条件下是稳定的。', NULL, '强还原剂、易燃物、有机物、硫、磷、金属粉末、酸类。', '不相容物质，热、火焰和火花。', NULL, '不会发生聚合反应。', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。高温分解可能产生碘化物、氧化物等。', NULL, NULL, '2026-03-06 14:43:09', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4833, 4968, '在正确的使用和存储条件下是稳定的', NULL, '强酸、强氧化剂、铝、锌、锡及其合金', '不相容物质，热、火焰和火花', NULL, '不会发生聚合反应', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。高温分解时可能产生氧化硅和氧化钠烟雾。', NULL, NULL, '2026-03-06 14:43:11', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4834, 4969, '在干燥空气中稳定，但具有强吸湿性。', NULL, '强碱、水、醇类、金属粉末、氧化剂。', '避免接触水、湿气、强碱、醇类。', NULL, '不能出现', NULL, '受热分解产生剧毒的氧化磷烟气（如五氧化二磷）。', NULL, NULL, '2026-03-06 14:43:11', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4835, 4970, '在正确的使用和存储条件下是稳定的', NULL, '强还原剂、易燃物、有机物、金属粉末、碱金属', '不相容物质，热、火焰和火花', NULL, '不会发生聚合反应', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物', NULL, NULL, '2026-03-06 14:43:11', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4836, 4971, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强酸、金属粉末、易燃物、有机物', '不相容物质，热、火焰和火花', NULL, '不会发生聚合反应', NULL, '受热分解产生有毒的砷氧化物和氧化钠气体', NULL, NULL, '2026-03-06 14:43:11', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4837, 4972, '在正确的使用和存储条件下是稳定的', NULL, '无资料', '不相容物质，热、火焰和火花', NULL, '无资料', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物', NULL, NULL, '2026-03-06 14:43:13', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4838, 4973, '稳定', NULL, '氧化剂、还原剂、碱类。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:43:13', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4839, 4974, '稳定', NULL, '强氧化剂。', '受热、接触潮湿空气。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:43:13', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4840, 4975, '在常温常压下化学性质稳定。作为多溴二苯醚类化合物，具有优异的热稳定性，可在较高温度下保持结构完整性。但在强紫外线照射、高温（>300℃）或强氧化剂作用下可能发生降解。长期暴露于光照条件下可能缓慢释放溴化氢', NULL, '强氧化剂（如过氧化氢、高锰酸钾、硝酸等）、强还原剂（如氢化铝锂、硼氢化钠）、强碱（如氢氧化钠、氢氧化钾）、活泼金属（如钠、钾、锂）、强酸（如浓硫酸、浓硝酸）。避免与胺类化合物、硫醇类、酚类物质接触', '避免暴露于高温环境（>200℃），防止热分解产生有毒的溴化氢和溴化芳烃化合物。避免强紫外线直接照射。避免与明火、火花和热源接触。避免产生粉尘积聚，防止粉尘爆炸。避免与不相容物质混合储存。避免长时间暴露在潮湿环境中', NULL, '不会发生聚合反应。七溴二苯醚为稳定的芳香族化合物，分子结构中不含可聚合的烯键或其他活性基团，在正常使用和储存条件下不会发生自聚或共聚反应', NULL, '高温热分解（>300℃）时可能产生：溴化氢（HBr）、二苯并二噁英（PBDDs）、二苯并呋喃（PBDFs）、多溴代苯酚、一氧化碳、二氧化碳、溴化芳烃化合物。光降解可能产生低溴代二苯醚。生物降解极其缓慢，可能产生脱溴产物。燃烧时产生黑色烟雾，含有溴化氢和其他有毒气体', NULL, NULL, '2026-03-06 14:43:13', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4841, 4976, '在正确的使用和存储条件下是稳定的', NULL, '无资料', '不相容物质，热、火焰和火花', NULL, '无资料', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物', NULL, NULL, '2026-03-06 14:43:14', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4842, 4977, '无资料', NULL, '无资料', '无资料', NULL, '无资料', NULL, '无资料', NULL, NULL, '2026-03-06 14:43:14', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4843, 4978, '稳定', NULL, '强氧化剂。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:43:14', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4844, 4979, '在正确的使用和存储条件下是稳定的', NULL, '无资料', '不相容物质，热、火焰和火花', NULL, '无资料', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物', NULL, NULL, '2026-03-06 14:43:16', '', NULL);
