INSERT INTO `msds_stability_reactivity` VALUES (4846, 4981, '在正确的使用和存储条件下是稳定的。', NULL, '还原剂、酸类、重金属化合物。', '不相容物质，热、火焰和火花。', NULL, '不能出现', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。', NULL, NULL, '2026-03-06 14:43:17', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4847, 4982, '不稳定', NULL, '酸类、水、醇类。', '接触潮湿空气、高温。', NULL, '不能出现', NULL, '遇水产生氢气。', NULL, NULL, '2026-03-06 14:43:17', '', NULL);
