INSERT INTO `msds_stability_reactivity` VALUES (4884, 5019, '稳定', NULL, '强酸、水、镁、氯甲酸盐、亚硝酸钠、亚硝酸钾。', '光照、潮湿空气', NULL, '不能出现', NULL, '遇酸或露置空气中能吸收水分和二氧化碳分解出剧毒的氰化氢气体。受热分解产生氰化氢、氮氧化物等有毒气体。', NULL, NULL, '2026-03-06 14:43:32', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4885, 5020, '在正确的使用和存储条件下是稳定的', NULL, '强酸、强氧化剂', '不相容物质，热、火焰和火花', NULL, '不能出现', NULL, '遇酸或露置空气中能吸收水分和二氧化碳分解出剧毒的氰化氢气体。受热分解产生氰化氢、氮氧化物等有毒气体。', NULL, NULL, '2026-03-06 14:43:32', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4886, 5021, '稳定', NULL, '强酸、水、镁、氯甲酸盐、亚硝酸钠、亚硝酸钾。', '潮湿空气、高温。', NULL, '不能出现', NULL, '遇酸或露置空气中能吸收水分和二氧化碳分解出剧毒的氰化氢气体。受高热分解，放出氮氧化物、氰化氢、铅等有毒气体。', NULL, NULL, '2026-03-06 14:43:32', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4887, 5022, '稳定', NULL, '强酸、水、镁、亚硝酸钠、亚硝酸钾、氯甲酸盐。', '潮湿空气、高温。', NULL, '不能出现', NULL, '遇酸或露置空气中能吸收水分和二氧化碳分解出剧毒的氰化氢气体。受热分解产生氰化氢、氮氧化物等有毒气体。', NULL, NULL, '2026-03-06 14:43:33', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4888, 5023, '稳定', NULL, '强氧化剂、强酸。', '光照、潮湿空气。', NULL, '不能出现', NULL, '遇酸或露置空气中能吸收水分和二氧化碳分解出剧毒的氰化氢气体。受热分解产生氰化氢、氮氧化物等有毒气体。', NULL, NULL, '2026-03-06 14:43:33', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4889, 5024, '稳定', NULL, '强氧化剂、碱类、酸类。', '受热、潮湿、光照。', NULL, '不能出现', NULL, '受热分解产生氰化氢（HCN）、溴化氢（HBr）、氮氧化物（NOx）、溴化物等剧毒气体。在潮湿环境中水解产生氰化氢和次溴酸。分解产物均具有剧毒性和强刺激性。', NULL, NULL, '2026-03-06 14:43:33', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4890, 5025, '稳定', NULL, '强氧化剂、强酸。', '避免接触的条件：明火、高热。', NULL, '无资料', NULL, '氰化氢、氧化氮。', NULL, NULL, '2026-03-06 14:43:35', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4891, 5026, '稳定', NULL, '强氧化剂、酸类。', '避免接触的条件：酸类、潮湿空气。', NULL, '不能出现', NULL, '氰化氢、氧化氮。', NULL, NULL, '2026-03-06 14:43:35', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4892, 5027, '稳定', NULL, '强酸。', '避免接触酸类、氧化剂。避免高温、明火。', NULL, NULL, NULL, '受热分解产生剧毒的氰化氢气体。', NULL, NULL, '2026-03-06 14:43:35', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4893, 5028, '在常温常压下稳定，但遇酸会分解释放出剧毒的氰化氢气体。', NULL, '强酸、强氧化剂、氯酸盐、亚硝酸盐等。', '避免接触酸类、高温、明火。避免产生粉尘。避免与氧化剂接触。', NULL, '不会发生聚合反应。', NULL, '受热或遇酸分解产生氰化氢、氧化氮、一氧化碳等有毒气体。', NULL, NULL, '2026-03-06 14:43:35', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4894, 5029, '稳定', NULL, '强氧化剂、强酸。', '光照、潮湿空气。', NULL, '不能出现', NULL, '遇酸或露置空气中能吸收水分和二氧化碳分解出剧毒的氰化氢气体。受热分解产生氰化氢、氮氧化物等有毒气体。', NULL, NULL, '2026-03-06 14:43:35', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4895, 5030, '稳定', NULL, '强酸、强氧化剂。', '光照、潮湿空气。', NULL, '不能出现', NULL, '遇酸或露置空气中能吸收水分和二氧化碳分解出剧毒的氰化氢气体。受热分解产生氰化氢、氮氧化物等有毒气体。', NULL, NULL, '2026-03-06 14:43:37', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4896, 5031, '稳定', NULL, '强氧化剂、强还原剂、强酸、强碱。', '光照、潮湿空气', NULL, '不能出现', NULL, '受潮或受高热分解释出剧毒的乙氰蒸气。受热分解产生氰化氢、氮氧化物等有毒气体。', NULL, NULL, '2026-03-06 14:43:37', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4897, 5032, '稳定', NULL, '强氧化剂、强还原剂、强酸、强碱。', '光照、潮湿空气', NULL, '不能出现', NULL, '受热分解产生氰化氢、氮氧化物等有毒气体。', NULL, NULL, '2026-03-06 14:43:37', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4898, 5033, '稳定', NULL, '强氧化剂。', '高温、明火', NULL, '不能出现', NULL, '受热分解产生氰化氢、氮氧化物等有毒气体。', NULL, NULL, '2026-03-06 14:43:38', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4899, 5034, '稳定', NULL, '强氧化剂、强酸、水、醇类。', '接触潮湿空气、高温', NULL, '不能出现', NULL, '受热分解产生氯化氢、氮氧化物等有毒气体。遇水或潮湿空气分解产生氯化氢。', NULL, NULL, '2026-03-06 14:43:38', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4900, 5035, '稳定', NULL, '强氧化剂、强酸、强还原剂、强碱。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:43:39', '', NULL);
