INSERT INTO `msds_stability_reactivity` VALUES (4930, 5065, '在干燥条件下稳定，但在潮湿空气中会水解。对热相对稳定，但在高温下可能分解。对光稳定，不易发生光解反应。', NULL, '强氧化剂、强碱、醇类、水、胺类、羧酸化合物。与这些物质接触可能发生剧烈反应，释放氯化氢气体。', '避免接触水分、潮湿空气和高温环境。避免与强氧化剂、强碱性物质和含羟基化合物接触。操作时应保持环境干燥，控制湿度在50%以下。', NULL, '不会发生聚合反应，但在特定条件下可能与含有活泼氢的化合物发生缩合反应。', NULL, '高温分解产生氯化氢气体、苯基自由基、硅氧化物和一氧化碳、二氧化碳等。水解产生氯化氢和苯基硅醇。', NULL, NULL, '2026-03-06 14:43:51', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4931, 5066, '稳定', NULL, '水、强氧化剂。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:43:51', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4932, 5067, '稳定', NULL, '强氧化剂。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:43:51', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4933, 5068, '稳定', NULL, '氧化剂、空气、水、氧、酸类、醇类。', '接触潮湿空气。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:43:53', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4934, 5069, '稳定', NULL, '强氧化剂。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:43:53', '', NULL);
