INSERT INTO `msds_stability_reactivity` VALUES (4951, 5086, '稳定', NULL, '强氧化剂、强碱。', '明火、高热、强氧化剂、强碱。', NULL, '不能出现', NULL, '一氧化碳、二氧化碳、氟化氢。', NULL, NULL, '2026-03-06 14:43:59', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4952, 5087, '稳定', NULL, '水、强酸、强氧化剂。', '避免受热、接触明火、避免与水、强酸、强氧化剂接触。', NULL, '不能出现', NULL, '遇水分解产生氟化氢；高温分解产生氟化氢、铋的氧化物等有毒气体。', NULL, NULL, '2026-03-06 14:44:00', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4953, 5088, '稳定', NULL, '还原剂、易燃或可燃物。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:44:01', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4954, 5089, '稳定', NULL, '水、碱类、氧化剂、氟、氧、硼烷。', '避免受热、接触明火、避免与水、碱类、氧化剂接触。', NULL, '不能出现', NULL, '遇水分解产生氟化氢和磷酸；高温分解产生氟化氢、氧化磷、磷化氢等有毒气体。', NULL, NULL, '2026-03-06 14:44:01', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4955, 5090, '稳定', NULL, '可燃物、还原剂、有机物、水、金属粉末、氢气、氨气等。', '避免受热、明火、摩擦、撞击。避免接触潮湿空气。', NULL, '不能出现', NULL, '氟化氢、氯化氢、氯气、氟气等。', NULL, NULL, '2026-03-06 14:44:01', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4956, 5091, '稳定', NULL, '水、胺类、醇类、碱类、金属粉末。', '避免接触潮湿空气、高温、明火。', NULL, '不能出现', NULL, '遇水分解产生氟化氢、硼酸。', NULL, NULL, '2026-03-06 14:44:01', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4957, 5092, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强碱、水、醇类', '不相容物质，热、火焰和火花', NULL, '无资料', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物', NULL, NULL, '2026-03-06 14:44:03', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4958, 5093, '在正确的使用和存储条件下是稳定的。', NULL, '强氧化剂、强碱、水、醇类。', '避免接触热源、火焰和火花。避免接触水分。', NULL, '不会发生聚合反应。', NULL, '受热分解产生氟化氢、氮氧化物、氧化硼等有毒气体。', NULL, NULL, '2026-03-06 14:44:03', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4959, 5094, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强碱、水、醇类、胺类、金属粉末、活性金属等。', '不相容物质，热、火焰和火花', NULL, '不会发生聚合反应。', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物', NULL, NULL, '2026-03-06 14:44:03', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4960, 5095, '在正确的使用和存储条件下是稳定的。', NULL, '强氧化剂、强碱、水、醇类。', '不相容物质，热、火焰和火花。', NULL, '不会发生', NULL, '受热分解产生氟化氢、氧化硼等有毒气体。', NULL, NULL, '2026-03-06 14:44:03', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4961, 5096, '在正确的使用和存储条件下是稳定的。遇水分解。', NULL, '强氧化剂、强碱、水、醇类、胺类。', '避免接触热源、火焰和火花。避免接触水分和潮湿空气。', NULL, '不会发生聚合反应。', NULL, '受热分解产生氟化氢、一氧化碳、二氧化碳、氧化硼等有毒气体。', NULL, NULL, '2026-03-06 14:44:03', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4962, 5097, '稳定', NULL, '酸类、强氧化剂。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:44:05', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4963, 5098, '稳定', NULL, '氧化剂、水、酸类、碱类。', '避免受热、接触明火、避免与水、酸类、氧化剂接触。避免潮湿空气。', NULL, '不能出现', NULL, '遇水分解产生氟化氢；高温分解产生氟化氢、氧化锑等有毒气体。', NULL, NULL, '2026-03-06 14:44:05', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4964, 5099, '稳定', NULL, '还原剂、易燃或可燃物、金属氧化物、金属及其卤化物、水、酸类。', '接触潮气可分解，遇水发生剧烈反应，产生剧毒的腐蚀性的氟化氢气体。', NULL, '不能出现', NULL, '氟化氢、溴化氢、氟化物、溴化物', NULL, NULL, '2026-03-06 14:44:05', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4965, 5100, '稳定', NULL, '强氧化剂、易燃或可燃物。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:44:05', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4966, 5101, '稳定', NULL, '强氧化剂、活性金属粉末、卤素。', '受热、光照、明火。', NULL, '能发生聚合反应，聚合反应放热，可能引起容器破裂。', NULL, '受热分解产生一氧化碳、二氧化碳、氟化氢、氯化氢等有毒气体。', NULL, NULL, '2026-03-06 14:44:06', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4967, 5102, '稳定', NULL, '碱类、强氧化剂、强还原剂。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:44:06', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4968, 5103, '稳定', NULL, '强氧化剂、强酸、强碱、水、醇类。', '接触潮气可分解。受热分解。', NULL, '不能出现', NULL, '受热分解产生氟化氢、一氧化碳、二氧化碳等有毒气体。', NULL, NULL, '2026-03-06 14:44:06', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4969, 5104, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强还原剂、强碱、金属粉末', '不相容物质，热、火焰和火花', NULL, '不会发生聚合反应', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。高温分解可能产生一氧化碳、二氧化碳、氟化氢、氧化铬等有毒气体。', NULL, NULL, '2026-03-06 14:44:08', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4970, 5105, '稳定', NULL, '强氧化剂、强酸、强碱。', '避免受热、明火、静电火花。避免与强氧化剂、强酸、强碱接触。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳、氟化氢等有毒有害气体。', NULL, NULL, '2026-03-06 14:44:08', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4971, 5106, '稳定', NULL, '强氧化剂、强酸。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:44:08', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4972, 5107, '稳定', NULL, '强还原剂、强酸、易燃或可燃物、水。', '接触潮湿空气。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:44:08', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4973, 5108, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强酸、强碱', '不相容物质，热、火焰和火花', NULL, '不会发生聚合反应', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。受热分解产生氧化硫、氧化锡烟雾。', NULL, NULL, '2026-03-06 14:44:08', '', NULL);
