INSERT INTO `msds_stability_reactivity` VALUES (4975, 5110, '在常温下稳定，但可被光、氧气或酸性条件下氧化。', NULL, '酸类、酰基氯、酸酐、强氧化剂。', '不相容物质，热、火焰和火花。', NULL, '无资料', NULL, '受热分解产生有毒的氮氧化物烟雾。', NULL, NULL, '2026-03-06 14:44:10', '', NULL);
