INSERT INTO `msds_stability_reactivity` VALUES (4989, 5124, '稳定', NULL, '酸类、强碱、强氧化剂、水、醇类、胺类。', '接触潮湿空气。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:44:15', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4990, 5125, '稳定', NULL, '易燃或可燃物、潮湿空气、碱类、氰化物、强还原剂。', '潮湿空气。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:44:15', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4991, 5126, '稳定', NULL, '水、潮湿空气、格利雅试剂。', '接触潮湿空气。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:44:17', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4992, 5127, '稳定', NULL, '强碱、强氧化剂、水、酸类、醇类、钾、钠、金属氧化物。', '潮湿空气。', NULL, '不能出现', NULL, '遇水猛烈分解，产生大量的热和浓烟，甚至爆炸，生成氯化氢、氧化磷、磷烷。与强碱、强氧化剂、酸类、醇类、钾、钠、金属氧化物接触可发生反应。对很多金属尤其是潮湿空气存在下有腐蚀性。', NULL, NULL, '2026-03-06 14:44:17', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4993, 5128, '稳定', NULL, '易燃或可燃物、碱类、水、醇类。', '潮湿空气。', NULL, '无聚合危害。', NULL, '高温分解产生氯化氢等有毒气体。', NULL, NULL, '2026-03-06 14:44:17', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4994, 5129, '在正确的使用和存储条件下是稳定的。但遇湿气、水分会分解。', NULL, '强氧化剂、强酸、水、潮湿空气。', '避免接触水、潮湿空气、强氧化剂、强酸。避免高温、明火。', NULL, '不会发生聚合反应。', NULL, '受热分解产生氯化氢、钼氧化物等有毒、腐蚀性气体。', NULL, NULL, '2026-03-06 14:44:17', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4995, 5130, '稳定', NULL, '水、碱、醇类、碱金属、强氧化剂。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:44:19', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4996, 5131, '稳定', NULL, '强氧化剂、强酸、水、胺类、卤化烃。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:44:19', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4997, 5132, '在正确的使用和存储条件下是稳定的', NULL, '无资料', '不相容物质，热、火焰和火花', NULL, '无资料', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物', NULL, NULL, '2026-03-06 14:44:19', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4998, 5133, '稳定', NULL, '强碱。', '潮湿空气。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:44:19', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (4999, 5134, '不稳定', NULL, '强氧化剂、水。', '空气、光照。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:44:19', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5000, 5135, '稳定', NULL, '强还原剂、水、醇类、碱类。', '潮湿空气、受热。', NULL, '不能出现', NULL, '氯化氢、氧化锑', NULL, NULL, '2026-03-06 14:44:21', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5001, 5136, '稳定', NULL, '强氧化剂、钾、钠。', '避免受热、避免接触强氧化剂', NULL, '不能出现', NULL, '氯化物、氧化铁', NULL, NULL, '2026-03-06 14:44:21', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5002, 5137, '在常温常压下稳定。', NULL, '强氧化剂、强碱、活性金属粉末、胺类等。', '高温、明火、静电、潮湿环境。', NULL, '不会发生聚合反应。', NULL, '受热分解产生一氧化碳、二氧化碳、氯化氢、光气等有毒气体。', NULL, NULL, '2026-03-06 14:44:22', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5003, 5138, '稳定', NULL, '碱类、铝。', '光照。', NULL, '不能出现', NULL, '受高热分解产生有毒的腐蚀性烟气（氯化氢、光气）。与碱类、铝接触可发生反应。对金属有强烈的腐蚀性。通常商品加有稳定剂（如乙醇）防止分解。', NULL, NULL, '2026-03-06 14:44:22', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5004, 5139, '稳定', NULL, '强氧化剂、强酸。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:44:22', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5005, 5140, '稳定', NULL, '硫酸、强还原剂、强氧化剂。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:44:22', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5006, 5141, '稳定', NULL, '强氧化剂、强碱、醇类、胺类、水。', '接触潮气可分解。避免受热。', NULL, '不能出现', NULL, '氯化氢、氧化钒。', NULL, NULL, '2026-03-06 14:44:22', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5007, 5142, '稳定', NULL, '强氧化剂、易燃或可燃物、铝。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:44:24', '', NULL);
