INSERT INTO `msds_stability_reactivity` VALUES (5031, 5166, '在正常储存和操作条件下稳定', NULL, '强氧化剂、活性金属粉末、强酸、强碱', '避免接触的条件：高温、明火、强氧化剂、强碱、强酸性物质、紫外线照射（基于结构相似化学品三氯乙烯估算）', NULL, '在特定条件下可能发生聚合，尤其是在有催化剂存在时', NULL, '受高热分解产生有毒的溴化氢气体和溴代烃类化合物', NULL, NULL, '2026-03-06 14:44:35', '', NULL);
