INSERT INTO `msds_stability_reactivity` VALUES (5034, 5169, '稳定', NULL, '热硝酸。', '受热。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:44:35', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5035, 5170, '稳定', NULL, '氨、卤素、氧、五氯化磷、氯化硫、硫、硫酸、水。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:44:37', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5036, 5171, '稳定。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:44:37', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5037, 5172, '稳定', NULL, '酸类、强氧化剂、卤素。', '避免接触明火、高热。避免与酸类、强氧化剂、卤素接触。避免受热分解。避免产生粉尘。', NULL, '不能出现', NULL, '若遇高热，升华产生剧毒的气体（氧化砷）。与酸类、强氧化剂、卤素接触可发生反应。', NULL, NULL, '2026-03-06 14:44:37', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5038, 5173, '稳定', NULL, '易燃或可燃物、强还原剂、活性金属粉末、硫、磷。', '潮湿空气。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:44:37', '', NULL);
