INSERT INTO `msds_stability_reactivity` VALUES (5098, 5233, '稳定', NULL, '强氧化剂、卤素、液氧。', '避免接触不相容物质，明火、高热。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳等有毒烟雾。', NULL, NULL, '2026-03-06 14:45:04', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5099, 5234, '稳定', NULL, '强氧化剂。', '避免接触不相容物质，明火、高热。', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳、硫化物等有毒烟雾。', NULL, NULL, '2026-03-06 14:45:04', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5100, 5235, '稳定', NULL, '强氧化剂、强酸、酸类。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:45:05', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5101, 5236, '稳定。在正常储存和使用条件下稳定。避免接触强氧化剂、强酸、强碱等不相容物质。应储存在阴凉、通风、干燥的环境中，远离火源和热源。', NULL, '强氧化剂（如过氧化物、高氯酸盐、高锰酸盐等）、强酸（如浓硫酸、浓硝酸、浓盐酸等）、强碱（如氢氧化钠、氢氧化钾等）。与这些物质接触可能发生剧烈反应，释放大量热量或产生有毒气体。', '避免高温、明火、火花、静电积聚。避免与强氧化剂、强酸、强碱等不相容物质接触。避免阳光直射。避免容器破损或泄漏。避免在密闭空间内大量积聚蒸气。', NULL, '不能出现。本品不会发生聚合反应。', NULL, '在高温或燃烧条件下，分解产物可能包括一氧化碳（CO）、二氧化碳（CO2）、苯、甲苯、二甲苯等有机化合物。在缺氧条件下燃烧可能产生炭黑。在高温分解时可能产生有毒的芳香族化合物。', NULL, NULL, '2026-03-06 14:45:05', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5102, 5237, '在正确的使用和存储条件下是稳定的。避免受热、光照和接触不相容物质。', NULL, '强氧化剂、强还原剂、强酸、强碱、金属粉末、胺类、酚类等', '不相容物质，热、火焰和火花，光照，摩擦、撞击', NULL, '可能发生聚合反应', NULL, '受热分解产生一氧化碳、二氧化碳、苯甲酸、叔丁醇等', NULL, NULL, '2026-03-06 14:45:05', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5103, 5238, '在正确的使用和存储条件下是稳定的。', NULL, '强氧化剂、强还原剂、强酸、强碱、金属粉末、重金属盐类、胺类、硫醇类等。', '不相容物质，热、火焰和火花。', NULL, '在适当的条件下可能发生自加速分解，需要控制储存温度，避免受热、摩擦、撞击。', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。', NULL, NULL, '2026-03-06 14:45:07', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5104, 5239, '在正确的使用和存储条件下是稳定的。在低温下储存，避免受热、光照和机械冲击。储存温度应低于30℃。', NULL, '强氧化剂、强还原剂、酸类、碱类、重金属化合物（如铜、铁、钴等）、胺类、硫醇类、过氧化物分解催化剂。', '避免受热、火焰、火花、摩擦、撞击、光照、静电放电。避免与不相容物质接触。避免在高温环境下储存和操作。', NULL, '本身为聚合引发剂，不会发生自聚合。但在特定条件下可能引发其他单体的聚合反应。', NULL, '受热分解可能产生二氧化碳、一氧化碳、叔丁醇、2-乙基己酸等产物。分解过程中可能释放热量，导致温度升高和压力增大。', NULL, NULL, '2026-03-06 14:45:08', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5105, 5240, '在正确的使用和存储条件下是稳定的。', NULL, '强氧化剂、还原剂、酸类、碱类、易燃物、有机物、金属粉末等。', '不相容物质，热、火焰和火花。避免受热、摩擦、撞击。', NULL, '不会发生聚合反应。', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。受热分解可能产生一氧化碳、二氧化碳等有害气体。', NULL, NULL, '2026-03-06 14:45:10', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5106, 5241, '在正确的使用和存储条件下是稳定的。', NULL, '强氧化剂、强还原剂、强酸、强碱、金属粉末', '不相容物质，热、火焰和火花。', NULL, '可能发生聚合反应', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。', NULL, NULL, '2026-03-06 14:45:10', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5107, 5242, '在常温常压下稳定。避免接触强氧化剂。受热分解产生有毒烟雾。遇明火、高热极易燃烧爆炸。', NULL, '强氧化剂（如高氯酸、高锰酸钾、过氧化氢、过氧化钠、过氧化钾、硝酸、浓硫酸、氯酸盐、高氯酸盐、过硫酸盐等）、强酸、强碱、活性金属（如钠、钾、镁、铝等）、卤素（如氟、氯、溴、碘）、卤代烃、硝酸盐、亚硝酸盐、过氧化物、有机过氧化物、金属氢化物、金属烷基化合物、金属卤化物等。', '避免受热、避免接触明火、避免接触高温表面、避免接触火花、避免接触静电、避免阳光直射、避免高温环境、避免接触强氧化剂、避免接触强酸、避免接触强碱、避免接触活性金属、避免接触卤素、避免接触卤代烃、避免接触硝酸盐、避免接触亚硝酸盐、避免接触过氧化物、避免接触有机过氧化物、避免接触金属氢化物、避免接触金属烷基化合物、避免接触金属卤化物、避免容器破损、避免泄漏、避免与不相容物质接触。', NULL, '不会发生聚合反应', NULL, '一氧化碳、二氧化碳、水蒸气、烷烃类气体、烯烃类气体、醛类、酮类、羧酸类、醇类、醚类、酯类等有机化合物。受热分解产生有毒烟雾，包括一氧化碳、二氧化碳、醛类、酮类等刺激性气体。燃烧产生大量黑烟和刺激性气体。分解产物可引起呼吸道刺激、头晕、恶心、头痛等症状。', NULL, NULL, '2026-03-06 14:45:11', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5108, 5243, '在正常储存和使用条件下稳定，但在空气中会缓慢氧化生成二硫化物。应储存在阴凉、通风、远离火源和氧化剂的环境中。', NULL, '强氧化剂（如高锰酸钾、过氧化氢、硝酸、过氧化钠等）、强酸（如硫酸、盐酸、硝酸等）、强碱（如氢氧化钠、氢氧化钾等）、碱金属（如钠、钾等）、卤素（如氯气、溴等）、酸酐、酰基氯、重金属化合物', '1. 避免高温、明火、火花、静电积聚；2. 避免与氧化剂、酸类、碱类接触；3. 避免长时间暴露在空气中（会缓慢氧化）；4. 避免阳光直射；5. 避免受潮（虽然对水不敏感，但应保持干燥）', NULL, '不会发生聚合反应', NULL, NULL, NULL, NULL, '2026-03-06 14:45:11', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5109, 5244, '在常温常压下稳定。遇水分解，放出氯化氢气体。遇碱发生中和反应。遇醇类、胺类等发生剧烈反应。遇金属粉末反应放出氢气。遇有机物、还原剂等发生反应。容器受热可能发生爆炸。', NULL, '强碱（如氢氧化钠、氢氧化钾、氨水等）、醇类（如乙醇、甲醇、异丙醇等）、胺类（如乙胺、丙胺、苯胺等）、活性金属（如钠、钾、镁、铝、锌等）、还原剂（如硫化物、亚硫酸盐等）、有机物（如苯、甲苯、丙酮等）、酸类、酸酐、氧化剂、卤代烃、硝酸盐、亚硝酸盐、碳酸盐、磷酸盐、硅酸盐、硼酸盐、氯化物、氟化物、溴化物、碘化物、硫酸盐、亚硫酸盐、硫代硫酸盐、连二亚硫酸盐、过硫酸盐、过氧化氢、过氧化钠、过氧化钾、高锰酸钾、重铬酸钾、氯酸盐、高氯酸盐等。', '避免受热、避免接触水分、避免接触潮湿空气、避免接触碱性物质、避免接触醇类、避免接触胺类、避免接触还原剂、避免接触活性金属、避免接触有机物、避免接触易燃物、避免接触可燃物、避免接触氧化剂、避免阳光直射、避免高温环境、避免潮湿环境、避免机械冲击、避免静电积聚、避免容器破损、避免泄漏。', NULL, '不会发生聚合反应', NULL, '氯化氢、氧化硅、一氧化碳、二氧化碳。分解产物均为强腐蚀性和刺激性气体，可引起严重的呼吸道损伤和肺水肿。受热分解产生氯化氢气体。与有机物反应可产生二氧化碳、一氧化碳等气体。与金属反应产生氢气。与醇类、胺类反应产生相应的有机硅化合物和氯化氢。', NULL, NULL, '2026-03-06 14:45:11', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5110, 5245, '在正确的使用和存储条件下是稳定的', NULL, '无资料', '不相容物质，热、火焰和火花', NULL, '无资料', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物', NULL, NULL, '2026-03-06 14:45:12', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5111, 5246, '在正确的使用和存储条件下是稳定的。热不稳定，加热易分解。', NULL, '还原剂、金属粉末、强酸、强碱、有机化合物、可燃物', '高温、热源、明火、火花、阳光直射、震动、摩擦', NULL, '不会发生危害聚合', NULL, '加热分解产生甲烷、乙烷等烃类化合物及氧气', NULL, NULL, '2026-03-06 14:45:12', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5112, 5247, '在正确的使用和存储条件下是稳定的。', NULL, '无资料', '不相容物质，热、火焰和火花。', NULL, '无资料', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。', NULL, NULL, '2026-03-06 14:45:12', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5113, 5248, '在正确的使用和存储条件下是稳定的。', NULL, '无资料', '不相容物质，热、火焰和火花。', NULL, '无资料', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。', NULL, NULL, '2026-03-06 14:45:12', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5114, 5249, '稳定', NULL, '强氧化剂、酸类、酰基氯、酸酐。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:45:13', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5115, 5250, '稳定', NULL, '强氧化剂、酸类', '高温、明火、静电', NULL, '不能出现', NULL, '一氧化碳、二氧化碳等', NULL, NULL, '2026-03-06 14:45:14', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5116, 5251, '稳定', NULL, '强氧化剂、酸类', '高温、明火、静电', NULL, '不能出现', NULL, '一氧化碳、二氧化碳等', NULL, NULL, '2026-03-06 14:45:14', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5117, 5252, '稳定', NULL, '强氧化剂、酸类', '高温、明火、静电', NULL, '不能出现', NULL, '一氧化碳、二氧化碳等', NULL, NULL, '2026-03-06 14:45:14', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5118, 5253, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强酸、强碱。', '避免受热、明火、火花。避免产生粉尘。', NULL, '不能出现', NULL, '一氧化碳、二氧化碳、氧化锰。', NULL, NULL, '2026-03-06 14:45:14', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5119, 5254, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强酸、强碱。', '避免受热、明火、火花。避免产生粉尘。', NULL, '不能出现', NULL, '一氧化碳、二氧化碳、氧化锌。', NULL, NULL, '2026-03-06 14:45:14', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5120, 5255, '稳定', NULL, '强氧化剂、强碱。', '接触潮湿空气。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:45:16', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5121, 5256, '稳定', NULL, '强氧化剂、水。', '接触潮气可分解。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:45:16', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5122, 5257, '稳定', NULL, '强氧化剂。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:45:16', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5123, 5258, '稳定', NULL, '强氧化剂、强酸、卤素。', '避免受热、明火', NULL, '不能出现', NULL, '一氧化碳、二氧化碳、氧化氮、氧化磷、氟化氢', NULL, NULL, '2026-03-06 14:45:16', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5124, 5259, '在正确的使用和存储条件下是稳定的。', NULL, '强氧化剂、强还原剂、酸类、碱类、金属粉末、有机胺类', '不相容物质，热、火焰和火花。', NULL, '不会发生聚合反应', NULL, '受热分解产生二氧化碳、水蒸气、有机酸等', NULL, NULL, '2026-03-06 14:45:18', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5125, 5260, '在正确的使用和存储条件下是稳定的。该物质为有机过氧化物，具有氧化性，遇热、摩擦、撞击或与还原剂接触可能发生分解。', NULL, '强还原剂、有机物、金属粉末、酸类、碱类、易（可）燃物。', '避免受热、摩擦、撞击、明火、火花。避免与不相容物质接触。', NULL, '不会发生聚合反应。', NULL, '受热分解产生一氧化碳、二氧化碳、氧化硫、氧化氮、硫化物等有毒有害气体。', NULL, NULL, '2026-03-06 14:45:18', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5126, 5261, '稳定', NULL, '强氧化剂、强酸。', '无资料', NULL, '能发生', NULL, '无资料', NULL, NULL, '2026-03-06 14:45:18', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5127, 5262, '稳定', NULL, '强氧化剂、强酸、铜、锌。', '高温、明火、氧化剂', NULL, '不能出现', NULL, '受热分解产生氮氧化物、氨气等有毒气体。', NULL, NULL, '2026-03-06 14:45:18', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5128, 5263, '稳定', NULL, '强氧化剂、强酸、强碱。', '高温、明火、氧化剂', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳等气体。', NULL, NULL, '2026-03-06 14:45:18', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5129, 5264, '稳定', NULL, '强氧化剂、强碱、潮湿空气。', '光照', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳等气体。', NULL, NULL, '2026-03-06 14:45:20', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5130, 5265, '在正确的使用和存储条件下是稳定的', NULL, '不相容物质、强氧化剂、强酸、强碱', '不相容物质、热、火焰和火花', NULL, '不能出现', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。受热分解产生一氧化碳、二氧化碳、氮氧化物、汞蒸气等有毒气体。', NULL, NULL, '2026-03-06 14:45:20', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5131, 5266, '在正确的使用和存储条件下是稳定的', NULL, '不相容物质、强氧化剂、强酸、强碱', '不相容物质、热、火焰和火花', NULL, '不能出现', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。受热分解产生一氧化碳、二氧化碳、氮氧化物等有毒气体。', NULL, NULL, '2026-03-06 14:45:20', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5132, 5267, '稳定', NULL, '强氧化剂、强酸、强碱。', '高温、明火、氧化剂', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳等气体。', NULL, NULL, '2026-03-06 14:45:20', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5133, 5268, '稳定', NULL, '强氧化剂、强酸、强碱。', '高温、明火、氧化剂', NULL, '不能出现', NULL, '受热分解产生氮氧化物等有毒气体。', NULL, NULL, '2026-03-06 14:45:21', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5134, 5269, '无资料', NULL, '无资料', '无资料', NULL, '无资料', NULL, '火中伴生毒气', NULL, NULL, '2026-03-06 14:45:22', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5135, 5270, '稳定', NULL, '强氧化剂、强酸。', '光照。', NULL, '不能出现', NULL, '一氧化碳、二氧化碳、锡、氧化锡、苯等有机化合物', NULL, NULL, '2026-03-06 14:45:22', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5136, 5271, '稳定', NULL, '强氧化剂、强碱、潮湿空气。', '接触潮气可分解。', NULL, '不能出现', NULL, '受热分解产生碘化氢、氧化锡等有毒有害气体。', NULL, NULL, '2026-03-06 14:45:22', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5137, 5272, '稳定', NULL, '强氧化剂、强酸、二氧化碳。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:45:22', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5138, 5273, '在正确的使用和存储条件下是稳定的。在乙醚、甲醇、乙醇等有机溶剂中较为稳定。', NULL, '强氧化剂、酸类、重金属及其盐类', '不相容物质、热、火焰和火花', NULL, '不会发生聚合反应', NULL, '受热分解产生磷氧化物、一氧化碳、二氧化碳等有毒气体', NULL, NULL, '2026-03-06 14:45:22', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5139, 5274, '稳定', NULL, '强氧化剂。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:45:24', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5140, 5275, '不稳定', NULL, '强还原剂、易燃或可燃物、空气、氧。', '无资料', NULL, '不能出现', NULL, '氮氧化物、氟化氢', NULL, NULL, '2026-03-06 14:45:24', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5141, 5276, '稳定', NULL, '强酸、强碱、水、醇类、胺类、金属粉末、易燃或可燃物。', '避免受热、明火、火花、静电积聚。避免与水、醇类、胺类、强酸、强碱接触。避免与金属粉末接触。避免潮湿环境。', NULL, '不能出现', NULL, '遇水分解产生氟化氢和硅酸。高温分解可能产生四氟化硅、氟化氢等有毒气体。', NULL, NULL, '2026-03-06 14:45:24', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5142, 5277, '稳定', NULL, '潮湿空气、酸类、活性金属粉末。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:45:24', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5143, 5278, '在正确的使用和存储条件下是稳定的', NULL, '强酸、强碱、水、醇类、胺类、金属粉末、易燃或可燃物、还原剂。', '避免受热、明火、火花、静电积聚。避免与水、醇类、胺类、强酸、强碱接触。避免与金属粉末接触。避免潮湿环境。', NULL, '不能出现', NULL, '高温分解可产生氟化氢、铅氧化物等有毒有害气体。', NULL, NULL, '2026-03-06 14:45:25', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5144, 5279, '稳定', NULL, '强氧化剂、强酸、水。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:45:26', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5145, 5280, '稳定', NULL, '强氧化剂、易燃或可燃物。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:45:26', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5146, 5281, '在正确的使用和存储条件下（低温、避光、防潮）相对稳定，但具有热不稳定性，受热、撞击、摩擦可能引起爆炸。', NULL, '强氧化剂、强酸、强碱、金属粉末、易燃或可燃物、还原剂、胺类、酚类、硫化物、重金属盐。', '避免受热、明火、火花、静电积聚、撞击、摩擦。避免与强氧化剂、强酸、强碱、金属粉末、易燃或可燃物、还原剂接触。避免潮湿环境。避免光照。避免高温环境。', NULL, '不能出现', NULL, '高温分解可产生氮气、氟化氢、苯衍生物等有毒有害气体。分解可能产生爆炸性气体。', NULL, NULL, '2026-03-06 14:45:26', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5147, 5282, '稳定', NULL, '强氧化剂、易燃或可燃物、金属粉末、铜、铝等。', '避免受热、明火、火花、静电积聚。避免与强氧化剂、易燃或可燃物接触。避免接触金属催化剂。', NULL, '能发生。受热或在催化剂作用下可发生聚合反应，放出大量热量，有爆炸危险。必须添加稳定剂抑制聚合。', NULL, '高温分解可产生一氧化碳、二氧化碳、氟化氢等有毒有害气体。', NULL, NULL, '2026-03-06 14:45:26', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5148, 5283, '稳定', NULL, '强氧化剂、强酸。', '无资料', NULL, '不能出现', NULL, '受热分解产生一氧化碳、二氧化碳、氧化铅等有毒烟雾。', NULL, NULL, '2026-03-06 14:45:27', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5149, 5284, '稳定', NULL, '强氧化剂。', '无资料', NULL, '不能出现', NULL, '一氧化碳、二氧化碳、氧化锡。', NULL, NULL, '2026-03-06 14:45:27', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5150, 5285, '在正确的使用和存储条件下是稳定的', NULL, '无资料', '不相容物质，热、火焰和火花', NULL, '无资料', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物', NULL, NULL, '2026-03-06 14:45:28', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5151, 5286, '稳定', NULL, '强氧化剂。', '无资料', NULL, '不能出现', NULL, '一氧化碳、二氧化碳、氧化磷', NULL, NULL, '2026-03-06 14:45:28', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5152, 5287, '稳定', NULL, '强氧化剂、强碱、钾、钠。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:45:28', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5153, 5288, '稳定', NULL, '强碱、氨。', '接触潮湿空气。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:45:28', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5154, 5289, '无资料', NULL, '无资料', '水、光、潮湿空气', NULL, '无资料', NULL, '无资料', NULL, NULL, '2026-03-06 14:45:29', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5155, 5290, '稳定', NULL, '水、胺类、醇类、酸类、酯类、酮。', '潮湿空气。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:45:29', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5156, 5291, '稳定', NULL, '强氧化剂、醇类、水、强碱。', '潮湿空气。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:45:29', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5157, 5292, '在干燥、低温条件下相对稳定，但遇水或水蒸气会迅速分解，受热也会分解。', NULL, '强氧化剂、水、潮湿空气、碱类、活性金属粉末、醇类、胺类、醚类。', '避免受热、明火、火花、静电积聚、撞击、摩擦。避免与水、潮湿空气、强氧化剂、碱类、活性金属粉末接触。避免高温环境。', NULL, '不能出现', NULL, '高温分解或遇水分解可产生氯化氢、二氧化硫、氯气等有毒有害气体。分解可能产生腐蚀性气体。', NULL, NULL, '2026-03-06 14:45:29', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5158, 5293, '不稳定', NULL, '水、醇类、碱类、氧化剂、易燃物。', '接触潮湿空气、受热、阳光直射。', NULL, '不能出现', NULL, '加热分解为二氯化铅和氯气。遇水反应生成二氧化铅和氯化氢。', NULL, NULL, '2026-03-06 14:45:30', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5159, 5294, '在干燥、低温条件下相对稳定，但遇水或水蒸气会剧烈反应，受热也会分解。', NULL, '强氧化剂、水、潮湿空气、强碱、活性金属粉末、醇类、胺类、醚类。', '避免受热、明火、火花、静电积聚、撞击、摩擦。避免与水、潮湿空气、强氧化剂、强碱、活性金属粉末接触。避免高温环境。避免在潮湿环境中储存。', NULL, '不能出现', NULL, '高温分解或遇水分解可产生氯化氢、二氧化钛、氯气等有毒有害气体。分解可能产生腐蚀性气体。', NULL, NULL, '2026-03-06 14:45:31', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5160, 5295, '在正确的使用和存储条件下是稳定的，但遇水或潮湿空气会分解', NULL, '水、潮湿空气、碱类、醇类、氧化剂、金属粉末', '避免接触水、潮湿空气、热源、火焰和火花', NULL, '无资料', NULL, '遇水或受热分解产生氯化氢、硒化合物、硒氧化物等有毒物质', NULL, NULL, '2026-03-06 14:45:31', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5161, 5296, '稳定', NULL, '强碱、易燃或可燃物、水、醇类。', '潮湿空气。', NULL, '不能出现', NULL, '无资料（高温下可能分解产生氯化氢和氧化锡）', NULL, NULL, '2026-03-06 14:45:31', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5162, 5297, '在常温常压下稳定，但与湿气或水接触时可能分解。', NULL, '强酸、强碱、氧化剂。', '避免接触火源、高温、潮湿环境。', NULL, '不会发生聚合反应。', NULL, '受高热分解产生有毒的氯化物烟雾。', NULL, NULL, '2026-03-06 14:45:31', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5163, 5298, '稳定', NULL, '强氧化剂、水、醇类、碱类。', '潮湿空气。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:45:32', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5164, 5299, '在正确的使用和存储条件下是稳定的', NULL, '无资料（建议避免与强氧化剂、强碱、胺类、醇类直接接触，可能发生剧烈反应）', '不相容物质，热、火焰和火花', NULL, '无资料（基于结构分析，本品在正常使用条件下不会发生聚合反应）', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物', NULL, NULL, '2026-03-06 14:45:32', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5165, 5300, '在正确的使用和存储条件下是稳定的', NULL, '无资料（建议避免与强氧化剂、强酸、强碱、还原剂接触，重氮化合物对光热敏感）', '避免接触不相容物质、热、火焰、火花、强光和振动，储存温度不应高于35℃', NULL, '无资料（建议评估重氮基团的聚合可能性，通常在特定条件下可能发生）', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物', NULL, NULL, '2026-03-06 14:45:32', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5166, 5301, '稳定', NULL, '强碱、活性金属粉末、碱金属。', '无资料', NULL, '能发生', NULL, '无资料', NULL, NULL, '2026-03-06 14:45:32', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5167, 5302, '稳定', NULL, '酸类、酸酐、强氧化剂、二氧化碳。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:45:32', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5168, 5303, '不稳定', NULL, '氧化剂、强酸。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:45:34', '', NULL);
