INSERT INTO `msds_stability_reactivity` VALUES (5173, 5308, '稳定', NULL, '强氧化剂、水、潮湿空气、强还原剂、强酸、强碱。', '接触潮气可分解。', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:45:35', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5174, 5309, '稳定', NULL, '强氧化剂、强还原剂、强碱、活性金属粉末、铜。', '受热。', NULL, '不能出现', NULL, '受热分解产生有毒的氮氧化物气体。', NULL, NULL, '2026-03-06 14:45:35', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5175, 5310, '不稳定', NULL, '还原剂、强氧化剂、起爆器材。', '受热、震动、撞击、摩擦。', NULL, '不能出现', NULL, '一氧化碳、二氧化碳、氮氧化物。', NULL, NULL, '2026-03-06 14:45:35', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5176, 5311, '在正常的储存和使用条件下是稳定的。', NULL, '强氧化剂、强酸。', '明火、高热、强氧化剂。', NULL, '不会发生聚合反应。', NULL, '受热分解产生溴化氢、一氧化碳、二氧化碳等有毒气体。', NULL, NULL, '2026-03-06 14:45:35', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5177, 5312, '稳定。在常温常压下稳定。', NULL, '强氧化剂、强碱、活泼金属（如钠、钾、锂）、强还原剂。', '光照、高温、明火、热源。避免与不相容物质接触。', NULL, '不会发生聚合反应。', NULL, '加热分解产生有毒的溴化氢（HBr）、一氧化碳（CO）、二氧化碳（CO2）和溴气（Br2）。', NULL, NULL, '2026-03-06 14:45:37', '', NULL);
