INSERT INTO `msds_stability_reactivity` VALUES (5179, 5314, '常温常压下稳定', NULL, '强氧化剂、强酸、强碱、酰氯、酸酐、重金属盐类。', '避免接触明火、高热、氧化剂、强酸、强碱。避免受热分解。避免与空气中的水分接触。', NULL, '不会发生聚合反应', NULL, '一氧化碳、二氧化碳、氮氧化物、氨等有毒气体', NULL, NULL, '2026-03-06 14:45:37', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5180, 5315, '稳定', NULL, '强还原剂、易燃或可燃物。', '无资料', NULL, '不能出现', NULL, '无资料', NULL, NULL, '2026-03-06 14:45:37', '', NULL);
INSERT INTO `msds_stability_reactivity` VALUES (5181, 5316, '稳定。常温下分解为二氧化氮。', NULL, NULL, '受热、明火、阳光直射、震动、摩擦。', NULL, '不会发生聚合反应。', NULL, '二氧化氮(NO₂)、一氧化氮(NO)、氧气(O₂)等。', NULL, NULL, '2026-03-06 14:45:38', '', NULL);
