INSERT INTO `msds_stability_reactivity` VALUES (5266, 5401, '稳定', NULL, '强氧化剂、酸类、碱类。', '避免接触火源、热源、强氧化剂、酸类、碱类。', NULL, '不能出现', NULL, '高温分解产生氧化硒、二氧化硒等有毒气体。', NULL, NULL, '2026-03-06 14:46:05', '', NULL);
