INSERT INTO `msds_stability_reactivity` VALUES (5270, 5405, '在正确的使用和存储条件下是稳定的', NULL, '强氧化剂、强酸', '不相容物质、热、火焰和火花', NULL, '不会发生', NULL, '在正常的储存和使用条件下，不会产生危险的分解产物。高温分解产生氧化硒、硒化物等有毒烟雾。', NULL, NULL, '2026-03-06 14:46:07', '', NULL);
