INSERT INTO `msds_toxicological` VALUES (2892, 3029, '无资料（关键安全数据缺失，建议开展急性经口毒性测试）\n        参考结构相似有机过氧化物：约2000 mg/kg（大鼠，估算值）\n        无资料（关键安全数据缺失，建议开展急性吸入毒性测试）', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_toxicological` VALUES (2893, 3030, '中等毒性。大鼠经口LD50：约500-2000 mg/kg（基于有机过氧化物类似物估算）。兔经皮LD50：>2000 mg/kg（低毒性，但可能引起皮肤刺激）。大鼠吸入LC50(4h)：约5-20 mg/L（估算值，高浓度可能引起呼吸道刺激）。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_toxicological` VALUES (2894, 3031, 'LC50：>200000mg/m3（大鼠吸入，4h）。短时间暴露在极高浓度可导致麻醉和心律异常。', NULL, NULL, '>200000mg/m3（大鼠吸入，4h）。短时间暴露在极高浓度可导致麻醉和心律异常。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
