INSERT INTO `msds_toxicological` VALUES (2897, 3034, '大鼠经口LD50：251mg/kg；小鼠经口LD50：580mg/kg；大鼠经皮LD50：>2000mg/kg。急性中毒主要表现为胃肠道刺激症状、中枢神经系统抑制、肝肾功能损害等。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
