INSERT INTO `msds_toxicological` VALUES (2899, 3036, 'LD50：43000mg/kg(大鼠经口)；LD50：35000mg/kg(兔经皮，估算值)；LC50：>50000ppm，4小时(大鼠吸入)。急性中毒主要表现为中枢神经系统抑制、麻醉作用，高浓度接触可引起心律不齐、心血管系统毒性作用。', 'LD50：43000mg/kg(大鼠经口)', '35000mg/kg(兔经皮，估算值)', '>50000ppm，4小时(大鼠吸入)。急性中毒主要表现为中枢神经系统抑制、麻醉作用，高浓度接触可引起心律不齐、心血管系统毒性作用。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
