INSERT INTO `msds_toxicological` VALUES (2903, 3040, 'LD50：176mg／kg(大鼠经口)；80mg／kg(兔经皮)LC50：无资料', 'LD50：176mg／kg(大鼠经口)', '80mg／kg(兔经皮)', '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_toxicological` VALUES (2904, 3041, '参考同类醚类物质，对大鼠经口LD50>2000mg/kg；对大鼠吸入LC50>5000ppm，4小时。急性中毒主要表现为中枢神经系统抑制、麻醉作用，可引起头痛、头晕、恶心、呕吐、倦睡、不安等症状。高浓度接触可引起肝、肾功能损害。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_toxicological` VALUES (2905, 3042, '参考同类醚类物质，对大鼠经口LD50>5000mg/kg。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_toxicological` VALUES (2906, 3043, '低毒性。大鼠经口LD50：12918mg/kg（基于现有数据）。兔经皮LD50：>2000mg/kg（低毒性，但可能引起皮肤刺激）。大鼠吸入LC50(4h)：约10-50mg/L（估算值，高浓度可能引起呼吸道刺激）。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_toxicological` VALUES (2907, 3044, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_toxicological` VALUES (2908, 3045, '参考同类有机过氧化物混合物，对大鼠经口LD50>2000mg/kg；对大鼠吸入LC50>5000mg/m3，4小时。急性中毒主要表现为对眼睛、皮肤和呼吸道的刺激作用，可引起头痛、头晕、恶心、呕吐等症状。高浓度接触可能对肝、肾造成损害。有机过氧化物可能引起皮肤过敏反应。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
