INSERT INTO `msds_toxicological` VALUES (3065, 3206, '无资料（基于结构相似卤代烷烃类化合物数据，1-氯戊烷的急性毒性估算：经口LD50（大鼠）约为2000-4000 mg/kg，参考1-氯丁烷LD50为2670 mg/kg，考虑到碳链长度增加1个碳原子，毒性可能略有降低；经皮LD50（大鼠）约为3000-6000 mg/kg，参考卤代烷烃类化合物经皮毒性数据；吸入LC50（大鼠，4小时）约为20-40 mg/L，参考1-氯丙烷LC50约为30-50 mg/L，1-氯丁烷LC50约为32 mg/L，考虑到碳链长度增加，挥发性降低，吸入毒性可能略有降低。建议通过实验测定获得准确数据，方法可参考OECD TG 401（经口）、TG 402（经皮）、TG 403（吸入）标准。）', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
