INSERT INTO `msds_toxicological` VALUES (3428, 3571, '大鼠经口LD50：约260-800mg/kg（苯基氨基甲酸酯类参考值）；大鼠经皮LD50：约1000-5000mg/kg；吸入LC50：无资料。氨基甲酸酯类杀虫剂通过抑制体内乙酰胆碱酯酶活性，导致乙酰胆碱在突触间隙过量蓄积，引起毒蕈碱样、烟碱样和中枢神经系统症状。', NULL, NULL, '无资料。氨基甲酸酯类杀虫剂通过抑制体内乙酰胆碱酯酶活性，导致乙酰胆碱在突触间隙过量蓄积，引起毒蕈碱样、烟碱样和中枢神经系统症状。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
