INSERT INTO `msds_toxicological` VALUES (4327, 4471, '高毒（基于钡化合物的高毒性，口服LD50估算值约为200-500 mg/kg）\n        高毒（基于钡化合物的高毒性，经皮LD50估算值约为500-1000 mg/kg）\n        高毒（吸入粉尘可导致严重呼吸道损伤和系统性毒性）', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_toxicological` VALUES (4328, 4472, 'LD50：58mg/kg(小鼠腹腔内)。根据LD50值判断，本品为高毒性物质。无资料（建议开展急性经口毒性测试，方法参考OECD TG 425）\n        无资料（建议开展急性经皮毒性测试，方法参考OECD TG 402）\n        迅速脱离现场至空气新鲜处。保持呼吸道通畅。如呼吸困难，给输氧。如呼吸停止，立即进行人工呼吸。就医。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_toxicological` VALUES (4329, 4473, 'LD50：无资料。LC50：无资料。高氯酸钙毒性较低，但长期接触可能引起甲状腺功能减退。', NULL, NULL, '无资料。高氯酸钙毒性较低，但长期接触可能引起甲状腺功能减退。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_toxicological` VALUES (4330, 4474, 'LD50: 1500-3000 mg/kg (大鼠经口) - 基于高氯酸锂和锂化合物特性估算\n        LD50: >2000 mg/kg (大鼠经皮) - 基于高氯酸锂和锂化合物特性估算\n        LC50: 无资料 - 建议进行急性吸入毒性测试(方法参考OECD TG 403)', NULL, '2000 mg/kg (大鼠经皮)', '无资料 - 建议进行急性吸入毒性测试(方法参考OECD TG 403)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_toxicological` VALUES (4331, 4475, 'LD50：1500mg/kg(小鼠腹腔内)。LC50：无资料。根据LD50值判断，本品为低毒性物质。', NULL, NULL, '无资料。根据LD50值判断，本品为低毒性物质。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_toxicological` VALUES (4332, 4476, 'LD50：2100mg/kg(大鼠经口)。LC50：无资料。根据LD50值判断，本品为低毒性物质。长期接触可能引起甲状腺功能减退。', 'LD50：2100mg/kg(大鼠经口)', NULL, '无资料。根据LD50值判断，本品为低毒性物质。长期接触可能引起甲状腺功能减退。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_toxicological` VALUES (4333, 4477, 'LD50: 1000-2000 mg/kg (大鼠经口) - 基于铅化合物毒性估算\n        LD50: >2000 mg/kg (大鼠经皮) - 基于铅化合物特性估算\n        LC50: 2-5 mg/L (大鼠吸入，4小时) - 基于铅化合物毒性估算', NULL, '2000 mg/kg (大鼠经皮)', '2-5 mg/L (大鼠吸入，4小时) - 基于铅化合物毒性估算', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_toxicological` VALUES (4334, 4478, 'LD50: >2000 mg/kg (大鼠经口) - 基于高氯酸银和银化合物特性估算\n        LD50: >2000 mg/kg (大鼠经皮) - 基于高氯酸银和银化合物特性估算\n        LC50: 无资料 - 建议进行急性吸入毒性测试(方法参考OECD TG 403)', NULL, '2000 mg/kg (大鼠经皮)', '无资料 - 建议进行急性吸入毒性测试(方法参考OECD TG 403)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_toxicological` VALUES (4335, 4479, 'LD50：无资料。LC50：无资料。高锰酸钡含有剧毒的钡离子，毒性极高。钡化合物可导致肌肉麻痹、心律失常、呼吸衰竭等严重症状，口服致死量约为1-15g。', NULL, NULL, '无资料。高锰酸钡含有剧毒的钡离子，毒性极高。钡化合物可导致肌肉麻痹、心律失常、呼吸衰竭等严重症状，口服致死量约为1-15g。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_toxicological` VALUES (4336, 4480, 'LD50：1090mg/kg（大鼠经口，参考高锰酸钾数据）；LD50：约2000mg/kg（大鼠经皮，参考高锰酸钾数据）；LC50：无资料。', NULL, NULL, '无资料。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_toxicological` VALUES (4337, 4481, 'LD50：1090mg/kg(大鼠经口)。LC50：无资料。根据LD50值判断，本品为中等毒性物质。高锰酸钾纯品致死量约为10g。', 'LD50：1090mg/kg(大鼠经口)', NULL, '无资料。根据LD50值判断，本品为中等毒性物质。高锰酸钾纯品致死量约为10g。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_toxicological` VALUES (4338, 4482, 'LD50：1090mg/kg(大鼠经口)。LC50：无资料。根据LD50值判断，本品为中等毒性物质。', 'LD50：1090mg/kg(大鼠经口)', NULL, '无资料。根据LD50值判断，本品为中等毒性物质。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
