INSERT INTO `msds_toxicological` VALUES (4657, 4803, '急性毒性：大鼠吸入LC50：2000ppm/4h；小鼠吸入LC50：2000ppm/4h。本品对眼睛、皮肤、粘膜和呼吸道有强烈的刺激作用。', NULL, NULL, '2000ppm/4h', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_toxicological` VALUES (4658, 4804, '大鼠经口LD50：约200 mg/kg；大鼠吸入LC50：约500 mg/m³（4小时）；小鼠经口LD50：约150 mg/kg。急性毒性数据表明该物质具有中等毒性。', NULL, NULL, '约500 mg/m³（4小时）', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_toxicological` VALUES (4659, 4805, 'LD50：LC50：11200mg／m3 4小时(大鼠吸入)', NULL, NULL, '11200mg／m3 4小时(大鼠吸入)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
