INSERT INTO `msds_toxicological` VALUES (4664, 4810, '大鼠经口LD50：2000mg/kg；小鼠吸入LC50：95g/m³，2小时。对眼睛、皮肤和呼吸道有刺激性。', NULL, NULL, '95g/m³，2小时。对眼睛、皮肤和呼吸道有刺激性。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_toxicological` VALUES (4665, 4811, '吸入高浓度可引起头痛、头晕、无力、恶心、呕吐、呼吸困难、呼气蒜臭味、口内金属味等症状，严重时肝、肾受损。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_toxicological` VALUES (4666, 4812, 'LD50：5790mg/kg(兔静脉)。LC50：未确定。纯品基本无毒，但若混杂低氟化硫、氟化氢，特别是十氟化硫时，则毒性显著增强。', NULL, NULL, '未确定。纯品基本无毒，但若混杂低氟化硫、氟化氢，特别是十氟化硫时，则毒性显著增强。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_toxicological` VALUES (4667, 4813, '剧毒。大鼠吸入LC50：0.12mg/m3/4h；小鼠吸入LC50：0.15mg/m3/4h。对粘膜有强烈刺激作用。动物吸入引起呼吸困难，可因肺水肿而致死。', NULL, NULL, '0.12mg/m3/4h', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_toxicological` VALUES (4668, 4814, '剧毒。六氟化铀具有放射性和化学毒性双重危害。急性毒性数据：大鼠吸入LC50：0.3 mg/m3（4小时）；小鼠吸入LC50：0.2 mg/m3（4小时）；大鼠经口LD50：未测定（因遇水分解）；小鼠经口LD50：未测定（因遇水分解）；兔经皮LD50：未测定（因遇水分解）。急性中毒症状：吸入后立即出现剧烈咳嗽、呼吸困难、胸痛、发绀、肺水肿。严重病例出现蛋白尿、氮质血症、急性肾功能衰竭。对眼有强烈刺激性，接触后立即出现剧烈疼痛、流泪、畏光，严重时角膜上皮坏死脱落形成溃疡，可导致失明。可致皮肤灼伤，接触部位出现红肿、水泡、坏死。六氟化铀遇水分解产生剧毒的氟化氢气体，可引起严重的化学灼伤和系统性氟中毒。氟化氢中毒可导致低钙血症、心律失常、呼吸衰竭甚至死亡。放射性危害：急性放射病、骨髓抑制、免疫功能下降。', NULL, NULL, '0.3 mg/m3（4小时）', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_toxicological` VALUES (4669, 4815, '属低毒类。大鼠吸入LC50：>2000ppm/4h；小鼠吸入LC50：>2000ppm/4h。本品主要危险是窒息，在高浓度环境下可引起缺氧。', NULL, NULL, '>2000ppm/4h', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_toxicological` VALUES (4670, 4816, 'LD50：大鼠经口：2000mg/kg；小鼠经口：1800mg/kg；大鼠经皮：>2000mg/kg', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_toxicological` VALUES (4671, 4817, '具刺激作用。大鼠经口LD50：约5g/kg；大鼠吸入LC50：约50g/m³/4h。急性毒性较低，但高浓度接触可引起中枢神经系统抑制。', NULL, NULL, '约50g/m³/4h。急性毒性较低，但高浓度接触可引起中枢神经系统抑制。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
