INSERT INTO `msds_toxicological` VALUES (4726, 4872, '大鼠经口LD50：约200-500 mg/kg（估算值，基于类似重氮盐化合物）。大鼠经皮LD50：约500-1000 mg/kg（估算值，基于类似重氮盐化合物）。小鼠吸入LC50：约100-500 mg/m³（估算值，基于类似重氮盐化合物）。注：以上数据为基于同类化合物的估算值，具体数据需通过实验测定。', NULL, NULL, '约100-500 mg/m³（估算值，基于类似重氮盐化合物）。注：以上数据为基于同类化合物的估算值，具体数据需通过实验测定。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
