INSERT INTO `msds_toxicological` VALUES (4754, 4900, '吸入：高浓度可引起窒息。LD50（经口）：无资料。LD50（经皮）：无资料。LC50（吸入）：无资料。由于该物质是窒息性气体，在高浓度环境下可引起缺氧、头晕、头痛、恶心、意识模糊，严重时可导致窒息死亡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
