INSERT INTO `msds_toxicological` VALUES (4767, 4913, '粉尘对眼睛、粘膜有刺激作用。吸入、摄入或经皮吸收后均可引起中毒。可引起心、肝、肾损害。全身毛发脱落是其中毒的特征，但眉毛内侧1/3常不受累。铊的化合物具有诱变性、致畸性和致癌性，会导致肝癌、食道癌、大肠癌等多种疾病的发生。急性中毒：出现胃肠道反应（腹痛、恶心、呕吐）、神经系统症状（头痛、头晕、失眠、多梦）、周围神经炎（肢体麻木、疼痛）、脱发等症状。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
