INSERT INTO `msds_toxicological` VALUES (4817, 4966, '急性毒性-经口，类别2。主要的刺激性影响：在皮肤上面：刺激皮肤和粘膜；在眼睛上面：刺激的影响；没有已知的敏化影响。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
