INSERT INTO `msds_toxicological` VALUES (4820, 4969, '偏磷酸具有强腐蚀性和刺激性。急性毒性：大鼠经口LD50约1530 mg/kg（参考磷酸数据）；兔经皮LD50约2740 mg/kg（参考磷酸数据）。吸入可引起呼吸道严重刺激、咳嗽、呼吸困难，严重时可导致肺水肿。食入可引起口腔、咽喉、食道和胃部严重灼伤，可能导致穿孔。皮肤接触可引起严重灼伤和疼痛，导致永久性损伤。眼睛接触可引起严重灼伤，导致永久性损伤甚至失明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
