INSERT INTO `msds_toxicological` VALUES (4875, 5024, 'LD50：大鼠经口约50mg/kg；小鼠经口约40mg/kg；兔经皮约50mg/kg。LC50：大鼠吸入约0.05mg/m3/4h；小鼠吸入约0.1mg/m3/4h。具有剧毒，毒作用似氢氰酸。氰化物抑制细胞呼吸酶，导致组织缺氧。中毒症状包括头痛、头晕、恶心、呕吐、紫绀、呼吸困难、惊厥等，严重者可因呼吸衰竭死亡。', NULL, NULL, '大鼠吸入约0.05mg/m3/4h', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_toxicological` VALUES (4876, 5025, '大鼠经口LD50：5 mg/kg；大鼠经皮LD50：100 mg/kg；大鼠吸入LC50：0.05 mg/m³（4小时）。氰化物为剧毒物质，可迅速抑制细胞呼吸，导致组织缺氧和死亡。', NULL, NULL, '0.05 mg/m³（4小时）。氰化物为剧毒物质，可迅速抑制细胞呼吸，导致组织缺氧和死亡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_toxicological` VALUES (4877, 5026, '大鼠经口LD50：1265 mg/kg；大鼠经皮LD50：>5000 mg/kg；大鼠吸入LC50：>5 mg/m³（4小时）。氰化物为剧毒物质，可迅速抑制细胞呼吸，导致组织缺氧和死亡。', NULL, NULL, '>5 mg/m³（4小时）。氰化物为剧毒物质，可迅速抑制细胞呼吸，导致组织缺氧和死亡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_toxicological` VALUES (4878, 5027, '大鼠经口LD50：约10mg/kg（以CN计）；小鼠经口LD50：约5mg/kg（以CN计）。氰化物剧毒，可经呼吸道、消化道和皮肤吸收，引起组织缺氧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_toxicological` VALUES (4879, 5028, '大鼠经口LD50：约10-50mg/kg（以氰化物计）；大鼠经皮LD50：约100-200mg/kg（以氰化物计）；大鼠吸入LC50：约100-200mg/m³（4小时，以氰化物计）。氰化物属于剧毒物质，急性中毒可迅速致死。', NULL, NULL, '约100-200mg/m³（4小时，以氰化物计）。氰化物属于剧毒物质，急性中毒可迅速致死。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
