INSERT INTO `msds_toxicological` VALUES (4886, 5035, '蒸气或雾对眼、粘膜和上呼吸道有刺激性。对皮肤有刺激性。吸入、摄入或经皮吸收后可能引起中毒。氰基化合物具有抑制细胞呼吸的作用，可导致组织缺氧。急性中毒可表现为头痛、头晕、乏力、恶心、呕吐、呼吸困难等症状，严重者可出现抽搐、昏迷。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
