INSERT INTO `msds_toxicological` VALUES (5132, 5282, '属低毒类。LD50：未测定。LC50：164000mg/m³ 4小时(大鼠吸入)。急性毒性：属低毒类，但高浓度吸入可引起严重肺水肿和心肌损害。吸入有机氟聚合物热解物可引起氟聚合物烟尘热，表现为发热、寒战、肌肉酸痛等。', NULL, NULL, '164000mg/m³ 4小时(大鼠吸入)。急性毒性：属低毒类，但高浓度吸入可引起严重肺水肿和心肌损害。吸入有机氟聚合物热解物可引起氟聚合物烟尘热，表现为发热、寒战、肌肉酸痛等。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
