INSERT INTO `msds_toxicological` VALUES (5143, 5293, '铅化合物具有较大毒性。急性铅中毒多由口服可溶性铅化合物引起，可引起口中金属味、恶心、呕吐、腹痛、腹泻等消化道症状。严重者可出现抽搐、昏迷。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
INSERT INTO `msds_toxicological` VALUES (5144, 5294, '属高毒类。LD50：无资料；LC50：400mg/m³（大鼠吸入，4小时）。急性中毒可引起上呼吸道粘膜强烈刺激症状，轻度中毒表现为喘息性支气管炎症状，严重者出现呼吸困难，呼吸脉搏加快，体温升高，化学性肺炎，肺水肿。', NULL, NULL, '400mg/m³（大鼠吸入，4小时）。急性中毒可引起上呼吸道粘膜强烈刺激症状，轻度中毒表现为喘息性支气管炎症状，严重者出现呼吸困难，呼吸脉搏加快，体温升高，化学性肺炎，肺水肿。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, '', NULL);
