INSERT INTO `msds_transportation` VALUES (2827, 3021, '61127', '2761', NULL, NULL, 'Ⅱ', NULL, '内层玻璃或金属容器，外覆钢桶/木箱，并配吸附材料防泄漏。包装应密封、防潮、防破损。', NULL, NULL, '运输前检查密封，防止跌落和碰撞。严禁与氧化剂、酸类、碱类、食用化学品混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:29:27', '', NULL);
INSERT INTO `msds_transportation` VALUES (2828, 3023, '61127', '2761', NULL, NULL, 'O52', NULL, '内层玻璃或金属容器，外覆钢桶/木箱，并配吸附材料防泄漏。包装应密封、防潮、防破损。', NULL, NULL, '运输前检查密封，防止跌落和碰撞。严禁与氧化剂、酸类、食用化学品混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。狄氏剂为禁用物质，运输需遵守特殊规定。', NULL, NULL, NULL, '2026-03-06 14:29:28', '', NULL);
INSERT INTO `msds_transportation` VALUES (2829, 3024, '61127', '2761', NULL, NULL, 'Ⅱ', NULL, '内层玻璃或金属容器，外覆钢桶/木箱，并配吸附材料防泄漏。包装应密封、防潮、防破损。', NULL, NULL, '运输前检查密封，防止跌落和碰撞。严禁与氧化剂、食用化学品混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。异狄氏剂为禁用物质，运输需遵守特殊规定。', NULL, NULL, NULL, '2026-03-06 14:29:28', '', NULL);
