INSERT INTO `msds_transportation` VALUES (2831, 3027, '61904', '2588', NULL, NULL, 'Ⅲ', NULL, '内层玻璃或金属容器，外覆钢桶/木箱，并配吸附材料防泄漏。包装应密封、防潮、防破损。', NULL, NULL, '运输前检查密封，防止跌落和碰撞。严禁与氧化剂、碱类、食用化学品混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:29:29', '', NULL);
INSERT INTO `msds_transportation` VALUES (2832, 3028, '81132', '2751', NULL, NULL, 'Ⅱ', NULL, '内层玻璃或金属容器，外覆钢桶/木箱，并配吸附材料防泄漏。包装应密封、防潮、防破损。', NULL, NULL, '运输前检查密封，防止跌落和碰撞。严禁与氧化剂、碱类、水、食用化学品混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:29:30', '', NULL);
INSERT INTO `msds_transportation` VALUES (2833, 3029, '3115', '3115', NULL, NULL, 'II（包装类别II）', NULL, '采用防震、防静电包装，避免与还原剂、促进剂、强酸、强碱混装。包装应密封、防潮、防破损。', NULL, NULL, '运输前检查密封，防止跌落、碰撞、摩擦和震动。严禁与还原剂、促进剂、强酸、强碱、金属粉末等混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。有机过氧化物运输需特别谨慎。', NULL, NULL, NULL, '2026-03-06 14:29:30', '', NULL);
INSERT INTO `msds_transportation` VALUES (2834, 3030, '3105', '3105', NULL, NULL, 'II（包装类别II）', NULL, '采用防震、防静电包装，避免与还原剂、促进剂、强酸、强碱混装。包装应密封、防潮、防破损。', NULL, NULL, '运输前检查密封，防止跌落、碰撞、摩擦和震动。严禁与还原剂、促进剂、强酸、强碱、金属粉末等混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。有机过氧化物运输需特别谨慎。', NULL, NULL, NULL, '2026-03-06 14:29:30', '', NULL);
INSERT INTO `msds_transportation` VALUES (2835, 3032, '61876', '2761', NULL, NULL, 'Ⅲ', NULL, '内层玻璃或金属容器，外覆钢桶/木箱，并配吸附材料防泄漏。包装应密封、防潮、防破损。', NULL, NULL, '运输前检查密封，防止跌落和碰撞。严禁与氧化剂、碱类、食用化学品混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。DDT为禁用物质，运输需遵守特殊规定。', NULL, NULL, NULL, '2026-03-06 14:29:31', '', NULL);
INSERT INTO `msds_transportation` VALUES (2836, 3034, '3082', '3082', NULL, NULL, 'Ⅲ', NULL, '内层玻璃或金属容器，外覆钢桶/木箱，并配吸附材料防泄漏。包装应密封、防潮、防破损。', NULL, NULL, '运输前检查密封，防止跌落和碰撞。严禁与氧化剂、碱类、还原剂、食用化学品混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。PFOS是POPs物质，运输需遵守特殊规定。', NULL, NULL, NULL, '2026-03-06 14:29:32', '', NULL);
INSERT INTO `msds_transportation` VALUES (2837, 3035, '61556', '1702', NULL, NULL, 'II', NULL, '采用防静电包装，避免与氧化剂、酸类、碱类混装。包装应密封、防潮、防破损、避光。包装材料应选用耐腐蚀材料，防止泄漏。包装上应标明\"毒害品\"、\"可疑致癌物\"等警示标识。', NULL, NULL, '运输前应先检查包装容器是否完整、密封。运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与氧化剂、碱类、活性金属粉末、食用化学品等混装混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。铁路运输时要禁止溜放。', NULL, NULL, NULL, '2026-03-06 14:29:32', '', NULL);
