INSERT INTO `msds_transportation` VALUES (2843, 3045, '3105', '3105', NULL, NULL, 'II（包装类别II）', NULL, '采用防震、防静电包装，避免与还原剂、促进剂、强酸、强碱混装。包装应密封、防潮、防破损。', NULL, NULL, '运输前检查密封，防止跌落、碰撞、摩擦和震动。严禁与还原剂、促进剂、强酸、强碱、金属粉末等混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。有机过氧化物运输需特别谨慎。', NULL, NULL, NULL, '2026-03-06 14:29:37', '', NULL);
INSERT INTO `msds_transportation` VALUES (2844, 3046, '21031', '1959', NULL, NULL, 'O52', NULL, '采用钢瓶包装，避免与强氧化剂、强酸混装。包装应密封、防潮、防破损。需添加阻聚剂防止聚合反应。', NULL, NULL, '运输前检查密封，防止跌落、碰撞。严禁与强氧化剂、强酸等混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。钢瓶运输需特别谨慎，需添加阻聚剂防止聚合反应。', NULL, NULL, NULL, '2026-03-06 14:29:37', '', NULL);
INSERT INTO `msds_transportation` VALUES (2845, 3047, '32012', '2263', NULL, NULL, 'O52', NULL, '采用防静电包装，避免与氧化剂、酸类、碱类混装。包装应密封、防潮、防破损。', NULL, NULL, '运输前检查密封，防止跌落和碰撞。严禁与氧化剂、酸类、碱类、食用化学品混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:29:37', '', NULL);
INSERT INTO `msds_transportation` VALUES (2846, 3048, '32011', '1146', NULL, NULL, 'II', NULL, '采用防静电包装，避免与氧化剂、酸类、碱类混装。包装应密封、防潮、防破损。', NULL, NULL, '运输前检查密封，防止跌落和碰撞。严禁与氧化剂、酸类、碱类、食用化学品混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:29:38', '', NULL);
INSERT INTO `msds_transportation` VALUES (2847, 3049, NULL, 'UN 1163', NULL, NULL, 'II(中等危险性)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:38', '', NULL);
INSERT INTO `msds_transportation` VALUES (2848, 3050, '31031', '2377', NULL, NULL, 'Ⅱ', NULL, '采用防静电包装，避免与氧化剂、酸类混装。包装应密封、防潮、防破损。通常商品加有稳定剂防止生成过氧化物。', NULL, NULL, '运输前检查密封，防止跌落和碰撞。严禁与氧化剂、酸类、食用化学品混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。注意：接触空气或在光照条件下可生成具有潜在爆炸危险性的过氧化物，需添加稳定剂。', NULL, NULL, NULL, '2026-03-06 14:29:38', '', NULL);
INSERT INTO `msds_transportation` VALUES (2849, 3051, '61579', '2650', NULL, NULL, 'Ⅱ', NULL, '内层玻璃或金属容器，外覆钢桶/木箱，并配吸附材料防泄漏。包装应密封、防潮、防破损。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。夏季最好早晚运输。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、还原剂、酸类、碱类、食用化学品等混装混运。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:29:39', '', NULL);
INSERT INTO `msds_transportation` VALUES (2850, 3052, '61876', '无资料', NULL, NULL, 'II（包装类别II）', NULL, '内层玻璃或金属容器，外覆钢桶/木箱，并配吸附材料防泄漏。包装应密封、防潮、防破损。', NULL, NULL, '运输前检查密封，防止跌落和碰撞。严禁与氧化剂、碱类、食用化学品混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。不能与粮食、食物、种子、饲料、各种日用品混装、混运。', NULL, NULL, NULL, '2026-03-06 14:29:39', '', NULL);
INSERT INTO `msds_transportation` VALUES (2851, 3054, '32035', 'UN 2362', NULL, NULL, 'II', NULL, '采用防静电包装，避免与氧化剂、酸类、碱类混装。包装应密封、防潮、防破损。包装材料应选用耐腐蚀材料，防止泄漏。包装上应标明\"中闪点易燃液体\"、\"可疑致癌物\"等警示标识。', NULL, NULL, '运输时应远离火源、热源，防止阳光直射。运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源、高温区。装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:29:39', '', NULL);
INSERT INTO `msds_transportation` VALUES (2852, 3055, '32040', '1303', NULL, NULL, 'I', NULL, '采用防静电包装，避免与氧化剂、酸类、碱类混装。包装应密封、防潮、防破损、避光。包装材料应选用耐腐蚀材料，防止泄漏。需添加阻聚剂防止聚合反应。包装上应标明\"中闪点易燃液体\"、\"可疑致癌物\"等警示标识。', NULL, NULL, '运输前应先检查包装容器是否完整、密封。运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与氧化剂、酸类、碱类、食用化学品等混装混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。铁路运输时要禁止溜放。', NULL, NULL, NULL, '2026-03-06 14:29:40', '', NULL);
INSERT INTO `msds_transportation` VALUES (2853, 3056, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:29:40', '', NULL);
INSERT INTO `msds_transportation` VALUES (2854, 3057, '61055', '2646', NULL, NULL, 'Ⅰ', NULL, '采用防静电包装，避免与氧化剂、酸类、碱类混装。包装应密封、防潮、防破损。包装材料应选用耐腐蚀材料，防止泄漏。包装上应标明\"剧毒品\"、\"可疑致癌物\"等警示标识。', NULL, NULL, '运输前检查密封，防止跌落和碰撞。严禁与氧化剂、酸类、碱类、食用化学品混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。本品属于持久性有机污染物（POPs），已被列入《斯德哥尔摩公约》禁用名单，禁止进出口。需\"五双\"管理。在火场中，受热的容器有爆炸危险，需特别注意。', NULL, NULL, NULL, '2026-03-06 14:29:40', '', NULL);
INSERT INTO `msds_transportation` VALUES (2855, 3058, '61127', '2761', NULL, NULL, 'Ⅱ', NULL, '采用防静电包装，避免与氧化剂、酸类、碱类混装。包装应密封、防潮、防破损。包装材料应选用耐腐蚀材料，防止泄漏。包装上应标明\"剧毒品\"、\"确认致癌物\"等警示标识。', NULL, NULL, '运输前检查密封，防止跌落和碰撞。严禁与氧化剂、酸类、碱类、食用化学品混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。本品属于持久性有机污染物（POPs），已被列入《斯德哥尔摩公约》禁用名单，禁止进出口。需\"五双\"管理。在火场中，受热的容器有爆炸危险，需特别注意。', NULL, NULL, NULL, '2026-03-06 14:29:41', '', NULL);
INSERT INTO `msds_transportation` VALUES (2856, 3059, '无资料', '2761', NULL, NULL, '无资料', NULL, '采用防静电包装，避免与氧化剂、酸类、碱类混装。包装应密封、防潮、防破损。包装材料应选用耐腐蚀材料，防止泄漏。包装上应标明\"剧毒品\"、\"可疑致癌物\"等警示标识。', NULL, NULL, '运输前检查密封，防止跌落和碰撞。严禁与氧化剂、酸类、碱类、食用化学品混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。本品属于持久性有机污染物（POPs），需\"五双\"管理。在火场中，受热的容器有爆炸危险，需特别注意。', NULL, NULL, NULL, '2026-03-06 14:29:41', '', NULL);
INSERT INTO `msds_transportation` VALUES (2857, 3060, '61659', '2811', NULL, NULL, 'III', NULL, '小开口钢桶；安瓿瓶外普通木箱；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。', NULL, NULL, '运输前应先检查包装容器是否完整、密封，运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与酸类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源。', NULL, NULL, NULL, '2026-03-06 14:29:41', '', NULL);
