INSERT INTO `msds_transportation` VALUES (2917, 3123, '61657', '无资料', NULL, NULL, 'O53', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:30:02', '', NULL);
INSERT INTO `msds_transportation` VALUES (2918, 3124, '61602', '2649', NULL, NULL, 'O52', NULL, '内层玻璃或金属容器，外覆钢桶/木箱，并配吸附材料防泄漏。包装应密封、防潮、防破损。包装材料应选用耐腐蚀材料，防止泄漏。', NULL, NULL, '运输前应先检查包装容器是否完整、密封。运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与氧化剂、还原剂、碱类、食用化学品等混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:30:02', '', NULL);
INSERT INTO `msds_transportation` VALUES (2919, 3125, '33525', '无资料', NULL, NULL, 'O53', NULL, '采用防静电包装，避免与氧化剂、酸类、碱类、铝混装。包装应密封、防潮、防破损。包装材料应选用耐腐蚀材料，防止泄漏。包装上应标明\"高闪点易燃液体\"、\"可疑致癌物\"等警示标识。', NULL, NULL, '运输前应先检查包装容器是否完整、密封。运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与氧化剂、酸类、碱类、食用化学品等混装混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。铁路运输时要禁止溜放。', NULL, NULL, NULL, '2026-03-06 14:30:02', '', NULL);
INSERT INTO `msds_transportation` VALUES (2920, 3126, '33528', '2047', NULL, NULL, 'O52', NULL, '采用防静电包装，避免与氧化剂、酸类混装。包装应密封、防潮、防破损，不可与空气接触。包装材料应选用耐腐蚀材料，防止泄漏。包装上应标明\"高闪点易燃液体\"、\"可疑致癌物\"等警示标识。', NULL, NULL, '运输前应先检查包装容器是否完整、密封。运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与氧化剂、酸类、食用化学品等混装混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。铁路运输时要禁止溜放。不宜大量储存或久存。', NULL, NULL, NULL, '2026-03-06 14:30:02', '', NULL);
INSERT INTO `msds_transportation` VALUES (2921, 3127, '61057', '1597', NULL, NULL, 'O52', NULL, '内层玻璃或金属容器，外覆钢桶/木箱，并配吸附材料防泄漏。包装应密封、防潮、防破损。禁止震动、撞击和摩擦。', NULL, NULL, '运输前应先检查包装容器是否完整、密封。运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与氧化剂、还原剂、碱类、食用化学品等混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。铁路运输时要禁止溜放。禁止震动、撞击和摩擦。', NULL, NULL, NULL, '2026-03-06 14:30:03', '', NULL);
