INSERT INTO `msds_transportation` VALUES (2963, 3174, '33534', '2391', NULL, NULL, 'O53', NULL, '内层玻璃或金属容器，外覆钢桶/木箱，并配吸附材料防泄漏。包装应密封、防潮、防破损。避免光照。', NULL, NULL, '运输前应先检查包装容器是否完整、密封。运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与氧化剂、碱类、食用化学品等混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温，避免光照。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。铁路运输时要禁止溜放。', NULL, NULL, NULL, '2026-03-06 14:30:17', '', NULL);
INSERT INTO `msds_transportation` VALUES (2964, 3175, '21025', '2452', NULL, NULL, 'O52', NULL, '内层玻璃或金属容器，外覆钢桶/木箱，并配吸附材料防泄漏。包装应密封、防潮、防破损。需添加稳定剂防止聚合。', NULL, NULL, '运输前应先检查包装容器是否完整、密封。运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与氧化剂、卤素、氯代烃等混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。需添加稳定剂防止聚合。', NULL, NULL, NULL, '2026-03-06 14:30:17', '', NULL);
INSERT INTO `msds_transportation` VALUES (2965, 3176, '33554', '无资料', NULL, NULL, 'Ⅱ', NULL, '内层玻璃或金属容器，外覆钢桶/木箱，并配吸附材料防泄漏。包装应密封、防潮、防破损。', NULL, NULL, '运输前应先检查包装容器是否完整、密封。运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与氧化剂、酸类、食用化学品等混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:30:17', '', NULL);
INSERT INTO `msds_transportation` VALUES (2966, 3177, '21019', '1012', NULL, NULL, 'O52', NULL, '采用防静电包装，避免与氧化剂、酸类、碱类混装。包装应密封、防潮、防破损。包装材料应选用耐腐蚀材料，防止泄漏。包装上应标明\"易燃气体\"、\"可疑致癌物\"等警示标识。需添加阻聚剂防止聚合反应。', NULL, NULL, '运输前检查密封，防止跌落和碰撞。严禁与氧化剂、酸类、碱类、食用化学品混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。本品易燃，能发生聚合反应，需添加阻聚剂。若遇高热，可发生聚合反应，放出大量热量而引起容器破裂和爆炸事故。与氧化剂接触猛烈反应。气体比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃，需特别注意。', NULL, NULL, NULL, '2026-03-06 14:30:17', '', NULL);
INSERT INTO `msds_transportation` VALUES (2967, 3178, '61731', '2946', NULL, NULL, 'Ⅲ', NULL, '内层玻璃或金属容器，外覆钢桶/木箱，并配吸附材料防泄漏。包装应密封、防潮、防破损。', NULL, NULL, '运输前应先检查包装容器是否完整、密封。运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与氧化剂、酸类、食用化学品等混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:30:18', '', NULL);
INSERT INTO `msds_transportation` VALUES (2968, 3179, '61677', '无资料', NULL, NULL, 'O53', NULL, '内层玻璃或金属容器，外覆钢桶/木箱，并配吸附材料防泄漏。包装应密封、防潮、防破损。', NULL, NULL, '运输前应先检查包装容器是否完整、密封。运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与氧化剂、碱类、食用化学品等混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:30:19', '', NULL);
INSERT INTO `msds_transportation` VALUES (2969, 3180, '32030', '无资料', NULL, NULL, 'O52', NULL, '内层玻璃或金属容器，外覆钢桶/木箱，并配吸附材料防泄漏。包装应密封、防潮、防破损。需添加稳定剂防止聚合。', NULL, NULL, '运输前应先检查包装容器是否完整、密封。运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与氧化剂等混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。需添加稳定剂防止聚合。', NULL, NULL, NULL, '2026-03-06 14:30:19', '', NULL);
INSERT INTO `msds_transportation` VALUES (2970, 3181, '33515', '2278', NULL, NULL, 'O53', NULL, '采用防静电包装，避免与氧化剂、酸类、碱类混装。包装应密封、防潮、防破损。包装要求密封，不可与空气接触。包装材料应选用耐腐蚀材料，防止泄漏。包装上应标明\"易燃液体\"、\"可疑致癌物\"等警示标识。需添加阻聚剂防止聚合反应。', NULL, NULL, '运输前检查密封，防止跌落和碰撞。严禁与氧化剂、酸类、碱类、食用化学品混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。本品易燃，能发生聚合反应，需添加阻聚剂。包装要求密封，不可与空气接触。若遇高热，可发生聚合反应，放出大量热量而引起容器破裂和爆炸事故，需特别注意。', NULL, NULL, NULL, '2026-03-06 14:30:19', '', NULL);
INSERT INTO `msds_transportation` VALUES (2971, 3182, '33510', '1262', NULL, NULL, 'O53', NULL, '采用防静电包装，避免与氧化剂、酸类、碱类混装。包装应密封、防潮、防破损。包装材料应选用耐腐蚀材料，防止泄漏。包装上应标明\"易燃液体\"、\"可疑致癌物\"等警示标识。', NULL, NULL, '运输前检查密封，防止跌落和碰撞。严禁与氧化剂、酸类、碱类、食用化学品混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。本品易燃，遇明火、高热或与氧化剂接触，有引起燃烧爆炸的危险。在火场中，受热的容器有爆炸危险，需特别注意。', NULL, NULL, NULL, '2026-03-06 14:30:19', '', NULL);
INSERT INTO `msds_transportation` VALUES (2972, 3183, '32029', '无资料', NULL, NULL, 'O52', NULL, '内层玻璃或金属容器，外覆钢桶/木箱，并配吸附材料防泄漏。包装应密封、防潮、防破损。需添加稳定剂防止聚合。', NULL, NULL, '运输前应先检查包装容器是否完整、密封。运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与氧化剂等混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。需添加稳定剂防止聚合。', NULL, NULL, NULL, '2026-03-06 14:30:20', '', NULL);
INSERT INTO `msds_transportation` VALUES (2973, 3184, '31009', '2370', NULL, NULL, 'O52', NULL, '采用防静电包装，避免与氧化剂、酸类、碱类混装。包装应密封、防潮、防破损。包装要求密封，不可与空气接触。包装材料应选用耐腐蚀材料，防止泄漏。包装上应标明\"低闪点易燃液体\"、\"可疑致癌物\"等警示标识。需添加阻聚剂防止聚合反应。', NULL, NULL, '运输前检查密封，防止跌落和碰撞。严禁与氧化剂、酸类、碱类、食用化学品混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。本品极度易燃，能发生聚合反应，需添加阻聚剂。若遇高热，可发生聚合反应，放出大量热量而引起容器破裂和爆炸事故。其蒸气比空气重，能在较低处扩散到相当远的地方，遇火源会着火回燃，需特别注意。', NULL, NULL, NULL, '2026-03-06 14:30:20', '', NULL);
INSERT INTO `msds_transportation` VALUES (2974, 3185, '32020', '无资料', NULL, NULL, 'Ⅲ', NULL, '采用防静电包装，避免与氧化剂、酸类、碱类混装。包装应密封、防潮、防破损。包装材料应选用耐腐蚀材料，防止泄漏。包装上应标明\"易燃液体\"、\"可疑致癌物\"等警示标识。需添加阻聚剂防止聚合反应。', NULL, NULL, '运输前检查密封，防止跌落和碰撞。严禁与氧化剂、酸类、碱类、食用化学品混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。本品易燃，能发生聚合反应，需添加阻聚剂。其蒸气比空气重，能在较低处扩散到相当远的地方，遇明火会引着回燃。若遇高热，容器内压增大，有开裂和爆炸的危险，需特别注意。', NULL, NULL, NULL, '2026-03-06 14:30:20', '', NULL);
INSERT INTO `msds_transportation` VALUES (2975, 3186, '无资料', '无资料', NULL, NULL, NULL, NULL, '采用防静电包装，避免与氧化剂、酸类、碱类混装。包装应密封、防潮、防破损。包装材料应选用耐腐蚀材料，防止泄漏。包装上应标明\"易燃液体\"、\"可疑致癌物\"等警示标识。', NULL, NULL, '运输前检查密封，防止跌落和碰撞。严禁与氧化剂、酸类、碱类、食用化学品混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。本品易燃，其蒸气与空气混合，能形成爆炸性混合物。加热时，容器可能爆炸。受热或接触火焰可能会产生膨胀或爆炸性分解，需特别注意。', NULL, NULL, NULL, '2026-03-06 14:30:20', '', NULL);
