INSERT INTO `msds_transportation` VALUES (2977, 3188, '41512', '无资料', NULL, NULL, 'O53', NULL, '内层玻璃或金属容器，外覆钢桶/木箱，并配吸附材料防泄漏。包装应密封、防潮、防破损。', NULL, NULL, '运输前应先检查包装容器是否完整、密封。运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与氧化剂、食用化学品等混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:30:22', '', NULL);
INSERT INTO `msds_transportation` VALUES (2978, 3189, '33554', '2282', NULL, NULL, 'Ⅲ', NULL, '采用防静电包装，避免与氧化剂、酸类、碱类混装。包装应密封、防潮、防破损。包装材料应选用耐腐蚀材料，防止泄漏。包装上应标明\"易燃液体\"、\"可疑致癌物\"等警示标识。', NULL, NULL, '运输前检查密封，防止跌落和碰撞。严禁与氧化剂、酸类、碱类、食用化学品混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。本品易燃，遇明火、高热能引起燃烧爆炸。与氧化剂能发生强烈反应。若遇高热，容器内压增大，有开裂和爆炸的危险，需特别注意。', NULL, NULL, NULL, '2026-03-06 14:30:22', '', NULL);
INSERT INTO `msds_transportation` VALUES (2979, 3190, '61849', '无资料', NULL, NULL, 'Ⅲ', NULL, '采用密封、防潮、防破损的包装。可使用玻璃瓶、塑料桶或内衬塑料袋的金属桶。包装应符合危险货物运输要求。包装上应标明\"毒害品\"、\"可疑致癌物\"等警示标识。', NULL, NULL, '运输前检查包装容器是否完整、密封。运输途中应防曝晒、雨淋，防高温。严禁与氧化剂、酸类、碱类、食用化学品混装混运。运输车辆应配备灭火器及泄漏应急处理设备。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。本品有毒，可燃，遇明火、高热可燃。受高热分解，放出有毒的烟气，需特别注意。', NULL, NULL, NULL, '2026-03-06 14:30:22', '', NULL);
INSERT INTO `msds_transportation` VALUES (2980, 3191, '32001', '1993', NULL, NULL, 'Ⅱ', NULL, '内层玻璃或金属容器，外覆钢桶/木箱，并配吸附材料防泄漏。包装应密封、防潮、防破损。需添加阻聚剂防止聚合。', NULL, NULL, '运输前应先检查包装容器是否完整、密封。运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与氧化剂、强酸等混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。需添加阻聚剂防止聚合。', NULL, NULL, NULL, '2026-03-06 14:30:22', '', NULL);
INSERT INTO `msds_transportation` VALUES (2981, 3192, '21033', '2517', NULL, NULL, 'O52', NULL, '内层玻璃或金属容器，外覆钢桶/木箱，并配吸附材料防泄漏。包装应密封、防潮、防破损。该物质属于消耗臭氧层物质（ODS），应按照《消耗臭氧层物质管理条例》进行包装。', NULL, NULL, '运输前应先检查包装容器是否完整、密封。运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与氧化剂、金属粉末等混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。该物质属于消耗臭氧层物质（ODS），应按照《消耗臭氧层物质管理条例》进行运输。', NULL, NULL, NULL, '2026-03-06 14:30:23', '', NULL);
INSERT INTO `msds_transportation` VALUES (2982, 3193, '61578', '无资料', NULL, NULL, 'Ⅲ', NULL, '内层玻璃或金属容器，外覆钢桶/木箱，并配吸附材料防泄漏。包装应密封、防潮、防破损。', NULL, NULL, '运输前应先检查包装容器是否完整、密封。运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与氧化剂、酸类、食用化学品等混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:30:23', '', NULL);
INSERT INTO `msds_transportation` VALUES (2983, 3194, '22041', '1983', NULL, NULL, 'O53', NULL, '内层玻璃或金属容器，外覆钢桶/木箱，并配吸附材料防泄漏。包装应密封、防潮、防破损。该物质属于消耗臭氧层物质（ODS），应按照《消耗臭氧层物质管理条例》进行包装。', NULL, NULL, '运输前应先检查包装容器是否完整、密封。运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与氧化剂、金属粉末等混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。该物质属于消耗臭氧层物质（ODS），应按照《消耗臭氧层物质管理条例》进行运输。', NULL, NULL, NULL, '2026-03-06 14:30:23', '', NULL);
INSERT INTO `msds_transportation` VALUES (2984, 3195, '环氧氯丙烷', '2023', NULL, NULL, 'Ⅱ', NULL, '采用防静电包装，避免与氧化剂、酸类、碱类混装。包装应密封、防潮、防破损。包装材料应选用耐腐蚀材料，防止泄漏。包装内需添加阻聚剂防止聚合。包装上应标明\"毒害品\"、\"可疑致癌物\"、\"能发生聚合反应\"等警示标识。', NULL, NULL, '运输前检查密封，防止跌落和碰撞。严禁与氧化剂、酸类、碱类、食用化学品混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。本品属于可疑致癌物2A类，能发生聚合反应，需添加阻聚剂。在火场中，受热的容器有爆炸危险，需特别注意。', NULL, NULL, NULL, '2026-03-06 14:30:23', '', NULL);
INSERT INTO `msds_transportation` VALUES (2985, 3196, '61681', '1577', NULL, NULL, 'O52', NULL, '采用防静电包装，避免与氧化剂、酸类、碱类、还原剂混装。包装应密封、防潮、防破损。包装材料应选用耐腐蚀材料，防止泄漏。包装上应标明\"毒害品\"、\"可疑致癌物\"、\"具致敏性\"等警示标识。', NULL, NULL, '运输前检查密封，防止跌落和碰撞。严禁与氧化剂、酸类、碱类、还原剂、食用化学品混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温，避免强烈震动。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。本品属于可疑致癌物2B类，具致敏性，已知在150℃下受强烈震动能引起爆炸，需\"五双\"管理。在火场中，受热的容器有爆炸危险，需特别注意。', NULL, NULL, NULL, '2026-03-06 14:30:24', '', NULL);
INSERT INTO `msds_transportation` VALUES (2986, 3197, '61584', '无资料', NULL, NULL, 'Ⅱ', NULL, '内层玻璃或金属容器，外覆钢桶/木箱，并配吸附材料防泄漏。包装应密封、防潮、防破损。', NULL, NULL, '运输前应先检查包装容器是否完整、密封。运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与氧化剂、强酸、强碱、食用化学品等混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:30:25', '', NULL);
INSERT INTO `msds_transportation` VALUES (2987, 3198, '32038', '无资料', NULL, NULL, 'Ⅱ', NULL, '内层玻璃或金属容器，外覆钢桶/木箱，并配吸附材料防泄漏。包装应密封、防潮、防破损。需添加稳定剂防止聚合。', NULL, NULL, '运输前应先检查包装容器是否完整、密封。运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与氧化剂、强酸等混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。需添加稳定剂防止聚合。', NULL, NULL, NULL, '2026-03-06 14:30:25', '', NULL);
INSERT INTO `msds_transportation` VALUES (2988, 3199, '61576', '无资料', NULL, NULL, 'Ⅱ', NULL, '内层玻璃或金属容器，外覆钢桶/木箱，并配吸附材料防泄漏。包装应密封、防潮、防破损。该物质属于消耗臭氧层物质（ODS），应按照《消耗臭氧层物质管理条例》进行包装。', NULL, NULL, '运输前应先检查包装容器是否完整、密封。运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与氧化剂、强酸等混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。该物质属于消耗臭氧层物质（ODS），应按照《消耗臭氧层物质管理条例》进行运输。', NULL, NULL, NULL, '2026-03-06 14:30:25', '', NULL);
INSERT INTO `msds_transportation` VALUES (2989, 3200, '61575', '无资料', NULL, NULL, 'Ⅲ', NULL, '内层玻璃或金属容器，外覆钢桶/木箱，并配吸附材料防泄漏。包装应密封、防潮、防破损。该物质属于消耗臭氧层物质（ODS），应按照《消耗臭氧层物质管理条例》进行包装。', NULL, NULL, '运输前应先检查包装容器是否完整、密封。运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与氧化剂、强碱、食用化学品等混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。该物质属于消耗臭氧层物质（ODS），应按照《消耗臭氧层物质管理条例》进行运输。', NULL, NULL, NULL, '2026-03-06 14:30:25', '', NULL);
INSERT INTO `msds_transportation` VALUES (2990, 3201, '32034', 'UN1993（基于卤代烷烃类化合物运输分类，参考1-氯丁烷UN编号）', NULL, NULL, 'O52', NULL, '采用防静电包装，避免与氧化剂、酸类、碱类混装。包装应密封、防潮、防破损。包装材料应选用耐腐蚀材料，防止泄漏。包装上应标明\"易燃液体\"、\"可疑致癌物\"等警示标识。', NULL, NULL, '运输前检查密封，防止跌落和碰撞。严禁与氧化剂、酸类、碱类、食用化学品混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。本品易燃，在火场中，受热的容器有爆炸危险，需特别注意。', NULL, NULL, NULL, '2026-03-06 14:30:25', '', NULL);
INSERT INTO `msds_transportation` VALUES (2991, 3202, '61576', '2688', NULL, NULL, 'Ⅲ', NULL, '采用防静电包装，避免与氧化剂、酸类、碱类混装。包装应密封、防潮、防破损。包装材料应选用耐腐蚀材料，防止泄漏。包装上应标明\"毒害品\"、\"可疑致癌物\"、\"消耗臭氧层物质\"等警示标识。', NULL, NULL, '运输前检查密封，防止跌落和碰撞。严禁与氧化剂、酸类、碱类、食用化学品混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。本品属于消耗臭氧层物质（ODS），需遵守《蒙特利尔议定书》相关规定。在火场中，受热的容器有爆炸危险，需特别注意。', NULL, NULL, NULL, '2026-03-06 14:30:26', '', NULL);
INSERT INTO `msds_transportation` VALUES (2992, 3203, '31019', '1278', NULL, NULL, 'O52', NULL, '采用防静电包装，避免与氧化剂、酸类、碱类混装。包装应密封、防潮、防破损。包装材料应选用耐腐蚀材料，防止泄漏。包装上应标明\"极度易燃液体\"、\"可疑致癌物\"等警示标识。', NULL, NULL, '运输前检查密封，防止跌落和碰撞。严禁与氧化剂、酸类、碱类、食用化学品混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。本品极度易燃，在火场中，受热的容器有爆炸危险，需特别注意。', NULL, NULL, NULL, '2026-03-06 14:30:26', '', NULL);
