INSERT INTO `msds_transportation` VALUES (3342, 3563, '61892', '2779', NULL, NULL, 'Ⅲ', NULL, '无资料', NULL, NULL, '无资料', NULL, NULL, NULL, '2026-03-06 14:33:01', '', NULL);
INSERT INTO `msds_transportation` VALUES (3343, 3564, '61893', '无资料', NULL, NULL, 'Ⅲ', NULL, '无资料', NULL, NULL, '无资料', NULL, NULL, NULL, '2026-03-06 14:33:01', '', NULL);
INSERT INTO `msds_transportation` VALUES (3344, 3565, '无资料', '无资料', NULL, NULL, '无资料', NULL, '运输时应包装严密，防止泄漏。包装容器应符合相关法规要求。', NULL, NULL, '运输过程中应避免受热、震动、撞击。远离火源、热源。运输车辆应配备相应的消防器材和泄漏应急处理设备。', NULL, NULL, NULL, '2026-03-06 14:33:01', '', NULL);
INSERT INTO `msds_transportation` VALUES (3345, 3566, '112', 'UN 3237', NULL, NULL, 'II', NULL, '使用符合危险货物运输要求的包装材料。包装应能承受正常运输条件下的震动和冲击。包装上应有清晰的危险品标志和标签。采用防爆型包装。', NULL, NULL, '运输时应远离火源、热源。运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。严禁与氧化剂、酸类、碱类、还原剂、金属粉末等混装混运。运输途中应防曝晒、防雨淋、防高温。运输过程中应避免摩擦、撞击。运输车辆应接地，防止静电积聚。', NULL, NULL, NULL, '2026-03-06 14:33:01', '', NULL);
INSERT INTO `msds_transportation` VALUES (3346, 3567, 'UN 2811', 'UN 2811', NULL, NULL, 'III', NULL, '按危险货物运输规定包装，确保包装完好无损。使用符合国际运输标准的包装容器。', NULL, NULL, '运输过程中应远离火源、热源。避免阳光直射。运输车辆应配备相应的消防器材和泄漏应急处理设备。严禁与氧化剂、强酸、强碱等混装混运。', NULL, NULL, NULL, '2026-03-06 14:33:01', '', NULL);
INSERT INTO `msds_transportation` VALUES (3347, 3568, '第4.1类 自反应物质', 'UN3224', NULL, NULL, 'II', NULL, '使用符合危险货物运输规范的包装容器。包装应密封、防潮、防撞击。', NULL, NULL, '运输过程中应远离火源、热源、阳光直射。避免与强氧化剂、强酸、强碱等不相容物质混装。运输车辆应配备相应的消防器材和泄漏应急处理设备。', NULL, NULL, NULL, '2026-03-06 14:33:03', '', NULL);
INSERT INTO `msds_transportation` VALUES (3348, 3569, NULL, 'UN 3027', NULL, NULL, 'II', NULL, '小开口钢桶；安瓿瓶外普通木箱；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。', NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:33:03', '', NULL);
INSERT INTO `msds_transportation` VALUES (3349, 3570, '61868', '1658', NULL, NULL, 'Ⅱ', NULL, '小开口钢桶；安瓿瓶外普通木箱；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。', NULL, NULL, '铁路运输时应严格按照铁道部《危险货物运输规则》中的危险货物配装表进行配装。运输前应先检查包装容器是否完整、密封，运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与氧化剂、碱类、食用化学品等混装混运。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:33:03', '', NULL);
INSERT INTO `msds_transportation` VALUES (3350, 3571, 'UN编号：2758（有毒固态氨基甲酸酯农药）', 'UN 2758', NULL, NULL, 'II类包装', NULL, '使用符合UN标准的II类包装容器。包装容器应密封完好，标签清晰。', NULL, NULL, '运输时应远离火源、热源。运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与氧化剂、酸类、碱类、食品、饲料等混装混运。运输途中应防暴晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:33:03', '', NULL);
INSERT INTO `msds_transportation` VALUES (3351, 3572, 'UN 2811', 'UN 2811', NULL, NULL, 'II', NULL, '使用符合联合国标准的II类包装容器。包装应坚固、密封，防止泄漏。外包装应贴有危险货物标签和标志。', NULL, NULL, '运输过程中应远离火源、热源。运输车辆应配备相应的消防器材和泄漏应急处理设备。严禁与食品、饲料、氧化剂、酸类等混装混运。运输途中应防暴晒、雨淋、高温。中途停留时应远离火种、热源。运输车辆应保持清洁，防止污染。', NULL, NULL, NULL, '2026-03-06 14:33:05', '', NULL);
INSERT INTO `msds_transportation` VALUES (3352, 3573, '3115', '3115', NULL, NULL, 'II', NULL, '联合国规格包装，外包装应标明\"有机过氧化物\"字样和相应的危险类别标志。', NULL, NULL, '运输过程中应确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与氧化剂、还原剂、酸类、胺类、可燃物等混装混运。运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。', NULL, NULL, NULL, '2026-03-06 14:33:05', '', NULL);
INSERT INTO `msds_transportation` VALUES (3353, 3574, '3077', '3077', NULL, NULL, 'III', NULL, '小开口钢桶；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。', NULL, NULL, '起运时包装要完整，装载应稳妥。运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与氧化剂等混装混运。运输途中应防曝晒、雨淋，防高温。', NULL, NULL, NULL, '2026-03-06 14:33:06', '', NULL);
INSERT INTO `msds_transportation` VALUES (3354, 3575, '82515', '2269', NULL, NULL, 'Ⅱ', NULL, '小开口钢桶；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱；螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱。', NULL, NULL, '铁路运输时，钢桶包装的可用敞车运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封。运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与氧化剂、酸类、食用化学品等混装混运。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:33:06', '', NULL);
INSERT INTO `msds_transportation` VALUES (3355, 3576, '3103', '3103', NULL, NULL, 'II', NULL, '小开口钢桶；安瓿瓶外普通木箱；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。夏季最好早晚运输。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、还原剂、酸类、碱类等混装混运。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源、高温区。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:33:06', '', NULL);
INSERT INTO `msds_transportation` VALUES (3356, 3577, '3105', '3105', NULL, NULL, 'II', NULL, '按照联合国《关于危险货物运输的建议书 规章范本》的要求进行包装。使用符合要求的危险品包装容器。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。夏季最好早晚运输。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与还原剂、酸类、碱类、易燃物或可燃物、食用化学品等混装混运。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:33:08', '', NULL);
INSERT INTO `msds_transportation` VALUES (3357, 3578, 'UN 1920', 'UN 1920', NULL, NULL, 'III', NULL, '符合联合国包装规范的III类包装', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。严禁与氧化剂、食用化学品等混装混运。装运该物品的车辆排气管必须配备阻火装置。使用槽(罐)车运输时应有接地链，槽内可设孔隔板以减少震荡产生静电。禁止使用易产生火花的机械设备和工具装卸。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:33:08', '', NULL);
INSERT INTO `msds_transportation` VALUES (3358, 3579, '32009', '1262', NULL, NULL, 'II类', NULL, '使用符合联合国标准的包装容器。小包装用塑料瓶或玻璃瓶，外包装用木箱或纸箱。大包装用钢桶。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。严禁与氧化剂、卤素等混装混运。装运该物品的车辆排气管必须配备阻火装置。使用槽（罐）车运输时应有接地链，槽内可设孔隔板以减少震荡产生静电。中途停留时应远离火种、热源。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:33:08', '', NULL);
INSERT INTO `msds_transportation` VALUES (3359, 3580, '32007', '3295', NULL, NULL, 'II', NULL, '小开口钢桶；安瓿瓶外普通木箱；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。夏季最好早晚运输。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、食用化学品等混装混运。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:33:09', '', NULL);
