INSERT INTO `msds_transportation` VALUES (3593, 3818, '61699', 'UN 2811', NULL, NULL, 'PG 3', NULL, '无资料', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。严禁与氧化剂、酸类、食用化学品等混装混运。装运该物品的车辆排气管须配备阻火装置。使用槽（罐）车运输时应有接地链，槽内可设孔隔板以减少震荡产生静电。中途停留时应远离火种、热源。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:34:47', '', NULL);
