INSERT INTO `msds_transportation` VALUES (3666, 3893, '61876', '2769', NULL, NULL, 'Ⅲ', NULL, '使用符合UN标准的包装容器。包装必须能经受住正常运输条件下的考验（如堆压、颠簸、温湿度变化），防止泄漏。可采用塑料复合包装袋、金属桶或塑料桶等包装形式，确保密封良好。', NULL, NULL, '运输时须单独装运，不得与食品、饲料、氧化剂、酸碱类等物品混装混运。运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输途中应防曝晒、雨淋、防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。运输人员应经过培训，了解该化学品的危险性，并配备必要的防护用品。', NULL, NULL, NULL, '2026-03-06 14:35:14', '', NULL);
