INSERT INTO `msds_transportation` VALUES (3694, 3922, '61078', '2738', NULL, NULL, 'II', NULL, '小开口钢桶；安瓿瓶外普通木箱；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。夏季最好早晚运输。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。', NULL, NULL, NULL, '2026-03-06 14:35:27', '', NULL);
