INSERT INTO `msds_transportation` VALUES (3734, 3962, '61125', '2783', NULL, NULL, 'Ⅱ', NULL, '无资料', NULL, NULL, '铁路运输时应严格按照铁道部《危险货物运输规则》中的危险货物配装表进行配装。运输前应先检查包装容器是否完整、密封。运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与酸类、氧化剂、食品及食品添加剂混运。运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:35:47', '', NULL);
