INSERT INTO `msds_transportation` VALUES (3740, 3968, '无资料', '3018', NULL, NULL, '无资料', NULL, '无资料', NULL, NULL, '无资料', NULL, NULL, NULL, '2026-03-06 14:35:48', '', NULL);
INSERT INTO `msds_transportation` VALUES (3741, 3969, '有机磷农药，液体，有毒', 'UN 3018', NULL, NULL, 'II', NULL, '使用符合危险货物运输规定的包装容器，确保密封完好。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与氧化剂、酸类、碱类、食用化学品等混装混运。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源。', NULL, NULL, NULL, '2026-03-06 14:35:50', '', NULL);
INSERT INTO `msds_transportation` VALUES (3742, 3970, 'UN 2811', 'UN 2811', NULL, NULL, 'Ⅲ', NULL, '包装方法：按照危险货物运输规则进行包装。使用符合标准的容器，确保包装完好无损。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源、高温区。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。铁路运输时要禁止溜放。严禁与氧化剂、酸类、食用化学品等混装混运。运输车船必须彻底清洗、消毒，否则不得装运其他物品。装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。', NULL, NULL, NULL, '2026-03-06 14:35:50', '', NULL);
