INSERT INTO `msds_transportation` VALUES (3785, 4013, '61876', 'UN 2761', NULL, NULL, 'II', NULL, '小开口钢桶；安瓿瓶外普通木箱；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。', NULL, NULL, '运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输时应避免受潮、受热。严禁与氧化剂、碱类、食用化学品等混装混运。运输途中应防曝晒、雨淋。中途停留时应远离火种、热源、高温区。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:36:09', '', NULL);
INSERT INTO `msds_transportation` VALUES (3786, 4014, '23003', '1005', NULL, NULL, 'O52', NULL, '钢质气瓶；安瓿瓶外普通木箱；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。严禁与氧化剂、酸类、卤素、食用化学品等混装混运。夏季应早晚运输，防止日光曝晒。中途停留时应远离火种、热源。公路运输时要按规定路线行驶，禁止在居民区和人口稠密区停留。铁路运输时要禁止溜放。', NULL, NULL, NULL, '2026-03-06 14:36:10', '', NULL);
INSERT INTO `msds_transportation` VALUES (3787, 4015, '61745', 'UN2811', NULL, NULL, 'Ⅲ', NULL, '塑料袋或多层牛皮纸袋外全开口或中开口钢桶、螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱；螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱；镀锡薄钢板桶（罐）、金属桶（罐）、塑料瓶或金属软管外瓦楞纸箱。', NULL, NULL, '铁路运输时应严格按照铁道部《危险货物运输规则》中的危险货物配装表进行配装。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应先检查包装容器是否完整、密封，运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与氧化剂、食用化学品等混装混运。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:36:10', '', NULL);
INSERT INTO `msds_transportation` VALUES (3788, 4016, 'UN 1325', 'UN 1325', NULL, NULL, 'III', NULL, '按照国际海运危险货物规则（IMDG Code）和国际航空危险货物运输规则（IATA DGR）的要求进行包装', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。装运该品的车辆排气管须有阻火装置。运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与氧化剂、酸类等混装混运。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源。', NULL, NULL, NULL, '2026-03-06 14:36:10', '', NULL);
INSERT INTO `msds_transportation` VALUES (3789, 4017, 'UN 1412', 'UN 1412', NULL, NULL, 'II', NULL, '密封包装，防止受潮', NULL, NULL, '4.3', NULL, NULL, NULL, '2026-03-06 14:36:10', '', NULL);
INSERT INTO `msds_transportation` VALUES (3790, 4018, '43042', 'UN 1412', NULL, NULL, 'II', NULL, '铁桶（氮气密封）包装，包装容器必须密封，切勿受潮。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源。车辆运输完毕应进行彻底清扫。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:36:11', '', NULL);
INSERT INTO `msds_transportation` VALUES (3791, 4019, '43051', 'UN 3129', NULL, NULL, 'II', NULL, '铁桶（氮气密封）包装，包装容器必须密封，切勿受潮。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源。车辆运输完毕应进行彻底清扫。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:36:11', '', NULL);
INSERT INTO `msds_transportation` VALUES (3792, 4020, '81506', '2967', NULL, NULL, 'III类', NULL, '塑料袋或二层牛皮纸袋外全开口或中开口钢桶；塑料袋或二层牛皮纸袋外普通木箱；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱；螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源。车辆运输完毕应进行彻底清扫。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:36:11', '', NULL);
INSERT INTO `msds_transportation` VALUES (3793, 4021, '27', '2244', NULL, NULL, '无资料', NULL, '无资料', NULL, NULL, '无资料', NULL, NULL, NULL, '2026-03-06 14:36:11', '', NULL);
INSERT INTO `msds_transportation` VALUES (3794, 4022, '无资料', '无资料', NULL, NULL, '无资料', NULL, '塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶；塑料袋外塑料桶(固体)；塑料袋外复合塑料编织袋。', NULL, NULL, '运输前应检查包装容器是否完整、密封。运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与氧化剂、食用化学品等混装混运。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:36:12', '', NULL);
INSERT INTO `msds_transportation` VALUES (3795, 4023, 'UN3077', 'UN3077', NULL, NULL, 'III', NULL, '无资料', NULL, NULL, '运输前应先检查包装容器是否完整、密封，运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与氧化剂、酸类、食用化学品等混装混运。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留', NULL, NULL, NULL, '2026-03-06 14:36:13', '', NULL);
INSERT INTO `msds_transportation` VALUES (3796, 4024, '82503', '2672', NULL, NULL, NULL, NULL, '小开口钢桶；玻璃瓶或塑料桶（罐）外普通木箱或半花格木箱；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱；螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。夏季最好早晚运输。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与酸类、金属粉末、食用化学品等混装混运。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源。', NULL, NULL, NULL, '2026-03-06 14:36:13', '', NULL);
INSERT INTO `msds_transportation` VALUES (3797, 4025, '无资料', '无资料', NULL, NULL, '无资料', NULL, '包装方法：按照危险货物运输规则进行包装，确保包装完好无损。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:36:13', '', NULL);
INSERT INTO `msds_transportation` VALUES (3798, 4026, '22038', '2422', NULL, NULL, 'Ⅲ', NULL, '钢质气瓶。', NULL, NULL, '运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源。车辆运输完毕应进行彻底清扫。铁路运输时要禁止溜放。严禁与氧化剂、易燃物、可燃物等混装混运。', NULL, NULL, NULL, '2026-03-06 14:36:13', '', NULL);
INSERT INTO `msds_transportation` VALUES (3799, 4027, '22035', '2424', NULL, NULL, 'Ⅲ', NULL, '钢质气瓶。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。严禁与氧化剂、食用化学品等混装混运。夏季应早晚运输，防止日光曝晒。中途停留时应远离火种、热源。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:36:13', '', NULL);
INSERT INTO `msds_transportation` VALUES (3800, 4028, '22036', '1976', NULL, NULL, 'Ⅲ', NULL, '钢瓶包装，包装容器必须密封，防止泄漏。包装容器上应有符合规定的危险货物标志。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。严禁与易燃物、可燃物、氧化剂等混装混运。运输途中应防曝晒、雨淋、防高温。中途停留时应远离火种、热源。车辆运输完毕应进行彻底清扫。', NULL, NULL, NULL, '2026-03-06 14:36:15', '', NULL);
INSERT INTO `msds_transportation` VALUES (3801, 4029, 'UN 2422', '2422', NULL, NULL, 'Ⅲ', NULL, '钢瓶包装，包装容器必须密封，防止泄漏。包装容器上应有符合规定的危险货物标志。包装类别：Ⅲ。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。严禁与易燃物、可燃物、氧化剂、还原剂、酸类等混装混运。运输途中应防曝晒、雨淋、防高温。中途停留时应远离火种、热源。车辆运输完毕应进行彻底清扫。铁路运输时要禁止溜放。', NULL, NULL, NULL, '2026-03-06 14:36:15', '', NULL);
INSERT INTO `msds_transportation` VALUES (3802, 4030, '61126', '3018', NULL, NULL, 'Ⅱ', NULL, '小开口钢桶；安瓿瓶外普通木箱；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。', NULL, NULL, '铁路运输时应严格按照铁道部《危险货物运输规则》中的危险货物配装表进行配装。运输前应先检查包装容器是否完整、密封，运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与酸类、氧化剂、食用化学品等混装混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:36:15', '', NULL);
INSERT INTO `msds_transportation` VALUES (3803, 4031, '61877', '2761', NULL, NULL, 'Ⅱ', NULL, '塑料袋或二层牛皮纸袋外全开口或中开口钢桶（钢板厚1.0毫米，每桶净重不超过150公斤；钢板厚0.75毫米，每桶净重不超过100公斤）；螺纹口玻璃瓶、塑料瓶或复合塑料瓶外木板箱；塑料瓶外瓦楞纸箱。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。严禁与氧化剂、碱类、食用化学品等混装混运。运输途中应防曝晒、雨淋、防高温。中途停留时应远离火种、热源。车辆运输完毕应进行彻底清扫。', NULL, NULL, NULL, '2026-03-06 14:36:15', '', NULL);
INSERT INTO `msds_transportation` VALUES (3804, 4032, 'UN 3077', 'UN 3077', NULL, NULL, 'Ⅲ', NULL, '按照危险货物运输规定进行包装。使用符合标准的包装容器。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源。车辆运输完毕应进行彻底清扫。', NULL, NULL, NULL, '2026-03-06 14:36:16', '', NULL);
INSERT INTO `msds_transportation` VALUES (3805, 4033, '42001', 'UN 1381（水中）/UN 1338（熔融）/UN 2447（干燥）', NULL, NULL, 'Ⅰ类包装', NULL, '钢瓶（UN1A2）或金属桶（UN1A1），必须保存在水中运输，确保完全浸没', NULL, NULL, '4.2类自燃物品，次要危险性6.1（毒害品），海洋污染物。运输时必须保存在水中，远离火种、热源，避免与空气接触。', NULL, NULL, NULL, '2026-03-06 14:36:17', '', NULL);
