INSERT INTO `msds_transportation` VALUES (3950, 4178, '无资料', '无资料', NULL, NULL, '无资料', NULL, '无资料', NULL, NULL, '无资料', NULL, NULL, NULL, '2026-03-06 14:37:14', '', NULL);
INSERT INTO `msds_transportation` VALUES (3951, 4179, 'UN 0224', '0224', NULL, NULL, 'Ⅰ', NULL, '内包装为玻璃瓶或塑料瓶，外包装为木箱或纸箱，衬垫物应柔软、干燥。包装必须密封，防止受潮。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。严禁与易燃物、氧化剂、酸性物质等混装混运。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源。车辆运输完毕应进行彻底清扫。', NULL, NULL, NULL, '2026-03-06 14:37:15', '', NULL);
INSERT INTO `msds_transportation` VALUES (3952, 4180, '61033', '1687', NULL, NULL, 'Ⅱ', NULL, '塑料袋或多层牛皮纸袋外钢桶；塑料袋外木板箱；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外木板箱', NULL, NULL, '铁路运输时应严格按照铁道部《危险货物运输规则》中的危险货物配装表进行配装。运输前应检查包装容器是否完整、密封。运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与酸类、氧化剂、金属粉末等混装混运。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:37:16', '', NULL);
INSERT INTO `msds_transportation` VALUES (3953, 4181, 'UN 0129', '0129', NULL, NULL, '无资料', NULL, '内包装：玻璃瓶、塑料瓶；外包装：木箱、纸箱。必须确保含水或乙醇≥20%。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。严禁与酸类、氧化剂、金属粉末等混装混运。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源。', NULL, NULL, NULL, '2026-03-06 14:37:16', '', NULL);
INSERT INTO `msds_transportation` VALUES (3954, 4182, 'UN1993', 'UN1993', NULL, NULL, 'III类', NULL, '小开口钢桶；安瓿瓶外普通木箱；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱；螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。夏季最好早晚运输。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、碱类等混装混运。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源、高温区。装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。铁路运输时要禁止溜放。严禁用木船、水泥船散装运输。', NULL, NULL, NULL, '2026-03-06 14:37:16', '', NULL);
INSERT INTO `msds_transportation` VALUES (3955, 4183, 'UN1993', 'UN1993', NULL, NULL, 'III类', NULL, '小开口钢桶；安瓿瓶外普通木箱；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。夏季最好早晚运输。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食用化学品等混装混运。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源、高温区。装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。铁路运输时要禁止溜放。严禁用木船、水泥船散装运输。', NULL, NULL, NULL, '2026-03-06 14:37:18', '', NULL);
INSERT INTO `msds_transportation` VALUES (3956, 4184, '61630', 'UN 3439', NULL, NULL, 'III', NULL, '螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱；螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱。', NULL, NULL, '运输前应检查包装容器是否完整、密封，运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与酸类、氧化剂、食品及食品添加剂混运。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:37:18', '', NULL);
INSERT INTO `msds_transportation` VALUES (3957, 4185, 'UN1993', 'UN1993', NULL, NULL, 'II类', NULL, '小开口钢桶；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱；螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。夏季最好早晚运输。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、还原剂、碱类、食用化学品等混装混运。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源、高温区。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:37:18', '', NULL);
INSERT INTO `msds_transportation` VALUES (3958, 4186, 'UN 3161', 'UN 3161', NULL, NULL, 'II', NULL, '钢质气瓶；安瓿瓶外普通木箱；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。夏季最好早晚运输。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、卤素等混装混运。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。铁路运输时要禁止溜放。严禁用木船、水泥船散装运输。', NULL, NULL, NULL, '2026-03-06 14:37:18', '', NULL);
INSERT INTO `msds_transportation` VALUES (3959, 4187, '81631', 'UN3265', NULL, NULL, NULL, NULL, '采用防静电包装，避免与氧化剂、碱类混装。包装应密封、防潮、防破损。粉体与空气可形成爆炸性混合物，需特别注意。', NULL, NULL, '运输前检查密封，防止跌落和碰撞。严禁与氧化剂、碱类、食用化学品混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。粉体与空气可形成爆炸性混合物，需特别注意。', NULL, NULL, NULL, '2026-03-06 14:37:18', '', NULL);
INSERT INTO `msds_transportation` VALUES (3960, 4188, '无资料', 'UN3082', NULL, NULL, 'III类', NULL, '采用密封包装，防止泄漏。包装应符合国际危险货物运输规则要求。', NULL, NULL, '运输前应检查包装容器的密封性和完整性。运输过程中要远离火种、热源，防止阳光直射。严禁与氧化剂、酸类、碱类等危险物品混装混运。运输车辆应配备相应的消防器材和泄漏应急处理设备。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:37:20', '', NULL);
INSERT INTO `msds_transportation` VALUES (3961, 4189, '无资料', 'UN3082', NULL, NULL, NULL, NULL, '采用密封包装，防止泄漏。包装应符合国际危险货物运输规则要求。', NULL, NULL, '运输前应检查包装容器的密封性和完整性。运输过程中要远离火种、热源，防止阳光直射。严禁与氧化剂、酸类、碱类等危险物品混装混运。运输车辆应配备相应的消防器材和泄漏应急处理设备。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:37:20', '', NULL);
INSERT INTO `msds_transportation` VALUES (3962, 4190, '81116', 'UN1760', NULL, NULL, NULL, NULL, '无资料', NULL, NULL, '运输前检查密封，防止跌落和碰撞。严禁与水、醇类、氧化剂、碱类、食用化学品混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。遇水猛烈分解，需特别注意。包装必须密封，切勿受潮。', NULL, NULL, NULL, '2026-03-06 14:37:20', '', NULL);
INSERT INTO `msds_transportation` VALUES (3963, 4191, '无资料', '无资料', NULL, NULL, '无资料', NULL, '螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱；螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱。', NULL, NULL, '运输前应检查包装容器是否完整、密封，运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与氧化剂、酸类、碱类、强还原剂混运。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:37:20', '', NULL);
INSERT INTO `msds_transportation` VALUES (3964, 4192, 'UN 1982', 'UN 1982', NULL, NULL, 'III', NULL, '小开口钢桶；安瓿瓶外普通木箱；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。夏季最好早晚运输。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类等混装混运。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:37:21', '', NULL);
