INSERT INTO `msds_transportation` VALUES (3987, 4215, '无资料', '无资料', NULL, NULL, 'Z01', NULL, '使用符合运输规定的包装容器。包装容器必须密封。', NULL, NULL, '运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源。', NULL, NULL, NULL, '2026-03-06 14:37:29', '', NULL);
INSERT INTO `msds_transportation` VALUES (3988, 4216, '81125', 'UN 3261', NULL, NULL, 'II', NULL, '使用符合国际运输规定的包装容器。包装容器必须密封。避免与水接触。', NULL, NULL, '运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源。严禁与氧化剂、碱类、醇类等混装混运。避免与水接触。', NULL, NULL, NULL, '2026-03-06 14:37:29', '', NULL);
INSERT INTO `msds_transportation` VALUES (3989, 4217, 'UN 1989', 'UN 1989', NULL, NULL, 'III', NULL, '玻璃瓶、塑料瓶或金属桶包装，包装容器必须密封，能防止泄漏。使用符合国际运输规定的包装容器。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。夏季最好早晚运输。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、碱类、食用化学品等混装混运。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源、高温区。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:37:31', '', NULL);
INSERT INTO `msds_transportation` VALUES (3990, 4218, '无资料', 'UN 2583', NULL, NULL, 'III', NULL, '使用符合国际运输规定的包装容器。包装容器必须密封。', NULL, NULL, '运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源。严禁与氧化剂、碱类等混装混运。', NULL, NULL, NULL, '2026-03-06 14:37:31', '', NULL);
INSERT INTO `msds_transportation` VALUES (3991, 4219, 'UN 1989', 'UN 1989', NULL, NULL, 'Ⅲ类包装', NULL, '专用危险品包装容器，包装方法应符合相关法规要求', NULL, NULL, '运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。严禁与氧化剂等混装混运。运输过程中应防止撞击、摩擦。', NULL, NULL, NULL, '2026-03-06 14:37:31', '', NULL);
