INSERT INTO `msds_transportation` VALUES (4025, 4253, '3105', '3105', NULL, NULL, 'II类包装', NULL, '钢桶（UN 1A1）、塑料桶（UN 1H1）或复合包装。包装应符合《国际海运危险货物规则》（IMDG Code）和《国际空运危险货物规则》（IATA DGR）的要求。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输前应检查包装容器是否完整、密封。运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与还原剂、促进剂、有机物、可燃物、酸类、碱类等混装混运。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:37:50', '', NULL);
