INSERT INTO `msds_transportation` VALUES (4265, 4510, '81116', 'UN 3261', NULL, NULL, 'Ⅱ', NULL, '塑料罐（UN1H1）、钢桶（UN1A1）或塑料桶（UN1H2），内衬耐酸材料。包装容器应密封、坚固，能防止泄漏。', NULL, NULL, '运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输途中应防曝晒、雨淋、高温。中途停留时应远离火种、热源。严禁与氧化剂、碱类、醇类、食用化学品等混装混运。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。装卸时要轻装轻卸，防止包装及容器损坏。', NULL, NULL, NULL, '2026-03-06 14:39:51', '', NULL);
