INSERT INTO `msds_transportation` VALUES (4454, 4700, '3484', 'UN 3484', NULL, NULL, 'Ⅲ', NULL, '安瓿瓶外普通木箱；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶(罐)外普通木箱。使用符合国际运输规定的包装容器。包装容器应密封、坚固，能防止泄漏。', NULL, NULL, '运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。严禁与氧化剂、食用化学品等混装混运。装运该物品的车辆排气管必须配备阻火装置。运输过程中应远离火源、热源。运输途中应防暴晒、雨淋、高温。中途停留时应远离火种、热源。', NULL, NULL, NULL, '2026-03-06 14:41:22', '', NULL);
