INSERT INTO `msds_transportation` VALUES (4465, 4711, 'UN1056', 'UN1056', NULL, NULL, '不适用', NULL, '钢质气瓶', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。夏季应早晚运输，防止日光曝晒。中途停留时应远离火种、热源。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:41:27', '', NULL);
