INSERT INTO `msds_transportation` VALUES (4486, 4732, '33557', '2617', NULL, NULL, 'Ⅲ', NULL, '采用防静电包装，避免与氧化剂、酸类、碱类混装。包装应密封、防潮、防破损。', NULL, NULL, '运输前检查密封，防止跌落和碰撞。严禁与氧化剂、酸类、碱类、食用化学品混装混运，车辆需配备灭火器与泄漏应急装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:41:33', '', NULL);
