INSERT INTO `msds_transportation` VALUES (4576, 4823, NULL, '无资料', NULL, NULL, '无资料', NULL, '无资料', NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:42:11', '', NULL);
INSERT INTO `msds_transportation` VALUES (4577, 4824, '61558', '2811', NULL, NULL, 'III', NULL, '小开口钢桶；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱；螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源。车辆运输完毕应进行彻底清扫。公路运输时要按规定路线行驶，禁止在居民区和人口稠密区停留。铁路运输时要禁止溜放。严禁与氧化剂、碱类、食用化学品等混装混运。', NULL, NULL, NULL, '2026-03-06 14:42:11', '', NULL);
INSERT INTO `msds_transportation` VALUES (4578, 4825, '61514', 'UN 2811', NULL, NULL, 'I', NULL, '塑料袋或二层牛皮纸袋外纤维板桶、胶合板桶、硬纸板桶；塑料袋外塑料桶(固体)；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶(罐)外普通木箱；螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶(罐)外满底板花格箱、纤维板箱或胶合板箱。包装容器必须符合安全标准，能够承受运输过程中可能遇到的温度和压力变化。', NULL, NULL, '运输前应检查包装容器是否完整、密封。运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与氧化剂、碱类、食用化学品等混装混运。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。运输车辆必须配备相应的应急处理设备和防护用品。驾驶员和押运员必须接受专业培训，并持有相应的资格证书。车辆运输完毕应进行彻底清扫。', NULL, NULL, NULL, '2026-03-06 14:42:11', '', NULL);
INSERT INTO `msds_transportation` VALUES (4579, 4826, 'UN0349', 'UN0349', NULL, NULL, '满足Ⅰ类包装要求', NULL, '使用符合联合国标准的爆炸品包装容器。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源、高温区。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。铁路运输时要禁止溜放。严禁用木船、水泥船散装运输。', NULL, NULL, NULL, '2026-03-06 14:42:12', '', NULL);
INSERT INTO `msds_transportation` VALUES (4580, 4827, '11073', '0079', NULL, NULL, 'I类', NULL, '使用符合联合国标准的爆炸品包装容器。包装应符合《危险货物运输包装通用技术条件》要求。', NULL, NULL, '运输时须按照《危险货物运输管理规定》执行。运输车辆应配备相应的消防器材和泄漏应急处理设备。运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与氧化剂、酸类、碱类等混装混运。运输途中应防曝晒、雨淋、防高温。中途停留时应远离火种、热源。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:42:13', '', NULL);
INSERT INTO `msds_transportation` VALUES (4581, 4828, '11074', '0475', NULL, NULL, '满足Ⅱ类包装要求', NULL, '包装类别：第Ⅱ类包装。包装方法：按照危险货物运输规则进行包装。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。严禁与氧化剂、还原剂、酸类、碱类等混装混运。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源。车辆运输完毕应进行彻底清扫。', NULL, NULL, NULL, '2026-03-06 14:42:13', '', NULL);
INSERT INTO `msds_transportation` VALUES (4582, 4829, '11075', '0401', NULL, NULL, 'I', NULL, '无资料', NULL, NULL, '无资料', NULL, NULL, NULL, '2026-03-06 14:42:13', '', NULL);
INSERT INTO `msds_transportation` VALUES (4583, 4830, 'UN 3077', 'UN 3077', NULL, NULL, 'III', NULL, '使用符合国际运输标准的包装容器。包装应密封、防泄漏。', NULL, NULL, '运输时应贴有\"对环境有害\"标志。运输车辆应配备相应的消防器材和泄漏应急处理设备。运输过程中应避免高温、日晒和雨淋。', NULL, NULL, NULL, '2026-03-06 14:42:13', '', NULL);
INSERT INTO `msds_transportation` VALUES (4584, 4831, 'UN 3077', 'UN 3077', NULL, NULL, 'Ⅲ', NULL, '符合危险货物运输规定的包装。', NULL, NULL, '运输时应贴有\"对环境有害\"标志。运输车辆应配备相应的消防器材和泄漏应急处理设备。', NULL, NULL, NULL, '2026-03-06 14:42:13', '', NULL);
INSERT INTO `msds_transportation` VALUES (4585, 4832, 'UN 3151', 'UN 3151', NULL, NULL, '包装类别：III', NULL, '包装方法：塑料袋或二层牛皮纸袋外全开口或中开口钢桶；塑料袋外木板箱；塑料袋或二层牛皮纸袋外普通木箱；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱；螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱。包装容器必须符合《危险货物运输包装通用技术条件》（GB12463-2009）的要求。', NULL, NULL, '运输注意事项：运输前应先检查包装容器是否完整、密封，运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与酸类、氧化剂、食用化学品等混装混运。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。属于持久性有机污染物（POPs），运输过程中应特别注意防止泄漏，避免对环境造成污染。运输车辆应配备应急处理设备和泄漏应急处理预案。运输人员应接受专门培训，了解POPs物质的特性和应急处理方法。', NULL, NULL, NULL, '2026-03-06 14:42:15', '', NULL);
INSERT INTO `msds_transportation` VALUES (4586, 4833, '61111', '2281', NULL, NULL, 'II', NULL, '小开口钢桶；安瓿瓶外普通木箱；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。夏季最好早晚运输。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、碱类、醇类、胺类等混装混运。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源、高温区。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:42:15', '', NULL);
INSERT INTO `msds_transportation` VALUES (4587, 4834, 'UN 1328', '1328', NULL, NULL, 'III', NULL, '小开口钢桶；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。', NULL, NULL, '运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。严禁与氧化剂、酸类等混装混运。装运该物品的车辆排气管必须配备阻火装置。运输过程中应防暴晒、雨淋、高温。中途停留时应远离火种、热源。', NULL, NULL, NULL, '2026-03-06 14:42:15', '', NULL);
INSERT INTO `msds_transportation` VALUES (4588, 4835, '32182', '2493', NULL, NULL, 'II', NULL, '小开口钢桶；安瓿瓶外普通木箱；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源。车辆运输完毕应进行彻底清扫。铁路运输时要禁止溜放。严禁与氧化剂、酸类等混装混运。', NULL, NULL, NULL, '2026-03-06 14:42:15', '', NULL);
