INSERT INTO `msds_transportation` VALUES (4810, 5059, '无资料', '无资料', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:43:49', '', NULL);
INSERT INTO `msds_transportation` VALUES (4811, 5060, '无资料', '无资料', NULL, NULL, '无资料', NULL, '无资料', NULL, NULL, '运输前应先检查包装容器是否完整、密封，运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源。车辆运输完毕应进行彻底清扫。', NULL, NULL, NULL, '2026-03-06 14:43:49', '', NULL);
INSERT INTO `msds_transportation` VALUES (4812, 5061, '61860', '无资料', NULL, NULL, 'Ⅱ', NULL, '小开口钢桶；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱；螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱。', NULL, NULL, '运输前应检查包装容器是否完整、密封。运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与氧化剂、食用化学品等混装混运。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:43:49', '', NULL);
INSERT INTO `msds_transportation` VALUES (4813, 5062, '61884', '2768', NULL, NULL, 'Ⅲ', NULL, '包装方法：小开口钢桶；安瓿瓶外普通木箱；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。', NULL, NULL, '铁路运输时应严格按照铁道部《危险货物运输规则》中的危险货物配装表进行配装。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。夏季最好早晚运输。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、食用化学品等混装混运。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源。车辆运输完毕应进行彻底清扫。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:43:49', '', NULL);
INSERT INTO `msds_transportation` VALUES (4814, 5063, '无资料', '无资料', NULL, NULL, '无资料', NULL, '无资料', NULL, NULL, '无资料', NULL, NULL, NULL, '2026-03-06 14:43:50', '', NULL);
INSERT INTO `msds_transportation` VALUES (4815, 5064, '61861', 'UN3077', NULL, NULL, '9', NULL, '使用符合IMDG Code规定的包装容器，常见的包装方式有编织袋、纸板桶或吨袋。包装必须坚固并处于完好状态，能与货物特性相容，防止在正常运输条件下因震动、温度、湿度或压力变化导致内装物泄漏。', NULL, NULL, '外包装必须同时张贴第9类危险品标志和海洋污染物标记。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源。', NULL, NULL, NULL, '2026-03-06 14:43:51', '', NULL);
INSERT INTO `msds_transportation` VALUES (4816, 5065, '81133', 'UN 2987', NULL, NULL, 'II', NULL, '应使用耐腐蚀、密封良好的容器包装。推荐使用内衬塑料的金属桶或玻璃瓶，外包装为木箱或纤维板箱。包装应符合《危险货物运输包装通用技术条件》(GB 12463)要求。包装上应有明显的腐蚀性物质标志和联合国编号。', NULL, NULL, '运输过程中应避免受潮、受热和剧烈震动。应与氧化剂、碱类、食品和饲料分开运输。运输车辆应配备防腐蚀和防泄漏设备。运输人员应经过专门培训，了解应急处理程序。运输过程中应避免与水接触，防止产生腐蚀性氯化氢气体。运输车辆应贴有危险品标志，并随车携带MSDS和应急处理设备。', NULL, NULL, NULL, '2026-03-06 14:43:51', '', NULL);
INSERT INTO `msds_transportation` VALUES (4817, 5066, '61884', '2786', NULL, NULL, '无资料', NULL, '无资料', NULL, NULL, '无资料', NULL, NULL, NULL, '2026-03-06 14:43:51', '', NULL);
INSERT INTO `msds_transportation` VALUES (4818, 5067, '无资料', '无资料', NULL, NULL, '无资料', NULL, '无资料', NULL, NULL, '无资料', NULL, NULL, NULL, '2026-03-06 14:43:51', '', NULL);
INSERT INTO `msds_transportation` VALUES (4819, 5068, '42022', '3051', NULL, NULL, 'Ⅰ', NULL, '小开口钢桶；安瓿瓶外普通木箱；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱；螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱。', NULL, NULL, '铁路运输时须报铁路局进行试运，试运期为两年。试运结束后，写出试运报告，报铁道部正式公布运输。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。装运本品的车辆排气管须有阻火装置。运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与氧化剂、易燃物、可燃物、醇类、胺类、碱类等混装混运。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源。车辆运输完毕应进行彻底清扫。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:43:53', '', NULL);
INSERT INTO `msds_transportation` VALUES (4820, 5069, '61132', '3020', NULL, NULL, 'Ⅲ', NULL, '无资料', NULL, NULL, '无资料', NULL, NULL, NULL, '2026-03-06 14:43:53', '', NULL);
