INSERT INTO `msds_transportation` VALUES (4825, 5074, '81610', '无资料', NULL, NULL, 'Ⅱ', NULL, '无资料', NULL, NULL, '无资料', NULL, NULL, NULL, '2026-03-06 14:43:55', '', NULL);
INSERT INTO `msds_transportation` VALUES (4826, 5075, '61857', '2788', NULL, NULL, 'Ⅱ', NULL, '包装方法：小开口钢桶；安瓿瓶外普通木箱；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。', NULL, NULL, '铁路运输时应严格按照铁道部《危险货物运输规则》中的危险货物配装表进行配装。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。夏季最好早晚运输。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、碱类、食用化学品等混装混运。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源。车辆运输完毕应进行彻底清扫。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:43:55', '', NULL);
INSERT INTO `msds_transportation` VALUES (4827, 5076, '无资料', '无资料', NULL, NULL, '无资料', NULL, '无资料', NULL, NULL, '无资料', NULL, NULL, NULL, '2026-03-06 14:43:55', '', NULL);
INSERT INTO `msds_transportation` VALUES (4828, 5077, 'UN 3054', '3054', NULL, NULL, 'I', NULL, '使用专用金属容器，密封包装。包装容器必须能承受内压，并防止与空气和水分接触。包装方法应符合IMDG Code第4.3类物质的要求。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。夏季最好早晚运输。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、醇类、食用化学品等混装混运。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源、高温区。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。铁路运输时要禁止溜放。严禁用木船、水泥船散装运输。', NULL, NULL, NULL, '2026-03-06 14:43:56', '', NULL);
INSERT INTO `msds_transportation` VALUES (4829, 5078, '61857', '2788', NULL, NULL, 'Ⅱ', NULL, '包装方法：小开口钢桶；安瓿瓶外普通木箱；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。', NULL, NULL, '铁路运输时应严格按照铁道部《危险货物运输规则》中的危险货物配装表进行配装。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。夏季最好早晚运输。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、碱类、食用化学品等混装混运。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源。车辆运输完毕应进行彻底清扫。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:43:57', '', NULL);
