INSERT INTO `msds_transportation` VALUES (4832, 5081, 'UN 2786', 'UN 2786', NULL, NULL, 'III', NULL, '钢桶、塑料桶或玻璃瓶外木箱内衬垫料', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。夏季最好早晚运输。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食用化学品等混装混运。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源、高温区。装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。铁路运输时要禁止溜放。严禁用木船、水泥船散装运输。', NULL, NULL, NULL, '2026-03-06 14:43:57', '', NULL);
