INSERT INTO `msds_transportation` VALUES (4946, 5198, 'UN 1562', 'UN 1562', NULL, NULL, 'II', NULL, '使用符合危险货物运输包装标准的容器包装。包装容器应密封、坚固，防止泄漏。运输时必须贴有危险货物标志和标签。', NULL, NULL, '运输车辆应配备相应的消防器材和泄漏应急处理设备。严禁与还原剂、金属粉末、酸类、食用化学品等混装混运。运输途中应防曝晒、雨淋、防高温。中途停留时应远离火种、热源。', NULL, NULL, NULL, '2026-03-06 14:44:48', '', NULL);
