INSERT INTO `msds_transportation` VALUES (4951, 5203, '61012', '1622', NULL, NULL, 'Ⅱ', NULL, '使用符合UN标准的包装容器。包装类别Ⅱ类。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源。车辆运输完毕应进行彻底清扫。严禁与氧化剂、酸类、食用化学品等混装混运。', NULL, NULL, NULL, '2026-03-06 14:44:51', '', NULL);
