INSERT INTO `msds_transportation` VALUES (5013, 5265, '61093', 'UN 1644', NULL, NULL, 'I', NULL, '无资料', NULL, NULL, '运输前应先检查包装容器是否完整、密封，运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。运输车辆应配备泄漏应急处理设备。严禁与食品、饲料等混装混运。', NULL, NULL, NULL, '2026-03-06 14:45:20', '', NULL);
INSERT INTO `msds_transportation` VALUES (5014, 5266, '无资料', '无资料', NULL, NULL, '无资料', NULL, '无资料', NULL, NULL, '运输前应先检查包装容器是否完整、密封，运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。运输车辆应配备泄漏应急处理设备。', NULL, NULL, NULL, '2026-03-06 14:45:20', '', NULL);
INSERT INTO `msds_transportation` VALUES (5015, 5267, '无资料', 'UN 3082', NULL, NULL, 'III', NULL, '无资料', NULL, NULL, '运输前应先检查包装容器是否完整、密封，运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。运输车辆应配备泄漏应急处理设备。', NULL, NULL, NULL, '2026-03-06 14:45:21', '', NULL);
INSERT INTO `msds_transportation` VALUES (5016, 5268, '无资料', '无资料', NULL, NULL, '无资料', NULL, '无资料', NULL, NULL, '运输前应先检查包装容器是否完整、密封，运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。运输车辆应配备泄漏应急处理设备。', NULL, NULL, NULL, '2026-03-06 14:45:21', '', NULL);
INSERT INTO `msds_transportation` VALUES (5017, 5269, '无资料', '2811', NULL, NULL, '无资料', NULL, '无资料', NULL, NULL, '无资料', NULL, NULL, NULL, '2026-03-06 14:45:22', '', NULL);
INSERT INTO `msds_transportation` VALUES (5018, 5270, '61857', 'UN 2811', NULL, NULL, 'II', NULL, '塑料袋外塑料桶（罐）加固外木箱；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱；螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱。', NULL, NULL, '运输前应检查包装容器是否完整、密封。运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与氧化剂、酸类、食用化学品等混装混运。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:45:22', '', NULL);
INSERT INTO `msds_transportation` VALUES (5019, 5271, '81528', 'UN 2923', NULL, NULL, '第8类腐蚀性物质', NULL, NULL, NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源。车辆运输完毕应进行彻底清扫。公路运输时要按规定路线行驶，禁止在居民区和人口稠密区停留。严禁与氧化剂、碱类等混装混运。', NULL, NULL, NULL, '2026-03-06 14:45:22', '', NULL);
INSERT INTO `msds_transportation` VALUES (5020, 5272, '82019', 'UN3266', NULL, NULL, 'Ⅱ', NULL, '无资料', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:45:22', '', NULL);
INSERT INTO `msds_transportation` VALUES (5021, 5273, '第8类腐蚀性物质', 'UN 3267', NULL, NULL, 'II', NULL, '使用耐腐蚀的容器包装，确保密封良好。包装应符合国际运输法规要求。', NULL, NULL, '运输过程中应远离火种、热源。防止日晒、雨淋。运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。严禁与酸类、氧化剂、食品等混装混运。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源、高温区。', NULL, NULL, NULL, '2026-03-06 14:45:22', '', NULL);
INSERT INTO `msds_transportation` VALUES (5022, 5274, 'UN 1993', '1993', NULL, NULL, 'III', NULL, '小开口钢桶；安瓿瓶外普通木箱；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。夏季最好早晚运输。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、食用化学品等混装混运。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源、高温区。装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。铁路运输时要禁止溜放。严禁用木船、水泥船散装运输。', NULL, NULL, NULL, '2026-03-06 14:45:24', '', NULL);
INSERT INTO `msds_transportation` VALUES (5023, 5275, '23031', '1955', NULL, NULL, '无资料', NULL, '无资料', NULL, NULL, '无资料', NULL, NULL, NULL, '2026-03-06 14:45:24', '', NULL);
INSERT INTO `msds_transportation` VALUES (5024, 5276, '23020', '1859', NULL, NULL, 'O52', NULL, '钢瓶包装，包装容器必须密封完好，符合相关标准要求。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。严禁与易燃物、可燃物、醇类、胺类、强酸、强碱、金属粉末等混装混运。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。铁路运输时要禁止溜放。运输车辆必须配备防泄漏装置和应急处理设备。运输人员必须经过专业培训，了解本品的危险特性和应急处理方法。', NULL, NULL, NULL, '2026-03-06 14:45:24', '', NULL);
INSERT INTO `msds_transportation` VALUES (5025, 5277, '23019', '2418', NULL, NULL, 'II类包装', NULL, '钢质气瓶', NULL, NULL, '铁路运输时须报铁路局进行试运，试运期为两年。试运结束后，写出试运报告，报铁道部正式公布运输条件。铁路运输时应严格按照铁道部《危险货物运输规则》中的危险货物配装表进行配装。采用钢瓶运输时必须戴好钢瓶上的安全帽。钢瓶一般平放，并应将瓶口朝同一方向，不可交叉。严禁与易燃物或可燃物、酸类、氧化剂等混装混运。', NULL, NULL, NULL, '2026-03-06 14:45:24', '', NULL);
INSERT INTO `msds_transportation` VALUES (5026, 5278, '61097', 'UN2291', NULL, NULL, 'Ⅲ', NULL, '按照GB 12463-2009《危险货物运输包装通用技术条件》要求进行包装。包装必须密封完整，防止泄漏。使用符合标准的危险货物运输包装容器。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。夏季最好早晚运输。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食用化学品等混装混运。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源。车辆运输完毕应进行彻底清扫。', NULL, NULL, NULL, '2026-03-06 14:45:25', '', NULL);
INSERT INTO `msds_transportation` VALUES (5027, 5279, '2912', 'UN2912', NULL, NULL, '无资料', NULL, '按照GB11806-2019《放射性物品安全运输规程》要求进行包装，使用符合标准的放射性物品运输容器，包装必须密封完整。', NULL, NULL, '运输要专车专运，包装必须密封，并应有放射性专用标志。搬运人员应穿戴防护用具。搬运时不得撞击、翻滚和摔落。运输过程中应避免与其它化学危险物品及生活用品混运。运输车辆应配备相应的辐射监测设备和应急处理设备。', NULL, NULL, NULL, '2026-03-06 14:45:26', '', NULL);
INSERT INTO `msds_transportation` VALUES (5028, 5280, '22033', '1982', NULL, NULL, 'O53', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:26', '', NULL);
INSERT INTO `msds_transportation` VALUES (5029, 5281, NULL, 'UN 3239', NULL, NULL, NULL, NULL, '使用符合联合国标准的危险货物包装容器。包装必须密封完整，能够防止泄漏。包装材料应与物质相容，避免发生化学反应。包装容器应标有正确的危险货物标签和标志。包装应符合《危险货物包装通用技术条件》的要求。', NULL, NULL, '运输前必须办理危险货物运输许可，取得相应的运输资质。运输车辆必须配备符合要求的危险货物运输标志和警示灯。运输过程中应避免阳光直射，保持阴凉通风。运输车辆应配备应急处理设备和防护用品。运输过程中应避免剧烈震动、撞击和摩擦。运输途中应远离火源、热源和易燃易爆物品。运输人员必须经过专业培训，熟悉危险货物运输规定和应急处理程序。运输过程中应保持包装完好，防止泄漏。运输车辆应配备GPS定位系统，便于实时监控。运输路线应避开人口密集区和敏感区域。运输过程中应遵守《危险货物运输安全管理条例》等相关法规。', NULL, NULL, NULL, '2026-03-06 14:45:26', '', NULL);
INSERT INTO `msds_transportation` VALUES (5030, 5282, '21032', '1081', NULL, NULL, 'O52', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:26', '', NULL);
INSERT INTO `msds_transportation` VALUES (5031, 5283, '61097', 'UN 1649', NULL, NULL, 'Ⅱ', NULL, '小开口钢桶；安瓿瓶外普通木箱；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源、高温区。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。铁路运输时要禁止溜放。严禁与氧化剂、酸类、食用化学品等混装混运。运输车船必须彻底清洗、消毒，否则不得装运其它物品。装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。', NULL, NULL, NULL, '2026-03-06 14:45:27', '', NULL);
INSERT INTO `msds_transportation` VALUES (5032, 5284, '61096', '1993', NULL, NULL, 'II类', NULL, '塑料瓶或玻璃瓶外用木箱或纸箱加固内衬垫料。', NULL, NULL, '运输前应检查包装容器是否完整、密封。运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与氧化剂等混装混运。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。', NULL, NULL, NULL, '2026-03-06 14:45:27', '', NULL);
INSERT INTO `msds_transportation` VALUES (5033, 5285, 'UN 3295', 'UN 3295', NULL, NULL, 'III类', NULL, '小开口钢桶；安瓿瓶外普通木箱；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。夏季最好早晚运输。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、食用化学品等混装混运。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源。', NULL, NULL, NULL, '2026-03-06 14:45:28', '', NULL);
INSERT INTO `msds_transportation` VALUES (5034, 5286, '61862', '1611', NULL, NULL, 'Ⅱ', NULL, '小开口钢桶；安瓿瓶外普通木箱；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。', NULL, NULL, '运输前应先检查包装容器是否完整、密封，运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与酸类、氧化剂、食用化学品等混装混运。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:45:28', '', NULL);
INSERT INTO `msds_transportation` VALUES (5035, 5287, '61580', '无资料', NULL, NULL, 'O53', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:28', '', NULL);
INSERT INTO `msds_transportation` VALUES (5036, 5288, '81044', '3260', NULL, NULL, 'Ⅱ', NULL, '磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱;安瓿瓶外普通木箱;螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶(罐)外普通木箱', NULL, NULL, '运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。夏季最好早晚运输。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、食用化学品等混装混运。装运该物品的车辆排气管必须配备阻火装置。', NULL, NULL, NULL, '2026-03-06 14:45:28', '', NULL);
INSERT INTO `msds_transportation` VALUES (5037, 5289, '81052', '2444', NULL, NULL, 'Ⅰ', NULL, '磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱;安瓿瓶外普通木箱;螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶(罐)外普通木箱', NULL, NULL, '运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。夏季最好早晚运输。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、食用化学品等混装混运。装运该物品的车辆排气管必须配备阻火装置。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:45:29', '', NULL);
INSERT INTO `msds_transportation` VALUES (5038, 5290, '81517', 'UN 2503', NULL, NULL, 'III', NULL, '小开口钢桶；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。', NULL, NULL, '1. 铁路运输时应严格按照铁道部《危险货物运输规则》中的危险货物配装表进行配装。2. 起运时包装要完整，装载应稳妥。3. 运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。4. 运输时运输车辆应配备泄漏应急处理设备。5. 运输途中应防曝晒、雨淋，防高温。6. 公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:45:29', '', NULL);
INSERT INTO `msds_transportation` VALUES (5039, 5291, '81043', '1818', NULL, NULL, 'O52', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:29', '', NULL);
INSERT INTO `msds_transportation` VALUES (5040, 5292, '81034', '1828', NULL, NULL, 'Ⅰ', NULL, '磨砂口玻璃瓶或螺纹口玻璃瓶外普通木箱;安瓿瓶外普通木箱;螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶(罐)外普通木箱', NULL, NULL, '运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。夏季最好早晚运输。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、食用化学品等混装混运。装运该物品的车辆排气管必须配备阻火装置。', NULL, NULL, NULL, '2026-03-06 14:45:29', '', NULL);
INSERT INTO `msds_transportation` VALUES (5041, 5293, '81049', '无资料', NULL, NULL, 'III类', NULL, '小开口钢桶；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。', NULL, NULL, '1. 铁路运输时应严格按照铁道部《危险货物运输规则》中的危险货物配装表进行配装。2. 起运时包装要完整，装载应稳妥。3. 运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。4. 运输时运输车辆应配备泄漏应急处理设备。5. 运输途中应防曝晒、雨淋，防高温。6. 公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:45:30', '', NULL);
INSERT INTO `msds_transportation` VALUES (5042, 5294, '81051', '1838', NULL, NULL, 'O52', NULL, '包装方法：按照《危险货物运输规则》进行包装。使用耐腐蚀、密封性好的容器，如玻璃瓶、金属桶或塑料桶。包装容器应能承受运输过程中的正常震动和冲击。包装容器应贴有危险货物标签和标志。包装容器应保持干燥，避免受潮。包装容器应定期检查，确保无泄漏。包装容器应存放在阴凉、通风、干燥的地方。', NULL, NULL, '运输前应检查包装容器的完整性和密封性。运输过程中应避免剧烈震动、撞击和摩擦。运输车辆应配备相应的应急处理设备和防护用品。运输过程中应远离火源、热源和明火。运输过程中应避免与水、潮湿空气接触。运输过程中应避免与强氧化剂、强碱、活性金属粉末等混装运输。运输过程中应保持良好通风。运输过程中应避免高温和阳光直射。运输过程中应遵守《危险货物运输规则》和《道路危险货物运输管理规定》等相关法规。运输过程中如发生泄漏，应立即采取应急措施，并报告有关部门。运输人员应经过专业培训，了解本物质的危险性和应急处理方法。', NULL, NULL, NULL, '2026-03-06 14:45:31', '', NULL);
INSERT INTO `msds_transportation` VALUES (5043, 5295, 'UN 2879', 'UN 2879', NULL, NULL, 'II类包装', NULL, '使用耐腐蚀的密封容器，确保包装完整无泄漏。运输过程中应避免受潮和接触水分。运输车辆应配备相应的应急处理设备。', NULL, NULL, '运输前应确保包装完好，无泄漏。运输过程中应避免受潮、受热和机械损伤。运输车辆应配备相应的应急处理设备和防护用品。运输过程中应远离火种、热源。运输人员应经过专门培训，了解本品的危险性和应急处理方法。运输过程中应遵守相关法规和标准，确保运输安全。', NULL, NULL, NULL, '2026-03-06 14:45:31', '', NULL);
INSERT INTO `msds_transportation` VALUES (5044, 5296, '81053', '1827', NULL, NULL, 'O52', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:31', '', NULL);
INSERT INTO `msds_transportation` VALUES (5045, 5297, 'UN 2440', NULL, NULL, NULL, NULL, NULL, '无资料', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。夏季最好早晚运输。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、碱类、食用化学品等混装混运。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源、高温区。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:45:31', '', NULL);
INSERT INTO `msds_transportation` VALUES (5046, 5298, 'UN 3260', '3390', NULL, NULL, 'II', NULL, '玻璃瓶外木箱或钙塑箱加固内衬垫料', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:45:32', '', NULL);
INSERT INTO `msds_transportation` VALUES (5047, 5299, '无资料（建议查询GB 12268-2012《危险货物品名表》或向运输部门确认）', '无资料（建议查询联合国《关于危险货物运输的建议书》或向供应商索取）', NULL, NULL, 'Ⅲ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:32', '', NULL);
INSERT INTO `msds_transportation` VALUES (5048, 5300, '无资料（建议根据GB 12268-2012查询，重氮化合物可能属于4.1类易燃固体）', '无资料（建议查询联合国危险品运输编号，或参考相似重氮化合物）', NULL, NULL, NULL, NULL, '无资料（建议采用防静电包装，密封包装，避免阳光直射）', NULL, NULL, '无资料（建议运输时避免高温、明火，防止剧烈振动，配备相应消防器材）', NULL, NULL, NULL, '2026-03-06 14:45:32', '', NULL);
