INSERT INTO `msds_transportation` VALUES (5056, 5308, '61651', '建议按6.1类危险品运输，UN编号需向相关部门申请', NULL, NULL, 'Ⅱ', NULL, '采用密封、防渗漏包装，确保运输过程中不泄漏', NULL, NULL, '运输过程中应防止包装破损，避免与酸类、氧化剂混运。配备应急处理设备', NULL, NULL, NULL, '2026-03-06 14:45:35', '', NULL);
INSERT INTO `msds_transportation` VALUES (5057, 5309, 'UN 1510', 'UN 1510', NULL, NULL, 'I类包装', NULL, '使用耐腐蚀的密封容器，确保包装完整无泄漏。运输过程中应避免受潮和接触水分。运输车辆应配备相应的应急处理设备。', NULL, NULL, '运输前应确保包装完好，无泄漏。运输过程中应避免受潮、受热和机械损伤。运输车辆应配备相应的应急处理设备和防护用品。运输过程中应远离火种、热源。运输人员应经过专门培训，了解本品的危险性和应急处理方法。运输过程中应遵守相关法规和标准，确保运输安全。', NULL, NULL, NULL, '2026-03-06 14:45:35', '', NULL);
INSERT INTO `msds_transportation` VALUES (5058, 5310, 'UN 0078', 'UN 0078', NULL, NULL, 'I类包装', NULL, '使用耐腐蚀的密封容器，确保包装完整无泄漏。运输过程中应避免受潮和接触水分。运输车辆应配备相应的应急处理设备。', NULL, NULL, '运输前应确保包装完好，无泄漏。运输过程中应避免受潮、受热和机械损伤。运输车辆应配备相应的应急处理设备和防护用品。运输过程中应远离火种、热源。运输人员应经过专门培训，了解本品的危险性和应急处理方法。运输过程中应遵守相关法规和标准，确保运输安全。禁止与还原剂、起爆器材、强氧化剂等混装运输。', NULL, NULL, NULL, '2026-03-06 14:45:35', '', NULL);
INSERT INTO `msds_transportation` VALUES (5059, 5311, 'UN 3077', 'UN 3077', NULL, NULL, 'III', NULL, '采用密闭包装，防止泄漏和污染。', NULL, NULL, '运输过程中应防潮、防晒，避免包装破损。不得与食品、氧化剂混运。运输车辆应配备相应的消防器材和泄漏应急处理设备。', NULL, NULL, NULL, '2026-03-06 14:45:35', '', NULL);
INSERT INTO `msds_transportation` VALUES (5060, 5312, NULL, 'UN 2516', NULL, NULL, 'III（低危险等级）', NULL, NULL, NULL, NULL, '运输前应先检查包装容器的完整性和密封性，确保无泄漏。\n        严禁与氧化剂、酸类、食用化学品等混装混运。装运时车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。\n        运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源、高温区。\n        运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。\n        运输途中应配备适当的应急处理设备，如吸附材料、灭火器材等。', NULL, NULL, NULL, '2026-03-06 14:45:37', '', NULL);
INSERT INTO `msds_transportation` VALUES (5061, 5313, '81524', '无资料', NULL, NULL, 'O52', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:37', '', NULL);
INSERT INTO `msds_transportation` VALUES (5062, 5314, '82505', '2320', NULL, NULL, 'Ⅲ', NULL, '小开口钢桶；安瓿瓶外普通木箱；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。包装容器必须符合《危险货物运输包装通用技术条件》（GB 12463）的要求。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源。车辆运输完毕应进行彻底清扫。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。运输车辆必须悬挂危险货物标志，配备押运人员。严禁与酸类、氧化剂、易燃物等混装混运。运输过程中应确保容器不泄漏、不倒塌、不坠落、不损坏。', NULL, NULL, NULL, '2026-03-06 14:45:37', '', NULL);
INSERT INTO `msds_transportation` VALUES (5063, 5315, '61076', '2471', NULL, NULL, 'I', NULL, '无资料', NULL, NULL, '无资料', NULL, NULL, NULL, '2026-03-06 14:45:37', '', NULL);
INSERT INTO `msds_transportation` VALUES (5064, 5317, '61507', '无资料', NULL, NULL, 'O52', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:45:38', '', NULL);
INSERT INTO `msds_transportation` VALUES (5065, 5318, '61126', '3018', NULL, NULL, 'Ⅰ', NULL, '小开口钢桶；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱；螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。夏季最好早晚运输。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、还原剂、酸类、碱类、食用化学品等混装混运。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源。车辆运输完毕应进行彻底清扫。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:45:38', '', NULL);
INSERT INTO `msds_transportation` VALUES (5066, 5319, '61097', '1649', NULL, NULL, 'O52', NULL, NULL, NULL, NULL, '运输前应先检查包装容器是否完整、密封，运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与酸类、氧化剂、食品及食品添加剂混运。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:45:38', '', NULL);
INSERT INTO `msds_transportation` VALUES (5067, 5320, 'UN 2688', '2688', NULL, NULL, 'II', NULL, '小开口钢桶；安瓿瓶外普通木箱；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食用化学品等混装混运。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源、高温区。装运该物品的车辆排气管必须配备阻火装置，禁止使用易产生火花的机械设备和工具装卸。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。铁路运输时要禁止溜放。', NULL, NULL, NULL, '2026-03-06 14:45:38', '', NULL);
INSERT INTO `msds_transportation` VALUES (5068, 5321, 'UN 1993', '1993', NULL, NULL, 'III', NULL, '钢瓶；安瓿瓶外普通木箱；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱；螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源。车辆运输完毕应进行彻底清扫。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:45:40', '', NULL);
INSERT INTO `msds_transportation` VALUES (5069, 5322, '第1类爆炸品', 'UN 0076', NULL, NULL, '满足Ⅱ类包装要求', NULL, '采用防爆型包装,密封完好。包装材料应与内装物性质相适应。', NULL, NULL, '运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与氧化剂、还原剂、酸类、碱类、食用化学品等混装混运。运输途中应防曝晒、雨淋,防高温。运输车辆装卸前后,均应彻底清扫、洗净,严禁混入有机物、易燃物等杂质。', NULL, NULL, NULL, '2026-03-06 14:45:40', '', NULL);
INSERT INTO `msds_transportation` VALUES (5070, 5323, '33555', 'UN 1299', NULL, NULL, 'III', NULL, '小开口钢桶；安瓿瓶外普通木箱；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱', NULL, NULL, '铁路运输时应严格按照铁道部《危险货物运输规则》中的危险货物配装表进行配装。运输前应先检查包装容器是否完整、密封。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。夏季最好早晚运输。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、碱类、食用化学品等混装混运。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:45:40', '', NULL);
INSERT INTO `msds_transportation` VALUES (5071, 5324, '33638', 'UN 1299', NULL, NULL, 'III', NULL, '玻璃瓶外木板箱内衬垫料或涂锡', NULL, NULL, '铁路运输时应严格按照铁道部《危险货物运输规则》中的危险货物配装表进行配装。运输前应先检查包装容器是否完整、密封。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。夏季最好早晚运输。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类等混装混运。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:45:40', '', NULL);
