INSERT INTO `msds_transportation` VALUES (5147, 5400, '61888', '2757', NULL, NULL, 'Ⅲ', NULL, '无资料', NULL, NULL, '无资料', NULL, NULL, NULL, '2026-03-06 14:46:05', '', NULL);
INSERT INTO `msds_transportation` VALUES (5148, 5401, '61502', 'UN2658', NULL, NULL, 'Ⅲ', NULL, '螺纹口玻璃瓶、塑料瓶或塑料袋外普通木箱；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶(罐)外普通木箱。使用符合国际运输规定的包装容器。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。严禁与氧化剂、酸类、碱类等混装混运。装运该物品的车辆排气管必须配备阻火装置。运输过程中应远离火源、热源。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源、高温区。', NULL, NULL, NULL, '2026-03-06 14:46:05', '', NULL);
INSERT INTO `msds_transportation` VALUES (5149, 5402, '2190', '3283', NULL, NULL, 'Ⅱ', NULL, '使用符合国际运输规定的包装容器。包装应密封，防止泄漏。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。严禁与氧化剂、酸类等混装混运。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源、高温区。', NULL, NULL, NULL, '2026-03-06 14:46:06', '', NULL);
INSERT INTO `msds_transportation` VALUES (5150, 5403, '2191', 'UN3288', NULL, NULL, 'Ⅱ', NULL, '使用符合国际运输规定的包装容器。包装应密封，防止泄漏。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。严禁与氧化剂、酸类等混装混运。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源、高温区。', NULL, NULL, NULL, '2026-03-06 14:46:07', '', NULL);
INSERT INTO `msds_transportation` VALUES (5151, 5404, '23007', 'UN2202', NULL, NULL, 'Ⅱ', NULL, '钢瓶包装。使用符合国际运输规定的包装容器。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。严禁与氧化剂、氧气、压缩空气等混装混运。装运该物品的车辆排气管必须配备阻火装置。运输过程中应远离火源、热源。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源、高温区。铁路运输时须报铁路局进行试运，试运期为两年。', NULL, NULL, NULL, '2026-03-06 14:46:07', '', NULL);
