INSERT INTO `msds_transportation` VALUES (5225, 5478, '32155', 'UN 1222', NULL, NULL, '满足Ⅱ类包装要求', NULL, '装入坚固金属容器内，严密封口。包装必须符合联合国危险货物运输规则要求。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。严禁与氧化剂、还原剂、酸类等混装混运。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源。车辆运输完毕应进行彻底清扫。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:46:37', '', NULL);
