INSERT INTO `msds_transportation` VALUES (5359, 5612, '22001', '1072', NULL, NULL, 'III', NULL, '钢瓶包装', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。装运本品的车辆排气管须有阻火装置。运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与易燃物、可燃物等混装混运。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:47:37', '', NULL);
INSERT INTO `msds_transportation` VALUES (5360, 5613, '61503', '1884', NULL, NULL, 'Ⅲ', NULL, '使用密封良好的防潮容器，防止吸潮。包装应符合相关运输规定。', NULL, NULL, '运输过程中应防止包装破损，避免与水或酸类物质接触。应与食品和饲料分开运输。', NULL, NULL, NULL, '2026-03-06 14:47:37', '', NULL);
INSERT INTO `msds_transportation` VALUES (5361, 5614, '无资料', '1993', NULL, NULL, 'III', NULL, '使用密封良好的容器，防止泄漏。包装应符合相关运输规定。', NULL, NULL, '运输过程中应远离火源、热源，避免剧烈震动，防止泄漏。应与氧化剂、酸类、碱类分开运输。', NULL, NULL, NULL, '2026-03-06 14:47:37', '', NULL);
INSERT INTO `msds_transportation` VALUES (5362, 5615, '无资料', '无资料', NULL, NULL, '无资料', NULL, '使用密封良好的容器，防止泄漏。包装应符合相关运输规定。', NULL, NULL, '运输过程中应防止包装破损，避免泄漏。应与食品、饲料分开运输。', NULL, NULL, NULL, '2026-03-06 14:47:38', '', NULL);
INSERT INTO `msds_transportation` VALUES (5363, 5616, 'T82501', '1910', NULL, NULL, 'O53', NULL, '使用密封良好的防潮容器，防止吸潮。包装应符合相关运输规定。', NULL, NULL, '运输过程中应防止包装破损，避免与水或酸类物质接触。应与易燃物分开运输。', NULL, NULL, NULL, '2026-03-06 14:47:39', '', NULL);
INSERT INTO `msds_transportation` VALUES (5364, 5617, '61504', 'UN 2570', NULL, NULL, 'Ⅲ', NULL, '螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱；安瓿瓶外普通木箱。使用符合国际运输规定的包装容器。包装容器应密封、坚固，能防止泄漏。', NULL, NULL, '铁路运输时应严格按照铁道部《危险货物运输规则》中的危险货物配装表进行配装。运输前应先检查包装容器是否完整、密封。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。夏季最好早晚运输。运输时所用的槽（罐）车应有接地链，槽内可设孔隔板以减少震荡产生静电。严禁与氧化剂、酸类、食品、饲料等混装混运。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:47:39', '', NULL);
INSERT INTO `msds_transportation` VALUES (5365, 5618, '61509', '1641', NULL, NULL, 'Ⅱ', NULL, '密封包装', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。装运本品的车辆排气管须有阻火装置。运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。严禁与酸类、氧化剂、食品及食品添加剂混运。运输途中应防曝晒、雨淋，防高温。公路运输时要按规定路线行驶，勿在居民区和人口稠密区停留。', NULL, NULL, NULL, '2026-03-06 14:47:39', '', NULL);
INSERT INTO `msds_transportation` VALUES (5366, 5619, '33640', '无资料', NULL, NULL, 'Ⅲ', NULL, '使用密封良好的容器，防止泄漏。包装应符合相关运输规定。', NULL, NULL, '运输过程中应远离火源、热源，避免剧烈震动，防止泄漏。应与氧化剂、酸类、碱类分开运输。', NULL, NULL, NULL, '2026-03-06 14:47:39', '', NULL);
