INSERT INTO `msds_transportation` VALUES (5535, 5789, '61789', 'UN 3276', NULL, NULL, '满足Ⅲ类包装要求', NULL, '螺纹口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱。使用符合国际运输规定的包装容器。包装容器应密封、坚固，能防止泄漏。', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。严禁与氧化剂、酸类、食用化学品等混装混运。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源。车辆运输完毕应进行彻底清扫。', NULL, NULL, NULL, '2026-03-06 14:48:58', '', NULL);
INSERT INTO `msds_transportation` VALUES (5536, 5790, '无资料', '无资料', NULL, NULL, '无资料', NULL, '25kgs/袋', NULL, NULL, '运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。严禁与氧化剂、食用化学品等混装混运。运输途中应防曝晒、雨淋，防高温。中途停留时应远离火种、热源。车辆运输完毕应进行彻底清扫。', NULL, NULL, NULL, '2026-03-06 14:48:58', '', NULL);
INSERT INTO `msds_transportation` VALUES (5537, 5791, '61093', 'UN 1640', NULL, NULL, 'I', NULL, '无资料', NULL, NULL, '运输前应先检查包装容器是否完整、密封，运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。运输车辆应配备泄漏应急处理设备。严禁与食品、饲料等混装混运。', NULL, NULL, NULL, '2026-03-06 14:48:58', '', NULL);
