INSERT INTO `msds_transportation` VALUES (5607, 5861, '51520', 'UN3087', NULL, NULL, 'II', NULL, '小开口钢桶；螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱；螺纹口玻璃瓶、塑料瓶或镀锡薄钢板桶（罐）外满底板花格箱、纤维板箱或胶合板箱', NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-06 14:49:32', '', NULL);
INSERT INTO `msds_transportation` VALUES (5608, 5862, '5.1', '3087', NULL, NULL, 'II', NULL, '螺纹口玻璃瓶、铁盖压口玻璃瓶、塑料瓶或金属桶（罐）外普通木箱', NULL, NULL, '铁路运输时应严格按照铁道部《危险货物运输规则》中的危险货物配装表进行配装。运输时单独装运，运输过程中要确保容器不泄漏、不倒塌、不坠落、不损坏。运输时运输车辆应配备相应品种和数量的消防器材及泄漏应急处理设备。严禁与酸类、易燃物、有机物、还原剂、自燃物品、遇湿易燃物品等并车混运。运输时车速不宜过快，不得强行超车。运输车辆装卸前后，均应彻底清扫、洗净，严禁混入有机物、易燃物等杂质。', NULL, NULL, NULL, '2026-03-06 14:49:32', '', NULL);
